INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1, 'آ', '<span class=\"hlight\">آ.</span> (حرف ) الف لَیِّنه، مقابل همزه یا الف متحرکه، حرف اوّل است از حروف هجا، و در حساب جُمَّل آن را به یک دارند. این حرف چون در اوّل کلمه باشد گاه به همزه ٔ مفتوحه بدل شود، چون در آفکانه، افکانه . آفسانه، افسانه <span class=\"hlight\">:</span> <br />شکم حادثات آبستن <br />از نهیب تو آفکانه کند.<br /> <font color=\"Red\">مسعودسعد.</font><br />هیبتش چون بانگ بر عالم زد افکانه شود<br />هر شکم کز حادثات دهر باشد حامله .<br /> <font color=\"Red\">مسعودسعد.</font><br />ترکیب من افکانه شد از زایش علت <br />زآن پس که بد از علت و از عارضه حامل .<br /> <font color=\"Red\">سنائی .</font><br />بپیش خلق شب و روز بر مناقب تست <br />مدار قصّه و تاریخ و آفسانه ٔ من .<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />ده روزه مهر گردون افسانه ای است افسون <br />نیکی بجای یاران فرصت شماریارا .<br /> <font color=\"Red\">حافظ.</font><br />و گاه از اوّل کلمه افتد و معنی کلمه بر جای باشد، چون لاله در آلاله، و درخش در آدرخش، و فکانه در آفکانه <span class=\"hlight\">:</span> <br />ساده دل کودکا مترس اکنون <br />نز یک آسیب خر فکانه کند.<br /> <font color=\"Red\">ابوالعباس .</font><br />چون دواتی بسدین است خراسانی وار<br />بازکرده سر او لاله به طرف چمنا.<br /> <font color=\"Red\">منوچهری .</font><br />بسمن زار درون لاله ٔ نعمان بشنار<br />چون دواتی بسدین است خراسانی وار.<br /> <font color=\"Red\">منوچهری .</font><br />خصمت بود به جنگ خف و تیرت آدرخش <br />تو همچو کوه و تیر بداندیش تو صدا.<br /> <font color=\"Red\">اسدی .</font><br />به پیش اندرآمد یکی تند ببر<br />جهان چون درخش و خروشان چو ابر.<br /> <font color=\"Red\">اسدی .</font><br />تبدیل «آ» به همزه ٔ مفتوحه و همچنین حذف آن از اول کلمه سماعی است و قیاس را در آن راهی نیست و الف لینه ٔ کلمه ٔآمن عربی را فارسی زبانان گاهی به «ای » بدل کنند و ایمن گویند <span class=\"hlight\">:</span> <br />هرکه بر درگاه او کرد التجا رست از محن <br />ایمن است از موج دریا هرکه در بوزی نشست .<br /> <font color=\"Red\">عمید لوبکی .</font><br />نوروز روزگار نشاط است و ایمنی <br />پوشیده ابر دشت به دیبای ارمنی .<br /> <font color=\"Red\">منوچهری .</font><br />زیرا که او به سیرت و خلق فریشته است <br />ایمن بود فریشته از کید اهرمن .<br /> <font color=\"Red\">معزی .</font><br />هرگز ایمن ز مار ننشستم <br />تا بدانستم آنچه خصلت اوست .<br /> <font color=\"Red\">سعدی .</font><br />و الف «ان »، علامت جمع، چون عقب کلمه ٔ مختوم به ألف درآید میان دو الف یائی درآرند آسانی تلفظ را، چون در شمایان و مایان <span class=\"hlight\">:</span> <br />قوم راگفتم چونید شمایان به نبید<br />همه گفتند صواب است صواب است صواب .<br /> <font color=\"Red\">فرخی .</font><br />گفت فردا شمایان را مثال داده آید که سوی هرات بر چه جمله باید رفت . (تاریخ بیهقی ). شمایان رااز این اخبار تفصیلی دارم . (تاریخ بیهقی ).<br />الف لینه در میان کلمه نیز چنانکه در اول آن، گاه به فتحه بدل شود، چون آشمیدن بجای آشامیدن و آرمیدن بجای آرامیدن و خوابنیدن بجای خوابانیدن و پردختن بجای پرداختن <span class=\"hlight\">:</span> <br />دد و دام و هر جانور کش بدید<br />ز گیتی به نزدیک او آرمید.<br /> <font color=\"Red\">فردوسی .</font><br />از آن بدکنش دیو روی زمین <br />بپرداز و پردخته کن دل ز کین .<br /> <font color=\"Red\">فردوسی .</font><br />بروز از هیچ گونه نارمیدی <br />چو گور و آهو از مردم رمیدی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />دل از دیدنم پاک پردخت کن .<br /> <font color=\"Red\">اسدی .</font><br /> <br />بگفت این سراسر یهودا نوشت <br />چو پردخته شد نامه را درنوشت .<br /><font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <br />زبیده بر عباسه حسد بردی ازبهر آنکه خلیفه مادام با وی آرمیدی . (تاریخ برامکه ).<br />از آن پس درِ خوابگه سخت کن <br />آنجا که سمند تو سم نماید<br />آدم علم خویش خوابنیده .<br /> <font color=\"Red\">سنائی .</font><br />اینک از اقبال تو پردخته شد آن خدمتی <br />کاندکش الفاظ و بسیارش معانی آمده ست .<br /> <font color=\"Red\">سنائی .</font><br />خوشدل شد و آرمیدبا او<br />هم خورد و هم آشمید با او.<br /> <font color=\"Red\">نظامی .</font><br />بر مهد عروس خوابنیده <br />خوابش بربود و بست دیده .<br /> <font color=\"Red\">نظامی .</font><br />و گاه بدل فتحه آید چون کهکان (افزاری کندن کوه را) در کهکن که الف بدل فتحه ٔ کاف دوم در کهکن است، و ماهار در مهار که الف بدل فتحه ٔ میم است و فراهنگ در فرهنگ به معنی کاریز، که الف بجای فتحه ٔ راء است <span class=\"hlight\">:</span> <br />که بر آب و گل نقش بنیاد کرد<br />که ماهار در بینی باد کرد.<br /> <font color=\"Red\">رودکی .</font><br />در این صندوق ساعت عمرها زین دهر بی رحمت <br />چو ماهارند بر اشتر بدین گردنده پنگانها.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و در استعمال فارسی الف وسطرا در مثل خزانه و کتاب و رکاب و عتاب و مکاس و حجاب و ادبار بدل به یاء کنند و خزینه و کتیب و رکیب و عتیب و مکیس و حجیب و ادبیر گویند. و در کلمات عربی مستعمل در فارسی گاه الف لیّنه جانشین یاء آخر کلمه گردد چون تمنا، تقاضا، تماشا، تولاّ، که در اصل عربی تمنی، تقاضی، تماشی و تولّی است <span class=\"hlight\">:</span> <br />ملکت قیصر و فغفور تماشاگه اوست <br />ظن بری هرگز روزی به تماشا نشود.<br /> <font color=\"Red\">منوچهری .</font><br />گوئی از دو لب من بوسه تقاضا چه کنی <br />وام خواهی نبود کو به تقاضا نشود.<br /> <font color=\"Red\">منوچهری .</font><br />و الف در کلمه ٔ تاغ به معنی غضا گاه به واو بدل شود و توغ گویند. و الف آخری که در عربی به صورت یاء نوشته میشود، چون موسی و عیسی و معنی و دعوی و لیلی در مواردی که اقتضای حرکت کند به یاء بدل گردد: موسی عمران، عیسی مریم، معنی لطیف، دعوی باطل، لیلی و مجنون <span class=\"hlight\">:</span> <br />ازبرای رغم من گوئی از این میدان حسن <br />عیسی مریم برفت و موسی عمران بماند.<br /> <font color=\"Red\">سنائی .</font><br />به حق دم پاک عیسی مریم <br />به حق کف دست موسی عمران .<br /> <font color=\"Red\">انوری .</font><br />چون که بی رنگی اسیر رنگ شد<br />موسیی با موسیی در جنگ شد.<br /> <font color=\"Red\">مولوی .</font><br />دعوی پیغمبری بااین گروه <br />همچنان باشد که دل جستن ز کوه .<br /> <font color=\"Red\">مولوی .</font><br />معنی قرآن ز قرآن پرس و بس <br />وز کسی کآتش زده ست اندر هوس .<br /> <font color=\"Red\">مولوی .</font><br />چون به بی رنگی رسی کان داشتی <br />موسی و فرعون دارند آشتی .<br /> <font color=\"Red\">مولوی .</font><br />و گاه در غیر این مورد نیز الف متطرّفه خواه مقصوره و خواه ممدوده تبدیل به یاء مُماله شود و موسی و عیسی و اِنشی و اِجْری را با آری و مانی و فربی قافیه کنند چنانکه در قصاید منوچهری و انوری و ظهیر فاریابی . و الف ممدوده در جمع تکسیر مانند علماء، حکماء، اعداء، اعضاء، احشاء. و نیز الف ممدوده در آخر اسماء و صفات چون بیضاء، حمراء، صفراء، سوداء، ضیاء، بهاء، دعاء، صحراء، ریاء، انشاء، استقراء، در فارسی غالباً بدل بألف مقصوره شود و علما، حکما، اعدا، اعضا، احشا، بیضا، حمرا، صفرا، سودا، ضیا، بها، دعا، صحرا، ریا، انشا و استقرا گویند <span class=\"hlight\">:</span> <br />عالمی از کبریائی سربسر<br />گرچه عالم سربسر کبر و ریاست .<br /> <font color=\"Red\">انوری .</font><br />که زیر گنبد خضرا چنان توان بودن <br />که اقتضای قضاهای گنبد خضراست .<br /> <font color=\"Red\">انوری .</font><br />و در الف و تاء آخر وزن مفاعله چون از ناقص واوی یا یائی و یا مهموزاللام باشد در استعمال فارسی گاه بهمان الف تنها اکتفا کنند و بجای مداراة ومعاداة و محاباة و مداواة و مماشاة و مواساة و مباراة و مفاجاة و محاکاة؛ مدارا، معادا، محابا، مداوا، مماشا، مواسا، مبارا، مفاجا و محاکا گویند <span class=\"hlight\">:</span><br />مدارا، خرد را برادر بود<br />خرد بر سر دانش افسر بود.<br /> <font color=\"Red\">فردوسی .</font><br />اندوهم از آن است که یک روز مفاجا<br />آسیبی از آن دل بفتد بر جگر آید.<br /> <font color=\"Red\">فرخی .</font><br />ناز چندان کن بر من که کنی صحبت من <br />تا مگرصحبت دیرینه معادا نشود.<br /> <font color=\"Red\">منوچهری .</font><br />به مدارادل تو نرم کنم وآخر کار<br />به درم نرم کنم گر به مدارا نشود.<br /> <font color=\"Red\">منوچهری .</font><br />گر دم خلع و مبارا میرود<br />بد مبین ذکر بخارا میرود.<br /> <font color=\"Red\">مولوی .</font><br />عاشق آن گوش ندارد که نصیحت شنود<br />درد ما نیک نگردد بمداوای حکیم .<br /> <font color=\"Red\">سعدی .</font><br />آسایش دو گیتی تفسیر این دو حرف است <br />با دوستان مروت با دشمنان مدارا.<br /> <font color=\"Red\">حافظ.</font><br /> <font color=\"Red\"># # #</font><br />الف لیّنه در سر برخی اسماء و افعال افاده ٔ سلب گونه ای در معنی اسم و فعل کند، چون «آ» در آهو و آسغده . چه «هو» به معنی خوب است و آهو به معنی ناخوب، و«سغده »سوخته و آسغده به معنی ناسوخته و یا نیم سوخته <span class=\"hlight\">:</span> <br />ایستاده میان گرمابه <br />همچو آسغده در میان تنور.<br /> <font color=\"Red\">معروفی .</font><br />دگر گفت بد چیست بر پادشا<br />کزو تیره گردد دل پارسا<br />چنین داد پاسخ که بر شهریار<br />خردمند گوید که آهوست چار.<br /> <font color=\"Red\">فردوسی .</font><br />سفر نیست آهو که والاگهر<br />چو بیند جهان بیش گیرد هنر.<br /> <font color=\"Red\">اسدی .</font><br />هرچه زایزد بود همه نیکوست <br />هرچه از تست سربسر آهوست .<br /> <font color=\"Red\">سنائی .</font><br />الف لینه در میان کلمه ٔ مکرّر گاه افاده ٔ معنی کثرت و بسیاری کند، مانند رنگارنگ، گوناگون، مولامول، خنداخند، فوزافوز، پیچاپیچ، چکاچاک، دمادم، چاکاچاک، دهاده، گیراگیر، مرگامرگی، دورادور، پیاپی، نوشانوش، زهازه، زودازود، ترنگاترنگ، هایاهای، هویاهوی و هیناهین <span class=\"hlight\">:</span> <br />به شادی یکی انجمن برشکفت <br />شهنشاه عالم زهازه گرفت .<br /> <font color=\"Red\">فردوسی .</font><br />تا بدانی که وقت پیچاپیچ <br />هیچکس را کسی نباشد هیچ .<br /> <font color=\"Red\">سنائی .</font><br />فلک از مجلس انس تو پر از هویاهوی <br />عالم از گریه ٔ خصم تو پر از هایاهای .<br /> <font color=\"Red\">انوری .</font><br />بکند رخنه نظم حال مرا<br />در چنان گیر و دار و هیناهین .<br /> <font color=\"Red\">انوری .</font><br />دفع چشم بدی جهانی را<br />همچنان نرم نرم و خنداخند.<br /> <font color=\"Red\">انوری .</font><br />ترنگاترنگ درخشنده تیغ<br />بمه درقها را برآورده میغ.<br /> <font color=\"Red\">نظامی .</font><br />در هم آمیختیم خنداخند<br />من و چون من فسانه گویی چند.<br /> <font color=\"Red\">نظامی .</font><br />سخن گرچه با او زهازه بود<br />نگفتن هم از گفتنش بِه ْ بود.<br /> <font color=\"Red\">نظامی .</font><br />شه بگرمی سیاستم فرمود<br />در هلاکم مکوش زودازود.<br /> <font color=\"Red\">نظامی .</font><br />ز پیچاپیچ آن شب گر دهم شرح <br />دو زلفش را دو رخ دادن توان طرح .<br /> <font color=\"Red\">امیرخسرو دهلوی .</font><br />شراب خانگی از بیم محتسب خوردن <br />بروی یار بنوشیم و بانگ نوشانوش .<br /> <font color=\"Red\">حافظ.</font><br />و گاه ترتیب و توالی را رساند چنانکه در یکایک، و گاه اتصال را چونانکه در دستادست (بمعنی نقد در مقابل نسیه ) و دوشادوش و گوشاگوش <span class=\"hlight\">:</span> <br />ستد و داد جز به دستادست <br />داوری باشد و زیان و شکست .<br /> <font color=\"Red\">سنائی .</font><br />تا رسیدند هر دو دوشادوش <br />به بیابانی از بخار بجوش .<br /> <font color=\"Red\">نظامی .</font><br />و در راستاراست و برابر و رمارم و لبالب نشانه ٔ برابری باشد <span class=\"hlight\">:</span> <br />مرا دخل و خورد ار برابر بدی <br />زمانه مرا چون برادر بدی .<br /> <font color=\"Red\">فردوسی .</font><br />شیرانه چو بر شیران او تیغ برآهیخت <br />باشند بچشمش همه با گور رمارم .<br /> <font color=\"Red\">فرخی .</font><br />او دادمرا بر رمه شبانی <br />زین میبردم با رمه رمارم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تخم خرفه و تخم گشنیز و بیخ خطمی راستاراست . (ذخیره ٔ خوارزمشاهی ).<br />در عرصه گه غمت شمرده <br />شیطان و ملائکه رمارم .<br /> <font color=\"Red\">عمادی شهریاری .</font><br />بموسم گندم درو، از آسمان باران آمد پانزده شبانه روز که حوضها لبالب شد. (تاریخ طبرستان ). و در سرازیر و سراشیب و سرابالا مراد سوی و جهت است . و در رویاروی مفهوم مقابله و مواجهه دارد، یعنی روی مواجه روی <span class=\"hlight\">:</span> <br />یا بزرگی و عز و نعمت وجاه <br />یا چو مردانْت مرگ رویاروی .<br /> <font color=\"Red\">حنظله ٔ بادغیسی .</font><br />و در مثل نصفانصف و نیمانیم مقصود حدّاقل و دست کم است <span class=\"hlight\">:</span> <br />نه راستی و درستی هر مثل که زدند<br />اگر نه جمله دروغ است هست نیمانیم .<br /> <font color=\"Red\">سوزنی .</font><br />و گاه بجای واو عاطفه باشد، مانند تکاپوی و کمابیش و زناشویی و هایاهوی و هیاهوی و گفتاگوی، به معنی تک و پوی، کم و بیش، زنی و شویی، های و هوی، هی و هوی، گفت و گوی .<br />و در سراسر و سراپای به معنی کلمه ٔ «تا» است، یعنی سرتاسر و سرتاپای <span class=\"hlight\">:</span> <br />سراسر ببندید دست هوا<br />هوا را مدارید فرمان روا.<br /> <font color=\"Red\">فردوسی .</font><br />بخدا و بسراپای تو کز دوستیت <br />خبر از دشمن و اندیشه ٔ دشنامم نیست .<br /> <font color=\"Red\">سعدی .</font><br />وگاهی معنی «اندر» و «در» دهد که گاه ضرب عددی در عدد دیگر آرند در کلام، و گویند دو در سه شش شود، یا قالی شش متر است ذرع اندر ذرع <span class=\"hlight\">:</span> <br />بید را سایه ای است میلامیل <br />جوی را دیده ای است مالامال .<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />و گاه معنی شدّت و غایت و نهایت دهد، مانند گرما گرم یعنی در شدت گرمی و فاشافاش یعنی در نهایت فاشی . و به معنی همه و کل ّ و تمام نیز باشد چون سالاسال <span class=\"hlight\">:</span> <br />نیکخواهان ترا سالاسال <br />همه روز است بدیدار تو عید.<br /> <font color=\"Red\">سوزنی .</font><br />و در باداباد معنی تواند بود دهد <span class=\"hlight\">:</span> <br />شراب و عیش نهان چیست ؟ کار بی بنیاد<br />زدیم بر صف رندان و هرچه باداباد.<br /> <font color=\"Red\">حافظ.</font><br />هرچه باداباد ما کشتی در آب انداختیم .<br /> <font color=\"Red\">؟</font><br />و در پیشاپیش و پیشادست (بمعنی سلم )، و دورادوربرای زینت است، چه پیش پیش و پیش دست و دور دور نیز همان معنی را دهد.<br />و نیز برای تحذیر آید، چون در بردابرد <span class=\"hlight\">:</span> <br />گیتی و آسمان گیتی گرد<br />بر در تو زنند بردابرد.<br /> <font color=\"Red\">نظامی .</font><br />نصیب خانه ٔ خصم تو باد بُردابُرد<br />ز سیل موکب جاه تو باد بَردابَرد.<br /> <font color=\"Red\">کمال اصفهانی .</font><br />الف لینه را گاه در مفرد غایب مضارع پیش از حرف آخر درآرند آفرین و نفرین و آرزوهای دیگر را <span class=\"hlight\">:</span> پادشاهان ما را آنانکه گذشته اند ایزدشان بیامرزاد و آنچه برجای است باقی داراد. (تاریخ بیهقی ). و او واپس مینگریست تا مگر مصطفی علیه السلام رحمت کناد. (تفسیر ابوالفتوح رازی ). و گاه الف دعا قبل از حرف آخر متکلم وحده و فعل مضارع درآید، چنانکه در بادام و میرام و مبینام <span class=\"hlight\">:</span> فدیتک، یعنی در عوض تو بادام . (تفسیر ابوالفتوح رازی ).<br />گرد سر و پای تو چو پروانه دوانم <br />بوسی بده ای شمع که در پای تو میرام .<br /> <font color=\"Red\">شرف شفروه .</font><br />چتر ظفرت نهان مبینام <br />بی رایت تو جهان مبینام <br />مأوی گه جیفه ٔ حسودت <br />جز سینه ٔ کرکسان مبینام .<br /> <font color=\"Red\">خاقانی .</font><br />و سنائی در کلمه ٔ ترّهات جمع ترّهه، الفی در میان افزوده و ترّاهات گفته است فقط برای حفظ وزن . و اینگونه توسعات مخصوص سران ادب است و درخور قیاس نیست <span class=\"hlight\">:</span> <br />خاص در بند لذت شهوات <br />عام در بند هزل و تراهات .<br /><font color=\"Red\">سنائی .</font><br />الف لینه چون به آخر کلمات آید در مفرد امر افاده ٔ فاعلیت کند و در آن حال کلمه در حکم اسم فاعل یا وصف فاعلی باشد، چون بینا و دانا و سنبا و گویا و گیرا که به معنی بیننده و داننده و سنبنده و گوینده و گیرنده است، و چون زیبا و شکیبا و گندا و توانا یعنی متصف بزیب و شکیب و گند و توان، و همین الف بقرینه ٔ کلام برای مبالغه ٔ معنی فاعلی نیز آید چنانکه در ترجمه اِنّه ُ سمیعٌ علیم، گوییم او تعالی شنوا و داناست، یعنی شنونده و داننده است بکمال .<br />و در «فریبا» کلمه را صورت صفت مفعولی بخشد. و این که بعضی گویند مجد همگر بغلط در شعر خود فریبا را معنی فریفته داده، سهویست . چه سعدی نیز کلمه را به همین معنی آورده است <span class=\"hlight\">:</span> <br />ولیکن بدین صورت دلپذیر<br />فریبا مشوسیرت خوب گیر.<br /> <font color=\"Red\">(بوستان ).</font><br />هم حور بهشت ناشکیبا از تست <br />هم جادو هم پری فریبا از تست <br />خوبان جهان بجامه نیکو گردند<br />آن خوب تویی که جامه زیبا از تست .<br /> <font color=\"Red\">مجد همگر.</font><br />یارب مرا بعشق شکیبا کن <br />یا عاشقی بمرد شکیبا ده .<br /> <font color=\"Red\">اورمزدی .</font><br />چنین است آیین چرخ روان <br />توانا به هر کار و ما ناتوان .<br /> <font color=\"Red\">فردوسی .</font><br />کسی را در غریبی دل شکیباست <br />که در خانه نباشد کار او راست .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />جواب آورند سخت نیکو و بندگانه با بسیار تواضع و بندگی، و عذر رفتن بتعجیل سخت زیبا بازنموده . (تاریخ بیهقی ).<br />تواناست بر دانش خویش دانا<br />نه داناست آنکو تواناست بر زر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />هرچند طعام خوشتر ثفل وی گنداتر. (کیمیای سعادت ). و گنداتر و رسواتر از آن چیزی که وی همیشه در باطن خویش دارد چیست ؟ (کیمیای سعادت ). سلطان از عشق او چنان گشت که یک ساعت شکیبا نتوانست بود. (نوروزنامه ).<br />بهرچ از راه دور افتی چه کفر آن حرف و چه ایمان <br />بهرچ از دوست وامانی چه زشت آن نقش و چه زیبا.<br /> <font color=\"Red\">سنائی .</font><br />وعظ گفتی همیشه بر منبر<br />گرم و گیرا چو وعظ پیغمبر.<br /> <font color=\"Red\">(مثنوی ولدنامه ).</font><br />نه هرکه به صورت نکوست سیرت زیبا در اوست . (گلستان ).<br />گنداو تیز همچو پیاز و تُرُش چو دوغ .<br /> <font color=\"Red\">پوربهای جامی .</font><br />و الف آخر «گردا» از قبیل الف جویا و دانا نیست بلکه مخفف گردان است <span class=\"hlight\">:</span> <br />کسی کز خدمتت دوری کند هیچ <br />بر او دشمن شود گردون گردا.<br /> <font color=\"Red\">عسجدی .</font><br />بنگر بچشم خاطر و چشم سر<br />ترکیب خویش و گنبد گردا را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و گردا در کلمه ٔ مرکب «منش گردا» مخفف گردیده یا گردانیده باشد، و گاه برای لیاقت و سزاواری آید مانند خوانا و پذیرا: خطی خوانا (هر چند ظاهراً قدما کلمه ٔ خوانا را بدین معنی استعمال نکرده اند) <span class=\"hlight\">:</span> <br />پذیرا سخن بود و شد جایگیر<br />سخن کز دل آید بود دلپذیر.<br /> <font color=\"Red\">نظامی .</font><br />و «آ» (-ا) در کلمات بنما و ببخشا و بازآ و نظائر آن، مخفف «آی » (-ای ) است <span class=\"hlight\">:</span> <br />خدایا ببخشا گناه ورا<br />بیفزای در حشر جاه ورا.<br /> <font color=\"Red\">فردوسی .</font><br />کسی کو ندیده بجز کام و ناز<br />برو بر ببخشای روز نیاز.<br /> <font color=\"Red\">فردوسی .</font><br />ببخشای بر من، یکی درنگر<br />که سوزان شود هر زمانم جگر.<br /> <font color=\"Red\">فردوسی .</font><br />بازآ بازآ هر آنچه هستی بازآ<br />گر کافر و گبر و بت پرستی بازآ<br />این درگه ما درگه نومیدی نیست <br />صد بار اگر توبه شکستی بازآ.<br /> <font color=\"Red\">(منسوب بخیام ).</font><br />بازآ که در فراق تو چشم امیدوار<br />چون گوش روزه دار بر اﷲاکبر است .<br /> <font color=\"Red\">سعدی .</font><br />ایا پر لعل کرده جام زرین <br />ببخشا بر کسی کش زر نباشد.<br /> <font color=\"Red\">حافظ.</font><br />و در آخر امر و نهی معنی تنبیه و تحذیر دهد <span class=\"hlight\">:</span> <br />مبادا که تنها بود نامجوی <br />بویژه که دارد سوی جنگ روی .<br /> <font color=\"Red\">فردوسی .</font><br />مبادا که بهمن شود تاجدار<br />بخواهد ز ما کین اسفندیار.<br /> <font color=\"Red\">فردوسی .</font><br />مبادا که در دهر دیر ایستی <br />مصیبت بود پیری و نیستی .<br /> <font color=\"Red\">فردوسی .</font><br />مبادا که گستاخ باشی بدهر<br />که زهرش فزون باشد از پای زهر.<br /> <font color=\"Red\">فردوسی .</font><br />در این ره گرم رو میباش لیک از روی نادانی <br />نگر مندیشیا هرگز که این ره را کران بینی .<br /> <font color=\"Red\">سنائی .</font><br />و نیز در آخر مضارع به معنی دعا و نفرین و خواهشهای دیگر آید <span class=\"hlight\">:</span> <br />هر چند بلای می بشویی ما را<br />کس مشنودا آنچه تو گوئی ما را.<br /> <font color=\"Red\">مسعودسعد.</font><br />سرمه ٔ چشم بزرگان باد خاک پای تو<br />وز بزرگان هیچکس منشیندا بر جای تو.<br /> <font color=\"Red\">سوزنی .</font><br />منشیندا از نیکوان جز تو کسی بر جای تو<br />کم بیندا جز من کسی آن روی شهرآرای تو.<br /> <font color=\"Red\">(از المعجم ).</font><br />و گاه این الف دعا و خواهش را با الف دعا و یائی که پیش از حرف آخر مضارع می آید جمع کنند در یک کلمه، چنانکه در مبادا و بادا <span class=\"hlight\">:</span> <br />بادا رخ عدوی تو همچون بهی دژم <br />روی تو باد همچو گل از شادی وبهی .<br /> <font color=\"Red\">رودکی .</font><br />همه مهتران خواندند آفرین <br />که بی تاج و تختت مبادا زمین .<br /> <font color=\"Red\">فردوسی .</font><br />همه انجمن خواندند آفرین <br />که آباد بادا بدادت زمین .<br /> <font color=\"Red\">فردوسی .</font><br />بمنذر بگوید که ای سرفراز<br />جهان را به نام تو بادا نیاز.<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت کاین نامه سوی مهست <br />سرافراز پرویز یزدان پرست <br />ز قیصر پدر مادر و شیرنام <br />که پاینده بادا بدو نام و کام .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت موبد بجان و سرت <br />که جاوید بادا سر و افسرت .<br /> <font color=\"Red\">فردوسی .</font><br />شنیدم همه هرچه گفتی بمهر<br />که از جان تو شادبادا سپهر.<br /> <font color=\"Red\">فردوسی .</font><br />ورا نام شاپور کردم ز مهر<br />که از بخت او شاد بادا سپهر.<br /> <font color=\"Red\">فردوسی .</font><br /> <br />بنام ایزد احسنت و خه نکو خلفی <br />ز چشم بد مرسادا بدولت تو گزند.<br /> <font color=\"Red\">سوزنی .</font><br />همیشه تا بسه قسمت بود مه روزه <br />بهر سه قسمت از ایزد کرامتی دیگر<br />غریق رحمت بادی بقسمت اول <br />دوم ز مغفرت جرم بر سرت مغفر<br />چو از عذاب سقر بنده خواهد آزادی <br />بقسمت سوم آزاد بادیا ز سقر.<br /> <font color=\"Red\">سوزنی .</font><br />و الف ِ گوییا و گویا که مخفّف آن است و الف پنداریا ظاهراً برای زینت باشد، چه از لفظ گویی و پنداری مُجرّد هم معنی گمان و تردید دانسته شود و در لفظ گوییا و گویا وپنداریا معنی زائدی نیست <span class=\"hlight\">:</span> <br />تو چه پنداریا که من ملخم <br />که بترسم ز بانگ سینی و طاس .<br /> <font color=\"Red\">؟ (از فرهنگ اسدی ).</font><br />رشح شبنم بر گیا پنداریا<br />بر لب خضر آب حیوان میچکد.<br /> <font color=\"Red\">؟ (از المعجم ).</font><br />گوییا با شیر خوردم عشق تو<br />کز تنم بی جان نمیگردد جدا.<br /><font color=\"Red\">؟ (از المعجم ).</font><br />گوییا باور نمیدارند روز داوری <br />کاین همه قلب و دغل درکار داور میکنند.<br /> <font color=\"Red\">حافظ.</font><br />صاحب دیوان ما گویا نمیداند حساب <br />کاندر این طغرا نشان حسبةﷲ نیست .<br /> <font color=\"Red\">حافظ.</font><br />گویا طلوع میکند از مغرب آفتاب <br />کآشوب در تمامی ذرات عالم است .<br /> <font color=\"Red\">محتشم .</font><br />فریاد بسی کردم و فریادرسی نیست <br />گویا که در این گنبد فیروزه کسی نیست .<br /> <font color=\"Red\">؟</font><br />و الف ِ ندانما در این مصرع قاآنی :<br />ندانما ز کودکی شکوفه از چه پیر شد.<br />و نظائر آن اگر آمده باشد برای حفظ وزن است و بس و چیزی بر معنی نمی افزاید. به آخر کلمه ٔ گفت نیز گاهی الف افزایند و آن ظاهراً ضمیر مفرد غائب است <span class=\"hlight\">:</span> <br />ناهید چون عقاب ترا دید زیر تو<br />گفتا درست هاروت ازبند رسته شد.<br /> <font color=\"Red\">دقیقی .</font><br />گفتا مرا چه چاره که آرام هیچ نیست <br />گفتم که زود خیز و همی گرد چام چام .<br /> <font color=\"Red\">منجیک .</font><br />بگفتا فروغی است این ایزدی <br />بپرسید باید اگر بخردی .<br /> <font color=\"Red\">فردوسی .</font><br />بگفتا من گِلی ناچیز بودم <br />ولیکن مدتی با گُل نشستم .<br /> <font color=\"Red\">سعدی .</font><br />گفتا برون شدی بتماشای ماه نو<br />از طاق ابروان منت شرم باد و رو.<br /> <font color=\"Red\">حافظ.</font><br />گفتم غم تو دارم، گفتاغمت سرآید<br />گفتم که ماه من شو، گفتا اگر برآید.<br /> <font color=\"Red\">حافظ.</font><br /> <br />الف لیّنه در آخر صفت گاهی دلالت بر بسیاری و تکثیر و تفخیم و تعجب کند، چون اندکا و نیکا و بدا و خوشا و خرّما <span class=\"hlight\">:</span> <br />خوشا نبید غارجی با دوستان یکدله <br />گیتی به آرام اندر و مجلس به بانگ ولوله .<br /> <font color=\"Red\">شاکر بخاری (از فرهنگ اسدی ).</font><br />بزرگوارا کاری که آمد از پدرت <br />بدولت پدر تو نبود هیچ پدر.<br /> <font color=\"Red\">فرخی .</font><br />نیک و بد این عالم پیش و پس کار او<br />زودا که تو دریابی زودا که تو بنگاری .<br /> <font color=\"Red\">منوچهری .</font><br />گفت نیکا گرده ها که آن گرده های جو بود و آن کس را که بوی خرسند باشد و از وی سیر گردد که وی نان منست و نان پیغمبران دیگر. (نوروزنامه ).<br />شکل دندان و سر زلف تو زودا که برو<br />سین و نون و الف و یا همه تاوان آرند.<br /> <font color=\"Red\">سنائی .</font><br />زیر و زبر عالم بهر طلب است ارنی <br />تنگا که زمینستی لنگا که زمانستی .<br /> <font color=\"Red\">سنائی .</font><br />مشکلا کاری که افتادت چه سود<br />کار سخت و نیست استادت چه سود.<br /> <font color=\"Red\">عطار.</font><br />خوشا وقت شوریدگان غمش <br />اگر زخم بینند و گر مرهمش .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />بزرگا جود دادار جهان بین <br />که بخشد مردمی را فضل چندین .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />و گاه درآخر صفت و موصوف هر دو الف کثرت و تعجّب و تعظیم آرند <span class=\"hlight\">:</span> <br />گفتم نایَمْت نیز هرگز پیرامنا<br />بیهده گفتم من این، بیهده گویا منا.<br /> <font color=\"Red\">اورمزدی .</font><br />بزرگوارا شاهنشها که خسروماست <br />بخوی خوب و به نام ستوده و اورنگ .<br /> <font color=\"Red\">فرخی .</font><br />همایونا کف دستا که آن دستست و آن بازو<br />که هم ابواب ارزاق است و هم آیات رزاقش .<br /> <font color=\"Red\">منوچهری .</font><br />بزرگا مردا که دامن قناعت تواند گرفت و حرص را گردن فروتواند شکست . (تاریخ بیهقی ). پس گفت <font color=\"DarkGreen\"><b>[ مادر حسنک ]</font></b> بزرگا مردا که این پسرم بود که پادشاهی چون محموداین جهان بدو داد و پادشاهی چون مسعود آن جهان . (تاریخ بیهقی ). گفت بزرگا شفیعا که تو آوردی و عزیز خواهشی که تراست . (نوروزنامه ).<br />ز آدم حرص میراث است ما را<br />درازا محنتا وآشفته کارا.<br /> <font color=\"Red\">عطار.</font><br />اگر آن دم نیاموزی تو گفتار<br />درازا منزلا و مشکلا کار.<br /> <font color=\"Red\">عطار (الهی نامه ).</font><br />و گاه این الف را تنها به آخر موصوف افزایند: با خود گفتم در بزرگ غلطا که من بودم، حق به دست خوارزمشاه است . (تاریخ بیهقی ).<br />ساده دل مردا که دل بر وعده ٔ مستان نهاد.<br /> <font color=\"Red\">سنائی .</font><br />و اما الفی که در نظم و نثر به آخر کلمه ٔ بس افزایند برای تأکید کثرت است . و این الف را گاهی تنها بهمان کلمه ٔ بس افزایند <span class=\"hlight\">:</span> <br />بسا شکسته بیابان که باغ خرم بود<br />و باغ خرم گشت آن کجا بیابان بود.<br /> <font color=\"Red\">رودکی .</font><br />بسا جای کاشانه و بادغرد<br />بدو اندرون شادی و نوشخورد.<br /> <font color=\"Red\">ابوشکور.</font><br />و گاهی به آخر موصوف یا معدود آن نیز مزید کنند <span class=\"hlight\">:</span> <br />بسا مرد بخیلا که می بخورد<br />کریمی بجهان در پراکنید.<br /> <font color=\"Red\">رودکی .</font><br />بسا کسا که بره ست و فرخشه بر خوانش <br />و بس کسا که جوین نان همی نیابد سیر.<br /> <font color=\"Red\">رودکی .</font><br />بسا کسا که ندیم حریره و بره است <br />و بس کس است که سیری نیاید از ملکش .<br /> <font color=\"Red\">ابوالمؤید.</font><br />خماردار همه ساله با کیاربود<br />بسا سرا که جدا کرد در زمانه خمار.<br /> <font color=\"Red\">دقیقی .</font><br />بسا روزگارا که بر کوه و دشت <br />گذشته ست و بسیار خواهد گذشت .<br /> <font color=\"Red\">فردوسی .</font><br />بسا تنا که فرستد دمادم اندر پس <br />سنان نیزه ٔ او از وجود سوی عدم .<br /> <font color=\"Red\">فرخی .</font><br />بسا زورمندا که افتاده سخت <br />بس افتاده را یاوری کرده بخت .<br /> <font color=\"Red\">اسدی .</font><br />و گاهی تنها به آخر موصوف یا معدود یا متعلقی دیگر افزایند <span class=\"hlight\">:</span> <br />و بس کسا که جوین نان همی نیابد سیر.<br /> <font color=\"Red\">رودکی .</font><br />بس بناگوش چو سیما که سیه شد چو شبه <br />آن ِ تو نیز شود صبر کن ای جان جهان .<br /> <font color=\"Red\">فرخی .</font><br />الف لیّنه در آخر صفت به معنی یاء مصدری هم آید و صفت را در چنین مورد بدل به اسم مصدر کند، چون درازا و پهنا و ژرفا و ستبرا و فراخا و باریکا و گرما و تاریکا. (نا نیز در آخر صفت افاده ٔ همین معنی کند، مانند درازنا و فراخ نا و تنگنا و تیزنا و ستبرنا و ژرف نا). و گاه درآخر کلمه ای که خود بیاء مصدری ختم شده است بدل یاء تنکیر آید سهولت ادا را <span class=\"hlight\">:</span> <br />بدا سلطانیا کو را بود رنج دل آشوبی <br />خوشا درویشیا کو را بود گنج تن آسانی .<br /> <font color=\"Red\">خاقانی .</font><br />الف لیّنه در آخر اسمها و صفتها گاه معنی ندا و خطاب دهد، چون دلا و جانا و پسرا و شها و بزرگا و مخدوما و قبله گاها و «ا»ی ِ ندا چون در آخر کلماتی مانند خدا درآید کلمه به صورت اصلی و تمام خود بازگردد <span class=\"hlight\">:</span> <br />خدایاببخشا گناه ورا<br />بیفزای در حشر جاه ورا.<br /> <font color=\"Red\">فردوسی .</font><br />بیدلی در همه احوال خدا با او بود<br />او نمیدیدش و ازدور خدایا میکرد.<br /> <font color=\"Red\">حافظ.</font><br />و گاه معنی تأسف و تحسر و توجّع وندبه و استغاثه را تأکید کند، چنانکه در زبان عرب نیز «ا» و «اه » در کلمات وامحمدا و واویلا و وااسلاما و وامحمداه و واویلاه و وااسلاماه و نظایر آن همین معنی بخشد <span class=\"hlight\">:</span> <br />دریغا تهی از تو ایران زمین <br />همه زار و بیمار و اندوهگین <br />دریغا که بدخواه دلشاد گشت <br />دریغا که رنجم همه باد گشت .<br /> <font color=\"Red\">فردوسی .</font><br />دردا و حسرتا که عنانم ز دست رفت <br />دستم نمیرسد که بگیرم عنان دوست .<br /> <font color=\"Red\">سعدی .</font><br />دل میرود ز دستم صاحبدلان خدا را<br />دردا که راز پنهان خواهد شد آشکارا. <br /> <font color=\"Red\">حافظ.</font><br />دردا و حسرتا که مرا دور روزگار<br />بی آلت و سلاح بزدراه کاروان .<br /> <font color=\"Red\">؟</font><br />دردا و دریغا که در این خورد و نشست <br />خاکی است مرا در کف و بادی است بدست .<br /> <font color=\"Red\">؟</font><br />و الف ندبه را گاه بقرینه حذف کنند <span class=\"hlight\">:</span> <br />بزاری همی گفت پس پیلتن <br />که شاهادلیرا سر انجمن <br />کیا کی نژادا شها سرورا<br />جهان شهریارا و گندآورا.<br /> <font color=\"Red\">فردوسی .</font><br />یعنی سر انجمنا.<br />و در آخر نامهای خاص برای تفخیم و تعظیم آید، مانند عمادا و جلالا و محمودا و احمدا و صدرا و صائبا. و الف مسیحا جزء کلمه است، چه اصل آن به عبری «ماشیاه » است به معنی مسح شده و مدهون <span class=\"hlight\">:</span> <br />فیض روح القدس ار باز مدد فرماید<br />دیگران هم بکنند آنچه مسیحا میکرد.<br /> <font color=\"Red\">حافظ.</font><br />و در آخر بعض اسمها بجای تنوین نصب عربی باشد <span class=\"hlight\">:</span> <br />خاقان اعظم کز شرف آمد سلاطین را کنف <br />باران جود از ابر کف شرقا و غربا ریخته .<br /> <font color=\"Red\">خاقانی .</font><br />گذشت آن نوبت قولا ثقیلا<br />تو بر در باش اکنون جبرئیلا.<br /> <font color=\"Red\">عطار (اسرارنامه ).</font><br />من و انک</font></div>'),
(2, 'آء', '<span class=\"hlight\">آء.</span> (ع اِ) ج ِ آءة.<br /></font></div>'),
(3, 'آآ', '<span class=\"hlight\">آآ.</span> (اِخ ) (کلمه ٔ آلمانی به معنی آب ) نام عده ٔ بسیاری از رودخانه های ممالک سلت و آلمان . <BR><font color=\"Blue\">◄</font> نام رودخانه ٔ ساحلی فرانسه (دریای شمال ) که کشت و زرع سنتومر بدوست . طول آن <span class=\"hlight\" dir=\"rtl\">٨٠</span> هزار گز.<br /></font></div>'),
(4, 'آآر', '<span class=\"hlight\">آآر.</span> (اِخ ) رودخانه ای است در سویس که از گردنه ٔ «گِرمَسل » سرچشمه گیرد و «برن » و «سُلور» را آبیاری کند و با «روس » و «لیما» و «تی یِل » یکی شده به رود رَن ریزد. طول آن <span class=\"hlight\" dir=\"rtl\">٢٨٠</span> هزار گز.<br /></font></div>'),
(5, 'آآرو', '<span class=\"hlight\">آآرو.</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) شهری است در سویس کرسی ولایت آرگوی، در ساحل «آر»، دارای <span class=\"hlight\" dir=\"rtl\">١٢٠٠٠</span> تن سکنه .<br /></font></div>'),
(6, 'آارخیس', '<span class=\"hlight\">آارخیس .</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِ) آرخیس . آرغیس . اَرغیس . پوست ریشه ٔ امبرباریس یعنی زرشک و در دمشق و مصر آن را عودالریح خوانند.<br /></font></div>'),
(7, 'آارس', '<span class=\"hlight\">آارس .</span> <font color=\"DarkGreen\"><b>[ اُ رُ ]</font></b> (اِخ ) نام بندری به دانمارک دارای <span class=\"hlight\" dir=\"rtl\">٧٨٠٠٠</span> مردم .<br /></font></div>'),
(8, 'آاطریلال', '<span class=\"hlight\">آاطریلال .</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِ) آطریلال . رجوع به اَآطریلال و اِطریلال شود.<br /></font></div>'),
(9, 'آالبرگ', '<span class=\"hlight\">آالبرگ .</span> <font color=\"DarkGreen\"><b>[ اُ ب ِ ]</font></b> (اِخ ) نام بندری است به دانمارک دارای <span class=\"hlight\" dir=\"rtl\">٤٣٠٠٠</span> تن سکنه .<br /></font></div>'),
(10, 'آانس', '<span class=\"hlight\">آانس .</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِ) سپند.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(11, 'آب', '<span class=\"hlight\">آب .</span> (اِ) (اوستائی آپ <span class=\"hlight\" dir=\"rtl\">ap</span>، سانسکریت آپ َ <span class=\"hlight\" dir=\"rtl\">apa</span>، پارسی باستانی آپی <span class=\"hlight\" dir=\"rtl\">api</span>، پهلوی آپ <span class=\"hlight\" dir=\"rtl\">ap</span>) مایعی شفاف بی مَزه و بوی که حیوان از آن آشامد و نبات بدان تازگی و تری گیرد. و آن یکی از چهار عنصر قدماست و به عربی آن را ماء و بلال خوانند. و ابوحیّان و ابوالحیوة و ابوالعباب و ابوالغیاث و ابومدرک از کنیتهای آن است و در بعض لهجه های فارسی آف، آو، و اَو گویند . حصبه، وبا، نوبه، ذوسنطاریا و بسیاری از بیماریهای وافِده و نیز بقاعی از آب ناپاک و آلوده زاید. <BR><font color=\"Blue\">◄</font> دریا. بحر. مقابل خشکی و برّ. <BR><font color=\"Blue\">◄</font> دریاچه . بحیره <span class=\"hlight\">:</span> <br />بیاورد لشکر بدریای چین <br />بر او تنگ شد پهن روی زمین <br />بدانگه کجا خواست بگذاشت آب <br />به پیران چنین گفت افراسیاب .<br /> <font color=\"Red\">فردوسی .</font><br />بمادر چنین گفت کافراسیاب <br />فرستاد و خوانَد مرا نزد آب <font color=\"DarkGreen\"><b>[ دریای چین ]</font></b>.<br /> <font color=\"Red\">فردوسی .</font><br />دگر نامور گنج افراسیاب <br />که کس را نبود آن بخشکی و آب .<br /> <font color=\"Red\">فردوسی .</font><br />که بازارگانان ایران بدند<br />به آب و بخشکی دلیران بدند.<br /> <font color=\"Red\">فردوسی .</font><br />قضا را من و پیری از فاریاب <br />رسیدیم در خاک مغرب به آب .<br /> <font color=\"Red\">سعدی .</font><br />مراپیر دانای مرشد شهاب <br />دو اندرز فرمود بر روی آب .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آبهای اسلامبول </span> ؛ دریاهای ساحلی آن .<br /> <BR><font color=\"Blue\">◄</font> رود. نهر. جوی . چشمه <span class=\"hlight\">:</span> واندر وی <font color=\"DarkGreen\"><b>[ اندر دریاچه ٔ بتمان ]</font></b> آبها درافتد از بتمان میانه . (حدودالعالم ). و چون از آنجا <font color=\"DarkGreen\"><b>[ از سول ]</font></b> بهندوستان بروی تا بحسینان راه اندر میان دو کوه است و اندر این راه هفتاد و دو آب بباید گذاشتن . (حدودالعالم ).<br />رسیدند بر آب گل زرّیون <br />شهنشاه را گیو بد رهنمون .<br /> <font color=\"Red\">فردوسی .</font><br />بد آن آب را نام گل زرّیون <br />بدی در بهاران چو دریای خون .<br /> <font color=\"Red\">فردوسی .</font><br />ز جنگش بپستی بپیچید روی <br />گریزان همی رفت پرخاش جوی <br />چو از آب وز لشکرش دور کرد<br />بزین اندر افکند گرز نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />دو <font color=\"DarkGreen\"><b>[ شهر ]</font></b> در بوم بغداد و آب فرات <br />پر از چشمه و چارپای ونبات .<br /> <font color=\"Red\">فردوسی .</font><br />ملک بر پسران قسمت کرد، ترکستان از آب جیحون تا چین و ماچین تور را داد. (نوروزنامه ).<br />عاقل بکنار آب تا ره می جست <br />دیوانه ٔ پابرهنه از آب گذشت .<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب زمزم </span> ؛ چشمه ٔ زمزم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب علا</span> ؛ چشمه ٔ علا بدماوند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب گرم </span> ؛ هر چشمه که آبش بطبع گرم بود.<br /><BR><font color=\"Blue\">◄</font> (اِخ ) جیحون <span class=\"hlight\">:</span> <br />خوش نخسبند همی از فزعش زآن سوی آب <br />نه قدرخان نه طغان خان نه خطاخان نه تکین .<br /> <font color=\"Red\">فرخی .</font><br />سکندر آنگه کز چین همی فرود آمد<br />بماند برلب جیحون سه ماه تابستان <br />بدان نیت که مگر پل بر آن تواند بست <br />همی نشسته در آن کار بسته جان و توان <br />هزار حیله فزون کرد و آب دست نداد<br />در آن حدیث فروماند عاجز و حیران .<br /> <font color=\"Red\">فرخی .</font><br />و اسفندیار سدی کرد برابر ترکان از پس بیست فرسنگی سمرقند و در آب سلسله ای عظیم آهنین ساخت تا گذار ترکان نیفتد. (مجمل التواریخ و القصص ).<br />سواد نظم مرا گر بود بر آب گذر<br />کنند فخر رشیدی و صابر و عمعق . <br /> <font color=\"Red\">انوری .</font><br /> <BR><font color=\"Blue\">◄</font> سیحون <span class=\"hlight\">:</span> <br />تا بدید آتش ملک سیحون <br />هم بر آن آب نیست آب کنون .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> رود گنگ <span class=\"hlight\">:</span> <br />چو بشنید بدگوهر افراسیاب <br />که شد طوس و رستم بر آن روی آب <br />شد از باختر سوی دریای گنگ <br />دلی پر ز کین و سری پر ز جنگ .<br /> <font color=\"Red\">فردوسی .</font><br />با آنکه فرهنگ نویسان به آب معنی جیحون و سیحون و گنگ و امثال آن داده اند لیکن حق آن است که مجاورین هر رود و دریایی از آب همان معنی اصلی او را اراده می کرده اند نه آنکه آب نام آن رودها و دریاها باشد. <BR><font color=\"Blue\">◄</font> (اِ) بول . گمیز. شاش . و آب در آب تاختن و آب ریختن و آب افکندن و آب انداز از این قبیل است <span class=\"hlight\">:</span> <br />گراین اسب سرگین و آب افکند<br />و گر خشت این خانه را بشکند<br />بشبگیر سرگینْش بیرون بری ...<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> قاروره . تفسره . دلیل . بیسیار <span class=\"hlight\">:</span> خواجه اسماعیل قاروره نگرید، گفت این آب فلان است و فواقش پدید آمده . (چهارمقاله ). <BR><font color=\"Blue\">◄</font> اشک . دمعه . سرشک <span class=\"hlight\">:</span> <br />ز سوک سیاوش پر از آب روی <br />برخ بر نهاده ز دیده دو جوی .<br /> <font color=\"Red\">فردوسی .</font><br />بر آنسان به نزدیک افراسیاب <br />ببردند رخ زرد و دیده پرآب .<br /> <font color=\"Red\">فردوسی .</font><br />خروشید سودابه در پیش اوی <br />همی ریخت آب و همی کند موی .<br /> <font color=\"Red\">فردوسی .</font><br />گشادند از دیدگان هر دو آب <br />زبان پر ز نفرین افراسیاب .<br /> <font color=\"Red\">فردوسی .</font><br />چو گیو آن نشان دید بردش نماز<br />همی ریخت آب و همی گفت راز.<br /> <font color=\"Red\">فردوسی .</font><br />همی رفت سوی سیاووش گرد<br />بماه سفندارمذروز ارد<br />چو آمد بدین شارسان پدر<br />دو رخسار پرآب و خسته جگر...<br /> <font color=\"Red\">فردوسی .</font><br />وز آن پس فروریخت بر چهره آب <br />بسی یاد کرد از رد افراسیاب .<br /> <font color=\"Red\">فردوسی .</font><br />از آن درد بگریست افراسیاب <br />همی کند موی و همی ریخت آب .<br /> <font color=\"Red\">فردوسی .</font><br />ز درد برادر پر از آب روی <br />گزین کرد نیک اختری چرب گوی .<br /> <font color=\"Red\">فردوسی .</font><br />بترسید کو را بد آمد بروی <br />دلش گشت پرخون و پرآب روی .<br /> <font color=\"Red\">فردوسی .</font><br />همی کند گودرز کشواد موی <br />همی ریخت آب و همی خست روی .<br /> <font color=\"Red\">فردوسی .</font><br />نهادند سر سوی افراسیاب <br />همه رخ ز خون سیاوش پرآب .<br /> <font color=\"Red\">فردوسی .</font><br />رسیدند یاران لشکر بدوی <br />غمی یافتندش پر از آب روی .<br /> <font color=\"Red\">فردوسی .</font><br />همه زار و گریان و پرآب روی <br />زبان شاه گوی و روان شاه جوی .<br /> <font color=\"Red\">فردوسی .</font><br />همه سوگوار و پر از آب روی <br />سوی راه ایران نهادند روی .<br /> <font color=\"Red\">فردوسی .</font><br />نگون شدسر و تاج افراسیاب <br />همی کند موی و همی ریخت آب .<br /> <font color=\"Red\">فردوسی .</font><br />چو زآن گونه دیدند گفتار اوی <br />برفتند گریان و پرآب روی .<br /> <font color=\"Red\">فردوسی .</font><br />نگه کرد پیران بر آن فر و چهر<br />رخش گشت پرآب و دل پر ز مهر.<br /> <font color=\"Red\">فردوسی .</font><br />ز تاب ماند جانم به آذرِ برزین <br />ز آب ماند چشمم برود آبسکون .<br /> <font color=\"Red\">قطران .</font><br />موسی را آب در چشم آمد. (مجمل التواریخ ).<br /> و آب دیده و آب چشم و آب مژه و آب گرم نیز به معنی سرشک است . و آب بچشم و در چشم گردانیدن وآب بچشم و بدیده آوردن، گریستن و گریه آغازیدن باشد. <BR><font color=\"Blue\">◄</font> خلط که از بینی ترشح کند. مخاط. خلم . <BR><font color=\"Blue\">◄</font> بصاق . رضاب . خیو. خیم . و نیز لیزآبه ٔ دهان گاو و جز آن <span class=\"hlight\">:</span> <br />بر این شهر بگذشت پویان دو تن <br />پر از گرد و بی آب گشته دهن .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> خوی . عرق <span class=\"hlight\">:</span> <br />پرآب ترا غیبه های جوشن <br />پرخاک ترا فرجه های دیبا.<br /> <font color=\"Red\">منجیک .</font><br />بیامد به نزدیک افراسیاب <br />نیا را رخ از شرم شد پر ز آب .<br /> <font color=\"Red\">فردوسی .</font><br />دهان خشک و غرقه شده تن در آب <br />ز رنج و ز تابیدن آفتاب .<br /> <font color=\"Red\">فردوسی .</font><br />فرستاده آمد رخی پر ز شرم <br />ز شرم فریدون پر از آب گرم .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> (اصطلاح کحالی ) رطوبت غریبه که زیرثقبه ٔ عنبیه میان رطوبت بیضیه و صفاق قرنی پیدا آید. و فعل آن آب آوردن چشم باشد <span class=\"hlight\">:</span> <br />هر چشم که از خاک درت سرمه ٔ او بود<br />زآوردن هر آب که آرد نشود تار.<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> (اصطلاح طب ) رطوبتی که در شکم یا زیر پوست مستسقی گرد آید. <BR><font color=\"Blue\">◄</font> (اصطلاح بیطاری ) رطوبتی که در پی و زانوی ستور جمع شود. (السامی فی الاسامی ). <BR><font color=\"Blue\">◄</font> نطفه . (السامی فی الاسامی ). منی . آب پشت <span class=\"hlight\">:</span> <br />هر آنکس که او باشد از آب پاک <br />نیارد سر گوهر اندر مغاک .<br /> <font color=\"Red\">فردوسی .</font><br />که بهرام فرزند او همچو اوست <br />ز آب پدر یافت او مغز و پوست .<br /> <font color=\"Red\">فردوسی .</font><br />کسی کو برادر فروشد بخاک <br />سزد گر نخوانندش از آب پاک .<br /> <font color=\"Red\">فردوسی .</font><br />آب کارت مبر که گردی پیر<br />کار این آب را تو سهل مگیر.<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> عصاره و شیره که از بعض میوه ها و گیاهان گیرند، خواه به کوفتن چون آب گشنیز و کاسنی و قصیل و خواه به فشردن، چون آب غوره و آب انار و آب هندوانه <span class=\"hlight\">:</span> <br />ویحک ای برقعی ای تلختر از آب فرژ<br />تا کی این طبع بد تو که گرفتی سر پژ.<br /> <font color=\"Red\">منجیک .</font><br />وآب انگور بگرفتند و خم پر کردند. (نوروزنامه ). دفع مضرت شراب مویزی با سکنجبین و آب کاسنی و تخم خیار... کنند. (نوروزنامه ). <BR><font color=\"Blue\">◄</font> آب که از جوشانیدن چیزی در آب حاصل کنند، چون آبگوشت، نخوداب، آبچلو. <BR><font color=\"Blue\">◄</font> آب که از تخمیر چیزی بدست کنند، چون آب جو، و آب انگور بمعنی شراب . <BR><font color=\"Blue\">◄</font> نرمی و پختگی که در میوه به آغاز رسیدن پیدا آید، و فعل آن آب افتادن باشد. <BR><font color=\"Blue\">◄</font> زیبق . جیوه . سیماب . <BR><font color=\"Blue\">◄</font> مستراح . مبرز: سر آب رفتن، دست به آب رسانیدن ؛ یعنی به آبخانه شدن . <BR><font color=\"Blue\">◄</font> عطر و عَرَقهای نباتی : و از وی <font color=\"DarkGreen\"><b>[ از پارس ]</font></b> آب گل و آب بنفشه و آب طلع خیزد. (حدودالعالم ). <BR><font color=\"Blue\">◄</font> شرم و حیا <span class=\"hlight\">:</span> <br />بر روی بیخرد نبود شرم و آب <br />آن کس که باک نیستش از سرزنش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و به این معنی شرم آب و آب شرم نیز گویند <span class=\"hlight\">:</span> <br />مباد اندرآن دیده در آب شرم <br />که از درد ما نیست پر خون گرم .<br /> <font color=\"Red\">فردوسی .</font><br />شاب نه ای چونکه به شویی همی <br />شرم کن از روی مَشو شرم آب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چون سگ و گربه آب شرم برد<br />تا ز خلق آب و نان گرم برد.<br /> <font color=\"Red\">سنائی (حدیقه ).</font><br /> <BR><font color=\"Blue\">◄</font> طراوت و تازگی و لطافت <span class=\"hlight\">:</span> <br />چو آمد ببرج حمل آفتاب <br />جهان گشت با فر و آیین و آب .<br /> <font color=\"Red\">فردوسی .</font><br />و امیر فرمود که قصاص باید کرد. مهتر سرای گفت زندگانی خداوند دراز باد دریغ باشد اینچنین رویی زیر خاک کردن . امیر گفت او را هزار چوب بزنند و خصی کرد. اگر بمیرد قصاص کرده باشند، اگربزیَد بگویم تا چه کار را شاید. بزیست و به آب خود بازآمد، و در خادمی هزار بار نیکوتر از آن شد و زیباتر. (تاریخ بیهقی ).<br />آب نمانده در آن دو رنگین سوسن <br />تاب نمانده در آن دو مشگین چنبر.<br /> <font color=\"Red\">مسعودسعد.</font><br />چو باغ گشت خراب از خزان نماندش آب <br />نماند آب مر آن جای را که گشت خراب .<br /> <font color=\"Red\">مسعودسعد.</font><br />جانا خوش است تحفه ٔ باغ بتان ولیک <br />نوباوه ٔ جمال ترا آب دیگر است .<br /> <font color=\"Red\">سیدحسن غزنوی .</font><br />نماند قوت آذر ز صولت آذر<br />برفت آب ریاحین ز صدمت آبان .<br /> <font color=\"Red\">جمال الدین عبدالرزاق .</font><br />پیش رخسار عرقناک تو مه را تاب نیست <br />چشمه ٔ خورشید را گر تاب هست این آب نیست .<br /> <font color=\"Red\">نظامی .</font><br />ز تازگی نوزیده نسیم صبح بر او<br />فرو همی چکد از آتش عذارش آب .<br /> <font color=\"Red\">سیف اسفرنگ .</font><br /> <BR><font color=\"Blue\">◄</font> روش . طرز. وتیره . گونه . نوع <span class=\"hlight\">:</span> <br />تا بدید آتش ملک سیحون <br />هم بر آن آب نیست آب کنون .<br /> <font color=\"Red\">سنائی .</font><br />ز غزنی تا لب دریا در این باب <br />همه اسلام بینی بر یکی آب .<br /> <font color=\"Red\">امیرخسرو.</font><br />بسی گشتم در این گردنده دولاب <br />ندیدم هیچ دورش بر یکی آب .<br /> <font color=\"Red\">امیرخسرو.</font><br />نیکوان راندند سوی گلشن و آب روان <br />هر بتی در هر چمن بر آب دیگر میرود.<br /> <font color=\"Red\">امیرخسرو.</font><br />باز ابر تیره از هر سوی سر برمیکند<br />سبزه را در هر چمن بر آب دیگر می کند.<br /> <font color=\"Red\">امیرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> رونق و رواج <span class=\"hlight\">:</span> <br />ای همه کار تو برونق و آب <br />وی همه رای تو درست و صواب .<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> درخشندگی و صفا و تلألؤ گوهرها، یعنی فلزات و احجار کریمه <span class=\"hlight\">:</span> <br />چون زورق افلاک پر از در ثمین کرد<br />آب گهر مدح تو این بحر روان را.<br /> <font color=\"Red\">سیف اسفرنگ .</font><br /> <BR><font color=\"Blue\">◄</font> رونق و روشنی دندان . (السامی فی الاسامی ). <BR><font color=\"Blue\">◄</font> مینای دندان <span class=\"hlight\">:</span> <br />زینهار از دهان خندانش <br />وآتش لعل و آب دندانش .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> جلا و صقال . <BR><font color=\"Blue\">◄</font> درجه ٔ الماس درخوبی و ارز: الماس آب اول . <BR><font color=\"Blue\">◄</font> باده . شراب . و در عبارت ذیل آب ظاهراً کنایه از شراب است <span class=\"hlight\">:</span> و طرفه آنکه من بنده که چون آهوی دام دریده و مرغ قفس شکسته آمده بودم و در تحذیر <font color=\"DarkGreen\"><b>[ از باده پیمائی بعلت نزدیکی دشمن ]</font></b> آنهمه مبالغت مینمودم چون همه ٔ ابلهان، الحاقاً للفرد بالاعم ّ، در شهر کوران دست بدیده ٔباز نهادم و مصلحت کلی فرا آب داد. عُقاب عِقاب در شتاب و مجلس اعلی در شراب . (نفثةالمصدور زیدری ). <BR><font color=\"Blue\">◄</font> جاه . منزلت . مقام . عز. شرف . قدر. قیمت . خطر. اعتبار. آبروی . فر. شکوه . حیثیت . مرتبت . رتبت و محل <span class=\"hlight\">:</span> <br />ناسزا را مکن آیفت که آبت بشود<br />بسزاوار کن آیفت که ارجت دارد.<br /> <font color=\"Red\">دقیقی .</font><br />بگویش بر آن رو که باشد صواب <br />که پیش شه هند بفزایی آب .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد بگفتش بافراسیاب <br />که ای شاه بادانش و فر و آب .<br /> <font color=\"Red\">فردوسی .</font><br />ورا <font color=\"DarkGreen\"><b>[ سیاوش را ]</font></b> هر زمان پیش افراسیاب <br />فزونتر شدی حشمت وجاه و آب .<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود <font color=\"DarkGreen\"><b>[ کیخسرو ]</font></b> تاجهن افراسیاب <br />بیارند در پیش با جاه و آب .<br /> <font color=\"Red\">فردوسی .</font><br />سپهرم ز خویشان افراسیاب <br />گوی نامور بود با جاه و آب .<br /> <font color=\"Red\">فردوسی .</font><br />زده بر درش خیمه ٔ هر کسی <br />که نزدیک او آب بودش بسی .<br /> <font color=\"Red\">فردوسی .</font><br />آب و شرف و عز جهان روزبهان راست <br />ناروزبهان جمله نیرزند بنانی .<br /> <font color=\"Red\">فرخی .</font><br />گر سخن گوید آب سخن ما ببرد<br />بشود نور ستاره چو برآید مهتاب .<br /> <font color=\"Red\">فرخی .</font><br />من دو عمل را اندر سیستان خریدار بودم، کنون آب آن بشد، نخواهم . (تاریخ سیستان ). آنچه من کردمی امیری ِ شهر بود، کنون فلان گندمک را دادی، آب آن بشد، و دیگر امیری ِ آب بود فلان محمدبن عبدالرحمن را دادی آب آن بشد، کنون مرا هیچ عمل نماند و نخواهم و نکنم . (تاریخ سیستان ). <br />کند بیشرم هر کاری که خواهد<br />نترسد زآنکه آب او بکاهد.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />هرچند، بیک چیز آب خود ببری و دوستان را دل مشغول کنی . (تاریخ بیهقی ). چون فرمانی بدین مولی داده بود... نخواست آب و جاه وی بیکبار تباه شود. (تاریخ بیهقی ). هرچند سلطان پادشاهانه دریافت ولی آب این مرد ریخته شد. (تاریخ بیهقی ).<br />گر او را <font color=\"DarkGreen\"><b>[ ابن یامین را ]</font></b> نیارید با خویشتن <br />نباشد دگر آبتان نزد من .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />اگرچه نداری گنه نزد شاه <br />چنان باش پیشش که مرد گناه <br />چو چیزیش خواهی و ندْهد متاب <br />مبر به آتش خشمش از رویت آب .<br /> <font color=\"Red\">اسدی .</font><br />روی تازه ت زی سراب اندر منه <br />تا نریزد آن سراب از رویت آب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نزد مردم مر رجب را آب و جاه و حرمت است <br />گرچه گاو و خر نداند حرمت ماه رجب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آب ار بشودْتان بطمع باک ندارید<br />مانند ستوران سپس ِ آب و گیایید.<br /> <font color=\"Red\">ناصرخسرو.</font><br />از پی نان آبروی خویش مبر<br />آب بکار آیدت کز آب و گلی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />سخنم ریخت آب دیو لعین <br />ببدخشان و جام و تون و تراز.<br /> <font color=\"Red\">ناصرخسرو.</font><br />به نانشان چون من آب خویش بدهم <br />چو آبم شد من آنگه چون خورم نان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چون قیمت یاقوت به آبست تو دانی <br />کابت سخن است ای سره یاقوت سخندان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نماند آب سخن را چو رانی از پی نان .<br /> <font color=\"Red\">سنائی .</font><br />مغز را حزم شاه خواب ببرد<br />آب را عزم شاه آب ببرد.<br /> <font color=\"Red\">سنائی .</font><br />هنر ز بی هنری به و گرچه مرد هنر<br />خطر ندارد و دارد هزار گونه خطر<br />خطر بود هنری را ز بی هنر لیکن <br />هم از هنر هنری را فزاید آب و خطر.<br /> <font color=\"Red\">سوزنی .</font><br />گر برای او نباشد تو نخواهی صدر و قدر<br />ور برای تو نباشد او نخواهد جاه و آب .<br /> <font color=\"Red\">انوری .</font><br />چو باد ازآتشم تا کی گریزی <br />نه من خاک توام آبم چه ریزی ؟<br /> <font color=\"Red\">نظامی .</font><br />چون بصحرای سلیمانی رسید <font color=\"DarkGreen\"><b>[ بلقیس ]</font></b><br />خاک آن ره جمله زرّ پخته دید<br />بر سر زر تا چهل فرسنگ راند<br />تا که زر را در نظر آبی نماند.<br /> <font color=\"Red\">مولوی .</font><br />اگر چون زنان جست خواهی گریز<br />مرو آب مردان جنگی مریز.<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />گرفتن برد از رخ مرد آب <br />سیه روی شد تا گرفت آفتاب .<br /> <font color=\"Red\">سعدی .</font><br />وزیری که جاه من آبش بریخت <br />بفرسنگ باید ز مکرش گریخت .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />چو حکم ضرورت بود کآب روی <br />بریزند، باری بر این خاک کوی .<br /><font color=\"Red\">سعدی (بوستان ).</font><br />ور آبت نماند شفیع آر پیش <br />کسی را که هست آبرو از تو بیش .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />ابر میخواست که باران برد از بحر محیط<br />گفتمش آب خود ای ابر مبر پیش لئام .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />هرچند بردی آبم رو از درت نتابم <br />جور از حبیب خوشتر کز مدعی رعایت .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> خوی . طبع <span class=\"hlight\">:</span> <br />ای باد سحر بکوی آن سلسله موی <br />احوال دلم بگوی گر باشد روی <br />ور زانکه بر آب خود نباشد مه روی <br />زنهار مرا ندیده ای هیچ مگوی .<br /> <font color=\"Red\">مولوی (از مجالس سبعه ).</font><br />و صاحب برهان برای آب، معانی فیض و عطا و رحمت و دولت و ترقی و رواج و قاعده و قانون و خجلت زده و هموار براه رونده نیز ذکر کرده و کنایه از لؤلؤ و جواهر و شمشیر و تیغ جوهردار و نفس کامل و عقل کل که او را نفس ملهمه گویند، نیز گرفته است .<br /> - <span class=\"hlight\">آب آتش شدن </span> ؛ سکونت و آرامشی به فتنه و فساد وآشوب سخت بدل گشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از آب نجنبیدن، یا تکان نخوردن </span> ؛ آرامش و سکونت کامل برقرار بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از بنه تیره بودن </span> ؛ عیب و خلل در اصل و بنیان امر بودن <span class=\"hlight\">:</span> <br />سخن هرچه گفتم همه خیره بود<br />که آب روان از بنه تیره بود.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از تارک گذشتن </span> ؛ برسیدن، و به آخر شدن عمر. یکباره امیدبنومیدی بدل گشتن . بدبختی از حدّ تحمل تجاوز کردن <span class=\"hlight\">:</span> <br />بدو داد پس گنجها را کلید<br />یکی باد سرد از جگر برکشید<br />بدو گفت کار من اندرگذشت <br />هم از تارکم آب برتر گذشت <br />تواکنون همی کوش و با داد باش <br />چو داد آوری از غم آزاد باش .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از جگر بخشیدن </span> ؛ عطا کردن و چیزی بمردم دادن . (برهان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از چک و چانه سرازیر شدن کسی را</span> ؛ در تداول عوام بمزاح، از دیدن یا شنیدن چیزی سخت لذت بردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از دریا بخشیدن </span> ؛ از چیزی بی ارز و فراوان عطا دادن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از دست نچکیدن کسی را</span> ؛ سخت ممسک بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از دهان رفتن یا سرازیر شدن کسی را</span> ؛ سخت شیفته و خواهان چیزی گشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از سر تیره بودن، آب از بنه تیره بودن </span> ؛ نقص و عیب در اصل و بنیان امر بودن <span class=\"hlight\">:</span> <br />هجران تو زان تیره بکرد آب سرم <br />تا بشناسم که آبم از سر تیره ست .<br /> <font color=\"Red\">محمدبن نصیر.</font><br />تا تیره شده ست آبم از سر<br />اشکم بخلاف آن چو زنگ است .<br /> <font color=\"Red\">انوری .</font><br />مرا گوئی که آب از کار بردی <br />نبردم، خود ز سر تیره ست آبم .<br /> <font color=\"Red\">فتوحی مروزی .</font><br />آب از سر تیره است ای خیره خشم <br />بیشتر بنگر یکی بگشای چشم .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از سرچشمه گل بودن </span> ؛ آب از بنه تیره بودن وآب از سر تیره بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از سر گذشتن کسی را</span> ؛ آب از تارک گذشتن <span class=\"hlight\">:</span> <br />دل به من گوید چون آب تو از سر بگذشت <br />روی بر خاک نه از جور وی و زار بنال .<br /> <font color=\"Red\">رضی نیشابوری .</font><br />مرا بگذشت آب و رفت از سر<br />بر این حالم مدارا نیست درخور.<br /> <font color=\"Red\">(ویس و رامین ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب از کسی گشادن کسی را</span> ؛نفع و فائدت یا مددی از وی او را رسیدن <span class=\"hlight\">:</span> <br />هزار بیت بگفتم که آب از آن بچکید<br />که جزز دیده دگر آبم از کسی نگشاد.<br /> <font color=\"Red\">ظهیر فاریابی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب افتادن دهان </span> ؛ آب راندن آن از خوردن چیزی ترش و جز آن و مجازاً سخت شیفته ٔ چیزی شدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب انداختن دهان </span> ؛ فزوده شدن اشتها نسبت بچیزی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب انداختن ستور</span> ؛ میختن او.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب انداختن ماست و آش سرد</span> ؛ جداشدن آب آن از مواد دیگر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب باریک </span> ؛ آب جاری اندک . مجازاً، رزقی متوسط و دائم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب (آبی ) بر آتش کسی ریختن (زدن )</span> ؛ غم یا خشم او را با گفتاریا کرداری تسلی دادن و فرونشاندن <span class=\"hlight\">:</span> <br />بی شرابی آتش اندر ما زده ست <br />کیست کو آبی بر این آتش زند.<br /> <font color=\"Red\">انوری .</font><br />یک صراحی آب چون آتش فرست <br />تا از آن آبی بر این آتش زنم .<br /> <font color=\"Red\">فرقدی .</font><br />امید را جگر از تاب حرص سوخته بود<br />ولیک فیض سحابت بر آتشش زد آب .<br /> <font color=\"Red\">رفیعالدین لنبانی .</font><br />هفت اختر بی آب را کز خاکیان خون میخورند<br />هم آب بر آتش زنم هم باد ایشان بشکنم .<br /> <font color=\"Red\">مولوی .</font><br />ساقی سیم تن چه خسبی خیز<br />آب شادی بر آتش غم ریز.<br /> <font color=\"Red\">سعدی .</font><br />آبی بر آتش دل ما هیچکس نزد<br />هرچند پیش محرم و بیگانه سوختیم .<br /><font color=\"Red\">بابافغانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب بر آسمان انداختن </span>؛ ظاهراً، سخت خشمگین شدن <span class=\"hlight\">:</span> و بونصر بر آسمان آب انداخت که تا یک سر اسب و استر بکار است و اضطرابها کرد و گفت چون کار بونصر بدان منزلت رسید که بگفتار بوالحسن ایدونی بر وی دستوری نویسند زندان و خواری و درویشی و مرگ بر وی خوشتر. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب برداشتن </span> ؛ با ظرفی از منهل یا آبدان آب برگرفتن، و مجازاً گفتاری یا کرداری، معنی و مقصود صعب تر و بدتر از آنچه ظاهر است داشتن <span class=\"hlight\">:</span> این گفته بسیار آب برمیدارد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب بردن </span> ؛ بی قدر و عزت ساختن <span class=\"hlight\">:</span> <br />آنکه تا دست بتیر و بکمان برد ببرد<br />آب سام یل و قدر و خطر رستم زر.<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب بستن در...</span> ؛ مشروب کردن زمین و امثال آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب بستن در مالی </span> ؛ به اسراف و تبذیر صرف کردن آن در زمانی کوتاه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب بقا</span> ؛ آب زندگی <span class=\"hlight\">:</span> <br />وآنکه تا حشر بخاصیت خاک درِ او<br />به خضر دجله ٔ بغداد دهد آب بقا.<br /><font color=\"Red\">سیف اسفرنگ .</font><br />آنکه چو خضر از دم تو آب بقا یافت <br />باد شمارد فریب ماء معین را.<br /> <font color=\"Red\">سیف اسفرنگ .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به آب شدن </span> ؛ سفری کوتاه یا درازکردن تغییر آب و هوا را. بهبود یا بیماری بواسطه ٔ سفر پدید آمدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به جوی بازآمدن، آب رفته به جوی بازآمدن </span> ؛ سعادت یا دولتی پشت کرده بازگشتن <span class=\"hlight\">:</span> <br />نشاط جوانی ز پیران مجوی <br />که آب روان بازناید به جوی .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به جوی کسی روان بودن </span> ؛ بکام و مراد خویش بودن او <span class=\"hlight\">:</span> <br />اکنون به جوی اوست روان آب عاشقی <br />آن روز شد که آب گذشتی به جوی ما.<br /> <font color=\"Red\">منوچهری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به (در، اندر) دهان آمدن کسی را، و آب به (در، اندر) دهان آوردن </span> ؛ شائق شدن او. مشتاق کردن او <span class=\"hlight\">:</span> <br />شیر گردون بیشه گر بر مرغزارت بگذرد<br />از صفای شیر حوضت آبش آید در دهان .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />قرص گرم و برّه با هم بر سر خوان فلک <br />ابر تا دیده ست آب اندر دهان می آورد.<br /> <font color=\"Red\">سلمان ساوجی .</font><br />پارسا از لب ساغر به دهان آب آرد<br />دیگران را ز می و نقل چرا توبه دهد؟<br /> <font color=\"Red\">کمال خجند.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به روی آتش زدن </span> ؛ تسکین غضب فتنه ای <span class=\"hlight\">:</span> من بنده، بفرمان رفتم نزدیک خواجه، چنانکه فرمان عالی بود، آبی به روی آتش زدم تا حصیری و پسرش را نزدند. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به (بر) روی کار آوردن </span> ؛ به صلاح آوردن فسادی را <span class=\"hlight\">:</span> در حفظ مصالح ولایت شروع کرد بر توقع آنکه مگر کرمان را از خاک افتادگی بردارد، یا آبی به روی کار آرد. (تاریخ سلاجقه ٔ کرمان محمدبن ابراهیم ).<br />زمانه را ز تو آبی به روی کار آمد<br />روا بود که کنون روی کار بشناسد.<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />و خضروار آب زندگانی او به روی کار آوردم . (مرزبان نامه ).<br />ز شوق در جگرم آتشی است بنشاند<br />به روی کار من خسته آب بازآرد.<br /> <font color=\"Red\">رفیعالدین .</font><br />گفتا که بوده است ز چشمم امید این <br />کآرَد بلطف بازم بر روی کار آب .<br /> <font color=\"Red\">ابن یمین .</font><br />در خشکسال مکرمت از آب رأفتت <br />آرد به روی کار مرا روزگار آب .<br /> <font color=\"Red\">ابن یمین .</font><br />آتش آورده ست آبی هم به روی کار شمع<br />بنگر اینک چشمه ای کآبش روان از آتش است .<br /> <font color=\"Red\">ابن یمین .</font><br />دارای دین طغای تمورخان که ملک را<br />آورد زَ ابر معدلت آبی به روی کار.<br /> <font color=\"Red\">ابن یمین .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به ریسمان بستن </span> ؛ کار عبث و بیهوده کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به زیر کسی هشتن </span> ؛ او را فریفتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به زیر هشتن </span> ؛ میختن، و بیشتر از روی ترس .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به سوراخ مورچه ریخته شدن </span> ؛ غوغا و اجتماعی ناگهانی پیدا آمدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به (با) غربال پیمودن </span> ؛ کار بیهوده کردن <span class=\"hlight\">:</span> <br />بنگر که کجا خواهدت این باز همی برد<br />دیوانه مباش آب مپیمای به غربال .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کآن چاره چو سنبیدن کوه است به سوزن <br />وآن حیله چو پیمودن آبست به غربال .<br /> <font color=\"Red\">معزّی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به گلو جستن </span> ؛ فرودویدن آب به قصبةالرّیه بجای مری .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب به هاون کوفتن </span> ؛ کار بیهوده و عبث کردن <span class=\"hlight\">:</span> <br />گوئی بَهْمان ز من مِه است و نمرده ست <br />آب همی کوبی ای رفیق به هاون .<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب بی لجام (بی لگام ) خوردن </span> ؛ بی مربّی و سرپرستی بار آمدن . خودسر و مطلق العنان بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب پاکی (با یاء مصدری ) بر (روی ِ) دست کسی ریختن </span> ؛ یکباره و از هر جهت او را مأیوس کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب پیکر</span> ؛ بکنایه، جرمی روشن از اجرام علوی <span class=\"hlight\">:</span> <br />ای فلک صولتی که خاک درت <br />پرده ٔ آب پیکران برداشت .<br /> <font color=\"Red\">مجیر بیلقانی .</font><br />صبح است کمانکش اختران را<br />آتش زده آب پیکران را.<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب تیره گشتن کسی را نزد دیگری </span> ؛ منفور ومغضوب او گردیدن <span class=\"hlight\">:</span> <br />چه گویم کنون پیش افراسیاب <br />مرا گشت نزدیک او تیره آب .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب چکیدن از چیزی </span> ؛ تازه و طری بودن آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب چکیدن از نثر یا نظمی </span> ؛ سخت فصیح بودن آن <span class=\"hlight\">:</span> <br />هر کجا در خجندیان صدریست <br />زآتش فکر آب میچکدش .<br /> <font color=\"Red\">خاقانی .</font><br />هزار بیت بگفتم که آب از آن بچکید<br />که جز ز دیده دگر آبم از کسی نگشاد.<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />بجز غبغبش کآب از او میچکید<br />به آتش بر، آب معلق که دید؟<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب چکیده </span> ؛ ماءالقطر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب حیات </span> ؛ بروایات مقدمه نام چشمه ای به ناحیتی تاریک از شمال زمین موسوم به ظلمات که آشامنده را زندگی جاودانی بخشد و گویند اسکندر ذوالقرنین بطلب آن شد و نیافت و خضر که مصاحب او بود بدان رسید و بیاشامید و زنده ٔ ابد گشت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب حیوان </span> ؛ آب زندگانی . آب خضر. آب حیات . آب بقا.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب خفته </span> ؛ آب راکد و مجازاً ژاله و برف و شمشیر در نیام <span class=\"hlight\">:</span> <br />در آبی نرگسی دیدم شکفته <br />چو آبی خفته وز او آب خفته .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب خوش </span> ؛ آب گوارا. فُرات . آب شیرین .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب دادن </span> ؛ آب خورانیدن حیوان و روان کردن آب بر زمین و جز آن زنده داشتن زرع و درختان را. و به عربی اسقاء و سقی و سقایت و تسقیه و اماهه گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب دادن فلز</span> ؛ طلی کردن آن به فلزی گرانبهاتر <span class=\"hlight\">:</span> آب سیم دادن . آب زر دادن . طلی کردن بسیم را به عربی تفضیض و طلی کردن بزر را تذهیب گویند و بسیم آب داده را مفضض یعنی سیم اندود و بزر آب داده را مذهّب یعنی زراندود خوانند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب دادن کارد و شمشیر و نوع آن </span> ؛ عملی است که شمشیرسازان و کاردگران کنند سخت کردن آهن را و آن فروبردن آهن تفته ٔ شمشیر و امثال آن باشد در آب . و عربی آن اماهه و امهاء است . و آب داده را به عربی رونق گویند. (ربنجنی ) (السامی فی الاسامی ). و فارسی آن پرند و پرنگ است . و شمشیر را آنگاه بنیکی جوهر و گوهر و پرندآوری وصف کنند که بمهارت و استادی آب آن داده باشند <span class=\"hlight\">:</span> <br />ز دو چیز گیرند مر مملکت را<br />یکی زعفرانی یکی ارغوانی <br />یکی زرّ نام ملک برنبشته <br />دگر آهن آب داده ی ْ یمانی .<br /> <font color=\"Red\">دقیقی .</font><br />خورشید تیغ تیز ترا آب میدهد<br />مریخ نوک خشت تو بر سان زند همی .<br /> <font color=\"Red\">دقیقی یا ابوشکور.</font><br />بهیچ روی تو ای خواجه برقعی نه خوشی <br />بگاه نرمی گویی که آب داده تشی . <br /> <font color=\"Red\">منجیک .</font><br />مرا چو تیغ دهد آب آبگون گردون <br />هر آنگهی که بنالم بپیش اوز ظما<br />چو تیغ نیک بتفساندم ز آتش دل <br />در آب دیده کند غرق تا بفرق مرا.<br /> <font color=\"Red\">مسعودسعد.</font><br />چو از گرد سپه خواهد که جان خصم غسل آرد<br />شود در چشمه ٔ تیغت چو آب تیغ ناپیدا.<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />سر ز تیغ زبان خویش بتاب <br />که ز خون تو داده اندش آب .<br /> <font color=\"Red\">مکتبی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در جگر نداشتن </span> ؛ سخت محتاج و فقیر بودن <span class=\"hlight\">:</span> <br />این پرشکسته را که نبود آب در جگر<br />آروغ امتلا زند اکنون ز خوان شکر.<br /> <font color=\"Red\">کمال اسماعیل .</font><br />در جگر گرچه مرازآتش فقر آب نماند<br />لیک بحری است کف راد تو پر آب زلال .<br /> <font color=\"Red\">ابن یمین .</font><br />باآنکه آب در جگرم نیست هر شبی <br />باشد خیال روی توام میهمان چشم .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />نماند در جگرم آب و این سیه چشمان <br />هنوز زین ده ویران خراج می طلبند.<br /> <font color=\"Red\">بابافغانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب خاطر</span> ؛ صفای فکرت <span class=\"hlight\">:</span> <br />بجوی تو همه آب روان است <br />سزد گر من هواجوی تو باشم .<br /> <font color=\"Red\">امیر معزّی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در جوی داشتن </span> ؛ صاحب دولت و اقبال بودن . صاحب حل ّ وعقد و رتق و فتق امور بودن <span class=\"hlight\">:</span> <br />آب در جوی تست و چرخ چو پیل <br />دشمنان را لگدسپر دارد.<br /> <font color=\"Red\">انوری .</font><br />هنوزم آب در جوی جوانی است <br />هنوزم لب پر آب زندگانی است .<br /> <font color=\"Red\">نظامی .</font><br />ای دیده بسوز من ببخشای <br />کامروز تراست آب در جوی .<br /> <font color=\"Red\">امیرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در جوی نماندن </span> ؛ بشدن دولت و اقبال .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در چشم نبودن کسی را</span> ؛ بی حیاو بی شرم بودن <span class=\"hlight\">:</span> <br />چه شد که آب مروت بچشم اخوان نیست ؟<br /> <font color=\"Red\">صائب .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در چیزی کردن </span> ؛ دغل و غش در وی بکاربردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در دل تکان نخوردن </span> ؛ سخت آهسته کار و دیرجنب بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در دهان آمدن از...</span> ؛ شائق و خواهان آن شدن <span class=\"hlight\">:</span> <br />شیر گردون بیشه گر بر مرغزارت بگذرد<br />از صفای شیر حوضت آبش آید در دهان .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />نام تتماج بر زبان بردم <br />ماست را آب در دهان آمد.<br /> <font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در دهان خشک شدن </span> ؛ سخت حیرت زده گشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در دهان گشتن کسی را</span> ؛ ازدیدن یا شنیدن مطلوبی شائق و شیفته ٔ او شدن <span class=\"hlight\">:</span> <br />اگر نظارگی آنجا گذشتی <br />ز حسرت در دهانش آب گشتی .<br /> <font color=\"Red\">جامی .</font><br />چنان پیاله ٔ دردی کشان لبالب شد<br />که خاک را ز هوس آب در دهان گردید.<br /> <font color=\"Red\">بابافغانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در دیده یا چشم نداشتن </span> ؛ بی شرم بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در زیر کاه </span> ؛ حیلتی پوشیده <span class=\"hlight\">:</span> <br />به گفت سیاوش بخندید شاه <br />نبود آگه از آب در زیر کاه .<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به ترکیب آب زیر کاه شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در سینه شکستن </span> ؛ دردی گذرا و موقت پس از خوردن آب در سینه پیدا آمدن . واکفیدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در شکر داشتن </span> ؛ روز از روز نزارتر شدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در شیر داشتن </span> ؛ دورو و منافق بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در شیر کردن </span> ؛ غش و دغل کردن در معامله <span class=\"hlight\">:</span> <br />پیش از این از ننگ صنعت عشق فارغبال بود<br />کوهکن در عاشقی این آب را در شیر کرد.<br /> <font color=\"Red\">صائب .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در غربال کردن یا با غربال بیختن و آب در قفس کردن </span> ؛ کار بیهوده و عبث مرتکب شدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در گلو شکستن یا به گلو جَستن </span> ؛ فرودویدن آب به قصبةالریه بجای مری . و بکنایه، از چیزی که مایه ٔ سود و آسایش است زیان و آسیب دیدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در گوش کسی کردن </span> ؛ در سودایی او را فریفتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب در هاون ساییدن (سودن، کوفتن )</span> ؛ کار عبث و بیهوده ارتکاب کردن <span class=\"hlight\">:</span> <br />بی علم، دین همی چه طمع داری <br />در هاون آب، خیره چرا سایی ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />اندر این جای سپنجی چو نهادی دل <br />آب کوبی همی ای بیهده در هاون .<br /> <font color=\"Red\">ناصرخسرو.</font><br />درون هاون شهوت چه آب میکوبید<br />چو آبتان بنماند ز لاف پیمائی .<br /> <font color=\"Red\">مولوی .</font><br />زنهار مبند باد در چنبر<br />بیهوده مسای آب در هاون .<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب دریا به کیل پیمودن </span> ؛ کار بی نتیجه کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب دهان، آب دهن </span> ؛ خیو <span class=\"hlight\">:</span> <br />کوچ ز شاخ درخت خویشتن آویخته <br />بانگ کنان تا سحر آب دهان ریخته .<br /> <font color=\"Red\">منوچهری (از فرهنگ اسدی، خطی ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب دهان </span> ؛ آنکه سِر نگاه ندارد <span class=\"hlight\">:</span> آب دهانی است <font color=\"DarkGreen\"><b>[ قلم ]</font></b> که سخن نگاه نمیدارد. (نفثة المصدور).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب دیزی را زیاده کردن </span> ؛ بمزاح، چیزی بطعام افزودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب را آب کشیدن </span> ؛ سخت پرهیز و احتیاط در امور صِحّی کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب را گِل (گل آلود) کردن </span> ؛ آشفتن کاری سود خویش را <span class=\"hlight\">:</span> آب را گل آلود می کند ماهی بگیرد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب رفته به جوی بازآمدن </span> . رجوع به آب به جوی بازآمدن شود <span class=\"hlight\">:</span> و اگر در سنه ٔ احدی و خمسین و اربعمائه (<span class=\"hlight\" dir=\"rtl\">٤٥١</span> هَ . ق .) از زمانه ٔ ناجوانمرد کراهتی دید و درشتی پیش آمد آخر نیکو شد و بجوئی که میرفت و می آمدآب رفته بازآمد. (تاریخ بیهقی ).<br />روزگار ار آب جویی را بجویی بازبرد<br />هم بجوی خویش بازآمد ز گشت روزگار.<br /> <font color=\"Red\">سوزنی .</font><br />تشنه ترسم که منقطع گردد<br />ورنه بازآید آب رفته بجوی .<br /> <font color=\"Red\">سعدی .</font><br />دشمن آتش پرست بادپیما را بگوی <br />خاک بر سر کن که آب رفته بازآمد بجوی .<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب روشن داشتن یا آب روشن بودن کسی را</span> ؛ صاحب عزّ و جاه بودن <span class=\"hlight\">:</span><br />پیش بزرگان عصر آب کسی روشن است <br />کآب ز پس میخورد بر صفت آسیا.<br /> <font color=\"Red\">خاقانی .</font><br />آب جاه تو روشن است از سر<br />خصم را گو که باد می پیمای .<br /> <font color=\"Red\">انوری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب روی کار آوردن </span> . رجوع به آب به روی کار آوردن شود <span class=\"hlight\">:</span> یعنی وقت است که آب روی کار آورم . (مرزبان نامه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب ریخت وپاش </span> ؛ آبی که خاص شست و شوی و دیگر مصارف جز آشامیدن باشد، مقابل آب ِ خوردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب زیر کاه، آب در زیر کاه </span> ؛ مکر و حیله . مکار و حیله گر و بَدْاَندرون . تبند. نرم بر <span class=\"hlight\">:</span> <br />بگفت سیاوش بخندید شاه <br />نبود آگه از آب در زیر کاه .<br /> <font color=\"Red\">فردوسی .</font><br />با مهان آب زیر کاه مباش <br />تات بی آب تر ز کَه ْنکند.<br /> <font color=\"Red\">سنائی .</font><br />نیست تنزیل سوی عقل مگر<br />آب در زیر کاه بی تأویل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />حال من و تو از تو و من دور نیست از آنک <br />تو آب زیر کاهی و من کاه زیرآب .<br /> <font color=\"Red\">خاقانی .</font><br />و گفته اند مکیدت دشمنان و سگالش خصمان در پرده کارگرتر آید که آب که در زیر کاه حیلت پوشانند خصم را بغوطه ٔ هلاک زودتر رساند. (مرزبان نامه ).<br />رقعه پنهان کرد و ننمود او بشاه <br />کو منافق بود و آب زیر کاه .<br /> <font color=\"Red\">مولوی .</font><br />گرچه غم سوز و غصه کاه است او<br />زو بِرَم کآب زیرکاه است او.<br /> <font color=\"Red\">اوحدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب زیر کَه ْ</span> ؛ آب زیرکاه <span class=\"hlight\">:</span> <br />یکی چون آب زیر کَه ْبقول خوش فریبنده <br />چو شاخی بار آن نشتر ولیکن برگ او بیرم .<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آبشان از یک جوی نرفتن </span> ؛ همدست و همداستان شدنشان ممکن نبودن <span class=\"hlight\">:</span> <br />زاهد بکتابی و کتاب من و تو<br />سنگ است و صراحی انتساب من و تو<br />تو مرده ٔ کوثری و من زنده ٔ می <br />مشکل که بیک جو رود آب من و تو.<br /> <font color=\"Red\">خیام .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب شدن </span> ؛ گداختن . ذوبان . ذوب . مذاب شدن . حل یا منحل شدن . انهمام .و مجازاً، از شرم آب شدن ؛ سخت خجل گشتن <span class=\"hlight\">:</span> <br />چنین داد پاسخ به افراسیاب <br />که لختی بباید شد از شرم آب .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب شدن دل (زَهره )</span> ؛ عظیم ترسیدن . سخت هراسیدن <span class=\"hlight\">:</span><br />چو چرخ خصم ترا گر هزار دل باشد<br />شود ز آتش کین تو هر هزارش آب .<br /><font color=\"Red\">سیف اسفرنگ .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب شدن دل برای (از) چیزی </span> ؛ سخت خواهان و آرزومند وی گشتن <span class=\"hlight\">:</span> <br />اگرچه تلخ کند کام، چون سخن گوید<br />دل شکر شود از لعل آبدارش آب .<br /> <font color=\"Red\">سیف اسفرنگ .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آ</font></div>'),
(12, 'آب', '<span class=\"hlight\">آب .</span> (اِ) نام ماه یازدهم از سال ملی یهودو ماه پنجم از سال عرفی و دیوانی آنان و غُرّه ٔ آن بگفته ٔ مورخین قدیم با سلخ مرداد یا غُرّه ٔ شهریور مطابق است . و این ماه نزد بنی اسرائیل ماه عزا و ماتم باشد. و بروز پسین آن وفات هارون است و یهود بدان روز روزه دارند. (از قاموس کتاب مقدس ). و در فرهنگهای فارسی نام ماه یازدهم سال سریانی معروف برومی میان تموز و ایلول مطابق اسد عربی و مرداد فارسی و نیز اغسطوس رومی، و بعضی گفته اند مطابق عقرب، و در سامی فی الاسامی ماه سوم تابستان، و سبب اختلاف اقوال ظاهراً اختلاف حسابهای نجومی در اعصار مختلفه است <span class=\"hlight\">:</span> <br />ساحت آفاق را اکنون که فرّاش صبا<br />از حزیران فرش گسترد از تموز و آب نخ .<br /> <font color=\"Red\">انوری .</font><br />بسوزد بشب خرمن ماه را<br />سموم نهیب تو در ماه آب .<br /><font color=\"Red\">اثیراخسیکتی .</font><br /></font></div>'),
(13, 'آب', '<span class=\"hlight\">آب .</span> (اِخ ) نزد نصاری، اقنوم اوّل از اقانیم سه گانه . صورتی از اَب .<br /></font></div>'),
(14, 'آب آسیا', '<span class=\"hlight\">آب آسیا.</span> (اِ مرکب ) آسیا که بزورِ آب گردد.<br /></font></div>'),
(15, 'آب آشنا', '<span class=\"hlight\">آب آشنا.</span> <font color=\"DarkGreen\"><b>[ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) آنکه شناوری داند. آنکه معرفت بسباحت دارد. سباح . شناگر. (فرهنگ اسدی ) <span class=\"hlight\">:</span> <br />کسی کاندر آب است و آب آشناست <br />از آب ار چو آتش بترسد رواست .<br /><font color=\"Red\">ابوشکور.</font><br /></font></div>'),
(16, 'آب آلو', '<span class=\"hlight\">آب آلو.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب که در آن آلو تر نهاده باشند.<br /></font></div>'),
(17, 'آب آمیخته', '<span class=\"hlight\">آب آمیخته .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) آب مضاف : و عقرب را آب آمیخته و سخت رو. (التفهیم ).<br /></font></div>'),
(18, 'آب آهن تاب', '<span class=\"hlight\">آب آهن تاب .</span> <font color=\"DarkGreen\"><b>[ ب ِ هََ ]</font></b> (ترکیب وصفی، اِ مرکب ) آبی که آهن تفته در آن فروبرده باشند و در طب بکار است .<br /></font></div>'),
(19, 'آب آهن تافته', '<span class=\"hlight\">آب آهن تافته .</span> <font color=\"DarkGreen\"><b>[ ب ِ هََ ن ِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) ماءالحدید. (تحفه ).<br /></font></div>'),
(20, 'آب آهنج', '<span class=\"hlight\">آب آهنج .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (نف مرکب ) آب آهنگ .<br /></font></div>'),
(21, 'آب آهنگ', '<span class=\"hlight\">آب آهنگ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (نف مرکب ) آدمی یا ستوری که آب از چاه و جز آن برکشد. آبکش . آب آهنج <span class=\"hlight\">:</span> <br />کرده شیران حضرت تو مرا<br />سرزده همچو گاو آب آهنگ .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(22, 'آب آهک', '<span class=\"hlight\">آب آهک .</span> <font color=\"DarkGreen\"><b>[ ب ِ هََ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که در آن مقداری معلوم آهک ریزند و پس از رسوب آب را در معالجات بکار برند.<br /></font></div>'),
(23, 'آب آورد', '<span class=\"hlight\">آب آورد.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ن مف مرکب، اِ مرکب ) آب آورده . خاشاک و جز آن که دریا یا رود و یا سیل با خود آرد و آن را عرب جفاء (صراح ) و جفال و حمیل گویند.<br /></font></div>'),
(24, 'آب آورده', '<span class=\"hlight\">آب آورده .</span> <font color=\"DarkGreen\"><b>[ وَدَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب، اِ مرکب ) آب آورد <span class=\"hlight\">:</span> <br />دوش ازبرای مطبخش هیزم ز مژگان برده ام <br />گفت از کجا آورده ای خاشاک آب آورده را.<br /> <font color=\"Red\">؟</font><br /><BR><font color=\"Blue\">◄</font> چشم آب آورده ؛ چشمی که ببیماری آب مبتلی باشد.<br /></font></div>'),
(25, 'آب ابرو', '<span class=\"hlight\">آب ابرو.</span> <font color=\"DarkGreen\"><b>[ ب ِ اَ ]</font></b> (ترکیب اضافی، اِمرکب ) ترکیبی مایع که زنان ابروان بدو سیاه کنند.<br /></font></div>'),
(26, 'آب استه', '<span class=\"hlight\">آب استه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> ( ) و اندر نواحی وی <font color=\"DarkGreen\"><b>[ قصبه ٔ پریم در جبل قارن ]</font></b> چشمه های آبست که بیک سال اندر، چندین بار بیشترین مردم این ناحیت بدانجا شوند، آب استه با نبید و رود و سرود و پای کوفتن و آنجا حاجتها خواهند از خدای و آن را چون تعبدی دارند و باران خواهند بوقتی که شان بباید. (حدودالعالم ). معنی آب استه در این عبارت ظاهر نیست و در فرهنگها نیز یافته نشد و اگر تصحیف و تحریفی در کلمه نباشد شاید معنی ناشتا و پگاه و شبگیر یا تشنه دهد.<br /></font></div>'),
(27, 'آب افتاده', '<span class=\"hlight\">آب افتاده .</span> <font color=\"DarkGreen\"><b>[ اُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ]</font></b> (ن مف مرکب ) میوه ٔ نیم رَس . <BR><font color=\"Blue\">◄</font> متاعی در آب دریا یا رود تر شده و رنگ بگردانیده و زیان دیده .<br /></font></div>'),
(28, 'آب الهی', '<span class=\"hlight\">آب الهی .</span> <font color=\"DarkGreen\"><b>[ ب ِ اِ لا هی ]</font></b> (ترکیب وصفی، اِ مرکب ) آب محض و خالص از نباتی .<br /></font></div>'),
(29, 'آب انار', '<span class=\"hlight\">آب انار.</span> <font color=\"DarkGreen\"><b>[ ب ِ اَ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که از فشردن انار گیرند.<br /></font></div>'),
(30, 'آب انبار', '<span class=\"hlight\">آب انبار.</span> <font color=\"DarkGreen\"><b>[اَم ْ ]</font></b> (اِ مرکب ) خانه ای در زیر قسمتی از بنا حفر کرده ذخیره کردن آب را. <BR><font color=\"Blue\">◄</font> پارگین . (ربنجنی ). <BR><font color=\"Blue\">◄</font> آبدان . آبگیر. تالاب . مصنع. بَرْخ .<br /></font></div>'),
(31, 'آب انبار', '<span class=\"hlight\">آب انبار.</span> <font color=\"DarkGreen\"><b>[ اَم ْ ]</font></b> (اِخ ) نام محلی کنار راه کازرون ببوشهر میان راهدار و برازجان در <span class=\"hlight\" dir=\"rtl\">١١٠٩١٠٠</span> گزی طهران .<br /></font></div>'),
(32, 'آب انداختن', '<span class=\"hlight\">آب انداختن .</span> <font color=\"DarkGreen\"><b>[ اَ ت َ ]</font></b> (مص مرکب ) میختن ستور. <BR><font color=\"Blue\">◄</font> پختگی آغازیدن میوه . <BR><font color=\"Blue\">◄</font> جدا شدن آب ماست و آش سرد و جز آن از دیگر اجزاء.<br /></font></div>'),
(33, 'آب انداز', '<span class=\"hlight\">آب انداز.</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِ مرکب ) توقفگاه ستور میان دو منزل، آسایش و رفع ماندگی را. <BR><font color=\"Blue\">◄</font> چوبی کاواک و میان تهی کرده که چوبی دیگر در میان آن فروبرند و بفشار آب در آن کنند و نیز بیرون افکنند. آبدزدک . و به عربی آن را زراقه (ربنجنی )، ذراقه و سراقه و مضخه گویند.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(34, 'آب انگور', '<span class=\"hlight\">آب انگور.</span> <font color=\"DarkGreen\"><b>[ ب ِ اَ ]</font></b> (ترکیب اضافی، اِ مرکب ) شراب . باده <span class=\"hlight\">:</span> <br />آب انگور بیارید که آبان ماهست <br />آب انگور خزانی را خوردن گاهست .<br /> <font color=\"Red\">منوچهری .</font><br />ای یارِ سرود و آب انگور<br />نه یار منی بحق والطور.<br /> <font color=\"Red\">ناصرخسرو.</font><br />زاهد گوید که جنت و حور خوش است <br />من میگویم که آب انگور خوش است .<br /> <font color=\"Red\">خیام .</font><br />زآب انگور، نار طبع مکش <br />زآتش باده آب روی مبر.<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(35, 'آب ایستاده', '<span class=\"hlight\">آب ایستاده .</span> <font color=\"DarkGreen\"><b>[ ب ِ دَ ]</font></b> (اِخ ) نام دریاچه ای ازافغانستان در جنوب غربی غزنین بفاصله ٔ <span class=\"hlight\" dir=\"rtl\">٨٠</span>هزار گز. وسعت آن برحسب بسیاری و اندکی ِ باران کم و بیش شود.<br /></font></div>'),
(36, 'آب باران', '<span class=\"hlight\">آب باران .</span> (اِخ ) ناحیتی خوش آب و هوا از مضافات کابل <span class=\"hlight\">:</span> <br />اگرچه جای خوش کابل آب باران است <br />بهشت روی زمین خواجه ٔ سه یاران است .<br /><font color=\"Red\">؟</font><br /></font></div>'),
(37, 'آب باران', '<span class=\"hlight\">آب باران .</span><font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) ماءالمطر. (تحفه ).<br /></font></div>'),
(38, 'آب باریک', '<span class=\"hlight\">آب باریک .</span> (اِخ ) نام محلی کنار راه همدان به کرمانشاه، میان روان و گندچین . و رجوع به گردنه ٔ آب باریک شود. <BR><font color=\"Blue\">◄</font> نام کوهی در کرمان متصل بجبال بارز.<br /></font></div>'),
(39, 'آب باز', '<span class=\"hlight\">آب باز.</span> (نف مرکب ) شناگر. سباح .<br /></font></div>'),
(40, 'آب بازی', '<span class=\"hlight\">آب بازی .</span> (حامص مرکب ) شناگری . سباحت .<br /></font></div>'),
(41, 'آب بخش', '<span class=\"hlight\">آب بخش .</span> <font color=\"DarkGreen\"><b>[ آب ْ، ب َ ]</font></b> (نف مرکب ) میرآب . قلاد. (مهذب الاسماء). آب یار. اویار. آنکه شغلش آب دادن بکشت بود.<br /></font></div>'),
(42, 'آب بخش کن', '<span class=\"hlight\">آب بخش کن .</span> <font color=\"DarkGreen\"><b>[ آب ْ، ب َ ک ُ ]</font></b> (اِ مرکب ) مَقْسم و محل بخشیدن ِ آب . <BR><font color=\"Blue\">◄</font> (اِخ ) نام محله ای بطهران .<br /></font></div>'),
(43, 'آب بخشان', '<span class=\"hlight\">آب بخشان .</span> <font color=\"DarkGreen\"><b>[ آب ْ، ب َ ]</font></b> (اِخ ) نام رودیست در طرف غرب ایران که خط سرحدی ایران و عراق از آن گذرد و معروفست به نمود. <BR><font color=\"Blue\">◄</font> نام محله ای باصفهان .<br /></font></div>'),
(44, 'آب برز', '<span class=\"hlight\">آب برز.</span> <font color=\"DarkGreen\"><b>[ آب ْ، ب ُ ]</font></b> (اِخ ) نام شعبه ای از رود کارون .<br /></font></div>'),
(45, 'آب برین', '<span class=\"hlight\">آب برین .</span> <font color=\"DarkGreen\"><b>[ آب ْ، ب َ ]</font></b> (اِ مرکب ) کنار جوی را گویند که زیرش مجوف باشد و هر دم آب در آنجا رخنه کند وبیرون رود یا پیوسته تراوش میکرده باشد. (برهان ).<br /></font></div>'),
(46, 'آب بزرگ', '<span class=\"hlight\">آب بزرگ .</span> <font color=\"DarkGreen\"><b>[ ب ِ ب ُ زُ ]</font></b> (اِخ ) نام شعبه ٔ غربی و اصلی رود کارون که در بند قیر بشعبه ٔ شرقی یا آب گرگر پیوندد.<br /></font></div>'),
(47, 'آب بقا', '<span class=\"hlight\">آب بقا.</span> <font color=\"DarkGreen\"><b>[ ب ِ ب َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب زندگانی .<br /></font></div>'),
(48, 'آب بن', '<span class=\"hlight\">آب بن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ب ُ]</font></b> (ترکیب اضافی، اِ مرکب ) سادآوران . و آن چیزی است چون صمغ که در بیخ درخت گردکان کهنه و مجوف یابند.<br /></font></div>'),
(49, 'آب بند', '<span class=\"hlight\">آب بند.</span> <font color=\"DarkGreen\"><b>[ آب ْ، ب َ ]</font></b> (نف مرکب ) آنکه ماست و پنیر و سرشیر و خامه کند. <BR><font color=\"Blue\">◄</font> آنکه درزهای ظروف فلزین با موم مذاب یا قلعی سد سازد. <BR><font color=\"Blue\">◄</font> آنکه یخ گیرد.<br /></font></div>'),
(50, 'آب بندی', '<span class=\"hlight\">آب بندی .</span> <font color=\"DarkGreen\"><b>[ آب ْ، ب َ ]</font></b> (حامص مرکب ) شغل و عمل آب بند.<br /></font></div>'),
(51, 'آب بنفشه', '<span class=\"hlight\">آب بنفشه .</span> <font color=\"DarkGreen\"><b>[ ب ِ ب َ ن َ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) عطر و عرق بنفشه <span class=\"hlight\">:</span> و از وی <font color=\"DarkGreen\"><b>[ از پارس ]</font></b> آب گل و آب بنفشه و آب طلع... خیزد. (حدودالعالم ).<br /></font></div>'),
(52, 'آب بوری', '<span class=\"hlight\">آب بوری .</span> <font color=\"DarkGreen\"><b>[ ب ِ بو ]</font></b> (ترکیب اضافی، اِ مرکب ) دوائی است که زنان با آن رنگ موی گیسوان بگردانند برنگ خرمایی روشن .<br /></font></div>'),
(53, 'آب بین', '<span class=\"hlight\">آب بین .</span> (نف مرکب ) آب شناس .<br /></font></div>'),
(54, 'آب بینی', '<span class=\"hlight\">آب بینی .</span> (حامص مرکب ) عمل آب بین .<br /></font></div>'),
(55, 'آب بینی', '<span class=\"hlight\">آب بینی .</span> <font color=\"DarkGreen\"><b>[ب ِ بی ]</font></b> (ترکیب اضافی، اِ مرکب ) مخاط. مُرگ . خلم .<br /></font></div>'),
(56, 'آب تابه', '<span class=\"hlight\">آب تابه .</span> <font color=\"DarkGreen\"><b>[ تا ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ مرکب ) ظرفی که در آن آب گرم کنند. <BR><font color=\"Blue\">◄</font> ابریق . آفتابه .<br /></font></div>'),
(57, 'آب تاختن', '<span class=\"hlight\">آب تاختن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b>(مص مرکب ) میختن . میزیدن . (صحاح الفرس ) <span class=\"hlight\">:</span> <br />ز قلب آنچنان سوی دشمن بتاخت <br />که از هیبتش شیر نر آب تاخت .<br /> <font color=\"Red\">رودکی .</font><br />و سنگ اندر کمیزدان و دشخواری آب تاختن . (التفهیم ).<br /></font></div>'),
(58, 'آب تبرستان', '<span class=\"hlight\">آب تبرستان .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ ب َ رِ ]</font></b>(اِخ ) نام چشمه ای بر کوهی از تبرستان که گویند چون بانگ بر او زنی بازایستد و چون بازایستی روان شود.<br /></font></div>'),
(59, 'آب تبریه', '<span class=\"hlight\">آب تبریه .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ ب َ ری ی َ ]</font></b> (اِخ ) بگفته ٔ فرهنگ نویسان نام چشمه ای است نزدیک اردن که هفت سال روان و هفت سال خشک است .<br /></font></div>'),
(60, 'آب تراز', '<span class=\"hlight\">آب تراز.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) طراز بنایان که در درون آب دارد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب تراز کردن زمین </span> ؛ تسطیح آن برای جریان آب .<br /></font></div>'),
(61, 'آب ترازو', '<span class=\"hlight\">آب ترازو.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) دانش تسطیح زمین و کاریز سهولت جریان آب را.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب ترازو کردن </span> ؛ تسطیح زمین و کاریز بصورتی که آب جریان کند.<br /></font></div>'),
(62, 'آب تراش کردن', '<span class=\"hlight\">آب تراش کردن .</span> <font color=\"DarkGreen\"><b>[ ت َ ک َ دَ ]</font></b> (مص مرکب ) خراشیدن خیار و خربزه و امثال آن با کفچه سهولت مضغ را.<br /></font></div>'),
(63, 'آب تره', '<span class=\"hlight\">آب تره .</span> <font color=\"DarkGreen\"><b>[ ت َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) گیاهی است آبی با برگهای مایل بتدویر و زبانگز چون ترتیزک و در چهارمحال اصفهان آن را بَکلو گویند، و آن از احرار بُقول است .<br /></font></div>'),
(64, 'آب تنزیه', '<span class=\"hlight\">آب تنزیه .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ]</font></b> (ترکیب اضافی، اِ مرکب ) پیش یهود آبی است آمیخته بخاکستر گاو سوخته <font color=\"DarkGreen\"><b>[ گاوی سرخ که بنی اسرائیل بکشتن وسوختن آن مأمور شدند ]</font></b> و چوب سرو و زوفا و ارغوان و آن را بر تن کسی که مس میت کرده ریزند، و آن کس که پس از مس میت این آب بر او نریزند از ملت اسرائیل طرد شده و کشتن او واجب آید. (از قاموس کتاب مقدس ).<br /></font></div>'),
(65, 'آب تنی کردن', '<span class=\"hlight\">آب تنی کردن .</span> <font color=\"DarkGreen\"><b>[ ت َ ک َ دَ ]</font></b> (مص مرکب ) غوطه خوردن در آب سرد بقصد خنک شدن .<br /></font></div>'),
(66, 'آب تیرگان', '<span class=\"hlight\">آب تیرگان .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ مرکب ) رجوع به آبریزگان شود.<br /></font></div>'),
(67, 'آب جر', '<span class=\"hlight\">آب جر.</span> <font color=\"DarkGreen\"><b>[ ج َ ]</font></b> (اِ مرکب ) جزر. مقابل مد.<br /></font></div>'),
(68, 'آب جو', '<span class=\"hlight\">آب جو.</span> <font color=\"DarkGreen\"><b>[ ب ِ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> جُو ]</font></b> (ترکیب اضافی، اِ مرکب ) فوگان . فقاع . فقع. نبیدجو. آخسمه . آخمسه . جعه . و قسم ستبر آن را بوزه گویند. <BR><font color=\"Blue\">◄</font> ماءالشعیر. آبی که در آن جو مقشر جوشانیده باشند مداوا را.<br /></font></div>'),
(69, 'آب جوش', '<span class=\"hlight\">آب جوش .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که در آن جوش یعنی بی کربنات سود و حامض طرطیر کرده و چون گوارشی آشامند. <BR><font color=\"Blue\">◄</font> (ترکیب وصفی، اِ مرکب ) آب جوشان .<br /></font></div>'),
(70, 'آب حسرت', '<span class=\"hlight\">آب حسرت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ح َ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) اشک <span class=\"hlight\">:</span> <br />بگذاشتند ما را در دیده آب حسرت <br />گریان چو در قیامت چشم گناهکاران .<br /> <font color=\"Red\">سعدی .</font><br />هر می لعل کز آن دست بلورین ستدیم <br />آب حسرت شد و در چشم گهربار بماند.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(71, 'آب حیات', '<span class=\"hlight\">آب حیات .</span> <font color=\"DarkGreen\"><b>[ ب ِ ح َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب زندگانی <span class=\"hlight\">:</span> <br />آب حیات زیر سخنهای خوب اوست <br />آب حیات را بخور و جاودان ممیر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />کنونم آب حیاتی بحلق تشنه فروکن <br />نه آنگهی که بمیرم به آب دیده بشویی .<br /> <font color=\"Red\">سعدی .</font><br />سیاهی گر بدانی عین ذاتست <br />بتاریکی درون آب حیات است .<br /> <font color=\"Red\">شیخ محمود شبستری .</font><br />طبیبی چه خوش گفت در خاک بلخ <br />که آب حیاتست داروی تلخ .<br /><font color=\"Red\">امیرخسرو دهلوی .</font><br />چو هست آب حیاتت به دست تشنه ممیر<br />فلاتمت و من الماء کل شی ٔ حی .<br /> <font color=\"Red\">حافظ.</font><br /><BR><font color=\"Blue\">◄</font> بمجاز، دهان معشوق . <BR><font color=\"Blue\">◄</font> قسمی از شیرینی و حلوا. <BR><font color=\"Blue\">◄</font> نوعی از شراب به ادویه ٔ تند آمیخته و آن را ماءالحیات نیز گویند. <BR><font color=\"Blue\">◄</font> نوعی از مهره ها برنگ زرد که زنان از آن دستبند و امثال آن کنند.<br /></font></div>'),
(72, 'آب حیوان', '<span class=\"hlight\">آب حیوان .</span> <font color=\"DarkGreen\"><b>[ ب ِ ح َی ْ <span class=\"hlight\" dir=\"rtl\">/</span> ح ِی ْ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب زندگانی <span class=\"hlight\">:</span> <br />خردیافته مرد یزدان پرست <br />بدو در یکی چشمه گوید که هست <br />گشاده سخن مرد با رای و کام <br />همی آب حیوانْش خواند بنام .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت روشن دل پرخرد<br />که هر کآب حیوان خورد کی مِرَد؟<br /> <font color=\"Red\">فردوسی .</font><br />بدست آور از آب حیوان نشان <br />بخور زو و پس شاد زی جاودان .<br /> <font color=\"Red\">اسدی .</font><br />اهل دنیا اهل دین نبود ازیرا راست نیست <br />هم سکندر بودن و هم آب حیوان داشتن .<br /> <font color=\"Red\">سنائی .</font><br />که بدین راه در بدی نیکی است <br />آب حیوان درون تاریکی است .<br /> <font color=\"Red\">سنائی .</font><br />در تاریکی است آب حیوان .<br /> <font color=\"Red\">عمادی شهریاری .</font><br />شگفتی نبد کآب حیوان گهر<br />کند ماهی مرده را جانور<br />شگفت اندر آن ماهی مرده بود<br />که بر چشمه ٔ زندگی ره نمود.<br /> <font color=\"Red\">نظامی .</font><br />بیا ساقی آن آب حیوان گوار<br />بدولت سرای سکندر سپار.<br /> <font color=\"Red\">نظامی .</font><br />ذوق در غمها است پی گم کرده اند<br />آب حیوان را بظلمت برده اند.<br /> <font color=\"Red\">مولوی .</font><br />آب حیوان اگر این است که دارد لب دوست <br />روشن است این که خضر بهره سرابی دارد.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(73, 'آب خاکستر', '<span class=\"hlight\">آب خاکستر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ک ِ ت َ ]</font></b> (اِخ ) نام رودی در حدود ایران و روس که به رود لائین پیوندد.<br /></font></div>'),
(74, 'آب خضر', '<span class=\"hlight\">آب خضر.</span> <font color=\"DarkGreen\"><b>[ ب ِ خ ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب زندگانی، و مجازاً علم لدنّی . (برهان ) <span class=\"hlight\">:</span> <br />در کلک تو سرّ غیب مضمر<br />در لفظ تو آب خضر مدغم .<br /><font color=\"Red\">کمال الدین اصفهانی .</font><br /></font></div>'),
(75, 'آب خفته', '<span class=\"hlight\">آب خفته .</span> <font color=\"DarkGreen\"><b>[ ب ِ خ ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) آب راکد. <BR><font color=\"Blue\">◄</font> آب جاری که جریان آن از تراکم یا همواری مجری محسوس نباشد.<br /></font></div>'),
(76, 'آب خوردن', '<span class=\"hlight\">آب خوردن .</span> <font color=\"DarkGreen\"><b>[ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ دَ ]</font></b> (مص مرکب ) آشامیدن آب <span class=\"hlight\">:</span> <br />هرچند خلنده ست چو همسایه ٔ خرماست <br />بر شاخ چو خرماش همی آب خورَد خار.<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">در یک آب خوردن </span> ؛ در لحظه ای . در مدتی سخت کوتاه .<br /></font></div>'),
(77, 'آب خوز', '<span class=\"hlight\">آب خوز.</span> (اِخ ) رودی نزدیک قریه ٔ امیرآباد در سرحد ایران و روس .<br /></font></div>'),
(78, 'آب خون', '<span class=\"hlight\">آب خون .</span> (اِ مرکب ) آبخست است که جزیره ٔ میان دریا باشد. (برهان ). شاهدی برای این کلمه پیدا نشد، ممکن است مصحف آبخو یا آبخوست باشد. <BR><font color=\"Blue\">◄</font> خونابه .<br /></font></div>'),
(79, 'آب خیز', '<span class=\"hlight\">آب خیز.</span> (اِ مرکب ) طوفان <span class=\"hlight\">:</span> <br />آب خیز است این جهان کشتیت را<br />بادبان این طاعت و دانش خله .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و دل در میان طوفان بلا و آبخیز محنت و عنا گرفتار شد. (تاج المآثر).<br />اندر این آب خیز نوح توئی <br />واندر این دامگه فتوح توئی .<br /> <font color=\"Red\">اوحدی .</font><br /><BR><font color=\"Blue\">◄</font> طغیان و افزایش آب در فصل بهار. بهارآب <span class=\"hlight\">:</span> و ایشان را <font color=\"DarkGreen\"><b>[ مردم سرخس را ]</font></b> یکی خشک رود است که اندر میان بازار میگذرد و بوقت آبخیز اندرو آب رَوَد و بس . (حدودالعالم ). و از آنجا روی بقصبه نهاد وقت آبخیز بودبه شور رسید ترسید از عبره کردن آن آب . (تاریخ بیهق ). <BR><font color=\"Blue\">◄</font> مد، مقابل جزر. <BR><font color=\"Blue\">◄</font> و در برهان به معنی ناودان نیز آمده است . <BR><font color=\"Blue\">◄</font> (نف مرکب ) زمین آب دار چون چمن و جز آن . نزّاز.<br /></font></div>'),
(80, 'آب دادن', '<span class=\"hlight\">آب دادن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص مرکب ) آبیاری کردن . پسانیدن .<br /></font></div>'),
(81, 'آب داغ', '<span class=\"hlight\">آب داغ .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) آب جوشانیده . آب گرم کرده : یک استکان آب داغ .<br /></font></div>'),
(82, 'آب در خصیه', '<span class=\"hlight\">آب در خصیه .</span> <font color=\"DarkGreen\"><b>[ دَ خ ُ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (اِ مرکب ) اُدره . قیل الماء. قیله .<br /></font></div>'),
(83, 'آب درخت کافور', '<span class=\"hlight\">آب درخت کافور.</span> <font color=\"DarkGreen\"><b>[ ب ِ دِ رَت ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) ماءالکافور. (تحفه ).<br /></font></div>'),
(84, 'آب دز', '<span class=\"hlight\">آب دز.</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) رجوع به آبدیز شود.<br /></font></div>'),
(85, 'آب دزد', '<span class=\"hlight\">آب دزد.</span> <font color=\"DarkGreen\"><b>[ دُ]</font></b> (اِ مرکب ) منفذی بدرون زمین که آب و نم از آن نفوذ کند، و گویند این زمین یا این کاریز آب دزد دارد.<br /></font></div>'),
(86, 'آب دزدک', '<span class=\"hlight\">آب دزدک .</span> <font color=\"DarkGreen\"><b>[ دُ دَ ]</font></b> (اِ مرکب ) نی یا چوبی کاواک که در درون آن چوب دیگر تعبیه کنند و از دهان آن آب افکنند. و عربی آن مضخه و ذرّاقه و زرّاقه و سرّاقه است . و به فارسی آب انداز نیز گویند. <BR><font color=\"Blue\">◄</font> قسمی حشره چندِ زنبوری سرخ که در زیر خاک باشد و ریشه ٔ نبات خورد و آن را تباه کند و حوض و امثال آن را سوراخ کند، و در بعض ولایات آن را زمین سنبه گویند. پشیل . <BR><font color=\"Blue\">◄</font> (اصطلاح طب ) آلتی از شیشه که بر سر آن سوزنی مجوّف است و بدان در تن آدمی و جانوران دواهای مایع کنند. و این عمل را تزریق نامند.<br /></font></div>'),
(87, 'آب دزفول', '<span class=\"hlight\">آب دزفول .</span> <font color=\"DarkGreen\"><b>[ ب ِ دِ ]</font></b> (اِخ ) آبدیز.<br /></font></div>'),
(88, 'آب دست', '<span class=\"hlight\">آب دست .</span> <font color=\"DarkGreen\"><b>[ ب ِ <span class=\"hlight\" dir=\"rtl\">/</span> ب ْ دَ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبدست . آبی که بیشتر با دو ظرف موسوم به آفتابه لگن پیش از طعام و بعد از طعام برای شستن دست و دهان بکار است <span class=\"hlight\">:</span> <br />حورعین را ببهشت آرزو آید همه شب <br />کآدمی وار به بزم تو رسد در شبگیر<br />آب دستت همه بر روی کشیدی چو گلاب <br />خاک پایت همه در زلف دمیدی چو عبیر.<br /> <font color=\"Red\">معزی .</font><br />هم خلال ازطوبی و هم آبدست از سلسبیل <br />بلکه دستاب همه تسنیم رضوان آمده .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> وضو. تکرع . غسل . توضؤ: الحدَث ؛ هرچه آبدست بدان تباه شود. (دستوراللغه ٔادیب نطنزی ). این معنی رفتن گناهان است به آبدست، اگر از اینها چیزی مانده است بدان که هنوز گناه در تست و وضوی تو تمام نیست . (کتاب المعارف ).<br />جمال یارشد قبله ی ْ نمازم <br />ز اشک رشک او شد آبدستم .<br /><font color=\"Red\">مولوی .</font><br />نماز عید خواهم کرد هان ساقی بیار آبی <br />برای آبدست ما به ابریق قدح شویان .<br /> <font color=\"Red\">کمال خجند.</font><br /> <BR><font color=\"Blue\">◄</font> استنجا کردن به آب . (برهان ). <BR><font color=\"Blue\">◄</font> لطف و مهارت در صنعت <span class=\"hlight\">:</span> <br />که بست آن نقش عارض، آفرین باد<br />که آب دست از وی آشکار است .<br /><font color=\"Red\">کمال خجندی .</font><br /></font></div>'),
(89, 'آب دندان', '<span class=\"hlight\">آب دندان .</span> <font color=\"DarkGreen\"><b>[ ب ِ دَ ]</font></b> (ترکیب اضافی، اِ مرکب ) صفا و برق دندان <span class=\"hlight\">:</span> <br />بیا و بوسه بده زآن دهان خندانت <br />که در دلم زده آتش بس آب دندانت .<br /><font color=\"Red\">نزاری .</font><br /></font></div>'),
(90, 'آب دهان', '<span class=\"hlight\">آب دهان .</span> <font color=\"DarkGreen\"><b>[ ب ِ دَ ]</font></b> (ترکیب اضافی، اِ مرکب ) بزاق . بصاق . خیو. تفو. خدو.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">آب دهان برای چیزی رفتن </span> ؛ خواهان و آرزومند آن بودن .<br /></font></div>'),
(91, 'آب دوغ', '<span class=\"hlight\">آب دوغ .</span> (اِ مرکب ) ماستی با آب بسیار، گشاده کرده <span class=\"hlight\">:</span> <br />کسی را کو تو بینی درد سرفه <br />بفرمایش تو آب دوغ و خرفه .<br /> <font color=\"Red\">طیان .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">بخیه به آب دوغ زدن </span> ؛ رنجی بیفائده بردن .<br /></font></div>'),
(92, 'آب دوغی', '<span class=\"hlight\">آب دوغی .</span> (ص نسبی ) منسوب به آب دوغ . چون آب دوغ . <BR><font color=\"Blue\">◄</font> در اصطلاح بنایان گچی یا آهکی با آب بسیار، تنک و رقیق کرده و آن را دوغاب هم گویند.<br /></font></div>'),
(93, 'آب دیده', '<span class=\"hlight\">آب دیده .</span> <font color=\"DarkGreen\"><b>[ ب ِ دی دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب اضافی، اِ مرکب ) اشک <span class=\"hlight\">:</span> <br />فرنگیس چون روی بهزاد دید<br />شد از آب دیده رخش ناپدید.<br /> <font color=\"Red\">فردوسی .</font><br />سزد که دو رخ کاریز آب دیده کنی <br />که ریزریز بخواهدْت ریختن کاریز.<br /> <font color=\"Red\">کسائی .</font><br />بدم چو بلبل وآنان به پیش دیده ٔ من <br />بدند همچو گل نوشکفته در گلزار<br />کنون ز دوری ایشان دو جوی میرانم <br />ز آب دیده و من بر کنار بوتیمار.<br /> <font color=\"Red\">جمال الدین عبدالرزاق .</font><br />کنونم آب حیاتی بحلق تشنه فروکن <br />نه آنگهی که بمیرم به آب دیده بشویی .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(94, 'آب راه', '<span class=\"hlight\">آب راه .</span> (اِ مرکب ) رهگذر آب .مجرای آب . نهر. جوی . آب راهه . راه آب . آوره . فرخور.<br /></font></div>'),
(95, 'آب راهه', '<span class=\"hlight\">آب راهه .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (اِ مرکب ) هر جا که آب در آن گذرد از رود و جوی و مسیل و مانند آن . گذرگاه سیل . (فرهنگستان زمین شناسی ) <span class=\"hlight\">:</span> <br />خاک خور، گو پس از این روح طبیعی تا من <br />آب راهه ش ز گذرگاه جگر بربندم .<br /> <font color=\"Red\">سیف اسفرنگ .</font><br /><BR><font color=\"Blue\">◄</font> راه آب . مجری . آوره . آب راه . فرخور. <BR><font color=\"Blue\">◄</font> نهری یا رودی که در نهر یا رود دیگر ریزد. رافد. رافده .<br /></font></div>'),
(96, 'آب رخ', '<span class=\"hlight\">آب رخ .</span> <font color=\"DarkGreen\"><b>[ ب ِ رُ ]</font></b> (ترکیب اضافی، اِ مرکب ) اعتبار. جاه . آبرو <span class=\"hlight\">:</span> <br />آب رخ زآب پشت بگریزد<br />کآب پشت آب رویها ریزد.<br /> <font color=\"Red\">سنائی .</font><br />در جستن نان آب رخ خویش مریزید<br />در نار مسوزید روان از پی نان را.<br /> <font color=\"Red\">سنائی .</font><br />خاقانیا ز نان طلبی آب رخ مریز<br />کآن حرص کآب رخ برد آهنگ جان کند.<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب رخ بردن کسی را</span> ؛ آبرو ریختن او را.<br /></font></div>'),
(97, 'آب رز', '<span class=\"hlight\">آب رز.</span> <font color=\"DarkGreen\"><b>[ ب ِ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) در تداول شعرا، شراب . خمر <span class=\"hlight\">:</span> <br />آب رز باید که باشد در صفا چون آب زر<br />گر ز زَرّمغربی ساغر نباشد گو مباش .<br /><font color=\"Red\">ابن یمین .</font><br /></font></div>'),
(98, 'آب رفت', '<span class=\"hlight\">آب رفت .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (ن مف مرکب، اِ مرکب ) سنگی که در جریان آب بطول زمان ساییده و لغزان و مایل بگردی شده باشد. <BR><font color=\"Blue\">◄</font> ته نشین آب رودخانه ها. (فرهنگستان زمین شناسی ). <br /></font></div>'),
(99, 'آب رفتن', '<span class=\"hlight\">آب رفتن .</span> <font color=\"DarkGreen\"><b>[ رَ ت َ ]</font></b>(مص مرکب ) کوتاه شدن جامه ٔ نو پس از شسته شدن آن .<br /></font></div>'),
(100, 'آب روده', '<span class=\"hlight\">آب روده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ]</font></b> (اِ مرکب ) قراقر. قرقر شکم . (فرهنگ اسدی، خطی ).<br /></font></div>'),
(101, 'آب روغن', '<span class=\"hlight\">آب روغن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رُو غ َ ]</font></b> (اِ مرکب ) روغن گداخته به آب گرم آمیخته که چلو را دهند. <BR><font color=\"Blue\">◄</font> ثرید. ترید. زریقاء. اشکنه .<br /></font></div>'),
(102, 'آب زال', '<span class=\"hlight\">آب زال .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) نام یکی از آبراهه های کشگان رود که در نزدیکی قلعه ٔ قاسم بدان می پیوندد.<br /></font></div>'),
(103, 'آب زدن', '<span class=\"hlight\">آب زدن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ ]</font></b> (مص مرکب ) آب افشاندن و پاشیدن، بچیزی یا بجایی .<br /></font></div>'),
(104, 'آب زر', '<span class=\"hlight\">آب زر.</span> <font color=\"DarkGreen\"><b>[ ب ِ زَ ]</font></b> (ترکیب اضافی، اِ مرکب ) زر محلول که بدان نویسند و تذهیب کنند. معرّب آن زریاب و بتصحیف زرباب است <span class=\"hlight\">:</span> کسی گفت چگونه میبینی این دیبای مُعْلَم را بر این حیوان لایعلم ؟ گفتم خطی زشت است که به آب زر نوشته است . (گلستان ).<br />منه جان من آب زر برپشیز<br />که صراف دانا نگیرد بچیز.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چون آب زر شدن ِ کار</span> ؛ سخت نیکو و بسامان شدن آن، و مرادف آن چون زر و چون نگار شدن است <span class=\"hlight\">:</span> <br />از پی زر بسر چو آب از پی آن دَوَم که او<br />با چو تو نقره ای کند کار دلم به آب زر.<br /> <font color=\"Red\">مجیر بیلقانی .</font><br />تا ز رای تو یافت پرتو نور<br />کار خورشید همچو آب زر است .<br /> <font color=\"Red\">رفیعالدین لنبانی .</font><br />آفتابی که هر دو عالم را<br />کار از او همچو آب زر گردد.<br /> <font color=\"Red\">عطار.</font><br /><BR><font color=\"Blue\">◄</font> شراب سفید.<br /></font></div>'),
(105, 'آب زرتاب', '<span class=\"hlight\">آب زرتاب .</span> <font color=\"DarkGreen\"><b>[ ب ِ زَ ]</font></b> (ترکیب وصفی، اِ مرکب ) آبی که در آن زر تفته فروبرده سرد کنند و در طب بکار بوده است .<br /></font></div>'),
(106, 'آب زرد', '<span class=\"hlight\">آب زرد.</span> <font color=\"DarkGreen\"><b>[ ب ِ زَ ]</font></b> (اِخ ) نام یکی از آبراهه های رود جراحی، و آن را آب زلال هم میخوانند.<br /></font></div>'),
(107, 'آب زرشک', '<span class=\"hlight\">آب زرشک .</span> <font color=\"DarkGreen\"><b>[ ب ِ زِ رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که از تر نهادن و خیسانیدن زرشک حاصل کنند.<br /></font></div>'),
(108, 'آب زلال', '<span class=\"hlight\">آب زلال .</span> <font color=\"DarkGreen\"><b>[ ب ِ زُ ]</font></b> (اِخ ) آب زرد. نام یکی از دو آبراهه ٔ رود جراحی .<br /></font></div>'),
(109, 'آب زندگانی', '<span class=\"hlight\">آب زندگانی .</span><font color=\"DarkGreen\"><b>[ ب ِ زِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب حیات .آب خضر. آب زندگی . آب بقاء. ماءالحیات <span class=\"hlight\">:</span> <br />ابر آب زندگانی اوست من زنده شوم <br />چون یکی قطره ز ابرش در دهان من چکید.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و آب زندگانی عمر جاوید دهد. (کلیله و دمنه ).<br />سکندر رفت لیکن جست بهره <br />ز آب زندگانی خضر و الیاس .<br /> <font color=\"Red\">سنائی .</font><br />هنوزم آب در جوی جوانی است <br />هنوزم لب پُر آب زندگانی است .<br /> <font color=\"Red\">نظامی .</font><br />و خضروار آب زندگانی او من بروی کار آوردم . (مرزبان نامه ).<br />دانش است آب زندگانی مرد<br />خنک آن کاب زندگانی خورد.<br /> <font color=\"Red\">اوحدی .</font><br />هوای منزل یار آب زندگانی ماست <br />صبا بیار نسیمی ز خاک شیرازم .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(110, 'آب زندگی', '<span class=\"hlight\">آب زندگی .</span> <font color=\"DarkGreen\"><b>[ ب ِ زِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب حیات . آب خضر. آب زندگانی . آب بقا. ماءالحیات . چشمه ٔ خضر. چشمه ٔ زندگی <span class=\"hlight\">:</span> <br />با که گویم در همه ده زنده کو<br />سوی آب زندگی پوینده کو؟<br /> <font color=\"Red\">مولوی .</font><br />ابر اگر آب زندگی بارد<br />هرگز از شاخ بید بر نخوری .<br /> <font color=\"Red\">سعدی .</font><br />نشود آب زندگی ریزان <br />مگر از دیده ٔ سحرخیزان .<br /> <font color=\"Red\">اوحدی .</font><br />گر ز سوز تشنگی جانت بلب خواهد رسید<br />از خضر مپذیر منت بهر آب زندگی .<br /> <font color=\"Red\">ابن یمین .</font><br />معنی ّ آب زندگی و روضه ٔ ارم <br />جز طرف جویبار و می خوشگوار چیست ؟<br /> <font color=\"Red\">حافظ.</font><br />شاهدی از لطف و پاکی رشک آب زندگی .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(111, 'آب زه', '<span class=\"hlight\">آب زه .</span> <font color=\"DarkGreen\"><b>[ زِه ْ ]</font></b> (اِمرکب ) آبی که از کنار چشمه یا رود و تالاب و امثال آن زِهَد یعنی ترابد و آن را زه آب نیز گویند. نزیز.<br /></font></div>'),
(112, 'آب ساب کردن', '<span class=\"hlight\">آب ساب کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) مصحف آب سای کردن . در اصطلاح بنایان، املس و لغزان کردن کنار آجری با ساییدن آجری دیگر بر او که پیاپی به آب فروزنند.<br /></font></div>'),
(113, 'آب سار', '<span class=\"hlight\">آب سار.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) در قزوین و قمشه و سمیرم فارس نام چشمه هائی است که بزعم عوام افشاندن آب آن در مزارعی که ملخ بدانجا فرود آمده باشد سبب آمدن مرغ سار که ملخ را دفعو تباه می کند، گردد، و آن را آب مرغان نیز گویند.<br /></font></div>'),
(114, 'آب سبز', '<span class=\"hlight\">آب سبز.</span> <font color=\"DarkGreen\"><b>[ ب ِ س َ ]</font></b> (ترکیب وصفی، اِ مرکب ) نام بیماریی در چشم، بسیار شایع که از فشار درونی چشم پدید آید.<br /></font></div>'),
(115, 'آب سرخ', '<span class=\"hlight\">آب سرخ .</span> <font color=\"DarkGreen\"><b>[ ب ِس ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) شراب . خمر <span class=\"hlight\">:</span> <br />من و آب سرخ و سر سبز شاه <br />جهان گو فروشو به آب ِ سیاه .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(116, 'آب سردی', '<span class=\"hlight\">آب سردی .</span> <font color=\"DarkGreen\"><b>[ ب ِ س َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب که پس از بول از مجری برآید. ودی . وذی . (زمخشری ).<br /></font></div>'),
(117, 'آب سفید', '<span class=\"hlight\">آب سفید.</span> <font color=\"DarkGreen\"><b>[ ب ِ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) نام علتی در چشم . رجوع به آب مروارید شود.<br /></font></div>'),
(118, 'آب سکندر', '<span class=\"hlight\">آب سکندر.</span> <font color=\"DarkGreen\"><b>[ ب ِ س ِ ک َ دَ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب زندگی .<br /></font></div>'),
(119, 'آب سیاه', '<span class=\"hlight\">آب سیاه .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) آب سیه . کوری تام یا ناقص که از ضمور و اطروفیای ِ عصب باصره پدید آید <span class=\"hlight\">:</span> <br />ز سهم خدنگت بروز سپید<br />درآید بچشم خور آب سیاه .<br /> <font color=\"Red\">کمال الدین اسماعیل .</font><br />و چشم آب سیاه آورده را زاور گویند. (برهان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب سیاه آوردن چشم </span> ؛ زاور شدن آن و نزول آب سیاه در آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب سیاه ناقص </span> ؛ درجه ٔ اول آب سیاه است که تیرگی و تاری در چشم پدید آرد و بعمی و آب سیاه تام منتهی گردد.<br /> <BR><font color=\"Blue\">◄</font> آب عظیم و عمیق <span class=\"hlight\">:</span> بر لب آب سیاهی که در میانه فاصله بود فرود آمدند. (ظفرنامه ٔ شرف الدین ). <BR><font color=\"Blue\">◄</font> طوفان . <BR><font color=\"Blue\">◄</font> مجازاً به معنی آفات و مکروهات ومرگ آید <span class=\"hlight\">:</span> <br />زردگوشان بگوشه ها مردند<br />سر به آب سیه فروبردند.<br /> <font color=\"Red\">نظامی .</font><br />من و آب سرخ و سر سبز شاه <br />جهان گو فروشو به آب سیاه .<br /> <font color=\"Red\">نظامی .</font><br />جهان اگر همه آب سیه گرفت چه باک <br />چو راضیم بیکی نان و آبک انگور.<br /> <font color=\"Red\">ابن جلال .</font><br /> <BR><font color=\"Blue\">◄</font> سعیر که از دهانه های آتش فشانی بیرون دَوَد <span class=\"hlight\">:</span> <br />آب سیه از زمین برآمد<br />مرگ از در آهنین برآمد<br />بارید بباغ ما تگرگی <br />وز گلبن ما نماند برگی .<br /> <font color=\"Red\">نظامی .</font><br />خضرت صحرا آب سیاه پنداشتی . (راحةالصدور راوندی ). <BR><font color=\"Blue\">◄</font> مداد. نِقس . زگالاب . دوده ٔ مرکب <span class=\"hlight\">:</span> <br />آب سیه خورده چنان گشت مست <br />کش چو نگیرند بیفتد ز دست .<br /> <font color=\"Red\">امیرخسرودهلوی (در وصف قلم ).</font><br /><BR><font color=\"Blue\">◄</font> و به معنی سرشک و اشک و طوفان نوح و سیل و گل ولای و شراب نیز در فرهنگها آمده است .<br /></font></div>'),
(120, 'آب سیاه', '<span class=\"hlight\">آب سیاه .</span>(اِخ ) نام دره ای در نزدیکی شهر قنوج در هندوستان .<br /></font></div>'),
(121, 'آب شبی', '<span class=\"hlight\">آب شبی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ش َب ْ بی ]</font></b> (ترکیب وصفی، اِ مرکب ) آب معدنی که در آن شَب ّ یا زاج باشد.<br /></font></div>'),
(122, 'آب شناس', '<span class=\"hlight\">آب شناس .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b>(نف مرکب ) آنکه غرقاب و تنک آب را از یکدیگر بازداند و راه نمای کشتی شود تا بر خاک ننشیند <span class=\"hlight\">:</span> <br />بنزد آبشناس آن کس است طعمه ٔ موج <br />که زآب علم تو دارد گذر طمع به شناه .<br /> <font color=\"Red\">رضی الدین نیشابوری .</font><br />زیر رکاب تواَند کارگذاران ْ رهین <br />پیش عنان تواَند آب شناسان ْ مطیع.<br /> <font color=\"Red\">رضی الدین نیشابوری .</font><br /><BR><font color=\"Blue\">◄</font> مقنی که داندکدام زمین را آبست و کاریز در آن توان کردن . قناقن .قن قن . (ربنجنی ) (السامی فی الاسامی ). و مجازاً رسم و قاعده دان . و آبشناسان جمع آن است .<br /></font></div>'),
(123, 'آب شور', '<span class=\"hlight\">آب شور.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) نام یکی از سه آبراهه ٔ رودطاب در حدود فارس، و نام دیگر آن آب شولستان است .<br /></font></div>'),
(124, 'آب شوره', '<span class=\"hlight\">آب شوره .</span> <font color=\"DarkGreen\"><b>[ ب ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که با شوره ٔ قلمی خنک شده باشد.<br /></font></div>'),
(125, 'آب شیب', '<span class=\"hlight\">آب شیب .</span> (اِ مرکب ) رهگذر آب با شیب بسیار. و خود آن آب را نیز گویند.<br /></font></div>'),
(126, 'آب شیرین', '<span class=\"hlight\">آب شیرین .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) نام محلی کنار راه سیرجان و بندرعباس میان زرتو و سرزه . <BR><font color=\"Blue\">◄</font> نام یکی از سه آبراهه ٔ رود طاب، و آن را آب خیرآباد هم مینامند.<br /></font></div>'),
(127, 'آب صورت', '<span class=\"hlight\">آب صورت .</span> <font color=\"DarkGreen\"><b>[ ب ِ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب دست و روی شستن .<br /></font></div>'),
(128, 'آب طبرستان', '<span class=\"hlight\">آب طبرستان .</span> <font color=\"DarkGreen\"><b>[ ب ِ طَ ب َ رِ ]</font></b> (اِخ ) رجوع به آب تبرستان شود.<br /></font></div>'),
(129, 'آب طبریه', '<span class=\"hlight\">آب طبریه .</span> <font color=\"DarkGreen\"><b>[ ب ِ طَ ب َ ری ی َ ]</font></b> (اِخ ) رجوع به آب تبریه شود.<br /></font></div>'),
(130, 'آب طلا', '<span class=\"hlight\">آب طلا.</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (اِ مرکب ) آب زر. <BR><font color=\"Blue\">◄</font> آب اکلیل . و رجوع بکلمه ٔ طلا شود.<br /></font></div>'),
(131, 'آب طلاکاری', '<span class=\"hlight\">آب طلاکاری .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (حامص مرکب ) تذهیب . <BR><font color=\"Blue\">◄</font> اندودن به اکلیل .<br /></font></div>'),
(132, 'آب طلایی', '<span class=\"hlight\">آب طلایی .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ]</font></b> (ص نسبی ) مذهَّب . <BR><font color=\"Blue\">◄</font> به اکلیل اندوده .<br /></font></div>'),
(133, 'آب طلع', '<span class=\"hlight\">آب طلع.</span> <font color=\"DarkGreen\"><b>[ ب ِ طَ ]</font></b> (ترکیب اضافی، اِ مرکب ) ظاهراً عرقی که از شکوفه ٔ خرما گیرند و امروز آن را طلعانه گویند <span class=\"hlight\">:</span> و از وی <font color=\"DarkGreen\"><b>[ از فارس ]</font></b> آب گل و آب بنفشه و آب طلع خیزد. (حدودالعالم ).<br /></font></div>'),
(134, 'آب علا', '<span class=\"hlight\">آب علا.</span> <font color=\"DarkGreen\"><b>[ ب ِ ع َ ]</font></b> (اِخ ) نام چشمه ای بدماوند که آب آن دَم دارد و یکی از بهترین آبهای نوع خود برای گوارش و دیگر خاصیتهای طبی است .<br /></font></div>'),
(135, 'آب غوره', '<span class=\"hlight\">آب غوره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) عصاره ای که از غوره ٔ انگور گیرند. امعاسین (کلمه ٔ یونانی ) <span class=\"hlight\">:</span> <br />غنیمت دان ز آب غوره بغرایی چو میدانی <br />که بیش از چند روزی غوره در بستان نمی ماند.<br /><font color=\"Red\">بسحاق اطعمه .</font><br /></font></div>'),
(136, 'آب فرنگی', '<span class=\"hlight\">آب فرنگی .</span> <font color=\"DarkGreen\"><b>[ ف ِ رَ ]</font></b> (اِخ ) نام چشمه ٔ آب معدنی به لاریجان .<br /></font></div>'),
(137, 'آب فشان', '<span class=\"hlight\">آب فشان .</span> <font color=\"DarkGreen\"><b>[ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (نف مرکب، اِ مرکب ) سوراخهایی که آب گرم از آنها بیرون رانده می شود. (فرهنگستان زمین شناسی ).<br /></font></div>'),
(138, 'آب قصیل', '<span class=\"hlight\">آب قصیل .</span> <font color=\"DarkGreen\"><b>[ ب ِ ق َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که از کوفتن خوید جو به دست کنند و آشامیدن آن در مسلولین فربهی آرد و این بیماری را عظیم نافع باشد.<br /></font></div>'),
(139, 'آب قنبر', '<span class=\"hlight\">آب قنبر.</span> <font color=\"DarkGreen\"><b>[ ب ِ قَم ْ ب َ ]</font></b> (اِخ ) رجوع بگردنه ٔ آب قنبر شود.<br /></font></div>'),
(140, 'آب قند', '<span class=\"hlight\">آب قند.</span> <font color=\"DarkGreen\"><b>[ ب ِ ق َ ]</font></b> (ترکیب اضافی، اِ مرکب ) شربت قند. <BR><font color=\"Blue\">◄</font> قسمی خربزه بکاشان بسیار شیرین و نازک .<br /></font></div>'),
(141, 'آب لحیم', '<span class=\"hlight\">آب لحیم .</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ ]</font></b> (ترکیب اضافی، اِ مرکب ) جوهر نمک .<br /></font></div>'),
(142, 'آب لنبه کردن', '<span class=\"hlight\">آب لنبه کردن .</span> <font color=\"DarkGreen\"><b>[ لَم ْ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ک َ دَ ]</font></b> (مص مرکب ) فشردن میوه ٔ چون نار و جدا کردن آب آن از دانه در پوست خود.<br /></font></div>'),
(143, 'آب لیمو', '<span class=\"hlight\">آب لیمو.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که از فشردن لیموی ترش حاصل کنند <span class=\"hlight\">:</span> <br />آرزویی که ترا هست به آب لیمو<br />شرح آن راست نیاید به هزاران طومار.<br /><font color=\"Red\">بسحاق اطعمه .</font><br /></font></div>'),
(144, 'آب مالی کردن', '<span class=\"hlight\">آب مالی کردن .</span> <font color=\"DarkGreen\"><b>[ ک َدَ ]</font></b> (مص مرکب ) شستن جامه بار اول به آب تا سپس با صابون شویند. <BR><font color=\"Blue\">◄</font> شستن جامه ٔ آلوده بصابون در آب خارج حوض تا کف صابون آب حوض را آلوده نکند.<br /></font></div>'),
(145, 'آب مانه', '<span class=\"hlight\">آب مانه .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) نام محلی از توابع کاشان دارای معدن زغال سنگ .<br /></font></div>'),
(146, 'آب ماه', '<span class=\"hlight\">آب ماه .</span> (اِ مرکب ) ماه آب سریانی، مرادف آغوسطس رومی . و رجوع به آب (مدخل ِ دوم ) شود.<br /></font></div>'),
(147, 'آب ماهی نمکسود', '<span class=\"hlight\">آب ماهی نمکسود.</span> <font color=\"DarkGreen\"><b>[ ب ِ ی ِ ن َ م َ ]</font></b> (ترکیب اضافی، اِ مرکب ) ماءالنون . (تحفه ).<br /></font></div>'),
(148, 'آب مرده', '<span class=\"hlight\">آب مرده .</span> <font color=\"DarkGreen\"><b>[ ب ِ م ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب وصفی، اِ مرکب ) آب راکد.<br /></font></div>'),
(149, 'آب مردی', '<span class=\"hlight\">آب مردی .</span> <font color=\"DarkGreen\"><b>[ ب ِ م َ ]</font></b> (ترکیب اضافی، اِ مرکب ) نطفه . منی .<br /></font></div>'),
(150, 'آب مرغان', '<span class=\"hlight\">آب مرغان .</span> <font color=\"DarkGreen\"><b>[ب ِ م ُ ]</font></b> (اِخ ) نام تفرج گاهی به نزدیکی شیراز که مردمان در ماه رجب هر سه شنبه بدانجا روند <span class=\"hlight\">:</span> <br />دیگر نروم به آب مرغان <br />دیگر نخورم کباب مرغان .<br /> <font color=\"Red\">؟ (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> نام چشمه ای است در قهستان و سمیرم فارس و گویند هر جای که ملخ فرود آید چون آب این چشمه بدانجا برند سار یعنی مرغ ملخ خوار از پی آب رود و ملخ فرود آمده را بخورد و تباه کند. و آن را آب سار نیز گویند.<br /></font></div>'),
(151, 'آب مروارید', '<span class=\"hlight\">آب مروارید.</span> <font color=\"DarkGreen\"><b>[ ب ِ م ُرْ ]</font></b> (ترکیب اضافی، اِ مرکب ) نام بیماریی در چشم که از کدورت زجاجیه یا پرده های آن حاصل شود و موجب عمای تام یا ناقص گردد. و آن را آب سپید و آب سفید نیزگویند. و در برهان «تمر» را بدین معنی آورده است .<br /></font></div>'),
(152, 'آب مضاف', '<span class=\"hlight\">آب مضاف .</span><font color=\"DarkGreen\"><b>[ ب ِ م ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع بمضاف شود.<br /></font></div>'),
(153, 'آب مطلق', '<span class=\"hlight\">آب مطلق .</span> <font color=\"DarkGreen\"><b>[ ب ِ م ُ ل َ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع بمطلق شود.<br /></font></div>'),
(154, 'آب معدنی', '<span class=\"hlight\">آب معدنی .</span> <font color=\"DarkGreen\"><b>[ ب ِ م َ دَ ]</font></b> (ترکیب وصفی، اِ مرکب ) چشمه ای که بطبع آمیخته به پاره ای املاح است مانند گوگرد و زیبق و ید و آهن و شب ّ و زاج و در بعض بیماریها بدان استحمام کنند و یا آشامند.<br /></font></div>'),
(155, 'آب معلق', '<span class=\"hlight\">آب معلق .</span> <font color=\"DarkGreen\"><b>[ ب ِ م ُ ع َل ْ ل َ ]</font></b> (ترکیب وصفی، اِ مرکب ) مجازاً، آسمان <span class=\"hlight\">:</span> <br />سنگ در این خاک مطبَّق نشان <br />خاک بر این آب معلق فشان .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(156, 'آب مقطر', '<span class=\"hlight\">آب مقطر.</span> <font color=\"DarkGreen\"><b>[ ب ِ م ُ ق َطْ طَ ]</font></b> (ترکیب وصفی، اِ مرکب ) آب حاصل کرده از بخار. آبی که با قرع و انبیق تصفیه شده باشد.<br /></font></div>'),
(157, 'آب مژه', '<span class=\"hlight\">آب مژه .</span> <font color=\"DarkGreen\"><b>[ ب ِ م ُژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ ]</font></b> (ترکیب اضافی، اِ مرکب ) اشک <span class=\"hlight\">:</span> <br />من شسته به نظاره و انگشت همی گز<br />وآب مژه بگشاده و غلطان شده چون گوز.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(158, 'آب مژگان', '<span class=\"hlight\">آب مژگان .</span> <font color=\"DarkGreen\"><b>[ ب ِ م ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) اشک :<br />ببدرود کردن رخ هر کسی <br />ببوسید با آب مژگان بسی .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(159, 'آب ناداده', '<span class=\"hlight\">آب ناداده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) مقابل آب داده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">شمشیر آب ناداده، پیکان آب ناداده و بی پر</span> ؛ شَرْخ .<br /></font></div>'),
(160, 'آب نار', '<span class=\"hlight\">آب نار.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به آب انار شود.<br /></font></div>'),
(161, 'آب نارنج', '<span class=\"hlight\">آب نارنج .</span> <font color=\"DarkGreen\"><b>[ ب ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که از فشردن نارنج حاصل کنند.<br /></font></div>'),
(162, 'آب نبات', '<span class=\"hlight\">آب نبات .</span> <font color=\"DarkGreen\"><b>[ ب ِ ن َ ]</font></b> (ترکیب اضافی، اِ مرکب ) قسمی حلوا و شیرینی <span class=\"hlight\">:</span> <br />چه شیوه میکندآب نبات با دل ما<br />که بر طبقچه ٔ شمشاد و کاسه ٔ حلبی است .<br /><font color=\"Red\">بسحاق اطعمه .</font><br /></font></div>'),
(163, 'آب ندیده', '<span class=\"hlight\">آب ندیده .</span> <font color=\"DarkGreen\"><b>[ ن َ دی دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) جامه یا سفال و مانند آن که هیچگاه شسته نشده و آب بدان نرسیده باشد: کوزه ٔ آب ندیده . کرباس آب ندیده .<br /></font></div>'),
(164, 'آب ندیدگی', '<span class=\"hlight\">آب ندیدگی .</span> <font color=\"DarkGreen\"><b>[ ن َ دی دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص مرکب ) کیفیت و حالت چیز آب ندیده ماننده ٔ کرباس و سفال .<br /></font></div>'),
(165, 'آب نشاط', '<span class=\"hlight\">آب نشاط.</span> <font color=\"DarkGreen\"><b>[ ب ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مذی . (زمخشری ) (ربنجنی ). <BR><font color=\"Blue\">◄</font> نطفه .<br /></font></div>'),
(166, 'آب نما', '<span class=\"hlight\">آب نما.</span> <font color=\"DarkGreen\"><b>[ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ]</font></b> (اِ مرکب ) مظهر چشمه و کاریز. <BR><font color=\"Blue\">◄</font> بنائی که در آنجا کنند. <BR><font color=\"Blue\">◄</font> سراب . کوراب . آل . کتیر. واله . کور. لعاب الشمس . یلمع. عسقل . عساقل . لوه .<br /></font></div>'),
(167, 'آب نمک', '<span class=\"hlight\">آب نمک .</span> <font color=\"DarkGreen\"><b>[ ب ِ ن َ م َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب آمیخته با نمک که در آن ماهی و پاره ای گوشتها و بعض حبوب و بُقول را از فساد و تباهی نگاه دارند، و آن را نمکاب نیز گویند.<br /></font></div>'),
(168, 'آب نورد', '<span class=\"hlight\">آب نورد.</span> <font color=\"DarkGreen\"><b>[ ن َ وَ ]</font></b> (نف مرکب ) ملاح . دریانورد <span class=\"hlight\">:</span> <br />خلیل آتش کوبی کلیم آب نورد<br />چه باک داری در کارزار ازآتش و آب .<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(169, 'آب نوشادری', '<span class=\"hlight\">آب نوشادری .</span> <font color=\"DarkGreen\"><b>[ ب ِ دُ ]</font></b> (ترکیب وصفی، اِ مرکب ) آب معدنی که در آن بطبع نوشادر باشد.<br /></font></div>'),
(170, 'آب نکشیده', '<span class=\"hlight\">آب نکشیده .</span> <font color=\"DarkGreen\"><b>[ ن َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) تطهیرنشده . <BR><font color=\"Blue\">◄</font> مجازاً در تداول عوام، سخت درشت <span class=\"hlight\">:</span> فحش آب نکشیده . <br /></font></div>'),
(171, 'آب نی', '<span class=\"hlight\">آب نی .</span> (اِخ ) نام رودی میان تورک و شیراز. (از بهار عجم ).<br /></font></div>'),
(172, 'آب نی', '<span class=\"hlight\">آب نی .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) میلاب (در قلیان ).<br /></font></div>'),
(173, 'آب نی شکر', '<span class=\"hlight\">آب نی شکر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ک َ ]</font></b> (ترکیب اضافی، اِ مرکب ) عسل القصب . (تحفه ).<br /></font></div>'),
(174, 'آب نیک', '<span class=\"hlight\">آب نیک .</span> (اِخ ) نام قریه ای از رودبار در ایالت طهران .<br /></font></div>'),
(175, 'آب هندوانه', '<span class=\"hlight\">آب هندوانه .</span> <font color=\"DarkGreen\"><b>[ ب ِ هَِ دِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که از فشردن مغز هندوانه حاصل کنند.<br /></font></div>'),
(176, 'آب و آش', '<span class=\"hlight\">آب و آش .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِ مرکب، از اتباع ) خوردنی های پخته .<br /></font></div>'),
(177, 'آب و جارو کردن', '<span class=\"hlight\">آب و جارو کردن .</span> <font color=\"DarkGreen\"><b>[ب ُ ک َ دَ ]</font></b> (مص مرکب ) روفتن بجاروب با آب پاشیدن .<br /></font></div>'),
(178, 'آب و رنگ', '<span class=\"hlight\">آب و رنگ .</span> <font color=\"DarkGreen\"><b>[ ب ُ رَ ]</font></b> (اِ مرکب، از اتباع ) سپیدی و سرخی در چهره ورونق و جلا: خوش آب و رنگ . بد آب و رنگ <span class=\"hlight\">:</span> <br />حواصل چون بود در آب چون رنگ <br />همان رونق در او از آب و از رنگ .<br /> <font color=\"Red\">نظامی .</font><br />ز قد و روی تو شرمنده باغبان میگفت <br />که آب و رنگ ندارند سرو و لاله ٔ ما.<br /> <font color=\"Red\">؟</font><br /><BR><font color=\"Blue\">◄</font> رنگ و رو. رنگ و آب .<br /></font></div>'),
(179, 'آب و رنگی', '<span class=\"hlight\">آب و رنگی .</span> <font color=\"DarkGreen\"><b>[ ب ُ رَ ]</font></b> (ص نسبی ) در اصطلاح نقاشان، نقشی بالوان . مقابل سیاه قلم .<br /></font></div>'),
(180, 'آب و هوا', '<span class=\"hlight\">آب و هوا.</span> <font color=\"DarkGreen\"><b>[ ب ُ هََ ]</font></b> (ترکیب عطفی، اِ مرکب ) کشور. اقلیم . <BR><font color=\"Blue\">◄</font> سقم یا صحت مربوط به آب و هوای ناحیتی .<br /></font></div>'),
(181, 'آب و گل', '<span class=\"hlight\">آب و گل .</span> <font color=\"DarkGreen\"><b>[ ب ُ گ ِ ]</font></b> (اِ مرکب، از اتباع ) خانه . بنا. زمین .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب و گلی در جایی داشتن </span> ؛ خانه یا مزرعه ای را در آنجا دارا بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">از آب و گل درآمدن یا درآوردن </span> ؛ بسن رشد و بلوغ یا نزدیک به آن رسیدن یا رسانیدن .<br /> <BR><font color=\"Blue\">◄</font> گاه آب و گل گویند و مراد آب و خاک است <span class=\"hlight\">:</span> <br />گر خود از اصل بنگریم او را<br />آب و گل مادر و پدر باشد.<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(182, 'آب ورز', '<span class=\"hlight\">آب ورز.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b>(نف مرکب ) آب باز. شناگر. سباح . <BR><font color=\"Blue\">◄</font> ملاح .<br /></font></div>'),
(183, 'آب ورزی', '<span class=\"hlight\">آب ورزی .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (حامص مرکب ) کار آب ورز.<br /></font></div>'),
(184, 'آب پاش', '<span class=\"hlight\">آب پاش .</span> (اِ مرکب ) آوندی که بدان بر زمین و گُل و چمن آب پاشند. رشاشه . آب پاچ .<br /></font></div>'),
(185, 'آب پاشی', '<span class=\"hlight\">آب پاشی .</span> (حامص مرکب ) عمل آب پاشیدن بر گل و جز آن .<br /></font></div>'),
(186, 'آب پخته', '<span class=\"hlight\">آب پخته .</span> <font color=\"DarkGreen\"><b>[ پ ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (اِ مرکب ) آش اماج . <BR><font color=\"Blue\">◄</font> آب سرد. آب سر. <BR><font color=\"Blue\">◄</font> (ن مف مرکب ) جوشانیده .<br /></font></div>'),
(187, 'آب پز', '<span class=\"hlight\">آب پز.</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (ن مف مرکب ) تخم مرغ یاگوشت به آب ساده و بی روغن پخته . مسلوق و مسلوقه .<br /></font></div>'),
(188, 'آب پشت', '<span class=\"hlight\">آب پشت .</span> <font color=\"DarkGreen\"><b>[ ب ِ پ ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) نطفه . منی . آب مردی <span class=\"hlight\">:</span> <br />آب رخ زآب پشت بگریزد<br />کآب پشت آب رویها ریزد.<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(189, 'آب پنیر', '<span class=\"hlight\">آب پنیر.</span> <font color=\"DarkGreen\"><b>[ ب ِ پ َ ]</font></b> (ترکیب اضافی، اِ مرکب ) ماءالجبن . (تحفه ).<br /></font></div>'),
(190, 'آب چرا', '<span class=\"hlight\">آب چرا.</span> <font color=\"DarkGreen\"><b>[ چ َ ]</font></b> (اِ مرکب ) غذائی که به ناشتا خورند و آن را نهاری گویند، و در بعض فرهنگها به معنی خوراک جن و پری و طیور آورده اند.<br /></font></div>'),
(191, 'آب چشی', '<span class=\"hlight\">آب چشی .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِمرکب ) غذائی که نخستین بار بطفل در شش ماهگی دهند.<br /></font></div>'),
(192, 'آب چلو', '<span class=\"hlight\">آب چلو.</span> <font color=\"DarkGreen\"><b>[ چ ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> لُو ]</font></b> (اِ مرکب ) آبی که برنج در آن جوشیده باشد و آن را آبریس و آشام و آشاب نیز گویند.<br /></font></div>'),
(193, 'آب چکیده', '<span class=\"hlight\">آب چکیده .</span> <font color=\"DarkGreen\"><b>[ ب ِ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب وصفی، اِ مرکب ) آب که از کوزه و جز آن ترابد. ماءالقطر. (تحفه ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(194, 'آب چین', '<span class=\"hlight\">آب چین .</span> (اِ مرکب ) جامه ای که تن مرده را پس از غسل بدان خشک کنند. (از برهان ) <span class=\"hlight\">:</span> <br />براهام گفت ای نبرده سوار<br />همی رنجه داری مرا خوارخوار<br />بخسبی و چیزت بدزدد کسی <br />از این در مرا رنجه داری بسی <br />بخانه درآی ار جهان تنگ شد<br />همه کار بی برگ و بی رنگ شد<br />به پیمان که چیزی نخواهی ز من <br />ندارم بمرگ آبچین و کفن .<br /> <font color=\"Red\">فردوسی .</font><br />بپوشم <font color=\"DarkGreen\"><b>[مرا]</font></b> به آیین به جامه ی ْ عجم <br />کفن وآبچین ده ز کافور نم .<br /> <font color=\"Red\">اسدی .</font><br />و آن را به عربی مرشحه و مرشف (ربنجنی ) و قطیفه گویند. <br /></font></div>'),
(195, 'آب کار', '<span class=\"hlight\">آب کار.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) نطفه <span class=\"hlight\">:</span> <br />آب کارت مبر که گردی پیر...<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(196, 'آب کاسنی', '<span class=\"hlight\">آب کاسنی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که از کوفتن و فشردن برگ کاسنی حاصل کنند مداوا را.<br /></font></div>'),
(197, 'آب کبریتی', '<span class=\"hlight\">آب کبریتی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ک ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) آب معدنی که در آن بطبع گوگرد باشد.<br /></font></div>'),
(198, 'آب کبود', '<span class=\"hlight\">آب کبود.</span> <font color=\"DarkGreen\"><b>[ ب ِ ک َ ]</font></b> (اِخ ) نام دریای چین . بحر اخضر. و در افسانه های قدیم آمده است که هر شب زنان نیکوروی از آن آب برآیند و در دامن کوهی که بر کنار آن است بازی کنند و چون روز شود باز دریا شوند.<br /></font></div>'),
(199, 'آب کردن', '<span class=\"hlight\">آب کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) تذویب . گداختن . اذابه . ذوب . مذاب کردن . حل کردن . محلول ساختن . <BR><font color=\"Blue\">◄</font> مجازاً، فروختن چیزی بنهانی . بفروش رسانیدن کالایی کم مشتری و کاسد یا قلب و ناروا.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دل کسی را آب کردن </span> ؛ او را در مطلوب و آرزویی انتظار دادن .<br /></font></div>'),
(200, 'آب کرده', '<span class=\"hlight\">آب کرده .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) محلول : قند آب کرده . <BR><font color=\"Blue\">◄</font> مذاب : قلعی آب کرده .<br /></font></div>'),
(201, 'آب کشیدن', '<span class=\"hlight\">آب کشیدن .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) حمل آب از جایی . <BR><font color=\"Blue\">◄</font> بیرون آوردن آب با دلو و مانند آن از چاه و حوض و جز آن . نَزْح . <BR><font color=\"Blue\">◄</font> تطهیر شرعی و نمازی کردن چیزی متنجس . <BR><font color=\"Blue\">◄</font> شستن جامه ٔ صابون زده با آب خالص تا اثر صابون بشود. <BR><font color=\"Blue\">◄</font> آب کشیدن زخم و جراحتی ؛ ریم و چرک پیداکردن آن بسبب آلوده شدن با آب ناپاک . هو کشیدن . <BR><font color=\"Blue\">◄</font> آب کشیدن غذائی ؛ خورنده را تشنگی آوردن .<br /></font></div>'),
(202, 'آب کشین', '<span class=\"hlight\">آب کشین .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِ) دست برنجن . دست بند.<br /></font></div>'),
(203, 'آب کلان', '<span class=\"hlight\">آب کلان .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) نام شعبه ای از رود گاماسب در نهاوند.<br /></font></div>'),
(204, 'آب کنار', '<span class=\"hlight\">آب کنار.</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (اِخ ) نام ناحیه ای از طالش دولاب گیلان .<br /></font></div>'),
(205, 'آب کندن', '<span class=\"hlight\">آب کندن .</span> <font color=\"DarkGreen\"><b>[ک َ دَ ]</font></b> (مص مرکب ) آب انداختن ماست یا آش سرد و جز آن چون قسمتی از آن را برگرفته باشند. آب انداختن .<br /></font></div>'),
(206, 'آب گذار', '<span class=\"hlight\">آب گذار.</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (اِ مرکب ) معبر آب . آبگذر.<br /></font></div>'),
(207, 'آب گردانی', '<span class=\"hlight\">آب گردانی .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (حامص مرکب ) تغییر دادن آب و هوا از لحاظ صِحّی .<br /></font></div>'),
(208, 'آب گردش', '<span class=\"hlight\">آب گردش .</span> <font color=\"DarkGreen\"><b>[ گ َ دِ ]</font></b> (ص مرکب ) تندرفتار <span class=\"hlight\">:</span> <br />آب گردش مرکبی کز چابکی هنگام تک <br />نعل سخت او ز خاک نرم می گردد غبار.<br /> <font color=\"Red\">ازرقی .</font><br /><BR><font color=\"Blue\">◄</font> (اِ مرکب ) نوبت آب در اصطلاح برزگران .<br /></font></div>'),
(209, 'آب گردنده', '<span class=\"hlight\">آب گردنده .</span> <font color=\"DarkGreen\"><b>[ ب ِ گ َ دَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب وصفی، اِ مرکب ) مجازاً، آسمان <span class=\"hlight\">:</span> <br />پیمبر بر آن ختلی ره نورد<br />برآورد از این آب گردنده گرد.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(210, 'آب گرم', '<span class=\"hlight\">آب گرم .</span> <font color=\"DarkGreen\"><b>[ ب ِ گ َ ]</font></b> (ترکیب وصفی، اِ مرکب ) آب جوشیده و حارّ. حمیم . (دهار). <BR><font color=\"Blue\">◄</font> آب معدنی که بالطبع گرم باشد. حَمّه : آب گرم لاریجان . آب گرم شاهان گرماب . <BR><font color=\"Blue\">◄</font> حمامی که بر این آب سازند مداوای بیماران را.<br /></font></div>'),
(211, 'آب گرم', '<span class=\"hlight\">آب گرم .</span> <font color=\"DarkGreen\"><b>[ ب ِ گ َ ]</font></b> (اِخ ) نام محلی کنار راه قزوین و همدان میان قرخبلاق و نجف آباد، بفاصله ٔ <span class=\"hlight\" dir=\"rtl\">٢٣٦٥٠٠</span> گز از تهران . <BR><font color=\"Blue\">◄</font> نام رودی از روافد رود گرگان .<br /></font></div>'),
(212, 'آب گرگر', '<span class=\"hlight\">آب گرگر.</span> <font color=\"DarkGreen\"><b>[ ب ِ گ َ گ َ ]</font></b> (اِخ ) نهری از کارون نزدیک شوشتر.<br /></font></div>'),
(213, 'آب گشنیز', '<span class=\"hlight\">آب گشنیز.</span> <font color=\"DarkGreen\"><b>[ ب ِ گ ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که از کوفتن برگ و ساق گشنیز حاصل کنند.<br /></font></div>'),
(214, 'آب گل', '<span class=\"hlight\">آب گل .</span> <font color=\"DarkGreen\"><b>[ ب ِ گ ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) گلاب . عطری که از گل سرخ گیرند <span class=\"hlight\">:</span> و از وی <font color=\"DarkGreen\"><b>[ از پارس ]</font></b> آب گل و آب بنفشه ... خیزد. (حدودالعالم ).<br />از آن پس به آب ِ گُل و بوی خوش <br />بشستند دست و نشستند کش .<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(215, 'آب گمه', '<span class=\"hlight\">آب گمه .</span> <font color=\"DarkGreen\"><b>[ گ ُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) ماءالجمة. آبی است خاکستری رنگ و بدبوی و آن را از شکم نوعی ماهی گیرند که در بحر چین است، هر عضوی که بشکند مقدار دو مثقال از آن بخورند چنانکه بدندانها نرسد آن عضو شکسته را درست کند و در دریای هرموز نیز بهم می رسد. (برهان ).<br /></font></div>'),
(216, 'آب گوهر', '<span class=\"hlight\">آب گوهر.</span> <font color=\"DarkGreen\"><b>[ ب ِ گ َ <span class=\"hlight\" dir=\"rtl\">/</span> گُو هََ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب مروارید. آب سپید که در چشم پدید آید.<br /></font></div>'),
(217, 'آب گوگردی', '<span class=\"hlight\">آب گوگردی .</span> <font color=\"DarkGreen\"><b>[ ب ِ گو گ ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) چشمه ٔ گرم طبیعی که در آن گوگرد باشد. در رامسر و سمنان و لارستان فارس و خراسان و دماوند آب گوگردی هست .<br /></font></div>'),
(218, 'آب یخ', '<span class=\"hlight\">آب یخ .</span> <font color=\"DarkGreen\"><b>[ ب ِ ی َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبی که در آن یخ افکنده و سرد کرده باشند.<br /></font></div>'),
(219, 'آب یک', '<span class=\"hlight\">آب یک .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) نام محلی از توابع قزوین، کنار جاده ٔ طهران، میان ینگی امام و قشلاق بفاصله ٔ <span class=\"hlight\" dir=\"rtl\">٦٥٨٠٠</span> گز از طهران . این قریه دارای معادن ذغال سنگ است بدره ٔ کوچکی واقع در شمال غربی بفاصله ٔ <span class=\"hlight\" dir=\"rtl\">٤٠٠٠</span> گز. زغال سنگ آب یک دارای <span class=\"hlight\" dir=\"rtl\">٧٥٠٠</span>کالری حرارت است و بسهولت به کک تبدیل تواند شدن .<br /></font></div>'),
(220, 'آبا', '<span class=\"hlight\">آبا.</span> (از ع، اِ) در تداول فارسی، آباء <span class=\"hlight\">:</span> <br />تا آدم و حوا که شدند اصل تناسل <br />هستی ملک و شاه به اجداد و به آبا.<br /> <font color=\"Red\">مسعودسعد.</font><br />ای خرابات جوی پرآفات <br />پسر خر توئی و خر آبات .<br /><font color=\"Red\">سنائی (حدیقه ).</font><br /></font></div>'),
(221, 'آباء', '<span class=\"hlight\">آباء.</span> (ع اِ) ج ِ اَب . پدران .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آباء علوی </span> ؛ افلاک و ستارگان . سبعه ٔ سیاره .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آباء عنصری </span> ؛ آخشیجان . چارآخشیج . عناصر اربعه . بسائط. چهاراَرکان . امهات . اسطقسات . ارکان اربعه . کیان <span class=\"hlight\">:</span> <br />مر جاه تو و قدر ترا از سر معنی <br />آباء و سطقسات غلامند و پرستار.<br /> <font color=\"Red\">سنائی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آباء یسوعیین </span> ؛ کشیشان پیرو طریقت ایگناس .<br /></font></div>'),
(222, 'آباتر', '<span class=\"hlight\">آباتر.</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) نام محلی است کنار راه رشت به آستارا میان کسما و تارگوراب بفاصله ٔ <span class=\"hlight\" dir=\"rtl\">٥١٤٠٠</span> گز از رشت .<br /></font></div>'),
(223, 'آباد', '<span class=\"hlight\">آباد.</span> (ع اِ) ج ِ ابد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ابدالاَّباد</span> ؛ همیشه .<br /></font></div>'),
(224, 'آباد', '<span class=\"hlight\">آباد.</span> (اِخ ) نام شهری کوچک بر ساحل یمین نهر ناری در بلوچستان . <BR><font color=\"Blue\">◄</font> نام قصبه ٔ کوچکی در سند یعنی درشمال غربی هندوستان . <BR><font color=\"Blue\">◄</font> نام ناحیتی در ناحیه ٔ سبلان کوه نزدیک ارجاق و پیشکین . (نزهةالقلوب ).<br /></font></div>'),
(225, 'آباد', '<span class=\"hlight\">آباد.</span> (ص ) (از پهلوی آپاتان، شاید مرکب از آو + پاته ) عامر. عامره . معمور. معموره . مزروع . آبادان . مسکون . مقابل ویران و ویرانه و بائر و خراب و یباب <span class=\"hlight\">:</span> <br />ز توران زمین تا بسقلاب و روم <br />ندیدند یک مرز آباد و بوم .<br /> <font color=\"Red\">فردوسی .</font><br />یکایک همه نام وکین توختیم <br />همه شهر آباد را سوختیم .<br /> <font color=\"Red\">فردوسی .</font><br />مرا پادشاهی ّ آباد هست <br />همان گنج و مردی و نیروی دست .<br /> <font color=\"Red\">فردوسی .</font><br />زمینی که آباد هرگز نبود<br />بر او بر ندیدند کشت و درود.<br /> <font color=\"Red\">فردوسی .</font><br />به گودرز فرمود پس شهریار<br />که رفتی کمربسته ٔ کارزار<br />نگر تا نَیازی به بیداد دست <br />نگردانی ایوان آباد پست .<br /> <font color=\"Red\">فردوسی .</font><br />به آباد و ویرانه جایی نماند<br />که منشور تیغ مرا برنخواند.<br /> <font color=\"Red\">فردوسی .</font><br />هر آن بوم و بر کان نه آباد بود<br />تبه بود وویران ز بیداد بود<br />درم داد و آباد کردش ز گنج <br />ز داد و ز بخشش نیامد برنج .<br /> <font color=\"Red\">فردوسی .</font><br />هر آنجا که ویران بد آباد کرد<br />دل غمگنان از غم آزاد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />تو دانی که من جان فرزند خویش <br />برو بوم آباد وپیوند خویش <br />بجای سر تو ندارم بچیز<br />گر این چیزها ارجمند است نیز.<br /> <font color=\"Red\">فردوسی .</font><br />تو ازبهرت آن کو شُد آباد داشت <br />بدیگر کس آباد باید گذاشت .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> تندرست . سالم . بی گزند <span class=\"hlight\">:</span> <br />ترا ای برادر تن آباد باد<br />دل شاه ایران بتو شاد باد.<br /> <font color=\"Red\">فردوسی .</font><br />تن شاه محمود آباد باد<br />سرش سبز بادا دلش شاد باد.<br /> <font color=\"Red\">فردوسی .</font><br />اگر کشور آباد داری بداد<br />بمانی تو آباد و از داد شاد.<br /> <font color=\"Red\">فردوسی .</font><br />بدیشان چنین گفت کآباد باد<br />شما را تن و دل پر از دادباد.<br /> <font color=\"Red\">فردوسی .</font><br />نه کیخسرو آباد ماند نه تخت <br />بایران نه بوم و نه شاخ درخت .<br /> <font color=\"Red\">فردوسی .</font><br />همیشه تن آباد با تاج و تخت <br />ز رنج و غم آزاد و پیروز بخت .<br /> <font color=\"Red\">فردوسی .</font><br />مرا گفت بگیر این و بزی خرّم و دلشاد<br />اگر تَنْت خرابست بدین آب کن آباد.<br /> <font color=\"Red\">کسائی .</font><br />جاودان شاد زیاد آن بهمه نیک سزا<br />تنش آباد و خرد پیر و دل و جان برناه .<br /> <font color=\"Red\">فرخی .</font><br />خانه آباد و خانه آبادان ؛ دعا و آفرینی است .<br /> <BR><font color=\"Blue\">◄</font> مرفّه . بساز. بسامان . منظم . مرتب . آراسته . منتسق . توانگر. پُرمایه . تمام سلاح . روا. مجری . برونق <span class=\"hlight\">:</span> <br />سوی هفت خوان رو بتوران نهاد<br />همی رفت با لشکر آباد و شاد.<br /> <font color=\"Red\">فردوسی .</font><br />چو آمَدْش رفتن بتنگی فراز<br />یکی گنج را در گشادند باز<br />چو بگشاد آن گنج آباد را<br />وصی کرد گودرز گشواد را.<br /> <font color=\"Red\">فردوسی .</font><br />همه دانش و گنج آباد هست <br />بزرگی و مردی و نیروی دست .<br /> <font color=\"Red\">فردوسی .</font><br />همیدون سپهدار او شادباد<br />دلش روشن و گنجش آباد باد.<br /> <font color=\"Red\">فردوسی .</font><br />بدو <font color=\"DarkGreen\"><b>[ بدبیر ]</font></b> باشد آباد شهر و سپاه <br />همان زیردستان فریادخواه .<br /> <font color=\"Red\">فردوسی .</font><br />جهان را چو آباد داری بداد<br />بود گنجت آباد و بخت از تو شاد.<br /> <font color=\"Red\">فردوسی .</font><br />ازاین گنج آباد و این خواسته <br />وزین تازی اسبان آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />بهر کار با هر کسی داد کرد<br />سپه را درم داد و آباد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />ز چیزی که دید اندر آن رزمگاه <br />ببخشید پاک آن همه بر سپاه <br />وزآنجایگه رفت ببْهشت گنگ <br />همه لشکر آباد با ساز جنگ .<br /> <font color=\"Red\">فردوسی .</font><br />سپه را درم داد و آباد کرد<br />سر دوده ٔ خویش پرباد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />سپه را همه زال آباد کرد<br />دل سرفرازان بدان شادکرد.<br /> <font color=\"Red\">فردوسی .</font><br />گزیده پس اندرْش فرهاد بود<br />کز او لشکر خسرو آباد بود.<br /> <font color=\"Red\">فردوسی .</font><br />ای بتو آباد عدل عمّر خطاب <br />وی بتو برپای عِلم حیدر کرار.<br /> <font color=\"Red\">فرخی .</font><br />مرا شاد کردی و آباد کردی <br />سرای مرا از فروش و اوانی .<br /> <font color=\"Red\">فرخی .</font><br />آنجا سپاهی جمع کرد از زمین داور و بسلاح آباد کردشان و بفرستاد. (تاریخ سیستان ). <BR><font color=\"Blue\">◄</font> خوش و خوب <span class=\"hlight\">:</span> <br />سوی هفت خوان رو بتوران نهاد<br />همی رفت با لشکر آباد و شاد .<br /> <font color=\"Red\">فردوسی .</font><br />اکنون بیا شاد آمدی خندان و آباد آمدی <br />چون سرو آزاد آمدی میگو بزیر لب صلا.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> آباد شدن ؛ سیر شدن : بچه ها با آن کاسه آش آباد شدند. <BR><font color=\"Blue\">◄</font> آهل . مأهول . بسیارمردم <span class=\"hlight\">:</span> <br />وز آنجایگه لشکر اندرکشید <font color=\"DarkGreen\"><b>[ رستم ]</font></b><br />بیک منزلی بر یکی شهر دید<br />کجا نام آن شهر بیداد بود<br />دژی بود و از مردم آباد بود.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مدر و حضر، مقابل وبر و بدو <span class=\"hlight\">:</span> <br />کنون کُرد از آن تخمه دارد نژاد<br />کز آباد ناید بدل بَرْش یاد.<br /> <font color=\"Red\">فردوسی .</font><br />نگر تا نباشی به آباد شهر<br />ترا در جهان کوه و دشت است بهر.<br /> <font color=\"Red\">فردوسی .</font><br />همه خانه از بیم بگذاشتند<br />دل از بوم آباد برداشتند.<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ که آباد جای <br />ز داد جهاندار باشد بپای .<br /> <font color=\"Red\">فردوسی .</font><br />و آباد، در آخر اسامی قری و قصبات و شهرها آید در ایران و عراق عرب و هندوستان و افغانستان و ترکستان و آسیای صغیر فال نیک را، یا بیان بانی را و در این حال معنی آبادکرده وآبادشده و معموره دهد، چون : اﷲآباد، خرس آباد، خرّم آباد، شاه آباد، شاه جهان آباد، عشرت آباد، عشق آباد، ماه آباد. گاهی بمجاز و استعاره غم آباد و محنت آباد و خراب آباد گویند و از آن، این جهان را خواهند <span class=\"hlight\">:</span> <br />من ملک بودم و فردوس برین جایم بود<br />آدم آورد در این دیر خراب آبادم .<br /><font color=\"Red\">حافظ.</font><br />که ای بلندنظر شاهباز سدره نشین <br />نشیمن تو نه این کنج محنت آباد است .<br /> <font color=\"Red\">حافظ.</font><br />و ناکجاآباد؛ صُقْع واجب . (سهروردی ).<br /> <BR><font color=\"Blue\">◄</font> (اِ) آفرین . احسنت . مرحبا. زه . ویران مباد. شاد باش . خرّم باش . دیر زی <span class=\"hlight\">:</span> <br />آباد بر آن سی ودو دندانک سیمین <br />چون بر درم حوذ زده سیم سماعیل .<br /> <font color=\"Red\">منجیک (از فرهنگ اسدی، خطی ).</font><br />ویران شده دلها بمی آبادان گردد<br />آباد بر آن دست که پرورد رزآباد.<br /> <font color=\"Red\">ابوالمظفر جخج (کذا) (ازفرهنگ اسدی ).</font><br />دل شاه شد زان سخن شادمان <br />سراینده را گفت آباد مان .<br /> <font color=\"Red\">فردوسی .</font><br />قول تو چو بار است و تو پربار درختی <br />آباد درختی که چو خرماست مقالش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آباد بر آن شاه که دارد چو تو مونس <br />آبادبر آن شهرکه دارد چو تو داور.<br /> <font color=\"Red\">معزی .</font><br />آباد بر آن باره ٔ میمون همایون <br />خوش گام چو یحموم و ره انجام چو دلدل .<br /> <font color=\"Red\">عبدالواسع جبلی .</font><br />آباد بر آن کسی که او هست <br />از بندگی زمانه آزاد.<br /> <font color=\"Red\">مجیر بیلقانی .</font><br />آباد بر آنکه جای عشرت <br />در حضرت پادشاه دارد.<br /> <font color=\"Red\">مجیر بیلقانی .</font><br />که آباد بر چون تو شاه دلیر.<br /><font color=\"Red\">نظامی .</font><br />در جلوه ٔ آن عروس دلشاد<br />آباد بر آنکه گوید آباد.<br /> <font color=\"Red\">نظامی .</font><br />دل من جای خرابست و در او گنج غمت <br />باد آباد بر این گنج و بر این ویرانی .<br /> <font color=\"Red\">نجیب الدین جرفاذقانی .</font><br />روز از پی شادی شرابست <br />آباد بر آنکه او خرابست .<br /> <font color=\"Red\">مغربی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِخ ) خانه ٔ کعبه <span class=\"hlight\">:</span> <br />فرستاد پس کردگار از بهشت <br />بدست سروش خجسته سرشت <br />ز یاقوت یک پاره ٔ لعل فام <br />درخشان بدان خان آباد نام <br />مر آن را میان جهان جای کرد<br />پرستشگه خاطرآرای کرد.<br /> <font color=\"Red\">اسدی .</font><br /><BR><font color=\"Blue\">◄</font> نام اوّلین پیغمبر از پیغمبران عجم . (برهان قاطع).<br /></font></div>'),
(226, 'آباد بوم', '<span class=\"hlight\">آباد بوم .</span> (اِ مرکب ) جای آباد <span class=\"hlight\">:</span> <br />یکی شارسان کرد و آباد بوم <br />برآورد بهر اسیران روم .<br /> <font color=\"Red\">فردوسی .</font><br />زتوران و از هند و از چین و روم <br />ز هر کشوری کان بد آباد بوم <br />همی باژ بردند نزدیک شاه <br />برخشنده روز و شبان سیاه .<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمد ز ایران بروم <br />که ویران شد آن مرز آباد بوم ...<br /> <font color=\"Red\">فردوسی .</font><br />گشاده شد آن مرز آباد بوم <br />سواری بدیدند جنگی ز روم .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت از ایدر برو تا به روم <br />میاسای هیچ اندر آباد بوم .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِخ ) در ابیات ذیل نام محلی گمان میرود و شاید ایران مراد باشد:<br />چنین گفت روشندل پارسی <br />که بگذشت سال از برش چارسی <br />که خسرو <font color=\"DarkGreen\"><b>[ پرویز ]</font></b> فرستاد کسها بروم <br />بهند و به چین و به آباد بوم <br />برفتند کاریگران سه هزار<br />ز هر کشوری هرکه بد نامدار.<br /> <font color=\"Red\">فردوسی .</font><br />هم آنگه فرستاد کسها بروم <br />بهند و بچین و به آباد بوم .<br /> <font color=\"Red\">فردوسی .</font><br />هر آنکس که بود اندر آباد بوم <br />رسیدند سرتاسر اکنون بروم .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد پراندیشه زآباد بوم <br />همی رفت هم زین نشان تا بروم .<br /> <font color=\"Red\">فردوسی .</font><br />سپاهی بدو داد تا باژ روم <br />بخواهد سپارد به آباد بوم .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(227, 'آباد جای', '<span class=\"hlight\">آبادجای .</span> (اِ مرکب ) آباد بوم . آبادی <span class=\"hlight\">:</span> <br />بپرسید از آن سرشبان راه شاه <br />کز ایدر کجایابم آرامگاه <br />چنین داد پاسخ که آباد جای <br />نیابی مگر باشدت رهنمای .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(228, 'آباد شدن', '<span class=\"hlight\">آباد شدن .</span> <font color=\"DarkGreen\"><b>[ ش ُ دَ ]</font></b> (مص مرکب ) عمران پذیرفتن .<br /></font></div>'),
(229, 'آباد کردن', '<span class=\"hlight\">آباد کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) عمارت . عمران <span class=\"hlight\">:</span> <br />به گرد اندرش روستاها بساخت <br />چو آباد کردش کهان را نشاخت .<br /> <font color=\"Red\">فردوسی .</font><br />وز آن پس جهان یکسرآباد کرد<br />همه روی گیتی پر از داد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />ز هوشنگ ماند این سده یادگار<br />بسی باد چون او دگر شهریار<br />کز آباد کردن جهان شاد کرد<br />جهانی بنیکی از او یاد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />از آن رفته نام آوران یادکرد<br />بداد و دهش گیتی آباد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />صد خانه اگر بطاعت آباد کنی <br />زآن به نبود که خاطری شاد کنی .<br /><font color=\"Red\">علأالدوله ٔ سمنانی .</font><br /></font></div>'),
(230, 'آبادان', '<span class=\"hlight\">آبادان .</span> (ص مرکب ) مسکون و مأهول . آهل . (زمخشری ) <span class=\"hlight\">:</span> و مزگت جامع این شهر <font color=\"DarkGreen\"><b>[ هری ]</font></b> آبادان تر مزگتها است بمردم از همه خراسان . (حدودالعالم ). <BR><font color=\"Blue\">◄</font> معمور. معموره . عامر. عامره <span class=\"hlight\">:</span> و اندر وی قبیله های بسیاری از خلخ و جایی آبادان . (حدودالعالم ). و جایی بسیارمردم و آبادان و با نعمت بسیار. (حدودالعالم ). و جایی بسیارمردم و آبادان و با نعمت و بازرگانان . (حدودالعالم ). مرعش، جذب دو شهرک است خرم و آبادان . (حدودالعالم ).<br />ویران شده دلها بمی آبادان گردد<br />آباد بر آن دست که پرورد رزآباد.<br /> <font color=\"Red\">ابوالمظفر جخج (؟) (از فرهنگ اسدی ).</font><br />به آب باشد ویران جهان و آبادان .<br /> <font color=\"Red\">مسعودسعد.</font><br />وز تو این باغ نصرت آبادان <br />بشگفتی چو قندهار شود.<br /> <font color=\"Red\">مسعودسعد.</font><br />و این عالم که بپای بود باعتدال برپای بود و بوی آبادان . (نوروزنامه ). و جهان آراسته و آبادان بدو <font color=\"DarkGreen\"><b>[ به آهن ]</font></b> ست . (نوروزنامه ). تا جهانیان بدانند که ما نیز در آبادان کردن جهان و مملکت همچنان راغبیم . (نوروزنامه ). شب و روز در آن اندیشه بودی ... تا آنجا شهری بنا کردندی تا ذکر او در آبادان کردن مملکت در جهان بماندی . (نوروزنامه ). حجاج بهری <font color=\"DarkGreen\"><b>[ از خانه ٔ کعبه را ]</font></b> بمنجنیق بیران کرده بود و چون از ابن الزبیر فارغ شد بهمان اساس اول بازبرد و آبادان کرد. (مجمل التواریخ ). <br />چون کنم خانه ٔ گل آبادان <br />دل من، اینما تکونوا، خوان .<br /> <font color=\"Red\">سنائی .</font><br />ملک ویران و گنج آبادان <br />نبود جز طریق بیدادان .<br /> <font color=\"Red\">سنائی .</font><br />چون نکردی خرابی آبادان <br />بخرابی چه میشوی شادان ؟<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> توانگر. مرفه <span class=\"hlight\">:</span> یعقوب بن لیث آنهمه مال و سلاح برگرفت و سپاه را بدان آبادان کرد. (تاریخ سیستان ). حربی صعب کرد و بسیار کفار کشت و غنائمی بسیار به دست آورد و لشکر آبادان کرد و بسیستان بازآمد. (تاریخ سیستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">قرض، دو خانه آبادان دارد</span> . (جامعالتمثیل )؛ قرض دائن را از فراخ خرجی بازدارد و مدیون را از دست تنگی رهاند.<br /> <span class=\"hlight\">کوشا باشید تا آبادان باشید</span> .<br /><BR><font color=\"Blue\">◄</font> تندرست . فربه . ساز <span class=\"hlight\">:</span> چون یک چندی آنجایگاه ببود <font color=\"DarkGreen\"><b>[ گاو شتربه نام ]</font></b> در خصب و نعمت روزگار گذاشت و فربه و آبادان گشت . (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> خصیب . پرآب وعلف . <BR><font color=\"Blue\">◄</font> مأمون . ایمن <span class=\"hlight\">:</span> جوابی رسید که خلیفه آل بویه رافرمان داد از دار خلافت تا راه حاج آبادان کردند و مانعی نمانده است . (تاریخ بیهقی ).<br /></font></div>'),
(231, 'آبادان', '<span class=\"hlight\">آبادان .</span> (اِخ ) بندری است در مصب شطالعرب موسوم بدماغه ٔ گُسبه . درازای آن <span class=\"hlight\" dir=\"rtl\">٦٤</span> هزار گز و پهنای آن از <span class=\"hlight\" dir=\"rtl\">٣</span> تا <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزار گز، حد شمالی و شرقی آن کارون و بهمشیر <font color=\"DarkGreen\"><b>[ بهمن شیر]</font></b> و حد غربی شطالعرب و جنوبی خلیج فارس . عرض جغرافیائی آن <span class=\"hlight\" dir=\"rtl\">٣١</span> درجه و <span class=\"hlight\" dir=\"rtl\">٢١</span> دقیقه ٔ شمالی و طول جغرافیائی آن <span class=\"hlight\" dir=\"rtl\">٤٨</span> درجه و <span class=\"hlight\" dir=\"rtl\">١٧</span> دقیقه ٔ شرقی، و فاصله ٔ آن تا اهواز <span class=\"hlight\" dir=\"rtl\">١١٥</span> هزار گز است . سابقاً به مناسبت مقبره ٔ منسوب بخضرکه در حوالی بهمشیر است جزیرةالخضر نامیده میشده است . از <span class=\"hlight\" dir=\"rtl\">١٣٢٧</span> هَ . ق . ببعد شرکت نفت جنوب تصفیه خانه ها در شهر آبادان ساخته و نفت را با لوله ها از مسجد سلیمان به این شهر می آورد، و طول لوله ها که میان این دومحل کشیده شده <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> هزار گز است . آبادان اکنون شهر وبندری مهم و یکی از مراکز تجارت ایران است، و در حدود سی هزار سکنه دارد. پلهای متعدد برای بارگیری در آن ساخته شده و همه ساله متجاوز از ششصد کشتی برای حمل نفت به آنجا وارد و از آنجا خارج می شود و هر ماهه چهل الی پنجاه کشتی در این بندر بارگیری می شود. و آبادان را به عربی عبادان گویند. رجوع به عبادان شود.<br /></font></div>'),
(232, 'آبادانی', '<span class=\"hlight\">آبادانی .</span> (حامص مرکب ) عمران . عمارت . (دستوراللغة) <span class=\"hlight\">:</span> آن زمین را که دروست برکت و آبادانی و قاعده های استوار می نهد. (تاریخ بیهقی ). متحیر گشت و گفت آنچه در دنیا برای آبادانی عالم بکار آید... در این آیت بیامده است . (کلیله و دمنه ). و بهیبت و شوکت ایشان آبادانی جهان وتألیف اهواء متعلق باشد. (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> (اِ مرکب ) محل معمور. آبادی . قریه . ده . شهر <span class=\"hlight\">:</span> زاغ روی به آبادانی نهاد. (کلیله و دمنه ).<br />آفتابی که رسد منفعت است <br />بخرابی و به آبادانی .<br /> <font color=\"Red\">انوری .</font><br /> <BR><font color=\"Blue\">◄</font> معموره ٔ ارض . ربع مسکون <span class=\"hlight\">:</span> و این <font color=\"DarkGreen\"><b>[ هندوستان ]</font></b> بزرگترین ناحیت است اندر آبادانی شمال . (حدودالعالم ). و خراسان نزدیک میانه ٔ آبادانی جهان است . (حدودالعالم ). آن مملکت های بزرگ که گرفت <font color=\"DarkGreen\"><b>[ اسکندر مقدونی ]</font></b> ودر آبادانی جهان که بگشت سبیل وی آن است که کسی بهرتماشا بجایها بگذرد. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> سکنه و پیشه وران و نظایر آن که اساس عمران بر آنها است <span class=\"hlight\">:</span> و این مداین شهری بزرگ بود و با آبادانی و آبادانی وی ببغداد بردند. (حدودالعالم ). <BR><font color=\"Blue\">◄</font> (حامص مرکب ) بسیارمردمی <span class=\"hlight\">:</span> و جایهایی اند با خواسته و نعمت و آبادانی . (حدودالعالم ). <BR><font color=\"Blue\">◄</font> مجازاً، رفاه . سعادت . غنا <span class=\"hlight\">:</span> و جز خشنودی و آبادانی خان و مان تو نخواهیم . (تاریخ بخارای نرشخی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آب آبادانی است </span> .<br /> <span class=\"hlight\">آب به آبادانی میرود</span> ؛رود و جوی منتهی بشهر یا دیه میشود.<br /><span class=\"hlight\">نه آب و نه آبادانی نه گلبانگ مسلمانی </span> ؛ مکانی قفر یا بی سکنه .<br /><span class=\"hlight\">هر آنچه بینند در ویرانی، نگویند در آبادانی </span> . (از اسرارالتوحید).<br /></font></div>'),
(233, 'آبادانی', '<span class=\"hlight\">آبادانی .</span> (اِخ ) نام مردی بعرب که بعلم و پرهیزگاری معروف بوده است، منسوب بشهر آبادان .<br /></font></div>'),
(234, 'آبادانیدن', '<span class=\"hlight\">آبادانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ]</font></b> (مص ) آباد کردن . <BR><font color=\"Blue\">◄</font> ستودن . مدح کردن .<br /></font></div>'),
(235, 'آباده', '<span class=\"hlight\">آباده .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) سه محل است در فارس . یکی شهرستان آباده که مشتمل بر هفت بخش یا بلوک است . آباده ٔ اقلید، مرغاب، مرودشت، مایین، رامجرد، بیضاء و ایرج . دیگر مرکز آباده ٔ اقلید و آن شهرکی است در راه اصفهان و شیراز میان جنّت آباد و خان درویش، فاصله ٔ آن تا تهران <span class=\"hlight\" dir=\"rtl\">٦١٧٧٠٠</span> گز و تا شیراز <span class=\"hlight\" dir=\"rtl\">٤٤</span> فرسخ است . پستخانه و تلگرافخانه دارد، جمعیت آن <span class=\"hlight\" dir=\"rtl\">٥٠٠٠</span> تن و منبت کاری و گیوه ٔ آن بخوبی معروف است . دیگر مرکز آباده ٔ طشک و آن قصبه ای است در مشرق شیراز بفاصله ٔ <span class=\"hlight\" dir=\"rtl\">٢٣</span> فرسخ و دارای <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> خانوار.<br /></font></div>'),
(236, 'آبادکرد', '<span class=\"hlight\">آبادکرد.</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (ن مف مرکب ) بناکرده . معموره . آبادکرده . ساخته <span class=\"hlight\">:</span> <br />این نهال نشانده را مشکن <br />مکن آبادکرد خویش خراب .<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(237, 'آبادکوشک', '<span class=\"hlight\">آبادکوشک .</span>(اِخ ) حسن آباد قاشق در سقز کردستان . (فرهنگستان ).<br /></font></div>'),
(238, 'آبادی', '<span class=\"hlight\">آبادی .</span> (حامص ) (از پهلوی آواتی، عمران . سعادت ) عمارت . عمران . برابر ویرانی <span class=\"hlight\">:</span> <br />آبادی میخانه ز ویرانی ماست <br />جمعیت کفر از پریشانی ماست .<br /> <font color=\"Red\">خیام .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) جای آباد و جای معمور. آبادانی، از ده و شهر و امثال آن <span class=\"hlight\">:</span> <br />که جغد آن به که آبادی نبیند.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(239, 'آبادی کاغذ', '<span class=\"hlight\">آبادی کاغذ.</span> <font color=\"DarkGreen\"><b>[ غ َ ]</font></b> (اِ مرکب ) قسمی کاغذ ابریشمین .<br /></font></div>'),
(240, 'آبادیان', '<span class=\"hlight\">آبادیان .</span> (اِخ ) امتان مه آباد را گویند و آن نخستین پیغمبری بوده است که بعجم مبعوث شد و کتاب او را دساتیر خوانند. (برهان ).<br /></font></div>'),
(241, 'آبار', '<span class=\"hlight\">آبار.</span> (ع اِ) ج ِ بئر.<br /></font></div>'),
(242, 'آبار', '<span class=\"hlight\">آبار.</span> (اِ) دفتر حساب و دیوان حساب و آن را آواره و آوارجه نیز گویند و شاید کلمه صورتی از آمار و آماره است .<br /></font></div>'),
(243, 'آبار', '<span class=\"hlight\">آبار.</span> (اِخ ) نام قریه ای به واسط.<br /></font></div>'),
(244, 'آبار', '<span class=\"hlight\">آبار.</span> (اِ) اُسْرُب . سرب . <BR><font color=\"Blue\">◄</font> سرب سوخته . آنُک محرق . رصاص اسود. (قاموس ). سرب سیاه . و طریقه ٔ ساختن آن آن است که سرب را در تابه ای آهنین نهند و کاسه ای که بن آن سوراخ است بر روی تابه واژگون کنند و بدمند تا آنگاه که سرب سوخته گردد و آن در علاج ریشها و بواسیر و سرطان بکار است . و نیز توتیا و اثمد را آبار نام داده اند، چه ماده ٔ عامله ٔ آن سرب سوخته است .<br /></font></div>'),
(245, 'آبار اعراب', '<span class=\"hlight\">آبار اعراب .</span> <font color=\"DarkGreen\"><b>[ رِ اَ ]</font></b> (اِخ )نام شهرستانی به پنج فرسنگی اجفر میان اجفر و فید.<br /></font></div>'),
(246, 'آبارالنحاس', '<span class=\"hlight\">آبارالنحاس .</span> <font color=\"DarkGreen\"><b>[ رُن ْ ن ُ ]</font></b> (اِ مرکب ) نامی است که کیمیاگران قدیم به مغنیسیا داده اند.<br /></font></div>'),
(247, 'آبازه', '<span class=\"hlight\">آبازه .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) نام دیگر ابخازو بنا به ضبط بعض لغویین در زبان ترکی ابخازی است .<br /></font></div>'),
(248, 'آباط', '<span class=\"hlight\">آباط.</span> (ع اِ) ج ِ اِبط.<br /></font></div>'),
(249, 'آبافت', '<span class=\"hlight\">آبافت .</span> (اِ) آبفت .<br /></font></div>'),
(250, 'آباقا', '<span class=\"hlight\">آباقا.</span> (اِخ ) رجوع به اَباقا شود.<br /></font></div>'),
(251, 'آبال', '<span class=\"hlight\">آبال .</span> (ع اِ) ج ِ اِبِل .<br /></font></div>'),
(252, 'آبان', '<span class=\"hlight\">آبان .</span> (اِخ ) نام فرشته ٔ موکل بر آب و تدبیر امور و مصالحی که در ماه آبان و روز آبان واقع شود. <BR><font color=\"Blue\">◄</font> (اِ) ماه هشتم از سال شمسی مطابق برج عقرب و تشرین اول یعنی ماه دوم خزان میان مهر و آذر و آن را آبانماه و اَبان نیز گویند <span class=\"hlight\">:</span> <br />ز میغ و نزم که بد، روز روشن از مه تیر<br />چنان نمود که تاری شب از مه آبان .<br /> <font color=\"Red\">عنصری .</font><br />آب انگور بیاریدکه آبان ماهست <br />وقت منظر شد و وقت نظر خرگاهست <br />دست تابستان از روی زمین کوتاهست .<br /> <font color=\"Red\">منوچهری .</font><br />و آفتاب در این ماه <font color=\"DarkGreen\"><b>[ آبان ]</font></b> در برج عقرب باشد. (نوروزنامه ).<br />گرم خونم چو آب در مرداد<br />سردآهم چو باد در آبان .<br /> <font color=\"Red\">سنائی .</font><br />گرچه درغربت ز بی آبی شکسته خاطرم <br />زآتش خاطر به آبان ضیمران آورده ام .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> نام روز دهم ازماههای فرس و برحسب رسم مطرد که چون نام ماه با روزتطابق کند آن روز را عید گیرند، روز آبان در این ماه یکی از اعیاد دوازده گانه ٔ سال است . و روز آبان را آبان روز و آبانگان نیز گویند <span class=\"hlight\">:</span> <br />آبان روز است و ماه آبان <br />خرم گردان به آب رز جان .<br /> <font color=\"Red\">مسعودسعد.</font><br />و گویند در این روز زَو پادشاه ایران بر افراسیاب پیروزی یافته و او را از ملک خویش برانده است و نیز در این روز پس از پنج یا هفت سال خشکی و قحط باران آمده است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">آبان ماه را بارانکی دیماه رابرفکی، فروردین ماه شب ببار روز ببار</span> ؛ برای خوبی زرع بارانی اندک به آبان و برفی کم به دی و به فروردین باران بسیار باید.<br /></font></div>'),
(253, 'آبانگان', '<span class=\"hlight\">آبانگان .</span> (اِ مرکب ) نام روزآبان در ماه آبان است، و آن روز عید آن ماه باشد.<br /></font></div>'),
(254, 'آبانگاه', '<span class=\"hlight\">آبانگاه .</span>(اِخ ) نام فرشته ٔ موکل بر آب . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) نام روز دهم فروردین ماه، و گویند اگر در این روزباران ببارد آبانگاه مردان است و مردان به آب درآیند و اگر نبارد آبانگاه زنان باشد و زنان در آب شوند و این عمل را بر خود شگون و مبارک دانند. (برهان ).<br /></font></div>'),
(255, 'آبانی', '<span class=\"hlight\">آبانی .</span> (اِخ ) تخلص میرزا نصراﷲ نام طهرانی از متأخرین شعرای ایران .<br /></font></div>'),
(256, 'آبایان', '<span class=\"hlight\">آبایان .</span> (اِخ ) آبایانی . نام کوهی است که گویند ارتفاع آن چهل فرسنگ است .<br /></font></div>'),
(257, 'آبت', '<span class=\"hlight\">آبت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) سخت گرم (روز).<br /></font></div>'),
(258, 'آبتاب', '<span class=\"hlight\">آبتاب .</span> (نف مرکب <span class=\"hlight\" dir=\"rtl\">/</span> ص مرکب ) مشعشع.<br /></font></div>'),
(259, 'آبتین', '<span class=\"hlight\">آبتین .</span> <font color=\"DarkGreen\"><b>[ ب ْ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِخ ) نام پدر فریدون، مصحف آتبین . و صاحب برهان معنی آن را نفس کامل و نیکوکار و صاحب گفتار و کردار نیک و اسعدالسعداء آورده است .<br /></font></div>'),
(260, 'آبج', '<span class=\"hlight\">آبج .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ) نشانه ٔ کمان گروهه . <BR><font color=\"Blue\">◄</font> آلتی در زراعت .<br /></font></div>'),
(261, 'آبجا', '<span class=\"hlight\">آبجا.</span> (اِ مرکب ) آبجامه . آوند آب .<br /></font></div>'),
(262, 'آبجامه', '<span class=\"hlight\">آبجامه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب )جام آبخوری . اناء. (زمخشری ): القحف ؛ آب جامه ٔ چوبین .(قاضی محمد دهار). کاس . جام شراب . تور <span class=\"hlight\">:</span> <br />زمزم لطف آب خامه ٔ اوست <br />کعبه ٔ اهل فضل نامه ٔ اوست .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(263, 'آبجو افشرده', '<span class=\"hlight\">آبجو افشرده .</span> <font color=\"DarkGreen\"><b>[ ب ِ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ُ وِ اَ ش ُ دَ<span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کشک الشعیر. (تحفه ).<br /></font></div>'),
(264, 'آبجی', '<span class=\"hlight\">آبجی .</span> (از ترکی، اِ مرکب ) (از ترکی ِ آغاباجی، مرکب از: آغا، سید و سیده + باجی، خواهر) در تداول خانگی، خواهر.<br /></font></div>'),
(265, 'آبجی', '<span class=\"hlight\">آبجی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص نسبی ) ظاهراً منسوب به آبج معرب آبه (آوه )، و محتمل است که آبج محلی دیگر باشد.<br /></font></div>'),
(266, 'آبجیل', '<span class=\"hlight\">آبجیل .</span> (ص مرکب، اِ مرکب ) در اصطلاح بنایان، گچی نیک ناسرشته که آب آن بیک سو و گچ آن بیک سو باشد.<br /></font></div>'),
(267, 'آبخانه', '<span class=\"hlight\">آبخانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) جایی معلوم برای قضای حاجت . مستراح . مبرز. مخرج .کنیف . مغتسل . متوضا. بیت الفراغ . مبال . خلا. بیت التخلیه . میضاء. مذهب . آبشتنگاه . تشتخانه . ادب خانه . جایی .صحت خانه . قدمگاه . کریاس . بیت الماء. بیت الخلاء. ضروری . کابینه . قدم جا. طهارتخانه . و گاه از آن به بیرون وسرِ آب تعبیر کنند <span class=\"hlight\">:</span> روزی شیخ ابوسعید رحمه اﷲ همی شد با صوفیان، فرا جایی رسید که چاه آبخانه پاک میکردند و نجاست بر راه بود... (کیمیای سعادت ). <BR><font color=\"Blue\">◄</font> در اصطلاح اهل خراسان قسمتی از کاریز باشد که از آن آب تراوش کند و آب قنات از آنجا خیزد.<br /></font></div>'),
(268, 'آبخانی', '<span class=\"hlight\">آبخانی .</span> (اِخ ) نام یکی از آبراهه های کشگان رود.<br /></font></div>'),
(269, 'آبخسب', '<span class=\"hlight\">آبخسب .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (نف مرکب ) ستوری که چون آب بیند در آن بخسبد و این از عیوب اسب و جز آن است .<br /></font></div>'),
(270, 'آبخست', '<span class=\"hlight\">آبخست .</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (اِ مرکب ) جزیره <span class=\"hlight\">:</span> <br />رفت در دریا بتنگی <font color=\"DarkGreen\"><b>[ظ: بیکّی ]</font></b> آبخست <br />راه دور از نزد مردم دوردست .<br /> <font color=\"Red\">بوالمثال (از فرهنگ اسدی پاول هورن ).</font><br /> <br />بردشان باد تند وموج بلند<br />تا بیک آبخستشان افکند.<br /> <font color=\"Red\">عنصری .</font><br />تنی چند از آن موج دریا برست <br />رسیدند نزدیکی آبخست .<br /> <font color=\"Red\">عنصری .</font><br /> <BR><font color=\"Blue\">◄</font> (ن مف مرکب ) آب گز. یعنی میوه ای که قسمتی از آن بگردیده و تباه شده باشد. خایس <span class=\"hlight\">:</span> <br />روی ترکان هست نازیبا و گست <br />زرد و پرچین چون ترنج آبخست .<br /> <font color=\"Red\">علی فرقدی .</font><br />و بهر دو معنی آبخوست نیز آمده است .و صاحب برهان معنی بَدْاَندرون نیز بکلمه داده .<br /></font></div>'),
(271, 'آبخشک کن', '<span class=\"hlight\">آبخشک کن .</span> <font color=\"DarkGreen\"><b>[ خ ُ ک ُن ْ]</font></b> (اِ مرکب ) آبخُشکان . کاغذ پرزدار که بدان مرکب نوشته خشک کنند. نشافه . و آن را آبچین نیز توان گفت .<br /></font></div>'),
(272, 'آبخو', '<span class=\"hlight\">آبخو.</span> (اِ مرکب ) آبخوست . آبخست . جزیره، یا جزیره ای در رودی بزرگ که آب سطح آن را فراگرفته و گیاه و درختان آن ظاهر باشد <span class=\"hlight\">:</span> <br />گویی که هست مردمک دیده آبخو<br />یا خود چو ماهی ای است که دارد در آب خو.<br /><font color=\"Red\">عمعق بخاری .</font><br /></font></div>'),
(273, 'آبخوار', '<span class=\"hlight\">آبخوار.</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) آشامنده ٔ آب <span class=\"hlight\">:</span> <br />تشنه میگوید که کو آب گوار<br />آب میگوید که کو آن آبخوار.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(274, 'آبخواره', '<span class=\"hlight\">آبخواره .</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) ظروف سفالینه که در آن آب یا شراب آشامند. آنچه که در آن آب توان خورد از سبو و جز آن <span class=\"hlight\">:</span> <br />همه آبخواره بینی که ز ما کنندمستی <br />اگر آبخواره سازند ز خاک ما سبویی .<br /> <font color=\"Red\">قاسم انوار.</font><br /><BR><font color=\"Blue\">◄</font> (نف مرکب ) آبخوار.<br /></font></div>'),
(275, 'آبخور', '<span class=\"hlight\">آبخور.</span> <font color=\"DarkGreen\"><b>[ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (اِ مرکب ) محل آب خوردن و آب برداشتن جانور و آدمی از نهر و جز آن . ورد. مورد. منهل . سَقایه . شرعه . شریعه . عطن . مشرب . مشرع . معطن . منزل . آبشخور. آبشخورد. آبخورد <span class=\"hlight\">:</span> <br />سر فروبردم میان آبخور<br />از فرنج مَنْش خشم آمد مگر.<br /> <font color=\"Red\">رودکی .</font><br />وزآن آبخور شد بجای نبرد<br />پراندیشه بودش دل و روی زرد.<br /> <font color=\"Red\">فردوسی .</font><br />گل و آب سیاه تیره همی <br />از چه معنیش آبخور باشد؟<br /> <font color=\"Red\">مسعودسعد.</font><br />پس نشان داد کآن درخت کجاست <br />گفت از آن آبخور که خانی ماست .<br /> <font color=\"Red\">نظامی .</font><br /> <br />نیست در سوراخ کفتار ای پسر<br />رفت تازان او بسوی آبخور.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> روزی . قسمت . نصیب <span class=\"hlight\">:</span> <br />ترسم که برآید ز جهان آبخور من <br />کز شهر برآورد جهان آبخور تو.<br /> <font color=\"Red\">قطران .</font><br />در عیش نقد کوش که چون آبخور نماند<br />آدم بهشت روضه ٔ دارالسلام را.<br /> <font color=\"Red\">حافظ.</font><br />خواست دلم تا که بمسجد شود<br />کابخورش جانب میخانه برد.<br /> <font color=\"Red\">؟ (از فرهنگ جهانگیری ).</font><br /> <BR><font color=\"Blue\">◄</font> ظرفی که بدان آب خورند. سِقایه <span class=\"hlight\">:</span> <br />پیراهنت دریده و استاد درزیی <br />چون کوزه گر ز کنج همی آبخور کنی .<br /> <font color=\"Red\">رشیداعور.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آبخورهای ریشه </span> ؛ آبکش های آن <span class=\"hlight\">:</span> چون بیخ آبخور ندارد نه برگش سبز بماند و نه شاخش تر بماند. (تفسیر ابوالفتوح رازی ).<br /></font></div>'),
(276, 'آبخورد', '<span class=\"hlight\">آبخورد.</span> <font color=\"DarkGreen\"><b>[ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (مص مرکب مرخم، اِمص مرکب ) مخفف آب خوردن <span class=\"hlight\">:</span> <br />درخت ارچه سبزش کند آبخورد<br />شود نیز زافزونی آب زرد.<br /> <font color=\"Red\">امیرخسرو دهلوی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ مرکب ) قسمت . نصیب <span class=\"hlight\">:</span> <br />جان شد این جا چه خاک بیزد تن <br />کابخوردش از این جهان برخاست .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> منهل و مشرب، و مجازاً به معنی مقام و منزل و جایگاه <span class=\"hlight\">:</span> <br />لیکن از یاد تو ما را چاره نیست <br />تا در این خاک است ما را آبخورد.<br /> <font color=\"Red\">سنائی .</font><br />شه عالم آهنج گیتی نورد<br />در آن خاک یک ماه کرد آبخورد.<br /> <font color=\"Red\">نظامی .</font><br />من جرعه نوش بزم تو بودم هزار سال <br />کی ترک آبخورد کند طبع خوگرَم ؟<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(277, 'آبخوردی', '<span class=\"hlight\">آبخوردی .</span> <font color=\"DarkGreen\"><b>[ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (اِ مرکب ) مَرَق . مَرَقه . گوشت آبه . نخوداب .<br /></font></div>'),
(278, 'آبخورش', '<span class=\"hlight\">آبخورش .</span> <font color=\"DarkGreen\"><b>[ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ رِ]</font></b> (اِ مرکب ) در تداول عامه به معنی نصیب و قسمت . <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب خورش کسی از جایی کنده شدن </span> ؛ از آنجای کوچ کردن و رفتن او.<br /></font></div>'),
(279, 'آبخوره', '<span class=\"hlight\">آبخوره .</span> <font color=\"DarkGreen\"><b>[ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) آبگیر. جوی <span class=\"hlight\">:</span> <br />آب چون برد سوی آبخوره <br />چون گسست آب بر بماندخره .<br /><font color=\"Red\">ابوالعباس .</font><br /></font></div>'),
(280, 'آبخوری', '<span class=\"hlight\">آبخوری .</span> <font color=\"DarkGreen\"><b>[ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ ]</font></b> (اِ مرکب ) ظرف آب خوردن . مشربه . آبخواره . آبخور. <BR><font color=\"Blue\">◄</font> شارب (موی سبلت ). <BR><font color=\"Blue\">◄</font> نوعی از دهنه ٔ اسب که هنگام آب دادن بر دهان او زنند.<br /></font></div>'),
(281, 'آبخوست', '<span class=\"hlight\">آبخوست .</span> <font color=\"DarkGreen\"><b>[ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خو ]</font></b> (اِ مرکب ) آبخو. آبخست .<br /></font></div>'),
(282, 'آبد', '<span class=\"hlight\">آبد.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) جاودانه . ج، آبدین . <BR><font color=\"Blue\">◄</font> مرغ مقیم بیک جا، خلاف قاطع. <BR><font color=\"Blue\">◄</font> جانور وحشی .<br /></font></div>'),
(283, 'آبداده', '<span class=\"hlight\">آبداده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span>دِ ]</font></b> (ن مف مرکب ) گوهردار. تیزکرده <span class=\"hlight\">:</span> گفتندپادشاه ما مسعود است هر کس که بی فرمان سلطان ما اینجا آید زوبین آبداده و شمشیر است . (تاریخ بیهقی ).<br />دیو هگرز آبروی من نبرد زآنک <br />روی بدو دارد آبداده سنانم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />پر آب داده حسامم به دست نصرت تو<br />ترا چه حاجت باشدبه آبداده حسام ؟<br /> <font color=\"Red\">مسعودسعد.</font><br />عدل را نوربخش ْ خورشیدی <br />ملک را آبداده پولادی .<br /> <font color=\"Red\">مسعودسعد.</font><br />خنجر آبداده را ماند<br />آن دل بادطبع آهن باس .<br /> <font color=\"Red\">مسعودسعد.</font><br />موی چون تاب خورده زوبینی است <br />مژه چون آبداده پیکانیست .<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(284, 'آبدار', '<span class=\"hlight\">آبدار.</span> (نف مرکب ) شربت دار. ساقی . ایاغچی . و در این زمان خادمی که بکار تهیه ٔ چای و قهوه و غلیان است <span class=\"hlight\">:</span> <br />بیوسف چنین گفت پس آبدار<br />که ای مایه ٔ علم و گنج وقار.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />ز یوسف پذیرفت پس آبدار<br />که گر بازخواند مرا شهریار...<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بپرسید از او پیشتر آبدار<br />که ای چون خرد پاک و پرهیزکار.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />همی بود غمگین دل شهریار<br />قضا را فراز آمد آن آبدار.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />یکی بود خواندار شاه جهان <br />ملک برخرسطوس روشن روان <br />یکی داشتی کار بیت الشراب <br />شراب او برِ شاه بردی و آب <br />قضای خداوند را آبدار<br />شبی دید در خواب خوش آشکار...<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> میوه ٔ پراز شیره ٔ نباتی . طری . شاداب . پرآب . رطب . ریّان <span class=\"hlight\">:</span> <br />همچو انگور آبدار بدی <br />نون شدی چون سکج ز پیری خشک .<br /> <font color=\"Red\">لبیبی .</font><br />بنگر که چو شنبلید گشته ست <br />آن لاله ٔ آبدار و رنگین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بسان پرستاره آسمان گردد سحرگاهان <br />ز سبزه ی ْ آبدار و سرخ گل وز لاله بستانها.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و مجازاً، شعر آبدار؛ فصیح و روان . <BR><font color=\"Blue\">◄</font> و سخنی یا دشنامی آبدار؛ سخت و صعب و پرمعنی در نوع خویش و زننده و نیش دار. <BR><font color=\"Blue\">◄</font> تیغ و خنجرو آهن برنده و جوهردار. حدید. حاد <span class=\"hlight\">:</span> <br />چو با او ندید ایچ جای درنگ <br />همان آبداری که بودش بچنگ <br />بزد بر سر ترگ آن نامدار<br />تو گفتی تنش سر نیاورده بار.<br /> <font color=\"Red\">فردوسی .</font><br />بیک زخم دو دو بیفکند خوار<br />بیک تن بدان آهن آبدار.<br /> <font color=\"Red\">فردوسی .</font><br />بجست از در کاخش اسفندیار<br />بدست اندرون خنجر آبدار.<br /> <font color=\"Red\">فردوسی .</font><br />آتش مرگ جان دشمن تو<br />زخم شمشیر آبدار تو باد.<br /> <font color=\"Red\">مسعودسعد.</font><br />پادشاه کامران آن باشد که ... بضربت شمشیر آبدار خاک از زاد و بود دشمن برآرد. (کلیله و دمنه ).<br />عروس مملکت آن در کنار گیرد تنگ <br />که بوسه بر لب شمشیر آبدار دهد.<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />شمع سحرگهی اگر لاف ز عارض تو زد<br />خصم زبان دراز شد خنجر آبدار کو؟<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> صاحب جاه وجلال <span class=\"hlight\">:</span> <br />ثقةالملک طاهر آنکه چو آب <br />ایزدش آبدار خواهد کرد.<br /> <font color=\"Red\">سنائی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بوسه ٔ آبدار</span> ؛ بوسه ای از روی شوق و گرمی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دندانی آبدار</span> ؛ سخت سپید و رخشان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گوهر آبدار</span> ؛ متلألی و گوهردار<span class=\"hlight\">:</span> <br />سخن بهتر از گوهر آبدار<br />چو بر جایگه بر برندش بکار.<br /> <font color=\"Red\">فردوسی .</font><br />در آرزوی بوس و کنارت مردم <br />وز حسرت لعل آبدارت مردم .<br /> <font color=\"Red\">حافظ.</font><br /><BR><font color=\"Blue\">◄</font> (اِ مرکب ) گیاهی مانندلیف خرما. (برهان ).<br /></font></div>'),
(285, 'آبدارخانه', '<span class=\"hlight\">آبدارخانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) اطاقی که مخصوص تهیه ٔ چای و قهوه و شربت و امثال آن است در خانه های بزرگان . <BR><font color=\"Blue\">◄</font> مجموع آلات و ادوات و خدّام و ستور آبداری در دستگاه سلاطین و حکام .<br /></font></div>'),
(286, 'آبدارو', '<span class=\"hlight\">آبدارو.</span> (اِ مرکب ) زفت رومی . <BR><font color=\"Blue\">◄</font> مومیایی . و محمدبن زکریای رازی دوای دیگری را به این اسم خوانده . (تحفه ).<br /></font></div>'),
(287, 'آبدارک', '<span class=\"hlight\">آبدارک .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ مرکب ) نام مرغکی است که به عربی صعوه گویند. (از ربنجنی ).<br /></font></div>'),
(288, 'آبداری', '<span class=\"hlight\">آبداری .</span> (حامص مرکب ) شغل آبدار <span class=\"hlight\">:</span> <br />سوی آبداری رسید آبدار<br />نکوهیده خواندار برشد بدار.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> طراوت . تازگی . ری ّ <span class=\"hlight\">:</span> <br />بدین آبداری و این راستی <br />زمان تا زمان آیدش کاستی .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> (اِ مرکب ) اسبی یا استری که بر آن اثاث آبدارخانه حمل کنند و نیز خود آن اثاث را آبداری گویند. <BR><font color=\"Blue\">◄</font> نمدی از جنس پست که در سفرها همراه دارند گستردن در منازل را.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(289, 'آبدان', '<span class=\"hlight\">آبدان .</span>(اِ مرکب ) غدیر. ژی . آبگیر. ژیر. آژیر. حوض . آب انبار. شمر. (صحاح الفرس ). کوژی . غفچی . فرغر <span class=\"hlight\">:</span> <br />کافور همچو گل چکد از دوش شاخسار<br />زیبق چو آب برجهد از ناف آبدان .<br /> <font color=\"Red\">(منسوب به رودکی ).</font><br />نه هر کس کو بملک اندر مکین باشد ملک باشد<br />نه نیلوفر بود هر گل که اندر آبدان باشد.<br /> <font color=\"Red\">فرخی .</font><br />آبدان گشت نیلگون دیدار<br />وآسمان گشت نیلگون سیما.<br /> <font color=\"Red\">فرخی .</font><br />بهر سو یکی آبدان چون گلاب <br />شناور شده ماغ بر روی آب .<br /><font color=\"Red\">اسدی (گرشاسبنامه ).</font><br />چو ابر فندق سیمین در آبدان ریزد<br />برآرد از دل فیروزه رنگ سیمین رنگ <br />مشعبدیست که بر خرده مهره های رخام <br />بحقه های بلورین همی کند نیرنگ .<br /> <font color=\"Red\">ازرقی .</font><br />خور چو سکندر گرفت هفت حوالی ّ خاک <br />ریخت ز چارم سپهر آینه در آبدان .<br /> <font color=\"Red\">مجیر بیلقانی .</font><br />فتد تشنه درآبدان عمیق <br />که داند که سیرآب میرد غریق .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> قدح . کاسه . آبخوری . اناء. آب وند. آوند <span class=\"hlight\">:</span> <br />ربود از یهودا سبک جام آب <br />که داند که چون کرد بر وی عتاب <br />مر آن آبدان را بصد پاره کرد<br />بسی شور و پرخاش و پتیاره کرد.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />آب باران خور صدف کردار گاه تشنگی <br />ماهی آسا هیچ آب از آبدان کس مخور.<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> کمیزدان به معنی مثانه . (زمخشری ). <BR><font color=\"Blue\">◄</font> ظرفی که مرغ در آن آب خورد.<br /></font></div>'),
(290, 'آبدان', '<span class=\"hlight\">آبدان .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص مرکب ) مخفف آبادان .<br /></font></div>'),
(291, 'آبدانک', '<span class=\"hlight\">آبدانک .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِ مصغر) مثانه ٔ کوچک . (فرهنگستان پزشکی ).<br /></font></div>'),
(292, 'آبدانی', '<span class=\"hlight\">آبدانی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (حامص مرکب، اِ مرکب ) مخفف آبادانی :<br />شانی ز آبدانی عالم کناره کرد<br />چندانکه در جهان خرابش ندید کس .<br /><font color=\"Red\">شانی .</font><br /></font></div>'),
(293, 'آبدست', '<span class=\"hlight\">آبدست .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ مرکب ) قسمی جامه و پوشش . لباده . جبه ٔ آستین کوتاه . <BR><font color=\"Blue\">◄</font> قسمت فوقانی سرآستین درازتر از قسمت تحتانی آن که بر روی آستین برگردانند زینت را. سنبوسه . <BR><font color=\"Blue\">◄</font> مستراح . مبرز. <BR><font color=\"Blue\">◄</font> (ص مرکب ) سخت چابک و تند. چربدست . ماهر. استاد. رجوع به آبدستی شود. <BR><font color=\"Blue\">◄</font> زاهد پاکدامن و پرهیزکار <span class=\"hlight\">:</span> <br />نعیم پاک بستاند چو کرد آلوده بسپارد<br />نه شرم از آبدست آید نه ننگ از آبدستانش .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(294, 'آبدست جای', '<span class=\"hlight\">آبدست جای .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ مرکب ) متوضا. خلوت خانه .<br /></font></div>'),
(295, 'آبدستان', '<span class=\"hlight\">آبدستان .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ مرکب ) آفتابه ای که بدان دست و روی شویند. ابریق . (مهذب الاسماء). تاموره . مطهره <span class=\"hlight\">:</span> <br />سر فروبرد و آبدستان خواست <br />بازوی شهریار را بربست .<br /> <font color=\"Red\">عسجدی یا سنائی یا عنصری .</font><br />درساعت طشت و آبدستان بیاوردند. (تاریخ برامکه ).<br />آسمان آورده زرین آبدستان زآفتاب <br />پشت خم پیش سران چون آبدستان آمده .<br /> <font color=\"Red\">خاقانی .</font><br />آبدستان در مصراع ثانی این بیت شاید بمعنی ابریق یا خادم و چاکر باشد.<br />من خمش کردم که آمد خوان غیب <br />نک بتان باآبدستان میرسند.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> مشربه .<br /></font></div>'),
(296, 'آبدستاندار', '<span class=\"hlight\">آبدستاندار.</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (نف مرکب ) آفتابه دار.<br /></font></div>'),
(297, 'آبدستدان', '<span class=\"hlight\">آبدستدان .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ مرکب ) آبدستان . رجوع به آبدستان شود.<br /></font></div>'),
(298, 'آبدستی', '<span class=\"hlight\">آبدستی .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (حامص مرکب ) مهارت . چابکی . تندی در کار. لطافت و نازکی در صنعت <span class=\"hlight\">:</span> <br />به نقاشی ز مانی مژده داده <br />به رسامی ز اقلیدس زیاده <br />چنان در لطف بودش آبدستی <br />که بر آب از لطافت نقش بستی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(299, 'آبدن', '<span class=\"hlight\">آبدن .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) نام یکی از قضات بنی اسرائیل .<br /></font></div>'),
(300, 'آبدندان', '<span class=\"hlight\">آبدندان .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ص مرکب، اِ مرکب ) قسمی نار که استخوان و هسته ندارد، و آن را رمان املیسی و رمان املیدی گویند. (از ربنجنی ). <BR><font color=\"Blue\">◄</font> قسمی از امرود <span class=\"hlight\">:</span> <br />میچکد آب حیات از میوه ٔ اشعار من <br />گوییا در بوستان آبدندان بوده ام .<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> نوعی از حلوا و شیرینی ها <span class=\"hlight\">:</span><br />تشنه در آب او نظر میکرد<br />آبدندانی از جگر میخورد.<br /> <font color=\"Red\">نظامی .</font><br />و آن دگر نقل و آبدندانا.<br /> <font color=\"Red\">عبید زاکانی .</font><br /> <BR><font color=\"Blue\">◄</font> گول . ساده لوح . سلیم دل . پپه . پخمه . مفت باز. زبون و مغلوب . (صحاح الفرس ) <span class=\"hlight\">:</span> <br />با عالم بر، قمار میبازم <br />داو سه سه و سه شش همی خوانم <br />وانگه بکشم همه دغای او<br />بنگر چه حریف آبدندانم .<br /> <font color=\"Red\">مسعودسعد.</font><br />گنه بمن بر، دلال وار عرضه دهد<br />بدان سبب که خریدار آبدندانم .<br /> <font color=\"Red\">سوزنی .</font><br />حادثه در نرد درد وفتنه در شطرنج رنج بدسگالت را حریف آبدندان یافته .<br /> <font color=\"Red\">انوری .</font><br />حاسدت با تو اگر نرد عداوت بازد<br />آبدندان تر ازو کس نتوان یافت، بباز.<br /> <font color=\"Red\">انوری .</font><br />خرد رااز سر غیرت قفای خاکپاشان زن <br />هوی را از بن دندان حریف آبدندان شو.<br /> <font color=\"Red\">خاقانی .</font><br /> <br /> <BR><font color=\"Blue\">◄</font> صاحب دندانی رخشان <span class=\"hlight\">:</span> <br />شاهدان آبدندان آمده در کار آب <br />فتنه را از خواب خوش دندان کُنان انگیخته .<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> صاحب برهان به کلمه معنی مضبوط و موافق و شجر و گیاه نیز داده است .<br /></font></div>'),
(301, 'آبدنگ', '<span class=\"hlight\">آبدنگ .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ مرکب ) دنگی که بقوت آب حرکت کند و بدان شلتوک برنج کوبند و از نیشکر آب گیرند.<br /></font></div>'),
(302, 'آبده', '<span class=\"hlight\">آبده .</span> <font color=\"DarkGreen\"><b>[ ب ِ دَ ]</font></b> (ع ص، اِ) چیستان . چربک . سخن غریب . مثل . حکایت . بردک . <BR><font color=\"Blue\">◄</font> آن داهیه که بماند یاد کردن آن همیشه . (ربنجنی ). <BR><font color=\"Blue\">◄</font> جانور وحشی . <BR><font color=\"Blue\">◄</font> مرغ که بر جای ماند و بسردسیر و گرمسیر نشود. <BR><font color=\"Blue\">◄</font> سختی . (ربنجنی ). ج، اوابد.<br /></font></div>'),
(303, 'آبده', '<span class=\"hlight\">آبده .</span> <font color=\"DarkGreen\"><b>[ دِه ْ]</font></b> (اِ مرکب ) چاه اصلی و نخستین یا مادرچاه کاریز.<br /></font></div>'),
(304, 'آبدهان', '<span class=\"hlight\">آبدهان .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ص مرکب ) آنکه سِر نگاه نتواند داشت : آبدهانی است که سخن نگاه نتواند داشت . (نفثةالمصدور، در صفت قلم ).<br /></font></div>'),
(305, 'آبدهانی', '<span class=\"hlight\">آبدهانی .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (حامص مرکب ) صفت آبدهان . صفت آنکه راز نگاه ندارد.<br /></font></div>'),
(306, 'آبدوات کن', '<span class=\"hlight\">آبدوات کن .</span> <font color=\"DarkGreen\"><b>[ دَ ک ُ ]</font></b> (اِ مرکب ) کفچه ٔ خرد و ظریف با دمی باریک و کشیده که بدان آب در دوات کنند و لیقه بدان آشورند. محراک . (ربنجنی ). دویت آشور. دوات آشور.<br /></font></div>'),
(307, 'آبدیده', '<span class=\"hlight\">آبدیده .</span> <font color=\"DarkGreen\"><b>[ دی دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) جامه یا متاعی دیگر که در آب افتاده و بدان زیان رسیده باشد.<br /></font></div>'),
(308, 'آبدیز', '<span class=\"hlight\">آبدیز.</span> (اِخ ) آب دزفول . یکی از روافد رود کارون و آن مهمترین آبراهه ٔ کارونست . این رود از مغرب بروجرد سرچشمه میگیرد، مرکب از دو شعبه ٔ متمایز و دور از یکدیگر شمالی و جنوبی . آبهای ناحیه ٔ بروجرد و علی آباد بشعبه ٔ شمالی ریزد. شعبه ٔ جنوبی از جاپلق و گلپایگان خیزد و از دامنه ٔ قلیان کوه گذرد و در خاک بختیاری بشعبه ٔ شمالی اتصال یافته و در بند قیر به رود کارون پیوندد. محل اتصال دوشعبه ٔ جنوبی و شمالی را بحرین یا میان دوآب نامند.<br /></font></div>'),
(309, 'آبدین', '<span class=\"hlight\">آبدین .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص، اِ) ج ِ آبِد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ابدالاَّبدین </span> ؛ همیشه . رجوع به اَبَد شود.<br /></font></div>'),
(310, 'آبر', '<span class=\"hlight\">آبر.</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) قریه ای از سیستان، و ابوالحسن محمدبن حسین بن ابراهیم بن عاصم آبری از ائمه ٔ حدیث بدانجا منسوب است . (معجم البلدان ).<br /></font></div>'),
(311, 'آبر', '<span class=\"hlight\">آبر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) آنکه تأبیر خرمابن کند. خرماگشن دهنده . (مهذب الاسماء). رجوع بتأبیر شود.<br /></font></div>'),
(312, 'آبرام', '<span class=\"hlight\">آبرام .</span> (اِخ ) رجوع به ابراهیم شود.<br /></font></div>'),
(313, 'آبراهام', '<span class=\"hlight\">آبراهام .</span> (اِخ ) رجوع به ابراهیم شود.<br /></font></div>'),
(314, 'آبرنگ', '<span class=\"hlight\">آبرنگ .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نام شهری از کشمیر برساحل نهر چالنگر در شمال سملان بفاصله ٔ <span class=\"hlight\" dir=\"rtl\">٢٨٨</span> هزار گز.<br /></font></div>'),
(315, 'آبره', '<span class=\"hlight\">آبره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) اَبره . رویه . ظهاره . آوره .<br /></font></div>'),
(316, 'آبرو', '<span class=\"hlight\">آبرو.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِ مرکب ) آبروی . آب روی . جاه . اعتبار.شرف . عِرض . ارج . ناموس . قدر. (ربنجنی ) <span class=\"hlight\">:</span> <br />شو این نامه ٔ خسروی بازگو<br />بدین جوی نزد مهان آبرو.<br /> <font color=\"Red\">فردوسی .</font><br />آبرو میرود ای ابر خطاشوی ببار<br />که بدیوان عمل نامه سیاه آمده ایم .<br /> <font color=\"Red\">حافظ.</font><br />در حفظ آبرو ز گهر باش سخت تر<br />کین آب رفته بازنیاید بجوی خویش .<br /> <font color=\"Red\">صائب .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آبی که آبرو ببرد در گلو مریز</span> .<br />و رجوع به آبروی شود.<br /></font></div>'),
(317, 'آبرو', '<span class=\"hlight\">آبرو.</span> <font color=\"DarkGreen\"><b>[رَ <span class=\"hlight\" dir=\"rtl\">/</span> رُو ]</font></b> (اِ مرکب ) راهی برای گذشتن آب باران و غیر آن . آب راهه . راه آب . <BR><font color=\"Blue\">◄</font> مسیل . (صراح ).<br /></font></div>'),
(318, 'آبرو', '<span class=\"hlight\">آبرو.</span> (اِخ ) تخلص شاه نجم الدین حاکم دهلی، متوفی به <span class=\"hlight\" dir=\"rtl\">١١٦١</span> هَ . ق . <BR><font color=\"Blue\">◄</font> لقب حافظ ابرو.<br /></font></div>'),
(319, 'آبروخواه', '<span class=\"hlight\">آبروخواه .</span> <font color=\"DarkGreen\"><b>[ ب ِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) شریف . آنکه از زوال اعتبار و شرف خویش هراسد.<br /></font></div>'),
(320, 'آبروخواهی', '<span class=\"hlight\">آبروخواهی .</span> <font color=\"DarkGreen\"><b>[ ب ِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (حامص مرکب ) سیرت و صفت آبروخواه .<br /></font></div>'),
(321, 'آبرود', '<span class=\"hlight\">آبرود.</span> (اِ مرکب ) سنبل . <BR><font color=\"Blue\">◄</font> نیلوفر. <BR><font color=\"Blue\">◄</font> (اِخ ) نام دهی به بردسیر کرمان .<br /></font></div>'),
(322, 'آبرودار', '<span class=\"hlight\">آبرودار.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (نف مرکب ) صاحب آبرو. متعفف . بااعتبار. ارجمند و بامناعت .<br /></font></div>'),
(323, 'آبروداری', '<span class=\"hlight\">آبروداری .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (حامص مرکب ) صفت و چگونگی آبرودار.<br /></font></div>'),
(324, 'آبروفت', '<span class=\"hlight\">آبروفت .</span> (ن مف مرکب، اِ مرکب ) آب رفت .<br /></font></div>'),
(325, 'آبرومند', '<span class=\"hlight\">آبرومند.</span> <font color=\"DarkGreen\"><b>[ ب ِ م َ ]</font></b> (ص مرکب ) عفیف . شریف .<br /></font></div>'),
(326, 'آبرومندی', '<span class=\"hlight\">آبرومندی .</span> <font color=\"DarkGreen\"><b>[ ب ِ م َ ]</font></b> (حامص مرکب ) عفت . عفاف . شرف . شرافت .<br /></font></div>'),
(327, 'آبرون', '<span class=\"hlight\">آبرون .</span> (اِ) نوعی از ریاحین که پیوسته سبز بود و برگ آن نیفتد و پای دیوارها و جاهای سایه دار روید و آن را به عربی حی العالم گویند و در طب بکار است و در آذربایجان بسیار باشد. (از برهان ). همیشه جوان . همیشک جوان . بیش بهار. میش بهار. میشا. اذن القاضی . اذن القسیس . بعضی گویند بستان افروز است و خوردن آن با شراب کرمهای دراز معده را برآورد. (از برهان ).<br /></font></div>'),
(328, 'آبروی', '<span class=\"hlight\">آبروی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِ مرکب ) آب روی . آبرو. حرمت . عزّت . شرف . اعتبار. ناموس . جاه . (ربنجنی ). عِرض . ارج . قدر. (ربنجنی ). شأن <span class=\"hlight\">:</span> <br />درِ بی نیازی بشمشیر جوی <br />بکشور بود شاه را آب روی .<br /> <font color=\"Red\">فردوسی .</font><br />اگر راستی تان بود گفتگوی <br />به نزدیک منْتان بود آبروی .<br /> <font color=\"Red\">فردوسی .</font><br />بدانش بود مرد را آبروی <br />ببیدانشی تا توانی مپوی .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت بهرام کاین خود مگوی <br />که از شاه گیرد سپه آبروی .<br /> <font color=\"Red\">فردوسی .</font><br />فروشنده ام هم خریدارجوی <br />فزاید مرا نزد کرم آبروی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آبروی کسی را ریختن و آب روی کسی ریختن و تیره گشتن یا کردن ِ آبروی کسی و شدن ِ آبروی و آبروی کسی را بردن و برباد دادن </span> ؛ خوار و بیمقدار و رسوا شدن و کردن <span class=\"hlight\">:</span> <br />خون خود را گر بریزی بر زمین <br />به که آب روی ریزی بر کنار<br />بت پرسیدن به از مردم پرست <br />پند گیر و کار بند و گوش دار.<br /> <font color=\"Red\">بوسلیک گرگانی .</font><br />به خَرّاد گفت آن زمان شهریار<br />که ای از ردان جهان یادگار<br />بدان کودک تیز و نادان بگوی <br />که ما را کنون تیره گشت آبروی <br />که بدرود بادی تو تا جاودان <br />سر و کار ما باد با بخردان .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت از این سان سخنها مگوی <br />که تیره کنی نزد ما آبروی .<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ که ای خوبروی <br />بتوران سپه شد مرا آبروی .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت رو پارسی را بگوی <br />که ایدر بخیره مریز آبروی .<br /> <font color=\"Red\">فردوسی .</font><br />به گودرز گشواد از من بگوی <br />که از کارگرگین بشد آبروی .<br /> <font color=\"Red\">فردوسی .</font><br />مریز آبروی ای برادر بکوی <br />که دهرت نریزد بشهر آبروی .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> بمعنی دیماس عربی نیز دیده شده است . <BR><font color=\"Blue\">◄</font> اعزاز. اکرام . احترام <span class=\"hlight\">:</span> <br />چنان دان که بی شرم بسیارگوی <br />نبیند بنزد کسی آب روی .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">مخواه آبروی مکاه </span> . (از تاریخ گزیده ).<br /></font></div>'),
(329, 'آبریز', '<span class=\"hlight\">آبریز.</span> (اِخ ) نام محلی کنار راه خاش به چاه ملک میان سامسور و چاه ملک به مسافت <span class=\"hlight\" dir=\"rtl\">١٩٢٦٠٠</span> گز از خاش .<br /></font></div>'),
(330, 'آبریز', '<span class=\"hlight\">آبریز.</span> (اِ مرکب ) دَلو. دول <span class=\"hlight\">:</span> <br />دوستی زآبریز چرخ بِبَر<br />زآنکه آن گه تهی بود گه پر.<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> مبرز. متوضا. مبال <span class=\"hlight\">:</span> <br />شعر تو باید به آبریز درانداخت <br />گر بود از مشک تر نبشته به ابریز.<br /> <font color=\"Red\">سوزنی .</font><br />ببهانه ٔ آبریز بیرون آمد و کاردی کوچک از خدمتکاران خویش بستد. (تاریخ طبرستان ).<br />میان بسته یکسر برای گریز<br />نه مطبخ بجا ماند و نه آبریز.<br /> <font color=\"Red\">زجاجی .</font><br /><BR><font color=\"Blue\">◄</font> چاه . چاه گنداب . بالوعه . بلوعه . گَوی که در آن آبهای مستعمل چون آب ریخته ٔ حمام و آب مطبخ گرد آید. و در بعض فرهنگها به آبریز معنی مزبله نیز داده اند. <BR><font color=\"Blue\">◄</font> ظرفی لوله و دسته دار که بدان وضو و طهارت کنند و معرب آن ابریق است . <BR><font color=\"Blue\">◄</font> سرازیریها که آب آن به رودی رسد. (فرهنگستان زمین شناسی ).<br /></font></div>'),
(331, 'آبریزان', '<span class=\"hlight\">آبریزان .</span> (اِ مرکب ) رجوع به آبریزگان شود.<br /></font></div>'),
(332, 'آبریزش', '<span class=\"hlight\">آبریزش .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِمص مرکب ) قطره قطره فروریختن آب از سقف و چشم و مانند آن .<br /></font></div>'),
(333, 'آبریزه', '<span class=\"hlight\">آبریزه .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ مرکب ) علتی در چشم که پیوسته اشک از آن فروریزد. <BR><font color=\"Blue\">◄</font> مبال . مستراح . آبریز.<br /></font></div>'),
(334, 'آبریزگان', '<span class=\"hlight\">آبریزگان .</span> (اِ مرکب ) نام جشنی است باستانی بسیزدهم تیر یعنی روز تیر از ماه تیر. گویند در زمان فیروز جدّنوشیروان چند سال در ایران قحط و خشکسالی بوده است و شاه و مردم در این روز بدعا باران خواسته اند و باران بیامده است و مردم بشادی آب بر یکدیگر پاشیده اند و این رسم و آن جشن بجای مانده است و در این روز بر یکدیگر آب و گلاب پاشیدندی . آن را آبریزان و آب پاشان و آب تیرگان نیز گویند. <BR><font color=\"Blue\">◄</font> نوعی از طعام .<br /></font></div>'),
(335, 'آبریس', '<span class=\"hlight\">آبریس .</span> (اِ مرکب ) (از: آب + ریس، ریشه ٔ کلمه ٔ ارز و رُز به معنی برنج ) آشام . آشاب . آب چلو.<br /></font></div>'),
(336, 'آبزان', '<span class=\"hlight\">آبزان .</span> (اِخ ) رجوع به ابصان شود.<br /></font></div>'),
(337, 'آبزده', '<span class=\"hlight\">آبزده .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) آب برافشانده . مرشوش . مرشوشه <span class=\"hlight\">:</span> <br />درِ سرای مغان رُفته بود و آب زده <br />نشسته پیر و صلایی بشیخ و شاب زده .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(338, 'آبزرفت', '<span class=\"hlight\">آبزرفت .</span> <font color=\"DarkGreen\"><b>[ زُ رُ ]</font></b> (ص مرکب، اِ مرکب ) آبخست و آبگز از میوه ها <span class=\"hlight\">:</span> <br />چون آب زرفت روی زشتش <br />چندین عفن و ترش چرا شد؟<br /><font color=\"Red\">طرطری .</font><br /></font></div>'),
(339, 'آبزن', '<span class=\"hlight\">آبزن .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِ مرکب ) حوض و خزانه ٔ حمام، مرادف آبشنگ <span class=\"hlight\">:</span> و یجب ازالة ما مکث من الماء فی الابازین لئلایفسد فیضر. (تذکره ٔ داود ضریر انطاکی، در شرایط حمام ). <BR><font color=\"Blue\">◄</font> ظرفی فلزین یا چوبین یا سفالین باندازه ٔ قامت آدمی با سرپوشی سوراخ دار که بیمار را درآن نشانند و سر وی از سوراخ بیرون کنند. و آن دو گونه است، آبزن تر و آبزن خشک . در آبزن تر آب گرم مخلوط به ادویه یا آب ادویه ٔ جوشانیده کنند و در آبزن خشک دواهای خشک ریزند یا بخور کنند و بیمار را در آن بنوعی که مذکور شد بنشانند یا بخوابانند <span class=\"hlight\">:</span> <br />همی خون دام و دد و مرد و زن <br />بریزد کند در یکی آبزن <br />مگر کو سر و تن بشوید بخون <br />شود فال اخترشناسان نگون .<br /> <font color=\"Red\">فردوسی .</font><br /><font color=\"DarkGreen\"><b>[ درِ خانه ]</font></b> بازگشادند بضرورت، آبزنی دید از رخام مانند حوضی و در آنجا مردی پیر همی خوابانیده بر قفا...ابوموسی پرسید از حال وی، گفتند این شخص دانیال پیغامبر است ... در این شهر <font color=\"DarkGreen\"><b>[ شوش ]</font></b> بمرد وی را در این آبزن نهادند، و هر وقت که بباران حاجت افتد بیرون برندش و دعا کنند. (مجمل التواریخ ). و خونهای ایشان در آبزنی ریزند و ملک را ساعتی در آن بنشانند. (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> دوائی که در آبزن کنند. نطولی که مریض را در آن نشانند. (بحرالجواهر) .<br /></font></div>'),
(340, 'آبس', '<span class=\"hlight\">آبس .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) در شرفنامه مسطور است که نام شهری است . (از فرهنگ شعوری ). و ممکن است تصحیف ابسس (صورتی از افسس ) باشد. رجوع به افسس شود.<br /></font></div>'),
(341, 'آبسال', '<span class=\"hlight\">آبسال .</span> (اِ مرکب ) باغ . حدیقه <span class=\"hlight\">:</span> <br />همی تابد ز چرخ سبز عیوق <br />چو آتش بر صحیفه ی ْ آبسالی .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(342, 'آبسالان', '<span class=\"hlight\">آبسالان .</span> (اِ مرکب ) ج ِ آبسال <span class=\"hlight\">:</span> <br />همان شیپور با صد راه نالان <br />بسان بلبل اندر آبسالان .<br /><font color=\"Red\">(ویس و رامین ).</font><br /></font></div>'),
(343, 'آبست', '<span class=\"hlight\">آبست .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b>(اِ) جزو درونی پوست ترنج و بادرنگ و امثال آن، که آن را گوشت پوست و پیه پوست نیز گویند. <BR><font color=\"Blue\">◄</font> (ص ) زمین آماده شده برای زراعت، ظاهراً مخفف آب بسته .<br /></font></div>'),
(344, 'آبست', '<span class=\"hlight\">آبست .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ص ) مخفف آبستن <span class=\"hlight\">:</span> <br />مریمان بی شوی آبست از مسیح <br />خامشان بی لاف و گفتار فصیح .<br /> <font color=\"Red\">مولوی .</font><br />مشتری شو تا بجنبد دست من <br />لعل زاید معدن آبست من .<br /> <font color=\"Red\">مولوی .</font><br />آنچه آبست است شب جز آن نزاد<br />حیله ها و مکرها باد است باد.<br /> <font color=\"Red\">مولوی .</font><br />از یکشبه همخوابی جود تو عجب نیست <br />گر لای سترون شود آبست نعم را.<br /> <font color=\"Red\">معالی بلخی .</font><br /><BR><font color=\"Blue\">◄</font> (اِ) زهدان . رحم .<br /></font></div>'),
(345, 'آبستا', '<span class=\"hlight\">آبستا.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) اَوِستا <span class=\"hlight\">:</span> و پارسیان ازکتاب آبستا که زردشت آورده است . (مجمل التواریخ ).<br />چو اینجا معنی قرآن ندانم <br />روم آنجا که آبستا بخوانم .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(346, 'آبستان', '<span class=\"hlight\">آبستان .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ص ) آبستن <span class=\"hlight\">:</span> <br />بهار تازه آبستان ببار است <br />چو فردوس برین وقت است و هنگام .<br /> <font color=\"Red\">سوزنی (از فرهنگ جهانگیری ).</font><br /> <br /> <BR><font color=\"Blue\">◄</font> (اِ) در این بیت مولوی، آبستان جمع آبست است <span class=\"hlight\">:</span> <br />درد زه گر رنج آبستان بود<br />بر جنین اشکستن زندان بود.<br /></font></div>'),
(347, 'آبستن', '<span class=\"hlight\">آبستن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ ]</font></b> (ص ) هر مادینه از انسان و حیوان که بچه در شکم دارد. حامل . حامله . آبست . بارور. باردار. حُبْلی ̍. (دهار). بارگرفته . حمل برداشته <span class=\"hlight\">:</span> <br />پریچهره آبستن آمد ز مای <br />پسر زاد از این نامور کدخدای .<br /> <font color=\"Red\">فردوسی .</font><br />که ازبهر اوازدرِ بستن است <br />همان نیز بیمار و آبستن است .<br /> <font color=\"Red\">فردوسی .</font><br />گل آبستن از باد مانند مریم <br />هزاران پسر زاده از چارمادر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />بلحسن آن معدن احسان کزو<br />دل بسخن گشته ست آبستنم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای برادر گر عروس خوبت آبستن شده ست <br />اندر آن مدت که بودی غائب از نزد عروس <br />بر عروست بدگمان گشتن نباید بهر آنک <br />ماکیان چون نیک باشد خایه گیرد بی خروس .<br /> <font color=\"Red\">علی شطرنجی .</font><br /> <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آبستن بودن از کسی </span> ؛ مجازاً رشوه ٔ نهانی ستده بودن از او.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آبستنان رفتن </span> ؛ سخت بکاهلی و آهستگی راه پیمودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">شب آبستن است </span> ؛ وقوع حوادث تازه و غیرمنتظر ممکن است <span class=\"hlight\">:</span> <br />ترا خواسته گر ز بهر تن است <br />ببخش و بدان کاین شب آبستن است .<br /> <font color=\"Red\">فردوسی .</font><br />شب بدخواه را عقوبت زاد<br />شب شنودم که باشد آبستن .<br /> <font color=\"Red\">فرخی .</font><br />نبندد در برویم تا دهد در بزم خود جایم <br />نمیدانم چه زاید صبحدم آبستن است امشب .<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />و عرب گوید: اللیل حُبْلی ̍ لست تدری ما تلد.<br />یک امشب را صبوری کرد باید<br />شب آبستن بود تا خود چه زاید.<br /> <font color=\"Red\">نظامی .</font><br />فریب جهان قصه ٔ روشن است <br />سحر تا چه زاید شب آبستن است .<br /> <font color=\"Red\">حافظ.</font><br /> <br /></font></div>'),
(348, 'آبستن شدن', '<span class=\"hlight\">آبستن شدن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َش ُ دَ ]</font></b> (مص مرکب ) آبستن گشتن . آبستن گردیدن . آبستن آمدن . تمخض . حَبَل . (دهار). بار گرفتن . بار برداشتن . حامله گشتن . حمل برداشتن . بچه گرفتن . زه برداشتن . باربردار شدن ماده از نر. <BR><font color=\"Blue\">◄</font> زنده شدن و شکوفه ٔ خرد برآوردن درخت در آخر زمستان و اول بهار.<br /></font></div>'),
(349, 'آبستن کردن', '<span class=\"hlight\">آبستن کردن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ ک َ دَ ]</font></b> (مص مرکب ) احبال . (زوزنی ). القاح .<br /></font></div>'),
(350, 'آبستن گردانیدن', '<span class=\"hlight\">آبستن گردانیدن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ گ َ دَ ]</font></b> (مص مرکب ) آبستن کردن .<br /></font></div>'),
(351, 'آبستن گشتن', '<span class=\"hlight\">آبستن گشتن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ گ َ ت َ ]</font></b> (مص مرکب ) آبستن شدن . رجوع به آبستن شدن شود <span class=\"hlight\">:</span> <br />این بلایه بچگان را ز چه کس آمده زِه <br />همه آبستن گشتند به یک شب کِه ْ و مِه ْ.<br /> <font color=\"Red\">منوچهری .</font><br /><BR><font color=\"Blue\">◄</font> رشوه در خفا ستده بودن .<br /></font></div>'),
(352, 'آبستنگاه', '<span class=\"hlight\">آبستنگاه .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ ]</font></b> (اِ مرکب ) در بعض فرهنگها به معنی آبشتنگاه و خلوت خانه و طهارتخانه و خلاخانه نوشته اند و بیت قریعالدهر را چنانکه برای آبشتنگاه، برای این کلمه نیز شاهد آورده اند.<br /></font></div>'),
(353, 'آبستنی', '<span class=\"hlight\">آبستنی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ ]</font></b> (حامص ) حَبَل . (دهار). حمل . باروری . بار <span class=\"hlight\">:</span> <br />ترا پنج ماهست از آبستنی <br />از این نامور بچه ٔ رستنی .<br /> <font color=\"Red\">فردوسی .</font><br />زآبستنی تهی نشوی هرگز<br />هرچند روزروز همی زایی .<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">آبستنی نهان بود و زادن آشکار</span> .<br /></font></div>'),
(354, 'آبسته', '<span class=\"hlight\">آبسته .</span> <font color=\"DarkGreen\"><b>[ ب َ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص ) آبست . زمین راست کرده برای زراعت .<br /></font></div>'),
(355, 'آبسته', '<span class=\"hlight\">آبسته .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (اِ) آبست . زهدان . رَحِم . <BR><font color=\"Blue\">◄</font> (ص ) آبستن . <BR><font color=\"Blue\">◄</font> متملق و چاپلوس . خوشامدگوی . معانی مذکور در فرهنگها برای این کلمه آمده است و شاهدی برای هیچیک یافته نشد، تنها این کلمه در بیت ذیل دیده میشود <span class=\"hlight\">:</span> <br />نه آرامید دیو دژ برامش <br />همان آبسته خوی خویش کامش <br />جز آنگاهی که کار ویس و رامین <br />بیامیزد بهم چون چرب و شیرین .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />باحتمالی ضعیف آبسته در این بیت چاپلوس و جاسوس و خوشامدگو و شاید به معنی واسطه ٔ بین عاشق و معشوق باشد.<br /></font></div>'),
(356, 'آبسر', '<span class=\"hlight\">آبسر.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) آبسَرد. لرزانک گونه که از آب گوشت یا آب کله پاچه کنند .<br /></font></div>'),
(357, 'آبسرد', '<span class=\"hlight\">آبسرد.</span> <font color=\"DarkGreen\"><b>[ ب ِ س َ ]</font></b> (اِخ ) نام محلی بر کنار راه خرّم آباد به بروجرد میان چغلوندی و بروجرد، و فاصله ٔ آن تا خرم آباد <span class=\"hlight\" dir=\"rtl\">٧٦٠٠</span> گز است .<br /></font></div>'),
(358, 'آبسرد', '<span class=\"hlight\">آبسرد.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) آبسر.<br /></font></div>'),
(359, 'آبسنج', '<span class=\"hlight\">آبسنج .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) آبزن .<br /></font></div>'),
(360, 'آبسنگ', '<span class=\"hlight\">آبسنگ .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) آبزن .<br /></font></div>'),
(361, 'آبسوار', '<span class=\"hlight\">آبسوار.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) حباب، و جمع آن آبسواران است <span class=\"hlight\">:</span> <br />آب که آن خیمه ز باران کند<br />دائره ٔ آبسواران کند.<br /> <font color=\"Red\">امیرخسرو.</font><br />و آن را گنبد آب و کوپله و آبله و به عربی فقاعه و نفاخه نیز گویند.<br /></font></div>'),
(362, 'آبسکن', '<span class=\"hlight\">آبسکن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ک ُ ]</font></b> (اِخ ) شهرکی است بناحیت دیلمان، بر کران دریا، آبادان و جای بازرگانان همه ٔ جهانست که بدریای خزران بازرگانی کنند و از آنجا کیمخته ٔ پشمین و ماهی گوناگون خیزد. (حدودالعالم ). رجوع به آبسکون شود.<br /></font></div>'),
(363, 'آبسکند', '<span class=\"hlight\">آبسکند.</span> <font color=\"DarkGreen\"><b>[ ب ِک َ ]</font></b> (اِخ ) نام قریه ای نزدیک سردارآباد بکردستان .<br /></font></div>'),
(364, 'آبسکون', '<span class=\"hlight\">آبسکون .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نام شهرکی بر ساحل طبرستان که میان او و جرجان سه روزه راه یعنی <span class=\"hlight\" dir=\"rtl\">٢٤</span> فرسنگ است، و آن را اَبسکون نیز گویند، و آن فرضه و بندری است برای توقف کشتیها. (یاقوت ). و گفته اند همین جزیره بود که سلطان محمد خوارزمشاه بدانجا گریخت و هم در آنجا درگذشت، و امروز آن جزیره را آب گرفته است . و دریای خزر و ارقانیا را به مناسبت این جزیره یا آن بندر دریای آبسکون نامند. و نیز گویند رودی بدین نام بوده است که آن را آبگون نیز میگفته اند و در همین موضع بدریا فرومیریخته، اکنون راه آن رود بگردانیده اند. و آسکون نیز صورتی از آبسکون است <span class=\"hlight\">:</span> <br />گرفته روی دریا جمله کشتیهای برّ تو<br />زبهر مدح خوانانت ز شروان تا به آبسکون .<br /> <font color=\"Red\">رودکی .</font><br />تو داری از کنار گنگ تا دریای آبسکون <br />تو داری از در کاکنج تا قصدار و تا مکران .<br /> <font color=\"Red\">فرخی .</font><br />و در شعر آبْسْکون، و نیز بسکون باء و حرکت سین آمده است :<br />چو بحر آبْسکون است چشمها تا شد<br />شریف قالب شهزاده را در آب سکون .<br /> <font color=\"Red\">رضی نیشابوری .</font><br />و رجوع به آبسکن شود.<br /></font></div>'),
(365, 'آبش', '<span class=\"hlight\">آبش .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) آنکه پیرامون و پیشگاه خانه ٔ کسی را بطعام و شراب آراید.<br /></font></div>'),
(366, 'آبش احمدلو', '<span class=\"hlight\">آبش احمدلو.</span> <font color=\"DarkGreen\"><b>[ ب ِ اَ م َ]</font></b> (اِخ ) مرکز بلوک گرمادوز قرجه داغ به آذربایجان .<br /></font></div>'),
(367, 'آبش خاتون', '<span class=\"hlight\">آبش خاتون .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) دختر اتابک سعدبن ابی بکر از سلغریان . او پس از هلاک سلجوقشاه در <span class=\"hlight\" dir=\"rtl\">٦٦٦</span> هَ . ق . پادشاهی فارس یافت و بمیل هلاکو با منکوتیمور ازدواج کرد، و به سال <span class=\"hlight\" dir=\"rtl\">٦٨٥</span> در تبریز درگذشت، و بمرگ او سلسله ٔ سلغریان منقرض گردید.<br /></font></div>'),
(368, 'آبشار', '<span class=\"hlight\">آبشار.</span> (اِ مرکب ) (از: آب، ماء + شار، از شاریدن به معنی فروریختن، سکب ) آب جوی ونهر بزرگ که از بلندی فروریزد. مصب . شَلاّ له . <BR><font color=\"Blue\">◄</font> سنگ مشبک که بر دهانه ٔ ناودانها نصب کنند.<br /></font></div>'),
(369, 'آبشت', '<span class=\"hlight\">آبشت .</span> <font color=\"DarkGreen\"><b>[ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ص ) نهفته . پنهان . <BR><font color=\"Blue\">◄</font> جاسوس .<br /></font></div>'),
(370, 'آبشتن', '<span class=\"hlight\">آبشتن .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ت َ ]</font></b> (مص ) نهفتن . پنهان کردن .<br /></font></div>'),
(371, 'آبشتنگاه', '<span class=\"hlight\">آبشتنگاه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ت َ ]</font></b> (اِ مرکب ) نهفتن گاه . <BR><font color=\"Blue\">◄</font> مبرز. مستراح <span class=\"hlight\">:</span> <br />نه همی بازشناسند عبیر از سرگین <br />نه گلستان بشناسند ز آبشتنگاه .<br /><font color=\"Red\">قریعالدهر (از فرهنگ اسدی، خطی ).</font><br /></font></div>'),
(372, 'آبشتنگه', '<span class=\"hlight\">آبشتنگه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ت َ گ َه ْ ]</font></b> (اِ مرکب ) آبشتنگاه .<br /></font></div>'),
(373, 'آبشتگاه', '<span class=\"hlight\">آبشتگاه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ مرکب ) خلوتخانه . نهانجای . جای نهفتن . <BR><font color=\"Blue\">◄</font> آبخانه . مستراح .<br /></font></div>'),
(374, 'آبشتگه', '<span class=\"hlight\">آبشتگه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ گ َه ْ ]</font></b> (اِ مرکب ) آبشتگاه .<br /></font></div>'),
(375, 'آبشخوار', '<span class=\"hlight\">آبشخوار.</span> <font color=\"DarkGreen\"><b>[ ب ِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (اِ مرکب ) آبشخور: التشریع؛ به آبشخوار آوردن . (زوزنی ).<br /></font></div>'),
(376, 'آبشخور', '<span class=\"hlight\">آبشخور.</span> <font color=\"DarkGreen\"><b>[ ب ِ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (اِ مرکب ) جایی از رود یا نهر یا حوض که از آن آب توان خورد و یا توان برداشت . ورد. مورد. مشرب . منهل . شریعه . مشرع . عَطَن . معطن . مشربه . شرعه . حوض . آبخور. سرچشمه . آبشخوار <span class=\"hlight\">:</span> الملحاح ؛ آن شتر که از آبشخور (عطن . معطن ) واتَر نیاید. (السامی فی الاسامی ).<br />جهان دار محمود شاه بزرگ <br />به آبشخور آرد همی میش و گرگ .<br /> <font color=\"Red\">فردوسی .</font><br />از این پس نه آشوب خیزد نه جنگ <br />به آبشخور آید گوزن و پلنگ .<br /> <font color=\"Red\">فردوسی .</font><br />چرا گاه این گاو بدتر نبود<br />هم آبشخورش نیز کمتر نبود<br />بپستان چنان خشک شد شیر اوی <br />دگرگونه شد رنگ و آژیر اوی .<br /> <font color=\"Red\">فردوسی .</font><br />گیا نیست و آبشخور چارپای <br />فرود آمدن را نیابی تو جای .<br /> <font color=\"Red\">فردوسی .</font><br />همان از دل پاک و پاکیزه کیش <br />به آبشخور آری همی گرگ و میش .<br /> <font color=\"Red\">فردوسی .</font><br /> <br /> <BR><font color=\"Blue\">◄</font> منزل . مقام . موطن <span class=\"hlight\">:</span> <br />ببهرام داد آن زمان دخترش <br />بدان تا بچین باشد آبشخورش .<br /> <font color=\"Red\">فردوسی .</font><br />بتوران زمین زادی از مادرت <br />همانجابد آرام و آبشخورت .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت رستم ترا کهترم <br />بشهر تو کرد ایزد آبشخورم .<br /> <font color=\"Red\">فردوسی .</font><br />دستش نگیرد حیدرم دستم نگیرد عمّرش <br />رفتم پس آبشخورم او از پس آبشخورش .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> نصیب . قسمت . روزی <span class=\"hlight\">:</span> <br />یکی راه بگشای تا بگذرم <br />بجایی که کرد ایزد آبشخورم .<br /> <font color=\"Red\">فردوسی .</font><br />وگر هیچ رنج آیدت بگذرم <br />ز جای دگر جویم آبشخورم .<br /> <font color=\"Red\">فردوسی .</font><br />ما برفتیم تو دانی و دل غمخور ما<br />بخت بد تا بکجا میبرد آبشخور ما.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(377, 'آبشم', '<span class=\"hlight\">آبشم .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِ) خانه ٔ کرم پیله . (شمس اللغات ). در جای دیگر این لغت دیده نشد و نمیدانم مراد از خانه ٔ کرم، تلمبار است یا پیله و بادامه و فیلق . <BR><font color=\"Blue\">◄</font> نوعی ابریشم خشن . لاس .<br /></font></div>'),
(378, 'آبشن', '<span class=\"hlight\">آبشن .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِ) سعتر. آویشن .<br /></font></div>'),
(379, 'آبشن', '<span class=\"hlight\">آبشن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ش َ ]</font></b> (اِ) در بعض فرهنگهاپیراهنی که بر داماد پوشند آمده است .<br /></font></div>'),
(380, 'آبشنگ', '<span class=\"hlight\">آبشنگ .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِ مرکب ) آبزن .<br /></font></div>'),
(381, 'آبشوران', '<span class=\"hlight\">آبشوران .</span> (اِخ ) نام رودی بکرمانشاه . <BR><font color=\"Blue\">◄</font> نام جزیره ای در مغرب بحر خزر.<br /></font></div>'),
(382, 'آبشی', '<span class=\"hlight\">آبشی .</span> (اِ مرکب ) چاهی که در صحن سرای کَنند رفع حوائج کودکان و گرد آمدن فاضل آب را. چاهک .<br /></font></div>'),
(383, 'آبشینه', '<span class=\"hlight\">آبشینه .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) نام محلی کنار راه ملایر بهمدان میان گنجیه و سنگستان بفاصله ٔ <span class=\"hlight\" dir=\"rtl\">٧٧</span> هزار گز از ملایر.<br /></font></div>'),
(384, 'آبفت', '<span class=\"hlight\">آبفت .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b>(اِ) جامه ٔ ستبر و سفته و گنده . آبافت <span class=\"hlight\">:</span> <br />تن همان خاک گران سیه است ارچه <br />شاره وآبفت کنی کرته و شلوارش .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(385, 'آبق', '<span class=\"hlight\">آبق .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (معرب، اِ) معرّب آبَک . زیبق . سیماب .<br /></font></div>'),
(386, 'آبق', '<span class=\"hlight\">آبق .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) گریخته . گریزنده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبدآبق </span> ؛ بنده ٔ گریخته یا گریزپا. ج، اُبَّق، اُبّاق .<br /></font></div>'),
(387, 'آبل', '<span class=\"hlight\">آبل .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) استاد و دانا بچرانیدن شتر.<br /></font></div>'),
(388, 'آبل', '<span class=\"hlight\">آبل .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) نام دیهی بدمشق . <BR><font color=\"Blue\">◄</font> دیهی بحمص . <BR><font color=\"Blue\">◄</font> موضعی نزدیک اردن .<br /></font></div>'),
(389, 'آبل الزیت', '<span class=\"hlight\">آبل الزیت .</span> <font color=\"DarkGreen\"><b>[ ب ِ لُزْ زَ ]</font></b> (اِخ ) نام موضعی نزدیک اردن، و آن را آبل نیز گویند.<br /></font></div>'),
(390, 'آبله', '<span class=\"hlight\">آبله .</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) برآمدگی قسمتی از بشره بعلت سوختگی یا ضرب و زخم و گرد آمدن آب میان بشره و دمه یعنی جلد اصلی . تاوَل . مَجْل . مَجْله . نفط. جدر. بثره . دژک . خجوله . نفاطه <span class=\"hlight\">:</span> <br />یا بکفش اندر بکفت و آبله شد کابلیج <br />از بسی غمها ببسته عمر گل پا را بپا (کذا) .<br /> <font color=\"Red\">عسجدی (از فرهنگ اسدی، چاپی ).</font><br />اگرچه پایت آبله کرده است ... دل تنگ مکن که همین ساعت راه قطع شود. (کتاب المعارف ).<br />هزار آبله بر دل از این یک آبله است <br />که گفت آنکه ز وحدت نخاست بسیاری .<br /> <font color=\"Red\">رفیعالدین ابهری .</font><br /> <BR><font color=\"Blue\">◄</font> تبخال و تبخاله <span class=\"hlight\">:</span> <br />با زبانی پربخار و با لبی پرآبله <br />از چه سوزد گر تب محرق ندارد در بدن ؟<br /> <font color=\"Red\">سلمان ساوجی .</font><br /> <BR><font color=\"Blue\">◄</font> تکمه ٔ پستان . سر پستان <span class=\"hlight\">:</span> <br />نیَم از پرورش مادر گیتی راضی <br />زآنکه خون خورده ام از آبله ٔ پستانش .<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> بیماریی است عفن، ساری و وبائی با تب و بثوری بر ظاهر اندام که منتهی بچرک و ریم شود و گاه مهلک باشد، از اینرو تلقیح اطفال و سالخوردگان نیز بهر چند سال یک بار برای دفع و جلوگیری آن لازم و ضروری است . جدری . نبخ . چیچک . (منتهی الارب ). نفطه . نفاطه . ماهه <span class=\"hlight\">:</span> <br />نُه مه غذای فرزند از خون حیض باشد<br />پس آبله برآرد صورت کند مجدّر<br />نه ماهه خون حیضی چون آبله برآرد<br />سی ساله خون مردم آخر چه آورد بر؟<br /> <font color=\"Red\">خاقانی .</font><br />احمدک را که رخ نمونه بود<br />آبله بردمد چگونه بود؟<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> تیر. تیرک . جوش . یعنی حبابی از بخار که از بن ظرف مایعی جوشان برخاسته و بروی آب آید. <BR><font color=\"Blue\">◄</font> حباب . کوپله . و آب سوار که گاه باران بر حوض و غدیر افتد. <BR><font color=\"Blue\">◄</font> برآمدگی خرد در جامه های ابریشمین و پشمین . <BR><font color=\"Blue\">◄</font> جوش که بر اندام افتد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آبله ٔ رخ فلک </span> ؛ مجازاً، ستاره . چشم شب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">مبارک خوشگل بود آبله هم برآورد</span> .<br /></font></div>'),
(391, 'آبله برآوردن', '<span class=\"hlight\">آبله برآوردن .</span><font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ب َ وَ دَ ]</font></b> (مص مرکب ) انتبار. تنفط.<br /></font></div>'),
(392, 'آبله دار', '<span class=\"hlight\">آبله دار.</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (نف مرکب ) آنکه بر تن جدری دارد. <BR><font color=\"Blue\">◄</font> آنکه بر اندام تاول دارد.<br /></font></div>'),
(393, 'آبله رو', '<span class=\"hlight\">آبله رو.</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ص مرکب ) مجدر <span class=\"hlight\">:</span> سلطان ملکشاه ... آبله رو بود، چهره بزردی مایل . (راحةالصدور راوندی ).<br /></font></div>'),
(394, 'آبله رویی', '<span class=\"hlight\">آبله رویی .</span><font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (حامص مرکب ) صفت و چگونگی آبله رو.<br /></font></div>'),
(395, 'آبله مرغان', '<span class=\"hlight\">آبله مرغان .</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ م ُ ]</font></b> (اِ مرکب ) بیماریی است عفن و ساری مخصوص اطفال و علامت آن بروز دانه های آبداری است در بشره و بیش از چند روز نپاید.<br /></font></div>'),
(396, 'آبله ناک', '<span class=\"hlight\">آبله ناک .</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ص مرکب ) آبله دار.<br /></font></div>'),
(397, 'آبله نشان', '<span class=\"hlight\">آبله نشان .</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ن ِ ]</font></b> (ص مرکب ) آنکه فرورفتگی ها از اثر آبله بر بشره دارد. آبله دار. مجدر: سلطان سنجر گندم گون آبله نشان بود. (راحةالصدور راوندی ).<br /></font></div>'),
(398, 'آبله نشان شدن', '<span class=\"hlight\">آبله نشان شدن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ن ِ ش ُ دَ ]</font></b> (مص مرکب ) نشان آبله و مانند آن بر بشره پیدا آمدن . مجدر شدن .<br /></font></div>'),
(399, 'آبله کردن', '<span class=\"hlight\">آبله کردن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ک َ دَ ]</font></b> (مص مرکب ) آبله برآوردن .<br /></font></div>'),
(400, 'آبله کوب', '<span class=\"hlight\">آبله کوب .</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (نف مرکب ) آنکه تلقیح مایه ٔ آبله کند.<br /></font></div>'),
(401, 'آبله کوبی', '<span class=\"hlight\">آبله کوبی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (حامص مرکب ) تلقیح مایه ٔ آبله .<br /></font></div>'),
(402, 'آبله گون', '<span class=\"hlight\">آبله گون .</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span>ل ِ ]</font></b> (ص مرکب ) چون آبله، و در بیت ذیل <span class=\"hlight\">:</span> <br />دوش که این گِردگَرد گنبد مینا<br />آبله گون شد چو چهر من ز ثریا.<br /> <font color=\"Red\">قاآنی .</font><br />ظاهراً غلط آمده است، چه گون در آخر کلمه چنانکه گونه به معنی رنگ و لون و فام و نیز مانند و شبه و سان و روش می آید و بس و بمعنی دارا و دارنده در جایی دیده نشده است .<br /></font></div>'),
(403, 'آبلوج', '<span class=\"hlight\">آبلوج .</span> (اِ) قند مکرر. (تحفه ). قند سفید. و آن را اَبْلوج نیز گویند و اُبْلوج معرب آن است <span class=\"hlight\">:</span> <br />تا آبلوج همچو تبرزد نشد بطعم <br />تا چون نبات نیست بپیش نظر شکر<br />بادا نهاده در دهن دولتت مقیم <br />دست نشاط و عیش بفتح و ظفر شکر.<br /><font color=\"Red\">پوربهای جامی .</font><br /></font></div>'),
(404, 'آبلیته', '<span class=\"hlight\">آبلیته .</span> <font color=\"DarkGreen\"><b>[ ب ِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b>(اِ) در مجمعالفرس بمعنی زراعت و فلاحت آمده است . (از فرهنگ شعوری ). و در جای دیگر این کلمه دیده نشد.<br /></font></div>'),
(405, 'آبمال واره', '<span class=\"hlight\">آبمال واره .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نام قریه ای و آن مرکز بلوک پایین ولایت مشهد خراسان است .<br /></font></div>'),
(406, 'آبن', '<span class=\"hlight\">آبن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) طعام خشک .<br /></font></div>'),
(407, 'آبناک', '<span class=\"hlight\">آبناک .</span> (ص مرکب ) آب دار. آمیخته به آب : ضیاح، ضیح ؛ شیری آبناک . و زمینی آبناک ؛ زمین که چشمه های بسیار دارد. زمین که آب از آن تراود.<br /></font></div>'),
(408, 'آبنایخ', '<span class=\"hlight\">آبنایخ .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) لقب قطلغبن پهلوان، از امرای دولت سلجوقیه . و او در زمان خوارزمشاه امیرالامراء و در حمله ٔ مغول امیر بخارا بوده است، پس از استیلای مغول بر بخارا بخراسان و از آنجا به ری رفت و بپسر خوارزمشاه تیرشاه التجا برد و تا پایان زندگی بدانجا بود.<br /></font></div>'),
(409, 'آبندون', '<span class=\"hlight\">آبندون .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نام قریه ای بجرجان . مسقطالرأس ابوبکر احمدبن محمدبن علی جرجانی آبدونی .<br /></font></div>'),
(410, 'آبنوس', '<span class=\"hlight\">آبنوس .</span> (اِ) (از یونانی ابنس و یا عبری هابن و یا آرامی آب نوسا) چوبی سیاه رنگ و سخت و سنگین و گرانبها از درختی به همین نام . و آن درخت شبیه بعناب است و ثمر آن مانندانگور زرد و باحلاوت، برگش چون برگ صنوبر و عریض تر از آن و خزان نمی کند و تخمش مانند تخم حنا. قسم هندی با خطوط سفید و قسم حبشی سیاه و صلب و املس . شیز. (ربنجنی ). شیزی ̍. شیزی، قسمی از آن تیره تر باشد و آن را آبنوس سیاه و ساسم خوانند. (زمخشری ). و این قسم چون املس بود اجود اقسام آبنوس است . و قسمی روشن تر که آن را آبنوس سپید، آبنوس پیسه، ملمع و ملمعه گویند. چغ. ساج . (از زمخشری ). رجوع به ساج شود <span class=\"hlight\">:</span> <br />ز آبنوس دری اندر او فراشته بود<br />بجای آهن، سیمین همه بش و مسمار.<br /> <font color=\"Red\">ابوالمؤید بلخی .</font><br />بینی آن زلفینکان چون چنبر بالابخم <br />گر بلخج اندرزنی اکنون شود چون آبنوس (کذا).<br /> <font color=\"Red\">طیان (از فرهنگ اسدی، خطی ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">پرده ٔ آبنوس </span> ؛ کنایه از شب است <span class=\"hlight\">:</span> <br />پدید آمد آن پرده ٔ آبنوس <br />برآسود گیتی ز آوای کوس .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چون آبنوس </span> ؛ تیره . تار. اغبر. سیاه <span class=\"hlight\">:</span> <br />سپاهی که شد دشت چون آبنوس <br />بدرّید گوش پلنگان ز کوس .<br /><font color=\"Red\">فردوسی .</font><br />تبیره برآمد ز درگاه طوس <br />زمین کوه تا کوه گشت آبنوس .<br /> <font color=\"Red\">فردوسی .</font><br />ز جوش سواران زرین کمر<br />ز بس تَرک زرین و زرین سپر<br />برآمد یکی ابر چون سندروس <br />زمین گشت از گرد چون آبنوس .<br /> <font color=\"Red\">فردوسی .</font><br />جهان پر شد از ناله ٔ بوق و کوس <br />زمین آهنین شد سپهر آبنوس .<br /> <font color=\"Red\">فردوسی .</font><br />ز گردش هوا گشت چون سندروس <br />زمین سربسر تیره چون آبنوس .<br /> <font color=\"Red\">فردوسی .</font><br />چو زال آگهی یافت بربست کوس <br />ز لشکر زمین گشت چون آبنوس .<br /> <font color=\"Red\">فردوسی .</font><br />مکن ایمنی در سرای فسوس <br />که گه سندروس است و گه آبنوس .<br /> <font color=\"Red\">فردوسی .</font><br />دریده درفش و نگون گشته کوس <br />رخ نامداران شده آبنوس .<br /> <font color=\"Red\">فردوسی .</font><br />برآمد ز درگاه بهرام کوس <br />رخ شید از گرد شد آبنوس .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(411, 'آبنوسی', '<span class=\"hlight\">آبنوسی .</span> (ص نسبی ) از آبنوس . برنگ آبنوس . سیاه . تیره . اغبر. و آبنوسی شاخ را بمعنی سورنای و شهنای آورده اند <span class=\"hlight\">:</span> <br />آن آبنوسی شاخ بین مار شکم سوراخ بین <br />افسونگر گستاخ بین لب بر لب یار آمده .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(412, 'آبه', '<span class=\"hlight\">آبه .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نام قریه ای نزدیک ساوه و نسبت بدان آبی است و آن را آوه نیز گویند و نسبت بدان آوی باشد. <BR><font color=\"Blue\">◄</font> نام قریه ای به اصفهان . <BR><font color=\"Blue\">◄</font> نام شهری به افریقیه .<br /></font></div>'),
(413, 'آبه', '<span class=\"hlight\">آبه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) لیزابه و لعابی که با جنین توأم برآید از شکم مادر. سخد. شاهد. نخط.<br /></font></div>'),
(414, 'آبه', '<span class=\"hlight\">آبه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) در نوشابه و شورآبه و دوآبه، آب .<br /></font></div>'),
(415, 'آبه', '<span class=\"hlight\">آبه .</span> <font color=\"DarkGreen\"><b>[ آب ْ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) در زبان کودکان خُرد، آب .<br /></font></div>'),
(416, 'آبه صوفیان', '<span class=\"hlight\">آبه صوفیان .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نام محلی کنار راه بجنورد بگنبد قابوس به فاصله ٔ <span class=\"hlight\" dir=\"rtl\">٥٤٨٤٣٠</span> گز از مشهد.<br /></font></div>'),
(417, 'آبهی', '<span class=\"hlight\">آبهی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) نام رود آمو یعنی جیحون <span class=\"hlight\">:</span> <br />همان گاه نزدیک دریا رسید<br />یکی ژرف دریای بن ناپدید<br />به وَستا درون نام او آبهی <br />که قعرش نبوده ست هرگز تهی .<br /><font color=\"Red\">زراتشت بهرام .</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(418, 'آبو', '<span class=\"hlight\">آبو.</span> (اِ) نیلوفر آبی . نیلوپر. لیلوپر <span class=\"hlight\">:</span> <br />صنعش بسر کوه برویانده شقایق <br />در باغ دمانده لَطَفش سوری و آبو.<br /> <font color=\"Red\">خواجه عمید لوبکی .</font><br />ای گرد درت آب رخ خواجه ٔ کاریز<br />وی خاک کف پای تو تاج سر آبو.<br /> <font color=\"Red\">شیخ آذری .</font><br /><BR><font color=\"Blue\">◄</font> خال . دایی . برادر مادر. خالو. مربرار.<br /></font></div>'),
(419, 'آبوباسر', '<span class=\"hlight\">آبوباسر.</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) تصحیف نام ابوبکربن طفیل نزد اروپائیان . رجوع به ابن طفیل شود.<br /></font></div>'),
(420, 'آبوند', '<span class=\"hlight\">آبوند.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ مرکب ) ظرف آب، و ظاهراً آوند مخفف این کلمه است .<br /></font></div>'),
(421, 'آبونمان', '<span class=\"hlight\">آبونمان .</span> (فرانسوی، اِ) نقدی که در ازاء خریدن ماهیانه یا سالیانه ٔ روزنامه و مانند آن پردازند.<br /></font></div>'),
(422, 'آبونه', '<span class=\"hlight\">آبونه .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (فرانسوی، ص، اِ) آبونه شدن روزنامه و مانند آن ؛ از خریداران ماهیانه یا سالیانه ٔ آن گردیدن .<br /></font></div>'),
(423, 'آبچ', '<span class=\"hlight\">آبچ .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ) آبج .<br /></font></div>'),
(424, 'آبژ', '<span class=\"hlight\">آبژ.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِ)سرشک آتش . <BR><font color=\"Blue\">◄</font> نام گیاهی که آن را بومادران گویند. (شمس اللغات ). و رجوع به آبید و آبیز شود.<br /></font></div>'),
(425, 'آبک', '<span class=\"hlight\">آبک .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ <span class=\"hlight\" dir=\"rtl\">/</span> ب ُ ]</font></b> (اِ) آبله . جدری .<br /></font></div>'),
(426, 'آبک', '<span class=\"hlight\">آبک .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ع صوت ) وَیْلَک . هلاک باد ترا.<br /></font></div>'),
(427, 'آبک', '<span class=\"hlight\">آبک .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ مرکب ) جیوه . سیماب .آبَق . زیبق، باصطلاح کیمیاگران . (تحفه ) <span class=\"hlight\">:</span> <br />مِس ّ وجود من شود از می بسان زر<br />گویی که می چو آبک از اجزای کیمیاست .<br /><font color=\"Red\">خجسته .</font><br /></font></div>'),
(428, 'آبک', '<span class=\"hlight\">آبک .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (ص ) هر چیز پرآب . (از برهان ).<br /></font></div>'),
(429, 'آبک', '<span class=\"hlight\">آبک .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نام جائی است .<br /></font></div>'),
(430, 'آبکار', '<span class=\"hlight\">آبکار.</span> (ص مرکب ) سقاء. آبکش <span class=\"hlight\">:</span> <br />در تتق بارگهش گاه بار<br />مائده کش عیسی و خضر آبکار.<br /> <font color=\"Red\">امیرخسرو.</font><br />ابر را گفتم که چندین دور امساکت ببود<br />گفت کزبهر رکاب شه بدم در انتظار<br />کآن زمان کآید شه عالم بدارالملک خویش <br />گوهر خود را کنم در راه میمونش نثار<br />تا درافشانی من در شهر هر کو بنگرد<br />دست شه خواند مرا باری نه ابر آبکار.<br /> <font color=\"Red\">امیرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> آبیار کشت و زرع . <BR><font color=\"Blue\">◄</font> شرابخوار. و رجوع به کارآب شود. <BR><font color=\"Blue\">◄</font> آنکه فلزات را آب دهد. <BR><font color=\"Blue\">◄</font> میفروش . باده فروش . شیره کش <span class=\"hlight\">:</span> <br />بانگ آمد از قنینه کآباد بر خرابی <br />هان آبکار عشرت گر مرد کار آبی .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ مرکب ) کاریزکنی . تنقیه ٔ قنات . لای روبی . لاروبی <span class=\"hlight\">:</span><br />دربن چاه بلا افتاده هم بر آب کار<br />هرکه در کوی تو یک بار از سر جاه آمده .<br /><font color=\"Red\">اثیر اخسیکتی .</font><br /></font></div>'),
(431, 'آبکاری', '<span class=\"hlight\">آبکاری .</span> (ص نسبی ) منسوب به آبکار. <BR><font color=\"Blue\">◄</font> (حامص مرکب ) شغل و عمل آبکار. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) دکان آبکار.<br /></font></div>'),
(432, 'آبکامه', '<span class=\"hlight\">آبکامه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) نان خورشی و نوعی از گوارشن بوده است بطعم ترش، وآن را از نان خشک گندم یا جو که در آب خیسانده و مدتی برای تخمیر در آفتاب مینهاده اند حاصل کنند، و گاهی پودنه و تخم کرفس و دارچینی و قرنفل و ابازیر دیگربر آن می افزایند. و یک قسم آن را از ماست و شیر و تخم سپند و خمیر خشک و سرکه میکرده اند، و آبکامه را برای تجارت از شهری بشهری نیز میبرده اند. مُری . کامه .کومه . و معرب آن کامَخ <span class=\"hlight\">:</span> و از وی <font color=\"DarkGreen\"><b>[ از مرو]</font></b> پنبه ٔ نیک و اشترغاز و فلاته و سرکه و آبکامه و جامه های قزین و ملحم خیزد. (حدودالعالم ). گاوپای گفت خواجه را لذت آبکامه دامن گیر شده، کنیزک را گفت از همسایه آبکامه بخواه، کنیزک بخانه ٔ همسایه رفت و گفت خواجه ٔ من میفرماید که این سُکره را آبکامه پر کن، همسایه گفت نمانده است . (روضةالعقول ). و ترتیب سرای توو لذت ریچار تو معلوم، مگر خواجه ٔ من بنده ٔ تو از آبکامه ٔ شما خورده است . (روضةالعقول ). آن کنیزک دیگر تای نان سپید باضافت کامه برد و گفت هرگاه که آبکامه بایست باشد بی اعلام خاتون مرا بگوی تا به اسعاف رسانم، کنیزک با نان و کامه در خدمت خواجه رفت . (روضةالعقول ). <BR><font color=\"Blue\">◄</font> آش و یخنی ترش . <BR><font color=\"Blue\">◄</font> آش ترخانه . آش بازرگان . <BR><font color=\"Blue\">◄</font> گوارشن . هاضوم .<br /></font></div>'),
(433, 'آبکانه', '<span class=\"hlight\">آبکانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص، اِ) بچه ٔ آدمی یا حیوان که سقط شود. جِهض . جهیض . مجهض . ملیص . زلیق . ملیط. مُملص . آفکانه . افکانه . فکانه . آپکانه . بچه ٔ از بار رفته .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آبکانه کردن </span> ؛ سقط کردن .<br /></font></div>'),
(434, 'آبکش', '<span class=\"hlight\">آبکش .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب، اِمرکب ) سقاء. کشنده ٔ آب از چاه . مستخلف <span class=\"hlight\">:</span> <br />بدین چاه در آب سرداست و خوش <br />بفرمای تا من بُوَم آبکش .<br /> <font color=\"Red\">فردوسی .</font><br />برهنه سر و پای و دوش آبکش <br />پدر شادمان روز و شب خفته خوش .<br /> <font color=\"Red\">فردوسی .</font><br />هم از پیش آن کس که با بوی خوش <br />همی رفت با مشک صد آبکش .<br /> <font color=\"Red\">فردوسی .</font><br />سقائی است این لنبک آبکش <br />بخوبی ّ گفتار وکردار خوش .<br /> <font color=\"Red\">فردوسی .</font><br />به آزادگی لنبک آبکش <br />جوانمرد و با خوان و گفتار خوش .<br /> <font color=\"Red\">فردوسی .</font><br />من از بیم آن نامور شهریار<br />چنین آبکش گشتم و پیشکار.<br /> <font color=\"Red\">فردوسی .</font><br />غلام آبکش باید و خشت زن <br />بود بنده ٔ نازنین مشت زن .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> ظرفی مسین یا چوبین با سوراخ بسیار که آب برنج جوشانیده را با آن گیرند. چلوصافی . چلوپالا. سماق پالا. پالاوَن . ترشی پالا. پالاوان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آبکش </span> ؛ یعنی بسیارسوراخ، و بیشتر این تشبیه را در سقفی که آب از آن فروچکد آرند.<br /> <BR><font color=\"Blue\">◄</font> در اصطلاح مُقنیان آن طبقه ای از زمین سست که فرودِ زمین دِج و رست باشد و در چاه و کاریز کندن چون بدانجا رسند عادةً بیش حفر نکنند. <BR><font color=\"Blue\">◄</font> عِرْق و رگ برگها. «لوله هائی در گیاه که دارای سوراخهای ذره بینی بسیار و در میان آنها صفحه هائی مانند غربال است ». (فرهنگستان طبی ) <span class=\"hlight\">:</span> <br />گر گوش تو آهنگ شناس است در این باغ <br />هر آبکش برگ گلی رشته ٔ سازی است .<br /> <font color=\"Red\">صالح یزدی .</font><br /><BR><font color=\"Blue\">◄</font> طعامی که تشنگی آرد.<br /></font></div>'),
(435, 'آبکشی', '<span class=\"hlight\">آبکشی .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (حامص مرکب ) شغل و عمل آبکش <span class=\"hlight\">:</span> دو ترکمان از خیل او بیامدند و مدتها بر آن قلعه آبکشی کردند. (راحةالصدور راوندی ).<br /></font></div>'),
(436, 'آبکشی کردن', '<span class=\"hlight\">آبکشی کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ک َ دَ ]</font></b> (مص مرکب ) سقائی . کشیدن آب از چاه و مانند آن . <BR><font color=\"Blue\">◄</font> شستن و تطهیر شرعی تن در حمّام . تطهیر جامه پس از شستن با صابون .<br /></font></div>'),
(437, 'آبکم', '<span class=\"hlight\">آبکم .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِ) نوعی از مار.<br /></font></div>'),
(438, 'آبکند', '<span class=\"hlight\">آبکند.</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِ مرکب ) جایی که رود یا سیل و جز آن برده و گود کرده باشد بدرازا. جرف <span class=\"hlight\">:</span> <br />دلش نگیرد از این کوه و دشت و بیشه و رود<br />سرش نپیچد از این آبکند و لوره و جر.<br /> <font color=\"Red\">عنصری .</font><br /> <BR><font color=\"Blue\">◄</font> آبگیر. غدیر. ژی . شمر. غفچی <span class=\"hlight\">:</span> <br />هرکه باشد تشنه و چشمه نیابد هیچ جای <br />بی گمان راضی بباشد گر بیابد آبکند.<br /> <font color=\"Red\">شهید بلخی .</font><br /> <BR><font color=\"Blue\">◄</font> گو. مغاک <span class=\"hlight\">:</span> <br />آبکندی دور و بس تاریک جای <br />لغزلغزان چون درو بنهند پای .<br /> <font color=\"Red\">رودکی .</font><br /><BR><font color=\"Blue\">◄</font> (اِخ ) نام شهری و مدینه ای . (برهان ).<br /></font></div>'),
(439, 'آبکور', '<span class=\"hlight\">آبکور.</span> (ص مرکب ) نمک ناشناس . نانکور <span class=\"hlight\">:</span> <br />نان کور و آب کورم خوانده ای .<br /> <font color=\"Red\">مولوی .</font><br />ناقه ٔ صالح به صورت بُد شتر<br />پی بریدندش ز جهل آن قوم ِ مُر<br />ازبرای آب جو خصمش شدند<br />آب کور و نان ثبور ایشان بدند.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> فاقد آب .<br /></font></div>'),
(440, 'آبکوه', '<span class=\"hlight\">آبکوه .</span> (اِخ ) نام قریه ای است در اطراف مشهد رضا.<br /></font></div>'),
(441, 'آبکوهه', '<span class=\"hlight\">آبکوهه .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (اِ مرکب ) موج . کوهه . نره ٔ آب . آبخیز.<br /></font></div>'),
(442, 'آبکوپیل', '<span class=\"hlight\">آبکوپیل .</span> (اِ مرکب ) قسمی از مرغابی و آن در بحر خزر و خاصه مرداب انزلی بسیار باشد و نام دیگر آن پاریلاست .<br /></font></div>'),
(443, 'آبکی', '<span class=\"hlight\">آبکی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص نسبی ) در تداول عامه، رقیق . تنک . گشاده . <BR><font color=\"Blue\">◄</font> مایع و روان . مقابل جامد.<br /></font></div>'),
(444, 'آبگار', '<span class=\"hlight\">آبگار.</span> (اِخ ) نام هشت تن از پادشاهان آذاسا، از <span class=\"hlight\" dir=\"rtl\">١٣٢</span> ق . م . تا <span class=\"hlight\" dir=\"rtl\">٢١٦</span> م . رجوع به عبقر شود.<br /></font></div>'),
(445, 'آبگاه', '<span class=\"hlight\">آبگاه .</span> (اِ مرکب ) ورد. مورد. (زمخشری ). منهل . مصنعه . تالاب . استخر. آبخور. <BR><font color=\"Blue\">◄</font> مثانه . <BR><font color=\"Blue\">◄</font> تهیگاه . زیر اضلاع از دو سوی وحشی تن آدمی و دیگر جانوران . خاصره .<br /></font></div>'),
(446, 'آبگذر', '<span class=\"hlight\">آبگذر.</span> <font color=\"DarkGreen\"><b>[ گ ُ ذَ ]</font></b> (اِ مرکب ) معبر آب . آبگذار.<br /></font></div>'),
(447, 'آبگرد', '<span class=\"hlight\">آبگرد.</span> <font color=\"DarkGreen\"><b>[ گ ِ ]</font></b> (اِ مرکب ) گرداب <span class=\"hlight\">:</span> <br />مگرد گرد آبگرد هیبتش <br />که درکشد ترا بدم چو اژدها.<br /><font color=\"Red\">ابوالفرج رونی .</font><br /></font></div>'),
(448, 'آبگردان', '<span class=\"hlight\">آبگردان .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b>(اِ مرکب ) چم فلزین . ملعقه ٔ کلان باندازه ٔ باطیه ٔ دسته دار که بدان از دیگ های بزرگ آب و جز آن برگیرند.<br /></font></div>'),
(449, 'آبگز', '<span class=\"hlight\">آبگز.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (ن مف مرکب ) آبخست . آبزُرُفْت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آبگز شدن </span> ؛ تباه شدن قسمتی از میوه .<BR>۩ ترنجیده شدن پوست تن آدمی بسبب آب، چنانکه کارگران حمّام را.<br /></font></div>'),
(450, 'آبگه', '<span class=\"hlight\">آبگه .</span> <font color=\"DarkGreen\"><b>[ گ َه ْ ]</font></b> (اِ مرکب ) آبگاه .<br /></font></div>'),
(451, 'آبگوشت', '<span class=\"hlight\">آبگوشت .</span>(اِ مرکب ) طعامی که از گوشت غالباً با نخود و لوبیاپزند و آب آن را اشکنه یعنی ترید کنند <span class=\"hlight\">:</span> <br />گر آبگوشت که من می پزم بخسته دهند<br />خورد به روز سیم پاچه چون شکر رنجور.<br /> <font color=\"Red\">بسحاق اطعمه .</font><br /><BR><font color=\"Blue\">◄</font> طعمه ای که پیش از شکار، باز و دیگر جوارح طیور را دهند. مُسْته . چشته . <BR><font color=\"Blue\">◄</font> مایعی خاص برای تربیت حیوانات ذره بینی .<br /></font></div>'),
(452, 'آبگوشت خوری', '<span class=\"hlight\">آبگوشت خوری .</span> <font color=\"DarkGreen\"><b>[ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ ]</font></b> (اِ مرکب ) کاسه ٔ خردتر از باطیه وبزرگتر از ماست خوری که عادةً در آن آبگوشت خورند.<br /></font></div>'),
(453, 'آبگون', '<span class=\"hlight\">آبگون .</span> (ص مرکب ) برنگ آب . آبی . کبود. ازرق <span class=\"hlight\">:</span> <br />ببارید و زهم بگسست و گردان گشت بر گردون <font color=\"DarkGreen\"><b>[ ابر ]</font></b><br />چو پیلان پراکنده میان آبگون صحرا.<br /> <font color=\"Red\">فرخی .</font><br />الا تا که روشن ستاره ست هر شب <br />بر این آبگون روی چرخ کیانی .<br /> <font color=\"Red\">فرخی .</font><br />زآن می عناب گون در قدح آبگون <br />ساقی مهتاب گون ترکی حورانژاد.<br /> <font color=\"Red\">منوچهری .</font><br />یکی دائره ست آبگون چنبری <br />فراوان در این دائره داوری .<br /> <font color=\"Red\">اسدی .</font><br />هر مَیَم کآبگون سپهر دهد<br />مغز عیش مرا خمار شود.<br /><font color=\"Red\">مسعودسعد.</font><br />یک ذرّه از آن کیمیا بر دُرست آفتاب و ماه و ستارگان مالیدند مس وجودشان چون درستهای مغربی بر نطع آبگون آسمان تابان شد. (کتاب المعارف ). <BR><font color=\"Blue\">◄</font> سبز. اخضر <span class=\"hlight\">:</span> <br />نگاه کن که به نوروز چون شده ست جهان <br />چو کارنامه ٔ مانی در آبگون قرطاس .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> آبدار.گوهردار. پرندآور. درخشان . روشن <span class=\"hlight\">:</span> <br />نخستین یکی گوهر آمد بچنگ <br />بدانش ز آهن جدا کرد سنگ <br />سر مایه کرد آهن آبگون <br />کز آن سنگ خارا کشیدش برون .<br /> <font color=\"Red\">فردوسی .</font><br />بچنگ اندرش آبگون دشنه بود<br />بخون پریچهرگان تشنه بود.<br /> <font color=\"Red\">فردوسی .</font><br />یکی خنجر آبگون برکشید<br />همی خواست از تن سرش را برید.<br /> <font color=\"Red\">فردوسی .</font><br />نشاننده ٔ خاک در کین بخون <br />فشاننده ٔ خنجر آبگون .<br /> <font color=\"Red\">فردوسی .</font><br />من اکنون بدین خنجر آبگون <br />جهان پیش چشمت کنم قیرگون (کذا).<br /> <font color=\"Red\">فردوسی .</font><br />چو بهرام جنگی بدان بنگرید<br />یکی خنجر آبگون برکشید.<br /> <font color=\"Red\">فردوسی .</font><br />نصرت اندر آبگون پولاد تست <br />ناصر این آبگون پولاد باش .<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> (اِ مرکب ) آبگون یا گل آبگون ؛ نیلوفر <span class=\"hlight\">:</span> <br />همیشه تا که گل آبگون ز لاله ٔ لعل <br />پدید باشد و خیری ز سوسن آزاد...<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> نشا. نشاسته . لباب القمح . لباب البر. لباب الفوم . لباب الحنطه . آمولن . <BR><font color=\"Blue\">◄</font> و در خراسان به معنی آب خیز یعنی قسمتی از کاریز است که آب از آن ترابد. <BR><font color=\"Blue\">◄</font> آبگیر. حوض <span class=\"hlight\">:</span> <br />ز ماهیی که در این آبگون بی آبست <br />بترس و او را چونین یکی نهنگ شمر.<br /> <font color=\"Red\">مسعودسعد.</font><br /><BR><font color=\"Blue\">◄</font> (اِخ ) نام رودی که گویند از جانب خوارزم آمده وبدریای خزر می ریخته است و مصب آن را بدریا آبسکون می گفته اند.<br /></font></div>'),
(454, 'آبگیر', '<span class=\"hlight\">آبگیر.</span> (اِ مرکب ) دریا. بحر <span class=\"hlight\">:</span> <br />بیامد بدریا هم اندر شتاب <br />زهر سو درافکند زورق بر آب <br />ز آگاهی نامدار اردشیر<br />سپاه انجمن شد بر آن آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br />یکی آبگیر است از آن روی شهر<br />کز آن آب کس را ندیدیم بهر<br />که خورشید تابان چو آنجا رسید<br />بدان ژرف دریا شود ناپدید.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مرداب . برکه . غدیر. بطیحه <span class=\"hlight\">:</span> <br />وز آنجایگه لشکر اندر کشید<br />یکی آبگیری نو آمد پدید<br />بگرد اندرش نی بسان درخت <br />تو گفتی که چوب چنار است سخت .<br /> <font color=\"Red\">فردوسی .</font><br />وراخرم خواند جهاندیده پیر<br />بدو اندرون بیشه و آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br />در کتاب خزائن العلوم چنین آورده است که این موضع که امروز بخاراست آبگیر بوده است و بعضی از وی نیستان بوده است و درختستان و مرغزار. (تاریخ بخارای نرشخی ). در آبگیری دو بط و سنگ پشتی ساکن بودند. (کلیله و دمنه ). در این نزدیکی آبگیری دانم . (کلیله و دمنه ). در این آبگیر ماهی بسیار است . (کلیله و دمنه ). بطی در آبگیر روشنایی ماه می دید، پنداشت که ماهی است . (کلیله و دمنه ). آورده اند که در آبگیری دور... سه ماهی بودند. (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> چشمه <span class=\"hlight\">:</span><br />از آن تاختن رنجه گشت اردشیر<br />بدید از بلندی یکی آبگیر<br />جوانمرد پویان بگلنار گفت <br />که اکنون که با رنج گشتیم جفت <br />بباید بر این چشمه آمد فرود<br />که شد باره و مرد بی تار و پود.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد سوی چشمه کهزاد شیر<br />زمانی برافتاد بر آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مصنعه <span class=\"hlight\">:</span> مهدی بحج رفت و اندر بادیه مصنعه ها و آبگیرها فرمود کردن . (مجمل التواریخ ). و از خیرات سلطان ملکشاه آبگیرهای راه حجاز است که فرمود. (راحةالصدور راوندی ). <BR><font color=\"Blue\">◄</font> حوض . استخر. آب انبار <span class=\"hlight\">:</span> <br />دگر شارسان برکه ٔ اردشیر<br />پر از باغ و پرگلشن و آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br />سبک بر سر آبگیر گلاب <br />بفرمودشان ساختن جای خواب .<br /> <font color=\"Red\">فردوسی .</font><br />در او آبگیری بپهنای راغ <br />شناور در آب شکن گیرماغ .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> ظرفی گلاب و عطرهای مایع را که در بزمها می نهاده اند <span class=\"hlight\">:</span> <br />صد اشتر ز گنج و درم کرد بار<br />ز دینار پنجَه زبهر نثار...<br />چو از جامه ٔ خزّ و چینی حریر<br />ز زرّ و زبرجد یکی آبگیر<br />بمریم فرستاد و چندی گهر<br />یکی نغز طاوس کرده بزر.<br /> <font color=\"Red\">فردوسی .</font><br />فروزنده ٔ مجلس و میگسار<br />نوازنده ٔ چنگ با گوشوار...<br />طبقهای زرین پراز مشک ناب <br />بپیش اندرون آبگیر گلاب .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> شمر. غفچ . ژی . (فرهنگ اسدی ). غفچی . (صحاح الفرس ). کوژی . آبدان . تالاب . کولاب . غدیر. ثغب <span class=\"hlight\">:</span> <br />باد بهاری به آبگیر برآمد<br />چون رخ من گشت آبگیر پر از چین .<br /> <font color=\"Red\">عماره .</font><br />ز باران زوبین وباران تیر<br />زمین شد ز خون چون یکی آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت بهرام کز شهر تو<br />ز مردی نیامد جز این بهر تو<br />که ماهی فروشند یکسر همه <br />ز تمّوز تا روزگار دمه <br />ترا پیشه دام است بر آبگیر<br />نه مرد سنانی نه کوپال و تیر.<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمد ز شاه اردشیر<br />که آورد لشکر بر این آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br />چکاچاک تیغ آمد و گرز و تیر<br />ز خون یلان گشت دشت آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمد بشاه اردشیر<br />پر اندیشه شد بر لب آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br />وز آن پس بهر سو بشد مرد پیر<br />بیاورد مردم سوی آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br />چو دو آبگیرش پر از خون دو چشم <br />مرا دید و غرّید و آمد بخشم .<br /> <font color=\"Red\">فردوسی .</font><br />هوا دام کرکس شد از پرّ تیر<br />زمین شد زخون سران آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br />شده آبگیران فسرده ز یخ <br />چنان کوس رویین اسکندران .<br /> <font color=\"Red\">منوچهری .</font><br />ماغ اندر آبگیر و بر او قطره های آب <br />چون چهره ٔ نشسته بر او قطره های خوی .<br /> <font color=\"Red\">منوچهری .</font><br />ماهی در آبگیر داردجَزْعین زره <br />آهو در مرغزار دارد سیمین شکم .<br /> <font color=\"Red\">منوچهری .</font><br />رسیدند زی آبگیری فراز<br />زده کله ٔ زرّبفت از فراز.<br /> <font color=\"Red\">اسدی .</font><br />کمان آزفنداک شد ژاله تیر<br />گل غنچه پیکان زره آبگیر.<br /> <font color=\"Red\">اسدی .</font><br />مرکبش را چه آب گیر و چه بحر<br />خنجرش را چه یک تن و چه هزار.<br /> <font color=\"Red\">مسعودسعد.</font><br />ریخت از شاخ درختان از نهیب تیر او<br />غیبه های جوشن زر آبگون بر آبگیر.<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> افزاری مانند جاروب از لیف و مانند آن که شومالان یعنی آهاردهندگان بر آب زنند و بر تانه که بجهت بافتن ترتیب کرده باشند، فشانند <span class=\"hlight\">:</span> <br />بدفته و حد و ماشوره و کلاوه و چرخ <br />به آبگیر و بمشتوب و میخ کوب و طناب .<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> گنجایش و ظرفیت حوضی یا پیمانه ای یا مکیالی : آبگیر این حوض ده کرّ است . <BR><font color=\"Blue\">◄</font> ظرف آب . آوند. آبدان . <BR><font color=\"Blue\">◄</font> تمام پهنه ای که آب آن بیک رود ریزد. (فرهنگستان زمین شناسی ). <BR><font color=\"Blue\">◄</font> (نف مرکب ) خادم حمام که آب ِ شست وشوی دهد. <BR><font color=\"Blue\">◄</font> آنکه سوراخ و درزهای ظروف فلزین چون سماورو آفتابه و تیان حمام با قلعی یا موم مذاب بندد.<br /></font></div>'),
(455, 'آبگیرناک', '<span class=\"hlight\">آبگیرناک .</span> (ص مرکب ) زمینی بسیار غدیر و آبگیر.<br /></font></div>'),
(456, 'آبگیری', '<span class=\"hlight\">آبگیری .</span> (حامص مرکب ) شغل آبگیر حمام . <BR><font color=\"Blue\">◄</font> لحیم کردن ظرفهای فلزین با قلعی یا بستن منافذ آن با موم مذاب . <BR><font color=\"Blue\">◄</font> پرآب کردن حوض و آب انبار و ظروف و اوانی .<br /></font></div>'),
(457, 'آبگین', '<span class=\"hlight\">آبگین .</span> (اِ مرکب ) آینه . مرآت <span class=\"hlight\">:</span> <br />همه سقف و دیوارها و زمین <br />بپوشید بر تخته ٔ آبگین .<br /><font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /></font></div>'),
(458, 'آبگینه', '<span class=\"hlight\">آبگینه .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) رجوع به پل آبگینه شود.<br /></font></div>'),
(459, 'آبگینه', '<span class=\"hlight\">آبگینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) جسمی جامد غیر حاجب ماوراء که از ذوب سنگ آتش زنه (چخماق ) با قلیا (ملح القلی ) سازند. شیشه . زجاج . زُجاجه . اَسر <span class=\"hlight\">:</span> بازرگانان مصر آنجا <font color=\"DarkGreen\"><b>[ سودان ]</font></b> روند و نمک و آبگینه و ارزیز برند و بهمسنگ زر فروشند. (حدودالعالم ).<br />اندر اقبال آبگینه خنور<br />بستاند عدو ز تو ببلور.<br /> <font color=\"Red\">عنصری .</font><br />گهر به دست کسی کو نه اهل آن باشد<br />چو آبگینه بود بی بها و پست بها.<br /> <font color=\"Red\">عنصری .</font><br />یکی با من چو جان با غم بکینه <br />یکی مانند سنگ و آبگینه .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />نپیوندند با هم مهر و کینه <br />چو کین آهن بود مهر آبگینه .<br /> <font color=\"Red\">(ویس ورامین ).</font><br />بهم چون بود مهر و کین گاه جنگ <br />ابا آبگینه کجا ساخت سنگ ؟<br /> <font color=\"Red\">اسدی .</font><br />آبگینه ز سنگ میزاید<br />لیک سنگ آبگینه میشکند.<br /> <font color=\"Red\">خاقانی .</font><br />مگر میرفت استاد مهینه <br />خری میبرد بارش آبگینه .<br /> <font color=\"Red\">عطار.</font><br />آبگینه همه جا یابی از آن قدرش نیست <br />لعل دشوار به دست آید از آن است عزیز.<br /> <font color=\"Red\">سعدی .</font><br />بدر میکنند آبگینه ز سنگ <br />کجا ماند آیینه در زیر زنگ ؟<br /> <font color=\"Red\">سعدی .</font><br />ز منجنیق فلک سنگ فتنه میبارد<br />من ابلهانه گریزم در آبگینه حصار.<br /> <font color=\"Red\">عرفی .</font><br />صبوری من و بیرحمی تو آتش و آب <br />دل من و غم عشق تو آبگینه و سنگ .<br /> <font color=\"Red\">ولی دشت بیاضی .</font><br /> <BR><font color=\"Blue\">◄</font> آینه ٔ زجاجی . <BR><font color=\"Blue\">◄</font> آینه ٔ حلبی . آینه ٔ رومی . آینه ٔ فلزین . سجنجل <span class=\"hlight\">:</span> <br />دو خانه دگر زآبگینه بساخت <br />زبرجد بهر جای اندر نشاخت .<br /> <font color=\"Red\">فردوسی .</font><br />که از آبگینه همی خانه کرد<br />وز آن خانه گیتی پرافسانه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />گفتم آن سفر کدام است، گفت گوگرد پارسی خواهم بچین بردن ... و آبگینه ٔحلبی بیمن . (گلستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سنگ آبگینه </span> ؛ قسمی از ریگ سنگ چخماقی باشد که آن را با مواد دیگر مخلوط و ذوب کنند شیشه ساختن را. مینا. (زمخشری ) <span class=\"hlight\">:</span> و از نصیبین سنگ آبگینه خیزد نیکو. (حدودالعالم ).<br /> <BR><font color=\"Blue\">◄</font> بمجاز، به معنی ظرف از شیشه، خاصه ظرف شراب <span class=\"hlight\">:</span><br />زآن شرابی خورد باید خرّم و یاقوت فام <br />کز فروغش سیمبر ساغر شود یاقوت سان <br />زآبگینه عکس آن چون نوربر دست افکند<br />دست بیرون کرد پنداری کلیم از بادبان .<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> برخی از چیزهای شفاف یادرخشنده را مانند الماس و بلور و تیغ و آسمان نیز مجازاً آبگینه گفته اند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آبگینه بحلب بردن </span> ؛ مرادف زیره بکرمان بردن .<br /><span class=\"hlight\">آبگینه و سنگ </span> ؛ دو چیز ضد و مخالف .<br /></font></div>'),
(460, 'آبگینه خانه', '<span class=\"hlight\">آبگینه خانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) آینه خانه .<br /></font></div>'),
(461, 'آبگینه فروش', '<span class=\"hlight\">آبگینه فروش .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ف ُ ]</font></b> (نف مرکب ) فروشنده ٔ آبگینه <span class=\"hlight\">:</span> <br />شرم آید از بضاعت بی قیمتم ولیک <br />در شهر آبگینه فروش است و جوهری .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(462, 'آبگینه گر', '<span class=\"hlight\">آبگینه گر.</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِگ َ ]</font></b> (ص مرکب ) شیشه گر. زَجّاج . زُجاجی . (ربنجنی ).<br /></font></div>'),
(463, 'آبگینه گری', '<span class=\"hlight\">آبگینه گری .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ گ َ ]</font></b> (حامص مرکب ) عمل ساختن آبگینه . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) جای ساختن آبگینه . زجّاجی .<br /></font></div>'),
(464, 'آبی', '<span class=\"hlight\">آبی .</span> (ص نسبی ) برنگ آب . کبود. ازرق . نیلی . نیلگون . نیلوفری . کوود. آبیو. رنگ کبود روشن . و گاه آبی آسمانی گویند و از آن آبی سخت روشن خواهند و این همان آسمانجونی و آسمانگونه است . و آبی سیر گویند و از آن آبی پررنگ و گرفته اراده کنند و مقابل آن آبی روشن است . <BR><font color=\"Blue\">◄</font> منسوب به آب . مائی <span class=\"hlight\">:</span> <br />در تن خود بنگر این اجزای تن <br />از کجا جمع آمدند اندر بدن <br />آبی و خاکی ّ و بادی وآتشی <br />عرشی و فرشی ّ ورومی ّ و کشی .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> آنچه از گیاه و حیوان که در آب باشد، مقابل خاکی : اسب آبی . مار آبی . نباتات آبی <span class=\"hlight\">:</span> <br />با غم مرگ کس نباشد خوش <br />آبیان را چه عیش در آتش ؟<br /> <font color=\"Red\">مکتبی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">زراعت آبی </span> ؛ زرع مسقوی و مسقاوی . مقابل دیم و دیمی یعنی مظمی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ساعت آبی </span> ؛ ظرفی بوده بدرجات بخش شده که پر آب می کرده اند و از چکیدن آب بحدی معلوم زمان را می پیموده اند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثلثه ٔ آبی و بروج آبی </span> ؛ در اصطلاح اهل تنجیم برجهای سرطان و عقرب و حوت باشد.<br /><BR><font color=\"Blue\">◄</font> آنکه باچرخ و ارابه آب بخانه ها برد.<br /></font></div>'),
(465, 'آبی', '<span class=\"hlight\">آبی .</span> (اِ) میوه ٔ بزرگتر از سیب برنگ زرد پرزدار و از سوی دم و سرترنجیده و برگ درخت آن با پرز و مخملی و رنگ و پوست چوب آن بسیاهی مایل . بهی . بِه ْ. سفرجل <span class=\"hlight\">:</span> <br />آبی مگر چو من ز غم عشق زرد گشت <br />وز شاخ همچو چوک بیاویخت خویشتن .<br /> <font color=\"Red\">بهرامی .</font><br />تا سرخ بود چون رخ معشوقان نارنج <br />تا زرد بود چون رخ مهجوران آبی .<br /> <font color=\"Red\">فرخی (از فرهنگ اسدی، خطی ).</font><br />نگرید آبی و آن رنگ رخ آبی <br />گشته از گردش این چنبر دولابی <br />رخ او چون رخ آن زاهد محرابی <br />بر رخش بر اثر سبلت سقلابی <br />یا چنان زرد یکی جامه ٔ عتّابی <br />پرز برخاسته زو چون سر مرغابی .<br /> <font color=\"Red\">منوچهری .</font><br />آبی چو یکی جوجگک از خایه بجسته <br />چون جوجگکان بر تن او موی برسته <br />مادرْش بجسته سرش از تن بگسسته <br />نیکو و باندام جراحتْش ببسته <br />یک پایک او را ز بن اندر بشکسته <br />وآویخته او را بدگر پای نگونسار.<br /> <font color=\"Red\">منوچهری .</font><br />آبی چو یکی کیسگکی از خز زرد است <br />در بیضه یکی کیسه ٔ کافور کلان است <br />و اندر دل آن بیضه ٔ کافور رباحی <br />ده نافه و ده شاخگک مشک نهان است .<br /> <font color=\"Red\">منوچهری .</font><br />دو صف سروبن دید و آبی و نار<br />زده نغز دکانی از هر کنار.<br /> <font color=\"Red\">اسدی .</font><br />دفع مضرت شرابی که نه تیره بود و نه تنک، ممزوج کنند به آب و گلاب و نقل نار و آبی کنند تا زیان ندارد. (نوروزنامه ).<br />چرا بر یک زمین چندین نبات مختلف روید<br />ز نخل و نار و سیب و بید و چون آبی و چون زیتون ؟<br /> <font color=\"Red\">سنائی .</font><br />چون دانه ٔ نار اشک بدخواهت <br />وز غصه رخش چو چهره ٔ آبی .<br /> <font color=\"Red\">انوری .</font><br />چو یک کیسه ٔ خزّ زرد است آبی <br />نه پیدا در او تار و نه ریسمانش .<br /> <font color=\"Red\">؟ (از تاج المآثر).</font><br />در سیب عقیقی نگر و آبی زرین <br />هر یک بصف عاشق معشوقه نشانند.<br /> <font color=\"Red\">؟ (از تاج المآثر).</font><br />خوش ترش، زردچهره آبی را<br />طبع مرطوب و لون محرور است .<br /> <font color=\"Red\">؟ (از تاج المآثر).</font><br />بحقه ٔ زرین ترنج و آبی از اوراق دیناری روی نمود. (تاج المآثر).<br />گر تو صد سیب و صد آبی بشمری <br />صد نماید، یک شود چون بفشری .<br /> <font color=\"Red\">مولوی .</font><br />دانه ٔ آبی بدانه ی ْ سیب نیز<br />گرچه ماند فرقها دان ای عزیز.<br /> <font color=\"Red\">مولوی .</font><br />آبی که بود بر او غباری <br />نوخط ذقنی بود ز یاری <br />کو در یرقان فتاده باشد<br />پس رو ببهی نهاده باشد.<br /> <font color=\"Red\">امیدی (از جهانگیری ).</font><br /><BR><font color=\"Blue\">◄</font> و به معنی مرغابی و امرود نیز در بعض فرهنگها دیده شده است . <BR><font color=\"Blue\">◄</font> قسمی از انگور که دانه ها و حبه ٔ آن مدور و پوست آن سخت باشد و از غوره ٔ آن گله ترشی کنند. و غوره ٔ آن را غوره ٔ آبی گویند. <BR><font color=\"Blue\">◄</font> آبو. برادر مادر. دائی . خال . خالو. مربرار.<br /></font></div>'),
(466, 'آبی', '<span class=\"hlight\">آبی .</span> (ع ص ) سرکش . نافرمان . بی فرمان . بازایستنده . انکارکننده . ممتنع. اَبی . آنکه سر باززند از. مکروه دارنده . کارِه ْ. <BR><font color=\"Blue\">◄</font> آن گشن که بول بوید. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> (اِخ ) آبی اللحم الغفاری ؛ نام صحابی که گوشت را ناخوش داشتی .<br /></font></div>'),
(467, 'آبی', '<span class=\"hlight\">آبی .</span> (ص نسبی ) منسوب به آبه یعنی آوه . از مردم آبه .<br /></font></div>'),
(468, 'آبی و خاکی', '<span class=\"hlight\">آبی و خاکی .</span> <font color=\"DarkGreen\"><b>[ ی ُ ]</font></b>(ص نسبی ) آنکه هم در آب و هم در خشکی زیستن دارد.<br /></font></div>'),
(469, 'آبیار', '<span class=\"hlight\">آبیار.</span> <font color=\"DarkGreen\"><b>[ آب ْ ]</font></b> (ص مرکب، اِ مرکب ) آنکه کشت را آب دهد. اویار. آب بخش . میرآب . قلاد. ساقی <span class=\"hlight\">:</span> <br />تا کشت تخم مهر تو، یکدم جدا نشد<br />از چشمه سار خون جگرآبیار چشم .<br /><font color=\"Red\">کمال اصفهانی .</font><br /></font></div>'),
(470, 'آبیار', '<span class=\"hlight\">آبیار.</span> <font color=\"DarkGreen\"><b>[ آب ْ ]</font></b> (اِخ ) نام محلی کنار راه سمنان و دامغان میان سمنان و تلیستان در <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> هزارگزی طهران .<br /></font></div>'),
(471, 'آبیاری', '<span class=\"hlight\">آبیاری .</span><font color=\"DarkGreen\"><b>[ آب ْ ]</font></b> (حامص مرکب ) کار آبیار. سقایت <span class=\"hlight\">:</span> <br />به آبیاری دولت بباغ نصرت شاه <br />بسال فتح گل خارمند شد بویا.<br /> <font color=\"Red\">خوندمیر مورخ .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آبیاری کردن </span> ؛ آب دادن . مشروب کردن . آب پاشی کردن . آب زدن . سیرآب کردن .<br /></font></div>'),
(472, 'آبید', '<span class=\"hlight\">آبید.</span> (اِ) شراره و سرشک آتش را گویند. در مؤیدالفضلاء بجای حرف آخر رای قرشت و در جای دیگر زای فارسی نوشته اندو بجای حرف ثالث (ب ) یاء حطی . (برهان ). و در برهان، ابیز بهمزه ٔ مفتوحه بر وزن تمیز و آییژ نیز به همین معنی ضبط شده است، و در بعض فرهنگهاسرشک، آب چشم، اشک و دمع نیز نوشته اند. و ظاهراً معنی اخیر اشتباه وخلطی است ناشی از کلمه ٔ سرشک آتش معنی اولی آبید.<br /></font></div>'),
(473, 'آبیدوس', '<span class=\"hlight\">آبیدوس .</span> (اِخ ) از شهرهای مصر علیاست و تخته سنگهای موسوم به آبیدوس که نامهای دو طبقه از فراعنه ٔ قدیم مصر در آن نقش بود در حفر اراضی آن به دست آمد (بسال <span class=\"hlight\" dir=\"rtl\">١٨٧١</span> م .).<br /></font></div>'),
(474, 'آبیذیمیا', '<span class=\"hlight\">آبیذیمیا.</span> (معرب، اِ) رجوع به اِبیدیمیا شود.<br /></font></div>'),
(475, 'آبین', '<span class=\"hlight\">آبین .</span> (اِخ ) نام قریه ای است از توابع شیراز و مغاره ای به نزدیک آن که مومیایی معدنی از آنجا خیزد. <BR><font color=\"Blue\">◄</font> نام مومیایی که از معدن آبین گیرند. موم آبین . و صاحب برهان در آیین نیز همین معنی را آورده است .<br /></font></div>'),
(476, 'آبیو', '<span class=\"hlight\">آبیو.</span> <font color=\"DarkGreen\"><b>[ وْ ]</font></b> (ص ) اَبیو. آبی . کبود. ازرق . نیلگون .<br /></font></div>'),
(477, 'آتا و اوتا', '<span class=\"hlight\">آتا و اوتا.</span> <font color=\"DarkGreen\"><b>[ وُ او ]</font></b> (اِ مرکب، ازاتباع ) در تداول عامه، همگی از بزرگ و کوچک، و گاه گویند آتا و اوتا بلند و کوتا؛ یعنی بلند و کوتاه .<br /></font></div>'),
(478, 'آتاب', '<span class=\"hlight\">آتاب .</span> (ع اِ) ج ِ اِتب . رجوع به اتب شود.<br /></font></div>'),
(479, 'آتابای', '<span class=\"hlight\">آتابای .</span> (اِخ ) نام تیره ای از ترکمانان . رجوع به اَتابای شود.<br /></font></div>'),
(480, 'آتابیک', '<span class=\"hlight\">آتابیک .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ترکی، ص مرکب، اِ مرکب ) اَتابیک . رجوع به اتابک شود.<br /></font></div>'),
(481, 'آتاش', '<span class=\"hlight\">آتاش .</span> (ترکی، ص مرکب، اِ مرکب ) (گویا از ترکی جغتائی آد، نام + تاش، هم )همنام . سَمی ّ. و آن را آداش نیز گویند <span class=\"hlight\">:</span> <br />گر کار بنام استی از آتاشی عمّر<br />فرزند تو با عمّر بودستی هموار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />آتاش عبادله ٔ مغتفره . (راحةالصدور راوندی ).<br />ای آنکه تراست ملک آتاش <br />با دیو و پری بزیر خاتم .<br />(راحةالصدور راوندی، در مدح سلیمان بن محمدبن ملکشاه ).<br />پشت دین بوالمظفر آن شاهی <br />کآمد آتاش شاه پیغمبر.<br /> <font color=\"Red\">(از راحةالصدور راوندی ).</font><br />روانش از روضه ٔ رضوان و فرضه ٔ جنان تماشای آن میکند که آتاش او بشادکامی حکم می راند و... (راحةالصدور راوندی ).<br /></font></div>'),
(482, 'آتبین', '<span class=\"hlight\">آتبین .</span> (اِخ ) نام پدر فریدون <span class=\"hlight\">:</span> <br />چو ضحاک بگرفت روی زمین <br />پدید آمد اندر جهان آتبین .<br /> <font color=\"Red\">فردوسی .</font><br />فریدون که بد آتبینش پدر<br />مر او را که بد پیش از آن تاجور.<br /> <font color=\"Red\">فردوسی .</font><br />باز دگرباره مهرگان بدر آمد<br />جشن فریدون آتبین ببر آمد.<br /> <font color=\"Red\">منوچهری .</font><br />دشت عرب را پسر ذوالیزن <br />خاک عجم را پسرآتبین .<br /> <font color=\"Red\">سنائی .</font><br />خاصه ٔ سیمرغ کیست جز پدر روستم <br />قاتل ضحاک کیست جز پسر آتبین ؟<br /> <font color=\"Red\">خاقانی .</font><br />و مصحف آن آبتین است . و در برهان نفس کامل و نیکوکار و صاحب گفتار و کردار نیک و اسعدالسعداء آمده است .<br /></font></div>'),
(483, 'آتربات', '<span class=\"hlight\">آتربات .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (ص مرکب، اِ مرکب ) آذربد. آتش پناه .<br /></font></div>'),
(484, 'آتربات مانسارسپندان', '<span class=\"hlight\">آتربات مانسارسپندان .</span> <font color=\"DarkGreen\"><b>[ ت ُ سا رِ پ َ ]</font></b> (اِخ ) (پسر قانون مقدس آتش پناه ) نام موبدی وزیر شاپور دویم و شارح اَوِستا.<br /></font></div>'),
(485, 'آترپاتن', '<span class=\"hlight\">آترپاتن .</span> <font color=\"DarkGreen\"><b>[ رُ ت ِ ]</font></b> (اِخ ) نام قدیم و اصلی آذربایجان .<br /></font></div>'),
(486, 'آترپاتنه', '<span class=\"hlight\">آترپاتنه .</span> <font color=\"DarkGreen\"><b>[ رُ ت ِ ن َ ]</font></b> (اِخ ) آترپاتن .<br /></font></div>'),
(487, 'آتسز', '<span class=\"hlight\">آتسز.</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) اَتْسِز. نام سومین فرمانروای سلسله ٔ خوارزم شاهی است که از حدود <span class=\"hlight\" dir=\"rtl\">٤٧٠</span> تا حدود <span class=\"hlight\" dir=\"rtl\">٦٢٨</span> هَ . ق . امارت داشته اند. آتسز پسر محمدبن انوشتکین و نخستین کسی است که در فرمانروایی خوارزم علم استقلال برافراشت . انوشتکین و پسرش محمد از جانب سلجوقیان حکومت خوارزم داشتند. آتسز نیز در سال <span class=\"hlight\" dir=\"rtl\">٥٢١</span> آنگاه که پدرش محمد درگذشت بفرمان سنجر پسر ملکشاه جانشین پدر گردید.لیکن پس از چندی دعوی استقلال کرد و میان او و سنجر چند نوبت جنگ افتاد و در سال <span class=\"hlight\" dir=\"rtl\">٥٣٣</span> مغلوب سنجر گردید. سه سال بعد (<span class=\"hlight\" dir=\"rtl\">٥٣٦</span>) کار سنجر بسبب شکست عظیمی که از ترکان یافت روی بضعف نهاد و آتسز این فرصت را از دست نداده بار دیگر سر بطغیان برآورد و بحدود مرو و خراسان تاختن برد و عاقبت در سال <span class=\"hlight\" dir=\"rtl\">٥٣٨</span> با سنجر آشتی کرد و فرمانروایی خوارزم او را مسلم گردید. آتسز پادشاهی دانش دوست و ادب پرور بود و در دربار او عده ای از علما و ادبا مجتمع بودند و ازجمله رشید وطواط است که سالها ندیم و مداح او بود و کتاب حدائق السحر را به نام او پرداخته است . آتسز مدت سی سال در ابتدا بنیابت و سپس به استقلال فرمانروایی کرد و در سال <span class=\"hlight\" dir=\"rtl\">٥٥١</span> درگذشت .<br /></font></div>'),
(488, 'آتش', '<span class=\"hlight\">آتش .</span><font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) تخلص شاعری فارسی از متأخرین که اصل وی از حِلّه و مسکنش فریدن اصفهان بوده و در تذکره هابه نام آتش اصفهانی یاد شده است . و نام اصلی او را ذکر نکرده اند. تخلص خواجه علی حیدر شاعر هندوستانی که به فارسی و اردو شعر میگفته و بهر دو زبان دیوان اشعار داشته و در سال <span class=\"hlight\" dir=\"rtl\">١٢٦٣</span> هَ . ق . وفات یافته است .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(489, 'آتش', '<span class=\"hlight\">آتش .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ) (از زندی آترس، و اوستایی آتر، و سانسکریت هوت آش، خورنده ٔ قربانی ؛ از: هوت، قربانی + آش، خورنده ) یکی از عناصر اربعه ٔ قدما و آن حرارت توأم با نوری است که از بعض اجسام سوختنی برآید چون چوب و ذغال و امثال آن . آذر. آدر. ورزم . تش . آدیش . وَداغ . بلک . کاغ . مخ . هیر. نار. سعیر. عجوز. ام القری . و در زبان شعری از آن بقبله ٔ جمشید، قبله ٔ دهقان، قبله ٔ زردشت، قبله ٔ مجوس، بستر سمندر، تخته ٔ زرنیخ و غیر آن تعبیر کرده اند <span class=\"hlight\">:</span> <br />عطات باد چو باران دل موافق خوید<br />نهیبت آتش و جان مخالفان پده باد.<br /> <font color=\"Red\">شهید بلخی .</font><br />آتش هجرانْت را هیزم منم <br />و آتش دیگرْت را هیزم پده .<br /> <font color=\"Red\">رودکی .</font><br />شب زمستان بود کپّی سرد یافت <br />کرمکی شب تاب ناگاهی بتافت <br />کپّیان آتش همی پنداشتند<br />پشته ٔ هیزم بدو برداشتند.<br /> <font color=\"Red\">رودکی (از کلیله ودمنه ٔ منظوم ).</font><br />بدان ماند بنفشه بر لب جوی <br />که بر آتش نهی گوگرد بفخم .<br /> <font color=\"Red\">منجیک .</font><br />وزو مایه ٔ گوهر آمد چهار...<br />یکی آتشی برشده تابناک <br />میان ْ باد و ابر از بر تیره خاک .<br /> <font color=\"Red\">فردوسی .</font><br />بکوه سپند آتش اندرفکند<br />که دودش برآمد بچرخ بلند.<br /> <font color=\"Red\">فردوسی .</font><br />پس آنگاه فرمود پرمایه شاه <br />که بر چوب ریزند نفت سیاه <br />زمین گشت روشنتر از آسمان <br />جهانی خروشان و آتش دمان .<br /> <font color=\"Red\">فردوسی .</font><br />بجنگ اندرون مرد را دل دهند<br />نه بر آتش تیز بر گل نهند.<br /> <font color=\"Red\">فردوسی .</font><br />چو بخشایش پاک یزدان بود<br />دم آتش و باد یکسان بود.<br /> <font color=\"Red\">فردوسی .</font><br />بشهر اندرون بانگ و فریاد خاست <br />بهر برزنی آتش و باد خاست .<br /> <font color=\"Red\">فردوسی .</font><br />همی برشد آتش فرود آمد آب <br />همی گشت گرد زمین آفتاب .<br /> <font color=\"Red\">فردوسی .</font><br />بدانگه بدی آتش خوبرنگ <br />چو مر تازیان راست محراب سنگ <br />بسنگ اندر آتش ازو شد پدید<br />کزو روشنی در جهان گسترید.<br /> <font color=\"Red\">فردوسی .</font><br />زلف در رخسار آن دلبر چو دیدم بیقرار<br />می بیندازم در آتش جان و دل چون داربوی .<br /> <font color=\"Red\">کشفی (از فرهنگ اسدی، خطی ).</font><br />گر به پیغاله از کدو فکنی <br />هست پنداری آتش اندر آب .<br /> <font color=\"Red\">عنصری .</font><br />به آتش مان چه سوزد نه خدای ا<br /> <font color=\"Red\">ست </font><br />که آتش کار بادافره نمای است .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />مر او را گفت پورا چند گویی <br />در آتش آب روشن چند جویی ؟<br /> <font color=\"Red\">(ویس و رامین ).</font><br />خردمند کوشد کز آتش رهد<br />نه خود را بسوزنده آتش دهد.<br /> <font color=\"Red\">اسدی .</font><br />خرد زآتش طبعی آتش تراست <br />که مر مردم خام را او پزد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />آتش دوزخ از آن آتش بسی عالی تر است <br />گر غذا درخورد یابد در سوی علیا شود.<br /> <font color=\"Red\">ناصرخسرو.</font><br />آتش دادت خدای تا نخوری خام <br />نز قبل سوختن بدو سر و دستار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />همچنان کاندر جهان زآتش نسوزد زر همی <br />زرّ جانت را نسوزد زآتش سوزان سقر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />شیخ ما گفت سری سقطی که خال جنید بود قدس اﷲ روحهما بیمار شد جنید بعیادت او درشد و مروحة برداشت تا بادش کند. گفت ای جنید آتش از باد تیزتر شود. (اسرارالتوحید).<br />آنکه آتش را کند ورد و شجر<br />هم تواند کرد این را بی ضرر.<br /> <font color=\"Red\">مولوی .</font><br />پلنگ از زدن کینه ورتر شود<br />بباد آتش تیز برتر شود.<br /><font color=\"Red\">سعدی .</font><br />آتش از خانه ٔ همسایه ٔ درویش مخواه <br />کآنچه بر روزن او میگذرد دود دل است .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> در امثله ٔ ذیل مفتوح بودن تاء در آتش ظاهر است <span class=\"hlight\">:</span> <br />آسمان ابلق و روی زمی ابرش گشته ست <br />دشت ماننده ٔ دیبای منقش گشته ست <br />لاله بر طرف چمن چون گه آتش گشته ست .<br /> <font color=\"Red\">منوچهری .</font><br />بگریه گه گهی دل را کنم خوش <br />تو گوئی می کشم آتش به آتش .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />کی شود دهر با تو یکدم خوش <br />چون جهد ناگه از خیار آتش .<br /> <font color=\"Red\">سنائی .</font><br />تا درنزنی بهرچه داری آتش <br />هرگز نشود حقیقت وقت تو خوش .<br /> <font color=\"Red\">بخاری .</font><br />با غم مرگ کس نباشد خوش <br />آبیان را چه عیش در آتش ؟<br /> <font color=\"Red\">مکتبی .</font><br /> <BR><font color=\"Blue\">◄</font> پاره ای از زغال یا هیمه ٔ افروخته . اخگر. جذوه . سکار. بجال . جمره . قبس . <BR><font color=\"Blue\">◄</font> گوگرد احمر در اصطلاح کیمیاگران . <BR><font color=\"Blue\">◄</font> مجازاً، جهنم . دوزخ <span class=\"hlight\">:</span> <br />اگر از من تو بد نداری باز<br />نکنی بی نیاز روز نیاز<br />نه مرا جای زیر سایه ٔ تو<br />نه از آتش دهی بحشر جواز<br />زِستن و مردنت یکی است مرا<br />غلبکن در، چه باز یا چه فراز.<br /> <font color=\"Red\">ابوشکور بلخی .</font><br />آزها را بسوی خویش مکش <br />که کشد جانت را سوی آتش .<br /> <font color=\"Red\">سنائی (حدیقه ).</font><br /> <BR><font color=\"Blue\">◄</font> تندی . تیزی <span class=\"hlight\">:</span> <br />بگفتند کین رنج دادی بباد<br />سر نامور پر ز آتش مباد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> ایذاء. اضرار. ظلم فاحش <span class=\"hlight\">:</span> <br />بهانه چه داری تو برمن بیار<br />که بر من سگالید بد روزگار<br />یکی بی زیان مرد آهنگرم <br />ز شاه آتش آید همی بر سرم .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> غم . اندوه سخت <span class=\"hlight\">:</span> <br />دلش <font color=\"DarkGreen\"><b>[ ضحاک ]</font></b> زآن زده فال پرآتش است <br />همان زندگانی بر او ناخوش است .<br /> <font color=\"Red\">فردوسی .</font><br />روان با چشم گریان و دل ریش <br />به آب اشک میکُشت آتش خویش .<br /> <font color=\"Red\">امیرخسرو دهلوی .</font><br /><BR><font color=\"Blue\">◄</font> شراب <span class=\"hlight\">:</span> <br />خاک را از باد بوی مهربانی آمده ست <br />درده آن آتش که آب زندگانی آمده ست .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> بلا و مصیبت <span class=\"hlight\">:</span> <br />زآتش قهر وبا گردید ناگاهان خراب <br />استرابادی که خاکش بود خوشبوتر ز مشک .<br /> <font color=\"Red\">کاتبی ترشیزی .</font><br /> <BR><font color=\"Blue\">◄</font> حرارت . عشق سوزان <span class=\"hlight\">:</span> <br />همه کسی صنما <font color=\"DarkGreen\"><b>[ مر ]</font></b> ترا پرستد و ما<br />از آتش دل آتش پرست شاماریم .<br /> <font color=\"Red\">منطقی (از فرهنگ اسدی، خطی ).</font><br /> <BR><font color=\"Blue\">◄</font> بمعنی نور و رواج و رونق و غضب و سبکروحی و قدر و مرتبه و گرانی نرخ هم گفته اند و کنایه از شیطان است و کنایه از مرد شجاع و دلیر هم هست و قوت هاضمه و اشتها را نیز گویند. (برهان قاطع).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آبی بر (بر روی ) آتش کسی زدن </span> ؛ تسکین غضب او کردن <span class=\"hlight\">:</span> من بنده بفرمان رفتم نزدیک خواجه ... و آبی بروی آتش زدم . (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آتش از آب (دریای آب ) برآمدن، یا آتش از آب افروختن </span> ؛ کاری عظیم سخت پیش آمدن <span class=\"hlight\">:</span><br />پس آگاهی آمد بافراسیاب <br />که آتش برآمد ز دریای آب ...<br />از ایران نهنگی <font color=\"DarkGreen\"><b>[ رستم ]</font></b> برآمد بجنگ <br />که شد چرخ گردنده را راه تنگ .<br /> <font color=\"Red\">فردوسی .</font><br />من چو خواهم کرد فریاد آب زآتش برکشم <br />او چو خواهد خورد تشویر آتش افروزد ز آب .<br /> <font color=\"Red\">معزی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آتش از آب ندانستن </span> ؛ عظیم متهور و بی باک بودن <span class=\"hlight\">:</span> <br />یکی شهریار است افراسیاب <br />که آتش همانا نداند ز آب .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آتش از جایی برانگیختن (برآوردن )</span> ؛ ویران کردن آن جای <span class=\"hlight\">:</span> <br />بکین سیاوش بریدم سرش <br />برانگیختم آتش از کشورش .<br /><font color=\"Red\">فردوسی .</font><br />سپاهی بر، از جنگجویان بروم <br />که آتش برآرند از آن مرزوبوم .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آتش از خیار برآمدن یا جستن </span> ؛ امری ممتنع و محال صورت بستن <span class=\"hlight\">:</span> <br />چون بعشق از خیارت آتش جست <br />آتش از آتشی بدارد دست .<br /> <font color=\"Red\">سنائی .</font><br />نامت بمیان مردمان در<br />چون آتشی از خیار جسته .<br /> <font color=\"Red\">انوری .</font><br />بی آبروی دست تو هر کس که آب یافت <br />از دست دهر، بود چنان کآتش از خیار.<br /> <font color=\"Red\">انوری .</font><br />یارب آن آتش از خیار جهد<br />که دلم زآتش غمش برهد.<br /> <font color=\"Red\">انوری .</font><br />لطیفه ٔ کرم تست این که نرگس را<br />بسعی باد بهار آتشی جهد ز خیار.<br /> <font color=\"Red\">کمال اسماعیل .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آتش به دست خویش بر ریش خویش زدن (از نفایس الفنون )، آتش به دست خویش در خرمن خویش زدن </span> ؛ خود باعث زیان و رنج خویش گشتن <span class=\"hlight\">:</span> <br />آتش بدو دست خویش در خرمن خویش <br />من خود زده ام چه نالم از دشمن خویش ؟<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آتش بی زبانه </span> ؛ بکنایه، لعل . یاقوت .<BR>۩ شراب <span class=\"hlight\">:</span> <br />بسفالی ز خانه ٔ خمار<br />آتش بی زبانه بستانیم .<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آتش کارزار برانگیختن </span> ؛ پیوستن حربی را. بر شدّت و حدّت جنگ فزودن <span class=\"hlight\">:</span> <br />برانگیختند آتش کارزار<br />هوا تیره گون شد ز گرد سوار.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آبی که روی آتش ریزند</span> ؛ دوائی سریعالتأثیر. گفتاری که زود اثر بخشددر شنونده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آتش </span> ؛ سخت بشتاب <span class=\"hlight\">:</span> <br />بکردار آتش همی راندند<br />جهان آفرین را همی خواندند.<br /> <font color=\"Red\">فردوسی .</font><br />بزد بوق و کوس و سپه برنشاند<br />بکردار آتش از آنجا براند.<br /> <font color=\"Red\">فردوسی .</font><br />بسیار گرم . نیک سرخ .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آتش خواه </span> ؛ آنکه درنگ نیارد و بمحض آمدن بازگشتن خواهد <span class=\"hlight\">:</span> <br />ای گشته دلم بی تو چو آتشگاهی <br />وز هر رگ جان من به آتش راهی <br />چون میدانی که در دل آتش دارم <br />ناآمده بگذری، چو آتش خواهی .<br /> <font color=\"Red\">عطار.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آتش سرخ </span> ؛ بثره یا دملی سخت باحرارت . تنی از سوزش تب سرخ شده . طعام یا دوائی سخت حارّ و حادّ.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آتش واسپند، مثل آتش و پنبه </span> ؛ سخت ناسازوار.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آب و آتش بهم نیاید راست </span> ؛ دو ضدفراهم نیایند.<br /> <span class=\"hlight\">آتش از آتش گل کند</span> ؛ یاری بیکدیگر مایه ٔ سعادت یاری دهندگان است .<br /> <span class=\"hlight\">آتش از باد تیزتر گردد</span> ؛ ملامت ْ عاشق را بر عشق او افزاید.<br /> <span class=\"hlight\">آتش از چنار پوده برآید</span> ؛دود از کنده برخیزد.<br /> <span class=\"hlight\">آتش از خیار نجهد</span> (برنیاید)؛ توقع و انتظاری نه بجای خویش است <span class=\"hlight\">:</span> <br />نکرد و هم نکند حاسد تو کار صواب .<br />نجست و هم نجهد هرگز از خیار آتش .<br /> <font color=\"Red\">ادیب صابر.</font><br />کی شود دهر با تو یک دم خوش <br />چون جهد ناگه از خیار آتش ؟<br /> <font color=\"Red\">سنائی .</font><br />آبی از روزگار اگر ببرم <br />آتشی دان که از خیار آید.<br /> <font color=\"Red\">انوری .</font><br /> <span class=\"hlight\">آتش اگر اندک است حقیر نباید داشت </span> . (گلستان )؛ دشمن حقیر و بلای خرد را کوچک شمردن صواب نباشد.<br /> <span class=\"hlight\">آتش بجان شمع فتد کین بنا نهاد</span> ؛ نفرینی است کسی را که بدعتی زشت نهاده باشد.<br /> <span class=\"hlight\">آتش بزمستان ز گل سوری به </span> ؛ آتش در زمستان سخت مطلوب است .<br /> <span class=\"hlight\">آتش بگرمی عرق انفعال نیست </span> ؛ شرم و خجلت گناه و خطایی سر زده سخت ناگوار باشد.<br /> <span class=\"hlight\">آتش جای خود باز کند</span> ؛ مرد زیرک وماهر و استاد زود شناخته شود. خوبان و صاحب جمالان درهر دل راه یابند.<br /> <span class=\"hlight\">آتش چنار از چنار است </span> ؛ آنچه از بدی که بما میرسد نتیجه ٔ کارهای ما یا کسان ماست <span class=\"hlight\">:</span> <br />کفن بر تن تَنَد هر کرم پیله <br />برآرد آتش از خود هر چناری .<br /> <font color=\"Red\">عطار.</font><br /> <span class=\"hlight\">آتش چو برافروخت بسوزد تر و خشک </span> ؛ کیفر و بادافراه گناهکاران گاه بی گناهان را نیز فرا گیرد.<br /> <span class=\"hlight\">آتش دوست و دشمن نداند</span> ؛ آتش چو برافروخت بسوزد تر و خشک .<br /> <span class=\"hlight\">آتش رابه آتش نتوان کشت </span> ؛ عداوت را با محبت تسکین توان داد نه با عداوت .<br /> <span class=\"hlight\">آتش را به آتش ننشانند</span> ؛ آتش را به آتش نتوان کشت .<br /> <span class=\"hlight\">آتش را به روغن نتوان نشاند</span> ؛ آتش را به آتش نتوان کشت .<br /> <span class=\"hlight\">اگر آتش شود خود را سوزد</span> ؛ حدت و شدت غضب یا کاراو بر خصم و حریف زیان نبخشد و خود او را زیانبخش ترباشد <span class=\"hlight\">:</span> <br />آتش سوزان بود حیات سمندر.<br /> <font color=\"Red\">قاآنی .</font><br /> <span class=\"hlight\">آتش کند هرآینه صافی عیار زر</span> .<br /> <font color=\"Red\">معزی .</font><br /> <span class=\"hlight\">آتش سوزان نکند با سپند</span> <br />آنچه کند دود دل مستمند.<br /> <font color=\"Red\">سعدی .</font><br /> <span class=\"hlight\">آتش کند پدید که عود است یا حطب </span> .<br /> <font color=\"Red\">ابن یمین .</font><br />عندالامتحان یکرم الرجل او یهان .<br />رجوع بمثل پیشین شود.<br /> <span class=\"hlight\">آتش که به بیشه افتد تر و خشک نداند، یا نه خشک گذارد و نه تر</span> .<br /> <span class=\"hlight\">آتش چو برافروخت بسوزد تر و خشک </span> .<br /> <span class=\"hlight\">بکش آتش خرد پیش از گزند</span> <br />که گیتی بسوزد چو گردد بلند.<br /> <font color=\"Red\">فردوسی .</font><br />دشمن را پیش از آنکه نیرو یابد دفع کردن باید.<br /> <span class=\"hlight\">تو خاکی چو آتش مشو تند و تیز</span> .<br /> <font color=\"Red\">فردوسی .</font><br />فروتن باش و از خشم و تندی بپرهیز.<br /> <span class=\"hlight\">آتش که بشعله برکشد سر</span> <br />چه هیزم خشک و چه گل تر.<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <span class=\"hlight\">تو آتش به نی درزن و درگذر</span> <br />که در بیشه نه خشک ماند نه تر.<br /> <font color=\"Red\">سعدی .</font><br /> <span class=\"hlight\">زآتش قهر وبا گردید ناگاهان خراب </span> <br />استرابادی که خاکش بود خوشبوتر ز مشک <br />وندرو از پیر و برنا هیچ تن باقی نماند<br /> <span class=\"hlight\">آتش اندر بیشه چون افتد نه تر ماند نه خشک </span> .<br /> <font color=\"Red\">کاتبی ترشیزی .</font><br /> <span class=\"hlight\">در آتش بودن به از بیرون آتش است </span> ؛ شریک بودن در بلا و رنج کسان خودبهتر از دور بودن از بلا و شنیدن اخبار مبالغه آمیز آن است .<br /> <span class=\"hlight\">هر کس آتش گوید دهانش نسوزد</span> . (از قرةالعیون )؛ گفتار محض را اثری نیست .<br /><span class=\"hlight\">گویی مویش را آتش زدند</span> ؛ با عدم آگاهی درست به وقت رسید.<br /></font></div>'),
(490, 'آتش آسمان', '<span class=\"hlight\">آتش آسمان .</span> <font color=\"DarkGreen\"><b>[ ت َ ش ِ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آتش آسمانی . برق . صاعقه .<br /></font></div>'),
(491, 'آتش افرازه', '<span class=\"hlight\">آتش افرازه .</span> <font color=\"DarkGreen\"><b>[ ت َ اَ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ مرکب ) قسمی از آتشبازی . تیر هوایی . فشفشه .<br /></font></div>'),
(492, 'آتش افروختن', '<span class=\"hlight\">آتش افروختن .</span><font color=\"DarkGreen\"><b>[ ت َ اَ ت َ ]</font></b> (مص مرکب ) تسعیر. تأریث . توقید. ایقاد. تسجیر. استیقاد. اشعال . اثقاب . تثقیب . تأریش . ایراء. توریه . تشعیل . الهاب . اضرام . تلهیب . تأجیج . روشن کردن . و رجوع به افروختن شود. <BR><font color=\"Blue\">◄</font> مجازاً، فتنه انگیختن و سبب جنگ و دشمنی شدن <span class=\"hlight\">:</span> <br />میان دو تن آتش افروختن <br />نه عقل است و خود در میان سوختن .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(493, 'آتش افروز', '<span class=\"hlight\">آتش افروز.</span> <font color=\"DarkGreen\"><b>[ ت َ اَ ]</font></b> (نف مرکب، اِ مرکب ) موقد و گیراننده و روشن کننده ٔ آتش <span class=\"hlight\">:</span> <br />ظرافت آتش افروز جدایی است <br />ادب آب حیات آشنایی است .<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> ظرفی سفالین بهیأت جمجمه ٔ آدمی که گویند از مخترعات جالینوس است و سوراخی تنگ دارد. و چون آن را درون آب فروبرند آب بخود کشد و سپس چون بکنار آتش نیم افروخته گذارند و گرم شود بخاری از سوراخ به آتش دمد و آتش را برافروزد. و آن را به فارسی دمه و آتش فروز و آذرافروز و آذرفروز و آذرافزا و آذرفزا نیز گویند و به عربی جُرّه ٔ مثقبه خوانند. <BR><font color=\"Blue\">◄</font> وَقود. آتش افروزنه . آتش افروزه . آتش افروزینه . آتش گیره . یعنی هر چیزی که بدان آتش افروزند از پنبه و خار و خاشاک و رکوی نیم سوخته . <BR><font color=\"Blue\">◄</font> مطبخی <span class=\"hlight\">:</span> <br />کآفتاب سپهر با همه قدر<br />آتش افروز دیگدان من است .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> هر یک از افراد هیأتی که از چند روز بنوروز مانده تا سیزدهم فروردین برای تفریح و شادمانی مردمان باشکال مضحک درمی آمدند و با ساز و آواز در کوچه ها میگشتند و از مردم چیزی می ستدند. و آن را کوسه گلین نیز می گفتند. و بی شبهه این رسم باقیمانده ٔ رکوب کوسج و میر نوروزی است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آتش افروز</span>؛ جامه های نامتناسب و کوتاه و بلند دربرکرده .<br /><BR><font color=\"Blue\">◄</font> نام مرغی که آن را ققنس گویند. <BR><font color=\"Blue\">◄</font> محضب . مسعر. مسعار. محراک . محرث . محراث . آتش کاو. اسطام . سطام . تنورآشور. چیزی که بدان آتش آشورند. <BR><font color=\"Blue\">◄</font> سوخته ٔ هر چیز که بدان آتش افروزند. (برهان ). <BR><font color=\"Blue\">◄</font> نام ماه یازدهم از سالهای ملکی یزدجردی . (برهان ).<br /></font></div>'),
(494, 'آتش افروزنه', '<span class=\"hlight\">آتش افروزنه .</span> <font color=\"DarkGreen\"><b>[ ت َ اَ زَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) خرده ها از خار و خاشاک که بدان آتش افروزند. فروزینه . آتش افروز. آتش افروزه . آتش افروزینه . آتش گیره . وَقود. گیره . <BR><font color=\"Blue\">◄</font> چخماق . (برهان ).<br /></font></div>'),
(495, 'آتش افروزه', '<span class=\"hlight\">آتش افروزه .</span> <font color=\"DarkGreen\"><b>[ ت َ اَ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ مرکب ) رجوع به آتش افروزنه شود.<br /></font></div>'),
(496, 'آتش افروزی', '<span class=\"hlight\">آتش افروزی .</span> <font color=\"DarkGreen\"><b>[ ت َ اَ ]</font></b> (حامص مرکب ) فعل آتش افروز.<br /></font></div>'),
(497, 'آتش افروزینه', '<span class=\"hlight\">آتش افروزینه .</span> <font color=\"DarkGreen\"><b>[ ت َ اَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) رجوع به آتش افروزنه شود.<br /></font></div>'),
(498, 'آتش انداز', '<span class=\"hlight\">آتش انداز.</span> <font color=\"DarkGreen\"><b>[ ت َ اَ ]</font></b> (نف مرکب ) آنکه در جنگها آتش یا نفط بصف دشمن افکند <span class=\"hlight\">:</span> <br />بهر سو که دو گرد کین ساز بود<br />میانْشان یکی آتش انداز بود.<br /> <font color=\"Red\">اسدی .</font><br /><BR><font color=\"Blue\">◄</font> کسی که افروختن تنور نانوایی با اوست .<br /></font></div>'),
(499, 'آتش انگیز', '<span class=\"hlight\">آتش انگیز.</span> <font color=\"DarkGreen\"><b>[ ت َ اَ ]</font></b> (اِ مرکب ) فروزینه . ذکوة. ذکیه . (حبیش تفلیسی ). <BR><font color=\"Blue\">◄</font> رکو و پنبه و قاو که از چخماق آتش بدان افتد. <BR><font color=\"Blue\">◄</font> (نف مرکب ) مجازاً، گوینده ٔ سخنان تند و خشمناک <span class=\"hlight\">:</span> <br />آن دل شده زآن فسانه شد تیز<br />بگشاد دهان آتش انگیز.<br /><font color=\"Red\">؟</font><br /></font></div>'),
(500, 'آتش باد', '<span class=\"hlight\">آتش باد.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) سَموم . باد گرم .<br /></font></div>'),
(501, 'آتش بار', '<span class=\"hlight\">آتش بار.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (نف مرکب ) آنکه آتش فروریزد <span class=\"hlight\">:</span> <br />هیزم خشک و برق آتش بار<br />مرد خفته ست و دشمن بیدار.<br /> <font color=\"Red\">اوحدی .</font><br /><BR><font color=\"Blue\">◄</font> (اِ مرکب ) باتری . دسته ای از توپها.<br /></font></div>'),
(502, 'آتش باره', '<span class=\"hlight\">آتش باره .</span><font color=\"DarkGreen\"><b>[ ت َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) چخماق . (فرهنگ نعمةاﷲ).<br /></font></div>'),
(503, 'آتش بجان', '<span class=\"hlight\">آتش بجان .</span> <font color=\"DarkGreen\"><b>[ ت َ ب ِ ]</font></b> (اِ مرکب ) غم و سوزش و شوق محبت . (برهان ). و آتش بجان گرفته، نفرینی است .<br /></font></div>'),
(504, 'آتش برزین', '<span class=\"hlight\">آتش برزین .</span> <font color=\"DarkGreen\"><b>[ ت َ ش ِ ب َ ]</font></b> (اِخ ) آذر برزین <span class=\"hlight\">:</span> <br />کسی که آتش برزین ندیده بود بدید<br />رخش چو آتش و زلفش دمیده ریحانش .<br /><font color=\"Red\">سلمان ساوجی .</font><br /></font></div>'),
(505, 'آتش برگ', '<span class=\"hlight\">آتش برگ .</span> <font color=\"DarkGreen\"><b>[ ت َ ب َ ]</font></b> (اِ مرکب ) چخماق . آتش زنه <span class=\"hlight\">:</span> <br />شد آنچنان برطوبت هوا که آتش برگ <br />ز سنگ قطره برون آورد بجای شرار.<br /><font color=\"Red\">حسین ثنائی .</font><br /></font></div>'),
(506, 'آتش بند', '<span class=\"hlight\">آتش بند.</span> <font color=\"DarkGreen\"><b>[ ت َ ب َ ]</font></b>(نف مرکب ) افسون که بدان آتش فرونشیند <span class=\"hlight\">:</span> <br />نسخه ای کز خط تست اندر دل سوزان من <br />سحر آتش بند یا تعویذ تب میخوانمش .<br /><font color=\"Red\">امیرخسرو دهلوی .</font><br /></font></div>'),
(507, 'آتش بی دود', '<span class=\"hlight\">آتش بی دود.</span> <font color=\"DarkGreen\"><b>[ ت َ ش ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) شواظ. <BR><font color=\"Blue\">◄</font> کنایه از آفتاب و قهر و غضب و شراب لعلی . (برهان ). <BR><font color=\"Blue\">◄</font> در بعض فرهنگها مجازاً به معنی لعل و عقیق و یاقوت نیز ضبط شده است .<br /></font></div>'),
(508, 'آتش بید', '<span class=\"hlight\">آتش بید.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) مرکز بلوک هشترود و قوریچای .<br /></font></div>'),
(509, 'آتش تاب', '<span class=\"hlight\">آتش تاب .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (نف مرکب ) گلخنی . تون تاب .<br /></font></div>'),
(510, 'آتش تاو', '<span class=\"hlight\">آتش تاو.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (نف مرکب ) آتش تاب .<br /></font></div>'),
(511, 'آتش خان', '<span class=\"hlight\">آتش خان .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) نام یکی از بزرگان باستانی نصیریان یعنی علی اللهیان . و او را خان آتش نیز گویند.<br /></font></div>'),
(512, 'آتش خانه', '<span class=\"hlight\">آتش خانه .</span> <font color=\"DarkGreen\"><b>[ ت َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) معبد آتش پرستان . آتشکده . آتشگاه . بیت النار. بیت النیران <span class=\"hlight\">:</span> و این آتشخانه را که داریم و خورشید را که داریم نه بدان داریم که گوئیم این را پرستیم اما بجایگاه آن داریم که شما محراب دارید. (تاریخ سیستان ). <BR><font color=\"Blue\">◄</font> مجموع سلاح آتشین از توپ و تفنگ و نظائر آن در فوجی از سپاهی . <BR><font color=\"Blue\">◄</font> آتشخانه ٔ سماور و کشتی و راه آهن ؛ قسمتی که آتش در آن است . و آتشخانه ٔ تفنگ، درون لوله ٔ آن است .<br /></font></div>'),
(513, 'آتش خو', '<span class=\"hlight\">آتش خو.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص مرکب ) آتش خوی . تندخوی .<br /></font></div>'),
(514, 'آتش خوار', '<span class=\"hlight\">آتش خوار.</span> <font color=\"DarkGreen\"><b>[ ت َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (اِ مرکب ) آتش خواره . شترمرغ . نعامه . ظلیم . اشترمرغ . <BR><font color=\"Blue\">◄</font> (نف مرکب ) مجازاً، سخت ستمکار <span class=\"hlight\">:</span> <br />ببَرَد آب عالم ابرار<br />مدحت پادشاه آتش خوار.<br /> <font color=\"Red\">سنائی .</font><br />در بعض فرهنگها معنی سمندر نیز به این کلمه داده و دو بیت ذیل را شاهد آورده اند <span class=\"hlight\">:</span> <br />خسرو است و سوز دل وز ذوق عالم بیخبر<br />مرغ آتش خواره کی لذت شناسد دانه را.<br /> <font color=\"Red\">امیرخسرو دهلوی .</font><br />مرغ آتش خواره جز اخگر نخواهد دانه را.<br /> <font color=\"Red\">عرفی .</font><br />و این سهوی است، چه سمندر مرغ نیست و مراد این دو شاعر از مرغ آتش خوار وآتش خواره همان نعامه و ظلیم است .<br /></font></div>'),
(515, 'آتش خواره', '<span class=\"hlight\">آتش خواره .</span> <font color=\"DarkGreen\"><b>[ ت َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب، اِ مرکب ) رجوع به آتش خوار شود.<br /></font></div>'),
(516, 'آتش خواه', '<span class=\"hlight\">آتش خواه .</span> <font color=\"DarkGreen\"><b>[ ت َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) آنکه ازخانه ٔ همسایه و مانند آن قبس و جذوه ای طلبد گیراندن هیمه یا ذغال و یا چراغ خویش را. قابس <span class=\"hlight\">:</span> <br />ای گشته دلم بی تو چو آتشگاهی <br />وز هر رگ جان من به آتش راهی <br />چون میدانی که در دل آتش دارم <br />ناآمده بگذری چو آتش خواهی .<br /><font color=\"Red\">عطار.</font><br /></font></div>'),
(517, 'آتش خواهی', '<span class=\"hlight\">آتش خواهی .</span> <font color=\"DarkGreen\"><b>[ ت َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (حامص مرکب ) کار و فعل آتش خواه .<br /></font></div>'),
(518, 'آتش دادن', '<span class=\"hlight\">آتش دادن .</span> <font color=\"DarkGreen\"><b>[ ت َ دَ ]</font></b> (مص مرکب ) گشاد دادن و افکندن توپ و امثال آن . <BR><font color=\"Blue\">◄</font> مجازاً، تحریک غضب کسی کردن .<br /></font></div>'),
(519, 'آتش داغ', '<span class=\"hlight\">آتش داغ .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) اثر آتش بر بشره .<br /></font></div>'),
(520, 'آتش دست', '<span class=\"hlight\">آتش دست .</span> <font color=\"DarkGreen\"><b>[ ت َ دَ ]</font></b> (ص مرکب ) جلد و چست در کار.<br /></font></div>'),
(521, 'آتش دستی', '<span class=\"hlight\">آتش دستی .</span> <font color=\"DarkGreen\"><b>[ ت َ دَ ]</font></b> (حامص مرکب ) صفت آتش دست .<br /></font></div>'),
(522, 'آتش دهقان', '<span class=\"hlight\">آتش دهقان .</span> <font color=\"DarkGreen\"><b>[ ت َ ش ِ دِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آتشی است که دهقانان پس از حصاد بر بازمانده ٔ کشت زنند تا زمین قوت گیرد <span class=\"hlight\">:</span> <br />فلک چون آتش دهقان زبان کین کشد بر من <br />که بر ملک مسیحم هست مساحی و دهقانی .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(523, 'آتش رنگ', '<span class=\"hlight\">آتش رنگ .</span> <font color=\"DarkGreen\"><b>[ ت َ رَ ]</font></b> (ص مرکب ) سخت سرخ <span class=\"hlight\">:</span> <br />هست یکدانه لعل آتش رنگ <br />بهتراز صدهزار خرمن سنگ .<br /> <font color=\"Red\">مکتبی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب آتش رنگ </span> ؛ مجازاً، شراب <span class=\"hlight\">:</span> <br />برحذر باش زآب آتش رنگ <br />که تفش اژدها است، تاب نهنگ .<br /><font color=\"Red\">اوحدی .</font><br /></font></div>'),
(524, 'آتش روشن کردن', '<span class=\"hlight\">آتش روشن کردن .</span> <font color=\"DarkGreen\"><b>[ ت َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رُو ش َ ک َ دَ ]</font></b> (مص مرکب ) افروختن آتش . <BR><font color=\"Blue\">◄</font> مجازاً، انگیختن فتنه و فساد.<br /></font></div>'),
(525, 'آتش زا', '<span class=\"hlight\">آتش زا.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (نف مرکب ) که آتش تولید کند.<br /></font></div>'),
(526, 'آتش زاد', '<span class=\"hlight\">آتش زاد.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ن مف مرکب <span class=\"hlight\" dir=\"rtl\">/</span> ص مرکب ) که از آتش زاده است .<br /></font></div>'),
(527, 'آتش زبان', '<span class=\"hlight\">آتش زبان .</span> <font color=\"DarkGreen\"><b>[ ت َ زَ ]</font></b> (ص مرکب ) تیز و تند زبان <span class=\"hlight\">:</span> <br />سعدی آتش زبانم وز غمت سوزان چو شمع<br />با همه آتش زبانی در تو گیراییم نیست .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(528, 'آتش زدن', '<span class=\"hlight\">آتش زدن .</span> <font color=\"DarkGreen\"><b>[ ت َ زَدَ ]</font></b> (مص مرکب ) آتش اندرزدن . سوزانیدن <span class=\"hlight\">:</span> <br />بفرمود تا آتش اندرزدند<br />همه شهر توران بهم برزدند.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آتش زدن در مالی </span> ؛ بگزاف صرف کردن آن، و یا فروختن آن بثمن بخس .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آتش زدن کسی را</span> ؛ او را خشمگین کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">موی کسی را آتش زده بودن </span> ؛ درست بوقت رسیدن او.<br /></font></div>'),
(529, 'آتش زنه', '<span class=\"hlight\">آتش زنه .</span> <font color=\"DarkGreen\"><b>[ ت َ زَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) چیزی که با آن بسودن و اصطکاک آتش پدید آرند، خواه از دو چوب باشد که زبرین را زند و زیرین را زنده گویند، و خواه از آهن و سنگ بود که آن را سنگ و چخماق خوانند. زند و زنده . قداحه . مقدحه . چخماق <span class=\"hlight\">:</span> <br />ای خداوندی که روز خشم تو از بیم تو<br />درجهد آتش بسنگ آتش و آتش زنه .<br /> <font color=\"Red\">منوچهری .</font><br />گوییش پنهان زنم آتش زنه <br />نی بقلب از قلب باشد روزنه .<br /> <font color=\"Red\">مولوی .</font><br />آتش زنه و سوخته و سنگ بهم <br />کی درگیرد چو سوخته دارد نم <br />نزدیکی و دوریت بلائی است عظیم <br />دوری ز تو کافری و نزدیکی هم .<br /> <font color=\"Red\">افضل الدین کاشانی .</font><br /><BR><font color=\"Blue\">◄</font> آتش گیره . فروزینه . شبوب .<br /></font></div>'),
(530, 'آتش سرخ کن', '<span class=\"hlight\">آتش سرخ کن .</span> <font color=\"DarkGreen\"><b>[ ت َ س ُ ک ُ ]</font></b> (اِ مرکب ) جوّاله . آتش گردان .<br /></font></div>'),
(531, 'آتش سری', '<span class=\"hlight\">آتش سری .</span> <font color=\"DarkGreen\"><b>[ ت َ س َ ]</font></b> (حامص مرکب ) غضب بسیار. خشم سخت . نابردباری <span class=\"hlight\">:</span> <br />مکن تیزمغزی و آتش سری <br />نه زینسان بود مهتر لشکری .<br /> <font color=\"Red\">فردوسی .</font><br />بگودرز فرمود پس شهریار <font color=\"DarkGreen\"><b>[ کیخسرو ]</font></b><br />که رفتی کمربسته ٔ کارزار<br />چو لشکر سوی مرز توران بری <br />مکن تیز دل را به آتش سری .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(532, 'آتش سوز', '<span class=\"hlight\">آتش سوز.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) آتش سوزان . حریق . (دهار) <span class=\"hlight\">:</span> <br />بر آتش سوز گردآید همه کس <br />تو بر فریاد آتش سوز من رس .<br /><font color=\"Red\">(ویس و رامین ).</font><br /></font></div>'),
(533, 'آتش سگ', '<span class=\"hlight\">آتش سگ .</span> <font color=\"DarkGreen\"><b>[ ت َ ش ِس َ ]</font></b> (ترکیب اضافی، اِ مرکب ) نام گیاهی است دوائی وآن را بتازی بنفسج الکلاب خوانند. (برهان ). برنوف . ظاهراً این کلمه مصحف تس سگ است . رجوع به تس سگ شود.<br /></font></div>'),
(534, 'آتش سیر', '<span class=\"hlight\">آتش سیر.</span> <font color=\"DarkGreen\"><b>[ ت َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (ص مرکب ) تندرو.<br /></font></div>'),
(535, 'آتش شناسی', '<span class=\"hlight\">آتش شناسی .</span> <font color=\"DarkGreen\"><b>[ ت َش ْ، ش ِ ]</font></b> (حامص مرکب ) مبحث آتش و خواص آن .<br /></font></div>'),
(536, 'آتش طبع', '<span class=\"hlight\">آتش طبع.</span> <font color=\"DarkGreen\"><b>[ ت َ طَ ]</font></b> (ص مرکب ) تند. تندخو.<br /></font></div>'),
(537, 'آتش طور', '<span class=\"hlight\">آتش طور.</span> <font color=\"DarkGreen\"><b>[ ت َ ش ِ ]</font></b> (اِخ ) آتشی که بر موسی تجلی کرد بطور.<br /></font></div>'),
(538, 'آتش عنان', '<span class=\"hlight\">آتش عنان .</span> <font color=\"DarkGreen\"><b>[ ت َ ع ِ ]</font></b> (ص مرکب ) تند (سوار).<br /></font></div>'),
(539, 'آتش فارسی', '<span class=\"hlight\">آتش فارسی .</span> <font color=\"DarkGreen\"><b>[ ت َ ش ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به آتش پارسی شود.<br /></font></div>'),
(540, 'آتش فام', '<span class=\"hlight\">آتش فام .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص مرکب ) برنگ آتش .<br /></font></div>'),
(541, 'آتش فرازه', '<span class=\"hlight\">آتش فرازه .</span> <font color=\"DarkGreen\"><b>[ ت َ ف َ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ مرکب ) آتش افرازه .<br /></font></div>'),
(542, 'آتش فروز', '<span class=\"hlight\">آتش فروز.</span> <font color=\"DarkGreen\"><b>[ ت َ ف ُ ]</font></b> (نف مرکب ) آتش افروز <span class=\"hlight\">:</span> <br />پس آنگاه فرمود پرمایه شاه <br />که بر چوب ریزند نفت سیاه <br />بیامد دوصد مرد آتش فروز<br />دمیدند و گفتی شب آمد بروز.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(543, 'آتش فروزنه', '<span class=\"hlight\">آتش فروزنه .</span> <font color=\"DarkGreen\"><b>[ ت َ ف ُ زَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) چیزی که بدان آتش افروزند. سوخته . شَبوب .<br /></font></div>'),
(544, 'آتش فشان', '<span class=\"hlight\">آتش فشان .</span> <font color=\"DarkGreen\"><b>[ ت َ ف َ<span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (نف مرکب ) آن چیز یا آن کس که آتش افشاند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طیاره ٔ آتش فشان </span> ؛ کشتی که با آن نفت و آتش بدشمن می افکندند <span class=\"hlight\">:</span> <br />مرکبی دریاکش و طیاره ای آتش فشان <br />گه نشیب و گه فراز و گاه وصل و گاه نای .<br /> <font color=\"Red\">منوچهری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کوه آتش فشان و آتش افشان </span> ؛ کوهی که از دهانه ٔ آن آب سیه و آتش و خاکستر سوزان بیرون جهد. بُرْکان .<br /></font></div>'),
(545, 'آتش فشانی', '<span class=\"hlight\">آتش فشانی .</span> <font color=\"DarkGreen\"><b>[ ت َ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (حامص مرکب ) فعل آتش فشان .<br /></font></div>'),
(546, 'آتش مزاج', '<span class=\"hlight\">آتش مزاج .</span> <font color=\"DarkGreen\"><b>[ ت َ م ِ ]</font></b> (ص مرکب ) تندخو.<br /></font></div>'),
(547, 'آتش موسی', '<span class=\"hlight\">آتش موسی .</span> <font color=\"DarkGreen\"><b>[ ت َ ش ِ سا ]</font></b> (اِخ ) آتشی که بر موسی علیه السلام تجلی کرد. آتش طور <span class=\"hlight\">:</span> <br />یعنی بیا که آتش موسی نمود گل <br />تا از درخت نکته ٔ توحید بشنوی .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(548, 'آتش ناک', '<span class=\"hlight\">آتش ناک .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص مرکب ) آتشین <span class=\"hlight\">:</span> <br />با دل سنگینت آیا هیچ درگیرد شبی <br />آه آتشناک و سوز سینه ٔ شبگیر ما؟<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آتشناک کردن آتش زنه </span> ؛بیرون کردن آتش از وی : اوری الزند؛ آتش ناک کرد آتش زنه را. (زمخشری ).<br /></font></div>'),
(549, 'آتش نشان', '<span class=\"hlight\">آتش نشان .</span> <font color=\"DarkGreen\"><b>[ ت َ ن ِ ]</font></b> (نف مرکب ) کارگری که مأمور اطفاء و فرونشاندن آتش است .<br /></font></div>'),
(550, 'آتش نشاندن', '<span class=\"hlight\">آتش نشاندن .</span> <font color=\"DarkGreen\"><b>[ ت َ ن ِ دَ ]</font></b> (مص مرکب ) کشتن آتش و اطفاء آن <span class=\"hlight\">:</span> آتش نشاندن و اخگر گذاشتن کار خردمندان نیست . (گلستان ).<br /></font></div>'),
(551, 'آتش نشانی', '<span class=\"hlight\">آتش نشانی .</span> <font color=\"DarkGreen\"><b>[ ت َ ن ِ ]</font></b> (حامص مرکب ) فعل آتش نشان . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) مجموع دستگاه و مأمورین فرونشاندن آتش در شهر یا قریه ای .<br /></font></div>'),
(552, 'آتش نعل', '<span class=\"hlight\">آتش نعل .</span> <font color=\"DarkGreen\"><b>[ ت َ ن َ ]</font></b> (ص مرکب ) تندرو (اسب ).<br /></font></div>'),
(553, 'آتش نفس', '<span class=\"hlight\">آتش نفس .</span> <font color=\"DarkGreen\"><b>[ ت َ ن َ ف َ ]</font></b> (ص مرکب ) پُرشور <span class=\"hlight\">:</span> <br />آتش نفسان قیمت میخانه شناسند<br />افسرده دلان را به خرابات چه کار است ؟<br /><font color=\"Red\">عمعق .</font><br /></font></div>'),
(554, 'آتش نمرود', '<span class=\"hlight\">آتش نمرود.</span> <font color=\"DarkGreen\"><b>[ ت َ ش ِ ن َ ]</font></b> (اِخ ) آتشی بزرگ که نمرود فرمانروای بابل برافروخت و حضرت ابراهیم خلیل اﷲ را در آن افکند و آتش بر آن حضرت بَرْد و سلام شد. رجوع به نمرود شود.<br /></font></div>'),
(555, 'آتش نهاد', '<span class=\"hlight\">آتش نهاد.</span> <font color=\"DarkGreen\"><b>[ ت َ ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ]</font></b> (ص مرکب )آنکه طبع آتش دارد. آنکه برنگ آتش است <span class=\"hlight\">:</span> <br />چو گلبن از تن آتش نهاد عکس افکند<br />بشاخ او بر دُرّاج شد ابستاخوان .<br /><font color=\"Red\">خسروانی .</font><br /></font></div>'),
(556, 'آتش هماردبیره', '<span class=\"hlight\">آتش هماردبیره .</span> <font color=\"DarkGreen\"><b>[ ت َ هََ دَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) دبیری آتش شماری . کتابت حسبانات آتشکده ها. (مفاتیح ).<br /></font></div>'),
(557, 'آتش وار', '<span class=\"hlight\">آتش وار.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص مرکب ) مانند آتش . زود بالاگیرنده و زود فرونشیننده <span class=\"hlight\">:</span> اسکندر مردی بود که آتش وار سلطانی وی نیرو گرفت و بر بالا شد روزی چند سخت اندک و پس خاکستر شد. (تاریخ بیهقی ).<br /></font></div>'),
(558, 'آتش پا', '<span class=\"hlight\">آتش پا.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص مرکب ) مجازاً تندرو. دوان <span class=\"hlight\">:</span> <br />باز در بستندش و آن درپرست <br />بر همان امید آتش پا شده ست .<br /> <font color=\"Red\">مولوی .</font><br />جنیبت بس که آتش پای گشته <br />هلال نعل پروین سای گشته .<br /><font color=\"Red\">امیرخسرو دهلوی .</font><br /></font></div>'),
(559, 'آتش پارسی', '<span class=\"hlight\">آتش پارسی .</span> <font color=\"DarkGreen\"><b>[ ت َ ش ِ ]</font></b>(ترکیب وصفی، اِ مرکب ) تبخال و تبخاله <span class=\"hlight\">:</span> <br />دید مرا گرفته لب آتش پارسی ز تب <br />نطق من آب تازیان برده بنکته ٔ دری .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> نام مرضی که آن را نار پارسی گویند و این مرض همان جمره است یا مرض دیگر نزدیک بدان، و آن بثره ٔ چند است بسیار سوزان و با درد شدید و در اوایل چرکی و زردابی با او همراه و جوشش وشور و پخته شدن آن بدیگر بثور شبیه نیست و لون آن بزردی مایل است و خداوند این مرض غالباً با حرارت و تب میباشد و علاج آن بدفع صفرا و ضمادهای خنک و غذاهای مرطوب باید کردن و این غیر از آتشک است که بنار فرنگ و آتشک فرنگ معروف است . (نقل به اختصار از فرهنگ سروری ). جمره . نار فارسیه <span class=\"hlight\">:</span> <br />نترسم ز خصمان اگر برطپند<br />کزین آتش پارسی در تبند.<br /> <font color=\"Red\">سعدی .</font><br />از آتش پارسی روان سوزتر است <br />این عشق که از خاک خراسان آورد.<br /><font color=\"Red\">؟ (از سروری ).</font><br /></font></div>'),
(560, 'آتش پاره', '<span class=\"hlight\">آتش پاره .</span> <font color=\"DarkGreen\"><b>[ ت َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) اخگر. سکار. بجال . جمره . جذوه . قبس . <BR><font color=\"Blue\">◄</font> کرم شب تاب . <BR><font color=\"Blue\">◄</font> (ص مرکب ) مجازاً، سخت جافی و ستمکار <span class=\"hlight\">:</span> <br />عقل و جانم برد شوخی آفتی عیاره ای <br />باددستی خاکیی بی آبی آتش پاره ای .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> داهی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آتش پاره </span> ؛ کودکی سخت بی آرام و شریر و شوخ .<br /><BR><font color=\"Blue\">◄</font> چابک و چربدست .<br /></font></div>'),
(561, 'آتش پرست', '<span class=\"hlight\">آتش پرست .</span> <font color=\"DarkGreen\"><b>[ ت َ پ َ رَ ]</font></b> (نف مرکب ) آنکه آتش را چون قبله ای نیایش کند <span class=\"hlight\">:</span> <br />همه کسی صنما <font color=\"DarkGreen\"><b>[ مر ]</font></b> ترا پرستد و ما<br />از آتش دل آتش پرست شاماریم .<br /> <font color=\"Red\">منطقی (از فرهنگ اسدی، خطی ).</font><br />بیک هفته بر پیش یزدان بدند<br />مپندار کآتش پرستان بدند<br />که آتش بدانگاه محراب بود<br />پرستنده را دیده پرآب بود.<br /> <font color=\"Red\">فردوسی .</font><br />(آنگاه که کیکاوس و کیخسرو برای دعا به آتشکده ٔ آذرگشنسب رفته بودند) .<br />بهر برزنی بر دبستان بدی <br />همان جای آتش پرستان بدی .<br /> <font color=\"Red\">فردوسی .</font><br />بکردار نیکان ستایش کنیم <br />چو آتش پرستان نیایش کنیم .<br /> <font color=\"Red\">فردوسی .</font><br />یکی دین دهقان آتش پرست <br />که بی باژ بَرْسَم نگیرد بدست .<br /> <font color=\"Red\">فردوسی .</font><br />بدو داد مهتر بفرمان اوی <br />برآیین آتش پرستان اوی .<br /> <font color=\"Red\">فردوسی .</font><br />هنوزم هندوان آتش پرستند<br />هنوزم چشم چون ترکان مستند.<br /> <font color=\"Red\">نظامی .</font><br />و سعدی آتش پرست را با بت پرست خلط فرموده و گفته است :<br />مغی در بروی از جهان بسته بود<br />بتی را بخدمت میان بسته بود...<br />که سرگشته ٔ دون آتش پرست <br />هنوزش سر از خمر بتخانه مست .<br />و مرادف آن آذرپرست است، و شعرا گبر، مغ، موغ و مجوسی را نیز به معنی آتش پرست استعمال کرده اند. <BR><font color=\"Blue\">◄</font> بمعنی سادن و پرستار آتش نیز آمده است <span class=\"hlight\">:</span> <br />چنان دید در خواب کآتش پرست <br />سه آتش فروزان ببردی بدست .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(562, 'آتش پرستی', '<span class=\"hlight\">آتش پرستی .</span> <font color=\"DarkGreen\"><b>[ ت َ پ َ رَ ]</font></b> (حامص مرکب ) فعل آتش پرست . <BR><font color=\"Blue\">◄</font> دین آتش پرست <span class=\"hlight\">:</span> <br />چو شب رفت و بر دشت پستی گرفت <br />هوا چون مغ آتش پرستی گرفت ...<br /><font color=\"Red\">عنصری .</font><br /></font></div>'),
(563, 'آتش پیکر', '<span class=\"hlight\">آتش پیکر.</span><font color=\"DarkGreen\"><b>[ ت َ پ َ <span class=\"hlight\" dir=\"rtl\">/</span> پ ِ ک َ ]</font></b> (اِ مرکب ) مجازاً، شیطان و جن .<br /></font></div>'),
(564, 'آتش چرخان', '<span class=\"hlight\">آتش چرخان .</span> <font color=\"DarkGreen\"><b>[ ت َ چ َ ]</font></b> (اِ مرکب ) جواله . آتشگردان . آتش سرخ کن .<br /></font></div>'),
(565, 'آتش کار', '<span class=\"hlight\">آتش کار.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص مرکب ) آنکه در شغل و پیشه ٔ خویش مباشرت با آتش دارد همچون گلخنی و مطبخی و آهنگر و مانند آن . <BR><font color=\"Blue\">◄</font> مجازاً، خشمگین و شتاب زده و بدکار. (برهان ).<br /></font></div>'),
(566, 'آتش کاری', '<span class=\"hlight\">آتش کاری .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (حامص مرکب ) فعل و عمل آتش کار.<br /></font></div>'),
(567, 'آتش کاو', '<span class=\"hlight\">آتش کاو.</span> <font color=\"DarkGreen\"><b>[ت َ ]</font></b> (اِ مرکب ) آلتی از آهن و جز آن که آتش را بدان آشورند. محراث . مسعار. سطام . اسطام . محراک . انبر.<br /></font></div>'),
(568, 'آتش کردن', '<span class=\"hlight\">آتش کردن .</span> <font color=\"DarkGreen\"><b>[ ت َ ک َ دَ ]</font></b> (مص مرکب ) افروختن آتش . تأجیج .<br /></font></div>'),
(569, 'آتش کش', '<span class=\"hlight\">آتش کش .</span> <font color=\"DarkGreen\"><b>[ ت َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (اِ مرکب ) افزاری که بدان آتش در تنور آشورند.<br /></font></div>'),
(570, 'آتش کشیدن', '<span class=\"hlight\">آتش کشیدن .</span> <font color=\"DarkGreen\"><b>[ ت َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) به آتش کشیدن . آتش کشیدن جائی را؛ سخت ببیدادی ویران کردن آن .<br /></font></div>'),
(571, 'آتش گر', '<span class=\"hlight\">آتش گر.</span> <font color=\"DarkGreen\"><b>[ ت َ گ َ ]</font></b> (ص مرکب ) خالق آتش <span class=\"hlight\">:</span> <br />خورشید صانع است مر آتش را<br />بشناس زآتش ای پسر آتش گر.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(572, 'آتش گردان', '<span class=\"hlight\">آتش گردان .</span> <font color=\"DarkGreen\"><b>[ ت َ گ َ ]</font></b> (اِ مرکب ) جوّاله . آتش سرخ کن .<br /></font></div>'),
(573, 'آتش گون', '<span class=\"hlight\">آتش گون .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص مرکب ) ارغوانی . ارجوانی . احمر. قانی <span class=\"hlight\">:</span> <br />ساقیا یک جرعه ای زآن آب آتش گون که من <br />در میان پختگان عشق او خامم هنوز.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(574, 'آتش گیر', '<span class=\"hlight\">آتش گیر.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (نف مرکب ) آتش انداز (در نانوائی ).<br /></font></div>'),
(575, 'آتش گیرانه', '<span class=\"hlight\">آتش گیرانه .</span> <font color=\"DarkGreen\"><b>[ ت َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) در تداول عامه، فروزینه .<br /></font></div>'),
(576, 'آتش گیره', '<span class=\"hlight\">آتش گیره .</span> <font color=\"DarkGreen\"><b>[ ت َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) آتش افروزنه <span class=\"hlight\">:</span> <br />شه آتشدان و آتش گیره این مشت عوان خس <br />که بهر خانمانها سوختن باشند اعوانش .<br /> <font color=\"Red\">جامی .</font><br /><BR><font color=\"Blue\">◄</font> چخماق .<br /></font></div>'),
(577, 'آتشبازی', '<span class=\"hlight\">آتشبازی .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) ترکیباتی از باروت و اجزاء دیگر که در جشنهاو شادیها بصور و اشکال گوناگون افروزند و افکنند.<br /></font></div>'),
(578, 'آتشبان', '<span class=\"hlight\">آتشبان .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص مرکب، اِ مرکب ) سادن آتشکده . <BR><font color=\"Blue\">◄</font> شیطان و دیو. <BR><font color=\"Blue\">◄</font> مالک دوزخ . زبنیة (مفرد زبانیة).<br /></font></div>'),
(579, 'آتشت', '<span class=\"hlight\">آتشت .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) نام محلی میان قلعه ٔ مندیش و کوهتیز به نزدیک ی کوژ.<br /></font></div>'),
(580, 'آتشدان', '<span class=\"hlight\">آتشدان .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) کانون . کانونه . اجاق . منقل : فرمودند من از قصر عارفان روان شدم شما دیگ بر آتشدان نهادید. (انیس الطالبین بخاری ).<br />دو گوهر است در این وقت شرط مجلس ما<br />قنینه معدن این و تنور مسکن آن <br />یکی چو آب زر اندر میان جام و قدح <br />یکی چو برگ گل اندر میان آتشدان .<br /> <font color=\"Red\">معزی .</font><br />دیگپایه . دیگدان . تنور. تنوره . کور. کوره . تنور آهنگر. کلانه ٔ آهنگر. (مقدمةالادب ): سطام ؛ کفچه ٔ آتشدان . (السامی فی الاسامی ). <BR><font color=\"Blue\">◄</font> (اِخ ) محراب . ببغاء. مجمره . (از ابوریحان بیرونی ).<br /></font></div>'),
(581, 'آتشه', '<span class=\"hlight\">آتشه .</span> <font color=\"DarkGreen\"><b>[ ت َ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِ) برق . آدرخش .<br /></font></div>'),
(582, 'آتشک', '<span class=\"hlight\">آتشک .</span> <font color=\"DarkGreen\"><b>[ ت َ ش َ ]</font></b> (اِ مرکب ) کرمکی خرد که بشب چون چراغ تابد و آن را شب چراغ و شب چراغک و شب تاب و چراغله نیز گویند و به عربی یراعه و ولدالزنا خوانند. <BR><font color=\"Blue\">◄</font> برق . آدرخش . <BR><font color=\"Blue\">◄</font> آبله ٔ فرنگ . نار افرنجیه . ارمنی دانه . کوفت . سیفیلیس . آتشک فرنگ .<br /></font></div>'),
(583, 'آتشکده', '<span class=\"hlight\">آتشکده .</span> <font color=\"DarkGreen\"><b>[ ت َ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) پرستشگاه مغان و جای آتش افروختن . بیت النار. بیت النیران . آتشگاه <span class=\"hlight\">:</span> <br />ای آنکه من از عشق تو اندر جگر خویش <br />آتشکده دارم سد و بر هر مژه ای ژی .<br /> <font color=\"Red\">رودکی .</font><br />بگه رفتن کآن ترک من اندر زین شد<br />دل من زآن زین آتشکده ٔبرزین شد.<br /> <font color=\"Red\">ابوشکور.</font><br />اندر خره <font color=\"DarkGreen\"><b>[ بناحیت پارس ]</font></b> یکی آتشکده است که آن را بزرگ دارند و زیارت کنند و بنیاداو را دارا نهاده است . (حدودالعالم ). و اندر کاریان بناحیت پارس آتشکده ای است که آن را بزرگ دارند. (حدودالعالم ). اندر بشاورد بناحیت پارس دو آتشکده است که آن را زیارت کنند. (حدودالعالم ). و اندر وی <font color=\"DarkGreen\"><b>[ کازرون پارس ]</font></b> دو آتشکده است که آن را بزرگ دارند. (حدودالعالم ).<br />بیامد خروشان به آتشکده <br />غمی شد از آن روزهای شده .<br /> <font color=\"Red\">فردوسی .</font><br />چو شد ساخته کار آتشکده <br />همان جای نوروز و جشن سده .<br /> <font color=\"Red\">فردوسی .</font><br /> <br />گویند پارسیان هفت آتشکده ٔ معتبر بعدد هفت کوکب سیار داشته اند و نامهای آنها بدین قرار بوده است : آذرمهر. آذرنوش . آذر بهرام . آذرآیین . آذرخرین . آذر برزین . آذر زردشت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آتشکده </span> ؛ پرخشم . غضبناک <span class=\"hlight\">:</span> <br />سر و مغز کاوس آتشکده ست <br />همان نامه و جنگ او بیهده ست .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(584, 'آتشکی', '<span class=\"hlight\">آتشکی .</span> <font color=\"DarkGreen\"><b>[ ت َ ش َ ]</font></b> (ص نسبی ) مبتلی به آتشک . <BR><font color=\"Blue\">◄</font> دشنامی است در تداول زنان .<br /></font></div>'),
(585, 'آتشگاه', '<span class=\"hlight\">آتشگاه .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) نام قلعه ای بوده است محکم به ترشیز. (نزهةالقلوب ). <BR><font color=\"Blue\">◄</font> نام محلی در مغرب باکو بفاصله ٔ پانزده هزار گز، و ایرانیان را در قدیم چندین آتشکده ٔ معروف در آنجا بوده است . در این محل چاه نفتی است با دهانه ٔ بیضی بطول چهل گز که پیوسته در حال احتراق است و شعله های آتش از آن بیرون آید و گاه تا شش گز بالا رود. در اطراف این محل هر کجا زمین را گود کنند نفت در آن جمعشود، و چون کبریتی نزدیک زمین آتش زنند درحال زمین مشتعل گردد. <BR><font color=\"Blue\">◄</font> نام محلی کنار راه اصفهان بنجف آباد میان کلادان و امیریه به <span class=\"hlight\" dir=\"rtl\">٧٣٠٠</span> گزی اصفهان .<br /></font></div>'),
(586, 'آتشگاه', '<span class=\"hlight\">آتشگاه .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) بیت النار. (السامی فی الاسامی ). آتشکده . معبد آتش پرستان <span class=\"hlight\">:</span> کیخسرو آنجا شد <font color=\"DarkGreen\"><b>[ به آتشگاه کرکو]</font></b> و پلاس پوشید و دعا کرد ایزد تعالی آنجا روشنائی فرا دید آورد که اکنون آتشگاه است . (تاریخ سیستان ). وآنجایگه که اکنون آتشگاه کرکوی است معبدجای گرشاسب بود. (تاریخ سیستان ). جهودان را نیز کنشت است و ترسایان را کلیسا و گبرکان را آتشگاه . (تاریخ سیستان ).<br />از فراوان طپش غم که مرا در دل بود<br />گفتی اندر دل من ساخته اند آتشگاه .<br /> <font color=\"Red\">فرخی .</font><br />و اسفندیار بفرمان پدر آن را از بتان خالی کرد و آتشگاه کرد. (مجمل التواریخ ).<br />نفسم سرد و سینه آتشگاه <br />دهنم خشک و دیده طوفان بار.<br /> <font color=\"Red\">انوری .</font><br />ای گشته دلم بی تو چو آتشگاهی <br />وز هر رگ جان من به آتش راهی <br />چون میدانی که در دل آتش دارم <br />ناآمده بگذری چو آتش خواهی .<br /><font color=\"Red\">عطار.</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(587, 'آتشگه', '<span class=\"hlight\">آتشگه .</span><font color=\"DarkGreen\"><b>[ ت َ گ َه ْ ]</font></b> (اِ مرکب ) آتشگاه . آتشکده <span class=\"hlight\">:</span> <br />چنین بود رسم اندر آن روزگار<br />که باشد در آتشگه آموزگار.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(588, 'آتشی', '<span class=\"hlight\">آتشی .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ) نام قسمی گل و شاید سوری <span class=\"hlight\">:</span> <br />بر گلبنان گنبد اخضر نهاد او<br />گلهای گونه گونه ز خیری و آتشی .<br /> <font color=\"Red\">؟ (از مقامات حمیدی ).</font><br /><BR><font color=\"Blue\">◄</font> (ص نسبی ) برنگ آتش . منسوب به آتش . و مثلثه یا بروج آتشی حمل و اسد و قوس است . <BR><font color=\"Blue\">◄</font> مجازاً، سخت خشمگین و غضبناک . سخت بهیجان آمده . سخت تیز و تند شده . و فعل آن آتشی شدن و آتشی کردن است .<br /></font></div>'),
(589, 'آتشیزه', '<span class=\"hlight\">آتشیزه .</span> <font color=\"DarkGreen\"><b>[ ت َ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ مرکب ) (از: آتش + -یزه، پسوند تصغیر) آتشک . کرم شبتاب .<br /></font></div>'),
(590, 'آتشین', '<span class=\"hlight\">آتشین .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص نسبی ) آتشی . از آتش . منسوب به آتش .<br /></font></div>'),
(591, 'آتل', '<span class=\"hlight\">آتل .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) نام رودیست بس بزرگ که از کوههای آس و بلغار خیزد و بدریای خزر ریزد. گویند که از آن رود بزرگتر در جهان نیست چنانکه بیش از هفتاد نهر از آن جداشود، اسب از هیچیک به آسانی گذر نیابد <span class=\"hlight\">:</span> <br />گر سوی قندز مژگان نرسد آتل اشک <br />ره قندز سوی آتل بخزر بگشایید.<br /> <font color=\"Red\">خاقانی .</font><br />فرهنگهای فارسی آنچه درباره ٔ آتل نوشته اند خلاصه اش این است که ذکر شد. و صاحب حدودالعالم در چند جا اسم از این رود میبرد و نیز آن را نام شهری بر ساحل همین رود میداند <span class=\"hlight\">:</span> آتل رودی است بر شمال غوز. (حدودالعالم ). نام رودی است که در ناحیت خزران بر میان شهری که نیز آتل نامیده می شود گذرد. (حدودالعالم ). آتل رودی است در جنوب کیماک . (حدود العالم ). آتل نام شهری است از ناحیت خزران که رودی موسوم به همین نام از میان وی گذرد و قصبه ٔ خزران است و مستقر پادشاه است و او را طرخان خاقان خوانند و از فرزندان انسانست (کذا) و اندر نیمه ٔ مغربی نشیند از این شهر، و این نیمه باره ای دارد. و اندر این نیمه ٔ دیگر مسلمانان و بت پرستانند و این پادشاه را هفت حاکم است اندر این شهر از هفت دین مختلف بهر ساعتی . چون داوری بزرگتر افتد از پادشاه دستوری خواهند یا آگه کنند بحکم آن داوری . (حدودالعالم ). و دیگر رود ارتشت هم از این کوه <font color=\"DarkGreen\"><b>[ از آن کوه که اندر حد میان کیماک است و خرخیز ]</font></b> گشاید آبی است بزرگ و سیاه لیکن خوردنی است و شیرین است و اندر میانه ٔ غوز وکیماک برود تا به ده جوبین رسد از کیماک آنگه اندر رود آتل افتد. و دیگر رود آتل که هم از این کوه گشاید از شمال اَرْتَش رودی است عظیم و فراخ و اندر میانه ٔ کیماکیان همی رود تا به ده جوبین رسد آنگه اندر حد میان غوز و کیماک همی رود روی بمغرب کرده تا بر بلغار بگذرد آنگه عطف کند و سوی جنوب اندر بجناک ترک وبرطاس بگذرد و اندر میانه ٔ شهر آتل از حد خزران برود آنگه بدریای خزران افتد. (حدودالعالم ). و دیگر بیابانی است مشرق وی بر حدود مرو بگذرد تا بجیحون رسد جنوب وی بر حدود باورد و نسا و فراو و دهستان و دریای خزران بگذرد تا بحدود آتل و مغرب وی رود آتل است و شمال او رود جیحون است و دریای خوارزم و حدود غوز تابحد بلغار و این بیابان را بیابان خوارزم و غوز خوانند. (حدودالعالم ). ناحیت غوز ناحیتی است مشرق وی بیابان غوز و شهرهای ماوراءالنهر و جنوب بعضی هم از این بیابان و دیگر دریای خزران است و مغرب و شمال او رود آتل است (حدودالعالم ). یغسویام سو، ناحیتی دیگر است از کیماک میان رود آتل و میان رود ارتش و مردمانی بیشتر با نعمت و کاری ساخته تر دارند. (حدودالعالم ). ناحیت خزران ناحیتی است مشرق وی دیواری است میان کوه و دریا و دیگر دریاست و بعضی از رود آتل و جنوب وی سریر است و مغربش کوه است و شمالش یراذاس است و نندز. (حدودالعالم ). بعض از جغرافیانویسان معاصر آتل را رود ولگا دانند و نیز محتمل است اورال باشد، واﷲ اعلم .<br /></font></div>'),
(592, 'آتلانتید', '<span class=\"hlight\">آتلانتید.</span> (اِخ ) در اساطیر قدما نام برّی واقع در محلی که اکنون دریای آتلانتیک واقع است .<br /></font></div>'),
(593, 'آتلانتیک', '<span class=\"hlight\">آتلانتیک .</span> (اِخ ) دریایی وسیع میان اروپا و افریقا و امریکا.<br /></font></div>'),
(594, 'آتم', '<span class=\"hlight\">آتم .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (فرانسوی، اِ) اَتُم . رجوع به جزء لایتجزی شود.<br /></font></div>'),
(595, 'آتن', '<span class=\"hlight\">آتن .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (ع اِ) ج ِ اَتان .<br /></font></div>'),
(596, 'آتن', '<span class=\"hlight\">آتن .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) کرسی آتیک و شهر بزرگ یونان قدیم . در <span class=\"hlight\" dir=\"rtl\">٤٨٠</span> ق .م . خشایارشا پادشاه ایران این شهر راتسخیر کرد. رجال سیاسی و فیلسوفان و نویسندگان و هنرمندان نامی و بزرگ از آن برخاسته اند و امروز نیز پایتخت یونان است . آطنه . اثینه . آتنه . مدینةالحکماء.<br /></font></div>'),
(597, 'آتو', '<span class=\"hlight\">آتو.</span>(فرانسوی، اِ) (از: آ، به + تو، همه ) رنگی یا صورتی معلوم از اوراق گنجفه و آس و مانند آن که با قراردادی از رنگهای دیگر برد.<br /></font></div>'),
(598, 'آتور', '<span class=\"hlight\">آتور.</span> (اِخ ) آثور. بعقیده ٔ مصریان قدیم نام رب النوع دریا و زوجه یا خواهر «فتا» رب النوع آتش .<br /></font></div>'),
(599, 'آتون', '<span class=\"hlight\">آتون .</span> (اِ) کدبانویی که دخترکان را تعلیم خواندن و دوختن دهد. معلمه . <BR><font color=\"Blue\">◄</font> مشیمه . زهدان . بچه دان .<br /></font></div>'),
(600, 'آتی', '<span class=\"hlight\">آتی .</span> (ع ص ) آینده . مستقبل : آتی الذکر.<br /></font></div>'),
(601, 'آتیشان', '<span class=\"hlight\">آتیشان .</span> (اِ) دیوان . (از شمس اللغات ). برای این کلمه شاهدی یافته نشد و شاید جمع آتیش صورتی از آتش باشد که مجازاً بمعنی دیو آمده است .<br /></font></div>'),
(602, 'آتیل', '<span class=\"hlight\">آتیل .</span> (اِخ ) نام دیهی از اکراد بناحیه ٔ زوزان .<br /></font></div>'),
(603, 'آتیلا', '<span class=\"hlight\">آتیلا.</span> (اِخ ) پادشاه قبیله ٔ هون که در <span class=\"hlight\" dir=\"rtl\">٤٣٤</span> م . امپراطوری روم شرقی و غربی را مغلوب و بپرداخت خراج ملزم ساخت . وفات او در <span class=\"hlight\" dir=\"rtl\">٤٥٣</span> م . بوده است .<br /></font></div>'),
(604, 'آتین', '<span class=\"hlight\">آتین .</span> (ص ) بلغت زند و پازندموجودشده و پیداگردیده و بهم رسیده باشد. (از برهان قاطع).<br /></font></div>'),
(605, 'آتیه', '<span class=\"hlight\">آتیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) تأنیث آتی .<br /></font></div>'),
(606, 'آثار', '<span class=\"hlight\">آثار.</span> (ع اِ) ج ِ اَثَر و اِثْر. نشانه ها. علامات . چیزها که از کسی بر جای ماند. آسال <span class=\"hlight\">:</span> <br />ای فخر آل اردشیر ای مملکت را ناگزیر<br />ای همچنان چون جان و تن آثار و افعالت هژیر.<br /> <font color=\"Red\">دقیقی .</font><br />چنین کنند بزرگان چو کرد باید کار<br />چنین نماید شمشیر خسروان آثار.<br /> <font color=\"Red\">عنصری .</font><br />آن رسوم و آثار ستوده هیچ جای نیست . (تاریخ بیهقی ). پادشاهان را چون نیکوسیرت و نیکوآثار باشند طاعت باید داشت . (تاریخ بیهقی ).<br />آنکه آثار همتش بسته ست <br />گردن دین و ملک را زیور.<br /> <font color=\"Red\">مسعودسعد.</font><br />و تو اگرچه مراد خویش مستور میداشتی من آثار آن میدیدم . (کلیله و دمنه ). و یکی از آثار باقی آن پادشاه حضرت بغداد است . (کلیله و دمنه ). آنچنان آثار مرضیه و مساعی حمیده که در تقدیم ابواب عدل و سیاست سلطان ماضی ... ابوالقاسم محمود است . (کلیله و دمنه ). آثار و دلائل آن حیرت می بینم . (کلیله و دمنه ). آنگاه در آثار و نتائج علم طب تأملی کردم . (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> احادیث و اخبار مأثوره . سنن . واهل حدیث آنچه را که از پیغمبر مأثور است خبر و آنچه را از صحابه منقول است اثر گویند. <BR><font color=\"Blue\">◄</font> لوازمی که معلل بیک چیز باشند یعنی علت آنها یک چیز باشد. (تعریفات میرسید شریف ). <BR><font color=\"Blue\">◄</font> ج ِ ثأر، به معنی خونخواهی، کینه جوئی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آثار سفلی </span> ؛ آثار طبایع و عناصر چهارگانه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آثار علوی </span> ؛ اثرهای افلاک و کواکب .<br /></font></div>'),
(607, 'آثام', '<span class=\"hlight\">آثام .</span> (ع اِ) ج ِ اِثم . بزه ها. گناهان .<br /></font></div>'),
(608, 'آثاناسیا', '<span class=\"hlight\">آثاناسیا.</span> (یونانی، اِ) اَثاناسیا. معجونی است نافع در اوجاع کبد و جز آن و معنای کلمه مُنْقِذ یا آیم وبهتر کنم و یا دواء گرگ و بز باشد. (بحرالجواهر).<br /></font></div>'),
(609, 'آثف', '<span class=\"hlight\">آثف .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع ص ) پس رو. (مهذب الاسماء). تابع.<br /></font></div>'),
(610, 'آثل', '<span class=\"hlight\">آثل .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع ص ) اصیل .<br /></font></div>'),
(611, 'آثم', '<span class=\"hlight\">آثم .</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع ص ) بزهمند. بزهکار. (مهذب الاسماء). گناهکار. مجرم . مذنب . عاصی . ج، آثمین، آثمون .<br /></font></div>'),
(612, 'آثور', '<span class=\"hlight\">آثور.</span> (اِخ ) رجوع به آشور شود.<br /></font></div>'),
(613, 'آثورا', '<span class=\"hlight\">آثورا.</span>(اِخ ) مطابق کتیبه های داریوش، نام دیگر آشور است .<br /></font></div>'),
(614, 'آثوری', '<span class=\"hlight\">آثوری .</span> (ص نسبی، اِ) رجوع به آشوری شود.<br /></font></div>'),
(615, 'آثوریه', '<span class=\"hlight\">آثوریه .</span> <font color=\"DarkGreen\"><b>[ ری ی َ ]</font></b> (اِخ ) رجوع به آشوریه شود.<br /></font></div>'),
(616, 'آثی', '<span class=\"hlight\">آثی .</span> (ع ص ) سخن چین . نمام . عیب گوی .<br /></font></div>'),
(617, 'آثینس', '<span class=\"hlight\">آثینس .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (اِخ ) آتن . آطن . آطنه . مدینةالحکماء. آثینا. منرفا. بزرگترین شهر آتیکا و کرسی آن در یونان بر خلیج سالونیک، و امروز نیز پای تخت یونان است .<br /></font></div>'),
(618, 'آثینه', '<span class=\"hlight\">آثینه .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) آطن .<br /></font></div>'),
(619, 'آج', '<span class=\"hlight\">آج .</span> (اِ) آز. خواهش . تمنا. طمع.<br /></font></div>'),
(620, 'آج آقایان', '<span class=\"hlight\">آج آقایان .</span> (اِخ ) (نهر...) رجوع به سومبار شود.<br /></font></div>'),
(621, 'آج دوجمش', '<span class=\"hlight\">آج دوجمش .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) شعبه ای از رود قزل اوزن .<br /></font></div>'),
(622, 'آجار', '<span class=\"hlight\">آجار.</span> (ع اِ) ج ِ اجر، به معنی مزد.<br /></font></div>'),
(623, 'آجاریدن', '<span class=\"hlight\">آجاریدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) در فرهنگها چنین کلمه ای ضبط نشده، ولی در این بیت ناصرخسرو اگر تحریفی در آن راه نیافته باشد ظاهراً به معنی درگذشتن و تخطی و تجاوز باشد <span class=\"hlight\">:</span> <br />نشانه ی ْ بندگی شکر است و هرگز مردم دانا<br />ز نسپاسی ز حد بندگی اندر، نیاجارد.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(624, 'آجال', '<span class=\"hlight\">آجال .</span> (ع اِ) ج ِ اَجَل، به معنی وقت و مدت معین و محدود و مرگ <span class=\"hlight\">:</span> تعاقب هر دو <font color=\"DarkGreen\"><b>[شب و روز]</font></b> بر... تقریب آجال مصروف است . <BR><font color=\"Blue\">◄</font> ج ِ اِجْل، به معنی گله ٔ گاو وحشی .<br /></font></div>'),
(625, 'آجام', '<span class=\"hlight\">آجام .</span> (ع اِ) جج ِ اَجَمه، به معنی نیستان و نیزار و بیشه <span class=\"hlight\">:</span> <br />با پیل پیلی کند بمیدان <br />با شیر شیری کند در آجام .<br /> <font color=\"Red\">فرخی .</font><br />چون دگران پادشاه نز عملی تو<br />شیر بمنشور نیست والی آجام .<br /> <font color=\"Red\">اثیر اخسیکتی .</font><br />آب آجام و بطایح بدتر است <br />کآن ببیشه وین بسنگ اخضر است .<br /> <font color=\"Red\">حکیم شیرازی .</font><br /><BR><font color=\"Blue\">◄</font> ج ِ اُجْم و اُجُم، به معنی حصار و حصن و دژ و دز.<br /></font></div>'),
(626, 'آجامی', '<span class=\"hlight\">آجامی .</span> (ص نسبی ) منسوب به آجام : تبهای آجامی .<br /></font></div>'),
(627, 'آجداد', '<span class=\"hlight\">آجداد.</span> (اِخ ) نام محلی کنار راه آباده به شیراز میان دِه ْبید و دیدگان، در <span class=\"hlight\" dir=\"rtl\">٧٢٥٧٠٠</span> گزی طهران .<br /></font></div>'),
(628, 'آجدن', '<span class=\"hlight\">آجدن .</span> <font color=\"DarkGreen\"><b>[ ج ْ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ دَ ]</font></b> (مص ) رجوع به آژدن شود.<br /></font></div>'),
(629, 'آجده', '<span class=\"hlight\">آجده .</span> <font color=\"DarkGreen\"><b>[ ج ْ <span class=\"hlight\" dir=\"rtl\">/</span>ج ِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آجیده . آزده . آژده <span class=\"hlight\">:</span> <br />از ملاقات صبا روی غدیر<br />راست چون آجده ٔ سوهان است .<br /> <font color=\"Red\">؟</font><br /><BR><font color=\"Blue\">◄</font> رنگ شده .<br /></font></div>'),
(630, 'آجر', '<span class=\"hlight\">آجر.</span> <font color=\"DarkGreen\"><b>[ ج ُرر ]</font></b> (اِخ ) قریه یا محله ای از بغداد که چند تن از مشاهیر بنسبت بدان آجری لقب یافته اند، و آن را درب الاَّجر هم می گفته اند.<br /></font></div>'),
(631, 'آجر', '<span class=\"hlight\">آجر.</span> <font color=\"DarkGreen\"><b>[ ج ُ ]</font></b> (از فرانسوی، ص، اِ) (از فرانسوی ِ آژور) مشبک . بسوراخ، و آن را شبکه و سه پایه نیز گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آجر زدن </span> ؛ سه پایه دوختن و شبکه زدن .<br /></font></div>'),
(632, 'آجر', '<span class=\"hlight\">آجر.</span> <font color=\"DarkGreen\"><b>[ ج َ ]</font></b> (اِخ ) صورتی از هاجر، نام مادر اسماعیل علیه السلام .<br /></font></div>'),
(633, 'آجر', '<span class=\"hlight\">آجر.</span><font color=\"DarkGreen\"><b>[ ج ُ ]</font></b> (معرب، اِ) معرب آگور، از فارسی یا بگفته ٔ منتهی الارب یونانی . خشت پخته . آجور. آگور <span class=\"hlight\">:</span> <br />خم رها کن، که بود چاهی ژرف <br />سر به آجر برآوریده شگرف .<br /> <font color=\"Red\">نظامی .</font><br /> - <span class=\"hlight\">آجر بزرگ </span> ؛ به فارسی تاوه گویند که معرب آن طابق است و نیز بتازی آن را اِردِبه خوانند.<BR><font color=\"HotPink\">♦ </font>آجر تراش ؛ آجری است که برونسوی اوساییده و هموار شده باشد زینت را و قسمی از آن را امروز قزاقی گویند.<BR><font color=\"HotPink\">♦ </font>آجر جوش ؛ آجر بسیار پخته و از صورت و رنگ بگشته که در بنیاد ابنیه و پیرامن تپه های گلکاری بکار برند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آجر ختایی </span> ؛ نوعی از آجر، بزرگتر از آجر عادی و کوچک تر از آجر نظامی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">نان کسی را آجر کردن </span> ؛ امید نفع و نعمت او را بدل بنومیدی کردن .<br /></font></div>'),
(634, 'آجرتراش', '<span class=\"hlight\">آجرتراش .</span> <font color=\"DarkGreen\"><b>[ ج ُ ت َ ]</font></b> (نف مرکب ) آنکه آجر را سوده و املس و هموار کند.<br /></font></div>'),
(635, 'آجرتراشی', '<span class=\"hlight\">آجرتراشی .</span> <font color=\"DarkGreen\"><b>[ ج ُ ت َ ]</font></b> (حامص مرکب ) پیشه و عمل آجرتراش .<br /></font></div>'),
(636, 'آجرفرش', '<span class=\"hlight\">آجرفرش .</span><font color=\"DarkGreen\"><b>[ ج ُ ف َ ]</font></b> (ص مرکب، اِ مرکب ) سطحی به آجر پوشیده .<br /></font></div>'),
(637, 'آجرفرش کردن', '<span class=\"hlight\">آجرفرش کردن .</span> <font color=\"DarkGreen\"><b>[ ج ُ ف َ ک َ دَ ]</font></b> (مص مرکب ) پوشیدن کف زمین به آجر.<br /></font></div>'),
(638, 'آجرلو و چاردولی', '<span class=\"hlight\">آجرلو و چاردولی .</span> <font color=\"DarkGreen\"><b>[ ج ُ وَ دَ ]</font></b> (اِخ ) از خرّه ٔ ولایت مراغه به آذربایجان که سی فرسنگ مساحت آن است و دارای <span class=\"hlight\" dir=\"rtl\">١١٩</span> قریه و نزدیک <span class=\"hlight\" dir=\"rtl\">١٦٢٩٧</span> تن سکنه می باشد. مرکز این خرّه دهکده ٔ کشاور، حد شمالی آن هشترود و گاودول و سراجو و حد شرقی افشار و جنوبی کردستان و غربی مرحمت آباد و گاودول است .<br /></font></div>'),
(639, 'آجرنما', '<span class=\"hlight\">آجرنما.</span> <font color=\"DarkGreen\"><b>[ ج ُ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ]</font></b>(ص مرکب، اِ مرکب ) دیواری که بگچ و نوع آن اندوده وبا خطوطی منتظم شکل دیوار آجرین بدان داده باشند.<br /></font></div>'),
(640, 'آجره', '<span class=\"hlight\">آجره .</span> <font color=\"DarkGreen\"><b>[ ج ُرْ رَ ]</font></b> (معرب، اِ) خشت پخته و جمع آن را به عربی آجر گویند.<br /></font></div>'),
(641, 'آجرپز', '<span class=\"hlight\">آجرپز.</span> <font color=\"DarkGreen\"><b>[ ج ُ پ َ ]</font></b> (نف مرکب ) فخاری . که آجر سازد.<br /></font></div>'),
(642, 'آجرپزی', '<span class=\"hlight\">آجرپزی .</span> <font color=\"DarkGreen\"><b>[ ج ُ پ َ ]</font></b> (حامص مرکب ) پیشه ٔ فخاری . شغل آجرپز. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) کوره و دستگاه آجرپزی .<br /></font></div>'),
(643, 'آجرک ا', '<span class=\"hlight\">آجرک ا.</span> <font color=\"DarkGreen\"><b>[ ج َ رَکَل ْ لاه ]</font></b> (ع جمله ٔ فعلیه ٔ دعایی ) خدات مزد دهاد.<br /></font></div>'),
(644, 'آجرکم ا', '<span class=\"hlight\">آجرکم ا.</span> <font color=\"DarkGreen\"><b>[ ج َ رَ ک ُ مُل ْ لاه ]</font></b> (ع جمله ٔ فعلیه ٔ دعایی ) خدایتان مزد دهاد.<br /></font></div>'),
(645, 'آجری', '<span class=\"hlight\">آجری .</span> <font color=\"DarkGreen\"><b>[ ج ُرْ ری ]</font></b> (ص نسبی ) منسوب به آجر یا درب الاَّجر و آن محله ای از بغداد بوده و برخی مشاهیر بدان منسوبند. <BR><font color=\"Blue\">◄</font> (اِخ ) نام و تخلص چند تن از مشایخ بزرگ .<br /></font></div>'),
(646, 'آجستن', '<span class=\"hlight\">آجستن .</span> <font color=\"DarkGreen\"><b>[ ج َ ت َ ]</font></b> (مص ) نشاندن درخت . (فرهنگ شعوری ). رجوع به نواجسته و نواخسته شود.<br /></font></div>'),
(647, 'آجل', '<span class=\"hlight\">آجل .</span> <font color=\"DarkGreen\"><b>[ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ُ ]</font></b> (اِ) بادی که با آواز از گلو برآید. آروغ . فوز. باد گلو. رجک . جشا. رغ <span class=\"hlight\">:</span> <br />ناخوشی های دهر را بالکل <br />بایدت خورد و نازدن آجل .<br /> <font color=\"Red\">روزبهان .</font><br />بسته دایم دهان خویش از بخل <br />کز گلو برنیایدت آجل .<br /><font color=\"Red\">؟</font><br /></font></div>'),
(648, 'آجل', '<span class=\"hlight\">آجل .</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع ص، اِ)بامهلت . دیرنده . تأخیرکننده . ضد عاجل <span class=\"hlight\">:</span> <br />عاجل نبود مگر شتابنده <br />هرگز نرود ز جای خویش آجل .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> دیر، مقابل زود <span class=\"hlight\">:</span> <br />بدین زودی ندانستم که ما را<br />سفر باشد بعاجل یا به آجل .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> آخرت . مقابل عاجل به معنی دنیا <span class=\"hlight\">:</span> باری عاجل و آجل بهم نپیوندد. (کلیله و دمنه ).<br />چون برای حق و روز آجل است <br />گر خطائی شد دیت بر عاقل است .<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> جانی و برانگیزنده ٔ بر جنایت .<br /></font></div>'),
(649, 'آجله', '<span class=\"hlight\">آجله .</span> <font color=\"DarkGreen\"><b>[ ج ِ ل َ ]</font></b> (ع ص، اِ) تأنیث آجل . <BR><font color=\"Blue\">◄</font> آن جهان . (مهذب الاسماء). آخرت . <BR><font color=\"Blue\">◄</font> هرچه بامهلت باشد.<br /></font></div>'),
(650, 'آجم', '<span class=\"hlight\">آجم .</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع ص ) زده شده ٔ از طعامی .<br /></font></div>'),
(651, 'آجن', '<span class=\"hlight\">آجن .</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع ص ) ماء آجن ؛ آب رنگ و طعم بگردانیده . آب بگشته . اَجِن .<br /></font></div>'),
(652, 'آجنقان', '<span class=\"hlight\">آجنقان .</span> <font color=\"DarkGreen\"><b>[ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ ]</font></b> (اِخ ) معرب آجنگان .<br /></font></div>'),
(653, 'آجنگان', '<span class=\"hlight\">آجنگان .</span> <font color=\"DarkGreen\"><b>[ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ ]</font></b> (اِخ ) نام قریه ای بسرخس و معرب آن آجنقان است .<br /></font></div>'),
(654, 'آجودان', '<span class=\"hlight\">آجودان .</span> (فرانسوی، ص، اِ) اَجودان . صاحب منصبی معلوم در نظام . نایب .<br /></font></div>'),
(655, 'آجودان باشی', '<span class=\"hlight\">آجودان باشی .</span> <font color=\"DarkGreen\"><b>[ دام ْ]</font></b> (ص مرکب، اِ مرکب ) اَجودان باشی . رئیس آجودانان .<br /></font></div>'),
(656, 'آجور', '<span class=\"hlight\">آجور.</span> (معرب، اِ) آجر. خشت پخته . معرب آگور.<br /></font></div>'),
(657, 'آجورا', '<span class=\"hlight\">آجورا.</span> (اِ) کوره ٔ خشت پزی . چار. (مهذب الاسماء).<br /></font></div>'),
(658, 'آجوری', '<span class=\"hlight\">آجوری .</span> <font color=\"DarkGreen\"><b>[ ری ی ]</font></b> (ع ص نسبی ) آگورگر. (مهذب الاسماء).<br /></font></div>'),
(659, 'آجی', '<span class=\"hlight\">آجی .</span> (اِخ ) یا آجی چای . نام امروزی آن تلخه رود. (فرهنگستان ). رودیست از کوههای سبلان سرچشمه گرفته، با شعب عدیده که از قوشه داغ و بزغوش و سهند جاری شود از شمال تبریز گذرد و نزدیک قصبه ٔ گوگان بدریاچه ریزد، و از آب راهه های مهم آن یکی گومان رود است که در قصبه ٔ گومان به آن ملحق شود و شعبه ای از آجی چای از تبریز گذرد.<br /></font></div>'),
(660, 'آجیدن', '<span class=\"hlight\">آجیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آجدن . آزدن . آژدن . نگندن . <BR><font color=\"Blue\">◄</font> منقور و مضرس کردن سطح سنگ آسیا با آسیازنه بهتر خرد کردن دانه را. رجوع به آژدن شود.<br /></font></div>'),
(661, 'آجیده', '<span class=\"hlight\">آجیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف، اِ) آجده . آژده . نگنده . و گیوه ٔ آجیده آن است که کف آن رااز برون سوی با ریسمان محکم، خانه خانه بافته باشند. <BR><font color=\"Blue\">◄</font> نوعی از بخیه کوتاهتر از کوک و شلال . <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آجیده ٔ سوهان </span> ؛ درشتیها و ناهمواریهای روی سوهان .<br /></font></div>'),
(662, 'آجیل', '<span class=\"hlight\">آجیل .</span> (اِ) خشک میوه . مجموع پسته، بادام، نخود، فندق، تخمه ٔ کدو و تخمه ٔ هندوانه ٔ تف داده و نمک زده یا آچارده . <BR><font color=\"Blue\">◄</font> نقل، مزه و توسعاً هر نعمت و فائده که از کسی بدیگری رسد از خوراک و پوشاک و نقدینه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آجیل مشکل گشا</span> ؛ خشک میوه ها باشد که زنان بنذر بخشند برآمدن حاجتی را.<br /></font></div>'),
(663, 'آجیل خوری', '<span class=\"hlight\">آجیل خوری .</span><font color=\"DarkGreen\"><b>[ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ ]</font></b> (اِ مرکب ) ظرفی که در آن آجیل کنند.<br /></font></div>'),
(664, 'آجیل فروش', '<span class=\"hlight\">آجیل فروش .</span> <font color=\"DarkGreen\"><b>[ ف ُ ]</font></b> (نف مرکب ) بایع و فروشنده ٔ آجیل .<br /></font></div>'),
(665, 'آجیل فروشی', '<span class=\"hlight\">آجیل فروشی .</span> <font color=\"DarkGreen\"><b>[ ف ُ ]</font></b> (حامص مرکب ) شغل آجیل فروش . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) دکان آجیل فروش .<br /></font></div>'),
(666, 'آجین', '<span class=\"hlight\">آجین .</span> (ن مف ) آجیده . آژده . آزده <span class=\"hlight\">:</span> <br />ز شاخ گوزنان رمه در رمه <br />زمین بیشه ای گشت آجین همه .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">تیرآجین </span> ؛ بتیر بسیار زده شده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">شمعآجین کردن </span> ؛ عقوبتی که تن را جای جای سوراخ کرده، شمع در آن فروکرده افروختندی .<br /></font></div>'),
(667, 'آح', '<span class=\"hlight\">آح .</span> (ع اِ) سپیده ٔ خایه . بیاض البیض . سپیده ٔ تخم مرغ .<br /></font></div>'),
(668, 'آحاب', '<span class=\"hlight\">آحاب .</span> (اِخ ) اَحاب . رجوع به اَخاب شود.<br /></font></div>'),
(669, 'آحاد', '<span class=\"hlight\">آحاد.</span> (ع اِ) ج ِ اَحَد. یکان . (التفهیم ). یک یک افراد و اشخاص <span class=\"hlight\">:</span> و قاضی فتوی داد که خون یکی از آحاد رعیت ریختن سلامت نفس پادشاه را، روا باشد.(گلستان ). <BR><font color=\"Blue\">◄</font> مرتبه ٔ اول از طبقات عدد.<br /></font></div>'),
(670, 'آحاز', '<span class=\"hlight\">آحاز.</span> (اِخ ) نام یازدهمین پادشاه یهود، پسر یوثام و پدر حزقیا. و این کلمه را آخار هم نوشته اند.<br /></font></div>'),
(671, 'آخ', '<span class=\"hlight\">آخ .</span> (صوت ) صوتی است مرادف وای و اُف، حاکی از درد و رنج و تعب <span class=\"hlight\">:</span> <br />عشق آتش تیز و هیزم تاخ منم <br />گر عشق بماند اینچنین آخ تنم .<br /> <font color=\"Red\">صفار.</font><br /><BR><font color=\"Blue\">◄</font> آفرین . بخ . بارک اﷲ.<br /></font></div>'),
(672, 'آخ و اوخ', '<span class=\"hlight\">آخ و اوخ .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (اِ صوت مرکب، از اتباع ) حکایت صوت ناله ٔ بیمار و مانند آن .<br /></font></div>'),
(673, 'آخا', '<span class=\"hlight\">آخا.</span> (صوت ) آخ . آفرین .<br /></font></div>'),
(674, 'آخال', '<span class=\"hlight\">آخال .</span> (اِ) سقط. افکندنی . نابکار. حشو. فضول . بدترین چیزی . (فرهنگ اسدی، خطی ). و این کلمه صورتی از آشغال متداول امروز است <span class=\"hlight\">:</span> <br />از عمر نمانده ست برِ من مگر آمرغ <br />در کیسه نمانده ست بمن بر مگر آخال .<br /> <font color=\"Red\">کسائی مروزی .</font><br />از بس گل مجهول که در باغ بخندید<br />نزدیک همه کس گل معروف شد آخال .<br /> <font color=\"Red\">فرخی .</font><br />ای مشکفشان زلفین ای غالیه گون خال <br />با هر دو بود غالیه و مشک چو آخال .<br /> <font color=\"Red\">قطران .</font><br />جاهی و جلالی که بصندوق درون است <br />جاهی و جلالی است گران سنگ و پرآخال .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> تراشه ٔ چوب و قلم و خس و خاشاک و رُفته ٔ جاروب <span class=\"hlight\">:</span> <br />دامن تردامنان عقل در آخال کش <br />ساعد هودج کشان عشق پر خلخال کن .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> جُفاء. جفال . آب آورد <span class=\"hlight\">:</span> <br />دُرِّ معنی در بن دریای عزلت جای ساخت <br />وز پی دعوی بروی آبها آخال ماند.<br /> <font color=\"Red\">سنائی .</font><br />و رجوع به آشغال شود.<br /></font></div>'),
(675, 'آخال', '<span class=\"hlight\">آخال .</span> (اِخ ) نام شهری . و رجوع به آخال تزیخه و آخال تکه شود.<br /></font></div>'),
(676, 'آخال تزیخه', '<span class=\"hlight\">آخال تزیخه .</span> <font color=\"DarkGreen\"><b>[ ت ِ خ َ ]</font></b> (اِخ ) شهری است در گرجستان بر ساحل پسخوچای دارای شانزده هزار سکنه که قسمتی از آن ارمنی باشد.<br /></font></div>'),
(677, 'آخال تکه', '<span class=\"hlight\">آخال تکه .</span> <font color=\"DarkGreen\"><b>[ ت ِک ْ ک َ ]</font></b> (اِخ ) نام واحه ای از ترکستان روس در دامنه ٔ قبه داغ، و رود اترک از آنجا گذرد.<br /></font></div>'),
(678, 'آختاتار', '<span class=\"hlight\">آختاتار.</span> (اِخ ) نام محلی کنار راه سنندج و ساوجبلاغ میان سه راهی و کانتوار در <span class=\"hlight\" dir=\"rtl\">٢٣١</span> هزارگزی سنندج .<br /></font></div>'),
(679, 'آختاچی', '<span class=\"hlight\">آختاچی .</span> (ترکی، ص مرکب، اِ مرکب ) شاه و فرمانروایی که دست نشانده و تابع شاه و فرمانروایی بزرگتر باشد.<br /></font></div>'),
(680, 'آختن', '<span class=\"hlight\">آختن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص ) آهختن . آهیختن . برآوردن . آهنجیدن . لنجیدن . کشیدن . برکشیدن . تشهیر. بیرون کشیدن . بیرون کردن . یازیدن . سَل ّ. استلال . اخراج <span class=\"hlight\">:</span> <br />یکی آخته تیغ زرین ز بر<br />یکی برسر آورده سیمین سپر.<br /> <font color=\"Red\">اسدی .</font><br />تا بتاج هدهد و طاوس در کین عدوت <br />تیرهای پرزده ست و تیغهای آخته .<br /> <font color=\"Red\">انوری .</font><br />ای که شمشیر جفا بر سر ما آخته ای <br />صلح کردیم که ما را سر پیکار تو نیست .<br /> <font color=\"Red\">سعدی .</font><br />گرش بر فریدون بدی تاختن <br />امانش ندادی بتیغ آختن .<br /> <font color=\"Red\">سعدی .</font><br />تیغ زبان آخت برای جدل <br />کی شده در شهرت کاذب مثل .<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آختن جامه و پوست </span> ؛ بیرون کردن و برکشیدن و برکندن آن از تن <span class=\"hlight\">:</span> <br />کمانهای ترکی بینداختند<br />قبای نبردی برون آختند.<br /> <font color=\"Red\">فردوسی .</font><br />گوان جامه ٔ رزم برآختند<br />نیایش کنان دست بفراختند.<br /> <font color=\"Red\">اسدی .</font><br />ز تن پوستهاشان برون آختند<br />وزآن جامه ٔ گونه گون ساختند.<br /> <font color=\"Red\">اسدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آختن ریسمان و نخ و طراز و مانند آن </span> ؛ مد و بسط و کشیدن آن <span class=\"hlight\">:</span> <br />بر طراز آخته پویه کند چون عنکبوت <br />بر بدستی جای بر، جولان کند چون بابزن .<br /> <font color=\"Red\">منوچهری .</font><br />چون طرازی آخته فردا بخواهی ریختن <br />گر کشد بر جامه ٔ جاهت فلک نقش طراز.<br /> <font color=\"Red\">سنائی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آختن صف </span> ؛ صف کشیدن . رده شدن <span class=\"hlight\">:</span> <br />همیدون صف شاعران آخته <br />بخوانده ثناها و پرداخته .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">از خانه بیاختن </span> ؛ از خانه بیرون بردن و بیرون کردن <span class=\"hlight\">:</span> <br />بدان ای پدر کآن جوانان من <br />که هستند همزادو اخوان من <br />ز خانه مرا چون بدشت آختند<br />برهنه بچاهم درانداختند.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">برون آختن </span> ؛بدر کشیدن . بدر آوردن . بیرون کردن . اخراج <span class=\"hlight\">:</span><br />بکشتی و مغزش برون آختی <br />مر آن اژدها را خورش ساختی .<br /> <font color=\"Red\">فردوسی (شاهنامه چ دبیرسیاقی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دست آختن </span> ؛ دست دراز کردن . دست یازیدن <span class=\"hlight\">:</span> <br />ندانست کس غارت و تاختن <br />دگر دست سوی بدی آختن .<br /> <font color=\"Red\">فردوسی .</font><br />به ایزدگشسب آن زمان دست آخت <br />به بیهوده بر، بند و زندانْش ساخت .<br /> <font color=\"Red\">فردوسی .</font><br />تو نشنیدی این داستان بزرگ <br />که شیر ژیان افکند پیش گرگ <br />که هر کو بخون کیان دست آخت <br />زمانه جز از خاک جایش نساخت .<br /> <font color=\"Red\">فردوسی .</font><br />میان تنگ خون ریختن را ببست <br />ببهرام آذرمهان آخت دست .<br /> <font color=\"Red\">فردوسی .</font><br />بدو <font color=\"DarkGreen\"><b>[ به مانی ]</font></b> گفت کای مرد صورت پرست <br />بیزدان چرا آختی خیره دست ؟<br /> <font color=\"Red\">فردوسی .</font><br />چو آمد بدانجایگه دست آخت <font color=\"DarkGreen\"><b>[ سیاوش ]</font></b><br />دو فرسنگ بالا و پهنا بساخت <br />بیاراست شهری بسان بهشت <br />بهامون گل و سنبل و لاله کشت .<br /> <font color=\"Red\">فردوسی .</font><br />میان بزرگان بیازید و دست <br />بدان جام می آخت و بر پای جست .<br /> <font color=\"Red\">فردوسی .</font><br />سرشکی سوی دیگر انداختی <br />دگر دست جای دگر آختی .<br /> <font color=\"Red\">فردوسی .</font><br />ستمگر <font color=\"DarkGreen\"><b>[ افراسیاب ]</font></b> بدانگونه بد آخت دست <br />دل هر کس از کشتن او <font color=\"DarkGreen\"><b>[ سیاوش ]</font></b> بخست .<br /> <font color=\"Red\">فردوسی .</font><br />زمانی بخوان، دستها آختند<br />بخوردند یک لخت و پرداختند.<br /> <font color=\"Red\">شمسی (یوسف وزلیخا).</font><br />چو نتوان بافلاک دست آختن <br />ضروری است با گردشش ساختن .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کین (کینه ) آختن </span> ؛ کین کشیدن . انتقام گرفتن . جنگ کردن <span class=\"hlight\">:</span> <br />دگر آنکه گفتی که از تاختن <br />نیاسودی از رنج و کین آختن .<br /> <font color=\"Red\">فردوسی .</font><br />همی تاخت وآن باره را تیز کرد<br />همی آخت کینه همی کشت مَرد.<br /> <font color=\"Red\">فردوسی .</font><br />سپاه پراکنده کرد انجمن <br />همی رفت تا بیشه ٔ نارون ...<br />همی برد بر هر سویی تاختن <br />بدان تاختن بود کین آختن .<br /> <font color=\"Red\">فردوسی .</font><br />دگر اسب شبدیز کز تاختن <br />نماندی بهنگام کین آختن .<br /> <font color=\"Red\">فردوسی .</font><br />یلانی که شان پیشه کین آختن <br />شبان روز خو کرده بر تاختن .<br /> <font color=\"Red\">اسدی .</font><br />کنون باید این رزم را ساختن <br />توانی مگر کین از او آختن .<br /> <font color=\"Red\">اسدی .</font><br />دگر باره هر دو سپه ساختند<br />کشیدند صف تیغ و خشت آختند.<br /> <font color=\"Red\">اسدی .</font><br />گر دلت بر نیکی همسایه ات کینه گرفت <br />کینت از بدفعل جان خویش بایدآختن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />امروز در این دولت و این ملک مهیا<br />هر قوم که آیند بکین آخته سکین ...<br /> <font color=\"Red\">معزی .</font><br />منم که همچو کمان دستمال ترکانم <br />همه ز غمزه خدنگ آخته بکینه ٔ من .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> بهم پیوستن . متصل کردن <span class=\"hlight\">:</span> <br />پیاده سپر در سپر آخته <br />خدنگ افکن از پس کمین ساخته .<br /> <font color=\"Red\">اسدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آختن رود و امثال آن </span> ؛ نواختن یا بساز و بسامان آوردن و کوک کردن آن <span class=\"hlight\">:</span> <br />همیشه دشمن تو سوخته تو ساخته بزم <br />ببزم ساخته، رود آخته دو صد چرگر.<br /> <font color=\"Red\">؟ (از فرهنگ اسدی، خطی ).</font><br /> <BR><font color=\"Blue\">◄</font> افراختن . برکشیدن . ترفیع. برکردن . افراشتن . بلند کردن . اِعلاء <span class=\"hlight\">:</span> <br />زن و شوی هر دو بهم ساختند<br />سر تاجشان بر سپهر آختند.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />چو شاهان یکی مرکبش ساخته <br />سرش بر سپهر بلند آخته .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بحد خنجر و نعل تکاوران کردی <br />زمین هامون دریا و کوه آخته، غار.<br /> <font color=\"Red\">مسعودسعد.</font><br />ببوستان شرف خرمی و پیروزیست <br />که سرو آخته قدی ببوستان شرف .<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> چشم دوختن . دیده آختن در (اندر، به ) <span class=\"hlight\">:</span> <br />بدو <font color=\"DarkGreen\"><b>[ بیوسف ]</font></b> بود چشم و دل خلق و بس <br />نبد آگه از مرگ خود هیچ کس <br />عزیز اندرو دیده ها آخته <br />دل و هوش خود پاک پرداخته .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> گستردن . پراکندن <span class=\"hlight\">:</span> <br />کاه داری آخته بر روی آب <br />زهر داری ساخته در زیر قند.<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> معنی آختن در بیت ذیل اگر تصحیفی در آن راه نیافته باشد معلوم نیست و شاید بمعنی روشن شدن و یا آگاهی یافتن باشد <span class=\"hlight\">:</span> <br />بدان تا شب تیره بی آختن <br />نیارد ز ترکان کسی تاختن <br />دوصد باره عراده و منجنیق <br />نهاد از برش هر سویی جاثلیق .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> در بیت ذیل آختن را ظهوری به معنی مصفا و مروق کردن شراب آورده است و البته محل اعتماد نیست جز آنکه شواهد دیگری یافته شود <span class=\"hlight\">:</span> <br />بده ساقیا آن می آخته <br />که جام جم از وی بپرداخته .<br /> <font color=\"Red\">ظهوری (از شعوری ).</font><br /><BR><font color=\"Blue\">◄</font> و در بعض فرهنگها به معنی انداختن و نیز دست کشیدن از چیزی آورده اند. <BR><font color=\"Blue\">◄</font> اسم مصدر غیرمستعمل این فعل آزش است : آختم . بیاز. و رجوع به آهختن و آهیختن و آهنجیدن شود.<br /></font></div>'),
(681, 'آخته', '<span class=\"hlight\">آخته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ترکی، ص ) خایه برکشیده . خصی کرده از جانوران و خاصه اسب و خروس . اَخته .<br /></font></div>'),
(682, 'آخته', '<span class=\"hlight\">آخته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف ) اَخْته . آهخته . آهیخته . کشیده . برکشیده . آهنجیده . لنجیده . مسلول . مشهر. بیرون کرده . برآورده . بیرون کشیده . مستخرج . <BR><font color=\"Blue\">◄</font> درازکرده . ممدود. ممدوده . مبسوط. <BR><font color=\"Blue\">◄</font> برافراشته . مرفوع . بلندکرده . برفراشته . <BR><font color=\"Blue\">◄</font> بردوخته به (چشم ). <BR><font color=\"Blue\">◄</font> کنده . برکنده (جامه ). <BR><font color=\"Blue\">◄</font> کشیده (صف و رده ). <BR><font color=\"Blue\">◄</font> پیوسته . متصل . <BR><font color=\"Blue\">◄</font> نواخته . بساز و بسامان کرده . و رجوع به آختن شود.<br /></font></div>'),
(683, 'آخته بیگ', '<span class=\"hlight\">آخته بیگ .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ترکی، ص مرکب، اِ مرکب ) اَخته بیگ . آخته چی .<br /></font></div>'),
(684, 'آخته بیگی', '<span class=\"hlight\">آخته بیگی .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (حامص مرکب ) اَخْته بیگی . سمت و شغل آخته چی یا آخته بیگ .<br /></font></div>'),
(685, 'آخته چی', '<span class=\"hlight\">آخته چی .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ترکی، ص مرکب، اِ مرکب ) اَخْته چی . اَختاجی . اَختاچی . آخته بیگ . اَخْته بیگ . کسی که اَخته کردن ستور و حیوانات بدستور او باشد. <BR><font color=\"Blue\">◄</font> داروغه ٔ اصطبل . میرآخور.<br /></font></div>'),
(686, 'آخذ', '<span class=\"hlight\">آخذ.</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b>(ع ص ) گیرنده . ج، آخذین . <BR><font color=\"Blue\">◄</font> شتری که بفربهی آغازیده باشد. <BR><font color=\"Blue\">◄</font> اشتری که دندان آن شروع ببرآمدن کرده باشد. <BR><font color=\"Blue\">◄</font> شیر که زبان بگزد از شدت ترشی . <BR><font color=\"Blue\">◄</font> آنکه چشم دردگن دارد.<br /></font></div>'),
(687, 'آخذه', '<span class=\"hlight\">آخذه .</span> <font color=\"DarkGreen\"><b>[ خ ِ ذَ ]</font></b> (ع ص ) تأنیث آخذ. <BR><font color=\"Blue\">◄</font> (اِمص ) سستی در عضو. جمود.<br /></font></div>'),
(688, 'آخر', '<span class=\"hlight\">آخر.</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (اِخ ) نام قصبه ای بدهستان . گویند نام قریه ای میان جرجان و خوارزم . و زاهد معروف ابوالفضل عباس بن احمدبن فضل منسوب بدانجاست . <BR><font color=\"Blue\">◄</font> نام قریه ای میان سمنان و دامغان .<br /></font></div>'),
(689, 'آخر', '<span class=\"hlight\">آخر.</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (ع ص ) دیگر. دگر. دیگری . یکی از دو چیز یا دو کس . غیر. مؤنث : اُخْری ̍. ج، آخَرین .<br /></font></div>'),
(690, 'آخر', '<span class=\"hlight\">آخر.</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (ع ص، ق، اِ) عاقبت . باَنجام . سرانجام . انجام . بازپسین . اخیر. واپسین . پسین . اَفدُم . آفدم . در آخر. به آفدم . پایان . فرجام . بفرجام . فرجامین . خاتمه . کرانه . کران . غایت . نهایت . خاتمت . پس کار. (زمخشری ). مقابل اوّل . مؤنث : آخِره . ج، آخِرین، و اواخر نیز بجای آن گفته می شود و به فارسی آخرها <span class=\"hlight\">:</span> <br />قند جدا کن از اوی دور شو از زهر دند<br />هرچه به آخر به است جان ترا، آن پسند.<br /> <font color=\"Red\">رودکی .</font><br />نه به آخر همه بفرساید<br />هرکه انجام راست فرسدنی است .<br /> <font color=\"Red\">رودکی .</font><br />تا کی کند او خوارم تا کی زند او شنگم <br />فرسوده شوم آخر گر آهن و گر سنگم .<br /> <font color=\"Red\">ابوشکور.</font><br />ببینم آخر روزی بکام دل خود را<br />گهی ایارده خوانم شها گهی خرده .<br /> <font color=\"Red\">دقیقی .</font><br />بیاویختند آن دو تن سخت دیر<br />به آخر ورا هوم آورد زیر.<br /> <font color=\"Red\">فردوسی .</font><br />ببد در جهان پنج صد سال شاه <br />به آخر شد و ماند زو جایگاه .<br /> <font color=\"Red\">فردوسی .</font><br />همی گفتش صبوری کن که آخر<br />بکام دل رسد یک روز صابر.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />پدر ما هرچند ما را ولی عهد کرده بود... در این آخرها که لختی مزاج او بگشت ... ما را به ری ماند. (تاریخ بیهقی ). امیر گفت اسبی نیک روز آخر خیلتاش را باید داد. (تاریخ بیهقی ). پس از جواب توقیع کند و به آخر آن ایزد... را یاد کند که وزیر رابر آن نگاه دارد. (تاریخ بیهقی ).<br />بخرم آخرآنین ترا جان پدر<br />پس درو ریزم جغرات و همی جنبانم .<br /> <font color=\"Red\">؟ (از فرهنگ اسدی، خطی ).</font><br />بار از خر بنهند آخر و زینها ننهند<br />زآنکه اینها سوی ایزد بسی از خر بترند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />از پی هر گریه آخر خنده ای است <br />مرد آخربین مبارک بنده ای است .<br /> <font color=\"Red\">مولوی .</font><br />میتوانی دید آخر را مکن <br />چشم آخربینْت را کور و کهن .<br /> <font color=\"Red\">مولوی .</font><br />همچنین در قاع بسیط مسافری گم شده بود و قوت و قوّتش به آخر آمده . (گلستان ).<br />برو از خانه ٔ گردون بدر و نان مطلب <br />کاین سیه کاسه در آخر بکشد مهمان را.<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> این کلمه را در فارسی در مقام تعریض و تقریعو تعجب و تقریر و شکایت از بطوء و انتظار و مانند آن نیز آرند <span class=\"hlight\">:</span> <br />نشسته جهاندار بر تخت خویش <br />همی گفت با هر کس از بخت خویش <br />که آخر بدین بارگاه مهی <br />نیامد ز بهرام هیچ آگهی .<br /> <font color=\"Red\">فردوسی .</font><br />نه آخرتو مردی جهاندیده ای <br />بد و نیک هر گونه ای دیده ای .<br /> <font color=\"Red\">فردوسی .</font><br />پیشکار کشتی نگاه کرد و فریاد برآورد و زاری کرد که ای مسلمانان شهادت بیارید که کار ما به آخر رسید... ما گفتیم آخر چه افتاده است . (مجمل التواریخ ). آخر نگوئی تو کیستی ؟ (کلیله و دمنه ).<br />آخر چه کارزار کند رنگ با پلنگ .<br /> <font color=\"Red\">سوزنی .</font><br />آخر زبهر کاری پردخته شد مناره .<br /> <font color=\"Red\">عمادی .</font><br />آخر ایران که ازو بودی فردوس برشک <br />وقف خواهد بد تا حشر بدین شوم حشر.<br /> <font color=\"Red\">انوری .</font><br />آخر امشب شبی است سالی نیست .<br /> <font color=\"Red\">نظامی .</font><br />آخر آدمزاده ای ای ناخلف <br />چند پنداری تو پستی را شرف ؟<br /> <font color=\"Red\">مولوی .</font><br />عشقبازی نه من آخر بجهان آوردم .<br /> <font color=\"Red\">سعدی .</font><br />آخر این آمدن بکاری بود<br />وز برای چنین شماری بود.<br /> <font color=\"Red\">اوحدی .</font><br />آخر عربی حمیّتت کو.<br /> <font color=\"Red\">؟</font><br /><BR><font color=\"Blue\">◄</font> (اِخ ) نامی از نامهای خدای تعالی، مقابل اوّل . آنکه همیشه باشد و آنکه باقی ماند بعد از فنای هر چیز.<br /></font></div>'),
(691, 'آخر', '<span class=\"hlight\">آخر.</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (اِ)آخور. جایگاهی از گل و سنگ و مانند آن کرده کاه و جو و علف خوردن ستور را. معلف . اَری . متبن . آغیل . ستورگاه . پایگاه . پاگاه . ستورخانه . اصطبل . (زمخشری ). جائی که چهارپایان را بندند. طویله به معنی متداول این عصر. آکنده . <BR><font color=\"Blue\">◄</font> آخیه . (زمخشری ) (نطنزی ). طویله <span class=\"hlight\">:</span> و آنجا <font color=\"DarkGreen\"><b>[ بسمنگان در خراسان ]</font></b> کوهها است از سنگ سپید چون رخام و اندر وی خانه های کنده است و مجلسها و کوشکها و بتخانه ها است و آخر اسبان، با همه آلتی که مر کوشکها را بباید. (حدودالعالم ).<br />ز آخر بیاورد پس پهلوان <br />ده اسب سوار آزموده ی ْ گوان .<br /> <font color=\"Red\">فردوسی .</font><br />رخش پر ز خون دل و دیده گشت <br />سوی آخر تازی اسبان گذشت .<br /> <font color=\"Red\">فردوسی .</font><br />ببینیم تا اسب اسفندیار<br />سوی آخر آید همی بی فسار...<br /> <font color=\"Red\">فردوسی .</font><br />روز به آکنده شدم یافتم <br />آخر چون پاتله ٔ سفلگان .<br /> <font color=\"Red\">ابوالعباس .</font><br />گر دنگل آمده ست پسر تا کی <br />بربندیش بر آخر هر مهتر.<br /> <font color=\"Red\">ابوالعباس .</font><br />چون خر رواست پایگهت آخر<br />چون سگ سزاست جایگهت شله .<br /> <font color=\"Red\">خفاف .</font><br />سلطان گفت برو از آخر هر کدام اسب که خواهی بگشای و در این حالت بر کنار آخر بودیم امیرعلی اسبی نامزد کرد بیاوردند و بکسان من دادند. (چهارمقاله ).<br />این بادپای خوشرو تازی نژاد فضل <br />تا چند گاه باشد بر آخر حمیر.<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> ناوه مانندی از چوب که در آن کاه و جو و مانند آن ریزندخوردن ستور را <span class=\"hlight\">:</span> <br />خراس و آخر و خنبه ببردند<br />نبود از چنگشان بس چیزپنهان .<br /> <font color=\"Red\">طیان .</font><br /> <BR><font color=\"Blue\">◄</font> گَوی که در سنگ یا چوب کنند آب را. حوض خرد. حوضچه <span class=\"hlight\">:</span> و چهار سوی خانه ٔ <font color=\"DarkGreen\"><b>[ ظ: چاه ]</font></b> زمزم آخرها کرده اند که آب در آن ریزند و مردم وضو سازند. (سفرنامه ٔ ناصرخسرو). <BR><font color=\"Blue\">◄</font> قوس گونه ای از استخوان بالای سینه زیر گردن . چنبره . ترقوه . آخره . آخرک <span class=\"hlight\">:</span> <br />بهر آن خنگ توسنی، دشمن <br />جای سازد به آخر گردن .<br /> <font color=\"Red\">امیرخسرو (در وصف شمشیر).</font><br />بزد بر آخر گردن چنانش <br />که بگذشت از بغل آب روانش .<br /> <font color=\"Red\">نزاری .</font><br /> <BR><font color=\"Blue\">◄</font> گَوی که در میان توده ٔ خاک کنند تا آب در آن ریخته و شفته و کاهگل سازند، و آن را آخره و آخرک نیز گویند. <BR><font color=\"Blue\">◄</font> (اِخ ) صورتی فلکی که عرب آن را معلف گوید. (از التفهیم ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">برای هر خری آخر نمی بندند</span> ؛ هر کس لایق این اعزاز و اکرام نباشد.<br /></font></div>'),
(692, 'آخر بیت', '<span class=\"hlight\">آخر بیت .</span><font color=\"DarkGreen\"><b>[ خ ِ رِ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) قافیه .<br /></font></div>'),
(693, 'آخر خشک', '<span class=\"hlight\">آخر خشک .</span> <font color=\"DarkGreen\"><b>[ خ ُ رِ خ ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) آخورِ خشک . مقابل آخُرِ چرب .<br /></font></div>'),
(694, 'آخر رحل', '<span class=\"hlight\">آخر رحل .</span> <font color=\"DarkGreen\"><b>[ خ ِ رِ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) دنباله ٔ پالان که راکب بدان تکیه زند.<br /></font></div>'),
(695, 'آخر رستم', '<span class=\"hlight\">آخر رستم .</span> <font color=\"DarkGreen\"><b>[ خ ُ رِ رُ ت َ ]</font></b> (اِخ ) نام محلی بوده در نزدیکی ری : سلطان از انبط برفت و بدر ری به آخر رستم فرود آمد، عباس به اردهن گریخت . (راحةالصدور).<br /></font></div>'),
(696, 'آخر سنگین', '<span class=\"hlight\">آخر سنگین .</span> <font color=\"DarkGreen\"><b>[ خ ُ رِ س َ ]</font></b>(ترکیب وصفی، اِ مرکب ) آخورِ سنگین . آخری که در آن کاه و علف نباشد. <BR><font color=\"Blue\">◄</font> جایی که در آن حاصل ونفعی نبود. (از برهان ). مقابل آخر چرب <span class=\"hlight\">:</span> <br />رخش ترا برآخر سنگین روزگار<br />برگ و گیا نه و خر تو عنبرین چرا.<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> سنگاب . مجازاً، چرب آخر <span class=\"hlight\">:</span> <br />حق تو خاقانیا کعبه تواند شناخت <br />وآخر سنگین طلب توشه ٔ یوم الحساب . <br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(697, 'آخر شدن', '<span class=\"hlight\">آخر شدن .</span> <font color=\"DarkGreen\"><b>[ خ ِ ش ُ دَ ]</font></b> (مص مرکب ) بپایان رسیدن . برسیدن . سر آمدن . بانجام رسیدن <span class=\"hlight\">:</span> <br />روز هجران و شب فرقت یار آخر شد<br />زدم این فال و گذشت اختر و کار آخر شد.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(698, 'آخر چرب', '<span class=\"hlight\">آخر چرب .</span> <font color=\"DarkGreen\"><b>[ خ ُ رِ چ َ ]</font></b> (ترکیب وصفی، اِ مرکب ) آخورِ چرب . نعمت فراوان . رفاه و فراوانی نعمت . رجوع به چرب آخر شود.<br /></font></div>'),
(699, 'آخر کار', '<span class=\"hlight\">آخر کار.</span> <font color=\"DarkGreen\"><b>[ خ ِ رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) انتها و عاقبت و نهایت امر. آخرالامر.<br /></font></div>'),
(700, 'آخر کتل ناسخند', '<span class=\"hlight\">آخر کتل ناسخند.</span> <font color=\"DarkGreen\"><b>[ خ ِ ک ُ ت َ ل ِ خ َ ]</font></b> (اِخ ) نام محلی کنار راه لارببستک میان برکه یوزه و انوه در <span class=\"hlight\" dir=\"rtl\">٤٤٩</span>هزارگزی شیراز.<br /></font></div>'),
(701, 'آخر کردن', '<span class=\"hlight\">آخر کردن .</span> <font color=\"DarkGreen\"><b>[ خ ِ ک َ دَ ]</font></b> (مص مرکب ) بپایان رسانیدن .<br /></font></div>'),
(702, 'آخرالامر', '<span class=\"hlight\">آخرالامر.</span> <font color=\"DarkGreen\"><b>[ خ ِ رَل ْ <span class=\"hlight\" dir=\"rtl\">/</span> رُل ْ اَ ]</font></b> (ع ق مرکب ) عاقبت . در پایان کار. الحاصل <span class=\"hlight\">:</span> <br />آخرالامر گل کوزه گران خواهی شد<br />حالیا فکر سبو کن که پر از باده کنی .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(703, 'آخرالزمان', '<span class=\"hlight\">آخرالزمان .</span> <font color=\"DarkGreen\"><b>[ خ ِ رُزْزَ ]</font></b> (ع اِ مرکب ) رجوع به آخرزمان شود <span class=\"hlight\">:</span> <br />تو فتنه ٔ آخرالزمانی <br />من سعدی آخرالزمانم .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(704, 'آخرالنهر', '<span class=\"hlight\">آخرالنهر.</span> <font color=\"DarkGreen\"><b>[ خ ِ رُن ْ ن َ ]</font></b> (اِخ ) (اصطلاح فلک ) نام یکی از ثوابت از قدراول بر منتهای صورت نهر، و آن را ظلیم نیز نامند.<br /></font></div>'),
(705, 'آخران', '<span class=\"hlight\">آخران .</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (ع اِ) دو پستان شتر که پیوسته ٔ بهم است، در دنبال قادمان .<br /></font></div>'),
(706, 'آخربین', '<span class=\"hlight\">آخربین .</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (نف مرکب ) عاقبت اندیش . آنکه در پایان و آخر و نتیجه ٔ کارها اندیشد از پیش <span class=\"hlight\">:</span> <br />در پس هر گریه آخر خنده ای است <br />مرد آخربین مبارک بنده ای است .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(707, 'آخربین', '<span class=\"hlight\">آخربین .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (نف مرکب ) آنکه از دوستی نظر بسود و نفع دارد و بس .<br /></font></div>'),
(708, 'آخربینی', '<span class=\"hlight\">آخربینی .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (حامص مرکب ) صفت آخُربین .<br /></font></div>'),
(709, 'آخربینی', '<span class=\"hlight\">آخربینی .</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (حامص مرکب ) صفت آخِربین .<br /></font></div>'),
(710, 'آخرت', '<span class=\"hlight\">آخرت .</span> <font color=\"DarkGreen\"><b>[ خ ِ رَ ]</font></b> (ع اِ) آخِره . آن جهان . آن سرای . عقبی ̍. معاد. دارالخلد. عجوز. آجل . آجله . اخری ̍. مقابل اولی ̍ و دنیا <span class=\"hlight\">:</span> و هر گاه که متقی در کار این جهان گذرنده تأملی کند هرآینه مقابح آن را بنظر بصیرت بیند... و با یاد آخرت الفت گیرد. (کلیله و دمنه ). و آنکه سعی برای مصالح دنیا مصروف دارد زندگانی بر وی وبال باشد و از ثواب آخرت بازماند. حاصل آن <font color=\"DarkGreen\"><b>[ راحتی اندک ]</font></b> اگر میسر گردد خسران دنیا و آخرت باشد. (کلیله و دمنه ). و اگر بقضاء مقرون گردد عز دنیا و آخرت مرا بهم پیوندد. (کلیله و دمنه ). و نیز آنکه سعی برای آخرت کند مرادهای دنیا بتبعیت بیابد. (کلیله و دمنه ). آخر رای من بر عبادت قرار گرفت چه مشقت طاعت در جنب نجات آخرت وزنی نیارد. (کلیله و دمنه ). و بحال خردمند آن لایقتر که همیشه طلب آخرت را بر دنیا مقدم دارد. (کلیله و دمنه ).<br />دنیا پلی است رهگذر دار آخرت <br />اهل تمیز خانه نگیرند بر پلی .<br /> <font color=\"Red\">سعدی .</font><br />دوست بدنیا و آخرت نتوان داد<br />صحبت یوسف به از دراهم معدود.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عشاء آخرت، عشاء آخره </span> ؛ نماز خفتن .<br /></font></div>'),
(711, 'آخرخشک', '<span class=\"hlight\">آخرخشک .</span> <font color=\"DarkGreen\"><b>[ خ ُ خ ُ ]</font></b> (ص مرکب ) آخورخشک . آنکه چیزی ندارد. فقیر.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(712, 'آخردانی', '<span class=\"hlight\">آخردانی .</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (حامص مرکب ) صفت آنکه پیش بین باشد و نتیجه ٔ کارها را پیش از وقوع داند.<br /></font></div>'),
(713, 'آخردست', '<span class=\"hlight\">آخردست .</span> <font color=\"DarkGreen\"><b>[ خ ِ دَ ]</font></b> (اِ مرکب ) آخربار. <BR><font color=\"Blue\">◄</font> پایان خانه، و مرادف آن صف نعال و پای ماچان است . <BR><font color=\"Blue\">◄</font> داو آخر قمار که دست آخر هم گویند. <BR><font color=\"Blue\">◄</font> آخر و پایان کار.<br /></font></div>'),
(714, 'آخرزمان', '<span class=\"hlight\">آخرزمان .</span> <font color=\"DarkGreen\"><b>[ خ ِ زَ ]</font></b> (اِ مرکب ) آخرالزّمان . قسمت واپسین از دوران که بقیامت پیوندد <span class=\"hlight\">:</span> <br />خواهم شدن بکوی مغان آستین فشان <br />زین فتنه ها که دامن آخرزمان گرفت .<br /> <font color=\"Red\">حافظ.</font><br />از آن زمان که فتنه ٔ چشمت بمن رسید<br />ایمن ز شر فتنه ٔ آخرزمان شدم .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">پیغمبر آخرالزمان یا آخرزمان </span> ؛ رسول خاتم، صلوات اﷲعلیه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مهدی آخرزمان </span> ؛ مهدی موعود علیه السلام .<br /></font></div>'),
(715, 'آخرسالار', '<span class=\"hlight\">آخرسالار.</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (ص مرکب، اِ مرکب ) آخورسالار. میرآخر. آنکه ریاست پرستاران ستور، خاصه اسب با اوست <span class=\"hlight\">:</span> ایشان <font color=\"DarkGreen\"><b>[ زنان دعوت شده ٔ زلیخا ]</font></b> پنج زن بودند یکی زن حاجب و یکی زن شرطه و یکی زن خوان سالار و یکی زن شرابدار و یکی زن آخرسالار. (بلعمی ترجمه ٔ طبری ).<br />آخرسالار جبرئیل است .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(716, 'آخرلو', '<span class=\"hlight\">آخرلو.</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (اِخ ) نام طایفه ای از ایل قشقایی دارای بیست خانوار.<br /></font></div>'),
(717, 'آخرملو', '<span class=\"hlight\">آخرملو.</span> <font color=\"DarkGreen\"><b>[ خ ِ رِ ]</font></b> (اِخ ) نام یکی از طوایف ایل قشقایی دارای چهل خانوار ساکن چهاردانگه .<br /></font></div>'),
(718, 'آخرنفس', '<span class=\"hlight\">آخرنفس .</span> <font color=\"DarkGreen\"><b>[ خ ِ ن َ ف َ ]</font></b> (اِ مرکب ) رمق .نیم جان . باقی جان . حشاشه . نیمه ٔ جان . دَم واپسین .<br /></font></div>'),
(719, 'آخره', '<span class=\"hlight\">آخره .</span> <font color=\"DarkGreen\"><b>[ خ ُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) آخوره . آخُرک . ترقوه . چنبره ٔ گردن . <BR><font color=\"Blue\">◄</font> گودی که در میان توده ٔ خاک کنند تا در آن آب ریزند گل ساختن را. <BR><font color=\"Blue\">◄</font> طویله، به معنی طنابی درازو برکشیده که چندین اسب بدو توان بستن <span class=\"hlight\">:</span> <br />تیغزنان میرسد خسرو انجم ز شرق <br />کو همه شب دررمید زآخره ٔ کهکشان .<br /><font color=\"Red\">عزالدین شروانی .</font><br /></font></div>'),
(720, 'آخره', '<span class=\"hlight\">آخره .</span> <font color=\"DarkGreen\"><b>[ خ ِ رَ ]</font></b> (ع ص ) تأنیث آخر. نقیض متقدمه . <BR><font color=\"Blue\">◄</font> (اِ) پس پالان . پس کوهه ٔ پالان . آخرةالرحل . ج، اواخر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آخره ٔ عین </span> ؛ دنباله ٔ چشم .<br /></font></div>'),
(721, 'آخرچرب', '<span class=\"hlight\">آخرچرب .</span> <font color=\"DarkGreen\"><b>[ خ ُ چ َ ]</font></b> (ص مرکب ) آنکه در رفاه و نعمت و فراوانی است .<br /></font></div>'),
(722, 'آخرچی', '<span class=\"hlight\">آخرچی .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (ص مرکب، اِ مرکب ) آخورچی . جلودار اسبان :<br />درزمان ْ آخرچیان چست و خوش <br />گوشه ٔ افسار او گیرند و کش .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(723, 'آخرک', '<span class=\"hlight\">آخرک .</span> <font color=\"DarkGreen\"><b>[ خ ُ رَ ]</font></b> (اِ مصغر) آخُرِ خُرد. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) ترقوه . چنبر گردن . آخُره <span class=\"hlight\">:</span> <br />تیغ تو تیز نیست که شد خنک توسنی (کذا)<br />درخورد او بگردن خصم آخرک بود.<br /><font color=\"Red\">امیرخسرو.</font><br /></font></div>'),
(724, 'آخرکانک', '<span class=\"hlight\">آخرکانک .</span> <font color=\"DarkGreen\"><b>[ خ ُ ن َ ]</font></b> (اِخ ) نام شهری بدهستان مازندران و نسبت بدان آخری باشد. (فیروزآبادی ). و از آنجاست اسماعیل بن احمد و عباس بن احمدبن فضل . رجوع به آخُر شود.<br /></font></div>'),
(725, 'آخری', '<span class=\"hlight\">آخری .</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (ص نسبی ) در محاوره ٔ عامه بجای آخرین به معنی پسین .<br /></font></div>'),
(726, 'آخریان', '<span class=\"hlight\">آخریان .</span> (اِ) اَخْریان . جهاز. بتات . (مهذب الاسماء). اثاث البیت . سِلْعة. متاع . کالا. (زمخشری ). قماش .مال التجارة: رسم آن بازار چنان بوده است که هرچه آخریان معیوب بودی از برده و ستور و دیگر آخریان باعیب، همه بدین بازار فروختندی . (تاریخ بخارای نرشخی ).<br />آخریان خرد سفته فرستم بدوست <br />هیچ ندارم دگر چون دل و جان نزد اوست .<br /> <font color=\"Red\">عسجدی .</font><br />و اما حال وجود آخریان، از حال کواکب جنس آخریان نگرند. (کفایةالتعلیم در نجوم ). چون دلیل آخریان بدرجه ٔ عاشر رسد یا درجه ٔ طالع...... نرخ آخریان زیادت گردد. (کفایةالتعلیم ).<br /></font></div>'),
(727, 'آخرین', '<span class=\"hlight\">آخرین .</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (ع ص، اِ) ج ِ آخَر. دیگران .<br /></font></div>'),
(728, 'آخرین', '<span class=\"hlight\">آخرین .</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (ص نسبی ) بترکیب فارسی بمعنی پسین و واپسین . ج، آخرینان : آخرین نفس، آخرین لحظه .<br /></font></div>'),
(729, 'آخرین', '<span class=\"hlight\">آخرین .</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (ع ص، اِ) ج ِ آخِر. بازپسینان .<br /></font></div>'),
(730, 'آخسمه', '<span class=\"hlight\">آخسمه .</span> <font color=\"DarkGreen\"><b>[ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ) آخمسه . اَخْسمه . اَخْمسه . شرابی که از ذرت و جویا برنج و ارزن کنند. بوزه . و اقسما معرب آن است .<br /></font></div>'),
(731, 'آخسی', '<span class=\"hlight\">آخسی .</span> (اِخ ) آخسیکت .<br /></font></div>'),
(732, 'آخسیکت', '<span class=\"hlight\">آخسیکت .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) رجوع به اَخسیکت شود.<br /></font></div>'),
(733, 'آخش', '<span class=\"hlight\">آخش .</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (صوت ) از اصوات، و حکایت از درد یا خوشی کند.<br /></font></div>'),
(734, 'آخش', '<span class=\"hlight\">آخش .</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (اِ) قیمت . بها. ارز. ارزش . صاحب معیار جمالی کلمه را بمد الف و فتح خا ضبط کرده، و بیتی نیز برای دعوی خود ساخته است و ظاهراً این درست نیست و اَخْش بر وزن بخش صحیح است، چنانکه عنصری گوید <span class=\"hlight\">:</span> <br />خود نماید همیشه مهر فروغ <br />خود فزاید همیشه گوهر اخش .<br /></font></div>'),
(735, 'آخش', '<span class=\"hlight\">آخش .</span> (اِخ ) نام موبدی پارسی نژاد که او مایه ٔ عناصر را پروردگار شناسد. (برهان ).<br /></font></div>'),
(736, 'آخشام زدن', '<span class=\"hlight\">آخشام زدن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ ]</font></b> (مص مرکب )(از ترکی آقشام به معنی شام و شبانگاه ) آقشام زدن . زدن نوبت بر در پادشاهان و حکام گاه فروشدن آفتاب .<br /></font></div>'),
(737, 'آخشمه', '<span class=\"hlight\">آخشمه .</span> <font color=\"DarkGreen\"><b>[ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ) رجوع به آخسمه شود.<br /></font></div>'),
(738, 'آخشیج', '<span class=\"hlight\">آخشیج .</span> (اِ) عنصر. طبع. اسطقس ّ. آخشیگ <span class=\"hlight\">:</span> <br />خداوند ما کاین جهان آفرید<br />بلند آسمان از برش برکشید<br />فراز آورید آخشیجان چهار<br />کجا اندرو بست چندین نگار<br />برین آتش است و فرودینْش خاک <br />میان آب دارد ابا باد پاک .<br /> <font color=\"Red\">ابوشکور.</font><br />ای خداوندی که از بیم سر شمشیر تو<br />از میان آخشیجان شد گسسته داوری .<br /> <font color=\"Red\">عنصری .</font><br />درختی شناس این جهان فراخ <br />سپهرش چو بیخ آخشیجانْش شاخ .<br /> <font color=\"Red\">اسدی .</font><br />همه از رای خود موجود گشتند<br />ببستند آخشیجان یک بدیگر!<br /> <font color=\"Red\">ناصرخسرو.</font><br />اگر جهان خرد خوانیم رواست که من <br />هم آخشیجم و هم مرکز و هم ارکانم .<br /> <font color=\"Red\">مسعودسعد.</font><br />بساختند چهارآخشیج دشمن ازآن <br />که رای تست بحق گشته در میان داور.<br /> <font color=\"Red\">مسعودسعد.</font><br />آخشیجان و گنبد دوار<br />مردگانند زندگانی خوار.<br /> <font color=\"Red\">سنائی .</font><br />تا سه فرزند آخشیجان را<br />چار مادر چنانکه نُه پدر است <br />ناگزیر زمانه باد بقات <br />تا زچار و نه و سه درگذر است .<br /> <font color=\"Red\">انوری .</font><br />بردم از نرّادگیتی یک دو داو اندر دو زخم <br />گرچه از چارآخشیج و پنج حس در ششدرم .<br /> <font color=\"Red\">خاقانی .</font><br />توئی گوهرآمای چارآخشیج <br />مسلسل کن ِ گوهران در مزیج .<br /> <font color=\"Red\">نظامی .</font><br />اختر و آسمان کمر بستند<br />بچهارآخشیج پیوستند.<br /> <font color=\"Red\">اوحدی .</font><br />بخواهد کجا ساز لشکر بسیج <br />بهم مویه آرند چارآخشیج .<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> هیولی، در زبان حکمت مقابل صورت <span class=\"hlight\">:</span> <br />ز آخشیج هر آن صورتی که برخیزد<br />اگر بجود بود فخر، فخر آن صوری .<br /> <font color=\"Red\">ازرقی .</font><br /> <BR><font color=\"Blue\">◄</font> مجازاً، ضدیت . معادات . جدال . جنگ . نزاع . منازعت . مخالفت <span class=\"hlight\">:</span> <br />گزیده جهان ز تست بدو در جهانیان <br />همارا به آخشیج همارا بکارزار.<br /> <font color=\"Red\">رودکی .</font><br /> <BR><font color=\"Blue\">◄</font> ضد <span class=\"hlight\">:</span> <br />کجا جوهری چیره شد زین چهار<br />یکی آخشیجش برو بر گمار.<br /> <font color=\"Red\">ابوشکور.</font><br />ز عزم و حزم تو ماند دو آخشیج اثر<br />هوا شتاب عجول و زمین درنگ صبور.<br /> <font color=\"Red\">اخسیکتی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چارآخشج، چهارآخشیج </span> ؛ عناصر اربعه یعنی خاک و آب و باد و آتش .<br /></font></div>'),
(739, 'آخشیدیان', '<span class=\"hlight\">آخشیدیان .</span> (اِخ ) رجوع به اِخشیدیان شود.<br /></font></div>'),
(740, 'آخشیگ', '<span class=\"hlight\">آخشیگ .</span> (اِ) رجوع به آخشیج شود.<br /></font></div>'),
(741, 'آخشیگان', '<span class=\"hlight\">آخشیگان .</span> (اِ) ج ِ آخشیگ .<br /></font></div>'),
(742, 'آخمسه', '<span class=\"hlight\">آخمسه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ُ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ) آخمشه . رجوع به آخسمه شود.<br /></font></div>'),
(743, 'آخنی', '<span class=\"hlight\">آخنی .</span> <font color=\"DarkGreen\"><b>[ خ ِ نی ی ]</font></b> (ع اِ) جامه ٔ بخط. ثوب مخطط. گلیم سیاه نرم که نصاری پوشیدندی . کتان ردی ّ.<br /></font></div>'),
(744, 'آخنیه', '<span class=\"hlight\">آخنیه .</span> <font color=\"DarkGreen\"><b>[ خ ِ نی ی َ ]</font></b> (ع اِ) کمانها.<br /></font></div>'),
(745, 'آخور', '<span class=\"hlight\">آخور.</span> <font color=\"DarkGreen\"><b>[ خُرْ ]</font></b> (اِ) آخُر (در تمام معانی ) <span class=\"hlight\">:</span> <br />چنان بد که اسبی ز آخور بجست <br />که بد شاه پرویز رابرنشست .<br /> <font color=\"Red\">فردوسی .</font><br />دگر اسب جنگی چل وشش هزار<br />که بودند بر آخور شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />دو اسب گرانمایه زآخور ببرد<br />گزیده سلیح سواران گرد.<br /> <font color=\"Red\">فردوسی .</font><br />ز آخور همانگه یکی کرّه خواست <br />بزین اندرون نوز ناگشته راست .<br /> <font color=\"Red\">فردوسی .</font><br />ز آخور ببرده ست خنگ و سیاه <br />که بد باره ٔ نامبردار شاه .<br /> <font color=\"Red\">فردوسی .</font><br />هر آنکس که آواز او بشنود<br />ز پیش سپهبد به آخور دود.<br /> <font color=\"Red\">فردوسی .</font><br />همانگه فرستادگان را براه <br />از ایوان فرستاد نزد سپاه <br />که تا اسب گردان به آخور برند<br />ازافکندنیها همه بشمرند.<br /> <font color=\"Red\">فردوسی .</font><br />ز کرسی و خرگاه و پرده سرای <br />همان خیمه و آخور و چارپای <br />شتر بود بیش اندر آن پنج صد<br />همه کرده آن رسم را نامزد.<br /> <font color=\"Red\">فردوسی .</font><br />بیاورد لشکر بدشت شکار<br />سواران شمشیرزن سی هزار<br />ببردند خرگاه و پرده سرای <br />همان خیمه و آخور و چارپای .<br /> <font color=\"Red\">فردوسی .</font><br />ز ایوان و خرگاه و پرده سرای <br />همان خیمه و آخور و چارپای .<br /> <font color=\"Red\">فردوسی .</font><br /> <br />قوت آرزو و قوت خشم در طاعت قوت خرد باشند... و چون آرزو آید سگالش کند درِ آخورش استوار ببندد چنانکه گشاده نتواند شد. (تاریخ بیهقی ).<br /></font></div>'),
(746, 'آخور خشک', '<span class=\"hlight\">آخور خشک .</span> <font color=\"DarkGreen\"><b>[ خ ُ رِ خ ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) آخُرِ خشک . آخری که علوفه در آن نباشد. <BR><font color=\"Blue\">◄</font> آخر بی آب . <BR><font color=\"Blue\">◄</font> مجازاً، جایی که نعمت و رفاه در آن نیست .<br /></font></div>'),
(747, 'آخور سنگین', '<span class=\"hlight\">آخور سنگین .</span> <font color=\"DarkGreen\"><b>[ خ ُ رِ س َ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به آخر سنگین شود.<br /></font></div>'),
(748, 'آخور چرب', '<span class=\"hlight\">آخور چرب .</span> <font color=\"DarkGreen\"><b>[ خ ُ رِچ َ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به آخر چرب شود.<br /></font></div>'),
(749, 'آخورجای', '<span class=\"hlight\">آخورجای .</span> <font color=\"DarkGreen\"><b>[ خُرْ ]</font></b> (اِ مرکب ) اسطبل .<br /></font></div>'),
(750, 'آخورسالار', '<span class=\"hlight\">آخورسالار.</span> <font color=\"DarkGreen\"><b>[ خُرْ ]</font></b> (ص مرکب، اِ مرکب ) رجوع به آخرسالار شود <span class=\"hlight\">:</span> و پانصد استر با ده مرد آخورسالار همیشه غله ٔ او به استراباد و دامغان بردندی برای فروختن . (تاریخ طبرستان ).<br />یکی کهتری نامبردار بود<br />که بر آخور شاه سالار بود.<br /> <font color=\"Red\">فردوسی .</font><br />بدان آخور اسب سالار باش <br />بهر کار با هر کسی یار باش .<br /> <font color=\"Red\">فردوسی .</font><br />چو آن کردنی کارها کرد راست <br />ز سالار آخور خری ده بخواست .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(751, 'آخوره', '<span class=\"hlight\">آخوره .</span> <font color=\"DarkGreen\"><b>[ خ ُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) رجوع به آخره شود.<br /></font></div>'),
(752, 'آخورچی', '<span class=\"hlight\">آخورچی .</span> <font color=\"DarkGreen\"><b>[ خُرْ ]</font></b> (ص مرکب، اِ مرکب ) آخرچی . جلودار اسبان <span class=\"hlight\">:</span> <br />تو مگو کآن بنده آخورچی ّ ماست <br />این بدان که گنج در ویرانه ها است .<br /> <font color=\"Red\">مولوی .</font><br />رجوع به آخرچی شود.<br /></font></div>'),
(753, 'آخورک', '<span class=\"hlight\">آخورک .</span> <font color=\"DarkGreen\"><b>[ خ ُ رَ ]</font></b> (اِ مرکب ) رجوع به آخرک و آخره شود.<br /></font></div>'),
(754, 'آخورگاه', '<span class=\"hlight\">آخورگاه .</span> <font color=\"DarkGreen\"><b>[ خُرْ ]</font></b> (اِ مرکب ) آخورگه . آخُر <span class=\"hlight\">:</span> <br />ابلق ایام در آخورگهش <br />زاویه ٔ فخر و تفاخرگهش .<br /><font color=\"Red\">امیرخسرو دهلوی .</font><br /></font></div>'),
(755, 'آخوند', '<span class=\"hlight\">آخوند.</span> <font color=\"DarkGreen\"><b>[ خو <span class=\"hlight\" dir=\"rtl\">/</span> خُن ْ ]</font></b> (ص، اِ) (شاید مخففی از آغا + خوندگار، به معنی خداوندگار) ملا. منلا. عالم . طالب علوم دینیه . <BR><font color=\"Blue\">◄</font> مکتب دار کودکان . معلم کُتّاب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آخوندبازی </span> ؛ توسل بحیل شرعی .<br />آخوند نباشد درد و غم، گفتن ؛ کسی را که بیمار نیست به القاء بیمار کردن .<br /></font></div>'),
(756, 'آخوندلی لی', '<span class=\"hlight\">آخوندلی لی .</span> (اِخ ) رجوع به باغ آخوندلی لی شود.<br /></font></div>'),
(757, 'آخوندمحله', '<span class=\"hlight\">آخوندمحله .</span> <font color=\"DarkGreen\"><b>[ م َ ح َل ْ ل َ ]</font></b> (اِخ ) مرکز خره ٔ سخت سر در تنکابن مازندران، نزدیک رامسر، میان راه رامسربلنگرود و رامسر و دریاپسته در <span class=\"hlight\" dir=\"rtl\">٤٨٤٧٠٠</span> گزی تهران .<br /></font></div>'),
(758, 'آخوندک', '<span class=\"hlight\">آخوندک .</span> <font color=\"DarkGreen\"><b>[ خو <span class=\"hlight\" dir=\"rtl\">/</span> خُن ْ دَ ]</font></b> (اِ مرکب ) نام عام دو حشره از ملخ بزرگتر با پاهای بلند و سری بزرگ برنگ سبز.<br /></font></div>'),
(759, 'آخچه', '<span class=\"hlight\">آخچه .</span> <font color=\"DarkGreen\"><b>[ چ َ ]</font></b> (اِخ ) شهری بیازده فرسنگی بلخ از سوی مغرب با حصاری محکم دارای هفت هزار سکنه .<br /></font></div>'),
(760, 'آخیز', '<span class=\"hlight\">آخیز.</span> (اِ) قالب خشت . مهره ٔ دیوار. رهص . باخز.<br /></font></div>'),
(761, 'آخیزگر', '<span class=\"hlight\">آخیزگر.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (ص مرکب ) رهاص . دیوارزن . مهره زن (مراد از مهره هر یک از طبقات گلین است که در چینه ای برهم نهند).<br /></font></div>'),
(762, 'آخیسه', '<span class=\"hlight\">آخیسه .</span> <font color=\"DarkGreen\"><b>[ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ) پیش آهنگ گله ٔ گوسفند. <BR><font color=\"Blue\">◄</font> سنگ میل که بر سر فرسنگها نهند نشانه را.<br /></font></div>'),
(763, 'آخیه', '<span class=\"hlight\">آخیه .</span> <font color=\"DarkGreen\"><b>[ خی ی َ ]</font></b> (ع اِ) میخ آخُر. جای اسب بستن . ادرون . آنچه ستور را بدان بندند. آخُر اسب . (نطنزی ). میخ و گوشه ٔ دوال که اسب را در آخر بر وی بندند. (صراح اللغة). رسنی یا دوالی که هر دو طرف آن در دیوار یادر زمین نیک فروبرده باشند و میان هر دو حلقه مانندی بیرون باشد که چارپای بدان بندند. آری ّ. اَخیه . <BR><font color=\"Blue\">◄</font> توسعاً، اسطبل . ج، اواخی <span class=\"hlight\">:</span> عن النبی صلی اﷲعلیه وسَلم انه قال مثل المؤمن کمثل الفرس فی آخیته یجول و یرجع الی آخیته و ان ّ المؤمن یسهو ثم یرجع الی الایمان . (از عوارف المعارف امام سهروردی ). <BR><font color=\"Blue\">◄</font> طناب خیمه . <BR><font color=\"Blue\">◄</font> حرمت . عهد.<br /></font></div>'),
(764, 'آخیه خانه', '<span class=\"hlight\">آخیه خانه .</span> <font color=\"DarkGreen\"><b>[ خی ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) طویله . اصطبل . پاگاه . آخُر.<br /></font></div>'),
(765, 'آد', '<span class=\"hlight\">آد.</span> <font color=\"DarkGreen\"><b>[ آدد ]</font></b> (ع اِ) غلبه . قهر. <BR><font color=\"Blue\">◄</font> قوّت . نیرو. زور. <BR><font color=\"Blue\">◄</font> سختی .<br /></font></div>'),
(766, 'آداب', '<span class=\"hlight\">آداب .</span> (ع اِ) ج ِ اَدَب . رسوم <span class=\"hlight\">:</span> نصر احمد سامانی ... سخت نیکو برآمد و بر همه ٔ آداب ملوک سوار شد. (تاریخ بیهقی ). گفت <font color=\"DarkGreen\"><b>[ دزدی ]</font></b> میخواهم ... آداب طریقت آموزم . (کلیله و دمنه ).<br />موسیا آداب دانان دیگرند<br />سوخته جان و روانان دیگرند.<br /> <font color=\"Red\">مولوی .</font><br />هیچ ترتیبی و آدابی مجو<br />هرچه میخواهد دل تنگت بگو.<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آداب فاضله </span> ؛ اخلاق ستوده . محاسن .<br /></font></div>'),
(767, 'آداب البحث', '<span class=\"hlight\">آداب البحث .</span> <font color=\"DarkGreen\"><b>[ بُل ْ ب َ ]</font></b> (ع اِ مرکب ) صناعت نظری که آدمی را بکیفیت مناظره و شرائط آن آشنا سازد تا در بحث و الزام و غلبه ٔ بر خصم خطا نکند. (تعریفات جرجانی ).<br /></font></div>'),
(768, 'آداب اللسان', '<span class=\"hlight\">آداب اللسان .</span> <font color=\"DarkGreen\"><b>[ بُل ْ ل ِ ]</font></b> (ع اِ مرکب ) علوم ادبیه .<br /></font></div>'),
(769, 'آداد', '<span class=\"hlight\">آداد.</span> (ع اِ) ج ِ اَدّ و اِدّ و اِدّه .<br /></font></div>'),
(770, 'آداران', '<span class=\"hlight\">آداران .</span> (اِخ ) نام محلی کناره ٔ راه طهران بچالوس میان پورکان و دارپان در شصت و یک هزار و سیصد گزی طهران .<br /></font></div>'),
(771, 'آداش', '<span class=\"hlight\">آداش .</span> (ترکی، ص مرکب، اِ مرکب ) آتاش . سمی ّ. همنام <span class=\"hlight\">:</span> <br />گر کار بنامستی از آداشی عمّر<br />فرزند تو با عمّر بودستی هموار.<br /><font color=\"Red\">ناصرخسرو.</font><br />رجوع به آتاش شود.<br /></font></div>'),
(772, 'آدام', '<span class=\"hlight\">آدام .</span> (ع اِ) ج ِ اِدام و اَدیم .<br /></font></div>'),
(773, 'آداک', '<span class=\"hlight\">آداک .</span> (اِ)آدَک . اَداک . خشکی میان آب . آبخو. آبخوست . جزیره .<br /></font></div>'),
(774, 'آدب', '<span class=\"hlight\">آدب .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (ع ص ) بمیهمانی خواننده . میزبان .<br /></font></div>'),
(775, 'آدخ', '<span class=\"hlight\">آدخ .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ص ) خوب . نغز. نیکو. میمون . مسعود. خجسته . مبارک . دَخ <span class=\"hlight\">:</span> <br />روز تو هرگز بایمان سعد و میمون کی شود<br />چون تو بر ابلیس ملعون خویشتن مفتون کنی <br />گر بشارستان علم اندر، بگیری خانه ای <br />روز خویش امروز و فردا آدخ و میمون کنی .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> (اِ) بلندی در زمین . تل .<br /></font></div>'),
(776, 'آدر', '<span class=\"hlight\">آدر.</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ) آذر. آتش .<br /></font></div>'),
(777, 'آدر', '<span class=\"hlight\">آدر.</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِ) نشتر فصاد و رگ زن .<br /></font></div>'),
(778, 'آدر', '<span class=\"hlight\">آدر.</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ع ص ) بادخایه . دبه . (مهذب الاسماء). دبه خایه . غر. بادخصیه . ج، اُدُر.<br /></font></div>'),
(779, 'آدرخش', '<span class=\"hlight\">آدرخش .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) برق . <BR><font color=\"Blue\">◄</font> درخش . صاعقه . آتش آسمانی <span class=\"hlight\">:</span> <br />نباشد زین زمانه بس شگفتی <br />اگر بر ما ببارد آدرخشا.<br /> <font color=\"Red\">رودکی .</font><br />خصمت بود به جنگ خف و تیرت آدرخش <br />تو همچو کوه و تیربداندیش تو صدا.<br /> <font color=\"Red\">اسدی .</font><br />و بهر دو معنی با ذال نقطه دار نیز آمده است . <BR><font color=\"Blue\">◄</font> سرما. <BR><font color=\"Blue\">◄</font> رعد. (برهان ).<br /></font></div>'),
(780, 'آدرس', '<span class=\"hlight\">آدرس .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (فرانسوی، اِ) نشانی خانه و جز آن . عنوان و نام کسی بر سر نامه یا پشت پاکت .<br /></font></div>'),
(781, 'آدرفش', '<span class=\"hlight\">آدرفش .</span> <font color=\"DarkGreen\"><b>[ دِ رَ ]</font></b> (اِ) درفش . بیز.<br /></font></div>'),
(782, 'آدرم', '<span class=\"hlight\">آدرم .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) نمدزین . آدرمه . آترمه . ادرمه . آشرمه <span class=\"hlight\">:</span> <br />مرد را آکنده از گرد سواران چشم و گوش <br />اسب را آغشته اندر خون مردم آدرم .<br /> <font color=\"Red\">مختاری غزنوی .</font><br />دو پهلوی من از خشکی بسوده <br />چو آن اسبی که او را آدرم نه .<br /> <font color=\"Red\">شرف الدین شفروه .</font><br /><BR><font color=\"Blue\">◄</font> سلاح چون خنجر و شمشیر و تیر و کمان و امثال آن . صاحب فرهنگ منظومه گفته است <span class=\"hlight\">:</span> <br />چیست انجام آخر کار است <br />آدرم اسلحه که خونخوار است .<br /> <BR><font color=\"Blue\">◄</font> زینی که نمدزین او دونیم بود. <BR><font color=\"Blue\">◄</font> درفش که بدان نمدزین دوزند. و رجوع به اَدرمکش شود. در تمام معانی آذرم بذال نقطه دار نیز آمده است . و شیخ نظامی این کلمه را بفتح دال و سکون را آورده است به معنی درفش و بیز <span class=\"hlight\">:</span> <br />دباغت چنان دادم این چرم را<br />که برتابد آسیب آدرم را.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(783, 'آدرنج', '<span class=\"hlight\">آدرنج .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) رجوع به اَدرنج و اُشکز شود.<br /></font></div>'),
(784, 'آدرنگ', '<span class=\"hlight\">آدرنگ .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) رنج . محنت . آفت <span class=\"hlight\">:</span> <br />از چشم بد ای مرا چو دیده <br />یک روز مباد آدرنگت .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> نیستی و نابودی و زوال <span class=\"hlight\">:</span> <br />مهرگان بر تو مبارک باد از گشت سپهر<br />جاه تو بی عیب باد و عمر تو بی آدرنگ .<br /> <font color=\"Red\">معزی .</font><br /><BR><font color=\"Blue\">◄</font> خدوک . غم . اندوه . <BR><font color=\"Blue\">◄</font> دمار. هلاک . <BR><font color=\"Blue\">◄</font> (ص ) روشن .منور. شاید مخفف آدررنگ مرادف آذررنگ . و به معنی آذرنگ بذال معجمه در تمام معانی آن نیز آمده است .<br /></font></div>'),
(785, 'آدره', '<span class=\"hlight\">آدره .</span> <font color=\"DarkGreen\"><b>[ دِ رَ ]</font></b> (ع ص ) شبی سرد. (مهذب الاسماء).<br /></font></div>'),
(786, 'آدریاتیک', '<span class=\"hlight\">آدریاتیک .</span> (اِخ ) اَدریاتیک . نام خلیجی بزرگ به بحرالروم که ممالک ایتالیا و یوگوسلاوی و آلبانی بر ساحل آن است و رود پو در آن ریزد.<br /></font></div>'),
(787, 'آدرین', '<span class=\"hlight\">آدرین .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) آدریانوس . نام عظیمی از عظماء روم متولد در <span class=\"hlight\" dir=\"rtl\">٧٦</span> م . وی پسرخوانده ٔ تراژان بود و چون تراژان بمرد جانشین او گردیده (<span class=\"hlight\" dir=\"rtl\">١١٧</span> - <span class=\"hlight\" dir=\"rtl\">١٣٨</span> م .). و بصنعت و ادبیات شوقی وافی داشت و قلاع و استحکامات بسیار در حدود مملکت برآورد.<br /></font></div>'),
(788, 'آدریون', '<span class=\"hlight\">آدریون .</span> <font color=\"DarkGreen\"><b>[ دَرْ ]</font></b> (اِ مرکب ) آذریون .<br /></font></div>'),
(789, 'آدغر', '<span class=\"hlight\">آدغر.</span> <font color=\"DarkGreen\"><b>[ غ َ ]</font></b> (اِ) ظاهراً مصحف بادغر. مکان تابستانی .<br /></font></div>'),
(790, 'آدفنداک', '<span class=\"hlight\">آدفنداک .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (اِ) قوس قُزح . رجوع به آزفنداک شود.<br /></font></div>'),
(791, 'آدل', '<span class=\"hlight\">آدل .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) قسمتی از سواحل افریقا در انتهای خلیج عدن که سکنه ٔ آن آفاریاداناکیل خوانده میشوند.<br /></font></div>'),
(792, 'آدم', '<span class=\"hlight\">آدم .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) نام پدر سنائی، شاعر معروف .<br /></font></div>'),
(793, 'آدم', '<span class=\"hlight\">آدم .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ع ص ) گندم گون . سیاه گونه . سیه چرده . اَسْمَر. <BR><font color=\"Blue\">◄</font> و در آهو، سفیدی که خطهای خاکی رنگ دارد. <BR><font color=\"Blue\">◄</font> اشتر سفید. ج، اُدْم، اُدْمان .<br /></font></div>'),
(794, 'آدم', '<span class=\"hlight\">آدم .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) نخستین پدر آدمیان، جفت حوّا. (توریة). ابوالبشر. بوالبشر. خلیفةاﷲ. صفی اﷲ. ابوالوری . ابومحمد. معلم الاسماء. ج، اوادِم <span class=\"hlight\">:</span> <br />تا جهان بود از سر آدم فراز<br />کس نبود از راه دانش بی نیاز.<br /> <font color=\"Red\">رودکی .</font><br />نشیبت فراز و فرازت نشیب <br />چو فرزند آدم بشیب و بتیب .<br /> <font color=\"Red\">رودکی .</font><br />یک بار طبع آدمیان گیر و مردمان <br />گرْت آدم است بابک و فرزند بابکی .<br /> <font color=\"Red\">اسدی .</font><br />ورنه آدم کی بگفتی با خدا<br />ربّنا انّا ظلمنا نفسنا.<br /> <font color=\"Red\">مولوی .</font><br />اکبر و اعظم خدای عالم و آدم <br />صورت خوب آفرید و سیرت زیبا.<br /> <font color=\"Red\">سعدی .</font><br />بنی آدم اعضای یکدیگرند<br />که در آفرینش ز یک گوهرند.<br /> <font color=\"Red\">سعدی .</font><br />حدیث عشق اگر گوئی گناه است <br />گناه اول ز حوّا بود و آدم .<br /> <font color=\"Red\">سعدی .</font><br />در نقد عیش کوش که چون آبخور نماند<br />آدم بهشت روضه ٔ دارالسلام را.<br /> <font color=\"Red\">حافظ.</font><br /><BR><font color=\"Blue\">◄</font> نامی است از نامها، ازجمله ابوبکر احمدبن آدم الادمی المحدث .<br /></font></div>'),
(795, 'آدم', '<span class=\"hlight\">آدم .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ) در تداول امروزی مرادف مردم . آدمی . آدمیان . اِنْس .ناس . <BR><font color=\"Blue\">◄</font> خادم .ج، آدمها. <BR><font color=\"Blue\">◄</font> (ص ) نیک تربیت شده . مؤدب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آدم از کوچکی بزرگ میشود</span> ؛ خضوع و فروتنی سبب بزرگی مردشود.<br /> <span class=\"hlight\">آدم به آدم بسیار ماند</span> ؛ آنکس نیست که گمان برده اید.<br /> <span class=\"hlight\">آدم به آدم می رسد</span> ؛ مردمان بایدبیکدیگر مدد و یاری دهند.<br /> <span class=\"hlight\">آدم به آدم میرسد کوه بکوه نمیرسد</span> ؛ هرچند سالها یا مرحله ها از یکدیگر دور بودیم و امید دیدار نداشتیم اکنون باز یکدیگر را دیدیم .<br /> <span class=\"hlight\">آدم با آدم خوش است </span> ؛ لذت حیات در معاشرت و خلطه و آمیزش است .<br /> <span class=\"hlight\">آدم با کسی که علی گفت عمر نمیگوید</span> ؛ نفاق پس از اتفاق نیکو نباشد.<br /> <span class=\"hlight\">آدم بدحساب دو بار میدهد</span> ؛ بدمعاملگی موجب زیان و خسران است .<br /> <span class=\"hlight\">آدم بی اولادپادشاه بی غم است </span> ؛ پرورش و تربیت اولاد سخت دشوار باشد.<br /> <span class=\"hlight\">آدم تا کوچکی نکند بزرگ نشود</span>؛ خضوع مایه ٔ رفعت قدر و بزرگی است .<br /> <span class=\"hlight\">آدم حسابش را پیش خودش میکند</span> ؛ از شرمگنی و حجب دیگران استفاده ٔ سوءنباید کردن .<br /> <span class=\"hlight\">آدم دو بار به این دنیا نمی آید</span> ؛ باید از لذات حیات هرچه بیشتر تمتع برد.<br /> <span class=\"hlight\">آدم دو دفعه نمی میرد</span> ؛ گاه دفاع از حق و حقیقتی رعب و هراس ناسزاوار است .<br /> <span class=\"hlight\">آدم که از زیر بته بیرون نیامده است </span> ؛ همه کس را اقربا و خویشان باشد.<br /> <span class=\"hlight\">آدم لخت کرباس پهنادار خواب بیند</span> ؛ امید و طمعی نابجاست .<br /> <span class=\"hlight\">آدم مال را پیدا میکند، مال آدم را پیدا نمیکند</span> ؛ از صرف مال در جای خویش دریغ و مضایقت سزاوار نیست .<br /> <span class=\"hlight\">آدم نترس سر سلامت بگور نمیبرد</span> ؛ ناپروائی و بی باکی سبب مرگ و هلاکت تواند بود.<br /> <span class=\"hlight\">آدم ندار را سر نمیبرند</span> ؛ المفلس فی امان اﷲ.<br /> <span class=\"hlight\">آدم نفهم هزار من زور دارد</span> ؛ نادان غالباً در آنچه نداند ستیز و لجاج کند.<br /> <span class=\"hlight\">آدم نمیداند بکدام سازَش برقصد</span> ؛ هر ساعت رایی دیگر دارد.<br /> <span class=\"hlight\">آدم یک بار پایش بچاله میرود</span> ؛ از مصائب پند گیرند.<br /> <span class=\"hlight\">آدم یک دفعه میمیرد</span> ؛ ترس و هراس از مرگ سزاوار شجعان نیست .<br /><span class=\"hlight\">همانقدر که آدم بد هست آدم خوب هم هست </span> ؛ همه ٔ مردمان را ذمائم اخلاق نباشد.<br /></font></div>'),
(796, 'آدم آبی', '<span class=\"hlight\">آدم آبی .</span> <font color=\"DarkGreen\"><b>[ دَ م ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) مردم آبی، و آن وجود اساطیری و بی اصل است و دریا را مردمی نیست .<br /></font></div>'),
(797, 'آدمخوار', '<span class=\"hlight\">آدمخوار.</span> <font color=\"DarkGreen\"><b>[ دَ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) در تداول عوام به معنی آدمیخوار.<br /></font></div>'),
(798, 'آدمخواره', '<span class=\"hlight\">آدمخواره .</span> <font color=\"DarkGreen\"><b>[ دَ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب ) مردمخوار.<br /></font></div>'),
(799, 'آدمخور', '<span class=\"hlight\">آدمخور.</span> <font color=\"DarkGreen\"><b>[ دَ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (نف مرکب ) در تداول عوام به معنی آدمیخوار.<br /></font></div>'),
(800, 'آدمخوره', '<span class=\"hlight\">آدمخوره .</span> <font color=\"DarkGreen\"><b>[ دَ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب ) آدمیخوار.<br /></font></div>'),
(801, 'آدمزاده', '<span class=\"hlight\">آدمزاده .</span> <font color=\"DarkGreen\"><b>[ دَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب، اِ مرکب ) آدمیزاد. آدمیزاده . فرزند آدم ابوالبشر. انسان :<br />آخر آدمزاده ای ای ناخلف <br />چند پنداری تو پستی را شرف ؟<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(802, 'آدمستان', '<span class=\"hlight\">آدمستان .</span> <font color=\"DarkGreen\"><b>[ دَ م ِ ]</font></b> (اِ مرکب ) جای آدم <span class=\"hlight\">:</span> <br />خاک از پس مدت فراوان <br />آدم ز تو گشت و آدمستان .<br /><font color=\"Red\">واله هروی .</font><br /></font></div>'),
(803, 'آدمه', '<span class=\"hlight\">آدمه .</span> <font color=\"DarkGreen\"><b>[ دِ م َ ]</font></b> (ع اِ) ج ِادیم . پوستها. <BR><font color=\"Blue\">◄</font> ج ِ اِدام . نانخورشها.<br /></font></div>'),
(804, 'آدمک', '<span class=\"hlight\">آدمک .</span> <font color=\"DarkGreen\"><b>[ دَ م َ ]</font></b> (اِ مصغر) لعبت اطفال که غالباً از چوب سازند. <BR><font color=\"Blue\">◄</font> شکل آدمی که نقش کنند.<br /></font></div>'),
(805, 'آدمی', '<span class=\"hlight\">آدمی .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ع اِ)یک تن از اولاد آدم ابوالبشر. اِنس . اِنسی . انسان . بشر. مردم . مردمی . ناس . اناس . ج، آدمیین <span class=\"hlight\">:</span> <br />شیب تو با فراز و فراز تو با نشیب <br />فرزند آدمی بتو اندر بشیب و تیب .<br /> <font color=\"Red\">رودکی .</font><br />چنین گفت ه̍رون مرا روز مرگ <br />مفرمای هیچ آدمی را مجرگ .<br /> <font color=\"Red\">رودکی یا ابوشکور.</font><br />هر آنکو گذشت از ره مردمی <br />ز دیوان شمر مشمرش زآدمی .<br /> <font color=\"Red\">فردوسی .</font><br />نه در وی آدمی را راه رفتن <br />نه در وی آبها را جوی فرکند.<br /> <font color=\"Red\">عباس (از فرهنگ اسدی، خطی ).</font><br />جهان خوردم و کارها راندم و عاقبت کار آدمی مرگ است . (تاریخ بیهقی ). آدمی را از مرگ چاره نیست .(تاریخ بیهقی ). و این است عاقبت آدمی . (تاریخ بیهقی ). چه از سلطان کریمتر و شرمگین تر آدمی نتواند بود. (تاریخ بیهقی ). آدمی معصوم نتواند بود. (تاریخ بیهقی ). آدمی از چهار چیز ناگزیر بود، اول نانی، دوم خلقانی، سوم ویرانی، چهارم جانانی . (قابوسنامه ).<br />هر آنکس که پیدا شود زآدمی <br />فراوان نماند بروی زمی .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />هرگز من و پدران من بمثل مورچه ای را نیازرده ایم تا بهلاکت آدمی چه رسد. (تاریخ برامکه ).<br />آدمی بعیب خویش نابینا بود. (کیمیای سعادت ). آدمی را <font color=\"DarkGreen\"><b>[ لذات ]</font></b> بیهوده از کار آخرت بازمیدارد. (کلیله و دمنه ). بشناختم که آدمی شریفتر خلائق و عزیزتر موجودات است . (کلیله و دمنه ). و آدمی در کسب آن چون کرم پیله است . (کلیله و دمنه ).<br />زآدمی ابلیس صورت دید و بس <br />غافل از معنی شد آن مردود خس .<br /> <font color=\"Red\">مولوی .</font><br />قیمت هر آدمی باندازه ٔ همت اوست . (تاریخ گزیده ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آدمی از زبان خود ببلاست </span> .<br /> <font color=\"Red\">مکتبی .</font><br />سخن نه بجای خویش گوینده را زیان آرد.<br /> <span class=\"hlight\">آدمی از سنگ سخت تر و از گل نازکتر است </span> ؛ مردم گاه تحمل رنجهای گران کند و گاه از اندک ناملائمی رنجور یا هلاک شود.<br /> <span class=\"hlight\">آدمی از سودا خالی نباشد</span> ؛ هر کسی را هوسی خاص است .<br /> <span class=\"hlight\">آدمی به امید زنده است </span> ؛ امید مایه ٔ تشویق بکار و تحمل مشقات حیات باشد.<br /> <span class=\"hlight\">آدمی بی خرد ستور بود</span> .<br /> <font color=\"Red\">سنائی .</font><br />خرد اصل و مایه ٔ امتیازآدمی از دیگر جانوران است .<br /> <span class=\"hlight\">آدمی جائزالخطاست </span> ؛ همه کس را سهو و خبط وگناه بی اراده تواند بودن .<br /> <span class=\"hlight\">آدمی چون بداشت دست از صیت </span> <br />هرچه خواهی بکن که فاصنع شیت .<br /> <font color=\"Red\">سنائی .</font><br />ای فاصنع ما شئت .<br /> <span class=\"hlight\">آدمیخوارند اغلب مردمان </span> .<br /> <font color=\"Red\">مولوی .</font><br />بعض مردم را صفات سَبُعی است .<br /> <span class=\"hlight\">آدمی در عالم خاکی نمی آید بدست </span> <br />آدمی از نوبباید ساخت وز نو عالمی .<br /> <font color=\"Red\">حافظ.</font><br />این جهان و مردم او نه نیکو باشند.<br /> <span class=\"hlight\">آدمی را آدمیت لازم است </span> <br />چوب صندل بو ندارد هیزم است .<br /> <font color=\"Red\">؟</font><br /> <span class=\"hlight\">مردم را صفات آدمی باید</span> .<br /> <span class=\"hlight\">آدمی را از مرگ چاره نیست </span> . (تاریخ بیهقی )؛ همه کس را مرگ دریابد.<br /> <span class=\"hlight\">آدمی را بتر از علت نادانی نیست </span> .<br /> <font color=\"Red\">سعدی .</font><br /> <span class=\"hlight\">آدمی را به رسن دیو فرا چاه نباید رفت </span> . (مرزبان نامه )؛ از وساوس شیطان حذر باید کردن .<br /> <span class=\"hlight\">آدمی را در این کهن برزخ </span> <br />هم ز مطبخ دری است در دوزخ .<br /> <font color=\"Red\">سنائی .</font><br />پرخواری منشاء مفاسد و مضار باشد.<br /> <span class=\"hlight\">آدمی را عقل باید در بدن </span> <br />ورنه جان در کالبد دارد حمار.<br /> <font color=\"Red\">سعدی .</font><br /> <span class=\"hlight\">آدمی را عقل میباید نه زر</span> . (جامعالتمثیل ).<br /> <span class=\"hlight\">آدمی را کس کجا گوید بپر</span> <br />یا بیا ای کور و در من درنگر؟<br /> <font color=\"Red\">مولوی .</font><br />لایکلف اﷲ نفساً الا وسعها.<br /> <span class=\"hlight\">آدمی را نسبت بهنر باید نه بپدر</span> ؛ از فضل پدر ترا چه حاصل ؟<br /> <span class=\"hlight\">آدمی سربسر همه عیب است </span> <br />پرده ٔ عیبهاش برنائی است .<br /> <font color=\"Red\">مسعودسعد.</font><br /> <span class=\"hlight\">آدمی فربه ز عز است و شرف </span> .<br /> <font color=\"Red\">مولوی .</font><br /> <span class=\"hlight\">آدمی فربه شود از راه گوش </span> .<br /> <font color=\"Red\">مولوی .</font><br />مرد از مسموعات نیک لذت برَد.<br /> <span class=\"hlight\">آدمی گرچه بر زمانه مهست </span> <br />زآدمی خام دیو پخته بِهَست .<br /> <font color=\"Red\">سنائی .</font><br /> <span class=\"hlight\">آدمی مخفی است در زیر زبان </span> .<br /> <font color=\"Red\">مولوی .</font><br />المرء مخبوء تحت لسانه ؛ مردم را بگفتار شناسند.<br /> <span class=\"hlight\">آدمی یک بار پایش بچاله میرود</span> ؛ از تجارب پند و عبرت گیرند.<br /> <span class=\"hlight\">آن به که خود آدمی نزاید</span> .<br /> <font color=\"Red\">مسعودسعد.</font><br /> <span class=\"hlight\">آن دو شاخ گاو اگر خر داشتی </span> <br />یک شکم در آدمی نگذاشتی .<br /> <font color=\"Red\">سعدی .</font><br />خدا خر را شناخت که شاخش نداد.<br /> <span class=\"hlight\">اگر آدمی بچشم است و دهان و گوش و ابرو</span> <br />چه میان نقش دیوار و میان آدمیت ؟<br /><font color=\"Red\">سعدی .</font><br /> <span class=\"hlight\">بشهر خود است آدمی شهریار</span> .<br /> <font color=\"Red\">نظامی .</font><br /> <span class=\"hlight\">به صورت آدمی بودن بی سیرت آدمی بچیزی نیست </span> .<br /> <span class=\"hlight\">به صورت آدمی کرده ست نقاش </span> <br />اگر مردی به معنی آدمی باش .<br /> <font color=\"Red\">پوریای ولی .</font><br /> <span class=\"hlight\">تو کز محنت دیگران بی غمی </span> <br />نشایدکه نامت نهند آدمی .<br /> <font color=\"Red\">سعدی .</font><br /> <span class=\"hlight\">در زمانه ز هرچه جانور است </span> <br />تا نشد پخته آدمی بتر است .<br /> <font color=\"Red\">سنائی .</font><br /> <span class=\"hlight\">ده آدمی بر سفره ای بخورندو دو سگ بر جیفه ای بسر نبرند</span> . (گلستان ).<br /> <span class=\"hlight\">سر نهد از دامن پر آدمی </span> <br />پله چو پر گشت ببوسد زمی .<br /> <font color=\"Red\">امیرخسرو.</font><br /> <span class=\"hlight\">سگ بدان آدمی شرف دارد</span> <br />که دل مردمان بیازارد.<br /> <font color=\"Red\">سعدی .</font><br /><span class=\"hlight\">سگ وفا دارد ندارد آدمی </span> ؛ بعض مردم دوستی قدیم فراموش کنند.<br /></font></div>'),
(806, 'آدمی بدور', '<span class=\"hlight\">آدمی بدور.</span> <font color=\"DarkGreen\"><b>[ دَ ب ِ ]</font></b> (ص مرکب ) مردم گریز. یالقوزک . آنکه معاشرت مردم خوش ندارد.<br /></font></div>'),
(807, 'آدمی سیرت', '<span class=\"hlight\">آدمی سیرت .</span> <font color=\"DarkGreen\"><b>[ دَ رَ ]</font></b> (ص مرکب ) نکورفتار. نیکوخصال .<br /></font></div>'),
(808, 'آدمی سیرتی', '<span class=\"hlight\">آدمی سیرتی .</span> <font color=\"DarkGreen\"><b>[ دَ رَ ]</font></b> (حامص مرکب ) چگونگی و صفت آدمی سیرت <span class=\"hlight\">:</span> <br />نخست آدمی سیرتی پیشه کن <br />پس آنگه ملک خویی اندیشه کن .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(809, 'آدمی شناس', '<span class=\"hlight\">آدمی شناس .</span> <font color=\"DarkGreen\"><b>[ دَ ش ِ ]</font></b> (نف مرکب ) رجوع به آدم شناس شود.<br /></font></div>'),
(810, 'آدمی و پری', '<span class=\"hlight\">آدمی و پری .</span> <font color=\"DarkGreen\"><b>[ دَ ی ُ پ َ ]</font></b> (ترکیب عطفی، اِ مرکب ) ثقلان . ثقلین . جن و انس <span class=\"hlight\">:</span> <br />طفیل هستی عشقند آدمی و پری <br />ارادتی بنما تا سعادتی ببری .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(811, 'آدمی وار', '<span class=\"hlight\">آدمی وار.</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ص مرکب ) باادب .<br /></font></div>'),
(812, 'آدمی کش', '<span class=\"hlight\">آدمی کش .</span> <font color=\"DarkGreen\"><b>[ دَ ک ُ ]</font></b> (نف مرکب ) قاتل <span class=\"hlight\">:</span> <br />میباش طبیب عیسوی هش <br />اما نه طبیب آدمی کش .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(813, 'آدمی گری', '<span class=\"hlight\">آدمی گری .</span> <font color=\"DarkGreen\"><b>[ دَ گ َ ]</font></b> (حامص مرکب ) بشریت <span class=\"hlight\">:</span> اما گاه گاه در درون استاد امام از راه آدمی گری اندک داوری می بود. (اسرارالتوحید). چون چشم من بر وی افتاد از آدمیگری هیچ چیز با من نماند. روحی و آسایشی از وی بمن رسید چنانکه بیخود گشتم . (اسرارالتوحید).<br /></font></div>'),
(814, 'آدمیان', '<span class=\"hlight\">آدمیان .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ) ج ِ آدمی <span class=\"hlight\">:</span> <br />یک بار طبع آدمیان گیر و مردمان <br />گرْت آدم است بابک و فرزند آدمی .<br /> <font color=\"Red\">اسدی .</font><br />آدمیان را سخنی بس بود<br />گاو بود کش خله در پس بود.<br /><font color=\"Red\">امیرخسرو.</font><br /></font></div>'),
(815, 'آدمیت', '<span class=\"hlight\">آدمیت .</span> <font color=\"DarkGreen\"><b>[ دَ می ی َ ]</font></b> (ع مص جعلی، اِمص ) انسانیت . مردمی . بشریت . آزرم <span class=\"hlight\">:</span> برنجید و گفت این طایفه ٔ خرقه پوشان امثال حیوانند، اهلیت و آدمیت ندارند. (گلستان سعدی ).<br />بحقیقت آدمی باش و گرنه مرغ دانی <br />که همین سخن بگوید بزبان آدمیت .<br /> <font color=\"Red\">سعدی .</font><br />طیران مرغ دیدی تو ز پای بند شهوت <br />بدر آی تا ببینی طیران آدمیت .<br /> <font color=\"Red\">سعدی .</font><br />گفتم این شرط آدمیت نیست <br />مرغ تسبیح خوان و من خاموش .<br /><font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">آدمی را آدمیت لازم است </span> ؛ مردم را صفات مردمی باید.<br /></font></div>'),
(816, 'آدمیخوار', '<span class=\"hlight\">آدمیخوار.</span> <font color=\"DarkGreen\"><b>[ دَ خوا<span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) مردم خوار. آدمیخواره <span class=\"hlight\">:</span> <br />آدمیخوارند اغلب مردمان .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(817, 'آدمیخواره', '<span class=\"hlight\">آدمیخواره .</span> <font color=\"DarkGreen\"><b>[ دَ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب ) آدمیخوار.<br /></font></div>'),
(818, 'آدمیرال', '<span class=\"hlight\">آدمیرال .</span> (انگلیسی، اِ) در انگلیسی بمعنی امیرالبحر است . این کلمه ازامیر یا امیرالبحر عربی گرفته شده و مرادف آن در زبان فرانسه آمیرال باشد.<br /></font></div>'),
(819, 'آدمیزاد', '<span class=\"hlight\">آدمیزاد.</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ص مرکب، اِ مرکب ) زاده ٔ آدم . انسان . مردم . بشر: یکی را شنیدم از پیران که مریدی را همی گفت ای پسر چندان که تعلق خاطر آدمیزاد بروزی است اگر... (گلستان ).<br />که هامون و دریا و کوه و فلک <br />پری وآدمیزاد و دیو و ملک <br />همه هرچه هستند از آن کمترند<br />که با هستیش نام هستی برند.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آدمیزاد اگر بی ادب است آدم نیست </span> .<br /> <span class=\"hlight\">آدمیزاد تخم مرگ است </span> ؛هیچ آدمی را از مرگ گزیری نباشد.<br /><span class=\"hlight\">آدمیزاد شیر خام خورده است </span> ؛ هر خطائی از انسان سر تواند زدن .<br /> <span class=\"hlight\">از سستی آدمیزاد گرگ آدمیخوار پیدا شود</span> ؛ اگر قبول ظلم نکنند ظلم از میان برخیزد.<br />(که ) باشد دزد طبع آدمیزاد؛ آدمی بمعاشرت بدان بدی آموزد.<br /></font></div>'),
(820, 'آدمیزاده', '<span class=\"hlight\">آدمیزاده .</span> <font color=\"DarkGreen\"><b>[ دَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب، اِ مرکب ) آدمیزاد <span class=\"hlight\">:</span> <br />گر سفله بمال و جاه از آزاده به است <br />سگ نیز بصید از آدمیزاده به است .<br /> <font color=\"Red\">سعدی .</font><br />نه هر آدمیزاده از دد به است <br />که دد زآدمیزاده ٔ بد به است .<br /> <font color=\"Red\">سعدی .</font><br />اگر مار زاید زن باردار<br />به از آدمیزاده ٔ دیوسار.<br /> <font color=\"Red\">سعدی .</font><br />ببخش ای پسر کآدمیزاده صید<br />باحسان توان کرد و وحشی بقید.<br /> <font color=\"Red\">سعدی .</font><br />آدمیزاده طرفه معجونی است <br />کز فرشته سرشته وز حیوان .<br /><font color=\"Red\">؟</font><br /></font></div>'),
(821, 'آدمیین', '<span class=\"hlight\">آدمیین .</span> <font color=\"DarkGreen\"><b>[ دَ می یی ]</font></b> (ع اِ) ج ِ آدمی .<br /></font></div>'),
(822, 'آده', '<span class=\"hlight\">آده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ)چوب بلند افقی که دو سر آن بر دو چوب افراشته و عمودی استوار کنند تا کبوتران و دیگر پرندگان بر آن نشینند. و آن را اَده بفتح همزه نیز گویند <span class=\"hlight\">:</span> <br />فلک چو برج کبوتر کبوتران چو نجوم <br />میان برج خط استواست چون آده .<br /> <font color=\"Red\">سنجری .</font><br />در صورتی که در بیت تصحیف و تحریفی نباشد چنان می نماید که آده چوبی است از یک سو بیک سوی دیگر برج کبوتر یا کبوترخان کشیده .<br /></font></div>'),
(823, 'آدوآ', '<span class=\"hlight\">آدوآ.</span> (اِخ ) پایتخت تیگره در حبشه دارای پنج هزار سکنه، و شکست سپاه ایتالیا از مردم حبشه در <span class=\"hlight\" dir=\"rtl\">١٣١٣</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٨٩٦</span> م . در این شهر بود.<br /></font></div>'),
(824, 'آدک', '<span class=\"hlight\">آدک .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ) آداک .<br /></font></div>'),
(825, 'آدی', '<span class=\"hlight\">آدی .</span> <font color=\"DarkGreen\"><b>[ دا ]</font></b> (ع ن تف ) امانت گذارنده تر. راست معامله تر.<br /></font></div>'),
(826, 'آدیابن', '<span class=\"hlight\">آدیابن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ناحیه ای از آشور قدیم که ایرانیان آن را مسخر کردند و در زمان رومیان مملکتی مستقل شد، طراژان آن را گرفت . و اشکانیان آن را از رومیان بازستدند و در زمان ساسانیان جزء مملکت ایران بود.<br /></font></div>'),
(827, 'آدیس آبابا', '<span class=\"hlight\">آدیس آبابا.</span> (اِخ ) پایتخت مملکت حبشه دارای <span class=\"hlight\" dir=\"rtl\">٥٠٠٠٠</span> تن سکنه .<br /></font></div>'),
(828, 'آدیش', '<span class=\"hlight\">آدیش .</span> (اِ) آتش . نار <span class=\"hlight\">:</span> <br />گر کند چوب آستان تو حکم <br />شحنه ٔ چوبها شود آدیش .<br /><font color=\"Red\">انوری .</font><br /></font></div>'),
(829, 'آدیمامان', '<span class=\"hlight\">آدیمامان .</span> (اِخ ) نام محلی کنار راه خوی و ماکو میان خوی و عسکرآباد، در <span class=\"hlight\" dir=\"rtl\">٤٠٠٠</span> گزی خوی .<br /></font></div>'),
(830, 'آدین', '<span class=\"hlight\">آدین .</span> (اِ) خوازه و آرایش ها که بنوروز یا گاه ورود پادشاهان و جشنهای بزرگ در کویها و برزنها و راهها کنند. آذین .<br /></font></div>'),
(831, 'آدینده', '<span class=\"hlight\">آدینده .</span> <font color=\"DarkGreen\"><b>[ ی َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ) قوس قزح <span class=\"hlight\">:</span> <br />عَلَم ابر و تندر بود کوس او<br />کمان آدینده شود ژاله تیر.<br /> <font color=\"Red\">رودکی .</font><br />و آن راکمان گردون، کمان بهن، کمان رستم، کمان شیطان، آفنداک، شدکیس، سرویسه، تیراژه، صدکیس، آزفنداک، ایرسا، طوق بهار، افنداک و درونه نیز خوانند و عامه آن را قالیچه ٔ فاطمه گویند.<br /></font></div>'),
(832, 'آدینه', '<span class=\"hlight\">آدینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) نام روزی از هفته میان پنجشنبه و شنبه، و آن در پیش مسلمانان چون شنبه نزد یهود و یکشنبه نزد نصاری عید و روز آخر هفته باشد. جمعه . جامع. یوم الازهر <span class=\"hlight\">:</span> <br />تا چو آدینه بسر برده شد آید شنبه <br />تا چوماه رمضان بگذرد آید شوال ...<br /> <font color=\"Red\">فرخی .</font><br />چندین محتشم بخدمت آمده اند و سوار ایستاده اند که روز آدینه است . (تاریخ بیهقی ).<br />من سوی تو شنبه و تو نزد من <br />چون سوی کودک شب آدینه ای .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> عامه آدینه را مانند جمعه علم و اسم کنند مردان را <span class=\"hlight\">:</span> <br />جمعه با زوجه ٔ خود گفت شبی <br />که مرا با تو ز آدینه شکی است <br />زن بدو گفت دوبینی بگذار<br />پیش من جمعه و آدینه یکی است .<br /> <font color=\"Red\">شهاب ترشیزی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل شب آدینه ٔ اطفال </span> ؛ روزی یا ساعتی خوش و فرخنده و خرّم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مسجد آدینه </span> ؛ مسجد جمعه . جامع <span class=\"hlight\">:</span> <br />تا نشنوی ز مسجد آدینه بانگ صبح <br />یا از در سرای اتابک غریو کوس <br />لب از لب چو چشم خروس ابلهی بود<br />برداشتن بگفته ٔ بیهوده ٔ خروس .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آدینه اش را گم کرده است </span> ؛ معتادی را فراموش کردن میخواهد.<br /> <span class=\"hlight\">احمدک استا نرفت روزی که رفت آدینه بود</span> ؛ کاهلی کار کرد نه بوقت خویش .<br /> <span class=\"hlight\">چه جمعه و چه آدینه </span> .<br /><span class=\"hlight\">در پیش خرد شنبه و آدینه یکی است </span> .<br /></font></div>'),
(833, 'آدینه بازار', '<span class=\"hlight\">آدینه بازار.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) نام رودی در سرحد ایران و روس در سه فرسنگی بالهارود، و این رود بساری قمیش پیوندد.<br /></font></div>'),
(834, 'آدینه وند', '<span class=\"hlight\">آدینه وند.</span> <font color=\"DarkGreen\"><b>[ ن َوَ ]</font></b> (اِخ ) (ایل ...) رجوع به طرهان (ایل ...) شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(835, 'آذار', '<span class=\"hlight\">آذار.</span> (اِ) ماه اول بهار سریانی . (السامی فی الاسامی ). ماه هفتم از سالهای سریانی است میان شباط و نیسان که ابتدای سال از ایلول ماه اول خزان باشد. نام ماه اول بهار است از سال رومیان و بودن آفتاب در برج حوت . (برهان قاطع) <span class=\"hlight\">:</span> <br />ابر آذاری برآمد باد نوروزی وزید<br />وجه ِ می میخواهم و مطرب که میگوید رسید.<br /> <font color=\"Red\">حافظ.</font><br />ماه ششم از ماههای رومیه . (قاموس فیروزآبادی ). مدت ماندن آفتاب در برج حوت که به هندش چیت نامند و آن ماه اول از ربیع است . (مؤیدالفضلاء). آذر و آذار، ماه سوم از سالهای مسیحی . (اقرب الموارد). و آن را اَذار بفتح همزه هم گفته اند <span class=\"hlight\">:</span> <br />آن پرّ نگارینْش بدو بازنبندند<br />تا آذرمه بگذرد وآید آذار.<br /> <font color=\"Red\">منوچهری .</font><br />منم آذار وتو نوروز خرم <br />هرآیینه بود این هر دو با هم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />آنی که پدید آمد در باغ شریعت <br />از عدل تو آذار و ز احسان تو نیسان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای دَرْت ز بی برگان چون شاخ در آذر<br />وی دِلْت ز بخشیدن چون باغ در آذار.<br /> <font color=\"Red\">سنائی .</font><br />این هنوز اول آذار جهان افروز است <br />باش تا خیمه زند دولت نیسان و ایار.<br /> <font color=\"Red\">سعدی .</font><br />آذار ببرد آب رخ آذر و کانون <br />وز دردسر هر دو امان داد جهان را.<br /><font color=\"Red\">سلمان ساوجی .</font><br /></font></div>'),
(836, 'آذارافیون', '<span class=\"hlight\">آذارافیون .</span><font color=\"DarkGreen\"><b>[ اَف ْ ]</font></b> (اِ) اَذاراَفْیون . نوعی از زبدالبحر است که آن را کف دریا گویند. (برهان ). و آن استخوان نوعی از نواعم است که در یونانی سِپیا گویند و در فرانسه آن را سِش و بیسکویت دو مِر خوانند، و این حیوان در دریا پیرامون خویش ماده ٔ سیاهی افشاند دفاع خویش را و در چین از این سیاهی آنگاه که منجمد شود نقس و دوده ٔ مرکب کنند و این همان مرکب معروف بچینی است .<br /></font></div>'),
(837, 'آذارطوس', '<span class=\"hlight\">آذارطوس .</span> (اِخ ) رجوع به آذرطوس شود.<br /></font></div>'),
(838, 'آذاریقون', '<span class=\"hlight\">آذاریقون .</span> (اِ) مصحف آذارافیون .<br /></font></div>'),
(839, 'آذان', '<span class=\"hlight\">آذان .</span> (ع اِ) ج ِ اُذُن .<br /></font></div>'),
(840, 'آذان الارنب', '<span class=\"hlight\">آذان الارنب .</span> <font color=\"DarkGreen\"><b>[ نُل ْ اَ ن َ ]</font></b> (ع اِ مرکب ) اُذُن الارنب . گیاهی است برگش شبیه و پهن تر از برگ بارتنگ و آن نوعی از بارتنگ یعنی لسان الحمل است و آن را آذان الشّاة و آذان الغزال نیز گویند و بلغت بربری لصیقی خوانند، و بعضی گویند آذان الارنب خرگوشک فارسی است . و نیز گفته اند گیاهی است که اسبغول یعنی اسفرزه تخم آن است .<br /></font></div>'),
(841, 'آذان الثور', '<span class=\"hlight\">آذان الثور.</span> <font color=\"DarkGreen\"><b>[ نُث ْ ث َ ]</font></b> (ع اِ مرکب ) گیاهی است که آن را لسان الثور نیز گویند و فارسی آن گاوزبان است .<br /></font></div>'),
(842, 'آذان الجدی', '<span class=\"hlight\">آذان الجدی .</span> <font color=\"DarkGreen\"><b>[ نُل ْ ج َدْی ْ ]</font></b> (ع اِ مرکب ) لسان الحمل . (قاموس ). بارتنگ . بارهنگ . و بعضی لسان الحمل را جنسی شمرده اند که آذان الجدی نوع بزرگتر آن و آذان الارنب نوع کوچک آن است، و صاحب تحفه گوید نوع بزرگ لسان الحمل است .<br /></font></div>'),
(843, 'آذان الدب', '<span class=\"hlight\">آذان الدب .</span> <font color=\"DarkGreen\"><b>[ نُدْ دُب ب ]</font></b> (ع اِ مرکب ) اُذُن الدب . گیاهی است که عرب آن را بوصیر خواند. (قاموس ). و بیونانی آن راقُلومُس گویند و بعضی فارسی آن را خرگوش گفته اند.<br /></font></div>'),
(844, 'آذان العبد', '<span class=\"hlight\">آذان العبد.</span> <font color=\"DarkGreen\"><b>[ نُل ْ ع َ ]</font></b> (ع اِ مرکب ) آن را آذان العنز نیز گویند و نام دیگر آن مِزمارالرّاعی است . (قاموس ). و گفته اند که آن نوعی از عصاالرّاعی باشد.<br /></font></div>'),
(845, 'آذان العنز', '<span class=\"hlight\">آذان العنز.</span> <font color=\"DarkGreen\"><b>[ نُل ْ ع َ ]</font></b> (ع اِ مرکب ) آذان العبد.<br /></font></div>'),
(846, 'آذان الغزال', '<span class=\"hlight\">آذان الغزال .</span> <font color=\"DarkGreen\"><b>[ نُل ْ غ َ ]</font></b> (ع اِ مرکب ) آذان الارنب . و صاحب تحفه گوید لصیقی است .<br /></font></div>'),
(847, 'آذان الفار', '<span class=\"hlight\">آذان الفار.</span> <font color=\"DarkGreen\"><b>[ نُل ْ ]</font></b> (ع اِ مرکب ) گیاهی است برّی و بستانی . بستانی آن در کنار آبها و بیشه ها وسایه ها روید، برگش مایل بتدویر و شبیه بگوش موش و گیاهش بی ساق و بی گل و بر روی زمین پهن شود و شاخه های آن سه پهلوست و چون مالند بوی خیار از وی آید. و برّی آن سه قسم است، قسمی را شاخه های بسیار باریک که از یک اصل روید و شاخه های اسفل سرخ و مجوّف است و برگها باریکتر و درازتر از نوع بستانی و مایل بسیاهی، و وسط و پشت برگها محدب و اطراف برگها تند و زوج بر شاخه ها رسته و هر ساقی مشتمل بر شاخه های ریزه و گلش لاجوردی و بعضی را گلش زرد و بیخش بقدر انگشتی و پرشعبه وفرق میان این قسم و اسقولوفندریون آن است که این رابرگ نرم و دراز و ریزه و اسقولوفندریون بخلاف اوست . و قسم دیگر را منابت رهگزارها است و شاخه های او بر روی زمین پهن شود و برگش مایل بتدویر و بی گل و بسیار شبیه بنوع بستانی از آن ریزه تر و باحرافت است و گویند بی گل نیست ولکن از غایت ریزگی و چسبیدن او بشاخه هاچندان مرئی نمی شود و قسم سوم را برگ مایل بتدویر و خارناک و مزغب و شاخش شیردار و مفروش بر روی زمین . وابن تلمیذ در مغنی میفرماید که اقسام آذان الفار غیرمرزنجوش است و همچنین از سایر کتب نیز این معنی ظاهر می شود چه مرزنجوش متصف بصفات دیگر و ازجمله ٔ ریاحین است و با عطریت و برگش شبیه بگوش موش و مایل بتدویر نیست و گل او سفید مایل بسرخی است و تخمش شبیه بتخم ریحان و شفاف میباشد و تشویش قول صاحب اختیارات نهایت ظهور دارد. (تحفه ). <br /></font></div>'),
(848, 'آذان الفیل', '<span class=\"hlight\">آذان الفیل .</span><font color=\"DarkGreen\"><b>[ نُل ْ ]</font></b> (ع اِ مرکب ) پیل گوش . فیل گوش . پیلغوش . فیلجوش . خبزالقرود. رجل العجل . آرن . (تحفه ). <BR><font color=\"Blue\">◄</font> آرن بزرگ . لوف الکبیر. شجرةالتّنین . دراقینون . <BR><font color=\"Blue\">◄</font> آرن جعده . لوف الجعده . <BR><font color=\"Blue\">◄</font> آرن قلقاس . قلقاس . (قاموس ). <BR><font color=\"Blue\">◄</font> آرن حیه . لوف الحیة. لوف مستطیل . لوف الارقط.<br /></font></div>'),
(849, 'آذان القاضی', '<span class=\"hlight\">آذان القاضی .</span> <font color=\"DarkGreen\"><b>[ نُل ْ ]</font></b> (ع اِ مرکب ) اُذُن القاضی . سرةالارض . آذان القسیس . در الجزایر بدان اذن الشیخ گویند. و لاتینی آن قوطولیدون است، بگفته ٔ بعضی نوعی از حی العالم است .<br /></font></div>'),
(850, 'آذان القسیس', '<span class=\"hlight\">آذان القسیس .</span> <font color=\"DarkGreen\"><b>[ نُل ْ ق ِس ْ سی ]</font></b> (ع اِ مرکب ) اُذُن القسیس .آذان القاضی . و صاحب تحفه گوید نوعی از ابرون است .<br /></font></div>'),
(851, 'آذر', '<span class=\"hlight\">آذر.</span> <font color=\"DarkGreen\"><b>[ ذَ]</font></b> (اِ) (از زندی آتارس ) آتش . آدر. نار <span class=\"hlight\">:</span> <br />برافروز آذری اکنون که تیغش بگذرد از بون <br />فروغش از بر گردون کند اجرام را اخگر.<br /> <font color=\"Red\">دقیقی .</font><br />همانا که برزوی را مادری <br />که روز و شب از درد بر آذری .<br /> <font color=\"Red\">فردوسی .</font><br />بدانست کآن زن ورا مادر است <br />ز درد دلش جانْش پرآذر است .<br /> <font color=\"Red\">فردوسی .</font><br />پرستش کنان پیش آذر شدند<br />همه موبدان دست برسر شدند.<br /> <font color=\"Red\">فردوسی .</font><br />دویست بود کم از پنج عمر ابراهیم <br />بشد برو گل و ریحان بسوختن آذر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />مدان مر خصم را خرد ای برادر<br />که سوزد عالمی یک ذره آذر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای بسا رزما که از هر سو سپاه <br />زآب خنجر شعله ٔ آذر کشید.<br /> <font color=\"Red\">مسعودسعد.</font><br />آذر بزبان پهلوی آتش بود. (نوروزنامه ).<br />ساغرش پر باده ٔ رنگین چنان آید بچشم <br />کز میان آب روشن برفروزی آذری .<br /> <font color=\"Red\">انوری .</font><br />دیدم از سوی چپ او آذری <br />سوی دست راست حوض کوثری .<br /> <font color=\"Red\">مولوی .</font><br />بوقت قهر در میدان ز آب آذر برانگیزی <br />بگاه لطف در کانون آذر گل برویانی .<br /> <font color=\"Red\">سلمان ساوجی .</font><br /> <BR><font color=\"Blue\">◄</font> آتشکده . بیت النار. بیت النیران . آتشگاه <span class=\"hlight\">:</span> <br />پس آزاده گشتاسب برشد بگاه <br />فرستاد هر سو بکشور سپاه <br />پراکند گرد جهان مؤبدان <br />نهاد از بر آذران گنبدان .<br /> <font color=\"Red\">دقیقی .</font><br />و در آذرمهر و آذرنوش و آذر بهرام و آذر برزین و آذر زردهشت و امثال آن مراد آتشکده های منسوب به این نامها است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">هفت آذر</span> . رجوع به آتشکده شود.<br /> <BR><font color=\"Blue\">◄</font> دوزخ . جهنم <span class=\"hlight\">:</span> <br />وگر این یکی را فریبند آن دو<br />خداوند آن خانه ماند در آذر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />بر من سفر از حضر به است ارچند<br />این شد چو نعیم و آن چو آذر شد.<br /> <font color=\"Red\">علی شطرنجی .</font><br /> <BR><font color=\"Blue\">◄</font> نام ماه نهم از سال شمسی ایرانیان مطابق قوس <span class=\"hlight\">:</span> <br />ای ماه رسید ماه آذر<br />برخیز و بده می چو آذر.<br /> <font color=\"Red\">مسعودسعد.</font><br />گر نیست آب نقش پذیرنده پس چرا<br />هر بامداد نقش کند باد آذرش ؟<br /> <font color=\"Red\">مختاری غزنوی .</font><br />همیشه تا بود دی پیش امروز<br />همیشه تا بود دی پیش آذر.<br /> <font color=\"Red\">خاقانی .</font><br />اگر نی کلک او شد ناف آهو<br />و گر نی طبع او شد ابر آذر<br />چرا بارد به نطق این درّ دریا<br />چرا بیزد بنوک او مشک اذفر؟<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> نام روز نهم از ماههای پارسی که در ماه آذر برای توافق نام ماه و روز ایرانیان قدیم جشن گرفتندی و آن را آذرگان نامیدندی و آن را آذرروز نیز گویند <span class=\"hlight\">:</span> آمدن یاقوتی بار دیگر روز آذرسال بر چهارصدوبیست وچهار از یزدجرد. (تاریخ سیستان ).<br />ای خردمند سرو تابان ماه <br />روز آذر می چو آذر خواه .<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> ماه آذار سریانی که آن را رومی نیز گویند <span class=\"hlight\">:</span> <br />برخشش بکردار تابان درخشی <br />که پیچان پدید آید از ابر آذر.<br /> <font color=\"Red\">؟ (از فرهنگ اسدی، خطی ).</font><br />ز تو باغ گردد کشفته به آذر<br />ز تو راغ گردد شکفته بنیسان .<br /> <font color=\"Red\">عبدالواسع جبلی .</font><br />آذار ببرد آب رخ آذر و کانون <br />وز درد سر هر دوامان داد جهان را.<br /> <font color=\"Red\">سلمان ساوجی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِخ ) نام فرشته ٔ موکل آفتاب و امور آذرماه و آذرروز. <BR><font color=\"Blue\">◄</font> مخفف آذرآبادگان . آذربایجان <span class=\"hlight\">:</span> <br />وز آنجایگه لشکر اندرکشید<br />سوی آذرآبادگان برکشید<br />چو بهرام رخ سوی آذر نهاد<br />فرستاده آمد ز قیصر چو باد.<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> در بعض فرهنگها، نامی از نامهای خدای تعالی و صاعقه و برق .<br /></font></div>'),
(852, 'آذر برزین', '<span class=\"hlight\">آذر برزین .</span> <font color=\"DarkGreen\"><b>[ ذَ رِ ب َ ]</font></b> (اِخ ) نام آتشکده ٔ ششم است از هفت آتشکده ٔ ایرانیان و آن را یکی از خلفای زردشت ساخته است و گویند روزی کیخسرو سوار بود ناگاه آواز رعدی برخاست چنان بهیبت که کیخسرو خود را از اسب درانداخت و آن آتش بر زین اسب فرودآمد و زین افروخته شد، دیگر نگذاشتند آن آتش فرونشیند و هم بدانجا برای آن آتش آتشکده ای ساخته و آذر برزین نام نهادند.(از برهان ) <span class=\"hlight\">:</span> <br />بزرگان از آن کار غمگین شدند<br />بر آذرپاک برزین شدند.<br /> <font color=\"Red\">فردوسی .</font><br />سزاوار این جستن کین منم <br />برزم آذر تیز برزین منم .<br /> <font color=\"Red\">فردوسی .</font><br />یکی آذری ساخت برزین بنام <br />که با فرهی بود و با رای و کام .<br /> <font color=\"Red\">فردوسی .</font><br />در دل و در دیده ٔ من سال و ماه <br />آذر برزین بُوَد و رود گنگ .<br /> <font color=\"Red\">مسعودسعد.</font><br />موبد آذرپرستان را دل من قبله شد<br />زآنکه عشقش بر دل من آذر برزین نهاد.<br /> <font color=\"Red\">معزی .</font><br />ای نمودار رحمت و سخطت <br />آب حیوان و آذر برزین .<br /> <font color=\"Red\">انوری .</font><br />ستمکارا بیا سوز دل ما<br />ببین گر آذر برزین ندیدی .<br /> <font color=\"Red\">شرف شفروه .</font><br />و از قطعه ٔ ذیل فردوسی چنین برمی آید که آذر برزین همان بهار یا نوبهار بلخ باشد:<br />یکی شارسانی برآورد شاه <br />پر از برزن و کوی و بازارگاه ...<br />یکی آذری ساخت برزین بنام <br />که بد بابزرگی و با فر و کام .<br /> <font color=\"Red\">فردوسی .</font><br />و صاحب فرهنگ زبان گویا گفته است که جای آن بروستای نشابور بوده . آنچه تا بحال نوشته شد مطابق فرهنگهای پارسی است لیکن آذر برزین یا آذر برزین مهر یکی از سه آتش مقدس است در نزد ایرانیان قدیم که حافظ جهانند. و دیگر آتشها از این سه زاید و آن دوی دیگر آذرفرنبغ و آذرگشنسب است . <BR><font color=\"Blue\">◄</font> نام پهلوانی .<br /></font></div>'),
(853, 'آذر بهرام', '<span class=\"hlight\">آذر بهرام .</span> <font color=\"DarkGreen\"><b>[ ذَ رِ ب َ ]</font></b> (اِخ ) نام آتشکده ٔ سوم از هفت آتشکده ٔ بزرگ پارسیان . <BR><font color=\"Blue\">◄</font> نام بنائی قدیم در همدان که اکنون ویران است .<br /></font></div>'),
(854, 'آذر بیگدلی', '<span class=\"hlight\">آذر بیگدلی .</span> <font color=\"DarkGreen\"><b>[ ذَ رِ ب َ دِ ]</font></b> (اِخ ) حاج لطفعلی بیگ شاملو (<span class=\"hlight\" dir=\"rtl\">١١٣٤</span> - <span class=\"hlight\" dir=\"rtl\">١١٩٥</span> هَ . ق .)، برادرزاده ٔ ولی محمدخان، متخلص بمسرور مستوفی و نویسنده ٔ عادلشاه افشار، معاصر زندیه بوده و به نام کریمخان وکیل تذکره ای موسوم به آتشکده نوشته ویوسف و زلیخائی نیز بنظم آورده و صاحب دیوان است .<br /></font></div>'),
(855, 'آذر خراد', '<span class=\"hlight\">آذر خراد.</span> <font color=\"DarkGreen\"><b>[ ذَ رِ خ َرْرا ]</font></b> (اِخ ) در چند موضع از فردوسی به نام این آذر برمیخوریم لیکن در فرهنگها ضبط نشده است <span class=\"hlight\">:</span> <br />چنان دید در خواب کآتش پرست <br />سه آتش فروزان ببردی بدست <br />چو آذرگشسب و چو خراد و مهر<br />فروزان چو بهرام و ناهید چهر.<br /> <font color=\"Red\">فردوسی .</font><br />دل شاه از اندیشه آزاد گشت <br />سوی آذر رام و خراد گشت .<br /> <font color=\"Red\">فردوسی .</font><br />تنها صاحب برهان در ردیف خاء خرّادمهرضبط کرده و آن را یک کلمه ٔ مرکب دانسته و گفته است که نام آتشکده ای در زمان بابک بوده است ولی از شعر فردوسی «چو آذرگشسب و چو خرّاد و مهر» روشن است که خرّاد نام آتشی و مهر نام آتشی دیگر است و شاید دو کلمه ٔ آذر خراد و آذر خرداد یکی تصحیف دیگری است . و رجوع به آذر خرداد شود.<br /></font></div>'),
(856, 'آذر خرداد', '<span class=\"hlight\">آذر خرداد.</span> <font color=\"DarkGreen\"><b>[ ذَ رِ خ ُ ]</font></b> (اِخ ) نام آتشکده ٔ شیراز است و بعضی آن را آتشکده ٔ پنجم از هفت آتشکده ٔ بزرگ دانسته اند. و نام مَلَکی است که باعتقاد فارسیان به محافظت این آتشکده مأمور است . (برهان قاطع). رجوع به آذر خرّاد شود <span class=\"hlight\">:</span> <br />پدر و مادر سخاوت و جود<br />هر دو خوانند شاه را داماد<br />پیش دو دست او سجود کنند<br />چون مغان پیش آذر خرداد.<br /> <font color=\"Red\">رودکی .</font><br />با رحمت تو دود سقر مروحه ٔ نور<br />با هیبت تو نکهت صبح آذر خرداد.<br /> <font color=\"Red\">شرف شفروه .</font><br /> <BR><font color=\"Blue\">◄</font> نام یکی از موبدان و دانشمندان که بانی آتشکده ٔ آذر خرداد است . (از برهان ) <span class=\"hlight\">:</span> <br />همه بیابان زآن روشنایی آگه شد<br />چو جان آذر خرداد از آذر خرداد.<br /> <font color=\"Red\">فرخی .</font><br />و این آتشکده را آذرخرین نیز نامند. (از برهان ).<br /></font></div>'),
(857, 'آذر خورداد', '<span class=\"hlight\">آذر خورداد.</span> <font color=\"DarkGreen\"><b>[ ذَ رِ خُرْ ]</font></b> (اِخ ) رجوع به آذر خرداد شود.<br /></font></div>'),
(858, 'آذر رام', '<span class=\"hlight\">آذر رام .</span> <font color=\"DarkGreen\"><b>[ ذَ رِ ]</font></b> (اِخ ) در بیت ذیل اگر تصحیفی راه نیافته باشد ظاهراً نام آتشکده ای بوده است <span class=\"hlight\">:</span> <br />دل شاه از اندیشه آزاد گشت <br />سوی آذر رام و خرّاد گشت .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(859, 'آذر زردشت', '<span class=\"hlight\">آذر زردشت .</span> <font color=\"DarkGreen\"><b>[ ذَ رِ زَ دُ ]</font></b> (اِخ ) آذَرِ زَرْدهُشْت . نام آتشکده ٔ هفتم از هفت آتشکده ٔ بزرگ پارسیان <span class=\"hlight\">:</span> <br />پرستنده ٔ آذر زردهشت <br />همی رفت با باژ و بَرْسَم بمشت <br />چو از دور جای پرستش بدید<br />شد از آب دیده رخش ناپدید.<br /> <font color=\"Red\">فردوسی .</font><br />ببلخ آمد و آذر زردهشت <br />بطوفان شمشیر چون آب کشت <br />بهار دل افروزدر بلخ بود<br />کزو تازه گل را دهن تلخ بود<br />زده موبدش نعل زرین بر اسب <br />شده نام آن خانه آذرگشسب .<br /> <font color=\"Red\">نظامی .</font><br />اگر بجنبه ٔ تاریخی اسکندرنامه ٔ نظامی اطمینان توان کرد از ابیات فوق برمی آید که آذر زردهشت در بلخ بوده و نام دیگر آن نیز آذرگشسب است . رجوع به آذرگشسب شود.<br /></font></div>'),
(860, 'آذرآباد', '<span class=\"hlight\">آذرآباد.</span><font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نام آتشکده ای در تبریز. (فرهنگ جهانگیری ). <BR><font color=\"Blue\">◄</font> آذربایجان . <BR><font color=\"Blue\">◄</font> تبریز.<br /></font></div>'),
(861, 'آذرآبادگان', '<span class=\"hlight\">آذرآبادگان .</span> <font color=\"DarkGreen\"><b>[ ذَ دَ ]</font></b> (اِخ ) آذربایجان <span class=\"hlight\">:</span> <br />بیک ماه در آذرآبادگان <br />ببودندشاهان و آزادگان .<br /> <font color=\"Red\">فردوسی .</font><br />وز آنجایگه لشکر اندرکشید<br />سوی آذرآبادگان برکشید.<br /> <font color=\"Red\">فردوسی .</font><br />سیُم بهره بود آذرآبادگان <br />که بخشش نهادند آزادگان .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد سوی آذرآبادگان <br />خود و نامداران و آزادگان .<br /> <font color=\"Red\">فردوسی .</font><br />نداد آن سر پربها رایگان <br />همی تاخت تا آذرآبادگان .<br /> <font color=\"Red\">فردوسی .</font><br />از آنجا بتدبیر آزادگان <br />بیامد سوی آذرآبادگان .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(862, 'آذرآبادگون', '<span class=\"hlight\">آذرآبادگون .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِ مرکب )آتشگاه . گلخن . کوره ٔ آهنگری و امثال آن . (برهان ).<br /></font></div>'),
(863, 'آذرآیین', '<span class=\"hlight\">آذرآیین .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نام آتشکده ٔ چهارم از هفت آتشکده ٔ ایرانیان که بشماره ٔ هفت سیاره کرده بودند و بخوری که متعلق به آن کوکب بوده در آن میسوخته اند. و آن را آذرآبتین نیز ضبط کرده اند.<br /></font></div>'),
(864, 'آذرافروز', '<span class=\"hlight\">آذرافروز.</span> <font color=\"DarkGreen\"><b>[ ذَ اَ ]</font></b> (اِ مرکب ) آتش افروز، یعنی ظرفی سفالین که برای تیز کردن آتش بکار میبرده اند. رجوع به آتش افروز شود. <BR><font color=\"Blue\">◄</font> ققنس، مرغ معروف یعنی فنقس .<br /></font></div>'),
(865, 'آذرافزا', '<span class=\"hlight\">آذرافزا.</span> <font color=\"DarkGreen\"><b>[ ذَ اَ ]</font></b> (اِ مرکب ) آتش افروز. آذرافروز، یعنی ظرف سفالین برای تیز کردن آتش .<br /></font></div>'),
(866, 'آذرانشاه', '<span class=\"hlight\">آذرانشاه .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) لقب آذر بهرام که نام آتشکده ٔ سوم از هفت آتشکده ٔ فارسیانست .<br /></font></div>'),
(867, 'آذرباد', '<span class=\"hlight\">آذرباد.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) آذربایجان . <BR><font color=\"Blue\">◄</font> نام موبدی که بانی آذربایجان بوده است .<br /></font></div>'),
(868, 'آذرباد زرادستان', '<span class=\"hlight\">آذرباد زرادستان .</span> <font color=\"DarkGreen\"><b>[ ذَ دِ زَ دِ ]</font></b> (اِخ ) نام حکیمی بزمان بهرام گور که بهرام را بنصیحت از گفتن شعر بازداشت . (از المعجم ).<br /></font></div>'),
(869, 'آذربادجان', '<span class=\"hlight\">آذربادجان .</span> <font color=\"DarkGreen\"><b>[ ذَ دِ ]</font></b> (اِخ ) آذربایجان : و باز مغیرةبن شعبه را بفرستاد تا آذربادجان را بگشاد. (تاریخ سیستان ).<br /></font></div>'),
(870, 'آذربادگان', '<span class=\"hlight\">آذربادگان .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نام آتشکده ای که در تبریز بوده است و معنی ترکیبی آن نگهدارنده و حافظ و خازن آتش است، چه آذر به معنی آتش و بادگان به معنی نگهدارنده و خزانه دار و حفظکننده باشد. (از برهان قاطع) <span class=\"hlight\">:</span> اندر خلافت او <font color=\"DarkGreen\"><b>[ عمر]</font></b> اویس بن انیس القرنی به آذربادگان بمرد. (مجمل التواریخ ) . <BR><font color=\"Blue\">◄</font> نام شهر تبریز. (برهان ). <BR><font color=\"Blue\">◄</font> (اِ مرکب ) آتشخانه . بیت النار. آتشکده . <BR><font color=\"Blue\">◄</font> شمال . (مفاتیح ).<br /></font></div>'),
(871, 'آذربایجان', '<span class=\"hlight\">آذربایجان .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) (گویند این کلمه از آترپاتوس، نام یکی از سرداران اسکندر مأخوذ است و صاحب معجم البلدان و بعض دیگر گفته اند که از لفظ آذر به معنی آتش و بادگان یا بایگان به معنی حافظ و خازن آمده است و معنی مجموع آن حافظالنار یا حافظ بیت النار باشد. آتروبات یا آذربدآتش پناه و اتروبات مانسارسپندان نام موبدی وزیر شاهپور دوم و شارح اوستاست که تمام نام او «پسر قانون مقدس آتش پناه » معنی میدهد. در صورتی که کلمه ٔ آتروبات و آذربد واسامی مانند این دو در زبان فارسی قدیم هست انتساب نام آذربایجان به نام سردار اسکندر محتاج به ادله ٔ قاطعتری از تاریخ است که از غیر مآخذ یونانی و رومی باشد) نام ایالتی از ایران که آن را آذر و آذرباد و آذربادگان و آذرباذگان و آذربایگان و آذربیجان و اَذْرَبیجان بر وزن عندلیبان (معجم البلدان ) نیز نامند. آذربایجان در قدیم از شمال به ارّان و از جنوب غربی به آشور و از مغرب بارمنستان و از مشرق بدو ایالت مغان و گیلان محدود میشده و پای تخت آن شهر گنجک بوده است در تخت سلیمان در جنوب شرقی مراغه و عرب آن را کزناو یونانیان گازا مینامیده اند. و آذربایجان فعلی محدود است از شمال برود ارس و از مغرب بارمنستان و کردستان ترکیه و از جنوب بکردستان و خمسه و از مشرق بکوههای طالش و مغان . سرزمین آذربایجان فلاتی مرتفع و کوهستانی و بلندترین نفاط آن قله ٔ معروف بکوه نوح کوچک است که <span class=\"hlight\" dir=\"rtl\">١٥٠٠</span> گز ارتفاع آن است . موقع جغرافیائی آن درعرض شمالی از <span class=\"hlight\" dir=\"rtl\">٣٦</span> تا <span class=\"hlight\" dir=\"rtl\">٣٨</span> درجه و نیم و طول شرقی از <span class=\"hlight\" dir=\"rtl\">٤١</span>درجه و نیم تا <span class=\"hlight\" dir=\"rtl\">٤٦</span> درجه و ربع، و مساحت سطح آن <span class=\"hlight\" dir=\"rtl\">١٠٤</span>هزار کیلومتر مربع و جمعیت آن در حدود دوملیون است . هوای آن معتدل و متمایل بسردی است . و در زمستان مخصوصاً در نقاط پرارتفاع بسیار سرد شود. اراضی آن عموماً حاصلخیز و مشتمل بر مراتع سبز و خرم است و انواع حبوب و میوه ها بخوبی و فراوانی در آن بعمل می آید و انگور آن مخصوصاً بتنوع و وفور و خوبی مشهور است . مهمترین کوههای آذربایجان سبلان و سهند و بلاد مشهور آن تبریز و ماکو و مرند و خوی و سلماس و قراجه داغ و اردبیل و خلخال و سراب و هشترود و مراغه و صاین قلعه ٔ افشار و ساوجبلاغ و ارومیه است . زبان مردم آذربایجان شعبه ای از زبان فارسی موسوم بزبان آذری بوده است . آذربایجان در این عصر بدو قسمت مستقل شرقی و غربی تقسیم شده، مرکز آذربایجان غربی شهر ارومیه است، دومین دریاچه ٔمهم و معتبر ایران در آذربایجان غربی واقع است و آن دریاچه ٔ ارومیه میباشد که آبش مختلط با املاح بسیار و غلظت و شوری و تلخی آن بحدی است که هیچگونه جانور در آن زیست نتواند کردن . آذربایجان از زلزله آسیب بسیار دیده و خاصّةً شهر تبریز چند بار بزلزله خراب شده است و بدین سبب از آثار قدیمه در این سرزمین جز قلیلی بر جای نمانده است .<br /></font></div>'),
(872, 'آذربایجان', '<span class=\"hlight\">آذربایجان .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نام شعبه ای از هری رود. (نزهةالقلوب ).<br /></font></div>'),
(873, 'آذربایجان', '<span class=\"hlight\">آذربایجان .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نامی است که امروز بولایت ارّان (جزئی از آذربایجان قدیم ) داده اند.<br /></font></div>'),
(874, 'آذربایگان', '<span class=\"hlight\">آذربایگان .</span> <font color=\"DarkGreen\"><b>[ ذَ ی ِ ]</font></b> (اِخ ) آذربایجان <span class=\"hlight\">:</span> <br />گزیده هرچه در ایران بزرگان <br />ز آذربایگان و ری و گرگان .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />ارمغان فتح آذربایگان شعر من است <br />ورچه شعری را بجای ارمغان نتوان گرفت .<br /><font color=\"Red\">اثیر اخسیکتی .</font><br /></font></div>'),
(875, 'آذربایگانی', '<span class=\"hlight\">آذربایگانی .</span> <font color=\"DarkGreen\"><b>[ ذَ ی ِ ]</font></b> (ص نسبی ) منسوب به آذربایگان . آذربایجانی <span class=\"hlight\">:</span> <br />چو شهرو ماهرخ زآن ماه آباد<br />چو آذربایگانی سرو آزاد.<br /><font color=\"Red\">(ویس و رامین ).</font><br /></font></div>'),
(876, 'آذربد', '<span class=\"hlight\">آذربد.</span> <font color=\"DarkGreen\"><b>[ ذَ ب َ ]</font></b> (ص مرکب، اِ مرکب ) رجوع به آتُربات شود.<br /></font></div>'),
(877, 'آذربدماراسپندان', '<span class=\"hlight\">آذربدماراسپندان .</span> <font color=\"DarkGreen\"><b>[ ذَ ب َ اِ پ َ ]</font></b> (اِخ ) رجوع به آتُربات مانسارسپندان شود.<br /></font></div>'),
(878, 'آذربو', '<span class=\"hlight\">آذربو.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِ مرکب ) بیخی سیاه رنگ شبیه به شلغم و بر روی او چیزها مثل گره رسته و گیاه او خاردار بقدر شبری بسیارشاخ و برگش شبیه بکرنب و ثمرش مانند غلاف نخود و در آن دو یا سه عدد دانه مایل بزردی و منبت او کشتزارها است، وبسریانی عرطنیثا نامند و به فارسی چووه ٔ صباغان گویند و او غیر از چووه ٔ گازران است . و قسمی از بخور مریم است و در بردن چرک از پشمینه و جامه مثل صابون است . (تحفه ). و آن را آذربویه نیز گویند. و گویند اصل کلمه یونانی است، و صاحب اختیارات بدیعی گوید گل آن زرد است و صاحب برهان گوید بر وزن نازک خو گل اشنان است و آن زردرنگ میباشد و بوته ٔ آن پرخار است و بیخ آن را گلیم شوی گویند و به عربی فلار خوانند و شیرازیان چوبک اشنانش گویند. آن را قصب شوی نیز نامند. و داودضریر انطاکی نیز عرطنیثا را معنی آذربو داده است .<br /></font></div>'),
(879, 'آذربویه', '<span class=\"hlight\">آذربویه .</span> <font color=\"DarkGreen\"><b>[ ذَ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (اِ مرکب ) رجوع به آذربو شود.<br /></font></div>'),
(880, 'آذربیجان', '<span class=\"hlight\">آذربیجان .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) معرّب آذربادگان . (مفاتیح ).<br /></font></div>'),
(881, 'آذرتش', '<span class=\"hlight\">آذرتش .</span> <font color=\"DarkGreen\"><b>[ ذَ ت ُ ]</font></b> (اِ مرکب ) بعض از فرهنگها این کلمه را ضبط کرده و معنی سمندربدان داده و شعر ذیل را شاهد آورده اند <span class=\"hlight\">:</span> <br />درروَد بی زخم و زجر و درشود بی ترس و بیم <br />همچو آذرتش به آتش همچو مرغابی بجوی .<br /> <font color=\"Red\">منوچهری .</font><br /> <br />و بعضی آذرشین را همین معنی داده و به همین شعر استشهاد کرده اند ولی ظاهراً صحیح آن آذرشب است .<br /></font></div>'),
(882, 'آذرجشن', '<span class=\"hlight\">آذرجشن .</span> <font color=\"DarkGreen\"><b>[ ذَ ج َ ]</font></b> (اِ مرکب ) نام عیدی از اعیاد فارسیان . رجوع به آذرخش شود.<br /></font></div>'),
(883, 'آذرخ', '<span class=\"hlight\">آذرخ .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) شهری است بشام خرّم و بانعمت و اندر وی خارجیانند. (حدودالعالم ). و این ظاهراً مصحف اَذْرُخ است که بنا بضبط یاقوت شهری است در اطراف شام .<br /></font></div>'),
(884, 'آذرخرین', '<span class=\"hlight\">آذرخرین .</span> <font color=\"DarkGreen\"><b>[ ذَ خ ُ ]</font></b> (اِخ ) آذر خرداد.<br /></font></div>'),
(885, 'آذرخش', '<span class=\"hlight\">آذرخش .</span> <font color=\"DarkGreen\"><b>[ ذَ خ ُ ]</font></b> (اِ مرکب ) نام روز آذر است از ماه آذر و فارسیان در این روز که نام ماه و نام روز مطابقت دارد جشن کنند و آتشکده ها را زینت دهند و در این روز موی ستردن و ناخن گرفتن و به آتش خانه شدن را نیک دانند.<br /></font></div>'),
(886, 'آذرخش', '<span class=\"hlight\">آذرخش .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ ]</font></b> (اِ) برق . صاعقه . آدرخش <span class=\"hlight\">:</span> <br />نباشد زین زمانه بس شگفتی <br />اگر بر ما بیاید آذرخشا.<br /> <font color=\"Red\">رودکی (از فرهنگ اسدی، خطی ).</font><br />خصمت بود بجنگ خف و تیرت آذرخش <br />تو همچو کوه و تیر بداندیش تو صدا.<br /> <font color=\"Red\">اسدی .</font><br /><BR><font color=\"Blue\">◄</font> در بعض فرهنگها سرمای سخت که در آن بیم هلاک بود و نام نهمین روز از ماه آذر.<br /></font></div>'),
(887, 'آذرسنج', '<span class=\"hlight\">آذرسنج .</span> <font color=\"DarkGreen\"><b>[ ذَ س َ ]</font></b> (اِ مرکب )پیرومتر . (فرهنگستان ).<br /></font></div>'),
(888, 'آذرشب', '<span class=\"hlight\">آذرشب .</span><font color=\"DarkGreen\"><b>[ ذَ ش َ ]</font></b> (اِخ ) نام فرشته ٔ موکل آتش که پیوسته در آتش است . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) سمندر <span class=\"hlight\">:</span> <br />در شودبی زخم و زجر و درشود بی ترس و بیم <br />همچو آذرشب به آتش همچو مرغابی بجوی .<br /> <font color=\"Red\">منوچهری .</font><br /><font color=\"DarkGreen\"><b>[ و خسروپرویز را بود ]</font></b> دستارچه ٔ آذرشب و آن از موی سمندر بافته بود. (مجمل التواریخ ). محتمل است مراد از موی سمندر حجرالفتیله یعنی پنبه ٔ کوهی باشد و بعید نیست که آذرشب نیز به معنی حجرالفتیله بوده است . <BR><font color=\"Blue\">◄</font> و در بعض فرهنگها معنی برق و نیز نام آتشکده ای که گشتاسب در بلخ بنا نهاد و گنج های خویش در آن پنهان کرد آمده است .<br /></font></div>'),
(889, 'آذرشسپ', '<span class=\"hlight\">آذرشسپ .</span> <font color=\"DarkGreen\"><b>[ ذَ ش َ ]</font></b> (اِخ )ظاهراً مخفف آذرگشسب یا آذرگشنسب باشد <span class=\"hlight\">:</span> <br />آب و آتش نخوانده او را اسب <br />آن صدف خواند و اینْش آذرشسب .<br /> <font color=\"Red\">سنائی .</font><br />وصاحب برهان میگوید نام فرشته ای است موکل بر آتش که پیوسته در میان آتش است . رجوع به آذرشب شود.<br /></font></div>'),
(890, 'آذرشین', '<span class=\"hlight\">آذرشین .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِ مرکب ) سمندر. <BR><font color=\"Blue\">◄</font> حربا. و در بعض فرهنگها در شعر منوچهری بجای آذرشب آذرشین ضبط کرده و شعر را شاهدبرای آذرشین آورده اند .<br /></font></div>'),
(891, 'آذرطوس', '<span class=\"hlight\">آذرطوس .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) در وامق و عذرای عنصری نام مردی است که مادر عذرا رابدو داده بودند. (از فرهنگ اسدی، خطی ) <span class=\"hlight\">:</span> <br />پدرداده بودش گه کودکی <br />به آذرطوس آن حکیم نکی (کذا) <br />بمرگ خداوندش آذرطوس <br />تبه کرد مر خویشتن برفسوس .<br /> <font color=\"Red\">عنصری (از فرهنگ اسدی، خطی ).</font><br /> <br /></font></div>'),
(892, 'آذرفرنبغ', '<span class=\"hlight\">آذرفرنبغ.</span> <font color=\"DarkGreen\"><b>[ ذَ ف َ رَم ْ ب َ ]</font></b> (اِخ ) نام یکی از سه آتش مقدس روحانی است که برای حفظ جهان آفریده شده و آتشهای دیگر از این سه زاده است و آن دوی دیگر آذرگشنسب و آذر برزین مهر است .<br /></font></div>'),
(893, 'آذرفروز', '<span class=\"hlight\">آذرفروز.</span> <font color=\"DarkGreen\"><b>[ ذَ ف ُ ]</font></b> (اِ مرکب ) آتش افروز، و آن ظرفی سفالین است که بدان آتش را تیز کنند.<br /></font></div>'),
(894, 'آذرفزا', '<span class=\"hlight\">آذرفزا.</span> <font color=\"DarkGreen\"><b>[ ذَ ف َ ]</font></b> (اِ مرکب ) آتش افروز. آذرفروز. آذرافزا. ظرفی سفالینه که مجاور آتش نیم افروخته نهند تیز کردن آنرا <span class=\"hlight\">:</span> <br />نفس را بعذرم چو انگیز کرد<br />چو آذرفزا آتشم تیز کرد.<br /> <font color=\"Red\">رودکی .</font><br /><BR><font color=\"Blue\">◄</font> مقراضی که آتش بدان تند و تیز کنند. <BR><font color=\"Blue\">◄</font> (نف مرکب ) سادن و خادم آتشکده .<br /></font></div>'),
(895, 'آذرم', '<span class=\"hlight\">آذرم .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِ) نمدزین . زینی که از میان دونیم باشد. رجوع به آدرم و ادرم شود.<br /></font></div>'),
(896, 'آذرم', '<span class=\"hlight\">آذرم .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نام قریه ای از قرای اذنه .<br /></font></div>'),
(897, 'آذرماه', '<span class=\"hlight\">آذرماه .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِ مرکب ) آذرمه . نام ماه نهم از ماههای شمسی . نوبت آفتاب در این ماه مر برج قوس را باشد. (نوروزنامه ). و مطابق است با تشرین ثانی . <BR><font color=\"Blue\">◄</font> آذرماه رومی یا سریانی مطابق است با فروردین ماه جلالی .<br /></font></div>'),
(898, 'آذرمه', '<span class=\"hlight\">آذرمه .</span> <font color=\"DarkGreen\"><b>[ ذَ م َه ْ ]</font></b> (اِ مرکب ) آذرماه <span class=\"hlight\">:</span> <br />وآن پرّ نگارینْش بر او بازنبندند<br />تا آذرمه بگذرد و آید آذار.<br /> <font color=\"Red\">منوچهری .</font><br />دست آذرمه از کمان هوا<br />تیرها زد چو ناوک دلدوز.<br /><font color=\"Red\">ازرقی .</font><br /></font></div>'),
(899, 'آذرمهر', '<span class=\"hlight\">آذرمهر.</span> <font color=\"DarkGreen\"><b>[ ذَ م ِ ]</font></b> (اِخ ) نام آتشکده ٔ نخستین از هفت آتشکده ٔ بزرگ ایرانیان . (از جهانگیری ). و ظاهراً اصل آن آذر برزین مهر است <span class=\"hlight\">:</span> شب سوم باز چنین دید که آذرفرنبغ و آذرگشسب و آذر برزین مهر بخانه ٔ ساسان فروزانند. (کارنامه ٔ اردشیر).<br /></font></div>'),
(900, 'آذرنوش', '<span class=\"hlight\">آذرنوش .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نوش آذر. نام آتشکده ٔ دوم از جمله ٔ هفت آتشکده ٔ فارسیان .<br /></font></div>'),
(901, 'آذرنگ', '<span class=\"hlight\">آذرنگ .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ ]</font></b> (اِ) غم صعب . محنت صعب . (فرهنگ اسدی ). درد. رنج . خدوگ . آدرنگ <span class=\"hlight\">:</span> <br />ز فرزند بر جان و تنْت آذرنگ <br />تو از مهر او روز و شب چون نهنگ .<br /> <font color=\"Red\">ابوشکور.</font><br />به آهن نگه کن که برّید سنگ <br />نرست آهن از سنگ بی آذرنگ .<br /> <font color=\"Red\">ابوشکور.</font><br />مکن بیش از این در جدایی درنگ <br />که از غم بجانم رسید آذرنگ .<br /> <font color=\"Red\">خسروانی .</font><br />نباشد کوه راوقت درنگ تو درنگ تو<br />جهان هرگز نجوید تا تو باشی آذرنگ تو.<br /> <font color=\"Red\">فرخی .</font><br />نیاید هیچ شاهی سوی تو هرگز بجنگ تو<br />جهان هرگز نجوید تا تو باشی آذرنگ تو.<br /> <font color=\"Red\">فرخی .</font><br />تا کیم از چرخ رسد آذرنگ <br />تا کیم از گونه ٔ چون بادرنگ ؟<br /> <font color=\"Red\">مسعودسعد.</font><br />ای چشم خوشت مرا چو دیده <br />یک روز مباد آذرنگت .<br /> <font color=\"Red\">سنائی .</font><br />بی آذرنگ آید هر لنگ از عصا<br />فرعون لنگ را ز عصا آمد آذرنگ .<br /> <font color=\"Red\">سوزنی .</font><br />انصاف و عدل شاه بتدبیر رای تو<br />برداشت از جهان ستم و جور و آذرنگ .<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> آتش <span class=\"hlight\">:</span> <br />چو گوگرد زد محنتم آذرنگ <br />که در خاکم افکند چون بادرنگ .<br /> <font color=\"Red\">مسعودسعد.</font><br />برآسود یک هفته بر جای جنگ <br />بیاقوت می رنگ داد آذرنگ .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> (ص )روشن . منور <span class=\"hlight\">:</span> <br />بسنگ گران آمد آن سنگ خورد<br />مر آن سنگ این سنگ بشکست خرد<br />فروغی پدید آمد از هر دو سنگ <br />دل سنگ گشت از فروغ آذرنگ .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(902, 'آذرنگی', '<span class=\"hlight\">آذرنگی .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ ]</font></b> (ص نسبی ) منسوب به آذرنگ . <BR><font color=\"Blue\">◄</font> آتشی . برنگ آتش <span class=\"hlight\">:</span> <br />سیه را سرخ چون کردآذرنگی <br />چو بالای سیاهی نیست رنگی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(903, 'آذره', '<span class=\"hlight\">آذره .</span> <font color=\"DarkGreen\"><b>[ ذِ رَ ]</font></b> (ع ص ) ماده اشتر قوی . <BR><font color=\"Blue\">◄</font> لیلة آذره ؛ شبی سرد. (مهذب الاسماء).<br /></font></div>'),
(904, 'آذرهمایون', '<span class=\"hlight\">آذرهمایون .</span> <font color=\"DarkGreen\"><b>[ ذَ هَُ ]</font></b> (اِخ ) نام دختری ازنسل سام، سادنه ٔ آتشکده ٔ اصفهان، و گویند او ساحره ای بوده است که چون اسکندر خواست آتشکده ٔ اصفهان خراب کند خود را به صورت ماری مهیب به اسکندر نمود و بلیناس سحر او را باطل کرد، اسکندر آذرهمایون را بدو بخشید و بلیناس او را به زنی کرد و بلیناس را بلیناس جادو از آن رو گفته اند که از این زن جادویی ها آموخته است . ظاهراً منشاء این افسانه اسکندرنامه ٔ نظامی است :<br />بهار کهن بود و چینی نگار<br />بسی خوشتر از باغ و از نوبهار<br />به آیین زردشت و رسم مجوس <br />بخدمت در آن خانه چندین عروس <br />هم آشوب دیده هم آشوب دل <br />فرورفته دل را بسی پا بگل <br />در او دختری جادو از نسل سام <br />پدر کرده آذرهمایونْش نام ...<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(905, 'آذرهوشنگ', '<span class=\"hlight\">آذرهوشنگ .</span> <font color=\"DarkGreen\"><b>[ ذَ ش َ ]</font></b> (اِخ ) نام نخستین پیغامبری که بایرانیان مبعوث شده . (از برهان، در کلمه ٔ آذریان ).<br /></font></div>'),
(906, 'آذروان', '<span class=\"hlight\">آذروان .</span> <font color=\"DarkGreen\"><b>[ ذَرْ ]</font></b> (ص مرکب، اِ مرکب ) (از آثاروان ) پیشوا و دستور مزدایسنی .<br /></font></div>'),
(907, 'آذرولاش', '<span class=\"hlight\">آذرولاش .</span> <font color=\"DarkGreen\"><b>[ ذَ وَ ]</font></b> (اِخ ) ششمین پادشاه سلسله ٔ اوّل ِ آل ِقارن (<span class=\"hlight\" dir=\"rtl\">٦٢٧</span>-<span class=\"hlight\" dir=\"rtl\">٦٤٧</span> هَ . ق .).<br /></font></div>'),
(908, 'آذرویه', '<span class=\"hlight\">آذرویه .</span> <font color=\"DarkGreen\"><b>[ ذَ وَی ْه ْ ]</font></b> (اِ) نامی از نامهای ایرانی .<br /></font></div>'),
(909, 'آذرپرست', '<span class=\"hlight\">آذرپرست .</span> <font color=\"DarkGreen\"><b>[ ذَ پ َ رَ ]</font></b> (نف مرکب ) آتش پرست . عابدالنار. گبر <span class=\"hlight\">:</span> <br />چو پیروزی شاهتان بشنوید<br />گزیتی به آذرپرستان دهید.<br /> <font color=\"Red\">فردوسی .</font><br />بر آن شهرها تازیان راست دست <br />که نه شاه ماند نه آذرپرست .<br /> <font color=\"Red\">فردوسی .</font><br />موبد آذرپرستان را دل من قبله شد<br />زآنکه عشقش در دل من آذر برزین نهاد.<br /> <font color=\"Red\">معزّی .</font><br />بگفتا نگیرم طریقی بدست <br />که نشنیدم از پیر آذرپرست .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(910, 'آذرپرستی', '<span class=\"hlight\">آذرپرستی .</span><font color=\"DarkGreen\"><b>[ ذَ پ َ رَ ]</font></b> (حامص مرکب ) دین و عمل پرستیدن آذر.<br /></font></div>'),
(911, 'آذرپیرا', '<span class=\"hlight\">آذرپیرا.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (نف مرکب ) سادن و خادم آتشکده .<br /></font></div>'),
(912, 'آذرکده', '<span class=\"hlight\">آذرکده .</span> <font color=\"DarkGreen\"><b>[ ذَ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) آتشکده .<br /></font></div>'),
(913, 'آذرکیش', '<span class=\"hlight\">آذرکیش .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ص مرکب ) آتش پرست . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) دین آتش پرستی .<br /></font></div>'),
(914, 'آذرکیوان', '<span class=\"hlight\">آذرکیوان .</span> <font color=\"DarkGreen\"><b>[ ذَ ک َی ْ ]</font></b> (اِخ ) نام حکیمی از مردم استخر فارس، معاصر و معاشر میرفندرسکی، و بهندوستان معتقدان داشته .<br /></font></div>'),
(915, 'آذرگشب', '<span class=\"hlight\">آذرگشب .</span> <font color=\"DarkGreen\"><b>[ ذَ گ ُ ش َ ]</font></b> (اِخ ) مخفف آذرگشسب .<br /></font></div>'),
(916, 'آذرگشسب', '<span class=\"hlight\">آذرگشسب .</span> <font color=\"DarkGreen\"><b>[ ذَ گ ُ ش َ ]</font></b> (اِخ ) مخفف آذرگشنسب، یکی از سه آتش مقدس حافظ جهان . <BR><font color=\"Blue\">◄</font> نام آتشکده ٔ گشتاسب است که در بلخ بوده، گنجهای گشتاسب نیز در آنجا بود، اسکندرآن را خراب کرده و گنجها برداشت، و بعضی گفته اند کتاب زند و اوستا نیز بدانجا بوده است . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) مطلق آتشکده را گویند. <BR><font color=\"Blue\">◄</font> بمعنی برق هم آمده است . <BR><font color=\"Blue\">◄</font> (اِخ ) نام فرشته ای است موکل بر آتش که پیوسته در آتش مقام دارد و معنی ترکیبی آن آتش جهنده باشد چه آذرآتش و گشسب به معنی جهنده و خیزکننده آمده است و این معنی مناسبت تمامی با برق دارد. (برهان ). رجوع به آذرگشنسب شود <span class=\"hlight\">:</span> <br />همان اسب تو شاه اسب من است <br />کلاه تو آذرگشسب من است .<br /> <font color=\"Red\">فردوسی .</font><br />چنان دید در خواب کآتش پرست <br />سه آتش فروزان ببردی بدست <br />چو آذرگشسب و چو خرّاد و مهر<br />فروزان چو بهرام و ناهید چهر.<br /> <font color=\"Red\">فردوسی .</font><br />بیزدان که او را سزد برتری <br />نگارنده ٔ زهره و مشتری <br />بتاج و بگاه و بخورشید و ماه <br />به آذرگشسب و بمهر و کلاه <br />که از شاه خاقان نپیچد بدل <br />نباشد بکاری ورا دل گسل .<br /> <font color=\"Red\">فردوسی .</font><br />در نظامی آمده است :<br />ببلخ آمد و آذر زردهشت <br />بطوفان شمشیر چون آب کشت <br />بهار دل افروز در بلخ بود<br />کزو تازه گل رادهن تلخ بود<br />زده موبدش نعل زرین بر اسب <br />شده نام آن خانه آذرگشسب .<br />از این روی ظاهر می شود که عقیده ٔ صاحب برهان و فرهنگ نویسان دیگر متکی بر همین ابیات نظامی است، لیکن با اینکه نظامی از بزرگان شعر و ادب است گفته های او در تاریخ محل اعتماد تام نتواند بود، خاصه اگر با صریح شاهنامه نیز مخالف باشد. آذرگشسب چنانکه از قطعات ذیل روشن است نام آتشکده ٔ آذربایجان بوده است نه آتشکده ٔ بلخ <span class=\"hlight\">:</span> <br />چو بشنید خسرو که شاه جهان <br />همی خون او جوید اندر نهان <br />شب تیره از طیسفون درکشید<br />تو گفتی که گشت از جهان ناپدید<br />نداد آن سر پربها رایگان <br />همی تاخت تا آذرآبادگان <br />چو آگاهی آمد بهر مهتری <br />که بد مرزبان یا سر کشوری ...<br />یکایک بخسرو نهادند روی <br />سپاه و سپهبد همه نامجوی <br />از ایران و از دشت نیزه وران <br />زخنجرگذاران و جنگی سران <br />همی گفت هر کس که ای پور شاه <br />ترا زیبد این تخت و تاج و کلاه <br />نگر تا نداری هراس از گزند<br />بزی شاد و آرام و دل ارجمند<br />زمانی بنخجیر تازیم اسپ <br />زمانی نوان پیش آذرگشسپ ...<br />بدیشان چنین گفت خسرو که من <br />پر از بیمم از شاه وز انجمن <br />اگر پیش آذرگشسب این سران <br />بیایند و سوگندهای گران <br />خورند و مرا یکسر ایمن کنند<br />که پیمان من زآن سپس نشکنند...<br />یلان چون شنیدند گفتار اوی <br />همه سوی آتش نهادند روی <br />بخوردند سوگندهایی که خواست <br />که مهر تو ما زنده داریم راست .<br /> <font color=\"Red\">فردوسی .</font><br />از آن جایگه لشکر اندرکشید<br />سوی آذرآبادگان برکشید<br />چو از پارس لشکر فراوان نبُرد<br />چنین بود نزد بزرگان و خرد<br />که از جنگ بگریخت بهرام شاه <br />ورا سوی آذرگشسپ است راه <br />چو بهرام رخ سوی آذر نهاد<br />فرستاده آمد ز قیصر چو باد.<br /> <font color=\"Red\">فردوسی .</font><br />پس و پیش گرد اندرآزادگان <br />همی رفت <font color=\"DarkGreen\"><b>[ نوشیروان ]</font></b> تا آذرآبادگان <br />چو چشمش برآمد بر آذرگشسپ <br />پیاده شد از دور و بگذاشت اسپ .<br /> <font color=\"Red\">فردوسی .</font><br />نشستند چون باد هر دو بر اسپ <br />دمان تا در خان آذرگشسپ <br />بیک ماه در آذرآبادگان <br />ببودند شاهان و آزادگان .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آذرگشسب </span> ؛ سخت تیز و چابک و چالاک <span class=\"hlight\">:</span><br />سواری بکردار آذرگشسپ <br />ز کابل سوی شام شد بر سه اسپ .<br /> <font color=\"Red\">فردوسی .</font><br />ازآتش گُسی کرد بانوگشسپ <br />ابا خواسته همچو آذرگشسپ .<br /> <font color=\"Red\">فردوسی .</font><br />چو رستم بدیدش برانگیخت اسپ <br />بیامد بر او چو آذرگشسپ .<br /> <font color=\"Red\">فردوسی .</font><br />سپهبد برآمد خروشان به اسپ <br />روان شد بکردار آذرگشسپ .<br /> <font color=\"Red\">فردوسی .</font><br />یکی نیزه زد همچو آذرگشسپ <br />ز کوهه ببردش سوی یال اسپ .<br /> <font color=\"Red\">فردوسی .</font><br />چو برساخت کار اندرآمد به اسپ <br />برآمد بکردار آذرگشسپ .<br /> <font color=\"Red\">فردوسی .</font><br />وز آن پس نشستند گردان بر اسپ <br />براندند برسان آذرگشسپ .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(917, 'آذرگشنسب', '<span class=\"hlight\">آذرگشنسب .</span> <font color=\"DarkGreen\"><b>[ ذَ گ ُ ن َ ]</font></b> (اِخ ) (از: آذر، آتش + گشن، نر یا بخواهش آمده + اسب، حیوان معروف ) آذرگشسب .<br /></font></div>'),
(918, 'آذرگل', '<span class=\"hlight\">آذرگل .</span> <font color=\"DarkGreen\"><b>[ ذَ گ ُ ]</font></b> (اِ مرکب ) نام گلیست برنگ سرخ شبیه بشقایق .<br /></font></div>'),
(919, 'آذرگون', '<span class=\"hlight\">آذرگون .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِ مرکب ) (از: آذر، آتش + گون، فام ) گلی است که آن را خجسته گویند، رنگش زرد بود و میانش سیاه . (فرهنگ اسدی، خطی ) <span class=\"hlight\">:</span> <br />تا همی سرخ بود آذرگون <br />تا همی سبز بود سیسنبر...<br /> <font color=\"Red\">فرخی .</font><br />بهم بودند آنجا ویس و رامین <br />چو در یک باغ آذرگون و نسرین .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />ز خون و تف همه روزه دو دیده و دل من <br />یکی به آذر ماند یکی به آذرگون .<br /> <font color=\"Red\">قطران .</font><br />کراسیه حدقه چشمهای زرد مژه <br />ندیده اینک چشمی بدین صفت آفاق <br />دو چشم خویش برافکن بچشم آذرگون <br />در این زمان و بر آماق او گمار آماق <br />بچشم بر مژه ٔ زرد اگر نکو نبود<br />نکو بود سیه اندر میان چشم احداق .<br /> <font color=\"Red\">لامعی .</font><br />گر کسی گویدْت بس نیکو جوانی شاد باش <br />شادمان گردی و رخ مانند آذرگون کنی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ببوی خلقش ار خواهی کنی آذر چو آذرگون <br />بتاب خشمش ار خواهی ز آذرگون کنی آذر.<br /> <font color=\"Red\">ازرقی .</font><br />که پنهان کردجز ایزد بسنگ خاره در آذر<br />که رویاند همی جز وی ز خاک تیره آذرگون ؟<br /> <font color=\"Red\">سنائی .</font><br />برای طاعت تست آن نسیم جان پرور<br />که از میانه ٔ آذر بروید آذرگون .<br /> <font color=\"Red\">ظهیر فاریابی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span>).</font><br />بسان غالیه دانی رسید آذرگون <br />نشان غالیه مانده میان غالیه دان .<br /> <font color=\"Red\">(ازتاج المآثر).</font><br />از امثله ٔ فوق و نیز از مندرجات فرهنگها و لغتهای طبی چنین مستفاد می شود که آذرگون را قدما بدرستی نمیشناخته اند و یا این کلمه در امکنه و ازمنه ٔ مختلف معانی مختلف میداده است . از معانیی که برای این کلمه آورده اند همیشه بهار، خجسته، قسمی از شقایق که اطرافش خیلی سرخ و وسطش نقطه ٔ سیاه دارد، لاله، شقر، لاله ٔ دختری، آردم، گل آفتاب پرست، گاوچشم، خیری، کحله و زبیده است و گفته اند نوعی از گل است که بعضی بسرخی زند و برخی بزردی، و گفته اند که خاصیت او آن است که در زمستان پیدا شودو در تابستان نباشد و در بلاد طبرستان بسیار است و گویند معرّب آن آذریون است . و رجوع به آذریون شود. <BR><font color=\"Blue\">◄</font> موش آتشین که آن را سمندر گویند.<br /></font></div>'),
(920, 'آذری', '<span class=\"hlight\">آذری .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ص نسبی، اِ) منسوب به آذر <span class=\"hlight\">:</span> <br />ز خونی که بد بهره ٔ مادری <br />بجوشید و شدچهره اش آذری .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> منسوب به آذربایجان . (درةالغواص حریری ). <BR><font color=\"Blue\">◄</font> نام جامه ای که در آذربایجان بافتندی . (محمودبن عمر ربنجنی ). <BR><font color=\"Blue\">◄</font> زبان آذری ؛ لهجه ای از فارسی قدیم که در آذربایجان متداول بوده و اکنون نیز در بعض نواحی قفقاز بدان تکلم کنند. <BR><font color=\"Blue\">◄</font> مشک تیزبو. (محمودبن عمر ربنجنی ).<br /></font></div>'),
(921, 'آذری', '<span class=\"hlight\">آذری .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) تخلص شاعری ایرانی بقرن نهم هجری مادح سلاطین عادلشاهی دکن .<br /></font></div>'),
(922, 'آذری', '<span class=\"hlight\">آذری .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ )شیخ نورالدین حمزةبن عبدالملک بیهقی طوسی، معاصر الغبیک تیموری . یکی از شعرا و از پیشوایان طریقت صوفیه بوده و به صحبت شاه نورالدین نعمةاﷲ کرمانی رسیده است، چندین بار بهند و بزیارت کعبه رفته است، مدت عمر او هشتادودو سال و در سال <span class=\"hlight\" dir=\"rtl\">٨٦٤</span> یا <span class=\"hlight\" dir=\"rtl\">٨٦٦</span> هَ . ق . وفات کرده است . مزارش در اسفراین است . از تصانیف او عجایب الدنیا و سعی الصفا و طغرای همایون و جواهرالاسرار است .<br /></font></div>'),
(923, 'آذری طوس', '<span class=\"hlight\">آذری طوس .</span><font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِ) نام مسهلی است مرکب از بیست وپنج جزء.<br /></font></div>'),
(924, 'آذریاس', '<span class=\"hlight\">آذریاس .</span> <font color=\"DarkGreen\"><b>[ ذَرْ ]</font></b> (اِ) اذریاس . صمغ سداب کوهی .<br /></font></div>'),
(925, 'آذریان', '<span class=\"hlight\">آذریان .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) امّتان آذرهوشنگ، و گویند آذرهوشنگ پیغمبر نخستین است که بعجم مبعوث شد.<br /></font></div>'),
(926, 'آذرین', '<span class=\"hlight\">آذرین .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِ) بضبط بعض فرهنگهای جدید، بابونه .<br /></font></div>'),
(927, 'آذریون', '<span class=\"hlight\">آذریون .</span> <font color=\"DarkGreen\"><b>[ ذَرْ ]</font></b> (اِ مرکب ) گلی باشد زرد که در میان زغب و پرزی با ریشه های سیاه دارد و خوش بوی نیست . و ایرانیان دیدار آن را نیک دارند و در خانه بپراکنند. (از قاموس ). چنانکه در آذرگون گفته شد آذریون معرب آذرگون است و اقوال فرهنگ نویسان مانند شعرا در معنی آن نهایت مختلف و مضطربست، و آن را خیری و نوعی بابونه و سطردیقون و اقحوان و زبیده و کخله و گاوچشم و همیشه بهار و نوعی از شقایق و گل آفتاب پرست و امثال آن گفته اند. صاحب تحفه گوید: نباتی است میان شجر و گیاه بقدر ذرعی برگش بی زواید و نرم بقدر برگ جرجیر و با اندک زغبیت و گلهای او بزرگ و پهن و مدور و زرد و رخشنده و در وسط او برگهای ریزه ٔسیاه مایل بسرخی و بغایت خوش منظر و همیشه رو به آفتاب دارد و بحرکت او دور میکند... و تشویش اقوال مؤلف اختیارات بر ارباب بصر پوشیده نخواهد بود - انتهی .و از این تعریف روشن می شود که آذریون همان گل است که اکنون آفتاب گردان نامند <span class=\"hlight\">:</span> و آذریون از حسد رخسار آتش رنگ او رخ بزرآب فروشست و بسان غمگینان از اوراق گلناری چهره زعفرانی بنمود. (تاج المآثر).<br />هر زمان چون آذر آذریون برخشد در چمن <br />هر زمان چون نیل نیلوفر بخندد در شمر.<br /> <font color=\"Red\">(تاج المآثر).</font><br />برای طاعت تست آن نسیم جان پرور<br />که از میانه ٔ آذر بروید آذریون .<br /><font color=\"Red\">ظهیر فاریابی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span>).</font><br /></font></div>'),
(928, 'آذن', '<span class=\"hlight\">آذن .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع ص ) دربان .<br /></font></div>'),
(929, 'آذن', '<span class=\"hlight\">آذن .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) مرد کلان گوش . بلّه گوش . حیوان بزرگ گوش و درازگوش .<br /></font></div>'),
(930, 'آذوغه', '<span class=\"hlight\">آذوغه .</span> <font color=\"DarkGreen\"><b>[ غ َ <span class=\"hlight\" dir=\"rtl\">/</span> غ ِ ]</font></b> (اِ) رجوع به آذوقه شود.<br /></font></div>'),
(931, 'آذوقه', '<span class=\"hlight\">آذوقه .</span> <font color=\"DarkGreen\"><b>[ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (اِ) (بعضی گویند کلمه ترکی است، و ظاهراً مصحف عدوقه و عذوقه ٔ عربی به معنی خوردنی باشد) ساز. ساز ره . برگ . آنچه از خوردنی همراه دارند سفر را. آنچه در خانه از غله و حبوب و امثال آن گرد کنند مصرف چند ماهی یا سالی را.<br /></font></div>'),
(932, 'آذون', '<span class=\"hlight\">آذون .</span> (ص ) به معنی آنچنان باشد، چنانکه ایذون به معنی اینچنین است <span class=\"hlight\">:</span> <br />تفکر کن یکی در خلقت شاهین و مرغابی <br />نگویی کز چه معنی راست این ایذون و آن آذون ؟<br /> <font color=\"Red\">سنائی .</font><br />رجوع به ایدون و اندون و آندون شود.<br /></font></div>'),
(933, 'آذی', '<span class=\"hlight\">آذی .</span> <font color=\"DarkGreen\"><b>[ ذی ی ]</font></b> (ع اِ) موج دریا. ج، اواذی .<br /></font></div>'),
(934, 'آذیش', '<span class=\"hlight\">آذیش .</span> (اِ) چوبی را گویند که بر آستانه ٔ در خانه استوار کنند. <BR><font color=\"Blue\">◄</font> بمعنی ریزه ٔ چوب و خس و خاشاک هم آمده است . (برهان ). و در بعض فرهنگها به معنی آتش یعنی صورتی از آدیش نیز آورده اند. و ظاهراً معنی دوم درست باشد. رجوع به آدیش شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(935, 'آذین', '<span class=\"hlight\">آذین .</span> (اِ) زیب . زیور. زینت . آرایش . آیین <span class=\"hlight\">:</span> <br />گر همی آرزو آیدْت عروسی ّ نو<br />دین عروست بس و دل خانه و علم آذین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای خوانده کُتْب و زو شده روشن دل <br />بسته ز علم و حکمت و پند آذین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تا ز مشک خم گرفته در گلش آذین بود<br />خم گرفتن قامت عشاق را آیین بود.<br /> <font color=\"Red\">امیر معزی .</font><br />از پی قدر خویش صدرش را<br />بسته روح القدس ز خلدآذین .<br /> <font color=\"Red\">سنائی .</font><br />ترک من مهر و وفا سیرت و آیین نکند<br />تا که بر برگ گل از غالیه آذین نکند<br />اندر آن آذین آیین وفا راست امید<br />ای نمیدی اگر آذین کند آیین نکند.<br /> <font color=\"Red\">سوزنی .</font><br />بر گل و نسرین و عنبر بند و آذین ای عجب <br />وآنگهی نظاره گرداندبر این آذین مرا.<br /> <font color=\"Red\">سوزنی .</font><br />بهر آذین عروس خاطرش <br />چرخ اطلس را بدیبایی فرست .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> خوازه و قبه یعنی چهارچوبها و گنبدها که گاه قدوم پادشاهی یا امیری و یا در جشنهای بزرگ در راهها و بازارها افرازند و بفرشها و جامه های گرانبها و گلها و چراغها و آینه ها زینت دهند، و آن را شهرآرای و آذین بند نیز گویند <span class=\"hlight\">:</span> <br />به آذین جهانی شد آراسته <br />در و بام و دیوار پرخواسته <br />همه روم با هدیه وبا نثار<br />برفتند شادان بر شهریار<br />جهانی به آذین بیاراستند<br />می و رود و رامشگران خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />بهمه شهر بود از آن آذین <br />در بریشم چو کرم پیله زمین .<br /> <font color=\"Red\">عنصری .</font><br /> <BR><font color=\"Blue\">◄</font> غرفه و نشیمن گاههای آراسته و مزین در جشنها <span class=\"hlight\">:</span> <br />خراسان سربسر آذین ببستند<br />پریرویان به آذینها نشستند.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />همه بازارها آذین ببستند<br />پریرویان بر آذینها نشستند.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بمرو اندر هزار آذین ببستند<br />پریرویان بر آذینها نشستند.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />همه شهر و ده بودپرخواسته <br />به آذین و گنبد بیاراسته .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> آیین و رسم و عادت <span class=\"hlight\">:</span> <br />نوشتند برسان و آذین چین <br />سوی شاه با صدهزار آفرین .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> خذرفه ؛ اَی انگور و خرما و انار که از خانه بیاویزند. (محمودبن عمر ربنجنی ) . <BR><font color=\"Blue\">◄</font> شیرزنه . آلتی که دوغ را از روغن جدا میکند. مرادف آیین . (برهان قاطع). چون کلمه ٔ آذین و آیین و آنین را به معنی بستو یا نهره که دوغ را در آن کرده بزنند تا روغن از آن جدا شود آورده اند، بعید نیست که دو صورت از آن سه مصحف باشد. <BR><font color=\"Blue\">◄</font> پیرایه از قبیل سرآویز و گوشوارو سلسله و حلقه ٔ بینی و گلوبند و بازوبند و دست برنجن و خلخال و انگشتری . <BR><font color=\"Blue\">◄</font> (اِخ ) نامی از نامهای مردان ایرانی <span class=\"hlight\">:</span> <br />چو انجامیده شد گفتار رامین <br />چو باد از پیش او برگشت آذین .<br /><font color=\"Red\">(ویس و رامین ).</font><br /></font></div>'),
(936, 'آذین بستن', '<span class=\"hlight\">آذین بستن .</span> <font color=\"DarkGreen\"><b>[ ب َ ت َ ]</font></b> (مص مرکب ) به آذین کردن <span class=\"hlight\">:</span> <br />نوروز جهان چون بت نوآیین <br />از لاله همه کوه بسته آذین .<br /> <font color=\"Red\">کسائی مروزی .</font><br />ببستند <font color=\"DarkGreen\"><b>[ رومیان ]</font></b> آذین ببیراه و راه <br />برآواز شیروی پرویزشاه <br />برآمد هم آواز رامشگران <br />همه شهر روم از کران تا کران .<br /> <font color=\"Red\">فردوسی .</font><br />ببستند آذین بشهر اندرون <br />پر از خنده لبها و دل پر ز خون .<br /> <font color=\"Red\">فردوسی .</font><br />بدان شهر بودیش جای نشست <br />همه شهر سرتاسر آذین ببست .<br /> <font color=\"Red\">فردوسی .</font><br />تبیره ببردند و پیل از درش <br />ببستند آذین همه کشورش .<br /> <font color=\"Red\">فردوسی .</font><br />ببستند آذین بشهر و براه <br />که شاه آمد از دشت نخجیرگاه .<br /> <font color=\"Red\">فردوسی .</font><br />ببستند آذین براه و بشهر<br />همی هر کس از کام برداشت بهر.<br /> <font color=\"Red\">فردوسی .</font><br />ابر فروردین گوئی بجهان آذین بست <br />که همه باغ پرند است و همه راغ حریر.<br /> <font color=\"Red\">فرخی .</font><br />فضل بن حمید اندر آمد مردمان شهر آذین بستند. (تاریخ سیستان ). و شهر را آذین بسته بودند آذینی از حد و اندازه گذشته . (تاریخ بیهقی ). و صحن گیتی را بنور علم و معرفت آذین بستند. (کلیله و دمنه ).<br /></font></div>'),
(937, 'آذین بند', '<span class=\"hlight\">آذین بند.</span> <font color=\"DarkGreen\"><b>[ ذیم ْ ب َ ]</font></b> (نف مرکب ) شهرآرای .<br /></font></div>'),
(938, 'آذین زدن', '<span class=\"hlight\">آذین زدن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ]</font></b> (مص مرکب ) آذین بستن <span class=\"hlight\">:</span> و بتمامت ممالک آذینها بزنند. (تاریخ طبرستان ). فرمود تا بخروارها زرو جواهر و جامه ها با مهد و عماری پیش مهر فیروز فرستند و بجمله ٔ ممالک آذینها زنند. (تاریخ طبرستان ).<br /></font></div>'),
(939, 'آذین نهادن', '<span class=\"hlight\">آذین نهادن .</span> <font color=\"DarkGreen\"><b>[ ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) آذین بستن <span class=\"hlight\">:</span> <br />بفرمود <font color=\"DarkGreen\"><b>[ افراسیاب ]</font></b> کز نامداران هزار<br />بخوانند و از بزم سازند کار<br />سراسر همه دشت آذین نهند<br />بسغد اندر آرایش چین نهند.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(940, 'آذینده', '<span class=\"hlight\">آذینده .</span> <font color=\"DarkGreen\"><b>[ ی َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ) رجوع به آدینده شود.<br /></font></div>'),
(941, 'آذینه', '<span class=\"hlight\">آذینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) آدینه .<br /></font></div>'),
(942, 'آذیوخان', '<span class=\"hlight\">آذیوخان .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) نام قریه ای بنهاوند.<br /></font></div>'),
(943, 'آر', '<span class=\"hlight\">آر.</span> (ع اِ) عار و ننگ .<br /></font></div>'),
(944, 'آر', '<span class=\"hlight\">آر.</span> (پسوند) -ار. اداتی است که عقیب مفرد غائب از ماضی درآید و آن را گاه بدل به اسم مصدر کند چون گفتار، کردار، رفتار، جستار، دیدار و گاه بدل بوصف فاعلی چون خواستار، خریدار، فروختار، نمودار و گاه وصف مفعولی چون گرفتار، کشتار. این ادات بطور ندرت بکلمات دیگر نیز ملحق شود و افاده ٔ معنی فاعلی کند چون پرستار، پدیدار، دوستار و کلمات خواستار و دوستار محتمل است که مخفف خواستگار و دوستدار باشد.<br /></font></div>'),
(945, 'آرا', '<span class=\"hlight\">آرا.</span> (نف مرخم ) مخفف آراینده، چنانکه در: انجمن آرا، بت آرا، بزم آرا، بهارآرا، پیکرآرا، جهان آرا، چمن آرا، خاطرآرا، خانه آرا، خودآرا، دست آرا، دل آرا، رزم آرا، سپاه آرا، سخن آرا، صدرآرا، صف آرا، عالم آرا، عروس آرا، کشورآرا، لشکرآرا، مجلس آرا، معرکه آرا، معنی آرا، ملْک آرا، موکب آرا، نثرآرا، نظم آرا، هنگامه آرا <span class=\"hlight\">:</span> <br />ترا نیز با رزم او پای نیست <br />ز ترکان چنین لشکرآرای نیست .<br /> <font color=\"Red\">فردوسی .</font><br />کجا نام آن نامور مای بود<br />بدنبر نشسته بت آرای بود.<br /> <font color=\"Red\">فردوسی .</font><br />مر آن را میان جهان جای کرد<br />پرستشگه خاطرآرای کرد.<br /> <font color=\"Red\">اسدی .</font><br />من اگر خارم اگر گل چمن آرایی هست <br />که از آن دست که میپروردم میرویم .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) زینت و زیب و آرایش <span class=\"hlight\">:</span> <br />نمیباید برافزودن اگر مشاطه ٔ قدرت <br />جمالی را بزیبائی نگاری کرد و آرایی .<br /><font color=\"Red\">نزاری قهستانی .</font><br /></font></div>'),
(946, 'آرا', '<span class=\"hlight\">آرا.</span> (اِخ ) (کلمه ٔ لاتینی ) یکی از صور فلکی . المحراب . الببغاء. المجمرة. آتشدان . (ابوریحان ).<br /></font></div>'),
(947, 'آراب', '<span class=\"hlight\">آراب .</span> (ع اِ) ج ِ اِرْب . اعضاء.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراب سبعه </span> ؛ مساجد سبعه است که گاه سجود بر زمین آید.<br /><BR><font color=\"Blue\">◄</font> آبله ها که بر اعضاء ظاهر شود. <BR><font color=\"Blue\">◄</font> پاره های گوشت .<br /></font></div>'),
(948, 'آرابایا', '<span class=\"hlight\">آرابایا.</span> (اِخ ) نام باستانی ایالت «چترپتی » بین النهرین .<br /></font></div>'),
(949, 'آراخوزیا', '<span class=\"hlight\">آراخوزیا.</span> (اِخ ) نام ناحیه ای باستانی در محل قندهار کنونی که آن را هراووتی و هرخوواهیش و یونانیان، آراکوزیا و عرب رخج مینامیدند.<br /></font></div>'),
(950, 'آراد', '<span class=\"hlight\">آراد.</span> (اِخ ) نام فرشته ای است موکل بر دین و تدبیر امور و مصالحی که بروز آراد متعلق است . <BR><font color=\"Blue\">◄</font> (اِ) روز بیست وپنجم از هر ماه شمسی که آن را ارد نیز گویند و در این روز نو بریدن و نو پوشیدن را نیک و سفر و نقل و تحویل شوم شمردندی .<br /></font></div>'),
(951, 'آرادان', '<span class=\"hlight\">آرادان .</span> (اِخ ) نام قریه ای بزرگ از ناحیه ٔ خوار ری .<br /></font></div>'),
(952, 'آرارات', '<span class=\"hlight\">آرارات .</span> (اِخ ) نام کوههای آتش فشان آذربایجان که بگفته ٔ توریة کشتی نوح بر یکی از قله های آن قرار گرفت، و کوه جودی و اگری داغ و آغری داغ جبل نوح و مسیس و مازیک از نامهای این کوه است، و آن را آراراط نیز نویسند.<br /></font></div>'),
(953, 'آرازش', '<span class=\"hlight\">آرازش .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِمص ) صَدَقه . انفاق در راه خدا.<br /></font></div>'),
(954, 'آراستن', '<span class=\"hlight\">آراستن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص ) (از پهلوی آرو، ایستادن، برخاستن، دور شدن ) زیب . زین . تقیین . تزیین . تجمیل . تحلیه . توشیح . تزویق . زبرجه . بزیب و زینت مزیّن کردن . تحسین کردن . متحلی کردن . آمودن . زیورکردن . آذین کردن . بگلگونه و غازه کردن <span class=\"hlight\">:</span> <br />شاه دیگر روز باغ آراست خوب <br />تختها بنهاد و برگسترد بوب .<br /> <font color=\"Red\">رودکی .</font><br />چو بشنید خاقان بیاراست گاه <br />بفرمود تا برگشادند راه .<br /> <font color=\"Red\">فردوسی .</font><br />بگویش که گردان ترا خواستند<br />سر تخت ایران بیاراستند.<br /> <font color=\"Red\">فردوسی .</font><br />رخ دختران را بیاراستند<br />سرزلف بر گل بپیراستند.<br /> <font color=\"Red\">فردوسی .</font><br />خرامان بیامد سیاوش برش <font color=\"DarkGreen\"><b>[ بر سودابه ]</font></b><br />بدید آن نشست و سر و افسرش <br />بیاراسته خویشتن چون بهار<br />بگِردَش هم از ماهرویان هزار.<br /> <font color=\"Red\">فردوسی .</font><br />چنین تا بیامد مه فرودین <br />بیاراست گلبرگ روی زمین .<br /> <font color=\"Red\">فردوسی .</font><br />چو آراید او تاج و تخت مهان <br />برآساید از رنج و محنت جهان .<br /> <font color=\"Red\">فردوسی .</font><br />عمر کرد اسلام را آشکار<br />بیاراست گیتی چو باغ بهار.<br /> <font color=\"Red\">فردوسی .</font><br />یکی کلبه ای ساخت اسفندیار<br />بیاراست همچون گل اندر بهار.<br /> <font color=\"Red\">فردوسی .</font><br />همه پشت پیلان به پیروزه بخت <br />بیاراست سالار بیداربخت .<br /> <font color=\"Red\">فردوسی .</font><br />بر او آفرین کرد و گفتا که بخت <br />بیاراید از تو سر تاج و تخت .<br /> <font color=\"Red\">فردوسی .</font><br />چو بر شاه عیب است بدخواستن <br />بباید بخوبی دل آراستن .<br /> <font color=\"Red\">فردوسی .</font><br />چو خورشید گیتی بیاراستی <br />خروشی ز درگاه برخاستی .<br /> <font color=\"Red\">فردوسی .</font><br />کنون تاج و اورنگ هرمزدشاه <br />بیارایم و برنشانم بگاه .<br /> <font color=\"Red\">فردوسی .</font><br />جهانی به آئین بیاراستند<br />چو خوشنودی نامور خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />گر عیب سر زلف بت از کاستن است <br />چه جای بغم نشستن و خاستن است <br />جای طرب و نشاط و می خواستن است <br />کآراستن سرو به پیراستن است .<br /> <font color=\"Red\">عنصری .</font><br />بدو داد فرخنده دخترْش را<br />بگوهر بیاراست اخترْش را.<br /> <font color=\"Red\">عنصری .</font><br />آنکه خوبی از او نمونه بود<br />چون بیارائیش چگونه بود؟<br /> <font color=\"Red\">عنصری .</font><br />روی گل سرخ بیاراستند<br />زلفک شمشاد بپیراستند.<br /> <font color=\"Red\">منوچهری .</font><br />شهر آذین بستند از در سرای ارتاش تا در بتان و همه بخود ومغفر و زره و جوشن و دیبا بیاراستند. (تاریخ سیستان ). ایزد عز ذکره سبکتکین را مسلمانی عطا داد و پس برکشید تا از آن اصل درخت ... شاخها پیدا آمد به بسیار درجه از اصل قویتر و بدان شاخها اسلام بیاراست . (تاریخ بیهقی ). و بمدد توفیق جمال حال ایشان بیاراست . (تاریخ بیهقی ). چون نیکوئی کند آن چیز را در چشم وی بیارایند، تا زیادت فرماید. (تاریخ بیهقی ).<br />گلستانی آرایم از نو سخن <br />که هرگزنگارَش نگردد کهن .<br /> <font color=\"Red\">اسدی .</font><br />چو حورا که آراست این پیرزن را<br />همان کس که آراست پیرار و پارش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عباسه خویشتن را بیاراست و به نزدیک جعفر شد. (تاریخ برامکه ).<br />بلؤلؤ ابر بیاراست روی صحرا را<br />مگر نشاط کند شهریار زی صحرا.<br /><font color=\"Red\">مسعودسعد.</font><br />تخت شاهان چگونه آرایند<br />گور تو همچنان بیارایم .<br /> <font color=\"Red\">مسعودسعد.</font><br />هنر از تیغ تیز پیدا شد<br />که بزر شاه قبضه اش آراست .<br /> <font color=\"Red\">مسعودسعد.</font><br />زیور آسمان چو بگشایند<br />کله های هوا بیارایند.<br /> <font color=\"Red\">مسعودسعد.</font><br />اگر ملک تماشاگاه خویش را بیاراید منت بر کسی نباید نهاد. (نوروزنامه ). و افعال و اقوال او را بتأییدآسمانی بیاراست . (کلیله و دمنه ). و برآنجمله که در احیاء سوابق معدلت امیر عادل ناصرالدین ... سعی نمود تا آن را بلواحق خویش بیاراست . (کلیله و دمنه ).<br />فر کیخسروی از اینجا خاست <br />که جهان را بعدل و علم آراست .<br /> <font color=\"Red\">اوحدی .</font><br />خوب چون روی خود بیاراید<br />از نماز و ورع چه کار آید؟<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> آهنگ کردن . قصد کردن <span class=\"hlight\">:</span> <br />چو سوگند شد خورده برخاستند<br />سوی خوابگه رفتن آراستند.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> زین کردن . یراق و برگ پوشانیدن اسب و پیل را. بزین و برگ و یراق کردن : یراق بستن . زین برنهادن . دهنه و افسار کردن <span class=\"hlight\">:</span> <br />سپهبدْش را گفت فردا پگاه <br />بیارای پیلان بیاور سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />درفشی بدو داد و گفتا بتاز<br />بیارای پیلان و لشکر بساز.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> تسویل . تمویه <span class=\"hlight\">:</span> <br />بیاراستی چون ببایست کار<br />نگشتی نهانش بشهر آشکار.<br /> <font color=\"Red\">فردوسی .</font><br />زمانه ٔ بد هر جا که فتنه ای باشد<br />چو نوعروسش در چشم من بیاراید.<br /> <font color=\"Red\">مسعودسعد (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٨٤</span>).</font><br />اهل دنیا راچو دیو آرایدش <br />لقمه های چرب و شیرین بایدش .<br /> <font color=\"Red\">عطار.</font><br /> <BR><font color=\"Blue\">◄</font> تمثیل . تصویر. تسویه . تشکیل . تمثل . تشکل . تصور <span class=\"hlight\">:</span> <br />جوانی برآراست از خویشتن <font color=\"DarkGreen\"><b>[ ابلیس ]</font></b><br />سخنگوی و بینادل و پاکتن ...<br />بدو <font color=\"DarkGreen\"><b>[ بضحاک ]</font></b> گفت اگر شاه را درخورم <br />یکی نامور مرد خوالیگرم ...<br />فراوان نبود آن زمان پرورش <br />که کمتر بداز کشتنیها خورش ...<br />پس آهرمن بدکنش رای کرد<br />بدل کشتن جانور جای کرد.<br /> <font color=\"Red\">فردوسی .</font><br />بیارای از آنسان که هستی رخت <br />بشمشیر باشد کنون پاسخت .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> تهیه کردن . مهیا کردن . آماده کردن . حاضر کردن . اِعداد <span class=\"hlight\">:</span> <br />بیاراستند از در جهن جای <br />خورش با پرستنده و رهنمای .<br /> <font color=\"Red\">فردوسی .</font><br />چو او بازگردد بیارای جنگ <br />منم ساخته رزم را چون پلنگ .<br /> <font color=\"Red\">فردوسی .</font><br />همی خورد یک هفته بر سوگ درد<br />پس آنگه برآراست کار نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />چو نامه بخوانی بیارای ساو<br />مرنجان تن خویش و با ما مکاو.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> راه انداختن <span class=\"hlight\">:</span> <br />چیست بنگر زآسیا مر آسیابان را، غله <br />گر نبایستیش غله آسیا ناراستی .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> چیدن (خوان را). نهادن . گستردن . راست کردن <span class=\"hlight\">:</span> <br />یکی خوان زرین بیاراستند<br />خورشها بخوردند و می خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />وز آن پس چو از تخت برخاستند<br />نهادند خوان و می آراستند.<br /> <font color=\"Red\">فردوسی .</font><br />بیارای خوان و بپیمای جام <br />ز تیمارگیتی مبر هیچ نام .<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود تا خوان بیاراستند<br />می و رود و رامشگران خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود پس کانجمن را بخوان <br />بایوان دیگر برآرای خوان .<br /> <font color=\"Red\">فردوسی .</font><br />پرستنده ای را بفرمود شاه <br />که در باغ گلشن بیارای گاه .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> در دل راه دادن <span class=\"hlight\">:</span> <br />در دل از شادی ساز دگر آراست همی <br />چون رهی نو زدی آن ماه، دگر کردی ساز.<br /> <font color=\"Red\">فرخی .</font><br />بحاجت ترا من از او خواستم <br />جز این آرزو را نیاراستم .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دل بکسی آراستن </span> ؛ دل بدو دادن <span class=\"hlight\">:</span> <br />تو پنداری دل بتو آراسته ایم <br />ما ای بت از آن سرای برخاسته ایم .<br /> <font color=\"Red\">فرخی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>).</font><br /> <BR><font color=\"Blue\">◄</font> هم آهنگ کردن <span class=\"hlight\">:</span> <br />برامشگری گفت امروز رود<br />بیارای با پهلوانی سرود.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن رود و مانندآن </span> ؛ کوک کردن آن . گوشمال دادن آن <span class=\"hlight\">:</span> <br />بیاورد جام دگر می گسار<br />چو از خوبرخ بستد آن شهریار<br />زننده دگرگون بیاراست رود<br />برآورد ناگاه دیگر سرود.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> غنی کردن . مستغنی کردن <span class=\"hlight\">:</span> <br />درم داد و دینار لشکرْش را<br />بیاراست گردان کشورْش را.<br /> <font color=\"Red\">فردوسی .</font><br />بیاراست دستان چنان دستگاه <br />شد از خواسته بی نیاز آن سپاه .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> کردن <span class=\"hlight\">:</span> <br />دگر آنکه گفتی که با شیده جنگ <br />برآراستی چون دلاور پلنگ <br />از آن بد کز ایران ندیدم سوار...<br /> <font color=\"Red\">فردوسی .</font><br />چو با رستم آیم بکین خواستن <br />بباید ترا نوحه آراستن .<br /> <font color=\"Red\">فردوسی .</font><br />بسی خواهش و پوزش آراستیم <br />همی زآن سخن داد او خواستیم .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> افکندن . گستردن . پهن کردن . انداختن بستر را <span class=\"hlight\">:</span> <br />بخوردند بی نان فراوان کباب <br />بیاراست هر مهتری جای خواب .<br /> <font color=\"Red\">فردوسی .</font><br />خورشها ز شهد و ز شیر و گلاب <br />بخوردی و آراستی جای خواب .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> گماشتن . مأمور کردن <span class=\"hlight\">:</span> <br />سپهدار توران برآراست جنگ <br />گرفتند کوپال و زوبین بچنگ ...<br />بیاراست بر میمنه گیو و طوس <br />سواران بیدار با بوق و کوس .<br /> <font color=\"Red\">فردوسی .</font><br />برآمد خروشیدن بوق و کوس <br />بیک دست خسرو سپهدار طوس <br />بیاراست با کاویانی درفش <br />همه پهلوانان زرینه کفش .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> آغازیدن . شروع کردن . گرفتن <span class=\"hlight\">:</span> <br />چو بنشست <font color=\"DarkGreen\"><b>[ زال ]</font></b> گودرز برپای خاست <br />بیاراست با شاه گفتار راست <font color=\"DarkGreen\"><b>[ با کیخسرو ]</font></b> .<br /> <font color=\"Red\">فردوسی .</font><br />بپاسخ برآراست جهن آن زمان <br />که ای دادگر شهریار جهان <br />بفرما تو تا من ببندم کمر<br />نهم پیش تخت تو بر خاک سر.<br /> <font color=\"Red\">فردوسی .</font><br />همه یکسر از جای برخاستند<br />بر او آفرینی نو آراستند.<br /> <font color=\"Red\">فردوسی .</font><br />ز کردار بد پوزش آراستن <br />منوچهر را نزدخود خواستن <br />میان بستن او را بسان رهی <br />سپردن بدو تاج و تخت مهی ...<br />فرستاده گفت و سپهبد <font color=\"DarkGreen\"><b>[ فریدون ]</font></b> شنید<br />مر آن گفت را پاسخ آمد پدید.<br /> <font color=\"Red\">فردوسی .</font><br />اَبا وی <font color=\"DarkGreen\"><b>[ با انوشیروان ]</font></b> بر آن گاه آرام و ناز<br /><font color=\"DarkGreen\"><b>[ در رؤیا ]</font></b> نشستی یکی تیزدندان گراز<br />نشستی و می خوردن آراستی <br />می از جام نوشیروان خواستی .<br /> <font color=\"Red\">فردوسی .</font><br />بشادی خروشیدن آراستند<br />کلاه کیانی بپیراستند.<br /> <font color=\"Red\">فردوسی .</font><br />زمانی بخفتند و برخاستند<br />یکی آفرین نو آراستند<br />بدان دادگر کو جهان آفرید<br />توانائی و ناتوان آفرید.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> به نگار کردن . منقش کردن <span class=\"hlight\">:</span> <br />فروریخت ازدیدگان آب مهر<br />بخون دو نرگس بیاراست چهر.<br /> <font color=\"Red\">فردوسی .</font><br />بدادندشان کوس و پیل و درفش <br />بیاراسته سرخ و زرد و بنفش .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> آباد کردن . معمور کردن <span class=\"hlight\">:</span> <br />زمین ایزد از مردم آراسته ست <br />جهان کردن ازبهر او خواسته ست <br />ز خاور بیاراست تا باختر<br />پدید آمد از فرّ او کان زر.<br /> <font color=\"Red\">فردوسی .</font><br />چنین بود آن شاه خسرونژاد<br />بیاراسته بد جهان را بداد.<br /> <font color=\"Red\">فردوسی .</font><br />بیاراست روی زمین را بداد<br />بپردخت زآن تاج بر سر نهاد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> برپا و منعقد کردن (بزم و جشن و مجلس و مانند آنرا) <span class=\"hlight\">:</span><br />سوی کاخ شد رستم پهلوان <br />یکی بزم آراست روشن روان .<br /> <font color=\"Red\">فردوسی .</font><br />بیاراست بزمی به آئین جم <br />همی شه ز شادی نکرد ایچ کم .<br /> <font color=\"Red\">فردوسی .</font><br />چو آگه شد از رستم و کار رزم <br />ز شادی بیاراست آنگاه بزم .<br /> <font color=\"Red\">فردوسی .</font><br />نشستند و بزم می آراستند<br />همه رود و رامشگران خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />بیاراست خرم یکی بزمگاه <br />بسر برنهاد آن کیانی کلاه .<br /> <font color=\"Red\">فردوسی .</font><br />بمان تا کسی دیگر آید برزم <br />تو با من بساز و بیارای بزم .<br /> <font color=\"Red\">فردوسی .</font><br />بباغ و بکاخ و بایوان اوی <font color=\"DarkGreen\"><b>[ کیکاوس ]</font></b><br />جهانی ز شادی نهادند روی <br />بهر جای جشنی بیاراستند<br />می و رود و رامشگران خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />یکی مجلس آراست با پیلتن <br />رد و موبد و خسرو پاکتن <br />فراوان سخن راند از افراسیاب <br />ز درد دل خویش وز رنج باب .<br /> <font color=\"Red\">فردوسی .</font><br />مجلس شراب جای دیگر آراسته بودند آنجای شدیم . (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> شاد کردن . مسرور کردن . خوش کردن <span class=\"hlight\">:</span> <br />چنان بد که در پارس یک روز تخت <br />نهادند زیر گل افشان درخت <br />بفرمود لهراسب تا مهتران <br />برفتند چندی ز لشکر سران <br />بخوان بر یکی جام می خواستند<br />دل شاه گیتی بیاراستند.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نامزد کردن چیزی یا کاری را برای کسی . معین و معلوم کردن ِ امری کسی را <span class=\"hlight\">:</span><br />سزاوار هر مهتری کشوری <br />بیارای و آغاز کن دفتری <br />بنام بزرگان وآزادگان ...<br /> <font color=\"Red\">فردوسی .</font><br />(نامه ٔارسطو به اسکندر)<br />اسیران و هرکس که بود از نوا<br />بیاراست مر هر یکی را سزا<br />یکی را نگهبان یکی را به بند<br />یکی پرامید و یکی با گزند.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> ساختن . درست کردن <span class=\"hlight\">:</span> <br />فریدون چو بشنید ناسود دیر<br />کمندی بیاراست از چرم شیر<br />ببندی ببستش دو دست و میان <br />که نگشاید آن بند شیر ژیان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> پوشانیدن جامه . پوشانیدن خلعت . ملبس کردن . بر تن راست کردن . بر تن کردن . پوشش دادن . لباس دادن . جامگی دادن <span class=\"hlight\">:</span> <br />سزاوار خلعت هر آن را که دید<br />بیاراست او را چنان چون سزید.<br /> <font color=\"Red\">فردوسی .</font><br />به نیکیت باید تن آراستن <br />که نیکی نشاید ز کس خواستن .<br /> <font color=\"Red\">فردوسی .</font><br />فرستاده را خلعت آراستند<br />پس اسب گرانمایگان خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />ببخش و بیارای و فردا مگوی <br />چه دانی که فردا چه آید بروی ؟<br /> <font color=\"Red\">فردوسی .</font><br />ور نیست بدیبا تنش آراسته شاید<br />چون جان خود آراست بدیبای خصالش .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> پوشیدن . ملبس شدن <span class=\"hlight\">:</span> <br />بفرمان بیاراست و آمد برون <br />پدر دل پراز درد و دیده ز خون .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">تاختن آراستن </span> ؛ تاختن آوردن <span class=\"hlight\">:</span> <br />برآراست بر هر سوئی تاختن . <font color=\"DarkGreen\"><b>[ افراسیاب ]</font></b><br />نبد هیچ هنگام پرداختن .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> پرکردن . انباشتن <span class=\"hlight\">:</span> <br />همه دل بکینه بیاراستند<br />بتاراج و کشتن بپیراستند.<br /> <font color=\"Red\">فردوسی .</font><br />ز هر چیز گنجی بد آراسته <br />جهانی سراسر پر از خواسته .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> صف بستن . صف کشیدن <span class=\"hlight\">:</span> <br />فروتر ز موبد مهان را بُدی <br />بزرگان و روزی دِهان را بُدی <br />بزیر مهان جای بازاریان <br />بیاراستندی، همه کاریان .<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به آراستن لشکر، و لشکر آراستن شود. <BR><font color=\"Blue\">◄</font> ازدیان . متحلی و مزین شدن . زینت و زیب گرفتن . تحلی <span class=\"hlight\">:</span> <br />مگرد ایچگونه بگرد بدی <br />به نیکی بیارای اگر بخردی .<br /> <font color=\"Red\">فردوسی .</font><br />بخوبی بیارای و بیشی ببخش <br />مکن روز را بر دل خویش بخش .<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ که شاهی و تخت <br />بیاراید و روز یابد ز بخت .<br /> <font color=\"Red\">فردوسی .</font><br />بدیبا بیاراست با رنگ و بوی <br />به نزدیک ارجاسب شد راه جوی .<br /> <font color=\"Red\">فردوسی .</font><br />فر و اوژنگ بتو گیرد دین <br />منبر ازخطبه ٔ تو آراید.<br /> <font color=\"Red\">دقیقی .</font><br /> <BR><font color=\"Blue\">◄</font> متخلق و متصف و موصوف کردن <span class=\"hlight\">:</span> <br />که گوید که کژّی به از راستی <br />چو دل را بکژّی بیاراستی ؟<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مرتب، منتظم، منتسق، بنظم، بنسق، بسامان کردن . نظم دادن . ترتیب دادن <span class=\"hlight\">:</span> <br />بایوان کشیدند ازآنجایگاه <br />سیاوش بیاراست آرامگاه .<br /> <font color=\"Red\">فردوسی .</font><br />جهان را بخوبی من آراستم <br />چنان گشت گیتی که من خواستم .<br /> <font color=\"Red\">فردوسی .</font><br />آن دیار تا روم از دیگر جانب تا مصر... بضبط ما آراسته گردد. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن دل </span> ؛ مستعد کردن آن . حاضر کردن آن . دل نهادن بر <span class=\"hlight\">:</span> <br />تو ای نامور زنگه ٔ شاوران <br />بیارای دل را برنج گران .<br /><font color=\"Red\">فردوسی .</font><br />برفتند با رامش و خواسته <br />همه دل بفرمانش آراسته .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> خوش کردن <span class=\"hlight\">:</span> <br />چنین گفت کو را بمن تازه کن <br />بیارای مغزش بشیرین سخن .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مسلح شدن <span class=\"hlight\">:</span> <br />ز پیش پدر چون بیاراستی <br />ز لشکر نبرد مرا خواستی .<br /> <font color=\"Red\">فردوسی .</font><br />که خسرو بسیجیدش آراستن <br />همی رفت خواهد بکین خواستن .<br /> <font color=\"Red\">فردوسی .</font><br />عید خوبان جهان آمد و خورشیدسپاه <br />جامه ٔ عید بپوشید و بیاراست پگاه .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> مصمم شدن . اراده کردن . مستعد شدن . معدّ شدن .حاضر گشتن <span class=\"hlight\">:</span> <br />نیاید ترا پوزش اکنون بکار<br />بپرداز جای و برآرای کار.<br /> <font color=\"Red\">فردوسی .</font><br />همی گفت کای مرد گم کرده راه <br />نه من خواستم رفته جانت ز شاه <br />چنین داد پاسخ که گر خواستی <br />چه کردم که بد کردن آراستی ؟<br /> <font color=\"Red\">فردوسی .</font><br />همه برتری را بیاراستی <br />چراگاه مازندران خواستی .<br /> <font color=\"Red\">فردوسی .</font><br />... که پیوند کس را نیاراستم <br />مگر کش به از خویشتن خواستم .<br /> <font color=\"Red\">فردوسی .</font><br />بجنگش بیاراست افراسیاب <br />بگردون همی خاک برزد بر آب .<br /> <font color=\"Red\">فردوسی .</font><br />بدرویش بخشید بسیار چیز<br />وز آنجایگه رفتن آراست نیز.<br /> <font color=\"Red\">فردوسی .</font><br />برآراست خراد برزین براه <br />بیامد بدانسان که فرمود شاه .<br /> <font color=\"Red\">فردوسی .</font><br />همه پاسخش را برآراستند<br />بتنگی دل، از جای برخاستند.<br /> <font color=\"Red\">فردوسی .</font><br />چو از شهربیرون شود شهریار<br />برفتن برآرای و برساز کار.<br /> <font color=\"Red\">فردوسی .</font><br />گر او جنگ را خواهد آراستن <br />هزیمت بود آشتی خواستن .<br /> <font color=\"Red\">فردوسی .</font><br />بخواری همی بردشان خواستند<br />بتاراج و کشتن بیاراستند.<br /> <font color=\"Red\">فردوسی .</font><br />کنونست هنگام کین خواستن <br />بباید بسیجید و آراستن .<br /> <font color=\"Red\">فردوسی .</font><br />به آواز گفتند ما کهتریم <br />ز رای و ز فرمان تو نگذریم <br />بر این برنهادند و برخاستند<br />همه جنگ چین را بیاراستند.<br /> <font color=\"Red\">فردوسی .</font><br />برادر سبک هردو برخاستند<br />تبه کردنش را بیاراستند.<br /> <font color=\"Red\">فردوسی .</font><br />بر این برنهادند و برخاستند<br />زبهر شبیخون بیاراستند.<br /> <font color=\"Red\">فردوسی .</font><br />گرانمایه شبگیر برخاستی <br />زبهر پرستش بیاراستی <br />سر و تن بشستی نهفته بباغ ...<br /> <font color=\"Red\">فردوسی .</font><br />بیاوردند هر چیزی که او خواست <br />نماز شام رفتن را بیاراست .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بپیوند یوسف من آراستم <br />من او را بمهر و وفا خواستم .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />گر دل توچنانکه من خواهم <br />مر چنین کار را بیاراید...<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> آبادان کردن . معمور کردن . در خصب و رفاه داشتن <span class=\"hlight\">:</span> و جهانیان را جمشید بزر و گوهر و دیبا و عطرها و چهارپایان بیاراست . (نوروزنامه ).<br />طلب عدل کن ز شاه و وزیر<br />گو مدان نحو و حکمت و تفسیر<br />نحوشان عمرو و زید را شاید<br />عدلشان عالمی بیاراید.<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> مفروش کردن . بساط گستردن <span class=\"hlight\">:</span> <br />یکی خانه او را بیاراستند<br />بدیبا و خوالیگران خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />بر آن جامه بر مجلس آراستند<br />نوازنده و رود و می خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />وز آن پس بفرمود کایوانها<br />ابا خانه و کاخ و کاشانها<br />بدیبای رومی بیاراستند<br />ز گنج مهی جامه ها خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت موبد که یک روز شاه <br />بدیبای رومی بیاراست گاه .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نوازش کردن <span class=\"hlight\">:</span> <br />به بهزاد بنمای زین و لگام <br />چو او رام گردد تو بردار گام <br />برو پیش او تیز و بنمای چهر<br />بیارای و میسای رویش بمهر.<br /> <font color=\"Red\">فردوسی .</font><br />چو کیخسرو آید بکین خواستن <br />عنانش ترا باید آراستن .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نوشتن . نگاشتن <span class=\"hlight\">:</span> <br />یکی دفتر آرایم از راستی <br />که نپْذیرد آن کژّی و کاستی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> ورزیدن <span class=\"hlight\">:</span> <br />بدو گفت شاه ای پسر شاد باش <br />همیشه خرد را تو بنیادباش <br />مدار ایچ اندیشه ٔ بد بدل <br />همی شادی آرای و غم برگسل .<br /> <font color=\"Red\">فردوسی .</font><br />کمی نیست در بخشش دادگر<br />همی شادی آرای و انده مخور.<br /> <font color=\"Red\">فردوسی .</font><br />از آن ده که بد منزل ما نخست <br />بپرس ای پسر تا بدانی درست ...<br />بدان تا بدانی که ما راستیم <br />بجز راستی را نیاراستیم .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> اندیشیدن . سگالیدن <span class=\"hlight\">:</span> <br />پس اندر نهان خون من خواستی <br />نبد سود هر چاره کآراستی .<br /> <font color=\"Red\">فردوسی .</font><br />بگنج و درم چاره آراستم <br />کنون آنچنان شد که من خواستم .<br /> <font color=\"Red\">فردوسی .</font><br />بر این گونه از جای برخاستند<br />همه شب همی چاره آراستند.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن با...</span> ؛ برابرکردن با. معادل کردن با <span class=\"hlight\">:</span> <br />بیاراست با میسره میمنه <br />سپاهی همه یکدل و یک تنه .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن جامه به تن </span> ؛ راست کردن آن بر تن . باندام برکردن آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن جنگ یا رزم </span> ؛ ترتیب، تنظیم، تنسیق و تعبیه ٔ آن <span class=\"hlight\">:</span> <br />چو بشنید آراست کهزاد رزم <br />هم آورد را رزم او بود بزم .<br /> <font color=\"Red\">فردوسی .</font><br />تو گفتی ز مستی کنون خاسته ست <br />که این جنگ را یکتن آراسته ست .<br /> <font color=\"Red\">فردوسی .</font><br />فراز آر لشکر بیارای جنگ <br />برزم آمدی چیست چندین درنگ ؟<br /> <font color=\"Red\">فردوسی .</font><br />سپهدار توران برآراست جنگ <br />گرفتند کوپال و زوبین بچنگ ...<br /> <font color=\"Red\">فردوسی .</font><br />و میمنه و میسره و قلب و جناح آن را بحقوق صحبت و ممالحت و سوابق دوستی و مخالصت بیاراسته . (کلیله و دمنه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن خلعت </span> ؛ دادن یا آماده و حاضر ساختن آن <span class=\"hlight\">:</span> <br />سزاوار او شهریار زمین <br />یکی خلعت آراست با آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />یکی خلعت آراست شاه جهان <br />کز او خیره ماندند یکسر مِهان .<br /> <font color=\"Red\">فردوسی .</font><br />یکی خلعت ازبهر مهران ستاد<br />بیاراست کآن کس ندارد بیاد.<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود تا خلعت آراستند<br />فرستاده را پیش او خواستند.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن خویشتن </span> ؛ تصنع. (دهّار).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن زبان به </span> ؛ تکلم کردن با آن . گفتن چیزی . متکلم و گویا کردن . گویا، گوینده کردن . رطب اللسان شدن به . ترطیب لسان به <span class=\"hlight\">:</span> <br />همه فرّ دارا همی خواستیم <br />زبان را به نام وی آراستیم .<br /> <font color=\"Red\">فردوسی .</font><br />بزرگ آن کسی کو بگفتار راست <br />زبان را بیاراست و کژّی نخواست .<br /> <font color=\"Red\">فردوسی .</font><br />بزرگان داننده برخاستند<br />بخوبی زبان را بیاراستند.<br /> <font color=\"Red\">فردوسی .</font><br />کنون ما یکایک تو را خواستیم <br />زبان را به پندت بیاراستیم .<br /> <font color=\"Red\">فردوسی .</font><br />همه پای مردان چو برخاستند<br />زبان را بنفرین بیاراستند.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن ِ زن ْ خود را</span> ؛ تشوف . جلوه کردن . آرایش کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن سخن و پاسخ و امثال آن </span> ؛ ادا کردن . گفتن . در میان نهادن . به ادب گفتن <span class=\"hlight\">:</span> <br />یلان پیش او پاسخ آراستند<br />بگفتار او دل بپیراستند.<br /> <font color=\"Red\">فردوسی .</font><br />جوانان ورا پاسخ آراستند<br />دل هوشمندی بپیراستند<br />که ما بندگانیم پیشت بپای <br />همیشه بنیکی ترا رهنمای .<br /> <font color=\"Red\">فردوسی .</font><br />سران یک بیک پاسخ آراستند<br />همه خوبی و آشتی خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />هرآنگه که باشی تو با رای زن <br />سخنها بیارای بی انجمن .<br /> <font color=\"Red\">فردوسی .</font><br />نگه کرد لهراسب برپای خاست <br />بخوبی بیاراست گفتار راست <br />به آواز گفت ای سران سپاه ...<br /> <font color=\"Red\">فردوسی .</font><br />چوناسفته گوهر سه دخترْش بود...<br />زبهر شما هر سه را خواستم <br />سخن های بایسته آراستم .<br /> <font color=\"Red\">فردوسی .</font><br />یا سخن آرای چو مردم بهوش <br />یا بنشین چون حیوانان خموش .<br /> <font color=\"Red\">سعدی .</font><br />سخن به پیش تو آراستن چنان باشد<br />که تحفه بر در سحبان برد سخن باقل .<br /> <font color=\"Red\">ابن یمین .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن سخن و جز آن </span> ؛ ترقیش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراستن لشکر</span> ؛ بصف کردن . تعبیه ٔ آن . مسلح کردن . بساز کردن . بصفوف کردن . صف راست کردن <span class=\"hlight\">:</span> <br />چو از هر دو سو لشکر آراستند<br />یلان کینه از یکدگر خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />بیاراسته لشکری چون بهار<br />برفتند نزدیک آن نامدار.<br /> <font color=\"Red\">فردوسی .</font><br />به پیمان بداند درم خواستن <br />چو جنگ اوفتد لشکر آراستن .<br /> <font color=\"Red\">فردوسی .</font><br />چپ و راست لشکر بیاراستند<br />دلیران همه رزم و کین خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />بگویم کنون رزم و کین خواستن <br />همان رستم و لشکرآراستن .<br /> <font color=\"Red\">فردوسی .</font><br />بیاراست رستم یکی رزمگاه <br />که از گرد اسبان زمین شد سیاه .<br /> <font color=\"Red\">فردوسی .</font><br />بدرد دل از جای برخاستند<br />چپ شاه ایران بیاراستند.<br /> <font color=\"Red\">فردوسی .</font><br />سپه را بیاراست و خود برنشست <br />یکی گرز پرخاش دیده بدست .<br /> <font color=\"Red\">فردوسی .</font><br />بسی برنیامد که طائفه ای از بزرگان گردن از طاعت او بپیچانیدند و ملوک از هر طرف منازعت خواستن گرفتند و بمقاومت لشکر آراستن . (گلستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">در چشم کسی آراستن چیزی را</span> ؛ تسویل . تمویه .<br /> <BR><font color=\"Blue\">◄</font> در بعض فرهنگها به معنی آرستن یعنی توانستن نیز ضبط کرده اند. مصدر دوم آن آرایش است : آراست . بیارای .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آراستن سرو به پیراستن است </span> .<br /> <font color=\"Red\">عنصری .</font><br /> <span class=\"hlight\">اگر راستی کارت آراستی </span> .<br /> <span class=\"hlight\">بر مشاطه عروس آراستن بود</span> .<br /><font color=\"Red\">(از قرةالعیون ).</font><br /></font></div>'),
(955, 'آراستنی', '<span class=\"hlight\">آراستنی .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص لیاقت ) از در آراستن . درخور آراستن . که آراستن آن ضروری است . که آراستن آن واجب است .<br /></font></div>'),
(956, 'آراسته', '<span class=\"hlight\">آراسته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف ) آموده . موده . پدرام . مزیّن . مجمل . مُحلی . حالی . حالیه . مُطرّز. مزخرف . بغازه و گلگونه کرده <span class=\"hlight\">:</span> <br />گر زآنکه به پیراسته ٔ شهر برآئی <br />پیراسته آراسته گردد ز رخانت .<br /> <font color=\"Red\">ابوشعیب .</font><br />و بهر پانزده روزی اندر وی <font color=\"DarkGreen\"><b>[ اندرپریم قصبه ٔ قارن ]</font></b> روز بازار باشد و از همه ٔ این ناحیت مردان و کنیزکان و غلامان آراسته ببازار آیند و با یکدیگر مزاج کنند. (حدودالعالم ).<br />شبستان همه پیش باز آمدند<br />بدیدار او <font color=\"DarkGreen\"><b>[ بزمساز ]</font></b> آمدند...<br />شبستان بهشتی بد آراسته <br />پر از خوبرویان و پر خواسته .<br /> <font color=\"Red\">فردوسی (شاهنامه چ دبیرسیاقی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٧</span>).</font><br />سپه را مر او بود ز ایران پناه <br />بدو گشت آراسته تختگاه .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گردد آراسته تاج و تخت <br />از آن رفته نام و بدین مانده بخت .<br /> <font color=\"Red\">فردوسی .</font><br />به آذین جهانی شدآراسته <br />در و بام و دیوار پرخواسته .<br /> <font color=\"Red\">فردوسی .</font><br />یکی پهن کشتی بسان عروس <br />بیاراسته همچو چشم خروس .<br /> <font color=\"Red\">فردوسی .</font><br />ز یاقوت سرخ است چرخ کبود...<br />بچندان فروغ و بچندان چراغ <br />بیاراسته چون بنوروز باغ .<br /> <font color=\"Red\">فردوسی .</font><br />چو دیدند زیبا رخ شاه را<br />بدانگونه آراسته گاه را<br />نهادند همواره سر بر زمین <br />بر او بر همی خواندند آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />زمین چون بهشتی شد آراسته <br />ز داد وز بخشش پر از خواسته .<br /> <font color=\"Red\">فردوسی .</font><br />بیاراسته همچو باغ بهار<br />سراسر پر از رنگ و بوی و نگار.<br /> <font color=\"Red\">فردوسی .</font><br />زر و گنج آن لشکر نامدار<br />بیاراسته چون گل اندر بهار.<br /> <font color=\"Red\">فردوسی .</font><br />بنام و کنیتت آراسته باد<br />ستایشگاه شعر و خطبه تا حشر.<br /> <font color=\"Red\">عنصری .</font><br />آراسته و مست ببازار آئی <br />ای دوست نترسی که گرفتار آئی ؟<br /> <font color=\"Red\">(از اسرارالتوحید).</font><br />جهان چون عروسی آراسته را مانست در آن روزگار مبارکش . (تاریخ بیهقی ). سرائی دیدم چون بهشت آراسته .(تاریخ بیهقی ). دو منشور نبشته آمد و بتوقیع آراسته گشت . (تاریخ بیهقی ). ناچار چون وی مقدم تر بود آن روز، در هر بابی سخن میگفت و ما آن را به استصواب آراسته می داشتیم . (تاریخ بیهقی ). گفتی جهان عروسی آراسته را ماند. (تاریخ بیهقی ).<br />هرکه زو شست ستمگر فلک آرایش <br />باغ آراسته او را بچه کار آید؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />این تیره و بی نور تن امروز بجانست <br />آراسته، چون باغ به نیسان و به آذار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />هر هفته باد جشنی و ایّام ملک از آن <br />آراسته چو بتکده ٔ قندهار باد.<br /> <font color=\"Red\">مسعودسعد.</font><br />و ایام عمر و روزگار دولت یکی از مقبلان بدان آراسته گردد. (کلیله و دمنه ). سپاس و حمد و ثنا و شکر مر آفریدگار را عزّ اسمه که خطه ٔ اسلام و واسطه ٔ عقد عالم را بجمال عدل و رأفت ... آراسته گردانیده است . (کلیله و دمنه ). و ظاهر و باطن من بعلم و عمل آراسته گردد. (کلیله و دمنه ). چون کاری آغاز کند <font color=\"DarkGreen\"><b>[ شیر ]</font></b>که بصواب نزدیک ... باشد آن را در چشم و دل او آراسته گردانم . (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> مهیا. آماده . حاضر. مستعد. ساخته . بسغده . بسیجیده <span class=\"hlight\">:</span> <br />نزد تو آماده بد وآراسته <br />جنگ او را خویشتن پیراسته .<br /> <font color=\"Red\">رودکی .</font><br />خود تو آماده بدی برخاسته <br />جنگ او را خویشتن آراسته .<br /> <font color=\"Red\">رودکی .</font><br />ترا این همه ایدر آراسته ست <br />اگر شهریاری و گر خواسته ست .<br /> <font color=\"Red\">فردوسی .</font><br />چون داد نوید رنج و دشواری <br />آراسته باش مر خرامش را.<br /><font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> فراهم . منتظم <span class=\"hlight\">:</span> باز سپاه آراسته کرد و عتیبةبن موسی را سالار کرد. (تاریخ سیستان ). <BR><font color=\"Blue\">◄</font> آبادان . معمور <span class=\"hlight\">:</span> <br />زمانه بمردم شد آراسته <br />وز او ارج گیرد همی خواسته .<br /> <font color=\"Red\">فردوسی .</font><br />خداوند این پادشاه را پیدا آورد... تا آن بقعه ... بدان پادشاه آراسته تر گردد. (تاریخ بیهقی ). اهل جمله ٔ آن ولایات گردن برافراشته اند تا نام ما بر آن نشیند و بضبط ما آراسته گردد. (تاریخ بیهقی ). احمدبن الحسن ... ببلخ آید... تا دولت ما به رای و تدبیر وی آراسته تر گردد. (تاریخ بیهقی ). و جهان آراسته و آبادان بدو <font color=\"DarkGreen\"><b>[ به آهَن ]</font></b> است . (نوروزنامه ). <BR><font color=\"Blue\">◄</font> باخصب . خرّم . پرگیاه <span class=\"hlight\">:</span> عین زربه، شهری است با میوه ها و کشتهای آراسته . (حدودالعالم ). به مرغزاری رسید <font color=\"DarkGreen\"><b>[ شتربه ]</font></b> آراسته . (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> مؤدّب . صاحب همه ٔ فضایل نیکو: جوانی آراسته . <BR><font color=\"Blue\">◄</font> تمام . کامل . تمام عیار. کامل عیار: مردی آراسته . <BR><font color=\"Blue\">◄</font> منقح . پیراسته . <BR><font color=\"Blue\">◄</font> غنی .مستغنی . توانگر. مرفّه . آبادان <span class=\"hlight\">:</span> <br />بتاراج داد آنهمه خواسته <br />شد از خواسته لشکر آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />بیابی تو چندان ز من خواسته <br />که گردد بر و بومت آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />در گنج بگشاد وز خواسته <br />سپه را همی کردش آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />همان باغبان را بسی خواسته <br />بداد وگُسی کردش آراسته .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نهاده . گسترده . چیده (خوان، سفره ) <span class=\"hlight\">:</span> <br />یکی میهمان خانه برخاسته ست <br />تو مهمان، جهان خوان ِ آراسته ست <br />بخور زود از او میهمان وار سیر<br />که مهمان نماند بیک جای دیر.<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> خوش . شادان . مسرور <span class=\"hlight\">:</span> <br />بپرسید دیگر که از خواسته <br />چه دانی که دارد دل آراسته <br />چنین داد پاسخ که مردم بچیز<br />گرامی است گر چیز خوار است نیز.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> پوشیده . ملبس . جامه برتن کرده <span class=\"hlight\">:</span> <br />چه مردم که گویا ندارد زبان <br />چه آراسته پیکری بی روان .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> دارای اخلاق ستوده <span class=\"hlight\">:</span> <br />زن خوب و خوشخوی و آراسته <br />چه ماند بنادان نوخاسته ؟<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> مسلح <span class=\"hlight\">:</span> <br />ز اسبان و مردان آراسته <br />زمین چون بهشتی پر از خواسته .<br /> <font color=\"Red\">فردوسی .</font><br />پس آراسته زال را پیش شاه <br />بزرّین عمود و بزرّین کلاه ...<br /> <font color=\"Red\">فردوسی .</font><br />شرط آن است که از زرّادخانه ... دوهزار غلام سوار آراسته با ساز و آلت تمام ... نزدیک ما فرستاده آید. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> انباشته . گردکرده . پرکرده . مملو <span class=\"hlight\">:</span> <br />نبشتند یک یک همه خواسته <br />که بود اندر آن گنج آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />بر این گونه آراسته گنجها<br />بگرد آمده بر بسی رنجها<br />سراسر سزای منوچهر دید <font color=\"DarkGreen\"><b>[ فریدون ]</font></b> ...<br /> <font color=\"Red\">فردوسی .</font><br />کلید در گنج آراسته <br />بگنجور او داد ناخواسته .<br /> <font color=\"Red\">فردوسی .</font><br />ز من رنج جان و ز تو خواسته <br />سپردن بمن گنج آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />بپرهیز از این گنج آراسته <br />از این مُردری تاج و این خواسته .<br /> <font color=\"Red\">فردوسی .</font><br />بایرانیان بخشم این خواسته <br />سلیح و زر و گنج آراسته .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> با اسباب و آلات . ببرگ . بساز <span class=\"hlight\">:</span> <br />ببخشید از آن رزمگه خواسته <font color=\"DarkGreen\"><b>[ اسفندیار ]</font></b><br />سوار و پیاده شد آراسته .<br /><font color=\"Red\">فردوسی .</font><br />ببخشید چندان ورا خواسته <br />که شد کاخ و ایوانش آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />ابا پیل و با گنج و با خواسته <br />بدرگاه شاه آمد آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />دو لشکر ببد هر دو آراسته <br />پر از کینه سر، گنج پرخواسته .<br /> <font color=\"Red\">فردوسی .</font><br />گر ایدون که زنهار خواهی ز من <br />سرت برگذارم از این انجمن <br />فراوان بیابی ز من خواسته <br />شود لشکرت یک سر آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />چون جنگی کردی سپاهی داشتی آراسته و ساخته . (نوروزنامه ). <BR><font color=\"Blue\">◄</font> بسامان . بنظم . بنسق <span class=\"hlight\">:</span> <br />به نزدیک او همچنان خواسته <br />ببر تا شود کار آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />ببخشید هر کس همی خواسته <br />همه کاراو گشت آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />این روز ابوالحسن دررسید با لشکری انبوه وآراسته . (تاریخ بیهقی ).<br />همه شادی آنراست کش خواسته است <br />کرا خواسته کارش آراسته است .<br /> <font color=\"Red\">اسدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آراسته به </span> ؛ حمایت، حراست، محافظت شده ٔ با. قوی . مؤیّد <span class=\"hlight\">:</span> <br />چو لشکر فراوان شد و خواسته <br />دل مرد بی بر شد آراسته .<br /> <font color=\"Red\">فردوسی .</font><br />هیچ شه را در جهان آن زهره نیست <br />کو سخن راند زایران بر زبان <br />مرغزار ما بشیر آراسته است <br />بد توان کوشید با شیر ژیان .<br /> <font color=\"Red\">فرخی .</font><br />یکی از سکرات ملک آن است که همیشه خاینان را بجمال رضا آراسته دارد. (کلیله و دمنه ). و کسب از جائی که همت بتوفیق آسمانی آراسته باشد آسان دست دهد. (کلیله و دمنه ).<br /> <BR><font color=\"Blue\">◄</font> زین و برگ کرده <span class=\"hlight\">:</span> <br />بفرمود تا هرچه بد خواسته <br />ز گنج و ز اسبان آراسته ...<br /> <font color=\"Red\">فردوسی (شاهنامه چ دبیرسیاقی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩١</span>).</font><br />پیل را پیش آورندآراسته . (تاریخ سیستان ). <BR><font color=\"Blue\">◄</font> (اِ) در بعض فرهنگها به معنی بتخانه و مقامی از موسیقی نیز آمده است . <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">پیری به هزار علت آراسته است </span> ؛ در پیری نسیان و ضعف بصر و سامعه و انواع بیماریها پدید آید.<br /> <span class=\"hlight\">که را خواسته کارش آراسته ست </span> .<br /> <font color=\"Red\">اسدی .</font><br />مال مایه ٔ آسایش و رفاه صاحب مال است .<br /> <span class=\"hlight\">گل بود به سبزه نیز آراسته شد</span> .<br /> <font color=\"Red\">عمعق بخاری .</font><br />نیکی نیکوتر شد. بدی به بدتری گرائید.<br /></font></div>'),
(957, 'آراسته سخن', '<span class=\"hlight\">آراسته سخن .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ س ُ خ َ ]</font></b> (ص مرکب ) خوش بیان <span class=\"hlight\">:</span> و در خواص <font color=\"DarkGreen\"><b>[ خواص زر ]</font></b> چنان آورده اند که کودک خرد را چون به دارودان زرش شیر دهند آراسته سخن آید و بر دل مردم شیرین آید. (نوروزنامه ).<br /></font></div>'),
(958, 'آراسته شدن', '<span class=\"hlight\">آراسته شدن .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ش ُ دَ ]</font></b> (مص مرکب ) تزیّن . (دهار). ازدیان . تقین . تزتت .<br /></font></div>'),
(959, 'آراسته کردن', '<span class=\"hlight\">آراسته کردن .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ک َ دَ ]</font></b> (مص مرکب ) تزیین . آراستن . تقیین . قبن . تمویه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خویشتن را آراسته کردن </span> ؛ تصنع.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(960, 'آراسته کننده', '<span class=\"hlight\">آراسته کننده .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ک ُ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) آراینده . مزیِّن . پیراینده .<br /></font></div>'),
(961, 'آراستک', '<span class=\"hlight\">آراستک .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ) پرستوک .<br /></font></div>'),
(962, 'آراستگی', '<span class=\"hlight\">آراستگی .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص ) چگونگی و حالت و صفت آراسته .<br /></font></div>'),
(963, 'آراض', '<span class=\"hlight\">آراض .</span> (ع اِ) ج ِ اَرض .<br /></font></div>'),
(964, 'آراقوا', '<span class=\"hlight\">آراقوا.</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (معرب، اِ) سیاهک . (برهان ). گندم سنگ . رجوع به اَراقوا شود.<br /></font></div>'),
(965, 'آراقیطون', '<span class=\"hlight\">آراقیطون .</span> (معرب، اِ) (از لاطینی آرکتولاپّا) باباآدم . اَراقیطون . اَرقیطون . (تحفه ).<br /></font></div>'),
(966, 'آرال', '<span class=\"hlight\">آرال .</span> (اِخ ) نام دریاچه ٔ بزرگ مشهور بدریای آرال به آسیا در ترکستان غربی بوسعت <span class=\"hlight\" dir=\"rtl\">٦٧</span> هزار کیلومترمربع. رود سیحون و جیحون بدان ریزد و این دریاچه بعلت خشکی هوای اطراف و ماسه و فُرش که رودها با خود بدان آرند رو بکاهش دارد.<br /></font></div>'),
(967, 'آرام', '<span class=\"hlight\">آرام .</span> (اِخ ) تخلص میرزاصادق نام یزدی از شعرای متأخر، در قرن سیزدهم هجری .<br /></font></div>'),
(968, 'آرام', '<span class=\"hlight\">آرام .</span> (اِ) سَکن . سکون . آرامش . ثبات . مقابل جُنبش . تَوَقف . درنگ . <BR><font color=\"Blue\">◄</font> آهستگی . مقابل شتاب <span class=\"hlight\">:</span> <br />من اینجا دیر ماندم خوار گشتم <br />عزیز از ماندن دائم شود خوار<br />چو آب اندر شمر بسیار ماند<br />زهومت گیرد از آرام بسیار.<br /> <font color=\"Red\">دقیقی .</font><br />از آرام و جنبش نبد پیش چیز<br />همان هر دو چیز آفریده است نیز.<br /> <font color=\"Red\">فردوسی .</font><br />چو آرام یابی برستی ز رنج .<br /> <font color=\"Red\">فردوسی .</font><br />نگه کن بدین گنبد تیز گرد...<br />نه از جنبش آرام گیرد همی <br />نه چون ما تباهی پذیرد همی .<br /> <font color=\"Red\">فردوسی .</font><br />بمرو اندر از بانگ چنگ و رباب <br />کسی را نبد هیچ آرام و خواب .<br /> <font color=\"Red\">فردوسی .</font><br />نخستین که آتش ز جنبش دمید<br />ز گرمیش پس خشکی آمد پدید<br />و از آن پس ز آرام سردی نمود<br />ز سردی همان بازتری فزود.<br /> <font color=\"Red\">فردوسی .</font><br />همه گفتنیها بدو بازگفت <br />همه رازها برگشاد از نهفت <br />چنین تا از آن بیشه و مرغزار<br />یکایک همی گفت با شهریار<br />وز آن رفتن گور و آن راه تنگ <br />از آرام بهرام و چندان درنگ .<br /> <font color=\"Red\">فردوسی .</font><br />از او کم وزو بیش آرام و جنبش <br />از او بر زمین زرّ و بر چرخ زیور.<br /> <font color=\"Red\">ناصرخسرو.</font><br />مکر تو صعب است که مردم ز تو<br />هست در آرام و تو خود در شتاب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گفتم چه چیز جنبش مبدای هر دوان <br />گفتا که هست آرام، انجام هر صُوَر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />نهایت حرکتها آرام است و غایت سفرها مقام . (مقامات حمیدی ). تا آئین زمین آرام است و تاطبیعت زمان و دور آسمان گردش ... (راحةالصدور).<br />رازیست در این جنبش و آرام ولیکن <br />ترسم که تو خود نیک در این راز نبینی .<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> آسایش . استراحت . راحت . هال . آسودگی . قرار.امان . صبر. شکیب <span class=\"hlight\">:</span> <br />گفتا مرا چه چاره که آرام هیچ نیست <br />گفتم که زود خیز و همی گرد چام چام .<br /> <font color=\"Red\">منجیک .</font><br />خور و خواب و آرامتان از من است <br />همان پوشش و کامتان از من است .<br /> <font color=\"Red\">فردوسی .</font><br />خور و خواب و آرام جوید <font color=\"DarkGreen\"><b>[ حیوان ]</font></b> همی <br />وز آن زندگی کام جوید همی .<br /> <font color=\"Red\">فردوسی .</font><br />شبی تیره هنگام آرام و خواب <br />کس آمد زنزدیک افراسیاب .<br /> <font color=\"Red\">فردوسی .</font><br />فرستاده آمد دلی پرشتاب <br />نبود آن شبش جای آرام و خواب .<br /> <font color=\"Red\">فردوسی .</font><br />چنین تا بدرگاه افراسیاب <br />برفت و نکرد ایچ آرام و خواب .<br /> <font color=\"Red\">فردوسی .</font><br />بپاسخ چنین گفت دستان سام <br />که ای سیرگشته ز آرام و جام .<br /> <font color=\"Red\">فردوسی .</font><br />ز بس ناله ٔ چنگ و نای و رباب <br />نبدبر زمین جای آرام و خواب .<br /> <font color=\"Red\">فردوسی .</font><br />وز آنسو چو آتش همی راند زال <br />نه خورد و نه خواب و نه آرام و هال .<br /> <font color=\"Red\">فردوسی .</font><br />چو یک بهره بگذشت از تیره شب <br />چنان چون کسی کو بلرزد ز تب <br />خروشی برآمد ز افراسیاب <br />بلرزید بر جای آرام و خواب .<br /> <font color=\"Red\">فردوسی .</font><br />از او دور شد خورد و آرام و خواب <br />ز مهر وی و خشم افراسیاب .<br /> <font color=\"Red\">فردوسی .</font><br />برآشفت چون آتش افراسیاب <br />به پیچید از جای آرام و خواب .<br /> <font color=\"Red\">فردوسی .</font><br />تو خفته به آرام در خان خویش <br />چه دیدی بگو تا چه آمدْت پیش .<br /> <font color=\"Red\">فردوسی .</font><br />ز گاه منوچهر تا کیقباد<br />ز کاووس تا شاه فرخ نژاد<br />به پیش بزرگان کمر بسته ایم <br />به آرام یک روز ننشسته ایم .<br /> <font color=\"Red\">فردوسی .</font><br />ز دینار گفتند وز کار پوست <br />ز کاری که آرام روم اندر اوست .<br /> <font color=\"Red\">فردوسی .</font><br />چو شستی بشمشیر روی زمین <br />به آرام بنشین و رامش گزین .<br /> <font color=\"Red\">فردوسی .</font><br />جهان را ز کردار بد شرم نیست <br />کسی را به نزدیکش آزرم نیست <br />همیشه بهر نیک و بد دسترس <br />ولیکن نجوید خود آرام کس .<br /><font color=\"Red\">فردوسی .</font><br />به بیژن بفرمود رستم که شو<br />تو با اشکش و با منیژه برو<br />که من امشب از کین افراسیاب <br />نه آرام گیرم نه خورد و نه خواب <br />یکی کار سازم کنون بر درش <br />که فردا بخندد بر او لشکرش .<br /> <font color=\"Red\">فردوسی .</font><br />بسوی سپنجاب رو همچو باد<br />ز آرام و شادی مکن هیچ یاد.<br /> <font color=\"Red\">فردوسی .</font><br />میاسای از کین افراسیاب <br />ز دل دور کن خورد و آرام و خواب .<br /> <font color=\"Red\">فردوسی .</font><br />بدید اندرآن هنگ افراسیاب <br />در او ساخته جای آرام و خواب .<br /> <font color=\"Red\">فردوسی .</font><br />سه فرزند را خواهم آرام و ناز<br />از آن پس که بردیم رنج دراز.<br /> <font color=\"Red\">فردوسی .</font><br />همه سر پر از گرد و دیده پرآب <br />کسی را نبد خورد و آرام و خواب .<br /> <font color=\"Red\">فردوسی .</font><br />برآمد از آرام و از خورد و خواب <br />همی بود با دیدگان پرآب .<br /> <font color=\"Red\">فردوسی .</font><br />بزن گیرد آرام مرد جوان <br />اگر تاجدار است اگر پهلوان .<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ که کردار اوی <br />به نزدیک ما رنج و پیکار اوی <br />که داند مگر کردگار سپهر<br />نماینده ٔ داد و آرام و مهر؟<br /> <font color=\"Red\">فردوسی .</font><br />بیهوده چه داری طمعدر این جای <br />آرام، که این نیست جای آرام .<br /> <font color=\"Red\">ناصرخسرو.</font><br />زمین جای آرام هر آدمیست <br />همان خانه ٔ کردگار از زمیست .<br /> <font color=\"Red\">اسدی .</font><br />و ضعفاء ملت و دولت را در سایه ٔ عدل و مایه ٔ رأفت او آرام داده . (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> طمأنینه ٔ دل . اطمینان خاطر. سکون نفس . فراغ بال . اطمینان قلب . آسودگی دل <span class=\"hlight\">:</span> <br />وز آن پس به آرام بنشست شاه <br />چو برخاست بهرام جنگی ز راه .<br /> <font color=\"Red\">فردوسی .</font><br />همان نیز پرویز چون کشته شد<br />بر ایرانیان کار برگشته شد<br />دلاور شد از کار او خوشنواز<br />به آرام بنشست بر تخت ناز.<br /> <font color=\"Red\">فردوسی .</font><br />مر مرا داد رای تو آرام <br />مر مرا کرد جود تو بنوا.<br /> <font color=\"Red\">مسعودسعد.</font><br />چو دشمن بدشمن شود مشتغل <br />تو با دوست بنشین به آرام دل .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> صلح . آشتی <span class=\"hlight\">:</span> <br />دگر گفت کز کردگار سپهر<br />کز اویست پرخاش و آرام و مهر.<br /> <font color=\"Red\">فردوسی .</font><br />نخست آفرین کرد بر دادگر<br />خداوند آرام و رای و هنر.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> سکوت . خاموشی <span class=\"hlight\">:</span> <br />خوشا نبید غارجی با دوستان یکدله <br />گیتی به آرام اندرو مجلس ببانگ و ولوله .<br />شاکر بخاری ؟ عرتامی ؟ (از فرهنگ اسدی، خطی، و چ پاول هورن ).<br />بدو گفت <font color=\"DarkGreen\"><b>[ به اسفندیار ]</font></b> رستم که آرام گیر<br />چه گوئی سخنهای نادلپذیر؟<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> اَمن . ایمنی . امنیت . امان . مقابل آشوب <span class=\"hlight\">:</span> <br />نبد خسروان را چنان کدخدای <br />به پرهیز و رادی بدین و به رای <br />که آرام این پادشاهی بدوست <br />که او بر سر نامداران نکوست .<br /> <font color=\"Red\">فردوسی .</font><br />کنون راهبر باش بهرام را<br />پرآشوب کن روز آرام را.<br /> <font color=\"Red\">فردوسی .</font><br />چنین تیر تیز آمد از بام دژ<br />که از بخت شاه است آرام دژ.<br /> <font color=\"Red\">فردوسی .</font><br />جز آرام و خوبی نجستم، بدین <br />که باشد پس از مرگ من آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />چون راست روَد دولت ایام نپاید<br />افتنده و خیزنده بود دولت ایّام <br />باید که بود مرد گهی شاد و گهی زار<br />نیکی ببدی درشده و کام به ناکام <br />زود از پی آرام پدید آید آشوب <br />زود از پی آشوب پدید آید آرام .<br /> <font color=\"Red\">قطران .</font><br /> <BR><font color=\"Blue\">◄</font> بستر. مرقد.خوابگاه <span class=\"hlight\">:</span> <br />نشستند <font color=\"DarkGreen\"><b>[ ایرانیان ]</font></b> با رامش و رود و می <br />یکی مست رود و یکی مست می <br />برفتند از آن پس به آرام خویش <br />گرفته ببر هر کسی کام خویش .<br /> <font color=\"Red\">فردوسی .</font><br />سحرگاهان بجستندی ز آرام <br />برامش دست بردندی سوی جام .<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> خلوت جای <span class=\"hlight\">:</span> <br />دوات و قلم خواست ناباک زن <br />به آرام بنشست با رای زن .<br /> <font color=\"Red\">فردوسی .</font><br />از این پس شب و روز گردنده دهر<br />نشست وببخشید بر چار بهر...<br />دگر بهره شادی و رامشگران <br />نشستن به آرام با مهتران .<br /> <font color=\"Red\">فردوسی .</font><br />نشسته به آرام در پیشگاه <br />چو سرو بلند از برش گرد ماه .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مقام . مقابل سفر <span class=\"hlight\">:</span> <br />بجرم خاک و فلک در نگاه باید کرد<br />که این کجاست ز آرام و آن کجا ز سفر.<br /> <font color=\"Red\">انوری .</font><br /> <BR><font color=\"Blue\">◄</font> سکینه . وِقار. طُمأنینه <span class=\"hlight\">:</span> <br />ور این آرام کاندر حلم تست اندر ترا بستی <br />حدیث زلزله کردن بچشم خلق خوابستی .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> قصر و کاخ پادشاهان ایران، مترادف سرای ترکان عثمانی . (از لاروس ). مقر. مستقر. کرسی . عاصمه . دربار <span class=\"hlight\">:</span> <br />برفتند یکسر سوی بارگاه <br />بدان جای شادی و آرام شاه .<br /> <font color=\"Red\">فردوسی .</font><br />چنان دان که یزدان ترا داد تاج <br />نشستی به آرام بر تخت عاج .<br /> <font color=\"Red\">فردوسی .</font><br />بمردی نشیند به آرام تو<br />ز تاج و کمر بسترد نام تو.<br /><font color=\"Red\">فردوسی .</font><br />نشیند به آرام بر تختگاه <br />همه بنده باشیم و او پادشاه .<br /> <font color=\"Red\">فردوسی .</font><br />سوم هفته در جایگاه مهی <br />نشست اندر آرام با فرهی .<br /> <font color=\"Red\">فردوسی .</font><br />سپهدار ترکان از آن روی چاچ <br />نشسته به آرام بر تخت عاج .<br /> <font color=\"Red\">فردوسی .</font><br />ترا با من اکنون چه کار است نیز<br />سپردم ترا تخت و آرام و چیز.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد همانگه به آرام خویش <br />پراکنده گرد جهان نام خویش .<br /> <font color=\"Red\">فردوسی .</font><br />نشیند به آرام بر تخت شاه <br />نباید فرستاد هر سو سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />سکندر ز گفتار او گشت شاد<br />به آرام شد تاج بر سر نهاد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> وطن . موطن . مولد. مسکن . محل سکون . خانه . جای . مأوی . مکان <span class=\"hlight\">:</span> <br />بدو گفت هوم این نه آرام تست <br />جهانی سراسر پر از نام تست .<br /> <font color=\"Red\">فردوسی .</font><br />دل موبد از درد پیغام اوی <br />غمی گشت و از جای وآرام اوی .<br /> <font color=\"Red\">فردوسی .</font><br />سه دیگر بپرسیدش از مام و باب <br />ازآرام و از شهر و از خورد و خواب .<br /> <font color=\"Red\">فردوسی .</font><br />چه باشد ز ایرانیان نام اوی <br />بگو تا کجا باشد آرام اوی ؟<br /> <font color=\"Red\">فردوسی .</font><br />بتوران زمین زادی از مادرت <br />هم آنجا بد آرام و آبشخورت .<br /> <font color=\"Red\">فردوسی .</font><br />بس است این فخر مر شاه جهان را<br />که آرام است چون تو دلستان را.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />نه هر آرام چون آرام پیشین <br />نه هر یاری است چون یار نخستین .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بیابانی که آرام بلا بود<br />ز ناخوشی چو کام اژدها بود.<br /> <font color=\"Red\">(ویس و رامین ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرام ساختن جائی </span> ؛ بوطن کردن آنجای . مسکن گرفتن در آن <span class=\"hlight\">:</span> روس بسیار بگردید و جائی نیافت که او را خوش آمدی، سوی خزر نامه ای نبشت و از کشور او گوشه ای بخواست که آنجا آرام سازد. (مجمل التواریخ ). و بربر و قبط هم از فرزندان وی بودند و بدین زمینها آرام ساختند که به نام ایشان بازخوانند. (مجمل التواریخ ).<br /> <BR><font color=\"Blue\">◄</font> قرارگاه . سرای باقی . دارالقرار <span class=\"hlight\">:</span> <br />همی بگذرد بر تو ایام تو<br />سرائی جز این <font color=\"DarkGreen\"><b>[ دنیا ]</font></b> باشد آرام تو.<br /> <font color=\"Red\">فردوسی .</font><br />بدانش بود نیک فرجام تو<br />بمینو دهد چرخ آرام تو.<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت این است فرجام ما<br />ندانم کجا باشد آرام ما.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به آرام </span> ؛ ساکن . ساکت . آسوده . مأمون . ایمن <span class=\"hlight\">:</span> <br />جهان بد به آرام زآن شادکام <font color=\"DarkGreen\"><b>[ از جمشید ]</font></b><br />ز یزدان بدو نو بنو بد پیام .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> زهدان . مشیمه <span class=\"hlight\">:</span><br />چنین گفت بانامداران شهر<br />هر آنکس که او از خرد داشت بهر<br />که از گفت دانا ستاره شمر<br />نباید که هرگز کند کس گذر<br />چنین گفته بد کید هندی که بخت <br />نگردد ترا شاد و خرّم نه تخت <br />مگر تخمه ٔ مهرک نوش زاد<br />بیامیزد آن تخمه با این نژاد<br />کنون سالیان اندرآمد به هشت <br />که جز به آرزو چرخ بر ما نگشت <br />چو رفت اورمزد اندر آرام خویش <br />ز گیتی ندیدم جز از نام خویش <br />زمین هفت کشور مرا گشت راست <br />دلم یافت از بخت چیزی که خواست .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مجازاً، آشیان . وَکر. وکنه . لانه <span class=\"hlight\">:</span> <br />وز آنجا بیامد سوی مرز سغد<br />یکی نوجهان دید آرام جغد.<br /> <font color=\"Red\">فردوسی .</font><br />همی عقاب و گوزن از نهیب تیر و کمانْت <br />بکوه و بیشه در، آرام و مستقر دارد.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> کنام <span class=\"hlight\">:</span> <br />آن قصر که جمشید در او جام گرفت <br />آهو بچه کردو شیر آرام گرفت .<br /> <font color=\"Red\">خیام .</font><br /> <BR><font color=\"Blue\">◄</font> گور. قبر. مَدفَن . دَخمه . <BR><font color=\"Blue\">◄</font> عشرت و صحبت با زنان <span class=\"hlight\">:</span> <br />چو سالت شد ای پیر بر شست ویک <br />می و جام و آرام شد بی نمک .<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به آرامیدن با... شود. <BR><font color=\"Blue\">◄</font> پروا. (فرهنگ اسدی ). <BR><font color=\"Blue\">◄</font> بمعنی آرام بَن نیز آمده است . <BR><font color=\"Blue\">◄</font> (ص ) دِنج . بی هیاهو. <BR><font color=\"Blue\">◄</font> آرمیده . آرمنده . اَرمنده . مستریح . صاحب آرامش . ساکن . ساکت . خاموش . بی اضطراب . مطمئن . مُتسلی . بی قَلَق . بی طوفان . که سرکش و توسن نباشد. ذلول .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اسبی آرام </span> ؛ مقابل توسن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بچه ای آرام </span> ؛ مقابل شوخ .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خاطری آرام </span> ؛ مقابل مضطرب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دریائی آرام </span> ؛ مقابل شوریده .<br /> <BR><font color=\"Blue\">◄</font> آهسته . نرم . <BR><font color=\"Blue\">◄</font> افتاده (آدمی ). سربپائین . <BR><font color=\"Blue\">◄</font> (صوت ) مَهْلاً! مَهْلاًمَهْلا! آهسته ! بی شتاب ! <BR><font color=\"Blue\">◄</font> شوخی مکن ! <BR><font color=\"Blue\">◄</font> (نف مرخم ) در کلمه ٔ مرکبه ٔ دِل آرام و نظایر آن مخفف آراماننده است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">هر کس که زن ندارد آرام تن ندارد</span> .<br /><span class=\"hlight\">یا شب گریه کن روز آرام بگیر یا روز گریه کن شب آرام بگیر</span> .<br /></font></div>'),
(969, 'آرام', '<span class=\"hlight\">آرام .</span> (اِخ ) بروایت تورات، نام پنجمین فرزند سام بن نوح . <BR><font color=\"Blue\">◄</font> نام سوریه و شام و بین النهرین مسکن آرامیان فرزندان آرام بن سام بن نوح .<br /></font></div>'),
(970, 'آرام', '<span class=\"hlight\">آرام .</span> (ع اِ) ج ِ رئم . آهوان سپید <span class=\"hlight\">:</span> <br />دیده از کبک در ایام تو شاهین شاهین <br />کرده با شیر بدوران تو آرام آرام .<br /> <font color=\"Red\">سلمان ساوجی .</font><br /><BR><font color=\"Blue\">◄</font> ج ِ اِرَم . نشانهای راه از سنگها در بیابان یا نشانه های قبیله ٔ عاد.<br /></font></div>'),
(971, 'آرام', '<span class=\"hlight\">آرام .</span> (اِخ ) نام کوهی یا آن کوه که میان مکه و مدینه است . <BR><font color=\"Blue\">◄</font> نام پدر عاد نخستین یا نام پدر عاد پسین یا نام شهر و یا نام مادر ایشان و یا نام قبیله ٔ ایشان . <BR><font color=\"Blue\">◄</font> نام آبی بدیار جذام در اطراف شام .<br /></font></div>'),
(972, 'آرام بخشیدن', '<span class=\"hlight\">آرام بخشیدن .</span> <font color=\"DarkGreen\"><b>[ ب َ دَ ]</font></b> (مص مرکب ) آرام دادن . تسکین درد. بردن اضطراب . فرونشاندن خشم .<br /></font></div>'),
(973, 'آرام بودن', '<span class=\"hlight\">آرام بودن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص مرکب ) استراحت <span class=\"hlight\">:</span> <br />چنان دان که هر کس جهان را شناخت <br />در او جای آرام بودن نساخت .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(974, 'آرام جان', '<span class=\"hlight\">آرام جان .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مایه ٔ سکون دل . معشوقه . معشوق <span class=\"hlight\">:</span> <br />بر این برز و بالا و این خوب چهر<br />تو گوئی که آرام جانست و مهر.<br /> <font color=\"Red\">فردوسی .</font><br />ای ساربان آهسته رو کآرام جانم می رود<br />وآن دل که با خود داشتم با دلستانم می رود.<br /> <font color=\"Red\">سعدی .</font><br />از من جدا مشو که توام نور دیده ای <br />آرام جان و مونس قلب رمیده ای .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(975, 'آرام خاطر', '<span class=\"hlight\">آرام خاطر.</span> <font color=\"DarkGreen\"><b>[م ِ طِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مایه ٔ سکون خاطر.<br /></font></div>'),
(976, 'آرام دادن', '<span class=\"hlight\">آرام دادن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص مرکب ) تقریر. (مجمل اللغه ). <BR><font color=\"Blue\">◄</font> تسکین . <BR><font color=\"Blue\">◄</font> تأمین . رَفْو. دل دادن <span class=\"hlight\">:</span> <br />خورش ساز و آرامشان ده بخورد<br />نشاید جز این چاره ای نیز کرد.<br /> <font color=\"Red\">فردوسی .</font><br />و باز بسیستان آمد...پس از آنکه آن ناحیت را آرام داد. (تاریخ سیستان ). <BR><font color=\"Blue\">◄</font> اطمینان دادن . قرار دادن <span class=\"hlight\">:</span> <br />بدینسان پیامش ز بهرام ده <br />دلش را به برگشتن آرام ده .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(977, 'آرام دل', '<span class=\"hlight\">آرام دل .</span> <font color=\"DarkGreen\"><b>[ م ِ دِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مایه ٔتسلی خاطر. مایه ٔ امید. معشوق . معشوقه <span class=\"hlight\">:</span> <br />یکی تخته ٔ جامه هم نابرید<br />دو آرام دل کودک نارسید<br />روان را همی لعلشان نوش داد<br />بیاورد و یکسر بشیدوش داد.<br /> <font color=\"Red\">فردوسی .</font><br />هرچند کآن آرام دل دانم نبخشد کام دل <br />نقش خیالی میکشم فال دوامی میزنم .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(978, 'آرام رفتن', '<span class=\"hlight\">آرام رفتن .</span> <font color=\"DarkGreen\"><b>[ رَ ت َ ]</font></b>(مص مرکب ) بتأنی، به آهستگی، بنرمی رفتن . رَهْو.<br /></font></div>'),
(979, 'آرام روح', '<span class=\"hlight\">آرام روح .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آرام دل . آرام جان . آرام خاطر.<br /></font></div>'),
(980, 'آرام شدن', '<span class=\"hlight\">آرام شدن .</span> <font color=\"DarkGreen\"><b>[ ش ُ دَ ]</font></b> (مص مرکب ) آرامیدن . بیارامیدن . آرام گرفتن . فرونشستن اضطراب . فرونشستن خشم . تسلی یافتن . بازایستادن باد و طوفان و انقلاب . مقابل بشوریدن (هوا، دریا). بازایستادن از گریه . بشدن دَرد از عضوی چون دندان و جز آن . ساکن شدن وَجع.<br /></font></div>'),
(981, 'آرام کردن', '<span class=\"hlight\">آرام کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) آرامانیدن . آرمش دادن . آرامش دادن . آرام بخشیدن . تسکین .<br /></font></div>'),
(982, 'آرام گرفتن', '<span class=\"hlight\">آرام گرفتن .</span> <font color=\"DarkGreen\"><b>[ گ ِ رِ ت َ ]</font></b> (مص مرکب ) استراحت کردن . آسودن <span class=\"hlight\">:</span> <br />به طینوس گفت ایدر آرام گیر<br />چو آسوده گردی بکف جام گیر.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> استقرار. ساکن شدن . تسکین یافتن . از جنبش بازایستادن . اقراد. مستریح گشتن . اقترار. اقرار. آرامش یافتن . قرار گرفتن <span class=\"hlight\">:</span> <br />نگه کن بر این گنبد تیزگرد...<br />نه از جنبش آرام گیرد همی <br />نه چون ما تباهی پذیرد همی .<br /> <font color=\"Red\">فردوسی .</font><br />چو بیدار باشی تو خواب آیدم <br />چو آرام باشی شتاب آیدم .<br /> <font color=\"Red\">فردوسی .</font><br />بی وصل تو دل در برم آرام نگیرد<br />بی صبحت تو کار من اندام نگیرد.<br /> <font color=\"Red\">معزی .</font><br />و لرزه بر اندامش افتاد چندانکه ملاطفت کردند آرام نمی گرفت .(گلستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرام گرفتن با</span> ؛ آسودن با. خوی کردن با. مأنوس گشتن با <span class=\"hlight\">:</span> <br />گر آهوئی بیا که کنار منت حرم <br />آرام گیر با من و از من چنین مَشَم .<br /> <font color=\"Red\">خفاف .</font><br /> <BR><font color=\"Blue\">◄</font> نشستن . جای گرفتن <span class=\"hlight\">:</span> <br />پس او را بفرمود شاه جهان <font color=\"DarkGreen\"><b>[ ضحاک ]</font></b><br />که آرام گیرد <font color=\"DarkGreen\"><b>[ کاوه ]</font></b> بَرِ آن مِهان .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرام گرفتن بچه </span> ؛ از گریستن بازایستادن او. پس از بازی و شرارت و شیطنت و شوخی ساکت و ساکن شدن او.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرام گرفتن درد</span> ؛ بریدن و قطع شدن آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرام گرفتن دریا</span> ؛ ساکن شدن امواج آن . فرونشستن انقلاب آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرام گرفتن هوا</span> ؛ از رعد و طوفان ایستادن آن .<br /></font></div>'),
(983, 'آرام یافتن', '<span class=\"hlight\">آرام یافتن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص مرکب ) استراحت کردن . برآسودن . مستریح شدن <span class=\"hlight\">:</span> <br />وز آن پس بکین سیامک شتافت <font color=\"DarkGreen\"><b>[ کیومرث ]</font></b><br />شب و روز آرام و خفتن نیافت .<br /> <font color=\"Red\">فردوسی .</font><br />سپهدار بشنید و آرام یافت <br />خوش آمدْش از آن مهتران کام یافت .<br /> <font color=\"Red\">فردوسی .</font><br />یکی بی هنر بود نامش گراز<br />کزو یافتی شاه <font color=\"DarkGreen\"><b>[ خسروپرویز ]</font></b> آرام و ناز<br />که بودی همیشه نگهبان روم <br />یکی دیوسر بود و بیداد و شوم .<br /> <font color=\"Red\">فردوسی .</font><br />شوریده ای که در آن سفر همراه ما بودنعره ای برآورد و راه بیابان گرفت و یک نفس آرام نیافت . (گلستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرام یافتن بچیزی </span> ؛ بدو تسلی گرفتن .<br /></font></div>'),
(984, 'آرامانیدن', '<span class=\"hlight\">آرامانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) اِسکان . (زوزنی ). اِهداء. اضجاع . اهجاع . <BR><font color=\"Blue\">◄</font> مطمئن کردن . (زمخشری ). <BR><font color=\"Blue\">◄</font> آرام کردن . آرام دادن .<br /></font></div>'),
(985, 'آرامجوی', '<span class=\"hlight\">آرامجوی .</span> (نف مرکب ) مصلح . صلاح اندیش . صلح طلب . آشتی خواه <span class=\"hlight\">:</span> <br />یکی پهلوان داشتی نامجوی <br />خردمند و بیدار و آرامجوی .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(986, 'آرامدن', '<span class=\"hlight\">آرامدن .</span> <font color=\"DarkGreen\"><b>[ م ِ دَ ]</font></b> (مص ) آرَمِدَن . آرمیدن .<br /></font></div>'),
(987, 'آرامش', '<span class=\"hlight\">آرامش .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِمص ) اسم مصدر از آرامیدن . سکون . آرمِش <span class=\"hlight\">:</span> <br />رایتش ساکن نگردد یک زمان در یک زمین <br />رخشش آرامش نگیرد ساعتی در یک مقام .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> طمأنینه . (ربنجنی ). اَون . سکینه . (ربنجنی ) (دستوراللغه ) <span class=\"hlight\">:</span> <br />دلم را بد آرامشی زآن خبر<br />روانم ز شادی برآمد بسر.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />و بنی اسرائیل را بدان <font color=\"DarkGreen\"><b>[ بتابوت سکینه ]</font></b> آرامش بود. (مجمل التواریخ ). <BR><font color=\"Blue\">◄</font> غفوه . خواب اندک و سبک . سبت . <BR><font color=\"Blue\">◄</font> رامش . آسایش . استراحت <span class=\"hlight\">:</span> <br />منجم بیاورد صلاب را<br />بینداخت آرامش و خواب را.<br /> <font color=\"Red\">فردوسی .</font><br />بر این کینه آرامش و خواب نیست <br />بمانند چشمم بجوی آب نیست .<br /> <font color=\"Red\">فردوسی .</font><br />ز شب نیمه ای گفت سهراب بود<br />دگر نیمه آرامش و خواب بود.<br /> <font color=\"Red\">فردوسی .</font><br />بگسترد آن هر دو در آفتاب <br />بخواب و به آرامش آمد شتاب .<br /> <font color=\"Red\">فردوسی .</font><br />زمین سبز و جوئی پر از آب دید<br />همه جای آرامش و خواب دید.<br /> <font color=\"Red\">فردوسی .</font><br />ایستادن ملکان را بدر خانه ٔ او<br />به ز آرامش و آسایش بر تخت بزر.<br /> <font color=\"Red\">فرخی .</font><br />همه شب گرد چشم من نگردد<br />ز خیل خواب و آرامش خیالی .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> آشتی . سلم <span class=\"hlight\">:</span> <br />نخست آفرین کرد بر کردگار<br />خداوند آرامش و کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />در تهور کسی فلاح ندید<br />روی آرامش و صلاح ندید.<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> مأمونی . ایمنی . امنیت <span class=\"hlight\">:</span> و آرامش اطراف ... بسیاست منوط است . (کلیله ودمنه ). <BR><font color=\"Blue\">◄</font> وقفه . <BR><font color=\"Blue\">◄</font> فراغ .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامش با جفت </span> ؛ رفث . مباضعه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامش دادن </span> ؛ مستریح کردن . مأمون ساختن . آرام و آرمش دادن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامش یافتن </span> ؛مستریح شدن . مطمئن شدن . آرمش یافتن . آرام یافتن . آسایش یافتن . و رجوع به آرام و آرام کردن و آرامی شود.<br /></font></div>'),
(988, 'آرامش جو', '<span class=\"hlight\">آرامش جو.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (نف مرکب ) آرامش جوی . آنکه طالب آرامش است . آرامش خواه . آرامش طلب .<br /></font></div>'),
(989, 'آرامش خواه', '<span class=\"hlight\">آرامش خواه .</span> <font color=\"DarkGreen\"><b>[ م ِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) آرامش جوی .<br /></font></div>'),
(990, 'آرامش دادن', '<span class=\"hlight\">آرامش دادن .</span> <font color=\"DarkGreen\"><b>[ م ِ دَ ]</font></b> (مص مرکب ) آرام کردن .<br /></font></div>'),
(991, 'آرامش یافتن', '<span class=\"hlight\">آرامش یافتن .</span> <font color=\"DarkGreen\"><b>[ م ِ ت َ ]</font></b> (مص مرکب ) آرام شدن . آرام گرفتن .<br /></font></div>'),
(992, 'آرامشاه', '<span class=\"hlight\">آرامشاه .</span> (اِخ ) نام پادشاهی مغولی در دهلی (<span class=\"hlight\" dir=\"rtl\">٦٠٧</span> - <span class=\"hlight\" dir=\"rtl\">٦٠٨</span> هَ . ق .).<br /></font></div>'),
(993, 'آرامنده', '<span class=\"hlight\">آرامنده .</span> <font color=\"DarkGreen\"><b>[ م َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) مطمئن .<br /></font></div>'),
(994, 'آرامگاه', '<span class=\"hlight\">آرامگاه .</span> (اِ مرکب ) وَطن . (محمودبن عمر ربنجنی ). موطن . مسکن . جای . جایگاه <span class=\"hlight\">:</span> <br />مگر کو بماند به نزدیک شاه <br />کند کشور و بومت آرامگاه .<br /> <font color=\"Red\">فردوسی .</font><br />که ما را دل از بوم و آرامگاه <br />چگونه بود شاد بی روی شاه ؟<br /> <font color=\"Red\">فردوسی .</font><br />بسازم بر این بوم آرامگاه <br />بمهر و وفای تو ای نیکخواه .<br /> <font color=\"Red\">فردوسی .</font><br />همه کوهشان بود آرامگاه <br />چنین بود آئین هوشنگ شاه .<br /> <font color=\"Red\">فردوسی .</font><br />ترا گنگ دژ باشد آرامگاه <br />نبیند مرا نیز شهر و سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />پسران موردبن سام واﷲ اعلم هم بر این شکل زمین مکران و کرمان به نام ایشان خوانند و آرام گاه بدین کشورها ساختند. (مجمل التواریخ ).<br /> <BR><font color=\"Blue\">◄</font> مقر. مستقر <span class=\"hlight\">:</span> <br />که ایدر ترا باشد آرامگاه <br />هم ایدر سپاه و هم ایدر کلاه .<br /> <font color=\"Red\">فردوسی .</font><br />خود آگاه نی خسرو از این گزند<br />نشسته به آرامگاه ارجمند.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> محل آسایش . جای آمن . مأمن . آرامگه <span class=\"hlight\">:</span> <br />زمینی زراغن بسختی چو سنگ <br />نه آرامگاه و نه آب و گیاه .<br /> <font color=\"Red\">بهرامی .</font><br />ترا تا نسازم سلیح و سپاه <br />نجویم خور و خواب و آرامگاه .<br /> <font color=\"Red\">فردوسی .</font><br />همی راند یک ماه خود با سپاه <br />ندیدند از ایشان کس آرامگاه .<br /> <font color=\"Red\">فردوسی .</font><br />کنی خانه تا زنده ای سال و ماه <br />وز آن پس کیت باشد آرامگاه ؟<br /> <font color=\"Red\">اسدی .</font><br />گر از فتنه آید کسی در پناه <br />ندارد جز این کشور آرامگاه .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> خانه . منزل . خفتنگاه <span class=\"hlight\">:</span> <br />چنین تا شب تیره سر برکشید...<br />چو رفتند هر کس به آرامگاه <br />پراندیشگان جان شاه و سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />فراز آوریدند بیمر سپاه <br />ز شادی بریدند و آرامگاه .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> آبادی . آبادانی <span class=\"hlight\">:</span><br />بپرسید از آن سر شبان، راه شاه <br />کز ایدر کجا یابم آرامگاه <br />چنین داد پاسخ که آبادجای <br />نیابی مگر باشدت رهنمای <br />ازیدر کنون چار فرسنگ راه <br />چو رفتی پدید آید آرامگاه <br />وز آن سوی پیوسته شد ده بده <br />بهر دِه یکی نامبردار مِه .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مِهاد. (مجمل اللغه ). مهد. دارالقرار. <BR><font color=\"Blue\">◄</font> سکن . (ربنجنی ). آرامگه . قرار. قرارگاه . محل آرامش <span class=\"hlight\">:</span> <br />...که چون رفت و آرامگاهش کجاست <br />نهان گشت از ایدر پناهش کجاست ؟<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> قبر. گور. مرقد. مدفن . دَخمه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامگاه شیر</span> ؛ عرین . کنام .<br /></font></div>'),
(995, 'آرامگه', '<span class=\"hlight\">آرامگه .</span> <font color=\"DarkGreen\"><b>[ گ َه ْ ]</font></b> (اِ مرکب ) مخفف آرامگاه . جای آسایش . مهد. مهاد <span class=\"hlight\">:</span> <br />نهاده برآن دژ دری آهنین <br />هم آرامگه گشت و هم جای کین .<br /> <font color=\"Red\">فردوسی .</font><br />ای نسیم سحر آرامگه یار کجاست <br />منزل آن مه عاشق کش عیار کجاست ؟<br /> <font color=\"Red\">حافظ.</font><br />جان بشکرانه کنم صرف گر آن دانه ٔ دُر<br />صدف دیده ٔ حافظ بود آرامگهش .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> مقر. مستقر. وطن . موطن <span class=\"hlight\">:</span> <br />بسازند و آرایش ره کنند<br />وز آرامگه دست کوته کنند.<br /> <font color=\"Red\">فردوسی .</font><br />این همان چشمه ٔ خورشید جهان افروز است <br />که همی تافت بر آرامگه عاد و ثمود.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> کنام <span class=\"hlight\">:</span> <br />رنگ آن روز غمی گردد و بیرنگ شود<br />که بر آرامگه شیر بگرد آید رنگ .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> لانه . آشیانه <span class=\"hlight\">:</span> <br />معدن زاغ شد آرامگه کبک و تذرو<br />مسکن شیر شد آوردگه گور و غزال .<br /><font color=\"Red\">فرخی .</font><br /></font></div>'),
(996, 'آرامی', '<span class=\"hlight\">آرامی .</span> (حامص ) آرام . سکون . سکنه . قرار. راحت . استراحت . آسایش . سکونت . <BR><font color=\"Blue\">◄</font> آهستگی . رفق . تأنی . مدارات . <BR><font color=\"Blue\">◄</font> هَون . (صراح ).<br /></font></div>'),
(997, 'آرامی', '<span class=\"hlight\">آرامی .</span> (ص نسبی ) منسوب به آرام، فرزند پنجم سام .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">زبان آرامی </span> ؛ لهجه ای از زبان سامیان بدوی مشرق فرات .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">قوم آرامی </span> ؛ آرامیان .<br /></font></div>'),
(998, 'آرامیان', '<span class=\"hlight\">آرامیان .</span> (اِخ ) شعبه ای از نژاد سامی، فرزندان آرام، پنجمین پسر سام، ساکن سوریه و بین النهرین .<br /></font></div>'),
(999, 'آرامیدن', '<span class=\"hlight\">آرامیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آرمیدن . استراحت کردن . آسودن . ساکن شدن . (زمخشری ). آسایش یافتن . سکون . استقرار. اسکان . (زوزنی ). بیارامیدن . قرار گرفتن <span class=\"hlight\">:</span> <br />نیارامد از بانگ هنگام جنگ <font color=\"DarkGreen\"><b>[ رستم ]</font></b><br />همی آتش افروزد از خاک و سنگ .<br /> <font color=\"Red\">فردوسی .</font><br />شاهی است به کشمیر اگر ایزد خواهد<br />امسال نیارامم تا کین نکشم زوی .<br /> <font color=\"Red\">فرخی .</font><br />دهقان به سحرگاهان کز خانه بیاید<br />نه هیچ بیارامد و نه هیچ بپاید.<br /> <font color=\"Red\">منوچهری .</font><br />نخفت و نیارامید تا به سیستان آمد. (تاریخ سیستان ). و اوقات را بخش کرده بود زمانی به نماز و خواندن زمانی به نشاط و خوردن زمانی کار پادشاهی بازنگریدن و زمانی به آسایش و خلوت به آرامیدن . (تاریخ سیستان ). در این وقت ملطفها رسید از منهیان بخارا، که علی تکین البته نمی آرامد و ژاژ می خاید و لشکر میسازد. (تاریخ بیهقی ). و اصحاب مناصب ... بمحل و مرتبه ٔ خویش پیش رفتند و ایستادند و بنشستند و بیارامیدند. (تاریخ بیهقی ).<br />هر چیز با قرین خود آرامد<br />جغدی قرار کرده بویرانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بلیناس رفت پیش بتی بیارامید که تعلق بعلم نجوم داشت . (مجمل التواریخ ). و او مردی سفردوست بود و هیچ نیارامیدی . (مجمل التواریخ ). تو که عمارت دنیا را دوست داری چون دلت آنجا نیارامد باز بدست خود خراب میکنی و جائیت که دل بیارامد بنا درمی افکنی . (کتاب المعارف ). درویش بی معرفت نیارامد تا فقرش بکفر انجامد. (گلستان ). <BR><font color=\"Blue\">◄</font> خفتن . خوابیدن . نوم . استنامه <span class=\"hlight\">:</span> <br />سام شب را بدانجایگاه رفتی و بیارامیدی (مجمل التواریخ ).<br />زلف او رهزن شود چشمش چو گردد مست خواب <br />شبرو طرّار خیزد چون بیارامد عسس .<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />بازرگانی ... شبی در جزیره ٔ کیش مرا بحجره ٔ خویش برد.همه شب نیارامید از سخنهای باخشونت گفتن . (گلستان ). <BR><font color=\"Blue\">◄</font> از جوش و غلیان بازایستادن . فرونشستن کف <span class=\"hlight\">:</span> باغبان بیامد و شاه را گفت <font color=\"DarkGreen\"><b>[ جمشید را]</font></b> این شیره <font color=\"DarkGreen\"><b>[ آب انگور ]</font></b> همچون دیگ بی آتش میجوشد و تیر میاندازد، گفت چون بیارامد مرا آگاه کن . باغبان روزی دید صافی و روشن شده ... و آرامیده شده . (نوروزنامه ). <BR><font color=\"Blue\">◄</font> شکیبیدن . صبر کردن . شکیبا شدن <span class=\"hlight\">:</span> <br />اگر طفلی بدو گوید بیارام <br />که زیر این عسل زهر است در جام ...<br /> <font color=\"Red\">(اسرارنامه ).</font><br /> <BR><font color=\"Blue\">◄</font> مطمئن شدن . اطمینان یافتن . (زمخشری ). از اضطراب بازآمدن . استیناس . طمأنینه . (مجمل اللغه ) <span class=\"hlight\">:</span> بدان نامه بیارامید و همه ٔ نفرتها زائل گشت و قرارگرفت <font color=\"DarkGreen\"><b>[ آلتونتاش ]</font></b>. (تاریخ بیهقی ). بسخن بونصر قویدل و ساکن گشت و بیارامید. (تاریخ بیهقی ). وی را نیک ترسانیده بودند اما بدان نامه بیارامید. (تاریخ بیهقی ). <font color=\"DarkGreen\"><b>[ منوچهر ]</font></b> خدمت و بندگی نمود و دل او بیارامید.(تاریخ بیهقی ).<br />از حجت بشنو سخن بحجت <br />بر حجت حجت بدل بیارام .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ایزدتعالی او را <font color=\"DarkGreen\"><b>[ موسی را ]</font></b> نبوت داد و با موسی مناجات کرد و آیتها نمود از عصا و دیگرچیزها تا موسی بیارامید. (مجمل التواریخ ). <BR><font color=\"Blue\">◄</font> وطن گرفتن . منزل کردن . جای گرفتن <span class=\"hlight\">:</span> و بدان موضع که عبداﷲ طاهر معین گردانیده بود بیارامید.(تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> نشستن آشوب . برخاستن فتنه <span class=\"hlight\">:</span> و بعد از مجارا طریق مدارا پیش گرفتیم و سر بتدارک بر قدم یکدیگر نهادیم و بوسه بر سر و روی هم دادیم و فتنه بیارامید. (گلستان ). <BR><font color=\"Blue\">◄</font> بازایستادن <span class=\"hlight\">:</span> <br />کسی کو بجوید ز ما راستی <br />بیارامد از کژّی و کاستی .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامیدن با</span> ؛ رفث . مباضعه . عشرت و صحبت با زنان <span class=\"hlight\">:</span> دختر دهقانی را دوست گرفت و بخواست و با وی بیارامید و دختر از قباد آبستن گشت بکسری نوشروان . (مجمل التواریخ ). و رجوع به آرام شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامیدن جمعی در طاعت کسی </span> ؛ یکدل و همداستان شدن در فرمانبرداری او <span class=\"hlight\">:</span> تا همگان بهرات رسیدند هر دو لشکر با هم برآمیخت، دلهای رعیت و لشکری بر طاعت ما و بندگی بیارامید و قرار گرفت . (تاریخ بیهقی ). ما در این هفته حرکت خواهیم کرد... جهانی در هوا و طاعت ما بیارامیده . (تاریخ بیهقی ). دلهای رعیت و لشکری بر طاعت ما... بیارامید. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامیدن دریا</span> ؛ از آشوب و انقلاب بازایستادن آن . رَهْو.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامیدن شب </span> ؛ سجو.<br /></font></div>'),
(1000, 'آرامیده', '<span class=\"hlight\">آرامیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) ساکن . ساکت . مستریح . مطمئن . آرمیده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامیده شدن </span> ؛ سجو. تفرج .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامیده شدن ورَم و آماس </span> ؛ انفشاش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامیده کردن ستور</span> ؛ توقیر آن . تسکین او.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامیده گفتن </span> ؛تهوید. نرم گفتن . آهسته و شمرده گفتن .<br /></font></div>'),
(1001, 'آرامیدگی', '<span class=\"hlight\">آرامیدگی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) طمأنینه . سکون . قرار. استقرار. آرمیدگی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرامیدگی نمودن </span> ؛ تَوَقّر.<br /></font></div>'),
(1002, 'آران', '<span class=\"hlight\">آران .</span> (اِ) آرنج . آرن . وارن . رونکک . مرفق .<br /></font></div>'),
(1003, 'آران', '<span class=\"hlight\">آران .</span> (اِخ ) نام مرکز خرّه ٔ کویرات کاشان، و خر و الاغ های آنجا از نوعی بزرگ باشد چون استری <span class=\"hlight\">:</span> <br />خوانی دو سه آراست که آرایش آن بود<br />یک کله ٔ گاو و دو سه دست خر آران .<br /> <font color=\"Red\">شفائی .</font><br />بمعنی ولایت اَرّان نیز آورده اند. رجوع به ارّان شود.<br /></font></div>'),
(1004, 'آراک', '<span class=\"hlight\">آراک .</span> (اِ) جزیره . و ظاهراً مصحف آداک است .<br /></font></div>'),
(1005, 'آراکس', '<span class=\"hlight\">آراکس .</span> (اِخ )نام قدیم رودخانه ای در ایران بطول <span class=\"hlight\" dir=\"rtl\">٧٠٠</span> هزار گز که از نزدیکی تخت جمشید گذشته و برود مدوس پیوسته بخلیج فارس می ریخته است . <BR><font color=\"Blue\">◄</font> نام رودخانه ای در مرز ایران به آذربایجان که برود کر پیوندد. رود ارس .<br /></font></div>'),
(1006, 'آراکوزیا', '<span class=\"hlight\">آراکوزیا.</span> (اِخ ) رجوع به آراخوزیا شود.<br /></font></div>'),
(1007, 'آرای', '<span class=\"hlight\">آرای .</span> (نف مرخم ) مانند آرا در اسماء مرکبه به معنی آراینده آید و کلمه ٔ مرکّبه معنی وصفی دهد، چون :انجمن آرای، بت آرای، بزم آرای، پیکرآرای، جهان آرای، چمن آرای، خاطرآرای، خودآرای، دست آرای، دل آرای، رزم آرای، سخن آرای، شهرآرای، صدرآرای، صف آرای، عالم آرای، عروس آرای، کشورآرای، گیتی آرای، لشکرآرای، مجلس آرای، معرکه آرای، ملک آرای، ملکت آرای، نخل آرای (نخلبند)، هنگامه آرای . <BR><font color=\"Blue\">◄</font> (اِمص ) در شهرآرای گاهی معنی اسمی دارد یعنی آذین بندی شهر. رجوع به شهرآرای شود.<br /></font></div>'),
(1008, 'آرایش', '<span class=\"hlight\">آرایش .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِمص، اِ) (از پهلوی آرایشن ) اسم مصدر آراستن . زیب . زینت . تدبیج . زیور. جمال . زَین . زبرج . حلیه . (دهّار). زهره . تنقیش . زخرف . تجمل . تزیین . تزین . تحلی . تقین . پیرایه <span class=\"hlight\">:</span> <br />خرد گیر کآرایش کارتست <br />نگهدار گفتار و کردار تست <br />هم آرایش تاج و گنج و سپاه <br />نماینده ٔ گردش هور و ماه .<br /> <font color=\"Red\">فردوسی .</font><br />ز کرده برخ بر نگارَش نبود<br />جز آرایش کردگارش نبود.<br /> <font color=\"Red\">فردوسی .</font><br />هم آرایش پادشاهی بُوَد<br />جهان بی درم در تباهی بُوَد.<br /> <font color=\"Red\">فردوسی .</font><br />که فرهنگ آرایش جان بود<br />ز گوهرسخن گفتن آسان بود.<br /> <font color=\"Red\">فردوسی .</font><br />سلیح تن آرایش خویش دار<br />بود کِت شب تیره آید بکار.<br /> <font color=\"Red\">فردوسی .</font><br />یکی بنده باشم بدرگاه تو<br />نخواهم جز آرایش گاه تو.<br /> <font color=\"Red\">فردوسی .</font><br />زنی بود آرایش روزگار<br />درختی کزو فر شاهی ببار<br />فرانک بدش نام و فرخنده بود<br />بمهر فریدون دل آکنده بود.<br /> <font color=\"Red\">فردوسی .</font><br />این عن فلان و قال فلان دان که پیش من <br />آرایش کراسه و تمثال دفتر است .<br /> <font color=\"Red\">طیان .</font><br />خواجه بروزگار پدرم آسیبها و رنجها دیده است و ماندن وی ازبهر آرایش روزگار ما بوده است . (تاریخ بیهقی ).<br />وین همه آرایش باغ بهار<br />بینی وین زیب و جمال و بهاش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تن بیچارت زین شوی همی یابد<br />این همه زینت و آرایش و این تحسین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آرایش سپاه تو چون برکشند صف <br />زین سرکشان خلخ و چاچ و تتار باد.<br /> <font color=\"Red\">مسعودسعد.</font><br />بگفت اینقدر ستر و آسایش است <br />وزین بگذری زیب و آرایش است .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرایش این جهان </span> ؛ زخرف دنیا. زهره ٔ حیات دنیا.<br /> <BR><font color=\"Blue\">◄</font> ساز. سامان . آمادگی . اِعداد. تهیه . ساختگی . تنظیم .ترتیب <span class=\"hlight\">:</span> <br />بیک هفته بودش بر آنجا درنگ <br />همی کرد آرایش وساز جنگ .<br /> <font color=\"Red\">فردوسی .</font><br />بسازند و آرایش ره کنند<br />وز آرامگه رای کوته کنند.<br /> <font color=\"Red\">فردوسی .</font><br />بسازیم و آرایش نو کنیم <br />نهانی مگر باغ بی خو کنیم .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> تعبیه <span class=\"hlight\">:</span> <br />نگه کرد آن رزمگه ساوه شاه <br />به آرایش و ساز آن رزمگاه .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> باندازه کردن جامه پس از کوک زدن آن . دوباره اندازه کردن خیاط جامه ٔ کوک زده را دربر صاحب آن . فعل آن، آرایش کردن است . <BR><font color=\"Blue\">◄</font> در مثال ذیل معنی آرایش برای نگارنده مبهم است : و ایزد تعالی منفعت همه ٔ گوهرها به آرایش مردم بازبست مگر منفعت آهن که جمیع صنایع را بکار است و جهان آراسته و آبادان بدوست . (نوروزنامه ). <BR><font color=\"Blue\">◄</font> اَدَب .رسم . آئین . نهاد <span class=\"hlight\">:</span> <br />سوی او یکی نامه ننوشته ای <br />ز آرایش بندگی گشته ای .<br /> <font color=\"Red\">فردوسی .</font><br />سنگ بی نمج و آب بی زایش <br />همچو نادان بود بی آرایش .<br /> <font color=\"Red\">عنصری (از صحاح الفرس ).</font><br /> <BR><font color=\"Blue\">◄</font> تزیین . آذین کردن <span class=\"hlight\">:</span> <br />چو بشنید سیندخت گفتار اوی <br />به آرایش کاخ بنهاد روی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> تسویل . تمویه . صورت سازی . ادب ِ بفریب . تعارف، باصطلاح امروز. تصنع. ظاهرسازی . تبدیل صورت <span class=\"hlight\">:</span> <br />از آن گفتم این کِم پسند آمدی <br />بدین کارها فرهمند آمدی <br />سپه ساختن دانی و کیمیا<br />سپهبد بدستت پدر با نیا<br />ز ما این نه گفتار آرایش است <br />مرا بر تو بر جای بخشایش است <br />بدین روز با خوارمایه سپاه <br />برابر یکی ساختی رزمگاه ...<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ که در خان تو<br />میان بتان شبستان تو<br />یکی مرد برناست کز خویشتن <br />به آرایش جامه کرده ست زن .<br /> <font color=\"Red\">فردوسی .</font><br />تاریخها دیده ام بسیار... پادشاهان گذشته را که خدمتکاران ایشان کرده اند و اندر آن زیادت و نقصان کرده اند و بدان آرایش آن خواسته اند. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> بسامانی . <BR><font color=\"Blue\">◄</font> زی ّ. <BR><font color=\"Blue\">◄</font> آذین . آئین . تحفل . <BR><font color=\"Blue\">◄</font> (اِخ ) نام لحنی از سی لحن باربد که آن را آرایش خورشید نیز گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرایش چین </span> ؛ معنی این ترکیب معلوم نیست، شاید آینه بندی یا پرده های نقاشی <span class=\"hlight\">:</span> <br />همه کاخ کرسی ّ زرّین نهاد<br />به پیش اندر آرایش چین نهاد.<br /> <font color=\"Red\">فردوسی .</font><br />برآراسته دختر شاه را<br />نباید خود آرایشی ماه را<br />بخانه درون تخت زرین نهاد<br />بگرد اندر آرایش چین نهاد.<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود تا تخت زرین نهند<br />بخیمه در آرایش چین نهند.<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود <font color=\"DarkGreen\"><b>[ افراسیاب ]</font></b> کز نامداران هزار<br />بخوانند و از بزم سازند کار<br />سراسر همه دشت آذین نهند<br />بسغد اندر آرایش چین نهند.<br /> <font color=\"Red\">فردوسی .</font><br />بایوانها تخت زرین نهاد<br />بخانه در آرایش چین نهاد.<br /> <font color=\"Red\">فردوسی .</font><br />و در این دو بیت ظاهراً شاعر از آرایش چین معنی دیگری فهمیده است :<br />بود در آرایش چین خسروی <br />وز رُخَش آرایش دین پرتوی .<br /> <font color=\"Red\">کاتبی .</font><br />روزی از آرایش چین شاهزاد<br />شد بسوی دشت دل از خالشاد.<br /><font color=\"Red\">کاتبی .</font><br /></font></div>'),
(1009, 'آرایش خورشید', '<span class=\"hlight\">آرایش خورشید.</span> <font color=\"DarkGreen\"><b>[ ی ِ ش ِ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (اِخ ) نام نوا و لحن اول است از جمله ٔ سی لحن باربد <span class=\"hlight\">:</span> <br />چو زد زآرایش خورشید راهی <br />در آرایش بدی خورشید ماهی .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> (ترکیب اضافی، اِ مرکب ) مجازاً، خط عارض خوبان .<br /></font></div>'),
(1010, 'آرایش کردن', '<span class=\"hlight\">آرایش کردن .</span> <font color=\"DarkGreen\"><b>[ ی ِ ک َ دَ ]</font></b> (مص مرکب ) تزیین . تزیّن . آراستن . جلوه کردن . <BR><font color=\"Blue\">◄</font> طرازیدن . پدرام کردن . تدبیج . تنقیش . خودسازی .<br /></font></div>'),
(1011, 'آرایش کننده', '<span class=\"hlight\">آرایش کننده .</span><font color=\"DarkGreen\"><b>[ ی ِ ک ُ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) زاین . آرایشگر.<br /></font></div>'),
(1012, 'آرایش گاه', '<span class=\"hlight\">آرایش گاه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِ مرکب ) آنجا که آرایش کنند. <BR><font color=\"Blue\">◄</font> دکان سلمانی .<br /></font></div>'),
(1013, 'آرایشکار', '<span class=\"hlight\">آرایشکار.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ص مرکب ) آرایشگر.<br /></font></div>'),
(1014, 'آرایشگر', '<span class=\"hlight\">آرایشگر.</span> <font color=\"DarkGreen\"><b>[ ی ِ گ َ ]</font></b> (ص مرکب ) زاین . مزیِّن . مشّاطه . <BR><font color=\"Blue\">◄</font> سلمانی . گرّای .<br /></font></div>'),
(1015, 'آراینده', '<span class=\"hlight\">آراینده .</span> <font color=\"DarkGreen\"><b>[ ی َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه آرایش دهد.<br /></font></div>'),
(1016, 'آراییدن', '<span class=\"hlight\">آراییدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آراستن .<br /></font></div>'),
(1017, 'آرباس', '<span class=\"hlight\">آرباس .</span> (اِخ ) آرباسِس . نام مردی اساطیری، فرمانروای مدی از طرف سارداناپال و گویند او با همراهی بلزیس حکمران بابل پادشاه آشور را برانداخت و خود را پادشاه مدی نامید.<br /></font></div>'),
(1018, 'آربل', '<span class=\"hlight\">آربل .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) رجوع به اَربل شود.<br /></font></div>'),
(1019, 'آرت', '<span class=\"hlight\">آرت .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b>(اِ) نام پرنده ای . <BR><font color=\"Blue\">◄</font> مِرفَق . آرنج . آرج .وارن . بندگاه ساعد و بازو. آرن . رونکک و بعید نیست که به این معنی مصحف آرن باشد. و رجوع به آرج شود.<br /></font></div>'),
(1020, 'آرتاباز', '<span class=\"hlight\">آرتاباز.</span> (اِخ ) نام سپهدار دارای سوم که پس از دارا از جانب اسکندر چترپت باختر و بلخ گردید. <BR><font color=\"Blue\">◄</font> نام چندین پادشاه ارمینیه . و رجوع به ارته باذ شود.<br /></font></div>'),
(1021, 'آرتابان', '<span class=\"hlight\">آرتابان .</span> (اِخ ) اردوان .<br /></font></div>'),
(1022, 'آرتاکزاستا', '<span class=\"hlight\">آرتاکزاستا.</span><font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (اِخ ) نام باستانی پایتخت ارمنستان ایران .<br /></font></div>'),
(1023, 'آرتاکزرسس', '<span class=\"hlight\">آرتاکزرسس .</span> <font color=\"DarkGreen\"><b>[ ک ِ زِ س ِ ]</font></b> (اِخ ) نامی که یونانیان به اردشیر درازدست داده اند.<br /></font></div>'),
(1024, 'آرتق', '<span class=\"hlight\">آرتق .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) نام ایستگاهی در حدود ایران و روس که از آب گلریز آبیاری می شود.<br /></font></div>'),
(1025, 'آرتماطیقی', '<span class=\"hlight\">آرتماطیقی .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (معرب، اِ) اَرِتماطیقی . اَرِثماطیقی . علم عدد و حساب و آن قسمتی از فلسفه ٔ تعلیمیه ٔ ریاضیه باشد. و رجوع به ارثماطیقی شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1026, 'آرتیست', '<span class=\"hlight\">آرتیست .</span> (فرانسوی، ص، اِ) هنرمند. هنری . <BR><font color=\"Blue\">◄</font> بازیگر.<br /></font></div>'),
(1027, 'آرث', '<span class=\"hlight\">آرث .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (ع ص ) اَرَث . گوسپند خال خال .گوسفند منقط. گوسفند که خالهای سیاه و سپید دارد.<br /></font></div>'),
(1028, 'آرج', '<span class=\"hlight\">آرج .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) آرنج . آرنگ . آرن . وارن . رونکک . مرفق . آرَت . <BR><font color=\"Blue\">◄</font> نام پرنده ای . (برهان ). و رجوع به آرت شود.<br /></font></div>'),
(1029, 'آرد', '<span class=\"hlight\">آرد.</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) مخفف آراد. نام روز بیست وپنجم از هر ماه شمسی .<br /></font></div>'),
(1030, 'آرد', '<span class=\"hlight\">آرد.</span> (اِ) نرمه و آس کرده یا نرم کوفته ٔ حبوب چون جو و گندم و برنج و نخود و باقلا. دقیق . طحین . طحن . آس . پِسْت . لوکه <span class=\"hlight\">:</span> <br />گیا همچو دانه ست و ما آرد او<br />چو بندیشی و این جهان آسیاست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بی آرد می شود بسوی خانه زآسیا<br />آنکو نبرده گندم و جو به آسیا شده ست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گفت لحم و دنبه گر یابم که خواهد داد آرد<br />گفتم آنکو آسیای چرخ گردان ساخته .<br /> <font color=\"Red\">کاتبی ترشیزی .</font><br />تا آرد ز خمره بار بربست <br />پیچان شده ام چو تیر تتماج .<br /> <font color=\"Red\">بسحاق اطعمه .</font><br /> <BR><font color=\"Blue\">◄</font> تقصیر. (برهان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد باقلا</span> .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد برنج </span> .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد جو</span> ؛ دقیق الشعیر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد جو بریان کرده </span> ؛پیَه . سویق الشعیر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد سبوس دار</span> ؛ خشکار.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد سپید</span> ؛ ارده ٔ کنجد سفید. لکد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد شدن </span> ؛ نرم گشتن به آس یا هاون و جز آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد کردن </span> ؛ نرم کردن به آس یا یانه و امثال آن . اِجشاش . طحن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد کنار</span> ؛ سویق النبق .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد گندم </span> ؛ دقیق الحنطه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد میده </span> ؛ سمید.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد نخود</span> ؛ آس کرده ٔ آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرد نخودچی </span> ؛ نرم کوفته و بیخته ٔ آن که از آن شیرینی پزند و در کوفته کنند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آرد</span> ؛ سخت نرم کرده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آرد بدهن گرفته بودن </span> ؛ آنجایی که باید سخن گفتن خاموش بودن .<br /><span class=\"hlight\">ما آرد خود را بیختیم آردبیز خود را آویختیم </span> ؛ نوبت جوانی، نوبت تحصیل نام، نوبت شوی نو یا زن نو کردن من گذشته است .<br /></font></div>'),
(1031, 'آرد و بار', '<span class=\"hlight\">آرد و بار.</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِ مرکب، از اتباع ) جنس آرد، خمیر، نان : آردوبار فلان نانوائی ؛ جنس نان ِ آن .<br /></font></div>'),
(1032, 'آرد کپان', '<span class=\"hlight\">آرد کپان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام طائفه ای از ایل قشقائی ساکن حوالی سمیرُم مرکب از <span class=\"hlight\" dir=\"rtl\">١٥٠</span> خانوار.<br /></font></div>'),
(1033, 'آردآب', '<span class=\"hlight\">آردآب .</span> (اِ مرکب ) آرد جو به آب آمیخته که بچارپا دهند.<br /></font></div>'),
(1034, 'آردآله', '<span class=\"hlight\">آردآله .</span><font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ مرکب ) آردهاله . سخینه . (ربنجنی ).<br /></font></div>'),
(1035, 'آردآلود', '<span class=\"hlight\">آردآلود.</span> (ن مف مرکب ) غبار آرد گرفته .<br /></font></div>'),
(1036, 'آردابه', '<span class=\"hlight\">آردابه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ مرکب ) آردآب . <BR><font color=\"Blue\">◄</font> آردی که به آب شوربا ریزند. <BR><font color=\"Blue\">◄</font> شوربائی که آرد در آن آمیزند. <BR><font color=\"Blue\">◄</font> آرد به آب آمیخته . کشک .<br /></font></div>'),
(1037, 'آرداد', '<span class=\"hlight\">آرداد.</span> (اِ) غول بیابان . و این غول به صورت آدمی باشد پرموی با پایهای دراز و عقب ماندگان کاروان را بشب چون راهنمائی در پیش افتد و از راه بیرون برد به بیابان و آنان را هلاک کند و خونشان بیاشامد. این کلمه تنها در فرهنگ شعوری هست و این فرهنگ معتمد نیست .<br /></font></div>'),
(1038, 'آردالو', '<span class=\"hlight\">آردالو.</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> لُو ]</font></b> (اِ مرکب ) قسمی اِشکنه که آرد در آن کنند.<br /></font></div>'),
(1039, 'آردبیز', '<span class=\"hlight\">آردبیز.</span> (اِ مرکب ) مُنخل . غربال . اَلک . تنگ بیز.<br /></font></div>'),
(1040, 'آردتوله', '<span class=\"hlight\">آردتوله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ مرکب ) آردهاله <span class=\"hlight\">:</span> <br />آن آردتوله خور که بمن لوت خوار گفت <br />چون ماستابه پخت ز من عذرها بخواست .<br /><font color=\"Red\">بسحاق اطعمه .</font><br /></font></div>'),
(1041, 'آرددان', '<span class=\"hlight\">آرددان .</span> (اِ مرکب ) آن خانه از نانوائی که در آن آرد پستا کنند. <BR><font color=\"Blue\">◄</font> کندو یا ظرفی دیگر که در آن آرد ریزند.<br /></font></div>'),
(1042, 'آرددوله', '<span class=\"hlight\">آرددوله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ مرکب ) آردهاله .<br /></font></div>'),
(1043, 'آردستان', '<span class=\"hlight\">آردستان .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) اَردِستان .<br /></font></div>'),
(1044, 'آردشیر', '<span class=\"hlight\">آردشیر.</span> (اِ مرکب ) حریره ٔ آرد گندم .<br /></font></div>'),
(1045, 'آردفروش', '<span class=\"hlight\">آردفروش .</span> <font color=\"DarkGreen\"><b>[ ف ُ ]</font></b> (نف مرکب ) دقّاق .<br /></font></div>'),
(1046, 'آردل', '<span class=\"hlight\">آردل .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِ) فراشی که برای خواندن و احضار سپاهیان یا گناهکاران و یا مدعی علیهم فرستادندی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آردل بی چوب </span>؛ کنایه از بول است آنگاه که تنگ گیرد کسی را.<br /></font></div>'),
(1047, 'آردل', '<span class=\"hlight\">آردل .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) نام راهی است در بختیاری که تا مالمیر بسیارتنگ است و برای عبور صعب و قلعه ٔ چغاخور نزدیک <span class=\"hlight\" dir=\"rtl\">٧٠٠</span> گز از آردل ارتفاع دارد. و اهل محل ّ اَردَل گویند.<br /></font></div>'),
(1048, 'آردل باشی', '<span class=\"hlight\">آردل باشی .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (ص مرکب، اِ مرکب ) رئیس آردِلان .<br /></font></div>'),
(1049, 'آردلو', '<span class=\"hlight\">آردلو.</span> <font color=\"DarkGreen\"><b>[ دَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> لُو ]</font></b> (اِ مرکب ) آردهاله . <BR><font color=\"Blue\">◄</font> آردالو. اشکنه ٔ با آرد.<br /></font></div>'),
(1050, 'آردم', '<span class=\"hlight\">آردم .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ) آذریون . آذرگون .<br /></font></div>'),
(1051, 'آردن', '<span class=\"hlight\">آردن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ) ظرفی چون طبقی با سوراخهای بسیار که طباخان و حلوائیان بر سر دیگ نهند و روغن و شیره و ترشی و غیر آن بدان پالایند. آبکش . پالاون . پالونه . ترشی پالا. ماشو. ماشوب . سماق پالا. اَردَن . پالوانه . زازل . <BR><font color=\"Blue\">◄</font> کفگیر. <BR><font color=\"Blue\">◄</font> (اِخ ) نام ولایتی . (برهان قاطع).<br /></font></div>'),
(1052, 'آردن', '<span class=\"hlight\">آردن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) مخفف آوردن، چون تانستن مخفف توانستن . این مصدرغیرمستعمل لکن مشتقات از آن معمول است <span class=\"hlight\">:</span> <br />درنگ آرا سپهر چرخ وارا<br />کیاخن تَرْت باید کرد کارا.<br /> <font color=\"Red\">رودکی .</font><br />لعل می را ز درج خم برکش <br />در کدو نیمه کن بنزد من آر.<br /> <font color=\"Red\">رودکی .</font><br />ار خوری از خورده بگساردْت رنج <br />ور دهی مینو فراز آردْت گنج .<br /> <font color=\"Red\">رودکی .</font><br />بود رسم و آئین شیر دلیر<br />که آرد به آهستگی شیر زیر.<br /> <font color=\"Red\">فردوسی .</font><br />به بیشه یکی خوبرخ یافتند <font color=\"DarkGreen\"><b>[ گیو و طوس ]</font></b><br />پر از خنده لب هر دو بشتافتند<br />نگاری بدیدند چون نوبهار<br />که از یک نظر شیر آرد شکار.<br /> <font color=\"Red\">فردوسی .</font><br />ورا <font color=\"DarkGreen\"><b>[ کیخسرو را ]</font></b> پیلتن گفت کاین غم مدار<br />که کامت برآرد همه روزگار.<br /> <font color=\"Red\">فردوسی .</font><br />به پیش تو آرم سر و رخش اوی <br />همان تیغ و گرز جهان بخش اوی .<br /> <font color=\"Red\">فردوسی .</font><br />گرفتند نفرین به بهرام بر<br />بدان جام و آرنده ٔ جام بر.<br /> <font color=\"Red\">فردوسی .</font><br />از مار کینه ورتر ناسازتر چه باشد<br />گفتار چربش آرد بیرون ز آشیانه .<br /> <font color=\"Red\">لبیبی .</font><br />و من اینجاام تا همگان را بخوبی ... بر اثر وی بیارند. (تاریخ بیهقی ).<br />یاد ناری پدرت را که مدام <br />گه تبنگش چدی و گه خنجک .<br /> <font color=\"Red\">اسدی (از فرهنگ، خطی ).</font><br />امروز آزار کس مجوی که فردا<br />هم ز تو بی شک بجان تو رسد آزار<br />آنچه نخواهی که من به پیش تو آرم <br />پیش من از قول و فعل خویش چنان مار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />خرج آن <font color=\"DarkGreen\"><b>[ مال ]</font></b> بیوجه کند پشیمانی آرد. (کلیله و دمنه ).<br /> <BR><font color=\"Blue\">◄</font> برکشیدن . فروبردن <span class=\"hlight\">:</span> <br />چنین است کردار گردان فلک <br />یکی بر مه آرد یکی بر سمک .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1053, 'آرده', '<span class=\"hlight\">آرده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ) آرد کنجده ٔ سپید. ارده . لکد.<br /></font></div>'),
(1054, 'آرده خرما', '<span class=\"hlight\">آرده خرما.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ خ ُ ]</font></b> (اِ مرکب ) طعامی است که از خرما و آرد یا نان گرم و کره سازند. رنگینک .<br /></font></div>'),
(1055, 'آردهالجه', '<span class=\"hlight\">آردهالجه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ج َ ]</font></b> (معرب، اِ مرکب ) معرب آردهاله .<br /></font></div>'),
(1056, 'آردهاله', '<span class=\"hlight\">آردهاله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ مرکب ) (از: آرد، دقیق + اهاله ٔ عربی، روغن و چربو) کاچی . حریره ٔ آردی . (زمخشری ). اوماج . (صراح ). سخینه . (صراح ) (زمخشری ). بلماق . بولماج . آرددوله . آردتوله . آرداله . (مهذب الاسماء). اَردوله .<br /></font></div>'),
(1057, 'آردهه', '<span class=\"hlight\">آردهه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام ناحیه ای از اعمال طهران دارای معدن ذغال سنگ .<br /></font></div>'),
(1058, 'آردوج', '<span class=\"hlight\">آردوج .</span> (اِ) اَردوج . درخت ابهل .<br /></font></div>'),
(1059, 'آردی', '<span class=\"hlight\">آردی .</span> (ص نسبی ) از آرد. منسوب به آرد. آلوده ٔ به آرد. آردین : حلوای آردی . <BR><font color=\"Blue\">◄</font> (اِ) قسمی از شفتالو. (غیاث اللغات ). هلوآرده، و آن شفتالوئی باشد خرد و کم آب .<br /></font></div>'),
(1060, 'آردی روغن', '<span class=\"hlight\">آردی روغن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رُو غ َ ]</font></b> (اِ مرکب )حلوای آردی . حلوا که از آرد گندم کنند <span class=\"hlight\">:</span> <br />آردی روغن و حلوای برنجی وزلیب <br />مرد کاری چو بچنگال زنی اول بار.<br /> <font color=\"Red\">بسحاق اطعمه .</font><br />آردی روغن برم لال آمده ست <br />نام من از غیب چنگال آمده ست .<br /><font color=\"Red\">بسحاق اطعمه .</font><br /></font></div>'),
(1061, 'آردین', '<span class=\"hlight\">آردین .</span> (ص نسبی ) آردی . منسوب به آرد. از آرد. آلوده ٔ به آرد.<br /></font></div>'),
(1062, 'آردینه', '<span class=\"hlight\">آردینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب )آنچه از آرد کنند. آشی که از آرد پزند <span class=\"hlight\">:</span> <br />فغان از دل آردینه بخاست <br />ببستند بر خود کفنهای ماست .<br /><font color=\"Red\">بسحاق اطعمه .</font><br /></font></div>'),
(1063, 'آرز', '<span class=\"hlight\">آرز.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) منقبض . مُتجمع. ثابت .<br /></font></div>'),
(1064, 'آرز', '<span class=\"hlight\">آرز.</span><font color=\"DarkGreen\"><b>[ رُ ]</font></b> (ع اِ) اَرُزّ. رُزّ. برنج (یکی از حبوب ).<br /></font></div>'),
(1065, 'آرزم', '<span class=\"hlight\">آرزم .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) رزم . جنگ . کارزار. (غیاث اللغات ).<br /></font></div>'),
(1066, 'آرزه', '<span class=\"hlight\">آرزه .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ) کاهگل .<br /></font></div>'),
(1067, 'آرزه', '<span class=\"hlight\">آرزه .</span> <font color=\"DarkGreen\"><b>[ رِ زَ ]</font></b> (ع ص ) شترماده ٔ قوی . <BR><font color=\"Blue\">◄</font> شب سرد. <BR><font color=\"Blue\">◄</font> درخت استوارشده ٔ در زمین .<br /></font></div>'),
(1068, 'آرزه گر', '<span class=\"hlight\">آرزه گر.</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ گ َ ]</font></b> (ص مرکب ) اندودگر. کاهگل کار.<br /></font></div>'),
(1069, 'آرزو', '<span class=\"hlight\">آرزو.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِ) شهوت . (ربنجنی ). اشتهاء. (حبیش تفلیسی ). قوّت ِ جذب ملایم . هوی ̍. هوا <span class=\"hlight\">:</span> <br />همی ز آرزوی ... -ر، خواجه را گه خوان <br />بجز زونج نباشد خورش بخوانش بر.<br /> <font color=\"Red\">معروفی .</font><br />برِ شاه مکران فرستاد و گفت <br />که با شهریاران خرد باد جفت <br />نگه کن که ما از کجا رفته ایم <br />نه مستیم و بر آرزو خفته ایم .<br /> <font color=\"Red\">فردوسی .</font><br />گر زآنکه لکانه ست آرزویت <br />اینک بمیان ْران من لکانه .<br /> <font color=\"Red\">طیان .</font><br />همیدون پندهای پادشائی <br />دو بهره باشد اندر پارسائی <br />بلهو و آرزو مولع نبودن <br />دل هر کس به نیکی برگشودن .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />اگر آرزو و خشم نبایستی خدای عزّ و جل ّ در تن مردم نیافریدی . (تاریخ بیهقی ). اگر آرزوی در دنیا نیافریدی کس سوی غذا... و سوی جفت ننگریستی . (تاریخ بیهقی ). اگر طاعنی گوید که اگر آرزوو خشم نبایستی خدای تعالی ... در تن مردم نیافریدی جواب آن است که ... (تاریخ بیهقی ). چون مرد افتد با خردتمام، و قوت خشم و قوت آرزو بر وی چیره گردند، قوت خرد منهزم گردد. (تاریخ بیهقی ). آن کسی که آرزوی وی بتمامی چیره تواند شد... چشم خردش نابینا ماند. (تاریخ بیهقی ). در این تن سه قوه است، یکی خرد... دیگر خشم، سه دیگر آرزو. (تاریخ بیهقی ).<br />خود سپس ِ آرزوی تن مرو<br />چون خُرُه ِ نر ز پس ماکیان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />پادشا گشت آرزو بر تو ز بیباکی ّ تو<br />جان و دل بایدْت داد این پادشا را باژ و سا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />پارسا شو تا بباشی پادشا بر آرزو<br />آرزو هرگز نباشد پادشا بر پارسا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />این آرزو ای خواجه اژدهائیست <br />بدخو که از این بدتر اژدها نیست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دردیست آرزو که به پرهیز به شود<br />پرهیز خلق را سوی دانا بهین دواست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دویدی بسی از پس آرزوها<br />بروز جوانی چو گاو جوانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ز آرزوی حسّی پرهیز کن <br />آرزویی را که یکی اژدها است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ترا آرزوها چنان چون همی <br />چو کوران بجرّ و بجوی افکند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />شرابی که بترشی زند... آرزوی مجامعت ببرد و پی ها را سست کند. (نوروزنامه ).<br />زآرزوی آب دل پرخون کنم <br />چون دریغ آید بخویشم چون کنم ؟<br /> <font color=\"Red\">عطار (منطق الطیر).</font><br />که مرا صد آرزو و شهوت است <br />دست من بسته ز بیم هیبت است .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> خواهش . کام . مراد. چیز. بغیه . مُنیَت <span class=\"hlight\">:</span> <br />یکی زردشت وارم آرزویست <br />که پیشت زند را برخوانم از بر.<br /> <font color=\"Red\">دقیقی .</font><br />ابا کردیه گفت کز آرزوی <br />چه خواهی بگوی ای زن نیکخوی .<br /> <font color=\"Red\">فردوسی .</font><br />مرادت بدین کار گردد تمام <br />بدین آرزو باشدت نام و کام .<br /> <font color=\"Red\">فردوسی .</font><br />یکی آرزو دارد اندر نهان <br />بیاید بخواهد ز شاه جهان .<br /> <font color=\"Red\">فردوسی .</font><br />ز هر کام و هر آرزو بی نیاز<br />بهر آرزو دست ایشان دراز.<br /> <font color=\"Red\">فردوسی .</font><br />گمانت چنین است کاین تاج و تخت <br />سپاه و فزونی و نیروی بخت <br />ز گیتی کسی را نبد آرزوی <br />از آن نامداران آزاده خوی .<br /> <font color=\"Red\">فردوسی .</font><br />چرا آمدستی بدین رزمگاه <br />ز ما آرزو هرچه خواهی بخواه .<br /> <font color=\"Red\">فردوسی .</font><br />ز یزدان چو شاه آرزوها بیافت <br />ز دریا سوی خان آذر شتافت .<br /> <font color=\"Red\">فردوسی .</font><br />بموبد چنین گفت پیروز شاه <br />که خواهش ز یزدان باندازه خواه <br />چو خواهش ز اندازه بیرون شود<br />از آن آرزو دل پر از خون شود.<br /> <font color=\"Red\">فردوسی .</font><br />ز یزدان همه آرزو یافتم <br />وگر دل همه سوی کین تافتم .<br /> <font color=\"Red\">فردوسی .</font><br />پسر گفت کای مرد آزاده خوی <br />مرا مرگ تو کی بود آرزوی ؟<br /> <font color=\"Red\">فردوسی .</font><br />چو شد بر جهان پادشاهیش راست <br />بزرگی فزون گشت و مهرش بکاست <br />خردمند نزدیک او خوار گشت <br />همه رسم شاهیش بیکار گشت ...<br />سترگی گرفت او نه مهر و نه داد<br />بهیچ آرزو نیز پاسخ نداد.<br /> <font color=\"Red\">فردوسی .</font><br />که پوشیده رویان و فرزند من <br />همان خواهران را و پیوند من <br />ببخشی بمن تا بتوران برم <br />چنین آرزو را اگر درخورم <br />چو بشنید از او <font color=\"DarkGreen\"><b>[ از جهن ]</font></b> شهریار این سخُن <br />بر این آرزو پاسخ افکند بن .<br /> <font color=\"Red\">فردوسی .</font><br />از این مرز رفتن ترا روی نیست <br />مکن گر ترا آرزو شوی نیست .<br /> <font color=\"Red\">فردوسی .</font><br />دگر کِت بدار مسیحا سخن <br />بیاد آمد از روزگار کهن ...<br />چو چوبی از ایران فرستم بروم <br />بخندند بر ما همه مرز و بوم <br />دگر آرزو هرچه باید بخواه <br />شما را سوی ما گشاده ست راه .<br /> <font color=\"Red\">فردوسی .</font><br />سخنهای زیبا و خوش گویشان <br />مراد دل و آرزو جویشان .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />آرزوی خویش بیابد در او<br />هر کسی از خلق کِهین و مِهین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نخستین قدح بدشخواری خوردم که تلخ مزه بود چون در معده ام قرار گرفت طبعم آرزوی قدح دیگر کرد. (نوروزنامه ). و خردمند چگونه آرزوی چیزی کند که رنج و تعب آن بسیار باشد؟ (کلیله و دمنه ).<br />چون چنین خواهی خدا خواهد چنین <br />میدهد حق آرزوی متقین .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> خواستگاری . خطبه . خواندن بتزویج زنی را <span class=\"hlight\">:</span> <br />دگر آنکه از روشنک یاد کرد<br />دل ما بدان آرزو شاد کرد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> انتظار. توقع. ترصد. رجاء. امل . امید. تمنی . اُمْنیه . مُنْیه <span class=\"hlight\">:</span> <br />شنیده ام که بهشت آن کسی تواند یافت <br />که آرزو برساند به آرزومندی .<br /> <font color=\"Red\">شهید بلخی .</font><br />کنون آنچه اندرخور کار تست <br />دلت یافت آن آرزوها که جست .<br /> <font color=\"Red\">فردوسی .</font><br />یک دل و صد آرزو بس مشکل است <br />یک مرادت بس بود چون یکدل است .<br /> <font color=\"Red\">امیرحسینی .</font><br />خسروابنده را چو ده سال است <br />که همی آرزوی آن باشد<br />کز ندیمان مجلس ار نشود<br />از مقیمان آستان باشد<br />بخرش پیش از آن که بشناسی <br />وآنگهت رایگان گران باشد.<br /> <font color=\"Red\">انوری .</font><br />ور بمردیم عذر مابپذیر<br />ای بسا آرزو که خاک شده .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> شوق . اشتیاق . توق . تیاقه . توقان . صبابت . حسرت . تلهف <span class=\"hlight\">:</span> <br />یکی نامه بنوشت با درد و خشم <br />پر از آرزو دل، پر از آب چشم .<br /> <font color=\"Red\">فردوسی .</font><br />چه بر کام دل کامکاری بود<br />چه بر آرزو تن بخواری بود<br />چو شد اسپری روز هر دو یکیست <br />گر افزون بود سال و گر اندکیست .<br /> <font color=\"Red\">فردوسی .</font><br />جهانجوی را نیز پاسخ نوشت <br />پر از آرزو نامه ای چون بهشت .<br /> <font color=\"Red\">فردوسی .</font><br />بود یک هفته به نزدیکی بیگانه و خویش <br />زآرزوی بچه ٔ رز دل او خسته و ریش .<br /> <font color=\"Red\">منوچهری .</font><br />گرْت آرزوست صورت او دیدن <br />وآن منظر مبارک و آن مخبر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />شعر حجت بایدت خواندن ترا گرْت آرزوست <br />نظم خوب و وزن خوب و لفظ خوش معنوی .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> ذوق و قریحه ٔ انتخاب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خوش آرزو</span> ؛ نیک گزین . به گزین : ریدک خوش آرزو.<br /> <BR><font color=\"Blue\">◄</font> هوس . میل <span class=\"hlight\">:</span> <br />ز دیدار خیزد همه آرزوی <br />ز چشم است گویند رژدی گلوی .<br /> <font color=\"Red\">ابوشکور.</font><br />چون بچه ٔ کبوتر منقار سخت کرد<br />هموار کرد موی و بیوکند موی زرد<br />کابوک را نشاید و شاخ آرزو کند<br />وز شاخ سوی بام شود باز گردگرد.<br /> <font color=\"Red\">ابوشکور.</font><br />اگر سال نیز آرزو آمده ست <br />نهم سال و هشتاد با سیصد است .<br /> <font color=\"Red\">فردوسی .</font><br />دو پرخاشجو با یکی نیکخوی <br />گرفتند پرسش نه بر آرزوی .<br /><font color=\"Red\">فردوسی .</font><br />چنان بد که یک روز پرویزشاه <br />همی آرزو کرد نخجیرگاه .<br /> <font color=\"Red\">فردوسی .</font><br />مرا گرآرزوش آید میان انجمن خواند.<br /> <font color=\"Red\">فرخی .</font><br />نه حاجب مر ترا گوید که بنشین <br />نه دربان مر ترا گوید که بگذر<br />اگر خواجه بودیا نه تو در قصر<br />بباش و آرزوها خواه درخور.<br /> <font color=\"Red\">فرخی .</font><br />وگر کریم شود آرزوت نام و لقب <br />کریم وارت فعل کرام باید کرد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />گفت خواهم دویست چوب بر او<br />گفت چوبت چه آرزوست بگو.<br /> <font color=\"Red\">سنائی .</font><br />دختری دارم لطیف و بس سنی <br />آرزو می بود او را مؤمنی .<br /> <font color=\"Red\">مولوی .</font><br />گفتم که یافت می نشود جسته ایم ما<br />گفت آنکه یافت می نشود آنم آرزوست .<br /> <font color=\"Red\">مولوی .</font><br />یک دست جام باده و یک دست زلف یار<br />رقصی چنین میانه ٔ میدانم آرزوست .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> چیز مطلوب . حاجت <span class=\"hlight\">:</span> <br />بدو گفت بنگر که تا آرزوی <br />چه خواهی بخواه از من ای نیکخوی .<br /> <font color=\"Red\">فردوسی .</font><br />یکی آرزو خواهم از شهریار<br />که آن آرزو نزد او هست خوار<br />که دار مسیحا بگنج شماست <br />چو بینید داریدگفتار راست <br />برآمد بر این روزگار دراز<br />سزد گر فرستد بما شاه باز.<br /> <font color=\"Red\">فردوسی .</font><br />هر آنگه که کاریت فرمود شاه <br />در آن وقت هیچ آرزو زو مخواه .<br /> <font color=\"Red\">اسدی .</font><br />آرزو میخواه لیک اندازه خواه <br />برنتابد کوه را یک برگ کاه .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> آز. حرص . (دهار).شره <span class=\"hlight\">:</span> <br />کراآرزو بیش تیمار بیش <br />بکوش و منه میوه ٔ آز پیش .<br /> <font color=\"Red\">فردوسی .</font><br />جهان خوش بود بر دل نیکخوی <br />نگردد بگرد درِ آرزوی .<br /> <font color=\"Red\">فردوسی .</font><br />آرزو را و حسد را مده اندر دل جای <br />گر همی خواهی تا جانْت بماران ندهی .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> تمنی . ترجی . دعا <span class=\"hlight\">:</span> <br />همی لشکر و کشور آراستی <br />همی رزم را به آرزو خواستی .<br /> <font color=\"Red\">فردوسی .</font><br />به اختیار کس از یار خویش دور شود<br />بروز وصل کسی آرزو کند هجران ؟<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> وصال . قرب <span class=\"hlight\">:</span> <br />گرفتند مر یکدگر را ببر<br />بسی بوسه دادند بر روی و سر<br />همی هر دوان زار بگریستند<br />که یکچند بی آرزو زیستند.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> طمع. داعیه <span class=\"hlight\">:</span> <br />ز شیر شتر خوردن و سوسمار<br />عرب را بجائی رسیده ست کار<br />که تاج کیان را کنند آرزو<br />تفو باد بر چرخ گردون تفو.<br /> <font color=\"Red\">فردوسی .</font><br />بدین چهر و این مهر و این راه و خوی <br />همی تخت و تاج آیدت آرزوی .<br /> <font color=\"Red\">فردوسی .</font><br />ترا آرزو کرد شاهنشهی <br />چنان دان که گردی تو از جان تهی .<br /> <font color=\"Red\">فردوسی .</font><br />ندیدم کسی کاینچنین زَهره داشت ...<br />کش اندیشه ٔ گاه او آمدی <br />وگرْش آرزو جاه او آمدی .<br /> <font color=\"Red\">فردوسی .</font><br />علی تکین به این یک ناحیت بازنایستد و وی را آرزوهای دیگر خیزد. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> استبداد رای . خودرائی . خودسری . میل . هوی ̍ <span class=\"hlight\">:</span> <br />همه به آرزو خواستی رسم و راه <br />نکردی بفرمان یزدان نگاه .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> عزم . قصد. مقصود. منظور <span class=\"hlight\">:</span> <br />خردمندو نامی و دانا بود<br />بهر آرزو بر توانا بود.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نفس آرزو</span> ؛ قُوّت شَهویه . نفس حیوانی <span class=\"hlight\">:</span> نفس آرزو، به وی است دوستی طعام و شراب و دیگر لذتها. (تاریخ بیهقی ).<br /> <BR><font color=\"Blue\">◄</font> مقصد <span class=\"hlight\">:</span> <br />سحرگه چو از خواب برخاستند<br />بر آن آرزو رفتن آراستند.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> معشوق .محبوب . مطلوب <span class=\"hlight\">:</span> <br />گر تو مرا دست بازداری بی تو<br />زیر نباشد چو من بزردی و زاری <br />میر نگفته ست مر ترا که روا نیست <br />کآرزوی خویش را براه بیاری .<br /> <font color=\"Red\">فرخی .</font><br />راست چو شب گاوگون شود بگریزم <br />گویم تا در نگه کنند بمسمار<br />آرزوی خویش را بخوانم و گویم <br />شب همه بگذشت خیز و داروی خواب آر.<br /> <font color=\"Red\">فرخی .</font><br />بپرهیز از او بر بد آراستن <br />هم از آرزوی کسان خواستن .<br /> <font color=\"Red\">اسدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزو آمدن </span> ؛ آرزو دست دادن . آرزو پیدا گشتن <span class=\"hlight\">:</span> <br />آرزو ناید همی بغدادیان را با تو شاه <br />روزگار معتصم یا روزگار مستعین .<br /> <font color=\"Red\">معزی .</font><BR>۩ اشتها. (زوزنی ). حرص . (دهار).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزو بردن </span> ؛ آرزو کردن . تَمنی . (دهار). غبطه . اغتباط <span class=\"hlight\">:</span> <br />آرزو می بریم چه تْوان کرد<br />سود ناکرده سخت بسیار است .<br /> <font color=\"Red\">انوری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزو پختن </span> ؛ طمع خام کردن <span class=\"hlight\">:</span> و آرزوی ناممکن و محال پختن نشان خامی و دشمن کامی باشد. (مرزبان نامه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزو خاستن کسی چیزی را</span> ؛ اشتهاء آن کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزوی خام </span> ؛خواهش یا امید یا طمعی ناممکن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزو خواستن، آرزو کردن </span> ؛ خواهش کردن . درخواست . التماس مطلوب . حاجت طلبیدن . تمنی . تقاضی . ادعاء <span class=\"hlight\">:</span> <br />ز من آب کرد آرزو آن سوار<br />چو از دور دیدش مرا نامدار.<br /> <font color=\"Red\">فردوسی .</font><br />و پیغام داد که عجب داشتم از کاردانی و عقل شما که بحکم همسایگی تا این غایت از جانب ما التماسی نکردید و آرزوئی نخواستید. (راحةالصدور).<br />یکی آرزو خواهم از شهریار<br />که با من فرستد یکی استوار<br />که تا هر کسی کو نبرد آورد<br />سر دشمنی زیر گرد آورد<br />نویسد بنامه درون نام او<br />رونده شود در جهان کام او.<br /> <font color=\"Red\">فردوسی .</font><br />غروری چه باید برآراستن <br />نه بر جای خویش آرزوخواستن ؟<br /> <font color=\"Red\">نظامی .</font><br />آرزو میخواه لیک اندازه خواه .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزو داشتن </span> ؛ آرزومند بودن <span class=\"hlight\">:</span> <br />بدو گفت کز کردگار جهان <br />یکی آرزو دارم اندر نهان <br />که ماند زتو نام تو یادگار<br />ز پشت تو آید یکی شهریار.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزو رساندن </span> ؛ آرزو و حاجت کسی را برآوردن <span class=\"hlight\">:</span> <br />شنیده ام که بهشت آن کسی تواند یافت <br />که آرزو برساند به آرزومندی .<br /> <font color=\"Red\">شهید بلخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزو شکستن در دل </span> ؛ یأس و نومیدی از حصول مطلوبی حاصل آمدن <span class=\"hlight\">:</span> <br />آخر ای آرزوی دل تا کی <br />در دل این آرزو فروشکنم ؟<br /> <font color=\"Red\">حسن غزنوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزو شکستن ْ کسی و خاصه بیماری را</span> ؛ بمزوَّره ای او را خوشدل کردن یا با بوی کباب و مانند آن او را تسلیت دادن <span class=\"hlight\">:</span> <br />بر آتش ستم جگرم زآن کباب کرد<br />تا آرزوی نرگس بیمار بشکند.<br /> <font color=\"Red\">کمال خجند.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزو کردن </span> ؛ تمنی . تشهی . (زوزنی ) <span class=\"hlight\">:</span> <br />کشکین نانت نکند آرزوی <br />نان و سمن خواهی گرد و کلان .<br /> <font color=\"Red\">رودکی (کذا).</font><br />مسکین خرک آرزوی دم کرد<br />نایافته دم دو گوش گم کرد.<br /> <font color=\"Red\">(از یادداشت به خط مرحوم دهخدا).</font><BR>۩ خواستن . خواهان شدن . هوس کردن <span class=\"hlight\">:</span> <br />برآراست رستم یکی جشنگاه <br />که بزم آرزو کرد خورشید و ماه .<br /> <font color=\"Red\">فردوسی .</font><br />پدرْت آن گرانمایه ٔ نیکخوی <br />نکرد ایچ از تخت او آرزوی .<br /> <font color=\"Red\">فردوسی .</font><br />یکی تاج بااو بد و مهر شاه <br />شبانزاده را آرزو کرد گاه .<br /> <font color=\"Red\">فردوسی .</font><br />تو چون اهرمن دیوی ای خاک روی <br />کند تاج و تخت شهانْت آرزوی .<br /> <font color=\"Red\">فردوسی .</font><br />ندیدی چو نیروی بخت مرا<br />دلت آرزو کرد تخت مرا.<br /> <font color=\"Red\">فردوسی .</font><br />بسان گوزنان بسر بر سُرو<br />همی رزم شیران کنند آرزو.<br /> <font color=\"Red\">فردوسی .</font><br />چو آباد شد زو همه مرز و بوم <br />چنان آرزو کرد کآید بروم .<br /> <font color=\"Red\">فردوسی .</font><br />همی تیر و چوگان کنند آرزوی <br />چه فرمان دهد شاه آزاده خوی ؟<br /> <font color=\"Red\">فردوسی .</font><br />و از آن پیره زن حلواها و خوردنیها آرزو کردندی و وی اندر آن تنوق کردی تا سخت نیکو آمدی . (تاریخ بیهقی ).<br />آرزو می کندم با تو دمی در بستان <br />یا بهر گوشه که باشد، که تو خود بستانی .<br /> <font color=\"Red\">سعدی .</font><br />آرزو می کندم شمعصفت پیش وجودت <br />که سراپای بسوزند من بی سروپا را.<br /> <font color=\"Red\">سعدی .</font><BR>۩ انتخاب کردن . گزیدن . اختیار کردن <span class=\"hlight\">:</span> <br />مرا خواستی <font color=\"DarkGreen\"><b>[ بجنگ ]</font></b> کس نبودی روا<br />که پیشت فرستادمی ناسزا<br />کنون آرزو کن یکی رزمگاه <br />که باشد بدور از میان سپاه .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">برآرزوی، به آرزوی </span> ؛ به اراده . به اختیار. طوعاً. به میل . به مراد. به دلخواه <span class=\"hlight\">:</span> <br />نبیند همی دشمن از هیچ سوی <br />بسندش بود زیستن به آرزوی .<br /> <font color=\"Red\">فردوسی .</font><br />کنون سالیان اندرآمد به هشت <br />که جز به آرزو چرخ بر ما نگشت .<br /> <font color=\"Red\">فردوسی .</font><br />بی اندازه بردند چیزی که خواست <br />چو شد کار برآرزو کرده راست ...<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت کای مادرنیکخوی <br />نه بگزینم این راه برآرزوی .<br /> <font color=\"Red\">فردوسی .</font><br />سپاهی بدین رزمگاه آمدیم <br />نه برآرزو، کینه خواه آمدیم .<br /> <font color=\"Red\">فردوسی .</font><br />همی بود جشنی نه برآرزوی <br />ز تیمار پیروز آزاده خوی .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به آرزو آوردن </span> ؛ تشویق .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">غایت آرزو</span> ؛ منتهای اَمَل . کمال مطلوب <span class=\"hlight\">:</span> <br />غایت آرزو چو دست نداد<br />پشت پائی زدم برآسودم .<br /> <font color=\"Red\">ابن یمین .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آرزو بجوانان عیب نیست </span> ؛ بمزاح، این آرزو بیش از حد تست .<br /> <span class=\"hlight\">آرزو رأس مال مفلس دان </span> .<br /> <font color=\"Red\">سنائی .</font><br /> <span class=\"hlight\">آرزو سرمایه ٔمفلس است </span> ؛ فقیر با امید، دل خویش خوش دارد.<br /> <span class=\"hlight\">آرزو عیب نیست </span> ؛ به استهزاء، این آرزو برتر از مرتبه و مقام تست .<br /> <span class=\"hlight\">آرزو میخواه لیک اندازه خواه </span> <br />برنتابد کوه را یک برگ کاه .<br /> <font color=\"Red\">مولوی .</font><br /> <span class=\"hlight\">آرزو هرگز نباشد پادشا بر پارسا</span> .<br /> <font color=\"Red\">ناصرخسرو.</font><br />هوی ̍ و هوس بر زاهد و پرهیزکار دست نیابد.<br /> <span class=\"hlight\">انسان (آدمی ) به آرزو زنده است </span> ؛ مایه ٔ سعی و جهد مردم امید باشد.<br /> <span class=\"hlight\">حاضربجنگ باش اگر صلحت آرزوست </span> ؛ برای حفظ صلح و آشتی باید قوی و مسلح بود(و این سفسطه ای است که نتیجه ٔ آن خرابی جهانست ).<br /> <span class=\"hlight\">کرا آرزو بیش تیمار بیش </span> ؛ هرکه را خواهش و اشتها بسیار بود غم و رنج بسیار است .<br /><span class=\"hlight\">نه هر آرزو آید آسان بدست </span> ؛ برای رسیدن به مطلوب تحمل تعب باید.<br /></font></div>'),
(1070, 'آرزو', '<span class=\"hlight\">آرزو.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) نام زن سلم <span class=\"hlight\">:</span> <br />زن سلم را کرد نام آرزوی <br />زن تور را نام آزاده خوی <br />زن ایرج نیک پی را سهی <br />کجا بد سهیلش بخوبی رهی .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> نام دختر ماهیار که بهرام گور او را بزنی کرد.<br /></font></div>'),
(1071, 'آرزو', '<span class=\"hlight\">آرزو.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) سراج الدین علی شاه . شاعر فارسی زبان ایرانی متوطن هند. وفات <span class=\"hlight\" dir=\"rtl\">١١٦٩</span> هَ . ق . مؤلف تذکره ٔ موسوم به تحفةالنفائس، معروف به تذکره ٔ آرزو و سراج اللغات و غرائب اللغات و مصطلحات الشعراء و شرح اسکندرنامه ٔ نظامی و غیره .<br /></font></div>'),
(1072, 'آرزو کشیدن', '<span class=\"hlight\">آرزو کشیدن .</span> <font color=\"DarkGreen\"><b>[ رِ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) آرزو بردن .<br /></font></div>'),
(1073, 'آرزوانه', '<span class=\"hlight\">آرزوانه .</span> <font color=\"DarkGreen\"><b>[ رِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) وَحم . ویارانه . آنچه آبستن از خوردنیها و غیرخوردنیهای عادی چون گِل و زغال آرزو کند خوردن را. <BR><font color=\"Blue\">◄</font> آنچه خویشان و کسان زن آبستن پزند و او را فرستند. <BR><font color=\"Blue\">◄</font> آنچه آرزو کنند. هوسانه . موضوع آرزو <span class=\"hlight\">:</span> آرزوانه همانقدر است که می بینی چو یک دم گذشت دگر بار آن ناآرزوانه شود و برنجاندت و این تن تو لقمه ٔ آرزوانه ٔتست . (کتاب المعارف ). پس با خود بس آی و ترک آرزوانه ٔ خود بگوی و این هوا پوست و آرزوانه مغز است، تو ازاین پوست و از این مغز بگذر تا بجنت مأوی برسی . (کتاب المعارف ). آرزوانه چو دانه ای است که در میان فَخَک باشد. (کتاب المعارف ).<br /></font></div>'),
(1074, 'آرزوانگیز', '<span class=\"hlight\">آرزوانگیز.</span> <font color=\"DarkGreen\"><b>[ رِ اَ ]</font></b> (نف مرکب ) مشهّی . شَهی ّ.<br /></font></div>'),
(1075, 'آرزوخواه', '<span class=\"hlight\">آرزوخواه .</span> <font color=\"DarkGreen\"><b>[ رِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) شهوی . شهوانی . <BR><font color=\"Blue\">◄</font> متمنی . راجی . مشتهی <span class=\"hlight\">:</span> <br />دل شه چو زآن نکته آگاه شد<br />از آن آرزو آرزوخواه شد.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(1076, 'آرزوسنج', '<span class=\"hlight\">آرزوسنج .</span> <font color=\"DarkGreen\"><b>[ رِ س َ ]</font></b> (نف مرکب ) آرزومند. آرزووَرز <span class=\"hlight\">:</span> <br />به خاک پای او چرخ آرزوسنج <br />چو درویش حریص و فکرت گنج .<br /><font color=\"Red\">امیرخسرو.</font><br /></font></div>'),
(1077, 'آرزومند', '<span class=\"hlight\">آرزومند.</span> <font color=\"DarkGreen\"><b>[ رِ م َ ]</font></b> (ص مرکب ) مشتاق . شایق <span class=\"hlight\">:</span> <br />فریدون نهاده دو دیده براه <br />سپاه و کلاه آرزومند شاه .<br /> <font color=\"Red\">فردوسی .</font><br />دوان آمد ازبهر آزارتان <br />همان آرزومند دیدارتان .<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاه شد خسرو از کارشان <br />نبود آرزومند دیدارشان .<br /> <font color=\"Red\">فردوسی .</font><br />همی راند حیران و پیچان براه <br />بخواب و <font color=\"DarkGreen\"><b>[ بخشک و؟ ]</font></b> به آب آرزومند شاه .<br /> <font color=\"Red\">فردوسی .</font><br />مثالها رفت بخراسان، بتعجیل ساخته شدن مردمانی که آرزومند خانه ٔ خدای عزّ و جل ّ بودند. (تاریخ بیهقی ).<br />آرزومند رخ شاه چو ماهم حافظ<br />همتی تا بسلامت ز درم بازآید.<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> حریص . آزوَر <span class=\"hlight\">:</span> <br />بپرسید دیگر که خرسند کیست <br />به بیشی ز چیز آرزومند کیست ؟<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> کامجوی . مرادطلب . حاجتمند. حاجتومند<span class=\"hlight\">:</span> <br />شنیده ام که بهشت آن کسی تواند یافت <br />که آرزو برساند به آرزومندی .<br /> <font color=\"Red\">شهید بلخی .</font><br /> <BR><font color=\"Blue\">◄</font> راجی . مرتجی . آرزوخواه . متمنی . مشتهی . <BR><font color=\"Blue\">◄</font> در حسرت . تمارزو. محتاج <span class=\"hlight\">:</span> <br />آرزومند آن شده تو بگور<br />که رسدنانْت پاره ٔ برزم . <br /> <font color=\"Red\">رودکی .</font><br />رفیقان او با زر و ناز و نعمت <br />پس او آرزومند یک تا زغاره .<br /> <font color=\"Red\">ابوشکور.</font><br />چنین است کیهان ناپایدار<br />در او تخم بد تا توانی مکار<br />یکی روز مرد آرزومند نان <br />دگر روز بر کشوری مرزبان .<br /> <font color=\"Red\">فردوسی .</font><br />تو شادان زی و خوش خور و به آرزو رس <br />بداندیش توآرزومند نانی .<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزومند بودن، آرزومند شدن </span> ؛ اشتیاق . (زوزنی ). حنین .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزومند کردن </span> ؛ تشویق .(دهّار).<br /></font></div>'),
(1078, 'آرزومندانه', '<span class=\"hlight\">آرزومندانه .</span> <font color=\"DarkGreen\"><b>[ رِ م َ دا ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) بحال آرزومندی . چون آرزومند.<br /></font></div>'),
(1079, 'آرزومندی', '<span class=\"hlight\">آرزومندی .</span> <font color=\"DarkGreen\"><b>[ رِ م َ ]</font></b> (حامص مرکب ) شوق . اشتیاق . پویه . تعطش . بَهْش . التیاع . توق . صبابت <span class=\"hlight\">:</span> <br />سحر با باد میگفتم حدیث آرزومندی <br />ندا آمد که واثق شو بالطاف خداوندی .<br /> <font color=\"Red\">حافظ.</font><br />ورای حد تقریر است شرح آرزومندی .<br /> <font color=\"Red\">حافظ.</font><br />حدیث آرزومندی که در این نامه ثبت افتد<br />همانا بی غلط باشد که حافظ داد تلقینم .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> تَحنّن . نُزوع . نِزاع . <BR><font color=\"Blue\">◄</font> غَرض .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزومندی نمودن </span> ؛ تَشوّق . تَنوّق .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزومندیها</span> ؛ آمال . اشواق . مُنی ̍. اهواء. اطماع . امانی . شهوات . حاجات .<br /></font></div>'),
(1080, 'آرزوناک', '<span class=\"hlight\">آرزوناک .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ص مرکب ) بسیارآرزو <span class=\"hlight\">:</span> <br />پی اظهار عشق آرزوناک <br />چو لعل از گرد تهمت دامنش پاک .<br /><font color=\"Red\">زلالی .</font><br /></font></div>'),
(1081, 'آرزوها', '<span class=\"hlight\">آرزوها.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِ) ج ِ آرزو. مُنی ̍. آمال . اطماع . اَمانی . اشواق . شهوات . اهواء. حاجات <span class=\"hlight\">:</span> امّا بمروت و حرّیت آن لایقتر که مرا بدین آرزوها برسانی . (کلیله و دمنه ).<br /></font></div>'),
(1082, 'آرزوکده', '<span class=\"hlight\">آرزوکده .</span> <font color=\"DarkGreen\"><b>[ رِ ک َدَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) کنایه از دنیاست . آرمان سرای .<br /></font></div>'),
(1083, 'آرزوگاه', '<span class=\"hlight\">آرزوگاه .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِ مرکب ) جای آرزو <span class=\"hlight\">:</span> <br />در آن آرزوگاه فرخاردیس <br />نکرد آرزو با معامل مکیس .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(1084, 'آرزوی', '<span class=\"hlight\">آرزوی .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِ) آرزو، در تمام معانی .<br /></font></div>'),
(1085, 'آرزوی دل', '<span class=\"hlight\">آرزوی دل .</span> <font color=\"DarkGreen\"><b>[ رِ ی ِ دِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مراد. کام . غایت مقصود <span class=\"hlight\">:</span> <br />آخر ای آرزوی دل تا کی <br />در دل این آرزو فروشکنم ؟<br /><font color=\"Red\">حسن غزنوی .</font><br /></font></div>'),
(1086, 'آرست', '<span class=\"hlight\">آرست .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) آلست . نشیمن حیوان . مَقعد.<br /></font></div>'),
(1087, 'آرستن', '<span class=\"hlight\">آرستن .</span> <font color=\"DarkGreen\"><b>[ رِ ت َ ]</font></b> (مص ) توانستن . یارستن . جرأت . تجرؤ. دلیری کردن . این مصدر صورتی از یارستن است و منفی یارستن را که نیارستن باشد میتوان منفی آرستن شمرد بتبدیل همزه بیاء <span class=\"hlight\">:</span> <br />دل جنگجویان ازاو شد بدرد<br />نیارد کسی رزم او یاد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />کس از نامداران و شاهان گُرد<br />چنین رنجها برنیارد شمرد.<br /> <font color=\"Red\">فردوسی .</font><br />کس این رازپیدا نیارست کرد<br />بماندند با درد و رخساره زرد.<br /> <font color=\"Red\">فردوسی .</font><br />نیارد شدن پیش گُرد گزین <br />نشیند براه وی اندر کمین .<br /> <font color=\"Red\">فردوسی .</font><br />بدرگاه خسرو بدی روز و شب <br />نیارست بر کس گشادن دو لب .<br /> <font color=\"Red\">فردوسی .</font><br />نیارست کردن کس آنجا گذر<br />زدیوان و پیلان و شیران نر.<br /> <font color=\"Red\">فردوسی .</font><br />کس از نامداران ایران سپاه <br />نیارست کردن بدو در نگاه .<br /> <font color=\"Red\">فردوسی .</font><br />ندارم سواری ورا هم نبرد<br />از ایران نیارد کس این کار کرد.<br /> <font color=\"Red\">فردوسی .</font><br />همی این بدان آن بدین گفت ماه <br />نیارد بدین شاه کردن نگاه .<br /> <font color=\"Red\">فردوسی .</font><br />هیچکس دانه در دهان نیارست نهادن از آن همی ترسیدند که نباید زهر باشد و هلاک شوند. (نوروزنامه ). و غلامان بیرون از قانون قرار و قاعده هیچ از رعایا نیارستندی خواست . (نوروزنامه ). و از آن پس کس طمع ایرانیان نیارست کردن . (مجمل التواریخ ). و رجوع به یارستن شود.<br /></font></div>'),
(1088, 'آرستن', '<span class=\"hlight\">آرستن .</span> <font color=\"DarkGreen\"><b>[ رَ ت َ ]</font></b> (مص ) مخفف آراستن <span class=\"hlight\">:</span> <br />بسیار مشو غره بدین حسن دلاویز<br />کاین حسن دلاویز تو از عشق من آرست .<br /><font color=\"Red\">سلمان ساوجی .</font><br /></font></div>'),
(1089, 'آرسته', '<span class=\"hlight\">آرسته .</span> <font color=\"DarkGreen\"><b>[ رِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) توانسته .<br /></font></div>'),
(1090, 'آرسته', '<span class=\"hlight\">آرسته .</span> <font color=\"DarkGreen\"><b>[رَ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف ) مخفف آراسته . مزین <span class=\"hlight\">:</span> <br />ایا ببزمگه آرسته تر ز صد حاتم <br />ایا بمعرکه مردانه تر ز صد سهراب .<br /> <font color=\"Red\">فرخی .</font><br />بنام و کنیتت آرسته بادا <br />ستایشگاه شعر و خطبه تا حشر.<br /><font color=\"Red\">عنصری .</font><br /></font></div>'),
(1091, 'آرسس', '<span class=\"hlight\">آرسس .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) نام پادشاه ایران، پسر اردشیر سوم، موسوم به اوخوس . و او را اندکی پس از استقرار بر اریکه ٔ ملک باگواس ِ خواجه سرا مسموم کرد. و این باگواس همان است که اردشیر دوم را نیز کشته بود (<span class=\"hlight\" dir=\"rtl\">٣٣٦</span> ق .م .).<br /></font></div>'),
(1092, 'آرسطولوخیا', '<span class=\"hlight\">آرسطولوخیا.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (معرب، اِ) (از یونانی آریسطولوخیا، مرکب از آریسطوس، اعلی و فاضل + لوخیا، زچگان یعنی زنان نوزائیده ) گیاهی است طبی که به فارسی زراوند گویند.و آن دو گونه است، مدور که آن را زراوند مدحرج و زراوند شامی و نخود الوندی و نخود مریم خوانند، و طویل که قثاءالحیة و زراوند طویل و شجره ٔ رستم و ببراله نامند، و قسم سومی از آن هست که خزان نکند و آن را به فارسی زراوند خوش و به عربی لعی و لعیة گویند. و ارسطولوخیا صورتی دیگر از این کلمه یاِمص حف آن است .<br /></font></div>'),
(1093, 'آرسکا', '<span class=\"hlight\">آرسکا.</span> (اِخ ) نام باستانی خبوشان که امروز بقوچان معروف است و آن را آشاک و استوا نیز مینامیده اند و مرکز خرّه ٔ سرولایت است .<br /></font></div>'),
(1094, 'آرش', '<span class=\"hlight\">آرش .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) جدّ اعلای اشکانیان . کی آرش <span class=\"hlight\">:</span> <br />کنون ای سراینده فرتوت مرد<br />سوی گاه اشکانیان بازگرد...<br />چنین گفت گوینده دهقان چاچ <br />کز آن پس کسی را نبد تخت و تاج <br />بزرگان که از تخم آرش بدند<br />دلیر و سبک سار و سرکش بدند<br />بگیتی بهر گوشه ای بر یکی <br />گرفته ز هر کشوری اندکی <br />چو بر تختشان شاد بنشاندند<br />ملوک طوائف همی خواندند...<br />نخست اشک بود از نژاد قباد<br />دگر گُرد شاپور خسرونژاد<br />دگر بود گودرز از اشکانیان <br />چو بیژن که بود از نژاد کیان <br />چو نرسی و چون اورمزد بزرگ <br />چو آرش که بد نامدار سترگ <br />چو زو بگذری نامدار اردوان ...<br />چوبنشست بهرام از اشکانیان <br />ببخشید گنجی به ارزانیان .<br /> <font color=\"Red\">فردوسی .</font><br />گرفتار شد اردوان <font color=\"DarkGreen\"><b>[ اشکانی ]</font></b> در میان <br />بداد از پی تاج ْ شیرین روان ...<br />دو فرزند او هم گرفتار شد<br />از او تخمه ٔ آرشی خوار شد.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1095, 'آرش', '<span class=\"hlight\">آرش .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِ) معنی . مقابل لفظ. (از برهان ). <BR><font color=\"Blue\">◄</font> تار. سَدی ̍. حابل . (زمخشری ).<br /></font></div>'),
(1096, 'آرش', '<span class=\"hlight\">آرش .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نام پسر دوم کیقباد برادر کیکاوس، و او را کی آرش گفتندی .<br /></font></div>'),
(1097, 'آرش', '<span class=\"hlight\">آرش .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نام پهلوانی کماندار از لشکر منوچهر. منوچهر در آخر دوره ٔ حکمرانی خویش از جنگ با فرمانروای توران، افراسیاب، ناگزیر گردید. نخست غلبه افراسیاب را بود و منوچهر بمازندران پناهید لکن سپس بر آن نهادند که دلاوری ایرانی تیری گشاد دهد و بدانجای که تیر فرود آید مرز ایران و توران باشد، آرش نام پهلوان ایرانی از قله ٔ دماوند تیری بیفکند که از بامداد تا نیمروز برفت و بکنار جیحون فرود آمد و جیحون حدّ شناخته شد. در اوستا بهترین تیرانداز را «اِرِخ ِش َ» نامیده و گمان میرود که مراد همان آرش است . طبری این کماندار را «آرش شاتین » می نامد و نولدکه حدس میزند این کلمه تصحیف جمله ٔ اوستائی «خَشووی ایشو» باشد چه معنی آن «خداوند تیر شتابنده » است که صفت یا لقب آرش بوده است . و بروایت دیگر رب النوع زمین (اسفندارمذ) تیر و کمانی به آرش داد و گفت این تیر دورپرتاب است لکن هرکه آن را بیفکند بجای بمیرد. و آرش با این آگاهی تن بمرگ درداد و تیر اسفندارمذ را برای سعه و بسط مرز ایران بدان صورت که گفتیم بیفکند و درحال بمرد. (از تاریخ ایران باستان حسن پیرنیا) <span class=\"hlight\">:</span> <br />چون کار بقفل و بند تقدیر افتد<br />از جیب خرد کلیدتدبیر افتد<br />آرش گهرم ولی چو برگردد بخت <br />در معرکه پیکان و پر از تیرافتد.<br /> <font color=\"Red\">خسروی .</font><br />از آن خوانند آرش را کمانگیر<br />که از آمل بمرو انداخت یک تیر<br />ترا زیبد نه آرش را سواری <br />که صد فرسنگ بگذشتی ز ساری .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />و افراسیاب تاختن ها آورد و منوچهر چند بار زال را پذیره فرستاد تاایشان را از جیحون زانسوتر کرده، پس یک راه افراسیاب با سپاهی بی اندازه بیامد و چند سال منوچهر را حصارداد اندر طبرستان و سام و زال غائب بودند و در آخر صلح افتاد به تیر انداختن آرش و از قلعه ٔ آمل با عقبه ٔ مزدوران برسید و آن مرز <font color=\"DarkGreen\"><b>[ را ]</font></b> توران خوانده اند. (مجمل التواریخ ) .<br /></font></div>'),
(1098, 'آرش', '<span class=\"hlight\">آرش .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نام کوهی .<br /></font></div>'),
(1099, 'آرش', '<span class=\"hlight\">آرش .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِمص ) اسم مصدر آردن آوردن .<br /></font></div>'),
(1100, 'آرش', '<span class=\"hlight\">آرش .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) اَرَش <span class=\"hlight\">:</span> <br />شاعر که دید به قدِ کاونجک <br />بیهوده گوی و نحسک و بوالکنجک <br />از ...ن خر فروتر و پنج آرش <br />می برجهد سبکتر اَز منجک .<br /><font color=\"Red\">منجیک .</font><br /></font></div>'),
(1101, 'آرش', '<span class=\"hlight\">آرش .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نامی از نامها <span class=\"hlight\">:</span> <br />وز آن دورتر آرش رزم یوز<br />چو گوران شه آن گرد لشکرفروز<br />یکی آنکه بر خوزیان شاه بود...<br />دگر شاه کرمان که هنگام جنگ <br />نکردی بدل یاد و رای درنگ .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1102, 'آرشی', '<span class=\"hlight\">آرشی .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ص نسبی ) معنوی، مقابل لفظی . (برهان ).<br /></font></div>'),
(1103, 'آرشی', '<span class=\"hlight\">آرشی .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (ص نسبی ) منسوب به آرش پهلوان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">تیر آرشی </span> ؛ تیری سخت دورپرتاب <span class=\"hlight\">:</span> <br />بزیر پی آن که هست آتشی <br />که سامیش گرز است و تیر آرشی .<br /> <font color=\"Red\">فردوسی .</font><br />منسوب به آرش سرسلسله ٔ سلاطین اشکانی :<br />دو فرزند او هم گرفتار شد<br />از او تخمه ٔ آرشی خوار شد.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1104, 'آرض', '<span class=\"hlight\">آرض .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (ع ن تف ) سزاوارتر. شایسته تر. اَلْیَق . اجدر. احری ̍. اولی ̍.<br /></font></div>'),
(1105, 'آرغ', '<span class=\"hlight\">آرغ .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِ) آروغ .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1106, 'آرغاده', '<span class=\"hlight\">آرغاده .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) نام رودخانه ایست . (برهان قاطع).<br /></font></div>'),
(1107, 'آرغامونی', '<span class=\"hlight\">آرغامونی .</span> (اِ) اَرغامونی . خشخاش مشوک . رجوع به اَرغامونی شود.<br /></font></div>'),
(1108, 'آرغدن', '<span class=\"hlight\">آرغدن .</span> <font color=\"DarkGreen\"><b>[ رُ دَ ]</font></b> (مص ) آشفتن . بخشم رفتن . <BR><font color=\"Blue\">◄</font> حریص شدن . حرص آوردن . شرهمند گشتن . آزور گردیدن .<br /></font></div>'),
(1109, 'آرغده', '<span class=\"hlight\">آرغده .</span> <font color=\"DarkGreen\"><b>[ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span>دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) حریص . آزور. شَرَهمند <span class=\"hlight\">:</span> <br />آرغده بر ثنای تو جان من است از آنک <br />پرورده ٔ مکارم اخلاق تو منم .<br /> <font color=\"Red\">منوچهری .</font><br /><BR><font color=\"Blue\">◄</font> مستی که باز طالب شراب باشد.<br /></font></div>'),
(1110, 'آرغده', '<span class=\"hlight\">آرغده .</span> <font color=\"DarkGreen\"><b>[ رُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آلغده . جنگاور. خشمگین . خشمناک . دژم . تافته . ارغنده . آشفته . برآشفته . بخشم آمده . خشمین . غضبناک . غضب آلود. خشمن . کج خلق . اوقات تلخ . قهرآلود. خشم آلود. مقابل آرمیده <span class=\"hlight\">:</span> <br />گهی آرَمْده و گه آرُغده <br />گهی آشفته و گه آهسته .<br /> <font color=\"Red\">رودکی .</font><br />سوی رزم آمد چو آرُغده شیر<br />کمندی ببازو سمندی بزیر.<br /> <font color=\"Red\">فردوسی .</font><br />سراپرده ای نیز دیدم بزرگ <br />سپاهی بکردار آرغده گرگ .<br /> <font color=\"Red\">فردوسی .</font><br />شیر آرُغده اگر پیش تو آید بنبرد<br />پیل آشفته اگر گرد تو گردد بجدال <br />پیل پیخسته ٔ صمصام تو بیند اندام <br />شیر پیرایه ٔ میدان تو یابد چنگال .<br /> <font color=\"Red\">فرخی .</font><br />اگر الفغده بستدند از من <br />نیست جانم چو شیر آرغده <br />شکر این حال چون توانم کرد<br />که مرا بستدند الفغده ؟<br /> <font color=\"Red\">ابوالفرج رونی .</font><br /> <br /></font></div>'),
(1111, 'آرغون', '<span class=\"hlight\">آرغون .</span> (اِخ ) رجوع به ارغون شود.<br /></font></div>'),
(1112, 'آرغیس', '<span class=\"hlight\">آرغیس .</span> (اِ) آرغیش . اَرغیس . پوست بیخ زرشک و او را در داروهای چشم بکار برند. (برهان ). عودالریح . این کلمه محتمل است مصحف بارباریس یا امبرباریس باشد.<br /></font></div>'),
(1113, 'آرق', '<span class=\"hlight\">آرق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) بیخواب شده . در شب بیدارمانده .<br /></font></div>'),
(1114, 'آرقالی', '<span class=\"hlight\">آرقالی .</span> (مغولی، اِ) آرغالی . اَرغالی . رجوع به اَرغالی شود.<br /></font></div>'),
(1115, 'آرل', '<span class=\"hlight\">آرل .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) نام قریه ای به ازینق درحلب و در آنجا زیارتگاهی است مشهور به مشهدالرحم .<br /></font></div>'),
(1116, 'آرم', '<span class=\"hlight\">آرم .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نام موضعی نزدیک مدینه ٔ رسول صلوات اﷲعلیه . <BR><font color=\"Blue\">◄</font> نام دهی نزدیک دهستان از قرای ساحلی بحر آبسکون . (یاقوت ).<br /></font></div>'),
(1117, 'آرم', '<span class=\"hlight\">آرم .</span> <font color=\"DarkGreen\"><b>[ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ]</font></b> (اِخ ) نام شهری بمازندران نزدیک ساری و از آنجاست خسروبن حمزه ٔ مؤدب . و رجوع به آرم دره شود.<br /></font></div>'),
(1118, 'آرمان', '<span class=\"hlight\">آرمان .</span> (اِ) حسرت . لهف . دریغ. اندوه . (مجمل اللغة). اَرمان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرمان خوردن </span> ؛ حسرت بردن .<br /> <BR><font color=\"Blue\">◄</font> آرزو. اَمَل <span class=\"hlight\">:</span> <br />هر حوائج را که بودش آرمان <br />راست کردی میر شهری رایگان .<br /> <font color=\"Red\">مولوی .</font><br />از فراقت روز و شب عشاق را هست الامان <br />هرکه دیدار تو بیند نیستش هیچ آرمان .<br /> <font color=\"Red\">خواجوی کرمانی .</font><br /> <BR><font color=\"Blue\">◄</font> امید. رجاء <span class=\"hlight\">:</span> <br />نه امّید آن کایچ بهتر شوی تو<br />نه ارمان آن کِم تو دل نگسلانی .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">بخورد و بمرد به از آرمان بگور</span> .<br /><span class=\"hlight\">کرده پشیمان نکرده آرمان </span> .<br /></font></div>'),
(1119, 'آرمان', '<span class=\"hlight\">آرمان .</span> (اِخ ) نامی از نامهای مردان <span class=\"hlight\">:</span> <br />چو کردوی شاپور و چون اندیان <br />سپهدار ارمینیه وْ آرمان <br />نشستند با شاه ایران براز<br />بزرگان فرزانه ٔ رزم ساز.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1120, 'آرمان خوار', '<span class=\"hlight\">آرمان خوار.</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) حسیر. حسران . حسر. حسرت خوار.<br /></font></div>'),
(1121, 'آرمان خوردن', '<span class=\"hlight\">آرمان خوردن .</span> <font color=\"DarkGreen\"><b>[خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ دَ ]</font></b> (مص مرکب ) تلهیف . (مجمل اللغة).<br /></font></div>'),
(1122, 'آرمان سرا', '<span class=\"hlight\">آرمان سرا.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) آرمان سرای . سرای حسرت . این جهان . ایرمان سرای .<br /></font></div>'),
(1123, 'آرمان فلوت', '<span class=\"hlight\">آرمان فلوت .</span> <font color=\"DarkGreen\"><b>[ ف ُ ]</font></b> (اِ مرکب ) نام سازی است .<br /></font></div>'),
(1124, 'آرمدن', '<span class=\"hlight\">آرمدن .</span> <font color=\"DarkGreen\"><b>[ رَ م ِ دَ ]</font></b> (مص ) آرمیدن .<br /></font></div>'),
(1125, 'آرمده', '<span class=\"hlight\">آرمده .</span> <font color=\"DarkGreen\"><b>[ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span>دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آرمیده . ساکن . بی حرکت <span class=\"hlight\">:</span> <br />گران ساخت سنگ و سبک باد پاک <br />روان کرد گردون و آرمده خاک .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> مجازاً، کاهل <span class=\"hlight\">:</span> <br />بود مرد آرمده در بند سخت <br />چو جنبنده گردد شود نیکبخت .<br /> <font color=\"Red\">عنصری .</font><br /> <BR><font color=\"Blue\">◄</font> خفته . <BR><font color=\"Blue\">◄</font> آهسته . نرم در رفتار <span class=\"hlight\">:</span> <br />چو بیدار باشی تو خواب آیدم <br />چو آرمده باشی شتاب آیدم .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> با خلق خوش . که در خشم نیست <span class=\"hlight\">:</span> <br />گهی آرمده و گه آرغده <br />گهی آشفته و گه آهسته .<br /><font color=\"Red\">رودکی .</font><br /></font></div>'),
(1126, 'آرمش', '<span class=\"hlight\">آرمش .</span> <font color=\"DarkGreen\"><b>[ رَ م ِ ]</font></b> (اِمص ) آرام . آرامش . اَون <span class=\"hlight\">:</span> <br />راه را هر کسی نمی شاید<br />پیر جوهرشناس می باید<br />تا ز خورشید پرورش یابد<br />در دل خلق آرمش یابد (کذا).<br /> <font color=\"Red\">شیخ آذری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرمش دادن </span> ؛ آرام بخشیدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرمش یافتن </span> ؛ آرام شدن .<br /></font></div>'),
(1127, 'آرمنده', '<span class=\"hlight\">آرمنده .</span> <font color=\"DarkGreen\"><b>[ رَ م َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه آرمیده است .<br /></font></div>'),
(1128, 'آرمه', '<span class=\"hlight\">آرمه .</span> <font color=\"DarkGreen\"><b>[ رِ م َ ]</font></b> (ع اِ) دندان . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> سال قحط.<br /></font></div>'),
(1129, 'آرموس', '<span class=\"hlight\">آرموس .</span> (اِخ ) نام جزیره ای متعلق بایران در بحر عمان . (از نزهةالقلوب ).<br /></font></div>'),
(1130, 'آرمیدن', '<span class=\"hlight\">آرمیدن .</span> <font color=\"DarkGreen\"><b>[ رَ دَ ]</font></b> (مص ) (شاید از: آ، ادات نفی و سلب + رمیدن ) آرامیدن . سکون . رکون . آرام شدن . استراحت . مستریح شدن . راحت یافتن . آسوده شدن . بیاسودن . آسودن . استقرار. قرار. آسایش . اِتّداع . انمهلال . خفتن . آرام گرفتن . قرار گرفتن . بی جنبش شدن <span class=\"hlight\">:</span> <br />بچنگ و بمنقار چندی طپید<br />چو شد زورش از تن سپس آرمید.<br /> <font color=\"Red\">فردوسی .</font><br />پراندیشه شد تا چه آمد پدید<br />که یارد بدین جایگه آرمید؟<br /> <font color=\"Red\">فردوسی .</font><br />بدانگه که تیره شب آمد به تنگ <br />گوان آرمیدند یکسر ز جنگ .<br /> <font color=\"Red\">فردوسی .</font><br />هر آنکس که چشمش سنان تو دید<br />که گوید کز آن پس روانْش آرمید؟<br /><font color=\"Red\">فردوسی .</font><br />هم از مهر مهتر دلش نارمید<br />چو باد دمان پیش رستم رسید.<br /> <font color=\"Red\">فردوسی .</font><br />نه شب خواب کرد و نه روز آرمید<br />نه می خورد نه نیز رامش گزید.<br /> <font color=\"Red\">فردوسی .</font><br />بگفت و برانگیخت شبدیز را<br />نداد آرمیدن دل تیز را.<br /> <font color=\"Red\">فردوسی .</font><br />چو بدخواه جنگی ببالین رسید<br />نباید ترا با سپاه آرمید.<br /> <font color=\"Red\">فردوسی .</font><br />دد و دام و هر جانور کش بدید<br />ز گیتی به نزدیک او آرمید.<br /> <font color=\"Red\">فردوسی .</font><br />همی رفت تا شهر رستم رسید<br />یکی روز جائی همی نارمید.<br /> <font color=\"Red\">فردوسی .</font><br />چو دانشگر این قولها بشنود<br />پس آنگه زمانی فروآرمد...<br /> <font color=\"Red\">طیّان .</font><br />بروز از هیچگونه نارمیدی <br />چو گور و آهو از مردم رمیدی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />گفت این علی تکین دشمنی بزرگ است از بیم سلطان ماضی آرمیده بود. (تاریخ بیهقی ).<br />سپاه آرمیدند بر جای خویش <br />همان شب مهان را بهو خواند پیش .<br /> <font color=\"Red\">اسدی .</font><br />بس بی آراما که بستد زو بی آرامی جهان <br />تا بیارامید و خود هرگز زمانی نارمید.<br /> <font color=\"Red\">ناصرخسرو.</font><br />که ما را نه چشم آرمید و نه گوش .<br /> <font color=\"Red\">سعدی .</font><br />ز یادملک چون ملک نارمند<br />شب و روز چون دد ز مردم رمند.<br /> <font color=\"Red\">سعدی .</font><br />بی تو از دردم آرمیدن نیست <br />وز توام طاقت بریدن نیست .<br /> <font color=\"Red\">کمال خجندی .</font><br /> <BR><font color=\"Blue\">◄</font> دوام کردن . باقی ماندن . مقام کردن <span class=\"hlight\">:</span> <br />چو ایدر نخواهی همی آرمید<br />بباید چرید و بباید چمید.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> زیستن <span class=\"hlight\">:</span> <br />بمردار خونش همی پرورید<br />ابا بچگانش همی آرمید.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرمیدن از چیزی </span> ؛ ترک گفتن آن <span class=\"hlight\">:</span> <br />ز تخت و ز آرامگه آرمید<br />بشدهر کسی روی او را بدید.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرمیدن از سخن </span> ؛ خاموش شدن . سکوت کردن <span class=\"hlight\">:</span> <br />برادر چو آواز خواهر شنید<br />ز گفتار و پاسخ فروآرمید.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرمیدن از کسی </span> ؛ فراموش کردن او <span class=\"hlight\">:</span> <br />ز رستم نخواهد جهان آرمید<br />نخواهد شدن نام او ناپدید.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرمیدن به (با) کسی </span> ؛ با او بسر بردن <span class=\"hlight\">:</span> <br />جهان چون من و چون تو بسیار دید<br />نخواهد همی با کسی آرمید.<br /> <font color=\"Red\">فردوسی .</font><br />الا ای خریدار مغز سخن <br />دلت برگسل زین سرای کهن <br />که او چون من و چون تو بسیار دید<br />نخواهد همی با کسی آرمید.<br /> <font color=\"Red\">فردوسی .</font><br />اگر گیتی بیک شاه آرمیدی <br />ز کیخسرو بخسرو کی رسیدی ؟<br /> <font color=\"Red\">نظامی .</font><BR>۩ مصاحبت کردن . هم بستر شدن <span class=\"hlight\">:</span> زبیده بر عباسه حسد بردی ازبهر آنکه خلیفه مادام با وی آرمیدی . (تاریخ برامکه ).<BR>۩ مواقعه کردن . درآمیختن با.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">در آن دلی که طلب هست آرمیدن نیست </span> .<br />صرف این فعل منتظم است .<br /></font></div>'),
(1131, 'آرمیده', '<span class=\"hlight\">آرمیده .</span> <font color=\"DarkGreen\"><b>[ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آسوده . مستریح . ساکن . بی حرکت . ساکت . خفته . خوابیده . آرام . آرام گرفته . مقابل جنبان و جنبنده <span class=\"hlight\">:</span> <br />از ما رها شدی دگری را رهی شدی <br />از ما رمیده با دگری آرمیده ای .<br /> <font color=\"Red\">شهره ٔ آفاق (از صحاح الفرس ).</font><br />ز کارآگهان آنکه بدرهنمای <br />بیامد به نزدیک پرده سرای <br />بجائی غو پاسبانی ندید<br />جز از آرمیده جهانی ندید.<br /> <font color=\"Red\">فردوسی .</font><br />محرّک نخستین، جنبنده نشاید وزبهر این او را آرمیده کردند... و گروهی جسم نهادند آرمیده ٔ بی کرانه . (التفهیم ).<br />یکی بین آرمیده در غنا غرق <br />یکی پویان و سرگشته ز افلاس .<br /> <font color=\"Red\">سنائی .</font><br />صدف حیران بدریا در دوان آهوبصحرا در<br />رمیده و آرمیده هر دو در دریا و در هامون .<br /> <font color=\"Red\">سنائی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرمیده خواندن </span> ؛ همواره خواندن . ترتیل .<br /></font></div>'),
(1132, 'آرمیدگی', '<span class=\"hlight\">آرمیدگی .</span> <font color=\"DarkGreen\"><b>[ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) حالت و چگونگی آرمیده . طمأنینه . آرامش . آرام .<br /></font></div>'),
(1133, 'آرن', '<span class=\"hlight\">آرن .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (یونانی، اِ) گیاهی است که آن را لوف گویند. قسم بزرگ آن لوف الکبیر و شجرةالتنین و آرن مطلق، و قسم کوچک آن لوف الصغیر و خبزالقرود و آذان الفیل و پیلگوش و فیلغوش و فیلگوش و فیلجوش و رجل العجل، و قسم دیگر آن لوف الحیه و دراقیطون و لوف مستطیل، و قسم چهارم آن لوف الجعدة، و قسم پنجم آن قلقاس نامیده میشود. و رجوع به آرن صارن شود.<br /></font></div>'),
(1134, 'آرن', '<span class=\"hlight\">آرن .</span><font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) بندگاه میان ساعد و بازو از برون سوی یعنی جانب وحشی . آرنج . وارن . رونکک . مرفق <span class=\"hlight\">:</span> <br />زمانی دست کرده جفت رخسار<br />زمانی جفت زانوکرده آرن .<br /><font color=\"Red\">آغاجی .</font><br /></font></div>'),
(1135, 'آرن صارن', '<span class=\"hlight\">آرن صارن .</span> <font color=\"DarkGreen\"><b>[ رُ رُ ]</font></b> (از یونانی، اِ) (از یونانی به قول صاحب مخزن ) لوف الصغیر. پیلغوش . پیلگوش . فیلجوش . خبزالقرود. رجل العجل . دراقیطس . و رجوع به آرُن شود.<br /></font></div>'),
(1136, 'آرناوود', '<span class=\"hlight\">آرناوود.</span> (اِخ ) اَرناوود. نام مردم آلبانی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آرناوود</span> ؛ زنی بلندآواز و بی حیا و دشنام گوی .<br /></font></div>'),
(1137, 'آرنج', '<span class=\"hlight\">آرنج .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) مفصل و بند و میان بازو و ساعد از طرف وحشی . مرفق . آرج .آرن . آران . وارَن . وارنج . آرنگ . رونکک <span class=\"hlight\">:</span> <br />گهی ببازی بازوش را فراشته داشت <br />گهی به رنج جهان اندرون بزد آرنج .<br /> <font color=\"Red\">ابوشکور.</font><br />آستین ازبرای رنج و الم <br />تا به آرنج برزنی هر دم .<br /> <font color=\"Red\">اسدی (از شعوری ).</font><br />زبهر سنگ ملمع که آیدت در دست <br />بسا کسان که شکستی بسنگشان آرنج .<br /> <font color=\"Red\">امیرخسرو دهلوی .</font><br /><BR><font color=\"Blue\">◄</font> یاز. ذراع . اَرَش .<br /></font></div>'),
(1138, 'آرنده', '<span class=\"hlight\">آرنده .</span> <font color=\"DarkGreen\"><b>[ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) مخفف آورنده <span class=\"hlight\">:</span> <br />فرستاده آرنده ٔ نامه بود<br />مرا پاسخ نامه این جامه بود.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1139, 'آرنگ', '<span class=\"hlight\">آرنگ .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) آرنج . مرفق . آرج . وارن <span class=\"hlight\">:</span> <br />گر بعهد تو ظلم یازد چنگ <br />باد دستش بریده از آرنگ .<br /> <font color=\"Red\">منصور شیرازی .</font><br /> <BR><font color=\"Blue\">◄</font> رنج . اذیت . آزار <span class=\"hlight\">:</span> <br />گشته ترا مسلم شوق و نشاط و اقبال <br />بوده نصیب دشمن آرنگ و رنگ و ادبار.<br /> <font color=\"Red\">غضایری رازی .</font><br />چو کاری برآید بی آرنگ و رنج <br />چه باید ترا رنج و پردخت گنج ؟<br /> <font color=\"Red\">اسدی .</font><br />نه هرگز از تو رسیده بموری آرنگی <br />نه هرگز ازتو رسیده بمردی آزاری .<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> گونه . رنگ . لون <span class=\"hlight\">:</span> <br />از من خوی خوش گیر از آنکه گیرد<br />انگور ز انگور رنگ و آرنگ .<br /> <font color=\"Red\">مظفری (از فرهنگ اسدی ).</font><br />آرنگ زرد باد چو نارنگ روی خصم <br />باداش سر بریده چو سرکفته بادرنگ .<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />زآن خردمند سرو سبزآرنگ <br />خواست تا از شکر گشاید تنگ .<br /> <font color=\"Red\">نظامی .</font><br />ای عجب شمشیر خسرو از چه سبزآرنگ شد<br />چون همه ساله ز خون خصم می یابد خورش .<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> مکر. حیله . فریب <span class=\"hlight\">:</span> <br />بر طبل قمر همی زند رایت <br />کای شاهدپیشه این چه آرنگ است ؟<br /> <font color=\"Red\">شرف شفروه .</font><br /> <br /> <BR><font color=\"Blue\">◄</font> نام میوه ای . (برهان ) . <BR><font color=\"Blue\">◄</font> حاکم و مرزبان . <BR><font color=\"Blue\">◄</font> گونه که زنان بر روی مالند. (فرهنگ اسدی، خطی ) . آلغونه . آلگونه . <BR><font color=\"Blue\">◄</font> گونه و روش و طرز، چنانکه گویند بر این آرنگ یعنی بدین طرز و روش . (برهان قاطع). <BR><font color=\"Blue\">◄</font> (ق ) همانا. گوئی . پنداری <span class=\"hlight\">:</span> <br />هرگز نکند سوی من خسته نگاهی <br />آرنگ نخواهد که شود شاد دل من .<br /> <font color=\"Red\">رودکی .</font><br />و کلمه ٔآرنگ را در بیت رودکی به معنی هرگز نیز حدس زده اند.<br /></font></div>'),
(1140, 'آره', '<span class=\"hlight\">آره .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نام وادئی به اندلس و آن را یاره نیز نامند. <BR><font color=\"Blue\">◄</font> نام دو جای دیگر به اندلس . <BR><font color=\"Blue\">◄</font> نام شهری به بحرین . <BR><font color=\"Blue\">◄</font> نام کوهی بحجاز میان مکه و مدینه . <BR><font color=\"Blue\">◄</font> کوهی قبیله ٔ مزینه را.<br /></font></div>'),
(1141, 'آره', '<span class=\"hlight\">آره .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نام دماغه ای در آخرین نقطه ٔ جنوبی جزیرةالعرب و آن را رأس آره نیز گویند و آن به <span class=\"hlight\" dir=\"rtl\">٢٥</span> هزارگزی مشرق باب المندب است .<br /></font></div>'),
(1142, 'آره', '<span class=\"hlight\">آره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) حفره ای که دندان در آن جای دارد <span class=\"hlight\">:</span> <br />بادام چشمکانت رخنه شود موسه (کذا)<br />وآن سی ّودو گهرها هم بگسلد ز آره .<br /><font color=\"Red\">خسروی .</font><br /></font></div>'),
(1143, 'آره', '<span class=\"hlight\">آره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) نوعی از لکنت و آن بحرف «راء» گشتن زبان باشد.<br /></font></div>'),
(1144, 'آره نان', '<span class=\"hlight\">آره نان .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نام محلی کنار راه سنندج و مریوان، میان سنندج و گردنه ٔ آریز در <span class=\"hlight\" dir=\"rtl\">١٣٠٠٠</span> گزی سنندج .<br /></font></div>'),
(1145, 'آرهن', '<span class=\"hlight\">آرهن .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) نام شهری از طخیرستان از اعمال بلخ .<br /></font></div>'),
(1146, 'آرو', '<span class=\"hlight\">آرو.</span> (اِخ ) نام موضعی از توابع طهران دارای معدن ذغال سنگ .<br /></font></div>'),
(1147, 'آرواره', '<span class=\"hlight\">آرواره .</span> <font color=\"DarkGreen\"><b>[ وا رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) (از: آر، مخفف آره، حفره ٔ دندان + واره، جای ) هر یک از دو قطعه استخوان که دندانهای فوقانی و تحتانی بر آن جای دارد. <BR><font color=\"Blue\">◄</font> تَوَسُعاً، فَک . و رجوع به حاشیه ٔ کلمه ٔ آره شود.<br /></font></div>'),
(1148, 'آروبند', '<span class=\"hlight\">آروبند.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (نف مرکب ) آنکه داند استخوان شکسته و ازجای برآمده را بهم پیوندد و جبر کند و یا بجای اندازد و ردّ کند. استخوان بند. اشکسته بند. شکسته بند. چک بند. ردّاد. مُجبّر. جبار.<br /></font></div>'),
(1149, 'آروبندی', '<span class=\"hlight\">آروبندی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (حامص مرکب ) عمل آروبند. جبر و ردّ عظام . پیوستن استخوان شکسته . بجای افکندن استخوان ازجای بگشته .<br /></font></div>'),
(1150, 'آروغ', '<span class=\"hlight\">آروغ .</span> (اِ) باد معده که از گلو برآید گاه ِ امتلاء، بی اراده و غالباً با آوازی که بوقت فقاع خوردن و چیزهای باد و دم دار مردم را افتد و آن تنفس معده باشد از راه گلو. زراغن . گوارش . باد گلو.آجل . رجک . جشاء. آرغ . زروغ . روغ . وروغ <span class=\"hlight\">:</span> <br />گر در حکایت آید بانگ شتر کند<br />وآروغها زند چو خورد ترب و گندنا.<br /> <font color=\"Red\">لبیبی .</font><br />زامتلا هضم نیابد بدوصد کوزه فقاع <br />گر کسی نان خورد و بر درش آروغ زند.<br /> <font color=\"Red\">انوری .</font><br />همیشه لب مرد بسیارخوار<br />در آروغ بد باشد از ناگوار.<br /> <font color=\"Red\">نظامی .</font><br />گیرد چوصبح آروغ از قرص آفتاب <br />آن را که تو بخوان کرم میهمان کنی .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />ز امتلا چو قناعت همی زند آروغ <br />ز خوان جود وی از بس که خورده معده ٔ آز.<br /> <font color=\"Red\">کمال اسماعیل .</font><br />این پیر گشته را که نبد آب در جگر<br />آروغ امتلا زند اکنون ز خوان شکر.<br /> <font color=\"Red\">کمال اسماعیل .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آروغ دادن، آروغ زدن </span> ؛ آروغ افتادن کسی را. آروغ کردن . تَجَشﱡؤ. و بمسامحه اوحدی آروق گفته و با عیوق قافیه کرده است . رجوع به حاشیه ٔ کلمه ٔ آرغ شود.<br /></font></div>'),
(1151, 'آروق', '<span class=\"hlight\">آروق .</span> (اِخ ) نام محلی در <span class=\"hlight\" dir=\"rtl\">٢٧٠٠</span>گزی دوراهه ٔ بناب، میان قلعه جق و حسین آباد.<br /></font></div>'),
(1152, 'آروق', '<span class=\"hlight\">آروق .</span> (اِ) این کلمه را اوحدی به معنی آروغ آورده و با عیّوق قافیه کرده است و این تسامحی است شایسته ٔ بی قیدی و وارستگی این مرد <span class=\"hlight\">:</span> <br />با چنین خوردن و چنین آروق <br />کی بری رخت خویش بر عیّوق ؟<br /><font color=\"Red\">اوحدی .</font><br /></font></div>'),
(1153, 'آرون', '<span class=\"hlight\">آرون .</span> (اِ) صفت نیک . خصلت حمیده . خوی خوش <span class=\"hlight\">:</span> <br />به آرون او نیست در بوم و رست <br />جهان را به آرون و آذین بست (کذا).<br /> <font color=\"Red\">عنصری .</font><br /> <br /></font></div>'),
(1154, 'آرون', '<span class=\"hlight\">آرون .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ) آبکش . ترشی پالا. زازل . رجوع به آردن شود. و ظاهراً یکی از دو صورت مصحف دیگریست .<br /></font></div>'),
(1155, 'آروند', '<span class=\"hlight\">آروند.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ) اَرْوَند. اورند. شأن و شوکت و فر و شکوه . (برهان ). رجوع به اورند و اورنگ شود.<br /></font></div>'),
(1156, 'آروپناهی', '<span class=\"hlight\">آروپناهی .</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (اِخ ) رجوع به محمود صالح (طائفه ٔ...) شود.<br /></font></div>'),
(1157, 'آروین', '<span class=\"hlight\">آروین .</span> <font color=\"DarkGreen\"><b>[ آرْ ]</font></b> (اِ) اَرْوین . تجربه . آزمایش . امتحان . آزمون .<br /></font></div>'),
(1158, 'آرپا', '<span class=\"hlight\">آرپا.</span> (اِخ ) نام آب راهه و رافده ای در قفقاز که به رود اَرَس پیوندد.<br /></font></div>'),
(1159, 'آرپه', '<span class=\"hlight\">آرپه .</span> <font color=\"DarkGreen\"><b>[ پ َ <span class=\"hlight\" dir=\"rtl\">/</span> پ ِ ]</font></b> (ترکی، ص ) باریک .<br /></font></div>'),
(1160, 'آرژانتین', '<span class=\"hlight\">آرژانتین .</span> (اِخ ) نام جمهوری متحده ای است در امریکای جنوبی در شرق شیلی، از شمال محدود به برزیل، پرو و بولیوی و از مشرق به اوقیانوس آتلانتیک . بوئنوس آیرس کرسی آن است . <span class=\"hlight\" dir=\"rtl\">١١</span>میلیون سکنه دارد. وسعت آن <span class=\"hlight\" dir=\"rtl\">٢٧٩٤٠٠٠</span> کیلومتر مربع باشد. زبان مردم آن اسپانیولی . صادرات آنجا غله، نیشکر، کتان، ستور و نفط است .<br /></font></div>'),
(1161, 'آرک', '<span class=\"hlight\">آرک .</span> <font color=\"DarkGreen\"><b>[ رِ]</font></b> (ع ص ) حیوان که اراک چرد. (ربنجنی ). ج، اوارِک .<br /></font></div>'),
(1162, 'آرکادیوس', '<span class=\"hlight\">آرکادیوس .</span>(اِخ ) پسر تئودُز، عظیم روم شرقی (<span class=\"hlight\" dir=\"rtl\">٣٩٥</span> - <span class=\"hlight\" dir=\"rtl\">٤٠٨</span> م .).<br /></font></div>'),
(1163, 'آری', '<span class=\"hlight\">آری .</span> (ق ) کلمه ای است برای تصدیق در پاسخ استفهام ثبوتی . بلی . ها. ای . نعم . اجل . مقابل نه، نی <span class=\"hlight\">:</span> <br />چنین گفت آری شنیدم پیام <br />دلم شد بدیدار تو شادکام .<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ بدو کندرو<br />که آری شنیدم تو پاسخ شنو.<br /> <font color=\"Red\">فردوسی .</font><br />گفت این پیغام خداوند بحقیقت می گذاری ؟ گفتم آری . (تاریخ بیهقی ).<br />کاین از آن جام هست ؟ - گفت آری .<br /> <font color=\"Red\">سنائی .</font><br />شیر گفت آری پدرش راشناختم . (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> و گاه برای تأکید و تأیید گفته ای آرند <span class=\"hlight\">:</span> <br />هرچند حقیرم سخنم عالی و شیرین <br />آری عسل شیرین ناید مگر از منج .<br /> <font color=\"Red\">منجیک .</font><br />آری چو پیش آید قضا مروا شود چون مرغوا<br />جای شجر گیرد گیا جای طرب گیرد شجن .<br /> <font color=\"Red\">معزی .</font><br />آری این اسب است لیک آن آب کو<br />با خود آ ای شهسوار اسب جو.<br /> <font color=\"Red\">مولوی .</font><br />حسنت باتفاق ملاحت جهان گرفت <br />آری باتفاق جهان میتوان گرفت .<br /> <font color=\"Red\">حافظ.</font><br />کبک آری می بخندد چون به بیند کوهسار.<br /><font color=\"Red\">قاآنی .</font><br /></font></div>'),
(1164, 'آری', '<span class=\"hlight\">آری .</span> (اِخ ) نام یکی از طوایف چادرنشین بندپی از بخشهای مازندران .<br /></font></div>'),
(1165, 'آری', '<span class=\"hlight\">آری .</span> <font color=\"DarkGreen\"><b>[ ری ی ]</font></b> (ع اِ) آخیه . اَخیه . میخ آخور. (مهذب الاسماء). ستوربند. ج، اواری ّ.<br /></font></div>'),
(1166, 'آری', '<span class=\"hlight\">آری .</span> (اِخ ) آریا. نام ایالت قدیم ایران که امروز مشتمل بر خراسان شرقی و سیستان است و نام کرسی آن در قدیم آرتاکوآنا بوده است و اسکندر شهری به نام اسکندریّه ٔ آره ایا در کنار هری رود بنا کرد و جمعیت و آبادی آن را بدین شهرکه شاید هرات امروزین باشد تحویل کرد.<br /></font></div>'),
(1167, 'آریا', '<span class=\"hlight\">آریا.</span> (اِخ ) رجوع به آری شود.<br /></font></div>'),
(1168, 'آریز', '<span class=\"hlight\">آریز.</span> (اِخ ) نام محلی براه سنندج و مریوان میان گردنه ٔ آریز و تودار در <span class=\"hlight\" dir=\"rtl\">٢٧</span>هزارگزی سنندج .<br /></font></div>'),
(1169, 'آریستارک شامسی', '<span class=\"hlight\">آریستارک شامسی .</span> <font color=\"DarkGreen\"><b>[ ک ِ م ُ ]</font></b> (اِخ ) نام ستاره شناسی یونانی در مائه ٔ سیم ق .م . نخستین کس که به حرکت انتقالی زمین یعنی گردش آن به دور آفتاب و نیز حرکت وضعی آن یعنی گردیدن بر محور خویش پی برده است .<br /></font></div>'),
(1170, 'آریستفان', '<span class=\"hlight\">آریستفان .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (اِخ ) اَریستفان . نام شاعر فکاهی مشهور آطنه (آتن ) در مائه ٔپنجم ق .م . او در اشعار خود برسوم و آداب و عادات زمان سخت تاخته و نامه هائی از مضاحک چون نامه ٔ غوکان، زنبوران، سواران، مرغان و مضحکه ٔ باستانی و جز آن دراین زمینه پرداخته است . و رجوع به اَریستفان شود.<br /></font></div>'),
(1171, 'آریسته', '<span class=\"hlight\">آریسته .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) نام پسر اَفولُن . آموزنده ٔ تربیت نحل .<br /></font></div>'),
(1172, 'آریغ', '<span class=\"hlight\">آریغ.</span> (اِ) کراهت و کینه یا نفرتی که از قول یا فعل کسی در دل گیرند. دل سردی <span class=\"hlight\">:</span> <br />آه از غم آن نگار بدمهر<br />کآریغ ز من بدل گرفته .<br /> <font color=\"Red\">خسروانی .</font><br />آزیغ را نیز بمعانی مذکوره در فرهنگها ضبط کرده اند و ظاهراً یکی تصحیف دیگریست .<br /></font></div>'),
(1173, 'آریم', '<span class=\"hlight\">آریم .</span> (اِخ ) نام قریه ای در خره ٔ خانقاه پی مازندران .<br /></font></div>'),
(1174, 'آریه', '<span class=\"hlight\">آریه .</span> <font color=\"DarkGreen\"><b>[ ری ی َ ]</font></b> (ع اِ) (شاید از ریشه ٔ فارسی آرواره ) سوراخ که دندان در آن جای دارد. (بحرالجواهر). <BR><font color=\"Blue\">◄</font> آری ّ. آخیه که چهارپایان را بدان بندند. معلف . ج، اواری .<br /></font></div>'),
(1175, 'آریه', '<span class=\"hlight\">آریه .</span> <font color=\"DarkGreen\"><b>[ رِ ی ِ ]</font></b> (اِخ ) نام سپهدار ایرانی طرفدار پادشاهی کوروش صغیر. این سپهدار در جنگ کوناکزا در <span class=\"hlight\" dir=\"rtl\">٤٠١</span> ق .م . فرمانده میسره ٔ سپاه بود. پس از شکست کوروش دوستی خود را با یونانیان نگاه داشت و نقشه ٔ بازگشت ده هزار سرباز مزدور یونانی را او طرح کرد، لیکن عاقبت به اردشیر م ِنُن پیوست .<br /></font></div>'),
(1176, 'آریوس باغوس', '<span class=\"hlight\">آریوس باغوس .</span> (اِخ ) رجوع به اَریوس باغوس شود.<br /></font></div>'),
(1177, 'آز', '<span class=\"hlight\">آز.</span> (اِ) زیاد جُستن . زیاده جوئی . افزون خواهی . افزون طلبی . خواهش بسیاری از هر چیز. طمع. ولع. حرص . شره . شُح ّ. تنگ چشمی <span class=\"hlight\">:</span> <br />از فرطعطای او زند آز<br />پیوسته ز امتلا زراغن .<br /> <font color=\"Red\">ابوسلیک .</font><br />جاه است و قدر و منفعه آن را که طَمْع نه <br />عز است و صدر و مرتبه آن را که آز نیست .<br /> <font color=\"Red\">خسروانی .</font><br />مکن امّید دور و آز دراز<br />گردش چرخ بین چه کرمند است .<br /> <font color=\"Red\">خسروی .</font><br />بدی در جهان بدتر از آز نیست .<br /> <font color=\"Red\">فردوسی .</font><br />بهر جای جاه وی افزون کنم <br />ز دل کینه و آز بیرون کنم .<br /> <font color=\"Red\">فردوسی .</font><br />میاز ایچ با آز وبا کینه دست <br />بمنزل مکن جایگاه نشست .<br /> <font color=\"Red\">فردوسی .</font><br />چو دانی که بر تو نماند جهان <br />چه رنجانی از آز جان و روان ؟<br /> <font color=\"Red\">فردوسی .</font><br />چنین بود تا بود این تیره روز<br />تو دل را به آز فزونی مسوز.<br /> <font color=\"Red\">فردوسی .</font><br />چه سودت بسی اینچنین رنج و آز<br />که از بیشتر کم نگردد نیاز؟<br /> <font color=\"Red\">فردوسی .</font><br />گرت دل نه با رای آهرمن است <br />سوی آز منگر که او دشمن است .<br /> <font color=\"Red\">فردوسی .</font><br />که چون آز گردد ز دلها تهی <br />همان خاک و هم گنج شاهنشهی .<br /> <font color=\"Red\">فردوسی .</font><br />ز آز و فزونی بیکسو شویم <br />بنادانی خویش خستو شویم <br />مگر بهرمان زین سرای سپنج <br />نباید همی کین و نفرین و رنج .<br /> <font color=\"Red\">فردوسی .</font><br />دگر آز بر تو چنان چیره گشت <br />که چشم خرد مرترا خیره گشت <br />ز بیچارگان خواسته بستدی <br />ز نفرین بروی تو آمد بدی .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت <font color=\"DarkGreen\"><b>[ به باربد ]</font></b> هر کس که شاه جهان <br />گزیده ست رامشگری در نهان <br />که گر با تو او را برابر کنند<br />ترابر سر سرکش افسر کنند<br />چو بشنید مرد آن بجوشیدش آز<br />و گرچه نبودش بچیزی نیاز.<br /> <font color=\"Red\">فردوسی .</font><br />به تخت خرد برنشست آزتان <br />چرا شد چنین دیو انبازتان ؟<br /> <font color=\"Red\">فردوسی .</font><br />در آز باشد دل سفله مرد<br />برِ سفلگان تا توانی مگرد.<br /> <font color=\"Red\">فردوسی .</font><br />چو بستی کمر بر در راه آز<br />شود کار گیتیت یکسر دراز.<br /> <font color=\"Red\">فردوسی .</font><br />اگر پادشاه آز گنج آورد<br />تن زیردستان به رنج آورد.<br /> <font color=\"Red\">فردوسی .</font><br />بخور آنچه داری و بیشی مجوی <br />که از آز کاهد همی آبروی .<br /> <font color=\"Red\">فردوسی .</font><br />تن مرد بی آز بهتر که گنج .<br /> <font color=\"Red\">فردوسی .</font><br />جهان چون بر او برنماند ای پسر<br />تو نیز آز مپْرست انده مخور.<br /> <font color=\"Red\">فردوسی .</font><br />از آن پس که بنمود پنجاه و هشت <br />بسربر فراوان شگفتی گذشت <br />همی آز کمتر نگردد بسال <br />همی روز جویم بتقویم و فال .<br /> <font color=\"Red\">فردوسی .</font><br />گنه کارتر چیز مردم بود<br />که از کین و آزش خرد گم بود.<br /> <font color=\"Red\">فردوسی .</font><br />مکن آز را بر خرد پادشا<br />که دانا نخواند ترا پارسا.<br /> <font color=\"Red\">فردوسی .</font><br />اگر جان تو بسپرد راه آز<br />شود کار بی سود بر تو دراز.<br /> <font color=\"Red\">فردوسی .</font><br />پریدند بسیار و ماندند باز<br />چنین باشد آنکس که گیردْش آز.<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ که آز و نیاز<br />دو دیوند با زور و گردنفراز.<br /> <font color=\"Red\">فردوسی .</font><br />چو کردی توبر دل در آز باز<br />شود رنج گیتی بتو بر دراز.<br /> <font color=\"Red\">فردوسی .</font><br />چو این چار با یک تن آید بهم <br />برآساید از آز و از رنج و غم .<br /> <font color=\"Red\">فردوسی .</font><br />بستان کشور جود وبفشان زرّ و درم <br />بشکن لشکر بخل و بفکن بُنگه آز.<br /> <font color=\"Red\">منوچهری .</font><br />هست حرص او بمال و خواسته ازبهر جود<br />چون غرض چونین بود محمود باشد حرص و آز.<br /> <font color=\"Red\">منوچهری .</font><br />هر آن سر که او آز را افسر است <br />به خاک اندر است ار ز مه برتراست .<br /> <font color=\"Red\">اسدی .</font><br />بود خیره دل سال و مه مرد آز<br />کَفَش بسته همواره و چشم باز.<br /> <font color=\"Red\">اسدی .</font><br />ز طمع است کوته زبان مرد آز<br />چو شد طمع کوته زبان شد دراز.<br /> <font color=\"Red\">اسدی .</font><br />دل از آز گیتی چه پرکرده ای <br />از او چون بری آنچه ناورده ای ؟<br /> <font color=\"Red\">اسدی .</font><br />جهان دامداری است نیرنگ ساز<br />هوای دلش چینه و دام آز.<br /> <font color=\"Red\">اسدی .</font><br />بر سر بخت بد فرود آید<br />هرکه گیرد عنان مرکبش آز.<br /> <font color=\"Red\">ناصرخسرو.</font><br />آزاد شد از بندگی آز مرا جان <br />آزاد شو از آز و بزی شاد و توانگر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />طعام ذل ّ و خواری خورد باید<br />کسی را کش برآرد آز دندان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />صد شکر خداوند را که آزم <br />کم شد چو فزون شدشمار سالَم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آزت هر روز بفردا دهد<br />وعده ٔ چیزی که نباشد چنان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />اگر جفت آزی نه آزاده ای <br />ازیرا که این زآن و آن زین جداست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />به هر خیر دوجْهانی امید دار<br />گر از بند آزت امید رهاست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />پیراهن آز برکش از گردن <br />وز گرد محال شانه زن طرّه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />این آز بود ای پسر نه دانش <br />یکباره چنین خر مباش و شاهی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چرا در جستن دانش نگیرد آزت ای نادان <br />اگر در جستن چیزی که آنت نیست باآزی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آز تو دیو است چندین چون رها جوئی ز دیو<br />تو رها کن دیو را تا زو بباشی خود رها.<br /><font color=\"Red\">ناصرخسرو.</font><br />کآتش آز چون فروخته شد<br />کرد بایدْت روی خویش کباب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دشمنانند مرا خوی بد و آز و هوی ̍<br />از هوی ̍ خیزم و بگریزم از آز و خوم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />زشت بار است ای برادر بار آز<br />دور بفکن بار آز از پشت و یال .<br /> <font color=\"Red\">ناصرخسرو.</font><br />زین اسب آز ذل ّ است ای پسر<br />نعل او خواری عنان او سؤال .<br /> <font color=\"Red\">ناصرخسرو.</font><br />با آز هگرز دین نیامیزد<br />تو رانده ز دین بلشکر آزی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />این آز نهنگیست همانا که نپرسد<br />از گرْسنگی خویش حرامی ز حلالی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آز نگردد ابداً گرد آنک <br />در شکم مادر گردد غنی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نپردازی براز ایزدی تو<br />که زیر بند جهل و بار آزی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آز ترا گل نماید ای پسر از دور<br />لیک نباشد گلش مگرهمه جز خار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />از دنائت شمر قناعت را<br />همتت را که نام کرده ست آز.<br /> <font color=\"Red\">(از کلیله و دمنه ).</font><br />سبز گشت از سخاش کشت امید<br />سیر گشت از عطاش معده ٔ آز.<br /> <font color=\"Red\">ادیب صابر.</font><br />هرکه بر خشم و آز قاهرتر<br />اوست بر خصم خویش قادرتر.<br /> <font color=\"Red\">سنائی .</font><br />طمع و آز را مرید مباش <br />بایزیدی کن و یزید مباش .<br /> <font color=\"Red\">سنائی .</font><br />آز مانند خوک و خرس شناس <br />آز بگذار و از کسی مهراس .<br /> <font color=\"Red\">سنائی .</font><br />راست گفت اندر این حدیث آن مرد<br />آز را خاک سیر داند کرد.<br /> <font color=\"Red\">سنائی .</font><br />آفتاب رای و ابر دست گوهربار تو<br />آز ما از بی نیازی جاودان قارون کند.<br /> <font color=\"Red\">انوری .</font><br />افسر عقل بایدت بر سر<br />از سر آز خون دل چه خوری ؟<br /> <font color=\"Red\">خاقانی .</font><br />آز تست اینکه همه چیز ترا نایابست <br />آز کم کن تو که نرخ همه ارزان گردد.<br /> <font color=\"Red\">کمال اسماعیل .</font><br />میان پنبه و آتش کسی چو جمع نکرد<br />چه میکنی سر چون پنبه را ز آتش آز؟<br /> <font color=\"Red\">کمال اسماعیل .</font><br />دایه ٔ جود ترا گفتم که را خواهی رضیع<br />گفت باری آز را، کش نیست امید فطام .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />کار زمانه قلب شد از کف تو که این زمان <br />بحر غنی است مفلس و آز گدا توانگر است .<br /><font color=\"Red\">کمال اسماعیل .</font><br />بر خیالی این چنین راه دراز<br />پیش گیری از سر جهل و ز آز.<br /> <font color=\"Red\">مولوی .</font><br />هرکه بر خود در سؤال گشود<br />تا بمیرد نیازمند بود<br />آز بگذار و پادشاهی کن <br />گردن بی طمع بلند بود.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> آرزو. هوی ̍ <span class=\"hlight\">:</span> <br />این جهان دام است و دانه ش آرزو<br />درگریز از دانه های آز او.<br /> <font color=\"Red\">مولوی .</font><br />گر بگویم آن سبب گردددراز<br />که چرا بودش به تخت آن عشق و آز.<br /> <font color=\"Red\">مولوی .</font><br />مرا هم ز صد گونه آز و هواست <br />ولیکن خزانه نه تنها مراست .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> غم و حسرت <span class=\"hlight\">:</span> <br />چنین است گیتی پر از آز و درد<br />از او تا توان گرد بیشی مگرد<br />فزونیش یک روز بگْزایدت <br />ببودن زمانی نیفزایدت .<br /> <font color=\"Red\">فردوسی .</font><br />دو دیگر چو توران سرافراز مرد<br />کجا آز ایران ورا رنجه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />آز آن ناز گذشته بگرفته ست ترا<br />نبد آن ناز ترا هیچ مگر مایه ٔ آز.<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> حاجت . نیاز <span class=\"hlight\">:</span> <br />سپاس از خدا ایزد رهنمای <br />که از کاف و نون کرد گیتی بپای <br />یکی کش نه آز و نه انباز بود<br />نه انجام باشد نه آغاز بود.<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(1178, 'آز', '<span class=\"hlight\">آز.</span> (اِخ ) نام شهری است .<br /></font></div>'),
(1179, 'آزآذان', '<span class=\"hlight\">آزآذان .</span> (اِخ ) نام قریه ای به هرات . <BR><font color=\"Blue\">◄</font> نام قریه ای به اصفهان . آزادان . رجوع به آزادان شود.<br /></font></div>'),
(1180, 'آزآور', '<span class=\"hlight\">آزآور.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ص مرکب ) حریص . مولَع. آزپرور. آزور.<br /></font></div>'),
(1181, 'آزا', '<span class=\"hlight\">آزا.</span> (اِ) در فرهنگهای فرانسوی در ریشه ٔ کلمه ٔ آسافوتیدا به معنی انقوزه مینویسند که اصل این کلمه از آزای فارسی به معنی راتیانج و رخبینه، و فوتیدای لاطینی بمعنای گنده است .<br /></font></div>'),
(1182, 'آزاج', '<span class=\"hlight\">آزاج .</span> (ع اِ) ج ِ اَزَج . اوستانها. بناهای دراز. سغها.<br /></font></div>'),
(1183, 'آزاج', '<span class=\"hlight\">آزاج .</span>(اِخ ) نام قریه ای از مَحال ّ بغداد بر راه خراسان .<br /></font></div>'),
(1184, 'آزاد', '<span class=\"hlight\">آزاد.</span> (اِخ ) نام زن شهربن باذان، والی صنعا از دست رسول صلوات اﷲعلیه . آنگاه که اسود عنسی ِ مُتنبی شوی او را بکشت آزاد را به عنف تزویج کرد، وقتی پیغامبر صلوات اﷲعلیه چند تن را بکشتن اسود بفرستاد این زن بخونخواهی شهربن باذان فرستادگان را در خانه پنهان داشت و آنان بر اسود دست یافته او را بکشتند.<br /></font></div>'),
(1185, 'آزاد', '<span class=\"hlight\">آزاد.</span> (ص ) آنکه بنده نباشد. آنکه در رقیت نباشد. حُرّ. حُرّه . ضد بنده <span class=\"hlight\">:</span> <br />هر آنکس که دارد ز پروردگان <br />ز آزاد وز پاکدل بندگان ...<br /> <font color=\"Red\">فردوسی .</font><br />ز بس جود او خلق را بنده کرد<br />بجز سرو و سوسن کس آزاد نیست .<br /> <font color=\"Red\">ابوعاصم .</font><br />تو آزادی و هرگزهیچ آزاد<br />نتابد همچو بنده جور و بیداد.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />آزاد شود بعقل ْ بنده .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بزرگ جشن است امروز مُلک را ملکا<br />که شادمان است ای شاه بنده و آزاد.<br /><font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> که بنظام و قیود و آداب سپاهیان و سایر ارباب مناصب مقید نباشد <span class=\"hlight\">:</span> <br />تن آزاد و آبادگیتی بر اوی <br />برآسوده از داور و گفتگوی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> یله . رها. مستخلص . رسته . فارغ . سالم از درد. تندرست <span class=\"hlight\">:</span> <br />ز گفتار اوانجمن شاد گشت <br />دل شهریار از غم آزاد گشت .<br /> <font color=\"Red\">فردوسی .</font><br />هر آنگه که باشی بدو شادتر<br />ز رنج زمانه دل آزادتر...<br /> <font color=\"Red\">فردوسی .</font><br />سیاوش ز گفتار او شاد شد<br />نهانش ز اندیشه آزاد شد.<br /> <font color=\"Red\">فردوسی .</font><br />شهنشاه ایران از آن شاد گشت <br />ز تیمار آن لشکر آزاد گشت .<br /> <font color=\"Red\">فردوسی .</font><br />چو رستم ز چنگ وی آزاد گشت <br />بسان یکی کوه پولادگشت .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت رستم برو شاد باش <br />بگو شاه را کز غم آزاد باش .<br /> <font color=\"Red\">فردوسی .</font><br />چو خواهی که آزاد باشی ز رنج <br />بی آزار و آکنده بی رنج گنج <br />بی آزاری زیردستان گزین ...<br /> <font color=\"Red\">فردوسی .</font><br />همی باد تا جاودان شاد دل <br />ز رنج و ز غم گشته آزاددل .<br /> <font color=\"Red\">فردوسی .</font><br />بدان شارسان ایمن و شاد باش <br />ز هر بد که اندیشی آزاد باش .<br /> <font color=\"Red\">فردوسی .</font><br />همیشه تن آباد و با تاج و تخت <br />ز رنج غم آزاد و پیروزبخت .<br /> <font color=\"Red\">فردوسی .</font><br />ز دست دیده و دل هر دو فریاد<br />که هرچه دیده بیند دل کند یاد<br />بسازم خنجری نیشش ز فولاد<br />زنم بر دیده تا دل گردد آزاد.<br /> <font color=\"Red\">باباطاهر.</font><br />اگر گردن بدانش داد خواهی <br />ز جهل آزاد بایدکرد گردن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کآن پی مصلحت خویش هم آنها گفتند<br />که نبودند ز بند طمع و حرص آزاد.<br /> <font color=\"Red\">اثیر اومانی .</font><br /> <BR><font color=\"Blue\">◄</font> معتق . آنکه او را مولی از بندگی رها ویله کرده باشد <span class=\"hlight\">:</span> <br />تا نکشد رنج بنده کی شود آزاد؟<br /><font color=\"Red\">ناصرخسرو.</font><br />آزاد شد از بندگی آز مرا جان <br />آزاد شو از آز و بزی شاد و توانگر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />من آزاد آزادکردان اویم <br />که بنده ست چون من هزاران هزارش .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> شاد. شادان . مسرور. مستریح . تهی . فارغ <span class=\"hlight\">:</span> <br />ز فرزند باشد پدر شاددل <br />ز غمها بدو دارد آزاد دل .<br /> <font color=\"Red\">فردوسی .</font><br />هر آنجا که ویران بدآباد کرد<br />دل غمگنان از غم آزاد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />خونیی را زار می بردند و خوار<br />تا درآویزند سر زیرش بدار<br />او طرب میکرد و بس دل زنده بود<br />خنده میزد وآن چه جای خنده بود<br />سائلی گفتش که آزادی چرا<br />وقت کشتن این چنین شادی چرا؟<br /><font color=\"Red\">عطار.</font><br /> <BR><font color=\"Blue\">◄</font> سربلند. سرافراز <span class=\"hlight\">:</span> <br />آزاد شوی چون الف اگر چند<br />امروز بزیر طمع چو دالی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کیست مولی آنکه او شادت کند<br />همچو سرو و سوسن آزادت کند.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> سالم . بی گزند <span class=\"hlight\">:</span> <br />دل شهریار جهان شاد باد<br />ز هر بد تن پاکش آزاد باد.<br /> <font color=\"Red\">فردوسی .</font><br />همیشه تن آزاد بادت ز رنج <br />پراکنده رنج و پُرآکنده گنج .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مختار. مُخیّر. <BR><font color=\"Blue\">◄</font> مخلی . خالی .بی مستأجر. بی سکنه . پرداخته . پردخته (خانه و دکان وجز آن ). <BR><font color=\"Blue\">◄</font> بی شوی . بی زن . مُجرّد. <BR><font color=\"Blue\">◄</font> وارسته . بی علاقه بمال و جاه و مانند آن . توسعاً، رند. لاابالی . بی قید. درویش . <BR><font color=\"Blue\">◄</font> بمعنی مجازی، سخت : چند کشیده ٔ آزاد زدن . <BR><font color=\"Blue\">◄</font> نجیب . نبیل . اصیل . شریف . کریم <span class=\"hlight\">:</span> <br />گشاده درِ هر دو آزادوار<br />میان ْ کوی کندوری افکنده خوار.<br /> <font color=\"Red\">ابوشکور.</font><br />ز شاهان کسی چون سیاوش نبود<br />چنو راد و آزاد و خامش نبود.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> بی نِکوهش . بی لوم و طعن لائم و طاعن . بی عیب . سالم . درست <span class=\"hlight\">:</span> هنوز این قصیده را کس جواب نگفته است که مجال آن ندیده اند که از این مضایق آزاد توانند بیرون آمد. (چهارمقاله ). <BR><font color=\"Blue\">◄</font> تمام . کامل . آزگار. تخت : شش ماه آزاد؛ شش ماه تمام . یک سال آزاد؛ عام اَجرد. سنة جرداء. یک ماه آزاد؛ شهر اَجرد <span class=\"hlight\">:</span> <br />زآن پس که هزار غصه خوردم <br />در بندگیت سه سال آزاد.<br /> <font color=\"Red\">کمال اسماعیل .</font><br />بودند هزار سال آزاد<br />از دولت خانه زادیت شاد.<br /> <font color=\"Red\">واله هروی .</font><br /> <BR><font color=\"Blue\">◄</font> هر درخت که بالطبع بی میوه باشد. (از ذخیره ٔ خوارزمشاهی ). <BR><font color=\"Blue\">◄</font> بری . مبرا <span class=\"hlight\">:</span> <br />چنین داد پاسخ که دل شاد دار<br />ز هر بد تن خویش آزاد دار.<br /> <font color=\"Red\">فردوسی .</font><br />طبعت آزاد بود از آزار.<br /> <font color=\"Red\">قوامی گنجه ای .</font><br />تو آزادی از ناپسندیده ها<br />نترسی که بر وی فتد دیده ها.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آزاد شدن </span> ؛ انفکاک . از بندگی رهائی یافتن . رها، مستخلص و یله گشتن . رستن <span class=\"hlight\">:</span> <br />چو بشنید شاه این سخن شاد شد<br />دل پهلوان از غم آزاد شد.<br /> <font color=\"Red\">فردوسی .</font><br />کنون روز داد است و بیداد شد<br />سران را سر از کشتن آزاد شد.<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به آزاد شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آزاد گردیدن، آزاد گشتن </span> ؛ از بندگی خلاص یافتن . محرَّر، عتیق، رها شدن . یله گشتن . رهائی یافتن .رستن . مستخلص گردیدن <span class=\"hlight\">:</span> <br />دل شاه پرویز از آن شاد گشت <br />کز آن پرهنر دشمن آزاد گشت .<br /> <font color=\"Red\">فردوسی .</font><BR>۩ فارغ شدن <span class=\"hlight\">:</span> <br />چو بشنید بیژن دلش شاد گشت <br />ببالید و زاندیشه آزاد گشت .<br /> <font color=\"Red\">فردوسی .</font><br />سیاوش بدان گفته ها شاد گشت <br />روانش از اندیشه آزاد گشت .<br /> <font color=\"Red\">فردوسی .</font><br />که دیدم ترا خرّم و شاددل <br />ز بند غمان گشته آزاددل .<br /> <font color=\"Red\">فردوسی .</font><br />دل شاه از اندیشه آزاد گشت <br />سوی آذر رام و خرّاد گشت .<br /> <font color=\"Red\">فردوسی .</font><br />بدینار چون لشکر آباد گشت <br />دل جنگجو از غم آزاد گشت .<br /> <font color=\"Red\">فردوسی .</font><br />همه لشکر نامور شاد گشت <br />دل مریم از دردش آزاد گشت .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> مُطلق . بی بند. بی قید. که محبوس نباشد. که اسیر نباشد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آزاد کردن و آزاد گردانیدن </span> ؛ شکستن مولی عقد بندگی عبد خود را. عتق . تحریر. اعتاق . (زوزنی ). فِکاک . فک ّ <span class=\"hlight\">:</span> <br />بخانه شد و بنده آزاد کرد<br />بدان خواسته بنده را شاد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />رسم است که مالکان تحریر<br />آزاد کنند بنده ٔ پیر.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />صد خانه اگر بطاعت آباد کنی <br />به زین نبود که خاطری شاد کنی <br />گر بنده کنی بلطف آزادی را<br />بهتر که هزار بنده آزاد کنی .<br /> <font color=\"Red\">علاءالدوله ٔ سمنانی .</font><BR>۩ رها، مستخلص و یله کردن . خلاص بخشیدن . اِطلاق . ول کردن . سر دادن <span class=\"hlight\">:</span> <br />سکندر دل از مردمان شاد کرد<br />ز رنج بیابان تن آزاد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />دل من بدین آشتی شاد کن <br />ز وام خرد گردن آزاد کن .<br /> <font color=\"Red\">فردوسی .</font><BR>۩ مجازاً، بخشیدن . عفو کردن <span class=\"hlight\">:</span> شاه وی را <font color=\"DarkGreen\"><b>[ قاتل را ]</font></b> آزاد کرد از گناهی که کرده بود. (نوروزنامه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آزاد را میازار و چون بیازردی بیوزن </span> . (قابوسنامه ).<br /> <span class=\"hlight\">عقیده آزاد است </span> .<br /><BR><font color=\"Blue\">◄</font> مُجرَّد. <BR><font color=\"Blue\">◄</font> بی عیب .<br /></font></div>'),
(1186, 'آزاد', '<span class=\"hlight\">آزاد.</span> (اِ) نام نوعی ماهی بزرگ و لذیذ، و آن در دریای خزر بسیار باشد.<br /></font></div>'),
(1187, 'آزاد', '<span class=\"hlight\">آزاد.</span> (اِخ ) نام شاعری پارسی گوی از اهل لاهور، نامش حافظ غلام محمد. وفاتش در <span class=\"hlight\" dir=\"rtl\">١٢٠٩</span> هَ . ق .<br /></font></div>'),
(1188, 'آزاد', '<span class=\"hlight\">آزاد.</span> (اِ) قسمی درخت جنگلی تنومند و بلند که چوب آن برای ساختن شانه و پوشانیدن پل و سقف بنا بکار است . <BR><font color=\"Blue\">◄</font> آزادرخت . (شلیمر). <BR><font color=\"Blue\">◄</font> ارژن . بادام کوهی . (شلیمر) .<br /></font></div>'),
(1189, 'آزاد', '<span class=\"hlight\">آزاد.</span> (اِ) نوعی از خرما. (مهذب الاسماء). اَزاد. و آن قسمی از خرمای خوب و خوش طعم باشد.<br /></font></div>'),
(1190, 'آزاد', '<span class=\"hlight\">آزاد.</span> (ص، اِ) نوعی سوسن و صفتی از آن و آن سوسن سپید است . (قاموس ) <span class=\"hlight\">:</span> <br />گلبن اندر باغ گوئی کودکی نیکوستی <br />سوسن آزاد گوئی ساقیی زیباستی .<br /> <font color=\"Red\">فرخی .</font><br />سوسن آزاد و شاخ نرگس بیمار جفت <br />نرگس خوشبوی و شاخ سوسن آزاد یار<br />این چنان زرین نمکدان بر بلورین مائده <br />وآن چنان چون بر غلاف زرّ سیمین گوشوار.<br /> <font color=\"Red\">منوچهری .</font><br />خداوندا ز مدح تو زبان بنده درماند<br />وگر چون سوسن آزاد سرتاپا زبان گردد.<br /><font color=\"Red\">کمال اسماعیل .</font><br /></font></div>'),
(1191, 'آزاد', '<span class=\"hlight\">آزاد.</span> (اِخ ) نام قصبه ای از توابع نخجوان که شراب و انگور آن مشهور بخوبی است . و مردم آن سفیدفام و نیکوروی باشند. و رجوع به آس و آزاده شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1192, 'آزاد', '<span class=\"hlight\">آزاد.</span> (اِ) نام لحنی که آن را آزادوار نیز خوانند:<br />همی تا برزند آزاد بلبلها به بستانها<br />همی تا برزند قالوس خنیاگر بمزمرها.<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(1193, 'آزاد', '<span class=\"hlight\">آزاد.</span> (اِخ ) تخلص شاعری فارسی گوی اهل کشمیر، از متأخرین، صاحب چندین هزار بیت مثنوی و غزل و جز آن . سیاحت را دوست میداشته و در پیری بتویسرکان ساکن و متأهل شده است . نامش احمد. وفات به سال <span class=\"hlight\" dir=\"rtl\">١١٥٠</span> هَ . ق .<br /></font></div>'),
(1194, 'آزاد', '<span class=\"hlight\">آزاد.</span> (ص، اِ) نوعی سرو و صفت آن <span class=\"hlight\">:</span> <br />بسرخه نگه کرد پس پیل تن <br />یکی سرو آزاد بد در چمن .<br /> <font color=\"Red\">فردوسی .</font><br />حکیمی را پرسیدند چندین درخت نامور که خدای عزوجل آفریده است و برومند هیچ یک را آزاد نخوانده اند مگر سرو را. (گلستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل سرو آزاد</span> ؛ سخت خرّم <span class=\"hlight\">:</span> <br />چو طینوش بشنید ازو شاد گشت <br />بسان یکی سرو آزاد گشت .<br /> <font color=\"Red\">فردوسی .</font><br />سیاوش ز ایرانیان شاد شد<br />بسان یکی سرو آزاد شد.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1195, 'آزاد بلگرامی', '<span class=\"hlight\">آزاد بلگرامی .</span> <font color=\"DarkGreen\"><b>[ دِ ب ِ ]</font></b> (اِخ ) از شعرای پارسی گوی هند، نامش امیرغلامعلی . وفاتش در سال <span class=\"hlight\" dir=\"rtl\">١١٦٥</span> هَ . ق . بوده است .<br /></font></div>'),
(1196, 'آزاد حبشی', '<span class=\"hlight\">آزاد حبشی .</span> <font color=\"DarkGreen\"><b>[ دِ ح َ ب َ ]</font></b> (اِخ ) نامش الماس و در ابتدا مملوک سیدمحمد متخلص بسحاب بود، چون شعر فارسی نیک میگفت فتحعلی شاه قاجار او را بخرید و آزاد کرد. صاحب مجمعالفصحاء در شرح حال شعرای معاصر دو شاعر آزادتخلص را یکی بعنوان «آزاد حبشی » و دیگری به نام «آزاد» مطلق یاد کرده است . لیکن این هر دو چنانکه از خود کتاب مستفاد می شود یکی است .<br /></font></div>'),
(1197, 'آزادان', '<span class=\"hlight\">آزادان .</span> (اِخ ) آزآذان . نام قریه ای نزدیک اصفهان، مسقطالرأس ابوعبدالرحمن قتیبةبن مهران مقری . <BR><font color=\"Blue\">◄</font> نام قریه ای نزدیک هرات، مدفن شیخ ابوالولید احمدبن ابی رجا.<br /></font></div>'),
(1198, 'آزادان', '<span class=\"hlight\">آزادان .</span> (اِ) ج ِ آزاد. احرار.<br /></font></div>'),
(1199, 'آزادبخت', '<span class=\"hlight\">آزادبخت .</span> <font color=\"DarkGreen\"><b>[ب َ ]</font></b> (اِخ ) (ایل ...) رجوع به طرهان (ایل ...) شود.<br /></font></div>'),
(1200, 'آزادبر', '<span class=\"hlight\">آزادبر.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نام قریه ای از لوراو شهرستانک بایالت طهران .<br /></font></div>'),
(1201, 'آزادبهر', '<span class=\"hlight\">آزادبهر.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص مرکب ) در شاهد زیر ظاهراً به معنی مبرّا و برکنار است :<br />تو شاد بادی و آزادبهر از چم دهر<br />عدوت باد ز بار عنا و غم دَخدَخ .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(1202, 'آزادخلق', '<span class=\"hlight\">آزادخلق .</span><font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (ص مرکب ) کامل الخلقه . (شعوری از شرفنامه ).<br /></font></div>'),
(1203, 'آزاددارو', '<span class=\"hlight\">آزاددارو.</span> (اِ مرکب ) سلق جَبلی، و بیخ آن را حلیمو گویند.<br /></font></div>'),
(1204, 'آزاددرخت', '<span class=\"hlight\">آزاددرخت .</span> <font color=\"DarkGreen\"><b>[ زادْ، دِ رَ ]</font></b> (اِ مرکب ) آزادِرَخْت . اَزادِرَخْت . نام درختی است عظیم، ثمرش شبیه به زعرور و بخوشه . تخمش مانند تخم زعرور، ثمر آن در آخر بهار رسد و مدتها بر درخت ماند و خوردنی نیست . برگش سبز مایل بسیاهی مثل برگ ترنج و خزان نمی کند گلش سرخ شبیه بخیری در غایت خوشبوئی . جوشانیده ٔ پوست آن در تب های آجامی نافع، و خواص بسیار دیگر نیز در مفردات برای برگ و تخم و میوه و پوست آن نوشته اند و بعضی تخم او را مقدار درهمی کشنده دانسته اند و نیز خوردن برگ و چوب آن را در بهایم زهر قاتل گفته اند و برخی آثار سمی را در آن انکار کرده و تنها نوعی از آن را که شبیه بفندق است سم شمرده اند. آن را در گرگان زهر زمین و در تنکابن جلی دارد (؟) و در طبرستان طاخک و بپارسی طاغ وسرشک گویند، و چون از هسته ٔ آن در پاره ای جایها سبحه کنند درخت تسبیح نیز خوانند و در عربی آن را قیقبان (ابن درید) و شجره ٔ حُرّه و شجرةالتسبیح نامند و بهندی نام آن بکاین است، و بگفته ٔ بعض فرهنگ نویسان طاخک و شالسنجان نیز مرادف این کلمه باشد <span class=\"hlight\">:</span> <br />من بنده ٔ آن قد چو آزاددرختم <br />من هندوی آن صورت چون لعبت چینم .<br /> <font color=\"Red\">شرف شفروه .</font><br /> <br /></font></div>'),
(1205, 'آزادزاد', '<span class=\"hlight\">آزادزاد.</span> (ن مف مرکب <span class=\"hlight\" dir=\"rtl\">/</span> ص مرکب ) نجیب زاده <span class=\"hlight\">:</span> تومرا یک لطمه بزن، حارث گفت حاشا که من هرگز این کنم و هیچ آزادزاد پدر را لطمه نزند. (مجمل التواریخ ).<br /></font></div>'),
(1206, 'آزادزن', '<span class=\"hlight\">آزادزن .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِ مرکب ) حُرّه .<br /></font></div>'),
(1207, 'آزادشده', '<span class=\"hlight\">آزادشده .</span> <font color=\"DarkGreen\"><b>[ ش ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) عتیق . معتق . آزادکرده . مَولی .<br /></font></div>'),
(1208, 'آزادماهی', '<span class=\"hlight\">آزادماهی .</span> (اِ مرکب ) اَزادماهی . قسمی ماهی بزرگ و لذیذ و در دریای خزر بسیار باشد. و رجوع به اَزادماهی شود.<br /></font></div>'),
(1209, 'آزادمرد', '<span class=\"hlight\">آزادمرد.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) لقب لهراسب . (مجمل التواریخ ).<br /></font></div>'),
(1210, 'آزادمرد', '<span class=\"hlight\">آزادمرد.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) نام عامل حجاج بن یوسف ثقفی که شهر فسا را در فارس تجدید عمارت کرد و شکل آن را که مثلث بود بگردانید. (از نزهةالقلوب ).<br /></font></div>'),
(1211, 'آزادمرد', '<span class=\"hlight\">آزادمرد.</span> <font color=\"DarkGreen\"><b>[م َ ]</font></b> (ص مرکب ) آزاده . حرّ. (دهار). جوانمرد. اصیل . نجیب . صاحب نسب بلند. شریف . کریم . نبیل <span class=\"hlight\">:</span> <br />همه پهلوانان آزادمرد<br />بر او خواندند آفرینها بدرد.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد سبک مرد افسون پژوه ...<br />بنزد سه دانا و آزادمرد.<br /> <font color=\"Red\">فردوسی .</font><br />پدرْت آن جهاندار آزادمرد<br />شنیدی که با روم و قیصر چه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />خروشی برآمد ز ایران بدرد<br />از آن شهریاران آزادمرد.<br /> <font color=\"Red\">فردوسی .</font><br />یکی دشت با دیدگان ْ پر ز خون <br />که تا او <font color=\"DarkGreen\"><b>[ سیاوش ]</font></b> کی آید ز آتش برون <br />ز آتش برون آمد آزادمرد<br />لبان پر ز خنده برخ همچو ورد.<br /> <font color=\"Red\">فردوسی .</font><br />بهر نیک و بد شاه آزادمرد<br />بفرزند بر، نازده باد سرد<br />همی پروریدش بناز و برنج ...<br /> <font color=\"Red\">فردوسی .</font><br />بگفتند کای شاه آزادمرد<br />بگرد بلا تا توانی مگرد.<br /> <font color=\"Red\">فردوسی .</font><br />سوم منزل آن شاه آزادمرد <font color=\"DarkGreen\"><b>[ فریدون ]</font></b><br />لب دجله و شهر بغداد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />وز آن پس بشد روشنک پر ز درد<br />چنین گفت کای شاه آزادمرد...<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت کای شاه آزادمرد<br />نگه کن که فرزند با من چه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />بشد موبد و برگرفتش ز گرد<br />ببردش بر شاه آزادمرد.<br /> <font color=\"Red\">فردوسی .</font><br />میازار کس را که آزادمرد<br />سر اندرنیارد به آزار مرد.<br /> <font color=\"Red\">فردوسی .</font><br />ندیده ست کس ترک آزادمرد<br />چه گویم کنون روز ننگ و نبرد؟<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت کای شاه آزاد مرد<br />چگونه ست کارت بدشت نبرد؟<br /> <font color=\"Red\">فردوسی .</font><br />و محمدبن هرمز... اندر مظالم شدو گفت بسیستان رسم نیست که مال زیادت خواهند و لشکری بلشکرجای باشد که مردمان را زنان و دختران باشد. مردم بیگانه بمنزل و سرای آزادمردان واجب نکند. (تاریخ سیستان ). جدّان من همه ٔ جهان بگرفتند هرجا که بسرای آزادمردان رسیدند همان کردند. (تاریخ سیستان ). گفت ای آزادمردان چون روز شود خصمی سخت شوخ و گربز پیش خواهد آمد. (تاریخ بیهقی ). پس گفت <font color=\"DarkGreen\"><b>[ عبداﷲ زبیر ]</font></b> هان ای آزادمردان حمله برید. (تاریخ بیهقی ). و من <font color=\"DarkGreen\"><b>[ عبدالرحمن ]</font></b> و این آزادمرد با ایشان میرفتیم تا پای قلعت، قلعه ای دیدم سخت بلند. (تاریخ بیهقی ). فضل <font color=\"DarkGreen\"><b>[ برمکی ]</font></b> املاء همی کرد و سخن نرم همی گفت، یکی سخن بگفت دبیر نشنید... از وی بازخواست ... دیگربار گفت دبیر هم نشنید آن سخن دیگربار خواست فضل ... گفت چند بار پرسی ای نبطی ؟ گفت آزادمردان چنین گویند! و این داشتم بتو که این شنوم ! (تاریخ برامکه ).<br />بوالفرج ای خواجه ٔ آزادمرد<br />هجر وصال تو مرا خیره کرد.<br /> <font color=\"Red\">مسعودسعد.</font><br />هیچ دانی از چه باشد قیمت آزادمرد<br />بر سر خوان لئیمان دست کوته کردن است .<br /> <font color=\"Red\">سنائی .</font><br />بخندید صراف آزادمرد<br />وز آمیزش زر بدو قصه کرد.<br /> <font color=\"Red\">نظامی .</font><br />بمرد از تهیدستی آزادمرد<br />ز پهلوی مسکین شکم پر نکرد.<br /> <font color=\"Red\">سعدی .</font><br />بخصمان بندی فرستاد مرد<br />که ای نیکمردان آزادمرد.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> ایرانی <span class=\"hlight\">:</span> <br />بگیتی نداند کسی هم نبرد<br />ز رومی ّ و توری ّ و آزادمرد.<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به آزاده و آزاده مردشود.<br /></font></div>'),
(1212, 'آزادمردآباد', '<span class=\"hlight\">آزادمردآباد.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) نام قلعه ای محکم در نواحی همدان .<br /></font></div>'),
(1213, 'آزادمردان', '<span class=\"hlight\">آزادمردان .</span> <font color=\"DarkGreen\"><b>[ م َ]</font></b> (اِ مرکب ) ج ِ آزادمرد. احرار. نجبا. شرفا. نبلا.<br /></font></div>'),
(1214, 'آزادمردی', '<span class=\"hlight\">آزادمردی .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (حامص مرکب ) چگونگی و صفت آزادمرد. حریّت . مکرمت . نجابت . اصالت . کرم . مردمی <span class=\"hlight\">:</span> <br />گر ایدون که بر من نسازید بد<br />کنید آنچه زآزادمردی سزد...<br /> <font color=\"Red\">فردوسی .</font><br />سپاهی که شان تاختن پیشه بود<br />وز آزادمردی کم اندیشه بود.<br /> <font color=\"Red\">فردوسی .</font><br />مردی و آزادمردی زو همی بوید بطبع<br />همچنان کز کلبه ٔ عطار بوید مشک و بان .<br /> <font color=\"Red\">فرخی .</font><br />از آزادمردی آنچه آمد گفتم و کردم و تو حرمت من نگاه نداشتی . (تاریخ بیهقی ).<br />به آزادمردی ستودش کسی <br />که در راه حق سعی کردی بسی .<br /> <font color=\"Red\">سعدی .</font><br />چو حاتم به آزادمردی دگر<br />ز دوران گیتی نیاید ببر.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1215, 'آزادمیوه', '<span class=\"hlight\">آزادمیوه .</span><font color=\"DarkGreen\"><b>[ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (اِ مرکب ) حلوا و نقلی باشد که از قند یا عسل و مغز بادام و نخود و پسته و فندق مقشر و خلال کرده کنند و آن را شکر بادام نیز گویند <span class=\"hlight\">:</span> <br />کعب الغزال دارد از بوی مشک سهمی <br />آزادمیوه دارد از قند سوده گردی .<br /> <font color=\"Red\">بسحاق اطعمه .</font><br /><BR><font color=\"Blue\">◄</font> نخود قندی و بادام قندی برنگهای مختلف . (برهان ).<br /></font></div>'),
(1216, 'آزادنامه', '<span class=\"hlight\">آزادنامه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) آزادی نامه . خط آزادی . نامه ٔ آزادی .(از بهار عجم ). لکن در فارسی فصیح مستعمل نیست . بلعمی در تاریخ و ابن بلخی در فارسنامه بکار برده اند.<br /></font></div>'),
(1217, 'آزاده', '<span class=\"hlight\">آزاده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص ) آنکه بنده نباشد. حرّ. حرّه . آزاد. آزادمرد. مقابل بنده و عبد. ج، آزادگان <span class=\"hlight\">:</span> <br />ز مادر همه مرگ را زاده ایم <br />همه بنده ایم ارچه آزاده ایم .<br /> <font color=\"Red\">فردوسی .</font><br />چه گفت آن سخنگوی آزاده مرد<br />که آزاده را کاهلی بنده کرد.<br /> <font color=\"Red\">فردوسی .</font><br />از ایران جز آزاده هرگز نخاست <br />گرفت از شما بنده هر کس که خواست .<br /> <font color=\"Red\">اسدی .</font><br />سیرت و کردار، گر آزاده ای <br />بر سنن و سیرت احرار کن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آزاده ای که جوید نام نکو بشعر<br />چون بندگان ز خلق نباید ستدبها.<br /> <font color=\"Red\">مسعودسعد.</font><br />هست زیر فلک گردنده <br />قانع آزاده و طامع بنده .<br /> <font color=\"Red\">جامی .</font><br /> <BR><font color=\"Blue\">◄</font> آزادکرده . مُحرّر. مولی . مُعتق <span class=\"hlight\">:</span> <br />بریدی سر ساوه شاه آنکه مهر<br />بر او داشت تا بود گردان سپهر<br />سپاهی بدانگونه کردی تباه <br />که بخشایش آرد همی هور و ماه <br />از آن شاه جنگی منم یادگار<br />مرا هم چنان دان که کُشتی بزار<br />ز مادر همه مرگ را زاده ایم <br />بناچار گردن ورا داده ایم <br />بمان تا بمانم بدهر اندکی <br />کز آزادگان تو باشم یکی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> گهری . اصیل . نجیب .شریف . کریم . از طبقه ٔ اشراف . به نسب <span class=\"hlight\">:</span> <br />مدخلان را رکاب زرآگین <br />پای آزادگان نیابد سر.<br /> <font color=\"Red\">رودکی .</font><br />گفت هنگامی یکی شهزاده بود<br />گوهری ّ و پرهنر آزاده بود<br />شد بگرمابه درون یک روز غوشت <br />بود فربی ّ و کلان و خوب گوشت .<br /> <font color=\"Red\">رودکی (از سندبادنامه ).</font><br />فرزانه تر از تو نبود هرگز مردم <br />آزاده تر از تو نبرد خلق گمانه .<br /> <font color=\"Red\">خسروی .</font><br />چو گشتاسب برشد بتخت پدر<br />که فرّ پدر داشت و بخت پدر<br />بسر برنهاد آن پدرداده تاج <br />که زیبنده باشد به آزاده تاج .<br /> <font color=\"Red\">دقیقی .</font><br />ای سر آزادگان و تاج بزرگان <br />شمع جهان و چراغ دوده و نوده .<br /> <font color=\"Red\">دقیقی .</font><br />پس و پیش گرد اندر آزادگان <br />همی رفت <font color=\"DarkGreen\"><b>[ نوشیروان ]</font></b> تا آذرآبادگان .<br /> <font color=\"Red\">فردوسی .</font><br />چو آمد <font color=\"DarkGreen\"><b>[ سیاوش ]</font></b> بر کاخ کاووس شاه <br />خروش آمد و برگشادند راه <br />پرستار با مجمر و بوی خوش <br />بشد پیش او دست کرده بکش <br />بهر گنج بر سیصد استاده بود<br />میان ْ در سیاووش آزاده بود.<br /> <font color=\"Red\">فردوسی .</font><br />همان نیز گودرز کشوادگان <br />سر نامداران و آزادگان <br />بکین سیاوش ده ودوهزار<br />بیاورد برگستوانور سوار<br />چنین گفت با ماهیار آرزوی <br />که ای پیر آزاده ٔ نیکخوی .<br /> <font color=\"Red\">فردوسی .</font><br />حسین قتیب است از آزادگان <br />که از من نخواهد سخن رایگان .<br /> <font color=\"Red\">فردوسی .</font><br />ز پیوند مهراب و از مهر زال <br />وز آن هر دو آزاده ٔ ناهمال (کذا).<br /> <font color=\"Red\">فردوسی .</font><br />بطوس و بگودرز کشوادگان <br />بگیو و بگرگین و آزادگان .<br /> <font color=\"Red\">فردوسی .</font><br />بزرگان و آزادگان را بشهر<br />ز نیکیت باید که یابندبهر.<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود تا پیشش آزادگان <br />ببستند و گردان لشکر میان <br /> <font color=\"Red\">فردوسی .</font><br />به آزادگان گفت پشت سپاه <br />که ای نامداران و شیران شاه .<br /> <font color=\"Red\">فردوسی .</font><br />از آزادگان هرکه دیدی براه <br />بپرسیدی از نامدار سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />پس آزاده نستور پور وزیر<br />به پیش افکند اسب چون نرّه شیر.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد بدرگاه ِ آزاده شاه <br />کمربسته و برنهاده کلاه .<br /> <font color=\"Red\">فردوسی .</font><br />من از دخت خاقان فرستاده ام <br />نه جنگی کسی ام نه آزاده ام .<br /> <font color=\"Red\">فردوسی .</font><br />پس آزاده شیدسپ فرزند شاه <br />بکینش کند تیزاسب سیاه .<br /> <font color=\"Red\">فردوسی .</font><br />کنون چیست پاسخ فرستاده را<br />چه گوئیم مهراب آزاده را؟<br /> <font color=\"Red\">فردوسی .</font><br />یکی جام زرین پر از باده کرد<br />وزو یادمردان آزاده کرد.<br /> <font color=\"Red\">فردوسی .</font><br />بچیز تو او ساز مهمان کند<br />دل مرد آزاده خندان کند.<br /> <font color=\"Red\">فردوسی .</font><br />ز دهقان و تازی ّ و پرمایگان <br />زنان بزرگان و آزادگان <br />از آن مهتران چار زن برگزید<br />که اندر گهر بد نژادش پدید.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد پس آزاده شیرو چو گرد<br />دلش گشت پرخون و رخسار زرد<br /> <font color=\"Red\">فردوسی .</font><br />برادر دو بودش <font color=\"DarkGreen\"><b>[ فریدون را ]</font></b> دو فرخ همال <br />از او هر دو آزاده، مهتر بسال .<br /> <font color=\"Red\">فردوسی .</font><br />بزرگان و آزادگان را بخوان <br />بجشن و بسور و به رای و به خوان .<br /> <font color=\"Red\">فردوسی .</font><br />بپالیز زیر گل افشان درخت <br />بخفت آن سه آزاده ٔ نیکبخت .<br /> <font color=\"Red\">فردوسی .</font><br />چو تاج بزرگی بسر برنهاد<br />از او شاد شد تاج و او نیز شاد<br />کجا بود از گیتی آزاده ای <br />خداوند تاج و کیان زاده ای .<br /> <font color=\"Red\">فردوسی .</font><br />از ایران هر آنکس که گوزاده بود<br />دلیر و خردمند و آزاده بود<br />بفرمود <font color=\"DarkGreen\"><b>[ کاوس ]</font></b> تا جمله بیرون شدند<br />ز پهلو سوی دشت و هامون شدند.<br /> <font color=\"Red\">فردوسی .</font><br />ندیده ست هرگز چنو هیچ زایر<br />عطابخشی آزاده ٔ زرفشانی .<br /> <font color=\"Red\">فرخی .</font><br />کریم است و آزاده و تازه روئی <br />جوان است و آهسته و باوقاری .<br /> <font color=\"Red\">فرخی .</font><br />گفتا چه خوانم این شه آزاده را به نام <br />گفتم یمین دولت محمود دین پناه .<br /> <font color=\"Red\">فرخی .</font><br />آزاده خداوندی و خوشخوی کریمی <br />با فرّ شهنشاهی و با زیب سواری .<br /> <font color=\"Red\">فرخی .</font><br />او تکیه کرده بر چمن و باغ پیش او<br />آزادگان نشسته و بت چهرگان بپای .<br /> <font color=\"Red\">فرخی .</font><br />دل بدان یافته ای زآنکه نکو دانی خواند<br />مدحت خواجه ٔ آزاده بالفاظ دری .<br /> <font color=\"Red\">فرخی .</font><br />ابوالفتح کآزادگان جهان <br />شدستند بر جود او مفتتن .<br /> <font color=\"Red\">فرخی .</font><br />آزاده برکشیدن و رادان رسوم اوست <br />وآزادگی نمودن و رادی شعاراو.<br /> <font color=\"Red\">فرخی .</font><br />همه آن گوید کآزاده ای از غم برهد<br />کارِ دشوار شود بر دل سلطان آسان .<br /> <font color=\"Red\">فرخی .</font><br />عطای او نه ز دشمن برید و نه از دوست <br />چنین بود ره آزادگان و خوی کرام .<br /> <font color=\"Red\">فرخی .</font><br />گشاده بر همه خواهندگان دست <br />چنان چون بر همه آزادگان در.<br /> <font color=\"Red\">فرخی .</font><br />کریم طبعی آزاده ٔ خداوندی <br />که خلق یکسر از او شاکرند و او مشکور.<br /> <font color=\"Red\">فرخی .</font><br />ترا به اصل بزرگ ای بزرگوار کریم <br />زیادتی است بر آزادگان همه هموار.<br /> <font color=\"Red\">فرخی .</font><br />ناب است هر آن چیز که آلوده نباشد<br />زین روی ترا گویم کآزاده ٔ نابی .<br /> <font color=\"Red\">فرخی .</font><br />جرعه بر خاک همی ریزم از جام شراب <br />جرعه بر خاک همی ریزد آزاده ادیب .<br /> <font color=\"Red\">منوچهری .</font><br />دگر آزادگان و نامداران <br />بزرگان و دلیران و سواران .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />نباشد هیچ بیگانه ستمگر<br />نباشد هیچ آزاده ستم بر.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />کجا چون برد <font color=\"DarkGreen\"><b>[ شاه موبد ]</font></b> لشکرگه به آمل <br />همه شب خورد با آزادگان مل .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />چنان دان که آن لائی نیک فال <br />که یعقوب را بود شایسته خال <br />دو آزاده دخت دلارام داشت <br />کز آن هر دو دختر جهان نام داشت .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />مردمی ورز و هگرز آزار آزاده مجوی <br />مردم آن را دان کزو آزاده را آزار نیست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />اگر جفت آزی نه آزاده ای <br />ازیرا که این زآن و آن زین جداست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نیست آزاده را قبانمدی <br />که همش پاره برندوخته اند.<br /> <font color=\"Red\">خاقانی .</font><br />گفته ٔ آنهاست که آزاده اند<br />کاین دو ز یک اصل و نسب زاده اند.<br /> <font color=\"Red\">نظامی .</font><br />نه چون ممسکان دست بر زر گرفت <br />چو آزادگان بند از او برگرفت .<br /> <font color=\"Red\">سعدی .</font><br />که زشت است در چشم آزادگان <br />بیفتادن از دست افتادگان .<br /> <font color=\"Red\">سعدی .</font><br />گر سفله بمال و جاه از آزاده به است <br />سگ نیز بصید از آدمیزاده به است .<br /> <font color=\"Red\">سعدی .</font><br />کسی گفتش چه نشینی که فلان در این شهر طبعی کریم دارد و کرمی عمیم میان به خدمت آزادگان بسته . (گلستان ).<br />هست ارادت برِ هر آزاده <br />ترک ماکان علیه العاده .<br /> <font color=\"Red\">جامی .</font><br /> <BR><font color=\"Blue\">◄</font> ولی ّ. صالح . حلال زاده . (از تحفةالسعاده ). <BR><font color=\"Blue\">◄</font> رها. مستخلص . یله <span class=\"hlight\">:</span> <br />بشنو این نکته که خود را ز غم آزاده کنی <br />خون خوری گر طلب روزی ننهاده کنی .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> خاضع <span class=\"hlight\">:</span> <br />سعدی افتاده ای است آزاده <br />کس نیاید بجنگ افتاده .<br /> <font color=\"Red\">سعدی .</font><br /> <br /> <BR><font color=\"Blue\">◄</font> فارغ . <BR><font color=\"Blue\">◄</font> بی بار <span class=\"hlight\">:</span> <br />زایران را هم از او نعمت و هم دانش (کذا)<br />وآنگه از منت آزاده دل و گردن <br />گر همه نعمت یک روز بما بخشد<br />ننهد منت بر ما و پذیرد من .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> آسوده . مرفّه . شاد <span class=\"hlight\">:</span> <br />چون ترا می بینم از آزادگان <br />کی شناسی درد کارافتادگان ؟<br /> <font color=\"Red\">عطار.</font><br />و رجوع به آزادگی شود. <BR><font color=\"Blue\">◄</font> پهلوان . سرسپاه <span class=\"hlight\">:</span> <br />چو ویرو دید گردان را چنین زار<br />بگرد قارن اندر کشته بسیار<br />بگفت آزادگانش را به تندی <br />که از جنگ آوران زشت است کندی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> وارسته <span class=\"hlight\">:</span> <br />لبی نان خشک و دمی آب سرد<br />همین بس بود قوت آزاده مرد.<br /> <font color=\"Red\">فردوسی .</font><br />گر آزاده ای بر زمین خسب و بس <br />مکن بهر قالی زمین بوس کس .<br /> <font color=\"Red\">سعدی .</font><br />مرد آزاده بگیتی نکند میل دو کار<br />تا همه عمروجودش بسلامت باشد<br />زن نخواهد اگرش دختر قیصر بدهند<br />وام نستاند اگر وعده قیامت باشد.<br /> <font color=\"Red\">ابن یمین .</font><br /> <BR><font color=\"Blue\">◄</font> لقب خاص ایرانیان بوده است و جز ایرانی حتی پادشاهان ملل دیگر را این نام نمیداده اند. آن گاه که کردیه خواهر بهرام چوبینه ازدواج خاقان چین را نمیپذیرد یلان سینه او را برای گستهم سردار ایرانی خواستاری میکند و کردیه تن درمیدهد <span class=\"hlight\">:</span> <br />یلان سینه با کردیه گفت زن <br />بگیتی ترا دیده ام رای زن <br />ز خاقان <font color=\"DarkGreen\"><b>[ پرموده شاه ]</font></b> کناره گزیدی سزید<br />که رأی تو آزادگان را گزید<br />چه گوئی ز گستهم یل خال شاه <br />توانگر سپهبد یل باسپاه <br />بدو گفت شوئی کز ایران بود<br />از او تخمه ٔ مانه ویران بود.<br /> <font color=\"Red\">فردوسی .</font><br />همی رای زد جنگ را با سپاه <br />بدینگونه تا گشت گیتی سیاه <br />بخفتند ترکان و آزادگان <br />جهان شد جهانجوی را رایگان .<br /> <font color=\"Red\">فردوسی .</font><br />ز جائی که آمد فرستاده ای <br />ز ترک و ز رومی ّ و آزاده ای <br />از او مرزبان آگهی داشتی <br />چنین کارها خوار نگذاشتی .<br /> <font color=\"Red\">فردوسی .</font><br />ج، آزادگان . و رجوع به آزادمرد و آزاده مرد شود.<br /> <BR><font color=\"Blue\">◄</font> اسب گرانمایه . اسب پادشاهان . طِرف . (زمخشری ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سرو آزاده </span> ؛ سروآزاد <span class=\"hlight\">:</span> <br />بشکست و بکند سرو آزاده <br />بنشاند بجای او سپیداری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و ظاهراً مراد از سرو آزاده، صنوبر و چلغوزه باشد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سوسن آزاده </span> ؛ سوسن آزاد. سوسن سفید <span class=\"hlight\">:</span> <br />از زبان سوسن آزاده ام آمد به گوش <br />کاندر این دیر کهن، کار سبکباران خوش است .<br /> <font color=\"Red\">حافظ.</font><br />نهفته سوسن آزاده در میان چمن <br />بگوش رهزن دی گفت از زبان بهار<br />بیار پیرهن شاهدان بستان را<br />وگرنه می کندت بید، گربه در شلوار.<br /> <font color=\"Red\">امیدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آزاده را میازار و چون بیازردی بیوزن </span> . (قابوسنامه ).<br /> <span class=\"hlight\">نباشد هیچ آزاده ستم بر</span> .<br /><font color=\"Red\">(ویس و رامین ).</font><br /></font></div>'),
(1218, 'آزاده', '<span class=\"hlight\">آزاده .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) لقب نوذر، پادشاه پیشدادی . <BR><font color=\"Blue\">◄</font> نام کنیزکی چنگ زن، معشوقه ٔ بهرام گور.<br /></font></div>'),
(1219, 'آزاده خو', '<span class=\"hlight\">آزاده خو.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b>(ص مرکب ) آزاده خوی . دارای خوی آزادگان <span class=\"hlight\">:</span> <br />همی تیر و چوگان کنند آرزوی <br />چه فرمان دهد شاه آزاده خوی ؟<br /> <font color=\"Red\">فردوسی .</font><br />گمانت چنین است کاین تاج و تخت <br />سپاه و فزونی و نیروی بخت <br />ز گیتی کسی را نبد آرزوی <br />از آن نامداران آزاده خوی ...<br />جهان را بمردی نگه داشتند<br />یکی چشم بر تخت نگماشتند.<br /> <font color=\"Red\">فردوسی .</font><br />سپهبد فرستاد از چار سوی <br />گزیده بزرگان آزاده خوی .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد سوی حجله ٔ آرزوی <br />بدو گفت ای ماه آزاده خوی .<br /> <font color=\"Red\">فردوسی .</font><br />همی بود جشنی نه برآرزوی <br />ز تیمار پیروز آزاده خوی .<br /> <font color=\"Red\">فردوسی .</font><br />توئی چون فریدون آزاده خوی <br />منم چون پرستار و نام آرزوی .<br /> <font color=\"Red\">فردوسی .</font><br />بدیدار او آمدش آرزوی <br />برِ دختر و شاه آزاده خوی <br />فرستاده هندی فرستاده ای ...<br /> <font color=\"Red\">فردوسی .</font><br />گرفتند گرد اندرش چار سوی <br />چو بیچاره شد شاه آزاده خوی ...<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> در صفت اسب، اصیل . نجیب <span class=\"hlight\">:</span> <br />هم آهوفغند است هم یوزتک <br />هم آزاده خویست و هم تیزگام .<br /><font color=\"Red\">فرالاوی .</font><br /></font></div>'),
(1220, 'آزاده خوی', '<span class=\"hlight\">آزاده خوی .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b>(اِخ ) نامی است که فریدون بزن تور داد <span class=\"hlight\">:</span> <br />زن سلم را کرد نام آرزوی <br />زن تور را نام آزاده خوی <br />زن ایرج نیک پی را سهی <br />کجا بد سهیلش بخوبی رهی .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1221, 'آزاده دل', '<span class=\"hlight\">آزاده دل .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ دِ ]</font></b> (ص مرکب ) فارغ بال . <BR><font color=\"Blue\">◄</font> صالح . (برهان ). <BR><font color=\"Blue\">◄</font> حلال زاده . (برهان ).<br /></font></div>'),
(1222, 'آزاده سرو', '<span class=\"hlight\">آزاده سرو.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ س َرْوْ ]</font></b> (اِ مرکب ) سرو آزاد <span class=\"hlight\">:</span> <br />یلی دید مانند آزاده سرو<br />برخ چون تذرو و میان همچو غَرْو.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1223, 'آزاده مرد', '<span class=\"hlight\">آزاده مرد.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ م َ ]</font></b> (ص مرکب ) آزادمرد. آزاده . جوان مرد. فتی ̍ <span class=\"hlight\">:</span> <br />چه گفت آن سخن گوی آزاده مرد<br />که آزاده را کاهلی بنده کرد.<br /> <font color=\"Red\">فردوسی .</font><br />بترسید شاپور آزاده مرد<br />دلش گشت پردرد و رخساره زرد.<br /> <font color=\"Red\">فردوسی .</font><br />بزرگان ایران همه پر ز درد<br />برفتند با شاه آزاده مرد.<br /> <font color=\"Red\">فردوسی .</font><br />چنین رادی چنین آزاده مردی <br />ندانم بر چه طالع زاد مادر!<br /> <font color=\"Red\">فرخی .</font><br /><BR><font color=\"Blue\">◄</font> ایرانی <span class=\"hlight\">:</span> <br />زشت بود بودن آزاده مرد<br />بنده ٔ طوغان و عیال ینال .<br /> <font color=\"Red\">ناصرخسرو.</font><br />رجوع به آزاد و آزادمرد و آزاده شود.<br /></font></div>'),
(1224, 'آزاده مردم', '<span class=\"hlight\">آزاده مردم .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ م َ دُ ]</font></b> (ص مرکب ) آزادمرد. آزاده مرد <span class=\"hlight\">:</span> <br />نهان در جهان چیست آزاده مردم <br />نبینی نهان را به بینی عیان را.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(1225, 'آزاده مردی', '<span class=\"hlight\">آزاده مردی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ م َ ]</font></b> (حامص مرکب ) آزادمردی . چگونگی و صفت آزاده مرد.<br /></font></div>'),
(1226, 'آزاده وار', '<span class=\"hlight\">آزاده وار.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب، ق مرکب ) آزادوار. با صفت آزاده . چون آزاده <span class=\"hlight\">:</span> <br />گشاده درِ هردو آزاده وار <br />میان ْ کوی کندوری افکنده خوار.<br /> <font color=\"Red\">ابوشکور.</font><br />هزار آفرین باد هر ساعتی <br />بر آن عادت و خوی آزاده وار.<br /><font color=\"Red\">فرخی .</font><br /></font></div>'),
(1227, 'آزادوار', '<span class=\"hlight\">آزادوار.</span> <font color=\"DarkGreen\"><b>[ زادْ ]</font></b> (ص مرکب، ق مرکب ) با خوی و خصلت آزادان . چون آزادمردان <span class=\"hlight\">:</span> <br />زمانه پندی آزادوار داد مرا<br />زمانه را چو نکو بنگری همه پند است <br />بروز نیک کسان گفت غم مخور زنهار<br />بسا کسا که بروز تو آرزومند است .<br /> <font color=\"Red\">رودکی .</font><br />گشاده درِ هر دو آزادوار <br />میان ْ کوی کندوری افکنده خوار.<br /><font color=\"Red\">ابوشکور.</font><br /></font></div>'),
(1228, 'آزادوار', '<span class=\"hlight\">آزادوار.</span> <font color=\"DarkGreen\"><b>[ زادْ ]</font></b> (اِخ ) شهرکی است <font color=\"DarkGreen\"><b>[ از خراسان بنواحی اسفراین ]</font></b> اندر میان بیابان و بانعمت و بر راه گرگان . (حدودالعالم ). و میوه خاصه انگور آن بخوبی مشهور است و یاقوت گوید شهری است در اول ناحیه ٔ جوین یا گویان از طرف قومس از توابع نیشابور - انتهی . ومدفن سیدحسن غزنوی شاعر بدانجاست و ابوموسی ابراهیم بن عبدالرحمن بن سهل آزادواری منسوب بدین قریه است .<br /></font></div>'),
(1229, 'آزادوار', '<span class=\"hlight\">آزادوار.</span> <font color=\"DarkGreen\"><b>[ زادْ ]</font></b> (اِ مرکب ) نام لحن و نوائی از موسیقی <span class=\"hlight\">:</span> <br />صلصل باغی بباغ اندر همی نالد بدرد<br />بلبل راغی براغ اندر همی نالد بزار<br />این زند بر چنگهای سغدیان پالیزبان <br />وآن زند بر نایهای لوریان آزادوار.<br /> <font color=\"Red\">منوچهری .</font><br />دستانهای چنگش سبزه بهار باشد<br />نوروز کیقبادی وآزادوار باشد.<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(1230, 'آزادکرد', '<span class=\"hlight\">آزادکرد.</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (ن مف مرکب ) آزادکرده . آزادشده . عتیق . معتق . محرّر. مولی <span class=\"hlight\">:</span> همه گفتند ما فرمان توکنیم و بنده و آزادکرد تو باشیم . (تاریخ سیستان ).<br />من آزاد آزادکردان اویم <br />که بنده ست چو من هزاران هزارش .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(1231, 'آزادکرده', '<span class=\"hlight\">آزادکرده .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن نف مرکب ) عتیق . مُعْتَق . محرَّر. مولی .<br /></font></div>'),
(1232, 'آزادکننده', '<span class=\"hlight\">آزادکننده .</span> <font color=\"DarkGreen\"><b>[ ک ُ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) مُعْتِق . محرِّر. مولی .<br /></font></div>'),
(1233, 'آزادگان', '<span class=\"hlight\">آزادگان .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span>دِ ]</font></b> (اِ) ج ِ آزاده . احرار. جوانمردان <span class=\"hlight\">:</span> <br />دیر زیاد آن بزرگوار خداوند<br />جان گرامی بجانش اندر پیوند...<br />دائم بر جان او بلرزم ازیراک <br />مادر آزادگان کم آرد فرزند.<br /> <font color=\"Red\">رودکی .</font><br />منم گیو گودرز کشوادگان <br />سر سرکشان پور آزادگان .<br /> <font color=\"Red\">فردوسی .</font><br />نیامد همی بانگ شهزادگان <br />مگر کشته شد شاه آزادگان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نُجبا <span class=\"hlight\">:</span> و سپاه جمع شد از موالی و سرهنگان و آزادگان سیستان همه یکدل و یک نهاد و تشویش از میان برخاست . (تاریخ سیستان ).<br />من از پاک فرزند آزادگانم <br />نگفتم که شاپوربن اردشیرم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کجا باشد محل آزادگان را در چنین وقتی <br />که بر هر گاهی و تختی شه و میر است مولائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />وگر آرزوت است کآزادگان <br />تراپیشکاران شوند و خدم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از آنکه وحشت آزادگان خطرناک است .<br /> <font color=\"Red\">عبدالواسع جبلی .</font><br /> <BR><font color=\"Blue\">◄</font> وارستگان . درویشان . (بمعنی مجازی فعلی ) لاابالیان . رندان . بی قیدان <span class=\"hlight\">:</span> <br />اگر ندارم سیم شکوفه نیست عجب <br />که سرو نیز ز آزادگان و بی درم است .<br /> <font color=\"Red\">رفیع لنبانی .</font><br />قرار در کف آزادگان نگیرد مال <br />نه صبر در دل عاشق نه آب در غربال .<br /> <font color=\"Red\">سعدی .</font><br />بسرو گفت یکی میوه ای نمی آری <br />جواب داد که آزادگان تهی دستند.<br /> <font color=\"Red\">سعدی .</font><br />گفت هر یکی را دخلی معین است بوقتی معلوم و گهی تازه اند و گاه پژمرده و سرو را هیچ نیست و همه وقتی تازه است و این است صفت آزادگان . (گلستان ).<br />مجلس آزادگان را از گرانی چاره نیست .<br /> <font color=\"Red\">ابن یمین .</font><br />بخواه جان و دل از بنده و روان بستان <br />که حکم بر سر آزادگان روان داری .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آزادگان تهی دستند</span> .<br /> <font color=\"Red\">سعدی .</font><br /><span class=\"hlight\">مادر آزادگان کم آرد فرزند</span> .<br /> <font color=\"Red\">رودکی .</font><br /> <span class=\"hlight\">مجلس آزادگان را از گرانی چاره نیست </span> .<br /> <font color=\"Red\">ابن یمین .</font><br />... <span class=\"hlight\">وحشت آزادگان خطرناک است </span> .<br /><font color=\"Red\">عبدالواسع جبلی .</font><br /></font></div>'),
(1234, 'آزادگی', '<span class=\"hlight\">آزادگی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) حریت . جوانمردی . اصالت . نجابت . شرافت . مُرُوّت . مکرمت . (دستوراللغة). وارستگی . مردمی <span class=\"hlight\">:</span> <br />همه آزادگی و همت تو<br />قهر کرده ست مر کیانا را.<br /> <font color=\"Red\">خسروانی یا خسروی .</font><br />ابوالمظفر شاه چغانیان که برید<br />به تیز دشنه ٔ آزادگی گلوی سؤال .<br /> <font color=\"Red\">منجیک .</font><br />بداد و دهش دل توانگر کنید<br />از آزادگی بر سر افسر کنید.<br /> <font color=\"Red\">فردوسی .</font><br />بزرگان گنج سیم و زر گوالند<br />تو از آزادگی مردم گوالی .<br /> <font color=\"Red\">طیان مرغزی .</font><br />به آزادگی از همه شهریاران <br />پدیدار همچون یقین از گمانی .<br /> <font color=\"Red\">فرخی .</font><br />اینت آزادگی و بارخدائی و کرم <br />اینت احسانی کآن را نه کران است و نه مر.<br /> <font color=\"Red\">فرخی .</font><br />ای صورت تو بر فلک رادی آفتاب <br />ای عادت تو بر تن آزادگی روان .<br /> <font color=\"Red\">فرخی .</font><br />نشان کریمی ّ و آزادگی <br />برآوردن مردم ممتحن <br />به آزادمردی ّ و آزادگی <br />تو کس دیده ای درخور خویشتن ؟<br />از آزادگان هرکه او پیشتر<br />بشکر تو دارد زبان مرتهن ...<br /> <font color=\"Red\">فرخی .</font><br />آزادگی آموخته زو طریق <br />رادی گرفته زو رسوم و سنن <br />وآزادگان را برکشیده ز چاه <br />چاهی که پایانش نیابد رسن .<br /> <font color=\"Red\">فرخی .</font><br />ای به آزادگی ّ و نیک خوئی <br />نه عجم دیده چون تو و نه عرب .<br /> <font color=\"Red\">فرخی .</font><br />تو را بمردی و آزادگی میان سپاه <br />هزار نام بدیع است و صدهزار لقب .<br /> <font color=\"Red\">فرخی .</font><br />ای خوی تو خجسته و رای تو چون تو راست <br />دائم تو را بفضل و به آزادگی هواست .<br /> <font color=\"Red\">فرخی .</font><br />بعلم و عدل و به آزادگی ّ و نیکخوئی <br />مؤیّد است و موفق مقدم است و امام .<br /> <font color=\"Red\">فرخی .</font><br />ملک چنانکه ز آزادگی سزید گزید<br />ز آهوان چو نگاری ز بتکده ٔ فرخار.<br /> <font color=\"Red\">فرخی .</font><br />بدین کریمی و آزادگی که داند بود<br />مگر امیر نکوسیرت نکوکردار.<br /> <font color=\"Red\">فرخی .</font><br />ای بحرّی و به آزادگی از خلق پدید<br />چون گلستان شکفته ز سیه شورستان .<br /> <font color=\"Red\">فرخی .</font><br />همه پادشاهان همی زو زنند<br />بشاهی ّ و آزادگی داستان .<br /> <font color=\"Red\">فرخی .</font><br />دانش و آزادگی ّ و دین و مروت <br />این همه را خادم درم نتوان کرد.<br /> <font color=\"Red\">عنصری .</font><br />هزار سال همیدون بزی بپیروزی <br />بمردمی ّ و به آزادگی ّ و نیک خوی .<br /> <font color=\"Red\">منوچهری .</font><br />خوی بد اندر ره آزادگی <br />قید دو دست و غل بر گردنست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />در ره آزادگیست قول وی و فعل وی <br />پاک ز تزویر و زرق دور ز تلبیس و بند.<br /> <font color=\"Red\">سوزنی .</font><br />طریق صدق بیاموز ز آب صاف ای دل <br />براستی طلب آزادگی ز سرو چمن .<br /> <font color=\"Red\">حافظ.</font><br />سر به آزادگی از خلق برآرم چون سرو<br />گردهد دست که دامن ز جهان درچینم .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> آسایش . آسودگی . شادی <span class=\"hlight\">:</span> <br />هست خلّت عین کارافتادگی <br />گر خلیلی کم طلب آزادگی .<br /> <font color=\"Red\">عطار.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آزادگی کردن </span> ؛ جوانمردی نمودن <span class=\"hlight\">:</span> <br />نه جز آزادگی کردن ترا کاری همی بینم .<br /> <font color=\"Red\">فرخی .</font><br />بر ظن نیکوقصد کردم بدو<br />آزادگی کرد و وفا کرد ظن .<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آزادگی نمودن </span> ؛ ابراز، اظهار و اعلام آزادگی <span class=\"hlight\">:</span> <br />آزاده برکشیدن و رادان رسوم اوست <br />وآزادگی نمودن و رادی شعار او.<br /> <font color=\"Red\">فرخی .</font><br />زآزادگی نمودن کردارهای نیک <br />آزادگان بشکر تو گشتند مرتهن .<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آزادگی و طمع بهم ناید</span> .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(1235, 'آزادی', '<span class=\"hlight\">آزادی .</span> (حامص ) عتق . حریت . اختیار. خلاف بندگی و رقیت و عبودیت و اسارت و اجبار. قدرت عمل و ترک عمل . قدرت انتخاب <span class=\"hlight\">:</span> <br />به آزادی است از خرد هر کسی <br />چنان چون ننالد ز اختر بسی .<br /> <font color=\"Red\">فردوسی .</font><br />جانت آزادی نیابد جز بعلم و بندگی <br />گر بدین برهانْت باید رو بدین اندر نگر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />آزادی اندر بی حاجتی است . (کیمیای سعادت ).<br />آزادی آرزوست مرا دیر سالهاست <br />تا کی ز بندگی، نه کم از سرو و سوسنم .<br /> <font color=\"Red\">عمادی شهریاری .</font><br /> <BR><font color=\"Blue\">◄</font> جدائی . دوری <span class=\"hlight\">:</span> <br />ز مهر خویش جز شادی نبینم <br />که از پیروزی آزادی نبینم .<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> رهائی . خلاص . <BR><font color=\"Blue\">◄</font> آزادمردی . <BR><font color=\"Blue\">◄</font> شادی . خُرّمی . خشنودی .رضا <span class=\"hlight\">:</span> <br />بدو گفت شاه ای زن کم سخن <br />یکی داستان گوی با من کهن <br />بدان تا بگفتار تو می خوریم <br />بمی درد و اندوه را بشکریم <br />بتو داستان نیز کردم یله <br />از این شاهت آزادی است ار گله <br />زن کم سخن گفت آری نکوست <br />هم آغاز و فرجام هر کار از اوست .<br /> <font color=\"Red\">فردوسی .</font><br />تا دلم نستدی نیاسودی <br />چون توان کرد از تو آزادی ؟<br /> <font color=\"Red\">فرخی .</font><br />خداوندا بدین مایه بکردم بر تو استادی <br />نه زآن گفتم من این کز تو پدر را نیست آزادی .<br /> <font color=\"Red\">فرخی .</font><br />سپهبد فرستاد نامه بشاه <br />ز پیروزی و کار آن رزمگاه <br />ز رزم نریمان یل روز کین <br />وز آزادی شاه توران زمین .<br /> <font color=\"Red\">اسدی .</font><br />که داند گفت چون بد شادی ویس <br />ز مرد چاره گر آزادی ویس .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />نشسته ویس چون خورشید بر تخت <br />هم از خوبی به آزادی هم از بخت .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />چو فغفور بنهاد در کاخ پای <br />بیامد سر خادمان سرای <br />ز گرشاسب آزادی آورد پیش <br />همان نیز خاتون، زاندازه بیش <br />که بر ما ز تو مهر به داشته ست <br />پس پرده بیگانه نگذاشته ست .<br /> <font color=\"Red\">اسدی .</font><br />ترا روز برنائی و شادی است <br />ز بختت بصد گونه آزادی است .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />ای گروه مؤمنان شادی کنید<br />همچو سرو و سوسن آزادی کنید.<br /> <font color=\"Red\">مولوی .</font><br />آنکه زو هر سرو آزادی کند<br />قادر است ار غصه را شادی کند.<br /> <font color=\"Red\">مولوی .</font><br />جَستن چشم راست از شادی <br />خبرت گوید و ز آزادی .<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> خوشی . استراحت <span class=\"hlight\">:</span> <br />ای جهانی ز تو به آزادی <br />بر من از تو چراست بیدادی ؟<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> شکر.شکر گفتن . (اوبهی ). سپاس . حق شناسی . مدح . ثنا: پس ازوی اندرگذشت و بعلم ِ عَم ّ خویش برزافره <font color=\"DarkGreen\"><b>[ فریبرز ]</font></b> بگذشت کشتگان دید بسیار، و گودرز ابا برزافره آزادی بسیار کرد او را <font color=\"DarkGreen\"><b>[ که ]</font></b> اندر این حرب کار بسیار کرد (کذا). (ترجمه ٔ طبری بلعمی ). ابلیس پیش ایشان شد و بنشست و از حال ایشان بپرسید آدم از خدای تعالی شکری کرد و آزادی کرد و تسبیح کرد خدای را. (بلعمی، ترجمه ٔطبری ).<br />نیا طوس را دید و در بر گرفت <br />بپرسید و آزادی اندرگرفت <br />ز قیصر که برداشت آنگونه رنج <br />ابا رنج لشکر تهی کرد گنج .<br /> <font color=\"Red\">فردوسی .</font><br />کنون آفرین تو شد ناگزیر<br />بما هرکه هستیم برنا و پیر<br />هم آزادی تو بیزدان کنیم <br />دگر پیش آزادمردان کنیم .<br /> <font color=\"Red\">فردوسی .</font><br />نعمتی بهتر از آزادی نیست <br />بر چنین مائده کفران چه کنم ؟<br /> <font color=\"Red\">خاقانی .</font><br />هرگز نفسی حکایت از تو نکنم <br />کآزادی بی نهایت از تو نکنم <br />از دل نکنم شکایتی از تو کنم (کذا)<br />وز دل کنم این شکایت از تو نکنم .<br /> <font color=\"Red\">ظهیر فاریابی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آزادی آبادیست </span> .<br /><span class=\"hlight\">آزادی اندر بی حاجتی است </span> .<br /></font></div>'),
(1236, 'آزادی طلب', '<span class=\"hlight\">آزادی طلب .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (نف مرکب ) آزادیخواه .<br /></font></div>'),
(1237, 'آزادی طلبی', '<span class=\"hlight\">آزادی طلبی .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (حامص مرکب ) چگونگی و صفت آزادی طلب . آزادیخواهی .<br /></font></div>'),
(1238, 'آزادیخواه', '<span class=\"hlight\">آزادیخواه .</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) طرفدار حکومت آزاد. آزادی طلب .<br /></font></div>'),
(1239, 'آزادیخواهی', '<span class=\"hlight\">آزادیخواهی .</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (حامص مرکب ) چگونگی و صفت آزادیخواه . آزادی طلبی .<br /></font></div>'),
(1240, 'آزاذوار', '<span class=\"hlight\">آزاذوار.</span> <font color=\"DarkGreen\"><b>[ زاذْ ]</font></b> (اِخ ) نام شهری کوچک از اعمال جوین از سوی قومِس . آزادوار.<br /></font></div>'),
(1241, 'آزار', '<span class=\"hlight\">آزار.</span>(اِمص، اِ) اَذا. ایذاء. اذیت . اذاة. رنج که دهند. رنجگی . عذاب . شکنجه . عقوبت . آسیب . گزند <span class=\"hlight\">:</span> <br />آزار بیش بینی زین گردون <br />گر تو بهر بهانه بیازاری .<br /> <font color=\"Red\">رودکی .</font><br />دل گسسته داری از بانگ بلند<br />رنجگی باشدْت و آزار <font color=\"DarkGreen\"><b>[ و ]</font></b> گزند.<br /> <font color=\"Red\">رودکی .</font><br />پسندش نیامد همی کار من <br />بکوشد برنج و به آزار من .<br /> <font color=\"Red\">فردوسی .</font><br />نیامدْش با مغز گفتار اوی <br />سرش تیزتر شد به آزار اوی ...<br /><font color=\"Red\">فردوسی .</font><br />ز بس زشت گفتار و کردار اوی <br />ز بیدادی و درد و آزار اوی ...<br /> <font color=\"Red\">فردوسی .</font><br />پشوتن بدو گفت کاین است راه <br />بدین باش و آزار مردان مخواه .<br /> <font color=\"Red\">فردوسی .</font><br />بدانست کاین جادوئی کار اوست <br />بدو بد رسیدن ز آزار اوست .<br /> <font color=\"Red\">فردوسی .</font><br />وگر سر بپیچم ز گفتار اوی <br />هراسان شود دل ز آزار اوی .<br /> <font color=\"Red\">فردوسی .</font><br />ور بدرّی شکم و بندم از بندم <br />نرسد ذره ای آزار بفرزندم .<br /> <font color=\"Red\">منوچهری .</font><br />من نیز از این پس تان ننمایم آزار.<br /> <font color=\"Red\">منوچهری .</font><br />سوگندان خورد... که ترا هیچ آزار از جهت من نباشد و با تو خیانت نکنم . (تاریخ سیستان ).<br />امروز آزار کس مجوی که فردا<br />هم ز تو بی شک بجان تو رسد آزار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چون که بجوئی همی آزار من <br />گر نپسندی ز من آزار خویش ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />جانش از آزار آن جهان برهد<br />هرکه ز دین گرد جان حصار کند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />جز که آزار و خیانت نشناسند ازیرا<br />ببدی فعل چو ماران و چو موشان بشمارند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />بنالد همی پیش گل زار بلبل <br />که از زاغ آزار بسیار دارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />غیبت مکن و مجوی کس را آزار<br />هم وعده ٔ آن جهان منم باده بیار.<br /> <font color=\"Red\">خیام .</font><br />گرْت خوی شیر و زور پیل و سم مار نیست <br />همچو مورو پشه و روباه کم آزار باش .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> کین . کینه . عداوت . بغض . بغضاء. دلتنگی . آزردگی . ملال . ملالت خاطر. <BR><font color=\"Blue\">◄</font> رنجیدگی .رنجش . شکرآب <span class=\"hlight\">:</span> <br />دل من پرآزار از آن بدسگال <br />نبد دست من چیر بر بدهمال .<br /> <font color=\"Red\">ابوشکور.</font><br />ز من خسرو آزار دارد همی <br />دلش از رهی بار دارد همی .<br /> <font color=\"Red\">فردوسی .</font><br />ترا و مرا رنج بسیار داد<br />روان وی از ما بی آزار باد.<br /> <font color=\"Red\">فردوسی .</font><br />بهنگام بدرود کردنْش گفت <br />که آزار داری ز من در نهفت <br />گرت هست با شاه ایران بگوی <br />نباید ترا زین سخن رنگ و بوی .<br /> <font color=\"Red\">فردوسی .</font><br />ز ره چون بدرگاه شد بار یافت <br />دل تاجور را بی آزار یافت .<br /> <font color=\"Red\">فردوسی .</font><br />غمین گشت <font color=\"DarkGreen\"><b>[ کاوس ]</font></b> و سودابه را خوار کرد<br />دل خویشتن زو پر آزار کرد.<br /> <font color=\"Red\">فردوسی .</font><br />تو نیز همه روز در اندیشه ٔ آنی <br />کآن چیز کنی کز تو نگیرد دلش آزار.<br /> <font color=\"Red\">فرخی .</font><br />و خلف بن اللیث از عمرو<font color=\"DarkGreen\"><b>[ بن لیث ]</font></b> به آزار رفته بود و بدرگاه خلیفت شده . (تاریخ سیستان ). شاه محمود که پسر مهتر ملک معظم نصیر الحق و الدین است و چند گاه پدر بدیدار جهان آرای او شد و او در خدمت پدر متفق اللفظ والمعنی ملازم تا چنان اوفتاد که بجهت جمعی از عشایر و قبایل مادر، در میان او و پدر آزاری ظاهر گشت و چشم زخم افتاد و شاه معظم رکن الدین محمود بخشم رفت . (تاریخ سیستان ). گفت بدرود باش ای دوست نیک که بروزگار دراز در یک جا بوده ایم و از یکدیگر آزار نداریم . (تاریخ بیهقی ). کسانی که خواجه از ایشان آزاری داشت نیک بشکوهیدند. (تاریخ بیهقی ). ابن الزیات را بکشت بسبب آزاری که از وی داشت بعهد برادرش واثق . (مجمل التواریخ ). اگر در دل او آزاری باقی است ناگاه خیانتی اندیشد. (کلیله و دمنه ).<br />که سلام ما بقاضی بر کنون <br />بازگو آزار ما زین مرد دون .<br /> <font color=\"Red\">مولوی .</font><br />حکما گفته اند هرکه را رنجی بدل رسانیدی ...از پاداش آن نیز ایمن مباش که پیکان از جراحت بدر آید و آزار در دل بماند. (گلستان ).<br />اگر آزاری از من داری که مرا از آن آگاهی نیست بازگوی . (آثارالوزراء عقیلی ). <BR><font color=\"Blue\">◄</font> اندوه . غم . تیمار <span class=\"hlight\">:</span> <br />کنون روزگاری بدین برگذشت <br />دل ما پر آزار و تیمار گشت .<br /> <font color=\"Red\">فردوسی .</font><br />نسوزد دلت بر چنین کارها<br />بدین درد و تیمار و آزارها.<br /> <font color=\"Red\">فردوسی .</font><br />کنون بشنو از من تو ای رادمرد<br />یکی داستانی پر آزار و درد.<br /> <font color=\"Red\">فردوسی .</font><br />زمانه نخواهم به آزارتان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> تعب . مشقت . ماندگی <span class=\"hlight\">:</span> <br />چو آسوده شد باره ٔ هر دو مرد<br />ز آزار جنگ و ز ننگ و نبرد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> تألم . توَجّع. رنجیدگی <span class=\"hlight\">:</span> <br />بنزد کهان و بنزد مهان <br />به آزار موری نیرزد جهان .<br /> <font color=\"Red\">فردوسی .</font><br />چو رامین دید کو را دل بیازرد<br />نگر تا پوزش آزار چون کرد.<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> بیماری .مرض . ناخوشی . داء. درد. عاهت : آزار جوع . <BR><font color=\"Blue\">◄</font> بیماری، چون جنون و هاری : مگر آزار داری ! <BR><font color=\"Blue\">◄</font> ضرب . کوب . صدمه . <BR><font color=\"Blue\">◄</font> آفت جراحت . <BR><font color=\"Blue\">◄</font> زحمت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">بکش آزار کسان و مکن آزار کسی </span> .<br /> <font color=\"Red\">هاتف .</font><br /> <span class=\"hlight\">بهشت آنجاست کآزاری نباشد</span><br />کسی را با کسی کاری نباشد.<br /> <font color=\"Red\">(مصاحب ).</font><br /> <span class=\"hlight\">مباش در پی آزار و هرچه خواهی کن </span> <br />که در شریعت ما غیر از این گناهی نیست .<br /> <font color=\"Red\">حافظ.</font><br /> <span class=\"hlight\">هرچه نه آزار نه گناه </span> . (خواجه عبداﷲ انصاری ).<br /> <BR><font color=\"Blue\">◄</font> (نف مرخم ) مخفف آزارنده، در مانند: جان آزار، خاطرآزار، دل آزار، زیردست آزار، کم آزار، گوش آزار، مردم آزار، همسایه آزار. <BR><font color=\"Blue\">◄</font> (ن مف مرخم <span class=\"hlight\" dir=\"rtl\">/</span> نف مرخم ) مخفف آزارده یا آزرده، چون در زودآزار، به معنی زودرنج <span class=\"hlight\">:</span> <br />زودبیز و تند و زودآزار باشد هر شهی <br />خواجه باری زودبیز و تند و زودآزارنیست .<br /><font color=\"Red\">فرخی .</font><br /></font></div>'),
(1242, 'آزار دادن', '<span class=\"hlight\">آزار دادن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص مرکب ) رنج و درد و الم دادن . آزردن . اذیت کردن . ایذاء. آزار کردن . رنجانیدن .<br /></font></div>'),
(1243, 'آزار نمودن', '<span class=\"hlight\">آزار نمودن .</span> <font color=\"DarkGreen\"><b>[ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) اظهار رنجش کردن : از ما نه بحقیقت آزاری نمود. (تاریخ بیهقی ).<br /></font></div>'),
(1244, 'آزار کردن', '<span class=\"hlight\">آزار کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) آزردن .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1245, 'آزار گرفتن', '<span class=\"hlight\">آزار گرفتن .</span> <font color=\"DarkGreen\"><b>[ گ ِ رِ ت َ ]</font></b> (مص مرکب ) آزار گرفتن از کسی ؛ از او رنجیده و دلتنگ شدن . به او خشم گرفتن <span class=\"hlight\">:</span> <br />همه بندگانیم و فرمان تراست <br />چه آزار گیری ز ما، جان تراست .<br /> <font color=\"Red\">فردوسی .</font><br />از این پس کسری از بزرجمهر آزار گرفت و چون از روم بازگشت او را بازداشت مدتها تا از آن تنگی و رنج چشمش تباه شد. (مجمل التواریخ ).<br /></font></div>'),
(1246, 'آزارتلخه', '<span class=\"hlight\">آزارتلخه .</span> <font color=\"DarkGreen\"><b>[ ت َ خ َ <span class=\"hlight\" dir=\"rtl\">/</span> خ ِ ]</font></b> (اِ مرکب ) یرقان . زردی (نام نوعی از بیماری ).<br /></font></div>'),
(1247, 'آزاردن', '<span class=\"hlight\">آزاردن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) (از پهلوی آزاریتن، بمعنی خستن و رنجانیدن ) ایذاء. اذیت . رنجاندن . رنجه کردن . گزند و صدمه و آسیب رسانیدن . آزردن . آزار دادن . عذاب دادن . خرابی و ویرانی کردن . بریدن . خستن . ریش و افکار کردن . بخشم آوردن . آزرده شدن . رنجیدن <span class=\"hlight\">:</span> <br />آزار بیش بینی از گردون <br />گر تو بهر بهانه بیازاری .<br /> <font color=\"Red\">رودکی .</font><br />ای دل من زو بهر حدیث میازار<br />کآن بت فرهخته نیست هست نوآموز.<br /> <font color=\"Red\">دقیقی .</font><br />به نیکی گرای و میازار کس <br />ره رستگاری همین است و بس .<br /> <font color=\"Red\">فردوسی .</font><br />از این پس بر و بوم مرز ترا<br />نیازارم ازبهر ارز ترا.<br /> <font color=\"Red\">فردوسی .</font><br />میازار موری که دانه کش است <br />که جان دارد و جان شیرین خوش است <br />پسندی و همداستانی کنی <br />که جان داری و جانستانی کنی .<br /> <font color=\"Red\">فردوسی .</font><br />نیازارد او را کسی زین سپس <br />کز او یافتم در جهان داد و بس .<br /> <font color=\"Red\">فردوسی .</font><br />چو من حق فرزند بگذاردم <br />کسی را بگیتی نیازاردم <br />شما هم بر این عهد من بگذرید...<br /> <font color=\"Red\">فردوسی .</font><br />به ره بر کسی تا نیازاردش <br />وز آن دشمنان نیز نشماردش .<br /> <font color=\"Red\">فردوسی .</font><br />یکی دست بگرفت و بفشاردش <br />همی آزمون را بیازاردش .<br /> <font color=\"Red\">فردوسی .</font><br />بشهری کجا برگذشتی سپاه <br />نیازاردی کشتمندی براه .<br /> <font color=\"Red\">فردوسی .</font><br />بدیوانها شاد بگذاردند<br />کز آن پس کسی را نیازاردند.<br /> <font color=\"Red\">فردوسی .</font><br />نیازارم آن را که پیوند تست <br />هم آن را کجا خویش و فرزند تست .<br /> <font color=\"Red\">فردوسی .</font><br />خواهم که بدانم من جانا تو چه خو داری <br />یا از چه برآشوبی یا از چه بیازاری .<br /> <font color=\"Red\">منوچهری .</font><br />یار چون خار ترا زود بیازارد<br />گر نخواهی که بیازارد، مازارش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آزردن ما زمانه خو دارد<br />مازار ازو گرت بیازارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />گرنه مستی تو بی آنکه بیازاریم <br />ما ترا، ما را ازبهرچه آزاری ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />گر بخواهی کت نیازارد کسی <br />بر سر گنج کم آزاری نشین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از آن پس کت نکوئیها فراوان داد بی طاعت <br />گر او را تو بیازاری ترا بی شک بیازارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />اگرچه سخت بیازاری از تو مازاریم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آزار کس نجویم و از هر چیز<br />از دوستان خویش نیازارم .<br /> <font color=\"Red\">مسعودسعد.</font><br />و بباذان ملک یمن کس فرستاد تا پیغامبر را علیه السلام نیازارد. (مجمل التواریخ ).<br />گوئی اندر پناه وصل شوم <br />تو شوی گر فراق بگذارد<br />وصل هم نازموده ای که بلطف <br />خون بریزد که موی نازارد.<br /> <font color=\"Red\">انوری .</font><br />یکی از ملوک بی انصاف پارسائی را پرسید که از عبادتها کدام فاضلتر است ؟ گفت ترا خواب نیم روز تا در آن یک نفس خلق را نیازاری . (گلستان ). هرکه خدای عزوجل را بیازارد تادل مخلوقی به دست آرد خداوند تعالی همان خلق را بر او گمارد تا دمار از روزگارش برآرد. (گلستان ).<br />همای بر همه مرغان از آن شرف دارد<br />که استخوان خورد و جانور نیازارد.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1248, 'آزارده', '<span class=\"hlight\">آزارده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آزرده شده .<br /></font></div>'),
(1249, 'آزارش', '<span class=\"hlight\">آزارش .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِمص ) آزار <span class=\"hlight\">:</span> <br />چنان داشتم ملک را پیش و پس <br />که آزارشی نامد از من بکس .<br /> <font color=\"Red\">نظامی .</font><br />(این کلمه جز در بیت مذکور دیده نشده و ظاهراً بتسامحی که از نظامی معهود است بقیاس بر سایر اسم های مصدر ساخته شده است ).<br /></font></div>'),
(1250, 'آزارمند', '<span class=\"hlight\">آزارمند.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ص مرکب ) صاحب آزار. علیل . بیمار. سقیم .<br /></font></div>'),
(1251, 'آزارنده', '<span class=\"hlight\">آزارنده .</span> <font color=\"DarkGreen\"><b>[ رَ دَ<span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) موذی . موجع. مولِم . متعب . شاق . مجحد.<br /></font></div>'),
(1252, 'آزارود', '<span class=\"hlight\">آزارود.</span> (اِخ ) نام محلی کنار راه چالوس و شهسوار میان نشتاب رود و پلات کلا در <span class=\"hlight\" dir=\"rtl\">٤٤٥٥٠٠</span>گزی طهران .<br /></font></div>'),
(1253, 'آزاری', '<span class=\"hlight\">آزاری .</span> (ص نسبی ) آزارنده . زننده <span class=\"hlight\">:</span> <br />سخن در نامه آزاری چنان بود<br />که خون از حرفهای او چکان بود.<br /><font color=\"Red\">(ویس و رامین ).</font><br /></font></div>'),
(1254, 'آزاری', '<span class=\"hlight\">آزاری .</span> (حامص ) تألم . تأثر. توجع. رنج . الم <span class=\"hlight\">:</span> <br />ابی آنکه بد هیچ بیماریی <br />نه از دردها هیچ آزاریی .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1255, 'آزاریدن', '<span class=\"hlight\">آزاریدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b>(مص ) آزرده شدن . <BR><font color=\"Blue\">◄</font> آزردن . آزرده کردن .<br /></font></div>'),
(1256, 'آزال', '<span class=\"hlight\">آزال .</span> (ع اِ) ج ِ اَزَل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ازل الاَّزال </span> .<br /></font></div>'),
(1257, 'آزج', '<span class=\"hlight\">آزج .</span> <font color=\"DarkGreen\"><b>[ زُ ]</font></b> (ع اِ) ج ِ اَزَج . اوستانها. خانه های دراز. سغها.<br /></font></div>'),
(1258, 'آزجو', '<span class=\"hlight\">آزجو.</span> (نف مرکب ) هوی ̍جو. آرزوجوی <span class=\"hlight\">:</span> <br />نکوهیده باشد جفاپیشه مرد<br />بگرد در آزجویان مگرد.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1259, 'آزخ', '<span class=\"hlight\">آزخ .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِ) واژو. (زمخشری ). بالو. ثؤلول . کوک . اَژخ . زخ . زگیل . پالو. سگیل . وارو. و آن برآمدگیهای خرد باشد چندِ ماشی و بزرگتر، گوشتین برنگ پوست و غیرحساس که بر دستها و گاه بر روی افتد <span class=\"hlight\">:</span> <br />آن سرخ عِمامه بر سر او<br />چون آزخ زشت بر سر ...-ر.<br /> <font color=\"Red\">مرادی .</font><br />ازراستی تو خشم خوری دانم <br />بر بام چشم سخت بود آزخ .<br /> <font color=\"Red\">کسائی .</font><br />و خداوندان فسون آژخ را بوی <font color=\"DarkGreen\"><b>[ به جو ]</font></b> افسون کنند بماه کاست و بپوشانندش تا آزخ فروریزد. (نوروزنامه ).<br />بگرد عارض آن ماه روی چاه زنخ <br />سپاه زنگ درآمد بسان مور و ملخ <br />گل رخانْش ز مشک سیاه خالی داشت <br />چه جرم کرد که گل خار گشت و مشک آزخ ؟<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(1260, 'آزدار', '<span class=\"hlight\">آزدار.</span> (نف مرکب ) آزمند. آزور. ولوع . حریص . مولع.<br /></font></div>'),
(1261, 'آزدف', '<span class=\"hlight\">آزدف .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ) رجوع به اَزدف شود.<br /></font></div>'),
(1262, 'آزدن', '<span class=\"hlight\">آزدن .</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span>زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ دَ ]</font></b> (مص ) آژدن . رجوع به آژدن شود. <BR><font color=\"Blue\">◄</font> بی قرار<font color=\"DarkGreen\"><b>[ ی کردن ]</font></b>. (مؤیدالفضلاء) <span class=\"hlight\">:</span> <br />تا هزارآوا از سرو برآورد آواز<br />گوید او را مزن ای باربد رودنواز<br />که بزاری ّ وی و زخم تو شد از هم باز<br />عابدان را همه در صومعه پیوند نماز<br />تو بدو گوی که ای بلبل خوشگوی میاز<br />که مرا در دل عشق است بدین ناله ٔ زار.<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(1263, 'آزده', '<span class=\"hlight\">آزده .</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) رجوع به آژده شود.<br /></font></div>'),
(1264, 'آزر', '<span class=\"hlight\">آزر.</span><font color=\"DarkGreen\"><b>[ زَ ]</font></b> (ع ص ) اسبی که هر دو ران سپید دارد و دو پای پیشین سیاه یا برنگی دیگر. <BR><font color=\"Blue\">◄</font> اسب که سرین وی سپید بود. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> دشنام گونه ای که معنی آن کج طبع یا لنگ یا خرف یا مخطی است .<br /></font></div>'),
(1265, 'آزر', '<span class=\"hlight\">آزر.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِمص، اِ) مخفف آزار. (برهان ). <BR><font color=\"Blue\">◄</font> (ص ) کج طبع. (برهان ).<br /></font></div>'),
(1266, 'آزر', '<span class=\"hlight\">آزر.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (فعل امر) صیغه ٔ امر از آزردن <span class=\"hlight\">:</span> <br />نگار و صورت آن بت به هند و چین در هم <br />شکست خامه ٔ مانی و رنده ٔ آزر<br />نگار آزر و مانی غلام صورت اوست <br />ز من بدین که بگفتم گر آزری آزر.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(1267, 'آزر', '<span class=\"hlight\">آزر.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) نام پدر ابراهیم پیغامبر علیه السلام . و او را آزر بت گر و آزر بت تراش نیز گویند <span class=\"hlight\">:</span> <br />دعوی کنند گرچه براهیم زاده ایم <br />چون ژرف بنگری همه شاگرد آزرند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />ابراهیم را چه زیان که آزر پدر اوست و آزررا چه سود که ابراهیم پسر اوست ؟ (خواجه عبداﷲ انصاری ).<br />نگار و صورت آن بت به هند و چین در هم <br />شکست خامه ٔ مانی و رنده ٔ آزر.<br /> <font color=\"Red\">سوزنی .</font><br />و سنت جاهلان است که چون بدلیل از خصم فرومانند سلسله ٔ خصومت جنبانند چون آزربت تراش که ... (گلستان ).<br />هنر بنمای اگر داری نه گوهر<br />گل از خارست و ابراهیم از آزر.<br /> <font color=\"Red\">سعدی .</font><br />و گفته اند که نام پدر ابراهیم تارخ است و آزر عم ابراهیم است . <BR><font color=\"Blue\">◄</font> نام بتی . (مهذب الاسماء) (ربنجنی ). <BR><font color=\"Blue\">◄</font> نام بتی که تارخ پدر ابراهیم سادن و خادم او بوده است .<br /></font></div>'),
(1268, 'آزر', '<span class=\"hlight\">آزر.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) نام ناحیه ای میان سوق اهواز <font color=\"DarkGreen\"><b>[ خوزیان واچار ]</font></b> و رامهرمز. <BR><font color=\"Blue\">◄</font> مدینه ٔ آزر؛ نام شهری بوده میان بصره و کوفه، و آن را اَطد و اَطط نیز می نامیده اند.<br /></font></div>'),
(1269, 'آزرد', '<span class=\"hlight\">آزرد.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِ) رنگ . لون . گونه . آرنگ <span class=\"hlight\">:</span> <br />ابر فروردین بباران در چمن پرورد ورد<br />گشت خیری با فراق نرگسش آزرد زرد.<br /> <font color=\"Red\">قطران .</font><br />بوستان از بانگ مرغان پرخروش زیر گشت <br />گلستان آزرد گوهر چون سریر میر گشت .<br /><font color=\"Red\">قطران .</font><br /></font></div>'),
(1270, 'آزرد', '<span class=\"hlight\">آزرد.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (مص مرخم، اِمص ) آزردگی . در شاهنامه های چاپی بیت ذیل دیده میشود <span class=\"hlight\">:</span> <br />منوچهر از این کار پردردشد<br />زمهراب و دستان پرآزرد شد.<br />(درجای دیگر این کلمه را ندیده ام و بیت را هم در شاهنامه ٔ خطی و نسبةً معتمدی که در حدود <span class=\"hlight\" dir=\"rtl\">٨٥٠</span> هَ . ق . نوشته شده نیافتم و احتمال میدهم که بیت مجعول باشد).<br /></font></div>'),
(1271, 'آزردن', '<span class=\"hlight\">آزردن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ ]</font></b> (مص ) رنجیدن . دلگیر شدن . دلتنگ شدن . رنجیده شدن . متأثر گشتن . تأذّی . ملول شدن . متألم گردیدن . آزرده شدن . دلخور شدن <span class=\"hlight\">:</span> <br />نه آن زین بیازرد روزی بنیز<br />نه این را از آن اندهی بود نیز.<br /> <font color=\"Red\">ابوشکور.</font><br />مشو شادمان گر بدی کرده ای <br />که آزرده گردی گر آزرده ای .<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمد بهر مهتری <br />که بد مرزبان بر سر کشوری <br />که خسرو بیازرد از شهریار<br />برفته ست با خوارمایه سوار...<br /> <font color=\"Red\">فردوسی .</font><br />همی گفت اگر من گنه کرده ام <br />ازیرا به بند اندر آزرده ام .<br /> <font color=\"Red\">فردوسی .</font><br />گر از ما بچیزی بیازرد شاه <br />وز آزار او هست ما را گناه <br />بگوید بما تا دلش خوش کنیم <br />پر از خون رخ و دل پرآتش کنیم .<br /> <font color=\"Red\">فردوسی .</font><br />چو رامین دید کو را دل بیازرد<br />نگر تا پوزش آزار چون کرد.<br /> <font color=\"Red\">(ویس ورامین ).</font><br />بدان روزگار که بمولتان میرفت تا آنجا مقام کند که پدرش از وی بیازرده بود... (تاریخ بیهقی ). خدمتی چند سره بکردند <font color=\"DarkGreen\"><b>[ ترکمانان ]</font></b> و آخر بیازردند <font color=\"DarkGreen\"><b>[ از مسعودبن محمود غزنوی ]</font></b> و بسر عادت خویش که غارت بود بازشدند. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> ایذاء. اذیت . رنجانیدن . ملول کردن . رنجه کردن . رنجور کردن . اشذاء. گزند و صدمه و آسیب رسانیدن . عذاب دادن .خرابی و ویرانی کردن . آزار دادن . آزار کردن . آزاردن بزبان یا دست یا هر چیز دیگر <span class=\"hlight\">:</span> <br />برآشفت و سودابه را پیش خواند<br />گذشته سخنها بدو بازراند<br />که بی شرمی و بدبسی کرده ای <br />فراوان دل من بیازرده ای <br />نشاید که باشی تواندر زمین <br />جز آویختن نیست پاداش این .<br /> <font color=\"Red\">فردوسی .</font><br />وز آن پس بیامد به نزدیک بلخ <br />نیازرد کس را بگفتار تلخ .<br /> <font color=\"Red\">فردوسی .</font><br />ز موبد شنیدستم این داستان <br />که برخواند از گفته ٔ باستان <br />که پرهیز از آن کن که بد کرده ای <br />که او را به بیهوده آزرده ای .<br /> <font color=\"Red\">فردوسی .</font><br />من او را نیازردم از هیچ روی <br />ز دشمن بود این زمان کینه جوی .<br /> <font color=\"Red\">فردوسی .</font><br />ز ره بازگشت آن زمان شاه روم <br />نیازرد خاک اندر آن مرز و بوم .<br /> <font color=\"Red\">فردوسی .</font><br />نیازرد شاه ترا شاه روم <br />سپردش ورا لشکر و گنج و بوم .<br /> <font color=\"Red\">فردوسی .</font><br />و هرگز من و پدران من بمثل مورچه ای را نیازرده ایم تا به هلاک آدمی چه رسد. (تاریخ برامکه ). ملک را سیرت حق شناسی از او پسند آمد و خلعت و نعمت بخشید و عذر خواست که خطا کردم ترابی جرم و خطا آزردن . (گلستان ). گفتا بعون خدای عز وجل هر مملکتی را که بگرفتم رعیتش را نیازردم . (گلستان ).<br />زد نعره که این چه دوست داریست <br />آزردن دوستان نه یاریست .<br /> <font color=\"Red\">امیرخسرو.</font><br />علم دانستن قفیز و نقیر<br />عمل آزردن یتیم و فقیر.<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> بغضب آوردن . خشمگین کردن <span class=\"hlight\">:</span> <br />خدا و جز خدا از من بیازرد<br />همه کس در جهانم سرزنش کرد.<br /> <font color=\"Red\">(ویس و رامین ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بر خود بیازردن، بیازردن بر کسی </span> ؛ بخود خشمگین کردن، خشم گرفتن بر کسی <span class=\"hlight\">:</span> <br />چنان بر ویس و بر ویرو بیازرد<br />که گشت از کین دل رنگ رخش زرد.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />اگر دوست بر خود نیازردمی <br />کی از دست دشمن جفابردمی ؟<br />بناچار دشمن بدرّدْش پوست <br />رفیقی که بر خود بیازرد دوست .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> بریدن . مجروح کردن . خستن . ریش کردن . افکار کردن . جراحت وارد آوردن <span class=\"hlight\">:</span> <br />چو اندر سری بینی آزار خلق <br />بشمشیر تیزش بیازار حلق .<br /> <font color=\"Red\">سعدی .</font><br />یکی تیری افکند و در ره فتاد<br />وجودم نیازرد و رنجم نداد.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آزردن آب را</span> ؛ آلودن آن . شستن شوخ تن و پلیدیهای دیگردر او <span class=\"hlight\">:</span> آبان روز از آب پرهیز کن و آب مازار. (اندرز آذرباد ماراسپندان ).<br />کشیشان ِ هرگز نیازرده آب <br />بغلها چو مردار در آفتاب .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آزردن دوستان جهل است و کفارت یمین سهل </span> . (گلستان ).<br /> <span class=\"hlight\">کشتن یا خون ریختن چنانکه موی نیازارد</span> ؛ تعبیری مثلی است بمزاح، با رفق و ملایمت صوری سخت ترین رنج یا ضرر را بر کسی وارد ساختن <span class=\"hlight\">:</span> <br />وصل هم نازموده ای که بلطف <br />خون بریزد که موی نازارد.<br /> <font color=\"Red\">انوری .</font><br />و اسم مصدر یا مصدر دویم آن آزرش است قیاساً. آزردم . بیازر.<br /></font></div>'),
(1272, 'آزردنی', '<span class=\"hlight\">آزردنی .</span><font color=\"DarkGreen\"><b>[ زَ دَ ]</font></b> (ص لیاقت ) اَزدَرِ آزردن . درخور آزردن .<br /></font></div>'),
(1273, 'آزرده', '<span class=\"hlight\">آزرده .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) رنجیده . ملول . رَنجه . دلتنگ . آزاردیده . رنج دیده . زیان رسیده <span class=\"hlight\">:</span> <br />گر این خواسته زو پذیرم همه <br />ز من گردد آزرده شاه و رَمه .<br /> <font color=\"Red\">فردوسی .</font><br />بسی گشتم آزرده از روزگار<br />ببخشد گناه مرا شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />همیشه بداندیشت آزرده باد<br />بدانش روان تو پرورده باد.<br /> <font color=\"Red\">فردوسی .</font><br />که آزرده گشته ست از تو پدر<br />یکی پوزش آور مکش هیچ سر.<br /> <font color=\"Red\">فردوسی .</font><br />ببخشید <font color=\"DarkGreen\"><b>[ اسفندیار ]</font></b> از آن رزمگه خواسته <br />سوار و پیاده شد آراسته <br />سران را سپرد آنچه آورده بود<br />بکشت آنکه زو لشکر آزرده بود.<br /> <font color=\"Red\">فردوسی .</font><br />بدو داد فرزند گم کرده را<br />وزو کرد خشنود آزرده را.<br /> <font color=\"Red\">فردوسی .</font><br />مشو شادمان گر بدی کرده ای <br />که آزرده گردی گر آزرده ای .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آزرده شدن کسی از اختر</span> ؛نُحوسَت از وی بدو رسیدن :<br />بناکام رزمی گران کرده شد<br />فراوان کس از اختر آزرده شد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> خسته . مجروح . متأذی . مصدوم . متألم <span class=\"hlight\">:</span> <br />ز خون در کَفَش خنجر افسرده بود<br />بر و کتفش از جوشن آزرده بود.<br /> <font color=\"Red\">فردوسی .</font><br />گرت رای بیند چو شیر ژیان <br />بکشتی ببندیم هر دو میان <br />بدان تا که را بر دهد روزگار<br />که برگردد آزرده از کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />تو گر پیش شمشیر مهر آوری <br />سرت گردد آزرده زین داوری .<br /> <font color=\"Red\">فردوسی .</font><br />سر خصم اگر بشکند مشت تو<br />شود نیز آزرده انگشت تو.<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> غضب گرفته . بخشم آمده <span class=\"hlight\">:</span> <br />از او پاک یزدان چو شد خشمناک <br />بدانست <font color=\"DarkGreen\"><b>[ جمشید ]</font></b> و شد شاه با ترس و باک <br />که آزرده شد پاک یزدان از اوی <br />بدان درد درمان ندید ایچ روی .<br /> <font color=\"Red\">فردوسی .</font><br />همی خواست تا بر پسر شهریار<br />سر آرد مگر بی گنه روزگار<br />پدر گردد آزرده زو در جهان <br />ستاند روانش یکی در نهان .<br /> <font color=\"Red\">فردوسی .</font><br />چون منصور بنشست حیلت کشتن ابومسلم کرد که از وی بروزگار برادر <font color=\"DarkGreen\"><b>[ یعنی سفاح ]</font></b> آزرده بود. (تاریخ سیستان ).<br /></font></div>'),
(1274, 'آزرده جان', '<span class=\"hlight\">آزرده جان .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب ) آزرده خاطر.<br /></font></div>'),
(1275, 'آزرده جانی', '<span class=\"hlight\">آزرده جانی .</span> <font color=\"DarkGreen\"><b>[زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص مرکب ) چگونگی و صفت آزرده جان .<br /></font></div>'),
(1276, 'آزرده خاطر', '<span class=\"hlight\">آزرده خاطر.</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ طِ ]</font></b> (ص مرکب ) رنجیده .<br /></font></div>'),
(1277, 'آزرده خاطری', '<span class=\"hlight\">آزرده خاطری .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ طِ ]</font></b> (حامص مرکب ) حالت و چگونگی آزرده خاطر.<br /></font></div>'),
(1278, 'آزرده دل', '<span class=\"hlight\">آزرده دل .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ دِ ]</font></b> (ص مرکب ) آزرده جان <span class=\"hlight\">:</span> <br />اگر برنخیزد به، آن مرده دل <br />که خسبند از او مردم آزرده دل .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1279, 'آزرده دلی', '<span class=\"hlight\">آزرده دلی .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ دِ ]</font></b> (حامص مرکب ) چگونگی و صفت آزرده دل .<br /></font></div>'),
(1280, 'آزرده پشت', '<span class=\"hlight\">آزرده پشت .</span> <font color=\"DarkGreen\"><b>[ زَدَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ پ ُ ]</font></b> (ص مرکب ) چاروائی که پشت او خسته و ریش شده باشد. <BR><font color=\"Blue\">◄</font> مجازاً، پیری پشت بخم کرده .<br /></font></div>'),
(1281, 'آزرده پشتی', '<span class=\"hlight\">آزرده پشتی .</span> <font color=\"DarkGreen\"><b>[ زَدَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ پ ُ ]</font></b> (حامص مرکب ) چگونگی و صفت آزرده پشت .<br /></font></div>'),
(1282, 'آزرده کردن', '<span class=\"hlight\">آزرده کردن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ک َ دَ ]</font></b> (مص مرکب )رنجانیدن : آزرده کردن بوعبداﷲ از همه زشت تر بود. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> خستن به نیش <span class=\"hlight\">:</span> <br />آزرده کرد کژدم غربت جگر مرا<br />گوئی زبون نیافت ز گیتی مگر مرا.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(1283, 'آزردگی', '<span class=\"hlight\">آزردگی .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) صدمه . جراحت . خستگی . <BR><font color=\"Blue\">◄</font> رنجگی .رنجیدگی . دلتنگی . دلخوری . <BR><font color=\"Blue\">◄</font> خشم . غضب .<br /></font></div>'),
(1284, 'آزرم', '<span class=\"hlight\">آزرم .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) آزرمی . آزرمیدخت <span class=\"hlight\">:</span> <br />یکی دختری داشت آزرم نام <br />ز تاج بزرگان شد او شادکام <br />همی بود بر تخت بر چار ماه <br />به پنجم شکست اندرآمد بگاه .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1285, 'آزرم', '<span class=\"hlight\">آزرم .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِ) شرم . حیا.ادب . نرمی . رفق . لطف و ملایمت در گفتار <span class=\"hlight\">:</span> <br />چو پرسدْت پاسخ ورا نرم گوی <br />سخنهای به آزرم و باشرم گوی .<br /> <font color=\"Red\">فردوسی .</font><br />خردمند بی شرم خواند مرا<br />چو خاقان بی آزرم داند مرا.<br /> <font color=\"Red\">فردوسی .</font><br />دل آرام دارید از چار چیز<br />کز او خوبی و سودمندیست نیز<br />یکی بیم و آزرم و شرم خدای <br />که تا باشدت یاور و رهنمای <br />دگر داد دادن تن خویش را<br />نگه داشتن دامن خویش را.<br /> <font color=\"Red\">فردوسی .</font><br />گر این رستخیز از پی خواسته ست <br />که آزرم و دانش بدو کاسته ست ...<br /> <font color=\"Red\">فردوسی .</font><br />درشتی ز کس نشنود نرمگوی <br />سخن تا توانی به آزرم گوی .<br /> <font color=\"Red\">فردوسی .</font><br />دل نامداران بتو گرم باد<br />روانت پراز شرم و آزرم باد.<br /> <font color=\"Red\">فردوسی .</font><br />چو فرهنگی آموزیش <font color=\"DarkGreen\"><b>[ شاه را ]</font></b> نرم باش <br />بگفتار با شرم و آزرم باش .<br /> <font color=\"Red\">اسدی .</font><br />اگر خواهی باآبروی باشی آزرم راپیشه کن . (منسوب بنوشیروان، از قابوسنامه ).<br />گفت ای بی حیا و بی آزرم <br />این چنین خندی و نداری شرم ؟<br /> <font color=\"Red\">سنائی .</font><br />بوسید برش به رفق و آزرم <br />خارید سرش بناخن شرم .<br /> <font color=\"Red\">امیرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به آزرم </span> ؛ مُؤدب <span class=\"hlight\">:</span> <br />از اینجا برفتند ده تن بدند<br />ببازآمدن یازده تن شدند<br />بر ایشان فزوده ست مردی جوان <br />برخسار همچون گل ارغوان <br />از آن ده برادر به آزرم تر<br />نکوروی و زیبا و باشرم تر.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> خجلت . انفعال . شرمندگی . شرم زدگی <span class=\"hlight\">:</span> <br />ز آزرم خاقان چینی نخست <br />که بهرام از آزرم او دل بشست .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> حرمت . (ربنجنی ). احترام . عزت . قدر. قیمت . منزلت . نام نیک . اعتبار. آبرو. ناموس . ارز. ارج . ادب <span class=\"hlight\">:</span> <br />دروغ ارز و آزرم کمتر کند<br />وگر راست گویی که باور کند.<br /> <font color=\"Red\">ابوشکور.</font><br />مرا پیش خوانی ترا شرم نیست <br />خرد را برِ مغزت آزرم نیست .<br /> <font color=\"Red\">فردوسی .</font><br />جهان را ز کردار بد شرم نیست <br />کسی را به نزدیکش آزرم نیست <br />همیشه بهر نیک وبد دسترس <br />ولیکن نجوید خود آزرم ِ کس .<br /> <font color=\"Red\">فردوسی .</font><br />دل پهلوانان همی گرم دار<br />بگفتار با هرکس آزرم دار.<br /> <font color=\"Red\">فردوسی .</font><br />جهاندار از او هم نه خشنود بود<br />ز تیزی روانش پر از دود بود<br />ز آزرم خاقان چینی نخست <br />که بهرام از آزرم او دل بشست <br />دگر آنکه چیزی که فرمان نبود<br />ببرداشتن خود دلیری نمود.<br /> <font color=\"Red\">فردوسی .</font><br />کرا کار با شاه بدخو بود<br />نه آزرم و نه بخت نیکو بود.<br /> <font color=\"Red\">فردوسی .</font><br />ترا چون سواران دل و شرم نیست <br />مِهان را به نزدیکت آزرم نیست .<br /> <font color=\"Red\">فردوسی .</font><br />ترا خود بدیده درون شرم نیست <br />پدر را بنزد تو آزرم نیست .<br /> <font color=\"Red\">فردوسی .</font><br />جهان را ز کردار بد شرم نیست <br />کسی را به نزدیکش آزرم نیست .<br /> <font color=\"Red\">فردوسی .</font><br />که دانا زد این داستان از نخست <br />که هر کس که آزرم مهمان نجست <br />نباشد خرد هیچ نزدیک اوی <br />نیاز آورد بخت تاریک اوی .<br /> <font color=\"Red\">فردوسی .</font><br />ترا گر زآن برادر شرم بودی <br />مرا پیشت هزار آزرم بودی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />گه آمد کز بزرگان شرم داری <br />برادر را بسی آزرم داری .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />که هرگز نَت آب و نه آزرم باد<br />تنت سوخته زآتش گرم باد.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />مکن ماهرویا دلت نرم دار<br />مرا بیش از این آب و آزرم دار.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />همان روزش از کار معزول کرد<br />بمصر اندرش خوار و مخذول کرد<br />زنش را و وی را بیک جا براند<br />ز بن آب و آزرم ایشان نماند.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />زن پادشا چون بود پارسا<br />بدو رسته باشد ز غم پادشا<br />بذنب زلیخا برآمد عزیز<br />از آزرم و از حشمت و جاه نیز.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بندویه با آن زینت پادشاهی بر بام دیر آمد و آواز داد کی <font color=\"DarkGreen\"><b>[ که ]</font></b> خدای از شما خوشنود باد چنانکه دی و دوش آزرم من داشتید اکنون اگر خواهید کی <font color=\"DarkGreen\"><b>[ که ]</font></b> حق نعمت خاندان من گذارده باشید امروز تا آخر روز مرا مهلت دهید تا توبه تمام کنم . (از فارسنامه ٔ ابن بلخی ). و آزرم و ناموس تو نگاه داشتن لازم آید. (کلیله و دمنه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آزرم داشتن کسی یا چیزی را</span> ؛ محترم شمردن او <span class=\"hlight\">:</span> <br />آزرم دارش ارچه به پیشت بود حقیر<br />ارزان شمارش ارچه بنزدت گران بود.<br /> <font color=\"Red\">مجد همگر.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آزرم نداشتن کسی یا چیزی را</span> ؛ او را بچیزی نشمردن . محل ّ و اهمیتی بدو ندادن <span class=\"hlight\">:</span> <br />ای بزرگی که از بلندی قدر<br />آسمان را نداشتی آزرم .<br /> <font color=\"Red\">انوری .</font><br /> <BR><font color=\"Blue\">◄</font> داد. انصاف . نصفت <span class=\"hlight\">:</span> <br />دو کس را روزگار آزرم داده ست <br />یکی کو مرد و دیگر کو نزاده ست .<br /> <font color=\"Red\">نظامی .</font><br />پیرزنی را ستمی درگرفت <br />دست زد و دامن سنجر گرفت <br />کای ملک آزرم تو کم دیده ام <br />وز تو همه ساله ستم دیده ام .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> یاد: به آزرم من ؛ به یادمن <span class=\"hlight\">:</span> <br />فرامش مکن یک زمان مهر من <br />بدل در نگاریده کن چهر من <br />به آزرم من بیکس سرزده <br />یتیم و اسیر و تبه دل شده <br />بهر جا که بینی یتیم و اسیر<br />نوازش کن او را و انده پذیر.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> اندیشه . دل مشغولی <span class=\"hlight\">:</span> <br />سپه کردن و جنگ را ساختن <br />وز آزرم او مغز پرداختن .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> راحت . رفاه <span class=\"hlight\">:</span> <br />چنین داد پاسخ که آن کز نخست <br />به نیک و بد آزرم ِ هر کس بجست .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> تاب و طاقت . (برهان ) <span class=\"hlight\">:</span><br />سر پهلوانان بدو گرم گشت <br />دل طوس نوذر بی آزرم گشت .<br /> <font color=\"Red\">فردوسی (از جهانگیری ).</font><br /> <BR><font color=\"Blue\">◄</font> سلامت . راحت . <BR><font color=\"Blue\">◄</font> بخواری و زاری گذاشتن . <BR><font color=\"Blue\">◄</font> تقصیر وگناه . <BR><font color=\"Blue\">◄</font> مسلمان شدن . (برهان ). <BR><font color=\"Blue\">◄</font> اندوه . غم <span class=\"hlight\">:</span> <br />که اندرزمانه مرا کودکیست <br />ز آزرم او بر دلم خواب نیست .<br /> <font color=\"Red\">فردوسی (از شعوری ).</font><br /> <BR><font color=\"Blue\">◄</font> جانبداری . طرفداری . رودربایستی <span class=\"hlight\">:</span> <br />دگر دین یزدان پرست است و بس <br />نیازارد او کس به آزرم ِ کس .<br /> <font color=\"Red\">فردوسی .</font><br />بمیدان شدی <font color=\"DarkGreen\"><b>[ اردشیر ]</font></b> بامداد پگاه <br />برفتی کسی کو بدی دادخواه <br />نجستی بداد اندر آزرم ِ کس <br />چه کهتر چه فرزند فریادرس .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> ضرر.زیان . آزار <span class=\"hlight\">:</span> <br />مگرد در پی آزرم و قول من بشنو<br />مباش بر سر آزار و پند من بنیوش .<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> ظاهر. آشکارا. بِجهر. بلند <span class=\"hlight\">:</span> <br />باز ز گنجینه گره کرد باز<br />گه سخن آزرم شد و گاه راز.<br /> <font color=\"Red\">امیرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> فضیلت . تقوی . دین داری <span class=\"hlight\">:</span> <br />سپردی مرا دختر اردوان <br />که تا بازخواهی تنی بی روان <br />نکشتم که فرزند بد در نهان <br />بترسیدم از کردگار جهان <br />نجستم بفرمانت آزرم خویش <br />بریدم هم اندرزمان شرم خویش <br />بدان تا کسی بد نگوید مرا<br />ز دریای تهمت نشوید مرا.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> محابا: بی آزرم ؛ بی محابا <span class=\"hlight\">:</span> <br />بدانید کاین عرض آزرم نیست <br />سخن با محابا و با شرم نیست .<br /> <font color=\"Red\">فردوسی .</font><br />چو زرد از ویسه این گفتار بشنید<br />عنان باره ٔ شبگون بپیچید<br />همی رفت و نبودش هیچ آگاه <br />که ره در پیش او راه است یا چاه <br />چنان بی سایه شد چونان بی آزرم <br />برِ چشمش جهان تاری شد از شرم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />همی زد دست را بر دل بی آزرم <br />همی راند از مژه خون دل ِ گرم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> مهر. مهربانی . محبت . شفقت . عشق <span class=\"hlight\">:</span> <br />شما را بدیده درون شرم نیست <br />ز راه خرد مهر و آزرم نیست .<br /> <font color=\"Red\">فردوسی .</font><br />که بر کارزاری ّ و مرد نژاد<br />دل ما پر آزرم و مهر است و داد.<br /> <font color=\"Red\">فردوسی .</font><br />از آن ترسم که تو روزی بگوراب <br />ببینی دختری چون درّ خوشاب <br />پس آزرم و وفای من نداری <br />دل بی مهر خویش او را سپاری .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />نه مرد بی وفا داردْش آزرم <br />نه در نامردمی دارد از او شرم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بگفت این و پس کاغد و خامه خواست <br />مر این هر دو را از پی نامه خواست <br />یهودای فرزانه را پیش خواند <font color=\"DarkGreen\"><b>[ یعقوب ]</font></b><br />به آزرم در پیش خویشش نشاند<br />بدو گفت بردار این خامه را<br />نویس ازمن خسته دل نامه را.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> نکبت : نکبه الزمان ؛ زیان رسانید او را زمان . آزرم رسانیدش زمان . نکبات زمان ؛ آزرمهای زمانه . (زمخشری ). <BR><font color=\"Blue\">◄</font> نگاهداشت و پاس خاطر <span class=\"hlight\">:</span> <br />که جز کشتن و خواری و درد و رنج <br />ز کهتر نهان کردن رای و گنج <br />ندانست و آزرم کس را نداشت <br />همی این بر آن آن بر این برگماشت .<br /> <font color=\"Red\">فردوسی .</font><br />جهان را گوهر آمد زشتکاری <br />چرا زو مهربانی چشم داری <br />بنزدش هیچکس را نیست آزرم <br />که بیقدر است و بی مهر است و بی شرم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />صواب آنچنان شد که آرم شتاب <br />که آزرم دشمن ندارد صواب .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> در بعضی فرهنگها به این کلمه معنی خشم و محافظه داده و بیت ذیل را شاهد آورده اند <span class=\"hlight\">:</span> <br />دباغت چنان دادم این چرم را<br />که برتابد آسیب آزرم را.<br /> <font color=\"Red\">نظامی .</font><br />لکن بگمان من کلمه ٔ بیت مصحّف آدَرْم لهجه و صورتی از آدْرَم است به معنی دِرفش فارسی و بیز ترکی . رجوع به آدرم شود.<br /> <BR><font color=\"Blue\">◄</font> یکدلی . یکرنگی <span class=\"hlight\">:</span> <br />بپاسخ تو او را درشتی مگوی <br />به پیوند آزرم ِ او را بجوی .<br /> <font color=\"Red\">فردوسی .</font><br />هرآنکس که با او بهم ساختند<br />ز آزرم ما دل بپرداختند<br />بداندیش و بدکام و بدگوهرند...<br /> <font color=\"Red\">فردوسی .</font><br />نه جانت را خرد نه دیده را شرم <br />نه گفتت راستی نه کارت آزرم .<br /><font color=\"Red\">(ویس و رامین ).</font><br /></font></div>'),
(1286, 'آزرمناک', '<span class=\"hlight\">آزرمناک .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (ص مرکب ) پرآزرم .<br /></font></div>'),
(1287, 'آزرمناکی', '<span class=\"hlight\">آزرمناکی .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (حامص مرکب ) پرآزرمی .<br /></font></div>'),
(1288, 'آزرمها', '<span class=\"hlight\">آزرمها.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِ) حُرُم . (دهار).<br /></font></div>'),
(1289, 'آزرمگن', '<span class=\"hlight\">آزرمگن .</span> <font color=\"DarkGreen\"><b>[ زَ گ ِ ]</font></b> (ص مرکب )باحیا. مؤدب . <BR><font color=\"Blue\">◄</font> شرمنده . خجل . شرمسار.<br /></font></div>'),
(1290, 'آزرمگنی', '<span class=\"hlight\">آزرمگنی .</span> <font color=\"DarkGreen\"><b>[ زَ گ ِ ]</font></b> (حامص مرکب ) حالت و کیفیت آزرمگِن .<br /></font></div>'),
(1291, 'آزرمگین', '<span class=\"hlight\">آزرمگین .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (ص مرکب ) آزرمگِن .<br /></font></div>'),
(1292, 'آزرمگینی', '<span class=\"hlight\">آزرمگینی .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (حامص مرکب ) آزرمگِنی .<br /></font></div>'),
(1293, 'آزرمی', '<span class=\"hlight\">آزرمی .</span><font color=\"DarkGreen\"><b>[ زَ ]</font></b> (ص نسبی ) باحیا: زنی آزرمی ؛ مخدره . عفیفه .<br /></font></div>'),
(1294, 'آزرمی', '<span class=\"hlight\">آزرمی .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) آزرمیدخت .<br /></font></div>'),
(1295, 'آزرمیدخت', '<span class=\"hlight\">آزرمیدخت .</span><font color=\"DarkGreen\"><b>[ زَ دُ ]</font></b> (اِخ ) نام شهری در حوالی قرمسین یا غزنین بناکرده ٔ آزرمیدخت بنت پرویزبن هرمزبن انوشیروان .<br /></font></div>'),
(1296, 'آزرمیدخت', '<span class=\"hlight\">آزرمیدخت .</span> <font color=\"DarkGreen\"><b>[ زَ دُ ]</font></b> (اِخ ) دختر پرویزبن هرمزبن انوشیروان ملقبه ٔ به عادله <font color=\"DarkGreen\"><b>[ مفاتیح ]</font></b> که پس از خواهر خویش پوراندخت لشکریان او را بپادشاهی برداشتند و چهار ماه ملک راند. و او را آزرم و آزرمی نیز خوانده اند. رجوع به آزرم شود.<br /></font></div>'),
(1297, 'آزرنگ', '<span class=\"hlight\">آزرنگ .</span> <font color=\"DarkGreen\"><b>[ رَ]</font></b> (اِ) بفتح رابع بر وزن بادرنگ بمعنی غم سخت و محنت صعب و رنج و هلاکت باشد، و با الف ممدوده و با زاء معجمه، آن خیار که سبز بود، کذا فی الادات . (مؤید الفضلاء). با زاء معجمه و راء مهمله بوزن بادرنگ خیار سبز بود، کذا فی المؤید. (سروری ). با زاء منقوطه ٔ موقوف و راء مفتوح بنون زده، هلاکت و محنت و غم سخت باشد.(جهانگیری ). ظ. این کلمه مصحف آذرنگ باشد با ذال، چه شواهدی که برای آذرنگ آمده بسیار است، یکی دو مثال که بعض فرهنگها برای آزرنگ با زاء می آورند عین بعض شواهد آذرنگ است . و اما معنی خیار سبز که به این کلمه داده اند بی شک اشتباهی است که ظاهراً نخست صاحب ادات الفضلاء را دست داده است . و منشاء اشتباه کلمه ٔ بادرنگ بوده که برای تعیین وزن آذرنگ در نسخه ای دیده و آن را معنی کلمه ٔ آذرنگ تصور کرده است و شاید در آن نسخه نوشته بوده است آذرنگ بر وزن بادرنگ به معنی خیار سبز، و کاتب <font color=\"DarkGreen\"><b>[ بر وزن ]</font></b> را از قلم انداخته بوده است .<br /></font></div>'),
(1298, 'آزره', '<span class=\"hlight\">آزره .</span> <font color=\"DarkGreen\"><b>[ زِ رَ ]</font></b> (ع اِ) ج ِ اِزار.<br /></font></div>'),
(1299, 'آزری', '<span class=\"hlight\">آزری .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (ص نسبی ) منسوب به آزر <span class=\"hlight\">:</span> <br />بزابُلْسِتان شد به پیغمبری <br />که نفرین کند بر بت آزری .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل بت آزری </span> ؛ سخت جمیل <span class=\"hlight\">:</span> <br />جدا گشت از او کودکی چون پری <br />بچهره بسان بت آزری .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1300, 'آزغ', '<span class=\"hlight\">آزغ .</span><font color=\"DarkGreen\"><b>[ زُ ]</font></b> (اِ) آنچه از شاخه های درخت خرما و انگور و دیگر درختان ببرند. (برهان ). آژغ . آزوغ . آژوغ . اَزغ . <BR><font color=\"Blue\">◄</font> عمل پیراستن و بریدن شاخه ها و برگها.<br /></font></div>'),
(1301, 'آزغده', '<span class=\"hlight\">آزغده .</span> <font color=\"DarkGreen\"><b>[ زُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) صاحب صحاح الفرس این صورت را ضبط کرده و بدان معنی خشم آلوده میدهد، و ظاهراً مصحف آرغده باشد.<br /></font></div>'),
(1302, 'آزغیده', '<span class=\"hlight\">آزغیده .</span> <font color=\"DarkGreen\"><b>[ زُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) صاحب صحاح الفرس این صورت را ضبط کرده و بدان معنی خشم آلوده داده است، و ظاهراً مصحف آرغده یا ارغنده است .<br /></font></div>'),
(1303, 'آزفت', '<span class=\"hlight\">آزفت .</span> <font color=\"DarkGreen\"><b>[ زُ ]</font></b> (ص، اِ) در بعض فرهنگها و ازجمله در صحاح هندوشاه آن را سنگ آبخورده معنی کرده اند. ظاهراً این کلمه مصحف آبرفت باشد.<br /></font></div>'),
(1304, 'آزفنداک', '<span class=\"hlight\">آزفنداک .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (اِ) آژفنداک . آفنداک . قوس قزح . تیراژه، نوشه، سریر، رخش، کمردون، آدینده، کمر رستم، کمان رستم، انطلیسون، طوق بهار و غیره از مترادفات آن است <span class=\"hlight\">:</span> <br />کمان آزفنداک شد ژاله تیر<br />گل غنچه پیکان زره آبگیر.<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(1305, 'آزفه', '<span class=\"hlight\">آزفه .</span> <font color=\"DarkGreen\"><b>[ زِ ف َ ]</font></b> (ع اِ) رستخیز. (مهذب الاسماء). رستاخیز. قیامت . <BR><font color=\"Blue\">◄</font> (ص ) شتابنده (صفت قیامت ).<br /></font></div>'),
(1306, 'آزم', '<span class=\"hlight\">آزم .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (ع اِ) ناب . نیش (دندان ). <BR><font color=\"Blue\">◄</font> (ص ) پرهیزکننده . محتمی . ج، اُزَّم، اُزُم .<br /></font></div>'),
(1307, 'آزما', '<span class=\"hlight\">آزما.</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (نف مرخم ) آزمای . مخفف آزماینده، و آن گاه که با اسمی مرکب شود، چنانکه در بخت آزما، جنگ آزما، دروغ آزما، رزم آزما، زورآزما، مهرآزما، هجرآزما، بمعانی مختلف آید. در جنگ آزمای، نبردآزمای و رزم آزمای و امثال آن به معنی دهنده و کننده ٔ جنگ و نبرد و رزم است <span class=\"hlight\">:</span> <br />سراپا بپوشید زآهن قبای <br />میان بست بر کین رزم آزمای .<br /> <font color=\"Red\">فردوسی .</font><br />که امروز سهراب جنگ آزمای <br />چگونه بخنگ اندر آورد پای ؟<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود تا جهن رزم آزمای <br />شود با بزرگان لشکر زجای .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت بهرام جنگ آزمای <br />بنزد بزرگان پاکیزه رای .<br /> <font color=\"Red\">فردوسی .</font><br />و در دروغ آزمای به معنی گوینده ٔ دروغ است :<br />دروغ آزمای است چرخ بلند<br />گهی شاد دارد گهی مستمند.<br /> <font color=\"Red\">فردوسی .</font><br />و در مهرآزمای و زورآزمای و مانند آن بمعنی ورزنده ٔ مهر و ورزنده ٔ زور باشد <span class=\"hlight\">:</span> <br />به تنهائی سخنهائی سرایان <br />که گویند آن سخن مهرآزمایان .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بزندان فرستادش از بارگاه <br />که زورآزمای است بازوی جاه .<br /><font color=\"Red\">سعدی .</font><br />و در هجرآزمای و نظایر آن به معنی متحمل و بَرَنده باشد:<br />زندواف زندخوان چون عاشق هجرآزمای <br />دوش بر گلبن همی تا روز ناله ٔ زار کرد.<br /><font color=\"Red\">فرخی .</font><br /></font></div>'),
(1308, 'آزمایان', '<span class=\"hlight\">آزمایان .</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (نف، ق ) در حال آزمودن .<br /></font></div>'),
(1309, 'آزمایش', '<span class=\"hlight\">آزمایش .</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ی ِ ]</font></b> (اِمص ) اسم مصدر آزمودن . بلا. بلاء. (ربنجنی ). خبرت . (دَهّار). تجربه . تجربت . آزمون . رون . اروند. بلی . (دَهّار). بلیه . (دَهّار) (دستوراللغة). بلوی . (دَهّار). محنت . امتحان . ابتلاء. آزمودن . اختبار. امتحان . سنجش . آروین . رون <span class=\"hlight\">:</span> <br />جوانان داننده ٔ با گهر<br />نگیرند بی آزمایش هنر.<br /> <font color=\"Red\">فردوسی .</font><br />کنون من تو را آزمایش کنم <br />یکی سوی رزمت گرایش کنم <br />گَرَم ازدرِ شوی یابی بگوی <br />همانا مرا خود پسندی به شوی .<br /> <font color=\"Red\">فردوسی .</font><br />برآنم که با او نسازیم جنگ ...<br />یکی پاسخ پندمندش دهیم ...<br />اگر جنگ جوید پس از پند من <br />نیندیشد از فرّ و اروند من <br />بدانسان شوم پیش او با سپاه <br />که بخشایش آرد بر او هور و ماه <br />از این آزمایش ندارد زیان <br />بماند مگر دوستی در میان .<br /> <font color=\"Red\">فردوسی .</font><br />چو بی آزمایش نباشد خرد<br />سرِ مایه ٔ کارها بنگرد.<br /><font color=\"Red\">فردوسی .</font><br />چو دیدمْت گفتم سراسر سخُن <br />مرا هر زمان آزمایش مکن .<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ که دانای پیر<br />که با آزمایش بود یادگیر...<br /> <font color=\"Red\">فردوسی .</font><br />بدانش ورا آزمایش کنید<br />هنر بر هنر بر فزایش کنید.<br /> <font color=\"Red\">فردوسی .</font><br />به از آزمایش ندیدم گوا<br />گوای سخنگوی و فرمانروا.<br /> <font color=\"Red\">فردوسی .</font><br />جز او هرکه با ما بدل دشمنند<br />ز تخم جفاپیشه اهریمنند<br />ز ما نیکوئیها نگیرند یاد<br />ترا آزمایش بس از نوش زاد.<br /> <font color=\"Red\">فردوسی .</font><br />دگر آنکه گفتی که چل ساله مرد<br />ز برنا فزون تر نجوید نبرد<br />چهل ساله با آزمایش بود<br />بمردانگی در فزایش بود.<br /> <font color=\"Red\">فردوسی .</font><br />جوان ارچه دانا بود با گهر<br />ابی آزمایش نگیرد هنر.<br /> <font color=\"Red\">فردوسی .</font><br />بدر بر همی بود با هر کسی <br />همی کرد از آن آزمایش بسی .<br /> <font color=\"Red\">فردوسی .</font><br />گرت رای با آزمایش بود<br />همه روزت اندر فزایش بود.<br /> <font color=\"Red\">فردوسی .</font><br />واکنون اینجا شحنه می گماریم با اندک مایه مرد، آزمایش را. (تاریخ بیهقی ).<br />جوان گرچه دانادل و پرفسون <br />بود نزد پیر آزمایش فزون .<br /> <font color=\"Red\">اسدی .</font><br />زیرا که جهان ز آزمایش <br />بس نادره ناطقیست ابکم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />سلطان چون از حجره ٔ خاص بیرون آمدی نخست روی او دیدی و مقصود سلطان آزمایش خجستگی دیدار او بود. (نوروزنامه ). و هر یک را بانواع آزمایش امتحان می کرد. (کلیله و دمنه ).<br />آزمایش کرد آن شاهش مگر<br />تا شناسد هیچ باز از یکدگر.<br /> <font color=\"Red\">عطار.</font><br />غوره ها را که بیارائید غول <br />پخته پندارد کسی که هست گول <br />آزمایش چون نماید جان او<br />کند گردد زآزمون دندان او.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> ورزش . ریاضت . مشق . کثرت عمل . کارکشتگی <span class=\"hlight\">:</span> <br />چنین داد پاسخ بمادر که شیر<br />نگردد مگر به آزمایش دلیر.<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به آزموده شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آزمایش کردن </span> ؛ امتحان . اختبار. ابتلاء.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">چهل ساله با آزمایش بود</span> .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1310, 'آزمایشگاه', '<span class=\"hlight\">آزمایشگاه .</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ی ِ ]</font></b> (اِ مرکب ) جای آزمایش . مورد آزمایش . محل امتحان .<br /></font></div>'),
(1311, 'آزمایشگر', '<span class=\"hlight\">آزمایشگر.</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ی ِ گ َ ]</font></b> (ص مرکب ) ممتحِن . آزماینده . مجرِّب <span class=\"hlight\">:</span> <br />بدان خانه ٔ باستانی شدم <br />بهنجار چون آزمایشگری .<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(1312, 'آزماینده', '<span class=\"hlight\">آزماینده .</span> <font color=\"DarkGreen\"><b>[ زْ<span class=\"hlight\" dir=\"rtl\">/</span> زِ ی َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) مجرِّب . ممتحِن . آزمایشگر.<br /></font></div>'),
(1313, 'آزمند', '<span class=\"hlight\">آزمند.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ص مرکب ) حریص . مولع. شَرِه ْ. طامع. آزور.صاحب آز. آزناک . طمعکار. پرخواه . ولوع <span class=\"hlight\">:</span> <br />حاسد و بدخواه او دائم به مرگ است آزمند<br />گر در این حسرت بمیرد باک نبود، گو بمیر.<br /> <font color=\"Red\">سوزنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">آزمند هماره نیازمند است </span> .<br /></font></div>'),
(1314, 'آزمندی', '<span class=\"hlight\">آزمندی .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (حامص مرکب ) حرص . ولع. طمع. شره . پرخواهی <span class=\"hlight\">:</span> <br />ایا دانشی مرد بسیارهوش <br />همه چادر آزمندی مپوش .<br /> <font color=\"Red\">فردوسی .</font><br />دگر آزمندیست اندوه و رنج <br />شدن تنگدل در سرای سپنج .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1315, 'آزمه', '<span class=\"hlight\">آزمه .</span> <font color=\"DarkGreen\"><b>[ زِ م َ ]</font></b> (ع اِ) آزِم . ناب . نیش (دندان ). ج، اَوازم .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1316, 'آزمودن', '<span class=\"hlight\">آزمودن .</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ دَ ]</font></b> (مص ) تجربت . تجربه . امتحان . اختبار. (زوزنی ). ابتلا. تجریب . (دهار). آزمایش کردن . تدریب . بلاء. (ادیب نطنزی ). بلا. بلو. ابلا. تجریس .بور. ابتیار. احتناک . سنجیدن . خبرت . (دهار). سبر. فتنه . افتتان . وارسی کردن . تمحیص . تضریس <span class=\"hlight\">:</span> <br />کرا آزمودیش و یار تو گشت <br />منال ار گناهی بر او برگذشت .<br /> <font color=\"Red\">ابوشکور.</font><br />تیزهش تا نیازماید بخت <br />بچنین جایگاه نگْراید.<br /> <font color=\"Red\">رودکی یا دقیقی .</font><br />میان من و او بسی رزم بود<br />مگر کِم بخواهد دگر آزمود.<br /> <font color=\"Red\">فردوسی .</font><br />چو مهر کسی را بخواهی بسود<br />بباید بسود و زیان آزمود.<br /> <font color=\"Red\">فردوسی .</font><br />ز لشکر هر آنکس که بد زورمند<br />بسودند سنگ آزمودند چند.<br /> <font color=\"Red\">فردوسی .</font><br />نشاندش به آنجا که آرام بود<br />همی خواست مر زال را آزمود.<br /> <font color=\"Red\">فردوسی .</font><br />چنین هفت سالش همی آزمود<br />بهر کار جز پاک زاده نبود.<br /> <font color=\"Red\">فردوسی .</font><br />مرا آزمودی که در کارزار<br />چنانم که با باده ٔ میگسار<br />سپه را بدین گفتها آزمود<br />که در دل ز لشکر ورا بیم بود.<br /> <font color=\"Red\">فردوسی .</font><br />تیغ بر پیل آزمایدتیر بر شیر ژیان <br />اینْت مردانه سواری اینْت مرد سهمگین .<br /> <font color=\"Red\">فرخی .</font><br />همی دانم که رنج خود فزایم <br />که چندین آزموده آزمایم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />چرا من آزموده آزمایم <br />چرا بیهوده رنج خود فزایم ؟<br /> <font color=\"Red\">(ویس و رامین ).</font><br />چه آشفته دل و چه خیره رایم <br />که چندین آزموده آزمایم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />تباهی روزگار خود فزایم <br />چو چیز آزموده آزمایم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />روان را رنج بیهوده نمائی <br />که چندین آزموده آزمائی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />نه من آشفته روی و سست رایم <br />که چندین آزموده آزمایم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بجز دوزخ نباشد هیچ جایم <br />اگر نیز آزموده آزمایم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />ایشان را نزد نصر احمد آوردند و نصر یک هفته ایشان را می آزمود. (تاریخ بیهقی ). ایشان را میباید آزمود تا تنی چند از ایشان بخردتر اختیار کرده آید. (تاریخ بیهقی ). و ما چون کارها را نیکوتر بازنهشتیم و پیش و پس آن را بنگریستیم و این مرد را دانسته بودیم و آزموده، صواب آن نمود که ... (تاریخ بیهقی ).<br />همانست او گرش صد آزمائی <br />که ناید هرگز از گرگ آشنائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />جهان را دیدم و خلق آزمودم <br />بهر میدان درون جستم مجالی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />جهان را دیده ای و آزمودی <br />شنیدی گفته ٔ تازی و دهقان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از آن پس که این سفله را آزمودم <br />بچاهش درون نوفتم گر بصیرم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گفتم وفا نداری گفتا که آزمودی <br />من جرب المجرب حلت بِه ِ الندامه .<br /> <font color=\"Red\">سنائی .</font><br />شیر... اخلاق و عادات او <font color=\"DarkGreen\"><b>[گاو]</font></b> را بیشتر آزمود. (کلیله و دمنه ). ایشان را بارها بیازموده است <font color=\"DarkGreen\"><b>[شیر ]</font></b> . (کلیله و دمنه ). بارها آن را <font color=\"DarkGreen\"><b>[ روشنائی را ]</font></b> بیازمود <font color=\"DarkGreen\"><b>[ بط ]</font></b> حاصل ندید. (کلیله و دمنه ). در تقدیم ... چنین کسان سعی پیوستن همچنان باشد که کسی شمشیر بر سنگ آزماید. (کلیله و دمنه ). شتربه ... گفته که شیر را آزمودم . (کلیله و دمنه ).<br />وصل هم نازموده ای که بلطف <br />خون بریزد که موی نازارد.<br /> <font color=\"Red\">انوری .</font><br />آزمودم مرگ من در زندگیست <br />چون رهم زین زندگی پایندگیست .<br /> <font color=\"Red\">مولوی .</font><br />اتفاقاً غلامی که دیگر دریا ندیده بود و محنت کشتی نیازموده ... (گلستان ). مردیت بیازمای وآنگه زن کن . (گلستان ).<br />من آزموده ام این رنج و دیده این سختی <br />ز ریسمان متنفر بود گزیده ٔ مار.<br /> <font color=\"Red\">سعدی .</font><br />یاری که بجان نیازمائی <br />در کار خودش مده روائی <br />صد یار بود به نان شکی نیست <br />چون کار بود بجان یکی نیست .<br /> <font color=\"Red\">امیرخسرو.</font><br />کسی کو آزمود آنگاه پیوست <br />نباید بعد از آن خائیدنش دست <br />چو پیوندی ّ و آنگه آزمائی <br />ز حسرت دست خود بسیار خائی .<br /> <font color=\"Red\">اوحدی (از ده نامه ).</font><br />هرچند آزمودم از وی نبود سودم <br />من جرب المجرب حلت بِه ِ الندامه .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> تحمل کردن . کشیدن . بردن . مقاسات <span class=\"hlight\">:</span> <br />به نخجیر برگرد با رای و رود<br />بدان تا نباید بدی آزمود.<br /> <font color=\"Red\">فردوسی .</font><br />چرا دل نهم بر دل جنگجوئی <br />که دل زو همه رنج و درد آزماید؟<br /> <font color=\"Red\">فرخی .</font><br />اگر رنج مرا کوه آزماید<br />بجای آب از او جز خون نیاید.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />نیارم بیش از این بر جای بودن <br />نهیب برف و سرما آزمودن .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />ز کشتن تا به رستن تا درودن <br />بسا رنجا که باید آزمودن .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />نه چون شاهان دیگر جام جوی است <br />که از رنج آزمودن نام جوی است .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />مردم خطر عافیت چه داند<br />تا بند بلا را نیازماید؟<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> کردن جنگ . دادن نبرد و رزم <span class=\"hlight\">:</span> <br />که گوید ز ایران سواری نبود<br />که یارست با شیده رزم آزمود؟<br /> <font color=\"Red\">فردوسی .</font><br />که گفتت که با شاه جنگ آزمای <br />ندیدی مرا پیش او بر بپای ؟<br /> <font color=\"Red\">فردوسی .</font><br />همی کرد نخجیر و یادش نبود<br />از آنکس که بااو نبرد آزمود.<br /> <font color=\"Red\">فردوسی .</font><br />که رزم آزماید بتوران زمین <br />بخواهد بمردی از ارجاسب کین .<br /> <font color=\"Red\">فردوسی .</font><br />بسی رنج بیند گرانمایه مرد<br />سواری کند آزموده نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />چو پیدا شود دشمنی کینه جوی <br />نهان هر زمان پرس از کار اوی <br />چو با او نشاید نبرد آزمود<br />بچیز فراوانْش بفْریب زود.<br /> <font color=\"Red\">اسدی .</font><br />نه با چرخ شاید نبرد آزمود<br />نه چون بخت بد شد بود چاره سود.<br /> <font color=\"Red\">اسدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دروغ آزمائی </span> ؛ دروغگوئی <span class=\"hlight\">:</span> <br />دروغ آزمائی نباشد ز رای <br />که از رای باشد بزرگی بجای .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دروغ آزمای </span> ؛ دروغگوی <span class=\"hlight\">:</span> <br />دروغ آزمائیست چرخ بلند<br />گهی شاد دارد گهی مستمند.<br /> <font color=\"Red\">فردوسی .</font><br />زبانی که باشد بریده ز جای <br />از آن به که باشد دروغ آزمای .<br /> <font color=\"Red\">اسدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دروغ آزمودن </span> ؛ دروغ گفتن <span class=\"hlight\">:</span> <br />دروغ آزمودن ز بیچارگیست <br />نگوید کرا در هنر بارگیست .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> ورزیدن : زور آزمودن ؛ کشتی گرفتن <span class=\"hlight\">:</span> بدان روزگار جوانی ... ریاضتها کردی چون زور آزمودن . (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> بکار بردن <span class=\"hlight\">:</span> <br />به تیغ و به تیر و بگرز و کمند<br />ز هر گونه ای آزمودیم چند.<br /> <font color=\"Red\">فردوسی .</font><br />چنان چون فریدون مرا داده بود<br />ترا دادم این تاج شاه آزمود.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> ورزانیدن . مشق دادن . ریاضت دادن <span class=\"hlight\">:</span> <br />نه روبه شود زآزمودن دلیر<br />نه گوران بساوند چنگال شیر.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">به آزموده رو نه طبیب </span> .<br /> <span class=\"hlight\">چهارپا را چهار روز آزمایند و دوپا را دو روز</span>؛ آدمی را زود توان شناخت .<br /> <span class=\"hlight\">مشک را با سیر آزمایند</span> .<br />و اسم مصدر و مصدر دویم آن آزمایش است . آزمودم . آزمای . <br /></font></div>'),
(1317, 'آزمودنی', '<span class=\"hlight\">آزمودنی .</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ دَ ]</font></b> (ص لیاقت ) ازدرِ آزمودن . درخور آزمودن . محتاج آزمودن .<br /></font></div>'),
(1318, 'آزموده', '<span class=\"hlight\">آزموده .</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) مجرب . ممتحَن . سنجیده . مُدَرَّب . مُنجَد. منجَذ. حُنک . موقر. (صُراح ). کاردیده . کرده کار. پخته . سُخته . ورزیده . دنیادیده <span class=\"hlight\">:</span> <br />ابا ششهزار آزموده سوار<br />همی دارد آن بستگان را بزار.<br /> <font color=\"Red\">فردوسی .</font><br />دو ره ششهزار آزموده سوار<br />زره دار با گرزه ٔ گاوسار.<br /> <font color=\"Red\">فردوسی .</font><br />ز قلب سپاه اندر آمد چو کوه <br />ابا ده هزار آزموده گروه .<br /> <font color=\"Red\">فردوسی .</font><br />برد ده هزار آزموده سوار<br />همه نیزه دار ازدرِ کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />بر مردم ناآزموده ایمن مباش و آزموده از دست مده که روزگار دراز باید تا باز کسی آزموده و معتمد به دست آید که اندر مثل آمده است که ددِ آزموده به از مردم ناآزموده . (از قابوسنامه ). <BR><font color=\"Blue\">◄</font> ریاضت دیده . ورزیده . کارکشته <span class=\"hlight\">:</span> <br />وگر آزموده نباشد ستور<br />نشاید به تندی بر او کرد زور.<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به آزمایش شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کارآزموده </span> ؛ نیک مُجرّب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گرم و سرد نیازموده بودن </span> ؛ بسیار ناپخته و بی تجربه بودن <span class=\"hlight\">:</span> <br />همی گفت کاوس خود کامه مرد<br />نه گرم آزموده ز گیتی نه سرد.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت گودرز کای شیرمرد<br />نه گرم آزموده ز گیتی نه سرد.<br /> <font color=\"Red\">فردوسی .</font><br />خردمند باشد جهاندیده مرد<br />که بسیار گرم آزموده است و سرد.<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />جهاندیده ای، آرامیده ای، گرم و سرد چشیده ای، نیک و بد آزموده ای . (گلستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نیک و بد (گرم و سرد) آزموده بودن </span> ؛ سخت مُجرب بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آزموده را آزمودن پشیمانی آرد</span> . (قرة العیون ).<br /> <span class=\"hlight\">آزموده را آزمودن جهل است </span> .<br /> <span class=\"hlight\">بناآزموده کار مفرمای و به آزموده استادی مکن </span> .<br /><span class=\"hlight\">ددِ آزموده به از مردم ناآزموده </span> . (قابوسنامه ).<br /></font></div>'),
(1319, 'آزموده کار', '<span class=\"hlight\">آزموده کار.</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب ) در تداول عوام، آزموده . مُجرّب .<br /></font></div>'),
(1320, 'آزمودگی', '<span class=\"hlight\">آزمودگی .</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) چگونگی و صفت آزموده . مجرب و ممتحن بودگی . کارکشتگی .<br /></font></div>'),
(1321, 'آزمون', '<span class=\"hlight\">آزمون .</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِمص، اِ) اسم مصدر از آزمودن . بلا. امتحان . تجربه . تجربت . آزمایش . رَوَن . آروین . سنجش . اروند <span class=\"hlight\">:</span> <br />کنون آزمون را یکی کارزار<br />بسازیم تا چون بود روزگار.<br /> <font color=\"Red\">فردوسی .</font><br />یکی دست بگرفت و بفشاردش <br />همی آزمون را بیازاردش .<br /> <font color=\"Red\">فردوسی .</font><br />اگر آزمون را کسی خورْد زهر<br />از آن خوردنش درد و مرگ است بهر.<br /> <font color=\"Red\">فردوسی .</font><br />که بر من یکی آزمون را بجنگ <br />بگردد بسان دلاور نهنگ .<br /> <font color=\"Red\">فردوسی .</font><br />دگر آنکه از آزمون خرد<br />بکوشد بمردی ّ و گرد آورد.<br /> <font color=\"Red\">فردوسی .</font><br />بپذرفت هر مهتری باژ و ساو<br />نکرد آزمون گاو با شیر تاو.<br /> <font color=\"Red\">فردوسی .</font><br />یکی تیغ دارم من الماس گون <br />بزخم نوی خواهمش آزمون .<br /> <font color=\"Red\">اسدی .</font><br />بجنگ آنکه سست آید از آزمون <br />ورا نام بفکن ز دیوان برون .<br /> <font color=\"Red\">اسدی .</font><br />همه دوستان را بمهر اندرون <br />گه خشم و سختی کنند آزمون .<br /> <font color=\"Red\">اسدی .</font><br />سزا آن بدی کز نخستین کنون <br />مرا کردی اندر هنرآزمون .<br /> <font color=\"Red\">اسدی .</font><br />مرا لشکری کآزمون کرده ام <br />همین بس که از زابل آورده ام .<br /> <font color=\"Red\">اسدی .</font><br />خواهی که کینْش جوئی ازبهر آزمون <br />پیشانی پلنگ و کف اژدها بخار.<br /> <font color=\"Red\">قطران .</font><br />از کمین بیرون جهد چون باد روز معرکه <br />گر کسی گوید زبهر آزمون آن را که هان .<br /> <font color=\"Red\">ازرقی .</font><br />آزادگی و طمع بهم ناید<br />من کرده ام آزمون بصد مرّه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />جهانا زآزمون سنجاب و از کردار پولادی <br />بزیر نوش در نیشی بروی زهر در قندی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ور بکاری آزمون را تخم آز<br />گر بروید برنیارد جز محال .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کسی راکآزمودی چند بارش <br />مکن زنهار دیگر آزمونش .<br /> <font color=\"Red\">عطار.</font><br />آزمایش چون نماید جان او<br />کندگردد زآزمون دندان او.<br /> <font color=\"Red\">مولوی .</font><br />جان نباشد جز خبر در آزمون <br />هر کرا افزون خبر جانش فزون .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> حاصل تجربه . عبرت که از تجربه حاصل آید <span class=\"hlight\">:</span> <br />بهمْدان گشسب آن زمان گفت باز<br />که ای گشته اندر نشیب و فراز<br />بگوی آنچه دانی بکار اندرون <br />به نیک و بد روزگار آزمون .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">آزمون رایگان </span> ؛ این همانست که امروز گویند امتحان مال و خرجی ندارد <span class=\"hlight\">:</span> با پدر رای زد وگفت ای پدر شهر بردسیر خالیست ... اگر سحرگاهی چند سوار در پس دیوارها نزدیک دروازه ٔ شهر کمین سازند و چون در بگشایند خود را در شهر اندازند همانا اهل شهر را دست مدافعت و طاقت ممانعت نباشد... اتابک گفت چنین گفته اند، آزمون رایگان ... (تاریخ سلاجقه ).<br /><span class=\"hlight\">هر چیز بخود نیازمند است و خرد به آزمون </span> . (منسوب به اردشیر بابکان ).<br /></font></div>'),
(1322, 'آزناک', '<span class=\"hlight\">آزناک .</span> (ص مرکب ) شَرِه ْ. حریص . آزمند.<br /></font></div>'),
(1323, 'آزندن', '<span class=\"hlight\">آزندن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ ]</font></b> (مص ) آزَنْدیدن . آزَنیدن . دوختن بسوزن . کوفتن (؟) <span class=\"hlight\">:</span> <br />عصیب و گرده برون کن تو زود و بر هم کوب <br />جگر بیازن و آکنج را بسامان کن .<br /><font color=\"Red\">کسائی .</font><br /></font></div>'),
(1324, 'آزود', '<span class=\"hlight\">آزود.</span>(ص ) عاقل . زیرک . (فرهنگ نعمةاﷲ). تیزنظر. تیزفهم .<br /></font></div>'),
(1325, 'آزور', '<span class=\"hlight\">آزور.</span> (ص مرکب ) آزوَر <span class=\"hlight\">:</span> <br />جرعه ٔ جام خود اگر بخورم <br />نکند درد منتم رنجور<br />فرد باش ای حمیت قانع<br />خاک خور ای طبیعت آزور.<br /><font color=\"Red\">انوری .</font><br />دهان تیر چنان باز مانده از پی چیست <br />اگر نشد بجگرگوشه ٔ عدوت آزور؟<br /><font color=\"Red\">کمال اسماعیل .</font><br /></font></div>'),
(1326, 'آزور', '<span class=\"hlight\">آزور.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ص مرکب ) حریص . (دهّار). آزمند. ورنج . صاحب آز. طامع. طمّاع . هلوع . ولوع . مولع <span class=\"hlight\">:</span> <br />چو داننده مردم شود آزور<br />همی دانش او نیاید ببر.<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ که فرشیدورد<br />یکی آزور مرد بیخواب و خورد.<br /><font color=\"Red\">فردوسی .</font><br />مگر گوسفندش بود صدهزار<br />همان اشتر و اسب و خر زین شمار<br />زمین پر ز آکنده دینار اوست <br />که نه مغز بادش بتن در نه پوست <br />شکم گرْسنه کالبد برْهنه <br />نه فرزند و خویش و نه بار و بنه <br />گرفتار در دست آز و نیاز<br />تن از ناچریدن به رنج و گداز.<br /> <font color=\"Red\">فردوسی .</font><br />دل آزور مرد باشد بدرد<br />بگرد طمع تا توانی مگرد.<br /> <font color=\"Red\">فردوسی .</font><br />توانگر شود هرکه خشنود گشت <br />دل آزور خانه ٔ دود گشت .<br /> <font color=\"Red\">فردوسی .</font><br />بچیزی فریبد دل آزور<br />که باشد نیازش بدان بیشتر.<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(1327, 'آزوری', '<span class=\"hlight\">آزوری .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (حامص مرکب ) (از پهلوی آزوریه، خواهش . هوی ̍) طمع. حرص . ولع. شهوت . هوی ̍. خواهش .<br /></font></div>'),
(1328, 'آزوغ', '<span class=\"hlight\">آزوغ .</span> (اِ) آزغ . آژغ . آژوغ .<br /></font></div>'),
(1329, 'آزپرور', '<span class=\"hlight\">آزپرور.</span> <font color=\"DarkGreen\"><b>[ پ َ وَ ]</font></b> (نف مرکب ) آزآور.<br /></font></div>'),
(1330, 'آزپیشه', '<span class=\"hlight\">آزپیشه .</span> <font color=\"DarkGreen\"><b>[ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) حریص :<br />برفتند <font color=\"DarkGreen\"><b>[ گرگین و بیژن ]</font></b> هر دو براه دراز<br />یکی آزپیشه <font color=\"DarkGreen\"><b>[ گرگین ]</font></b>یکی کینه ساز.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1331, 'آزگار', '<span class=\"hlight\">آزگار.</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (ص ) تمام . کامل . تخت . شمرده . اَجْرَد. آزاد. جَرْداء: شش ماه ِ آزگار. یک سال آزگار.<br /></font></div>'),
(1332, 'آزی دهاک', '<span class=\"hlight\">آزی دهاک .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) رجوع به آژی ده آک و ضحاک و آک و بیوراسب شود.<br /></font></div>'),
(1333, 'آزیدن', '<span class=\"hlight\">آزیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آژدن . آژیدن . آجدن . آجیدن . <BR><font color=\"Blue\">◄</font> رنگ کردن . و بدین معنی شاید مصحف رزیدن باشد. <BR><font color=\"Blue\">◄</font> آزار دادن . آزردن . (برهان ).<br /></font></div>'),
(1334, 'آزیر', '<span class=\"hlight\">آزیر.</span> (اِمص، اِ) مماله ٔ آزار <span class=\"hlight\">:</span> <br />در جهان چندانکه خواهی بیشمار<br />نیستی ّ و محنت و آزیر هست <br />وز فلک چندانکه خواهی بی قیاس <br />نفرت آهو و خشم شیر هست .<br /> <font color=\"Red\">انوری .</font><br /><BR><font color=\"Blue\">◄</font> (ص ) آژیر. <BR><font color=\"Blue\">◄</font> (اِ) حوض . برکه . تالاب . اسطخر. <BR><font color=\"Blue\">◄</font> غلبه . زیادتی . <BR><font color=\"Blue\">◄</font> بانگ و فریاد. (برهان ).<br /></font></div>'),
(1335, 'آزیغ', '<span class=\"hlight\">آزیغ.</span> (اِ) تنفر و نفرتی که از اقوال و افعال کسی در ظاهر و باطن بهم رسد. (برهان ). کراهت . آریغ را هم به این معنی آورده اند، و البته آریغ با راء مهمله صحیح است (فارسی باستانی : اَریکا).<br /></font></div>'),
(1336, 'آزین', '<span class=\"hlight\">آزین .</span> (اِخ ) آذین . پسر هرمزان، نام یکی از امراءایران که پس از فتح مداین به دست سعد وقاص سپاهی گرد کرد و با عرب رزم داد و در سال <span class=\"hlight\" dir=\"rtl\">١٦</span> هجری کشته شد.<br /></font></div>'),
(1337, 'آزینه', '<span class=\"hlight\">آزینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) رجوع به آژینه شود.<br /></font></div>'),
(1338, 'آس', '<span class=\"hlight\">آس .</span> (فرانسوی، اِ) قسمی بازی و قمار با اوراقی مخصوص که شکل خال و شاه و بی بی و سرباز و لکات بر آن است . <BR><font color=\"Blue\">◄</font> تک خال . ورق قمار که یک خال بر آن باشد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چهار شاهش به چهار آس خوردن </span> ؛ به قویتر از خودی مصادف شدن . به حیله و چاره ای رساتر از چاره ٔ خوددچار گشتن .<br /></font></div>'),
(1339, 'آس', '<span class=\"hlight\">آس .</span> (هندی، اِ) بزبان هندوستانی، تیرانداز ماهر. (فرهنگ شعوری ) <span class=\"hlight\">:</span> <br />تیغ رای تو خود سپر نکند<br />گرچه چرخ فلک شود پرآس .<br /><font color=\"Red\">مسعودسعد.</font><br /><BR><font color=\"Blue\">◄</font> کمان تیراندازان . <BR><font color=\"Blue\">◄</font> امید.<br /></font></div>'),
(1340, 'آس', '<span class=\"hlight\">آس .</span> (اِ) دو سنگ گرد و پخ برهم نهاده و زیرین را در میان میلی آهنین و جز آن از سوراخ میان زبرین درگذشته و سنگ زبرین بقوت دست آدمی یا ستور یا باد یا آب و بخار و برق گردد و حبوب و جز آن را خرد یا آرد سازد. آنچه را به دست گردد، دست آس و آسدست، و آنچه را با آب گردد آب آس یا آسیاب یا آسیا و عرب طاحونه و ناعور و آنچه را بباد گردد بادآس و آسیاچرخ و آس باد و رحی الریح نامند، و آس بستور گردنده و نیز آس بزرگ را خرآس و ستورآس گویند و آس با شتر گردنده را عرب طحانه و طحون گوید.(السامی فی الاسامی ). و آس که بگاو گردد آن را گاوآس و دولاب و عرب منجنین و منجنون و عربه و دالیه گوید. رحی . طاحونه . رحا. طاحون . طحانه . مطحنه <span class=\"hlight\">:</span> <br />در تو ای گنبد امید و هراس <br />گردش آس هست و گونه ٔ آس <br />سبز و خرم چو آسی اندر چشم <br />باز بر فرق تیزگرد چو آس .<br /> <font color=\"Red\">مسعودسعد.</font><br />عمرت از آس آسمان سوده <br />تو دمی زو بجان نیاسوده .<br /> <font color=\"Red\">سنائی .</font><br />دامن بخت تو پاک از گرد آس آسمان <br />وز جفای آسمان خصم تو سرگردان چو آس .<br /> <font color=\"Red\">انوری .</font><br />قدر سرمه بزرگتر باشد<br />هرچه اش آس خردتر ساید.<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> اشتر که موی او ریخته بود. اَنْبُره .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آس شدن </span> ؛آس گردیدن . آس گشتن . آرد شدن . نرم، خُرد، آسیائی شدن . مطحون، طحین، مُطحن گردیدن <span class=\"hlight\">:</span> <br />آس شدم زیر آسیای زمانه <br />نیسته خواهم شدن همی بکرانه .<br /> <font color=\"Red\">کسائی .</font><br />دوستا جای بین ومرد شناس <br />شد نخواهم به آسیای تو آس .<br /> <font color=\"Red\">لبیبی .</font><br />تا دل من آس شد در آسیای عشق او<br />هست پنداری غبار آسیا <font color=\"DarkGreen\"><b>[ بر ]</font></b> سر مرا.<br /> <font color=\"Red\">لبیبی (از فرهنگ اسدی ).</font><br />رفیقا جام می بر یاد من خور<br />که زیر آسیای غم شدم آس .<br /> <font color=\"Red\">سنائی .</font><br />چو دانه دیدی اندر خوشه رُسته <br />ببین هم گشته زیر آسیا آس .<br /> <font color=\"Red\">سنائی .</font><br />من بپای خود این خطا کردم <br />تا بدستاس رنج گشتم آس .<br /> <font color=\"Red\">مختاری .</font><br />موافقان را بأست نمالد و نه عجب <br />در آسیای فلک سنبله نگردد آس .<br /> <font color=\"Red\">حسن غزنوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آس کردن </span> ؛ آرد کردن . نرم وخرد کردن . آسیا کردن . آرد کردن <span class=\"hlight\">:</span> <br />آسمان آسیای گردانست <br />آسمان، آسمان کند هزمان .<br /> <font color=\"Red\">کسائی .</font><br />همی نثار کند ابر شامگاهی دُر<br />همی عبیر کند باد بامدادی آس .<br /> <font color=\"Red\">منوچهری .</font><br />دندانهای پیشین را سر تیز است تا طعام ببُرَد و دیگران را سر پهن است تا طعام آس کند. (کیمیای سعادت ). گفت نه، آس کن تا آرد شود، آس کرد تا آرد شد. (تفسیر ابوالفتوح ).<br />عشق اگر استخوانت آس کند<br />سنگ زیرین آسیا بودن .<br /><font color=\"Red\">انوری .</font><br /></font></div>'),
(1341, 'آس', '<span class=\"hlight\">آس .</span> (ع اِ) حیوانی که پوست و موئی نرم دارد و از آن پوستین کنند و نوک دم آن سیاه است . قاقم . <BR><font color=\"Blue\">◄</font> فنک . فنه . فرسان . (زمخشری ).<br /></font></div>'),
(1342, 'آس', '<span class=\"hlight\">آس .</span> (ع اِ) (از سریانی آسا) مورْد. رَند. اِسمار. مُرد. مرت . عمار. فیطس . مرسین . و آن درختی است بلندتر از انار، برگش ریزه تر از برگ انار و مایل به استداره، تخمش سیاه و خزان نمیکند و گل و برگ آن معطر است <span class=\"hlight\">:</span> <br />تا برآید لخت لخت از کوه میغ ماغ گون <br />آسمان آس رنگ از رنگ او گردد خلنگ .<br /> <font color=\"Red\">منوچهری .</font><br />در تو ای گنبد امید و هراس <br />گردش آس هست و گونه ٔ آس <br />سبز و خرم چو آسی اندر چشم <br />باز بر فرق تیزگرد چو آس .<br /> <font color=\"Red\">مسعودسعد.</font><br />ماه دوهفته ندارد قدو چشم و رخ و زلف <br />عرعر و نرگس سیرآب گل سوری و آس .<br /> <font color=\"Red\">سوزنی .</font><br />و میوه ٔ آن را حب ّالاَّس و فطس و تخم مورد گویند. <BR><font color=\"Blue\">◄</font> قبر. <BR><font color=\"Blue\">◄</font> صاحب . یار. <BR><font color=\"Blue\">◄</font> بقیه ٔ عسل آمیخته بموم در زنبورخانه . <BR><font color=\"Blue\">◄</font> خاکستری که از آتش برجای مانده باشد در دیگدان . باقی خاکستر در میان دیگ پایه . (ربنجنی ). <BR><font color=\"Blue\">◄</font> نشانه ها و علائم عمارت و آبادی . هر نشانی خفی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آس برّی </span> ؛ مورْد اسپرم . مُرد اسفرم . خیزران بلدی . قف و انظر. مورْد رومی . مورْد صحرائی .<br /></font></div>'),
(1343, 'آس', '<span class=\"hlight\">آس .</span> (اِخ ) نام قومی از ایرانیان، ساکن قفقاز مرکزی . زبان این مردم لهجه ای از فارسی است و ایشان را ایرُن و اِس و اُسِت نیز نامند. و آنان مردمی قوی با مویهای خرمائی و چشمهای آسمانگونه باشند و در قدیم پادشاهی و مملکتی به همین نام داشته اند. عده ٔ کنونی آنان نزدیک <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> هزار تن است . و نسبت بدان آسی و جمع آن آسیان است . و رجوع به آسیان و آزاد و آزاده شود. <BR><font color=\"Blue\">◄</font> نام قریه ای از فارس . <BR><font color=\"Blue\">◄</font> نام شهری در دشت قپچاق . <BR><font color=\"Blue\">◄</font> نام مرکز بلوک دیکله ٔ قراجه داغ آذربایجان .<br /></font></div>'),
(1344, 'آس', '<span class=\"hlight\">آس .</span> <font color=\"DarkGreen\"><b>[ سِن ْ ]</font></b> (ع ص ) آسی . اندوهگین .<br /></font></div>'),
(1345, 'آس آب', '<span class=\"hlight\">آس آب .</span> (اِ مرکب ) آب آسیا. آسیای آبی .<br /></font></div>'),
(1346, 'آس افزون', '<span class=\"hlight\">آس افزون .</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِ مرکب ) آس اَفژون . آژینه . آسیازنه . آسیاآژن . سنبه . منقار. مِکْوَس . میقعه . برطیل . نقار. چکوچ . کبیتک .<br /></font></div>'),
(1347, 'آس باد', '<span class=\"hlight\">آس باد.</span> (اِ مرکب ) آسیا که بقوت باد گردد. بادآس . رحی الرّیح . (ربنجنی ). آسیاچرخ .<br /></font></div>'),
(1348, 'آس باز', '<span class=\"hlight\">آس باز.</span> (نف مرکب ) آنکه آس بازد بقمار.<br /></font></div>'),
(1349, 'آس بازی', '<span class=\"hlight\">آس بازی .</span> (حامص مرکب ) قمار با آس .<br /></font></div>'),
(1350, 'آس بری', '<span class=\"hlight\">آس بری .</span> <font color=\"DarkGreen\"><b>[ س ِ ب َرْ ری ]</font></b> (ترکیب وصفی، اِ مرکب ) مورْد برّی . مقابل آس بستانی . مورْد اسپرم . برگ آن از آس بستانی زردتر و عریض تر و طرف او تند شبیه بسنان و چوب او صلب تر و بالای آن کمتر از ذرعی . ثمرش بغایت سرخ و مستدیر و از وسط برگ میروید و شاخهای بسیار از یک اصل برمی آید و آن را مورْد اسپرم و مُرد اسفرم نامند و مردم تنکابن جر خوانند و در زمستان برگ نمی ریزد و بسیار قابض است . (از تحفه ). قف و انظر، مورْد رومی، خیزران بلدی، مُرد رومی نیز نامهای دیگر آن است .<br /></font></div>'),
(1351, 'آس خانه', '<span class=\"hlight\">آس خانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) آسکده . سرآسیا. آسیاخانه . آسیاکده . مطحن . مرحی . محل آسیا.<br /></font></div>'),
(1352, 'آس نیکه', '<span class=\"hlight\">آس نیکه .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (اِ مرکب ) مورْد، یا گیاهی شبیه بکف دست و در طب بکار است و در اعمال قویتر از برگ و ثمر مورْد است .<br /></font></div>'),
(1353, 'آسا', '<span class=\"hlight\">آسا.</span> (اِ) گشاده شدن طبیعی دهان آدمی است بصورتی خاص از غلبه ٔ خواب یا ملال و یا شراب زدگی و یا پاره ای بیماریها. پاسک . باسک . دهان دره .دهن دره . دهن در. خمیازه . بیاستو. هاک . خامیازه . فاژ.فاژه . خامیاز. ثوباء. تثاوُب . آهنیابه <span class=\"hlight\">:</span> <br />چنان نمود بما دوش ماه نو دیدار<br />چو یار من که کند گاه خواب خوش آسا.<br /> <font color=\"Red\">بهرامی .</font><br />و ازاین گفته اند که عطسه ٔ بر وقت سخن، گوای باشد براستی، که اندر خبر است که عطسه از فرشته است و آسا کشیدن از شیطان . (کیمیای سعادت ).<br />و فعل آن کردن و کشیدن است .<br /> <BR><font color=\"Blue\">◄</font> زیور. زیب . آرایش .زینت <span class=\"hlight\">:</span> <br />بامّید قبولت بکر فکرم <br />چو بهر یوسف مصری زلیخا<br />بانواع نفایس خویشتن را<br />بسان نوعروسی کرده آسا.<br /> <font color=\"Red\">عسجدی .</font><br /> <BR><font color=\"Blue\">◄</font> وقار. ثبات . تمکین . آهستگی <span class=\"hlight\">:</span> <br />پیوسته همی شتاب و تمکین <br />ای شاه که طاعتت بود فرض <br />از عزم تو چرخ میکند وام <br />زآسای تو میکند زمین قرض .<br /> <font color=\"Red\">ملقابادی .</font><br />زور بستاند تدبیر تو از پنجه ٔ شیر<br />کبر بیرون کند آسای تو از طبع پلنگ .<br /> <font color=\"Red\">مختاری .</font><br />سرو اگر با قدّ رعنای تو هم بالاستی <br />کی چنان مطبوع و خوش اندام و باآساستی ؟<br /> <font color=\"Red\">ابن یمین .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به آسا</span> ؛ بطوری که باب است . به قسمی که معمول و رسم است . آلامُد. به اَندام <span class=\"hlight\">:</span> <br />ببین که صنعت استاد رسته ٔ کرمش <br />چگونه دوخت به آسا قبای تربیتم .<br /> <font color=\"Red\">ابن یمین .</font><br /> <br /> <BR><font color=\"Blue\">◄</font> طرز. روش . قاعده . قانون . <BR><font color=\"Blue\">◄</font> هیبت و صلابت . (برهان قاطع).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">برآسای ِ</span> ؛ مانندِ. بمنزله ٔ <span class=\"hlight\">:</span> <br />وراخواندی هر زمان اردشیر<br />که گوینده مردی بد و یادگیر<br />برآسای دستور بودی ورا<br />همان نیز گنجور بودی ورا.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1354, 'آسا', '<span class=\"hlight\">آسا.</span> (پسوند) اَسا. ادات تشبیه است . مثل . مانند. گون . گونه . شبه . وار. سان . سا. نظیر. شکل . صفت : آسمان آسا. بحرآسا. پادشاه آسا. پیل آسا. ترک آسا. خاقانی آسا. خورآسا. دلیرآسا. دودآسا. راهب آسا. رعدآسا. زمین آسا. ساسیاآسا. شیرآسا. عندلیب آسا. فلک آسا. مریدآسا. مهرآسا. یهودآسا <span class=\"hlight\">:</span> <br />عدوی او شود روباه بددل <br />چو شیرآسا خرامد او بمیدان .<br /> <font color=\"Red\">شهید.</font><br />دربدی ّ و گدی توئی منحوس <br />ساستاسا و ساسیاآسا.<br /> <font color=\"Red\">فرالاوی .</font><br />بزم خوب تو جنةالمأوی <br />مَثَل ِ ساقی تو حورآسا.<br /> <font color=\"Red\">خفاف .</font><br />عزم و حزمش به جنبش و بسکون <br />آسمان باشد و زمین آسا.<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />بگیر قبضه ٔ شمشیر عدل و جنبش کن <br />بگرد گرد همه هند پادشاه آسا.<br /> <font color=\"Red\">مسعودسعد.</font><br />جان بکف برنه و دلیرآسا<br />قصد این راه کن در او ماسا.<br /> <font color=\"Red\">سنائی .</font><br />از کس و ناکس ببرخاقانی آسا در جهان <br />هیچ صاحب درد را صاحب دوائی برنخاست .<br /> <font color=\"Red\">خاقانی .</font><br />صبحدم چون کِلّه بندد آه دودآسای من <br />چون شفق در خون نشیند چشم شب پیمای من .<br /> <font color=\"Red\">خاقانی .</font><br />فلک کج روتر است از خط ترسا<br />مرا دارد مسلسل راهب آسا.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(1355, 'آسا', '<span class=\"hlight\">آسا.</span> (نف مرخم ) مخفف آسای . آسایش دهنده . آسایش گیرنده :تن آسا. جان آسا. دل آسا. روان آسا. کم آسا <span class=\"hlight\">:</span> <br />کم آسا و دمساز و هنجارجوی <br />سبکیاب و آسان رو و تیزپوی .<br /> <font color=\"Red\">اسدی .</font><br /><BR><font color=\"Blue\">◄</font> آراینده یا آسایش دهنده <span class=\"hlight\">:</span> <br />در گه کین معرکه آرای رزم <br />در دم عیش انجمن آسای بزم .<br /> <font color=\"Red\">کاتبی .</font><br /> <br /></font></div>'),
(1356, 'آساب', '<span class=\"hlight\">آساب .</span> (ع اِ) ج ِ اِسب . مویهای برمکان و عانه یا موی شرم اندام .<br /></font></div>'),
(1357, 'آساد', '<span class=\"hlight\">آساد.</span> (ع اِ) ج ِ اَسَد.<br /></font></div>'),
(1358, 'آسارا', '<span class=\"hlight\">آسارا.</span> (اِخ ) نام محلی در راه طهران به چالوس میان ری زمین و کیاسر در <span class=\"hlight\" dir=\"rtl\">٨٣٣٠٠</span> گزی طهران .<br /></font></div>'),
(1359, 'آساره', '<span class=\"hlight\">آساره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ)حساب . و ظاهراً این صورت تصحیف آمار و آماره است .<br /></font></div>'),
(1360, 'آساس', '<span class=\"hlight\">آساس .</span> (ع اِ) ج ِ اَسَس . بنیادها.<br /></font></div>'),
(1361, 'آسال', '<span class=\"hlight\">آسال .</span> (ع اِ) نشانها. آثار. علامات . اخلاق . و این کلمه جمعی است بی مفرد.<br /></font></div>'),
(1362, 'آسال', '<span class=\"hlight\">آسال .</span> (اِ) بنیان . پایه . (جهانگیری ) (برهان قاطع) (شعوری ) (انجمن آرا) (برهان جامع) (بعض فرهنگهای هندوستانی ) <span class=\"hlight\">:</span> <br />ز دانا شنیدم که پیمان شکن <br />زن جاف جاف است آسال کن .<br /> <font color=\"Red\">ابوشکور (از جهانگیری و فرهنگهای بعد از او).</font><br />این کلمه پیش از جهانگیری در فرهنگی دیده نمیشود، مثلاً در اسدی و سروری نیست و نیز در لغات قدیمه ٔ عربی مترجم به فارسی مثل مقدمةالادب زمخشری و السامی فی الاسامی و دستوراللغه ٔ ادیب نطنزی و مهذب الاسماء و تاج المصادر زوزنی و مؤیدالفضلاء قاضی محمد دهار و نظایر آن به این کلمه در هیچ یک از مظان آن تصادف نمیشود. مصراع ثانی بیت فوق ابوشکور در فرهنگ اسدی پاول هورن بدین صورت است : زن جاف جاف است آسان فکن، و نسخه بدلی هم دارد بدین شکل : زن جاف جاف است بل کم ز زن . و در نسخه ٔ اسدی نفیس و نسبةً صحیحی که تاریخ کتابت آن <span class=\"hlight\" dir=\"rtl\">٧٦٦</span> هَ . ق . است ضبط مصراع این است : زن جاف جاف است و آسان فکن . کلمه ٔ آسال کن که ظاهراً مبتدع و مخترع آن صاحب فرهنگ جهانگیری است از ایهام و ابهام و بعید و قلیل الاستعمال بودن کلمه ٔ آسان فکن نشأت کرده .یعنی برای فهم بیت ابوشکور کلمه ٔ آسال را ساخته و معنی مصنوعی نیز بدان داده اند، چنانکه نسخه بدل اسدی پاول هورن نیز به همین علت پیدا شده است . آسان فکن چنانکه در جای خود خواهدآمد شبیه کلمه ٔ سست هل بیت ذیل منجیک است <span class=\"hlight\">:</span> <br />خواجه غلامی خریددیگر تازه <br />سست هل و حجره گرد و لتره ملازه .<br />و معنی زنی آسان فکن یا سست هل، زنی زود تن دردهنده و غیر اَبیّه و متأبّیه است مقابل منعه، متمنعه، اَبیّه و متأبّیه .<br /></font></div>'),
(1363, 'آسام', '<span class=\"hlight\">آسام .</span> (اِ) مقلوب آماس . (انجمن آرای ناصری ). و ظاهراً آسام اصل سام است نه مقلوب آماس : السرسام فارسیة، السَّر هو الرأس و السام هو الورم . البرسام، البر هو الصدر و السام هو الورم . و در فارسی حذف «آ» در کلمات مصدره ٔ بدان بسیار باشد. رجوع به «آ» شود.<br /></font></div>'),
(1364, 'آسان', '<span class=\"hlight\">آسان .</span> (ع اِ)ج ِ اُسُن . شمائل . اخلاق . <BR><font color=\"Blue\">◄</font> ج ِ اُسُن، به معنی بقیه ٔ پیه . <BR><font color=\"Blue\">◄</font> رشته های رسن و دوال .<br /></font></div>'),
(1365, 'آسان', '<span class=\"hlight\">آسان .</span> (ص، ق ) خوار. سهل . هَین . یَسیر. اَهوَن . مُیسر. میسور. مقابل دشوار، سخت، صعب، دشخوار، مشکل . نض <span class=\"hlight\">:</span> <br />بدان آنگهی زال اندیشه کرد<br />وز اندیشه آسانترش گشت درد.<br /> <font color=\"Red\">فردوسی .</font><br />ندیدم جهاندار بخشنده ای <br />بگاه و کیان بر درخشنده ای <br />همی این سخن بر دل آسان نبود<br />جز از خامشی هیچ درمان نبود<br />همی داشتم تا کی آید پدید<br />جوادی که جودش نخواهد کلید.<br /> <font color=\"Red\">فردوسی .</font><br />کنون چاره این دام را چون کنم <br />که آسان سر از بند بیرون کنم ؟<br /> <font color=\"Red\">فردوسی .</font><br />ور این رنج آسان کنم بر دلم <br />از اندیشه ٔ شاه دل بگسلم .<br /> <font color=\"Red\">فردوسی .</font><br />گر ایدون که با من تو پیمان کنی <br />نپیچی و اندیشه آسان کنی .<br /> <font color=\"Red\">فردوسی .</font><br />بزد نیزه و برگرفتش ز زین <br />بینداخت آسان بروی زمین .<br /> <font color=\"Red\">فردوسی .</font><br />برآویخت با طوس چون پیل مست <br />کمندی ببازو، عمودی بدست <br />کمربندبگرفت او را <font color=\"DarkGreen\"><b>[ طوس را ]</font></b> ز زین <br />برآورد آسان و زد بر زمین .<br /> <font color=\"Red\">فردوسی .</font><br />ز دانندگان گر بپوشیم راز<br />شود کار آسان بما بر دراز.<br /> <font color=\"Red\">فردوسی .</font><br />همی باش و دل را مکن هیچ تنگ <br />که آسان شود مر ترا کار جنگ .<br /> <font color=\"Red\">فردوسی .</font><br />کند <font color=\"DarkGreen\"><b>[ خدا ]</font></b> بر تو آسان همه کار سخت <br />ازوئی دل افروز و پیروزبخت .<br /> <font color=\"Red\">فردوسی .</font><br />اگر سعد با تاج شاهان بدی <br />مرا رزم و بزم وی آسان بدی .<br /> <font color=\"Red\">فردوسی .</font><br />همی پیلتن را بخواهی شکست <br />هماناکِت آسان نیاید بدست .<br /> <font color=\"Red\">فردوسی .</font><br />کشتی حسنات و ثمراتش بدرودی <br />دشوار تو آسان شد و آسان تو دشوار.<br /> <font color=\"Red\">منوچهری .</font><br />این چنین آسان فرزند نزاده ست کسی <br />که نه دردی بگرفتش متواتر نه تبی .<br /> <font color=\"Red\">منوچهری .</font><br />گفت ترا دشوار باشددویدن از پس من برنشین تا ترا آسان تر باشد. (تاریخ سیستان ). هرگاه اصل به دست آید کار فرع آسان باشد. (تاریخ بیهقی ). چون آسان گرفته آید آسان گردد. (تاریخ بیهقی ).<br />غمی نیست کآن دل هراسان کند<br />که آن را نه خرسندی آسان کند.<br /> <font color=\"Red\">اسدی .</font><br />بهو گفت با بسته دشمن به پیش <br />سخن گفتن آسان بود کم و بیش .<br /> <font color=\"Red\">اسدی .</font><br />میان عالم علوی و سفلی <br />باستادن نه کاری هست آسان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />اگر سهلست و آسان بر تو بر من <br />کشیدن ْ بار و پالان نیست آسان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />خیزم بفضل و رحمت یزدان حق <br />دشوار دهر بر دلم آسان کنم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گرچه صعبست عمل، از قبل بوی بهشت <br />جمله آسان شود ای پور پدر بر تو صعاب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نیست دشوار جهان بدتر از آسانش <br />چون همی بگذرد آسانش و دشوارش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بترس سخت ز سختی چو کار آسان شد<br />که چرخ زود کند سخت کار آسان را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و مر دهقانان و کشاورزان را بدین وقت <font color=\"DarkGreen\"><b>[ درسرطان ]</font></b> حق بیت المال دادن آسان بود. (نوروزنامه ). بدو <font color=\"DarkGreen\"><b>[ بمرجع ]</font></b> باید پیوست ... آنگاه ... انابت مفید نباشد نه راه بازگشتن مهیا... و نه طریق توبت آسان . (کلیله و دمنه ). کسب از جائی که همت بتوفیق آسمانی آراسته باشد آسان دست دهد. (کلیله و دمنه ). تا بر خوانندگان استفادت و اقتباس آسانتر باشد. (کلیله و دمنه ).<br />هر روز بمیر صد ره و زنده بباش <br />کآسان نبود ترا بیکبار بمرد.<br /> <font color=\"Red\">عطار.</font><br />هر کرا در عقل نقصان اوفتاد<br />کار او فی الجمله آسان اوفتاد.<br /> <font color=\"Red\">عطار.</font><br />به آسان برنمیگیرم دل از لعل لبت آری <br />مگس آسان بشهد افتد ولی دشوار برخیزد.<br /> <font color=\"Red\">جمالی شیرازی .</font><br /> <BR><font color=\"Blue\">◄</font> بی تعب . بی رنج <span class=\"hlight\">:</span> <br />تو رنجی و آسان دگر کس خورد<br />سوی گور و تابوت تو ننگرد.<br /><font color=\"Red\">فردوسی .</font><br />یکی چیز گرد آرد از هر دری <br />کشد رنج و آسان خورد دیگری .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسان داشتن </span> ؛ استسهال . تهوین .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسان شدن </span> ؛ تیسر. (دهار). هون . (ادیب نطنزی ) (زوزنی ). یُسر. تسهل . تساهل . استیسار.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسان فراگرفتن، آسان گرفتن </span> ؛ تجوز. تساهل . سهل انگاشتن . مساهله . مسامحه . سهل انگاری کردن . استیسار. ترخص . (دهار). بچیزی نداشتن . خوار شمردن . خرد پنداشتن . اهمیت ندادن <span class=\"hlight\">:</span> <br />کمان دار دل را، زبانت چو تیر<br />تو این داستان من آسان مگیر.<br /> <font color=\"Red\">فردوسی .</font><br />ز بغداد راه خراسان گرفت <br />همه رنجها بر دل آسان گرفت .<br /> <font color=\"Red\">فردوسی .</font><br />چنین کارها بر دل آسان مگیر<br />یکی رای زن با خردمند پیر.<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت پس کای گرامی دبیر<br />تو کاری چنین بر دل آسان مگیر.<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت پس شاه با اردشیر<br />که کار جهان بر دل آسان مگیر<br />بدان ای برادر که بیداد شاه <br />پی پادشاهی ندارد نگاه .<br /> <font color=\"Red\">فردوسی .</font><br />اول چراغ بودی آهسته شمع گشتی <br />آسان فراگرفتم در خرمن اوفتادی .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسان فراگرفتن با کسی </span> ؛ میاسره . (زوزنی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسان فراگرفتن با یکدیگر</span> ؛ تسامح . (زوزنی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسان فراگرفتن چیزی را</span> ؛ ترخص . (زوزنی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسان فراگرفتن در معامله </span> ؛ اغماض . تغمیض .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسان کردن </span> ؛ تسمیح . تسهیل . (دهار). تیسیر. (زوزنی ). تسریح . تهوین . (مجمل اللغة). تخفیض .<br /> <BR><font color=\"Blue\">◄</font> مُرفّه . خوش <span class=\"hlight\">:</span> <br />چو دانش تنش را نگهبان بود<br />همه زندگانیش آسان بود.<br /> <font color=\"Red\">فردوسی .</font><br />همه شبهای دیگر آسان باش .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آسان گذران کار جهان گذران را</span> .<br /> <span class=\"hlight\">آسان گردد بر آنچه همت بستی </span> .<br /> <span class=\"hlight\">بر آسمان شدن آسان بود بپای براق </span> .<br /> <font color=\"Red\">ظهیر فاریابی .</font><br /> <span class=\"hlight\">بنظاره بر، جنگ آسان بود</span> .<br /> <font color=\"Red\">اسدی .</font><br /> <span class=\"hlight\">چون معانی جمع گردد شاعری آسان بود</span> .<br /> <font color=\"Red\">عنصری .</font><br /> <span class=\"hlight\">که آسان زید مرد آسان گذار</span> .<br /> <font color=\"Red\">نظامی .</font><br /> <span class=\"hlight\">مشکلی نیست که آسان نشود</span> <br /> <span class=\"hlight\">مرد باید که هراسان نشود</span> .<br /> <font color=\"Red\">؟</font><br /> <span class=\"hlight\">هرچه آسان یافتی آسان دهی </span> .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آئین و آسان </span> ؛ آئین و سان <span class=\"hlight\">:</span> <br />که خرد و بزرگ و زن و مرد پاک <br />بگویند و از کس ندارند باک <br />همه بر سر کار و سامان خویش <br />بجویند آئین <font color=\"DarkGreen\"><b>[ و ]</font></b> آسان خویش .<br /><font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /></font></div>'),
(1366, 'آسان', '<span class=\"hlight\">آسان .</span> (اِ) در بعض فرهنگها به معنی بنیان آمده است چنانکه آسال را نیز به همین معنی آورده اند و آن اشتباهی است که از غلط خواندن بیت ابوشکور دست داده است . رجوع به آسال و آسان فکن شود.<br /></font></div>'),
(1367, 'آسان فکن', '<span class=\"hlight\">آسان فکن .</span> <font color=\"DarkGreen\"><b>[ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ک َ ]</font></b> (نف مرکب <span class=\"hlight\" dir=\"rtl\">/</span> ن مف مرکب ) که زود تن دردهد. که منعی پیش نیارد. زودهِل . سست هِل : زنی آسان فکن ؛ غیراَبیّه . غیرمنعه <span class=\"hlight\">:</span> <br />ز دانا شنیدم که پیمان شکن <br />زن جاف جاف است آسان فکن .<br /> <font color=\"Red\">ابوشکور (از فرهنگ اسدی و فرهنگ شعوری ).</font><br />رجوع به سست هِل و آسال و آسان شود.<br /></font></div>'),
(1368, 'آسان کار', '<span class=\"hlight\">آسان کار.</span> (ص مرکب ) رفیق . سهل الجانب . هش المکسر.<br /></font></div>'),
(1369, 'آسان کاری', '<span class=\"hlight\">آسان کاری .</span> (حامص مرکب ) مواسات . سهولت جانب . رفق . مساهلت . مدارات .<br /></font></div>'),
(1370, 'آسان گذار', '<span class=\"hlight\">آسان گذار.</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (نف مرکب ) سَمح <span class=\"hlight\">:</span> <br />رفیقی نیک یار از لشکری به <br />دلی آسان گذار از کشوری به .<br /> <font color=\"Red\">(ویس و رامین ).</font><br /><BR><font color=\"Blue\">◄</font> سهل انگار. مسامح . سهل .<br /></font></div>'),
(1371, 'آسان گذاری', '<span class=\"hlight\">آسان گذاری .</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (حامص مرکب ) سماحت .مسامحه . تسامح . مسامحت . مساهله . اغماض <span class=\"hlight\">:</span> <br />به آسان گذاری دمی میشمار<br />که آسان زیَد مرد آسان گذار.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(1372, 'آسان گوار', '<span class=\"hlight\">آسان گوار.</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (نف مرکب ) سریعالهضم . سریعالانهضام .<br /></font></div>'),
(1373, 'آسان گواری', '<span class=\"hlight\">آسان گواری .</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (حامص مرکب ) چگونگی آسان گوار.<br /></font></div>'),
(1374, 'آسان گیر', '<span class=\"hlight\">آسان گیر.</span> (نف مرکب ) سهل انگار. مداهن .<br /></font></div>'),
(1375, 'آسان گیری', '<span class=\"hlight\">آسان گیری .</span> (حامص مرکب ) سهل انگاری . مداهنه .<br /></font></div>'),
(1376, 'آسانی', '<span class=\"hlight\">آسانی .</span> (حامص ) (از پهلوی آسانیه، استراحت . آسایش . آشتی . صلح ) یُسر. سهولت . خواری . کسه . خلاف دشواری، دشخواری، سختی و صعوبت <span class=\"hlight\">:</span> ایزدتعالی ... مدت ملوک طوایف بپایان آورده بود تا اردشیر را آن بدان آسانی برفت . (تاریخ بیهقی ).چون خداوند متعال ... بدان آسانی تخت ملک بما داد اختیار آن است که عذر گناهکاران بپذیریم . (تاریخ بیهقی ). سوی پسر کاکو و دیگران ... نامه ها فرمودیم بقرار گرفتن این حالها بدین خوبی و آسانی . (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسانی دادن </span> . شفا. (دهار):<br />آنچه با رنج یافتیش به ذُل <br />تو به آسانی از گزافه مدیش .<br /> <font color=\"Red\">رودکی .</font><br />بیرون کندت خدای از او گرچه <br />بیرون نشوی تو زو به آسانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />صعب باشد پس ِ هر آسانی <br />نشنیدی که خاربا خرماست ؟<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> خواب . (برهان ). <BR><font color=\"Blue\">◄</font> رفاهیت . آسایش . خوشی . کامروائی . کامرانی . استراحت . رفاه . بی رنجی . رَوح . لذّت . مقابل رنج و گزند <span class=\"hlight\">:</span> <br />تو بر خویشتن گر کنی صد گزند<br />چه آسانی آید بدان ارجمند...<br /> <font color=\"Red\">فردوسی .</font><br />خداوند کوپال و شمشیر و رنج <br />خداوند آسانی و تاج و گنج .<br /> <font color=\"Red\">فردوسی .</font><br />نگه کرد بر کار چرخ بلند<br />ز آسانی و سود و درد و گزند.<br /> <font color=\"Red\">فردوسی .</font><br />همی از شهنشاه ترسانیَم <br />سزا زو بود رنج و آسانیَم .<br /> <font color=\"Red\">فردوسی .</font><br />نماند بکس روز سختی ّ و رنج <br />نه آسانی و شادمانی ّ و گنج .<br /> <font color=\"Red\">فردوسی .</font><br />نه دشواری از چیز برتر مَنِش <br />نه آسانی از اندک اندر بُوِش .<br /> <font color=\"Red\">فردوسی .</font><br />چو از پیش بدخواه برداشتش <br />به آسانی آورد و بگذاشتش .<br /> <font color=\"Red\">فردوسی .</font><br />دلاور چو پرهیز جوید ز جفت <br />بماند به آسانی اندر نهفت <br />بدان تاش دختر نباشد ز بن <br />نباید شنیدنْش ننگ سخن .<br /> <font color=\"Red\">فردوسی .</font><br />جهان جای بقا نیست به آسانی بگذار<br />بایوان چه بری رنج و بکاخ و ستناوند؟<br /> <font color=\"Red\">طیّان .</font><br />اینْت خوشی ّ و اینت آسانی <br />روز صدقه ست و بخشش و قربان (کذا).<br /> <font color=\"Red\">فرخی .</font><br />نخواهم بی تو یارا زندگانی <br />نه آسانی و کام این جهانی .<br /><font color=\"Red\">(ویس و رامین ).</font><br />از امّید تو چون من دل بریدم <br />ز نومیدی به آسانی رسیدم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />و حمزه اندر تاریخ خویش گفته است که نود پادشاه بکشت <font color=\"DarkGreen\"><b>[ اردشیر بابکان ]</font></b> از طوائف و از آن پس با مراد و آسانی بود. (مجمل التواریخ ).<br />روز بیکاری و شب آسانی <br />کی رسی در سریر ساسانی ؟<br /> <font color=\"Red\">سنائی .</font><br /><BR><font color=\"Blue\">◄</font> کاهلی <span class=\"hlight\">:</span> <br />ز آسانی نیاید شادکامی <br />ز بیرنجی نیاید نیک نامی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />جای رنج و انده است این ای پسر<br />جای آسانی ّ و شادی دیگر است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بیا بکش همه رنج و مجوی آسانی <br />که کار گیتی بی رنج می نگیرد ساز.<br /> <font color=\"Red\">مسعودسعد.</font><br />که آسانی گزیند خویشتن را<br />زن و فرزند بگذارد بسختی .<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /> <BR><font color=\"Blue\">◄</font> سرّاء. رخاء. رَغد. رفاه . رغادت . نعمت . نعیم . ناز. یسار <span class=\"hlight\">:</span> <br />آنکه در نعمت و آسایش و آسانی زیست <br />مردنش زینهمه شک نیست که دشوار آید.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> سماحت . نرمی . رفق .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسانی کردن در معامله </span> ؛ اِغاضه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">کاری را که گرگ بسختی انجام کند روباه به آسانی از پیش برد</span> ؛ گاهی چاره و حیلت از زور رسیدن مقصود را سودمندتر افتد.<br /> <span class=\"hlight\">هرکه زندگی به آسانی کند مرگش نیز به آسانی بود</span> . (مرزبان نامه ).<br /> <span class=\"hlight\">یک نَه و صدهزار آسانی </span>؛ پذیرفتن و تعهد امور مایه ٔ رنج و تن زدن از کارهامایه ٔ بی رنجی باشد <span class=\"hlight\">:</span> <br />از تو پرسم غمم خوری گو نه <br />یک نَه و صدهزار آسانی .<br /><font color=\"Red\">عمادی شهریاری .</font><br /></font></div>'),
(1377, 'آسانیدن', '<span class=\"hlight\">آسانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) رجوع به برآسانیدن شود.<br /></font></div>'),
(1378, 'آسای', '<span class=\"hlight\">آسای .</span> (نف مرخم ) رجوع به آسا شود.<br /></font></div>'),
(1379, 'آسایانیدن', '<span class=\"hlight\">آسایانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b>(مص ) راحت بخشیدن : الاراحه ؛ برآسایانیدن . (زوزنی ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1380, 'آسایش', '<span class=\"hlight\">آسایش .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِمص ) اسم مصدر و مصدر دویم آسودن . راحت . استراحت . آسانی . آسودگی . دعه . وداعَت . خفض عیش . تنعم . رَوح . مقابل رنج <span class=\"hlight\">:</span> <br />بدانگه که می چیره شد بر خرد<br />کجا خواب و آسایش اندرخورد.<br /> <font color=\"Red\">فردوسی .</font><br />شما را از آسایش و بزمگاه <br />بیکسر تهی شد سر از رزمگاه .<br /> <font color=\"Red\">فردوسی .</font><br />کنون بر تو بر جای بخشایش است <br />نه هنگام آرام و آسایش است .<br /> <font color=\"Red\">فردوسی .</font><br />همه جامه بر تنْش چون آب بود<br />نیازش به آسایش و خواب بود.<br /> <font color=\"Red\">فردوسی .</font><br />تا رنج کهتری بر خویشتن ننهی به آسایش مهتری نرسی . (قابوسنامه ).<br />ای پسر آسایش من رفتن است <br />زآنکه قرارم بدگر مسکن است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بطر آسایش ... بدو <font color=\"DarkGreen\"><b>[ بشتربه ]</font></b> راه یافت . (کلیله و دمنه ).<br />هرچند که لنبک دهد آسایش بهرام <br />بهرام بشاهی به و لنبک بسقائی .<br /> <font color=\"Red\">خاقانی .</font><br />بهر آسایش زبان کوتاه کن <br />در عوضْمان همتی همراه کن .<br /> <font color=\"Red\">مولوی .</font><br />خدا را بدان بنده بخشایش است <br />که خلق از وجودش در آسایش است .<br /> <font color=\"Red\">سعدی .</font><br />آسایش دو گیتی تفسیر این دو حرف است <br />با دوستان مروت با دشمنان مدارا.<br /> <font color=\"Red\">حافظ.</font><br />هست اگر آسایشی زیر فلک در غفلت است <br />وای بر آن کس کز این خواب گران برخاسته ست .<br /> <font color=\"Red\">صائب .</font><br /> <BR><font color=\"Blue\">◄</font> سکون نفس <span class=\"hlight\">:</span> <br />به آسایش و نیکنامی گرای <br />گریزان شو از مرد ناپاک رای .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مایحتاج، لوازم، اسباب آسایش <span class=\"hlight\">:</span> <br />همه راه پرپوشش و خوردنی <br />از آسایش بزم و گستردنی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> عطالت . تعطل . عطلت . فراغ . فراغت . کاهلی . غنودن . سبات <span class=\"hlight\">:</span> <br />چو چندی برآمد بر این روزگار<br />شب و روز آسایش آمد ز کار<br />چنان بد که در کوه چین آن زمان <br />دد ودام بودی فزون از گمان .<br /> <font color=\"Red\">فردوسی .</font><br />نشاید درنگ اندر این کار هیچ <br />که خام آید آسایش اندر بسیچ .<br /> <font color=\"Red\">فردوسی .</font><br />دلم بگرفت از این آسوده کاری <br />که آسایش بود بنیاد خواری .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />تا گویند خصمان بجنگ پیش نخواهند آمد که رسول می آمد تا امروز آسایشی باشد خوارزمشاه را آنگاه نگریم . (تاریخ بیهقی ). غایت نادانی است ... آموختن علم به آسایش . (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> سکون . بی جنبشی . آرام <span class=\"hlight\">:</span> <br />زیر کبود چرخ بی آسایش <br />هرگز گمان مبر که بیاسائی .<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسایش جستن </span> ؛ استراحت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسایش دادن </span> ؛ اراحه . اِجمام .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسایش کردن، آسایش گرفتن </span> ؛ استراحت . اسبات . اِتِّداع <span class=\"hlight\">:</span> <br />تا روز پدید آید و آسایش گیرم <br />زین علت مکروه و ستمکار و ژکاره .<br /><font color=\"Red\">خسروانی .</font><br /></font></div>'),
(1381, 'آسایش جو', '<span class=\"hlight\">آسایش جو.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (نف مرکب ) آسایش جوی . آنکه آسایش طلبد. آنکه فراغت و کاهلی دوست گیرد.<br /></font></div>'),
(1382, 'آسایش جویی', '<span class=\"hlight\">آسایش جویی .</span> <font color=\"DarkGreen\"><b>[ ی ِ جو ]</font></b> (حامص مرکب ) چگونگی و صفت آسایش جوی .<br /></font></div>'),
(1383, 'آسایش خواه', '<span class=\"hlight\">آسایش خواه .</span> <font color=\"DarkGreen\"><b>[ ی ِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) آسایش جوی .<br /></font></div>'),
(1384, 'آسایش خواهی', '<span class=\"hlight\">آسایش خواهی .</span> <font color=\"DarkGreen\"><b>[ ی ِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (حامص مرکب ) آسایش جویی .<br /></font></div>'),
(1385, 'آسایش طلب', '<span class=\"hlight\">آسایش طلب .</span> <font color=\"DarkGreen\"><b>[ ی ِ طَ ل َ ]</font></b> (نف مرکب ) آسایش جوی .<br /></font></div>'),
(1386, 'آسایش طلبی', '<span class=\"hlight\">آسایش طلبی .</span> <font color=\"DarkGreen\"><b>[ ی ِ طَ ل َ ]</font></b> (حامص مرکب ) آسایش جویی .<br /></font></div>'),
(1387, 'آسایش گه', '<span class=\"hlight\">آسایش گه .</span> <font color=\"DarkGreen\"><b>[ ی ِ گ َه ْ ]</font></b> (اِ مرکب ) آسایش گاه .<br /></font></div>'),
(1388, 'آسایشگاه', '<span class=\"hlight\">آسایشگاه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِ مرکب ) جائی که در آن آسایند. جای استراحت . آرام . آرامگاه . <BR><font color=\"Blue\">◄</font> بیت اللطف . <BR><font color=\"Blue\">◄</font> ساناتوریوم . (فرهنگستان ).<br /></font></div>'),
(1389, 'آساینده', '<span class=\"hlight\">آساینده .</span> <font color=\"DarkGreen\"><b>[ ی َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه آسودگی گرفته است .<br /></font></div>'),
(1390, 'آساییدن', '<span class=\"hlight\">آساییدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آرام یافتن . بازایستادن از کار.<br /></font></div>'),
(1391, 'آسبان', '<span class=\"hlight\">آسبان .</span> (ص مرکب، اِ مرکب ) آسیابان <span class=\"hlight\">:</span> <br />هنوز این آس خون گردان از آن است <br />که آن بی آب دیده آسبان است .<br /><font color=\"Red\">نزاری قهستانی .</font><br /></font></div>'),
(1392, 'آستارا', '<span class=\"hlight\">آستارا.</span> (اِخ ) نام بندر و مرکز تجارتی بمغرب خزر بشمال گرگانه رود بر خط سرحدی ایران و روس در <span class=\"hlight\" dir=\"rtl\">٣٧</span>هزارگزی جنوب لنکران، در مصب رودی به همین نام، موقف کشتی های بازرگانی، دارای پست خانه و تلگرافخانه و مدرسه و بیمارخانه، در <span class=\"hlight\" dir=\"rtl\">١٧٣٣٠٠</span>گزی طهران و <span class=\"hlight\" dir=\"rtl\">٢٨١٠٠٠</span>گزی تبریز. پیشتر این بندر جزو تقسیمات ایالت آذربایجان بود وامروز جزو ولایت گیلان است . این شهر را رود آستارا بدو بخش میکند، بخش شمالی آستارای روس و جنوبی آستارای ایران است . و شیلات این بندر و نواحی آن بسیار مهم وذیقیمت است . <BR><font color=\"Blue\">◄</font> آستارا و گرگانرود. یکی از تقسیمات نوزده گانه ٔ رشت . مرکز آن شهر ریگ که آن راگرگانه رود نیز گویند، و دارای معادن ذغال سنگ است .<br /></font></div>'),
(1393, 'آستان', '<span class=\"hlight\">آستان .</span> (اِ) درگاه . درگه . آستانه . وصید. فِناء. سُدّه . کفش کن . جناب . عتبه . ساحت . حضرت . کریاس (بفارسی ). اُسکفه . گذرگاه . و آن قسمت پیشین خانه باشد پیوسته ٔ بدر <span class=\"hlight\">:</span> <br />چو آن شیرپیکر علامت به بندد<br />کند سجده بر آستانش دوپیکر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />کز ندیمان مجلس ار نشود<br />از مقیمان آستان باشد.<br /> <font color=\"Red\">انوری .</font><br />وآنکه چون آستان فتد در پای <br />پیش او سر به آستان ننهند.<br /> <font color=\"Red\">مجیر بیلقانی .</font><br />از خانه ٔ اختیار خصمت <br />چون پرده برون آستان باد.<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />راست شو تا به راستان برسی <br />خاک شو تا بر آستان برسی .<br /> <font color=\"Red\">اوحدی .</font><br />سود کس بر زیان او مپسند<br />فتنه بر آستان او مپسند.<br /> <font color=\"Red\">اوحدی .</font><br />مشو یک زمان غایب از آستانش <br />که هر کس که غایب شد او هست خایب .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />بر آستان تو غوغای عاشقان نه عجب <br />که هر کجا شکرستان بود مگس باشد.<br /> <font color=\"Red\">حافظ.</font><br />از آستان پیر مغان سر چرا کشم <br />دولت در این سرا و گشایش در این در است .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آستان بوس </span> ؛ آستان بوسی <span class=\"hlight\">:</span> <br />پادشاها همه شاهان که بخواب آمده اند<br />آستان بوس تو در خواب تمنا کردند.<br /> <font color=\"Red\">امیرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آستان بوسی </span> ؛ اصطلاحی است در زبان ادب و احترام مترادف تشرف و بخدمت رسیدن، یعنی نزد بزرگی رفتن .<br /> <BR><font color=\"Blue\">◄</font> (ص ) ستان . برپشت خفته <span class=\"hlight\">:</span> <br />در تنگنای بیضه زتأثیر عدل او<br />نقاش صنع پیکر مرغ آستان نهاد.<br /><font color=\"Red\">سلمان ساوجی .</font><br /></font></div>'),
(1394, 'آستانه', '<span class=\"hlight\">آستانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) آستان . حضرت . جناب . عتبه . ساحت . وصید. فناء. درگاه . کریاس . سدّه . گذرگاه . کفش کن . اَستانه <span class=\"hlight\">:</span> <br />بهشت آئین سرائی را بپرداخت <br />ز هرگونه در او تمثالها ساخت <br />ز عود و چندن او را آستانه <br />درش سیمین و زرّین بالکانه .<br /> <font color=\"Red\">رودکی .</font><br />پیاده برفتند تا پیش اوی <br />بدان آستانه نهادند روی .<br /> <font color=\"Red\">دقیقی .</font><br />اگر بخواهم خانی کنم ز چشم و رخم <br />بناش زرّ و زمرّدْش آستانه کنم .<br /> <font color=\"Red\">خسروی .</font><br />بد آن بد کز این بد بهانه منم <br />سخن را نخست آستانه منم .<br /> <font color=\"Red\">فردوسی .</font><br />در خانه ٔ دین چونکه درنیائی <br />استاده چه ماندی بر آستانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بر عالم دین عالی آسمان شد<br />بر خانه ٔ حق محکم آستانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ز کویش ای دل پردرد پای بازمکش <br />وگرچه دانم کاین بادیه بپای تو نیست <br />بر آستانه سرِ درد بر زمین میزن <br />که پیشگاه سریر جلال جای تو نیست .<br /> <font color=\"Red\">(از مرصادالعباد).</font><br />آستانه و صدر در معنی کجاست <br />ما و من کو آن طرف کآن یار ماست .<br /> <font color=\"Red\">مولوی .</font><br />اگر ملازم خاک در کسی باشی <br />چو آستانه ندیم خسیت باید بود.<br /> <font color=\"Red\">ابن یمین .</font><br />همت ز آستانه ٔ فقر است ملک جو<br />آری هوا ز کیسه ٔ دریا بود سقا.<br /> <font color=\"Red\">خاقانی .</font><br />آسمان بلندرتبت را<br />رتبت قَدرت آستانه کند.<br /> <font color=\"Red\">مسعودسعد.</font><br />دو سال شد که بر این فرخ آستانه مرا<br />شده ست دست تفکر بزیر روی ستون .<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />مرا مبشر اقبال بامداد پگاه <br />نوید عاطفت آورد زآستانه ٔ شاه .<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />گر آستانه ٔ سیمین بمیخ زر بزند<br />گمان مبر که یهودی شریف خواهد شد.<br /> <font color=\"Red\">سعدی .</font><br />بر آستانه ٔ میخانه گر سری بینی <br />مزن بپای که معلوم نیست نیت او.<br /> <font color=\"Red\">حافظ.</font><br />و توسعاً قسمت فوقانی در را که بمحاذات آستانه است نیز آستانه گویند و بنایان آن را نعل درگاه خوانند و عرب اُسکفه نامد. <BR><font color=\"Blue\">◄</font> (اصطلاح نجاری ) چوب زیرین چارچوب (در دَر). اُسکفه . <BR><font color=\"Blue\">◄</font> مجازاً، مقدمه . وسیله <span class=\"hlight\">:</span> <br />سفر مربی مرد است و آستانه ٔ جاه <br />سفر خزانه ٔ مال است و اوستاد هنر.<br /> <font color=\"Red\">انوری .</font><br /><BR><font color=\"Blue\">◄</font> مجازاً، بارگاه ملوک . <BR><font color=\"Blue\">◄</font> (اِخ )آستانه، آستانه ٔ قدس، آستانه ٔ قدس رضوی ؛ مشهد حضرت رضا علیه السلام . <BR><font color=\"Blue\">◄</font> مشهد حضرت عبدالعظیم . <BR><font color=\"Blue\">◄</font> اسلامبول .<br /></font></div>'),
(1395, 'آستانه', '<span class=\"hlight\">آستانه .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) نام محلی در راه لاهیجان و رشت میان بازگوراب و گورکا، در <span class=\"hlight\" dir=\"rtl\">٥٦١٤٠٠</span>گزی طهران . مشهد سیّد جلال الدین اشرف بن موسی الکاظم . <BR><font color=\"Blue\">◄</font> نام قریه ای بدامغان دارای معدن ذغال سنگ .<br /></font></div>'),
(1396, 'آستانی', '<span class=\"hlight\">آستانی .</span> (ص نسبی ) منسوب به آستان . <BR><font color=\"Blue\">◄</font> (حامص ) کنایه از فروتنی و تواضع <span class=\"hlight\">:</span> <br />سری چون نقش پای دوست با افتادگان دارم <br />از آن بر آسمانی برگزیدم آستانی را.<br /><font color=\"Red\">طالب آملی .</font><br /></font></div>'),
(1397, 'آستر', '<span class=\"hlight\">آستر.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ق مرکب ) مخفف آنسوی تر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">زآستر</span> ؛ مخفف از آنسوی تر <span class=\"hlight\">:</span> <br />ستاره ندیدم ندیدم رهی <br />بدل زآستر ماندم از خویشتن .<br /> <font color=\"Red\">ابوشکور.</font><br />بمرو آیم و زآستر نگذرم <br />نخواهم که رنج آید از لشکرم .<br /> <font color=\"Red\">فردوسی .</font><br />از این کوه کس زآستر نگذرد<br />مگر رستم این رزمگه بنگرد.<br /> <font color=\"Red\">فردوسی .</font><br />هیچ علم از عقل اوموئی نگردد بازپس <br />هیچ فضل از خلق او گامی نگردد زآستر.<br /> <font color=\"Red\">فرخی .</font><br />و آنچه صلاح من در آن است و تو بینی و مثال دهی زآستر نشوم . (تاریخ بیهقی ).<br />گر جز رضای تست غرض مر مرا ز عمر<br />بر خیرها مده بدو عالم ظفر مرا<br />واندر رضای خویش تو یارب بدو جهان <br />از خاندان حق تو مکن زآستر مرا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چو روشن شد از نور خور باختر<br />شد از چشم سایه زمین زآستر.<br /> <font color=\"Red\">مسعودسعد.</font><br />بوالفضول از زمانه زآستر است .<br /> <font color=\"Red\">خاقانی .</font><br />چون بهمه حرف قلم برکشید<br />زآستر از عرش علم برکشید.<br /> <font color=\"Red\">نظامی .</font><br />بکنه مدحت او چون رسی که من باری <br />بسی ز خطه ٔ امکانْش زآستر دیدم .<br /><font color=\"Red\">کمال اسماعیل .</font><br /></font></div>'),
(1398, 'آستر', '<span class=\"hlight\">آستر.</span><font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ) لای و تاه زیرین جامه و جز آن . زیره . بطانه . مقابل اَبْره، رویه، ظهاره، و روی <span class=\"hlight\">:</span> <br />عارضش را جامه پوشیده ست نیکوئی ّ و فر<br />جامه ای کآن ابره از مشک است و زآتش آستر.<br /> <font color=\"Red\">عنصری .</font><br />نار ماند بیکی سُفرگک دیبا<br />آستر دیبه ٔ زرد، ابره ٔ آن حمرا.<br /> <font color=\"Red\">منوچهری .</font><br />بر جامه ٔ سخنهاش جز معنی آستر نیست <br />چون پندهاش پندی جز در قران دگر نیست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />قدر تو کسوتیست که خیاط فطرتش <br />بردوخته است ز ابره ٔ افلاکش آستر.<br /> <font color=\"Red\">انوری .</font><br />فلک ز مفرش خود خسقی شفق دار است <br />برای آستر صوف و حبر اخضر ما.<br /> <font color=\"Red\">نظام قاری .</font><br />فراوان در این کارگه کارگر<br />یکی ابره بافد دگر آستر.<br /> <font color=\"Red\">ظهوری ترشیزی .</font><br />مرا سردار پشمین جبه ای داد<br />نه آن را آستر بود و نه روئی .<br /> <font color=\"Red\">یغما.</font><br /> <BR><font color=\"Blue\">◄</font> پارچه ٔ کم ارز که بطانه بدان کنند. آستری <span class=\"hlight\">:</span> <br />شنیدم که فرماندهی دادگر<br />قبا داشتی هر دو رو آستر.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آستر کردن، آستر زدن </span> ؛ دوختن آستر بجامه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دهانش آستر دارد</span> ؛ تعبیر مثلی که بمزاح به آنکه طعام یا شرابی سخت گرم خورد و منتظر خنک شدن آن نشود گویند.<br /></font></div>'),
(1399, 'آسترکی', '<span class=\"hlight\">آسترکی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) شعبه ای از طایفه ٔ دورکی بختیاری و آن شعبه بر دو تیره است، چاربری و کایی وند.<br /></font></div>'),
(1400, 'آستری', '<span class=\"hlight\">آستری .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص نسبی، اِ) جامه و پارچه ٔ کم ارز که بطانه از آن کنند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آستری </span> ؛ جامه و قماشی بد و بی دوام .<br /></font></div>'),
(1401, 'آستن', '<span class=\"hlight\">آستن .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِ) آستین . آستی . کُم ّ <span class=\"hlight\">:</span> <br />روح اﷲ ار زآستن مریم آمده ست <br />صد مریم است روح ترا اندر آستین .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />کلیم از ید بیضا همین قَدَر لافد<br />که دست زآستن پیرهن برون آرد.<br /><font color=\"Red\">شفائی .</font><br /></font></div>'),
(1402, 'آسته', '<span class=\"hlight\">آسته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (اِ) هسته . اَسته . هستو. خسته .<br /></font></div>'),
(1403, 'آستی', '<span class=\"hlight\">آستی .</span> (اِ) مخفف آستین <span class=\"hlight\">:</span> <br />جوانان ز پاکی ّ و ازراستی <br />نوشتند بر پشت دست آستی .<br /> <font color=\"Red\">فردوسی .</font><br />قلون رفت با کارد در آستی <br />پدیدار شد کژّی و کاستی .<br /> <font color=\"Red\">فردوسی .</font><br />ز کژّی نجوید کسی راستی <br />گر از راستی پر کند آستی .<br /> <font color=\"Red\">فردوسی .</font><br />تو گفتی که از تیزی و راستی <br />ستاره برآرد همی زآستی .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد بجستش بر و آستی <br />همی جست از او کژّی و کاستی .<br /> <font color=\"Red\">فردوسی .</font><br />از گوهر دامنی برافشانم <br />گر آستئی ز طبع بفشانم .<br /> <font color=\"Red\">مسعودسعد.</font><br />خرامان چو کبک دری از وثاق <br />برون آمدی برزده آستی .<br /> <font color=\"Red\">مسعودسعد.</font><br />زآن زلفک پُرتاب و از آن دیده ٔ پرخواب <br />یک آستی و دامن مشک و گهر آمد.<br /> <font color=\"Red\">مسعودسعد.</font><br />هرکه او پیشه راستی دارد<br />نقد معنی در آستی دارد.<br /> <font color=\"Red\">سنائی .</font><br />کنار و آستی جان چو بحر پر در شد<br />که در ولایت معنی گدای کان من است .<br /> <font color=\"Red\">اثیر اخسیکتی .</font><br />تا کی جوئی طراز آستی من <br />نیست مرا آستین چه جای طراز است ؟<br /> <font color=\"Red\">خاقانی .</font><br />روح اﷲ ار ز آستی مریم آمده ست <br />صد مریم است روح ترا اندر آستین .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />آه از این طائفه ٔ زرق ساز<br />آستی کوته و دست دراز.<br /> <font color=\"Red\">امیرخسرو.</font><br />تا که کند آسمان از شفق لاله گون <br />آستی و دامن از خون شهیدان خضاب .<br /> <font color=\"Red\">زلالی .</font><br />ای همه از رادی و از راستی <br />گیتی زین هردو برآراستی <br />بی تو جوانمردی ناقص بود<br />راست چو پیراهن بی آستی .<br /><font color=\"Red\">قطران .</font><br /></font></div>'),
(1404, 'آستیاژ', '<span class=\"hlight\">آستیاژ.</span> (اِخ ) اَستیاژ. آسپاداس . نام آخرین پادشاه مِدو او را داریوش در <span class=\"hlight\" dir=\"rtl\">٥٤٩</span> ق .م . از پادشاهی خلع کرد. ازدهاک . (دمشقی ). آزی دهاک . اژدهاک . اژدها. اژدرها. ده آک . ضحاک . ضحاک ماران . و رجوع به اَستیاژ و آک شود.<br /></font></div>'),
(1405, 'آستیلن', '<span class=\"hlight\">آستیلن .</span> <font color=\"DarkGreen\"><b>[ س ِ ل ِ ]</font></b> (فرانسوی، اِ) اَسِتیلن . دَم که از نیم سوخته ٔ زغال سنگ و آهک مکلس گیرند.<br /></font></div>'),
(1406, 'آستیم', '<span class=\"hlight\">آستیم .</span> (اِ) چرک . ریم . ستیم . هَو. سیم در جراحت . <BR><font color=\"Blue\">◄</font> آستین . <BR><font color=\"Blue\">◄</font> دهان ظروف و اوانی . (برهان ). <BR><font color=\"Blue\">◄</font> اَستر یا آستر. (فرهنگ محمد هندوشاه از شعوری ).<br /></font></div>'),
(1407, 'آستین', '<span class=\"hlight\">آستین .</span> (اِ)قسمتی از جامه که دست را پوشد از بن دوش تا بند دست . کُم ّ. (السامی فی الاسامی ). آستن . آستی <span class=\"hlight\">:</span> <br />که آن شاه و لشکر بدین سو گذشت <br />که از باد کژآستین تر نگشت .<br /> <font color=\"Red\">فردوسی .</font><br />شد از کار ایشان دلش پر ز بیم <br />بپوشید رخ به آستین گلیم .<br /> <font color=\"Red\">فردوسی .</font><br />جهان سربه سر گفتی آهرمن است <br />به دامن بر از آستین دشمن است .<br /> <font color=\"Red\">فردوسی .</font><br />برهنه سر آن دخت افراسیاب <br />بر رستم آمد دو دیده پرآب <br />همی به آستین خون مژگان برُفت <br />بر او آفرین کرد و پرسید و گفت .<br /> <font color=\"Red\">فردوسی .</font><br />برآمد بَرِ کردیه پر ز درد<br />فراوان ز بهرام تیمار خورد<br />همان دردبندوی با او بگفت <br />همی به آستین خون ز مژگان برُفت .<br /> <font color=\"Red\">فردوسی .</font><br />چون آستین رنگرزان زآفت زمان <br />برگ رزان بشاخ بر از چند رنگ شد.<br /> <font color=\"Red\">لامعی .</font><br />به آستین خود اندر نهفته دارد زهر<br />اگرچه پیش تو در دستها شکر دارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />مر مرا شکّر چسان وعده کنی <br />گرْت سنگ است ای پسر در آستین ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />مکن دست پیشش اگر عهد گیرد<br />ازیرا که در آستین مار دارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />آستین گر ز هیچ خواهی پر<br />از صدف مشک جو، ز آهو دُر.<br /> <font color=\"Red\">سنائی .</font><br />آستین پیرهن بنمود زن <br />بس درشت و پروسخ بد پیرهن .<br /> <font color=\"Red\">مولوی .</font><br />در آستین جان تو صد نامه مُدْرَج است <br />وآن را فدای طرّه ٔ یاری نمیکنی .<br /> <font color=\"Red\">حافظ.</font><br />در روز محنتم سر دستی گرفته است <br />چون بهله آنکه در همه عمر آستین نداشت .<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> آنقدر چیز که در آستین گنجد <span class=\"hlight\">:</span> <br />قلم است این به دست سعدی در<br />یا هزار آستین درّ دری ؟<br /><font color=\"Red\">سعدی .</font><br />ترسم کز این چمن نبری آستین گل <br />کز گلبنش تحمل خاری نمیکنی .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> طریقه . راه <span class=\"hlight\">:</span> <br />هرکه بر آستین دین باشد<br />عیسی مریم آستین باشد.<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> دهانه ٔ خیک و مشک و مانند آن <span class=\"hlight\">:</span> <br />بگشای بشادی و فرخی <br />ای جان جهان آستین خی <br />کامروز بشادی فرارسید<br />تاج شعرا خواجه فرخی .<br /> <font color=\"Red\">مظفری (از فرهنگ اسدی ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آستین افشاندن (برفشاندن، فشاندن )</span> ؛ بعلامت مهر یا خلوص دوستی یا عفو یا تحسین، دست و بالتبع آستین را بحرکت آوردن <span class=\"hlight\">:</span><br />هر روز وقت صبح فشاند چو مخلصان <br />بر آستانْش گنبد دوّار آستین <br />چون روی همچو ماه ترا دیدبامداد<br />افشاندبر جمال تو گلزار آستین .<br /> <font color=\"Red\">ابوالفتح هروی .</font><br />زمانیش سودا بسر در بماند<br />پس آنگه بعفو آستین برفشاند<br />بدستان خود بنداز او برگرفت <br />سرش را ببوسید و در بر گرفت .<br /> <font color=\"Red\">سعدی .</font><br />سخن گفت و دامان گوهر فشاند<br />بلطفی که شه آستین برفشاند.<br /> <font color=\"Red\">سعدی .</font><BR>۩ اشارت کردن . اجازت دادن <span class=\"hlight\">:</span> <br />بیغما ملک آستین برفشاند<br />وز آنجا بتعجیل مرکب براند.<br /><font color=\"Red\">سعدی .</font><BR>۩ پشت پا زدن . ترک گفتن . فروگذاشتن . دامن کشیدن از. دامن برافشاندن بر. دست کشیدن از <span class=\"hlight\">:</span> <br />صبح خیزان چو جان برافشانند<br />آستین بر جهان برافشانند.<br /> <font color=\"Red\">سیف اسفرنگ .</font><BR>۩ رقص . پایکوبی <span class=\"hlight\">:</span> <br />تا بصبوح عشق در، محرم قدسیان شوی <br />خیز چو صبح آستین از سر صدق برفشان .<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آستین برزدن (برنوشتن، مالیدن، برچیدن، بالا زدن ) بکاری </span> ؛ مصمم بر آن شدن . مستعد، آماده و مهیای آن گشتن <span class=\"hlight\">:</span> <br />نخستین کسی کو بیفکند کین <br />بخون ریختن برنوشت آستین ...<br /> <font color=\"Red\">فردوسی .</font><br />خفته مرو نیز بیش از این و چو مردان <br />دامن با آستینْت برکش و برزن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ایشان را استماله کرد و لشکر را که برای قتل و غارت آستین برزده و دامن چیده بودند از تعرض ممنوع فرمود و معاف .<br />چو سنبل توسر از برگ یاسمین برزد<br />غمت بریختن خونم آستین برزد.<br /> <font color=\"Red\">ظهیر فاریابی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آستین (آستین ملال ) بر کسی افشاندن </span> ؛ با جنبش دست و آستین کراهت و نفرت نمودن <span class=\"hlight\">:</span> <br />زین آستین فشاندن بر عاشقان چه خیزد<br />رو دامن دلی ده از چنگ غم رهائی .<br /> <font color=\"Red\">لنبانی .</font><br />شکّرفروش مصری حال مگس چه داند<br />این دست شوق برسر وآن آستین فشانان .<br /> <font color=\"Red\">سعدی .</font><br />روا مدار که از دامنت بدارم دست <br />به آستین ملالی که بر من افشانی .<br /> <font color=\"Red\">سعدی .</font><br />تو خواهی آستین افشان و خواهی روی در هم کش <br />مگس جائی نخواهد رفت جز دکان حلوائی .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آستین بر گناه کسی کشیدن </span> ؛ او را عفو کردن . قلم بر جرایم او کشیدن <span class=\"hlight\">:</span> <br />چو دشمن بخواری شود عذرخواه <br />برحمت بکش آستین بر گناه .<br /> <font color=\"Red\">امیرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آستین پوش </span> ؛ خاضع. منقاد <span class=\"hlight\">:</span> بر درگاه تو فلک آستان بوس است و ملک آستین پوش . (راحةالصدور).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آستین گرفتن کسی را</span> ؛ مایه ٔزیان و ضرر شدن <span class=\"hlight\">:</span> <br />یک سلامی نشنوی ای مرد دین <br />که نگیرد آخرت آن آستین .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اشک در آستین داشتن </span> ؛ با هر ناملائمی خرد و ناچیز گریان شدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">تیریز کردن از آستین </span> ؛ دست تطاول کوتاه کردن <span class=\"hlight\">:</span> <br />تیریز کرد دست حوادث ز آستین <br />چون دامن تو دید گریبان روزگار.<br /> <font color=\"Red\">انوری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">در آستین کردن </span> ؛ سود بردن . نفع و فایدت بحاصل کردن <span class=\"hlight\">:</span> <br />هیچ سالی نیست کز دینار سیصد چارصد<br />از پی عرض حشم کمتر کنی در آستین .<br /> <font color=\"Red\">منوچهری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کوته آستین </span> ؛ ضعیف . ناتوان . و توسعاً، صوفی . درویش <span class=\"hlight\">:</span> <br />بزیر دلق ملمع کمندها دارند<br />درازدستی این کوته آستینان بین .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آستین رنگرز</span> ؛ به الوان . رنگارنگ .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مشک در آستین نهفتن </span> ؛ صفتی نیک را پوشیدن خواستن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">بر و آستین هم ز پیراهن است </span> .<br /> <font color=\"Red\">فردوسی .</font><br />یدک منک .<br /><span class=\"hlight\">هزار قبا بدوزد یکی آستین ندارد</span> ؛ به هیچ وعده وفا نکند.<br /></font></div>'),
(1408, 'آستینه', '<span class=\"hlight\">آستینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) بیضه . تخم مرغ . خایه . و آن را اَستینه بفتح همزه و نیز آشتینه و آشینه ضبط کرده اند. <BR><font color=\"Blue\">◄</font> دفتر. (دهّار).<br /></font></div>'),
(1409, 'آسد', '<span class=\"hlight\">آسد.</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (ع اِ) ج ِ اَسَد.<br /></font></div>'),
(1410, 'آسدست', '<span class=\"hlight\">آسدست .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ مرکب ) آسیا که گردد نه به آب و باد و ستور. دستاس . (ربنجنی ).<br /></font></div>'),
(1411, 'آسر', '<span class=\"hlight\">آسر.</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (اِ) کشتزار. مزرعه . غله زار <span class=\"hlight\">:</span> <br />چو ابر کف شه تقاطر نماید<br />زر از آسر طَمْع سائل برآید.<br /> <font color=\"Red\">منجیک .</font><br />و این کلمه را آسه نیز ضبط کرده اند با همین شاهد. <BR><font color=\"Blue\">◄</font> میدان . <BR><font color=\"Blue\">◄</font> بزبان علمی هند، مَردُمخوار.<br /></font></div>'),
(1412, 'آسرون', '<span class=\"hlight\">آسرون .</span> (اِ) (کلمه ٔ یونانی . مخزن الادویه ) سماق . تتری . تِم تِم . تُتُم . سُماک . سماقیل . و آن نیم درختی است با دانه ها چون عدس بخوشه و بر آن دانه ها گَردی تُرش که در طعام کنند.<br /></font></div>'),
(1413, 'آسریس', '<span class=\"hlight\">آسریس .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ <span class=\"hlight\" dir=\"rtl\">/</span> س ُ ]</font></b> (اِ مرکب ) میدان <span class=\"hlight\">:</span> <br />نشانه نهادند در آسریس <br />سیاوش نکرد ایچ با کس مکیس .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> رزمگاه . و اسپریس و اسفریس و اسپرس را نیز به معنی میدان گفته و همین بیت را مثال آورده اند. ظاهراً اسپریس و اسفریس درست باشد و آسریس مصحف است .<br /></font></div>'),
(1414, 'آسطرنومیا', '<span class=\"hlight\">آسطرنومیا.</span> <font color=\"DarkGreen\"><b>[ رُ ن ُ ]</font></b> (یونانی، اِ) (از یونانی آسترُن، ستاره + نومُس، قانون ) اخترشناسی . علم هیأت، یعنی علم شناختن مواضع و حرکات سیارات و ثوابت وآن یکی از اقسام چهارگانه ٔ علوم ریاضی قدیمه است .<br /></font></div>'),
(1415, 'آسغدن', '<span class=\"hlight\">آسغدن .</span> <font color=\"DarkGreen\"><b>[ س َ دَ ]</font></b> (مص ) ساختن . آمادن . سیجیدن . بسیجیدن . <BR><font color=\"Blue\">◄</font> گرد آوردن . فراهم کردن .ریشه ٔ این کلمه اگر ساختن باشد سین بفتح است و اگر سیجیدن باشد سین مکسور است، و تمیز آن برای من میسر نیست . رجوع به آسغده، بسغده، بسغدن و بسغدیدن شود.<br /></font></div>'),
(1416, 'آسغدن', '<span class=\"hlight\">آسغدن .</span> <font color=\"DarkGreen\"><b>[ س َ دَ ]</font></b> (مص )(از: آ، نا + سغدن، سختن یعنی سنجیدن ) ناسختن . ناسنجیدن . رجوع به آسغده، بسغده، بسغدن و بسغدیدن شود.<br /></font></div>'),
(1417, 'آسغدن', '<span class=\"hlight\">آسغدن .</span> <font color=\"DarkGreen\"><b>[ س ُ دَ ]</font></b> (مص ) (از: آ، نا + سغدن، سختن ) نیمه سوختن . رجوع به آسغده و بسغده و بسغدن شود.<br /></font></div>'),
(1418, 'آسغده', '<span class=\"hlight\">آسغده .</span> <font color=\"DarkGreen\"><b>[ س ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) (از: آ، نا + سُغده، سوخته ) نیم سوز <span class=\"hlight\">:</span> <br />ایستاده میان گرمابه <br />همچو آسغده در میان تنور.<br /><font color=\"Red\">معروفی .</font><br /></font></div>'),
(1419, 'آسغده', '<span class=\"hlight\">آسغده .</span> <font color=\"DarkGreen\"><b>[ س َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) (از: آ، نا + سغده، سخته یعنی سنجیده و وزن کرده ) نسنجیده و وزن ناکرده <span class=\"hlight\">:</span> <br />خاطر عاطر تو غارت کرد<br />گنج آسغده ٔنهان قلم .<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(1420, 'آسغده', '<span class=\"hlight\">آسغده .</span> <font color=\"DarkGreen\"><b>[ س َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) ساخته . آماده . سیجیده . بسیجیده <span class=\"hlight\">:</span> <br />همی بایدْت رفت و راه دور است <br />بسغده دار یکسر شغلها را.<br /> <font color=\"Red\">رودکی .</font><br />نشاید درون نابسغده شدن <br />نباید که نَتْوانْش بازآمدن .<br /> <font color=\"Red\">ابوشکور.</font><br />که من مقدمه ٔ خویش را فرستادم <br />بدانکه آمدنم را بسغده باشد کار.<br /> <font color=\"Red\">عنصری .</font><br />چو آمد سوی کاخ فغفور چین <br />ابا این بسغده دلیران کین .<br /> <font color=\"Red\">اسدی .</font><br />جائی که جنگ باشد پذرفته ایم صلح <br />وآنجا که صلح باشد آسغده ایم جنگ .<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> گردآمده . فراهم شده <span class=\"hlight\">:</span> <br />تن و جان چو هر دو فرودآمدند<br />بیک جای هر دو بسغده شدند.<br /><font color=\"Red\">ابوشکور.</font><br /></font></div>'),
(1421, 'آسفته', '<span class=\"hlight\">آسفته .</span> <font color=\"DarkGreen\"><b>[ س ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف ) نیم سوز. نیم سوخته . و ظاهراً این کلمه تصحیف آسغده است .<br /></font></div>'),
(1422, 'آسفدلس', '<span class=\"hlight\">آسفدلس .</span> <font color=\"DarkGreen\"><b>[ ف ُ دِ ل ُ ]</font></b> (یونانی، اِ) و اسقولوس فرهنگهای فارسی و عربی مصحف این کلمه است، و این بته ای است با گلهای زیبا که زینت را در بوستانها نشانند و از ریشه ٔ آن سریش کنند. و اسراش، خنثی، سرش، برواق مرادف آن است .<br /></font></div>'),
(1423, 'آسمار', '<span class=\"hlight\">آسمار.</span> (اِ مرکب ) مرسین . آس . درخت مورْد. عَمار. رند.<br /></font></div>'),
(1424, 'آسمان', '<span class=\"hlight\">آسمان .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ) چرخ . سماء. سما. فلک . اثیر. ام النجوم . سپهر. گنبد. گردون . گرزمان . خضراء. خضرا. میناء. عجوز. جرباء. رقیع. ضاحیه . جربةالنجوم . و آن بعقیده ٔ قدماء هفت باشد. مقابل زمین <span class=\"hlight\">:</span> <br />اخترانند آسمانْشان جایگاه <br />هفت تابنده دوان در دو و داه .<br /> <font color=\"Red\">رودکی .</font><br />همه بازبسته بدین آسمان <br />که بر برده بینی بسان کیان .<br /> <font color=\"Red\">ابوشکور.</font><br />سوی آسمان کردش آن مرد روی <br />بگفت ای خدا این تن من بشوی <br />از این اَزْغها پاک کن مر مرا<br />همه آفرین زآفرینش ترا.<br /> <font color=\"Red\">ابوشکور.</font><br />وآن شب تیره کآن ستاره برفت <br />وآمد از آسمان بگوش تراک .<br /> <font color=\"Red\">خسروی .</font><br />ستاره شناسان برِ او شدند<br />همی زآسمان داستانها زدند.<br /> <font color=\"Red\">فردوسی .</font><br />ز سُم ّ ستوران در آن پهن دشت <br />زمین شد شش و آسمان گشت هشت .<br /> <font color=\"Red\">فردوسی .</font><br />درختش ز یاقوت و آبش گلاب <br />زمینش سپهر، آسمان آفتاب .<br /> <font color=\"Red\">فردوسی .</font><br />اگر یاد گیری چنین بیگمان <br />گشاده ست بر تو در آسمان .<br /> <font color=\"Red\">فردوسی .</font><br />چگونه رسد نوک تیر خدنگ <br />بر این آسمان برشده کوه و سنگ .<br /> <font color=\"Red\">فردوسی .</font><br />کسی را که رستم بود هم نبرد<br />سرش زآسمان اندرآرد بگرد.<br /> <font color=\"Red\">فردوسی .</font><br />سپهبد سوی آسمان کرد روی <br />چنین گفت کای داور راستگوی .<br /> <font color=\"Red\">فردوسی .</font><br />همی جست بر چاره جستن رهی <br />سوی آسمان کرد روی آنگهی .<br /> <font color=\"Red\">فردوسی .</font><br />گرفتی زمین وآنچه بد کام تو<br />شود آسمان نیز در دام تو.<br /> <font color=\"Red\">فردوسی .</font><br />و پارسیان او را آسمان نام کردندیعنی ماننده ٔ آس از جهت حرکت او که گرد است . (التفهیم ).<br />سخاوت تو ندارددر این جهان دریا<br />سیاست تو ندارد بر آسمان بهرام .<br /> <font color=\"Red\">عنصری .</font><br />اسب تاختن گرفتم چنانکه ندانستم که بر زمینم یا در آسمان . (تاریخ بیهقی ).<br />ز من بگسل بفضل این آشنائی <br />نه بر من پاسبان کرد آسمانت .<br /> <font color=\"Red\">ناصرخسرو.</font><br />همی دانم که این جور است لیکن <br />ندانم زآسمان یا زآسمانگر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />بگشای درِ آسمان به نیکی <br />نیکیت کلید در آسمان است (کذا).<br /> <font color=\"Red\">ناصرخسرو.</font><br />بر آسمانْت خواند خداوند آسمان <br />بر آسمان چگونه توانی شد از زمی ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />آسیاآساست ناساید دمی <br />آسمان زآن است نام او همی .<br /> <font color=\"Red\">عطار.</font><br />آنکه میافراخت سر چون خیمه بر گردون به ری <br />شد اسیر خواری و مستوجب چندین عذاب <br />کرد رو بر آسمان کای آسمان تدبیر چیست <br />آسمان گفتش ترکت الرأی بالری در جواب .<br /> <font color=\"Red\">سلمان ساوجی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسمان برین </span> ؛ فلک اعلی . فلک الافلاک . آسمان نهم . فلک اطلس .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسمانها</span> ؛ ج ِ آسمان . سماوات . افلاک . اضاحی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">هفت آسمان </span> ؛ سم̍وات سبع.<br /> <BR><font color=\"Blue\">◄</font> مدار. فلک . فلک دائر. چرخ <span class=\"hlight\">:</span> <br />نخستین آنچه پیدا شد مَلَک بود<br />وز آن پس جوهر گردان فلک بود<br />وز ایشان آمد این اجرام روشن <br />بسان گل میان سبز گلشن <br />... اگر بی اخترستی چرخ گردان <br />نگشتی مختلف اوقات کیهان <br />نبودی این عللهای زمانی <br />کز او آید نباتی زندگانی <br />چو این مایه نبودی رُستنی را<br />نبودی جانور روی زمی را<br />وگر بی آسمان بودی ستاره <br />جهان پرنور بودی هامواره .<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> سقف . آسمانه . آسمانخانه . چُخت . چُخد <span class=\"hlight\">:</span> <br />خرامان همی رفت بهرام گور<br />یکی خانه دید آسمانش بلور.<br /> <font color=\"Red\">فردوسی .</font><br />و آلات زرین داد تا بر آسمان بیت المقدس بیاویزند. (مجمل التواریخ ).<br /> <BR><font color=\"Blue\">◄</font> بالا. جانب علو <span class=\"hlight\">:</span> <br />گر خدو را بر آسمان فکنم <br />بی گمانم که بر چکاد آید.<br /> <font color=\"Red\">طاهر فضل .</font><br />وز دژم روی ابر پنداری <br />کآسمان آسمانه ای است خدنگ .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِخ ) خدا <span class=\"hlight\">:</span> <br />ملک زآن داده ست ما را کن فکان <br />تا ننالد خلق سوی آسمان .<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> (اِ) آسیا <span class=\"hlight\">:</span> <br />دل منه بر عشوه های آسمان زیرا که هست <br />بی سر و بن کارهای آسمان چون آسمان .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> فضا. هوا <span class=\"hlight\">:</span> <br />نپرّید بر آسمانش عقاب <br />از آن بهره ای شخ ّ و بهری سراب .<br /> <font color=\"Red\">فردوسی .</font><br />چو جادو بکشت آسمان تیره گشت <br />بر آنسان که چشم اندرو خیره گشت .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسمان وفا</span> ؛ تعبیری مثلی به معنی مَثَل اعلا و امام و صنم عقلی وفا <span class=\"hlight\">:</span> <br />ببزم اندرون آسمان وفاست <br />برزم اندرون تیزچنگ اژدها است .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به آسمان شدن </span> ؛ مردن . درگذشتن <span class=\"hlight\">:</span> پس از این بوسعید صراف کدخدای غازی به آسمان شد. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دست بر آسمان برداشتن </span> ؛ دعا کردن با افراختن دو دست <span class=\"hlight\">:</span> <br />اوحدی را چو زور و زر کم بود<br />دست زاری بر آسمان برداشت .<br /> <font color=\"Red\">اوحدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آسمان به زمین نیامدن </span> ؛ کمی و بیشی سخت در امر پیدا نشدن .<br /> <span class=\"hlight\">آسمان و ریسمان </span> ؛ من سخن از آسمان می گویم او از ریسمان .<br />... <span class=\"hlight\">از ماست بر ما بدِ آسمان </span> .<br /> <font color=\"Red\">فردوسی .</font><br />مصائب وبلیات که بر ما آید نتیجه ٔ اعمال خود ماست .<br /> <span class=\"hlight\">به هر کجا که روی آسمان همین رنگ است </span> ؛ با تغییر شغل یا جای یا مخدوم امید بهتری نیست .<br /> <span class=\"hlight\">در هفت آسمان یک ستاره نداشتن </span> ؛ سخت فقیر بودن .<br /> <span class=\"hlight\">قطره ٔ آبی نخورد ماکیان </span> <br />تا نکند روی سوی آسمان .<br /> <font color=\"Red\">امیرخسرو.</font><br />آدمی را شکر نعما و آلاء خدای سبحانه و هر منعم دیگر وظیفه است .<br /> <span class=\"hlight\">کلاه به آسمان انداختن </span> ؛ سخت شادان و راضی بودن .<br /> <span class=\"hlight\">مرغ که آبکی خورَد سر سوی آسمان کند</span> .<br /> <font color=\"Red\">خاقانی .</font><br />رجوع به مَثَل «قطره ٔ آبی ...» شود.<br /><span class=\"hlight\">من سخن از آسمان میگویم او از ریسمان </span> ؛ میان گفتار من و او هیچ تناسبی نیست .<br /></font></div>'),
(1425, 'آسمان', '<span class=\"hlight\">آسمان .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b>(اِ) نام روز بیست وهفتم یا بیست وپنجم و بعضی بیست وششم گفته اند از هر ماه فارسی . و در این روز نیک است بسفر دور شدن و نشاید هیچ کار دیگر کردن <span class=\"hlight\">:</span> <br />مه بهمن و آسمان روز بود<br />که فالم بدین نامه پیروز بود.<br /> <font color=\"Red\">فردوسی .</font><br />آسمان روز ای چو ماه آسمان <br />باده نوش و دار دل را شادمان .<br /> <font color=\"Red\">مسعودسعد.</font><br />و این بیت مسعود مثال برای روز <span class=\"hlight\" dir=\"rtl\">٢٧</span> است و بس . <BR><font color=\"Blue\">◄</font> در تداول عوام، صحو. هوای بی ابر. <BR><font color=\"Blue\">◄</font> (اِخ ) نام فرشته ٔ موکل تدبیر امور و مصالح آسمان روز <span class=\"hlight\">:</span> <br />همه ساله ز اشتادو از آسمان <br />تن و جانْت با شادی و کامتان (کذا).<br /> <font color=\"Red\">فردوسی (از جهانگیری ).</font><br /><BR><font color=\"Blue\">◄</font> نام فرشته ٔ موکل بر ممات یعنی عزرائیل . (برهان ).<br /></font></div>'),
(1426, 'آسمان', '<span class=\"hlight\">آسمان .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِخ ) نام کوهی نزدیک بندر نخیلو بجنوب ایران .<br /></font></div>'),
(1427, 'آسمان خراش', '<span class=\"hlight\">آسمان خراش .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ خ َ ]</font></b> (نف مرکب ) سخت رفیع. بسیار بلند.<br /></font></div>'),
(1428, 'آسمان دره', '<span class=\"hlight\">آسمان دره .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ دَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ <span class=\"hlight\" dir=\"rtl\">/</span> دَرْ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) کاهکشان . کهکشان . مجرّه . اُم ُّالسماء. راه مکه .راه حاجیان . شرج . شرج السماء. (السامی ) <span class=\"hlight\">:</span> <br />بکوچه ای که رَوی با کف گهرافشان <br />چو آسمان دره سازی ز بس گهرباری .<br /> <font color=\"Red\">منجیک (از جهانگیری ).</font><br />سمند از آسمان داده نشانش <br />بسان آسمان درّه کمانش .<br /><font color=\"Red\">ثنائی .</font><br /></font></div>'),
(1429, 'آسمان رند', '<span class=\"hlight\">آسمان رند.</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ رَ ]</font></b> (نف مرکب ) آسمان خراش .<br /></font></div>'),
(1430, 'آسمان روز', '<span class=\"hlight\">آسمان روز.</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ مرکب ) رجوع به آسمان (مَدخل ِ دوم ) شود.<br /></font></div>'),
(1431, 'آسمان ساو', '<span class=\"hlight\">آسمان ساو.</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (نف مرکب ) آسمان سای . آسمان خراش . آسمان رَند.<br /></font></div>'),
(1432, 'آسمان غرغره', '<span class=\"hlight\">آسمان غرغره .</span> <font color=\"DarkGreen\"><b>[ غ ُ غ ُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) آسمان غُرّش . آسمان غُرُنْبه . آسمان غُرّه . تندر. رعد. سختو. بختو. کنور.<br /></font></div>'),
(1433, 'آسمان فرسا', '<span class=\"hlight\">آسمان فرسا.</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ف َ ]</font></b> (نف مرکب ) آسمان فرسای . سخت بلند. بسیار رفیع.<br /></font></div>'),
(1434, 'آسمان نورد', '<span class=\"hlight\">آسمان نورد.</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ مان ْ، ن َ وَ ]</font></b> (نف مرکب ) هواپیما. هوانورد.<br /></font></div>'),
(1435, 'آسمان نوردی', '<span class=\"hlight\">آسمان نوردی .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ مان ْ، ن َ وَ ]</font></b> (حامص مرکب ) هواپیمائی . هوانوردی .<br /></font></div>'),
(1436, 'آسمان کته', '<span class=\"hlight\">آسمان کته .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ک َ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (اِ مرکب )قسمی حشره ٔ درشت پرنده که بیشتر در باغها باشد و پرهای او چون پرهای زنبور طلائی و امثال آن دو روی پوش سخت دارد و خود او سه یا چهار چندِ زنبور طلائی است .<br /></font></div>'),
(1437, 'آسمانجون', '<span class=\"hlight\">آسمانجون .</span> (معرب، ص مرکب ) معرب آسمانگون .<br /></font></div>'),
(1438, 'آسمانجونی', '<span class=\"hlight\">آسمانجونی .</span> <font color=\"DarkGreen\"><b>[ نی ی ]</font></b> (معرب، ص نسبی ) معرب آسمانگون یا آسمانگونه یا آسمانگونی . آبی . لاجوردی . کبود. سوسنی . <BR><font color=\"Blue\">◄</font> یاقوت کبود.<br /></font></div>'),
(1439, 'آسمانخانه', '<span class=\"hlight\">آسمانخانه .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ خا ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) سقف . آسمانه . سَمْک . عرش . آشکوب . اَشکوب .<br /></font></div>'),
(1440, 'آسمانه', '<span class=\"hlight\">آسمانه .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) سقف .سَمْک . عرش . آشکوب . اَشکوب . آسمانخانه <span class=\"hlight\">:</span> <br />تا همی آسمان توانی دید<br />آسمان بین و آسمانه مبین .<br /> <font color=\"Red\">عماره .</font><br />وز دژم روی ابر پنداری <br />کآسمان آسمانه ای است خدنگ .<br /> <font color=\"Red\">فرخی .</font><br />همی پیچید سر را بر بهانه <br />گهی دیدی زمین گه آسمانه .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />در و دیوار و بوم و آسمانه <br />نگاریده بنقش چینیانه .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />کنون لاجرم چون سخن گفت بایدْت <br />بماند ترا چشم بر آسمانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بین ای مه آسمان و مبین آسمانه را<br />وآهنگ باغها کن بگذار خانه را.<br /> <font color=\"Red\">مسعودسعد.</font><br />و قولی دیگر آن است که <font color=\"DarkGreen\"><b>[ بناء ]</font></b> آسمانه ٔ خانه باشد که مبنی نباشد، چون آسمانه ٔ خیمه و خباء عرب . (تفسیر ابوالفتوح رازی ).<br />از آسمانه ٔ ایوان کسری اندر ملک <br />ترا رفیعتر است آستانه ودرگاه .<br /> <font color=\"Red\">انوری .</font><br />ز جاه تو نه عجب کاختران کرانه کنند<br />بر آسمان ز موازات آسمانه ٔ تو.<br /> <font color=\"Red\">انوری .</font><br />شرار آتش عزمش ز فرط استعداد<br />بر آسمانه ٔ گردون نشست و اختر شد.<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> آسمان <span class=\"hlight\">:</span> <br />ز تنگنای زمینم هزار آسیب است <br />برای عیش فراخ آسمانه میجویم .<br /><font color=\"Red\">کمال اسماعیل .</font><br /></font></div>'),
(1441, 'آسمانگر', '<span class=\"hlight\">آسمانگر.</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ گ َ ]</font></b> (ص مرکب ) صانع آسمان . خالق سماء <span class=\"hlight\">:</span> <br />همی دانم که جور است این ولیکن <br />ندانم زآسمان یا زآسمانگر.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(1442, 'آسمانگون', '<span class=\"hlight\">آسمانگون .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (ص مرکب ) برنگ آسمان .لاجوردی . کبود <span class=\"hlight\">:</span> پیلغوش، گلیست چون سوسن آزاد، آسمانگون و در کنارش رَخنگکی . (فرهنگ اسدی، خطی ). و پیراهن قباد آسمانگون بود و سپیدی آمیخته . (مجمل التواریخ ). پیراهن وشی داشت سرخ و شلوار آسمانگون و تاج سرخ . (مجمل التواریخ ). <BR><font color=\"Blue\">◄</font> چون آسمان .<br /></font></div>'),
(1443, 'آسمانگونه', '<span class=\"hlight\">آسمانگونه .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ گو ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) روباه کبود . سبحونه .<br /></font></div>'),
(1444, 'آسمانگونه', '<span class=\"hlight\">آسمانگونه .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ گو ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب ) برنگ آسمان . آبی . لاجوردی . کبود. <BR><font color=\"Blue\">◄</font> چون آسمان .<br /></font></div>'),
(1445, 'آسمانگونی', '<span class=\"hlight\">آسمانگونی .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b>(حامص مرکب ) برنگ آسمان بودن . چون آسمان بودن . <BR><font color=\"Blue\">◄</font> (ص نسبی ) برنگ آسمان . آسمانجونی . لاجوردی .<br /></font></div>'),
(1446, 'آسمانی', '<span class=\"hlight\">آسمانی .</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (ص نسبی ) سماوی . فلکی . سپهری . چرخی . گرزمانی . گردونی . <BR><font color=\"Blue\">◄</font> نجومی . احکامی . احکام نجومی <span class=\"hlight\">:</span> <br />ولیکن اتفاق آسمانی <br />کند تدبیرهای مرد باطل .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> عِلوی : اجرام آسمانی . <BR><font color=\"Blue\">◄</font> آسمانی، آبی آسمانی ؛ رنگ آبی روشن . <BR><font color=\"Blue\">◄</font> نوعی از آتش بازی . <BR><font color=\"Blue\">◄</font> ربانی . الهی . خدائی . لاهوتی . غیبی . طبیعی . قدرتی (باصطلاح عوام ) <span class=\"hlight\">:</span> <br />وگر آسمانی جز این است راز<br />چه باید کشیدن سخنها دراز.<br /> <font color=\"Red\">فردوسی .</font><br />همان نیز چیزی که کانی بود<br />کجا رستنش آسمانی بود.<br /> <font color=\"Red\">فردوسی .</font><br />شما را همه شادمانی بود<br />مرا اختر آسمانی بود.<br /> <font color=\"Red\">فردوسی .</font><br />مگر کآسمانی دگرگونه کار<br />فراز آید از گردش روزگار.<br /> <font color=\"Red\">فردوسی .</font><br />مگر آسمانی سخن دیگر است <br />که چرخ روان از گمان برتر است .<br /> <font color=\"Red\">فردوسی .</font><br />اگر آسمانی چنین است رای <br />کسی را به راز فلک نیست پای .<br /> <font color=\"Red\">فردوسی .</font><br />و هرکه از فیض آسمانی و عقل غریزی بهره مند شد... آرزوهای دنیا بیابد ودر آخرت نیکبخت گردد. (کلیله و دمنه ). و افعال و اقوال او را بتأیید آسمانی بیاراست . (کلیله و دمنه ). کسب از جائی که همت بتوفیق آسمانی آراسته باشد آسان دست دهد. (کلیله و دمنه ). و بر خردمند واجب است که بقضاهای آسمانی رضا دهد. (کلیله و دمنه ).<br />منگر ای مظلوم سوی آسمان <br />کآسمانی شاه داری درزمان .<br /> <font color=\"Red\">مولوی .</font><br />بخت و دولت بکاردانی نیست <br />جز بتأیید آسمانی نیست .<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> به وحی . به تنزیل : کتب آسمانی . احکام آسمانی .<br /></font></div>'),
(1447, 'آسمانی تیر', '<span class=\"hlight\">آسمانی تیر.</span> <font color=\"DarkGreen\"><b>[ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ مرکب ) شهاب .<br /></font></div>'),
(1448, 'آسمند', '<span class=\"hlight\">آسمند.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِ) دروغی که بقصد فریب گویند. <BR><font color=\"Blue\">◄</font> (ص ) حیران . سرگشته . و بدین معنی شاید مصحف آسیمه باشد.<br /></font></div>'),
(1449, 'آسموسا', '<span class=\"hlight\">آسموسا.</span> (یونانی، اِ) نوعی از مر و گویند گزر برّی .<br /></font></div>'),
(1450, 'آسموغ', '<span class=\"hlight\">آسموغ .</span> (اِخ ) نام دیوی از تابعان آهرمن که سخن چینی و دروغ گفتن میان دو کس و جنگ انداختن دو تن بدو متعلق است . (جهانگیری ). آشموغ <span class=\"hlight\">:</span> <br />گفته اش جملگی دروغ بود<br />او سخن چین چو آسموغ بود.<br /> <font color=\"Red\">طیان .</font><br />چنین قصه ها خود نباشد دروغ <br />نماند بافسانه ٔ آسموغ .<br /><font color=\"Red\">؟(از کتاب موسوم بخرم بهشت، از انجمن آرا).</font><br /></font></div>'),
(1451, 'آسن', '<span class=\"hlight\">آسن .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (ع ص ) طعم بگشته . (مهذب الاسماء). طعم بگردانیده . بگردیده . مزه و بوی گردانیده . طعم بگردیده . گشته . گندیده (آب ). آجن .<br /></font></div>'),
(1452, 'آسنستان', '<span class=\"hlight\">آسنستان .</span> <font color=\"DarkGreen\"><b>[ س ِ ن ِ ]</font></b> (اِخ ) نام پدرزن وامق که سرانجام وامق او را بکشت <span class=\"hlight\">:</span> <br />بفرمود تا آسنستان پگاه <br />بیامد به نزدیک رخشنده ماه .<br /> <font color=\"Red\">عنصری .</font><br /> <br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1453, 'آسه', '<span class=\"hlight\">آسه .</span> <font color=\"DarkGreen\"><b>[ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ) زردی و پژمردگی که بر روی آدمی یا بر گیاه افتد: صفارة؛ آسه ٔ غَله . المصفور؛ گرسنه ٔ آسه زده . (مهذب الاسماء). شاید در غله مرادف زنگ و زردی باشد. <BR><font color=\"Blue\">◄</font> اصل السوس . ریشه ٔ شیرین بیان . <BR><font color=\"Blue\">◄</font> قسمی از فیلزهره و دیوخار که بلاطینی آن را لیسیوم بارباروم گویند.<br /></font></div>'),
(1454, 'آسه', '<span class=\"hlight\">آسه .</span> <font color=\"DarkGreen\"><b>[ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ) زمین که برای کشت آماده کرده باشند. آبَسته <span class=\"hlight\">:</span> <br />چو ابر کف شه تقاطر نماید<br />زر از آسه ٔ طَمْع سائل بروید.<br /> <font color=\"Red\">منجیک .</font><br />و این کلمه را آسر نیز ضبط کرده اند با همین شاهد، و ظاهراًآسه صحیح است . <BR><font color=\"Blue\">◄</font> آس . آسیا. رحی .<br /></font></div>'),
(1455, 'آسه زده', '<span class=\"hlight\">آسه زده .</span> <font color=\"DarkGreen\"><b>[ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) رجوع به آسه (مَدخل ِ اوّل ) شود.<br /></font></div>'),
(1456, 'آسو', '<span class=\"hlight\">آسو.</span> (اِ) راسو. <BR><font color=\"Blue\">◄</font> کفش و نعلین . <BR><font color=\"Blue\">◄</font> سوی و جانب . (بادّعای بعض فرهنگهای نو. و این کلمه در برهان و جهانگیری نیست ).<br /></font></div>'),
(1457, 'آسو', '<span class=\"hlight\">آسو.</span> (اِ) نام شرابی مسکر که بهند کنند از قند سیاه و پوست مغیلان . (مخزن الادویه ).<br /></font></div>'),
(1458, 'آسو', '<span class=\"hlight\">آسو.</span> (اِخ ) نام محلی در راه لار به لنگه میان کوخرد و کررضائی .<br /></font></div>'),
(1459, 'آسودن', '<span class=\"hlight\">آسودن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آرمیدن . مستریح شدن . راحت . استراحت یافتن . استجمام . استرواح . اَون <span class=\"hlight\">:</span> <br />نخفت و نیاسود تا بامداد<br />از اندیشه بر دل نیامدْش یاد.<br /> <font color=\"Red\">فردوسی .</font><br />بخواب و به آسایش آمد شتاب <br />وزآن پس برآسود بر جای خواب .<br /><font color=\"Red\">فردوسی .</font><br />زیر کبود چرخ بی آسایش <br />هرگز گمان مبر که بیاسائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> آرام گرفتن . سکون <span class=\"hlight\">:</span> <br />برآرای کار و میاسای هیچ <br />که من رزم را کردخواهم بسیچ .<br /> <font color=\"Red\">فردوسی .</font><br />نیاساید وبرنگردد ز جنگ <br />ترا چاره در جنگ جستن درنگ .<br /> <font color=\"Red\">فردوسی .</font><br />دلم ز انده بی حد همی نیاساید<br />تنم ز رنج فراوان همی بفرساید.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> پرداختن <span class=\"hlight\">:</span> <br />نعوذ باﷲ اگر خلق غیب دان بودی <br />کسی بحال خود از دست کس نیاسودی .<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /> <BR><font color=\"Blue\">◄</font> خوابیدن . خفتن . آرمیدن <span class=\"hlight\">:</span> <br />بگفت و بخفت و برآسود دیر<br />گو نامبردار گرد دلیر.<br /> <font color=\"Red\">فردوسی .</font><br />چو آباد جائی بچنگ آمدش <br />برآسود و چندی درنگ آمدش .<br /> <font color=\"Red\">فردوسی .</font><br />برادر و پدر و مادرت همه رفتند<br />تو چند خواهی اندر سفر چنین آسود؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />حامد از آن آب بخورد وبیاسود. (مجمل التواریخ ).<br /> <BR><font color=\"Blue\">◄</font> درنگ کردن . توقف <span class=\"hlight\">:</span> <br />جان بکف درنه و دلیرآسا<br />قصد این راه کن در او ماسا.<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> ماندگی گرفتن . رنج راه و کار و سخن و فکر و هر امر دیگر رفع کردن . جمام . بی کار و عملی متعب زمان گذرانیدن <span class=\"hlight\">:</span> <br />بهار و تموز و زمستان و تیر<br />نیاسود هرگزیل شیرگیر.<br /> <font color=\"Red\">فردوسی .</font><br />بمصر اندرون بود یک سال شاه <br />بدان تا بیاسود شاه و سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />کئی وار بنشست بر تختگاه <br />بیاسود یکچند خود با سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />بیاساید امروز و فردا بگاه <br />همی راند اندر میان سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />ببود و برآسود و زآنجابرفت <br />به نزدیک خاقان خرامید تفت .<br /> <font color=\"Red\">فردوسی .</font><br />تو فردا برآسای تا من سپاه <br />بیارم از ایرانیان کینه خواه .<br /> <font color=\"Red\">فردوسی .</font><br />چون بیاسود مأمون خلیفه در شب بدیدار وی آمد. (تاریخ بیهقی ). سه روز بیاسود پس بدرگاه آمد. (تاریخ بیهقی ). رفتن گرفت <font color=\"DarkGreen\"><b>[ امیر محمدبن محمود غزنوی ]</font></b> سخت بجهد، و چند پایه که برفتی زمانی نیک بنشستی و بیاسودی . (تاریخ بیهقی ). فرمود قاصدان را فرود آوردند و صلتها فرمود، تا بیاسودند. (تاریخ بیهقی ).<br />بیاسود و از رنجگی دور شد<br />وز آنجا بشهر فُغَنشور شد.<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> بعطالت یا عشرت و سور و سرور گذرانیدن . تن زدن <span class=\"hlight\">:</span><br />بایران هر آنگه که آسود شاه <br />بهر کشوری برندارد سپاه <br />بیاید ز هر جای دشمن بکین <br />پرآشوب گردد سراسر زمین .<br /> <font color=\"Red\">فردوسی .</font><br />بیاسود چندی ز بهر شکار<br />همی گشت در کوه و در مرغزار.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> محظوظ شدن . حظ، نصیب، بهره بردن . مُلتذّ گشتن . لذت، تمتع یافتن <span class=\"hlight\">:</span> <br />در راه عمر خفته نیاساید ای پسر<br />گر بایدت بپرس ز دانای هندوان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نیاساید مشام از طبله ٔ عود<br />بر آتش نه که چون عنبر ببوید.<br /> <font color=\"Red\">سعدی .</font><br />چه گنجها که نهادند و دیگری برداشت <br />چه رنجها که کشیدند ودیگری آسود.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسودن، در خاک آسودن </span> ؛ بکنایه، مردن <span class=\"hlight\">:</span> <br />مرا نیز هنگام آسودن است <br />ترا رزم بدخواه پیمودن است .<br /> <font color=\"Red\">فردوسی .</font><br />اکنون که عماد دوله در خاک آسود<br />ازدیده ٔ من خاک شود خون آلود<br />در خاک فتاده چون توانم دیدن <br />آن را که مرا زخاک برداشته بود؟<br /> <font color=\"Red\">عمادی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسودن از</span> ؛ فارغ ماندن . خالی ماندن از. فارغ شدن . معطل ماندن . از دست نهادن . ساکت نشستن . بازایستادن از <span class=\"hlight\">:</span> <br />ببودند روشندل و شادمان <br />ز خنده نیاسود لب یک زمان .<br /> <font color=\"Red\">فردوسی .</font><br />چوجم ّ و فریدون بیاراست گاه <br />ز داد و ز بخشش نیاسود شاه .<br /> <font color=\"Red\">فردوسی .</font><br />نیاسود لشکر زمانی ز کار<br />ز چوگان و تیر و نبید و شکار.<br /> <font color=\"Red\">فردوسی .</font><br />ز خوردن نیاسود یک روز شاه <br />گهی رود و می گاه نخجیرگاه .<br /> <font color=\"Red\">فردوسی .</font><br />ببسته کند راه خون ریختن <br />بیاساید از رنج و آویختن .<br /> <font color=\"Red\">فردوسی .</font><br />زمانی میاسای از آموختن <br />اگر جان همی خواهی افروختن .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت شیرین که دادم نخست <br />بده وآنگهی جان من پیش تست <br />وزآن پس نیاسایم از پاسخت <br />ز فرمان و رای دل فرّخت .<br /> <font color=\"Red\">فردوسی .</font><br />نهادند بر نامه بر مُهر شاه <br />فرستاده را گفت برکش براه <br />میاسا ز رفتن شب و روز هیچ <br />بهر منزلی اسب دیگر بسیچ .<br /> <font color=\"Red\">فردوسی .</font><br />که آن جای گور است و تیر و کمان <br />نیاسایم از تاختن یک زمان .<br /> <font color=\"Red\">فردوسی .</font><br />همی تا رفته ام از مرو گنده <br />نیاسودستم از بازی ّ و خنده .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />چنین یال و بازو و آن زور و برز<br />نشاید که آساید از تیغ و گرز.<br /> <font color=\"Red\">اسدی .</font><br />ای بشبان خفته ظن مبر که بیاسود<br />گر تو بیاسودی این زمانه ز گشتن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از آنکه طبع کریم از کرم نیاساید.<br /> <font color=\"Red\">اثیر اخسیکتی .</font><BR>۩ ترک گفتن آن ؛ دست کشیدن از آن <span class=\"hlight\">:</span> <br />ز خورد و ز بخشش میاسای هیچ <br />همه دانش و داد دادن بسیچ .<br /> <font color=\"Red\">فردوسی .</font><br />بیاساید از بزم و شادی دو ماه <br />که این باشد آئین پس از مرگ شاه .<br /> <font color=\"Red\">فردوسی .</font><br />نیاسود یک تن ز خورد و شکار<br />همان یک سواره همان شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />بایران و توران بود شهریار<br />دو کشور بیاساید از کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />دشمن از کینه کم آمد بکمینگاه مرو<br />لشکر از جنگ بیاسود بیاسای از جنگ .<br /> <font color=\"Red\">فرخی .</font><BR>۩ ماندگی گرفتن <span class=\"hlight\">:</span> <br />چو آسود پرموده از رنج راه <br />به هشتم یکی سور فرمود شاه .<br /> <font color=\"Red\">فردوسی .</font><br />و هیچ نیاسودی ازتعبد و ذکر ایزدی . (مجمل التواریخ ).<br />من ز خدمت دمی نیاسودم <br />گاه و بیگاه در سفر بودم .<br /> <font color=\"Red\">سعدی .</font><BR>۩ بی رنج گشتن از. بی تعب گشتن از <span class=\"hlight\">:</span> <br />به اختر نگه کن که تا من ز جنگ <br />کی آسایم و کشور آرم بچنگ .<br /> <font color=\"Red\">فردوسی .</font><br />شب تیره چون زلف را تاب داد<br />همان تاب او چشم را خواب داد<br />پدید آمد آن پرده ٔ آبنوس <br />برآسود گیتی ز آوای کوس .<br /> <font color=\"Red\">فردوسی .</font><br />زمانی نیاسود از تاختن <br />هم از گردش و تیر انداختن .<br /> <font color=\"Red\">فردوسی .</font><br />بتو شادم ار باشی ایدر دو ماه <br />بیاساید از رنج شاه و سپاه .<br /> <font color=\"Red\">فردوسی .</font><BR>۩ تهی، فارغ، خالی ماندن <span class=\"hlight\">:</span> <br />اگر جنگجوئی همی بیگمان <br />نیاساید از کین دلت یک زمان .<br /> <font color=\"Red\">فردوسی .</font><br />میاسای از کین افراسیاب <br />ز دل دور کن خورد و آرام و خواب .<br /> <font color=\"Red\">فردوسی .</font><br />آمد ماه بزرگوار و گرامی <br />وآسود از تلخ باده زرین جامت .<br /> <font color=\"Red\">مسعودسعد.</font><BR>۩ بازایستادن از <span class=\"hlight\">:</span> <br />بانگ زلّه کرّ خواهد کرد گوش <br />هیچ ناساید زمانی از خروش .<br /> <font color=\"Red\">رودکی .</font><br />تو آن ابری که ناساید شب و روز<br />ز باریدن چنانچون از کمان تیر.<br /> <font color=\"Red\">دقیقی .</font><br />میاسای از آموختن یک زمان <br />ز دانش میفکن دل اندر گمان .<br /> <font color=\"Red\">فردوسی .</font><br />چه گویم از این گنبد تیزگرد<br />که هرگز نیاساید از کارکرد.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت خسرو <font color=\"DarkGreen\"><b>[ پرویز ]</font></b> ز کردار بد<br />چه داری بیا روز گفتار بد<br />چنین داد پاسخ که از کار بد<br />نیاسایم و نیست با من خرد.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسودن از خشم </span> ؛ فرونشستن آن <span class=\"hlight\">:</span> <br />مگر شاه ایران از این خشم و کین <br />بیاساید آرام گردد زمین .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسودن با</span> ؛ مضاجعت با. آرامیدن با. عشرت و صحبت کردن با <span class=\"hlight\">:</span> <br />ساعتی با او ننشست و نیاسود و نخفت ...<br />این چنین سنگدل و بیحق و بیحرمت جفت <br />شاه مسعود مبیناد و میفتاد از راه .<br /> <font color=\"Red\">منوچهری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسودن دل </span> ؛ خوش و مسرور بودن <span class=\"hlight\">:</span> <br />دردا که ز عمر آنچه خوش بود گذشت <br />دوری که دلی در او بیاسود گذشت <br />ایام جوانی که بهاری خوش بود<br />چون خنده ٔبرق و عهد گل زود گذشت .<br /> <font color=\"Red\">سیف اسفرنگ .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسودن دل به </span> ؛ استیناس با. عشرت و صحبت و آرمیدن با <span class=\"hlight\">:</span> <br />بمردان همی دل نیاسایدش <br />بجز بازنان هیچ خوش نایدش .<br /> <font color=\"Red\">اسدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">حسود هرگز نیاسود</span> ؛ مردم رشکناک هماره در رنج و تعب باشد.<br /> <span class=\"hlight\">رنج امروزین آسودن فردائین بود و آسودن امروزین رنج فردائین </span> . (قابوسنامه ).<br />اسم مصدر و مصدر دوم آن آسایش است . آسودم، بیاسای .<br /></font></div>'),
(1460, 'آسوده', '<span class=\"hlight\">آسوده .</span> <font color=\"DarkGreen\"><b>[دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) فارغ . فراغ یافته <span class=\"hlight\">:</span> <br />نباید که آسوده باشد سپاه <br />نه آسوده از رنج تدبیر شاه .<br /> <font color=\"Red\">فردوسی .</font><br />چو از جنگ این لشکر آسوده شد<br />بلشکرگه شاه پرموده شد.<br /> <font color=\"Red\">فردوسی .</font><br />ببد شاه چندی بدان رزمگاه <br />چو آسوده شد شهریار و سپاه ...<br /> <font color=\"Red\">فردوسی .</font><br />هر جا که دلی هست ز غم فرسوده ست <br />کس نیست که از رنج جهان آسوده ست .<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> دور. جدا <span class=\"hlight\">:</span> <br />بتو آسوده بودم از همه غم <br />تو بمردی ّ و من نیاسایم .<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> خوش <span class=\"hlight\">:</span> <br />تن آسوده دارید یکسر ببزم <br />که زود آید اندیشه ٔ روز رزم .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> با خاطری مجموع . مطمئن <span class=\"hlight\">:</span> <br />اگر از خویش برون آمده ای چون مردان <br />باش آسوده که دیگر سفری نیست ترا.<br /> <font color=\"Red\">صائب .</font><br /> <BR><font color=\"Blue\">◄</font> مستریح . بی مشقت . آرام یافته . بی ترس . بی هراس و بیم از بدی و مصائب . جمام <span class=\"hlight\">:</span> وطلیعه ها نامزد کرد و مردم آسوده و من بازگشتم . (تاریخ بیهقی ). تا خلایق روی زمین آسوده و مرفّه پشت بدیوار امن و فراغ آوردند. (کلیله و دمنه ).<br /> <BR><font color=\"Blue\">◄</font> آرمیده . تسکین یافته . مقابل شورانیده <span class=\"hlight\">:</span> <br />چنین گفت شاپور <font color=\"DarkGreen\"><b>[ طائر ]</font></b> بدنام را<br />که از پرده چون دخت بهرام را<br />بیاری ّ و رسوا کنی دوده را<br />بشورانی این کین آسوده را...<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> فارغ البال <span class=\"hlight\">:</span> <br />آسوده زهرچه نیست میباید زیست <br />وآزاده ز هرچه هست می باید بود.<br /> <font color=\"Red\">سلمان ساوجی .</font><br /> <BR><font color=\"Blue\">◄</font> ماندگی گرفته . مقابل مانده <span class=\"hlight\">:</span> <br />بخفتی ّ و آسوده برخاستی <br />ز نو باز جنگی بیاراستی .<br /> <font color=\"Red\">فردوسی .</font><br />یکی اسب آسوده را برنشست <br />رخ از خون دیده شده چون کبست .<br /> <font color=\"Red\">فردوسی .</font><br />برآسود روزی بر آنجایگاه <br />چو آسوده گشت اسب و شاه و سپاه <br />بکشمیهن آمد بهنگام روز...<br /> <font color=\"Red\">فردوسی .</font><br />جهاندار <font color=\"DarkGreen\"><b>[ افراسیاب ]</font></b> چون بخت برگشته دید<br />دلیران توران همه کشته دید<br />بیفکند شمشیر هندی ز دست <br />یکی اسب آسوده را برنشست <br />خود و سرکشان سوی توران شتافت <br />کز ایرانیان کام کینه نیافت .<br /> <font color=\"Red\">فردوسی .</font><br />بدان جایگه شاه ماهی بماند<br />چو آسوده شد باز لشکر براند.<br /> <font color=\"Red\">فردوسی .</font><br />چو آسوده تر گشت شاه و ستور<br />بیاورد لشکر سوی شهرزور.<br /> <font color=\"Red\">فردوسی .</font><br />و هر پیک مانده نامه به پیک آسوده دادی و نامه زودتر بجای مقصود رسیدی .<br /> <BR><font color=\"Blue\">◄</font> بی رنج <span class=\"hlight\">:</span> <br />ز فرمان سرآزاده و ژنده پوش <br />ز آواز بیغاره آسوده گوش .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> بی رنج و عذاب و لوم ِ نفس لوامه . بی اضطراب وجدانی <span class=\"hlight\">:</span> <br />کسی خسبد آسوده در زیر گل <br />که خسبند از او مردم آسوده دل .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> متمتع. مُلتذّ <span class=\"hlight\">:</span> <br />سرش گشت از اندیشه ٔ دل گران <br />بخفت و نه آسوده گشت اندر آن .<br /><font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> از کفک و جوش فرونشسته (باده ) <span class=\"hlight\">:</span> <br />باده ٔ روشن و آسوده و صافی چو گلاب <br />ساقی دلبر و شایسته و شیرین چو شکر.<br /> <font color=\"Red\">فرخی .</font><br />روز و شب در بر تو کودک بالیده چو سرو<br />سال و مه در کف توباده ٔ آسوده چو زنگ .<br /> <font color=\"Red\">فرخی .</font><br /> <br /> <BR><font color=\"Blue\">◄</font> مَدفون . آرام یافته در قبر و خاک <span class=\"hlight\">:</span> قتیبه در ناحیت رباط سرهنگ، در دیهی که آن را کاخ خوانند آسوده است و از ولایتها پیوسته آنجا روند بزیارت . (تاریخ بخارای نرشخی ). <BR><font color=\"Blue\">◄</font> در حال راحت باش <span class=\"hlight\">:</span> <br />نباید که ایمن شوی از کمین <br />سپه باشد آسوده در دشت کین .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">رسیده آسوده باشد</span> . (کشف المحجوب )؛ آنکه بمطلوب و مراد دست یابد آرام گیرد.<br /> <span class=\"hlight\">مسجد گرم و گدا آسوده </span> .<br /><span class=\"hlight\">یک تن آسوده در جهان دیدم </span> <br />آن هم آسوده اش تخلص بود.<br /><font color=\"Red\">؟</font><br /></font></div>'),
(1461, 'آسوده', '<span class=\"hlight\">آسوده .</span> <font color=\"DarkGreen\"><b>[ دَ]</font></b> (اِخ ) ظاهراً تخلص شاعری . رجوع به سطر فوق شود.<br /></font></div>'),
(1462, 'آسوده خاطر', '<span class=\"hlight\">آسوده خاطر.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ طِ ]</font></b> (ص مرکب ) آسوده دل . فارغ البال <span class=\"hlight\">:</span> <br />آسوده خاطرم که تو در خاطر منی <br />گر تاج می فرستی و گر تیغ می زنی .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1463, 'آسوده خاطری', '<span class=\"hlight\">آسوده خاطری .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ طِ ]</font></b> (حامص مرکب ) صفت و چگونگی آسوده خاطر. فراغ ِ بال .<br /></font></div>'),
(1464, 'آسوده دل', '<span class=\"hlight\">آسوده دل .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ دِ ]</font></b> (ص مرکب ) فارغ البال . بی دلواپسی . بی رنج . بی عذاب . غیرمضطرب <span class=\"hlight\">:</span> <br />کسی خسبد آسوده در زیر گل <br />که خسبند از او مردم آسوده دل .<br /><font color=\"Red\">سعدی (بوستان ).</font><br /></font></div>'),
(1465, 'آسوده دلی', '<span class=\"hlight\">آسوده دلی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ دِ ]</font></b> (حامص مرکب ) آسوده خاطری . فراغ بال .<br /></font></div>'),
(1466, 'آسوده کاری', '<span class=\"hlight\">آسوده کاری .</span><font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص مرکب ) عطلت . بیکاری <span class=\"hlight\">:</span> <br />دلم بگرفت از این آسوده کاری <br />که آسایش بود بنیاد خواری .<br /><font color=\"Red\">(ویس و رامین ).</font><br /></font></div>'),
(1467, 'آسودگی', '<span class=\"hlight\">آسودگی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ]</font></b> (حامص ) آرامش . آرامی . نرمی . آهستگی . فراغ بال . جمعیت خاطر. راحت . استراحت . سبات . بی رنجی <span class=\"hlight\">:</span> <br />بباشیم بر آب و چیزی خوریم <br />وزآن پس به آسودگی بگذریم .<br /> <font color=\"Red\">فردوسی .</font><br />خود و ویژگان بر هیونان چست <br />بباید به آسودگی راه جست .<br /> <font color=\"Red\">فردوسی .</font><br />به آسودگی روز بر سر رسید<br />بسی لشکر از هر سوئی دررسید.<br /> <font color=\"Red\">فردوسی .</font><br />از آن پس ز اسبان فرودآمدند<br />زمانی بر آسودگی دم زدند.<br /> <font color=\"Red\">فردوسی .</font><br />به آسودگی باز برخاستند<br />به پیکار و کینه بیاراستند.<br /> <font color=\"Red\">فردوسی .</font><br />ز نیرو و آسودگی اسب و مرد<br />نیندیشد از روزگار نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />آسودگی مجوی که از صدمت اجل <br />کس را نداده اند برات مسلمی .<br /> <font color=\"Red\">ابوالفرج سگزی .</font><br />ای گرفتار وپای بند عیال <br />دگر آسودگی مبند خیال .<br /><font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مگر آسودگی بر ما حرام است </span> ؛ جمله ٔ مبتذله ای است و چرا همیشه در رنج باید بود معنی میدهد. <br />و رجوع به آسایش و آسودن شود.<br /></font></div>'),
(1468, 'آسودگی خاطر', '<span class=\"hlight\">آسودگی خاطر.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ی ِ طِ ]</font></b> (ترکیب اضافی، اِمص مرکب ) فراغ بال . بی اضطرابی . سکون و اطمینان دل .<br /></font></div>'),
(1469, 'آسور', '<span class=\"hlight\">آسور.</span> (اِخ ) نام رب النوع بزرگ آشوریان .<br /></font></div>'),
(1470, 'آسور', '<span class=\"hlight\">آسور.</span> (اِخ ) رجوع به آسوریان و آشور شود.<br /></font></div>'),
(1471, 'آسور بانی پال', '<span class=\"hlight\">آسور بانی پال .</span> (اِخ ) نام پادشاه آسور (<span class=\"hlight\" dir=\"rtl\">٦٦٩</span>-<span class=\"hlight\" dir=\"rtl\">٦٢٦</span> ق .م .)، و او پادشاهی مقتدر و سلحشور بوده و مملکت بابل و ایلام را تسخیر کرده است .<br /></font></div>'),
(1472, 'آسوری', '<span class=\"hlight\">آسوری .</span> (ص نسبی، اِ) رجوع به آسوریان شود.<br /></font></div>'),
(1473, 'آسوریان', '<span class=\"hlight\">آسوریان .</span> (اِخ ) نام قومی از نژاد سامی، ساکن بابل که سپس بسواحل وسطای دجله و جبال مجاور آن هجرت کردند و در آنجا دولتی کوچک به نام آسور بنیاد نهادند. و آسور نام رب النوعی معبود آنان بود. پایتخت این ملک نیز در ابتدا شهری به همین نام بود ولی در دوره های بعد شهر کالاه (در توریة: کالَح ) و پس از آن نینوا را عاصمه ٔ ملک کردند و استقلال آنان میان قرن هیجدهم و پانزدهم ق .م . است . و رفته رفته این دولت بزرگ شد، از طرفی تا مصر و از یک سو تا کویر ایران و ارمنستان انبساط یافت و ماد و پارس دست نشانده ٔ او شدند وایلام را از میان برداشت و پس از قریب ده قرن مردم ماد بر آن دست یافته و منقرض گردید (<span class=\"hlight\" dir=\"rtl\">٦٠٦</span> ق .م .). و در دوره ٔ هخامنشیان آسور یکی از چترپتی های ایران بود.<br /></font></div>'),
(1474, 'آسوریه', '<span class=\"hlight\">آسوریه .</span> <font color=\"DarkGreen\"><b>[ ری ی َ ]</font></b> (اِخ ) رجوع به آسوریان شود.<br /></font></div>'),
(1475, 'آسوز', '<span class=\"hlight\">آسوز.</span> (اِ) بوی تیز بول در زمین و بستر و یا جامه .<br /></font></div>'),
(1476, 'آسپا', '<span class=\"hlight\">آسپا.</span> (اِخ ) رجوع به آسپادانا شود.<br /></font></div>'),
(1477, 'آسپاداس', '<span class=\"hlight\">آسپاداس .</span> (اِخ ) آستیاژ. (کِتِزیاس ). رجوع به آستیاژ شود.<br /></font></div>'),
(1478, 'آسپادانا', '<span class=\"hlight\">آسپادانا.</span> (اِخ ) نام قدیم اصفهان و این شهر در زمان اسکندر شهری کوچک بوده است و آن را آسپا نیز می گفته اند.<br /></font></div>'),
(1479, 'آسپاس', '<span class=\"hlight\">آسپاس .</span> (اِخ ) یا آسپاس سرحد. نام قریه ای در خرّه ٔ اقلید فارس میان علی آباد و چمن اوچون و فاصله ٔ آن تا علی آباد سه فرسنگ ونیم و تا رضاآباد چهار فرسنگ و سه ربع فرسنگ است .<br /></font></div>'),
(1480, 'آسپست', '<span class=\"hlight\">آسپست .</span> <font color=\"DarkGreen\"><b>[ پ ِ ]</font></b> (اِ) اسپست . گیاهی که آن را یونجه گویند و به بهار بستور خورانند. رطبه . فِسفسه . فِصفصه . اِسپرس . جلبان الحیه . سله . و رجوع به اسپست شود.<br /></font></div>'),
(1481, 'آسک', '<span class=\"hlight\">آسک .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) نام شهری از نواحی اهواز نزدیک ارّجان <font color=\"DarkGreen\"><b>[ ارغان ]</font></b> بین ارّجان و رامهرمز، و میان آن و شیراز شصت فرسنگ است .<br /></font></div>'),
(1482, 'آسکده', '<span class=\"hlight\">آسکده .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) جایگاه آسیا. مطحن . (ربنجنی ). آسیاکده . مرحی . سرآسیا. آسیاخانه . آس خانه .<br /></font></div>'),
(1483, 'آسکون', '<span class=\"hlight\">آسکون .</span> (اِخ ) آبسکون . بحر خزر. دریای قزوین . آرقانیا. هیرکانی . دریای مازندران . دریای گیلان، و آن را بغلط قلزم نیز گفته اند <span class=\"hlight\">:</span> <br />باد اندر او وزیده ز پهنای آسکون <br />ابر اندر او گذشته ز بالای قیروان .<br /> <font color=\"Red\">ازرقی .</font><br />میغ از تو بر اسب آسکون تاخت <br />میدان فلک پلنگ وش ساخت .<br /> <font color=\"Red\">خاقانی .</font><br />چه مایه دارد در پیش طبع او دریا<br />چه پایه دارددر نزد آسکون فرغر؟<br /> <font color=\"Red\">قاآنی .</font><br />و ظاهراً بمعانی دیگر آبسکون نیز آید.<br /></font></div>'),
(1484, 'آسگون', '<span class=\"hlight\">آسگون .</span> (ص مرکب ) چون آسیا. چون آس . رحوی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بحر آسگون </span> ؛ مجازاً، آسمان . فلک .<br /></font></div>'),
(1485, 'آسی', '<span class=\"hlight\">آسی .</span> (ع ص ) غَمناک . حَزین . اندوهگین . <BR><font color=\"Blue\">◄</font> پشیمان . <BR><font color=\"Blue\">◄</font> بِجشک . پزشک . طبیب . مُعالج . پزشک ریشها و قرحه ها. جراح . ج، اِساء، اُساة.<br /></font></div>'),
(1486, 'آسی', '<span class=\"hlight\">آسی .</span> (ص نسبی ) منسوب به مملکت آس . از آس . رجوع به آسیان شود.<br /></font></div>'),
(1487, 'آسی', '<span class=\"hlight\">آسی .</span> <font color=\"DarkGreen\"><b>[ سا ]</font></b> (ع ن تف ) غمگین تر. اندوهناکتر.<br /></font></div>'),
(1488, 'آسیا', '<span class=\"hlight\">آسیا.</span> (اِ) دستگاهی خرد کردن و آرد کردن حبوب یا گچ و آهک و مانند آن، یا گرفتن روغن و شیره ٔ نبات و جز آن را. رحی . طاحونه . آس .آسیاو. این کلمه بر همه ٔ انواع از بادی و آبی و دستی و ستوری اطلاق شود <span class=\"hlight\">:</span> و ایشان را <font color=\"DarkGreen\"><b>[ مردم سیستان را ]</font></b> آسیاها است بر باد ساخته . (حدودالعالم ).<br />آس شدم زیر آسیای زمانه <br />نیسته خواهم شدن همی بکرانه .<br /> <font color=\"Red\">کسائی .</font><br />چونکه یکی تاج و بساک ملوک <br />باز یکی کوفته ٔ آسیاست .<br /> <font color=\"Red\">کسائی .</font><br />هم اندر دژش کشتمند و گیا<br />درخت برومند و هم آسیا.<br /> <font color=\"Red\">فردوسی .</font><br />ستوران و پیلان چو تخم گیا<br />شد اندر دم پرّه ٔ آسیا.<br /> <font color=\"Red\">فردوسی .</font><br />چه جای نشست تو بود آسیا<br />پر از گندم و خاک و چندی گیا؟<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت کای شاه خورشیدروی <br />بدین آسیا چون رسیدی بگوی .<br /><font color=\"Red\">فردوسی .</font><br />همی تاخت جوشان چو از ابر برق <br />یکی آسیا دید بر آب زرق <br />فرود آمد از اسب شاه جهان <br />ز بدخواه در آسیا شد نهان .<br /> <font color=\"Red\">فردوسی .</font><br />چنان برخروشیدم از پشت زین <br />که چون آسیا شد بر ایشان زمین .<br /> <font color=\"Red\">فردوسی .</font><br />یکی آسیا دید در پیش ده <br />نشسته پراکنده مردان مه .<br /> <font color=\"Red\">فردوسی .</font><br />یکی کوهش آمد به ره پرگیا<br />بدو اندرون چشمه و آسیا.<br /> <font color=\"Red\">فردوسی .</font><br />که در آسیاماهروی ترا<br />جهاندار و دیهیم جوی ترا<br />بدشنه جگرگاه بشکافتند<br />برهنه به آب اندر انداختند.<br /> <font color=\"Red\">فردوسی .</font><br />آسمان آسیای گردان است <br />آسمان آسمان کند هزمان .<br /> <font color=\"Red\">لبیبی .</font><br />تا دل من آس شد در آسیای عشق او<br />هست پنداری غبار آسیا <font color=\"DarkGreen\"><b>[ بر ]</font></b> سر مرا.<br /> <font color=\"Red\">لبیبی .</font><br />دوستا جای بین و مرد شناس <br />شد نخواهم به آسیای تو آس .<br /> <font color=\"Red\">لبیبی .</font><br />آسیای زودگرد است این فلک <br />زو نشاید بود شاد و نی حزین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />این جای فنائی چه آسیائیست <br />آن دیگر بی شک چو آسیا نیست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بسنگ آسیا ماند بگردش <br />فرود آید همی چون سنگ بر سر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چیست بنگر ز آسیا مر آسیابان را، غله <br />گر نبایستیش غلّه آسیا ناراستی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گرچه موش از آسیا بسیار دارد فایده <br />بیگمان روزی فروکوبد سر موش آسیا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چرخ است خراس آسیارو<br />چه کهنه چه نو در آسیا جو.<br /> <font color=\"Red\">امیرخسرو.</font><br />گفت مرد آن بود که درهمه وقت <br />سنگ زیرین آسیا باشد.<br /> <font color=\"Red\">کمال اسماعیل .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسیا بخون گردانیدن </span>؛ خلقی عظیم را در یک جای بکشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسیا بخون گشتن </span> ؛ قتل و کشتاری سخت و عظیم روی دادن <span class=\"hlight\">:</span> <br />از ایشان <font color=\"DarkGreen\"><b>[ از ترکان ]</font></b> بکشتند چندان سپاه <br />کزآن تنگ شد جای آوردگاه <br />چنان خون همی رفت بر کوه و دشت <br />کزآن آسیاها بخون در بگشت .<br /> <font color=\"Red\">دقیقی .</font><br />بخون غرقه شد خاک و سنگ و گیا<br />بگشتی بخون گر بدی آسیا.<br /> <font color=\"Red\">فردوسی .</font><br />دل بر این گنبد گردنده منه کاین دولاب <br />آسیائی است که بر خون عزیزان گردد.<br /> <font color=\"Red\">عبید زاکانی (از کلیات ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">از آسیا بانگ بودن </span> ؛ در امری خرد یا بزرگ بی ارزترین حصه و سهل ِ فعل و عمل را داشتن <span class=\"hlight\">:</span> <br />باتو باشم درست و ششدانگم <br />بی تو باشم از آسیا بانگم .<br /> <font color=\"Red\">سنائی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">در آسیای روزگار بگشتن </span> ؛ بتصاریف و تحولات و مصائب آن دچار شدن <span class=\"hlight\">:</span> و از پس برافتادن، سپاه سالار غازی سعید در آسیای روزگار بگشت و خاست و افتاد و بر شغل بود و نبود. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ریش را در آسیا سفید کرده بودن </span> ؛ با سالخوردگی بی تجربه و جاهل بودن .<br /> <BR><font color=\"Blue\">◄</font> بتسامُح، سنگ آسیا. آسیاسنگ . حجر طاحونه . رحی . (السامی فی الاسامی ). لافظه . (السامی فی الاسامی ) <span class=\"hlight\">:</span> <br />با گران جان مگوی هرگز راز<br />کآسیا چون دو شد شود غماز.<br /> <font color=\"Red\">سنائی .</font><br />مابین آسمان و زمین جای عیش نیست <br />یک دانه چون جهد ز میان دو آسیا؟<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسیا، آسیای فلک، آسیای چرخ </span> ؛ آسمان <span class=\"hlight\">:</span> <br />ای خردمند پس گمان تو چیست <br />کاین دوان آسیا کی آساید؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />غافل کی بود خداوند از آنچ <br />رفت در این سبز و بلند آسیاش ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />چندین همی بقدرت او گردد<br />این آسیای تیزرو بی در.<br /> <font color=\"Red\">ناصرخسرو.</font><br />این آسیا دوان و در او من نشسته پست <br />ایدون سپیدسار در این آسیا شدم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای اژدهای چرخ دلم بیشتر بخور<br />وی آسیای چرخ تنم تنگ تر بسای .<br /> <font color=\"Red\">مسعودسعد.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسیا، آسیای معده </span> ؛ مجازاً، معده . جهاز هاضمه <span class=\"hlight\">:</span> <br />شکمی باید آهنین چون سنگ <br />کآسیاش از خورش نیاید تنگ .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> آسیاخانه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسیا کردن </span> ؛ طحن . و برای آسیای آبی و آسیای بادی و آسیای ستوری و آسیای بزرگ و آسیای اشتری و آسیای گاوی و آسیای دستی و مانند آن رجوع به آس شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسیای باد</span> ؛ بادآس <span class=\"hlight\">:</span> <br />از شکست ماست گردش چرخ بی بنیاد را<br />نیست غیر از دانه آبی آسیای باد را.<br /> <font color=\"Red\">صائب .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آبیست زیر پرّه که می گردد آسیا</span> ؛ این معلول را بی شک علتی است .<br /> <span class=\"hlight\">آسیا بنوبت، آسیا و پستا</span> ؛ هر کسی را باید بانتظار نوبت خود بود.<br /> <span class=\"hlight\">از آسیا من می آیم تو میگوئی پستا نیست </span> .<br /> <span class=\"hlight\">بی آرد می شود بسوی خانه زآسیا</span> <br />آنکو نبرده گندم و جو به آسیا شده ست .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <span class=\"hlight\">چو بارم آرد شد دیگرچرا در آسیا مانم </span> ؟<br /> <font color=\"Red\">صائب .</font><br /> <span class=\"hlight\">چون خشت به آسیا بری خاک آری </span> <br />بد میکنی و نیک طمع میداری <br />هم بد باشد جزای بدکرداری <br />نشنیدستی تواین مثل پنداری ...<br /> <font color=\"Red\">؟(از تاریخ گیلان مرعشی ).</font><br /> <span class=\"hlight\">دخل آب روان است و خرج آسیای گردان </span> .<br />(گلستان ).<br /> <span class=\"hlight\">گوئی مرا براه آسیا دیدی </span> ؛ سخت نامهربانی، چونانکه دوستی یا خویشی در میان ما نبوده و تنهایک بار براه آسیا یکدیگر را دیده ایم <span class=\"hlight\">:</span> <br />می بگذری و نپرسی از کارم <br />مانام براه آسیا دیدی .<br /> <font color=\"Red\">عطار.</font><br /> <span class=\"hlight\">مرد باید که در کشاکش دهر</span> <br />سنگ زیرین آسیا باشد.<br /><font color=\"Red\">؟</font><br /></font></div>'),
(1489, 'آسیا', '<span class=\"hlight\">آسیا.</span> (اِ) هر یک از دندانهای سرپَخ و درشت که خوردنی خشک و سخت را نرم و خرد کند، و شمار آن در آدمیان بیست باشد، ده در فک زبرین و ده دیگر در فک زیرین و جای آنها در پی ضواحک است . و نام هر یک از آن ده کرسی و به عربی طاحنه و رحی و مجموع آن طواحن و ارحاء باشد.<br /></font></div>'),
(1490, 'آسیا', '<span class=\"hlight\">آسیا.</span> (اِخ ) (کلمه ٔ یونانی . ابوریحان بیرونی ) و آن نام یکی از پنج برّ زمین است و آسیای کبری همانست . و این قطعه از چهار خشکی دیگر زمین بزرگتر باشد. آسیا قدیمترین ناحیه ٔ مسکون و مهد تمدن بشر است و حدود آن از شمال اوقیانوس منجمد و از مشرق اوقیانوس کبیر و دریای برنگ (برینگ ) و از جنوب دریای چین و اقیانوس هند و از مغرب دریای احمر و ترعه ٔ سوئز و مدیترانه باشد. این قاره چهار بار و نیم از اروپا بزرگتر است (<span class=\"hlight\" dir=\"rtl\">٤٥</span> میلیون کیلومترمربع) و از ضمایم آن بحر خزر و کوههای اورال است . این برّ در قدیم بقسمتهای زیرین منقسم میشده است : آسیای صغیر. ارمینیه . خراسان (پارتیا یا باختر). بین النهرین (آرام نهرین . آرام ناهارائیم ). بابل یا کلده . آشور و سوریه و کُلشید و عربستان و ایران و هندوستان و سیتی یا سارمانی (ممالک مردم سین یا چین ). وممالک کنونی آن آسیای روس (سیبری و قفقاز). منچوریا. مغولستان . تبت . ترکیه . سوریه . فلسطین . بین النهرین .عربستان (عراق عرب ). ایران . افغانستان . بلوچستان . ترکستان . هندوستان . بیرمانی . سیام . کامبوژ. آنام . تُنکن . هندوچین . چین . کره . ژاپن و مالاکاست . و مردم آن در حدود <span class=\"hlight\" dir=\"rtl\">٩٥٣</span> میلیون است .<br /></font></div>'),
(1491, 'آسیاآژن', '<span class=\"hlight\">آسیاآژن .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِمرکب ) آژینه . آسیازنه . برطیل . منقار. آس افزون . مِکْوَس . میقعه . <BR><font color=\"Blue\">◄</font> (نف مرکب ) نقار. آسیازن .<br /></font></div>'),
(1492, 'آسیاب', '<span class=\"hlight\">آسیاب .</span> (اِ مرکب ) (از: آس + آب ) آس که بقوت آب گردد، و توسعاً، هر نوع دیگر از آن . آب آسیا. آب آس <span class=\"hlight\">:</span> <br />چرا چون آسیاب گردگردی <br />بیاکنده به آب وباد و گردی ؟<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بخواهد همی خوردمان آسیاب <br />بدندان ما، در، گیا را فناست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گر نان طلب کنند در من زنند ازآنک <br />بی دانه ٔ من آب زده ست آسیابشان .<br /><font color=\"Red\">خاقانی .</font><br />هست بپیرامنش طوف کنان آسمان <br />آری بر گرد قطب چرخ زند آسیاب .<br /> <font color=\"Red\">خاقانی .</font><br />بر سرم گردید سنگ آسیاب <br />تا برآمد گردم از جان خراب .<br /><font color=\"Red\">بسحاق اطعمه .</font><br /></font></div>'),
(1493, 'آسیاب خسروخان', '<span class=\"hlight\">آسیاب خسروخان .</span> <font color=\"DarkGreen\"><b>[ ب ِ خ ُ رَ ]</font></b> (اِخ ) نام محلی در راه مشهد بباجگیران میان شاخه و دوربادام، در <span class=\"hlight\" dir=\"rtl\">٢٠٧٤٣٠</span> گزی مشهد.<br /></font></div>'),
(1494, 'آسیابان', '<span class=\"hlight\">آسیابان .</span> (ص مرکب، اِ مرکب ) آسبان . طَحّان <span class=\"hlight\">:</span> <br />چو بشنید از آسیابان سخُن <br />نه سر دید از آن کار پیدا نه بن .<br /> <font color=\"Red\">فردوسی .</font><br />فروماند از آن آسیابان شگفت <br />شب تیره اندیشه اندرگرفت .<br /> <font color=\"Red\">فردوسی .</font><br />هر آنکس که او فرّ یزدان ندید<br />از این آسیابان بباید شنید.<br /> <font color=\"Red\">فردوسی .</font><br />گشاد آسیابان در آسیا<br />به پشت اندرش بار لختی گیا.<br /> <font color=\"Red\">فردوسی .</font><br />بدو آسیابان بتشویر گفت <br />که جز تنگدستی مرا نیست جفت .<br /> <font color=\"Red\">فردوسی .</font><br />بشد آسیابان دو دیده پرآب <br />بزردی دو رخسار چون آفتاب .<br /> <font color=\"Red\">فردوسی .</font><br />پدرْمان یکی آسیابان پیر<br />بر این دامن کوه نخجیرگیر.<br /> <font color=\"Red\">فردوسی .</font><br />از این آسیابان بپرسید مه <br />که بَرْسَم کرا خواهی ای روزبه ؟<br /> <font color=\"Red\">فردوسی .</font><br />از بس که بر تو برگشت این آسیای گیتی <br />چون مرد آسیابان پرگرد آسیائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آسیابان را به بینی چون از او بیرون شوی <br />وندرین جا هم ببینی چشمت ار بیناستی .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(1495, 'آسیابانی', '<span class=\"hlight\">آسیابانی .</span> (حامص مرکب ) حرفه ٔ آسیابان . طِحانت . آسبانی <span class=\"hlight\">:</span> <br />آنکه رفتم بکسب فضل و هنر<br />کاشکی رفتمی بدهقانی <br />کاش کردی بدهر بخت سیاه <br />روسفیدم به آسیابانی .<br /><font color=\"Red\">؟</font><br /></font></div>'),
(1496, 'آسیابک', '<span class=\"hlight\">آسیابک .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نام قریه ای در زرند.<br /></font></div>'),
(1497, 'آسیات', '<span class=\"hlight\">آسیات .</span> (ع ص، اِ) ج ِ آسیه .<br /></font></div>'),
(1498, 'آسیاخانه', '<span class=\"hlight\">آسیاخانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) بنائی برآورده آسیا را. جایگاه آسیا. آس کده . آسیاکده . سرآسیا. مرحی . مطحن .<br /></font></div>'),
(1499, 'آسیاروب', '<span class=\"hlight\">آسیاروب .</span> (اِ مرکب ) ثِفال . سفره ٔ چرمین زیر دستاس .<br /></font></div>'),
(1500, 'آسیازن', '<span class=\"hlight\">آسیازن .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (نف مرکب ) نَقّار. (دهار). آسیاآژن .<br /></font></div>'),
(1501, 'آسیازنه', '<span class=\"hlight\">آسیازنه .</span> <font color=\"DarkGreen\"><b>[ زَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) ابزار آجیدن سنگ آسیا. آژینه . منقار. میقعه . مِکْوَس . برطیل . آس افزون .<br /></font></div>'),
(1502, 'آسیاس', '<span class=\"hlight\">آسیاس .</span> (اِخ ) مرکز خُرّه ٔ چهاردانگه ٔ ولایت قشقائی فارس .<br /></font></div>'),
(1503, 'آسیاسنگ', '<span class=\"hlight\">آسیاسنگ .</span> <font color=\"DarkGreen\"><b>[ سیا س َ ]</font></b> (اِ مرکب ) سنگ آسیا. حجر طاحونه . رحی <span class=\"hlight\">:</span> <br />یکی آسیاسنگ را درربود<br />به نزدیک رستم درآمد چو دود.<br /> <font color=\"Red\">فردوسی .</font><br />برگرفت آن آسیاسنگ و بزد<br />بر مگس تا آن مگس واپس خزد.<br /> <font color=\"Red\">مولوی .</font><br />آسیاسنگ زیرین متحرک نیست لاجرم تحمل بار گران همی کند. (گلستان ).<br />سهمگین آبی که مرغابی در او ایمن نبودی <br />کمترین موج آسیاسنگ از کنارش درربودی .<br /> <font color=\"Red\">سعدی .</font><br />نه آنکه بر در دعوی نشیند از خلقی <br />وگر خلاف کنندش بجنگ برخیزد<br />که گر ز کوه فروغلطد آسیاسنگی <br />نه عارف است که از راه سنگ برخیزد.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1504, 'آسیان', '<span class=\"hlight\">آسیان .</span> (اِخ ) ج ِ آسی . مردمان مملکت آس . - زبان آسیان ؛ لهجه ای از زبان فارسی قدیم : دَنَه ؛ نام زن است به زبان آسیان . (فرهنگ اسدی، خطی ). صابوته ؛ زن پیر باشد بزبان آسیان . هاز؛ بِدان بزبان آسیان . (فرهنگ اسدی، خطی ) .<br /></font></div>'),
(1505, 'آسیانه', '<span class=\"hlight\">آسیانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) سنگ فسان .<br /></font></div>'),
(1506, 'آسیاه', '<span class=\"hlight\">آسیاه .</span> (اِ مرکب ) آسیا.<br /></font></div>'),
(1507, 'آسیاو', '<span class=\"hlight\">آسیاو.</span> (اِ مرکب ) آسیا.<br /></font></div>'),
(1508, 'آسیاچرخ', '<span class=\"hlight\">آسیاچرخ .</span> <font color=\"DarkGreen\"><b>[ چ َ ]</font></b> (اِ مرکب ) آسیا که بقوت باد گردد. بادآس . آسیای بادی <span class=\"hlight\">:</span> و دیگر <font color=\"DarkGreen\"><b>[ از خواص سیستان ]</font></b> آنکه در آنجا آسیاچرخ کنند تا باد بگرداند و آرد کند و بدیگر شهرها ستور باید یا آسیاء آب یا به دست آسیا کنند. (تاریخ سیستان ). و رجوع به چرخباد شود.<br /></font></div>'),
(1509, 'آسیاکده', '<span class=\"hlight\">آسیاکده .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) آسکده . جایگاه آسیا. آسیاخانه . آسی خانه . مرحی . مطحن . سرآسیا.<br /></font></div>'),
(1510, 'آسیای صغیر', '<span class=\"hlight\">آسیای صغیر.</span> <font color=\"DarkGreen\"><b>[ ی ِ ص َ ]</font></b> (اِخ ) آسیةالصّغری . آناطولی . نام شبه جزیره ای بجنوب دریای سیاه و مشرق مدیترانه و شمال سوریه . و مملکت ترکیه ٔ امروزین تقریباً همین شبه جزیره است و شهرهای مهم آن انگوریه (آنگرا، آنقره ) عاصمه ٔ کنونی ترکیه و ازمیر و ادنه و بروسه است . و در دوره ٔ هخامنشیان مملکت ایران را رود فرات بدو بخش غربی و شرقی منقسم می کرده، قسمت غربی آن آسیای صغیر و مصر بوده است و آن بچترپتی های ذیل تقسیم میشده : لیدی، ایونی، کاری، میزی، افروغیه، قبادقیّه، بافلاغونیه، بیتینی، لیسی، پامفیلی، پیزیدی، سیلیسی، سوریه، غلاطیه، ترواس، پنطس .<br /></font></div>'),
(1511, 'آسیب', '<span class=\"hlight\">آسیب .</span> (اِ) زخم . کوب . ضرب <span class=\"hlight\">:</span> <br />به آسیب پا و بزانو و دست <br />همی مردم افکند چون پیل مست .<br /> <font color=\"Red\">عنصری .</font><br /> <BR><font color=\"Blue\">◄</font> صدمه . کوس . کوست . عیب و نقص یا شکستگی که از زخم و ضرب پیدا آید <span class=\"hlight\">:</span> <br />همان گرد بررفت مانند دود<br />ز آسیب رخساره ٔ مه شخود.<br /> <font color=\"Red\">فردوسی .</font><br />اندوهم از آن است که یک روز مفاجا<br />آسیبی از این دل بفتد بر جگر آید.<br /> <font color=\"Red\">فرخی .</font><br />بدین شهر دروازه ها شد منقش <br />از آسیب و از کوس چتر و عماری .<br /> <font color=\"Red\">زبیبی یا ربیبی یا زینبی یا زینتی .</font><br /> <BR><font color=\"Blue\">◄</font> ضرب . ضربت . زخم . ضربه <span class=\"hlight\">:</span> <br />که گشتستند از آسیب شمشیر و سنان تو<br />بنقش پیل گرمابه بشکل شیر شادروان .<br /> <font color=\"Red\">عبدالواسع جبلی .</font><br /> <BR><font color=\"Blue\">◄</font> لطام <span class=\"hlight\">:</span> <br />سر بادبانها برآمد بر اوج <br />بجنبید کشتی ز آسیب موج .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> تعب . رنج . مشقت . کلفت <span class=\"hlight\">:</span> <br />چه آزادند درویشان ز آسیب گرانباری <br />چه محتاجند سلطانان به اسباب جهانبانی .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> جرح . خستگی . فکاری <span class=\"hlight\">:</span> <br />ز آسیب شیران پولادچنگ <br />دریده دل شیر و چرم پلنگ .<br /> <font color=\"Red\">فردوسی .</font><br />رسیده آفت نشبیل او به هر کامی <br />نهاده کشته ٔ آسیب او به هر مشهد.<br /> <font color=\"Red\">منجیک .</font><br /> <BR><font color=\"Blue\">◄</font> آفت . نکبت . بلا. فتنه . مصیبت . خطر. آکفت <span class=\"hlight\">:</span> <br />سپهدار هندوستان شاد گشت <br />کز آسیب اسکندر آزاد گشت .<br /> <font color=\"Red\">فردوسی .</font><br />و هیچ آسیب نبود اندرین روزگار بسیستان تا آمدن طغرل . (تاریخ سیستان ). بوسهل آمد و پیغام آورد که خواجه بروزگار پدرم آسیبها و رنجها دیده است ... باید که در این کار تن دردهد. (تاریخ بیهقی ).<br />اقلیم پارس را غم از آسیب دهر نیست <br />تا بر سرش بود چو توئی سایه ٔ خدا.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> زیان . ضرر <span class=\"hlight\">:</span> <br />نه آسیب یابد بدین گنج تو<br />نه ارزد همه گنجها رنج تو.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسیب آسیب !</span> ؛ الخطر الخطر! حذار حذار! اَلحذَر <span class=\"hlight\">:</span> <br />ای برادر سخن نادان خاری است درشت <br />دور باش از سخن بیهده آسیب آسیب !<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> گزند. آزار <span class=\"hlight\">:</span> <br />دلش باد شادان و تاجش بلند<br />تنش دور از آسیب و جان از گزند.<br /> <font color=\"Red\">فردوسی .</font><br />چون بایشان بازخورد آسیب شاه شهریار<br />جنگ ایشان عجز گشت و سحر ایشان بادرم .<br /> <font color=\"Red\">عنصری .</font><br />او را <font color=\"DarkGreen\"><b>[ دانیال را ]</font></b> با شیری در چاه کردند هیچ آسیبی نرسیدش . (مجمل التواریخ ). زینهار تا آسیبی بدونزنی . (کلیله و دمنه ). اگر روباه در حرص و شره مبالغت ننمودی ... آسیب نخجیران بدو نرسیدی . (کلیله و دمنه ).<br />قصد آن کردم که ذوالقرنین ثانی خوانمش <br />عقل گفت ای خاطرت آسیب نقصان یافته .<br /> <font color=\"Red\">انوری .</font><br />گرچه ز هرچه دوست بد آسیب دیده ام <br />ورچه ز هرچه خصم بد آزار خورده ام .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> مالش . نظر نَحس <span class=\"hlight\">:</span> <br />مرد آسیب فلک یابد کاندر دو صفت <br />همچنو عنصر نفع آمد و سرمایه ٔ ضَر.<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> لگد. اسکیزه . جُفته . آلیز <span class=\"hlight\">:</span> <br />سواری پدید آمد اندر نبرد<br />کز آسیب اسبش جهان شد بدرد.<br /> <font color=\"Red\">فردوسی .</font><br />آسمان زآسیب خنگش راست چون شیشه ز باد<br />چار جانب پس خزد کش وسعت میدان کند.<br /> <font color=\"Red\">امیرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> تماس . سایش . ببساوش . تلاقی <span class=\"hlight\">:</span> در آنجا خداوند، حال آن آب را میگرداند تا درّ میشود. پردگیان با جمال باید که آسیب آن درّ چون با گوش و بناگوش ایشان باشد قدر آن درّ بدانند و جمال خود را بقیمت کامله بفروشند. (کتاب المعارف ).<br />دست زن درکرد در شلوار مرد<br />خرزه اش بر دست زن آسیب کرد.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> پرتو. (لسان الشعراء از مؤیدالفضلاء). نور، مقابل ضیاء. <BR><font color=\"Blue\">◄</font> تبش . هُرم <span class=\"hlight\">:</span> <br />شعله ٔقهر تو گر با کوثر آسیبی زند<br />زو برآید همچنان کز قعر دوزخ التهاب .<br /> <font color=\"Red\">علی فرقدی .</font><br />یکی شعله ای باشدی سهمناک <br />که دوزخ از آسیب آن باشدی .<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> دمش . وزش . نفحه <span class=\"hlight\">:</span> <br />گناه من بیک آسیب باد رحمت تو<br />بریزد ار مثل افزون ز برگ اشجار است .<br /> <font color=\"Red\">امیرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> کوفتگی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسیب دیده، آسیب رسیده </span> ؛ ضرب خورده . صدمه دیده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسیب زدن، آسیب رسانیدن </span> ؛ صدمه و ضرب زدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسیبها</span> ؛ آفات .مصائب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آسیب یافتن، آسیب دیدن </span> ؛ صدمه دیدن .<br /></font></div>'),
(1512, 'آسیب و شیب', '<span class=\"hlight\">آسیب و شیب .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِ مرکب، از اتباع ) دلواپسی . اضطراب . تشویش . رنج . تعب <span class=\"hlight\">:</span> <br />بلشکرگه خویش بازآمدند<br />برِ پهلوانان فراز آمدند<br />همه شب بخواب اندر آسیب و شیب <br />ز پیکارشان دل شده ناشکیب .<br /> <font color=\"Red\">فردوسی .</font><br />چنین است گیتی پر آسیب و شیب <br />پس ِ هر فرازی نهاده نشیب .<br /> <font color=\"Red\">فردوسی .</font><br />در بعض نسخ شاهنامه بجای آسیب، آشیب ضبط شده، و ظاهراً صحیح هم همان است . و کلمه ٔ آشیب و شیب درصورتی دیگر از شیب و تیب یا شیب و شیب مینماید <span class=\"hlight\">:</span> <br />شیب تو با فراز و فرازتو با نشیب <br />فرزند آدمی بتو اندر به شیب و تیب .<br /> <font color=\"Red\">رودکی .</font><br />نبوده مرا هیچ با تو عتیب <br />مرا بیگنه کرده ای شیب و تیب .<br /><font color=\"Red\">عماره .</font><br /></font></div>'),
(1513, 'آسیبی', '<span class=\"hlight\">آسیبی .</span> (ص نسبی ) ذوجِنّه . پری زده . دیودیده . پری گرفته . دیوگرفته . دیوزده .سایه دار. سایه زده . دیودار. کوهه گرفته . بیوقتی شده .<br /></font></div>'),
(1514, 'آسیم', '<span class=\"hlight\">آسیم .</span> (ص، اِ) بلغت زند و پازند استاد بزرگ مرتبه و عظیم الشأن . (برهان ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1515, 'آسیمه', '<span class=\"hlight\">آسیمه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ]</font></b> (ص ) مضطرب . مشوش . پریشان خاطر. آشفته <span class=\"hlight\">:</span> <br />بدان تن در آسیمه گردد روان <br />سپه چون بود شاد بی پهلوان .<br /> <font color=\"Red\">فردوسی .</font><br />به ره گیو را دید <font color=\"DarkGreen\"><b>[ دستان ]</font></b> پژمرده روی <br />همی آمد آسیمه و پوی پوی .<br /> <font color=\"Red\">فردوسی .</font><br />بگفت این وبرخاست و در خیمه شد<br />جهانی ز گفتارش آسیمه شد.<br /> <font color=\"Red\">فردوسی .</font><br />نه آسیمه گشت و نه پرسید راز<br />نیایش کنان رفت و بردش نماز.<br /> <font color=\"Red\">فردوسی .</font><br />دل یوسف آسیمه شد زآن نهاد<br />به لاحول گفتن زبان برگشاد.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />آسیمه بسی کرد فلک بی خبران را<br />وآشفته بسی گشت بدو کار مهیا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />آسیمه شد و رنجه دل، تنم را<br />نه غبن ضیاع و عقار دارد.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> حیران . بشگفتی مانده . متحیر. متعجب . خیره . حیرت زده . مبهوت . سرگردان . سرگشته <span class=\"hlight\">:</span> <br />بدو گفت قیدافه کای نیطقون <br />چرا خیره گشتی بکاخ اندرون <br />همانا که چونین نباشد بروم <br />که آسیمه گشتی بدین مایه بوم ؟<br /> <font color=\"Red\">فردوسی .</font><br />آسیمه شدم هیچ ندانم چکنم من <br />عاجز شدم و کردم بر عجز خود اقرار.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> دنگ . دنگ و دَلْو. مَنگ <span class=\"hlight\">:</span> <br />ز دریاتو گوئی که برخاست موج <br />سپاه اندر آمد همی فوج فوج <br />سراپرده بردند از ایوان بدشت <br />سپه از خروشیدن آسیمه گشت .<br /> <font color=\"Red\">فردوسی .</font><br />گرفتند هر دو دوال کمر<br />پریشان و غمگین و آسیمه سر.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نه بسامان . ژولیده <span class=\"hlight\">:</span> <br />بدشت آوریدندش آسیمه خوار<br />برهنه سر و پای و برگشته کار.<br /> <font color=\"Red\">فردوسی .</font><br />چو اسب پسر دید گیوش بدست <br />پر از خاک و آسیمه برسان مست .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> گیج . بِدُوار <span class=\"hlight\">:</span> <br />بینداخت ژوبین به پیران رسید<br />زره در برش سر بسر بردرید<br />ز پشت اندرآمد براه جگرْش <br />بغلطید و آسیمه برگشت سرْش .<br /> <font color=\"Red\">فردوسی .</font><br />بجوشیدخون از دهان تا جگر<br />تنش سست تر گشت و آسیمه سر.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> دهشت زده . بیمناک . هراسیده <span class=\"hlight\">:</span> <br />یکی بانگ برزد بر او مادرش <br />که آسیمه تر گشت جنگی سرش .<br /> <font color=\"Red\">فردوسی .</font><br />دگر خفته آسیمه برخاستند<br />بهر جای جنگی بیاراستند.<br /> <font color=\"Red\">فردوسی .</font><br />ور ذرّه بچشم آیدش آسیمه بماند<br />گوید مگر آن از تک اسب تو غباریست .<br /> <font color=\"Red\">فرخی .</font><br />روزی درخش تیغ تو بر آتش اوفتاد<br />آتش ز بیم تیغ تو در سنگ شد نهان <br />واکنون چو آهنی زبر سنگ برزنی <br />آسیمه گردد و شود اندر جهان جَهان .<br /> <font color=\"Red\">فرخی .</font><br />ز روحه همه مهتران سر بسر<br />بماندند مدهوش و آسیمه سر.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> شتاب زده <span class=\"hlight\">:</span> <br />کله دار چون بانگ اسبان شنید<br />شد آسیمه از خواب و سر برکشید.<br /> <font color=\"Red\">فردوسی .</font><br />و در همه ٔ معانی آسیوَن مرادف آسیمه است . و در فرهنگها باین کلمه معنی کالیوه (اسدی )، شیدا (صحاح الفرس )، دیوانه، دیوانه مزاج، شوریده، شیفته و دست پاچه نیز داده اند. رجوع به آسیمه سار و آسیمه سر و سرآسیمه شود.<br /></font></div>'),
(1516, 'آسیمه سار', '<span class=\"hlight\">آسیمه سار.</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span>م ِ ]</font></b> (ص مرکب ) آسیمه سر. سرآسیمه .آسیمه <span class=\"hlight\">:</span> <br />من از بهر آن بچه آسیمه سار<br />همی گردم اندر جهان سوگوار.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />و رجوع به آسیمه و آسیمه سر و سرآسیمه شود.<br /></font></div>'),
(1517, 'آسیمه سر', '<span class=\"hlight\">آسیمه سر.</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ س َ ]</font></b> (ص مرکب ) آسیمه سار. سرگشته . سرگردان . متحیر <span class=\"hlight\">:</span> <br />وزآن پس شنیدم یکی بد خبر<br />کزآن نیز بر، گشتم آسیمه سر.<br /> <font color=\"Red\">فردوسی .</font><br />ایمه دوران چو من آسیمه سر است <br />نسبت جور بدوران چه کنم ؟<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> گیج . پریشان حواس . شیفته گونه . شوریده حال <span class=\"hlight\">:</span> <br />من بنده که نزدیک تو شعر آرم باشم <br />آسیمه سر و ساده دل و خیره و واله .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> مضطرب . مشوش . پریشان خاطر.آشفته <span class=\"hlight\">:</span> <br />خدنگی بر اسب سپهبد <font color=\"DarkGreen\"><b>[ طوس ]</font></b> بزد <font color=\"DarkGreen\"><b>[ فرود ]</font></b><br />چنان کز کمان دلیران سزد<br />نگون شد سر بارگی جان بداد<br />دل طوس پرکین و سر پر ز باد<br />بلشکرگه آمد بگردن سپر<br />پیاده پر از گرد و آسیمه سر.<br /> <font color=\"Red\">فردوسی .</font><br />که آن ده تن از تخمه ٔ نامور<br />از او بازگشتند آسیمه سر.<br /> <font color=\"Red\">فردوسی .</font><br />یاران بدرد من ز من آسیمه سرترند<br />ایشان چه کرده اندبگو تا من آن کنم .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> متزلزل . نوان <span class=\"hlight\">:</span> <br />تا ماه بکشتی در، من در خطرم <br />چون کشتی از آب دیده آسیمه سرم <br />زآن باد کز او بشادی آرد خبرم <br />چون آب بشیبم و چو کشتی ببرم .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> دست وپاگم کرده . دستپاچه <span class=\"hlight\">:</span> <br />چو از رود کردند هر سه گذر<br />نگهبان کشتی شد آسیمه سر.<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به آسیمه و آسیمه سار و سراسیمه شود.<br /></font></div>'),
(1518, 'آسینه', '<span class=\"hlight\">آسینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) تخم مرغ . آشینه .<br /></font></div>'),
(1519, 'آسیه', '<span class=\"hlight\">آسیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص، اِ) تأنیث آسی . حزینه . زنی اندوهگین . <BR><font color=\"Blue\">◄</font> خاتنه . آلت ختنه کردن . <BR><font color=\"Blue\">◄</font> زن بجشک . (ربنجنی ). طبیبه . ج، اَواسی، آسیات . <BR><font color=\"Blue\">◄</font> ستون . (ربنجنی ). ساریه . اسطوانه . دعامه . دیرک . ج، اَواسی .<br /></font></div>'),
(1520, 'آسیه', '<span class=\"hlight\">آسیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) بنت مزاحم . نام زن فرعون که گویند موسی علیه السلام را از نیل برگرفت و نهان از شوی بپرورد <span class=\"hlight\">:</span> <br />بازگفت او این سخن با آسیه <br />گفت جان افشان بر او ای روسیه .<br /><font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> آسیه بنت فَرَج جرهمیه . نام یکی از صحابیات . <BR><font color=\"Blue\">◄</font> نام محدّثه ای خواهر ضیاء مقدسی . <BR><font color=\"Blue\">◄</font> (اِ) امروز نامی است از نامهای زنان ایرانی و ترک و عرب .<br /></font></div>'),
(1521, 'آسیه', '<span class=\"hlight\">آسیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) ج ِ اِساء. ادویه .<br /></font></div>'),
(1522, 'آسیون', '<span class=\"hlight\">آسیون .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ص ) آسیمه <span class=\"hlight\">:</span> <br />گر نه عشقت کرد آسیون مرا<br />از چه رو سرگشته و آسیونم ؟<br /> <font color=\"Red\">منجیک .</font><br />چه چیزی کاین همه آسیون از تست <br />که بی تو زندگانی ّ من از تست ؟<br /> <font color=\"Red\">فریدالدین عطار.</font><br />و صاحب برهان بر وزن آبگون ضبط کرده وظاهراً غلط است، یا صورتی دیگر از این کلمه است .<br /></font></div>'),
(1523, 'آش', '<span class=\"hlight\">آش .</span> (اِ) آنچه پزند از طعام . یا طعام رقیق آشامیدنی . مَرَق <span class=\"hlight\">:</span> <br />رزق تن پاک همه باطل و ناچیز شود<br />گر نیاید پدر تاش تکین بر دم آش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />این آشها را مدبران ملائکه از سرای بهشت دست به دست کرده اند و این آشها را می فرستند و دو تن فرشته برهر خوان ایستاده اند و محافظت می کنند. (کتاب المعارف ). و از تو هم بخورند از کژدم و مار و پرنده و بر آش جهان ترا نواله کنند. (کتاب المعارف ).<br />تا تو در بند قلیه و نانی <br />کی رسی در بهشت رحمانی <br />خوردن اینجا روا نمیدارند<br />در بهشت آش و سفره کی آرند<br />در بهشت ار خوری جو و گندم <br />هم ّ آدم کنی پی خود گم .<br /> <font color=\"Red\">اوحدی .</font><br />هرچه در وجه آش و نان تو نیست <br />بفشان و بده که آن تو نیست .<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> طعامی خاص که باقسام پزند روان و با برنج و غالباً با سبزی و حبوب و دانه ها و ترشی ها و چاشنی ها. و این همان ابا و با و وا باشد <span class=\"hlight\">:</span> <br />نه همچو دیگ سیه رو شوم ز بهر شکم <br />نه دست کفچه کنم از برای کاسه ٔ آش .<br /> <font color=\"Red\">ابن یمین .</font><br />در حجره نشسته بودیم و آش کدو می پختیم . (انیس الطالبین بخاری ) . حلق های شما را گرفتیم تا نتوانید آش خوردن . آن درویشان بذوق تمام آش را بخدمت خواجه حاضر کردند. (انیس الطالبین بخاری ). چون چهار دانگ راه آمدم آش را از دیگ کشیدید. (انیس الطالبین بخاری ). <font color=\"DarkGreen\"><b>[ مقصود از این آش شیربرنج است ]</font></b> آن مقداری که آش پخته گردد آن درویش ابراهیم بر همان صفت بود. (انیس الطالبین بخاری ).<br />مطبخی را دی طلب کردم که بغرائی پزد<br />تا شود زآن آش کار ما و مهمان ساخته .<br /> <font color=\"Red\">کاتبی ترشیزی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش آب غوره، آش آب لیمو، آش آب نارنج </span> ؛آبغوره با و آب لیموبا و آب نارنج با است که آچار آن ازافشره ٔ غوره و لیموی ترش و نارنج کنند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش آلو</span> ؛ آلوباست که چاشنی آن آلوست و عرب آن را اجاصیه گوید.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش آلوچه </span> ؛ آلوچه با <span class=\"hlight\">:</span> <br />آش آلوچه خوش و معتدل آمد بمزاج <br />ای دل از آش چنین دست مداری زنهار.<br /><font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش آلوزرد</span> ؛ آشی که چاشنی آلوزرد دارد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش ابودردا</span> ؛ آشی که برای شفای دردمندان و بیماران پزند و بمستحقان دهند، و نسبت آن به ابوالدرداء عویمربن مالک صحابی کنند و بی شک حروف درد در ابودردا و مشابهت آن با درد به معنی بیماری در فارسی منشاء این نسبت شده است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش ارزن </span> . رجوع به آش الم و آش گاورس شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش الم </span> ؛ آشی است که بجای برنج گاورس دارد <span class=\"hlight\">:</span> <br />قوت کردان چه بود نان بلوت آش الم <br />میخورند این دو غذا در سربند کلبار.<br /> <font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش اُماج </span> ؛ آشی که اماج (خمیرهای ریز است چندِ عدسی ) در آن کنند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش امام زین العابدین </span> ؛ آشی که در آن انواع سبزیها و گوشت کنند و آن را بنذر پزند و بفقرا بخشند. و آن را شله قلمکار نیز گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش انار</span> ؛ آشی که آچار آن آب انار است . ناربا.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش برگ </span> ؛ آشی که اسفناج یا برگ چغندر سبزی آن است . و آش رشته را نیز گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش بغرا</span> ؛ آشی بوده که در آن گوشت و دنبه می کرده اند و خمیری چون اماج یا رشته نیز داشته است، و گویند آن منسوب به بغراخان پسر قدرخان است <span class=\"hlight\">:</span> <br />مطبخی را دی طلب کردم که بغرائی پزد<br />تا شود زآن آش کار ما و مهمان ساخته <br />گفت لحم و دنبه گر یابم که خواهد داد آرد<br />گفتم آنکو آسیای چرخ گردان ساخته .<br /> <font color=\"Red\">کاتبی ترشیزی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش پشت پا، قفابا</span> ؛ آشی که پس از مسافرت کسی بروز سوم پزند و آن را بشگون دارندصحت و سلامت مسافر و کوتاهی سفر او را.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش ترخنه </span> ؛ آش جو مقشر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش ترخنه دوغ </span> ؛ آشی که جو مقشر در دوغ تر نهاده وسپس خشک کرده در آن ریزند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش ترش </span> ؛ هر آش که در آن قسمی ترشی کرده باشند <span class=\"hlight\">:</span> <br />فصل رابعهمه از آش ترش خواهم گفت <br />ای که صفرات گرفته ست ز پار و پیرار.<br /> <font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش تره جعفری </span> ؛ آشی که سبزی آن تره و جعفریست . و آن را شوربا نیز گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش تمر</span> ؛ آشی که آچار آن تمر هندیست .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش جو</span> ؛ آشی که دانه اش بلغور و جریش جو است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش جو نعمّه </span> ؛ آشی که قطعات خمیر بشکل لوزی در آن کنند، و تتماج همانست .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش حلیم </span> ؛ آشی است که از گندم و گوشت و نخود پزند و سخت بورزند تا اجزاء آن در هم پیوندد. و آن را گندم با و کشک با نیز گویند، و عرب هریسه خواند، و این آش سبزی ندارد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش خلو</span> ؛ آش آلو یا قسمی از آلو <span class=\"hlight\">:</span> <br />در آش خلو کوفته دیدم که بدعوی <br />برد آن گرو از میوه که با هیئت بِه ْ بست .<br /> <font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش خلیل، آش خلیل اﷲ</span> ؛ آشی که دانه ٔ آن عدس است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش درهم جوش </span> ؛ آشی که سبزیها و حبوبات گوناگون در آن ریخته باشند و از آنرو نامطبوع شده باشد: مثل آش درهم جوش ؛ مخلوطی از بسیار چیزهای نامتناسب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش دوغ </span> ؛ آشی که آچار آن دوغ ماست یا دوغ کشک است و در آن گاهی گوشت بره نیز ریزند <span class=\"hlight\">:</span> <br />ساعد و ران بره و آش دوغ <br />میکشد از ساق چغندر بلا.<br /> <font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش رشته </span> ؛ آشی که در آن رشته ٔ خمیر ریزند. و در تداول اطفال به معنی حجامت است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش زرشک </span> ؛ آشی که چاشنی آن زرشک است <span class=\"hlight\">:</span> <br />صفت آش بنا کردم و عقلم می گفت <br />لوحش اﷲ دگر از آش زرشک خوشخوار.<br /> <font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش زیره </span> ؛ آش شوربا که از ابازیرْ زیره دارد. زیره با. زیرباج <span class=\"hlight\">:</span> <br />چنان آش زیره ز کرمان براند<br />کز او یلغز کوفته بازماند.<br /> <font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش ساده </span> ؛ آش بی ترشی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش ساک </span> ؛ آشی که سرکه و اسفناج دارد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش سرخ حصار</span> ؛ آش قجری .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش سرکه </span> ؛ آش که در آن به آچار سرکه کنند. سرکه با. سکبا <span class=\"hlight\">:</span> <br />چار ارکان مختلف در دیگ آش سرکه هست <br />روپیاز و مس چغندر، دنبه سیم و گوشت زر.<br /> <font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش سماق </span> ؛ آشی که آچار آن سماق است <span class=\"hlight\">:</span> <br />سر میسره گشته آش سماق <br />که بود از چغندر بدستش چماق .<br /> <font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش شلغم </span> ؛ آشی که در آن شلغم مُقشر و خردکرده ریزند. شلغم شوربا. لفتیه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش شُلّه زرد</span> ؛ آشی که تنها از برنج و شکر کنند و ابازیر زعفران بدان زنند و خلال پسته و بادام نیز در آن ریزند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش شُلّه قلمکار</span> ؛ آش امام زین العابدین :مثل آش شله قلمکار؛ مخلوطی از چیزهای نامتناسب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش شله ماش </span> ؛ آشی ازبرنج و ماش، تنک تر از کته ٔ ماش و ستبرتر از آش ماش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش شوربا</span> ؛ آشی که از تره و جعفری و برنج و کمی لپه کنند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش عدس </span> ؛ آشی که از حبوب ْ عدس دارد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش غوره </span> ؛ آشی که آچار آن غوره ٔ تازه است . غوره با. حِصرمیه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش قارا</span> ؛ آشی که درآن قره قوروت کنند. مصلیه . رخبین با.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش قجری </span> ؛ آشی که سلاطین قاجار سالی یک بار در ییلاق شمیران می پختند و زنان شاه و رجال و اعیان و زنانشان در پاک کردن حبوب و بُقول و پختن آن همدستی می کردند، و آن را گاهی در قریه ٔ سرخ حصار طبخ میکردندو از آنرو آش سرخ حصار نیز نامیده میشد. مثل آش قجری یا مثل آش سرخ حصار؛ تشبیهی مبتذل است مخلوطی از بسیار چیزهای نامتناسب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش کدو</span> ؛ شوربائی که کدو نیز بر آن مزید کنند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش کرَم، آش کلم </span> ؛ کرنبیه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش کشک </span> ؛ آشی که ترشی آن دوغ کشک است و آن را در قدیم پینوئین می گفته اند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش کشکاب، کشکاب </span> ؛آش جو <span class=\"hlight\">:</span> <br />در زمانی که چنین نعمت هر جنس خوری <br />آش کشکاب در آن حال بخاطر میدار.<br /> <font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش کلم </span> ؛ آشی که در آن کلم مُقشر خردکرده ریزند و به عربی کرنبیه گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش گاورس </span> ؛ آش الم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش گوجه </span> ؛ آشی که آچار گوجه ٔ تر دارد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش گوجه برغانی </span> ؛ آشی که در آن گوجه ٔ برغانی خشک که نوع بهتر و درشت تر گوجه ها است ریزند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش لخشک </span> ؛ آش جو نعمه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش ماست </span> ؛ آشی که ترشی آن ماست است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش ماش </span> ؛ آشی که دانه ٔ آن ماش است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش میویز</span> ؛ آشی که در آن مویز یعنی انگور خشک ریزند. مویزوا <span class=\"hlight\">:</span> <br />بتعجیل آمد روان زاصفهان <br />بسر آش میویز با ناردان .<br /> <font color=\"Red\">بسحاق اطعمه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش ناردان، آش ناردانگ </span> ؛ آشی که در آن اناردانه ٔ خشک بستانی یا جنگلی کنند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش ویشیل </span> ؛ بلهجه ٔ بعض ولایات آش بی ترشی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش یا ولی اﷲ</span> ؛ فیرنی . و در بعض جاها بکلمه ٔ آش معنی پلاو (پُلَو) دهند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آش دهن سوزی نبودن </span> ؛ بسیار مطلوب نبودن .<br /> <span class=\"hlight\">آشی برای کسی پختن </span> ؛ کسی را در نهانی بایذاء کسی برانگیختن .<br /> <span class=\"hlight\">این آش و این نقاره </span> ؛ با کار و عملی صعب مزدی اندک .<br /> <span class=\"hlight\">کاسه ٔ از آش گرمتر</span> ؛ مرادف دایه ٔ از مادر مهربانتر <span class=\"hlight\">:</span> <br />کیسه ٔ بیشتر از کان که شنید<br />کاسه ٔ گرمتر از آش که دید؟<br /> <font color=\"Red\">جامی .</font><br /> <span class=\"hlight\">هرجا آش است کَل فرّاش است </span> ؛ هرجا طعامی یا سودی هست او در آنجاست .<br /><span class=\"hlight\">همان آش در کاسه است، همان آش است و همان کاسه </span> ؛ هیچگونه بهبودی درامر نیست .<br /></font></div>'),
(1524, 'آش', '<span class=\"hlight\">آش .</span> (اِ) آهر. آهار. بت . پت .شوی و شو که بجامه کنند. <BR><font color=\"Blue\">◄</font> ترکیبی مایع که پوست خام در آن آغارند پیراستن و دباغت را. خورش . <BR><font color=\"Blue\">◄</font> لعاب که بر ظروف سفالین و فلزین دهند. <BR><font color=\"Blue\">◄</font> لعابی که به پشم زنند نمد ساختن را.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آش کردن </span> ؛ دباغت و پیراستن ادیم . آغاردن پوست در خورش . رجوع به آشدار شود.<br /></font></div>'),
(1525, 'آش', '<span class=\"hlight\">آش .</span> (اِخ ) نام قریه ای بخراسان . و از آنجاست محمدبن احمد ملقب به ابوبکر الخبازی خطیب و او بمرو بوده و در <span class=\"hlight\" dir=\"rtl\">٥٠٣</span> هَ .ق . دیواری بر او افتاده ودرگذشته است . <BR><font color=\"Blue\">◄</font> وادی آش . رجوع به وادی آش شود. <BR><font color=\"Blue\">◄</font> قصر آش ؛ نام موضعی به اندلُس .<br /></font></div>'),
(1526, 'آش باوردی', '<span class=\"hlight\">آش باوردی .</span> <font color=\"DarkGreen\"><b>[ ش ِ وَ ]</font></b> (ترکیب وصفی، اِ مرکب ) قسمی آش منسوب به ابیورد.<br /></font></div>'),
(1527, 'آش برگ پزان', '<span class=\"hlight\">آش برگ پزان .</span> <font color=\"DarkGreen\"><b>[ ش ِ ب َ پ َ ]</font></b> (اِ مرکب ) احتفالی زنان را برای پختن آش برگ .<br /></font></div>'),
(1528, 'آش بچگان', '<span class=\"hlight\">آش بچگان .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ مرکب ) جندبیدستر. جندبادستر. قندزقوری . قندقیرس . (مخزن الادویه ). گندبیدستر. جندقضاعه . گندسکلابی . خایه ٔ سگ آبی . جندقندز. قسطور. قسطوریون <span class=\"hlight\">:</span> <br />جندبیدستر آش بچگانست <br />که کند دفع علت صبیان .<br /><font color=\"Red\">یوسفی طبیب .</font><br /></font></div>'),
(1529, 'آش جرد', '<span class=\"hlight\">آش جرد.</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (اِخ ) نام خره ای بخراسان نزدیک چغانیان . (از تاریخ سیستان ).<br /></font></div>'),
(1530, 'آش خوری', '<span class=\"hlight\">آش خوری .</span> <font color=\"DarkGreen\"><b>[ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ ]</font></b> (اِ مرکب ) ظرفی گود، میان باطیه و ماست خوری که در آن آش خورند. <BR><font color=\"Blue\">◄</font> کفچه ای که بدان آش گیرند.<br /></font></div>'),
(1531, 'آش قلعه', '<span class=\"hlight\">آش قلعه .</span> <font color=\"DarkGreen\"><b>[ ق َ ع َ ]</font></b> (اِخ ) نام محلی میان ایلیجا و مشاورک در راه تبریز به طرابوزان .<br /></font></div>'),
(1532, 'آش و آب', '<span class=\"hlight\">آش و آب .</span> <font color=\"DarkGreen\"><b>[ ش ُ ]</font></b> (اِ مرکب، از اتباع ) آش و جز آن . آش و مانند آش .<br /></font></div>'),
(1533, 'آش و لاش شدن', '<span class=\"hlight\">آش و لاش شدن .</span> <font color=\"DarkGreen\"><b>[ ش ُ ش ُ دَ ]</font></b> (مص مرکب ) متلاشی شدن . از هم پاشیدن، چنانکه مردار و جیفه ای . <BR><font color=\"Blue\">◄</font> سخت ریمناک و منبسط گشتن، چنانکه ریشی .<br /></font></div>'),
(1534, 'آش کشکی', '<span class=\"hlight\">آش کشکی .</span> <font color=\"DarkGreen\"><b>[ ش ِ ک َ کی ]</font></b> (ص نسبی ) آش ِکشک فروش . <BR><font color=\"Blue\">◄</font> آلوده به آش کشک . <BR><font color=\"Blue\">◄</font> در تداول خانگی، بی سروپا.<br /></font></div>'),
(1535, 'آش گرد', '<span class=\"hlight\">آش گرد.</span> <font color=\"DarkGreen\"><b>[ گ ِ ]</font></b> (اِخ ) رجوع به آش جرد شود.<br /></font></div>'),
(1536, 'آشا', '<span class=\"hlight\">آشا.</span> (پسوند)در بعض فرهنگها و ازجمله شرفنامه بدان معنی مثل و مانند و نظایر آن داده اند، و ظاهراً مصحف آسا باشد.<br /></font></div>'),
(1537, 'آشاب', '<span class=\"hlight\">آشاب .</span> (اِ مرکب ) آشام . آبچلو. آبریس .<br /></font></div>'),
(1538, 'آشام', '<span class=\"hlight\">آشام .</span> (اِ) نوشیدنی . مشروب . شربت <span class=\"hlight\">:</span> <br />همه زرّ و پیروزه بد جامشان <br />بروشن گلاب اندر آشامشان .<br /> <font color=\"Red\">فردوسی .</font><br />حسرت فروخورم چو بسینه فروشود<br />آشام خون دل کنم آن را فروبرم .<br /> <font color=\"Red\">خاقانی .</font><br />چون نتوانم که نفس را رام کنم <br />خود را چه بهرزه شهره ٔ عام کنم <br />زایل نشود تیرگی خاطر من <br />گر چشمه ٔ خور فی المثل آشام کنم .<br /> <font color=\"Red\">امیرخسرو.</font><br />آشام خود بزخم زبان میخورد عوان <br />آری درندگان همه آب از زبان خورند.<br /><font color=\"Red\">سیدحسین اخلاطی .</font><br /></font></div>'),
(1539, 'آشام', '<span class=\"hlight\">آشام .</span> (نف مرخم ) مخفف آشامنده، در کلمات مرکبه ٔ خون آشام، دردی آشام، غم آشام، می آشام و جز آن <span class=\"hlight\">:</span> <br />شب عنبرین هندوی بام اوی <br />شفق دردی آشام از جام اوی .<br /> <font color=\"Red\">فردوسی .</font><br />اصطناعت چو آب جان پرور<br />انتقامت چو خاک خون آشام .<br /> <font color=\"Red\">انوری .</font><br />درآ در بزم رندان غم آشام <br />ز شادی صاف شو دردِ غم آشام .<br /> <font color=\"Red\">سراج راجی .</font><br />ای ترک می آشام که گفتت که می آشام <br />در خانه ٔ من باده بیاشام بیا شام <br />خوف است بطاعتگه زهاد ریاکیش <br />امن است بسرمنزل رندان می آشام .<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> (اِ)باندازه ٔ یک بار آشامیدن . شربه . جرعه : یک آشام شیر. <BR><font color=\"Blue\">◄</font> آبچلو. آشاب . آبریس . <BR><font color=\"Blue\">◄</font> و فرهنگ جهانگیری بکلمه معنی قوت (و هو ما یقوم به بدن الانسان من الطعام . صراح ) داده و از شاعری مجهول به نام استاد بیت ذیل را شاهد آورده است <span class=\"hlight\">:</span> <br />بملک شام ندْهم تار مویت <br />ندارم گرچه گاه شام آشام .<br /><BR><font color=\"Blue\">◄</font> (اِمص ) در بعض فرهنگها به معنی آشامیدن و چیز کم خوردن و شرب و تجرّع نیز آمده است .<br /></font></div>'),
(1540, 'آشام', '<span class=\"hlight\">آشام .</span> (اِمص ) جذب مایع. (فرهنگستان ).<br /></font></div>'),
(1541, 'آشام', '<span class=\"hlight\">آشام .</span> (اِخ ) نام ولایتی میان مشرق و شمال بنگاله . و عود آن بخوبی شهرت دارد.<br /></font></div>'),
(1542, 'آشامان', '<span class=\"hlight\">آشامان .</span> (نف، ق ) در حال ِ آشامیدن .<br /></font></div>'),
(1543, 'آشامانیدن', '<span class=\"hlight\">آشامانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) نوشانیدن . اِسقاء.<br /></font></div>'),
(1544, 'آشامنده', '<span class=\"hlight\">آشامنده .</span> <font color=\"DarkGreen\"><b>[ م َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) نوشنده . شارب . خورنده ٔ مایعی .<br /></font></div>'),
(1545, 'آشامیدن', '<span class=\"hlight\">آشامیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) بلعیدن یعنی فروبردن مایعی . نوشیدن . نوش کردن . درکشیدن . کشیدن . گساردن (در شراب ). آشمیدن . پیمودن (باده ). خوردن . حسو. (دهار). شرب . تکرّع . تجرّع . تشرّب . احتسا. تَرَمﱡق <span class=\"hlight\">:</span> حصیری ... می آمد دُردی آشامیده . (تاریخ بیهقی ).<br />تا بی ادبی همی توانی کرد<br />خون علما بدم بیاشامی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تا تشنه و بیطاقت بچاهی رسید قومی بر او گرد آمده هر شربتی به پشیزی همی آشامیدند. (سعدی ).<br /></font></div>'),
(1546, 'آشامیدنی', '<span class=\"hlight\">آشامیدنی .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ص لیاقت ) درخور آشامیدن . سزاوار نوشیدن . <BR><font color=\"Blue\">◄</font> که نوشیدن آن بتوان . <BR><font color=\"Blue\">◄</font> که نوشیدن آن واجب است . <BR><font color=\"Blue\">◄</font> (اِ) آنچه آشامند. مقابل خوردنی . شراب . مشروب . شربت . حسو. (دهار). نوشیدنی . شروب .<br /></font></div>'),
(1547, 'آشامیده', '<span class=\"hlight\">آشامیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) نوشیده .<br /></font></div>'),
(1548, 'آشانه', '<span class=\"hlight\">آشانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) آشیانه <span class=\"hlight\">:</span> <br />زهی عرش مجید آشانه ٔ تو<br />زهی هفت آسمان یک خانه ٔ تو.<br /><font color=\"Red\">عطار.</font><br /></font></div>'),
(1549, 'آشاک', '<span class=\"hlight\">آشاک .</span> (اِخ ) نام باستانی خبوشان (قوچان ) است و آن را آرسکا و استو و استوا نیز میخوانده اند.<br /></font></div>'),
(1550, 'آشب', '<span class=\"hlight\">آشب .</span> <font color=\"DarkGreen\"><b>[ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ْ ]</font></b> (اِخ ) نام سردسیری از طالقان ری، و در آن برفهای سنگین افتد.<br /></font></div>'),
(1551, 'آشب', '<span class=\"hlight\">آشب .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِخ ) نام قلعه ای بزرگ بموصل از قلاع هکاریه و آن را زنگی بن آق سنقر ویران کرد و در عوض قلعه ٔ عمادیه را به نزدیکی آن برآورد.<br /></font></div>'),
(1552, 'آشتالنگ', '<span class=\"hlight\">آشتالنگ .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ) اَشتالنگ . شتالنگ . کعب <span class=\"hlight\">:</span> <br />صفات ... آن کودک چه گویم خود که آن کودک <br />همه ...است و... و... ز سر تا آشتالنگش .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(1553, 'آشتوه', '<span class=\"hlight\">آشتوه .</span> (اِ) نام درختی .<br /></font></div>'),
(1554, 'آشتی', '<span class=\"hlight\">آشتی .</span> (اِ) (از پهلوی آشتیه ) دوستی از نو کردن . ترک جنگ . رنجشی را از کسی فراموش کردن . صلح . مصالحه . سلم . مسالمه . موادعه . هدنه . مهادنه . سازش . مقابل جنگ و پنداشتی و حرب <span class=\"hlight\">:</span> <br />چو از آشتی شادی آید بچنگ <br />خردمند هرگز نکوشد بجنگ .<br /> <font color=\"Red\">ابوشکور.</font><br />ز جنگ آشتی بی گمان بهتر است <br />نگه کن که گاوت بچرم اندر است .<br /> <font color=\"Red\">فردوسی .</font><br />ترا آشتی بهتر آید ز جنگ <br />فراخی مکن بر دل خویش تنگ .<br /> <font color=\"Red\">فردوسی .</font><br />کسی نیست بی آز و بی نام و ننگ <br />همان آشتی بهتر آید ز جنگ .<br /> <font color=\"Red\">فردوسی .</font><br />بجنگ آنگهی شو که دشمن ز جنگ <br />بپرهیزد و سست گرددْش چنگ <br />وگر آشتی جوید و راستی <br />نبینی بدلْش اندرون کاستی <br />از او باژ بستان و کینه مجوی <br />نگه دار او را همی آبروی .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت لشکر که فرمان تراست <br />بدین آشتی رای و پیمان تراست <br />فرستاده را نغز پاسخ دهیم <br />بر این آشتی رای فرخ نهیم .<br /> <font color=\"Red\">فردوسی .</font><br />نبد آشتی پیش از آوردشان <br />بدین روز گرز من آوردشان .<br /> <font color=\"Red\">فردوسی .</font><br />گر ایدون که با شهریار جهان <br />همی آشتی جوئی اندر نهان <br />ترا اندرین مرز مهمان کنم <br />بچیزی که جوئی تو پیمان کنم .<br /> <font color=\"Red\">فردوسی .</font><br />گر او جنگ را خواهد آراستن <br />هزیمت بود آشتی خواستن .<br /> <font color=\"Red\">فردوسی .</font><br />سران یک بیک پاسخ آراستند<br />همه خوبی و آشتی خواستند.<br /> <font color=\"Red\">فردوسی .</font><br />دگر آنکه جستی همه آشتی <br />بسی روز با پند بگذاشتی .<br /> <font color=\"Red\">فردوسی .</font><br />چو آیم مرا با شما نیست رزم <br />بدل آشتی دارم و رای بزم .<br /> <font color=\"Red\">فردوسی .</font><br />ترا جنگ با آشتی گر یکیست <br />خرد بی گمان نزد تو اندکیست .<br /> <font color=\"Red\">فردوسی .</font><br />همه آشتی گردد این جنگ ما<br />بدین رزمگه کردن آهنگ ما.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت خاقان برو پیش اوی <br />سخن هرچه باید همه نرم گوی <br />اگر آشتی خواهد و دستگاه <br />چه بایدبر این دشت رنج سپاه ؟<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت رستم که ای شهریار<br />مجوی آشتی در گه کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />از این آشتی جنگ بهر من است <br />همه نوش تو درد و زهر من است .<br /> <font color=\"Red\">فردوسی .</font><br />بسی آشتی خواستم پیش جنگ <br />نکرد آشتی چون نبودش درنگ .<br /> <font color=\"Red\">فردوسی .</font><br />بپرسید از آن پس که با ساوه شاه <br />کنم آشتی یا فرستم سپاه <br />چنین داد پاسخ بدو جنگجوی <br />که با ساوه شاه آشتی نیست روی .<br /> <font color=\"Red\">فردوسی .</font><br />چو نتوان گرفتن گریبان جنگ <br />سوی دامن آشتی یاز چنگ <br />بهر کار در زور کردن مشور<br />که چاره بسی جای بهتر ز زور.<br /> <font color=\"Red\">اسدی .</font><br />سزای جنگند اینها که آشتی کردند<br />نگر که اکنون با من همی عتاب کنند.<br /> <font color=\"Red\">مسعودسعد.</font><br />گرگ را با میش باشد آشتی بر پهن دشت <br />باز را با کبک باشد دوستی در کوهسار.<br /> <font color=\"Red\">معزی .</font><br />عدل وانصاف تو اندر بیشه ٔ ایران زمین <br />آشتی داده است با شیر ژیان روباه را.<br /> <font color=\"Red\">معزی .</font><br />ز دنیا برم زنگ ناداشتی <br />دهم بادرا با چراغ آشتی .<br /> <font color=\"Red\">نظامی .</font><br />نه دانش باشد آنکس را نه فرهنگ <br />که وقت آشتی پیش آورد جنگ .<br /> <font color=\"Red\">نظامی .</font><br />جرم بر خود نه که تو خود کاشتی <br />با جزاو عدل حق کن آشتی .<br /> <font color=\"Red\">مولوی .</font><br />بیا که نوبت صلح است و آشتی ّ و عنایت <br />بشرط آنکه نگوئیم از گذشته حکایت .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> سازواری و صفای دوستی ذات البین که پس از تافتگی و دل آزردگی و سرگرانی و دژمی و پنداشتی و رنجیدگی میان دو دوست یا دو خویشاوند و مانند آن پدیدار آید <span class=\"hlight\">:</span> <br />چو رای آیدت آشتی با پدر<br />بسازم ترا تاج و تخت و کمر.<br /><font color=\"Red\">فردوسی .</font><br />چو بنمائی بدل پنداشتی را<br />بمانی جای لختی آشتی را.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />نگارا نه همه پنداشتی کن <br />زمانی دوستی ّ و آشتی کن .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />همه کارش آشوب و پنداشتی است <br />از او آشتی جنگ و جنگ آشتی است .<br /> <font color=\"Red\">اسدی .</font><br />مرابا شما کرده شد آشتی <br />نباشد کنون خشم و پنداشتی .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بود در جهان جنگ و پنداشتی <br />ولیکن از آن پس بود آشتی .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />ولیکن نه هنگام پنداشتی است <br />که هنگام مهر و گه آشتی است .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> وفق . توفیق . وفاق . جمع میان دو عقیده و یا دو رای که صورةً مخالف نمایند. <BR><font color=\"Blue\">◄</font> آرامش <span class=\"hlight\">:</span> <br />کسی کآشتی جوید و سور و بزم <br />نه نیکو بود تیز رفتن برزم .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشتی جستن </span> ؛ آشتی خواستن . استرضا. صلح طلبیدن . استعتاب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشتی دادن </span> ؛ اصلاح . سازواری بخشیدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشتی کردن </span> ؛ اصلاح . اصطلاح .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">پدر کشتی و تخم کین کاشتی </span> <br />پدرکشته کی می کند آشتی ؟<br /> <span class=\"hlight\">تا مرا دُم، ترا پسر یاد است </span> <br />آشتی ّ من و تو بر باد است .<br /> <font color=\"Red\">؟</font><br /> <span class=\"hlight\">جنگ از سر شخم آشتی از سر خرمن </span> .<br /> <span class=\"hlight\">ز جنگ آشتی بیگمان بهتر است </span> .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1555, 'آشتی خواره', '<span class=\"hlight\">آشتی خواره .</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) حلوا یا طعام دیگر یا دعوتی که پس از آشتی دو تن، آن دو با دوستان دیگر در یک جای صرف کنند. حلوای آشتی .<br /></font></div>'),
(1556, 'آشتی پذیر', '<span class=\"hlight\">آشتی پذیر.</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (نف مرکب ) قابل صلح . لایق وفق .<br /></font></div>'),
(1557, 'آشتی پذیری', '<span class=\"hlight\">آشتی پذیری .</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (حامص مرکب ) قابلیت وفق . قابلیت اصلاح .<br /></font></div>'),
(1558, 'آشتی کنان', '<span class=\"hlight\">آشتی کنان .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِمص مرکب ) عمل آشتی کردن . احتفال برای آشتی دادن و آشتی کردن .<br /></font></div>'),
(1559, 'آشتیان', '<span class=\"hlight\">آشتیان .</span> (اِخ ) یکی از سه قصبه ٔ مَحال ّ ثلاث (تفرش و گرگان و آشتیان ) از خره ٔ عراق بشمال شرقی فراهان، و صابون آن بخوبی مشهور است .<br /></font></div>'),
(1560, 'آشتینه', '<span class=\"hlight\">آشتینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) تخم مرغ . مرغانه . بیضه . خایه (در مرغ ). و آن را آستینه و آشینه نیز ضبط کرده اند.<br /></font></div>'),
(1561, 'آشخال', '<span class=\"hlight\">آشخال .</span> (اِ) آخال . سقط. افکندنی . نابکار. آشغال . حثاله .<br /></font></div>'),
(1562, 'آشخال برچین', '<span class=\"hlight\">آشخال برچین .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (نف مرکب ) آشغال برچین . آنکه در کویها چیزهای نابکار چیند تا از فروش یا بکار بردن آن سود برد. <BR><font color=\"Blue\">◄</font> سخت فقیر. سخت ناچیز. سخت فرومایه .<br /></font></div>'),
(1563, 'آشخانه', '<span class=\"hlight\">آشخانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) مطبخ . آشپزخانه . تنورخانه . باورچی خانه . <BR><font color=\"Blue\">◄</font> رستوران .<br /></font></div>'),
(1564, 'آشخانه', '<span class=\"hlight\">آشخانه .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) نام محلی در راه بجنورد بگنبدقابوس میان دربند و قره مصلی در <span class=\"hlight\" dir=\"rtl\">٣٥٥٤٣٠</span>گزی مشهد.<br /></font></div>'),
(1565, 'آشدار', '<span class=\"hlight\">آشدار.</span> (نف مرکب ) (از: آش، لعابی که بر روی ظروف سفالین و فلزین دهند + دار، مخفف دارنده ) لعابدار <span class=\"hlight\">:</span> <br />صحن کاشی کاریش را گاه لنگر فوته بین <br />هرکه را باشد تمنا سیر صحن آشدار.<br /> <font color=\"Red\">اشرف .</font><br />ز کاشی پرده و چینی سقرلات <br />ز صحن آشدار و طاس گجرات .<br /> <font color=\"Red\">اشرف .</font><br /><BR><font color=\"Blue\">◄</font> آهاردار.<br /></font></div>'),
(1566, 'آشر', '<span class=\"hlight\">آشر.</span> <font color=\"DarkGreen\"><b>[ ش ِ]</font></b> (ع اِ) خاری که در هر یک از دو ساق ملخ است . <BR><font color=\"Blue\">◄</font> گرهی مانند دو چنگال که در سر دم آن است .<br /></font></div>'),
(1567, 'آشردن', '<span class=\"hlight\">آشردن .</span> <font color=\"DarkGreen\"><b>[ ش ُ دَ ]</font></b> (مص ) آشوردن .<br /></font></div>'),
(1568, 'آشرمه', '<span class=\"hlight\">آشرمه .</span> <font color=\"DarkGreen\"><b>[ ش ُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ) زین و برگ . یراق اسب . <BR><font color=\"Blue\">◄</font> نمدزین .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشرمه دریده </span> ؛ بی سروپا، و آن دشنامی است . و رجوع به آدرم و آدرمه و اترمه شود.<br /></font></div>'),
(1569, 'آشرمه دوز', '<span class=\"hlight\">آشرمه دوز.</span> <font color=\"DarkGreen\"><b>[ ش ُم َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (نف مرکب ) آنکه حرفتش آشرمه دوختن است .<br /></font></div>'),
(1570, 'آشرمه دوزی', '<span class=\"hlight\">آشرمه دوزی .</span> <font color=\"DarkGreen\"><b>[ ش ُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (حامص مرکب ) حرفت آشرمه دوز. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) دکان آشرمه دوز.<br /></font></div>'),
(1571, 'آشره', '<span class=\"hlight\">آشره .</span> <font color=\"DarkGreen\"><b>[ ش ِ رَ ]</font></b> (ع ص ) چوب شکافته .<br /></font></div>'),
(1572, 'آشغال', '<span class=\"hlight\">آشغال .</span> (اِ) فضول چیزی :آشغال سبزی . آشغال کلّه . <BR><font color=\"Blue\">◄</font> سقط. نابکار. افکندنی . آخال . آشخال . خاش و خش . خش و خاش . خاشک . خاشاک . خاش و خماش . خماشه . خماش . آقال . داس و دلوس . حثاله . خس . <BR><font color=\"Blue\">◄</font> دَم ِ جارو. خاکروبه . قمامه .<br /></font></div>'),
(1573, 'آشغال برچین', '<span class=\"hlight\">آشغال برچین .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (نف مرکب ) آشخال برچین . آنکه خاش و خش از معابر برچیند چون پاره های جامه و خرده های چوب و پوست انار و مانند آن و با فروش آن معاش او باشد. <BR><font color=\"Blue\">◄</font> مجازاً و بتحقیر، سخت بی سروپا.<br /></font></div>'),
(1574, 'آشغال کله', '<span class=\"hlight\">آشغال کله .</span> <font color=\"DarkGreen\"><b>[ ک َل ْ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ]</font></b> (اِ مرکب ) افکندنیها از استخوانهای خرده و غضروفها و مانند آن از طعام موسوم به کیپا و کله پاچه . <BR><font color=\"Blue\">◄</font> (ص مرکب ) سخت بی ارز. بسی بی سروپا (مردم ).<br /></font></div>'),
(1575, 'آشغالدان', '<span class=\"hlight\">آشغالدان .</span> (اِ مرکب ) جای آشغال . ظرف آشغال .<br /></font></div>'),
(1576, 'آشفتن', '<span class=\"hlight\">آشفتن .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ ]</font></b> (مص ) خشم گرفتن . غضب کردن . خشمگین شدن . تیز شدن . از جا دررفتن . تافته شدن <span class=\"hlight\">:</span> <br />ز خاقان مقاتوره آمد بخشم <br />یکایک برآشفت و بگشاد چشم .<br /> <font color=\"Red\">فردوسی .</font><br />بروز چهارم برآشفت شاه <br />بر آن موبدان نماینده راه <br />که گر زنده تان دار باید بسود...<br /> <font color=\"Red\">فردوسی .</font><br />همه یاد کرد آن کجا رفته بود<br />که شاه اردوان از چه آشفته بود.<br /> <font color=\"Red\">فردوسی .</font><br />چو آن نامه برخواند پیروزشاه <br />برآشفت از آن نامور پیشگاه <br />فرستاده را گفت برخیز و رو<br />به نزدیک آن مرد بی مایه شو.<br /> <font color=\"Red\">فردوسی .</font><br />چو بشنید پیغام او ساوه شاه <br />برآشفت از آن سنگدل رزمخواه .<br /> <font color=\"Red\">فردوسی .</font><br />برآشفت از آن اسب او شهریار<br />جهاندیدگان را همه کرد خوار.<br /> <font color=\"Red\">فردوسی .</font><br />چو بشنید بیژن برآشفت سخت <br />کزو شاه را تیره شد روی بخت .<br /> <font color=\"Red\">فردوسی .</font><br />سیاوش بدانست کاین کار اوست <br />برآشفتن شاه بازار اوست .<br /> <font color=\"Red\">فردوسی .</font><br />برآشفت ماننده ٔ پیل مست <br />یکی گرزه ٔ گاوپیکر بدست .<br /> <font color=\"Red\">فردوسی .</font><br />ز دین مسیحا برآشفت شاه <br />سپاهی فرستاد بی مر براه <br />همی گفت پیغمبری کش جهود<br />کشد، دین او را نباید ستود.<br /> <font color=\"Red\">فردوسی .</font><br />بسهراب گفت این چه آشفتن است <br />همه با من از رستمت گفتن است .<br /> <font color=\"Red\">فردوسی .</font><br />مرا خود ز گیتی گه رفتن است <br />نه هنگام تیزی ّ و آشفتن است .<br /> <font color=\"Red\">فردوسی .</font><br />برآشفت کشواد از آن نامدار<br />ز بس گرمیش شد فسرده شرار.<br /> <font color=\"Red\">فردوسی .</font><br />شنیدم که از نیکمردی فقیر<br />دل آزرده شد پادشاه کبیر<br />مگر بر زبانش حقی رفته بود<br />ز گردنکشی بر وی آشفته بود.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> برآشوبیدن . شوریدن . شورش کردن . انقلاب <span class=\"hlight\">:</span> <br />همی ریخت خون سر بیگناه <br />ازآن پس برآشفت بر وی سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />بعد از آن ترکان بر متوکل بیاشفتند و قصد کردندبر کشتن او. (مجمل التواریخ ). پس پرویز همه بزرگان را بند کرد و بفرمود کشتن و ایشان مقداری هزار مرد بودند از مهتران عجم تا ایرانیان بیاشفتند و پسرش شیروی را از زندان بشب اندر بیرون آوردند و بپادشاهی بنشاندند. (مجمل التواریخ ). <BR><font color=\"Blue\">◄</font> بهم برآمدن . رنجیدن از. سرگران شدن با <span class=\"hlight\">:</span> <br />چو بشنید رستم برآشفت ازوی <br />بدو گفت ای باب پرخاشجوی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> بهیجان آمدن . آتشی شدن <span class=\"hlight\">:</span> <br />وصف عشق و عاشقان گفتن گرفت <br />وز کمال عشق آشفتن گرفت .<br /> <font color=\"Red\">عطار.</font><br /> <BR><font color=\"Blue\">◄</font> مضطرب شدن . پریشان خیال گشتن . مشوش شدن . اضطراب . (حبیش تفلیسی ). آلفتن . کالفتن . بشولیدن <span class=\"hlight\">:</span> <br />که او را ستاره شمر گفته بود<br />ز گفتار ایشان برآشفته بود<br />که باشد ترا زندگانی سه بیست <br />چهارم بمرگت بباید گریست .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتن چشم </span> ؛ بهم خوردن آن . سرخی و یا آبریزش در آن پدید آمدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتن دریا</span> ؛ انقلاب آن .ارتجاج .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتن لانه ٔ زنبور و جز آن </span> ؛ زبرزیر کردن آن با چوبی و مانند آن برهم زدن آن . رجوع به آشوفتن شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتن موی و دستار</span> ؛ ژولیده و شوریده شدن آن <span class=\"hlight\">:</span> <br />صوفی سرخوش از این دست که کج کرد کلاه <br />بدو جام دگر آشفته شود دستارش .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتن هوا</span> ؛ باد سخت یا ابر سیاه یا برف با بوران پدید آمدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">دستار کل که برآشفت تاجان بکوشد</span> .<br /> <BR><font color=\"Blue\">◄</font> پریشان شدن . درهم و برهم شدن . کراشیده گشتن . کراشیدن . (تحفةالاحباب اوبهی ). <BR><font color=\"Blue\">◄</font> تغییر به بدی . بدل شدن از حسن به قبح <span class=\"hlight\">:</span> <br />چنین بود تا شد بزرگیش راست <br />بر آن چیز بر، پادشه شد که خواست <br />برآشفت و خوی بد آورد پیش <br />بیک سو شد از راه و آئین خویش .<br /> <font color=\"Red\">فردوسی .</font><br />داده آن صورت و آن هیکل آبادان <br />روی زی زشتی و آشفتن و ویرانی .<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتن باد</span> ؛ سخت وزیدن آن : از آشفتن باد، چوب سراپرده بر سرش افتاده و از آن بمرد. (مجمل التواریخ ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتن بر</span> ؛ شیفته شدن به . عاشق گشتن به <span class=\"hlight\">:</span> <br />همی گفت هر زن که جفت عزیز<br />گهر بود کردش زمانه پشیز<br />بیاشفت بر بنده ٔ خویشتن <br />نه دل پاک مانده ست وی را، نه تن <br />بصد دل بر او عاشق و مبتلاست ...<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />لفظ و معنی بیکدگر جفت است <br />زآن خرد بر خطش بیاشفته ست .<br /> <font color=\"Red\">سنائی .</font><br />اگر خود هفت سبع از بر بخوانی <br />چو آشفتی الف بی تی ندانی .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتن روزگار و زمانه </span> ؛ برگشتن آن . ادبار بخت <span class=\"hlight\">:</span> <br />چون روزگار برتو بیاشوبد<br />یک چند پیشه کن تو شکیبائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />پیش زمانه چو برآشفته شد<br />خوار شود همچو عدو آشناش .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> مصدر دیگر آن آشوب است . آشفتم . بیاشوب .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1577, 'آشفته', '<span class=\"hlight\">آشفته .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) خشمگین . بخشم آمده . مقابل آهسته <span class=\"hlight\">:</span> <br />گهی آرمده و گه آرغده <br />گهی آشفته و گه آهسته .<br /> <font color=\"Red\">رودکی .</font><br />میغ چون ترکی آشفته که تیر اندازد<br />برق تیر است مر اورا مگر و رخش کمان .<br /> <font color=\"Red\">فرالاوی .</font><br />بگفت آنچه خاقان بدو گفته بود<br />که از کین آن کشته آشفته بود.<br /> <font color=\"Red\">فردوسی .</font><br />بگفتش بدو آن کجا رفته بود<br />چو خاقان ورا دید کآشفته بود.<br /> <font color=\"Red\">فردوسی .</font><br />پراندیشه شد شاه یزدان پرست <br />ز خون ریختن دست گردان ببست <br />چو مهر جهانجوی پیوسته شد<br />دل مرد آشفته آهسته شد.<br /> <font color=\"Red\">فردوسی .</font><br />سیاوش بگفت آن کجا رفته بود<br />وز آن کو ز سودابه آشفته بود.<br /> <font color=\"Red\">فردوسی .</font><br />سپهبد شد آشفته از گفت اوی <br />نشد پند بهرام یل جفت اوی .<br /> <font color=\"Red\">فردوسی .</font><br />بگفت آنچه با پیلتن گفته بود<br />ز طوس و ز کاووس کآشفته بود.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> ارغنده . آرغده <span class=\"hlight\">:</span> <br />که هرگز ندیدم بدینسان دلیر<br />نه ببر بیان و نه آشفته شیر.<br /> <font color=\"Red\">فردوسی .</font><br />نگه کرد برزو بدان ده سوار<br />چو شیران آشفته در کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />سپهدار قارن چه آشفته پیل <br />زمین کرد از خون چو دریای نیل .<br /> <font color=\"Red\">فردوسی .</font><br />چو آشفته شد شیر و تندی نمود<br />سر نیزه را سوی او کرد زود.<br /> <font color=\"Red\">فردوسی .</font><br />شیر ارغنده اگر پیش تو آید بنبرد<br />پیل آشفته اگر گرد تو آید بجدال ...<br /> <font color=\"Red\">فرخی .</font><br />همی آمد آشفته چون پیل مست <br />ببازو کمانی ّ و نیزه بدست .<br /> <font color=\"Red\">اسدی .</font><br />تاج در میان دو شیر آشفته نهادند بر تخت و بهرام با گرز برفت و شیر را بکشت و بر تخت نشست . (مجمل التواریخ ). <BR><font color=\"Blue\">◄</font> کراشیده . ریخته و پاشیده . درهم وبرهم . زَبَرزیر. شلوغ پلوغ . شوریده و گوریده . کالفته . مختلط. آشوفته <span class=\"hlight\">:</span> <br />برآنگونه سودابه را خفته دید <font color=\"DarkGreen\"><b>[ کاوس ]</font></b><br />سراسر شبستان برآشفته دید.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> متفرق . پراکنده . پریشان <span class=\"hlight\">:</span> <br />سپهبدان بر، آشفته لشکری گشتند<br />چنانکه خواهند از هر سوئی همی رانند.<br /> <font color=\"Red\">مسعودسعد.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفته شدن موی سر</span> ؛ شعث . شعثان . ناخوار شدن آن <span class=\"hlight\">:</span> <br />زلف آشفته و خوی کرده و خندان لب و مست <br />پیرهن چاک و غزلخوان و صراحی دردست <br />نرگسش عربده جوی و لبش افسوس کنان <br />نیم شب دوش ببالین من آمد بنشست .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دریائی آشفته </span> ؛ منقلب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">موئی آشفته </span> ؛ ژولیده . پریشان . گوریده . وژگال . شوریده . کالیده .<br /> <BR><font color=\"Blue\">◄</font> شیدا. (فرهنگ اسدی ). کالیوه . کالُفته . توسعاً، عاشق <span class=\"hlight\">:</span> <br />دل برد و چون بدانست کم کرد ناشکیبا<br />بگریخت تا چنینم آشفته کرد و شیدا.<br /> <font color=\"Red\">دقیقی .</font><br />عاشق آشفته فرمان چون برد<br />درد درمانسوز درمان چون برد؟<br /> <font color=\"Red\">عطار.</font><br />کسانی که آشفته ٔ دلبرند<br />بری از غم خویش و از دیگرند.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> مضطرب . مشوش . بهم برآمده <span class=\"hlight\">:</span> <br />پدر گفتش ای نازنین چهر من <br />چه داری دل آشفته در مهر من ؟<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> شوریده . شورانیده <span class=\"hlight\">:</span> محمدبن الحصین القوسی شهر بر او آشفته همی داشت . (تاریخ سیستان ). <BR><font color=\"Blue\">◄</font> مختل . باختلال . بفسادگرائیده . ازصحت بگشته <span class=\"hlight\">:</span> <br />بیمار بد این ملکت زو دور طبیب او<br />آشفته شده طبعش هم مائی و هم ناری .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> کاسد. بی رونق <span class=\"hlight\">:</span> <br />جهانا چه بدمهر و بدخو جهانی <br />چو آشفته بازار بازارگانی .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> شلوغ . پر از قطاع الطریق . نامأمون . غیرایمن (راه ) <span class=\"hlight\">:</span> راهها ناایمن شده است ... و راه از نشابور تا اینجا سخت آشفته است . (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> بطپش . باضَربان .مشوش <span class=\"hlight\">:</span> <br />همه دشت از ایشان پر از خفته دید<br />یکایک دل لشکر آشفته دید.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مضطرب . مشوَّش، چنانکه عبارتی یا تاریخی <span class=\"hlight\">:</span> و حمزة الاصفهانی روایت کند که هیچ تواریخ آشفته تر از حمیریان نبوده است از بسیاری سالهای ایشان . (مجمل التواریخ ). <BR><font color=\"Blue\">◄</font> بی نظم و نسق .بی انضباط. با هرج و مرج . بَلبشو <span class=\"hlight\">:</span> <br />جهانم بی تو آشفته ست یک سر<br />چنان چون بی امیر آشفته لشکر.<br /> <font color=\"Red\">(ویس و رامین ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">دزد بازار آشفته میخواهد</span>.<br /><BR><font color=\"Blue\">◄</font> ژولیده موی . ژولیده یال . گردآلوده . اشعث .اغبر <span class=\"hlight\">:</span> <br />ببودند بر در زمانی بپای <br />بپرسید از او آن دو پاکیزه رای <br />که بیگه چنین از کجا رفته اید<br />که با گرد راهید و آشفته اید.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد جهانجوی را خفته دید<br />برِ او یکی اسب آشفته دید.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> شوریده . گوریده، چنانکه دستار و عمامه <span class=\"hlight\">:</span> <br />ساقی مگر وظیفه ٔ حافظ زیاده داد<br />کآشفته گشت طره ٔ دستار مولوی ؟<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفته شدن اختر بر کسی </span> ؛ بنحوست گراییدن آن <span class=\"hlight\">:</span> <br />بپیروز بر اختر آشفته شد<br />نه بر کام ما شاه تو کشته شد.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفته کردن سخن </span> ؛ تلجلج .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفته کردن کار</span> ؛ شوریدن کار. ارتثاء. تلبیس .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفته گفتن </span> ؛ آمیخته گفتن . تبکل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خواب آشفته </span> ؛ خواب شوریده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خوابهای آشفته </span> ؛ اضغاث احلام . خوابهای شوریده . خوابهای پریشان <span class=\"hlight\">:</span> <br />ندانند تعبیر خوابم همی <br />باحلام گویند جوابم همی <br />به آشفته خوانند خواب مرا<br />خطا گفته اند آن صواب مرا.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">دور از شتر بخواب، خواب آشفته مبین </span> .<br /></font></div>'),
(1578, 'آشفته', '<span class=\"hlight\">آشفته .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ ]</font></b> (اِخ ) تخلص شاعری از مردم ایروان بزمان ناصرالدین شاه، نامش حسین .<br /></font></div>'),
(1579, 'آشفته بخت', '<span class=\"hlight\">آشفته بخت .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِب َ ]</font></b> (ص مرکب ) شقی . بدبخت . بشوریده بخت <span class=\"hlight\">:</span> <br />بدو گفت کای ترک آشفته بخت <br />بگرداد از تو همه تاج و تخت .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1580, 'آشفته حال', '<span class=\"hlight\">آشفته حال .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) مجذوب . شوریده در اصطلاح صوفیان <span class=\"hlight\">:</span> <br />ندانی که آشفته حالان مست <br />چرا برفشانند در رقص دست <br />گشاید دری بر دل از واردات <br />فشاند سر دست بر کائنات (کذا).<br /> <font color=\"Red\">سعدی .</font><br />مکن عیب آشفته حالان مست <br />که غرق است، از آن میزند پا و دست .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> پریشان و بی بضاعت <span class=\"hlight\">:</span> <br />بدیدار مسکین و آشفته حال .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1581, 'آشفته حالی', '<span class=\"hlight\">آشفته حالی .</span> <font color=\"DarkGreen\"><b>[ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) چگونگی و صفت آشفته حال .<br /></font></div>'),
(1582, 'آشفته خاطر', '<span class=\"hlight\">آشفته خاطر.</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ طِ ]</font></b> (ص مرکب ) پریشان خاطر.<br /></font></div>'),
(1583, 'آشفته خاطری', '<span class=\"hlight\">آشفته خاطری .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ طِ ]</font></b> (حامص مرکب ) پریشان خاطری .<br /></font></div>'),
(1584, 'آشفته خوی', '<span class=\"hlight\">آشفته خوی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) تُندخوی .<br /></font></div>'),
(1585, 'آشفته خویی', '<span class=\"hlight\">آشفته خویی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) تندخویی .<br /></font></div>'),
(1586, 'آشفته دل', '<span class=\"hlight\">آشفته دل .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ دِ ]</font></b> (ص مرکب ) پریشان خاطر.<br /></font></div>'),
(1587, 'آشفته دلی', '<span class=\"hlight\">آشفته دلی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ دِ ]</font></b> (حامص مرکب ) پریشان خاطری .<br /></font></div>'),
(1588, 'آشفته دماغ', '<span class=\"hlight\">آشفته دماغ .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ دِ ]</font></b> (ص مرکب )دیوانه . مختل در عقل . معتوه . مخبط. <BR><font color=\"Blue\">◄</font> پریشان حواس . آشفته عقل . <BR><font color=\"Blue\">◄</font> غمین <span class=\"hlight\">:</span> <br />آشفته دماغم سر و برگ سخنم نیست .<br /><font color=\"Red\">طالب آملی .</font><br /></font></div>'),
(1589, 'آشفته دماغی', '<span class=\"hlight\">آشفته دماغی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِدِ ]</font></b> (حامص مرکب ) حالت و چگونگی و صفت آشفته دماغ .<br /></font></div>'),
(1590, 'آشفته رای', '<span class=\"hlight\">آشفته رای .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) آنکه مصمم نتواند شدن . مردد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفته رای شدن </span> ؛ تغییق .<br /></font></div>'),
(1591, 'آشفته رایی', '<span class=\"hlight\">آشفته رایی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) چگونگی و حالت آشفته رای .<br /></font></div>'),
(1592, 'آشفته رنگ', '<span class=\"hlight\">آشفته رنگ .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ رَ ]</font></b> (ص مرکب ) آنکه ظاهرالصلاح نباشد <span class=\"hlight\">:</span> <br />در اوباش، پاکان آشفته رنگ <br />همان جای تاریک و لعل است و سنگ .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1593, 'آشفته رنگی', '<span class=\"hlight\">آشفته رنگی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ رَ ]</font></b> (حامص مرکب ) حالت و چگونگی آشفته رنگ .<br /></font></div>'),
(1594, 'آشفته روز', '<span class=\"hlight\">آشفته روز.</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) شقی . بدبخت <span class=\"hlight\">:</span> <br />بگفت ای ستمکار آشفته روز...<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1595, 'آشفته روزگار', '<span class=\"hlight\">آشفته روزگار.</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ص مرکب ) آشفته روز <span class=\"hlight\">:</span> <br />دست نوازشی چو بزلف آشنا کنی <br />غافل مشو ز صائب آشفته روزگار.<br /><font color=\"Red\">صائب .</font><br /></font></div>'),
(1596, 'آشفته روزگاری', '<span class=\"hlight\">آشفته روزگاری .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِزْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (حامص مرکب ) چگونگی و حال آشفته روزگار.<br /></font></div>'),
(1597, 'آشفته روزی', '<span class=\"hlight\">آشفته روزی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) شقاوت . بدبختی .<br /></font></div>'),
(1598, 'آشفته سامان', '<span class=\"hlight\">آشفته سامان .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) فقیر. <BR><font color=\"Blue\">◄</font> شوریده . مجذوب (باصطلاح صوفیه و عرفا) <span class=\"hlight\">:</span> <br />نه بم داند آشفته سامان نه زیر<br />به آواز مرغی بنالد فقیر.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1599, 'آشفته سامانی', '<span class=\"hlight\">آشفته سامانی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span>ت ِ ]</font></b> (حامص مرکب ) چگونگی و حال و صفت آشفته سامان .<br /></font></div>'),
(1600, 'آشفته شدن', '<span class=\"hlight\">آشفته شدن .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ش ُ دَ ]</font></b> (مص مرکب ) اهیجاج .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفته شدن کار</span> ؛ ایتلاخ . التباس . ارتجان .<br /></font></div>'),
(1601, 'آشفته عقل', '<span class=\"hlight\">آشفته عقل .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ع َ ]</font></b> (ص مرکب ) آشفته دماغ .<br /></font></div>'),
(1602, 'آشفته عقلی', '<span class=\"hlight\">آشفته عقلی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ع َ ]</font></b> (حامص مرکب ) آشفته دماغی .<br /></font></div>'),
(1603, 'آشفته مغز', '<span class=\"hlight\">آشفته مغز.</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ م َ ]</font></b> (ص مرکب ) آشفته دماغ .<br /></font></div>'),
(1604, 'آشفته مغزی', '<span class=\"hlight\">آشفته مغزی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ م َ ]</font></b> (حامص مرکب ) آشفته دماغی .<br /></font></div>'),
(1605, 'آشفته موی', '<span class=\"hlight\">آشفته موی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) کالیده موی . ژولیده موی . اشعث . شَعثاء.<br /></font></div>'),
(1606, 'آشفته مویی', '<span class=\"hlight\">آشفته مویی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) کالیده مویی . ژولیده موئی .<br /></font></div>'),
(1607, 'آشفته هوش', '<span class=\"hlight\">آشفته هوش .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) پریشان حواس <span class=\"hlight\">:</span> <br />بدو گفتم ای یار آشفته هوش <br />شگفت آمد این داستانم بگوش .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1608, 'آشفته هوشی', '<span class=\"hlight\">آشفته هوشی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) پریشان حواسی .<br /></font></div>'),
(1609, 'آشفتگی', '<span class=\"hlight\">آشفتگی .</span> <font color=\"DarkGreen\"><b>[ ش ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص )کیفیت و چگونگی و صفت آشفته . خشم . غضب <span class=\"hlight\">:</span> <br />نیاطوس چون دیدبنداخت نان <br />ز آشفتگی بازپس شد ز خوان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> اختلال <span class=\"hlight\">:</span> ابتداء آشفتگی دولت بنی العباس اندر سال سیصدوهشت بود پس از هر نواحی اضطراب خاست و شکوه ایشان کم شد. (مجمل التواریخ ). <BR><font color=\"Blue\">◄</font> هرج و مرج <span class=\"hlight\">:</span> چون آشفتگی برخاست بعد از وفات سلطان، دبیس بن صَدَقه در حدود عراق تغلب کرد... (مجمل التواریخ ). <BR><font color=\"Blue\">◄</font> عشق . وَلَه ْ. شیفتگی <span class=\"hlight\">:</span> <br />پس آنگه زلیخا بر ایشان نمود<br />کز آشفتگی داستانْشان چه بود.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> جنون <span class=\"hlight\">:</span> <br />پس آشفتگی باشد و ابلهی <br />که انگشت بر حرف صنعش نهی .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتگی آبی </span> ؛ برهم خوردگی و اختلاط آن با رسوب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتگی چشم </span> ؛ برهم خوردگی و دردگین شدن آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتگی دریا</span> ؛ اضطراب و انقلاب و تلاطم و طوفان آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتگی موی </span> ؛ کالیدگی آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشفتگی هوا</span> ؛ انقلاب آن . باد یا ابر سیاه یا برف و بوران در آن پیدا آمدن .<br /></font></div>'),
(1610, 'آشمالی', '<span class=\"hlight\">آشمالی .</span> (حامص مرکب ) تملق .تَبصبُص . چاپلوسی . دُم لابه . خوش آمدگوئی <span class=\"hlight\">:</span> <br />می کند دم لابه ها تا استخوانی میخورد<br />عمر او در آشمالی ّ و خوش آمد میرود.<br /> <font color=\"Red\">شفائی .</font><br /><BR><font color=\"Blue\">◄</font> قلتبانی . کشخانی .<br /></font></div>'),
(1611, 'آشموغ', '<span class=\"hlight\">آشموغ .</span> (اِخ ) نام دیویست از پیروان آهرمن که سخن چینی و دروغ گفتن از کسی بدیگری و جنگ افکندن میان دو تن شغل اوست . برای امثله رجوع به آسموغ شود.<br /></font></div>'),
(1612, 'آشمیدن', '<span class=\"hlight\">آشمیدن .</span> <font color=\"DarkGreen\"><b>[ ش َ دَ ]</font></b> (مص ) مخفف آشامیدن <span class=\"hlight\">:</span> <br />خوش دل شد و آرمید با او<br />هم خوردو هم آشمید با او.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(1613, 'آشنا', '<span class=\"hlight\">آشنا.</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِ) آشناه . شنا. شناو. شناه . شناوری . سباحت . آب بازی <span class=\"hlight\">:</span> <br />آشنا ورزمی ز اشک دو چشم <br />اگرم چشم آشنا باشد.<br /> <font color=\"Red\">مسعودسعد.</font><br />هر وهم که هست کی تواند<br />در بحر مدیحت آشنا کرد؟<br /> <font color=\"Red\">مسعودسعد.</font><br />مانند زنگئی که بر آتش همی طپد<br />زلفش در آب دیده همی کرد آشنا.<br /> <font color=\"Red\">معزی .</font><br />در چشمه ٔ وزارت و در بحر مملکت <br />ماند به آشنای پدر آشنای تو.<br /> <font color=\"Red\">معزی .</font><br />از تو بودم به آستانه ٔ خواجه عارف معرفت <br />وز تو کردم در فرات نعمت او آشنا.<br /> <font color=\"Red\">سنائی .</font><br />غرقه ٔ دریای حیرت خواستی گشتن ولیک <br />آشنائی ما برونْت آورد از او بی آشنا.<br /> <font color=\"Red\">سنائی .</font><br />بر سر دریا چو از کاهی کمم در آشنا<br />با گهر در قعر دریا آشنائی چون کنم ؟<br /> <font color=\"Red\">سنائی .</font><br />بیگانه باد با تو غم و آشنا طرب <br />در بحر لهوباد و طرب آشنای تو.<br /> <font color=\"Red\">سوزنی .</font><br />با علم آشنا شو و از آب بر سر آی <br />کز آب بر سر آمدن از علم آشناست .<br /> <font color=\"Red\">کمال .</font><br />هر دو بحری آشناآموخته <br />هر دو جان بی دوختن بردوخته .<br /> <font color=\"Red\">مولوی .</font><br />آن سکون سابح اندر آشنا<br />به ز جهد اعجمی با دست و پا.<br /> <font color=\"Red\">مولوی .</font><br />هیچ دانی آشنا کردن بگو<br />گفت نی از من تو سباحی مجو.<br /> <font color=\"Red\">مولوی .</font><br />همچو کنعان کآشنا میکرد او<br />که نخواهم کشتی نوح عدو.<br /> <font color=\"Red\">مولوی .</font><br />کاشکی او آشنا ناموختی <br />تا طمع در نوح و کشتی دوختی .<br /> <font color=\"Red\">مولوی .</font><br />دلت را با غم عشقش به معنی آشنائی ده <br />که تن را آشنا کردن نمی شاید در این دریا.<br /><font color=\"Red\">سلمان .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مردِ آشنا</span> ؛ سباح <span class=\"hlight\">:</span> <br />تا دل من در هوای نیکوان شد آشنا<br />در سرشک دیده گردانم چو مرد آشنا.<br /> <font color=\"Red\">رودکی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشنا ورزیدن </span> ؛ آشنا کردن . سباحت .<br /> <BR><font color=\"Blue\">◄</font> در غالب فرهنگها به کلمه ٔ آشنا معنی شناور و سابح داده اند و بیت ابوشکور را مثال آورده اند <span class=\"hlight\">:</span> <br />کسی کاندر آبست و آب آشناست <br />از آب ار چو زآتش بترسد رواست .<br />و این بی شبهه غلط است چه در این بیت آشنا بمعنی عارف و شناساست و با ترکیب با آب معنی عارف بشنا و داننده ٔ شناوری داده است و کلمه ٔ آشنا بانفراده به معنی شناور و سباح نیامده است .<br /></font></div>'),
(1614, 'آشنا', '<span class=\"hlight\">آشنا.</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص ) آشنای . معروف . مأنوس . مألوف . گستاخ . نزدیک . اُلفت گرفته . مستأنس بتعارف . پیوسته . بسته . شناسا. شناسنده . مقابل بیگانه، ناآشنا، غریب <span class=\"hlight\">:</span> <br />تا دل من در هوای نیکوان شد آشنا<br />در سرشک دیده گردانم چو مرد آشنا.<br /> <font color=\"Red\">رودکی .</font><br />غریبی گرچه باشد پادشائی <br />بگریدچون ببیند آشنائی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بخدمت همی آمدم سوی تو<br />مگر با سعادت شوم آشنا.<br /> <font color=\"Red\">لامعی .</font><br />بر سخن حجت مگزین سخن <br />زآنکه خرد با سخنش آشناست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />با علم اگر آشنا شوی تو<br />با زهد بیابی آشنائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گرافلاک جمله لطیفند پس <br />بگو گر خرد با دلت آشناست ...<br /> <font color=\"Red\">ناصرخسرو.</font><br />دانی که چون شدم چو ز دیوان گریختم <br />ناگاه با فریشتگان آشنا شدم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />انده چرا برم چو تحمل ببایدم <br />روی از که بایدم که کسی نیست آشنا؟<br /> <font color=\"Red\">مسعودسعد.</font><br />سایه با ذات آشنا باشد<br />سایه از ذات کی جداباشد؟<br /> <font color=\"Red\">سنائی .</font><br />و هرگاه که متقی در کار این جهان گذرنده تأملی کند هرآینه مقابح آن را بنظر بصیرت بیند... و سخاوت را با خود آشنا گرداند. (کلیله و دمنه ).<br />بیگانه باد با تو غم و آشنا طرب <br />در بحر لهو باد و طرب آشنای تو.<br /> <font color=\"Red\">سوزنی .</font><br />با علم آشنا شو و از آب بر سر آی <br />کز آب بر سر آمدن از علم آشناست .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />چو تو با علم آشنا گشتی <br />بگذری زآب نیز بی کشتی .<br /> <font color=\"Red\">اوحدی .</font><br />بدریای جودت کند آشنا<br />چه بیگانه مردم چه شهرآشنا.<br /> <font color=\"Red\">ابراهیم فاروقی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آواز او مرا آشنا می آید</span> ؛ چنان مینماید که صاحب آن را می شناسم .<br />فعل آن آشنا آمدن و آشنا شدن و آشنا کردن و آشنا گردانیدن است .<br /> <BR><font color=\"Blue\">◄</font> خویش . قریب <span class=\"hlight\">:</span> <br />با نبی بود آشنا بیگانه چون شد بولهب <br />وز حبش بیگانه آمد آشنا چون شد بلال ؟<br /> <font color=\"Red\">معزی .</font><br /> <BR><font color=\"Blue\">◄</font> دوست . یار<span class=\"hlight\">:</span> <br />چون آشنات باشد ابلیس مکرپیشه <br />با زرق و مکر یابی ناچار آشنائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بنشست و نرم نرم همی گفت زارزار<br />با آشنا چنین نکند هیچ آشنا.<br /> <font color=\"Red\">معزی .</font><br />من از بیگانگان هرگز ننالم <br />که با من هرچه کرد آن آشنا کرد.<br /> <font color=\"Red\">حافظ.</font><br />خلقم اگر آشنای خود میخواهند<br />الحق سپر بلای خود میخواهند.<br /> <font color=\"Red\">فدائی لاهیجی .</font><br />ترک و حدیث دوستی قصه ٔ آب و آتش است <br />گرگ بگله آشنا می شود این نمیشود.<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> آنکه او ترا شناسد و تو او را شناسی و هنوز دوستی و انسی در میان شما نیست . دوست نو. یار نو. <BR><font color=\"Blue\">◄</font> معرّف . معدّل . مزکّی <span class=\"hlight\">:</span> <br />اگر پیش تو بگذارم گوایان <br />بیارم با گوایان آشنایان <br />دو چشم سیل بارم آشنایش <br />دو مرد آشنا بادو گوایش <br />بزر اندوده بینی دو گوایم <br />بخون آلوده بینی آشنایم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> عارف به کاری .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب آشنا</span>؛ عارف بکار آب بازی <span class=\"hlight\">:</span> <br />کسی کاندر آب است و آب آشناست <br />از او گرچه آتش بترسد رواست .<br /> <font color=\"Red\">ابوشکور.</font><br /> <BR><font color=\"Blue\">◄</font> موافق . سازگار. سازوار. ملایم <span class=\"hlight\">:</span> <br />هر دو در تابخانه ای رفتیم <br />که نبود آشنا هوای رواق .<br /> <font color=\"Red\">انوری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشنا شدن با کسی </span> ؛ بار اول او را دیدن و با او گفتگوکردن و بیکدیگر خود را شناسانیدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشنا شدن بعلمی یا صنعتی </span> ؛ اندکی فراگرفتن آن . آموختن آن نه بکمال .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشنا کردن </span> ؛ معرفی کردن کسی را بدیگری .<BR>۩ نزدیک کردن نه بدان حد که بُرَد (کارد، شمشیر و امثال آن ): خنجر را بگلوی او آشنا کرد. شمشیر را به گردن اوآشنا کرد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آشنا داند زبان آشنا</span> .<br /><span class=\"hlight\">با کسی آشنا نمی گردم </span> <br />چون شدم آشنا، نمی گردم .<br /> <font color=\"Red\">؟</font><br /> <span class=\"hlight\">عیسات دوست به که حواریت آشنا</span> .<br />که ناید هرگز از گرگ آشنائی .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(1615, 'آشنا', '<span class=\"hlight\">آشنا.</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِخ ) تخلص شاعری پارسی سرای هندوستانی، موسوم به میرزا محمدطاهر، پسر نواب ظفرخان احسان که بنام عنایت خان معروف بوده . اشعار او را با عنوان کلیات آشنا جمع کرده اند. در مدح شاه جهان و داراشکوه قصاید بسیار دارد و<span class=\"hlight\" dir=\"rtl\">١٠٧٧</span> هَ .ق . درگذشته است . <BR><font color=\"Blue\">◄</font> تخلص شاعر فارسی گوی هندی موسوم به غیاث الدین متوفی بسنه ٔ <span class=\"hlight\" dir=\"rtl\">١٠٧٣</span> هَ .ق . و احتمال میرود این دونام عنایت و غیاث یکی مصحف دیگری باشد. واﷲ اعلم .<br /></font></div>'),
(1616, 'آشناروی', '<span class=\"hlight\">آشناروی .</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) روشناس . دلنشین . دلپذیر. مقابل دشمن روی <span class=\"hlight\">:</span> <br />آشناروی دیده ٔ عرفان <br />گر نداری ز عارفان بستان .<br /> <font color=\"Red\">سنائی .</font><br />در این عهد از وفا بویی نمانده ست <br />بعالم آشنارویی نمانده ست .<br /> <font color=\"Red\">خاقانی .</font><br />بنالم کآرزوبخشی ندیدم <br />بگریم کآشنارویی ندارم .<br /> <font color=\"Red\">خاقانی .</font><br />روز و شب آورده ام در معنی بیگانه روی <br />چون کنم صائب ندارم آشناروی دگر.<br /><font color=\"Red\">صائب .</font><br /></font></div>'),
(1617, 'آشناه', '<span class=\"hlight\">آشناه .</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِ) شناه . آشنا. شنا. سباحت <span class=\"hlight\">:</span> <br />بزرگان بدانش بیابند راه <br />ز دریا گذر نیست بی آشناه .<br /> <font color=\"Red\">فردوسی .</font><br />چو بشنید آوازش افراسیاب <br />همانگه برآمد ز دریای آب <br />بدستش همی کرد و پای آشناه <br />بیامد بجائی که بد پایگاه .<br /> <font color=\"Red\">فردوسی .</font><br />بدست چپ و پای کرد آشناه <br />بدیگر ز دشمن همی جست راه .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1618, 'آشناو', '<span class=\"hlight\">آشناو.</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِ) آشنا. آشناه . شناه . شناوری . سباحت .<br /></font></div>'),
(1619, 'آشناور', '<span class=\"hlight\">آشناور.</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ وَ ]</font></b> (ص مرکب ) شناور. آشناگر. شناگر. آب باز. سابح . سَبّاح <span class=\"hlight\">:</span> <br />روان اندر او کشتی و خیره مانده <br />ز پهنای او دیده ٔ آشناور.<br /> <font color=\"Red\">فرخی .</font><br />بریگ اندر همی شد مرد تازان <br />چو در غرقاب مرد آشناور.<br /> <font color=\"Red\">لبیبی .</font><br />آن آشناوشی که خیال است نام او<br />در موج آب دیده ٔ من آشناور است .<br /> <font color=\"Red\">سیدحسن غزنوی .</font><br />آن قَدَر دستی که خرچنگ قضا<br />آشناور در محیط نام اوست .<br /> <font color=\"Red\">عمادی شهریاری .</font><br />آشناور شود خرد در خون <br />جان بجان کندن افکند بکنار.<br /> <font color=\"Red\">عمادی شهریاری .</font><br />دلبسته ٔ روزگار پرزرق شدن <br />یا شیفته ٔ حیات چون برق شدن <br />چون مردم آشناور اندر گرداب <br />دستی زدنست و بعد از آن غرق شدن .<br /><font color=\"Red\">سیدحسن اشرف .</font><br /></font></div>'),
(1620, 'آشناوری', '<span class=\"hlight\">آشناوری .</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ وَ ]</font></b> (حامص مرکب ) شناوری . سباحت .<br /></font></div>'),
(1621, 'آشناگر', '<span class=\"hlight\">آشناگر.</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ گ َ ]</font></b> (ص مرکب ) شناگر. آشناور. شناور. سباح . آب باز.<br /></font></div>'),
(1622, 'آشناگری', '<span class=\"hlight\">آشناگری .</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ گ َ ]</font></b> (حامص مرکب ) شناوری . سباحت .<br /></font></div>'),
(1623, 'آشنایی', '<span class=\"hlight\">آشنایی .</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (حامص ) آشنائی . تعارف . معارفه . معرفت . عرفان . شناخت . شناسائی . قرب . نزدیکی . الفت . انس . استیناس . مقابل بیگانگی <span class=\"hlight\">:</span> <br />از ایران و توران جدایی نبود<br />که با جنگ و کین آشنایی نبود.<br /> <font color=\"Red\">فردوسی .</font><br />نه من با پدر بیوفایی کنم <br />نه با اهرمن آشنایی کنم .<br /> <font color=\"Red\">فردوسی .</font><br />بدان راستی دل گوایی دهد<br />مرا با پسر آشنایی دهد.<br /> <font color=\"Red\">فردوسی .</font><br />به آغاز آن آشنایی نخست <br />همی از رد و موبدان رای جست .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت بهرام شیرین سخُن <br />که با مردگان آشنائی مکن .<br /> <font color=\"Red\">فردوسی .</font><br />بهستی ّ یزدان گوایی دهیم <br />روان را بدین آشنایی دهیم .<br /> <font color=\"Red\">فردوسی .</font><br />با علم اگر آشنا شوی تو<br />با زهد بیابی آشنایی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بر سر دریا چو از کاهی کمم در آشنا<br />با گهر در قعر دریا آشنایی چون کنم ؟<br /> <font color=\"Red\">سنائی .</font><br />غرقه ٔ دریای حیرت خواستی گشتن ولیک <br />آشنایی ما برونْت آورد از او بی آشنا.<br /> <font color=\"Red\">سنائی .</font><br />من آن روز از خویش بیگانه گشتم <br />که افتاد با تو مرا آشنایی .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />در مقامی که آشنایی نیست <br />بهتر از عقل روشنایی نیست .<br /> <font color=\"Red\">اوحدی .</font><br />دلت را با غم عشقش به معنی آشنای ده <br />که تن را آشنا کردن نمی شاید در این دریا.<br /> <font color=\"Red\">سلمان ساوجی .</font><br />یار بگزید بیوفایی را<br />رفت و بُبْرید آشنایی را.<br /> <font color=\"Red\">کمال خجند.</font><br />دلت را با غم عشقش به معنی آشنایی ده <br />که تن را آشنا کردن نمی شاید در این دریا.<br /> <font color=\"Red\">سلمان ساوجی .</font><br />فغان که نیست بجز عیب یکدگر جستن <br />نصیب مردم عالم ز آشنایی هم .<br /> <font color=\"Red\">صائب .</font><br />زآن سیه دل کز حقوق آشنایی غافل است <br />بهتر است آن سگ که پای آشنا نگرفته است .<br /> <font color=\"Red\">صائب .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشنایی دادن </span> ؛ خود را شناسانیدن . خود را معرفی کردن : الاستعراف ؛ آشنائی فادادن . (مجمل اللغه ).<br />یکی سوی روح الامین بنگرید <font color=\"DarkGreen\"><b>[ یوسف ]</font></b><br />ندانست کو از کجاشد پدید<br />همی چهر وی را شگفتی نمود<br />ندانست وی را که نادیده بود<br />بپرسید و گفت ای همایون بچهر<br />چه خلقی که دارد دلم بر تو مهر<br />ورا جبرئیل آشنایی بداد<br />به پیغام یزدان زبان برگشاد.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">آشنایی روشنائیست </span> ؛ معرفت، دوم ْ بینائیست .<br /></font></div>'),
(1624, 'آشو', '<span class=\"hlight\">آشو.</span> (نف مرخم ) مخفف آشوب . (جهانگیری ) <span class=\"hlight\">:</span> <br />ز باغ عافیت بویی ندارم <br />که دل گم گشت و دلجویی ندارم <br />فلک پل بر دلم خواهد شکستن <br />کز آب عافیت جویی ندارم <br />بسازم مجلسی از سایه ٔ خویش <br />که آنجا مجلس آشوئی ندارم .<br /> <font color=\"Red\">خاقانی .</font><br />و ظاهراً آشو فقط در صورت ترکیب معنی بخشد و استعمال آن به تنهائی و انفراد بسته به یافته شدن شواهد دیگر است . و در بعض فرهنگها معنی هیاهو و آشفتن باین کلمه داده اند و به همین بیت استشهاد کرده اند و این غلط است، چه آشو یا آشوی فقط معنی فاعلی میدهد نه معنی اسمی و مصدری .<br /></font></div>'),
(1625, 'آشوب', '<span class=\"hlight\">آشوب .</span> (اِمص، اِ) (اسم مصدر آشفتن و آشوفتن : آشفتم . بیاشوب ) اختلاف . فتنه . فساد. تباهی <span class=\"hlight\">:</span> <br />بفر و هیبت شمشیر تو قرار گرفت <br />زمانه ای که پرآشوب بود پالاپال .<br /> <font color=\"Red\">دقیقی .</font><br />وزآن پس چنین گفت افراسیاب <br />که بد در جهان اندرآمد بخواب <br />از این پس نه آشوب خیزد نه جنگ <br />به آبشخور آید گوزن و پلنگ .<br /> <font color=\"Red\">فردوسی .</font><br />ز آشوب وز جنگ روی زمین <br />بیاساید و راه جوید بدین .<br /> <font color=\"Red\">فردوسی .</font><br />وزآن پس پرآشوب گردد جهان <br />شود نام و آواز او در نهان .<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ <font color=\"DarkGreen\"><b>[ خسروپرویز را ]</font></b> ستاره شمر<br />که بر چرخ گردون نیابی گذر<br />از این کودک <font color=\"DarkGreen\"><b>[ شیروی ]</font></b> آشوب گیرد زمین <br />نخواند سپاهش بر او آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />نه کاوس خواهد ز من نیز کین <br />نه آشوب گیرد سراسر زمین .<br /> <font color=\"Red\">فردوسی .</font><br />ز هاماوران زآن پس اندیشه کرد<br />که برخیزد آشوب و جنگ و نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />بایران هر آنگه که آسود شاه <br />بهر کشوری برندارد سپاه <br />بیاید ز هر جای دشمن بکین <br />پرآشوب گردد سراسر زمین .<br /> <font color=\"Red\">فردوسی .</font><br />ما را رمه بانیست نه زو در گله آشوب <br />نه ایمن از او گرگ و نه سگ زو بفغان است .<br /> <font color=\"Red\">منوچهری .</font><br />نه آشوب گیتی به هنگام تست <br />که تابد همیدون بدست از نخست .<br /> <font color=\"Red\">اسدی .</font><br />پس مردمان را مرگ رسول علیه السلام حقیقت شد و غریو و گریستن از آن جمع برخاست و خلاف و آشوب درافتاد تا بسقیفه ٔ بنی ساعده پس از گفت و گوی با ابوبکر بیعت کردند. (مجمل التواریخ ).<br />ز کفر زلف تو هر حلقه ای ّ و آشوبی <br />ز سحر چشم تو هر گوشه ای ّ و بیماری .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> مخفف مایه ٔ آشوب <span class=\"hlight\">:</span> آشوب قندهار؛ چنانکه گویند فتنه ٔ چین و رشک پری، غیرت حور و مانند آن : برنائی نوخط، آشوب زنان و فتنه ٔ مردان . (کلیله و دمنه ).<br />آشوب عقلم آن شبه ٔ عاج مفرش است .<br /> <font color=\"Red\">سیدحسن غزنوی .</font><br /> <BR><font color=\"Blue\">◄</font> هیاهو. ضوضاء. ضوضا. مشغله . غوغا. شور و غوغا. جلب . جلبه <span class=\"hlight\">:</span> <br />چو آشوب برخاست از انجمن <br />چنین گفت سهراب با پیلتن .<br /> <font color=\"Red\">فردوسی .</font><br />مرد بیگانه را دید با زن او بهم نشسته، دشنام و سقط گفت و فتنه و آشوب برخاست . (گلستان ).<br />مویت رها مکن که چنین درهم اوفتد <br />کآشوب چین زلف تو در عالم اوفتد.<br /> <font color=\"Red\">سعدی .</font><br />مست بگذشتی و از خلوتیان ملکوت <br />بتماشای تو آشوب قیامت برخاست .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> خلل . هرج و مرج <span class=\"hlight\">:</span> <br />سپاهی نباید که با پیشه ور<br />بیک روی جویند هر دو هنر...<br />چو این کار آن جوید آن کار این <br />پرآشوب گردد سراسر زمین .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> اختلال . آشفتگی <span class=\"hlight\">:</span> <br />آشوب عقلم آن شبه ٔ عاج مفرش است <br />نقل امیدم آن شکر پسته پیکر است .<br /> <font color=\"Red\">سیدحسن غزنوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشوب دریا</span> ؛ طغیان . تلاطم . انقلاب . طوفان و آشفتگی آن <span class=\"hlight\">:</span> مروارید نیکوتر شودبوقت بهار که دریا از آشوب آرام گیرد. (نزهةالقلوب حمداﷲ مستوفی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشوب کردن بر سر یا دماغ </span> ؛ اختلال زادن در آن <span class=\"hlight\">:</span> <br />خیالش چنان بر سر آشوب کرد<br />که بام دماغش لگدکوب کرد.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> ازدحام . زحام <span class=\"hlight\">:</span> <br />در آن کین و آشوب و دار و بکُش <br />نه با اسب زور و نه با مرد هُش .<br /> <font color=\"Red\">فردوسی .</font><br />ببازیچه مشغول مردم شدم <br />وز آشوب خلق از پدر گم شدم .<br /> <font color=\"Red\">سعدی .</font><br />بدرجست از آشوب، دزد دغل <br />دوان جامه ٔ پارسا در بغل .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> انقلاب . شورش <span class=\"hlight\">:</span> <br />از آشوب گفت آنچه دید و شنید<br />جوان شد چو برگ گل شنبلید.<br /> <font color=\"Red\">فردوسی .</font><br />همه شب بدی خوردن آئین او <font color=\"DarkGreen\"><b>[ فرائین ]</font></b><br />دل مهتران پر شد از کین او...<br />دل آزرده زو گشت لشکر همه <br />پرآشوب وپردرد کشور همه .<br /> <font color=\"Red\">فردوسی .</font><br />بترسم از آشوب بدگوهران <br />بویژه ز گردان مازندران .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> انقلاب هوا. وزش سخت باد. طوفان بادی <span class=\"hlight\">:</span> <br />خوش نازکانه می چمی ای شاخ نوبهار<br />کآشفتگی مبادت از آشوب باد دی .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> مقابل آرام و سکون <span class=\"hlight\">:</span> <br />کنون راهبر باش بهرام را<br />پرآشوب کن روز آرام را.<br /> <font color=\"Red\">فردوسی .</font><br />زود از پی آرام پدید آیدآشوب <br />زود از پی آشوب پدید آید آرام .<br /> <font color=\"Red\">قطران .</font><br /> <BR><font color=\"Blue\">◄</font> در تداول عوام، منش گردا. غثیان : دلم آشوب است . <BR><font color=\"Blue\">◄</font> (نف مرخم ) مخفف آشوبنده در کلمات مرکبه از قبیل دل آشوب، شهرآشوب، لشکرآشوب و نظایر آن <span class=\"hlight\">:</span> <br />عالم افروز بهارا که توئی <br />لشکرآشوب سوارا که توئی .<br /> <font color=\"Red\">خاقانی .</font><br />فغان کاین لولیان شوخ شیرین کار شهرآشوب <br />چنان بردند صبر از دل که ترکان خوان یغما را.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(1626, 'آشوب', '<span class=\"hlight\">آشوب .</span> (اِخ ) تخلص شاعری از متأخرین از مردم طهران، معاصر صاحب مجمعالفصحاء. نام او ابوالقاسم بوده است . <BR><font color=\"Blue\">◄</font> شاعری مسمی بحسین از مردم مازندران که بهندوستان مهاجرت کرده . <BR><font color=\"Blue\">◄</font> شاعری از اهل همدان . <BR><font color=\"Blue\">◄</font> شاعری هندوستانی موسوم بمحمد بخش، و او در زمان شجاع الدوله و پسرش آصف الدوله میزیسته و دیوان او به فارسی در هند معروف و متداول است .<br /></font></div>'),
(1627, 'آشوب انگیز', '<span class=\"hlight\">آشوب انگیز.</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (نف مرکب ) فتنه انگیز.<br /></font></div>'),
(1628, 'آشوب انگیزی', '<span class=\"hlight\">آشوب انگیزی .</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (حامص مرکب ) فتنه انگیزی .<br /></font></div>'),
(1629, 'آشوب طلب', '<span class=\"hlight\">آشوب طلب .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (نف مرکب ) فتنه جو. انقلاب خواه .<br /></font></div>'),
(1630, 'آشوب طلبی', '<span class=\"hlight\">آشوب طلبی .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (حامص مرکب ) فتنه جوئی . انقلاب و شورش خواهی .<br /></font></div>'),
(1631, 'آشوب گر', '<span class=\"hlight\">آشوب گر.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (ص مرکب ) فتنه جوی . فتان .<br /></font></div>'),
(1632, 'آشوب گری', '<span class=\"hlight\">آشوب گری .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (حامص مرکب ) فتنه جوئی . فتّانی .<br /></font></div>'),
(1633, 'آشوب گستر', '<span class=\"hlight\">آشوب گستر.</span> <font color=\"DarkGreen\"><b>[ گ ُ ت َ ]</font></b> (نف مرکب ) فتّان <span class=\"hlight\">:</span> <br />چون موی زنگیش سیه و کوته است روز<br />از عشق ترک هندوی آشوب گسترش .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(1634, 'آشوب گستری', '<span class=\"hlight\">آشوب گستری .</span> <font color=\"DarkGreen\"><b>[ گ ُ ت َ ]</font></b> (حامص مرکب ) فتّانی .<br /></font></div>'),
(1635, 'آشوبش', '<span class=\"hlight\">آشوبش .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِمص ) آشوب <span class=\"hlight\">:</span> <br />از اختر بدینسان نشانی نمود<br />که آشوبش و جنگ بایست بود. <br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1636, 'آشوبناک', '<span class=\"hlight\">آشوبناک .</span> (ص مرکب ) پرآشوب .<br /></font></div>'),
(1637, 'آشوبناکی', '<span class=\"hlight\">آشوبناکی .</span> (حامص مرکب ) پرآشوبی .<br /></font></div>'),
(1638, 'آشوبنده', '<span class=\"hlight\">آشوبنده .</span> <font color=\"DarkGreen\"><b>[ ب َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) که بیاشوبد.<br /></font></div>'),
(1639, 'آشوبندگی', '<span class=\"hlight\">آشوبندگی .</span> <font color=\"DarkGreen\"><b>[ ب َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) کیفیت و چگونگی آشوبنده .<br /></font></div>'),
(1640, 'آشوبی', '<span class=\"hlight\">آشوبی .</span> (اِخ ) تخلص شاعری پارسی گوی از مردم هندوستان . و او خط نستعلیق را نیز بغایت نیکو می نوشته است .<br /></font></div>'),
(1641, 'آشوبیدن', '<span class=\"hlight\">آشوبیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آشفتن . آشفته کردن . <BR><font color=\"Blue\">◄</font> منقلب و متغیر شدن <span class=\"hlight\">:</span> <br />بایران رسد زین بدی آگهی <br />برآشوبد این روزگار بهی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> خشمگین و آشفته شدن <span class=\"hlight\">:</span> <br /><span class=\"hlight\" dir=\"rtl\">١</span>خواهم که بدانم من جانا تو چه خو داری <br />یا از چه برآشوبی یا از چه بیازاری .<br /> <font color=\"Red\">منوچهری .</font><br />بغرّد همچو اژدرها چو بر عالم بیاشوبد<br />ببارد آتش و دود از میان کام و دندانش . <br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> شور و غوغا کردن . <BR><font color=\"Blue\">◄</font> تفتین . افساد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشوبیدن مغز</span> ؛ پریشان کردن حواس <span class=\"hlight\">:</span> <br />پیل مستم مغزم از آهن بیاشوبند از آنک <br />گر بیاسایم دمی هندوستان یاد آورم .<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بهم برآشوبیدن </span> ؛ بهم ریختن در ستیز و آویز <span class=\"hlight\">:</span> <br />برآشوبد ایران و توران بهم <br />ز کینه شود زندگانی دژم .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1642, 'آشور', '<span class=\"hlight\">آشور.</span> (نف مرخم ) در کلمات مرکبه مثل دویت آشور و تنورآشور، مخفف آشورنده است، یعنی بهم زننده .<br /></font></div>'),
(1643, 'آشور', '<span class=\"hlight\">آشور.</span> (اِخ ) رجوع به آسوریان شود.<br /></font></div>'),
(1644, 'آشور', '<span class=\"hlight\">آشور.</span> (اِخ ) نام پسر دوم سام بن نوح، و مملکت آشور به نام او خوانده شده است .<br /></font></div>'),
(1645, 'آشور', '<span class=\"hlight\">آشور.</span> (اِخ ) نام رب النوع بزرگ آسوریان .<br /></font></div>'),
(1646, 'آشور بانی پال', '<span class=\"hlight\">آشور بانی پال .</span> (اِخ ) رجوع به آسور بانی پال شود.<br /></font></div>'),
(1647, 'آشوراده', '<span class=\"hlight\">آشوراده .</span> <font color=\"DarkGreen\"><b>[دِه ْ ]</font></b> (اِخ ) نام جزیره ای در خلیج استراباد در امتداد میانکاله در عرض شمالی <span class=\"hlight\" dir=\"rtl\">٣٦/٥٤</span> و طول شرقی <span class=\"hlight\" dir=\"rtl\">٥٣/٣٥</span>.<br /></font></div>'),
(1648, 'آشوران', '<span class=\"hlight\">آشوران .</span> (نف، ق ) در حال آشوردن .<br /></font></div>'),
(1649, 'آشوردن', '<span class=\"hlight\">آشوردن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آشوریدن . شورانیدن . درهم کردن . بر هم زدن . زبرزیر کردن . <BR><font color=\"Blue\">◄</font> آمیختن . مزج . <BR><font color=\"Blue\">◄</font> تخمیر. خمیر کردن . سرشتن . <BR><font color=\"Blue\">◄</font> آشفتن خواب کسی را، او رابدخواب کردن <span class=\"hlight\">:</span> مرا دل نیامد که ایشان را بیدار کنم و خواب بر ایشان بیاشورم . (تفسیر ابوالفتوح رازی ). و رجوع به آشور و دویت آشور و تنورآشور شود.<br /></font></div>'),
(1650, 'آشورده', '<span class=\"hlight\">آشورده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) شورانیده . درهم کرده .<br /></font></div>'),
(1651, 'آشورنده', '<span class=\"hlight\">آشورنده .</span> <font color=\"DarkGreen\"><b>[ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) که بیاشورد.<br /></font></div>'),
(1652, 'آشوره', '<span class=\"hlight\">آشوره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) هر آلت که بدان آشورند.<br /></font></div>'),
(1653, 'آشوری', '<span class=\"hlight\">آشوری .</span> (ص نسبی، اِ) رجوع به آسوریان شود. <BR><font color=\"Blue\">◄</font> (اِخ ) نام طائفه ای از مردم قزوین .<br /></font></div>'),
(1654, 'آشوریان', '<span class=\"hlight\">آشوریان .</span> (اِخ ) رجوع به آسوریان شود.<br /></font></div>'),
(1655, 'آشوریدن', '<span class=\"hlight\">آشوریدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) رجوع به آشوردن شود.<br /></font></div>'),
(1656, 'آشوریده', '<span class=\"hlight\">آشوریده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آشورده .<br /></font></div>'),
(1657, 'آشوریه', '<span class=\"hlight\">آشوریه .</span> <font color=\"DarkGreen\"><b>[ ری ی َ ]</font></b> (اِخ ) رجوع به آسوریان شود.<br /></font></div>'),
(1658, 'آشوغ', '<span class=\"hlight\">آشوغ .</span> (ص ) مجهول . غیرمعروف . ناشناس . نامعروف . (تحفةالاحباب اوبهی ). گمنام <span class=\"hlight\">:</span> <br />چه کنم از جفای دهر که من <br />هستم آشوغ در میان شما.<br /><font color=\"Red\">طرطری .</font><br /></font></div>'),
(1659, 'آشوفتن', '<span class=\"hlight\">آشوفتن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص ) آشفتن . برآشفتن . غضبناک و خشمگین گردیدن . بهم برآمدن <span class=\"hlight\">:</span> <br />نه مردی بود خیره آشوفتن <br />بزیراندرآورده را کوفتن .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بیکدیگر آشوفتن </span> ؛ خشم گرفتن یکی بر دیگری <span class=\"hlight\">:</span> <br />دلیران بیکدیگر آشوفتند<br />همی گرز بر یکدگر کوفتند.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> بهیجان آمدن . بهیجان آوردن <span class=\"hlight\">:</span> <br />چو لشکر سراسر برآشوفتند<br />بگرز و تبرزین همی کوفتند<br />سپاه اندرآمد ز جای کمین <br />سیه شد بر آن نامداران زمین .<br /> <font color=\"Red\">فردوسی .</font><br />بهو چون سپه دید کآشوفتند<br />بفرمود تا کوس کین کوفتند.<br /> <font color=\"Red\">اسدی .</font><br />لوت خوردند و سماع آغاز کرد<br />خانقه تا سقف شد پر دود و گرد<br />دود مطبخ گرد آن پا کوفتن <br />زاشتیاق و وجد و جان آشوفتن .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> منقلب شدن هوا و مانند آن <span class=\"hlight\">:</span> <br />ز بس گرز بر ترکها کوفتن <br />فتاد آسمان اندر آشوفتن .<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br /> <BR><font color=\"Blue\">◄</font> زیر و زبر شدن . رجوع به آشوفته شود. <BR><font color=\"Blue\">◄</font> برهم زدن با چوبی یا چیزی مانند آن توده ای را. زبرزیر کردن مجموعی را. آشوردن <span class=\"hlight\">:</span> <br />چو زنبور خانه برآشوفتی <br />گریز از محلت که گرم اوفتی .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> بهم خوردن، یعنی سرخ شدن و دردگن گشتن و رمد پدید آمدن (در چشم ) <span class=\"hlight\">:</span> <br />چشم بی شرم تو گر روزی برآشوبد ز درد<br />نوک خارش جا کشو باد ای دریده چشم و کون .<br /> <font color=\"Red\">منجیک .</font><br />اسم مصدر و مصدردوم آن آشوب است . آشوفتم . برآشوب .<br /></font></div>'),
(1660, 'آشوفته', '<span class=\"hlight\">آشوفته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آشفته . زیروزبرشده <span class=\"hlight\">:</span> <br />سپاهی همه خسته و کوفته <br />گریزان و سخت اندرآشوفته .<br /> <font color=\"Red\">فردوسی .</font><br />اگر کشتمندی شود کوفته <br />وزآن رنج کارنده آشوفته <br />وگر اسب در کشتزاری شود<br />کسی نیز بر میوه داری شود<br />دم اسب و گوشش بباید برید<br />سر دزد بر دار باید کشید.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1661, 'آشوفتگی', '<span class=\"hlight\">آشوفتگی .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص ) آشفتگی .<br /></font></div>'),
(1662, 'آشپز', '<span class=\"hlight\">آشپز.</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (نف مرکب ) آنکه شغلش پختن طعام است . خوالیگر. خوالگر. دیگ پز. مطبخی . طباخ . باورچی . پزنده . خوراک پز. خورده پز.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">آشپز که دو تا شد آش یا شور می شود یا بی مزه </span> .<br /></font></div>'),
(1663, 'آشپزباشی', '<span class=\"hlight\">آشپزباشی .</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (ص مرکب، اِ مرکب ) (از فارسی ِ آشپز، طباخ + ترکی ِ باشی، سر و رئیس ) رئیس طباخان .<br /></font></div>'),
(1664, 'آشپزخانه', '<span class=\"hlight\">آشپزخانه .</span> <font color=\"DarkGreen\"><b>[ پ َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ]</font></b> (اِ مرکب ) مطبخ . تنورخانه . آش خانه . باورچی خانه .<br /></font></div>'),
(1665, 'آشپزی', '<span class=\"hlight\">آشپزی .</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (حامص مرکب ) طباخی . خوالیگری . دیگپزی . پزندگی . خوراک پزی . طباخت . خورده پزی .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1666, 'آشکار', '<span class=\"hlight\">آشکار.</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص، ق، اِ) (از پهلوی آشکاراک ) ظاهر. بارز. مشهود. مرئی . روشن . هویدا. پیدا. پدید. پدیدار. مکشوف . جلی . جلیه . واضح . عیان . محسوس . مقابل مخفی، پنهان، نهان، ناپیدا، ناپدید، نهفته <span class=\"hlight\">:</span> <br />ازو دان فزونی ازو دان شمار<br />بد و نیک نزدیک او آشکار.<br /> <font color=\"Red\">فردوسی .</font><br />ز زخمش <font color=\"DarkGreen\"><b>[ زخم روزگار ]</font></b> همه خستگانیم زار<br />بود زخم پنهان و درد آشکار.<br /> <font color=\"Red\">اسدی .</font><br />هست ذرات خواطر وافتکار<br />پیش خورشید حقایق آشکار.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> رُک . بی پرده . صریح . واضح . علنی . پوست کنده . بی رودربایستی . علی رؤس الاشهاد <span class=\"hlight\">:</span> <br />سعدیا چندان که میدانی بگوی <br />حق نشاید گفتن الا آشکار.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> فاشی . فاش . ذایع. شایع. آشکارا. آشکاره <span class=\"hlight\">:</span><br />رازها را می کند حق آشکار<br />چون بخواهد رُست تخم بد مکار.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> علانیه . علن . مقابل رازو سر <span class=\"hlight\">:</span> <br />توئی کرده ٔ کردگار جهان <br />شناسی همی آشکار و نهان .<br /> <font color=\"Red\">فردوسی .</font><br />سِرّ تو دیگر بُد آشکار دگر<br />سِرّْ یکی بود و آشکار مرا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />مرا بعشق تو طشت ای پسر ز بام افتاد<br />چه راز ماند طشتی بدین خوش آوازی <br />خوش است عشق اگر آشکار یا راز است <br />خوش است با توام ار آشکار یا رازی .<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> ظاهر. مقابل نهان و باطن <span class=\"hlight\">:</span> <br />ای بهر بابی دو دست تو سخی تر زآسمان <br />ای نهان تو بهر کاری نکوتر زآشکار.<br /> <font color=\"Red\">فرخی .</font><br />سوی قوی نهان من از چشم دل نگر<br />غره مشو به سست و ضعیف آشکار من .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> مُبرز. مُبین . متجاهر. بیّن <span class=\"hlight\">:</span> <br />اگر هیچ دشمن ترا نیست کس <br />جهان دشمن آشکار است و بس .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> شهود. شهادت . مقابل غیب <span class=\"hlight\">:</span> <br />چنین است فرجام کار جهان <br />نداند کسی آشکار و نهان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> صورت، مقابل معنی <span class=\"hlight\">:</span> <br />از آن بِه ْ چه در آشکار و نهان <br />که آرد یکی چون خود اندر جهان ؟<br /> <font color=\"Red\">اسدی .</font><br /><BR><font color=\"Blue\">◄</font> حواس خمسه ٔ ظاهره <span class=\"hlight\">:</span> <br />بدین آشکارت ببین آشکار<br />نهانیت را برنهانی گمار.<br /> <font color=\"Red\">رودکی .</font><br /> <BR><font color=\"Blue\">◄</font> مخفف به آشکار. صورةً، مقابل معناً <span class=\"hlight\">:</span> <br />فریدون فرخ که او از جهان <br />بدی دور کرد آشکار و نهان .<br /> <font color=\"Red\">فردوسی .</font><br />برهنه بدی کآمدی در جهان <br />نبد با تو چیز آشکار و نهان .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> در جلوت، مقابل خلوت . جهراً، مقابل خفیةً. علانیةً. علناً، مقابل سِرّاً <span class=\"hlight\">:</span> <br />نویسند نامه بشاه جهان <br />سخن هرچه رفت آشکار و نهان .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکار شدن (گشتن )</span> ؛ ظاهر شدن . تجلی کردن . استبانه . ابانه . برح . براح . جلاء. انجلاء. و رجوع به معانی آشکار شود <span class=\"hlight\">:</span> <br />شاه چون خورشید رخشان است و دشمن چون شب است <br />شب شود پنهان چو گردد نور خورشید آشکار.<br /> <font color=\"Red\">معزی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکار کردن </span> ؛ اظهار. الاحه . تشهیر. ابداء. اعلان . (زوزنی ). فاش کردن . افشاء. بَوح . بدح . تجلیه . بث ّ. بیان . تأویل . تفسیر. تفصیل . ایضاح . اجهار. اشاعت . تشییع. اذاعه . جهره . جَهر. تصریح .(دهار). اشاعه . کشف . عرض . ابانه . اخفاء . تحصیل . بثاث . تبثیث . اعلان کردن . اظهار کردن . ابراز و مکشوف و افشاء کردن . مقابل پوشیدن، نهفتن، پنهان کردن، و راز داشتن <span class=\"hlight\">:</span> <br />که خراد برزین برِ شهریار<br />سخنهای پوشیده کرد آشکار.<br /> <font color=\"Red\">فردوسی .</font><br />کی نامور دادشان زینهار <font color=\"DarkGreen\"><b>[ دیوان را ]</font></b><br />بدان تا نهانی کنند آشکار.<br /> <font color=\"Red\">فردوسی .</font><br />صاحب غازی در نیشابور شعار ما را آشکار کرده بود و خطبه بگردانیده . (تاریخ بیهقی ).<BR>۩ رَفع. نَشر. نمودن <span class=\"hlight\">:</span> <br />بفرمایدش تا سوی شهریار<br />شود تا سخنهاکند آشکار.<br /> <font color=\"Red\">فردوسی .</font><br />عمرکرد اسلام را آشکار<br />بیاراست گیتی چو باغ بهار.<br /> <font color=\"Red\">فردوسی .</font><br />و قتیبةبن طغشاده، بخارخدات با ده هزار مرد بیامد و علامت سپاه آشکار کرد وبا زیادبن صالح جنگ درپیوست . (تاریخ بخارای نرشخی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکار گفتن </span> ؛افاصه . بیان . مفاوصه . ابانه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکار و نهان، آشکار و نهفت </span> ؛ سِرّ و علن . سِرّ و علانیه . ظاهر و باطن . صورت و معنی . خلوت و جلوت . غیب و شهود. غیب و شهادت <span class=\"hlight\">:</span> <br />همه هرچه دید آشکار و نهفت <br />به پیش پدر یک بیک بازگفت .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکار و نهان ندانستن </span> ؛ از هیچ چیز آگاه نبودن <span class=\"hlight\">:</span> <br />پدر مرده و ناسپرده جهان <br />نداند همی آشکار و نهان .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکار و نهفت کسی با کسی بودن </span> ؛ محرم اسرار او بودن . چیزی از او در پرده نداشتن . ظاهر و باطن با او یکی داشتن <span class=\"hlight\">:</span> <br />بایزدگشسب آن زمان شاه گفت <br />که با او بدش آشکار و نهفت <br />که چون بینی این کار چوبینه را<br />بمردی بپای آورد کینه را.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1667, 'آشکار ساختن', '<span class=\"hlight\">آشکار ساختن .</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ت َ ]</font></b> (مص مرکب ) ظاهر کردن . <BR><font color=\"Blue\">◄</font> ظاهر کردن جریانهای برق مغناطیسی . (فرهنگستان ).<br /></font></div>'),
(1668, 'آشکارا', '<span class=\"hlight\">آشکارا.</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص، ق، اِ) بی پرده . صریح <span class=\"hlight\">:</span> <br />یکی بانگ برزد <font color=\"DarkGreen\"><b>[ پلاشان ]</font></b> به بیژن بلند<br />منم گفت شیراوژن دیوبند<br />بگوآشکارا که نام تو چیست <br />که اختر همی بر تو خواهد گریست .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> روی، مقابل پشت . ظاهر، مقابل باطن . صورت، مقابل معنی <span class=\"hlight\">:</span> <br />تفو باد بر این گزند جهان <br />بتر زآشکارا مر او را نهان .<br /> <font color=\"Red\">فردوسی .</font><br />خنک آنکه آباد دارد جهان <br />بود آشکارای او چون نهان .<br /> <font color=\"Red\">فردوسی .</font><br />بجز داد و خوبی نبد در جهان <br />یکی بود با آشکارا نهان .<br /> <font color=\"Red\">فردوسی .</font><br />به بینیم تا کردگار جهان <br />در این آشکارا چه دارد نهان .<br /> <font color=\"Red\">فردوسی .</font><br />بگیتی ز نیکی چه چیز است گفت <br />هم از آشکارا هم اندر نهفت .<br /> <font color=\"Red\">فردوسی .</font><br />پس چشمه در تیره گردد جهان <br />شود آشکارای گیتی نهان .<br /> <font color=\"Red\">فردوسی .</font><br />همی گفت این سخن دل با زبان نه <br />سخن را آشکارا چون نهان نه .<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> علانیه، مقابل سِر <span class=\"hlight\">:</span> به ایزد و بزینهار ایزد و بدان خدای که نهان و آشکارا خلق داند... تا... منوچهربن قابوس طاعت دار... سلطان باشد... دوست او باشم . (تاریخ بیهقی ).<br />در بسته بروی خود ز مردم <br />تا عیب نگسترند ما را<br />در بسته چه سود و عالم الغیب <br />دانای نهان و آشکارا؟<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> مشهود. مرئی . پدیدار. ظاهر. پیدا <span class=\"hlight\">:</span> <br />هنر خوار شد جادوئی ارجمند<br />نهان راستی، آشکارا گزند.<br /> <font color=\"Red\">فردوسی .</font><br />مار تا پنهان باشد نتوان کشت او را<br />نتوان کشت عدو تا آشکارا نشود.<br /> <font color=\"Red\">منوچهری .</font><br />چه بودی که مرگ آشکارا شدی <br />سکندر هم آغوش دارا شدی ؟<br /> <font color=\"Red\">نظامی .</font><br />بسر مناره اشتر رود و فغان برآرد<br />که نهان شدستم اینجا مکنیدم آشکارا.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> بظاهر <span class=\"hlight\">:</span> <br />وز ایشان یکی زنده اندر جهان <br />ممان آشکارا نه اندر نهان .<br /> <font color=\"Red\">فردوسی .</font><br />بسی چشم سَرم دید آشکارا<br />دوچندان چشم سِر اندر نهان دید.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> مکشوف <span class=\"hlight\">:</span> <br />من آوردمش نزد شاه جهان <br />همه آشکارا بکردم نهان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> عالم شهادت، مقابل عالم غیب <span class=\"hlight\">:</span> <br />از آن دادگر کو جهان آفرید<br />ابا آشکارا نهان آفرید.<br /> <font color=\"Red\">فردوسی .</font><br />بر او آفرین کو جهان آفرید<br />ابا آشکارا نهان آفرید.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> آشکارا، در آشکارا؛ علناً، مقابل سِرّاً <span class=\"hlight\">:</span> <br />نجوید جز ازراستی در جهان <br />چه در آشکارا چه اندر نهان .<br /> <font color=\"Red\">فردوسی .</font><br />رسیدند پس یک بدیگر فراز<br />سخن رفت چند آشکارا و راز.<br /> <font color=\"Red\">فردوسی .</font><br />نپیوست خواهد جهان با تو مهر<br />نه نیز آشکارا نمایدْت چهر.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> هویدا. روشن . آشکار. بیّن .بدیهی . ضروری . واضح . عیان . مبین . جلی . جلیه . اَبلَج . <BR><font color=\"Blue\">◄</font> بالعیان . عیاناً. قِبَلاً. جهرةً.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکاراتر</span> ؛ ابدی . اظهر. اجلی . ابین . اَعلَن . اَصرح . اَوضَح . اجهر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکارا کردن </span> ؛ افشاء، علنی کردن <span class=\"hlight\">:</span> <br />خوش آمدْت گفتار آن دلنواز<br />بکرد آشکارا و بنمود راز.<br /> <font color=\"Red\">فردوسی .</font><br />عادت ملوک عجم چنان بودی که از سر گناهان درگذشتندی الااز سه گناه، یکی آنکه راز ایشان آشکارا کردی ... (نوروزنامه ).<BR>۩ اظهار. ابراز <span class=\"hlight\">:</span> <br />بدو راز بگشاد و گفت این سخُن <br />بجز پیش جان آشکارا مکن .<br /> <font color=\"Red\">فردوسی .</font><BR>۩ پیدا، پدید، پدیدار کردن <span class=\"hlight\">:</span> <br />زمین آشکارا کند دشمنی <br />بجوشد دل مرد آهرمنی .<br /> <font color=\"Red\">فردوسی .</font><br />بیاورد و کرد آشکارا نهان <br />به پیش جهاندیدگان جهان .<br /> <font color=\"Red\">فردوسی .</font><br />هر آن چیز کاندر جهان سودمند<br />کنم آشکارا گشایم ز بند.<br /> <font color=\"Red\">فردوسی .</font><BR>۩ جهر. جهار. اجهار. مجاهره . اِسرار. اخفاء. تصریح . تشییع. عرض .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکارا کردن راز</span> ؛ افشاکردن آن . اذاعه <span class=\"hlight\">:</span> <br />بگفت این و گریان بیامد ز پیش <br />نکرد آشکارا بکس راز خویش .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکارا گشتن، آشکارا گردیدن، آشکارا شدن </span> ؛ شایع شدن . ظاهر گردیدن <span class=\"hlight\">:</span> در اول فتوح خراسان که ایزد تعالی ... خواست که مسلمانی آشکاراتر گردد. (تاریخ بیهقی ).<BR>۩ هویدا، پیدا، پدیدار، پدید، ظاهر، ساطع، لایح شدن <span class=\"hlight\">:</span> <br />بدان آفریدش خدای جهان <br />که تا آشکارا شود زو نهان .<br /> <font color=\"Red\">فردوسی .</font><br />پراکنده گردد بدی در جهان <br />گزند آشکارا و خوبی نهان .<br /> <font color=\"Red\">فردوسی .</font><br />فضل را هرچند که پنهان دارند آشکارا شود. (تاریخ بیهقی ).<BR>۩ از پرده برآمدن <span class=\"hlight\">:</span> پس از این آشکارا گردید کار رضا علیه السلام . (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نفس آشکارا کشیدن زمین </span> ؛ مقابل نفس دزده، و دزدیده در نزد عامه . حرارتی را گویند که در چهل و پنجم روز زمستان (<span class=\"hlight\" dir=\"rtl\">١٥</span> بهمن ) در هوا محسوس گردد.<br /><BR><font color=\"Blue\">◄</font> تصریح . اعراض . شیوع . استعلان . بیان . ظهور. <BR><font color=\"Blue\">◄</font> آزرم .<br /></font></div>'),
(1669, 'آشکارساز', '<span class=\"hlight\">آشکارساز.</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِمرکب ) اسبابی که وجود جریانهای برق مغناطیسی را ظاهر میسازد. (فرهنگستان ).<br /></font></div>'),
(1670, 'آشکارسازی', '<span class=\"hlight\">آشکارسازی .</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (حامص مرکب ) عمل آشکار ساختن جریانهای برق مغناطیسی . (فرهنگستان ).<br /></font></div>'),
(1671, 'آشکاره', '<span class=\"hlight\">آشکاره .</span> <font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص، ق، اِ)آشکار. آشکارا. پدید. هویدا. پیدا. ظاهر. معلوم <span class=\"hlight\">:</span> و سختی بعالم آشکاره گشت . (تاریخ سیستان ).<br />گل عاشق شه است و چو دیدار او بدید<br />گشت آشکاره از دل راز نهان گل .<br /> <font color=\"Red\">مسعودسعد.</font><br />فرصت شمر طریقه ٔ رندی که این نشان <br />چون راه گنج بر همه کس آشکاره نیست .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> علن <span class=\"hlight\">:</span> <br />یکی نام گفتی مر او را پدر<br />نهانی دگر آشکاره دگر.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> متجاهر. متجاسر <span class=\"hlight\">:</span> <br />دزدیست آشکاره که نستاند<br />جز باغ و حایط و زر و ابکاره .<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکاره شدن </span> ؛ اعلان شدن . ظهور <span class=\"hlight\">:</span> و محبت امیربا جعفر اندر دل مردمان جایگیر دید و شعار او آشکاره . (تاریخ سیستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکاره کردن </span> ؛ فاش کردن . افشا کردن . افشاء. (زوزنی ). تشهیر <span class=\"hlight\">:</span> <br />ز باده خوردن پنهان ملول شد حافظ<br />ببانگ بربط و نی رازش آشکاره کنم .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشکاره کردن اسلام </span> ؛ اعلای کلمه ٔ آن <span class=\"hlight\">:</span> <br />نوشته نام سلطان بر مناره <br />شده زو دین اسلام آشکاره .<br /> <font color=\"Red\">(ویس و رامین ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به آشکاره </span> ؛ علناً. جهراً. بالعلانیه . علانیةً. فاش . جهاراً <span class=\"hlight\">:</span> <br />نه هرکه هست سخن گوی هم سخن دانست <br />به آشکاره همی گویم این نه پنهانی .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />و آشکاره به تمام معانی آشکار و آشکارا آمده است .<br /></font></div>'),
(1672, 'آشکاری', '<span class=\"hlight\">آشکاری .</span><font color=\"DarkGreen\"><b>[ ش ْ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (حامص ) هویدائی . ظهور. پیدائی . پدیداری . فاشی . ذیعان . ذیوع . شیوع . وضوح . روشنی . صراحت . رکی . بی پردگی . بروز. بیان . بداهت . یقین . تبین . ابانت .<br /></font></div>'),
(1673, 'آشکو', '<span class=\"hlight\">آشکو.</span> (اِ) آشکوب <span class=\"hlight\">:</span> <br />وین چارطاق ششدر هفت آشکوی چرخ <br />یک تابخانه ٔ حرم کبریای اوست .<br /><font color=\"Red\">خواجو.</font><br /></font></div>'),
(1674, 'آشکوب', '<span class=\"hlight\">آشکوب .</span> (اِ) (از پهلوی آشکپ، سقف . بام . مرتبه و طبقه ٔ بناء) طبقه و مرتبه ٔ خانه . آشیان . آشکو. بربار. برباره . برواره <span class=\"hlight\">:</span> <br />بر آشکوب نخستینْش دست فکرت من <br />بزیر پای فلک را چو نردبان افکند.<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> هر یک از طبقات نه گانه ٔ آسمان <span class=\"hlight\">:</span> <br />روان ساعدماضی چو خواجه بار دهد<br />ز آشکوب نهم میکند تماشائی .<br /> <font color=\"Red\">شرف شفروه .</font><br /> <br /><BR><font color=\"Blue\">◄</font> سقف . آسمانه . <BR><font color=\"Blue\">◄</font> مُهره و رگه های چینه . <BR><font color=\"Blue\">◄</font> آسمان . فلک .<br /></font></div>'),
(1675, 'آشکوب', '<span class=\"hlight\">آشکوب .</span> (اِ) هر یک از طبقات زمین در زمین شناسی . (فرهنگستان ).<br /></font></div>'),
(1676, 'آشکوبه', '<span class=\"hlight\">آشکوبه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) آشکوب .<br /></font></div>'),
(1677, 'آشکوخ', '<span class=\"hlight\">آشکوخ .</span> (اِمص ) سکندری .<br /></font></div>'),
(1678, 'آشکوخیدن', '<span class=\"hlight\">آشکوخیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) سکندری رفتن . از سر پنجه ٔ پای لغزیدن بی اراده و ناآگاهانه . و آن را در ستور سَر سُم رفتن گویند <span class=\"hlight\">:</span> <br />چون بگردد پای او از پای دار <br />آشکوخیده بماندهمچنان .<br /> <font color=\"Red\">رودکی .</font><br />آشکوخدبر زمین هموار بر<br />همچنان چون برزمین دشخوار بر .<br /><font color=\"Red\">رودکی .</font><br /></font></div>'),
(1679, 'آشکوی', '<span class=\"hlight\">آشکوی .</span> (اِ) قصر و مکان عالی <span class=\"hlight\">:</span> <br />توئی که از غرف آشکوی طارم چرخ <br />نزول یافت بایوان جد تو تنزیل .<br /> <font color=\"Red\">استاد.</font><br />در فرهنگها کلمه ٔ فوق و معنای مذکور آمده و شعر استاد ناشناس را هم مثال آورده اند و ظاهراً این صورت مصحف آشکوب باشد.<br /></font></div>'),
(1680, 'آشی', '<span class=\"hlight\">آشی .</span> <font color=\"DarkGreen\"><b>[ شا ]</font></b> (اِخ ) نام پدر داود پیغامبر علیه السلام .<br /></font></div>'),
(1681, 'آشیان', '<span class=\"hlight\">آشیان .</span> (اِ) آشیانه . خانه ٔ مرغ . لانه ٔ مرغ . مأوای طیر. آموت . کابک . کابوک . پدواز. تکند. عش ّ. وکر.وکنه . اُکنه . وقنه . موکن . فراش . موکنه <span class=\"hlight\">:</span> <br />بدان هر عمود آشیانی بزرگ <br />نشسته برو سبز مرغ سترگ .<br /> <font color=\"Red\">فردوسی .</font><br />در آشیان چرخ دو مرغان زیرکند<br />کاندر فضای ربع زمین دانه میخورند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />از شمس دین چه آید جز افتخار دین <br />لابد که باز باز پراندز آشیان .<br /> <font color=\"Red\">سوزنی </font><br />از صدهزار طفل که مویش چو زر بود<br />سیمرغ زال را بسوی آشیان برد.<br /> <font color=\"Red\">عمادی شهریاری .</font><br />مرغ دل از آشیانی دیگر است <br />عقل و جان را سوی او آهنگ نیست .<br /> <font color=\"Red\">عطار.</font><br />مرغ را پر می برد تا آشیان <br />پرّ مردم همت است ای مردمان .<br /> <font color=\"Red\">مولوی .</font><br />کبوتری که دگر آشیان نخواهد دید<br />قضا همی بَرَدش تا بسوی دانه و دام .<br /> <font color=\"Red\">سعدی .</font><br />باز کز آشیان برون نپرد<br />بر شکاری ظفر کجا یابد؟<br /> <font color=\"Red\">ابن یمین .</font><br />ای خسرو خسرونشان کردی جهان را آنچنان <br />کز آمنی باز آشیان سازد کبوتر مستقر.<br /> <font color=\"Red\">ابن یمین .</font><br />اگرچه ساعد شاهان بود نشیمن باز<br />ولی بکام دل باز آشیان باشد.<br /> <font color=\"Red\">ابن یمین .</font><br /> <BR><font color=\"Blue\">◄</font> لانه ٔ زنبور.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مُنج آشیان </span> ؛ زنبورخانه .<br /> <BR><font color=\"Blue\">◄</font> سوراخ مار <span class=\"hlight\">:</span> <br />چیست از گفتار خوش بهتر که او<br />مار را آرد برون از آشیان .<br /> <font color=\"Red\">خفاف .</font><br /> <BR><font color=\"Blue\">◄</font> لانه ٔ موش . <BR><font color=\"Blue\">◄</font> طبقه . مرتبه . آشکوب . <BR><font color=\"Blue\">◄</font> مجازاً، خانه <span class=\"hlight\">:</span> <br />چون خانه ٔ بیگانه آشیان شد<br />خو کرد در این بند زاولانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />جنت آشیان و خلدآشیان تعبیری است که باحترام پیش از نام ِ درگذشته آرند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آشیان عقاب </span> ؛ سخت رفیع (خانه و جز آن ).<br /></font></div>'),
(1682, 'آشیانه', '<span class=\"hlight\">آشیانه .</span><font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) آشیان و مترادفات آن <span class=\"hlight\">:</span> <br />مرا خورد خون بود بر جای شیر<br />در آن آشیانه بسان اسیر.<br /> <font color=\"Red\">فردوسی .</font><br />بل دهر درختی است نَفْس مرغی <br />وین کالبد او را چو آشیانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تو زآشیانه ٔ باز سپید خاسته ای <br />ز بازخانه نپرّد بهیچ حالی بوم .<br /> <font color=\"Red\">سوزنی .</font><br />ز گرد راه چو عنقا به آشیانه ٔ باز<br />بسوی بنده خرامید شاه بنده نواز.<br /> <font color=\"Red\">سوزنی .</font><br />هوای باغ جهان را چو بلبلی بودم <br />که بود گلشن صدر تو آشیانه ٔ من .<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />نصرت که فَرْخ بیضه ٔ پولاد تیغ اوست <br />بر شاخسار رایت او آشیان نهاد.<br /> <font color=\"Red\">سلمان ساوجی .</font><br />برو این دام بر مرغ دگر نه <br />که عنقارا بلند است آشیانه .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> سوراخ مار <span class=\"hlight\">:</span> <br />از مار کینه ورتر ناسازگارتر چه <br />گفتار چربش آرد، بیرون ز آشیانه .<br /> <font color=\"Red\">لبیبی .</font><br /> <BR><font color=\"Blue\">◄</font> آشیانه ٔ مور؛ قریه . <BR><font color=\"Blue\">◄</font> لانه ٔ موش . <BR><font color=\"Blue\">◄</font> آشکوب . طبقه . مرتبه . آشیان <span class=\"hlight\">:</span> <br />بر ایوانش مه و سال از بلندی <br />نهاده نسر طائر آشیانه <br />ز فخر و مرتبت زیبد که باشد<br />سپهرش کاخ و مهرش آستانه .<br /> <font color=\"Red\">عبدالواسع جبلی .</font><br />بناهای چندین آشیانه . (تحفه ٔ اهل بخارا).<br />ما بلبلان بلند نسازیم خانه را<br />خوش کرده ایم خانه ٔ یک آشیانه را.<br /> <font color=\"Red\">غنی .</font><br /> <BR><font color=\"Blue\">◄</font> جای . مأوی . خانه <span class=\"hlight\">:</span> <br />بیاموز اگر پارسا بود خواهی <br />مکن دیو را جان خود آشیانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> سقف . آسمانه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آشیانه نهادن </span> ؛ آشیانه گرفتن . آشیانه کردن . آشیانه ساختن . اعتشاش . تعشیش . (دهار).<br /></font></div>'),
(1683, 'آشیب', '<span class=\"hlight\">آشیب .</span> (اِ) آسیب . (مجمعالفرس از شعوری ).<br /></font></div>'),
(1684, 'آشیب و شیب', '<span class=\"hlight\">آشیب و شیب .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِ مرکب، از اتباع ) این صورت در بیت ذیل بضبط بعض نسخ شاهنامه آمده است، و در بعض دیگر آسیب با سین مهمله بجای آشیب دارد، و معنی آن ظاهراً رنج و تعب و مانند آن باشد <span class=\"hlight\">:</span> <br />چنین است گیتی پر آشوب و شیب <br />پس ِ هرفرازی نهاده نشیب .<br /> <font color=\"Red\">فردوسی .</font><br />و بگمان من کلمه ٔ اول آشیب و کلمه ٔ دوم تیب است، صورتی از شیب و تیب .<br /></font></div>'),
(1685, 'آشیل', '<span class=\"hlight\">آشیل .</span> (اِخ ) نامی از نامهای یونانی . رجوع به اخلوس و اخیلوس شود.<br /></font></div>'),
(1686, 'آشینه', '<span class=\"hlight\">آشینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) بیضه . تخم مرغ . خایه . مرغانه . رجوع به آستینه و آسینه و آشتینه شود.<br /></font></div>'),
(1687, 'آشیهه', '<span class=\"hlight\">آشیهه .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (اِ) شیهه . صهیل . شنه .<br /></font></div>'),
(1688, 'آصار', '<span class=\"hlight\">آصار.</span> (ع اِ) ج ِ اِصْر.<br /></font></div>'),
(1689, 'آصال', '<span class=\"hlight\">آصال .</span> (ع ص، اِ) ج ِ اصیل . صاحب اصلان . <BR><font color=\"Blue\">◄</font> محکم رایان . <BR><font color=\"Blue\">◄</font> (اِ) شبان گاه ها. عشایا.<br /></font></div>'),
(1690, 'آصده', '<span class=\"hlight\">آصده .</span> <font color=\"DarkGreen\"><b>[ ص ِدَ ]</font></b> (ع اِ) اِصاد. گوِ آب میان کوهها. <BR><font color=\"Blue\">◄</font> (مص ) برابر کردن دو چیز با یکدیگر. (شرح قاموس ).<br /></font></div>'),
(1691, 'آصره', '<span class=\"hlight\">آصره .</span> <font color=\"DarkGreen\"><b>[ ص ِ رَ ]</font></b> (ع اِ) گرایش و مهر و مایه و وسیله ٔ نزدیکی از رحم و قرابت و خویشی وخویشاوندی و پیوند سببی و معروف و احسان و منت . <BR><font color=\"Blue\">◄</font> رسن کوتاه که بدان دامن خیمه را بمیخ استوار کنند. پاچه بند. آخیه . اَخیه . آری ّ. ج، اَواصِر.<br /></font></div>'),
(1692, 'آصره', '<span class=\"hlight\">آصره .</span> <font color=\"DarkGreen\"><b>[ ص ِ رَ ]</font></b> (ع اِ) ج ِ اِصار. میخهای طناب . <BR><font color=\"Blue\">◄</font> زنبیلها. <BR><font color=\"Blue\">◄</font> چادرهائی که در آن گیاه پر کنند. <BR><font color=\"Blue\">◄</font> ثقلها. بارها. <BR><font color=\"Blue\">◄</font> گناهان . <BR><font color=\"Blue\">◄</font> عهدها. پیمان ها. <BR><font color=\"Blue\">◄</font> سوراخها (در گوش ). <BR><font color=\"Blue\">◄</font> سوگندان بطلاق زن یا آزادی بنده . <BR><font color=\"Blue\">◄</font> نذرها.<br /></font></div>'),
(1693, 'آصف', '<span class=\"hlight\">آصف .</span> <font color=\"DarkGreen\"><b>[ ص َ ]</font></b> (اِخ ) پسر برخیا. نام وزیر یا دبیر سلیمان نبی و یا دانشمندی از بنی اسرائیل، و گویند این همان کس است که علمی از کتاب داشت و در قرآن کریم ذکر آن رفته است . و او تخت بلقیس سبا را از دوماهه راه بکمتر از لمح بصرو چشم زخمی در پیشگاه سلیمان حاضر ساخت <span class=\"hlight\">:</span> <br />یک زمان صد روی از اهل هنر خالی نیست <br />همچو خالی نبدی تخت سلیمان زآصف <br />آسمان بوسه دهد خاک درش راباُمید<br />کآستانش بزداید ز رخ ماه کلف .<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> توسعاً، وزیر و یا وزیری بخرد و تدبیر <span class=\"hlight\">:</span> <br />عمل و علم بباید صفت آصف شاه <br />آصفی چون کند آن خواجه که نادان باشد؟<br /> <font color=\"Red\">کمال اسماعیل .</font><br /><BR><font color=\"Blue\">◄</font> نام خنیاگری مشهور بزمان داود نبی . <BR><font color=\"Blue\">◄</font> (از ع، اِ) اَصَف . بیخ کبر. (برهان ).<br /></font></div>'),
(1694, 'آصف الدوله', '<span class=\"hlight\">آصف الدوله .</span> <font color=\"DarkGreen\"><b>[ ص َ فُدْ دَ ل َ ]</font></b> (اِخ ) پسر شجاع الدوله . از امراء و نُوّاب هندوستان، و او بزبان فارسی وارد بوده و شعر می سروده . مدت امارت او در فیض آبادو لکنهو <span class=\"hlight\" dir=\"rtl\">٢٣</span> سال و در <span class=\"hlight\" dir=\"rtl\">١٢١٢</span> هَ .ق . وفات یافته است .<br /></font></div>'),
(1695, 'آصف خان', '<span class=\"hlight\">آصف خان .</span> <font color=\"DarkGreen\"><b>[ ص َ ]</font></b>(اِخ ) نام وزیر جهانگیر پادشاه هند، و او اصلاً اصفهانی و پسر میرزا رفیعالدین و برادرزاده ٔ میرغیاث الدین است . در جوانی بهندوستان رفته و بوساطت عم ّ خویش میرغیاث الدین بدربار اکبرشاه راه یافت و در زمان جهانگیر بوزارت رسید. آصف خان دارای طبع شعر بوده و مثنوی خسرو و شیرین سروده است . وفات او<span class=\"hlight\" dir=\"rtl\">١٠٢١</span> هَ .ق . است .<br /></font></div>'),
(1696, 'آصفجاه', '<span class=\"hlight\">آصفجاه .</span> <font color=\"DarkGreen\"><b>[ ص َ ]</font></b> (اِخ ) رجوع به نظام الملک (چن قلیچ خان ...) شود.<br /></font></div>'),
(1697, 'آصفی', '<span class=\"hlight\">آصفی .</span> <font color=\"DarkGreen\"><b>[ ص َ ]</font></b> (اِخ ) از شعرای عصر تیموری، پدرش خواجه نعمةاﷲ وخود او از مقربان سلطان مذکور بوده و در اواخر عهد بخدمت سلطان حسین بایقرا پیوسته است . دیوانی بزرگ و چند مثنوی دارد. امیرعلی شیر نوائی او را در تذکره یادکرده است . وفات او به سال <span class=\"hlight\" dir=\"rtl\">٩٢٠</span> یا <span class=\"hlight\" dir=\"rtl\">٩٢٦</span> هَ .ق . است .<br /></font></div>'),
(1698, 'آصل', '<span class=\"hlight\">آصل .</span> <font color=\"DarkGreen\"><b>[ ص ُ ]</font></b> (ع اِ) ج ِ اَصْل .<br /></font></div>'),
(1699, 'آصیه', '<span class=\"hlight\">آصیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) آش که از گندم و خرما کنند.<br /></font></div>'),
(1700, 'آطال', '<span class=\"hlight\">آطال .</span> (ع اِ) ج ِ اِطْل و اِطِل، به معنی خاصره و تهیگاه .<br /></font></div>'),
(1701, 'آطام', '<span class=\"hlight\">آطام .</span> (ع اِ) ج ِ اُطُم . دژها. حصارها. حصون . خانه ها از سنگ .<br /></font></div>'),
(1702, 'آطام', '<span class=\"hlight\">آطام .</span> (اِخ ) نام دهی به یَمامه .<br /></font></div>'),
(1703, 'آطروفیا', '<span class=\"hlight\">آطروفیا.</span> (یونانی، اِ) (از یونانی آ، حرف سلب + طروفه، خورش . غذا)هزال مُفرط. ضمور عضوی . و رجوع به اَطْروفیا شود.<br /></font></div>'),
(1704, 'آطریلال', '<span class=\"hlight\">آطریلال .</span> (اِ) رجوع به اِطریلال شود.<br /></font></div>'),
(1705, 'آطمه', '<span class=\"hlight\">آطمه .</span> <font color=\"DarkGreen\"><b>[ طِ م َ ]</font></b> (ع اِ) ج ِ اَطوم . سنگ پشت های دریائی که کاسه و لاک ستبر دارند.<br /></font></div>'),
(1706, 'آطن', '<span class=\"hlight\">آطن .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) آتن . نام شهر مشهور یونان باستانی، کرسی آتیک و پایتخت مملکت یونان کنونی . این شهر در قدیم مهد تربیت حکما و نویسندگان و هنرپیشگان بزرگ بوده و ابنیه و عمارات زیباداشته و در <span class=\"hlight\" dir=\"rtl\">٤٨٠</span> ق .م . خشایارشا شاهنشاه هخامنشی آن را مسخر کرده است . سکنه ٔ فعلی آن نزدیک سیصدهزار نفراست . اَثینس و اَتینا و اَطینه نیز صورتهای دیگر این نام است، و آن را لقب مدینةالحکماء نیز داده اند.<br /></font></div>'),
(1707, 'آطوسا', '<span class=\"hlight\">آطوسا.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) نام چندین زن از دوده ٔهخامنشی و ازجمله دختر کورش، و شاید واستی که در تورات نام او مسطور است هم او باشد. در اول زن برادر خویش کامبوزیا (کمبوجیه ) بود، پس از او با سمردیس مغ شوهر کرد و شوی سوم او دارایاوش (داریوش ) است و از او دو فرزند آورد، یکی بنام خشایارشا و دیگری آرتابازان، و این ملکه شوهر خود شاهنشاه ایران دارایاوش را به تسخیر یونان برانگیخت . و این نام در اوستا هوطَاوسه آمده است . و اَطوسای دیگری دختر چایش پس است و نیز نام دختر اردشیر دوم و خواهر و زن اردشیر سوم است .<br /></font></div>'),
(1708, 'آغ بلاغ', '<span class=\"hlight\">آغ بلاغ .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) نام محلی کنار راه قزوین و همدان میان گوریجان و گوروان .<br /></font></div>'),
(1709, 'آغ بوغوش', '<span class=\"hlight\">آغ بوغوش .</span> <font color=\"DarkGreen\"><b>[ ب ُ غُش ْ ]</font></b> (اِخ ) نام محلی کنار راه سراب به اردبیل میان ساری قیه و مجمیر در <span class=\"hlight\" dir=\"rtl\">١٦١٣٠٠</span> گزی تبریز.<br /></font></div>'),
(1710, 'آغ و داغ', '<span class=\"hlight\">آغ و داغ .</span> <font color=\"DarkGreen\"><b>[ غ ُ ]</font></b> (ص مرکب، از اتباع ) در تداول عوام، آغ و داغ چیزی یا کسی بودن ؛ سخت خواهان و شیفته ٔ او بودن . عاشق غاش کسی یا چیزی بودن . <BR><font color=\"Blue\">◄</font> (اِ مرکب، از اتباع ) آغ و داغش درآمده بودن ؛ سخت لاغر و نزار شده بودن چنانکه یک یک استخوانهای او بچشم توان دیدن .<br /></font></div>'),
(1711, 'آغا', '<span class=\"hlight\">آغا.</span> (ترکی، اِ) خاتون . بی بی . سیده . ستی . بانو. بیگم . خانم . <BR><font color=\"Blue\">◄</font> زن . حرَم <span class=\"hlight\">:</span> اما شرط رعایت اصناف اربعه، اول جانب حرمهای بزرگ اگرچه در ازمنه ٔ سالفه، خصوص ملوک عجم، خواتین را در مهمات ملکی و دولت ملاحظه بسیار نمی بود و امور سلطنت بارادت یا عدم ارادت ایشان زیاده تعلقی نمیداشت ولیکن خاقانان ترکستان را قاعده این بود که مطلقاً در جمیع وقایع مشورت با آغایان کردندی و رای ایشان بر جمیع اهل استشارت مقدم بودی و سلاطین ترکمان نیز در اصل چون پرورده ٔ دولت ایشانند همان طریقه قدوه و دستور خود دارند و بناء کلیات امور بر صوابدید ایشان نهند پس پناه بحمایت ایشان بردن ازجمله ٔ ضروریات است و آن چنان باید که بعد از عدم اختلاط آغایان با لواحق و حواشی ایشان که در مقام قرب باشند علی اختلاف طبقاتهم از احسان این کس محروم نباشند. (از اندرزنامه ٔ منسوب به خواجه نظام الملک ). <BR><font color=\"Blue\">◄</font> کلمه ٔ احترامی است که بر سر نام خادمان یعنی خواجه سرایان درآرند، چنانکه آقا در دیگر مردم : آغابشارت . آغاجوهر.<br /></font></div>'),
(1712, 'آغا احمد عالی', '<span class=\"hlight\">آغا احمد عالی .</span> <font color=\"DarkGreen\"><b>[ اَ م َ دِ ]</font></b> (اِخ ) نام شاعری ایرانی، ساکن هندوستان، و اورا درعلم لغت کتابی به نام مؤید برهان و در علم صرف رساله ای بعنوان رساله ٔ اشتقاق هست، و رساله ٔ ترانه و هفت آسمان آثار دیگر اوست . وفات در <span class=\"hlight\" dir=\"rtl\">١٢٩٠</span> هَ .ق .<br /></font></div>'),
(1713, 'آغاج', '<span class=\"hlight\">آغاج .</span> (ترکی، اِ) چوب . درخت . <BR><font color=\"Blue\">◄</font> فرسنگ . فرسَخ . <BR><font color=\"Blue\">◄</font> قره آغاج ؛ نارون بی پیوند.<br /></font></div>'),
(1714, 'آغاج دلن', '<span class=\"hlight\">آغاج دلن .</span> <font color=\"DarkGreen\"><b>[ دَ ل َ ]</font></b> (ترکی، اِ مرکب ) (از: آغاج، درخت + دلن، سوراخ کننده ) درخت سنبه . دارکوب . سودانیات . داربر. دارتمک .<br /></font></div>'),
(1715, 'آغاجی', '<span class=\"hlight\">آغاجی .</span> (اِخ ) آغاچی . امیرحسن علی بن الیاس آغاجی بخاری . از امراء سامانیه، معاصر نوح بن منصور سامانی . شاعر مشهور ایران، و او در هر دو زبان فارسی و عربی شعر گفته و ممدوح دقیقی شاعر بوده است .<br /></font></div>'),
(1716, 'آغار', '<span class=\"hlight\">آغار.</span> (اِ) نم . زه . ثاد. نداوت . ندا <span class=\"hlight\">:</span> <br />عقیق وار شده ست آن زمین ز بس که ز خون <br />بروی دشت و بیابان فروشده ست آغار.<br /> <font color=\"Red\">کسائی یا عنصری .</font><br /> <BR><font color=\"Blue\">◄</font> آنچه ترابد از کوزه ومانند آن <span class=\"hlight\">:</span> <br />از هرچه سبو پر کنی از زیر و ز پهلوش <br />زآن چیز برون آید و بیرون دهد آغار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />از خاطرپرعلم سخن ناید جز خوب <br />از پاک سبو پاک برون آید آغار.<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> اُغُر. آغال .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بدآغار</span> ؛ بدآغال . شوم . نحس <span class=\"hlight\">:</span> <br />یکی زشت روی بدآغار بود<br />تو گوئی بمردم گزی مار بود.<br /> <font color=\"Red\">ابوشکور.</font><br /> <br /></font></div>'),
(1717, 'آغاران', '<span class=\"hlight\">آغاران .</span> (نف، ق ) در حال آغاردن . در حال آغاریدن .<br /></font></div>'),
(1718, 'آغاردان', '<span class=\"hlight\">آغاردان .</span> (ترکی، اِ) آغاج دَلَن . دارتمک . داربر. سودانیات . شقراق . ستوچه . (زمخشری ). دارکوب .<br /></font></div>'),
(1719, 'آغاردن', '<span class=\"hlight\">آغاردن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آغاریدن .<br /></font></div>'),
(1720, 'آغارده', '<span class=\"hlight\">آغارده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آغاریده .<br /></font></div>'),
(1721, 'آغاردگی', '<span class=\"hlight\">آغاردگی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) فرغاردگی . نم کشیدگی . آغشتگی . چگونگی و کیفیت آغارده .<br /></font></div>'),
(1722, 'آغارش', '<span class=\"hlight\">آغارش .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِمص ) اسم مصدر آغاریدن <span class=\"hlight\">:</span> <br />نه آغارش پذیرد زآب آهن .<br /><font color=\"Red\">(ویس و رامین ).</font><br /></font></div>'),
(1723, 'آغارنده', '<span class=\"hlight\">آغارنده .</span> <font color=\"DarkGreen\"><b>[ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه آغارد.<br /></font></div>'),
(1724, 'آغاره', '<span class=\"hlight\">آغاره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) دوالی که کفشگر بر درز میان رویه و زیره ٔ کفش کند تا آب و خاک در درون نشود . <BR><font color=\"Blue\">◄</font> کفه ٔ کفش که از درونسوی افکنند.<br /></font></div>'),
(1725, 'آغاری', '<span class=\"hlight\">آغاری .</span> (اِ) آغری . قسمی جامه ٔ ابریشمین سطبر که از آن مردان لباده و عباو سرداری کردندی و زنان یَل و نیم تنه و مانند آن .<br /></font></div>'),
(1726, 'آغاریدن', '<span class=\"hlight\">آغاریدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) خیساندن . تر نهادن . نم کردن . فژغردن . فرغاردن . آغشتن . فروشدن آب و نم در چیزی . خیسیدن . نم کشیدن . نرم شدن . فروبردن آب و نم در جسمی، از زمین و جز آن <span class=\"hlight\">:</span> <br />بهنگام نان شیر گرم آوری <br />بدان شیر این چرم نرم آوری <br />بشیر اندر آغاری این چرم خر<br />چنان چون که گردد بگیتی سمر...<br />کنیزک همی خواستی شیر گرم <br />نهانی ز هرکس به آواز نرم ...<br />دو هفته سپهر اندرین گشته شد<br />بفرجام چرم خر آغشته شد.<br /> <font color=\"Red\">فردوسی .</font><br />آب انگور فراز آور یا خون زبیب <br />که زبیب ای عجبی هست بانگور قریب <br />شود انگور زبیب آنگه کش خشک کنی <br />چون بیاغاری انگور شود خشک زبیب .<br /> <font color=\"Red\">منوچهری .</font><br />نه آغارش پذیرد زآب آهن .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بر شوره مریز آب خوش ایرا<br />نایدْت بکار چون بیاغارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />بیاغارد بخون پهلوی ماهی <br />بینبارد بگرد افلاک گردان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چگونه بی سر و دندان و حلق و معده ای دانه <br />همی خاکی خورد هموار و آب او را بیاغارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />پولاد نرم کی شود و شیرین <br />گرچه در انگبینْش بیاغاری ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />ز آغاریدن آن دشت با خون <br />شده یکسر درختانش طبرخون <br />بسکه گردون را خوش آمد شربت گفتار من <br />در گلاب دیده هر دم چون شکر آغاردم .<br /> <font color=\"Red\">ابن یمین .</font><br />بمنزلی که فرود آیم از فراق رخت <br />ز خون دیده زمین سربسر بیاغارم .<br /> <font color=\"Red\">نزاری قهستانی .</font><br /> <BR><font color=\"Blue\">◄</font> تراویدن . ترابیدن . زهیدن <span class=\"hlight\">:</span> <br />خردمندی که نعمت خورد شکر آنْش باید کرد<br />ازیرا کز سبوی سرکه جز سرکه نیاغارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> آمیختن <span class=\"hlight\">:</span> <br />ز باد سرد کجا آب منعقد گردد<br />بلطف طبعش اگر آب را بیاغاری ؟<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> سرشتن . <BR><font color=\"Blue\">◄</font> آغاردن . تحریک کردن . تحریض کردن . اغراء. آغالیدن . تفتین . وژولیدن . فژولیدن . فتنه کردن . برغلانیدن . افژولیدن . اوژولیدن . در بعض فرهنگها برای معنی اغراء و آغالیدن بیت ذیل را شاهد آورده اند و ظاهراً درست نیست و آغازیدن خواندن کلمه در آن انسب است <span class=\"hlight\">:</span> <br />با چنین کم دشمنان خواجه نیاغارد بجنگ <br />اژدها را حرب ننگ آید که با حربا کند.<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(1727, 'آغاریده', '<span class=\"hlight\">آغاریده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آغارده . خیسیده . خیسانیده . فژغرده . فرغارده . ترنهاده . آغشته . <BR><font color=\"Blue\">◄</font> زهیده . تراویده . ترابیده . <BR><font color=\"Blue\">◄</font> آغالیده .<br /></font></div>'),
(1728, 'آغاریدگی', '<span class=\"hlight\">آغاریدگی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) آغاردگی .<br /></font></div>'),
(1729, 'آغاریقون', '<span class=\"hlight\">آغاریقون .</span> (معرب، اِ) (از یونانی آگاریکوس ) غاریقون . قسمی سماروغ (قارچ ) که در جوف اشجار سال خورد پوسیده مانند انجیر و جمیز پدید آید، چنانکه قاو بر درخت بلوط پیدا شود. و رجوع به غاریقون شود.<br /></font></div>'),
(1730, 'آغاز', '<span class=\"hlight\">آغاز.</span> (اِ) بدائت (بدایت ).بدء (بدو). ابتدا. ابتداء. فاتحه . مفتتح . شروع . سر.دخش . درآمد. صدر. مبداء. اوّل . نخست . ازل . اصل . مقابل فرجام و انتها و انجام و بن و اَبَد <span class=\"hlight\">:</span> <br />چون فراز آمد بدو آغاز مرگ <br />دیدنش بیگار گرداند و مجرگ .<br /> <font color=\"Red\">رودکی .</font><br />بر اندازه بر هر کسی می خورید<br />ز آغاز فرجام را بنگرید.<br /> <font color=\"Red\">فردوسی .</font><br />همین است فرجام و آغاز ما<br />سخن گفتن فاش و هم راز ما.<br /> <font color=\"Red\">فردوسی .</font><br />بکوشیم و از کوشش ما چه سود<br />کز آغاز بود آنچه بایست بود.<br /> <font color=\"Red\">فردوسی .</font><br />به آغاز گنج است و فرجام رنج <br />پس از رنج، رفتن ز جای سپنج .<br /><font color=\"Red\">فردوسی .</font><br />یکی آنکه هستیش را راز نیست <br />بکاریش انجام و آغاز نیست .<br /> <font color=\"Red\">فردوسی .</font><br />چرا گشت باید همی زآن سرشت <br />که پالیزبانش به آغاز کشت ؟<br /> <font color=\"Red\">فردوسی .</font><br />جهاندار چون دید بهرام را<br />بدانست زآغاز فرجام را.<br /> <font color=\"Red\">فردوسی .</font><br />که آهوست بر مرد گفتار زشت <br />ترا خود ز آغاز بود این سرشت .<br /> <font color=\"Red\">فردوسی .</font><br />چنین بود از آغاز یکسر سخن <br />همین باشد و این نگردد کهن .<br /> <font color=\"Red\">فردوسی .</font><br />ورا زآن سخن تند و ناکام دید<br />به آغاز آن رنج فرجام دید.<br /> <font color=\"Red\">فردوسی .</font><br />بدو راز بگشاد و زو چاره جست <br />کز آغاز پیمانْت خواهم درست .<br /> <font color=\"Red\">فردوسی .</font><br />بدل کین همی داشت زاسفندیار<br />ندانم چه سان بود زآغاز کار.<br /> <font color=\"Red\">فردوسی .</font><br />همه رنج تو داد خواهد بباد<br />که بردی ز آغاز با کیقباد.<br /> <font color=\"Red\">فردوسی .</font><br />همان زور خواهم کز آغاز کار<br />مرا دادی ای پاک پروردگار.<br /> <font color=\"Red\">فردوسی .</font><br />شنیدم که رستم ز آغاز کار<br />چنان یافت نیرو ز پروردگار.<br /> <font color=\"Red\">فردوسی .</font><br />چو بشنید کاوس آواز اوی <br />بدانست انجام و آغاز اوی .<br /> <font color=\"Red\">فردوسی .</font><br />همه کارها سخت باساز بود<br />به آوردگه گشتن آغاز بود.<br /> <font color=\"Red\">فردوسی .</font><br />سپهبد چو بشنید زین سان سخن <br />که چون بود از آغاز کردار و بن .<br /> <font color=\"Red\">فردوسی .</font><br />شنیدی که با ایرج کم سخُن <br />به آغاز کینه چه افکند بن .<br /> <font color=\"Red\">فردوسی .</font><br />یکی کار پیش است با درد و رنج <br />به آغاز رنج و بفرجام گنج .<br /> <font color=\"Red\">فردوسی .</font><br />کنون بازگردم به آغاز کار<br />سوی نامه ٔ نامور شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />بدو <font color=\"DarkGreen\"><b>[ قیصر ]</font></b> شاه گفت ای سرشت بدی <br />که ترسائی و دشمن ایزدی <br />پسر گوئی آن را کش انباز نیست <br />ز گیتیش فرجام و آغاز نیست .<br /> <font color=\"Red\">فردوسی .</font><br />ز آغاز باید که دانی درست <br />سرِ مایه ٔ گوهران از نخست .<br /> <font color=\"Red\">فردوسی .</font><br />که گیتی به آغاز چون داشتند<br />که ایدون بما خوار بگذاشتند؟<br /> <font color=\"Red\">فردوسی .</font><br />کنون بازگردم به آغاز کار<br />که چون بود کردار آن شهریار <font color=\"DarkGreen\"><b>[ کیخسرو ]</font></b> .<br /> <font color=\"Red\">فردوسی .</font><br />هرچه به آغازی بوده شود<br />طَمْع مدار ای پسر اندر بقاش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ز آغاز بودش بداد آورید<br />خدای این جهان را ز کتم عدم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آغاز تاریخ امیر شهاب الدوله مسعودبن محمود. (تاریخ بیهقی ).<br />دادند دو گوش و یک زبانت زآغاز<br />یعنی که دو بشنو و یکی بیش مگو.<br /> <font color=\"Red\">باباافضل الدین کاشانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آغاز جوانی </span> ؛ رَیعان شباب . عنفوان شباب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آغاز کار</span> ؛ ابتدا، فاتحه، افتتاح، شروع، دخش آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آغاز نامه </span> ؛صدر کتاب . مفتتح آن . سر کتاب . دیباچه ٔ کتاب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">در آغاز</span> ؛ نخست .<br /> <BR><font color=\"Blue\">◄</font> و معنی صدا و ندا نیز به این کلمه داده اند و بشعر ذیل تمثل کرده اند و ظاهراً درست نباشد، چه آغاز در این بیت به معنی متبادر لفظ یعنی شروع است <span class=\"hlight\">:</span> <br />بدشمن بر، از خشم آواز کرد<br />تو گفتی مگر تندر آغاز کرد.<br /> <font color=\"Red\">رودکی .</font><br /> <BR><font color=\"Blue\">◄</font> قصد. اراده . (برهان ). صاحب جهانگیری که برهان و دیگران بمتابعت او به کلمه ٔ آغاز معنی قصد و اراده داده اند بیت ذیل را مثال آورده است <span class=\"hlight\">:</span> <br />رو بگرد خاکبازی گرد کاین آن راه نیست <br />کاندرین ره با براق جلد خرتازی کنی <br />نی تو خود کی مرد آن باشی که خود را چون خلیل <br />در کف محنت چو گوئی پهنه آغازی کنی .<br /> <font color=\"Red\">سنائی .</font><br />اگر شاهد این معنی منحصر باین بیت است بی شبهه دعوی غلطی است که از مصحَّف خواندن بیت سنائی پیدا شده، مصراع سنائی اصلش این است <span class=\"hlight\">:</span> <br />در کف محنت چو گوی پهنه ٔ غازی کنی .<br />پهنه همان راکت است و بازی گوی و پهنه، طنیس (تنیس ) امروزینست .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">هرچه آغاز ندارد نپذیرد انجام </span> .<br /> <font color=\"Red\">حافظ.</font><br />ما ثبت قدمه امتنع عدمه .<br /></font></div>'),
(1731, 'آغاز نهادن', '<span class=\"hlight\">آغاز نهادن .</span> <font color=\"DarkGreen\"><b>[ ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) آغاز کردن . آغازیدن <span class=\"hlight\">:</span> پس آن مزدور چنگ برداشت و سماع خوش آغاز نهاد. (کلیله و دمنه ). شکال هم بدین نمط فصلی آغاز نهاد. (کلیله و دمنه ). هر دو جنگ آغاز نهادند. (کلیله و دمنه ).<br /></font></div>'),
(1732, 'آغاز کردن', '<span class=\"hlight\">آغاز کردن .</span> <font color=\"DarkGreen\"><b>[ک َ دَ ]</font></b> (مص مرکب ) بداء. ابتداء. بنیاد کردن . شروع .سر گرفتن . از سر گرفتن . انشاء. آغازیدن . آغاز نهادن . گرفتن . برداشتن . برداشت کردن . افتتاح <span class=\"hlight\">:</span> <br />بدشمن بر از خشم آواز کرد<br />تو گفتی مگر تندر آغاز کرد.<br /> <font color=\"Red\">رودکی .</font><br />سرانجام آغاز این قصه کرد<br />جوان بود چون سی ّوسه ساله مرد.<br /> <font color=\"Red\">ابوشکور.</font><br />برآغالش هر دو آغاز کرد<br />بدی گفت و نیکی همه راز کرد.<br /> <font color=\"Red\">ابوشکور.</font><br />کنیزک در گنجها باز کرد<br />ز هر گوهری جستن آغاز کرد.<br /> <font color=\"Red\">فردوسی .</font><br />همه نیکیت باید آغاز کرد<br />چو با نیکنامان بُوی در نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />ز مهراب و زال آن سخن راز کرد<br />نخستین از آن جنگ آغاز کرد.<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود تا نام او سر کنند<br />بدانگه که آغاز دفتر کنند.<br /> <font color=\"Red\">فردوسی .</font><br />نگهبان در دخمه را باز کرد<br />زن پارسا مویه آغاز کرد.<br /> <font color=\"Red\">فردوسی .</font><br />سر گنجهای کهن باز کرد<br />سپه را درم دادن آغاز کرد.<br /> <font color=\"Red\">فردوسی .</font><br />گو پیلتن جنگ را ساز کرد<br />وز آنجایگه رفتن آغاز کرد.<br /> <font color=\"Red\">فردوسی .</font><br />چو آغاز کردی بدینگونه جای <br />کجا آمدی جای از این سان بپای .<br /> <font color=\"Red\">فردوسی .</font><br />سلیح و درم دادن آغاز کرد<br />جهان را ز گردان پرآواز کرد.<br /> <font color=\"Red\">فردوسی .</font><br />من آغاز کرده بودم که بازگردم مرا بنشاند. (تاریخ بیهقی ). آغاز کرد تا پیش خواجه رود. (تاریخ بیهقی ). آغاز کردم آنچه رفته بود بشرح بازگفتم . (تاریخ بیهقی ). چون او به خرگاه رسید حدیثی آغاز کرد... و سخت سره و نغز قصه ای بود. (تاریخ بیهقی ). چون از این فصل فارغ شدم آغاز فصلی دیگر کردم . (تاریخ بیهقی ). چون ... فضیحت خویش بدید <font color=\"DarkGreen\"><b>[ شتربه ]</font></b> بمکاره آغازکند. (کلیله و دمنه ). چون کاری آغاز کند <font color=\"DarkGreen\"><b>[ شیر ]</font></b> که بصواب نزدیک ... باشد در چشم دل او آراسته گردانم . (کلیله و دمنه ).<br />نطفه را گر ز قبول درِتو مژده رسد<br />کندآغاز هم از پشت پدر خندیدن .<br /> <font color=\"Red\">ضیاءالدین پارسی .</font><br />آن امام القصه گفت آغاز کرد<br />دفتر عشاق از هم باز کرد.<br /> <font color=\"Red\">عطار (مصیبت نامه ).</font><br />یکی از آن میان زبان تعرض دراز کرد و ملامت آغاز. (گلستان ). بنشست و عتاب آغاز کرد. (گلستان ). هرگز کسی بجهل خویش اقرار نکرده است مگر آنکس که چون دیگری در سخن باشد همچنان ناتمام گفته، سخن آغاز کند. (گلستان ).<br />سخن آنگه کند حکیم آغاز<br />یا سرانگشت سوی لقمه دراز<br />که ز ناگفتنش خلل زاید<br />یا ز ناخوردنش بجان آید.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1733, 'آغازان', '<span class=\"hlight\">آغازان .</span> (نف، ق ) در حال آغازیدن .<br /></font></div>'),
(1734, 'آغازنده', '<span class=\"hlight\">آغازنده .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) مبتدی . منشی .<br /></font></div>'),
(1735, 'آغازه', '<span class=\"hlight\">آغازه .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ) نام دست افزاری است کفشگران را. (از برهان ). <BR><font color=\"Blue\">◄</font> دوالی بدرز میان رویه و زیره ٔ کفش دوخته تا گرد و آب بدرون نشود. رجوع به آغاره شود.<br /></font></div>'),
(1736, 'آغازکننده', '<span class=\"hlight\">آغازکننده .</span> <font color=\"DarkGreen\"><b>[ ک ُ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) آغازنده . مبتدی .<br /></font></div>'),
(1737, 'آغازگر', '<span class=\"hlight\">آغازگر.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (ص مرکب ) آنکه در سَبَق فرمان حرکت دهد. (فرهنگستان ).<br /></font></div>'),
(1738, 'آغازیان', '<span class=\"hlight\">آغازیان .</span> (اِ مرکب ) پرتیست . (فرهنگستان ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1739, 'آغازیدن', '<span class=\"hlight\">آغازیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) ابتداء. شروع .افتتاح . آغاز کردن . آغاز نهادن . گرفتن . سر گرفتن . بنا نهادن . بنیاد. برداشت کردن . برداشتن <span class=\"hlight\">:</span> <br />مرد مزدور اندرآغازید کار<br />پیش او دستان همی زد بی کیار .<br /> <font color=\"Red\">رودکی .</font><br />گه کشتی بیامد پیر نوساز (کذا)<br />دگر گرد و نهاد دیگر آغاز.<br /> <font color=\"Red\">کسائی (از صحاح الفرس ).</font><br />چو آغازی از جنگ پرداختن <br />بود خواب را بر تو بر، تاختن .<br /> <font color=\"Red\">فردوسی .</font><br />اگر فیلفوس این نوشتی بفور<br />تو هم رزم آغاز و بردار شور.<br /> <font color=\"Red\">فردوسی .</font><br />اگر شاخ بد خیزد از بیخ نیک <br />تو با شاخ تندی میاغاز ویک .<br /> <font color=\"Red\">فردوسی .</font><br />که جز مرگ را کس ز مادر نزاد<br />ز کسری بیاغاز تا نوش زاد.<br /> <font color=\"Red\">فردوسی .</font><br />جنگی که تو آغازی صلحی که تو پیوندی <br />شوری که تو انگیزی عذری که تو پیش آری .<br /> <font color=\"Red\">منوچهری .</font><br />با چنین کم دشمنان کی خواجه آغازد بجنگ <br />اژدها را جنگ ننگ آید که با حربا کند.<br /> <font color=\"Red\">منوچهری .</font><br />من آغازیدم عربده کردن و او را مالیدن تا چرا حدّ ادب نگاه نداشت پیش خوارزمشاه و سقطها گفت . (تاریخ بیهقی ).<br />همی این چرخ بی انجام عمرت را بینجامد<br />پس اکنون گر تو کار دین نیاغازی کی آغازی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />همه فرجامهات مسعود است <br />محکم آغاز هرچه آغازی .<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />هر زمان نوحه ای نو آغازید<br />چون بپایان رسد ز سر گیرید.<br /> <font color=\"Red\">مسعودسعد.</font><br />هر زمان ماتمی بیاغازم <br />هر نفس نوحه ای بیفزایم .<br /> <font color=\"Red\">مسعودسعد.</font><br />باز حدیث حرب بود که با خاقان آغازید. (مجمل التواریخ ). چون ... فضیحت خویش بدید. <font color=\"DarkGreen\"><b>[ شتربه ]</font></b> ... بسیجیده جنگ آغازد. (کلیله و دمنه ).<br />چون سماع آمد ز اول تا کران <br />مطرب آغازید یک لحن گران .<br /> <font color=\"Red\">مولوی .</font><br />گر بیاغازید نصحی آشکار<br />ما کنیم این دم شما را سنگسار.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> فتالیدن . (تحفةالاحباب اوبهی ). <BR><font color=\"Blue\">◄</font> قصد و اراده کردن . (برهان ).<br /></font></div>'),
(1740, 'آغازیده', '<span class=\"hlight\">آغازیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آغازکرده . مبتدی .<br /></font></div>'),
(1741, 'آغال', '<span class=\"hlight\">آغال .</span> (اِ) آغِل . <BR><font color=\"Blue\">◄</font> خانه ٔ زنبوران . زنبورخانه . <BR><font color=\"Blue\">◄</font> خانه ٔ پشه و امثال آن . <BR><font color=\"Blue\">◄</font> آغاز و ابتدا.<br /></font></div>'),
(1742, 'آغال', '<span class=\"hlight\">آغال .</span> (نف مرخم ) در کلمات مرکبه مانند مرگ آغال و بدآغال، مخفف آغالنده است <span class=\"hlight\">:</span> <br />ز روی تیغ تو اندر دو چشم دشمن تو<br />دهان گشاده نماید نهنگ مرگ آغال .<br /><font color=\"Red\">ازرقی .</font><br /></font></div>'),
(1743, 'آغال', '<span class=\"hlight\">آغال .</span> (اِ) آغار. اُغُر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بدآغال </span> ؛ بداُغُر. بدآغار <span class=\"hlight\">:</span> <br />چون کلاژه همه دزدندو رباینده چو خاد<br />همه چون بوم بدآغال و چو دمنه محتال .<br /><font color=\"Red\">معروفی .</font><br /></font></div>'),
(1744, 'آغال', '<span class=\"hlight\">آغال .</span> (اِمص ) آغالش <span class=\"hlight\">:</span> <br />ترک آغال و فتنه سازی کن <br />جامه ٔ خُلق خود نمازی کن .<br /><font color=\"Red\">؟</font><br /></font></div>'),
(1745, 'آغال پشه', '<span class=\"hlight\">آغال پشه .</span> <font color=\"DarkGreen\"><b>[ پ َش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِ مرکب ) نام درختی که آن را به عربی شجرةالبق گویند. پشه غال . سارخکدار. سارشکدار. لامشگر. کژم . کنجک . ناژین . پشه خار. پشه دار. دردار. و نام دیگرآن سده است . و خریطه گونه ها بر آن پدید آید که پشه در آن جای دارد و بعضی گفته اند که سفیدار و سفیددار وسپیدار همین درخت است .<br /></font></div>'),
(1746, 'آغالان', '<span class=\"hlight\">آغالان .</span> (نف، ق ) در حال آغالیدن .<br /></font></div>'),
(1747, 'آغالش', '<span class=\"hlight\">آغالش .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِمص ) عمل و اسم مصدر آغالیدن . بدآموزی و تحریک و انگیختن و تحریض و تحریص و اغراء و تهییج و برفژولیدن و وژولیدن بجنگ و فتنه و فساد و خصومت . تحریش و ایساد و تغریش میان دو جانور. تیز کردن کسی را بر دیگری . شورانیدن بر یکدیگر. خبث کردن میان دو تن . میان دو کس بزیان بردن <span class=\"hlight\">:</span> <br />من ز آغالشت نترسم هیچ <br />گر بمن شیر را برآغالی .<br /> <font color=\"Red\">فرالاوی .</font><br />برآغالش هر دو آغاز کرد<br />بدی گفت و نیکی همه راز کرد.<br /> <font color=\"Red\">ابوشکور.</font><br />خویشتن پاک دار و بی پرخاش <br />رو به آغالش اندرون مخراش .<br /> <font color=\"Red\">دقیقی یا لبیبی .</font><br />به آغالش هر کسی بد مکن <br />نشانه مشو پیش تیر سخن .<br /> <font color=\"Red\">اسدی .</font><br />بدو گفت نیو این هنر کار تست <br />ترا شاید این نام و این رزم جست <br />بخندید بیگاو و گفت این مباد<br />کز آغالش تو دهم سر بباد.<br /> <font color=\"Red\">اسدی .</font><br />در این باب سفاح را همی گفت و آغالش همی کرد که تا بومسلم را نخوانی و نکشی کار تو استقامت نگیرد. (مجمل التواریخ ).<br /></font></div>'),
(1748, 'آغالشگر', '<span class=\"hlight\">آغالشگر.</span> <font color=\"DarkGreen\"><b>[ ل ِ گ َ ]</font></b> (ص مرکب ) محرِّض . <BR><font color=\"Blue\">◄</font> مفتِّن .<br /></font></div>'),
(1749, 'آغالشگری', '<span class=\"hlight\">آغالشگری .</span> <font color=\"DarkGreen\"><b>[ ل ِ گ َ ]</font></b> (حامص مرکب ) تحریض . <BR><font color=\"Blue\">◄</font> تفتین .<br /></font></div>'),
(1750, 'آغالنده', '<span class=\"hlight\">آغالنده .</span> <font color=\"DarkGreen\"><b>[ ل َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) محرِّض .<br /></font></div>'),
(1751, 'آغالیدن', '<span class=\"hlight\">آغالیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) انگیختن و تحریک و اغرا و برشورانیدن و تیز کردن بر خصومت و جنگ و فتنه . بشورانیدن بر کسی . آشوفتن کسی بر دیگری <span class=\"hlight\">:</span> شتربه ... گفت واجب نکند که شیر بر من غدر کند لیکن او را بدروغ بر من آغالیده باشند. (کلیله و دمنه ).<br />بر آغالیدنش استیز کردند<br />بکینه چون پلنگش تیز کردند.<br /> <font color=\"Red\">ابوشکور.</font><br />تو لشکر برآغال بر لشکرش <br />بیکبار تا خیره گردد سرش .<br /> <font color=\"Red\">فردوسی .</font><br />مطربان را بهم برآغالد<br />وز میانه سبک برون کالد.<br /> <font color=\"Red\">مسعودسعد.</font><br />سگ سگ است ارچه بیاغالندش <br />کاستخوان خواره ٔ شیر اجم است .<br /> <font color=\"Red\">خاقانی .</font><br />و رجوع به برآغالیدن و بیاغالیدن شود. <BR><font color=\"Blue\">◄</font> آشوفتن . پریشان و پراکنده کردن . بر باد دادن <span class=\"hlight\">:</span> <br />بگرد عارض آن زلف را بیاغالد<br />بروم قافله ٔ زنگبار بگشاید.<br /> <font color=\"Red\">حسن کاشی .</font><br />برای این معنی رجوع به آغالیش شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">برآغالیدن چشم بر کسی </span> ؛ دریدن چشم بر روی کسی از روی غضب، یا بگوشه ٔ چشم دیدن در او به تحقیر. حملقه <span class=\"hlight\">:</span> <br />که با خشم چشم ار برآغالدت <br />بیک دم هم از دور بفتالدت .<br /> <font color=\"Red\">اسدی .</font><br />رجوع به آغول و آغیل و چشم آغیل شود. محارشه ؛ سگان را بر یکدیگر برآغالیدن . (زوزنی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بر یکدیگر برآغالیدن </span> ؛ توریش . (زوزنی ).<br /><BR><font color=\"Blue\">◄</font> ناجویده فروبردن . بلع. اوباریدن . (برهان ). <BR><font color=\"Blue\">◄</font> تنگ فراگرفتن . (برهان ). و این مصدر متعدی است و از آنروآغالانیدن و آغالاندن نیامده است .<br /></font></div>'),
(1752, 'آغالیده', '<span class=\"hlight\">آغالیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) تیزکرده و برانگیخته و برشورانیده و آشوفته بر خصومت .<br /></font></div>'),
(1753, 'آغالیش', '<span class=\"hlight\">آغالیش .</span> (اِمص )بر باد دادن خرمن کاه و غیره . (فرهنگ اسدی، خطی ).<br /></font></div>'),
(1754, 'آغاندن', '<span class=\"hlight\">آغاندن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آغاردن . تر نهادن . خیسانیدن .<br /></font></div>'),
(1755, 'آغاپنبه', '<span class=\"hlight\">آغاپنبه .</span> <font color=\"DarkGreen\"><b>[ پَم ْ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ مرکب ) صورت پنبه ای که در عروسیها برای مسخرگی سازند.<br /></font></div>'),
(1756, 'آغاچی', '<span class=\"hlight\">آغاچی .</span> (ترکی، اِ مرکب ) اَغاجی و آغاجی و آغجی نیز در کتب آمده است، و ظاهراً بمعنی حاجب و پرده دار است، و اوچون واسطه ٔ بلاغ میان شاه و مردم یا وزراء بوده است <span class=\"hlight\">:</span> ملطفه به نزدیک اغاجی خادم خاصه بردم و بدو دادم و جائی فرود آمدم نزدیک سرای پرده وقت سحرگاه فراشی آمد و مرا بخواند برفتم اَغاجی مرا پیش برد. (تاریخ بیهقی ). استادم رقعتی نوشت سخت درشت و بوثاق اَغاچی آمد و رقعه بدو داد و ضمان کرد که وقتی سره جوید و برساند و پس بازآمد بدیوان و بر آغاچی پیغام را شتاب میکرد. (تاریخ بیهقی ). رقعتی نوشتم بامیر چنانکه رسم است که نویسند در معنی استعفا... و آن رقعه به اَغاچی دادم و برسانید. (تاریخ بیهقی ). و در جامعالتواریخ تحت عنوان الحجاب، یعنی حجاب طغرل بیک سلجوقی نام یکی از آنان را بدینگونه برده است : النذر الاغاجی . و نیز در راحةالصدور راوندی نام حاجبی را نگاشته است بدین صورت : الحاجب عبدالرحمن الب زن الاَغاجی . الحاجب عبدالرحمن الاَّغاجی .<br /></font></div>'),
(1757, 'آغر', '<span class=\"hlight\">آغر.</span> <font color=\"DarkGreen\"><b>[ غ َ ]</font></b> (اِ) خشک رود که سیلاب از آن قطع شده و جاجا آب ایستاده بود <span class=\"hlight\">:</span> <br />فرازش پر از خون چوکوه تبرخون <br />نشیبش ز اشکم چو ارغاب و آغر.<br /><font color=\"Red\">عمعق .</font><br /></font></div>'),
(1758, 'آغردن', '<span class=\"hlight\">آغردن .</span> <font color=\"DarkGreen\"><b>[ غ َ دَ ]</font></b> (مص ) خوردن . (فرهنگ اسدی، خطی ) <span class=\"hlight\">:</span> <br />باده خوریم اکنون با دوستان <br />زآنکه بدین وقت می آغرده به .<br /><font color=\"Red\">خفاف (ازفرهنگ اسدی، خطی ).</font><br /></font></div>'),
(1759, 'آغرده', '<span class=\"hlight\">آغرده .</span> <font color=\"DarkGreen\"><b>[ غ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) نم دیده . خیسیده . ترشده <span class=\"hlight\">:</span> <br />بدرد خاست کمرگاه و پشتت از ترّی <br />که پوشش زبرین تو بود آغرده .<br /> <font color=\"Red\">سوزنی .</font><br />معنی جامه ٔ تنگ و نازک و نیز تنگ و پاره پاره بدین کلمه داده و به همین بیت استشهاد کرده اندو ظاهراً همان معنی خیسیده و نم دیده انسب است، مگر شواهد دیگری یافته شود. <BR><font color=\"Blue\">◄</font> خوردشده .<br /></font></div>'),
(1760, 'آغری', '<span class=\"hlight\">آغری .</span> <font color=\"DarkGreen\"><b>[ غ َ ]</font></b> (اِ) آغاری .<br /></font></div>'),
(1761, 'آغریداغ', '<span class=\"hlight\">آغریداغ .</span> (اِخ ) (از کردی ِ آگْری، آذری + فارسی ِ داغ، خشک . بی علف ) آرارات . کوه نوح . مازیک .و آن دارای دو قله است که یکی به آغریداغ کوچک و دیگری به آغریداغ بزرگ معروف است . و این کوه حد میان ایران و روس و ترکیه است در <span class=\"hlight\" dir=\"rtl\">٤٥</span> درجه ٔ طول شرقی گرینویچ و <span class=\"hlight\" dir=\"rtl\">٣٩</span> درجه ٔ عرض شمالی . خط سرحدی ایران و عراق از آغریداغ بزرگ گذرد و نقطه ٔ سرحدی موسوم بمردآزماست .<br /></font></div>'),
(1762, 'آغریقی', '<span class=\"hlight\">آغریقی .</span> (ص نسبی ) (مشتق از لاطینی ِ گْرِکوس ) اِغریقی . یونانی .<br /></font></div>'),
(1763, 'آغریقیه', '<span class=\"hlight\">آغریقیه .</span> <font color=\"DarkGreen\"><b>[ قی ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (ص نسبی ) تأنیث آغریقی . یونانیه . و رجوع به رومیة شود.<br /></font></div>'),
(1764, 'آغریوس', '<span class=\"hlight\">آغریوس .</span> (یونانی، اِ) حلیمو. حماض البقر. سلق برّی . سلق جبلی . جلناق . آزاددارو. ترشینک . طوطاغ آغرس . سرخ پای . هلموت .<br /></font></div>'),
(1765, 'آغز', '<span class=\"hlight\">آغز.</span> <font color=\"DarkGreen\"><b>[ غ ُ ]</font></b> (اِ) شیرماک . رجوع به آغوز شود.<br /></font></div>'),
(1766, 'آغزون', '<span class=\"hlight\">آغزون .</span> (اِخ ) نام قریه ای به بخارا، مسقطالرأس ابوعبداﷲ عبدالواحدبن محمدبن عبداﷲ آغزونی .<br /></font></div>'),
(1767, 'آغستن', '<span class=\"hlight\">آغستن .</span> <font color=\"DarkGreen\"><b>[ غ َ ت َ ]</font></b> (مص ) انباشتن و پر کردن با فشار و زور. چپاندن . تپاندن .<br /></font></div>'),
(1768, 'آغسته', '<span class=\"hlight\">آغسته .</span> <font color=\"DarkGreen\"><b>[ غ َ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف ) بفشار پرکرده . چپانده .<br /></font></div>'),
(1769, 'آغش', '<span class=\"hlight\">آغش .</span> <font color=\"DarkGreen\"><b>[ غ ُ ]</font></b> (اِ) مخفّف آغوش .<br /></font></div>'),
(1770, 'آغشتن', '<span class=\"hlight\">آغشتن .</span> <font color=\"DarkGreen\"><b>[ غ َ <span class=\"hlight\" dir=\"rtl\">/</span> غ ِ ت َ ]</font></b> (مص ) تر نهادن . خیس کردن . خیساندن . فژغردن . نرم کردن با تری و نم . سرشتن . آغاریدن . آغاردن . انقاع . نقع. <BR><font color=\"Blue\">◄</font> آلودن . ضمخ . تضمیخ . مضخ . تضمخ . لطخ . تلطیخ . تر کردن . رجوع به آغشته شود. <BR><font color=\"Blue\">◄</font> و بمعنی آمیختن و مزج و خلط نیز آورده اند لیکن شواهدی که می آورند بهمان معانی پیشین انسب است . این فعل لازم و متعدی هر دو آید.و ظاهراً مصدر دوم آن آغارش باشد. آغشتم . بیاغار.<br /></font></div>'),
(1771, 'آغشتنی', '<span class=\"hlight\">آغشتنی .</span> <font color=\"DarkGreen\"><b>[ غ َ <span class=\"hlight\" dir=\"rtl\">/</span> غ ِ ت َ ]</font></b> (ص لیاقت ) درخور آغشتن . ازدرِ آغشتن .<br /></font></div>'),
(1772, 'آغشته', '<span class=\"hlight\">آغشته .</span> <font color=\"DarkGreen\"><b>[ غ َ <span class=\"hlight\" dir=\"rtl\">/</span> غ ِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) نرم کرده با نم و تری . ترنهاده . خیسانیده . خیس کرده . آغارده . آغاریده . فژغرده . <BR><font color=\"Blue\">◄</font> آلوده . مضمخ . ملطخ . ترکرده . مبلول . <BR><font color=\"Blue\">◄</font> آمیخته . ممزوج . مخلوط. (از فرهنگها). <BR><font color=\"Blue\">◄</font> زمین آب داده . (از برهان ) <span class=\"hlight\">:</span> <br />فروبارم خون از مژه چنان <br />که آغشته کنم سنگ را ز خون .<br /> <font color=\"Red\">حکاک .</font><br />دو بهره ز توران سپه کشته شد<br />ز خونْشان زمین چون گل آغشته شد.<br /> <font color=\"Red\">فردوسی .</font><br />فراوان از ایرانیان کشته بود<br />ز خون یلان کشور آغشته بود.<br /> <font color=\"Red\">فردوسی .</font><br />مرا رحمت آید بتو بر ز دل <br />که از خونت آغشته گشته ست گل .<br /> <font color=\"Red\">فردوسی .</font><br />از ایرانیان من بسی کشته ام <br />زمین را بخون چون گل آغشته ام .<br /> <font color=\"Red\">فردوسی .</font><br />بخون گشته آغشته هامون و کوه <br />ز بس کشته آمد ز هر دو گروه .<br /> <font color=\"Red\">فردوسی .</font><br />بهنگام نان شیر گرم آوری <br />بدان شیر این چرم نرم آوری <br />بشیر اندر آغاری این چرم خر<br />چنان چون که گردد بگیتی سمر...<br />دو هفته سپهر اندرین گشته شد<br />بفرجام چرم خر آغشته شد.<br /> <font color=\"Red\">فردوسی .</font><br />بسا شیر مردان که من کشته ام <br />زمین را بخونْشان برآغشته ام .<br /> <font color=\"Red\">فردوسی .</font><br />همه دشت از کشته چون پشته گشت <br />بخون و به خاک اندر آغشته گشت .<br /> <font color=\"Red\">فردوسی .</font><br />همچو لاله ز خون دل آغشته <br />متحیر بماند و سرگشته .<br /> <font color=\"Red\">عنصری .</font><br />عقل با آب رویش آغشته <br />سهو در گرد دینْش ناگشته .<br /> <font color=\"Red\">سنائی .</font><br />همه دشت پر خسته و کشته شد<br />زمین سربسر چون گل آغشته شد.<br /> <font color=\"Red\">شرف شفروه .</font><br />زمینش به آب زر آغشته اند<br />تو گوئی در آن زعفران کشته اند.<br /> <font color=\"Red\">نظامی .</font><br />دلیران جهان آغشته در خون <br />تو سرپوشیده نَنْهی پای بیرون .<br /><font color=\"Red\">شیخ محمود شبستری .</font><br /></font></div>'),
(1773, 'آغشته شدن', '<span class=\"hlight\">آغشته شدن .</span> <font color=\"DarkGreen\"><b>[ غ َ <span class=\"hlight\" dir=\"rtl\">/</span> غ ِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ش ُ دَ ]</font></b> (مص مرکب ) آغشتن .<br /></font></div>'),
(1774, 'آغشته کردن', '<span class=\"hlight\">آغشته کردن .</span> <font color=\"DarkGreen\"><b>[ غ َ <span class=\"hlight\" dir=\"rtl\">/</span> غ ِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ک َ دَ ]</font></b> (مص مرکب ) آغشتن .<br /></font></div>'),
(1775, 'آغشتگی', '<span class=\"hlight\">آغشتگی .</span> <font color=\"DarkGreen\"><b>[ غ َ <span class=\"hlight\" dir=\"rtl\">/</span> غ ِ ت َ<span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص ) چگونگی و کیفیت و حال و صفت آغشته .<br /></font></div>'),
(1776, 'آغل', '<span class=\"hlight\">آغل .</span> <font color=\"DarkGreen\"><b>[ غ ِ <span class=\"hlight\" dir=\"rtl\">/</span> غ ُ ]</font></b> (اِ) جای گوسفندان و گاوان و دیگر چارپایان بشب در خانه یا کوه وبیشتر کنده ای در زیرزمین باشد. کمرا. شب گاه . شبغا. شوگاه . آغیل . شوغا. شب غاز. شب غازه . شوغار. شوغاره . شب غاو. آغول . نَغِل . نُغول . باغل . غال . آغال . غول . غوشا. غوشاد. غوشاک . کاز. زاغه . غاو. کنده . چپر. خبک . خباک . خپاک . سم . سمج . سمجه . دیل . بیکند <span class=\"hlight\">:</span> <br />برو برو که خران آمدند به آغلها<br />خر جوان و خر پیر و خرّ یکساله .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> هاله . خرمن ماه . دارَه . شابورد. شادورد. خرگاه، خرگه ماه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">حساب بز گر را در آغل کنند</span> ؛ غالباً بزان گر در چراگاه میرند و شب به آغل بازنگردند. و در نظایر مورد، این مثل را بکار برند.<br /></font></div>'),
(1777, 'آغلس', '<span class=\"hlight\">آغلس .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (از یونانی، اِ) اِغلیفس . دَوسَر. (مخزن الادویه ).<br /></font></div>'),
(1778, 'آغلیس', '<span class=\"hlight\">آغلیس .</span> (از یونانی، اِ) (بمعنی طاهر) فنجنکشت . (مخزن الادویه ). پنج انگشت . فنطافلون . ذو خمسة اوراق . ذو خمسةاصابع. دل آشوب . سگسنبویه . فقد. فقده . سیسبان . اثلق .بنطافلن . بنطاباطیس . بنطاطومن . بنطادقطولن . آغنس .<br /></font></div>'),
(1779, 'آغندن', '<span class=\"hlight\">آغندن .</span> <font color=\"DarkGreen\"><b>[ غ ُ دَ ]</font></b> (مص ) تر نهادن . خیساندن .<br /></font></div>'),
(1780, 'آغندن', '<span class=\"hlight\">آغندن .</span> <font color=\"DarkGreen\"><b>[ غ َ دَ ]</font></b> (مص ) آکندن .<br /></font></div>'),
(1781, 'آغنده', '<span class=\"hlight\">آغنده .</span> <font color=\"DarkGreen\"><b>[ غ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آکنده <span class=\"hlight\">:</span> <br />دل ز مهر جهانیان کنده <br />وآنگه از مهر دوست آغنده .<br /> <font color=\"Red\">امیرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دل آغنده </span> ؛ غمین . غمگن . حزین .<BR>۩ مصمم . جازم <span class=\"hlight\">:</span> <br />فرنگیس با رنج دیده پسر<br />بخواب اندر آورده بودند سر<br />ز پیمودن راه و رنج شبان <br />مر آن هر دو را گیو بد پاسبان <br />زره در بر و بر سرش نیز ترگ <br />دل آغنده و تن نهاده بمرگ .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1782, 'آغنده', '<span class=\"hlight\">آغنده .</span> <font color=\"DarkGreen\"><b>[ غ ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ) پنبه ٔ پیچیده و گردکرده باشد ریشتن را. کلوچ . باغنده . پاغنده . غنده . غندش . <BR><font color=\"Blue\">◄</font> نوعی از عنکبوت زهردار. رتیلا. رُتیل . غنده .<br /></font></div>'),
(1783, 'آغنس', '<span class=\"hlight\">آغنس .</span> <font color=\"DarkGreen\"><b>[ ن ُ ]</font></b> از یونانی ویتکس آگنوس . پنج انگشت . فنجنکشت . بنطافلن . بنطاباطیس . بنطاطومن . بنطادقطولن . ذو خمسة اوراق . ذو خمسة اصابع. دل آشوب . سکسنبویه . فقد. فقده . سیسبان . اثلق . فنطافلون . و آغلیس و آغیش مصحف این کلمه است .<br /></font></div>'),
(1784, 'آغو', '<span class=\"hlight\">آغو.</span> (اِ) دفلی . (مخزن الادویه ). خرزهره . سَم ّالحمار. حبن . حبین . پَهی . خوره .<br /></font></div>'),
(1785, 'آغورس', '<span class=\"hlight\">آغورس .</span> (اِ) ابهل . (مخزن الادویه ). صفینه . وُهْل .<br /></font></div>'),
(1786, 'آغوز', '<span class=\"hlight\">آغوز.</span> <font color=\"DarkGreen\"><b>[ غو <span class=\"hlight\" dir=\"rtl\">/</span> غُزْ ]</font></b> (اِ) آغُز. شیرِ ماده ٔ نوزائیده . ماک . شیرماک . پَله . پَلّه . فَله . فَلّه . فُرش . فُرشه . زِهَک . گورماست . لبا. کنف .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آغوز</span> ؛ ماستی ستبر.<br /></font></div>'),
(1787, 'آغوز', '<span class=\"hlight\">آغوز.</span> (اِ) نام درختی است جنگلی که از چوب آن میز و صندلی و مانند آن سازند و در جنگلهای ایران بسیار است .<br /></font></div>'),
(1788, 'آغوزگول', '<span class=\"hlight\">آغوزگول .</span> (اِخ ) نام محلی در راه رشت و انزلی، میان گرفن و سره دشت در <span class=\"hlight\" dir=\"rtl\">٣٥٠٥٠٠</span>گزی طهران .<br /></font></div>'),
(1789, 'آغوش', '<span class=\"hlight\">آغوش .</span> (اِ) آگوش . آگش . بغل . میان دو دست فراهم آورده چون از آن دو، دائره واری کنند <span class=\"hlight\">:</span> <br />پیری آغوش باز کرده فراخ <br />تو همی گوش با شکافه ٔ غوش .<br /> <font color=\"Red\">کسائی .</font><br />سیاوش فرود آمد از نیل رنگ <br />پیاده گرفتش <font color=\"DarkGreen\"><b>[ پیران را ]</font></b> به آغوش تنگ .<br /> <font color=\"Red\">فردوسی .</font><br />گرفتش به آغوش کاوس شاه <br />ز زالش بپرسید و از رنج راه .<br /> <font color=\"Red\">فردوسی .</font><br />ز من بد سخن نشنود گوش تو<br />جدائی نجویم ز آغوش تو.<br /> <font color=\"Red\">فردوسی .</font><br />همی تیره بینم دل و هوش تو<br />همی گور بینم در آغوش تو.<br /> <font color=\"Red\">فردوسی .</font><br />تو بندوی را سر به آغوش گیر<br />مگو ایچ گفتارنادلپذیر.<br /> <font color=\"Red\">فردوسی .</font><br />در آغوش آنچنان گیرم تنت را<br />که نَبْوَد آگهی پیراهنت را.<br /> <font color=\"Red\">نظامی .</font><br />می باش چو خار حربه بر دوش <br />تا خرمن گل کشی در آغوش <br />هزار آغوش را پر کرده از خار<br />یک آغوش از گلش ناچیده دیّار.<br /> <font color=\"Red\">نظامی .</font><br />وصال دولت بیدار ترسمت ندهند<br />که خفته ای تو در آغوش بخت خواب زده .<br /> <font color=\"Red\">حافظ.</font><br />مرگ اگر مرد است گو نزد من آی <br />تا در آغوشش بگیرم تنگ تنگ <br />من از او عمری ستانم جاودان <br />او ز من دلقی رباید رنگ رنگ .<br /> <font color=\"Red\">؟</font><br />و این کلمه غیر از بَر و کِنار فارسی و حجر عربی است، چه در بر گرفتن و در کنار گرفتن تنها با یک دست نیم حلقه کرده و با یک سوی تن گرفتن باشد.و بغل در استعمال کنونی اعم از آغوش و بر و کنار است <span class=\"hlight\">:</span> <br />یکی ساعت از وی نبودش قرار<br />در آغوش بودیش یا در کنار.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> توسعاً، گردن <span class=\"hlight\">:</span> <br />ور نبود دلبر همخوابه پیش <br />دست توان کرد در آغوش خویش .<br /> <font color=\"Red\">سعدی (گلستان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">در آغوش گرفتن </span> ؛ به آغوش کشیدن . در میان دو دست فراهم آورده، بخود دوسانیدن کسی یا چیزی را.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یکدیگر را در آغوش کشیدن </span> ؛ تعانق . معانقه .<br /> <BR><font color=\"Blue\">◄</font> آن مقدار از گیاه یا چوب و کاغذ و مانند آن که به آغوش توان برداشت : یک آغوش ؛ یک بَغل .<br />آن روی او بسان یک آغوش غوش خشک <br />وآن موی او بسان یک آغوش غوشنه .<br /> <font color=\"Red\">یوسف عروضی .</font><br />هزارآغوش را پر کرده از خار<br />یک آغوش از گلش ناچیده دیّار.<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آغوش بستن کتاب </span> ؛ ضبر کتب . (ادیب نطنزی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یک آغوش از هر چیز که باشد</span> ؛ حزمه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یک آغوش کتاب یا کاغذ</span> ؛ اضباره .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یک آغوش گیاه </span> ؛ ضغث .<br /> <BR><font color=\"Blue\">◄</font> نامی از نامهای غلامان و بندگان ترک <span class=\"hlight\">:</span> <br />ای خواجه ٔ ارسلان و آغوش <br />فرمان ده خود مکن فراموش .<br /> <font color=\"Red\">سعدی .</font><br />وشاقی پریچهره در خیل داشت <br />که طبعش بدو اندکی میل داشت ...<br />مگر پاسبانت فراموش شد<br />که دستت در آغوش آغوش شد؟<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1790, 'آغوشتن', '<span class=\"hlight\">آغوشتن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص ) در آغوش گرفتن . (از شعوری ).<br /></font></div>'),
(1791, 'آغوشیدن', '<span class=\"hlight\">آغوشیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) در بغل گرفتن . در بر کشیدن . (برهان ). <BR><font color=\"Blue\">◄</font> بغل . خیس کردن . (شعوری از اسدی ).<br /></font></div>'),
(1792, 'آغول', '<span class=\"hlight\">آغول .</span> (اِ) آغل . زاغه . <BR><font color=\"Blue\">◄</font> چشم آغول ؛ چشم آغیل .<br /></font></div>'),
(1793, 'آغوندن', '<span class=\"hlight\">آغوندن .</span><font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) در دهان خیسانیدن چیزی را، چون آلو و انجیر خشک و مانند آن تا مضغ و خائیدن آن آسان شود.<br /></font></div>'),
(1794, 'آغونیدن', '<span class=\"hlight\">آغونیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آغوندن .<br /></font></div>'),
(1795, 'آغیش', '<span class=\"hlight\">آغیش .</span> (از یونانی، اِ) به معنی طاهر به یونانی، فنجنکشت . (مخزن الادویه ). رجوع به آغلیس شود .<br /></font></div>'),
(1796, 'آغیل', '<span class=\"hlight\">آغیل .</span> (اِ) ستورگاه . ستورخانه . آخور. اصطبل . (زمخشری ). جای برای گوسفندان و گاوان به شب . و امروز آغِل به کسر غین گویند، و نیز آغُل بضم غین و آغول .<br /></font></div>'),
(1797, 'آغیل', '<span class=\"hlight\">آغیل .</span> (اِ) این کلمه با چشم مرکب شود و صورت مرکبه، بخشم دیدن معنی دهد <span class=\"hlight\">:</span> <br />نرمک او را یکی سلام زدم <br />کرد زی من نظر بچشم آغیل .<br /> <font color=\"Red\">حکاک .</font><br />چشم آغول و چشم آلوس مرادف آن است و امروز چشم غُله رفتن، بغضب و با چشمهای دریده در کسی دیدن است بقصد تهدید و ترسانیدن او.<br /></font></div>'),
(1798, 'آغیه', '<span class=\"hlight\">آغیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) جویچه که برای آبیاری بسوی کشت آرند. <BR><font color=\"Blue\">◄</font> بندآب . (مهذب الاسماء). ج، اَواغی .<br /></font></div>'),
(1799, 'آف', '<span class=\"hlight\">آف .</span> (اِ) آهوی تاتار. آهوی چین . آهوی ختن . آهوی خطا. آهوی مشک . آهوی مشکین . غزال المسک . <BR><font color=\"Blue\">◄</font> مِهر. خور. شمس .<br /></font></div>'),
(1800, 'آفات', '<span class=\"hlight\">آفات .</span> (ع اِ) ج ِ آفت (آفة). آسیبها <span class=\"hlight\">:</span> آن چهار که مطلوب است و بدین اغراض بجز آن نتوانند رسید، کسب مال است از وجهی پسندیده ... و صیانت نفس از حوادث و آفات آنقدر که در امکان درآید. (کلیله و دمنه ). و حوادث و آفات عارضی ... در کمین . (کلیله و دمنه ).<br />بنفشه با شقایق در مناجات <br />فلک میگفت فی التأخیر آفات .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفات آسمانی </span> ؛ در زراعت، آسیبهای جوّی که به کشت رسد، چون سِن و تگرگ و ملخ و شجام و زنگ و امثال آن .<br /><BR><font color=\"Blue\">◄</font> مصائب . بلیات . مِحَن .<br /></font></div>'),
(1801, 'آفار', '<span class=\"hlight\">آفار.</span> (اِخ ) نام قریه ای به بحرین، و میان آن و قطیف چهار فرسنگ راه است . و آن را آنار نیز ضبط کرده اند.<br /></font></div>'),
(1802, 'آفاق', '<span class=\"hlight\">آفاق .</span> (ع اِ) ج ِ افق . کران ها. کرانه های آسمان . اطراف . اطراف هامون . نواحی . اقطار. <BR><font color=\"Blue\">◄</font> عالم . گیتی . جهان . جایها، و توسعاً زمانه . روزگار <span class=\"hlight\">:</span> <br />در آفاق هرجا ز نزدیک و دور<br />نبد کآن نه از فرّ اویافت نور.<br /> <font color=\"Red\">فردوسی .</font><br />بجست آنکه هرگز نجسته ست کس <br />سخن ماند از وی در آفاق و بس .<br /> <font color=\"Red\">فردوسی .</font><br />ملک همه آفاق بدو روی نهاده ست <br />هرچ آن پدرش را نگشاد او بگشاده ست .<br /> <font color=\"Red\">منوچهری (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٥٢</span>).</font><br />که دار ملک تو را جز به نام ما ناید<br />طراز کسوة آفاق و سکه دینار.<br /> <font color=\"Red\">(از تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٨٠</span>).</font><br />روزی برسیدم بدر شهری کآن را<br />اجرام فلک بنده بدآفاق مسخر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای خداوندی کِت نیست در آفاق نظیر<br />رحمت و فضل تو زی حجت تو مستتر است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آفاق جهان زیر اوست و او خود<br />بیرون ز جهانست و در جهانست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چو عهد عدو جرم آفاق تیره <br />چو تیغ یلان روی مریخ احمر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و ذکر آن در آفاق سایر شود. (کلیله و دمنه ). و ذکر آن در آفاق و اقطار عالم سایر و مبسوط گشت . (کلیله و دمنه ).<br />زهی دین طرازی که بی نقش نامت <br />در آفاق یک حرف معجم ندارم .<br /> <font color=\"Red\">خاقانی .</font><br />عیاره ٔ آفاق است این یار که من دارم <br />بازیچه ٔ ایام است این کار که من دارم .<br /> <font color=\"Red\">خاقانی .</font><br />بی ادب تنها نه خود را داشت بد<br />بلکه آتش در همه آفاق زد.<br /> <font color=\"Red\">مولوی .</font><br />چون مرد برفتاد ز جای و مقام خویش <br />دیگر چه غم خورد همه آفاق جای اوست .<br /> <font color=\"Red\">سعدی .</font><br />سرتاسر آفاق بهیچم نخرند<br />یارب چه متاعم که خریدارم نیست .<br /> <font color=\"Red\">اوحدی .</font><br />هرچه در آفاق زخیر و ز شر<br />هرکه در آفاق شناسد مگر.<br /> <font color=\"Red\">خواجو.</font><br />همه اطراف گرفت و همه آفاق گشاد<br />صیت مسعودی و آوازه ٔشه سلطانی .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفاق حمایلی، آفاق مایله </span> ؛ نقاطی از زمین که در غیر خط استوا و دو قطب واقع شده است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفاق دولابی (استوائی )</span> ؛ نقاطی از زمین که بر خط استواست .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفاق رَحَوی </span> ؛ نقاطی از زمین که در قطب شمال یا جنوب افتاده است .<br /></font></div>'),
(1803, 'آفاقی', '<span class=\"hlight\">آفاقی .</span> (ص نسبی ) منسوب به آفاق .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سیر آفاقی </span> ؛ در اصطلاح صوفیه و ارباب سلوک، دیدن جهان . سیر در بیرون نفس . مقابل سیر انفسی وخارجی . متخذ از این آیت قرآن <span class=\"hlight\">:</span> سنریهم آیاتنا فی الاَّفاق و فی انفسهم حتی یتبین لهم انه الحق ّ. (<span class=\"hlight\" dir=\"rtl\">٥٣/٤١</span>).<br /><BR><font color=\"Blue\">◄</font> (اصطلاح فقه ) افقی . آنکه در بیش از شانزده فرسنگی خانه اقامت دارد و او مکلف به گزاردن حج ّ تمتع است .<br /></font></div>'),
(1804, 'آفت', '<span class=\"hlight\">آفت .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (ع اِ) (شاید از ریشه ٔ آکفت فارسی ) آفة. آفه . عاهت . عاهه . عارضه . (زمخشری ).جانحه . زحمت . علت . بلا. بلیه . ضرر. آکفت . آسیب . بیماری . (ربنجنی ). گزند. عیب . آهو. ج، آفات <span class=\"hlight\">:</span> <br />رسیده آفت نشبیل او به هر کامی <br />نهاده کشته ٔ آسیب او به هر مشهد.<br /> <font color=\"Red\">منجیک .</font><br />خردمند باشید و پاکیزه دین <br />از آفت همه پاک و بیرون ز کین .<br /> <font color=\"Red\">فردوسی .</font><br />سزاوارتر که روح را نیز طبیبان و معالجان گزینند تا آن وقت آن آفت را معالجه کنند.(تاریخ بیهقی ). وقتی که مردم در خشم شود... حاجتمند شود بطبیبی که آن آفت را علاج کند. (تاریخ بیهقی ). وقتی که مردم در خشم شود سطوتی در او پیدا آید در آن ساعت بزرگ آفتی بر خرد وی مستولی باشد. (تاریخ بیهقی ).<br />دست من گیر ای اله العالمین <br />زین پرآفت جای و چاه تاربام .<br /> <font color=\"Red\">ناصرخسرو.</font><br />هرک آفت خلاف علی هست بر دلش <br />تو روی از او بتاب و بپرهیز از آفتش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />در هدی نگشاید مگر کلید سخن <br />هم او گشاید درهای آفت و بلوی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گر هیچ چاره کرد ندانم غم ترا<br />این دل که آفت است پس ِ تو رها کنم .<br /> <font color=\"Red\">مسعودسعد.</font><br />یک آفتم را هر روز صد طریق نهند<br />یک اندهم را هر شب هزار باب کنند.<br /> <font color=\"Red\">مسعودسعد.</font><br />چون سرگذشت مجنون پر فتنه و بلا<br />چون داستان وامق پر آفت و خطر.<br /> <font color=\"Red\">مسعودسعد.</font><br />شاه بی بخشش آفت سپه است <br />بی نیازی سپاه، ذل شه است .<br /> <font color=\"Red\">سنائی .</font><br />دوستیَّت مبادبا نادان <br />که بود دوستیش آفت جان .<br /> <font color=\"Red\">سنائی .</font><br />آفت عقل تصلف است . (کلیله و دمنه ).گویند آفت ملک شش چیز است حرمان و... (کلیله و دمنه ). از عثرت رای دروقت آفت تمتعی زیادت نتوان یافت . (کلیله و دمنه ). وآدمی از آن روز که در رحم نطفه گردد تا آخر عمر یک لحظه از آفت نرهد. (کلیله و دمنه ). من دنیا را بدان چاه پرآفت ... مانند کردم . (کلیله و دمنه ). کسی گفتش چه آفت است که موجب چندین مخافت است ؟ (گلستان ).<br />خروش از شهر بنشاند هر آنگاهی که بنشیند<br />هزار آفت برانگیزد هر آنگاهی که برخیزد.<br /> <font color=\"Red\">معزی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفت دین و دل </span> ؛ در زبان شعری، معشوقی سخت جمیل .<br /> <BR><font color=\"Blue\">◄</font> آسیب که کشت را رسد، چون مَلخ و سن و تگرگ و زنگ و شجام و برق و صاعقه و سیل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفت ارضی </span> ؛ آسیب زمینی از قبیل زلزله و خسف .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفت سماوی </span> ؛ آسیب جَوّی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آفت رسیده را غم باج و خراج نیست </span> .<br /><span class=\"hlight\">پر عقاب آفت عقاب است </span> . <br /></font></div>'),
(1805, 'آفت دیو', '<span class=\"hlight\">آفت دیو.</span> <font color=\"DarkGreen\"><b>[ ف َ ت ِ وْ ]</font></b> (ترکیب اضافی، اِ مرکب ) صرع . دیوزدگی <span class=\"hlight\">:</span> <br />تا برند از طریق چاره گری <br />آفت دیو را ز جان پری .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(1806, 'آفت رسیده', '<span class=\"hlight\">آفت رسیده .</span> <font color=\"DarkGreen\"><b>[ ف َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) آفت زده . مَؤوف . آکفت دیده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کِشتی آفت رسیده </span> ؛ بسن یا ملخ یا تگرگ یا خشکی یا زنگ و یرقان و یا سرمازدگی و مانند آن زیان دیده . آفت زده .<br /></font></div>'),
(1807, 'آفت رسیدگی', '<span class=\"hlight\">آفت رسیدگی .</span> <font color=\"DarkGreen\"><b>[ ف َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص مرکب ) چگونگی و صفت آفت رسیده . آفت زدگی .<br /></font></div>'),
(1808, 'آفت زده', '<span class=\"hlight\">آفت زده .</span> <font color=\"DarkGreen\"><b>[ ف َ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) آفت رسیده . کِشتی به آفتهائی چون تگرگ و شجام و ملخ و سن و زنگ و سیل دچارشده .<br /></font></div>'),
(1809, 'آفت زدگی', '<span class=\"hlight\">آفت زدگی .</span> <font color=\"DarkGreen\"><b>[ ف َ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص مرکب ) چگونگی آفت زده .<br /></font></div>'),
(1810, 'آفتاب', '<span class=\"hlight\">آفتاب .</span> (اِ مرکب ) (از: آف، مِهر، خور + تاب، فروغ، نور) نور شمس . خورشید. مقابل سایه <span class=\"hlight\">:</span> <br />شخصی نه چنان کریه منظر<br />کز زشتی او خبر توان داد<br />وآنگه بغلی نعوذباﷲ<br />مردار بر آفتاب مرداد.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِخ ) توسعاً، بزرگترین کوکب آسمان زمین که هر صبح طالع شود و روی زمین روشن کند و شبانگاه فروشود. مهر. خور. هور. آف . چشمه . لیو.شِر. اختران شاه . خورشید. شمس . بوح . یوح . شارق . (دستوراللغه ). شرق . ابوقابوس . بیضا. ذکاء. جاریه . غزاله .عجوز. مهات . بتیراء. اِلاهه . و شعرا از آن بصدها نام تعبیر کرده اند از قبیل شاه انجم، آبله ٔ روز، خسرو خاور، همسایه ٔ مسیح و امثال آن <span class=\"hlight\">:</span> <br />نبی آفتاب و صحابان چو ماه <br />بهم نسبتی یکدگر راست راه .<br /> <font color=\"Red\">فردوسی .</font><br />همی برشد آتش فرود آمد آب <br />همی گشت گردزمین آفتاب .<br /> <font color=\"Red\">فردوسی .</font><br />ز چارم همی بنگرد آفتاب <br />بجنگ بزرگانش آید شتاب .<br /> <font color=\"Red\">فردوسی .</font><br />چو آمد ببرج حمل آفتاب <br />جهان گشت با فر و آئین و آب .<br /> <font color=\"Red\">فردوسی .</font><br />برفت آفتاب از جهان ناپدید<br />چه داند کسی کآن شگفتی ندید؟<br /> <font color=\"Red\">فردوسی .</font><br />رخ رستم زال از آن گرد باز<br />همی تافت چون آفتاب از فراز.<br /> <font color=\"Red\">فردوسی .</font><br />چو از لشکر آگه شد افراسیاب <br />برو تیره شد تابش آفتاب .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت اولاد چون آفتاب <br />شود گرم دیو اندر آید بخواب .<br /> <font color=\"Red\">فردوسی .</font><br />وزآن زشت بدکامه ٔ شوم پی <br />که آمد ز درگاه خسرو <font color=\"DarkGreen\"><b>[ پرویز ]</font></b> بری <br />شد آن شهر آباد یکسر خراب <br />بسر بر همی تافتی آفتاب .<br /> <font color=\"Red\">فردوسی .</font><br />بدانگونه شادم که تشنه ز آب <br />وگر سبزه از تابش آفتاب .<br /> <font color=\"Red\">فردوسی .</font><br />چون کشتی پر آتش و گرد اندر آب نیل <br />بیرون زد آفتاب سر از گوشه ٔ جهن .<br /> <font color=\"Red\">عسجدی .</font><br />محمود و مسعود... دو آفتاب روشن بودند... اینک از این دو آفتاب چندین ستاره ٔ تابدار بیشمارحاصل گشته است . (تاریخ بیهقی ). بحمداﷲ تعالی معالی ایشان چون آفتاب روشن است . (تاریخ بیهقی ). پیش آفتاب ذرّه کجا در حساب آید؟ (تاریخ بیهقی ). گر بحجت پیشم آید آفتاب <br />بی گمان بینم کز او روشن ترم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نی مشتری نه زهره نه مریخ و نه زحل <br />نی آفتاب روشن و نه ماه انورند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />بس نمانده ست کآفتاب خدای <br />سر بمغرب برون کند ز حجاب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عدل است وارث همه آثار عقل پاک <br />عقل است آفتاب دل و عدل از او ضیاست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آفتاب پیش رُخَش سجده کردی . (کلیله و دمنه ). و چون آفتاب روشن است . (کلیله و دمنه ). و آفتاب ملت احمدی بر آن دیار از عکس ماه رایت محمودی بتافت .(کلیله و دمنه ).<br />هست حربا را ز نادانی خیال <br />کآفتاب از بهر او کرد انتقال .<br /> <font color=\"Red\">عطار.</font><br />گر بقدر خود نمودی آفتاب <br />کی شدی حربا ز عشق او خراب ؟<br /> <font color=\"Red\">عطار.</font><br />چنان نورانی از فرّ عبادت <br />که گوئی آفتابانند و ماهان .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> و خانه ٔ او اسد است . و شرف او <font color=\"DarkGreen\"><b>[ به نوزدهم درجه ]</font></b> در حمل است . (مفاتیح ) <span class=\"hlight\">:</span> <br />شرف همی بحمل یابد آفتاب ار چند<br />نیافته ست خطر جز که زآفتاب حمل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عمر برف است و آفتاب تموز<br />اندکی مانده خواجه غرّه هنوز.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ مرکب ) مجازاً، شراب <span class=\"hlight\">:</span> <br />در جشن آسمان وش تو ریخته نثار<br />ساقی ّ ماه روی تو در ساغر آفتاب .<br /> <font color=\"Red\">انوری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب به آفتاب </span> ؛ هر روز: آفتاب به آفتاب سه تومان کارگر است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب بر دیوار رفتن کسی را</span> ؛ عمر او نزدیک به آخر رسیدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب بزرد (بزردی ) رسیدن </span> ؛ عمراو بپایان نزدیک گردیدن <span class=\"hlight\">:</span> <br />زمانه مه روشنش تیره کرد<br />ز دوران رسید آفتابش بزرد.<br /> <font color=\"Red\">سلمان ساوجی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب بگل اندودن </span> ؛ حقیقتی را با مجازی، حسنی را با تقبیح پوشیدن خواستن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب دادن (آفتاب کردن ) جامه را</span> ؛ گستردن آن در آفتاب برای بشدن بوی یا تباه شدن پت (بید) آن . تشمیس .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب را بجائی بردن </span> ؛ پیش از غروب بدانجای رسیدن : آفتاب را به دِه بردیم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب را بسایه نگذاشتن </span> ؛ شتاب کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب سر دیوار</span> ؛ آفتاب لب بام . خورشید سر دیوار. کنایه از پیری نزدیک به مرگ <span class=\"hlight\">:</span> <br />هرکه را سایه ٔ عدل تو نباشد بر سر<br />آفتاب املش بر سر دیوار بود.<br /> <font color=\"Red\">معزی .</font><br />من کیستم ز هجر تو ازکاررفته ای <br />خورشید عمر بر سر دیوار رفته ای .<br /> <font color=\"Red\">امیرخسرو.</font><br />هرکه چون خورشید بر بامت دوید<br />آفتابش بر سر دیوار شد.<br /> <font color=\"Red\">امیرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب کسی بکوه فرورفتن (شدن )</span> ؛ عمر او نزدیک به پایان رسیدن <span class=\"hlight\">:</span> <br />یکی سلطنت ران صاحب شکوه <br />فروخواست رفت آفتابش بکوه .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب ِ کش </span> ؛ ماه مقنع. ماه سیام . ماه نخشب . ماه کش <span class=\"hlight\">:</span> <br />روی به نخشب نهاد خواهم زینسان <br />چهره بزردی چو آفتاب چَه ِ کش .<br /> <font color=\"Red\">سوزنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب لب بام </span> ؛ پیری نزدیک به مرگ . آفتاب سر دیوار.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب و ماه </span> ؛ نیّرین . قمران . شمسین . ازهران .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سر آفتاب </span> ؛ اوّل روز.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آفتاب </span> ؛ سخت جمیل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آفتاب در وسط نهار (در رابعه ٔ نهار)</span> ؛ سخت هویدا.قوی پیدا. نیک پدید و آشکار. عظیم روشن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آفتاب آمد دلیل آفتاب </span> <br />گر دلیلت باید از وی رخ متاب .<br /> <font color=\"Red\">مولوی .</font><br /> <span class=\"hlight\">آفتاب بزردی افتاد تنبل بجلدی </span> ؛ کاهل کار را بوقت انجام نکند و در تنگی از سرعت و شتاب ناگزیر گردد.<br /> <span class=\"hlight\">ز آفتاب نتیجه شگفت نیست ضیا</span> .<br /><span class=\"hlight\">نه آفتاب از این گرمتر می شود نه قنبر از این سیاه تر</span> ؛ زیان و ضرر که ممکن بود دست دهد دست داد، دیگر از دنبال کردن کار و بپایان رسانیدن آن هراسیدن جای ندارد.<br /></font></div>'),
(1811, 'آفتاب', '<span class=\"hlight\">آفتاب .</span> (اِخ ) تخلص شاه عالم ابوالمظفر مروج الدین، از فرمانروایان دهلی . او را به فارسی اشعاربسیار است و ازجمله منظومه ای به نام شهرآشوب در شرح فتنه ٔ غلام قادرخان . وفات او در <span class=\"hlight\" dir=\"rtl\">١٢٢١</span> هَ .ق . است .<br /></font></div>'),
(1812, 'آفتاب', '<span class=\"hlight\">آفتاب .</span> (اِخ ) نام رودی است که از انجیرکوه چشمه گیرد به پشت کوه، و آن رافده و آب راهه ٔ کشکانرود است .<br /></font></div>'),
(1813, 'آفتاب جبین', '<span class=\"hlight\">آفتاب جبین .</span> <font color=\"DarkGreen\"><b>[ ج َ ]</font></b> (ص مرکب ) صاحب جبین تابان .<br /></font></div>'),
(1814, 'آفتاب دزدک', '<span class=\"hlight\">آفتاب دزدک .</span> <font color=\"DarkGreen\"><b>[ دُ دَ ]</font></b> (اِ مرکب ) شبکه ای که طفلان از نی بوریا ساخته و در آفتاب گذارند.<br /></font></div>'),
(1815, 'آفتاب رو', '<span class=\"hlight\">آفتاب رو.</span> (اِ مرکب ) جائی که آفتاب بر آن تابد. بَرآفتاب . آفتاب گاه . مشراق .مشرقه . بتو. مقابل نَسا، نَسار، نَسَر <span class=\"hlight\">:</span> <br />در موسم زمستان سعدی دو چیز خواهد<br />با روی ْآفتابی در آفتاب روئی .<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> ((ص مرکب ) با روئی چون آفتاب . با صورتی سخت جمیل .<br /></font></div>'),
(1816, 'آفتاب روی', '<span class=\"hlight\">آفتاب روی .</span> (ص مرکب، اِ مرکب ) آفتاب رو.<br /></font></div>'),
(1817, 'آفتاب رویه', '<span class=\"hlight\">آفتاب رویه .</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (اِ مرکب ) مشراق . مشرقه . (صراح ). برآفتاب . آفتاب گاه .<br /></font></div>'),
(1818, 'آفتاب زده', '<span class=\"hlight\">آفتاب زده .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) متشمس .آنکه از بسیاری تافتن آفتاب بر او بیمار شده باشد.<br /></font></div>'),
(1819, 'آفتاب زدگی', '<span class=\"hlight\">آفتاب زدگی .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص مرکب ) تشمس، و آن بیماریی باشد که از بسیار ماندن در آفتاب زاید.<br /></font></div>'),
(1820, 'آفتاب زرد', '<span class=\"hlight\">آفتاب زرد.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِ مرکب، ق مرکب ) نزدیک غروب که رنگ آفتاب پریده نماید. اصیل . پس از نماز دیگر. پسین ِ دور.ایوار <span class=\"hlight\">:</span> و پیش سلطان شد، آفتاب زرد. (چهارمقاله ). جمله کارها فروگذاشت و فرخی را برنشاند و روی بامیر نهاد و آفتاب زرد پیش امیر آمد. (چهارمقاله ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب زرد نزدیک شدن کسی را</span> ؛ مرگ او نزدیک رسیدن <span class=\"hlight\">:</span> <br />دور از تو گذشت روز عمرم <br />نزدیک شد آفتاب زردش .<br /> <font color=\"Red\">خاقانی .</font><br />افتاد بر آفتاب گردم <br />نزدیک شد آفتاب زردم .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(1821, 'آفتاب زردی', '<span class=\"hlight\">آفتاب زردی .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِ مرکب، ق مرکب ) آفتاب زرد.<br /></font></div>'),
(1822, 'آفتاب طلعت', '<span class=\"hlight\">آفتاب طلعت .</span> <font color=\"DarkGreen\"><b>[طَ ع َ ]</font></b> (ص مرکب ) سخت جمیل . آفتاب روی . آفتاب عذار.<br /></font></div>'),
(1823, 'آفتاب عذار', '<span class=\"hlight\">آفتاب عذار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص مرکب ) آفتاب طلعت .<br /></font></div>'),
(1824, 'آفتاب لقا', '<span class=\"hlight\">آفتاب لقا.</span><font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ص مرکب ) آفتاب طلعت . آفتاب عذار. سخت جمیل .<br /></font></div>'),
(1825, 'آفتاب مهتاب', '<span class=\"hlight\">آفتاب مهتاب .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِ مرکب ) قسمی از آتش بازی که نور آن گاه سوختن بچند رنگ زند.<br /></font></div>'),
(1826, 'آفتاب ناک', '<span class=\"hlight\">آفتاب ناک .</span> (ص مرکب ) آفتاب گن . آفتاب گین . پرآفتاب . بسیارآفتاب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتاب ناک شدن روز</span> ؛ بی ابر شدن آن : شمس ؛ آفتاب ناک شدن روز. (صراح ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">روزی آفتاب ناک </span> ؛ بی ابر. صحو.<br /></font></div>'),
(1827, 'آفتاب ناکی', '<span class=\"hlight\">آفتاب ناکی .</span> (حامص مرکب ) حالت و چگونگی آفتاب ناک .<br /></font></div>'),
(1828, 'آفتاب نزده', '<span class=\"hlight\">آفتاب نزده .</span> <font color=\"DarkGreen\"><b>[ ن َ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ق مرکب ) پیش از طلوع آفتاب .<br /></font></div>'),
(1829, 'آفتاب پرست', '<span class=\"hlight\">آفتاب پرست .</span> <font color=\"DarkGreen\"><b>[ پ َ رَ ]</font></b> (نف مرکب ) آنکه آفتاب را چون خدائی یا قبله ای نیایش کند. مشمِّس . (السامی فی الاسامی ). عابدالشمس . پرستنده ٔ آفتاب . خورشیدپرست . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) حربا. بوقلمون . خامالاون . حجل . حربایه . آفتاب گردک . اسدالارض . روزگردک . پژمره . خور. انگلیون . مارپلاس . و آن جانوری است چون چلپاسه که هماره روی فرا آفتاب دارد <span class=\"hlight\">:</span> در آن حال آن جانور را که او را آفتاب پرست میگویند دیدم که در جمال آفتاب حیران و مستغرق شده است . (انیس الطالبین بخاری ). <BR><font color=\"Blue\">◄</font> گلی که آن را امروز آفتاب گردان گویند. آفتاب گردک . درختک دانا. وقواق . (برهان، ذیل درختک دانا). آذرگون . آذریون . و آن گلی است که ساق آن سبز است بستبری ِ ابهامی و گاهی ستبرتر، با برگهای پهن و گلی زرد و بزرگ و با تدویری تمام چون طبقی خرد. تنوم . دوارالشمس . <BR><font color=\"Blue\">◄</font> نیلوفر. گل کبود. گل ازرق . آبرود. آبو. عروس النیل . آبگون <span class=\"hlight\">:</span> <br />هر سوئی کآفتاب سر دارد<br />گل ازرق در او نظر دارد<br />لاجرم هر گلی که ازرق هست <br />خواندش هندو آفتاب پرست .<br /> <font color=\"Red\">نظامی .</font><br />و صاحب صراح، شکاعی را به آفتاب پرست ترجمه کرده که آن را چرخه و چرخله و خارمهک و کافیلو و شوکةالعربیه و ابرةالراهب نیز گویند. <BR><font color=\"Blue\">◄</font> ورتاج . پنیرک . خبازی . نانکلاغ . ملوخیا. خبزالغراب . ملوکیه . <BR><font color=\"Blue\">◄</font> اسفراج . مارچوبه . مارگیا. هلیون . یرامیع. <BR><font color=\"Blue\">◄</font> هلل .<br /></font></div>'),
(1830, 'آفتاب پرستک', '<span class=\"hlight\">آفتاب پرستک .</span> <font color=\"DarkGreen\"><b>[ پ َ رَ ت َ ]</font></b> (اِ مرکب ) مصغر آفتاب پرست . درختی خرد که برگهای آن جمله سوی آفتاب باشد، و در هند آن را هرهر گویند. <BR><font color=\"Blue\">◄</font> جامه ٔ بوقلمون که رنگ رنگ نماید. (مؤیدالفضلاء).<br /></font></div>'),
(1831, 'آفتاب پرستی', '<span class=\"hlight\">آفتاب پرستی .</span> <font color=\"DarkGreen\"><b>[ پ َ رَ ]</font></b> (حامص مرکب ) عبادت شمس . تشمیس .<br /></font></div>'),
(1832, 'آفتاب پرورد', '<span class=\"hlight\">آفتاب پرورد.</span> <font color=\"DarkGreen\"><b>[ پ َ وَ ]</font></b> (ن مف مرکب ) آفتاب پرورده . آنکه در آفتاب نهاده باشند تخمیر یا قوام آمدن را <span class=\"hlight\">:</span> شرابی که آفتاب پرورده باشد لطیف تر و زودگوارتر از همه ٔ شرابها بود. (نوروزنامه ).<br /></font></div>'),
(1833, 'آفتاب پهن', '<span class=\"hlight\">آفتاب پهن .</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (اِ مرکب ) در تداول خانگی، آنگاه از بامداد که قسمتی از سطح سرای را آفتاب گیرد.<br /></font></div>'),
(1834, 'آفتاب چشمه', '<span class=\"hlight\">آفتاب چشمه .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ م َ <span class=\"hlight\" dir=\"rtl\">/</span>م ِ ]</font></b> (اِ مرکب ) چشمه ٔ آفتاب . قرص آفتاب . (برهان ).<br /></font></div>'),
(1835, 'آفتاب گاه', '<span class=\"hlight\">آفتاب گاه .</span>(اِ مرکب ) برآفتاب . مشرقه . (زمخشری ). آفتاب رو. مشراق . بتو. آنجای خانه که بیشتر روز آفتاب بدان تابد.<br /></font></div>'),
(1836, 'آفتاب گردان', '<span class=\"hlight\">آفتاب گردان .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِ مرکب ) سایبان . چتر. <BR><font color=\"Blue\">◄</font> لبه ای جدا که بر مقدم کلاه پیوستندی در سفرها تا آفتاب بر روی کمتر تابد. <BR><font color=\"Blue\">◄</font> گلی که ساق آن بستبری ِ دو ابهام و درازای آن ببالای آدمی و بیشتر رسد با برگهای بزرگ و مزغّب و گلی زرد و پهن و بزرگ چون صحنی خرد، وتخم آن را چون تخمه هندوانه سمچکی در گیلان تفت داده و مغز آن را خورند. تنوم . دوارالشمس . <BR><font color=\"Blue\">◄</font> آفتاب پرست . حربا. روزگردک . (محمودبن عمر). بوقلمون .<br /></font></div>'),
(1837, 'آفتاب گردش', '<span class=\"hlight\">آفتاب گردش .</span> <font color=\"DarkGreen\"><b>[ گ َ دِ ]</font></b> (اِ مرکب ) حرباء.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1838, 'آفتاب گردک', '<span class=\"hlight\">آفتاب گردک .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ ]</font></b> (اِ مرکب ) حرباء. آفتاب پرست . بوقلمون . <BR><font color=\"Blue\">◄</font> گل آفتاب پرست . <BR><font color=\"Blue\">◄</font> خبازی . پنیرک .<br /></font></div>'),
(1839, 'آفتاب گرفتگی', '<span class=\"hlight\">آفتاب گرفتگی .</span> <font color=\"DarkGreen\"><b>[ گ ِ رِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) کسوف شمس . احتجاب شمس . پوشیدگی آفتاب .<br /></font></div>'),
(1840, 'آفتاب گن', '<span class=\"hlight\">آفتاب گن .</span> <font color=\"DarkGreen\"><b>[ گ ِ ]</font></b> (ص مرکب ) آفتاب گین .<br /></font></div>'),
(1841, 'آفتاب گنی', '<span class=\"hlight\">آفتاب گنی .</span> <font color=\"DarkGreen\"><b>[ گ ِ ]</font></b> (حامص مرکب ) آفتاب گینی .<br /></font></div>'),
(1842, 'آفتاب گیر', '<span class=\"hlight\">آفتاب گیر.</span> (نف مرکب ) آنجا که هر روز آفتاب در آن تابد. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) سایبان . چتر. سپر با دسته که بر سر پادشاهان چون سایبان داشتندی <span class=\"hlight\">:</span> <br />ز روی قدر جز آن آفتاب گیر که زد<br />تپانچه بر رخ خورشید ساعتی صد بار؟<br /><font color=\"Red\">بدیعی سمرقندی .</font><br /></font></div>'),
(1843, 'آفتاب گین', '<span class=\"hlight\">آفتاب گین .</span> (ص مرکب ) آفتاب گن . آفتاب ناک : شمس یومنا؛ آفتاب گین شد روز ما. (زمخشری ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">روزی آفتاب گین </span> ؛ بی ابر. صحو.<br /></font></div>'),
(1844, 'آفتاب گینی', '<span class=\"hlight\">آفتاب گینی .</span> (حامص مرکب ) آفتاب گنی . چگونگی و صفت آفتاب گین .<br /></font></div>'),
(1845, 'آفتابه', '<span class=\"hlight\">آفتابه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ مرکب ) آب تابه . ظرفی فلزین با لوله ای بلند که در آن آب گرم کنند. مِحَم ّ. <BR><font color=\"Blue\">◄</font> اِبریقی از فلز و بیشتر از مس که در طهارتخانه بکاربرند. قُمْقُمه . (مهذب الاسماء). قُمْقُم . کُمْکُم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتابه گرفتن، آفتابه برداشتن </span> ؛ بقضای حاجت شدن .<br /> <BR><font color=\"Blue\">◄</font> ظرفی فلزین که پیش و پس از طعام دست و دهان بدان شویند <span class=\"hlight\">:</span> <br />بدستش داد زرین آفتابه <br />کنیزی از پیَش زرکش عصابه <br />یکی طشتش بکف از نقره ٔ خام <br />بسان سایه او را گام بر گام .<br /><font color=\"Red\">جامی .</font><br /></font></div>'),
(1846, 'آفتابه خانه', '<span class=\"hlight\">آفتابه خانه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) بیت الخلا.<br /></font></div>'),
(1847, 'آفتابه دار', '<span class=\"hlight\">آفتابه دار.</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (نف مرکب ) آنکه در خانه ٔ پادشاهان و اعیان رجال شغلش آفتابه داشتن است .<br /></font></div>'),
(1848, 'آفتابه داری', '<span class=\"hlight\">آفتابه داری .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (حامص مرکب ) کار آفتابه دار. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) آنجای که آفتابه در آن دارند.<br /></font></div>'),
(1849, 'آفتابه دزد', '<span class=\"hlight\">آفتابه دزد.</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ دُ ]</font></b> (نف مرکب <span class=\"hlight\" dir=\"rtl\">/</span> ص مرکب ) دَله دُزد.<br /></font></div>'),
(1850, 'آفتابه لگن', '<span class=\"hlight\">آفتابه لگن .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ل َ گ َ ]</font></b> (اِ مرکب ) ابریق و لگنی فلزین برای شستن دست و دهان پیش و بعد از طعام .<br /></font></div>'),
(1851, 'آفتابه چی', '<span class=\"hlight\">آفتابه چی .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ص مرکب، اِ مرکب ) آفتابه دار.<br /></font></div>'),
(1852, 'آفتابه گلدان', '<span class=\"hlight\">آفتابه گلدان .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ گ ُ ]</font></b> (اِ مرکب ) آفتابه و لگنی کوچک که گاه خفتن دارند میختن شب را یا بیماران و پیران را.<br /></font></div>'),
(1853, 'آفتابی', '<span class=\"hlight\">آفتابی .</span> (ص نسبی، اِ) منسوب به آفتاب . شمسی . <BR><font color=\"Blue\">◄</font> در آفتاب پرورده . در آفتاب بقوام آمده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گل قند آفتابی </span> ؛ گلقند آفتاب پرورد. مجازاً، لب معشوق :<br />گلقند آفتابی تو درهمی بچند؟<br /> <BR><font color=\"Blue\">◄</font> به آفتاب خشک شده : کشمش آفتابی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتابی شدن </span> ؛ سخت آشکار و علنی شدن، و بیشتر کاری زشت .<BR>۩ از خانه بیرون آمدن منزوی و معتزل .<BR>۩ به آفتاب رو درآمدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتابی شدن قنات در جائی </span> ؛ بر سطح زمین، جاری شدن آن در آن جای <span class=\"hlight\">:</span> آب شاه در ارک آفتابی میشود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفتابی کردن </span> ؛ سخت علنی کردن چیزی نهفته و پنهان را.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">روزی آفتابی </span> ؛ روزی بی ابر. صحو. مصرح . بی میغ. باز.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یک روزآفتابی </span> ؛ یک روز.<br /> <BR><font color=\"Blue\">◄</font> سایبان . چتر. آفتاب گردان <span class=\"hlight\">:</span> <br />پیش روی تو آفتابی زلف <br />زیر زلف تو سایه پرور گل .<br /> <font color=\"Red\">وحشی .</font><br /><BR><font color=\"Blue\">◄</font> لنگ حمام خشک و بی نم . <BR><font color=\"Blue\">◄</font> رنگ بگشته و داغ زده از آفتاب، چون سیب و مانند آن . <BR><font color=\"Blue\">◄</font> بغایت سرخ . <BR><font color=\"Blue\">◄</font> ظرفی آهنین . <BR><font color=\"Blue\">◄</font> قسمی کشمش که در آفتاب خشک کنند. مقابل سایه خشک .<br /></font></div>'),
(1854, 'آفتابی', '<span class=\"hlight\">آفتابی .</span> (اِخ ) تخلص شاعری از مردم ساوه .<br /></font></div>'),
(1855, 'آفتاوه', '<span class=\"hlight\">آفتاوه .</span> <font color=\"DarkGreen\"><b>[ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (اِ مرکب ) آفتابه .<br /></font></div>'),
(1856, 'آفتی', '<span class=\"hlight\">آفتی .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (اِخ ) تخلص شاعری از مردم تون (فردوس ).<br /></font></div>'),
(1857, 'آفدم', '<span class=\"hlight\">آفدم .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِ) فرجام . انجام . عاقبت . <BR><font color=\"Blue\">◄</font> (ص ) اخیر. پسین . <BR><font color=\"Blue\">◄</font> (اِخ ) لقب اردوان، یکی از سلاطین اشکانی <span class=\"hlight\">:</span> اردوان کوچک، اَفدم ... آفدم یعنی آخر. (مجمل التواریخ ). اردوان بود بزرگتر پادشاهان ملوک طوائف آنکه آفدم خوانندش . (مجمل التواریخ ). <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به آفدم (بآفدم )</span> ؛ سرانجام . در آخر. بفرجام . بعاقبت <span class=\"hlight\">:</span> <br />همچنان سرمه که دخت خوبروی <br />هم بسان گرد بردارد ز روی <br />گرچه هر روز اندکی برداردش <br />بآفدم روزی بپایان آردش .<br /> <font color=\"Red\">رودکی (از کلیله و دمنه ).</font><br /> <br />مکن خویشتن از ره راست گم <br />که خود را به دوزخ بری بآفدم .<br /> <font color=\"Red\">رودکی .</font><br />بودنت در خاک باشد بآفدم <br />همچنان کز خاک بود انبودنت .<br /> <font color=\"Red\">رودکی .</font><br />چه بایدْت کردن کنون بآفدم <br />مگر خانه روبی چو روبه بدم .<br /> <font color=\"Red\">ابوشکور.</font><br />محکم کند سرهای خم تا ماه پنجم یا ششم <br />آنگه بیاید بآفدم وآنگه بیارد باطیه .<br /> <font color=\"Red\">منوچهری .</font><br />بر اسب گمان از ره راست گم <br />قرارت بدوزخ بود بآفدم .<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(1858, 'آفرازه', '<span class=\"hlight\">آفرازه .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ) شعله . زبانه . لهب <span class=\"hlight\">:</span> <br />کنم ز آتش طبع تو آفرازه بلند<br />ز آفرین تو گر باشد آفروزه ٔ من .<br /> <font color=\"Red\">سوزنی .</font><br />خلیل وار بتان بشکند که نندیشد<br />زآفرازه ٔ نمرود منجنیق انداز.<br /> <font color=\"Red\">سوزنی .</font><br />گشت ز انگشت آفرازه ٔ دوزخ <br />نیمه تن او کباب و نیمه مهرّا.<br /> <font color=\"Red\">سوزنی .</font><br />نرم گشته به لوس و لابه ٔ من <br />گرم گشته به آفرازه ٔ من .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(1859, 'آفران', '<span class=\"hlight\">آفران .</span> <font color=\"DarkGreen\"><b>[ ف ُ ]</font></b> (اِخ ) نام قریه ای بماوراءالنهر، و میانه ٔ آن با نسف دو فرسنگ و نیم باشد.<br /></font></div>'),
(1860, 'آفرنگ', '<span class=\"hlight\">آفرنگ .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) اورنگ . حشمت . زیبائی .<br /></font></div>'),
(1861, 'آفرنگان', '<span class=\"hlight\">آفرنگان .</span> <font color=\"DarkGreen\"><b>[ ف َ رِ ]</font></b> (اِ) نام نسکی از بیست ویک نسک کتاب زند. (برهان ) <span class=\"hlight\">:</span> <br />از اطاعت با پدر زردشت پیر<br />خود به نسک آفرنگان گفته است .<br /> <font color=\"Red\">لبیبی .</font><br />اصل این کلمه آفرینگان است .<br /></font></div>'),
(1862, 'آفره', '<span class=\"hlight\">آفره .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) اَفرا. اَفراغ . آچ .<br /></font></div>'),
(1863, 'آفروزه', '<span class=\"hlight\">آفروزه .</span> <font color=\"DarkGreen\"><b>[زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ) فروزینه . گیره . آتش زنه <span class=\"hlight\">:</span> <br />کنم ز آتش طبع تو آفرازه بلند<br />ز آفرین تو گر باشد آفروزه ٔ من .<br /> <font color=\"Red\">سوزنی .</font><br /><BR><font color=\"Blue\">◄</font> فتیله ٔ چراغ . پلیته . ذباله . زَم .<br /></font></div>'),
(1864, 'آفروشه', '<span class=\"hlight\">آفروشه .</span> <font color=\"DarkGreen\"><b>[ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِ) نام قسمی حلواست که از آرد و عسل و روغن یا از زرده ٔ تخم و شیره و شکر سازند، و آن را حلوای خانگی و حلوای سفید و اَفروشه نیز نامند و عرب آن را خبیص . (زمخشری ) (ربنجنی ). خبیصه . (ربنجنی ). و ابوطیب و ابوسهل و ابوصالح گویند <span class=\"hlight\">:</span> <br />رفیقا چند گوئی کو نشاطت <br />بنگریزد کس از گرم آفروشه <br />مرا امروز توبه سود دارد<br />چنان چون دردمندان را شنوشه .<br /> <font color=\"Red\">رودکی .</font><br />این آفروشه ای است که زاغ است خوالگرْش <br />هر دو قرین یکدگر و نیک درخورند.<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفروشه نان </span> ؛ کنایت از چیزی بی اصل و دروغ است <span class=\"hlight\">:</span> هرچند این همه حال نیرنگ است و بر آن داهیان و سوختگان بنشود و دانند که آفروشه نانست باز مجاملتی در میانه نماند. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">در آفروشه سیر دادن </span> ؛ در صورتی خوب و فریبا آزار و رنجی رسانیدن . نظیردر لوزینه سیر خورانیدن <span class=\"hlight\">:</span> <br />همه جهان شکر لطف تو گرفت و هنوز<br />در آفروشه درون میدهی عدو را سیر.<br /> <font color=\"Red\">رضی الدین نیشابوری .</font><br /><BR><font color=\"Blue\">◄</font> بلغور گندم . (برهان ).<br /></font></div>'),
(1865, 'آفرید', '<span class=\"hlight\">آفرید.</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (ن مف مرخم ) مخفف آفریده در اعلام و اسماء مرکبه، چون به آفرید و دادآفرید و گردآفرید و ماه آفرید <span class=\"hlight\">:</span> <br />یکی خوب چهره پرستنده دید<br />کجا نام او بود ماه آفرید.<br /> <font color=\"Red\">فردوسی .</font><br />چو هنگامه ٔ زادن آمد پدید<br />یکی دختر آمد ز ماه آفرید.<br /> <font color=\"Red\">فردوسی .</font><br />ابا خواهر خویش به آفرید<br />بخون مژه هر دو رخ ناپدید.<br /> <font color=\"Red\">فردوسی .</font><br />سرودی به آواز خوش برکشید<br />که اکنون تو خوانیش دادآفرید.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد به نزدیک گردآفرید<br />چو دخت کمندافکن او را بدید...<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1866, 'آفریدن', '<span class=\"hlight\">آفریدن .</span> <font color=\"DarkGreen\"><b>[ ف َ دَ ]</font></b> (مص ) (از پهلوی ِ آفریتن، خلق کردن . بار آوردن ) نیستی را هست کردن . خلق . ابداء. بدء. فطر. ذرء. ابداع . ایجاد. تکوین . خِلقت . برء. بُروء. انشاء. تنشئه . جَبْل .(دهار). احداث . ابتداء. ابتداع . صَوْغ <span class=\"hlight\">:</span> <br />یارب بیافریدی روئی بدین مثال <br />خود رحم کن بر امت و از راهشان مکیب .<br /> <font color=\"Red\">شهید.</font><br />آنکه نشک آفرید و سرو سهی <br />آنکه بید آفرید و نار و بهی .<br /> <font color=\"Red\">رودکی .</font><br />ای غافل از شمار چه پنداری <br />کِت آفرید خالق بیکاری <br />عمری که مر تراست سرِ مایه <br />وید است و کارهات بدین زاری .<br /> <font color=\"Red\">رودکی .</font><br />ترا پاک یزدان چنان آفرید<br />که مهر آورد بر تو هر کِت بدید.<br /> <font color=\"Red\">فردوسی .</font><br />مرا آفریننده از فرّ خویش <br />چنین آفرید ای نگارین ز پیش .<br /> <font color=\"Red\">فردوسی .</font><br />بر او آفرین، کو جهان آفرید<br />ابا آشکارا نهان آفرید.<br /> <font color=\"Red\">فردوسی .</font><br />زمانی بخفتند و برخاستند<br />یکی آفرین نو آراستند<br />بدان دادگر کو جهان آفرید<br />توانائی و ناتوان آفرید.<br /> <font color=\"Red\">فردوسی .</font><br />جهان آفرین تا جهان آفرید<br />چو رستم سرافراز نامد پدید.<br /> <font color=\"Red\">فردوسی .</font><br />مرا بازو ایزد قوی آفرید<br />بنیروی من دهر مردی ندید.<br /> <font color=\"Red\">فردوسی .</font><br />مرا ایزد از بهر جنگ آفرید<br />ترا از پی زین و تنگ آفرید.<br /> <font color=\"Red\">فردوسی .</font><br />بر آن آفرین کآفرین آفرید<br />مکان وزمان و زمین آفرید.<br /> <font color=\"Red\">فردوسی .</font><br />جهان آفرین تا جهان آفرید<br />چنو مرزبانی نیامد پدید.<br /> <font color=\"Red\">فردوسی .</font><br />نباید بدیشان بد ایمن بجان <br />چنین آفریده خدای جهان .<br /> <font color=\"Red\">فردوسی .</font><br />که یزدان ز ناچیز چیز آفرید<br />بدان تا توانائی آید پدید. <br /> <font color=\"Red\">فردوسی .</font><br />اگر آرزوی در دنیا نیافریدی کس سوی غذا... و سوی جفت ... ننگریستی . (تاریخ بیهقی ). اگر طاعنی گوید که اگر آرزو و خشم نبایستی خدای تعالی ... در تن مردم نیافریدی ... (تاریخ بیهقی ).تا ایزد تعالی ... آدم ... را بیافریده است تقدیر چنان کرده است که ملک را انتقال می افتد از این امت بدان امت . (تاریخ بیهقی ). ایزد تبارک و تعالی بکمال قدرت وحکمت عالم را بیافرید. (کلیله و دمنه ).<br />و مصدر دیگر آن آفرینش است . آفریدم . بیافرین .<br /></font></div>'),
(1867, 'آفریده', '<span class=\"hlight\">آفریده .</span> <font color=\"DarkGreen\"><b>[ ف َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف، اِ) خلق شده . خلقت شده . مخلوق . خلق . مقابل آفریننده، خالق <span class=\"hlight\">:</span> <br />میان او که خدا آفریده است از هیچ <br />دقیقه ای است که هیچ آفریده نگشاده ست .<br /> <font color=\"Red\">حافظ.</font><br />همه از آفرینش برگزیده <br />همه از نور یک ذات آفریده .<br /> <font color=\"Red\">طالب آملی .</font><br /> <BR><font color=\"Blue\">◄</font> بریه . (زمخشری ) (دهار). خلیقه . وری . انام . (زمخشری ). خلق .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفریده ای، هیچ آفریده </span> ؛ اَحدی . یک تن . دیّاری . کسی . هیچ کسی . یک کس . آفریدگاری <span class=\"hlight\">:</span> که هیچ آفریده را چندین حزم و خرد... نتواند بود. (کلیله و دمنه ). نذر کردم که بدین گناه هیچ آفریده ای را مکافات نکنم . (تاریخ طبرستان ). هیچ آفریده با اصفهبد نمانده بود جز تنی چند از... (تاریخ طبرستان ). آفریده ای در اینجا نیست ؛ دیّاری .<br /><BR><font color=\"Blue\">◄</font> بشر. (زمخشری ) <span class=\"hlight\">:</span> شهنشاه موبدان را گفت در رأی ما نبود که ما نام شاهی بر هیچ آفریده نهیم در ممالک پدران خویش . (تاریخ طبرستان ).<br /></font></div>'),
(1868, 'آفریدون', '<span class=\"hlight\">آفریدون .</span> (اِخ ) نام پادشاهی داستانی از ایران که ضحاک را دربند و مملکت ایران را تسخیر کرد و رسم و راه ظلم ضحاک برانداخت و جهان را بسه فرزند خویش سلم و تور و ایرج بخشید.و او را فَریدون و اَفریدون نیز گویند <span class=\"hlight\">:</span> <br />سپه را ز دریا بهامون کشید<br />ز چین دژ سوی آفریدون کشید.<br /> <font color=\"Red\">فردوسی .</font><br />تو ا ز آفریدون فزونتر نه ای <br />چو پرویز با تخت و افسر نه ای .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت من خویش گرسیوزم <br />بشاه آفریدون کشد پروزم .<br /> <font color=\"Red\">فردوسی .</font><br />زمینی کجا آفریدون گرد<br />بدانگه بتوج دلاور سپرد.<br /> <font color=\"Red\">فردوسی .</font><br />ز دهقان پرمایه کس را ندید<br />که شایسته ٔ آفریدون سزید.<br /> <font color=\"Red\">فردوسی .</font><br />و بعضی او را ذوالقرنین اکبر میدانند! (برهان ).<br /></font></div>'),
(1869, 'آفریدونی', '<span class=\"hlight\">آفریدونی .</span> (ص نسبی ) منسوب به آفریدون <span class=\"hlight\">:</span> <br />بگفتا که از مام خاتونیَم <br />بسوی پدر آفریدونیَم .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1870, 'آفریدگار', '<span class=\"hlight\">آفریدگار.</span> <font color=\"DarkGreen\"><b>[ ف َ دْ <span class=\"hlight\" dir=\"rtl\">/</span> دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِخ ) آفریده گار. نامی از نامهای خدای تعالی . خالق . (ربنجنی ) (دهار). باری . (مهذب الاسماء). فاطر. صانع. (ربنجنی ) (مهذب الاسماء). خلاق . (السامی فی الاسامی ). آفریننده . پدیدآرنده ٔ همه <span class=\"hlight\">:</span> آفریدگار... عالم اسرار است و کارهای نابوده را بداند. (تاریخ بیهقی ). بزرگتر گواهی بر این چه میگویم کلام آفریدگار است جل جلاله . (تاریخ بیهقی ). خردمندان اگر... استخراج کنند تا بر این دلیلی روشن یابند ایشان را مقررگردد که آفریدگار... عالم اسرار است . (تاریخ بیهقی ). تقدیر آفریدگار که در لوح محفوظ قلم چنان رانده است تغییر نیابد. (تاریخ بیهقی ). نگاه باید کرد... که ایشان برگزیدگان آفریدگار بوده اند. (تاریخ بیهقی ). و هر کس که آن را <font color=\"DarkGreen\"><b>[ قوت انبیا و پادشاهان را ]</font></b> از فلک و کواکب و بروج داند آفریدگار را از میانه بردارد. (تاریخ بیهقی ). آفریدگار را... در هرچه آفریده است مصلحتی است عام و ظاهر. (تاریخ بیهقی ). آخر بمرگ ناچیز شود و باز بقدرت آفریدگار جل جلاله ناچار از گور برخیزد. (تاریخ بیهقی ). او آفریدگار خویش را بدانست و مقرر است که آفریدگار چون آفریده نباشد... (تاریخ بیهقی ). و تناسخیان گویند که <font color=\"DarkGreen\"><b>[ جمال ]</font></b> خلعت آفریدگار است که بمکافات آن پاکی و پرهیزکاری که بنده کرده بود اندر پیش، آن بنور خویش او را کرامت کند. (نوروزنامه ).و بحقیقت باید شناخت که پادشاهان اسلام سایه ٔ آفریدگارند. (کلیله و دمنه ). در هیچ حال از رحمت آفریدگار و مساعدت روزگار نومید نشاید بود. (کلیله و دمنه ).<br />کای کاینات را بوجود تو افتخار<br />وی بیش از آفرینش و کم زآفریدگار.<br /> <font color=\"Red\">انوری .</font><br /><BR><font color=\"Blue\">◄</font> (اِ مرکب ) خلیقه . (دهار). انام . بریه : آفریدگاری درخانه نیست ؛ احدی، کسی، دیّاری، آفریده ای .<br /></font></div>'),
(1871, 'آفریدگان', '<span class=\"hlight\">آفریدگان .</span> <font color=\"DarkGreen\"><b>[ ف َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ) ج ِ آفریده . خلق . خلیقه . مخلوق . مخلوقات . وَری . بریه . (صراح ). انام . کائنات .<br /></font></div>'),
(1872, 'آفرین', '<span class=\"hlight\">آفرین .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (اِ) زه . فری .فریش . افرا. آباد. خَه . خهی . بَه . بَه بَه . پَه . پَه پَه . زهی . پَخ پَخ . آخ . (برهان ). اَخ . (برهان ). بخ . وَه . وَه وَه . شاباش . شادباش . شادزی . مریزاد. دستخوش . انوشه . انوشه بزی . چنانهن (؟). احسنت . مرحبا. بارک اﷲ. مرحباً بِک . طوبی لَک . بخ بخ . ماشأاﷲ <span class=\"hlight\">:</span> <br />یکی یادگاری شد اندر جهان <br />بر او آفرین از کهان و مهان .<br /> <font color=\"Red\">فردوسی .</font><br />چو هوم آن سر و تاج شاهان بدید<br />بر ایشان بداد آفرین گسترید<br />همان شهریاران بدو آفرین <br />همی خواندند از جهان آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />همه سرکشان آفرین خواندند<br />بر آن نامه بر گوهر افشاندند.<br /> <font color=\"Red\">فردوسی .</font><br />ز نیکو سخن بِه ْ چه اندر جهان <br />بر او آفرین از کهان و مهان .<br /> <font color=\"Red\">فردوسی .</font><br />ز ترکان همه بیشه ٔ نارون <br />برستند و بی رنج گشت انجمن <br />ز دشمن برَستندخلق جهان <br />بر او <font color=\"DarkGreen\"><b>[ برانوشیروان ]</font></b> آفرین از کهان و مهان .<br /> <font color=\"Red\">فردوسی .</font><br />بر او آفرین کرد مهتر بسی <br />که چون تو نیابیم مهمان کسی .<br /> <font color=\"Red\">فردوسی .</font><br />بر او آفرین کو کند آفرین <br />بر آن بخت بیدار و تاج و نگین .<br /> <font color=\"Red\">فردوسی .</font><br />خرامان برفت از بر تخت اوی <br />همی آفرین خواند بر بخت اوی .<br /><font color=\"Red\">فردوسی .</font><br />سر نامه کرد آفرین از نخست <br />بر آنکس که او دل ز کینه بشست .<br /> <font color=\"Red\">فردوسی .</font><br />هزار آفرین باد بر خوی تو<br />بر آن تیغ و دست جهانجوی تو.<br /> <font color=\"Red\">فردوسی .</font><br />همه خلعت شاه پیش آورید<br />براو آفرین کرد هر کش بدید.<br /> <font color=\"Red\">فردوسی .</font><br />گر به بیند چشم تو فرزند زهرا را بمصر<br />آفرین از جانْت بر فرزند و بر مادر کنی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از رهی و حجّت او خوان بر او<br />هر سحر ای باد هزار آفرین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />این زمستان بهار دولت اوست <br />آفرین بر چنین زمستان باد.<br /> <font color=\"Red\">مسعودسعد.</font><br />آفرین باد بر این خواجه ٔ مخدوم پرست <br />که ز سعیش خرد انگشت بدندان آرد.<br /> <font color=\"Red\">سلمان ساوجی .</font><br /> <BR><font color=\"Blue\">◄</font> و بطنز، بجای اَه واَخ و تعساً لک، و لامرحباً بک <span class=\"hlight\">:</span> <br />ترا زندان جهان است و تنت بند<br />بر این زندان و این بند آفرین باد!<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> دعای نیک . خواهش خیر و سعادت برای کسی . مقابل نفرین <span class=\"hlight\">:</span> <br />نفرین کند بمن بر، دارم به آفرین <br />مروا کنم بدو بر، دارد به مرغوا.<br /> <font color=\"Red\">ابوطاهر خسروانی .</font><br />اکنون که ترا تکلفی گویم <br />پیداست بر آفرینم ار نفرین .<br /> <font color=\"Red\">دقیقی .</font><br />بی آزاری و خامشی برگزین <br />که گوید که نفرین به از آفرین ؟<br /> <font color=\"Red\">فردوسی .</font><br />که من آفرینها کنم بیشمار<br />بخواهم ز دادار پروردگار<br />که دارد چو شاهان ترا شادکام <br />بزور و دل و زَهره گسترده نام <br />مرا آفرین بر تونفرین بود<br />همان نام تو شاه بیدین بود.<br /> <font color=\"Red\">فردوسی .</font><br />سپه خواند یکسر بر او آفرین <font color=\"DarkGreen\"><b>[ بفرخ زاد ]</font></b><br />که بی تو مبادا زمان و زمین .<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ ستاره شمر<br />که بر چرخ گردون نیابی گذر<br />از این کودک <font color=\"DarkGreen\"><b>[ شیرویه ]</font></b> آشوب گیرد زمین <br />نخواند سپاهش براو آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />بر او آفرین کرد <font color=\"DarkGreen\"><b>[ بر کیخسرو ]</font></b> بسیار زال <br />که شادان بزی تا بود ماه و سال .<br /> <font color=\"Red\">فردوسی .</font><br />برون کن ز دل درد و آزار و کین <br />پس آنگه دعا گستر و آفرین <br />بر اندیشه ٔ شهریار زمین <br />بخفتم شبی لب پر از آفرین .<br /><font color=\"Red\">فردوسی .</font><br />بهر کشوری داد کردی چنین <br />زدهقان همی یافتی آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />همه مهتران خواندند آفرین <br />که بی تاج و تختت مبادا زمین .<br /> <font color=\"Red\">فردوسی .</font><br />به آفرین و دعای نکو بسنده کنم <br />بدست بنده چه باشد جز آفرین و دعا؟<br /> <font color=\"Red\">عنصری .</font><br />بشدزود اسحاق و کرد آفرین <br />چنان خواستش زآفرین آفرین .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بکرد آفرین هم بدانسان که گفت <br />شد آن مرد با زور و فرهنگ جفت .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />که مان زین بلاها رهاند خدای <br />بماننداین بی گناهان بجای .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />چو فارغ شد از آفرین و دعا<br />عرابی بشد خرّم و بارضا.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />دعا کرد بسیار و کرد آفرین <br />فراوان بمالید رخ بر زمین <br />زدادار فرزند آن مرد خواست <br />همان کار وی نغز و درخورد خواست .<br /> <font color=\"Red\">شمسی (یوسف وزلیخا).</font><br />رو زبان از هر دوان کوتاه کن <br />چون همی نفرین ندانی زآفرین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تا کس از آفرین سخن گوید<br />سخن خلق آفرین تو باد.<br /> <font color=\"Red\">انوری .</font><br /> <BR><font color=\"Blue\">◄</font> دعا. ذکر. ورد. صلوة. نماز <span class=\"hlight\">:</span> <br />بدین پنج هفته که من روز و شب <br />همی به آفرین برگشادم دو لب <br />بدان تا جهاندار یزدان پاک <br />رهاند روانم از این تیره خاک .<br /> <font color=\"Red\">فردوسی .</font><br />دو بهره ز شب شاه فرخنده دین <font color=\"DarkGreen\"><b>[ کیخسرو ]</font></b><br />زبان را نپرداختی زآفرین .<br /> <font color=\"Red\">فردوسی .</font><br />دگر هرچه گفتی ز پاکیزه دین <br />ز یکشنبدی روزه و آفرین <br />همه خواند بر ما یکایک دبیر<br />سخنهای شایسته ٔ دلپذیر<br />بما بر ز دین کهن ننگ نیست <br />بگیتی به از دین هوشنگ نیست .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> ستایش . مدح . تحسین <span class=\"hlight\">:</span> <br />توانگر برد آفرین سال و ماه <br />و درویش نفرین برد بیگناه .<br /> <font color=\"Red\">ابوشکور.</font><br />ز بُست و ز کشمیر تا مرزچین <br />بر او بود از مهتران آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت پس شاه را خانگی <br />که چون تو که باشد بفرزانگی ...<br />ز قیصر درود و ز ما آفرین <br />بر این نامور شهریار زمین .<br /> <font color=\"Red\">فردوسی .</font><br />پرستنده ٔ آز و جویای کین <br />بگیتی ز کس نشنود آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />ستودش فراوان و کرد آفرین <br />بر آن پرهنر پهلَوِ پاکدین .<br /> <font color=\"Red\">فردوسی .</font><br />بزرگان و شیران ایران زمین <br />همه شاه را خواندند آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />دلی بخش از ثنای خویش معمور<br />زبانی زآفرین دیگران دور.<br /> <font color=\"Red\">امیرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> دعای آفرینگان <span class=\"hlight\">:</span> <br />ز یزدان چو شاه آرزوها بیافت <br />ز دریا سوی خان آذر شتافت <br />بسی زر بر آتش برافشاندند<br />بزمزم همی آفرین خواندند.<br /> <font color=\"Red\">فردوسی .</font><br />بزاری ابا کردگار جهان <br />بزمزم کنیم آفرین نهان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> شکر. سپاس <span class=\"hlight\">:</span> <br />جهاندار <font color=\"DarkGreen\"><b>[ هوشنگ ]</font></b> پیش جهان آفرین <br />نیایش همی کرد و خواند آفرین <br />که او را فروغی چنین هدیه داد<br />همین آتش آنگاه قبله نهاد.<br /> <font color=\"Red\">فردوسی .</font><br />به شکر و تحیت زبان برگشاد<br />هزاران هزار آفرین کرد یاد<br />بچین نیز مهمان رستم بماند <font color=\"DarkGreen\"><b>[ کیخسرو ]</font></b><br />بیک هفته از چین و ماچین براند<br />بفغفور و خاقان سپرد آن زمین <br />بسی شاه راخواندند آفرین <br />بسی خلعت و پندها دادشان <br />ز غم کرد یکسر دل آزادشان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> حمد. ثنا <span class=\"hlight\">:</span> <br />سوی آسمان کردش آن مرد روی <br />بگفت ای خدا این تن من بشوی <br />از این اَزْغها پاک کن مر مرا<br />همه آفرین زآفرینش ترا.<br /> <font color=\"Red\">ابوشکور.</font><br />سر نامه کرد آفرین خدای <br />ستایش هم او را هم او رهنمای .<br /> <font color=\"Red\">فردوسی .</font><br />اَبَر خاک چون مار پیچان ز کین <br />همی خواند بر کردگار آفرین <br />که همواره پست و بلندی ز تست <br />بهر سختیی یارمندی ز تست .<br /> <font color=\"Red\">فردوسی .</font><br />کند آفرین بر خداوند مهر<br />کزین گونه بر پای دارد سپهر.<br /> <font color=\"Red\">فردوسی .</font><br />به پیش خداوند گردان سپهر<br />برفت <font color=\"DarkGreen\"><b>[ کیخسرو ]</font></b> آفرین را بگستردمهر.<br /> <font color=\"Red\">فردوسی .</font><br />بر آن آفرین کآفرین آفرید<br />مکان و زمان و زمین آفرید.<br /> <font color=\"Red\">فردوسی .</font><br />سپهبد بیامد برِ شهریار<br />بسی آفرین کرد بر کردگار.<br /> <font color=\"Red\">فردوسی .</font><br />جهان دار پیش جهان آفرین <br />نیایش همی کرد و خواند آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />نخست آفرین کرد بر کردگار<br />جهاندار و پیروز پروردگار.<br /> <font color=\"Red\">فردوسی .</font><br />ز جان، آفرین خداوند کرد<br />که آغاز و انجام اویست فرد.<br /> <font color=\"Red\">فردوسی .</font><br />بپاسخ نوشت آفرین مهان <br />زمن بنده بر کردگار جهان .<br /> <font color=\"Red\">فردوسی .</font><br />سر نامه گفت آفرین مهان <br />ز ما باد بر کردگار جهان .<br /> <font color=\"Red\">فردوسی .</font><br />بِاِستادی و برگرفتی دعا<br />ز هر گونه ای آفرین و ثنا<br />چو دیدند پیران رخ دخت شاه ...<br />خردمند ده پیر مانده بجای <br />زبانها پر از آفرین خدای .<br /> <font color=\"Red\">فردوسی .</font><br />مر او را سزد سجده و آفرین <br />که او آفرید آسمان و زمین .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />ابر پاک یزدان پیروزگر<br />که در تن روان آفرید و گهر.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بر او <font color=\"DarkGreen\"><b>[ بر خدا ]</font></b> آفرین باد زو آفرین <br />بر آن شخص محمود پاکیزه دین .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> درود. سلام . تحیت <span class=\"hlight\">:</span> <br />ز سام نریمان بشاه جهان <br />هزار آفرین باد و هم بر مهان .<br /> <font color=\"Red\">فردوسی .</font><br />فرستادگان خواندند آفرین <br />که از شاه شاد است خاقان چین .<br /> <font color=\"Red\">فردوسی .</font><br />همی تاخت <font color=\"DarkGreen\"><b>[ چوبینه ]</font></b> پوزش کنان پیش اوی <br />پر از شرم جان بداندیش اوی <br />چو پرموده را دید کرد آفرین <br />از او سر بپیچید خاقان چین <font color=\"DarkGreen\"><b>[ یعنی پرموده ]</font></b> .<br /> <font color=\"Red\">فردوسی .</font><br />چو کاوس را دید <font color=\"DarkGreen\"><b>[ سیاوش ]</font></b> بر تخت عاج <br />ز یاقوت رخشنده بر سَرْش تاج <br />نخست آفرین کرد و بردش نماز<br />زمانی همی گفت با خاک راز.<br /> <font color=\"Red\">فردوسی .</font><br />فرسته چواز پیش ایوان رسید<br />زمین بوسه داد آفرین گسترید.<br /> <font color=\"Red\">فردوسی .</font><br />چو دیدند <font color=\"DarkGreen\"><b>[ فرستادگان قیصر ]</font></b> زیبا رخ شاه را<br />بدانگونه آراسته گاه را<br />نهادند همواره سر بر زمین <br />بر او بر همی خواندند آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />بدو آفرین کرد و نامه بداد<br />پیام نیا پیش او کرد یاد.<br /> <font color=\"Red\">فردوسی .</font><br />ابا هدیه و باژ روم آمدیم <br />بدین نامبردار بوم آمدیم <br />برفتیم با فیلسوفان بهم <br />بدان تا نباشد کس از ما دژم <br />ز قیصر پذیرد مگر باژ و چیز<br />که با باژ و چیز آفرین است نیز.<br /> <font color=\"Red\">فردوسی .</font><br />التحیات می خواندم یعنی که آفرینها مر اﷲ را گفتم . (کتاب المعارف ).<br /><BR><font color=\"Blue\">◄</font> تهنیت . تبریک <span class=\"hlight\">:</span> <br />بر اورنگ زرّینْش بنشاندند<br />بشاهی بر او آفرین خواندند.<br /> <font color=\"Red\">فردوسی .</font><br />برفتیم نزدیک خاقان چین <br />بشاهی بر او خواندیم آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />بزرگانْش گوهر برافشاندند<br />بشاهی بر او آفرین خواندند.<br /> <font color=\"Red\">فردوسی .</font><br />بسی زرّ و گوهر برافشاندند<br />سراسر بر او آفرین خواندند.<br /> <font color=\"Red\">فردوسی .</font><br />بشادی بر او آفرین خواندند<br />بر آن تاج بر، گوهر افشاندند.<br /> <font color=\"Red\">فردوسی .</font><br />موبد موبدان پیش ملک آمدی <font color=\"DarkGreen\"><b>[ بنوروز ]</font></b> با جام زرین پر می ... و ستایش نمودی و نیایش کردی او را بزبان پارسی . چون موبد موبدان از آفرین بپرداختی پس بزرگان دولت درآمدندی ... (نوروزنامه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفرین آفرین </span> ؛ فاعل خیر. معطی الخیر <span class=\"hlight\">:</span> <br />بشد زود اسحاق و کرد آفرین <br />چنان خواستش زآفرین آفرین .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> مدحت . مدیح . مدیحه ٔ شاعران و جز آنان <span class=\"hlight\">:</span> <br />آفرین و مدح سود آید همی <br />گر بگنج اندر زیان آید همی .<br /> <font color=\"Red\">رودکی .</font><br />زلف او حاجب لب است و لبش <br />نپسندد بهیچکس بیداد<br />خاصه بر تو که تو فزون ز عدد<br />آفرینهای خواجه داری یاد.<br /> <font color=\"Red\">فرخی .</font><br />آفرین خدای باد بر او<br />کآفرین را بلند کرد بها.<br /> <font color=\"Red\">فرخی .</font><br />تو آفرین خسرو گوئی دروغ باشد<br />ویحک دلیر ردّی کاین لفظ گفت یاری .<br /> <font color=\"Red\">منوچهری .</font><br />گر مدیح و آفرین شاعران بودی دروغ <br />شعر حسان بن ثابت کی شنیدی مصطفی ؟<br /> <font color=\"Red\">منوچهری .</font><br />من تا در این دیارم مدح کسی نکردم <br />جز آفرین و مدحت زآن شاه کامکاری .<br /><font color=\"Red\">منوچهری .</font><br />بی آفرین سرائی بلبل بهار و باغ <br />پدرام نیست گرچه چمن شد بهار چین .<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> تحسین .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفرین کردن </span> ؛ تحسین کردن <span class=\"hlight\">:</span> <br />بتا روزگاری برآید بر این <br />کنم پیش هر کس ترا آفرین .<br /> <font color=\"Red\">ابوشکور.</font><br />مر او را بسی داد آب و زمین <br />درم داد و دینار و کرد آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />چو آن نامه ٔ قیصر آمد به بن <br />جهاندار <font color=\"DarkGreen\"><b>[ خسروپرویز ]</font></b> بشنید چندان سخن <br />بسی آفرین کرد بر خانگی <font color=\"DarkGreen\"><b>[ فرستاده ٔ قیصر ]</font></b><br />بدو گفت بس کن ز بیگانگی .<br /><font color=\"Red\">فردوسی .</font><br />دل خویش گر دور داری ز کین <br />مهان و کهانت کنند آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />چو دستان چنین دید شادی نمود<br />برستم بسی آفرین برفزود.<br /> <font color=\"Red\">فردوسی .</font><br />پس از آنکه حصار ستده آمد لشکر دیگر دررسید و همگان آفرین کردند. (تاریخ بیهقی ).<br /> <BR><font color=\"Blue\">◄</font> بَرَکَت . بَرَکه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفرین کردن </span> ؛ برکت دادن، چنانکه در مذهب یهود و ترسایان <span class=\"hlight\">:</span> <br />نشان پذیرفتنش <font color=\"DarkGreen\"><b>[ قربان ]</font></b> آن بدی <br />که از آسمان آتشی آمدی <br />خداوند خوان سخت خرم شدی <br />اساس طربهاش محکم شدی <br />که پذرفته بودی جهان آفرین <br />هم از بهر قربان هم از آفرین .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بعصیا چنین گفت اسحاق نیز<br />که رو دعوتی ساز بس با تمیز<br />بگو تا بیایم کنم آفرین <br />هم از خوان قربان هم از آفرین .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بگفتش برو خوان قربان بساز<br />بدان تا کنم آفرین ِ دراز.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بیا ای پیمبر بکن آفرین <br />مرا نیکخواه از جهان آفرین ...<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />ز عصیات نشناسد ای نیکرای <br />بیاید کند آفرین ِ خدای .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />چو آن آفرین و دعا گفته شد<br />ز یعقوب قربان پذیرفته شد.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> تعظیم . تجلیل . احترام . حرمت داشتن <span class=\"hlight\">:</span> <br />چو بر دین کند شهریار آفرین <br />برآرد ورا پادشاهی ّ و دین .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> خوشی . خیر. برکت .آبادی . سعادت <span class=\"hlight\">:</span> <br />جهان شدز دادش پر از آفرین <br />بفرمان دادار دادآفرین .<br /> <font color=\"Red\">فردوسی .</font><br />درود جهان آفرین بر تو باد<br />همان آفرین زمین بر تو باد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> آمرزش خواهی درگذشته ای را. طلب مغفرت و رحمت فرستادن مرده ای را <span class=\"hlight\">:</span> <br />بسی آفرین بر سیاوش بخواند <font color=\"DarkGreen\"><b>[ کاوس ]</font></b><br />که خسرو بچهره جز او را نماند.<br /> <font color=\"Red\">فردوسی .</font><br />هر آنکس که دارد هش و رای و دین <br />پس از مرگ بر من کند آفرین .<br /> <font color=\"Red\">فردوسی .</font><br />همه زیردستانْش پیچان شدند<br />فراوان ز تندیش بیجان شدند<br />کنون رفت و زو نام بد ماند و بس <br />همی آفرینی نیابد ز کس .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نظر سَعد <span class=\"hlight\">:</span> <br />همه جنگ بر دشت خوارزم بود<br />ز چرخ آفرین بر چنان رزم بود.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> یُمن . سعادت <span class=\"hlight\">:</span> <br />شدم تا به نزدیک آن شهرتنگ <br />که ناگه برآمد یکی بوی و رنگ <br />دل افروز بد یوسف پاکدین <br />درآمد بپیروزی و آفرین <br />چو شاهان یکی مرکبش ساخته ...<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />یلان سینه گفت ای سپهدار گرد<br />هر آنکس که او راه یزدان سپرد<br />خردمند و نامی ّ و دانا بود<br />بهر آرزو بر توانا بود<br />چو فیروزی و فرهی یابد اوی <br />بسوی بدی هیچ نشتابد اوی <br />که آن آفرین باز نفرین شود<br />وز او چرخ گردنده پرکین شود.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> خوبی . نیکی . خیر. صلاح . عمل خیر <span class=\"hlight\">:</span> <br />بنام خداوند خورشید و ماه <br />که او داد بر آفرین دستگاه .<br /> <font color=\"Red\">فردوسی .</font><br />شبانی همی کرد روزان شبان <br />خوشا آن گَله کش چو او بُد شبان <br />همی داشت روز و شب آن را نگاه <br />همی بود ایزد مر او را پناه <br />نیامد ز یعقوب جز آفرین <br />جز ایزدپرستی ّ و جز راه دین .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />پرستش همی کردمش این زمان <br />بسا شکر کردم ورا بیکران <br />که درج من از گوهر انباشته است <br />بچون تو کس ارزانیم داشته است <br />که چندان هنرو آفرین از تو است <br />درستی ّ و عقل متین از تو است .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> هورّا. هَرّا <span class=\"hlight\">:</span> <br />یکی آفرین خاست از بزمگاه <br />که پیروز باد این جهاندار شاه .<br /> <font color=\"Red\">فردوسی .</font><br />همه خلعت شاه پیش آورید<br />بر او آفرین کرد هر کس که دید<br />سخنهای ایرانیان هر چه بود<br />بدان نامه اندر بدیشان نمود<br />ز گردان برآمد یکی آفرین <br />که گفتی بجنبید روی زمین .<br /> <font color=\"Red\">فردوسی .</font><br />چو از دور دید آن سر و تاج شاه <br />پیاده فراوان به پیموده راه <br />همی کرد یکسر سپاه آفرین <br />برآن دادگر شاه ایران زمین .<br /> <font color=\"Red\">فردوسی .</font><br />چو بر تخت بنشست فرخنده رو<br />ز گیتی یکی آفرین خاست نو.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نام روز نخست از پنجه ٔ دزدیده بسالهای ملکی . <BR><font color=\"Blue\">◄</font> آفرین، گاهی عبارات معلوم و معینی و شاید با وزن و سجع بوده است که در اعیاد و نظایر آن بپادشاهان و سران دیگر می خوانده اند و ازجمله آفرین موبد موبدان بوده که بنوروز، شاه را می ستوده است و آن را صاحب نوروزنامه بدین گونه نقل کرده است <span class=\"hlight\">:</span> شها بجشن فروردین، بماه فروردین . آزادی گزین ردان <font color=\"DarkGreen\"><b>[ کذا ]</font></b>، و دین کیان، سروش آورد ترا دانائی، و بینائی بکاردانی، و دیر زی با خوی هژیر و شاد باش بر تخت زرین، و انوشه خور بجام جمشید، و برسم نیاکان از هوم بلند <font color=\"DarkGreen\"><b>[ اصل نسخه : و رسم نیاکان در همت بلند. و تصحیح قیاسی است ]</font></b> و نیکوکاری وورزش داد و راستی نگاه دار، سرت سبز باد و جوانی چوخوید، اسپت کامکار و فیروز، و تیغت روشن و کاری بدشمن و بازت گیرا <font color=\"DarkGreen\"><b>[ و ]</font></b> خجسته بشکار، و کارت راست چون تیر، و هم کشوری بگیر نو، بر تخت با درم و دینار، پیشت هنری و دانا گرامی، و درم خوار، و سرایت آباد و زندگی بسیار . صورتی دیگر از آفرین در فردوسی دیده می شود از زبان رستم به کیخسرو، آنگاه که رستم برای خلاص دادن بیژن از چاه افراسیاب از زابل بایران آمده است <span class=\"hlight\">:</span> <br />برآوردسر آفرین کرد و گفت <br />که بادی همه ساله با تخت جفت <br />که هرمزد بادت بدین پایگاه <br />چو بهمن نگهدار تخت و کلاه <br />همه ساله اردیبهشت هژیر<br />نگهبان تو باد و بهرام و تیر<br />ز شهریر بادی تو پیروزگر<br />بنام بزرگی ّ و فرّ و هنر<br />سپندارمذ پاسبان تو باد<br />خرد جان روشن روان تو باد<br />دی و فرودینت خجسته بواد<br />در هر بدی بر تو بسته بواد<br />از آذرْت رخشنده تر شب و روز<br />تو شادان و تاج تو گیتی فروز<br />وز آبانْت هر کار فرخنده باد<br />سپهر روان پیش تو بنده باد<br />تن چارپایانْت امرداد باد<br />همیشه تن و تخم تو شاد باد<br />ترا باد فرخ نیا و نژاد<br />ز خردادبادا بر و بوم شاد<br />چو این آفرین کرد رستم بپای <br />شهنشه بدادش بر خویش جای .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به آفرین (بآفرین )، باآفرین </span> ؛ ستوده . ممدوح . ممدوحه <span class=\"hlight\">:</span> <br />تو تا زادی از مادر بآفرین <br />پر از آفرین شد سراسر زمین .<br /> <font color=\"Red\">فردوسی .</font><br />مر او را بود هفت کشور زمین <br />گرانمایه شاهی بود بآفرین .<br /> <font color=\"Red\">فردوسی .</font><br />من او را گزین کردم از دختران <br />نگه داشتم چشم از دیگران <br />مرا گفت خاقان که دیگر گزین <br />که هر پنج خوبند و بآفرین .<br /> <font color=\"Red\">فردوسی .</font><BR>۩ سعید. مسعود <span class=\"hlight\">:</span> <br />چنین باد و هرگز مبادا جز این <br />که او شهریاری شود بآفرین .<br /> <font color=\"Red\">فردوسی .</font><BR>۩ خوش <span class=\"hlight\">:</span> <br />برآمد یکی باد بآفرین <br />هوا گشت خندان و روی زمین <br />جهان شد بکردار تابنده ماه <br />به نام جهاندار و از فرّ شاه .<br /> <font color=\"Red\">فردوسی .</font><BR>۩ نجیب . اصیل <span class=\"hlight\">:</span> <br />چو این کرده شد برنهادند زین <br />بر آن بادپایان باآفرین .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفرین کردن </span> ؛ بدرود کردن <span class=\"hlight\">:</span> گودرز زمین بوسه داد بر وی <font color=\"DarkGreen\"><b>[ بر کیخسرو ]</font></b> آفرین کرد و بیرون آمد شادمان . (ترجمه ٔ تاریخ طبری ).<br /> <BR><font color=\"Blue\">◄</font> رحمت . تأیید. توفیق <span class=\"hlight\">:</span> <br />ز یزدان بر آن شاه باد آفرین <br />که نازد بدو تخت و تاج و نگین .<br /> <font color=\"Red\">فردوسی .</font><br />بمالید پس خانگی رخ بخاک <br />همی گفت کای مهترداد و پاک <br />ز پیروزگر آفرین بر تو باد<br />مبادی همیشه مگر شاه وشاد.<br /> <font color=\"Red\">فردوسی .</font><br />زمین مرو پنداری بهشت است <br />خدایش زآفرین خود سرشته ست .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بنام خداوند هر دو سرای <br />که جاوید ماند همیشه بجای ...<br />بر او آفرین باد و زو آفرین <br />بر آن شخص محمود پاکیزه دین .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />کنون بآفرین جهان آفرینم <br />من اندر حصار حصین محمد.<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> رحمت فرستادن، مقابل لعن کردن <span class=\"hlight\">:</span> <br />گر اهل آفرین نیَمی هرگز<br />جهال چون کنندی نفرینم ؟<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">عطای بزرگان ایران زمین </span> <br />دو ره بارک اﷲست یک آفرین .<br /><font color=\"Red\">؟</font><br /></font></div>'),
(1873, 'آفرین', '<span class=\"hlight\">آفرین .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (اِخ ) تخلص شیخ قلندربخش هندوستانی که به فارسی شعر می سروده و منظومه ٔ تحفةالصنایع از اوست . <BR><font color=\"Blue\">◄</font> تخلص شاعری فارسی گوی از رؤسای قوم کاینهه ساکن اﷲآباد. <BR><font color=\"Blue\">◄</font> تخلص شاه فقیراﷲ لاهوری، که در بادی عمر زردشتی بوده و سپس بدین اسلام درآمده و به فارسی شعر بسیار گفته است . وفات او در <span class=\"hlight\" dir=\"rtl\">١١٤٣</span> یا <span class=\"hlight\" dir=\"rtl\">١١٥٤</span> هَ .ق . است . <BR><font color=\"Blue\">◄</font> تخلص زین العابدین نام، از شعرای اصفهان، شعرش نیکو و بسیار بوده و دیوان او در فتنه ٔ افغان از میان رفته و اشعار کمی از او متفرق مانده است . وفات <span class=\"hlight\" dir=\"rtl\">١١٢٥</span> هَ .ق .<br /></font></div>'),
(1874, 'آفرین', '<span class=\"hlight\">آفرین .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (نف مرخم ) مخفف آفریننده در کلمات مرکبه، چون آفرین آفرین، بکرآفرین، جان آفرین، جهان آفرین، دادآفرین، زبان آفرین، سحرآفرین، سحرحلال آفرین، سخن آفرین، صورت آفرین، گیتی آفرین <span class=\"hlight\">:</span> <br />جهان شد ز دادش پر از آفرین <br />بفرمان دادار دادآفرین .<br /> <font color=\"Red\">فردوسی .</font><br />بشد زود اسحاق و کرد آفرین <br />چنان خواستش زآفرین آفرین .<br /><font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />همی ریخت از دیدگان آب زرد<br />همی از جهان آفرین یاد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />که پیش تو آمد بدین هفت خوان <br />بر این بر، جهان آفرین را بخوان .<br /> <font color=\"Red\">فردوسی .</font><br />جهان آفرین تا جهان آفرید<br />چو رستم سرافراز نامد پدید.<br /> <font color=\"Red\">فردوسی .</font><br />از سین سحر نکته ٔ بکرآفرین منم <br />چون حق تعالی از ری بِر رحمت آفرین .<br /> <font color=\"Red\">خاقانی .</font><br />از تبش عشق تو در روش مدح شاه <br />خاطر خاقانی است سحرحلال آفرین .<br /> <font color=\"Red\">خاقانی .</font><br />من چه گویم حسب حال خود که هست <br />عالم الاسرار گیتی آفرین .<br /> <font color=\"Red\">خاقانی .</font><br />آفرین جان آفرین پاک را<br />آنکه جان بخشید مشتی خاک را.<br /> <font color=\"Red\">عطار (منطق الطیر).</font><br />از کف پاکباز تو بال وپری جدا کند<br />روح مجسم ار کشد خامه ٔ صورت آفرین .<br /><font color=\"Red\">سیف اسفرنگ .</font><br /></font></div>'),
(1875, 'آفرین خوان', '<span class=\"hlight\">آفرین خوان .</span> <font color=\"DarkGreen\"><b>[ ف َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) آفرین گوی <span class=\"hlight\">:</span> <br />بجان آمدند آن سپاه مهان <br />شدند آفرین خوان بشاه جهان .<br /> <font color=\"Red\">فردوسی .</font><br />بر آن راه و رسم آفرین خوان شدند<br />شهنشاه را بنده فرمان شدند.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(1876, 'آفرین نامه', '<span class=\"hlight\">آفرین نامه .</span> <font color=\"DarkGreen\"><b>[ ف َ م َ ]</font></b> (اِخ ) نام منظومه ای و ظاهراً ببحر متقارب از ابوشکور بلخی <span class=\"hlight\">:</span> <br />نگه کن که در نامه ٔ آفرین <br />چه گوید سراینده ٔ پاکدین ...<br /><font color=\"Red\">(راحةالانسان ).</font><br /></font></div>'),
(1877, 'آفرین گر', '<span class=\"hlight\">آفرین گر.</span> <font color=\"DarkGreen\"><b>[ف َ گ َ ]</font></b> (ص مرکب ) آفرین خوان . آفرین گوی <span class=\"hlight\">:</span> <br />نهاد آن روی خون آلود بر خاک <br />اَبَر شاه آفرینگر، با دل پاک .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />جوان و پیر سزد آفرین گر تو که تو<br />بسال و بخت جوانی بعقل و دانش پیر.<br /><font color=\"Red\">معزی .</font><br /></font></div>'),
(1878, 'آفرینش', '<span class=\"hlight\">آفرینش .</span> <font color=\"DarkGreen\"><b>[ ف َ ن ِ ]</font></b> (اِمص ) اسم مصدر و عمل آفریدن . خلق . انشاء. ابداع . خلقت . (دهار). اسر. فطرت . (ربنجنی ). فطر. (دهار). جبلت . نشأت . بَنیه <span class=\"hlight\">:</span> <br />حکیما چو کس نیست گفتن چه سود<br />از این پس بگو کآفرینش چه بود.<br /> <font color=\"Red\">فردوسی .</font><br />من از آفرینش یکی بنده ام <br />پرستنده ٔ آفریننده ام .<br /> <font color=\"Red\">فردوسی .</font><br />در کتب طب چنین یافته می شودکه آبی که اصل آفرینش فرزند آدم است چون برحم پیوندد و آب زن بیامیزد تیره و غلیظ شود. (کلیله و دمنه ).<br />بپای فکرسفر کن در آفرینش خویش <br />بسا غنیمتها کاندرین سفر یابی .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />بنی آدم اعضای یکدیگرند<br />که در آفرینش ز یک گوهرند.<br /> <font color=\"Red\">سعدی .</font><br />ای دل توئی ّ و من، بنشین کژ، بگوی راست <br />تا زآفرینش تو جهان آفرین چه خواست .<br /> <font color=\"Red\">اوحدی .</font><br />زابتدای آفرینش تا بوقت پادشاه <br />از بزرگان عفو بوده ست از فرودستان گناه .<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) در امثله ٔذیل کلمه ٔ آفرینش ظاهراًسرنوشت و تقدیر و قلم رفته یا خالق و خدای عزوجل و مقدر آمده است <span class=\"hlight\">:</span> <br />توبا آفرینش بسنده نه ای <br />مشو تیز چون پرورنده نه ای .<br /> <font color=\"Red\">فردوسی .</font><br />ولیکن چو جان و سر بی بها<br />نهد بخرد اندر دم اژدها<br />چه پیش آیدش جز گزاینده زهر<br />کش از آفرینش چنین است بهر.<br /> <font color=\"Red\">فردوسی .</font><br />چو من صدهزاران فدای تو باد<br />خرد زآفرینش ردای تو باد.<br /> <font color=\"Red\">فردوسی .</font><br />زینسوی آفرینش و زآنسوی کائنات <br />بیرون و اندرون زمانه مجاورند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />سوی تو نوید گر فرستادند<br />بر دست زمانه زآفرینش دو.<br /> <font color=\"Red\">ناصرخسرو.</font><br />گفتم که آفرینش اسباب ظاهرند<br />گفتا که هست قدرت و تقدیر مشتهر<br />گفتم که بی مسبب هرگز بود سبب <br />گفتا که بی مقدّر هرگز بود قدر؟<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> مخلوق . کائنات . ماسوی اﷲ <span class=\"hlight\">:</span> <br />سوی آسمان کردش آن مرد روی <br />بگفت ای خدا این تن من بشوی <br />از این اَزْغها پاک کن مر مرا<br />همه آفرین زآفرینش ترا.<br /> <font color=\"Red\">ابوشکور.</font><br />نخست آفرینش خرد را شناس <br />نگهبان جان است و آن ِ سه پاس .<br /> <font color=\"Red\">فردوسی .</font><br />چیست خلاف اندر آفرینش عالم <br />چون همه را دایه و مَشاطه تو گشتی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آفرینش نثار فرق تواند<br />برمچین چون خسان ز راه نثار.<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(1879, 'آفریننده', '<span class=\"hlight\">آفریننده .</span> <font color=\"DarkGreen\"><b>[ ف َ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِخ ) آنکه آفریند. آنکه خلق کند. نامی از نامهای خدای تعالی . خالق . وجودبخشنده . آفریدگار. باری . فاطر. خلاق . ذاری . (ربنجنی ). جهان آفرین . مبدع . موجد. مکوّن . منشی <span class=\"hlight\">:</span> <br />چنین گفت کای داور دادِ پاک <br />توئی آفریننده ٔ باد و خاک .<br /> <font color=\"Red\">فردوسی .</font><br />به بینندگان آفریننده را<br />نبینی مرنجان دو بیننده را.<br /> <font color=\"Red\">فردوسی .</font><br />کز اویست پیروزی و دستگاه <br />هم او آفریننده ٔ هور و ماه .<br /> <font color=\"Red\">فردوسی .</font><br />بدین آلت و رای و جان و توان <br />ستود آفریننده را چون توان ؟<br /> <font color=\"Red\">فردوسی .</font><br />بداندیش ِ ما را تو کردی تباه <br />توئی آفریننده ٔ هور و ماه .<br /> <font color=\"Red\">فردوسی .</font><br />هم او آفریننده ٔ روزگار<br />به نیکی هم او باشد آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />چو بهرام را دید داننده مرد<br />بر او آفریننده را یاد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />یقین ْ مرد را دیده بیننده کرد<br />شد و تکیه بر آفریننده کرد.<br /> <font color=\"Red\">سعدی .</font><br />آنکه خود را شناخت نتواند<br />آفریننده را کجا داند؟<br /><font color=\"Red\">امیرخسرو.</font><br /></font></div>'),
(1880, 'آفرینگان', '<span class=\"hlight\">آفرینگان .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (اِ) رجوع به آفرنگان شود.<br /></font></div>'),
(1881, 'آفریک', '<span class=\"hlight\">آفریک .</span> (اِخ ) آفریکا. آفریقا. افریقا. افریقیه . رجوع به افریقیه شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1882, 'آفسانه', '<span class=\"hlight\">آفسانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) افسانه <span class=\"hlight\">:</span> <br />بدان بد کزین بد بهانه منم <br />سخن را نخست آفسانه منم .<br /> <font color=\"Red\">فردوسی .</font><br />آن موی که در ستایش آمد<br />زلف است و کله نه موی شانه <br />مردم جستم نه ریش و دستار<br />حکمت گفتم نه آفسانه .<br /> <font color=\"Red\">عمادی .</font><br />به پیش خلق شب و روز برمناقب تست <br />مدارِقصه و تاریخ و آفسانه ٔ من .<br /><font color=\"Red\">سیف اسفرنگ .</font><br /></font></div>'),
(1883, 'آفق', '<span class=\"hlight\">آفق .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص ) مرد بزرگوار. (مهذب الاسماء). آنکه در کرم به نهایت رسیده باشد. بغایت کریم .<br /></font></div>'),
(1884, 'آفق', '<span class=\"hlight\">آفق .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (ع ص ) نامختون .<br /></font></div>'),
(1885, 'آفقه', '<span class=\"hlight\">آفقه .</span> <font color=\"DarkGreen\"><b>[ ف ِ ق َ ]</font></b> (ع اِ) خاصره . تهیگاه .<br /></font></div>'),
(1886, 'آفقه', '<span class=\"hlight\">آفقه .</span> <font color=\"DarkGreen\"><b>[ ف ِ ق َ ]</font></b> (ع ص، اِ) تأنیث آفق . <BR><font color=\"Blue\">◄</font> ج ِ افیق . پوستهای دباغی شده . پوستهای نیم پیراسته .<br /></font></div>'),
(1887, 'آفل', '<span class=\"hlight\">آفل .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص ) فروشونده . ناپدیدگردنده . غروب کننده . که فرورود. غارب <span class=\"hlight\">:</span> <br />آنکه گه ناقص گهی کامل بود<br />نیست معبود خلیل آفل بود.<br /> <font color=\"Red\">مولوی .</font><br />هم خر و خرگیر اینجا در گلند<br />غافلند اینجا و آنجا آفلند.<br /> <font color=\"Red\">مولوی .</font><br />بانگ و صیتی جوکه آن خامل نشد<br />تاب خورشیدی که آن آفل نشد.<br /> <font color=\"Red\">مولوی .</font><br />جز خیالی عارضی ّ و باطلی <br />که بود چون صبح کاذب آفلی .<br /> <font color=\"Red\">مولوی .</font><br />ج، آفلین .<br /></font></div>'),
(1888, 'آفلات', '<span class=\"hlight\">آفلات .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص، اِ) ج ِ آفله .<br /></font></div>'),
(1889, 'آفله', '<span class=\"hlight\">آفله .</span> <font color=\"DarkGreen\"><b>[ ف ِ ل َ ]</font></b> (ع ص ) تأنیث آفل . ج، آفلات .<br /></font></div>'),
(1890, 'آفلونیا', '<span class=\"hlight\">آفلونیا.</span> (اِ) اَفلونیا. فَلونیا. نام معجونی طبّی است منسوب به آفولن، رب النوع روشنی و صنایع.<br /></font></div>'),
(1891, 'آفلین', '<span class=\"hlight\">آفلین .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص، اِ) ج ِ آفِل <span class=\"hlight\">:</span> <br />شد صفیر باز جان در مرج دین <br />نعره های لااحب الاَّفلین .<br /> <font color=\"Red\">مولوی .</font><br />ناخوشت آید مقال آن امین <br />در نُبی که لااحب الاَّفلین .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(1892, 'آفلیون', '<span class=\"hlight\">آفلیون .</span> (اِ) شیح جبلی .<br /></font></div>'),
(1893, 'آفند', '<span class=\"hlight\">آفند.</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (اِ) جنگ . خصومت <span class=\"hlight\">:</span> <br />دلیر و جهانسوز و پرخاشخر<br />جز آفند کاری ندارد دگر.<br /> <font color=\"Red\">فردوسی .</font><br />آورد پیامی که مبادا که خوری می <br />مستک شوی و عربده آغازی و آفند.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(1894, 'آفنداک', '<span class=\"hlight\">آفنداک .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b>(اِ) آدفنداک . آزفنداک . نوشه . قوس قزح . انطلیسون . تیراژه . کمر رستم . کمردون . طوق بهار. سریر. آدینده .<br /></font></div>'),
(1895, 'آفندیدن', '<span class=\"hlight\">آفندیدن .</span> <font color=\"DarkGreen\"><b>[ ف َ دی دَ ]</font></b> (مص ) اَفندیدن .<br />جنگ کردن . جدال و عداوت و خصومت ورزیدن <span class=\"hlight\">:</span> <br />در دل او آن نصیحت کار کرد<br />ترک آفندیدن و پیکار کرد.<br /><font color=\"Red\">لبیبی .</font><br /></font></div>'),
(1896, 'آفه', '<span class=\"hlight\">آفه .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (ع اِ) آفة. آفت . ج، آفات .<br /></font></div>'),
(1897, 'آفولن', '<span class=\"hlight\">آفولن .</span> <font color=\"DarkGreen\"><b>[ ل ُ ]</font></b> (اِخ ) اَفولن . رب النوع روشنی و صنایع یونانیان و رومیان را.<br /></font></div>'),
(1898, 'آفگانه', '<span class=\"hlight\">آفگانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص، اِ) اَفگانه . فگانه . آبگانه . جنین سقطشده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آفگانه کردن </span>؛ بچه افکندن <span class=\"hlight\">:</span> <br />شکم حادثات ِ آبستن <br />از نهیب تو آفگانه کند.<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(1899, 'آفی', '<span class=\"hlight\">آفی .</span> (اِخ ) تخلص یکی از امراء هند، موسوم باحمدیارخان، متوفی به سال <span class=\"hlight\" dir=\"rtl\">١٢٦٥</span> هَ .ق . او به فارسی شعر می گفته و مثنویی به نام گلزار خیال دارد.<br /></font></div>'),
(1900, 'آق', '<span class=\"hlight\">آق .</span> (ترکی، ص ) سپید. سفید.<br /></font></div>'),
(1901, 'آق', '<span class=\"hlight\">آق .</span> (اِخ ) نام طائفه ای از ترکمانان ساکن ایران، دارای <span class=\"hlight\" dir=\"rtl\">٧٠٠</span> خانوار. <BR><font color=\"Blue\">◄</font> نام طائفه ای از ترکمانان ایران، ساکن قزل ملته حرگلان دارای سی خانوار.<br /></font></div>'),
(1902, 'آق آتابای', '<span class=\"hlight\">آق آتابای .</span> (اِخ ) نام تیره ای از ترکمانان یموت .<br /></font></div>'),
(1903, 'آق اردو', '<span class=\"hlight\">آق اردو.</span> <font color=\"DarkGreen\"><b>[ اُ ]</font></b>(اِخ ) نام طایفه ای که از <span class=\"hlight\" dir=\"rtl\">١٢٢٦</span> تا <span class=\"hlight\" dir=\"rtl\">١٤٢٨</span> م . بر دشت قبچاق شرقی یعنی جانب مغرب سیراردو تسلط داشته اند، مقابل گوگ <font color=\"DarkGreen\"><b>[ کبود ]</font></b>اردو که نام قسمت دست چپ قبائل مطیع باتو بود. قبایل آق اردو همیشه بر طوائف گوگ اردو چیره بودند و گاهی نیز بر سایر شعب متمدن خاندان باتو در دوره ٔ ضعف آنان دست اندازی می کردند. در این قبیله ریاست از پدر بپسر ارث میرسیده است . یکی از رؤسای آق اردو موسوم به کوچی، تا نواحی غزنه و بامیان را نیز متصرف شده و اوروس خان نخستین خان این خاندان چند کرت سپاه امیرتیمور را شکست داده است . در زمان توقتمش نفاق دیرینه ٔ قبایل آق اردو با گوگ اردو از میان برخاست و این دو طائفه در تحت لواء توقتمش یکی شده بروسیه لشکرکشیده و مسکو را مسخّر کرده و امر بغارت داده اند.<br /></font></div>'),
(1904, 'آق بهی', '<span class=\"hlight\">آق بهی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) نام تیره ای از قشقائی نزدیک <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> خانوار.<br /></font></div>'),
(1905, 'آق حصار', '<span class=\"hlight\">آق حصار.</span> <font color=\"DarkGreen\"><b>[ ح ِ ]</font></b> (اِخ ) نام شهری در <span class=\"hlight\" dir=\"rtl\">٨٠</span> هزارگزی ازمیر، دارای دوازده هزار مردم . و این همان ثیاتیرای قدیم باشد.<br /></font></div>'),
(1906, 'آق دربند', '<span class=\"hlight\">آق دربند.</span> <font color=\"DarkGreen\"><b>[ دَ ب َ ]</font></b> (اِخ ) نام دره ای در شمال مشهد، و در آنجا سه رَگه ٔ مهم ذغال سنگ هست .<br /></font></div>'),
(1907, 'آق دریا', '<span class=\"hlight\">آق دریا.</span> <font color=\"DarkGreen\"><b>[ دَرْ ]</font></b> (اِخ ) بحر خزر.<br /></font></div>'),
(1908, 'آق سنقر', '<span class=\"hlight\">آق سنقر.</span> <font color=\"DarkGreen\"><b>[ س ُ ق ُ ]</font></b> (ترکی، اِ مرکب ) (از ترکی ِ آق، سپید + سُنقر، شنگار و شنغار، نام یکی از جوارح طیور) صاحب برهان گوید: مرغی باشد شکاری از جنس شاهین و چرخ بحری، و لقب پادشاهان ترک نیز بوده، و کنایه از روز و آفتاب هم هست و گویند این لقب ترکیست - انتهی . مقابل قره سنقر.و خاقانی آق سنقری و قره سنقری را چون وصفی می آورد.<br /></font></div>'),
(1909, 'آق سنقر', '<span class=\"hlight\">آق سنقر.</span> <font color=\"DarkGreen\"><b>[ س ُ ق ُ ]</font></b> (اِخ ) نام فرمانروای ارمینیه (<span class=\"hlight\" dir=\"rtl\">٥٧٩</span>-<span class=\"hlight\" dir=\"rtl\">٥٨٩</span> هَ .ق .).<br /></font></div>'),
(1910, 'آق سنقر', '<span class=\"hlight\">آق سنقر.</span> <font color=\"DarkGreen\"><b>[ س ُ ق ُ ]</font></b> (اِخ ) یکی از غلامان ترک ملک شاه که در حلب از جانب تتش حکومت داشت (<span class=\"hlight\" dir=\"rtl\">٤٧٨</span>-<span class=\"hlight\" dir=\"rtl\">٤٨٧</span> هَ .ق .)، و در آخر کار بر تتش قیام کرد و اسیر شد. و او پدر اتابک عمادالدین زنگی سرسلسله ٔ اتابکان موصل و حلب است . و نام کامل او قسیم الدوله ابوسعید حاجب آق سنقربن عبداﷲ است . <BR><font color=\"Blue\">◄</font> نام یکی از امراء معروف عصر سلاجقه که با اهل صلیب جنگهای بزرگ داده و در <span class=\"hlight\" dir=\"rtl\">٥٢٠</span> هَ .ق .فدائیان مقتول گردیده است . <BR><font color=\"Blue\">◄</font> نام چند تن دیگر از امرای سلجوقیان و غیرهم .<br /></font></div>'),
(1911, 'آق سو', '<span class=\"hlight\">آق سو.</span> (اِخ ) نام ترکی چند رود به آسیای مرکزی .<br /></font></div>'),
(1912, 'آق سو', '<span class=\"hlight\">آق سو.</span> (اِخ ) نام شهری بترکستان شرقی چین، دارای <span class=\"hlight\" dir=\"rtl\">٥٠</span>هزار سکنه . <BR><font color=\"Blue\">◄</font> نام واحه ای بترکستان . <BR><font color=\"Blue\">◄</font> نام شهری به آسیای صغیر.<br /></font></div>'),
(1913, 'آق شهر', '<span class=\"hlight\">آق شهر.</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِخ ) نام شهری از ولایت قونیه .<br /></font></div>'),
(1914, 'آق قلعه', '<span class=\"hlight\">آق قلعه .</span> <font color=\"DarkGreen\"><b>[ قَل ْ ع َ ]</font></b> (اِخ ) نام محلی براه حیدرآباد به خانه، در <span class=\"hlight\" dir=\"rtl\">١٦</span> هزارگزی حیدرآباد، میان حیدرآباد و نقده .<br /></font></div>'),
(1915, 'آق قویونلو', '<span class=\"hlight\">آق قویونلو.</span> (اِخ ) نام طائفه ای از امرای ترکمان، رقبای قبیله ٔ قره قویونلو که از <span class=\"hlight\" dir=\"rtl\">٧٨٠</span> تا <span class=\"hlight\" dir=\"rtl\">٩٠٨</span> هَ .ق . در آذربایجان و دیاربکر حکمرانی داشتند و شاه اسماعیل صفوی در <span class=\"hlight\" dir=\"rtl\">٩٠٧</span> در جنگ شرور آنان را مغلوب و منقرض کرد. قرایولق عثمان، حمزه، جهانگیر، اوزون حسن، خلیل، یعقوب، بایسنقر، رستم، احمد، مراد، الوند، مراد (بار دوم ) نام امرای این طایفه است .<br /></font></div>'),
(1916, 'آق محمدتیمور', '<span class=\"hlight\">آق محمدتیمور.</span> <font color=\"DarkGreen\"><b>[ م ُ ح َم ْ م َ ت َ ]</font></b> (اِخ ) سومین حکمران سربداری که در بیهق فرمانروائی داشتند. وی به سال <span class=\"hlight\" dir=\"rtl\">٧٤٤</span> هَ .ق . پس از کشته شدن سلف او خواجه وجیه الدین بر مسند حکومت نشست و پس از دو سال و دو ماه بر دست خواجه علی شمس الدین بقتل رسید.<br /></font></div>'),
(1917, 'آق مسجد', '<span class=\"hlight\">آق مسجد.</span> <font color=\"DarkGreen\"><b>[ م َ ج ِ ]</font></b> (اِخ ) مرکز شبه جزیره ٔ قرم (کریمه ) که امروز به نام سیمفروپول مشهور است و در <span class=\"hlight\" dir=\"rtl\">١١٦٤</span> هَ .ق . دولت روس آنجارا تسخیر کرد و محله ای نو بساختند و قصبه ٔ قدیمی ازاهمیت سابق بیفتاد. سکنه ٔ آن در حدود سی هزار است .<br /></font></div>'),
(1918, 'آق پر', '<span class=\"hlight\">آق پر.</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (ص مرکب ) (از ترکی ِ آق، سفید + فارسی ِ پر، رگ ِ خُرد) نام قسمی چای که دارای رنگ روشن و طعمی تلخ تر و بوی خوش است .<br /></font></div>'),
(1919, 'آق چای', '<span class=\"hlight\">آق چای .</span> (اِخ ) سفیدرود. و آن دارای دوشعبه است، یکی موسوم به قتورچای که از خوی گذرد و دیگری رود مرند که در جنوب ماری کند به قتورچای پیونددو در ماریکند شعبه ٔ اصلی آقچای که از جنوب چالدران جاری است به آن پیوسته در مغرب جلفا به ارس آمیزد.<br /></font></div>'),
(1920, 'آق کند', '<span class=\"hlight\">آق کند.</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) نام مرکز بلوک کاغه کنان در خلخال .<br /></font></div>'),
(1921, 'آق گنبد', '<span class=\"hlight\">آق گنبد.</span> <font color=\"DarkGreen\"><b>[ گُم ْ ب َ ]</font></b> (اِخ ) نام محلی نزدیک شرف خانه، بساحل دریاچه ٔ ارومیّه .<br /></font></div>'),
(1922, 'آقا', '<span class=\"hlight\">آقا.</span> (ترکی، اِ) خواجه . کیا. مهتر. سراکار. سرکار. بزرگ . سَر. سَرور. میر. میره . خداوند. خداوندگار. سیّد. مولی . صاحب . و در صدر یا ذیل نامهای خاص، کلمه ٔ تعظیم است .<br /> - <span class=\"hlight\">آقابالاسر</span> ؛ مدعی سری و مهتری بر کسی بی سود و نفعی برای آن کس : آقابالاسر لازم ندارم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آقاها</span> ؛ در تداول خانگی، مؤدّب . موقّر.<br /></font></div>'),
(1923, 'آقا', '<span class=\"hlight\">آقا.</span>(اِخ ) نام قلعه ای بکرمان . رجوع به کلاته ٔ آقا شود.<br /></font></div>'),
(1924, 'آقا و اینی', '<span class=\"hlight\">آقا و اینی .</span> <font color=\"DarkGreen\"><b>[ وُ اَ ]</font></b> (ترکیب عطفی، اِ مرکب ) شورای برادر بزرگ و کوچک، و توسعاً، مجمع و شورای شاهزادگان .<br /></font></div>'),
(1925, 'آقابا', '<span class=\"hlight\">آقابا.</span> (اِخ ) آقابابا. نام قریه ای بزرگ در راه قزوین و رشت میان حسین آباد و رشت، در <span class=\"hlight\" dir=\"rtl\">١٧٠</span> هزارگزی طهران، و سنجد آن بخوبی مشهور است .<br /></font></div>'),
(1926, 'آقابلی چی', '<span class=\"hlight\">آقابلی چی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص مرکب ) متملق . چاپلوس . آنکه هرچه دیگری گوید تصدیق کند خوش آمدِ گوینده را.<br /></font></div>'),
(1927, 'آقاج', '<span class=\"hlight\">آقاج .</span> (ترکی، اِ) آغاج . فرسنگ . فرسخ . مطابق هفت ورس روسی .<br /></font></div>'),
(1928, 'آقاجری', '<span class=\"hlight\">آقاجری .</span> (اِخ ) نام یکی از سه شعبه ٔ طوایف کوه گیلویه، دارای دوهزار خانوار.<br /></font></div>'),
(1929, 'آقازاده', '<span class=\"hlight\">آقازاده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب، اِ مرکب ) زاده ٔ آقا. فرزند مردی بزرگ، و بیشتر فرزندان سادات علوی و مجتهدین .<br /></font></div>'),
(1930, 'آقازادگی', '<span class=\"hlight\">آقازادگی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص مرکب ) مقام و رتبت آقازاده .<br /></font></div>'),
(1931, 'آقاسی', '<span class=\"hlight\">آقاسی .</span> (ترکی، اِ مرکب ) (شاید از ترکی ِ آقا، سید + سی، حرف اضافه ) نامی از نامها: حاج میرزا آقاسی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اشیک آقاسی </span> ؛ رئیس دربار.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">قوللرآقاسی </span> ؛ رئیس غلامان خاصه . داروغه ٔ دیوان خانه .<br />و رجوع به آغاچی شود.<br /></font></div>'),
(1932, 'آقاعلی', '<span class=\"hlight\">آقاعلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (معدن ...) بجنوب ارس و مغرب کانتال، نام معدن آهنی است ممزوج با پیریت و مس کلوخه . و در برابر آن به دره ٔ آهکی دامنه ٔ کوهستانی کانتال معدن دیگری از آهن هست نیز بدین نام .<br /></font></div>'),
(1933, 'آقال', '<span class=\"hlight\">آقال .</span> (اِ) مصحف آخال . داس و دلوس . خاش و خماش . سَقط. افکندنی . بکارنیامدنی .<br /></font></div>'),
(1934, 'آقبانو', '<span class=\"hlight\">آقبانو.</span> (اِ مرکب ) قسمی جامه ٔ باریک پنبه ای منقش که زنان از آن پیراهن و چادرنماز کردندی .<br /></font></div>'),
(1935, 'آقداغ', '<span class=\"hlight\">آقداغ .</span> (اِخ ) نام کوهی میان دو دره ٔ قزل اوزن و زنگانه رود. <BR><font color=\"Blue\">◄</font> نام سلسله ٔ کوهی واقعدر سرحد غربی ایران، مشتمل بر آقداغ کوچک و بزرگ .<br /></font></div>'),
(1936, 'آقداغ بزرگ', '<span class=\"hlight\">آقداغ بزرگ .</span> <font color=\"DarkGreen\"><b>[ غ ِ ب ُ زُ ]</font></b> (اِخ ) رجوع به آقداغ شود.<br /></font></div>'),
(1937, 'آقداغ کوچک', '<span class=\"hlight\">آقداغ کوچک .</span> <font color=\"DarkGreen\"><b>[ غ ِ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِخ ) رجوع به آقداغ شود.<br /></font></div>'),
(1938, 'آقداغی', '<span class=\"hlight\">آقداغی .</span> (اِخ ) (سفیدکوه ) نام کوهی در سرحد غربی ایران .<br /></font></div>'),
(1939, 'آقرا', '<span class=\"hlight\">آقرا.</span> (اِخ ) نام رودی از آب راهه های ارس .<br /></font></div>'),
(1940, 'آقسرای', '<span class=\"hlight\">آقسرای .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) نام شهری ازولایت قونیه . <BR><font color=\"Blue\">◄</font> نام محله ای به اسلامبول .<br /></font></div>'),
(1941, 'آقسرایی', '<span class=\"hlight\">آقسرایی .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (ص نسبی ) منسوب به آقسرای . <BR><font color=\"Blue\">◄</font> (اِخ ) لقب جمال الدین محمد از اخلاف امام فخر رازی، و او از دانشمندان عصر خویش بوده است، معاصر با میرسید شریف جرجانی .<br /></font></div>'),
(1942, 'آقشام', '<span class=\"hlight\">آقشام .</span> (اِ مرکب ) (از ترکی ِ آق، سپید + فارسی ِ شام، شب ) اول شب . فلق . <BR><font color=\"Blue\">◄</font> نوبتی که بر در پادشاهان و امراء ترک زدندی شامگاهان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آقشام زدن </span> .<br /></font></div>'),
(1943, 'آقشقه', '<span class=\"hlight\">آقشقه .</span> <font color=\"DarkGreen\"><b>[ ق ِ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (اِ) قسمی در بی پاشنه که بر روی چارچوب نیفتد بلکه چون ببندند با چهارچوب پیوندد.<br /></font></div>'),
(1944, 'آقطی', '<span class=\"hlight\">آقطی .</span> (معرب، اِ) نام گیاهی که آن را بیلسان و بیلاسان و شُبوقه و خمان کبیر ویاس کبود گویند. اَقطی . اقطی بزرگ . نام آن بلاطینیه، سامبوکوس نیگرا، باشد.<br /></font></div>'),
(1945, 'آقطی صغیر', '<span class=\"hlight\">آقطی صغیر.</span> <font color=\"DarkGreen\"><b>[ ی ِ ص َ]</font></b> (ترکیب وصفی، اِ مرکب ) نام گیاهی که آن را اِبُل، بُل، بُل شیرین، بیلسان خرد، بیلاسان خرد، بیل، طراثیت، طرثیث، طرثوث، شُن، خامااَقطی، خمان صغیر، خمان الارض، غلیون و یدقه نیز گویند. و آن مسهلی قویست و لاطینی آن اِبولوس میباشد.<br /></font></div>'),
(1946, 'آقوش', '<span class=\"hlight\">آقوش .</span> (اِ) ببر و شیر و پلنگ و یوز، و مطلق سباع . (بعض فرهنگهای نو).<br /></font></div>'),
(1947, 'آقچه', '<span class=\"hlight\">آقچه .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (ترکی، اِ) اَخْچه . اَقْچه .زر یا سیم مسکوک، و توسعاً، هر مسکوکی <span class=\"hlight\">:</span> <br />وز پی آن تا زند سکه به نام بقاش <br />میزند از آفتاب آقچه موزون فلک .<br /> <font color=\"Red\">خاقانی .</font><br />آقچه زر گر هزار سال بماند<br />عاقبتش جای هم دهانه ٔ گاز است .<br /> <font color=\"Red\">خاقانی .</font><br />شاهد طارم فلک رست ز دیو هفت سر<br />ریخت بهر دریچه ای آقچه زرّ شش سری .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(1948, 'آل', '<span class=\"hlight\">آل .</span> (ص ) سرخ . احمر <span class=\"hlight\">:</span> <br />دو لب چو نار کفیده چو برگ سوسن زرد<br />دو رخ چو نار شکفته چو برگ لاله ٔ آل .<br /> <font color=\"Red\">فرخی .</font><br />از تازه گل و لاله که در باغ بخندد<br />در باغ نکوتر نگری چشم شود آل .<br /> <font color=\"Red\">فرخی .</font><br />میرُست ز دشت خاوران لاله ٔ آل <br />چون دانه ٔ اشک عاشقان در مه و سال .<br /> <font color=\"Red\">ابوسعید ابوالخیر.</font><br />تا بود بی زخم روی چرخ سیمابی کبود<br />همچو لعل از خون دل رخسار خصمت آل باد.<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />صد شام در فراق سطرلاب آفتاب <br />از خون دیده دامن افلاک آل کرد.<br /><font color=\"Red\">شمس طبسی .</font><br />نه باده یابی روشن نه رنگ ساقی لعل <br />نه چشمه بینی صافی نه چهره بینی آل .<br /> <font color=\"Red\">طالب .</font><br />در اطلس آل گرم و سرکش <br />ابراهیمی میان آتش .<br /> <font color=\"Red\">قاسم گونابادی .</font><br />و آل در کلمه ٔ آلگونه و آلغونه به همین معنی است . <BR><font color=\"Blue\">◄</font> سرخ نیمرنگ در تداول زنان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خون آل </span> ؛ خون نیمرنگ . خونی رنگ باخته <span class=\"hlight\">:</span> <br />رحمی بشیشه خانه ٔ دلهای خلق کن <br />از می مکن دوآتشه این رنگ آل را.<br /> <font color=\"Red\">صائب .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">لاله ٔ آل </span> ؛ قسمی لاله که رنگ سرخ دارد.<br /> <BR><font color=\"Blue\">◄</font> خندان بلغت خوارزمیان . <BR><font color=\"Blue\">◄</font> (اِ) نام درختی که از بیخ آن رنگی سرخ گیرند و جامه بدان سرخ کنند، و نیز در طب بکار است . و شاید آلائی یا وسمه ٔ اَلائی در بیت ذیل همین کلمه باشد <span class=\"hlight\">:</span> <br />تا بوی دهدیاسمن و چنبی و سنبل <br />تا رنگ دهد وسمه ٔ رومی ّ و الائی .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> مُهر و نگین پادشاهان بترکی (از برهان )، و ظاهراً این درست نیست و از کلمه ٔ آل تمغا (از آل یعنی سرخ + تمغا به معنی مُهر) در مقابل قره تمغا (از قره یعنی سیاه + تمغا به معنی مُهر) گمان برده اند که آل به معنی مُهر است و در بیت ذیل نزاری نیز آل مخفف آل تمغاست و بمعنی مُهر مطلق نیست <span class=\"hlight\">:</span> <br />ز بیم خاتم القاب تو نهادستند<br />بحکم یرلیغ از آل ایلخان یاقوت .<br /><font color=\"Red\">نزاری .</font><br /></font></div>'),
(1949, 'آل', '<span class=\"hlight\">آل .</span> (پسوند) َال . چنانکه آله (َاله ) در آخر بعض کلمات، گاه ادات نسبت باشدو گاه افاده ٔ معنی تشبیه کند، مانند انگشتال به معنی چون انگشت، یعنی لوت . عور. بی سازوبرگ <span class=\"hlight\">:</span> <br />ز خانمان وقرابت بغربت افتادم <br />بماندم اینجا بی سازوبرگ و انگشتال .<br /> <font color=\"Red\">ابوالعباس .</font><br />و امروزنیز در تداول عوام تشبیهی مبتذل هست و گویند مثل انگشت لیشته (لیسیده ) به همین معنی . و اینکه در فرهنگ منسوب به اسدی به کلمه ٔ انگشتال معنی بیمارناک داده اند، ظاهراً درست نیست . و تیغال در شکر تیغال مرکب از تیغ به معنی خار و آل ادات نسبت . و چنگال از چنگ و آل . و خشکال از خشک و آل، برگها و شاخهای خرد خشک از درختی زنده و سبز. و خنگال از خنگ، به معنی سپید و روشن و آل . و درغال، از درغ بمعنی سد و بند، و آل که جمعاً به معنی سد و بند بسته و استوارکرده است <span class=\"hlight\">:</span> <br />ای شاه نبی سیرت ایمان بتو محکم <br />ای میرعلی حکمت عالم بتو درغال .<br /> <font color=\"Red\">رودکی .</font><br />و دنبال از دنب و آل . و کاخال از کاخ و آل، بمعنی اثاث کاخ از فُروش و اوانی و کرسیها و جز آن . و کشال از کش، پیوندگاه سر ران بیک سوی زیرین شکم از پیش روی و آل ِ ادات نسبت به معنی نواحی و حوالی کش . و کنغال و کنگال و کنغالگی و کنگالگی، از کنگ و آل . و کوپال از کوب و کوپ به معنی ضرب و زخم وآل ِ نسبت . و کوتوال از کوت قلعه و آل ادات نسبت . و کونال در اصطلاح بنایان، بن یا سر دیوار یعنی آن جزء از دیوار که بزمین یا سقف پیوندد. و گریال از گری به معنی مطلق پیمانه و آل ادات نسبت، به معنی ساعت آبی <span class=\"hlight\">:</span> <br />دانی چراست ناله ٔ گریال هر دمی <br />یعنی که این سرای مقام درنگ نیست .<br /> <font color=\"Red\">؟</font><br />و گوال از گو به معنی بزرگ یا سرگین و آل، ادات نسبت . و گوگال از گوه به معنی عَذِره و آل نسبت . اصل کلمه ٔ جعل عربی . و مرکب بودن کلمات ذیل نیز با آل بعید نمی نماید: پشکال از پشک به معنی شب نم و آل برسات، یعنی موسم بارانهای ممتد هند. و پشه غال از پشه یا پشک و آل . و پوچال و پوشال و پوکال ازپوچ و پوش و پوک، به معنی تهی و بی مغز، و آل . و پیخال از پیخ و آل . و تروال و جنجال و جوال و چال و غنجال و کلال (شاید از کله و آل ) و همال (احتمالاً از هم و آل، مانند هماور از هم و آورد، و همانند از هم و مانند). و البته آنچه در معنی آل و کلمات مختومه ٔ بدان گفته شد از حدّ حدسی ساده تجاوز نمیکند لیکن از مجموع شواهد مذکوره و نظایر آن و نیز آمدن آل به همین معانی در بعض زبانهای دیگر آریائی در صحت قسمتی از این دعاوی ظنی قریب بیقین حاصل می آید . و آل در کلمات کاخال و آل عطاری و آل و اوضاع ظاهراً به معنی ادوات و آلات باشد.<br /></font></div>'),
(1950, 'آل', '<span class=\"hlight\">آل .</span> (اِخ ) نام قلعه ای بخراسان <span class=\"hlight\">:</span> <br />شنیدم از این مرزها هرچه گفت <br />بلندی ّ و پستی ّ و راز نهفت <br />چو آل و چو فخروم و چون دشت گل <br />بخوبی نمود آنچه بودش بدل .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(1951, 'آل', '<span class=\"hlight\">آل .</span> (اِ) نام دیوی مادینه، یعنی پری بدکار در خرافات زنانه که بشب ششم جگر زچگان بَرَد و آنان را هلاک کند. <BR><font color=\"Blue\">◄</font> بیماری که زن نوزاده را رسد تا شش روز پس از وضع حمل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آل </span> ؛ زنی بداندرون و بدخواه .<br /><BR><font color=\"Blue\">◄</font> مرضی به صورت صرع که زنان حامله را افتد . <BR><font color=\"Blue\">◄</font> قسمی ماهی بزرگ، و این مصحف بال و وال است .<br /></font></div>'),
(1952, 'آل', '<span class=\"hlight\">آل .</span> (ع اِ) گروه خویشان . (مهذب الاسماء). خاندان (مجمل اللغه ). دودمان . دوده . فرزندان . فرزندزادگان . خویشان . خویشاوندان . تبار.اولاد. اهل . اهل خانه . اهل بیت . عیال . اهل و عیال . قبیله و عشیره . قوم . چون : آل احمد. آل اردشیر. آل افراسیاب . آل افریغ. آل اﷲ (مجازاً). آل امیر. آل باوند. آل برمک . آل برهان . آل بویه . آل تبانیان . آل جعفر. آل جفنه . آل حق (بمجاز). آل خورشیدی . آل داود.آل ساسان . آل سامان . آل سلجوق . آل شنسب . آل صوفان . آل طاهر. آل طه (مجازاً). آل عباس . آل عثمان . آل عراق . آل عقیل . آل علی . آل عمران . آل غسان . آل فاطمه . آل فرعون . آل فریغون . آل قاورد. آل کثیر. آل کثکثه . آل محتاج . آل محمد. آل مظفر. آل میکال . آل ناصرالدین . آل نصرة. آل نوبخت . آل یاسین (مجازاً) <span class=\"hlight\">:</span> <br />ای فخر آل اردشیرای مملکت را ناگزیر<br />ای همچنان چون جان و تن افعال و اعمالت هژیر.<br /> <font color=\"Red\">دقیقی .</font><br />از آن چندان نعیم این جهانی <br />که ماند از آل سامان وآل ساسان <br />ثنای رودکی مانده ست و مدحت <br />نوای باربد مانده ست و دستان .<br /> <font color=\"Red\">مجلدی جرجانی .</font><br />گر سوی آل مرد شود مال او چرا<br />زی آل او نشد ز پیمبر شریعتش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />جز که زهرا و علی واولادشان <br />مر رسول مصطفی را کیست آل ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />سعدی اگر عاشقی کنی ّ و جوانی <br />عشق محمد بس است و آل محمد.<br /> <font color=\"Red\">سعدی .</font><br />با آل علی هرکه درافتادبرافتاد.<br /> <BR><font color=\"Blue\">◄</font> سراب . کوراب . کَوَر. کتیر. واله که بامدادو شبانگاه بینند <span class=\"hlight\">:</span> <br />با عطای کف تو بخشش آل برمک <br />مَثَل ِ لجه ٔ دریا بود و لمعه ٔ آل .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />نسبت دست تو میکردم بدریا عقل گفت <br />رسم دانش نیست کردن نسبت دریا به آل .<br /> <font color=\"Red\">حسین کاشفی .</font><br /><BR><font color=\"Blue\">◄</font> چوب . <BR><font color=\"Blue\">◄</font> ستون خیمه . <BR><font color=\"Blue\">◄</font> تابعین . پیروان . پس روان . <BR><font color=\"Blue\">◄</font> اولیاء کسی . <BR><font color=\"Blue\">◄</font> پیرامون کوه . نواحی جبل . <BR><font color=\"Blue\">◄</font> شخص . کالبد. شبح . <BR><font color=\"Blue\">◄</font> و صاحب برهان بتقلید سایر فرهنگ نویسان بکلمه ٔ آل عربی معنی شراب خوردن صبح و شام داده است، و این از غلط خواندن عبارت قوامیس عرب است که در فرق آل و سراب مینویسند: اَلاَّل ؛ السراب . مذ غدوة الی ارتفاع الضحی الاعلی ثم هو سراب سائر الیوم - انتهی . الاَّل ؛ السراب او هو خاص بما فی اول النهار. و لفظ سراب را شراب به معنی خمر خوانده اند. <BR><font color=\"Blue\">◄</font> (اِخ ) نام کوهی .<br /></font></div>'),
(1953, 'آل آجیل', '<span class=\"hlight\">آل آجیل .</span> (اِ مرکب، از اتباع ) آل و آجیل . آجیل و جز آن . توسعاً، سود. فائده .<br /></font></div>'),
(1954, 'آل آروادی', '<span class=\"hlight\">آل آروادی .</span> <font color=\"DarkGreen\"><b>[ رْ ]</font></b> (اِ مرکب ) (از: فارسی ِ آل، دیو مادینه که به زچگان آسیب رساند + ترکی ِ آروادی، زن ) مثل آل آروادی ؛ زنی سخت بی حیا و بدرفتار.<br /></font></div>'),
(1955, 'آل آشخال', '<span class=\"hlight\">آل آشخال .</span> (اِمرکب، از اتباع ) آل آشغال . خاش و خماش . خرت و پرت .<br /></font></div>'),
(1956, 'آل آفریغ', '<span class=\"hlight\">آل آفریغ.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) نام سلسله ای از ملوک خوارزم که پیش از اسلام تا زمان سامانیان در آن خطه فرمان رانده اند. و آفریغ نام مؤسس این دوده است و متأخرین آنان را که در دوره ٔ اسلامی میزیسته اند آل عراق نیز نامیده اند. و آنان را آل افریغون و آل فریغون نیز گویند.<br /></font></div>'),
(1957, 'آل ا', '<span class=\"hlight\">آل ا.</span> <font color=\"DarkGreen\"><b>[ لُل ْ لاه ]</font></b> (ع اِ مرکب ) اولیای خدا. <BR><font color=\"Blue\">◄</font> (اِخ ) خاندان و احفاد رسول صلوات اﷲعلیه .<br /></font></div>'),
(1958, 'آل ابوسفیان', '<span class=\"hlight\">آل ابوسفیان .</span> <font color=\"DarkGreen\"><b>[ ل ِ اَ س ُف ْ ]</font></b> (اِخ ) آل بوسفیان .بنوامیه . از اولاد ابوسفیان و مراد معاویةبن ابی سفیان و یزیدبن معاویه و معاویةبن یزید است <span class=\"hlight\">:</span> <br />چه خطر دارد آل بوسفیان <br />که برآرند نامشان بزبان ؟<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(1959, 'آل اخشید', '<span class=\"hlight\">آل اخشید.</span> <font color=\"DarkGreen\"><b>[ ل ِ اِ ]</font></b> (اِخ )خانواده ای از امرای ایرانی نژاد که از سال <span class=\"hlight\" dir=\"rtl\">٣٢٣</span> تا <span class=\"hlight\" dir=\"rtl\">٣٥٨</span> هَ .ق . در مصر و شام و دمشق و حرمین به استقلال فرمانروا بوده اند. سرسلسله ٔ آنان محمدبن طغج معروف به اخشید و آخریشنان ابوالفوارس احمدبن علی و عده ٔ آنان پنج تن : محمد اخشیدبن طغج (<span class=\"hlight\" dir=\"rtl\">٣٢٣</span> - <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>)، ابوالقاسم انوجور (به معنی محمود. ابن خلکان ) ابن اخشید (<span class=\"hlight\" dir=\"rtl\">٣٣٤</span> - <span class=\"hlight\" dir=\"rtl\">٣٤٩</span>)، ابوالحسن علی بن اخشید (<span class=\"hlight\" dir=\"rtl\">٣٤٩</span> - <span class=\"hlight\" dir=\"rtl\">٣٥٥</span>)، ابوالمسک کافور (از خادمان یعنی خواجه سرایان ) (<span class=\"hlight\" dir=\"rtl\">٣٥٥</span> - <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>)، ابوالفوارس احمدبن علی (<span class=\"hlight\" dir=\"rtl\">٣٥٧</span> - <span class=\"hlight\" dir=\"rtl\">٣٥٨</span>). اخشید عنوان رسمی و عام امرای فرغانه است که این دوده نیز از آن خاندان بوده اند. و فاطمیان مصر این سلسله را منقرض کردند.<br /></font></div>'),
(1960, 'آل اردشیر', '<span class=\"hlight\">آل اردشیر.</span> <font color=\"DarkGreen\"><b>[ ل ِ اَ دَ ]</font></b> (اِخ ) ساسانیان . <BR><font color=\"Blue\">◄</font> در بیت ذیل مراد چغانیان یا سامانیانند <span class=\"hlight\">:</span> <br />ای فخر آل اردشیر ای مملکت را ناگزیر<br />ای همچنان چون جان و تن آثار و افعالت هژیر.<br /><font color=\"Red\">دقیقی .</font><br /></font></div>'),
(1961, 'آل اغلب', '<span class=\"hlight\">آل اغلب .</span> <font color=\"DarkGreen\"><b>[ ل ِ اَ ل َ ]</font></b> (اِخ ) نام سلسله ای از پادشاهان افریقیه از دست بنی عباس . مقر سلطنت قیروان و قلمرو آنان در شمال افریقا بوده است . و ده تن بوده اند، نخستین ابراهیم اغلب و آخرین زیادةاﷲ ثالث است و مدت حکمرانی آنان <span class=\"hlight\" dir=\"rtl\">١٤٦</span> سال کشیده است .در <span class=\"hlight\" dir=\"rtl\">٢٩٦</span> هَ .ق . فاطمیان این سلسله را برانداختند.<br /></font></div>'),
(1962, 'آل افراسیاب', '<span class=\"hlight\">آل افراسیاب .</span> <font color=\"DarkGreen\"><b>[ ل ِ اَ ]</font></b> (اِخ ) نام سلسله ای از امراء ترک که آل خاقان و خانیه و ایلک خانیه و افراسیابیه نیز خوانده میشوند (از حدود <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> تا حدود <span class=\"hlight\" dir=\"rtl\">٥٦٠</span> هَ .ق .). از تاریخ این سلسله اطلاعات کمی در دست است و ظاهراً امرای مزبور پس از اتحاد با طوائف ترکان مشرق فرغانه در قرن چهارم هجری قبول اسلام کرده اند. پایتخت این امرا در کاشغر بوده و ایلک خان نصردر سال <span class=\"hlight\" dir=\"rtl\">٣٨٩</span> هَ .ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">٩٩٩</span> م . پس از تسخیر ماوراءالنهر بخارا را مرکز قرار داده و از آنجا بر ممالکی که از بحر خزر تا حدود چین امتداد داشته حکومت کرده است .امرای ایلک خانیه درصدد تسخیر ولایات جنوبی جیحون نیزبرآمدند ولی پس از شکستی که در سال <span class=\"hlight\" dir=\"rtl\">٣٩٨</span> هَ .ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٠٠٧</span> م . از سلطان محمود غزنوی یافتند بهمان ماوراءالنهر و کاشغر و مغولستان شرقی قناعت کردند. در ایام امارت این سلسله قبایل دیگری نیز از ترکان به ماوراءالنهر آمدند و بعدها از آنجا به ایران راه یافتند و ازاین قبایلند ترکمانان سلجوقی . ترتیب جانشینی امرای ایلک خانی از یکدیگر و سنوات راجع بامارات هر یک از ایشان تحقیقاً معلوم نیست . و فهرست ذیل تقریبی است :<br />عبدالکریم ستق، موسی بن ستق، شهاب الدوله هارون بغراخان بن سلیمان (وفاتش بین <span class=\"hlight\" dir=\"rtl\">٣٨٣</span>-<span class=\"hlight\" dir=\"rtl\">٣٨٤</span>)، ابوالمحسن نصر اول بن علی (حدود <span class=\"hlight\" dir=\"rtl\">٣٨٩</span>-<span class=\"hlight\" dir=\"rtl\">٤٠٠</span>)، قطب الدوله ابونصر احمد اول بن علی (حدود <span class=\"hlight\" dir=\"rtl\">٤٠١</span>-<span class=\"hlight\" dir=\"rtl\">٤٠٧</span>)، شرف الدوله طغان بن علی (<span class=\"hlight\" dir=\"rtl\">٤٠٣</span>-<span class=\"hlight\" dir=\"rtl\">٤٠٨</span>)، ابوالمنتصر ارسلانخان اول بن علی، یوسف خضرخان اول (وفاتش در <span class=\"hlight\" dir=\"rtl\">٤٢٣</span>)، شرف الدوله ابوشجاع ارسلانخان ثانی (حدود <span class=\"hlight\" dir=\"rtl\">٤٢١</span>-<span class=\"hlight\" dir=\"rtl\">٤٢٤</span>)، محمود اول بغراخان (حدود <span class=\"hlight\" dir=\"rtl\">٤٢٥</span>-<span class=\"hlight\" dir=\"rtl\">٤٣٥</span>).<br />در سمت مغرب : جغراتکین ابوالمظفر عمادالدوله ابراهیم طفغاج بن نصر (حدود <span class=\"hlight\" dir=\"rtl\">٤٤٠</span>-<span class=\"hlight\" dir=\"rtl\">٤٦٠</span>)، شمس الملوک نصر ثانی بن طفغاج (وفاتش در <span class=\"hlight\" dir=\"rtl\">٤٧٢</span>)، خضرخان بن طفغاج، احمدخان ثانی بن خضر (وفاتش در <span class=\"hlight\" dir=\"rtl\">٤٨٨</span>)، محمودخان ثانی (وفاتش میان <span class=\"hlight\" dir=\"rtl\">٤٩٠</span>-<span class=\"hlight\" dir=\"rtl\">٤٩٥</span>)، خضرخان ثانی بن عمربن احمد (وفاتش در <span class=\"hlight\" dir=\"rtl\">٤٩٥</span>)، محمود ارسلانخان ثالث بن سلیمان، ابوالمعالی حسن تگین بن علی، رکن الدوله محمودخان ثالث بن ارسلان، قلج طفغاج خان بن محمد (حدود <span class=\"hlight\" dir=\"rtl\">٥٥٨</span>)، جلال الدین علی گورکان بن حسن تگین .<br />در سمت مشرق : طغرل خان بن یوسف خضرخان (<span class=\"hlight\" dir=\"rtl\">٤٣٩</span>-<span class=\"hlight\" dir=\"rtl\">٤٥٥</span>)، طغرل تگین بن طغرل (<span class=\"hlight\" dir=\"rtl\">٤٥٥</span>)، هارون بغراخان بن یوسف خضرخان (<span class=\"hlight\" dir=\"rtl\">٤٥٥</span>؟-<span class=\"hlight\" dir=\"rtl\">٤٩٦</span>)، نورالدوله احمدبن ارسلان .<br /></font></div>'),
(1963, 'آل الیاس', '<span class=\"hlight\">آل الیاس .</span> <font color=\"DarkGreen\"><b>[ ل ِ اِل ْ ]</font></b> (اِخ ) نام سلسله ای از فرمانروایان کرمان، و سرسلسله ٔ آنان ابوعلی محمدبن الیاس بن الیسع سمرقندی از ممالیک نصربن احمد سامانیست . در <span class=\"hlight\" dir=\"rtl\">٣١٧</span> هَ .ق . بر کرمان استیلا یافت . در <span class=\"hlight\" dir=\"rtl\">٣٥٧</span> عضدالدوله ٔ دیلمی کرمان را از الیسع آخرین ِ افراد این سلسله انتزاع کرد و دولت آل الیاس سپری شد.<br /></font></div>'),
(1964, 'آل امیر', '<span class=\"hlight\">آل امیر.</span> <font color=\"DarkGreen\"><b>[ ل ِ اَ ]</font></b> (اِخ ) نام تیره ای از طایفه ٔ بکش از قبایل ممسنی .<br /></font></div>'),
(1965, 'آل باوند', '<span class=\"hlight\">آل باوند.</span> <font color=\"DarkGreen\"><b>[ ل ِ وَ ]</font></b> (اِخ ) باوندیه . سلسله ای از ملوک طبرستان که آخرین آنان به نام اسپهبد رستم بن شهریار به سال <span class=\"hlight\" dir=\"rtl\">٤١٦</span> هَ .ق . در جنگ با علاءالدوله مقتول گشت و دولت این طبقه سپری گردید. و آنان نسب خویش را به کیوس بن قباد برادر اکبر انوشیروان (که بحکم پدر والی مازندران گردید) می پیوسته اند.<br /></font></div>'),
(1966, 'آل بتول', '<span class=\"hlight\">آل بتول .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب َ ]</font></b> (اِخ ) آل رسول از اولاد فاطمه علیهاالسلام <span class=\"hlight\">:</span> <br />آن بحجت چراغ دین رسول <br />وین بنسبت جمال آل بتول .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(1967, 'آل برمک', '<span class=\"hlight\">آل برمک .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب َ م َ ]</font></b> (اِخ ) برامکه . خانواده ٔ جلیل و کریم ایرانی که در آغازعصر عباسی متصدی کارهای مهم دولت شده و درجات و منصبهای عالی از امارت و وزارت یافته اند. نسبت این خانواده به برمک نام است که گویند در بلخ میزیسته و ریاست بتکده ٔ نوبهار و حکومت بلخ داشته و در اواخر عصر اموی اسلام آورده است، و برخی گفته اند که برمک لقب کلیه ٔرؤسای بتکده ٔ نوبهار بوده و آخرین برمک که خاندان برامکه بدو منسوب است نامش جعفر بوده است . مشاهیر این خانواده خالدبن برمک (<span class=\"hlight\" dir=\"rtl\">١٦٣</span> یا <span class=\"hlight\" dir=\"rtl\">١٦٦</span> هَ .ق .) و پسرش یحیی بن خالد (متوفی <span class=\"hlight\" dir=\"rtl\">١٩٠</span>) و دو پسر یحیی، فضل متولد <span class=\"hlight\" dir=\"rtl\">١٤٧</span> و متوفی <span class=\"hlight\" dir=\"rtl\">١٩٣</span> و جعفر متولد <span class=\"hlight\" dir=\"rtl\">١٤٩</span> و متوفی <span class=\"hlight\" dir=\"rtl\">١٨٧</span> که همگی بجود و کرم و علم و ادب و انواع مکارم و فضائل اخلاق معروف و موصوف بوده اند. خالد از امرای سپاه ابومسلم خراسانی بود که پس از زوال ملک بنی امیه بخدمت ابوالعباس سفاح پیوست و سمت وزارت یافت . یحیی بن خالد که مربی و حامی هارون الرشید بود در زمان هارون قدرت و نفوذی عظیم داشت و استقرار و عظمت دولت عباسی در آغاز امر نتیجه ٔ حسن تدبیر و لطف سیاست وی و دو پسرش فضل و جعفر بوده است . هارون الرشید بر شوکت و عظمت این خانواده رشک برد و در سال <span class=\"hlight\" dir=\"rtl\">١٨٧</span> بشرحی که مشهور است آن خانواده ٔ نبیل را قلع و قمع کرد. و ابوالفرج عبدالرحمن بن علی بن جوزی متوفی <span class=\"hlight\" dir=\"rtl\">٥٩٧</span> هَ .ق . را در شرح حال این خاندان تاریخی مستقل بوده است به نام اخبارالبرامکه .<br /></font></div>'),
(1968, 'آل برهان', '<span class=\"hlight\">آل برهان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب ُ]</font></b> (اِخ ) نام خاندانی بزرگ از بخارا، معاصر سلاجقه و خوارزمشاهیان که بجود و کرم و بزرگواری معروف و ریاست حنفیان بخارا و ماوراءالنهر اباً عن جد بعهده ٔ ایشان موکول بود و بعض ایشان از ملوک بخارا محسوب میشوند و در اواخر دولت قراخطائیان در ماوراءالنهر پادشاهان این خاندان باجگذار قراخطائیان بوده اند. (نقل به اختصار از حواشی حضرت علامه ٔ قزوینی بر چهارمقاله ). نخستین کسی از این خانواده که بریاست و دانشمندی اشتهار یافت امام برهان الدین عبدالعزیزبن مازه است که دراوایل قرن ششم هجری میزیسته، و این خانواده را بنسبت او آل برهان و بنسبت پدرش بنی مازه خوانده اند. آل برهان یا بنی مازه تا اوایل قرن هشتم هجری معروف بوده اند. سیف الدین از آل برهان ممدوح سوزنی است <span class=\"hlight\">:</span> <br />آل برهان گزیده ٔ حقند<br />باد برهان حق درو پیدا<br />در شهنشاه و آل برهان باد<br />سوزنی پیر مستجاب دعا.<br /></font></div>'),
(1969, 'آل بوبکره', '<span class=\"hlight\">آل بوبکره .</span> <font color=\"DarkGreen\"><b>[ ل ِ بو ب َ رَ ]</font></b>(اِخ ) بوبکره مولای پیغامبر علیه السلام بود و معاویه احفاد او را به قریش ملحق کرده بود و مهدی عباسی ایشان را نسبت اندر مولائی درست کرد <font color=\"DarkGreen\"><b>[ و بفرمود تا ببصره آل زیاد و آل بوبکره که فرزندانشان را در قریش درست بکرده بودند بگردانند چنانکه بود ]</font></b>. (مجمل التواریخ ).<br /></font></div>'),
(1970, 'آل بوسفیان', '<span class=\"hlight\">آل بوسفیان .</span> <font color=\"DarkGreen\"><b>[ ل ِ س ُف ْ ]</font></b> (اِخ ) رجوع به آل ابوسفیان شود <span class=\"hlight\">:</span> <br />وآن دگر بغض آل بوسفیان <br />که از ایشان بدو رسید زیان .<br /> <font color=\"Red\">سنائی .</font><br />بود آن زن ز آل بوسفیان <br />منعم و مالدار و خوب و جوان .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(1971, 'آل بویه', '<span class=\"hlight\">آل بویه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ی َ ]</font></b> (اِخ ) خانواده ٔ ایرانی نژاد از اولاد بویه نام دیلمی که از <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> تا <span class=\"hlight\" dir=\"rtl\">٤٤٨</span> هَ .ق .در ایران جنوبی و عراق فرمانروائی به استقلال داشته اند. آل بویه را نظر بدیلمی بودن، دیالمه نیز خوانده اند. مؤسس سلطنت دیالمه علی عمادالدوله از امرای مرداویج بن زیار و حسن رکن الدوله و احمد معزالدوله پسران بویه ٔ دیلمی بوده اند. این سه پسر ولایات بدست آورده رامیان خود تقسیم کردند و چهارده تن از اولاد و اعقاب آنها هرکدام در قسمتی از مملکت اسلاف خود حکومت مستقل داشته و به مناسبت قلمرو حکمرانی خود بدیالمه ٔ فارس و دیالمه ٔ عراق و اهواز و کرمان و دیالمه ٔ ری و همدان و اصفهان و دیالمه ٔ کردستان موسوم شده اند. انقراض دیالمه بر دست آل کاکویه و غزنویان و سلجوقیان بوده است و آنان را بُوَیْهیّون نیز نامند. و ابواسحاق ابراهیم بن هلال صابی متوفی به سال <span class=\"hlight\" dir=\"rtl\">٣٨٦</span> را تاریخی است از این دودمان به نام تاجی، و نیز جمال الدین علی بن یوسف قفطی وزیر، تاریخی دیگر در شرح حال آنان کرده است .<br /></font></div>'),
(1972, 'آل تبان', '<span class=\"hlight\">آل تبان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ت َب ْ با ]</font></b> (اِخ ) تبانیان . نام خانواده ای ازنژاد امام ابوالعباس تبانی، شاگرد ابویوسف قاضی معاصر هارون الرشید عباسی است . از این خانواده فقها و دانشمندان نامی برخاسته و در عهد سامانیان و غزنویان در ماوراءالنهر و خراسان و غزنه متصدی قضا و فتوی و تدریس بوده و بر حنفیان ریاست داشته اند. از مشاهیر این دانشمندان ابونصر تبانی معاصر سامانیان و ابوصالح و ابوصادق و ابوطاهر تبانی معاصر غزنویان بوده اند.<br /></font></div>'),
(1973, 'آل تمغا', '<span class=\"hlight\">آل تمغا.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ترکی، اِ مرکب ) (از: آل فارسی، سرخ + تمغا، خاتم ) مُهر با مرکّب سرخ که سلاطین مغول بر یرلیغها می نهاده اند. و آن را «آل » تنها نیزمیگفته اند. <BR><font color=\"Blue\">◄</font> فرمان زرنشان <span class=\"hlight\">:</span> <br />نبشتند فرمان نهادند آل <br />که آن است نقش خجسته بفال .<br /> <font color=\"Red\">زجاجی .</font><br />ز بیم خاتم القاب تو نهادستند<br />بحکم یرلیغ از آل ایلخان یاقوت .<br /> <font color=\"Red\">نزاری قهستانی .</font><br />بر مثال عید گردون از شفق چون آل زد<br />شکل طغری بین که بر بالای آل آمد پدید.<br /> <font color=\"Red\">سلمان ساوجی .</font><br />خون بدخواهان او آل است بر حکم اجل <br />آنچنان حکم آل تمغا برنتابد بیش از این .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />بهر عزل عامل منسوب (کذا) و نصب نامیه <br />آل تمغائیست از سلطان دریابار گل .<br /> <font color=\"Red\">کاتبی .</font><br />روز محشر سرخ رو چون لاله برخیزد ز خاک <br />آل تمغای شهادت هرکه دارد بر جبین .<br /> <font color=\"Red\">صائب .</font><br />نه هر تن لایق تشریف شاهی است <br />شهادت آل تمغای الهی است .<br /> <font color=\"Red\">صائب .</font><br />و رجوع به آل طمغی ̍ و اَل طمغی ̍ شود.<br /></font></div>'),
(1974, 'آل جفنه', '<span class=\"hlight\">آل جفنه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ج َ ن َ ]</font></b> (اِخ ) شعبه ای از قبیله ٔ ازد از اولاد جفنةبن عمرو مُزَیقیاء که در حدود شام از دست قیاصره دولتی تشکیل داده اند که تا ظهور و غلبه ٔ اسلام باقی بوده، و امرای این دولت را غساسنه و ملوک غسان نیز گفته اند. و آنان از یمن بوده اند. در شماره ٔ ملوک این سلسله و اسامی و مدت فرمانروائی ایشان اختلاف بسیار است و مورد اتفاق اینکه آخرین ایشان جبلةبن الایهم بوده است که در زمان خلیفه ٔ دوم اسلام آورد و بعد مرتد شد. و رجوع به جفنه شود.<br /></font></div>'),
(1975, 'آل جلایر', '<span class=\"hlight\">آل جلایر.</span> <font color=\"DarkGreen\"><b>[ ل ِ ج َ ی ِ ]</font></b> (اِخ ) ایلکانیان از <span class=\"hlight\" dir=\"rtl\">٧٤٠</span>تا <span class=\"hlight\" dir=\"rtl\">٨٣٦</span> هَ .ق . در عراق فرمانروای مستقل بوده، و بعض آنها آذربایجان و موصل و دیاربکر را نیز در تصرف داشته اند. مؤسس این سلسله حسن بزرگ از رؤسای ایل جلایر، و شماره ٔ ایشان شش تن و مقر حکمرانی آنان بغداد بوده است . این سلسله را امرای قراقویونلو برانداختند و آخرین فرمانروای آنها موسوم به شاه ولد بوده است .<br />امیر شیخ حسن بزرگ بن امیر حسین بن آقبوقابن ایلکانی (<span class=\"hlight\" dir=\"rtl\">٧٤٠</span>-<span class=\"hlight\" dir=\"rtl\">٧٥٧</span>)، سلطان شیخ اویس بن شیخ حسن (<span class=\"hlight\" dir=\"rtl\">٧٥٧</span>-<span class=\"hlight\" dir=\"rtl\">٧٧٦</span>)، سلطان حسین بن شیخ اویس (<span class=\"hlight\" dir=\"rtl\">٧٧٦</span>-<span class=\"hlight\" dir=\"rtl\">٧٨٤</span>)، سلطان احمدبن شیخ اویس (<span class=\"hlight\" dir=\"rtl\">٧٨٤</span>-<span class=\"hlight\" dir=\"rtl\">٨١٣</span>)، شاه ولدبن شیخ علی بن شیخ اویس (<span class=\"hlight\" dir=\"rtl\">٨١٣</span>-<span class=\"hlight\" dir=\"rtl\">٨١٤</span>)، سلطان اویس بن شاه ولد (<span class=\"hlight\" dir=\"rtl\">٨١٤</span>-<span class=\"hlight\" dir=\"rtl\">٨٢٤</span>)، سلطان محمودبن شاه ولد (<span class=\"hlight\" dir=\"rtl\">٨٢٤</span>-<span class=\"hlight\" dir=\"rtl\">٨٢٧</span>)، سلطان حسین بن علاءالدولةبن سلطان احمد (<span class=\"hlight\" dir=\"rtl\">٨٢٧</span>-<span class=\"hlight\" dir=\"rtl\">٨٣٦</span>)، و امیر اصفهان پسر قرایوسف او را بکشت و سلسله ٔ آل جلایر منقرض گردید. و بطوری که محمّد قزوینی مرقوم داشته اند ایلخانیان با خاء معجمه است .<br /></font></div>'),
(1976, 'آل حسنویه', '<span class=\"hlight\">آل حسنویه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ح َ س َ ی َ ]</font></b> (اِخ ) حسنویه، پسر حسین برزگانی، از سران یکی از قبایل کرد، در نیمه ٔ اول مائه ٔچهارم هجری قسمت عمده ٔ کردستان و بلاد دینور و همدان و نهاوند و قلعه ٔ سرماج را بتصرف خود آورد. پس از مرگ او عضدالدوله ٔ بویهی متصرفات او را مسخر کرد، لکن بدر پسر حسنویه را از جانب خویش در همان ناحیت حکومت داد. بدر بر اعتبار و اقتدار خود رفته رفته بیفزود تا آنجا که خلیفه باو لقب ناصرالدوله داد. پس از بدریکی از احفاد او ظاهرنام بجای او نشست لکن یک سال بیشتر در این مقام نماند و شمس الدوله ٔ دیلمی او را ازمقر خود براند و کمی پس از آن زمان ظاهر کشته شد.<br />حسنویه پسر حسین مؤسس این سلسله (<span class=\"hlight\" dir=\"rtl\">٣٤٨</span>-<span class=\"hlight\" dir=\"rtl\">٣٦٩</span>هَ .ق .)، ناصرالدوله بدربن حسنویه مکنی به ابوالنجم (<span class=\"hlight\" dir=\"rtl\">٣٦٩</span>-<span class=\"hlight\" dir=\"rtl\">٤٠٥</span>)، ظاهر هلال بن بدر (<span class=\"hlight\" dir=\"rtl\">٤٠٥</span>-<span class=\"hlight\" dir=\"rtl\">٤٠٦</span>).<br /></font></div>'),
(1977, 'آل حق', '<span class=\"hlight\">آل حق .</span> <font color=\"DarkGreen\"><b>[ ل ِ ح َق ق ]</font></b> (ترکیب اضافی، اِ مرکب ) اهل اﷲ. اولیأاﷲ. اولیاء <span class=\"hlight\">:</span> <br />آنچنان پر گشته از اجلال حق <br />کاندر او هم ره نیابد آل حق .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(1978, 'آل حمدان', '<span class=\"hlight\">آل حمدان .</span><font color=\"DarkGreen\"><b>[ ل ِ ح َ ]</font></b> (اِخ ) حکام حلب که سرسلسله ٔ آنان عبداﷲبن حمدان بن حارث بن نعمان از بنی ربیعه بوده و در عهد مکتفی در <span class=\"hlight\" dir=\"rtl\">٢٩٣</span> هَ .ق . حکومت حلب یافته و <span class=\"hlight\" dir=\"rtl\">٢٥</span> سال حکم رانده و تا <span class=\"hlight\" dir=\"rtl\">٣٩١</span> اخلاف او در حلب فرمانروائی داشته اند.<br /></font></div>'),
(1979, 'آل خاقان', '<span class=\"hlight\">آل خاقان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) رجوع به آل افراسیاب شود.<br /></font></div>'),
(1980, 'آل خورشیدی', '<span class=\"hlight\">آل خورشیدی .</span> <font color=\"DarkGreen\"><b>[ ل ِ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ]</font></b> (اِخ ) تیره ای از جانکی گرم سیر چهارلنگ بختیاری .<br /></font></div>'),
(1981, 'آل داود', '<span class=\"hlight\">آل داود.</span> <font color=\"DarkGreen\"><b>[ ل ِ وو ]</font></b> (اِخ ) فرزندان داود نبی، سلیمان و اولاد او <span class=\"hlight\">:</span> اِعملوا آل داود شکراً... (قرآن <span class=\"hlight\" dir=\"rtl\">١٣/٣٤</span>). <BR><font color=\"Blue\">◄</font> تیره ای از چهارلنگ بختیاری از شعبه ٔ محمود صالح .<br /></font></div>'),
(1982, 'آل رسول', '<span class=\"hlight\">آل رسول .</span> <font color=\"DarkGreen\"><b>[ ل ِ رَ ]</font></b> (اِخ ) اولاد و احفاد او صلوات اﷲعلیه از نسل علی و فاطمه سلام اﷲعلیهما <span class=\"hlight\">:</span> <br />خاصه بر ظالمان آل رسول <br />آنکه دارند جای فضل فضول .<br /> <font color=\"Red\">سنائی .</font><br />بحق ِ مصطفی و آل رسول <br />که کنی این سخن ز بنده قبول .<br /> <font color=\"Red\">سنائی .</font><br />اگر طاعتم ردکنی یا قبول <br />من و دست و دامان آل رسول .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(1983, 'آل زیاد', '<span class=\"hlight\">آل زیاد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) اولاد زیادبن ابیه که معاویةبن ابی سفیان او را بپدر خویش ابوسفیان ملحق ساخت، و در دواوین و انساب، او و فرزندانش را بقریش منسوب کردند. و عبیداﷲ زیاد، حسین بن علی علیه السلام را بامر یزید در کربلا بشهادت رسانید <span class=\"hlight\">:</span> <br />کربلا چون مقام و منزل ساخت <br />تا که آل زیاد بر وی تاخت .<br /> <font color=\"Red\">سنائی .</font><br />کرده آل زیاد و شمر لعین <br />ابتذال چنین بتر بر دین .<br /> <font color=\"Red\">سنائی .</font><br />آل مروان و آل سفله زیاد<br />که نرفتند جز براه عناد.<br /> <font color=\"Red\">سنائی .</font><br />و مهدی عباسی در <span class=\"hlight\" dir=\"rtl\">١٥٩</span> هَ .ق . نسب آنان رابگردانید و بمردی موسوم به عبید رومی از ثقیف نسب کرد.<br /></font></div>'),
(1984, 'آل زیار', '<span class=\"hlight\">آل زیار.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) سلسله ای از ملوک و امرای ایرانی نژاد در گرگان، از سال <span class=\"hlight\" dir=\"rtl\">٣١٦</span> تا <span class=\"hlight\" dir=\"rtl\">٤٣٤</span> هَ .ق . مؤسس این سلسله مرداویج (مرداویز)بن زیار که خود را از اعقاب پادشاهان قدیم میشمرد در جرجان علم استقلال برافراشت و اصفهان و همدان را نیز بحیطه ٔ تصرف آورد و در سالهای <span class=\"hlight\" dir=\"rtl\">٣١٦</span> تا<span class=\"hlight\" dir=\"rtl\">٣١٩</span> ایران غربی را تا حوالی حلوان مسخر کرد. آل بویه نخست در خدمت او بودند و علی بن بویه از دست او حکومت کرج داشت . مرداویج صورةً فرمان خلفای عباسی را گردن نهاده بود و برادر او وشمگیربن زیار نسبت به سامانیان نیز اظهار انقیاد میکرد. پس از آنکه آل بویه به سال <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> استقلال یافتند اقتدار زیاریان بجرجان و طبرستان محدود شد، و این سلسله را غزنویان منقرض کردند.<br />مردوایج بن زیار (<span class=\"hlight\" dir=\"rtl\">٣١٦</span>-<span class=\"hlight\" dir=\"rtl\">٣٢٣</span>)، ابومنصوربن وشمگیر ملقب بظهیرالدوله (<span class=\"hlight\" dir=\"rtl\">٣٢٣</span>-<span class=\"hlight\" dir=\"rtl\">٣٥٦</span>)، بیستون (<span class=\"hlight\" dir=\"rtl\">٣٥٦</span>-<span class=\"hlight\" dir=\"rtl\">٣٦٦</span>)، شمس المعالی قابوس معروفترین ِ افراد این سلسله (<span class=\"hlight\" dir=\"rtl\">٣٦٦</span>-<span class=\"hlight\" dir=\"rtl\">٤٠٣</span>)، انوشیروان (دارا؟) (<span class=\"hlight\" dir=\"rtl\">٤٢٠</span>-<span class=\"hlight\" dir=\"rtl\">٤٣٤</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(1985, 'آل ساسان', '<span class=\"hlight\">آل ساسان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ساسانیان . بنی ساسان . نام سلسله ای از پادشاهان ایران پس از اشکانیان منسوب به اسم جدّ مؤسس این پادشاهی، اردشیر بابکان . اردشیر بابک یا بابکان از احفاد موبدی موسوم بساسان بوده و پدر او پاپک درمعبدی به استخر ریاست داشته . نهضتی که اردشیر پیشواو قائد آن گردید برای برچیدن اوضاع ملوک الطوایف و تجدید عظمت و شوکت و رسوم دین باستانی ایران یعنی رسانیدن مملکت بپایه ٔ بزرگواری و مجد دولت هخامنشی و هدم و برانداختن آثار غلبه ٔ اسکندر بود. گذشته از صعوبت و عسرتی که پیشرفت این منظور در داخله ٔ کشور داشت روم شرقی بمغرب و قبائل ترک بشمال و شرق دو عائق بزرگ بودند. اردشیر و اخلاف او بر جمله ٔ این موانع فائق آمدند و بتوحید و بسطت و تحکیم بنیاد ملک کامروا گشتند و از <span class=\"hlight\" dir=\"rtl\">٢٢٦</span> تا <span class=\"hlight\" dir=\"rtl\">٦٣٢</span> م . یعنی چهارصد سال و اندی سلطنت راندند. و عاقبت بر حسب ناموس طبیعت تاریخ، رو بانحطاط نهاده و مغلوب عرب گشته منقرض شدند <span class=\"hlight\">:</span> <br />از آن چندان نعیم این جهانی <br />که ماند از آل ساسان وآل سامان <br />ثنای رودکی مانده ست و مدحت <br />نوای باربد مانده ست و دستان .<br /> <font color=\"Red\">مجلّدی گرگانی .</font><br />اردشیر اول (<span class=\"hlight\" dir=\"rtl\">٢٢٦</span>)، شاپور اول (<span class=\"hlight\" dir=\"rtl\">٢٣٨</span>)، هرمز اول (<span class=\"hlight\" dir=\"rtl\">٢٧١</span>)، بهرام اول (<span class=\"hlight\" dir=\"rtl\">٢٧٢</span>)، بهرام دوم (<span class=\"hlight\" dir=\"rtl\">٢٧٦</span>)، بهرام سوم (<span class=\"hlight\" dir=\"rtl\">٢٩٣</span>)، نرسی (<span class=\"hlight\" dir=\"rtl\">٢٩٤</span>)، هرمز دوم (<span class=\"hlight\" dir=\"rtl\">٣٠٣</span>)، شاپور دوم (<span class=\"hlight\" dir=\"rtl\">٣١٠</span>)، اردشیر دوم (<span class=\"hlight\" dir=\"rtl\">٣٨١</span>)، شاپور سوم (<span class=\"hlight\" dir=\"rtl\">٣٨٥</span>)، بهرام چهارم ملقب بکرمانشاه (<span class=\"hlight\" dir=\"rtl\">٣٨٩</span>)، یزدگرد اول (<span class=\"hlight\" dir=\"rtl\">٤٠٤</span>)، بهرام پنجم (<span class=\"hlight\" dir=\"rtl\">٤٢٠</span>)، یزدگرد دوم (<span class=\"hlight\" dir=\"rtl\">٤٤٠</span>)، هرمز سوم (<span class=\"hlight\" dir=\"rtl\">٤٥٦</span>)، فیروز (<span class=\"hlight\" dir=\"rtl\">٤٥٨</span>)، بلاش (<span class=\"hlight\" dir=\"rtl\">٤٨٤</span>)، قباد (<span class=\"hlight\" dir=\"rtl\">٤٨٨</span>)، خسرو انوشیروان (<span class=\"hlight\" dir=\"rtl\">٥٣١</span>)، هرمز سوم (<span class=\"hlight\" dir=\"rtl\">٥٧٩</span>)، خسروپرویز (<span class=\"hlight\" dir=\"rtl\">٥٩٠</span>)، شیرویه (<span class=\"hlight\" dir=\"rtl\">٦٢٨</span>)، اردشیر دوم (<span class=\"hlight\" dir=\"rtl\">٦٢٩</span>)، شهریار (<span class=\"hlight\" dir=\"rtl\">٦٢٩</span>)، پوراندخت (<span class=\"hlight\" dir=\"rtl\">٦٢٩</span>)، آزرمیدخت (<span class=\"hlight\" dir=\"rtl\">٦٣٢</span>)، خسرو (<span class=\"hlight\" dir=\"rtl\">٦٣٢</span>)، فرخ زاد (<span class=\"hlight\" dir=\"rtl\">٦٣٢</span>)، یزدگرد سوم (<span class=\"hlight\" dir=\"rtl\">٦٣٢</span>)، و یزدگرد سوم در حمله ٔ عرب مغلوب و کشته شد و ساسانیان به سیگنانفو نزد امپراطور چین رفته و از او مدد خواستند واو بفیروز پسر یزدگرد سپاهی داد تا بایران بازگشت ودر جنگی که خود فیروز سردار بود مقتول گردید.<br /></font></div>'),
(1986, 'آل ساعدی', '<span class=\"hlight\">آل ساعدی .</span> <font color=\"DarkGreen\"><b>[ ل ِع ِ ]</font></b> (اِخ ) نام طایفه ای از عرب جباره، ساکن فارس .<br /></font></div>'),
(1987, 'آل سامان', '<span class=\"hlight\">آل سامان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) نام سلسله ای از سلاطین اسلامی ایران منسوب به سامان نامی، از نجبا و بزرگان بلخ که نسب او ببهرام چوبینه می پیوسته است <span class=\"hlight\">:</span> <br />از آن چندان نعیم این جهانی <br />که ماند از آل ساسان وآل سامان ؟...<br /> <font color=\"Red\">مجلّدی گرگانی .</font><br />هیچکس از آل سامان باسیاست تر از وی نبود. (تاریخ بخارای نرشخی ).<br />سامان در خدمت اسدبن عبداﷲ حکمران خراسان دین بهی را ترک گفته مسلمانی پذیرفت . فرزند او اسد صاحب چهار پسر موسوم بالیاس و یحیی و احمد و نوح بود. مأمون خلیفه در <span class=\"hlight\" dir=\"rtl\">٢٠٤</span> هَ .ق . الیاس را حکومت هرات و یحیی را امارت چاچ و احمد را فرمانروائی فرغانه و نوح را ولایت سمرقند داد. نصر پسر احمد پس از مرگ پدر از دست مأمون خلیفه بسمرقند فرمانروائی یافت و در <span class=\"hlight\" dir=\"rtl\">٢٧٥</span> اسماعیل پسر کوچک احمد برادر خویش نصر را خلع کرد و بجای او نشست و بامر معتضد خلیفه بجنگ صفّاریان پرداخت و سلطنت آنان را برانداخت . خلیفه بپاس این خدمت فرمانروائی ماوراءالنهر و خراسان و طبرستان را بدو سپرد و او پس از استقرار، تمام ترکستان را فتح و تسخیر کرد. جانشین او پسرش احمد است و مدت امارت او پنج سال و چهار ماه بود و پس از او حکومت به نصر ثانی انتقال یافت و او سی سال و سه ماه حکم راند، و بعد پسرش نوح بمقام پدر رسید و حکمرانی او دوازده سال کشید و خلف او عبدالملک بن نوح است و او هفت سال و شش ماه فرمان راند. سپس منصور اول بن نوح بجای او نشست و پادشاهی او یازده سال دوام یافت و متعاقب او نوح بن منصور بسلطنت رسید و بیش از یک سال و هفت ماه نپائید و پس از او منصور ثانی پسر نوح ثانی بجای پدر قرار گرفت و قریب دو سال سلطنت راند و از پی او عبدالملک ثانی بن نوح ثانی برادر منصور مستقرّ گشت و هشت ماه ببود و بزمان او سلسله ٔ سامانی در سال <span class=\"hlight\" dir=\"rtl\">٣٨٩</span> هَ .ق . منقرض گردید و ابوابراهیم منتصربن نوح تا <span class=\"hlight\" dir=\"rtl\">٣٩٥</span> در طلب ملک از دست رفته کوشش و جنگ میکرد. این سلسله را امرای ایلک خانی و محمود غزنوی منقرض کردند.<br /></font></div>'),
(1988, 'آل سلجوق', '<span class=\"hlight\">آل سلجوق .</span> <font color=\"DarkGreen\"><b>[ ل ِ س َ]</font></b> (اِخ ) در دوره ٔ ضعف و انحطاط عباسیان، سلسله ای ازترکمانان بر ممالک اسلامی تسلط یافتند و آن را تحت حکومت درآوردند. سلاجقه به ایران و الجزیره و شام و آسیای صغیر هجوم برده و سلسله هائی را که در این نواحی فرمانروائی داشتند برانداخته و آسیای اسلامی را از حدغربی افغانستان تا ساحل بحرالروم متصرف شدند. سلاجقه فرزندان سلجوق بن تقاق از رؤسای ترکمانند که در خدمت یکی از خانان ترکستان میزیسته و از دشت قرقیز با تمام قبیله ٔ خود بطرف جَنْد و از آنجا ببخارا کوچ کرده و در آن سرزمین ساکن شده قبول اسلام کرده اند. سلجوق و پسران او در جنگهائی که مابین سامانیان و امرای ایلک خانیه و سلطان محمود غزنوی اتفاق افتاد شرکت می جستند و بتدریج قدرت آنان بجائی رسید که طغرل بیک و برادرش چغری بیک بریاست قبیله ٔ خود بخراسان هجوم بردند وغزنویان را از آنجا رانده جانشین ایشان شدند و در سال <span class=\"hlight\" dir=\"rtl\">٤٢٩</span> هَ .ق . در مرو خطبه به نام چغری بیک داود خوانده و او را سلطان السلاطین نامیدند و همین مراسم را نیز در نیشابور به نام برادرش طغرل بیک بجای آوردند و بتدریج بلخ و جرجان و طبرستان و خوارزم بممالک سلجوقی افزوده شد و بزودی جبل و همدان و دینور و حلوان و ری و اصفهان بدان ضمیمه گردید و طغرل بیک در سال <span class=\"hlight\" dir=\"rtl\">٤٤٧</span> به بغداد ورود کرد و نام او با لقب سلطانی در دارالخلافه بر منابر خوانده شد. و این خاندان را به نام سلاجقه و سلجوقیه و سلجوقیان نیز خوانند. (نقل به اختصاراز طبقات سلاطین اسلام استانلی لین پول ). بعد از ملکشاه میان فرزندان او نفاق و خلاف افتاد و برخی از امرای سلجوقی که در نواحی مُلک حکمران بودند فرصت را غنیمت شمرده سر از اطاعت جانشینان ملکشاه پیچیدند و در قلمرو حکمرانی خود سلطنت یا امارتی مستقل تشکیل کردندو بدین نهج چندین سلسله ملوک سلجوقی بوجود آمد که معروفترین آنها سلاجقه ٔ روم و شام و کرمان است و سلسله ٔ اصلی را در مقابل این سلسله های فرعی سلاجقه ٔ بزرگ نامند و سلطنت این دودمان از <span class=\"hlight\" dir=\"rtl\">٤٢٩</span> تا <span class=\"hlight\" dir=\"rtl\">٥٥٢</span> دوام یافت .<br />رکن الدین ابوطالب طغرل بیک (<span class=\"hlight\" dir=\"rtl\">٤٢٩</span>-<span class=\"hlight\" dir=\"rtl\">٤٥٥</span>)، عضدالدین ابوشجاع آلب ارسلان (<span class=\"hlight\" dir=\"rtl\">٤٥٥</span>-<span class=\"hlight\" dir=\"rtl\">٤٦٥</span>)، جلال الدین ابوالفتح ملکشاه (<span class=\"hlight\" dir=\"rtl\">٤٦٥</span>-<span class=\"hlight\" dir=\"rtl\">٤٨٥</span>)، ناصرالدین محمود (<span class=\"hlight\" dir=\"rtl\">٤٨٥</span>-<span class=\"hlight\" dir=\"rtl\">٤٨٧</span>)، رکن الدین ابوالمظفر برکیارق (<span class=\"hlight\" dir=\"rtl\">٤٨٧</span>-<span class=\"hlight\" dir=\"rtl\">٤٩٨</span>)، ملکشاه دوم (<span class=\"hlight\" dir=\"rtl\">٤٩٨</span>)، غیاث الدین ابوشجاع محمد (<span class=\"hlight\" dir=\"rtl\">٤٩٨</span>)، معزالدین ابوالحارث سنجر (<span class=\"hlight\" dir=\"rtl\">٥١١</span>-<span class=\"hlight\" dir=\"rtl\">٥٥٢</span>). این شعبه را خوارزمشاهیان منقرض کردند. (از طبقات سلاطین اسلامی استانلی لین پول ).<br />سلاجقه ٔ روم : از سال <span class=\"hlight\" dir=\"rtl\">٤٧٠</span> تا <span class=\"hlight\" dir=\"rtl\">٧٠٠</span> هَ .ق . در آسیای صغیر فرمانروایی به استقلال داشته اند. مؤسس این سلسله سلیمان بن قتلمش و آخرین ایشان علاءالدین کیقباد ثانی و شماره ٔ آنان <span class=\"hlight\" dir=\"rtl\">١٧</span> تن، و انقراضشان به دست مغول و ترکان عثمانی بوده است .<br />سلاجقه ٔ شام : سلسله ای از آل سلجوق که از <span class=\"hlight\" dir=\"rtl\">٤٨٧</span> تا سال <span class=\"hlight\" dir=\"rtl\">٥١١</span> در شام فرمانروای مستقل بوده اند. مؤسس این سلسله تتش بن ارسلان و آخرین آنان سلطان شاه بن رضوان و عده ٔ آنها پنج تن، و انقراضشان به دست اتابکان بوری و امرای ارتقی بوده است .<br />سلاجقه ٔ عراق و کردستان : نُه تن اخیر از سلاجقه ٔ اصلی که از سال <span class=\"hlight\" dir=\"rtl\">٥١١</span> تا <span class=\"hlight\" dir=\"rtl\">٥٩٠</span> در عراق و کردستان فرمانروایی به استقلال داشته اند. نخستین ایشان مغیث الدین محمودبن محمد ملکشاه و آخرین طغرل ثانی است که نسبت بسلاجقه ٔ بزرگ طغرل ثالث شمرده میشود. انقراض این سلسله خوارزمشاهیان بوده است .<br />سلاجقه ٔ کرمان : سلسله ای از آل سلجوق که از سال <span class=\"hlight\" dir=\"rtl\">٤٢٣</span> تا <span class=\"hlight\" dir=\"rtl\">٥٨٣</span> در کرمان به استقلال فرمانروایی داشته اند.مؤسس این سلسله عمادالدین قراارسلان قاوردبیک و آخرین ایشان محمدشاه ثانی و شماره ٔ آنان سیزده تن، و انقراضشان به دست ترکان غُز بوده است .<br /></font></div>'),
(1989, 'آل شنسب', '<span class=\"hlight\">آل شنسب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ش َ س َ ]</font></b> (اِخ ) ملوک شنسبانیه . در غور فرمانروایی داشته اند. و آنها دو طایفه بودند، طایفه ای در خود غور امارت داشته و مقر ایشان فیروزکوه بوده است و طایفه ٔ دیگر در طخارستان (ناحیه ای در شمال غور) فرمانروا بوده و مقرشان بامیان بوده است . نسبت این خانواده به جدّ اعلای ایشان شنسب نام است که گویند در عصر علی بن ابیطالب علیه السلام میزیسته است . شماره ٔ فرمانروایان غور که دارای اقتداربوده اند پنج تن و مدت فرمانروایی ایشان از سال <span class=\"hlight\" dir=\"rtl\">٥٤٥</span> تا <span class=\"hlight\" dir=\"rtl\">٦٠٩</span> هَ .ق . و نخستین امیر این دودمان علاءالدین حسن بن حسین بن سام بوده است . و اما ملوک غوریه ٔ بامیان چهار تن بوده و از سال <span class=\"hlight\" dir=\"rtl\">٥٥٠</span> تا <span class=\"hlight\" dir=\"rtl\">٦٠٩</span> امارت داشته اند و اولین ایشان ملک فخرالدین مسعودبن عزالدین حسین بوده است . این هر دو سلسله را خوارزمشاهیان برانداختند.<br /></font></div>'),
(1990, 'آل شیراز', '<span class=\"hlight\">آل شیراز.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آل شیرازی . شراب سرخ یا نیم رنگ شیرازی .<br /></font></div>'),
(1991, 'آل صوفان', '<span class=\"hlight\">آل صوفان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) این نام را بعضی مترادف بنی صوفه دانسته و بشعری تازی از گفته ٔ اوس بن معزاءاستشهاد کرده اند، و برخی گفته اند که آل صوفان در شعراوس آل صفوان بوده و بغلط و تحریف آل صوفان شده است .<br /></font></div>'),
(1992, 'آل طاهر', '<span class=\"hlight\">آل طاهر.</span> <font color=\"DarkGreen\"><b>[ ل ِ هَِ ]</font></b> (اِخ ) طاهریان . نام سلسله ای از امرای خراسان از اولاد طاهربن حسین بن مصعب، ملقب بذوالیمینین . این دوده ٔ ایرانی از<span class=\"hlight\" dir=\"rtl\">٢٠٥</span> تا <span class=\"hlight\" dir=\"rtl\">٢٥٩</span> هَ .ق . در خراسان استقلال داشته اند. طاهر ذوالیمینین سرسلسله ٔ آنان، سردار مشهور عباسیان (که در قصیده ای معروف، بایرانی بودن خویش می بالد) از جانب مأمون به سال <span class=\"hlight\" dir=\"rtl\">٢٠٥</span> بحکومت منصوب گردید و پس از یک سال و نیم دعوی استقلال کرده و در روز جمعه ای از جمادی الاَّخره ٔ سال <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> در نیشابور نام مأمون از خطبه بینداخت . پس از او پسرش طلحه به همین سال بجای پدر نشست و چند نوبت با حمزةبن عبداﷲ خارجی حرب کرد و سرانجام به سال <span class=\"hlight\" dir=\"rtl\">٢١٣</span> درگذشت . بعد از او برادرش عبداﷲبن طاهر فرمانروائی خراسان و کرمان یافت و با بابک خرم دین مصاف داده او را بشکست و نیز مازیاربن قارن حکمران طبرستان را مغلوب و دستگیر کرده نزد مأمون خلیفه فرستاد و در سال <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> فرمان یافت . سپس امارت خراسان بابوطیب طاهربن عبداﷲ رسید و او مدت <span class=\"hlight\" dir=\"rtl\">١٨</span> سال حکم راند و در <span class=\"hlight\" dir=\"rtl\">٢٤٨</span> وفات کرد. و محمدبن طاهر جای پدر گرفت و عاقبت در <span class=\"hlight\" dir=\"rtl\">٢٥٩</span> یعقوب لیث صفاری این خاندان را برانداخت .<br /></font></div>'),
(1993, 'آل طمغا', '<span class=\"hlight\">آل طمغا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ترکی، اِ مرکب ) آل تمغا.<br /></font></div>'),
(1994, 'آل طمغی', '<span class=\"hlight\">آل طمغی .</span> <font color=\"DarkGreen\"><b>[ طَغا ]</font></b> (ترکی، اِ مرکب ) کلمه ای است ترکی به معنی علامت سرخ : و عند باب الخرقة النائب و الوزیر و الحاجب و صاحب العلامة و هم یسمون آل طمغی، و آل معناه الاحمر و طمغی ... معناه العلامة. (رحله ٔ ابن بطوطه : آل تمغا).<br /></font></div>'),
(1995, 'آل عبا', '<span class=\"hlight\">آل عبا.</span> <font color=\"DarkGreen\"><b>[ ل ِ ع َ ]</font></b> (اِخ ) حضرت رسول اکرم و امیرالمؤمنین علی و فاطمه ٔ زهرا و حسن و حسین صلوات اﷲعلیهم . و از اینرو بایشان آل عبا گویند که زمانی در زیر یک عبا خفته بودند و برحسب اخبار جبرئیل نیز بیامد و در زیر آن عبا ششم آن گردید کسب شرف و مرتبت را. و بجای آل عبا، پنج تن و پنج تن آل عبا نیز گویند <span class=\"hlight\">:</span> <br />سید سرفراز آل عبا<br />یافت تشریف سوره ٔ هل اتی .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(1996, 'آل عباس', '<span class=\"hlight\">آل عباس .</span> <font color=\"DarkGreen\"><b>[ ل ِ ع َب ْ با ]</font></b> (اِخ ) نام بطنی از بنی هاشم از نژاد عباس بن عبدالمطلب بن هاشم بن عبدمناف، عم ّ پیغمبر خاتم (ص ). این نام گاهی بر خلفای عباسی که پس از بنی امیه خلافت یافتند اطلاق میشود. خلفای عباسی از سال <span class=\"hlight\" dir=\"rtl\">١٣٢</span> تا <span class=\"hlight\" dir=\"rtl\">٦٥٦</span> هَ .ق . خلافت داشته اند. اول ایشان ابوالعباس عبداﷲبن محمدبن علی بن عبداﷲبن عباس معروف بسفاح و آخر آنان معروف به مستعصم باﷲ، و عده ٔ این خلفاء <span class=\"hlight\" dir=\"rtl\">٣٧</span> تن و انقراض ایشان بر دست هلاکو نبیره ٔ چنگیز بوده است . و محل خلافت آنان ابتدا انبار و بعد کوفه و سپس بغداد بود. بنی عباس . عباسیان . خلفای عباسی :<br />ابوالعباس سفاح <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">١٣٢</span>-<span class=\"hlight\" dir=\"rtl\">١٣٦</span></font><br />منصور<br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">١٣٦</span>-<span class=\"hlight\" dir=\"rtl\">١٥٨</span></font><br />مهدی <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">١٥٨</span>-<span class=\"hlight\" dir=\"rtl\">١٦٩</span></font><br />هادی <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">١٦٩</span>-<span class=\"hlight\" dir=\"rtl\">١٧٠</span></font><br />هارون الرشید<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">١٧٠</span>-<span class=\"hlight\" dir=\"rtl\">١٩٣</span></font><br />امین <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">١٩٣</span>-<span class=\"hlight\" dir=\"rtl\">١٩٨</span></font><br />مأمون <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">١٩٨</span>-<span class=\"hlight\" dir=\"rtl\">٢١٨</span></font><br />معتصم <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٢١٨</span>-<span class=\"hlight\" dir=\"rtl\">٢٢٧</span></font><br />واثق <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٢٢٧</span>-<span class=\"hlight\" dir=\"rtl\">٢٣٢</span></font><br />متوکل <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٢٣٢</span>-<span class=\"hlight\" dir=\"rtl\">٢٤٧</span></font><br />منتصر<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٢٤٧</span>-<span class=\"hlight\" dir=\"rtl\">٢٤٨</span></font><br />مستعین <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٢٤٨</span>-<span class=\"hlight\" dir=\"rtl\">٢٥١</span></font><br />معتز<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٢٥١</span>-<span class=\"hlight\" dir=\"rtl\">٢٥٥</span></font><br />مهتدی <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٢٥٥</span>-<span class=\"hlight\" dir=\"rtl\">٢٥٦</span></font><br />معتمد<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٢٥٦</span>-<span class=\"hlight\" dir=\"rtl\">٢٧٩</span></font><br />معتضد<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٢٧٩</span>-<span class=\"hlight\" dir=\"rtl\">٢٨٩</span></font><br />مکتفی <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٢٨٩</span>-<span class=\"hlight\" dir=\"rtl\">٢٩٥</span></font><br />مقتدر<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٢٩٥</span>-<span class=\"hlight\" dir=\"rtl\">٣٢٠</span></font><br />قاهر<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٣٢٠</span>-<span class=\"hlight\" dir=\"rtl\">٣٢٢</span></font><br />راضی <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>-<span class=\"hlight\" dir=\"rtl\">٣٢٩</span></font><br />متقی <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٣٢٩</span>-<span class=\"hlight\" dir=\"rtl\">٣٣٣</span></font><br />مستکفی <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٣٣٣</span>-<span class=\"hlight\" dir=\"rtl\">٣٣٤</span></font><br />مطیع<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>-<span class=\"hlight\" dir=\"rtl\">٣٦٣</span></font><br />طایع<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٣٦٣</span>-<span class=\"hlight\" dir=\"rtl\">٣٨١</span></font><br />قادر<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٣٨١</span>-<span class=\"hlight\" dir=\"rtl\">٤٢٢</span></font><br />قائم <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٤٢٢</span>-<span class=\"hlight\" dir=\"rtl\">٤٦٧</span></font><br />مقتدی <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٤٦٧</span>-<span class=\"hlight\" dir=\"rtl\">٤٨٧</span></font><br />مستظهر<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٤٨٧</span>-<span class=\"hlight\" dir=\"rtl\">٥١٢</span></font><br />مسترشد<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٥١٢</span>-<span class=\"hlight\" dir=\"rtl\">٥٢٩</span></font><br />راشد<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٥٢٩</span>-<span class=\"hlight\" dir=\"rtl\">٥٣٠</span></font><br />مقتفی <br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٥٣٠</span>-<span class=\"hlight\" dir=\"rtl\">٥٥٥</span></font><br />مستنجد<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٥٥٥</span>-<span class=\"hlight\" dir=\"rtl\">٥٦٦</span></font><br />مستضی ٔ<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٥٦٦</span>-<span class=\"hlight\" dir=\"rtl\">٥٧٥</span></font><br />ناصر<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٥٧٥</span>-<span class=\"hlight\" dir=\"rtl\">٦٢٢</span></font><br />ظاهر<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٦٢٢</span>-<span class=\"hlight\" dir=\"rtl\">٦٢٣</span></font><br />مستنصر<br /> <font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٦٢٣</span>-<span class=\"hlight\" dir=\"rtl\">٦٤٠</span></font><br />مستعصم <br /><font color=\"Red\"> <span class=\"hlight\" dir=\"rtl\">٦٤٠</span>-<span class=\"hlight\" dir=\"rtl\">٦٥٦</span></font><br /></font></div>'),
(1997, 'آل عثمان', '<span class=\"hlight\">آل عثمان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ُ ]</font></b> (اِخ ) پادشاهان ترکیه که از سال <span class=\"hlight\" dir=\"rtl\">٦٩٩</span> تا سال <span class=\"hlight\" dir=\"rtl\">١٣٤٢</span> هَ .ق . در آسیای صغیر سلطنت داشته اند. مؤسس این سلسله که به نام او منسوب شده اند، عثمان بن ارطغرل و شماره ٔ آنها <span class=\"hlight\" dir=\"rtl\">٣٨</span> تن و آخرین آنان عبدالعزیز ثانی، و انقراض این دودمان در نتیجه ٔ برقرار شدن حکومت جمهوری بوده است . آل عثمان یا پادشاهان عثمانی قریب سه قرن کمال اقتدار داشته قلمرو حکمرانی خود را از بوداپست و ساحل دانوب تا شلاله ٔ اسوان در مصر و از ساحل فرات تا تنگه ٔ جبل الطارق وسعت داده ممالک شبه جزیره ٔ بالکان و شام و مصر و عربستان را مسخر ساختند. پس از سه قرن دوره ٔ ضعف و انحطاط آنان شروع و بسیاری از ممالک مفتوحه از تصرف ایشان خارج شد. مشهورترین این سلسله سلطان محمد ثانی معروف بفاتح است که در سال <span class=\"hlight\" dir=\"rtl\">٨٥٧</span> قسطنطنیه را بگشاد.<br /></font></div>'),
(1998, 'آل عراق', '<span class=\"hlight\">آل عراق .</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ ]</font></b> (اِخ ) نام سلسله ای از ملوک پیش از اسلام خوارزم .و این سلسله نسب خود بکیخسرو می پیوسته اند و تا زمان سامانیان شبه قدرت و نفوذی در خوارزم داشته اند. آخرین آنان ابوعبداﷲ محمدبن احمدبن محمدبن عراق است که ابوریحان از او به شهید تعبیر می کند. و پدر او احمد، تقویم سنین و شهور اهل خوارزم را اصلاح کرده است . انقراض این خاندان ظاهراً سلطان محمود غزنوی بوده است .<br /></font></div>'),
(1999, 'آل عطاری', '<span class=\"hlight\">آل عطاری .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِ مرکب، از اتباع ) آل و عطاری . آنچه پیله وران در قراء و قصبات از قبیل حنا و صابون و نخ و سوزن و نبات و جز آن گردانند فروختن را.<br /></font></div>'),
(2000, 'آل علی', '<span class=\"hlight\">آل علی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ع َ ]</font></b> (اِخ ) سادات از نسل علی و فاطمه علیهماالسلام . علویین <span class=\"hlight\">:</span> <br />با آل علی هرکه درافتاد برافتاد.<br /></font></div>'),
(2001, 'آل عمران', '<span class=\"hlight\">آل عمران .</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ ]</font></b> (اِخ ) نام سوره ٔ سیم از قرآن پس از بَقَرة و پیش از نساء و آن دویست آیت باشد و مدنی است . <BR><font color=\"Blue\">◄</font> موسی و هارون . (مجمل اللغه ).<br /></font></div>'),
(2002, 'آل غالب', '<span class=\"hlight\">آل غالب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ل ِ ]</font></b> (اِخ ) منسوب به غالب بن قهر، یکی از اجداد رسول صلوات اﷲعلیه یا منسوب به بنی الادرم بن غالب <span class=\"hlight\">:</span> من <font color=\"DarkGreen\"><b>[ حلیمه، بنت ابی ذویب السعدیه دایگان رسول صلوات اﷲعلیه ]</font></b> تَرسان برِ عبدالمطلب شدم، چون مرابدان حال بدید گفت چه بود، شغلی رسید؟ گفتم شغلی و چه شغلی ! گفت مگر پسرت گم شد؟ گفتم نعم . او را ظن شدکه مگر قریش او را بکشتند، شمشیر برکشید و خشمناک بیرون آمد، بانگ کرد یا آل غالب و ایشان اندر جاهلیت چنین گفتندی، درساعت همه جمع شدند. (تاریخ سیستان ).<br /></font></div>'),
(2003, 'آل فاطمه', '<span class=\"hlight\">آل فاطمه .</span> <font color=\"DarkGreen\"><b>[ ل ِ طِ م َ ]</font></b>(اِخ ) اولاد رسول از نسل علی و فاطمه علیهماالسلام .<br /></font></div>'),
(2004, 'آل فرعون', '<span class=\"hlight\">آل فرعون .</span> <font color=\"DarkGreen\"><b>[ ل ِ ف ِ ع َ ]</font></b> (اِخ ) کسان فرعون .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مؤمن آل فرعون </span> ؛ گویند از آل او تنها خِربیل یا شمعان نام ایمان داشت و ایمان خویش می نهفت . و بعضی گویند سه تن بوده اند که ایمان داشته اند، خربیل و آسیه زن فرعون و آن مرد که قصد قتل موسی را بموسی خبر داد.<br /></font></div>'),
(2005, 'آل فریغون', '<span class=\"hlight\">آل فریغون .</span> <font color=\"DarkGreen\"><b>[ ل ِ ف َ ]</font></b> (اِخ ) فریغونیان . امرای خوارزم یا خوارزمشاهیان، نخستین آنان مأمون بن احمدبن محمد بود که از دست آل سامان حکومت خوارزم یافت و پس از او پسرش ابومنصور احمدبن مأمون فرمان راند و آخرین آنان امیرابوالعباس مأمون بن مأمون داماد محمود غزنوی است که به دست امرای خویش مقتول شد و محمود بکین کشی او لشکر به خوارزم برد و خوارزم را مسخر و ضمیمه ٔ قلمرو خویش کرد <span class=\"hlight\">:</span> <br />کجاست آنکه فریغونیان ز هیبت او<br />ز دست خویش بدادند گوزگانان را؟<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(2006, 'آل قاورد', '<span class=\"hlight\">آل قاورد.</span> <font color=\"DarkGreen\"><b>[ ل ِ وَ ]</font></b> (اِخ ) نام خانواده ای از سلاجقه که از سال <span class=\"hlight\" dir=\"rtl\">٤٣٣</span> تا <span class=\"hlight\" dir=\"rtl\">٥٨٣</span> هَ .ق . در کرمان حکومت مستقل داشته اند. مؤسس این خانواده عمادالدین قراارسلان قاوردبن چغری بیک داودبن میکائیل بن سلجوق، و شماره ٔ فرمانروایان آنها سیزده تن و آخرین ایشان محمدشاه ثانی و انقراضشان ترکان غز بوده است . رجوع به سلاجقه ٔ کرمان ذیل «آل سلجوق » در همین لغت نامه شود.<br /></font></div>'),
(2007, 'آل قراس', '<span class=\"hlight\">آل قراس .</span> <font color=\"DarkGreen\"><b>[ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ُ ]</font></b> (اِخ ) (قرس سرما باشد) نام کوههائی بناحیه ٔ شراه . و آل قراس و مابد نام دو کوه باشد در زمین بنی هذیل .<br /></font></div>'),
(2008, 'آل لیث', '<span class=\"hlight\">آل لیث .</span> <font color=\"DarkGreen\"><b>[ ل ِ ل َ ]</font></b> (اِخ ) صفاریان . نام سلسله ای از ملوک ایران . یعقوب بن لیث صفار مؤسس این دودمان در سال <span class=\"hlight\" dir=\"rtl\">٢٢٤</span>هَ .ق . سردار سپاه حاکم سیستان بود و در همان سال هرات را مسخر کرده و فارس و کرسی آن شیراز را نیز متصرف شد و بمرور بلخ و تخارستان را قبضه کرد و به سال <span class=\"hlight\" dir=\"rtl\">٢٥٩</span> خراسان را از طاهریان منتزع ساخت و لشکر بطبرستان کشید و حسن بن زید علوی را مغلوب کرده از راه اهواز بسوی بغداد شتافت . موفق عباسی برادر معتمد خلیفه با یعقوب مصاف داده و او را بشکست و یعقوب <span class=\"hlight\" dir=\"rtl\">٢٦٥</span> درگذشت .برادر او عمرو از جانب خلیفه حکومت خراسان و فارس وکردستان و نیم روز یافت لکن سپس خلیفه از قدرت او بیم کرده و اسماعیل سامانی را بمخاصمت او برانگیخت و عمرو مغلوب و اسیر گشت . نبیره ٔ عمرو، طاهر در سیستان به سال <span class=\"hlight\" dir=\"rtl\">٢٨٧</span> بجای او نشست و در <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> به دست سبکری اسیرشده و سبکری او را با برادرش یعقوب ببغداد فرستاد. احفاد این خانواده مدتی در ادعای حکومت اجدادی خود در سیستان باقی بودند و پاره ای از آنان نیز به آن مقام رسیدند، و عاقبت به دست محمود غزنوی منقرض شدند.<br /></font></div>'),
(2009, 'آل محتاج', '<span class=\"hlight\">آل محتاج .</span> <font color=\"DarkGreen\"><b>[ ل ِ م ُ ]</font></b> (اِخ ) خانواده ای مشهور که در عهد پادشاهان سامانی و غزنوی متصدی کارهای مهم و دارای مناصب عالی بوده اند، حکومت و ولایت چغانیان در ماوراءالنهر بایشان اختصاص داشته است، نخستین امیر معروف این خانواده ابوبکر محمدبن مظفربن محتاج است که در سال <span class=\"hlight\" dir=\"rtl\">٣٢١</span> هَ .ق . از طرف امیرنصربن احمد سامانی سپهسالارو حکمران خراسان شده و در سال <span class=\"hlight\" dir=\"rtl\">٣٢٩</span> وفات یافته است .<br /></font></div>'),
(2010, 'آل محمد', '<span class=\"hlight\">آل محمد.</span> <font color=\"DarkGreen\"><b>[ ل ِ م ُح َم ْ م َ ]</font></b> (اِخ ) اولاد و احفاد پیامبر صلوات اﷲ علیه و آله از نسل علی و فاطمه علیهماالسلام <span class=\"hlight\">:</span> <br />سعدی اگر عاشقی کنی ّ و جوانی <br />عشق محمد بس است و آل محمد.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(2011, 'آل مرداس', '<span class=\"hlight\">آل مرداس .</span> <font color=\"DarkGreen\"><b>[ ل ِ م َ ]</font></b> (اِخ ) سلسله ای از امرای عرب بنی کلاب که در حلب حکومت کرده اند (<span class=\"hlight\" dir=\"rtl\">٤١٤</span>-<span class=\"hlight\" dir=\"rtl\">٤٧٢</span> هَ .ق .) اسدالدوله ابوعلی صالح بن مرداس نخستین آنان در حدود سال <span class=\"hlight\" dir=\"rtl\">٤١٢</span> بحلب آمده و آن زمان حلب در اختیار خلفای فاطمی بود. پس از چندی اهل حلب بر حاکم خویش شوریده و آن را بتصرف اسدالدوله دادند ولی پیوسته خلفای فاطمی با او و خاندانش در نزاع و کشمکش بودند که گاهی غالب و گاهی مغلوب میشدند. نام امرای این سلسله این است : صالح بن مرداس، شهاب الدولةبن مرداس، معزالدولةبن مرداس، ابوذوابه عطیه، رشیدالدولةبن شهاب الدوله، جلال الدولةبن رشیدالدوله، سابق بن رشیدالدوله .<br /></font></div>'),
(2012, 'آل مروان', '<span class=\"hlight\">آل مروان .</span> <font color=\"DarkGreen\"><b>[ ل ِ م َرْ ]</font></b> (اِخ ) سلسله ای از خلفای اموی هستند که پس از آل بوسفیان به خلافت رسیدند. اولین خلیفه ٔ آل مروان، مروان بن حکم است که بعد از معاویةبن یزید در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٦٤</span> هَ .ق . بدعوی خلافت در دمشق و شام برخاست و پس از آنکه ضحاک بن قیس فهری سردار عبداﷲبن زبیر را مغلوب کرد چهار ماه خلافت راند، پس از او پسرش عبدالملک بن مروان در<span class=\"hlight\" dir=\"rtl\">٦٥</span> و ولید اول در <span class=\"hlight\" dir=\"rtl\">٨٦</span> و سلیمان در <span class=\"hlight\" dir=\"rtl\">٩٦</span> و عمر در <span class=\"hlight\" dir=\"rtl\">٩٩</span> و یزید ثانی در <span class=\"hlight\" dir=\"rtl\">١٠١</span> و هِشام در <span class=\"hlight\" dir=\"rtl\">١٠٥</span> و ولید ثانی در <span class=\"hlight\" dir=\"rtl\">١٢٥</span>و یزید ثالث در <span class=\"hlight\" dir=\"rtl\">١٢٦</span> و ابراهیم در <span class=\"hlight\" dir=\"rtl\">١٢٦</span> و مروان ثانی ملقب به مروان حمار از <span class=\"hlight\" dir=\"rtl\">١٢٧</span>تا<span class=\"hlight\" dir=\"rtl\">١٣٢</span> مقام خلافت مسلمین داشتند، و ابومسلم خراسانی مروان حمار را مغلوب کرده بکشت و خلفای عباسی قائم مقام آنان شدند <span class=\"hlight\">:</span> <br />آل مروان و آل سفله زیاد<br />که نرفتند جز براه عناد.<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(2013, 'آل مشعشع', '<span class=\"hlight\">آل مشعشع.</span> <font color=\"DarkGreen\"><b>[ ل ِ م ُ ش َ ش َ ]</font></b>(اِخ ) نام خاندانی از سادات علوی موسوی که رئیس آنان سیدمحمدبن فلاح بن هبةاﷲ در <span class=\"hlight\" dir=\"rtl\">٨٤٨</span> هَ .ق . بخوزستان دعوی مهدویت کرد. این مرد نخست در سلک طلاّ ب علوم دینیه بود و نزد شیخ احمدبن فهد تلمّذ می کرد. پس از آنکه این داعیه در او پیدا آمد جمعی از عَرَب بدو گرویده و بامر او به نهب و غارت و تاخت و تاز پرداختند و با امرا و حکام بعض بلاد عراق عرب و خوزستان جنگها کردتا کار او قوّت گرفت و بر بسیاری از شهرهای عراق و فارس و خوزستان مستولی گشت و در سال <span class=\"hlight\" dir=\"rtl\">٨٧٥</span> درگذشت . پسرسلحشور و شجاع او علی که میتوانست پس از پدر دنباله ٔ فتوحات او را بگیرد در حیات پدر بمرد و سلطان محسن فرزند دیگر سیدمحمد بجای او نشست، و او مردی علم دوست بود چنانکه شمس الدین محمد استرآبادی حاشیه ٔ خود رابر تجریداو نگاشت . پس از محسن علی و ایوب بفرمانروائی رسیدند، و آن دو را شاه اسماعیل اول صفوی در <span class=\"hlight\" dir=\"rtl\">٩١٤</span> منکوب و مقهور کرده بقتل رسانید لکن تا مدتی حکومت حویزه از دست صفویه ببازماندگان این دوده مفوض بود.<br /></font></div>'),
(2014, 'آل مظفر', '<span class=\"hlight\">آل مظفر.</span> <font color=\"DarkGreen\"><b>[ ل ِ م ُ ظَف ْ ف َ ]</font></b> (اِخ ) سلسله ای از فرمانروایان که از<span class=\"hlight\" dir=\"rtl\">٧١٣</span> تا <span class=\"hlight\" dir=\"rtl\">٧٩٥</span> هَ .ق . در فارس و کرمان و کردستان به استقلال فرمانروایی کرده اند. سرسلسله ٔ این دودمان امیرمبارزالدین محمدبن مظفر است (<span class=\"hlight\" dir=\"rtl\">٧١٣</span>-<span class=\"hlight\" dir=\"rtl\">٧٦٠</span>)، پس از او شاه شجاع الدین بن امیرمبارزالدین (<span class=\"hlight\" dir=\"rtl\">٧٦٠</span>-<span class=\"hlight\" dir=\"rtl\">٧٨٦</span>)، شاه محمودبن مبارزالدین (<span class=\"hlight\" dir=\"rtl\">٧٦٠</span> -<span class=\"hlight\" dir=\"rtl\">٧٧٧</span>)، عمادالدین بن احمدبن مبارزالدین (<span class=\"hlight\" dir=\"rtl\">٧٦٠</span>- <span class=\"hlight\" dir=\"rtl\">٧٩٥</span>)، شاه نصرةالدین یحیی بن امیرمبارزالدین (<span class=\"hlight\" dir=\"rtl\">٧٨٩</span>-<span class=\"hlight\" dir=\"rtl\">٧٩٥</span>)، سلطان زین العابدین بن شاه شجاع (<span class=\"hlight\" dir=\"rtl\">٧٨٦</span>-<span class=\"hlight\" dir=\"rtl\">٧٩٠</span>)، شاه منصوربن شاه مظفربن امیر مبارزالدین (<span class=\"hlight\" dir=\"rtl\">٧٩٠</span>-<span class=\"hlight\" dir=\"rtl\">٧٩٥</span>). این سلسله را امیرتیمور گورکان برانداخت و چنانکه صاحب کشف الظنون گوید معین الدین یزدی را تاریخی است به فارسی (<span class=\"hlight\" dir=\"rtl\">٧٥٧</span>) راجع باین سلسله به نام مواهب الهی .<br /></font></div>'),
(2015, 'آل معصفر', '<span class=\"hlight\">آل معصفر.</span> <font color=\"DarkGreen\"><b>[ م ُ ع َ ف َ ]</font></b> (اِ مرکب ) قسمی ماهی درم دار. <BR><font color=\"Blue\">◄</font> سرخ نیم رنگ .<br /></font></div>'),
(2016, 'آل مهلب', '<span class=\"hlight\">آل مهلب .</span> <font color=\"DarkGreen\"><b>[ ل ِ م ُ هََل ْ ل َ ]</font></b> (اِخ ) آل مهلب بن ابی صفره . مهالبه . ابوصُفره از مردم یمن و از جانب امیرالمؤمنین علی علیه السلام امیر آنجا بود. مهلب پسراو از جانب عبداﷲ زبیر امارت خراسان یافت و با خوارج (ازارقه ) جنگها کرد و آنان را چند نوبت بشکست و آنگاه که حجاج بن یوسف ثقفی بامارت خراسان و عراق منصوب گشت هرچند جهد کرد مهلب را از امارت جیوش خلع کند نتوانست، عاقبت حجاج او را بامارت خراسان فرستاد و درسال <span class=\"hlight\" dir=\"rtl\">١٠٢</span> هَ .ق . وفات کرد و مغیرةبن مهلب امارت مروداشت و بمرو در حیات پدر فرمان یافت، و یزیدبن مهلب پس از پدر سه سال والی خراسان بود، سپس حجاج او را معزول کرد و امارت خراسان را به برادر او یعنی مفضل بن مهلب داد، و این مفضل مردی عالم و سخی بود و سلیمان بن عبدالملک در خلافت خویش امارت خراسان را به اصالت به یزیدبن مهلب سپرد، عمربن عبدالعزیز یزید را از امارت خراسان عزل و بند کرد و مخلدبن یزیدبن مهلب را نیز جراح امیر خراسان بگرفت و مغلولاً بدمشق نزد عمربن عبدالعزیز فرستاد، و گویند مخلد در این راه با اینکه در بند بود هشتصدهزار درم بفقرا و محاویج و صلحا عطا داد و عمر بر او ببخشود و بشفاعت وی یزید را نیزآزاد فرمود و آنگاه که عمربن عبدالعزیز در بستر مرگ بود یزیدبن مهلب به بصره شد و یزیدبن عبدالملک پسر خود مسلمه را بجنگ یزیدبن مهلب فرستاد و یزیدبن مهلب در این جنگ کشته شد. و از بزرگان این خاندان روح بن حاتم المهلبی و یزیدبن حاتم المهلبی است، و از یزیدبن مهلب در خراسان اولاد و اعقاب ماند، از آنجمله است فقیه رئیس ابوعبداﷲ محمدبن یحیی، و از این خاندان دربیهق و نشابور نیز امرا و فقها و محدثین بوده اند.<br /></font></div>'),
(2017, 'آل میکال', '<span class=\"hlight\">آل میکال .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) نام خاندانی قدیم به نیشابور و بیهق، از احفاد میکال بن عبدالواحدبن جبریل بن قاسم بن بکربن دیواستی سوربن سوربن سوربن سوربن فیروزبن یزدجردبن بهرام گور وفرزند او شاه بن میکال است، و از این دوده است امیرابوالعباس اسماعیل بن عبداﷲبن محمدبن میکال و مقصوره ٔ ابن درید به نام ابوالعباس و پدر اوست و پسر ابوالعباس اسماعیل ابومحمد عبداﷲ است . و ابوالعباس در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٣٩٢</span> هَ .ق . درگذشته است و او رئیس نیشابور بود و املاک خویش وقف بر خیرات و مبرات کرد. و نیز از این خاندان است امیراحمدبن علی بن اسماعیل میکالی و فرزند اوامیر عالم ابوالفضل عبیداﷲبن احمد صاحب کتاب المنتحل یا المنتخب و کتاب مخزون البلاغه و غیر آن و او صاحب نظم و نثر بوده و او را دیوان رسائل است، و پسران او امیرحسین و امیرعلی و امیراسماعیل است و امیرعلی را دیوان شعر است و امیر رئیس جمال الامراء علی بن الامیرابی عبداﷲ الحسین از طرف جدّه از این خانواده است .<br /></font></div>'),
(2018, 'آل ناصرالدین', '<span class=\"hlight\">آل ناصرالدین .</span> <font color=\"DarkGreen\"><b>[ ل ِ ص ِ رِدْ دی ]</font></b> (اِخ ) آل سبکتکین . غزنویان (<span class=\"hlight\" dir=\"rtl\">٣٥١</span> - <span class=\"hlight\" dir=\"rtl\">٥٨٢</span> هَ .ق .). آلبتکین غلامی ترک از جانب عبدالملک بفرماندهی لشکر مقیم خراسان منصوب شد و پس از عبدالملک در <span class=\"hlight\" dir=\"rtl\">٣٥١</span> از این منصب معزول گردید و بمقر پیشین خویش یعنی شهر غزنه بازگشت و غزنه را تسخیر کرد ولی بزودی وفات یافت و در <span class=\"hlight\" dir=\"rtl\">٣٥٢</span> اسحاق پسر او جای پدر گرفت و او در <span class=\"hlight\" dir=\"rtl\">٣٥٥</span> بمرد و بلکاتکین غلام البتکین از <span class=\"hlight\" dir=\"rtl\">٣٥٥</span> تا <span class=\"hlight\" dir=\"rtl\">٣٦٢</span> امارت کردو پس از او پیری از <span class=\"hlight\" dir=\"rtl\">٣٦٢</span> تا <span class=\"hlight\" dir=\"rtl\">٣٦٦</span> فرمان راند، پس از او سبکتکین غلام دیگر البتکین به مقام امارت رسید و اومؤسس واقعی سلسله ٔ غزنوی است، سبکتکین قلمرو خویش را از طرف مشرق و مغرب بسط داد یعنی از جانب هندوستان قبائل رجپوت را مغلوب و شهر پیشاور را تسخیر کرد و<span class=\"hlight\" dir=\"rtl\">٣٨٤</span> نوح سامانی حکومت خراسان را باو داد. سبکتکین درمدت امارت خویش با اینکه در اواخر از حیث اقتدار برسامانیان برتری داشت لیکن صورةً از راه احتیاط اظهار تبعیت آنان میکرد، پس از اینکه در <span class=\"hlight\" dir=\"rtl\">٣٨٧</span> سبکتکین وفات کرد پسرش محمود جانشین او شد و او یکی از بزرگترین سلاطین اسلام است، در اول امر اسماعیل برادر کوچک خودرا عزل کرد و مستقیماً از جانب خلیفه حکومت خراسان و غزنه بدو تفویض شد و پس از صلح با خوانین ایلک خانی بهندوستان تاخت و دامنه ٔ لشکرکشیهای خود را تا حدودکشمیر و پنجاب بسط داد و در سال <span class=\"hlight\" dir=\"rtl\">٤٠٨</span> بلاد قنوج و مُترا را گرفت و سومنات را در <span class=\"hlight\" dir=\"rtl\">٤١٥</span> غارت کرد. علاوه بر فتوحات هندوستان بلاد غور و مرغاب علیا را ضمیمه ٔ قلمروخویش ساخت و ماوراءالنهر را با بخارا و سمرقند دو پایتخت آن بگرفت ولی ترکمانان سلجوقی که بظاهر اطاعت غزنویان میکردند در زمان او قوت گرفتند، پس از مراجعت از سفری که بداخله ٔ ممالک خلفا کرد اصفهان را از دیالمه منتزع ساخت و در <span class=\"hlight\" dir=\"rtl\">٤٢١</span> در غزنه درگذشت . تشویق اواز علم و ادب نهایت مشهور است و بزرگترین شعرای فارسی چون فردوسی و عنصری و فرخی و امثال آنان در عصر محمود و در کنف حمایت او تربیت شدند. و از اولاد و نبیرگان او پادشاهان ذیل میباشند: محمد، جلال الدوله <span class=\"hlight\" dir=\"rtl\">٤٢١</span><br />مسعود اول، الناصر لدین اﷲ که در جنگی با سلاجقه شکست یافت <br /><font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٣٢</span></font><br />مودود، شهاب الدوله <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٤٠</span></font><br />مسعود ثانی <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٤٠</span></font><br />علی ابوالحسن، بهاءالدوله <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٤٠</span></font><br />عبدالرشید، عزالدوله <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٤٠</span></font><br />فرخزاد، جمال الدوله <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٤٤</span></font><br />ابراهیم، ظهیرالدوله <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٥١</span></font><br />مسعود ثالث، علاءالدوله <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٩٢</span></font><br />شیرزاد، کمال الدوله <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٥٠٨</span></font><br />ارسلان، سلطان الدوله <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٥٠٩</span></font><br />بهرامشاه، یمین الدوله <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٥١٢</span></font><br />خسروشاه، معزالدوله <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٥٤٧</span></font><br />خسرو ملک، تاج الدوله <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٥٥٥</span>-<span class=\"hlight\" dir=\"rtl\">٥٨٢</span></font><br />و این سلسله را غوریان برانداختند. (نقل به اختصار از طبقات سلاطین اسلام استانلی لین پول ).<br /></font></div>'),
(2019, 'آل نجاح', '<span class=\"hlight\">آل نجاح .</span> <font color=\"DarkGreen\"><b>[ ل ِ ن َ ]</font></b> (اِخ ) طائفه ای از سلاطین اسلام که در زبید مدتی حکم رانده اند (<span class=\"hlight\" dir=\"rtl\">٤١٢</span>-<span class=\"hlight\" dir=\"rtl\">٥٥٣</span> هَ .ق .). سرسلسله ٔ آنان نجاح مملوک حبشی مرجان از ملوک بنی زیاد بود و در زمان او در زبید حکومت میکرد و در سال <span class=\"hlight\" dir=\"rtl\">٤٥٤</span> طائفه ٔ بنی صُلیح شهر زبید را تصرف کردند ولیکن پسر نجاح در سال <span class=\"hlight\" dir=\"rtl\">٤٧٣</span> آنجا را از بنی صلیح مستردداشت و اولاد او در آنجا حکم راندند و بواسطه ٔ بنی مهدی منقرض شدند. اسامی ملوک آل نجاح بدین ترتیب است :<br />نجاح المؤید<br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤١٢</span></font><br />علی داعی صلیحی از غیرآل نجاح <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٥٤</span></font><br />سعیدبن نجاح <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٧٣</span></font><br />جیش بن نجاح <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٨٢</span></font><br />الفاتک الاول بن جیش <br /><font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٤٩٨</span></font><br />المنصوربن الفاتک <br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٥٠٣</span></font><br />الفاتک الثانی بن منصور<br /> <font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٥١٧</span></font><br />الفاتک الثالث بن محمدبن منصور<br /><font color=\"Red\"><span class=\"hlight\" dir=\"rtl\">٥٣١</span></font><br /></font></div>'),
(2020, 'آل نصر', '<span class=\"hlight\">آل نصر.</span> <font color=\"DarkGreen\"><b>[ ل ِ ن َ ]</font></b> (اِخ ) آل لخم . آل عمروبن عدی . ملوک حیره . مناذره . سلسله ای از امرای عرب که در عراق حکومت داشته از پادشاهان ایران اطاعت میکردند. مرکز حکومت آنان شهر حیره نزدیک کوفه بوده ... سرسلسله ٔ آنها عمروبن عدی بن نصر معاصر با اردشیربابکان است . و بین عدی و جذیمة الابرش و قصیر حکایتی در بین عرب معروف است و لا مرء ما جدع قصیر انفه در امثال عرب اشاره بحکایت آنهاست . ابتدای سلطنت آنان از <span class=\"hlight\" dir=\"rtl\">٢٦٨</span> تا <span class=\"hlight\" dir=\"rtl\">٦٢٨</span> م . یکی از معاریف این سلسله نعمان بن امروءالقیس است (<span class=\"hlight\" dir=\"rtl\">٤٠٣</span>-<span class=\"hlight\" dir=\"rtl\">٤٣١</span> م .) که قصر خورنق را سنمار برای او بنا کرده است، و دیگر منذربن نعمان که بهرام گور در زمان کودکی نزد او بسر برد (<span class=\"hlight\" dir=\"rtl\">٤٣١</span>-<span class=\"hlight\" dir=\"rtl\">٤٧٣</span> م .)، و منذربن امروءالقیس بن ماءالسماء (<span class=\"hlight\" dir=\"rtl\">٥٠٧</span>-<span class=\"hlight\" dir=\"rtl\">٥١٤</span> م .)، مشهورترین آنها معاصر با قباد بوده، او از قبول دین مزدک ابا کرد، قباد او را معزول و حارث بن عمرو کندی را بجای او گذارد و انوشیروان حکومت او را به وی ردّ کرد، و دیگر نعمان بن منذر ابوقابوس (<span class=\"hlight\" dir=\"rtl\">٥٨٥</span>-<span class=\"hlight\" dir=\"rtl\">٦١٣</span> م .)، خسروپرویز بعض دختران عم وی را برای فرزندان خویش خواستگاری کرد، نعمان ابا ورزید، خسروپرویز بر وی خشم گرفت و نعمان پناه ببعض قبائل برده و آنان او را نپذیرفتند، ناچار خود برای پوزش بدربار خسرو آمد، خسرو او را گرفته و محبوس کرد تا سال <span class=\"hlight\" dir=\"rtl\">٦١٣</span> م . بطاعون درگذشت و خسرو مملکت او را به یک تن از غیر آن خاندان، ایاس بن قبیصه بخشید. آخرین ِ ملوک این سلسله منذربن نعمان در بحرین در جنگی کشته شد و سلسله ٔ آنان منقرض گردید (<span class=\"hlight\" dir=\"rtl\">٦٣٢</span> م .). حمزةبن حسن اصفهانی عده ٔ ملوک و مدت سلطنت آنان را بدینگونه ذکر کرده است : عمروبن عدی، معاصر اردشیر بابکان . امروءالقیس بن عمروبن عدی، معاصر شاپوربن اردشیر و هرمزبن شاپور و بهرام و بهرام بن بهرام و بهرام بن بهرام بن بهرام و نرسی و هرمز و شاپور ذوالاکتاف . عمروبن امروءالقیس، معاصر شاپور ذوالاکتاف و برادرش اردشیر. امروءالقیس بن بدأبن عمرو، معاصر اردشیر برادرشاپور و شاپوربن شاپور و بهرام بن شاپور و یزدجردبن شاپور. نعمان بن امروءالقیس، معاصر یزدجردبن بهرام و بهرام گور. منذربن نعمان، معاصر بهرام گور و یزدجردبن بهرام گور و فیروزبن یزدجرد. اسودبن منذر، معاصر فیروزبن یزدجرد و بلاش و قباد. منذربن منذر، معاصر قباد. نعمان بن اسود، معاصر قباد. ابویعفربن علقمه، معاصر قباد. امروءالقیس بن نعمان، معاصر قباد. منذربن امروءالقیس، معاصر قباد و انوشیروان . حارث بن عمرو، معاصر انوشیروان . منذربن امروءالقیس (بار دوم )، معاصر انوشیروان . عمروبن منذر، معاصر انوشیروان . قابوس بن منذر، معاصر انوشیروان . منذربن منذر، معاصر انوشیروان وهرمز پسر او. نعمان بن منذر، معاصر هرمز و خسروپرویز. ایاس بن قبیصه، معاصر خسروپرویز. ذادیه (ایرانی عامل خسروپرویز بر ممالک حیره ). منذربن نعمان بن منذر.<br /></font></div>'),
(2021, 'آل نصره', '<span class=\"hlight\">آل نصره .</span> <font color=\"DarkGreen\"><b>[ ل ِ ؟ ]</font></b> (اِخ ) رجوع به معد شود.<br /></font></div>'),
(2022, 'آل نوبخت', '<span class=\"hlight\">آل نوبخت .</span> <font color=\"DarkGreen\"><b>[ ل ِ ن َ ب َ ]</font></b> (اِخ ) خانواده ای ایرانی از اولاد نوبخت زردشتی ستاره شناس معروف که در زمان منصور خلیفه ٔ دوم عباسی (<span class=\"hlight\" dir=\"rtl\">١٣٦</span>-<span class=\"hlight\" dir=\"rtl\">١٥٨</span> هَ .ق .) میزیسته و افراد این خاندان بزرگ بدو منسوب اند و از این رو ایشان را آل نوبخت یا بنی نوبخت یا نوبختیون نامند. این خاندان نسبت خود را به گیو پسر گودرز پهلوان معروف ایرانی میرسانند. منصور عباسی چون بستاره شناسی و احکام نجوم رغبت داشت منجمین و ستاره شناسان را از هر سو جمع میکرد، از آنجمله نوبخت جد آل نوبخت و پسرش ابوسهل را نزد خود خواند و بقبول دین اسلام داشت و هنگام بنای دارالخلافه ٔ بغداد (<span class=\"hlight\" dir=\"rtl\">١٤٤</span>) اساس آن شهر را در ساعتی ریخت که نوبخت از روی احکام نجومی اختیار کرده بود.چون نوبخت در زمان منصور پیر و ناتوان شد و نمیتوانست چنانکه باید از عهده ٔ وظائف محوله برآید بأمر خلیفه پسر خود ابوسهل را بجای خویش گماشت و ظاهراً نوبخت جز این یک پسر فرزند دیگری نداشته است چه نسبت عموم نوبختیها به همین ابوسهل منتهی میشود. ابوسهل از همان تاریخ بنای بغداد (<span class=\"hlight\" dir=\"rtl\">١٤٤</span>) تا سال فوت منصور (<span class=\"hlight\" dir=\"rtl\">١٥٨</span>)در خدمت خلیفه و از ندمای او بود. ابوسهل بعد از فوت منصور نیز حیات داشت و زمان هارون الرشید (<span class=\"hlight\" dir=\"rtl\">١٧٠</span>-<span class=\"hlight\" dir=\"rtl\">١٩٣</span>)را درک کرده است . ابوسهل از منجمین ایرانی و از مترجمین کتب فارسی پهلوی به عربی است، و در نجوم مستند او اطلاعات و کتب منجمین ایرانی عهد ساسانی بود. و ابن الندیم هفت کتاب ذیل را از او نام می برد: <span class=\"hlight\" dir=\"rtl\">١</span> - کتاب النهمطان <span class=\"hlight\" dir=\"rtl\">٢</span> - کتاب الفال <span class=\"hlight\" dir=\"rtl\">٣</span> - کتاب الموالید <span class=\"hlight\" dir=\"rtl\">٤</span> - کتاب تحویل <span class=\"hlight\" dir=\"rtl\">٥</span> - کتاب المدخل <span class=\"hlight\" dir=\"rtl\">٦</span> - کتاب التشبیه <span class=\"hlight\" dir=\"rtl\">٧</span> - کتاب المنتحل . از ابوسهل ده پسر باقی ماند که نام آنها در کتب و اخبار و اشعار مذکور است . از این خانواده تا اوایل قرن پنجم هجری عده ای علما و محدثین و ادبا و نویسندگان نامی برخاسته اند از قبیل : ابوسهل اسماعیل بن علی اسحاق بن ابی سهل نوبختی که هم در دربار خلیفه منصب داشته و هم در زمان خود رئیس امامیه بوده و با حسین بن منصور حلاج صوفی معروف معارضه داشته و او را مُجاب کرده و در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٣١١</span> هَ .ق . در سن هفتادوچهارسالگی درگذشته است . و ابوجعفر محمد برادر ابوسهل مذکور متصدی کارهای دولتی و ادیب و شاعر بوده است . ابومحمد حسن بن موسی نوبختی از علمای کلام است و بین سال <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> و <span class=\"hlight\" dir=\"rtl\">٣١٠</span> درگذشته است، وی خواهرزاده ٔ ابوسهل ثانی است . ابواسحاق ابراهیم نوبختی که سلسله ٔ نسبش معلوم نیست در اوائل قرن چهارم میزیسته و از متکلمین است و کتابی در علم کلام موسوم بیاقوت از او معروف است . ابوالقاسم حسین بن روح که بعقیده ٔ شیعه نائب سوم امام غائب بوده در سال <span class=\"hlight\" dir=\"rtl\">٣٢٦</span> وفات کرده و پنج سال (<span class=\"hlight\" dir=\"rtl\">٣١٢</span>-<span class=\"hlight\" dir=\"rtl\">٣١٧</span>) بتهمت این که باقرامطه رابطه دارد در حبس بسر برده است . ابوالحسن موسی بن کبریاء از این خاندان در نیمه ٔ اول قرن چهارم از منجمین بشمار آمده است . و ابوالحسن علی بن احمد معروف بابن نوبخت متوفّی به <span class=\"hlight\" dir=\"rtl\">٤١٦</span> شاعری صاحب دیوان است .<br /></font></div>'),
(2023, 'آل و آجیل', '<span class=\"hlight\">آل و آجیل .</span> <font color=\"DarkGreen\"><b>[ ل ُ ]</font></b> (اِ مرکب، از اتباع ) آل آجیل . آجیل و جز آن . آجیل با امثال آن .<br /></font></div>'),
(2024, 'آل و آشوب', '<span class=\"hlight\">آل و آشوب .</span> <font color=\"DarkGreen\"><b>[ ل ُ ]</font></b> (اِ مرکب، از اتباع ) هیاهو. هرج و مرج .<br /></font></div>'),
(2025, 'آل و ادویه', '<span class=\"hlight\">آل و ادویه .</span> <font color=\"DarkGreen\"><b>[ ل ُ اَدْ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (اِ مرکب، از اتباع ) ادویه و جز آن . و از آن فلفل، زردچوبه، دارچین، هیل، میخک، بیخ جوز و امثال آن مراد است .<br /></font></div>'),
(2026, 'آل و اوضاع', '<span class=\"hlight\">آل و اوضاع .</span> <font color=\"DarkGreen\"><b>[ ل ُ اَ <span class=\"hlight\" dir=\"rtl\">/</span>اُو ]</font></b> (اِ مرکب، از اتباع ) فزونیها. زوائد بسیار.<br /></font></div>'),
(2027, 'آل و تبار', '<span class=\"hlight\">آل و تبار.</span> <font color=\"DarkGreen\"><b>[ ل ُ ت َ ]</font></b> (اِ مرکب، از اتباع ) اعقاب و احفاد.<br /></font></div>'),
(2028, 'آل و عطاری', '<span class=\"hlight\">آل و عطاری .</span> <font color=\"DarkGreen\"><b>[ ل ُ ع َطْ طا ]</font></b> (اِ مرکب، از اتباع ) آل عطاری . آخریان و کالای عطاری از حنا و رنگ و قند و فلفل و زردچوبه و دارچین و نخ و سوزن و سنجاق و قندرون و امثال آن . <BR><font color=\"Blue\">◄</font> پیله وری .<br /></font></div>'),
(2029, 'آل کاکویه', '<span class=\"hlight\">آل کاکویه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ی َ ]</font></b> (اِخ ) دیالمه ٔ کردستان که از <span class=\"hlight\" dir=\"rtl\">٣٩٨</span> تا <span class=\"hlight\" dir=\"rtl\">٤٤٣</span> هَ .ق . در همدان ونهاوند فرمانروایی به استقلال داشته اند. مهمترین ایشان علاءالدوله ابوجعفر محمدبن دشمنزیاربن کاکویه پسر خال مجدالدوله ٔ دیلمی و پسرش ظهیرالدین فرامرز علی وبعد از ایشان گرشاسب بن علاءالدوله و ابوحرب بن علاءالدوله است که اولین در همدان و نهاوند و دومین در نطنزحکومت داشته است . و انقراض آنان به دست سلاجقه بود.<br /></font></div>'),
(2030, 'آل کثکثه', '<span class=\"hlight\">آل کثکثه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ک َ ک َ ث َ ]</font></b> (اِخ ) قومی از سکنه ٔ بخارا که اغلب بازرگانان توانگر و محترم بودند. قتیبةبن مسلم پس از فتح بخارا اهالی شهر را فرمود تا یک نیمه از خانه ها و ضیاع خود را بعرب دهند و مقصودش این بود که اهالی با اعراب معاشر و به آداب آنان مأنوس شوند و درصدد طغیان و ارتداد برنیایند. آل کثکثه خانه ها و املاک خود را در شهر بیکباره بعرب گذاشتند و در بیرون شهر هفتصد کوشک برای خود بنا کردند و هرکس بر در کوشک خویش صحرا و بوستانی کرد و گرداگرد آن، خانه ها برای اتباع و چاکران خود بساخت . در تاریخ بخارای نرشخی آمده است که قومی بودند در بخارا که ایشان را کثکثان گفتندی و ایشان مردمانی بودند با حرمت و قدر و منزلت و در میان اهل بخارا ایشان را شرف زیاده بودی، و ایشان از دهقانان نبودند غربا بودند اصیل وبازرگانان بودند و توانگر. (تاریخ بخارای نرشخی ).<br /></font></div>'),
(2031, 'آل کثیر', '<span class=\"hlight\">آل کثیر.</span> <font color=\"DarkGreen\"><b>[ ل ِ ک َ ]</font></b> (اِخ ) نام قبیله ای بخوزستان مرکب از سه هزار خانوار در غرب و جنوب رود دزفول که در سیاه چادرها منزل دارند و در قریه ٔ قومات نیز نزدیک سیصد خانوار از این قبیله ساکن است و این قبیله به تیره های سعد و عنافجه و ضیاغمه و جز آن منشعب میشود. و آنان تا ساحل نهر هاشم یورت دارند.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2032, 'آل کرت', '<span class=\"hlight\">آل کرت .</span><font color=\"DarkGreen\"><b>[ ل ِ ک َ ]</font></b> (اِخ ) طبقه ای از ملوک شرق ایران از نژاد غوریان که از <span class=\"hlight\" dir=\"rtl\">٦٤٣</span> تا <span class=\"hlight\" dir=\"rtl\">٧٩١</span> هَ .ق . حکومت رانده اند و پای تخت آنان هرات بود. سرسلسله ٔ این دودمان شمس الدین محمد دخترزاده ٔ ملک رکن الدین، و او بزمان جدّ خویش رکن الدین یکی از سران سپاه و از مقربین چنگیز بود (<span class=\"hlight\" dir=\"rtl\">٦٤٣</span>-<span class=\"hlight\" dir=\"rtl\">٦٧٦</span>)، و پس از او رکن الدین کهین پسر شمس الدین محمدبجای او نشست (<span class=\"hlight\" dir=\"rtl\">٦٧٧</span>-<span class=\"hlight\" dir=\"rtl\">٧٠٥</span>)، و بعد از رکن الدین کهین پسر او فخرالدین بمقام پدر رسید (<span class=\"hlight\" dir=\"rtl\">٧٠٥</span>-<span class=\"hlight\" dir=\"rtl\">٧٠٦</span>)، چهارمین فرمانروای این سلسله غیاث الدین پسر فخرالدین است (<span class=\"hlight\" dir=\"rtl\">٧٠٧</span>-<span class=\"hlight\" dir=\"rtl\">٧٢٩</span>)، و پنجمین آنان شمس الدین محمد (<span class=\"hlight\" dir=\"rtl\">٧٢٩</span>-<span class=\"hlight\" dir=\"rtl\">٧٣٠</span>)، ششمین ملک حافظ (<span class=\"hlight\" dir=\"rtl\">٧٣٠</span> -<span class=\"hlight\" dir=\"rtl\">٧٣٢</span>)، و هفتمین این دوده معزالدین حسین است (<span class=\"hlight\" dir=\"rtl\">٧٣٢</span>-<span class=\"hlight\" dir=\"rtl\">٧٧١</span>)، و پس از او پسرش غیاث الدین جای پدر گرفت (<span class=\"hlight\" dir=\"rtl\">٧٧١</span>-<span class=\"hlight\" dir=\"rtl\">٧٨٣</span>)، و او را امیرتیمور گورکان مغلوب کرده و با پسر بماوراءالنهر فرستاد و در آنجا در <span class=\"hlight\" dir=\"rtl\">٧٨٧</span>بامر او بقتل رسیدند و سلسله ٔ آل کرت منقرض گردید.<br /></font></div>'),
(2033, 'آل یاسین', '<span class=\"hlight\">آل یاسین .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) آل یس . خاندان رسول صلوات اﷲعلیه <span class=\"hlight\">:</span> <br />چون تو بتی گزیدی کز رنج و شرّ آن بت <br />برکنده گشت و کشته یکرویه آل یاسین ؟<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(2034, 'آل یس', '<span class=\"hlight\">آل یس .</span> <font color=\"DarkGreen\"><b>[ ل ِ یا سین ]</font></b> (اِخ ) آل یاسین . خاندان رسول صلوات اﷲعلیه .<br /></font></div>'),
(2035, 'آلا', '<span class=\"hlight\">آلا.</span> (فرانسوی، حرف اضافه ) در کلماتی که از فرانسه در زبان ما داخل شده چون و مانند و مطابق باشد، چون : آلافرانک، آلانگله، آلاتورک، آلاگارسن و آلامد. لیکن دو کلمه ٔ آلاپلنگی به معنی منقش بخالهای درشت و آلابلبلی به معنی جای رفیع و بلند (چون آشیان بلبل ) در زبان فارسی هست که در صورت و معنی عین «آلا»ی سابق الذکر است و از این رو محتمل است که کلمه ٔ آلا در این دو زبان مشترک باشد.<br /></font></div>'),
(2036, 'آلا', '<span class=\"hlight\">آلا.</span> (ص ) آل . سرخ نیمرنگ . پشت گلی . و در فرهنگها بیت ذیل برای این معنی شاهد آمده است، لیکن صریح در مدعا نیست <span class=\"hlight\">:</span> <br />چو چشم ابر شد آلا و روی گل ناری <br />در آبگون قدح افکن شراب گلناری .<br /> <font color=\"Red\">منصور شیرازی .</font><br /><BR><font color=\"Blue\">◄</font> (اِ) پروا. (تحفةالاحباب اوبهی ).<br /></font></div>'),
(2037, 'آلا', '<span class=\"hlight\">آلا.</span> (اِخ ) نام یکی از آبادیهای سقزکردستان و نام پیشین آن «ایلو» است . (فرهنگستان ).<br /></font></div>'),
(2038, 'آلابلبلی', '<span class=\"hlight\">آلابلبلی .</span> <font color=\"DarkGreen\"><b>[ ب ُ ب ُ ]</font></b> (اِ مرکب ) جائی بلند و رفیع.<br /></font></div>'),
(2039, 'آلابولا', '<span class=\"hlight\">آلابولا.</span> (ص ) (شاید از ترکی ) آلابولا دیدن ؛ درهم و آشفته دیدن چنانکه با چشمی خواب آلود.<br /></font></div>'),
(2040, 'آلات', '<span class=\"hlight\">آلات .</span> (ع اِ) ج ِ آلت . افزارها. ابزارها. ادوات .سازوبرگ . ساز. ساختگی ها. اسباب . سامان <span class=\"hlight\">:</span> <br />سکندر بیامد بدشت نبرد<br />همه خواسته سربسر گرد کرد<br />ز تخت و ز خرگاه و پرده سرای <br />ز فرش وز آلات و از چارپای .<br /> <font color=\"Red\">فردوسی .</font><br />نگه کرد قارن بتورانیان <br />همه ساز و آلات ایرانیان .<br /> <font color=\"Red\">فردوسی .</font><br /> - <span class=\"hlight\">آلات تغذیه </span> ؛ مجموع عضوها که در عمل تغذیه بکار است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات تناسل </span> ؛ عضوها در حیوان از نرینه و مادینه که سبب تولید مثل و نتاج است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات تنفس </span> ؛ اندامها از حنجره و ریه و جز آن که در حیوان وسیله ٔ نفس برآوردن و فروبردن است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات جارحه </span> ؛ افزارهای طبیعی و غیرآن از چنگال و دندان و شمشیر و کارد و جز آن که خستن راست .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات جنگ </span> ؛ آلات رزم . آلات حرب . سلاح <span class=\"hlight\">:</span> <br />بفرمای تا ساز و آلات جنگ <br />بیارند پیشم کنون بیدرنگ .<br /> <font color=\"Red\">فردوسی .</font><br />که برخیز و درپوش آلات رزم <br />که کوتاه کردیم ما جام بزم .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات حیات </span> ؛ آنچه از اعضاء و جز آن که برای دوام زندگی بکار است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات دفاع </span> ؛ آنچه از اعضاء طبیعی و ادوات مصنوع که برای راندن دشمن دارند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات رصدیه </span> ؛ افزارهای علم هیئت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات شکم </span> ؛ حشو.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات صوت </span> ؛ عضوهای تن حیوان که آواز از آنها خیزد، چون شش و گلو و کام و زبان و لب و غیره .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات لهو</span> ؛ افزار نواختن موسیقی و باختن قمار و مانند آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات محرّکه </span> ؛ آنچه در تن حیوان از اعصاب و عضلات و جز آن بکارِ بسط و قبض و حرکت و سکون است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلات موسیقی </span>؛ ابزارهای آن .<br />این کلمه را در تداول فارسی چون علامت جمع در آخر کلمه برای نمودن انواع جنسی آرند، چون : آهن آلات، بلورآلات، ترشی آلات، شیشه آلات و غیره .<br /></font></div>'),
(2041, 'آلات', '<span class=\"hlight\">آلات .</span> (اِخ ) نام شهری از طایفه ٔ نصر، و گفته اند نام دو شهر است .<br /></font></div>'),
(2042, 'آلاتورک', '<span class=\"hlight\">آلاتورک .</span> (فرانسوی، ص مرکب ) چون ترکان بپیرایش موی . <BR><font color=\"Blue\">◄</font> خشن . قسی .<br /></font></div>'),
(2043, 'آلاجق', '<span class=\"hlight\">آلاجق .</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ترکی، اِ) آلاچیق . نوعی از خیمه که از جامه ٔ سطبر و گن-ده کنن-د. <BR><font color=\"Blue\">◄</font> کلبه ها که به صورت خیمه های تاتار باشد.<br /></font></div>'),
(2044, 'آلاجه', '<span class=\"hlight\">آلاجه .</span> <font color=\"DarkGreen\"><b>[ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ ]</font></b> (اِ) بُرد.<br /></font></div>'),
(2045, 'آلاخون والاخون شدن', '<span class=\"hlight\">آلاخون والاخون شدن .</span> <font color=\"DarkGreen\"><b>[ ش ُ دَ ]</font></b> (مص مرکب ) در تداول خانگی، از خانمان خود برافتادن . بی سروسامان گردیدن . دربدر شدن .<br /></font></div>'),
(2046, 'آلاداغ', '<span class=\"hlight\">آلاداغ .</span> (اِخ ) نام کوهی بخراسان در جنوب رود اترک . <BR><font color=\"Blue\">◄</font> نام چند قله و کوه در آسیای صغیر. <BR><font color=\"Blue\">◄</font> نام خُرّه ای از ولایت قونیه .<br /></font></div>'),
(2047, 'آلاس', '<span class=\"hlight\">آلاس .</span> (اِ) زغال . زگال . انگِشت . فحم <span class=\"hlight\">:</span> <br />تاب قهرش تیغ را الماس کرد<br />برق خشمش کوه را آلاس کرد.<br /><font color=\"Red\">سراج الدین راجی .</font><br /></font></div>'),
(2048, 'آلاسکا', '<span class=\"hlight\">آلاسکا.</span> (اِخ ) نام شبه جزیره ای در شمال غربی امریکای شمالی متعلق بدول متحده ٔ امریکای شمالی، دارای <span class=\"hlight\" dir=\"rtl\">٥٥٠٠٠</span> مردم .<br /></font></div>'),
(2049, 'آلاشت', '<span class=\"hlight\">آلاشت .</span> (اِخ ) نام خُرّه ای در ناحیه ٔ ولوپی بسوادکوه مازندران . <BR><font color=\"Blue\">◄</font> نام قریه ٔ بزرگ این خُرّه .<br /></font></div>'),
(2050, 'آلاف', '<span class=\"hlight\">آلاف .</span> (ع اِ) ج ِ اَلْف . هزاران . <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ اِلْف .<br /></font></div>'),
(2051, 'آلافرانک', '<span class=\"hlight\">آلافرانک .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (از فرانسوی، ص مرکب ) آلافرنگ . چون مردم فرانسه از جامه و عادات .<br /></font></div>'),
(2052, 'آلالان', '<span class=\"hlight\">آلالان .</span> (اِخ ) نام مرکز خُرّه ٔ اسالم در طوالش گیلان . <BR><font color=\"Blue\">◄</font> نام رودی میان گرگان رود و شفارود طالش .<br /></font></div>'),
(2053, 'آلاله', '<span class=\"hlight\">آلاله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) شقایق . (برهان ). الاله . لاله، یا لاله ٔ نعمان <span class=\"hlight\">:</span> <br />چون دواتی بُسَدین است خراسانی وار<br />باز کرده سر آلاله بطَرْف ِ چمنا.<br /> <font color=\"Red\">منوچهری .</font><br />و بیت ذیل که لفظاً و معناً صورت دیگر بیت فوق است از همین شاعر مؤید این دعویست <span class=\"hlight\">:</span> <br />بسمن زار درون لاله ٔ نعمان بشیار<br />چون دواتی بُسَدین است خراسانی وار.<br /> <font color=\"Red\">منوچهری .</font><br />یکی برزیگرک دیدم در این دشت <br />بخون دیدگان آلاله می کشت .<br /><font color=\"Red\">باباطاهر.</font><br /></font></div>'),
(2054, 'آلام', '<span class=\"hlight\">آلام .</span> (ع اِ) ج ِ اَلَم . دردها. رنجها.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلام جسمانی </span> ؛ دردها که به تن رسد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلام روحانی </span> ؛ تعب ها که خاطر و روح آزارد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلام نفسانی </span> ؛ کُرَب .<br /></font></div>'),
(2055, 'آلامد', '<span class=\"hlight\">آلامد.</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (فرانسوی، ص مرکب ) بِرَسْم . به آئین . چنانکه باب است .<br /></font></div>'),
(2056, 'آلامل', '<span class=\"hlight\">آلامل .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) مرکز بلوک کوهستان در ناحیه ٔ تنکابن .<br /></font></div>'),
(2057, 'آلاملیک', '<span class=\"hlight\">آلاملیک .</span><font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِ) اَلاملیک . کرم دشتی . سپیدتاک . کرمةالبیضاء. حالق الشَّعر. تاک دشتی . هزارجشان . فاشرا. نخوش .<br /></font></div>'),
(2058, 'آلان', '<span class=\"hlight\">آلان .</span> (اِخ ) نام مملکت و قومی به نزدیکی ارمینیه مشتمل بر قراء کثیره . یاقوت گوید این کشور مجاور دربند است در جبال قفقاز و لقب پادشاه آنجا کنداج است و میان این مملکت و جبال قفقاز قلعه و پلی است بزرگ و قلعه را باب اللان نامند و تا تفلیس چندین روزه راه است . و عرب آن را اَلان گوید. و علان (به عین ) از اغلاط عامه است . (نقل به اختصار از تاج العروس ). و در فارسی آن را اَلان نیز گویند <span class=\"hlight\">:</span> <br />بگرداگرد خرگاه کیانی <br />فروهشته نمدهای الانی <br />و امثله ٔ آلان این است <span class=\"hlight\">:</span> <br />تف تیغ هندیش هندوستانی <br />علی الروس در روس و آلان نماید.<br /> <font color=\"Red\">خاقانی .</font><br />ستیزنده روسی زآلان و ارگ <br />شبیخون درآورد همچون تگرگ .<br /> <font color=\"Red\">نظامی .</font><br />و صاحب برهان گوید آلان نام ولایتی و نام محله ای و بعضی گویند شهری است در ترکستان و نام کوهی هم هست - انتهی . <BR><font color=\"Blue\">◄</font> نام تنگه ای در جنوب سردشت که آبهای بانه و مکری از آن گذشته وارد زاب صغیر میشود. <BR><font color=\"Blue\">◄</font> مرکز خُرّه ٔ آلان برآغوش .<br /></font></div>'),
(2059, 'آلان براغوش', '<span class=\"hlight\">آلان براغوش .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نام خُرّه ای از سراب آذربایجان، وسعت آن سی فرسنگ مربع و دارای بیست وهفت قریه، مرکز آن را آلان نامند. حد شمالی این خرّه مشگین شرقی و جنوبی آن شقاقی و غربی خانمرود است .<br /></font></div>'),
(2060, 'آلان کوه', '<span class=\"hlight\">آلان کوه .</span> (اِخ ) نام کوهی بمغرب دریاچه ٔ خزر.<br /></font></div>'),
(2061, 'آلانان', '<span class=\"hlight\">آلانان .</span> (اِخ ) نام آلان است، چون خزران نام خزر <span class=\"hlight\">:</span> و هرگز هیچکس در آن زمین <font color=\"DarkGreen\"><b>[ روس ]</font></b> نرسیده مگر گشتاسف بفرمان پدرش لهراسف در آن وقت که کیخسرو او را بخزران و آلانان فرستاد. (مجمل التواریخ ).<br /></font></div>'),
(2062, 'آلانقوا', '<span class=\"hlight\">آلانقوا.</span> (اِخ ) نام جدّه ٔ چنگیز.<br /></font></div>'),
(2063, 'آلانک', '<span class=\"hlight\">آلانک .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِ) آلونَک . کوخ . کوخچه . کوله . مجازاً، خانه ٔ محقر.<br /></font></div>'),
(2064, 'آلانگله', '<span class=\"hlight\">آلانگله .</span> <font color=\"DarkGreen\"><b>[ گ ِ ل ِ ]</font></b> (فرانسوی، ص مرکب ) چون انگلیسیان برفتار و جامه و مانند آن .<br /></font></div>'),
(2065, 'آلاو', '<span class=\"hlight\">آلاو.</span> (اِ) اَلاو. اَلَو. آتش شعله ناک . <BR><font color=\"Blue\">◄</font> لهَب . زبانه . شعله <span class=\"hlight\">:</span> <br />بر اوج گنبد گردون از آن بتابد هور<br />که یافت از تف قندیل مرتضی آلاو.<br /><font color=\"Red\">آذری .</font><br /></font></div>'),
(2066, 'آلاوه', '<span class=\"hlight\">آلاوه .</span> <font color=\"DarkGreen\"><b>[ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (اِ) دو پاره چوب که کودکان بدان بازی کنند یکی بلند نزدیک سه بدست و دیگری کوتاه چندِ قبضه ای، و دو سر چوب کوتاه تیز باشد.<br /></font></div>'),
(2067, 'آلاوه', '<span class=\"hlight\">آلاوه .</span> <font color=\"DarkGreen\"><b>[ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (اِ) آلاو. اَلَو <span class=\"hlight\">:</span> <br />ز چشمان آنقدر اخگر ببارم <br />که گیتی سربسر آلاوه گیرد.<br /> <font color=\"Red\">باباطاهر.</font><br /><BR><font color=\"Blue\">◄</font> دیگدان . جائی که در آن آتش روشن کنند. (برهان ).<br /></font></div>'),
(2068, 'آلاپلنگی', '<span class=\"hlight\">آلاپلنگی .</span> <font color=\"DarkGreen\"><b>[ پ َ ل َ ]</font></b> (ص نسبی ) با گلها و خالهای بزرگ چون پوست پلنگ . گل گل .<br /></font></div>'),
(2069, 'آلاچی', '<span class=\"hlight\">آلاچی .</span> (اِ) هیل، و امروز هِل گویند.<br /></font></div>'),
(2070, 'آلاچیق', '<span class=\"hlight\">آلاچیق .</span> (ترکی، اِ) آلاجق . کوخ . کوله . رجوع به آلاجق شود.<br /></font></div>'),
(2071, 'آلاکلنگ', '<span class=\"hlight\">آلاکلنگ .</span> <font color=\"DarkGreen\"><b>[ ک ُ ل َ ]</font></b> (اِ مرکب ) آله کُلو. ذروح . ج، ذراریح .<br /></font></div>'),
(2072, 'آلاکلنگ', '<span class=\"hlight\">آلاکلنگ .</span> <font color=\"DarkGreen\"><b>[ آل ْ لا ک ُ ل َ ]</font></b> (اِ مرکب ) دو چوب برهم نهاده است متقاطع که دو کس بر دو سر چوب زبرین نشینند و بنوبت بزیر و بالا شوند، و این عمل را نیز آلاّکلنگ نامند.<br /></font></div>'),
(2073, 'آلاگارسن', '<span class=\"hlight\">آلاگارسن .</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (فرانسوی، ص مرکب ) (مانند پسر) پیرایش موی در زنان چون مردان .<br /></font></div>'),
(2074, 'آلای', '<span class=\"hlight\">آلای .</span>(نف مرخم ) در کلمات مرکبه مخفف آلاینده <span class=\"hlight\">:</span> <br />نیست بر من روزه در بیماری دل زآن مرا<br />روزه باطل میکند اشک دهان آلای من .<br /> <font color=\"Red\">خاقانی .</font><br />لبش گاهی بخواهش لقمه آلای <br />ولی در زیر لب لخت جگرخای .<br /><font color=\"Red\">طالب آملی .</font><br /></font></div>'),
(2075, 'آلایان', '<span class=\"hlight\">آلایان .</span> (نف، ق ) در حال آلودن .<br /></font></div>'),
(2076, 'آلایش', '<span class=\"hlight\">آلایش .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِمص، اِ) اسم مصدر و فعل آلودن . آلودگی . <BR><font color=\"Blue\">◄</font> مجازاً، فسق . فجور. عیب . (برهان ). تردامنی . ناپاکی <span class=\"hlight\">:</span> <br />از ایشان ترا دل پرآلایش است <br />گناه مرا جای پالایش است .<br /> <font color=\"Red\">فردوسی .</font><br />بران از دو سرچشمه ٔ دیده جوی <br />ور آلایشی داری از خود بشوی .<br /> <font color=\"Red\">سعدی .</font><br />چه آمیزش بغساقش چه آلایش بغسلینش .<br /> <font color=\"Red\">قاآنی .</font><br /><BR><font color=\"Blue\">◄</font> در تداول امروزین، دَین . وام . بدهکاری . <BR><font color=\"Blue\">◄</font> عادت های زشت، چون عادت به افیون یا شراب . رجوع به بی آلایش شود.<br /></font></div>'),
(2077, 'آلایش ناک', '<span class=\"hlight\">آلایش ناک .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ص مرکب ) دارای آلایش . آلوده <span class=\"hlight\">:</span> <br />مبر آنجا دل آلایشناک <br />صحبت پاک نیابد جز پاک .<br /><font color=\"Red\">جامی .</font><br /></font></div>'),
(2078, 'آلاینده', '<span class=\"hlight\">آلاینده .</span> <font color=\"DarkGreen\"><b>[ ی َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه آلاید.<br /></font></div>'),
(2079, 'آلاییدن', '<span class=\"hlight\">آلاییدن .</span> <font color=\"DarkGreen\"><b>[ دَ]</font></b> (مص ) در بعض فرهنگها بدان معنی ِ آلودن داده اند.<br /></font></div>'),
(2080, 'آلب', '<span class=\"hlight\">آلب .</span> <font color=\"DarkGreen\"><b>[ آل ْب ْ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ترکی، ص ) بترکی قدیم، دلیر. پهلوان . و جزء نخستین بعض اعلام مرکبه ٔ ترکانست، چون آلب ارغون، آلب ارسلان، آلب تگین، و آن را اَلْب نیز گویند.<br /></font></div>'),
(2081, 'آلب', '<span class=\"hlight\">آلب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) گِردکننده . (مهذب الاسماء).<br /></font></div>'),
(2082, 'آلب ارسلان', '<span class=\"hlight\">آلب ارسلان .</span> <font color=\"DarkGreen\"><b>[ اَ س َ ]</font></b> (اِخ ) محمدبن داود میکائیل بن سلجوق . دومین ِ پادشاهان سلجوقی ایران . در سال <span class=\"hlight\" dir=\"rtl\">٤٥٣</span> هَ .ق . بجای پدر خویش داود معروف بجغری بیک والی خراسان شد و دو سال بعد (<span class=\"hlight\" dir=\"rtl\">٤٥٥</span>) بجای عم پادشاهی یافت . وی پادشاهی دلیر و دادگر و جنگجوی بود. مملکت را از یک سو تا حدود چین و از سوی دیگر تا حدود روم بسط داد و در سال <span class=\"hlight\" dir=\"rtl\">٤٦٥</span>با امپراطور روم (دیوژن رومان ) در ملازگرد جنگ کرد واو را مغلوب و اسیر کرد و از آن پس بجانب جیحون شتافت و در آنجا بر دست یوسف نامی از مردم خوارزم مجروح و مقتول گردید (<span class=\"hlight\" dir=\"rtl\">٤٦٥</span>). مدت پادشاهی او نُه سال بود.<br /></font></div>'),
(2083, 'آلب ارغون', '<span class=\"hlight\">آلب ارغون .</span> <font color=\"DarkGreen\"><b>[ ل ِاَ ]</font></b> (اِخ ) چهارمین فرمانروا از سلسله ٔ اتابکان لرستان . هلاکو پس از فتح بغداد برادر او تکله را بکشت و او را حکومت لرستان داد، و او پانزده سال با حسن سیاست و تدبیر فرمان راند و در سال <span class=\"hlight\" dir=\"rtl\">٦٧٣</span> هَ .ق . بمرد.<br /></font></div>'),
(2084, 'آلب تکین', '<span class=\"hlight\">آلب تکین .</span> <font color=\"DarkGreen\"><b>[ ل ِ ت َ ]</font></b> (اِخ ) آلب تگین . اَلب تکین . نام یکی ازامراء آل بویه . او در بغداد در جنگ با عزالدوله بختیار مغلوب گردیده بشام گریخت و شام را از ریّان عامل خلفای فاطمی انتزاع کرد و چندی بدانجای فرمان راند تا آنگاه که عزیز فاطمی بدان صوب لشکر کشید و او را بشکست و به اسارت بمصر برد و در آنجا به سال <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> هَ .ق . او را بسم بکشتند. <BR><font color=\"Blue\">◄</font> نام مؤسس سلسله ٔ غزنویان . او در سال <span class=\"hlight\" dir=\"rtl\">٣٥١</span> هَ .ق . غزنه را بگشاد و دعوی استقلال کرد. پس از وی سبکتکین پدر محمود غزنوی که از ممالیک و امرای لشکر او بود حکومت غزنه یافت .<br /></font></div>'),
(2085, 'آلباتنیوس', '<span class=\"hlight\">آلباتنیوس .</span> (اِخ ) آلباتنیی . مصحّف نام محمدبن جابربن سنان البتانی، نزد اروپائیان .<br /></font></div>'),
(2086, 'آلباق', '<span class=\"hlight\">آلباق .</span> (اِخ ) (دره ٔ...) نام دره ای است که خط سرحدی ایران و ترکیه از مشرق آن بامتداد رشته ٔ جبال کشیده میشود، میان گردنه ٔ کیکان و قله ٔ هراویل .<br /></font></div>'),
(2087, 'آلبالو', '<span class=\"hlight\">آلبالو.</span> (اِ) آلبالی . آلوبالو. قسمی گیلاس که میوه ٔ آن سرخ و ترش است . قراصیا . جراسیا. قاراسیا. آلوی ابوعلی . نمتک .<br /></font></div>'),
(2088, 'آلبالوپلو', '<span class=\"hlight\">آلبالوپلو.</span> <font color=\"DarkGreen\"><b>[ پ ُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> لُو ]</font></b> (اِ مرکب ) قسمی پلو که چاشنی آن آلبالو کنند.<br /></font></div>'),
(2089, 'آلبالی', '<span class=\"hlight\">آلبالی .</span> (اِ) آلبالو.<br /></font></div>'),
(2090, 'آلبانی', '<span class=\"hlight\">آلبانی .</span> (اِخ ) آلبانیا. نام دولتی کوچک از بالکان بساحل آدریاتیک با <span class=\"hlight\" dir=\"rtl\">٨٣١٠٠٠</span> مردم، و از شهرهای بزرگ آن اسکوتاری و دوراتسو (دورِس ) است . این مملکت از سال <span class=\"hlight\" dir=\"rtl\">١٩١٢</span> م . مستقل شده است . زبان این قوم شعبه ای از زبانهای آریائیست . و ارناوود نام دیگر این قوم است .<br /></font></div>'),
(2091, 'آلبانی', '<span class=\"hlight\">آلبانی .</span> (اِخ ) نام ایالتی قدیم از قفقاز بجائی که امروز شیروان و لگزستان و داغستان واقع است، و در زمان ساسانیها یکی از چترپتی های ایران بشمار می آمده، و آن را آگووانی نیز میگفتند.<br /></font></div>'),
(2092, 'آلبغبش', '<span class=\"hlight\">آلبغبش .</span> <font color=\"DarkGreen\"><b>[ ب َ ب ِ ]</font></b> (اِخ ) نام تیره ای از قبیله ٔ بنی کعب از طوایف خوزستان .<br /></font></div>'),
(2093, 'آلبوانس', '<span class=\"hlight\">آلبوانس .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (اِخ ) تصحیف نام ابوالحسن بن ابی الرجال، نزد اروپائیان .<br /></font></div>'),
(2094, 'آلبوهازن', '<span class=\"hlight\">آلبوهازن .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِخ ) تصحیف نام ابوالحسن بن ابی الرجال، نزد اروپائیان .<br /></font></div>'),
(2095, 'آلبوکازیس', '<span class=\"hlight\">آلبوکازیس .</span> (اِخ ) تصحیف نام ابوالقاسم خلف بن عباس طبیب قرطبی است نزد اروپائیان . و او صاحب کتاب التصریف در طب و جراحی است .<br /></font></div>'),
(2096, 'آلبوکرک', '<span class=\"hlight\">آلبوکرک .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (اِخ ) آلفونسو دُ. نام ملاحی پرتقالی . او در <span class=\"hlight\" dir=\"rtl\">٩١٣</span> هَ .ق . جزیره ٔ هرمز را متصرف شد و در <span class=\"hlight\" dir=\"rtl\">١٠٣٢</span> هَ .ق . شاه عباس پرتقالیان را از آنجا براند.<br /></font></div>'),
(2097, 'آلبی ین', '<span class=\"hlight\">آلبی ین .</span> <font color=\"DarkGreen\"><b>[ یُن ْ ]</font></b> (اِخ ) (از لاطینی ِ آلبوس، سفید) نامی است که شعرابه انگلستان دهند به مناسبت به سپیدی زدن صخره های آن از دور یا به مناسبت آلبی ین پسر نبطون . و آلبی یُن دَغَل یا غدّار، سیاست خودخواه انگلیسان را گویند.<br /></font></div>'),
(2098, 'آلت', '<span class=\"hlight\">آلت .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِ) آله . واسطه ٔ میان فاعل و مفعول در رسیدن اثر، چون اره برای نجار. افزار. ابزار. دست افزار. (مهذب الاسماء). ساز کار. ساز. (زمخشری ). ادات . ساز دست <span class=\"hlight\">:</span> <br />ببازار شد مشک و آلت ببرد<br />گروکان به پرمایه مردی سپرد.<br /> <font color=\"Red\">فردوسی .</font><br />هیونی جدا زآلت بزم و خوان <br />ز زرّینه هم برد با خود جوان .<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود شاه دلاور بدوی <br />که رو آلت بزم شاهی بجوی .<br /> <font color=\"Red\">فردوسی .</font><br />گر ایدون که دهقان بدی تنگدست <br />سوی نیستی گشته کارش ز هست <br />بدادی ز گنج آلت و چارپای <br />نماندی که پایش برفتی ز جای .<br /> <font color=\"Red\">فردوسی .</font><br />دوسیصد هیون کرد در زیر بار<br />همه زآلت بزم وز کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />خواجه ٔ بزرگ گفته بود که از وی وجیه تر مردی و پیری نیست و آلت و عُدّت و مردم و غلامان دارد. (تاریخ بیهقی ). طاهر تجملی و آلتی سخت تمام داشت . (تاریخ بیهقی ). رمادی ... خویشتن را برابر ابوالحسن سیمجور داشتی بحشمت و آلت و عُدّت . (تاریخ بیهقی ). او را فروگرفتند و ستوران و سلاح و تجمل و آلت ... غارت کردند. (تاریخ بیهقی ).<br />کز همه حالتی مرا نظمی است <br />وز همه آلتی مرا جانیست .<br /> <font color=\"Red\">مسعودسعد.</font><br />هر کو بغذی مغز شتر خورده نباشد<br />آلت ز پی شیشه زدودن تَبَر آرد.<br /> <font color=\"Red\">اثیر اخسیکتی .</font><br />نفس اژدرها است او کی مرده است <br />از غم بی آلتی افسرده است .<br /> <font color=\"Red\">مولوی .</font><br />چوب حق و پشت وپهلو آن ِ او<br />من غلام و آلت فرمان ِ او.<br /> <font color=\"Red\">مولوی .</font><br />نسبتی باید مرا یا حیلتی <br />هیچ پیشه راست شد بی آلتی ؟<br /> <font color=\"Red\">مولوی .</font><br />آلت زرگر به دست کفشگر<br />همچو دانه کشت کرده ریگ در<br />وآلت اسکاف پیش برزگر<br />پیش سگ که استخوان در پیش خر.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> عضو <span class=\"hlight\">:</span> <br />بدین آلت و رای و جان و روان <br />ستود آفریننده را کی توان ؟<br /> <font color=\"Red\">فردوسی .</font><br />دل و مغز مردم دو شاه تنند<br />دگر آلت تن سپاه تنند.<br /> <font color=\"Red\">فردوسی .</font><br />تنت آینه ساز و هر دو جهان <br />ببین اندر او آشکار و نهان <br />هر آلت که باید بداد است نیز<br />بهانه بیزدان نمانده ست چیز.<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> زین و برگ . یراق اسب <span class=\"hlight\">:</span> <br />بیاورد پس جامه ٔ پهلوی <br />یکی اسب با آلت خسروی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مجازاً، مایه . وسیلت . سبب <span class=\"hlight\">:</span> <br />جهان پرشگفتی است چون بنگری <br />ندارد کسی آلت داوری .<br /> <font color=\"Red\">فردوسی .</font><br />زمانه ز ما نیست چون بنگری <br />ندارد کسی آلت داوری .<br /> <font color=\"Red\">فردوسی .</font><br />و برحسب این سخن میتوان شناخت که آلت جهان گیری مال است . (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> ستون خیمه . دیرک چادر. <BR><font color=\"Blue\">◄</font> شدت و سختی . <BR><font color=\"Blue\">◄</font> حالت . <BR><font color=\"Blue\">◄</font> سریرالمیت . جنازه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلت، آلت تناسل </span> ؛ شرم اندام مرد و زن . قُبُل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلت جرم </span> ؛ آنچه از وسائط، مجرم برای اجرای جرم بکار برده، چون کارد و چوب و طپانچه (نوعی اسلحه ٔ گرم ) و تفنگ و جز آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلت جنگ، آلت رزم، آلت سپاه، آلت کارزار، آلت لشکر</span> ؛ سلاح . سلیح <span class=\"hlight\">:</span> <br />دوباره ز لشکر هزاران هزار<br />سپه بود با آلت کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />سیاوش بدان آلت و فرّ و برز<br />بدان ایزدی دست و آن تیغ و گرز...<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت کاینجا بمانید بار<br />مدارید جز آلت کارزار.<br /><font color=\"Red\">فردوسی .</font><br />فَرُخ زاد برگشت نزدیک شاه <br />پر از گَرد با آلت رزمگاه .<br /> <font color=\"Red\">فردوسی .</font><br />نخست آلت جنگ را دست برد<br />در نام جستن بگردان سپرد.<br /> <font color=\"Red\">فردوسی .</font><br />از آن بار چیزی که اندرخور است <br />همه گوهر و آلت لشکر است .<br /> <font color=\"Red\">فردوسی .</font><br />خروشی برآمد ز لشکر بزار<br />فروریختند آلت کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />همه رزمگه پر ستام و کمر<br />پر از آلت لشکر و سیم و زر.<br /> <font color=\"Red\">فردوسی .</font><br />یکی نامور بود نامش تباک <br />ابا آلت و لشکر و رای پاک .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت شیرین که ای شهریار<br />بدشمن <font color=\"DarkGreen\"><b>[ کردیه ]</font></b> دهی آلت کارزار<br />که خون برادر بیاد آورد<br />بترسم که کارت بباد آورد.<br /> <font color=\"Red\">فردوسی .</font><br />ز شاه کیان خواستند زینهار<br />فروریختند آلت کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد دلی شاد بِبْهشت گنگ <br />ابا آلت لشکر و ساز جنگ .<br /> <font color=\"Red\">فردوسی .</font><br />پسر هفت با تیغزن ده هزار<br />همان گنج و هم آلت کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />گزین کرد از ایرانیان صدهزار<br />که بودند با آلت کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />همه آلت لشکر و ساز جنگ <br />ببردند نزدیک پور پشنگ .<br /> <font color=\"Red\">فردوسی .</font><br />شرط آن است که ... دوهزار غلام آراسته با ساز و آلت تمام ... به نزدیک ما فرستاده آید. (تاریخ بیهقی ). از آن شرح کردن نباید که بمعاینه حالت و حشمت و آلت ... وی <font color=\"DarkGreen\"><b>[ یعنی محمود ]</font></b> دیده آمده است . (تاریخ بیهقی ). نیمه ٔ ماه بهرات آمد سخت با شکوه و آلت و حشمت تمام . (تاریخ بیهقی ).<br />هیون دوکوهه دگر شش هزار<br />همه بارشان آلت کارزار.<br /> <font color=\"Red\">اسدی .</font><br />چون مرد جنگ را نبود آلت <br />حیلت گریز باشد ناچاره .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بدان بکوش که گردنْت را گشاده کند<br />کنون که با حشر و آلت اندرین حبسی .<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلت حرکت </span> ؛ عضله و عصب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلت ذات الحلق </span> ؛ نام ابزاری است نزد هیئت شناسان قدیم، مرکب از دو حلقه ٔ افقی و عمودی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلت رجولیت </span> ؛ شرم اندام مرد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلت زبان، آلت اللسان </span>؛ مجموع غده های زیر زبان که آب دهان از آن ترابد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلت شکره </span> ؛ آنچه نخجیرگیران و صیادان دارند از دام و تیر و کمان و کمانگروهه و جز آن <span class=\"hlight\">:</span> <br />با غلامان و آلت شکره <br />کرد کار شکار و کار سره .<br /> <font color=\"Red\">عنصری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلت طرب </span> ؛ ساز و هر چیز که نوازند طرب را. آلت موسیقی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلت (آلت دست ) کسی شدن </span> ؛ برای نفع او غالباً بضرر و زیان خود بکار رفتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلت لعاب </span> ؛ آلت زبان، یعنی غده های زیر زبان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">ز بی آلتان کار ناید درست </span> .<br /> <font color=\"Red\">نظامی .</font><br />هرکه را بیش حاجت آلت بیش .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(2099, 'آلت', '<span class=\"hlight\">آلت .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ) هر یک از قطعات چوب باریک تراشیده بدرازا با درز و شکاف که در در و پنجره و قاب سقف بکار برند چون فاصله ٔ میان دو صفحه یا دو لغت یا دو شیشه و چهارسوی لغت یا شیشه را در درزهای آن استوار کنند.<br /></font></div>'),
(2100, 'آلت تراش', '<span class=\"hlight\">آلت تراش .</span> <font color=\"DarkGreen\"><b>[ ل َت ْ، ت َ ]</font></b> (نف مرکب ) آنکه آلت در و پنجره و جز آن تراشد. رجوع به آلت شود.<br /></font></div>'),
(2101, 'آلتن', '<span class=\"hlight\">آلتن .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) نامی است که ترکان بکشاورزی ایرانی موسوم به یحیی متولد بسال <span class=\"hlight\" dir=\"rtl\">١١٢٠</span> هَ .ق . داده اند. در یکی از جنگهای ایران با عثمانیان، ترکان یحیی را به اسارت به آسیای صغیر برده و چون بردگان بفروختند. او پس از چندی از جور ترکان به مارسی گریخت .در این وقت زبردستی ایرانیان در دَهقنت و پرورش حیوانات اهلی و کرم پیله شهرتی عالمگیر داشت . از این رو اولیای امور فرانسه مقدم این برزگر ایرانی را گرامی داشتند، تا آنجا که نزد لوئی پانزدهم بار یافت و پادشاه او را به اصلاح زراعت فرانسه و تربیت کرم ابریشم فرمان داد، لکن از جانب دولت در مساعدتهای لازمه ٔ این مأموریت اهمال رفت و او با دستی تهی تعب طلب را برخویش هموار کرد و در سایه ٔ کوشش و اتکاء بنفس در نواحی اوین یُن با بذری که از ایران آورد بامتحان زرع روناس پرداخت و از پای ننشست تا تخمها ببار و شاهد مقصود بکنار آمد. لکن قدر یحیی در زندگی مجهول ماند و عمرش با فاقه و فقر در <span class=\"hlight\" dir=\"rtl\">١١٨٧</span> سپری گشت و دختر یگانه ٔ او نیز در <span class=\"hlight\" dir=\"rtl\">١٢٣٦</span> در بیمارستان عمومی درگذشت . فرانسویان بپاس خدمات او <span class=\"hlight\" dir=\"rtl\">٧٥</span> سال بعد در <span class=\"hlight\" dir=\"rtl\">١٢٦٢</span> هَ .ق . مجسمه ٔ او را ریخته و بر صخره ٔ نتردام دِ دُم برافراشتند.<br /></font></div>'),
(2102, 'آلتون', '<span class=\"hlight\">آلتون .</span> (ترکی، اِ) زر. ذَهَب <span class=\"hlight\">:</span> <br />تو همی سوز این ضعیفان را که هین جامه بکش <br />تو همی زن این یتیمان را که هان آلتون بیار.<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> نامی از نامهای اماء و کنیزکان ترک <span class=\"hlight\">:</span> <br />طاس و مندیل و گِل از آلتون بگیر<br />تا بگرمابه رویم ای ناگزیر.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(2103, 'آلتون بیلکا', '<span class=\"hlight\">آلتون بیلکا.</span> (ترکی، اِ مرکب ) منشور و نشان یا منشور زرنشان .<br /></font></div>'),
(2104, 'آلتون تاش', '<span class=\"hlight\">آلتون تاش .</span> (اِخ ) نام حاجب سلطان محمود غزنوی، و او پس از فتح خوارزم و قلع و قمع مأمونیان (<span class=\"hlight\" dir=\"rtl\">٤٠٧</span> هَ .ق .) بفرمان سلطان حکومت و امارت خوارزم داشت و بعهد مسعود در <span class=\"hlight\" dir=\"rtl\">٤٢٣</span> در جنگ با علی تکین کشته شد.<br /></font></div>'),
(2105, 'آلتون تمغا', '<span class=\"hlight\">آلتون تمغا.</span> <font color=\"DarkGreen\"><b>[ تو ت َ ]</font></b> (ترکی، اِ مرکب ) آلتون بیلکا. منشور زرنشان .<br /></font></div>'),
(2106, 'آلتون سو', '<span class=\"hlight\">آلتون سو.</span>(اِخ ) نامی که ترکان عثمانی به زاب صغیر داده اند.<br /></font></div>'),
(2107, 'آلتون کپری', '<span class=\"hlight\">آلتون کپری .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) (از: ترکی ِ آلتون، زَر + کپری، پُل ) نام موضعی در کردستان در جزیره از زاب صغیر، رافده و آبراهه ٔ دجله، میان راه بغداد بموصل . و اینجاست که امتعه و اجناسی را که با شتراز کردستان جنوبی حمل شده بر کشتی به بغداد برند.<br /></font></div>'),
(2108, 'آلتی آچلان', '<span class=\"hlight\">آلتی آچلان .</span> <font color=\"DarkGreen\"><b>[ چ ِ ]</font></b> (ترکی، اِ مرکب ) ششلول . طپانچه که شش تیر گشاد تواند داد با یک بار پر کردن .<br /></font></div>'),
(2109, 'آلج', '<span class=\"hlight\">آلج .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِ) زعرور. آلوج . آژدف . (زمخشری ).<br /></font></div>'),
(2110, 'آلر', '<span class=\"hlight\">آلر.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ) سرین . آلست . آرست <span class=\"hlight\">:</span> <br />بیکی گرم تپانچه که بر آن آلر تو <br />بزدم جنگ چه سازی چه کنی بانگ و ژغار؟<br /> <font color=\"Red\">ابوالمثل بخاری .</font><br />بینی آن جزبن اندام تو و آلر تو<br />جان من باد فدای پدر و مادر تو.<br /> <font color=\"Red\">طیان .</font><br />ندیده دیده ٔ دنیا که دلبری دارد<br />سفید و نازک و فربه که آلرت باشد .<br /> <font color=\"Red\">عبید زاکانی .</font><br />و رجوع به اَلر شود.<br /></font></div>'),
(2111, 'آلس', '<span class=\"hlight\">آلس .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) نام شهری ببلاد روم نزدیک بدریا بیک روزه راه از طرسوس .<br /></font></div>'),
(2112, 'آلست', '<span class=\"hlight\">آلست .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ) سُرین . آلر. آرست <span class=\"hlight\">:</span> <br />همچون رطب اندام و چو روغنْش سراپای <br />همچون شبه زلفین و چو پیلسته ش آلست .<br /> <font color=\"Red\">عسجدی .</font><br />در بعض فرهنگها بکلمه معنی اِست نیز داده اند.<br /></font></div>'),
(2113, 'آلسن', '<span class=\"hlight\">آلسن .</span> <font color=\"DarkGreen\"><b>[ ل ُ س ُ ]</font></b> (از یونانی، اِ) (از یونانی آلوسُن به معنی مبرّی الکلب، از آنرو که بگمان قدما او زهر سگ دیوانه را علاج میکرده است ) نباتیست ساقش بدرازی زرعی و شبیه ببرگ فراسیون و از آن درشت تر و خارناک و مابین سرخی و سیاهی و تخم آن بپهنی مایل است و رنگش سبز و تیره و در غلاف دوطبقه، و از ترمس کوچکتر و در طعم و تندی و تلخی نانخواه و گلش سرخ مایل به تیرگی و از زیر برگها روید. و مؤلف جامعالادویه از محمدبن احمد نقل کند که این گیاه در شام بسیار است و آن را حشیشةالسلحفاة نامند. و چون این گیاه را قدما در بیماری هاری بکار می بردند آن را شجرةالکلب نیز گفته اند.<br /></font></div>'),
(2114, 'آلش', '<span class=\"hlight\">آلش .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ترکی، اِمص ) تبدیل . تعویض .<br /></font></div>'),
(2115, 'آلش', '<span class=\"hlight\">آلش .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) نام شهری به اندُلس .<br /></font></div>'),
(2116, 'آلش', '<span class=\"hlight\">آلش .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِ) نبع. بشجیر . نام درختی است جنگلی و چوب آن در نجاری بکار است و در قدیم از آن کمان کردندی .<br /></font></div>'),
(2117, 'آلش دگش', '<span class=\"hlight\">آلش دگش .</span> <font color=\"DarkGreen\"><b>[ ل ِ دَ گ ِ ]</font></b> (ترکی، اِمص مرکب، از اتباع ) مبادله . معاوضه . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) کن و واکن . شور واشور.<br /></font></div>'),
(2118, 'آلشتر', '<span class=\"hlight\">آلشتر.</span> <font color=\"DarkGreen\"><b>[ ل ِ ت َ ]</font></b> (اِخ ) نام رودی، و آن یکی از روافد و آبراهه های کشکانرود است . و آن را اَلشتر نیز گویند.<br /></font></div>'),
(2119, 'آلغدن', '<span class=\"hlight\">آلغدن .</span> <font color=\"DarkGreen\"><b>[ ل ُ دَ ]</font></b> (مص ) آرغدن . خشم گرفتن .<br /></font></div>'),
(2120, 'آلغده', '<span class=\"hlight\">آلغده .</span> <font color=\"DarkGreen\"><b>[ ل ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آرُغده . ارغنده . خشم گرفته . قهرآلود. خشمگین . جنگ آور <span class=\"hlight\">:</span> <br />شیر خشم آورد و جست از جای خویش <br />آمد آن خرگوش را آلغده پیش .<br /> <font color=\"Red\">رودکی .</font><br />شیر آلغده که بیرون جهد از خانه بصید<br />تا بچنگ آورد آهو را وآهوبره را.<br /><font color=\"Red\">رودکی .</font><br /></font></div>'),
(2121, 'آلغو', '<span class=\"hlight\">آلغو.</span> (اِخ ) نام محلی کنار راه تبریز و مراغه میان شورکول و روشت در <span class=\"hlight\" dir=\"rtl\">١١٣٥٠٠</span>گزی تبریز.<br /></font></div>'),
(2122, 'آلغونه', '<span class=\"hlight\">آلغونه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) آلگونه . گلگونه . سرخی باشد که زنان درروی مالند زینت را. غازه . سرخی . سرخاب <span class=\"hlight\">:</span> <br />آن بناگوش لعلگون گوئی <br />برنهاده ست آلغونه بسیم .<br /> <font color=\"Red\">شهید.</font><br />رو که را در نبرد گردد زرد<br />سرخ رویش به آلغونه کنند.<br /> <font color=\"Red\">منجیک .</font><br /><BR><font color=\"Blue\">◄</font> در بعض فرهنگها باین کلمه معنی آمیخته نیز داده اند.<br /></font></div>'),
(2123, 'آلف', '<span class=\"hlight\">آلف .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) خوگیرنده . خوگر. الیف . <BR><font color=\"Blue\">◄</font> هزاردهنده . ج، اُلاّ ف .<br /></font></div>'),
(2124, 'آلفات', '<span class=\"hlight\">آلفات .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص، اِ) ج ِ آلِفه .<br /></font></div>'),
(2125, 'آلفتن', '<span class=\"hlight\">آلفتن .</span> <font color=\"DarkGreen\"><b>[ ل ُ ت َ ]</font></b> (مص ) آشفتن . مشوش کردن . پریشان ساختن .<br /></font></div>'),
(2126, 'آلفته', '<span class=\"hlight\">آلفته .</span> <font color=\"DarkGreen\"><b>[ ل ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آشفته . پریشان . شوریده . مشوّش . <BR><font color=\"Blue\">◄</font> درویش . بی نوا .<br /></font></div>'),
(2127, 'آلفنس', '<span class=\"hlight\">آلفنس .</span> <font color=\"DarkGreen\"><b>[ ف ُ ]</font></b> (اِخ ) آلفونس . رجوع به ادفونس شود.<br /></font></div>'),
(2128, 'آلفه', '<span class=\"hlight\">آلفه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ف َ ]</font></b> (ع ص ) تأنیث آلف . خوگر. خوگیرنده . ج، آلفات، اوالف .<br /></font></div>'),
(2129, 'آلمالو', '<span class=\"hlight\">آلمالو.</span> (اِخ ) نام محلی کنار راه زنجان به میانه میان نیک پی و اغمزاز در <span class=\"hlight\" dir=\"rtl\">٤٦٤٨٠٠</span>گزی طهران .<br /></font></div>'),
(2130, 'آلمان', '<span class=\"hlight\">آلمان .</span> (اِخ ) آلمانْی . آلمانی . (دمشقی ). نام مملکتی به اروپای مرکزی . حدّ شمالی آن دریای شمال و شبه جزیره ٔ دانمارک و دریای بالتیک و حدّ شرقی، لهستان و حد جنوبی، کشورهای چِکُسلواکی و مجارستان و ایتالیا و سویس و حدّ غربی، هلند و بلژیک و لوگزامبورک وفرانسه میباشد. وسعت سابق آن <span class=\"hlight\" dir=\"rtl\">٤٧٢٠٣٤</span> کیلومتر مربع با <span class=\"hlight\" dir=\"rtl\">٦٦</span>میلیون سکنه بوده است ولی از <span class=\"hlight\" dir=\"rtl\">١٩٣٥</span> م . ببعد به تدریج بر وسعت خاک خود افزوده و ناحیه ٔ سار و کشور اطریش و قسمتی از چِکُسلواکی و قسمتی از لهستان را تصرف کرده است و مساحت کنونی آن به <span class=\"hlight\" dir=\"rtl\">٥٨٣٢٨٠</span> کیلومتر مربع و جمعیّت آن به <span class=\"hlight\" dir=\"rtl\">٧٤</span>میلیون میرسد. کرسی آن شهر بِرْلین (بِرْلَن ) دارای <span class=\"hlight\" dir=\"rtl\">٤٢٥٠٠٠٠</span> سکنه است و یکی از بزرگترین شهرهای صنعتی و سیاسی و علمی و تجارتی آلمان بشمار میرود. کشور آلمان تا سال <span class=\"hlight\" dir=\"rtl\">١٨٧١</span> م . از کشورهای کوچکی که هر یک صاحب استقلال بودند تشکیل میشد ولی در این سال ویلهِلْم اوّل بدستیاری صدراعظم خود بیسمارک موفق گردید دولت های مزبور را متّحد ساخته و امپراطوری بزرگ آلمان را تأسیس کند. حکومت آلمان تا پایان جنگ <span class=\"hlight\" dir=\"rtl\">١٩١٤</span> م . مشروطه ٔ متّحده بود ولی پس از جنگ (<span class=\"hlight\" dir=\"rtl\">١٩١٨</span>) حکومت مشروطه ٔ آن به جمهوری مرکّب از <span class=\"hlight\" dir=\"rtl\">١٦</span> دولت تبدیل شد.<br /></font></div>'),
(2131, 'آلن', '<span class=\"hlight\">آلن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام طایفه ای که در حوالی بحر خزر ساکن بوده اند. (التدوین ).<br /></font></div>'),
(2132, 'آلنج', '<span class=\"hlight\">آلنج .</span> <font color=\"DarkGreen\"><b>[ ل ُ ]</font></b> (اِ) آلوچه .<br /></font></div>'),
(2133, 'آلنگ', '<span class=\"hlight\">آلنگ .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ) مورچال . گوی که در اطراف قلعه، گاه محاصره و تسخیر آن حفر کنند. <BR><font color=\"Blue\">◄</font> دیواری که برای حفظ سپاه کشند. سنگر. <BR><font color=\"Blue\">◄</font> حاجز و حوالی که سازند حفظ قلعه را. <BR><font color=\"Blue\">◄</font> جمعی از سپاهی که در اطراف قلعه برای تسخیر آن جابجای گمارند. <BR><font color=\"Blue\">◄</font> جمعی از مردم که در درون قلعه برای حراست آن جای بجای معین کنند.<br /></font></div>'),
(2134, 'آلنگ و دولنگ', '<span class=\"hlight\">آلنگ ودولنگ .</span> <font color=\"DarkGreen\"><b>[ ل َ گ ُ دُ ل َ ]</font></b> (اِ مرکب، از اتباع ) در تداول عامه، اسباب و آلات و غالباً زاید و فضول .<br /></font></div>'),
(2135, 'آله', '<span class=\"hlight\">آله .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِ) آلت <span class=\"hlight\">:</span> <br />یکی اسب ترکی بیاورد پیش <br />بر آن اسب آله ز اندازه بیش .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> نیزه ٔ سخت کوتاه . نیم نیزه . و رجوع به آلت شود.<br /></font></div>'),
(2136, 'آله', '<span class=\"hlight\">آله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (پسوند) َاله . در ترشاله، تفاله، چاله، چغاله، درغاله، دنباله، سکاله، کشاله، کلاله، کنغاله، کنگاله، گاله و مچاله مانند آل (َال ) علامت نسبت و گاهی ادات تشبیه است . رجوع به آل شود.<br /></font></div>'),
(2137, 'آله', '<span class=\"hlight\">آله .</span> <font color=\"DarkGreen\"><b>[ ل ُه ْ ]</font></b> (اِ)عقاب . (مهذب الاسماء). خداریه . شقواء. ابوالهیثم . بوالهیثم . دال من . ججا. زمج . و کلمه ٔ اَلَموت را گویند در اصل مرکب از آله به معنی عقاب و آموت آشیان است .<br /></font></div>'),
(2138, 'آله', '<span class=\"hlight\">آله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) آلک . سنبل الطیب .<br /></font></div>'),
(2139, 'آله کلو', '<span class=\"hlight\">آله کلو.</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ک ُ ]</font></b> (اِ مرکب ) آلاکلنگ . ذَراریح، و آن جانوری است مانند زنبور سرخ و از او باریکتر و نقطه های سیاه دارد. (ریاض الادویه ).<br /></font></div>'),
(2140, 'آلهه', '<span class=\"hlight\">آلهه .</span> <font color=\"DarkGreen\"><b>[ ل ِ هََ ]</font></b> (ع اِ) ج ِ اِله . (ربنجنی ). خدایان . ارباب .<br /></font></div>'),
(2141, 'آلهه پرست', '<span class=\"hlight\">آلهه پرست .</span> <font color=\"DarkGreen\"><b>[ ل ِ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ پ َ رَ ]</font></b> (نف مرکب ) آنکه بچندین خدای باور دارد. عابد ارباب . پرستنده ٔ ارباب انواع .<br /></font></div>'),
(2142, 'آلهه پرستی', '<span class=\"hlight\">آلهه پرستی .</span> <font color=\"DarkGreen\"><b>[ ل ِ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ پ َ رَ ]</font></b> (حامص مرکب ) دین آلهه پرست .<br /></font></div>'),
(2143, 'آلو', '<span class=\"hlight\">آلو.</span> (ن مف مرخم <span class=\"hlight\" dir=\"rtl\">/</span> نف مرخم ) مخفف آلود، در کلمات مرکبه چون گِل آلو، خواب آلو، پشمالو، خشم آلو و نظایر آن، معنی آلوده دهد <span class=\"hlight\">:</span> <br />جمله اهل بیت خشم آلو شدند<br />که همه در شیر بز طامع بدند.<br /> <font color=\"Red\">مولوی .</font><br />پر سبک دارد ره بالا کند<br />چون گل آلو شد گرانیها کند.<br /> <font color=\"Red\">مولوی .</font><br />این کلمه را جز حضرت جلال الدین محمد بلخی سایرفصحا استعمال نکرده اند.<br /></font></div>'),
(2144, 'آلو', '<span class=\"hlight\">آلو.</span> (اِ) قسمی میوه که مترجمین قدیم آن را به اجاص و اجاس ترجمه می کنند، لکن آلو دارای اجناسی است و اجاس عرب ظاهراً قسمی از آن است . و اقسام آن آلوزرد، آلوسیاه، آلوقیصی، آلوبخارا، آلوی کوهی، آلوی سفید است . رجوع به کلمات مزبوره شود. بعض میوه های دیگر نیز که از این قسم نیست باز آلو خوانده شده اند چون شفتالو، زردآلو، آلبالو، خرمالو <span class=\"hlight\">:</span> <br />برفتم برز تا بیارم کنستو<br />چو سیب و چو غوره چو امرود و آلو.<br /> <font color=\"Red\">علی قرط اندکانی .</font><br />جز پند حکیم و علم کی راند<br />صفرای جهالت از سرت آلو؟<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">پیرزن را دست بدرخت آلو نرسید گفت مرا خود ترش نسازد</span> .<br /><BR><font color=\"Blue\">◄</font> داش خشت پذیر را گویند. (فرهنگ جهانگیری ).<br /></font></div>'),
(2145, 'آلواه', '<span class=\"hlight\">آلواه .</span> <font color=\"DarkGreen\"><b>[ آل ْ ]</font></b> (اِ) وُج .فرژ. اگیر. عودالوج . عودالولوج . رجوع به وُج شود.<br /></font></div>'),
(2146, 'آلوبالو', '<span class=\"hlight\">آلوبالو.</span> (اِ) آلبالو. آلی بالی . آلوی ابوعلی . درختی است خوش قامت با پوستی بسرخی مائل و برگهای بی زغب و میوه ٔ چندِ فندقی سرخ و آبدار و خوش تُرُش، با دُمی درازتر از دم آلو و گوجه و امثال آنها و قسمی از آن میوه اش شیرین است که گیلاس نامند و رنگ میوه ٔ گیلاس روشن تر از آلوبالوست . و بیونانی آلوبالو را قراسیا (قراصیا) گویند <span class=\"hlight\">:</span> <br />سیب و زردآلو و آلوچه و آلوبالو<br />باز انجیر وزیری ّ و خیار خوشخوار.<br /> <font color=\"Red\">بسحاق اطعمه .</font><br />آلوبالو چو قطره ٔ خون <br />از بینی شاخ جسته بیرون .<br /><font color=\"Red\">مکتبی .</font><br /></font></div>'),
(2147, 'آلوبخارا', '<span class=\"hlight\">آلوبخارا.</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b>(اِ مرکب ) آلوبخارایی . قسمی آلو برنگ سرخ و بطعم ترش یا میخوش که پوست آن را کَنند و در خیک یا ظروف دیگر کنند و بشهرها برند. اجاص . آلو خراسانی . برقوق .<br /></font></div>'),
(2148, 'آلوترش', '<span class=\"hlight\">آلوترش .</span> <font color=\"DarkGreen\"><b>[ ت ُ رُ <span class=\"hlight\" dir=\"rtl\">/</span> ت ُ ]</font></b> (اِ مرکب ) نِلْک .<br /></font></div>'),
(2149, 'آلوج', '<span class=\"hlight\">آلوج .</span> (اِ) آلج . آژْدَف . اَژْدَف . زُعرور.<br /></font></div>'),
(2150, 'آلوخراسانی', '<span class=\"hlight\">آلوخراسانی .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (اِ مرکب ) آلوبخارا.<br /></font></div>'),
(2151, 'آلوخشک', '<span class=\"hlight\">آلوخشک .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (اِ مرکب ) آلوبخارائی خشک کرده .<br /></font></div>'),
(2152, 'آلود', '<span class=\"hlight\">آلود.</span> (ن مف مرخم <span class=\"hlight\" dir=\"rtl\">/</span> نف مرکب ) در کلمات مرکبه از قبیل آردآلود، اشک آلود، بت آلود، تراب آلود، تهمت آلود، خاک آلود، خشم آلود، خواب آلود، خون آلود، خوی آلود، ریگ آلود، زهرآلود، سرمه آلود، شکرآلود، غرض آلود، غضب آلود، گردآلود، گِل آلود، مشک آلود، می آلود، مخفّف آلوده است <span class=\"hlight\">:</span> <br />ریشی چگونه ریشی، چون ماله ٔ بت آلود<br />گوئی که دوش تا روز با ریش گوه پالود.<br /> <font color=\"Red\">عماره .</font><br />دو چشم موژان بودیش خوب و خواب آلود<br />بماند خواب و شد آن نرگسش که موژان بود.<br /><font color=\"Red\">عماره .</font><br />نهاد آن روی خوی آلود بر خاک <br />اَبَر شاه آفرینگر با دل پاک .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />گفت زندگانی خداوند دراز باد روباهان را زهره نباشد از شیر خشم آلود که صید گوزنان نمایند که این در سخت بسته است .(تاریخ بیهقی ).<br />هزار فتنه ٔ خوابیده را کند بیدار<br />دو چشم مست تو از یک نگاه خواب آلود.<br /> <font color=\"Red\">سعدی .</font><br />بخت خواب آلود ما بیدار خواهد شدمگر<br />زآنکه زد بر دیده آبی روی رخشان شما.<br /> <font color=\"Red\">حافظ.</font><br />حافظ بخود نپوشید این خرقه ٔ می آلود<br />ای شیخ پاکدامن معذور دار ما را.<br /> <font color=\"Red\">حافظ.</font><br />القضض ؛ ریگ آلود شدن . (تاج المصادر بیهقی ). و رجوع به آلوده شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2153, 'آلودن', '<span class=\"hlight\">آلودن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) مالیدن یا مالیده شدن چیزی به چیزی چنانکه اثری از آن در دوّمین بماند اعم ّ از نیک و بد و خشک و تر، چون آب و خاک و خون و اشک و مشک و زهر و قیر و خوی و پلیدی و جز آن . واین فعل لازم و متعدّی آید. تلویث . ملوث کردن . بطغ. بَدغ . تمریخ . تلطیخ . لطخ . تلطخ . تَمضخ . تضمیخ . تمشیغ. لوث . (دهار). چرکین کردن . آلوده کردن <span class=\"hlight\">:</span> <br />شکسته شود چرخ و گردونها<br />درفشان بیالاید از خونها.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت هرمز که بر پای زهر<br />میالای زهر ای بداندیش دهر.<br /> <font color=\"Red\">فردوسی .</font><br />هر آنگه که تو تشنه گشتی بخون <br />بیالودی این خنجر آبگون .<br /> <font color=\"Red\">فردوسی .</font><br />یکی داستان زد پس از مرگ اوی <br />بخون دو دیده بیالود روی .<br /> <font color=\"Red\">فردوسی .</font><br />بدان برتری نام یزدانْش را<br />بخواند و بیالود مژگانْش را.<br /> <font color=\"Red\">فردوسی .</font><br />کسی کو بپرهیزد از بدکنش <br />نیالاید اندر بدیها تنش .<br /> <font color=\"Red\">فردوسی .</font><br />سپه بود چندانکه گفتی سپهر<br />ز گردش بقیر اندر آلود چهر.<br /> <font color=\"Red\">فردوسی .</font><br />تا دیو چه افکند هوا بر زنخ سیب <br />مهتاب بگلگونه بیالودش رخسار.<br /> <font color=\"Red\">مخلدی .</font><br />همه میران جهاندیده کز او یاد کنند<br />خاک بوسند و بیالایند از خاک جباه .<br /> <font color=\"Red\">فرخی .</font><br />نباشد خوب اگر زآن پس که شستم دل به آب حق <br />که جان روشنم هرگز بناحقی بیالاید.<br /> <font color=\"Red\">ناصرخسرو.</font><br />جانْت بیالود به آثار جهل <br />قصدبه بر کردن آثار کن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آزاده ٔ کریم بیالاید از لئیم <br />چون دامن قبات نپوشانی از لاَّم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />با مردم نفایه مکن صحبت <br />زیرا که از نفایه بیالائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از قرین بد حذر بایدْت کرد<br />کز قرین بد بیالاید قرین <br />زر ندیدستی که بی قیمت شود<br />چون بیندائیش با چیزی مسین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بخون ای برادر میالای دست <br />که بالای دست تو هم دست هست .<br /> <font color=\"Red\">ناصرخسرو (از تاریخ گزیده ).</font><br />قطره ای آب خاک را ندهند<br />تا بخون روی گل نیالایند.<br /> <font color=\"Red\">مسعودسعد.</font><br />تو بحرص و حسد میالایَش <br />بخصال حمیده آرایَش .<br /> <font color=\"Red\">سنائی .</font><br />نعمت آلوده بیش نیست جهان <br />دامن همتت بدو مالای .<br /> <font color=\"Red\">انوری .</font><br />ز طاعت تا کمر بسته ست در دیوان تو خامه <br />چو حرز بازوی عصمت نیالوده ست طغیانش .<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />ندیدستی که گاوی در علفزار<br />بیالاید همه گاوان ده را؟<br /> <font color=\"Red\">سعدی .</font><br />اغلب تهیدستان دامن عصمت بمعصیت آلایند و گرسنگان نان ربایند. (گلستان ).<br />و مصدردوم آن آلایش است ؛ آلودم . بیالای .<br /></font></div>'),
(2154, 'آلوده', '<span class=\"hlight\">آلوده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) لوث، دَرَن، وسخ، نجاست، شوخ، پلیدی گرفته . ملوّث . مدَرّن . متنجس <span class=\"hlight\">:</span> <br />...َر آلوده بیاری ّ و نهی در...َس من <br />بوسه ای چند بتزویر دهی بر نس من .<br /> <font color=\"Red\">رودکی (از اوبهی در تحفةالاحباب ).</font><br />پیری ّ و درازی ّ و خشک شنجی <br />گوئی به گُه آلوده لتره غنجی .<br /> <font color=\"Red\">منجیک .</font><br />زآب شود هر تن آلوده پاک <br />پاک نگردد زن بد جز بخاک .<br /> <font color=\"Red\">ناصرخسرو.</font><br />شرممان باد ز پشمینه ٔ آلوده ٔ خویش <br />گر بدین فضل و هنر نام کرامات بریم .<br /> <font color=\"Red\">حافظ.</font><br />دلق آلوده ٔ صوفی بمی ناب بشوی .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> آغشته . ملطخ . مضمخ . آگشته . آگسته <span class=\"hlight\">:</span> <br />...نی دارد چو ...ن خواجه ش لت لت <br />ریشی دارد چو ماله آلوده به بت .<br /> <font color=\"Red\">عماره .</font><br />گر بلبل محنت زده عاشق بوده ست <br />باری دل غنچه از چه خون آلوده ست ؟<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> ممزوج .مخلوط. آمیخته . آمیغی . مشوب . مضاف . غیرخالص . که ویژه و ناب نیست <span class=\"hlight\">:</span> <br />ناب است هر آن چیز که آلوده نباشد<br />زین روی ترا گویم کآزاده ٔ نابی .<br /> <font color=\"Red\">فرخی .</font><br />یکی را میدهی صد گونه نعمت <br />یکی را نان جو آلوده با خون .<br /> <font color=\"Red\">باباطاهر.</font><br />اشک آلوده ٔ ما گرچه روانست ولی <br />برسالت سوی او پاک نهادی طلبیم .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> مغشوش . پربار، چنانکه زر <span class=\"hlight\">:</span> <br />زر آلوده کم عیار بود<br />زر پالوده پایدار بود.<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> تردامن . فاسق . فاجر. بدکار. تبه کار <span class=\"hlight\">:</span> <br />یکی آلوده ای باشد که شهری را بیالاید<br />چو از گاوان یکی باشد که گاوان را کند ریخن .<br /> <font color=\"Red\">رودکی .</font><br />دوستی را امید میدارم <br />گرچه آلوده و گنه کارم .<br /> <font color=\"Red\">سنائی .</font><br />چون نیست نمازمن آلوده نمازی <br />در میکده زآن کم نشود سوز و گدازم .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> معتاد بشراب . آموخته بافیون و مانند آن <span class=\"hlight\">:</span> <br />چوآلوده ای بینی آلوده ای <br />ولیکن سوی شستگان شسته ای .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> زشت . بد. ناپاک <span class=\"hlight\">:</span> <br />فعل آلوده گوهر آلاید<br />از خم سرکه سرکه پالاید.<br /><font color=\"Red\">عنصری .</font><br /> <BR><font color=\"Blue\">◄</font> مالیده شده <span class=\"hlight\">:</span> <br />ز کشته بهرسویکی توده بود<br />گیاهان بمغز سر آلوده بود.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مجازاً، رهین . مرهون <span class=\"hlight\">:</span> <br />آلوده ٔ منت کسان کم شو<br />تا یکشبه در وثاق تو نانست .<br /> <font color=\"Red\">انوری .</font><br /><BR><font color=\"Blue\">◄</font> مقروض . وام دار. <BR><font color=\"Blue\">◄</font> خرج کرده . نفقه کرده . <BR><font color=\"Blue\">◄</font> جُنب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلودگان دهر</span> ؛ دنیاداران بخیل و طالبان دنیا بحرص . محبان دنیا. گناهکاران . (از مؤید الفضلا).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلوده شدن </span> ؛ آلودن . تلطخ . ارتداع . (تاج المصادر بیهقی ). لوث . تضمخ <span class=\"hlight\">:</span> <br />ز بور اندرافتاد خسرو نگون <br />تن پاکش آلوده شد بر ز خون .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلوده کردن </span> ؛ آلودن . تلویث . تمشیغ. تلطیخ . تضمیخ . تمضیخ <span class=\"hlight\">:</span> <br />بهر جایگه بر یکی توده کرد<br />زمینها بمغز سرآلوده کرد.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلوده کردن کسی را به ...</span> ؛افترا بدو زدن . متهم کردن : الابتهار؛ زنی را بی گناه بخویش آلوده کردن . (تاج المصادر بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلوده گشتن </span> ؛ آلودن <span class=\"hlight\">:</span> <br />چو از خون در و دشت آلوده گشت <br />ز کشته بهر جای بر، توده گشت .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> این کلمه در مرکّبات معانی مختلف بخشد، چنانکه در گل آلوده ؛ پوشیده ٔ بگل . و در قیرآلوده ؛ اندوده ٔ بقیر. و در شراب آلوده و می آلوده و خوی آلوده ؛ ترشده ٔ بشراب و می و خوی . و در گردآلوده و آردآلوده و غبارآلوده و خاک آلوده و تراب آلوده و خواب آلوده ؛ گرد و آرد و غبار و خاک و تراب و خواب گرفته . و در خون آلوده ؛ آغشته و ملطخ بخون . ودر دهن آلوده و دامن آلوده ؛ ملوث و ناپاک دهان و دامان . و در غضب آلوده و خشم آلوده ؛ بسیارغضب و بسیارخشم . و در نعمت آلوده ؛ کم و اندک نعمت <span class=\"hlight\">:</span> <br />یکی مغفر خسروی بر سرش <br />خوی آلوده ببر بیان در برش .<br /> <font color=\"Red\">فردوسی .</font><br />نعمت آلوده بیش نیست جهان <br />دامن همّتت بدو مالای .<br /> <font color=\"Red\">انوری .</font><br />گل آلوده ای راه مسجد گرفت .<br /><font color=\"Red\">سعدی .</font><br />در کوی تو معروفم و از روی تو محروم <br />گرگ دهن آلوده ویوسف ندریده .<br /> <font color=\"Red\">سعدی .</font><br />دوش رفتم بدر میکده خواب آلوده <br />خرقه تردامن و سجّاده شراب آلوده .<br /> <font color=\"Red\">حافظ.</font><br />پاک و صافی شو و از چاه طبیعت بدرآی <br />که صفائی ندهد آب تراب آلوده .<br /> <font color=\"Red\">حافظ.</font><br />و رجوع به آلود شود.<br /></font></div>'),
(2155, 'آلوده دامان', '<span class=\"hlight\">آلوده دامان .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب ) آلوده دامن . آنکه دامن ملوث دارد. مجازاً، که عفیف نباشد. بی عفاف . فاسق . فاجر <span class=\"hlight\">:</span> <br />گرمن آلوده دامنم نه عجب <br />همه عالم گواه عصمت اوست .<br /> <font color=\"Red\">حافظ.</font><br /><BR><font color=\"Blue\">◄</font> عاصی . گناهکار. (برهان ).<br /></font></div>'),
(2156, 'آلوده کش', '<span class=\"hlight\">آلوده کش .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ک َ ]</font></b> (ص مرکب ) (از: آلوده، مُلوث + کَش، بغل و تهیگاه ) بی عفاف <span class=\"hlight\">:</span> <br />یکی آلوده کش باشد که شهری را بیالاید<br />هم از گاوان یکی باشد که گاوان را کند ریخن .<br /><font color=\"Red\">رودکی (از فرهنگ اسدی، نسخه ٔ خطی قدیم ).</font><br /></font></div>'),
(2157, 'آلودگی', '<span class=\"hlight\">آلودگی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص، اِ) لَوث . آلایش . عادت باعمال زشت . <BR><font color=\"Blue\">◄</font> گناه . فسق . فجور. جرم . <BR><font color=\"Blue\">◄</font> شوخ . دَرَن . وَسَخ <span class=\"hlight\">:</span> <br />چو بشنید از او شاه به، دین به <br />پذیرفت از او راه و آئین به <br />پر از نور ایزد بشد دخمه ها<br />وز آلودگی پاک شد تخمه ها.<br /> <font color=\"Red\">دقیقی .</font><br />چنان دان که هرگز گرامی پسر<br />نبوده ست یازان بخون پدر<br />مگر مادرش تخمه را تیره کرد<br />پسر را به آلودگی خیره کرد.<br /> <font color=\"Red\">فردوسی .</font><br />زن پاک تن را به آلودگی <br />برد نام و یازد به بیهودگی .<br /> <font color=\"Red\">فردوسی .</font><br />ره داور پاک بنمودشان <br />از آلودگی ها بپالودشان .<br /> <font color=\"Red\">فردوسی .</font><br />در این خرقه بسی آلودگی هست <br />خوشا وقت قبای می فروشان .<br /> <font color=\"Red\">حافظ.</font><br />آلودگی خرقه خرابی ّ جهانست .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> عَذِره . گوه <span class=\"hlight\">:</span><br />در حدث افتد نداند بوی چیست <br />از من است این بوی یا آلودگیست .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آلودگی آب </span> ؛ تیرگی آن .<br /><BR><font color=\"Blue\">◄</font> دَین . وام . بدهکاری .<br /></font></div>'),
(2158, 'آلوزان', '<span class=\"hlight\">آلوزان .</span> (اِخ ) نام قریه ای بسرخس .<br /></font></div>'),
(2159, 'آلوزرد', '<span class=\"hlight\">آلوزرد.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِ مرکب ) قسمی آلو که میوه ٔ آن خردتر از آلوسیاه و پوست و گوشت زرد دارد. در اوّل تُرُش خوش وچون برسد شیرین است . شاهلوک . (تاریخ طبری ترجمه ٔ بلعمی ). شاهلوج . اجاص اصفر. آلوگرده . گرده آلو. گرده .<br /></font></div>'),
(2160, 'آلوس', '<span class=\"hlight\">آلوس .</span> (اِ) در کلمه ٔ مرکبه ٔ چشمالوس، آغیل در چشماغیل است . و چشمالوس، دیدن بگوشه ٔ چشم باشد، بخشم یا بناز.<br /></font></div>'),
(2161, 'آلوسن', '<span class=\"hlight\">آلوسن .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ) قسمی زردآلوی لطیف <span class=\"hlight\">:</span> <br />پس بخور مطبوخ آلوسن تو زود<br />تا کند تسکین برد و هم خمود.<br /><font color=\"Red\">حکیم شیرازی (از شعوری ).</font><br /></font></div>'),
(2162, 'آلوسه', '<span class=\"hlight\">آلوسه .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) نام شهری بناحیه ٔ نزدیک فرات، و آن را اَلوس و اَلوسه نیز گویند.<br /></font></div>'),
(2163, 'آلوسیاه', '<span class=\"hlight\">آلوسیاه .</span> (اِ مرکب ) قسمی آلو درشت تر از آلوزرد برنگ سرخ تیره . اجاص . اجاس .<br /></font></div>'),
(2164, 'آلوسیاه جنگلی', '<span class=\"hlight\">آلوسیاه جنگلی .</span> <font color=\"DarkGreen\"><b>[ هَِ ج َ گ َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کامپوری .<br /></font></div>'),
(2165, 'آلوفروش', '<span class=\"hlight\">آلوفروش .</span> <font color=\"DarkGreen\"><b>[ ف ُ ]</font></b>(نف مرکب ) آنکه آلوبخارایی در آب خیسانیده فروشد.<br /></font></div>'),
(2166, 'آلوفروشی', '<span class=\"hlight\">آلوفروشی .</span> <font color=\"DarkGreen\"><b>[ ف ُ ]</font></b> (حامص مرکب ) حرفه ٔ آلوفروش . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) دکان آلوفروش .<br /></font></div>'),
(2167, 'آلوقیسی', '<span class=\"hlight\">آلوقیسی .</span> <font color=\"DarkGreen\"><b>[ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (اِ مرکب ) آلوقیصی . قسمی میوه بدرشتی درشت ترین هلو و آبدارتر از آن بطعم میخوش و پوستی اَملس و برنگ سرخ و سبز بهم آمیخته .<br /></font></div>'),
(2168, 'آلوم', '<span class=\"hlight\">آلوم .</span> (اِخ ) نام محلی از توابع طهران و در آنجا معدن ذغال سنگ باشد.<br /></font></div>'),
(2169, 'آلوند', '<span class=\"hlight\">آلوند.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) اَلوند.<br /></font></div>'),
(2170, 'آلونه', '<span class=\"hlight\">آلونه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) مخفف آلگونه . غازه . سرخی .<br /></font></div>'),
(2171, 'آلونک', '<span class=\"hlight\">آلونک .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِ)خانه ٔ خرد و بی ثبات و بی سامان . کوخ . کوخچه . کومه .<br /></font></div>'),
(2172, 'آلوه', '<span class=\"hlight\">آلوه .</span> (اِ) آلُه ْ. عقاب .<br /></font></div>'),
(2173, 'آلوچه', '<span class=\"hlight\">آلوچه .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ مصغر) مصغّر آلو. قسم خرد و ترش تر گوجه . اِدرِک . اجاص . (داود ضریر انطاکی ). آلنج . نیسوق <span class=\"hlight\">:</span> <br />سیب و زردآلو وآلوچه و امرود و هلو<br />باز انجیر وزیری ّ و خیار خوشخوار.<br /><font color=\"Red\">بسحاق اطعمه .</font><br /></font></div>'),
(2174, 'آلوچه سگک', '<span class=\"hlight\">آلوچه سگک .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ س َ گ َ ]</font></b> (اِ مرکب ) قسم پست و خرد و ترش ِ آلوچه . نِلْک . آلوکوهی .<br /></font></div>'),
(2175, 'آلوکوهی', '<span class=\"hlight\">آلوکوهی .</span> (اِ مرکب ) آلوی ِ کوهی . نِلْک . (فرهنگ اسدی ). اِدرِک . آلوچه ٔ کوهی . و آن آلوئی باشد برنگ زرد و بطعم تلخ، شبیه به آلوچه سگک .<br /></font></div>'),
(2176, 'آلوگرده', '<span class=\"hlight\">آلوگرده .</span> <font color=\"DarkGreen\"><b>[ گ ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) شاهلوک . شاهلوج . آلوزرد. رجوع به آلوزرد شود.<br /></font></div>'),
(2177, 'آلوی ابوعلی', '<span class=\"hlight\">آلوی ابوعلی .</span> <font color=\"DarkGreen\"><b>[ ی ِ اَ ع َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آلبالو. قراصیا.<br /></font></div>'),
(2178, 'آلوی بخارا', '<span class=\"hlight\">آلوی بخارا.</span> <font color=\"DarkGreen\"><b>[ ی ِ ب ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) آلوی بخارایی . آلوبخارا.<br /></font></div>'),
(2179, 'آلوی جیلی', '<span class=\"hlight\">آلوی جیلی .</span> <font color=\"DarkGreen\"><b>[ ی ِ جی ]</font></b> (ترکیب وصفی، اِ مرکب ) آلوچه . گوجه گیلانی . آلوی گیلی .<br /></font></div>'),
(2180, 'آلوی خراسانی', '<span class=\"hlight\">آلوی خراسانی .</span> <font color=\"DarkGreen\"><b>[ ی ِ خ ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) آلوبخارا.<br /></font></div>'),
(2181, 'آلوی دشتی', '<span class=\"hlight\">آلوی دشتی .</span> <font color=\"DarkGreen\"><b>[ ی ِ دَ ]</font></b> (ترکیب وصفی، اِ مرکب ) زعرور.<br /></font></div>'),
(2182, 'آلوی سفید', '<span class=\"hlight\">آلوی سفید.</span> <font color=\"DarkGreen\"><b>[ ی ِ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ]</font></b> (ترکیب وصفی، اِ مرکب ) شاهلوک . شاهلوج . آلوزرد.<br /></font></div>'),
(2183, 'آلوی سیاه', '<span class=\"hlight\">آلوی سیاه .</span> <font color=\"DarkGreen\"><b>[ی ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به آلوسیاه شود.<br /></font></div>'),
(2184, 'آلوی چینی', '<span class=\"hlight\">آلوی چینی .</span> <font color=\"DarkGreen\"><b>[ ی ِ چی ]</font></b> (ترکیب وصفی، اِ مرکب ) نام درختی است که میوه ٔ آن را تولی و تیره تُلی و چاکشو، و برود نیز گویند.<br /></font></div>'),
(2185, 'آلوی کشته', '<span class=\"hlight\">آلوی کشته .</span> <font color=\"DarkGreen\"><b>[ ی ِ ک ِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) آلوی خشک کرده .<br /></font></div>'),
(2186, 'آلوی کوهی', '<span class=\"hlight\">آلوی کوهی .</span> <font color=\"DarkGreen\"><b>[ی ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به آلوکوهی شود.<br /></font></div>'),
(2187, 'آلوی گیلی', '<span class=\"hlight\">آلوی گیلی .</span> <font color=\"DarkGreen\"><b>[ ی ِ گی ]</font></b> (ترکیب وصفی، اِ مرکب ) گوچه .<br /></font></div>'),
(2188, 'آلپ', '<span class=\"hlight\">آلپ .</span> (اِخ ) نام سلسله ٔکوههای عظیم اروپای غربی در شمال ایطالیا و فاصله ٔ میان مملکت فرانسه از سویس و آلمان، و این سلسله را بسه قسمت آلپ غربی و مرکزی و شرقی تقسیم کنند. قله ٔ معروف آن مُن بلان (کوه سفید) است بارتفاع <span class=\"hlight\" dir=\"rtl\">٤٨١٠</span> گز.<br /></font></div>'),
(2189, 'آلپ نورد', '<span class=\"hlight\">آلپ نورد.</span> <font color=\"DarkGreen\"><b>[ ن َوَ ]</font></b> (نف مرکب ) آنکه بگردش و تماشا به آلپ برشود.<br /></font></div>'),
(2190, 'آلپ نوردی', '<span class=\"hlight\">آلپ نوردی .</span> <font color=\"DarkGreen\"><b>[ ن َ وَ ]</font></b> (حامص مرکب ) عمل آلپ نورد.<br /></font></div>'),
(2191, 'آلک', '<span class=\"hlight\">آلک .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ) آله . اُشنه . (ریاض الادویه ). دوالک . (ریاض الادویه ) (بحرالجواهر). <BR><font color=\"Blue\">◄</font> سنبل الطیب .<br /></font></div>'),
(2192, 'آلکساندر', '<span class=\"hlight\">آلکساندر.</span> <font color=\"DarkGreen\"><b>[ ل ِ دْ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِخ ) رجوع به اسکندر شود.<br /></font></div>'),
(2193, 'آلکل', '<span class=\"hlight\">آلکل .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (فرانسوی، اِ) (از عربی ِ اَلکُحل ) اَلْکُل . جوهر. جوهَر شراب . و رجوع به الکل شود.<br /></font></div>'),
(2194, 'آلکلی', '<span class=\"hlight\">آلکلی .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (ص نسبی ) الکلی . آنکه به بسیار آشامیدن مشروبهای الکل دار چون شراب و عرق و کنیاک و رم و سایر انواع آن معتاد است .<br /></font></div>'),
(2195, 'آلکی', '<span class=\"hlight\">آلکی .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ) پالکی .<br /></font></div>'),
(2196, 'آلگون', '<span class=\"hlight\">آلگون .</span> (اِخ ) نام یکی از آبادیهای سَقّز کردستان که پیشتر آلْکَلو نامیده میشده . (فرهنگستان ).<br /></font></div>'),
(2197, 'آلگونه', '<span class=\"hlight\">آلگونه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) آلغونه . سرخی که زنان درروی مالند زینت را. سرخه . غازه . سرخاب <span class=\"hlight\">:</span> <br />آن بناگوش کز صفا گوئی <br />برکشیده ست آلگونه بسیم .<br /><font color=\"Red\">شهید.</font><br /></font></div>'),
(2198, 'آلی', '<span class=\"hlight\">آلی .</span> <font color=\"DarkGreen\"><b>[ لا ]</font></b> (ع ص ) گوسفند بزرگ دنبه . کبش دنبه ناک . <BR><font color=\"Blue\">◄</font> مرد بزرگ سرین .<br /></font></div>'),
(2199, 'آلی', '<span class=\"hlight\">آلی .</span> (حامص ) سرخی . سرخی نیم رنگ .<br /></font></div>'),
(2200, 'آلی', '<span class=\"hlight\">آلی .</span> <font color=\"DarkGreen\"><b>[ لی ی ]</font></b> (ع ص نسبی ) منسوب به آلت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">جسم آلی </span> ؛ جسمی مرکب از آلات که هر یک را منصبی جدا باشد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عضو آلی </span> ؛ هر عضو که اسم کل بر جزو آن صدق نکند. مقابل عضو غیرآلی یا عضو مفرد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مرض آلی </span> ؛ بیماری که متوجه عضوی آلی باشد:قولنج مرض آلی است .<br /></font></div>'),
(2201, 'آلی بالی', '<span class=\"hlight\">آلی بالی .</span> (اِ) آلوبالو. آلبالو. قراصیا. آلوی ابوعلی .<br /></font></div>'),
(2202, 'آلیاران', '<span class=\"hlight\">آلیاران .</span> (اِخ ) نام محلی کنار راه اصفهان به نجف آباد، میان تیرانچه و کرسنگ در <span class=\"hlight\" dir=\"rtl\">١٤٣٠٠</span>گزی اصفهان .<br /></font></div>'),
(2203, 'آلیز', '<span class=\"hlight\">آلیز.</span> (اِمص، اِ) جُفته . جُفتک، و آن لگد پرانیدن ستور باشد با دو پای از پس . <BR><font color=\"Blue\">◄</font> رَم .<br /></font></div>'),
(2204, 'آلیزدن', '<span class=\"hlight\">آلیزدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آلیزیدن .<br /></font></div>'),
(2205, 'آلیزش', '<span class=\"hlight\">آلیزش .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِمص ) اسم مصدر و فعل آلیزیدن .<br /></font></div>'),
(2206, 'آلیزنده', '<span class=\"hlight\">آلیزنده .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه آلیزد از ستور. جفته انداز. جفتک زن <span class=\"hlight\">:</span> <br />چو آلیزنده شددر مرغزاری <br />نباشد بر دلش از بار باری .<br /> <font color=\"Red\">ابوشکور.</font><br />قموص ؛ خر آلیزنده . (السامی فی الاسامی ). توسن . بدخو. لگدزن . جهنده (اسب و استر).<br /></font></div>'),
(2207, 'آلیزیدن', '<span class=\"hlight\">آلیزیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) جفته افکندن . جفتک انداختن <span class=\"hlight\">:</span> <br />نفس چون سیر گشت بستیزد<br />توسن آسا بهر سوآلیزد.<br /><font color=\"Red\">سراج الدین راجی .</font><br /></font></div>'),
(2208, 'آلین', '<span class=\"hlight\">آلین .</span> (اِخ ) نام قریه ای از مرو به سفلای رود خارقان .<br /></font></div>'),
(2209, 'آلیه', '<span class=\"hlight\">آلیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) شاید نام محلی که قصر آلیه منسوب بدانجاست . (مراصدالاطلاع ).<br /></font></div>'),
(2210, 'آلیه', '<span class=\"hlight\">آلیه .</span> <font color=\"DarkGreen\"><b>[ لی ی َ ]</font></b> (ع ص نسبی ) تأنیث آلی ّ: اجسام آلیه .<br /></font></div>'),
(2211, 'آم', '<span class=\"hlight\">آم .</span> (ع اِ) ج ِ اَمة. کنیزکان . پرستاران .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آم و عام </span> ؛ زن و ستور.<br /></font></div>'),
(2212, 'آم', '<span class=\"hlight\">آم .</span> <font color=\"DarkGreen\"><b>[ آم م ]</font></b> (ع ص ) قصدکننده . (مهذب الاسماء). قاصد.<br /></font></div>'),
(2213, 'آم', '<span class=\"hlight\">آم .</span>(اِخ ) نام شهری و نوعی جامه که بدانجا منسوب است .<br /></font></div>'),
(2214, 'آما', '<span class=\"hlight\">آما.</span> (نف مرخم ) آمای .<br /></font></div>'),
(2215, 'آماج', '<span class=\"hlight\">آماج .</span> (اِ) خاک توده کرده که نشان تیر بر آن نصب کنند. آماجگاه :<br />گر موی بر آماج نهی موی بدوزی <br />وین از گهر آموخته ای تو نه بتلقین .<br /> <font color=\"Red\">فرخی .</font><br />چنان چون سوزن از وَشّی ّ و آب روشن از توزی <br />ز طوسی بیل بگذاری به آماج اندرون بیله .<br /> <font color=\"Red\">فرخی .</font><br />چو تیر انداختی در روی دشمن <br />حذر کن کاندر آماجش نشستی .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> توسعاً، نشان . نشانه . غرض . هدف . (دهار). <BR><font color=\"Blue\">◄</font> پرتاب . تیر پرتاب . تیررَس . بیست و چهار یک ِ فرسنگ . قریب پانصد قدم <span class=\"hlight\">:</span> <br />آماج تو از بُست بود تا به سپنج آب <br />پرتاب تو از بلخ بود تا بفلسطین .<br /> <font color=\"Red\">فرخی .</font><br />ستاده قیصر و خاقان و فغفور<br />یک آماج از بساط پیشگه دور.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> آهن گاوآهن که در زمین فروشود و شیار کند. <BR><font color=\"Blue\">◄</font> مجموع آهن جفت . سپار. گاوآهن : جفت الفدّان ؛ ساخت آماج کشاورز. (منتهی الارب ) <span class=\"hlight\">:</span> <br />برکند تیر تو زآنسان خاک در آماجگاه <br />برزگر برکنده پنداری به آماج و کلند.<br /> <font color=\"Red\">سوزنی .</font><br />خواجه بهیبت در او نظر کردند، افتاد و سر او چون آماج در زمین می رفت و سر و گردن او در خاک پوشیده گشت . (انیس الطالبین بخاری ).<br />تیر؛ یوع آماج . (صراح ). <BR><font color=\"Blue\">◄</font> اوماج . (مؤید).<br /></font></div>'),
(2216, 'آماج خانه', '<span class=\"hlight\">آماج خانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) آماجگاه .<br /></font></div>'),
(2217, 'آماجگاه', '<span class=\"hlight\">آماجگاه .</span> (اِ مرکب ) آماج . نشانه گاه <span class=\"hlight\">:</span> <br />سرشک دیده برخسار تو فروبارد<br />هر آنگهی که بر آماجگاه او گذری .<br /> <font color=\"Red\">عماره .</font><br />کند به تیر چو زنبورخانه سندان را<br />اگر نهند بر آماجگاه او سندان .<br /> <font color=\"Red\">فرخی .</font><br />زمین هست آماجگاه زمان <br />نشانه تن ما و چرخش کمان .<br /> <font color=\"Red\">اسدی .</font><br />برکند تیر تو زآنسان خاک در آماجگاه <br />برزگربرکنده پنداری به آماج و کلند.<br /> <font color=\"Red\">سوزنی .</font><br />چو خاک آماجگاه تیر گشته .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> نشانه . <BR><font color=\"Blue\">◄</font> میدانی که در آن نشانه نهند مشق و ورزش تیراندازی را<span class=\"hlight\">:</span> <br />واندر آماجگاه راه کند<br />تیر او اندر آهنین دیوار.<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> آنجا که شیار کنند. زمین شیاریده . <BR><font color=\"Blue\">◄</font> مجازاً، دنیا. ملک . سریر ملک <span class=\"hlight\">:</span> <br />چو الب ارسلان جان بجان بخش داد...<br />بتربت سپردندش از تاجگاه <br />نه جای نشستن بد آماجگاه .<br /> <font color=\"Red\">سعدی .</font><br /> <br /></font></div>'),
(2218, 'آماد', '<span class=\"hlight\">آماد.</span> (ع اِ) ج ِ اَمَد.<br /></font></div>'),
(2219, 'آمادن', '<span class=\"hlight\">آمادن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) ساختن . بساختن . بسیجیدن . بسغدن . سغدن . آسغدن . برساختن . مهیا کردن . مهیا شدن . تهیه . آماده کردن . آماده شدن . آراستن . معدات فراهم کردن . مستعد کردن . ساز کردن . راست کردن . تیارکردن . <BR><font color=\"Blue\">◄</font> پر و مملو گردانیدن . (برهان ).<br /></font></div>'),
(2220, 'آماده', '<span class=\"hlight\">آماده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) حاضر. مستعد. مُعدّ. مهیا. مُشمر. عتید. (دهار). مُمهّد. موجود. ساخته .آراسته . بسیجیده . فراهم کرده . برساخته . حاضر. شکرده .سیجیده . (فرهنگ اسدی ). بسغده . آسغده . سغده . (اوبهی ). چیره . بسامان . ساخته و پرداخته . تیار <span class=\"hlight\">:</span> <br />خود تو آماده بدی برخاسته <br />جنگ او را خویشتن آراسته .<br /> <font color=\"Red\">رودکی .</font><br />یکی بدسگال و یکی ساده دل <br />سپهبد بهر کار آماده دل .<br /> <font color=\"Red\">فردوسی .</font><br />چون همی شد بخانه آماده <br />دید مردی بره براستاده .<br /> <font color=\"Red\">عنصری .</font><br />حاجب گفت که همه قوم با وی <font color=\"DarkGreen\"><b>[ امیر محمدبن محمود ]</font></b> خواهند رفت و فرزندان بجمله آماده اند. (تاریخ بیهقی ). چون این مکار غدار بباید ساخته و آماده باید بود. (کلیله و دمنه ).<br />گفتم ای گوسفند کاه بخور<br />کز علفها همینت آماده ست <br />گفت جو، گفتمش ندارم، گفت <br />در کدیه خدای بگشاده ست (کذا).<br /> <font color=\"Red\">انوری (از صحاح الفرس ).</font><br />تو داری بدل گنج آماده را<br />تو کردی بلند آدمیزاده را.<br /> <font color=\"Red\">امیرخسرو.</font><br />تکیه بر جای بزرگان نتوان زد بگزاف <br />مگراسباب بزرگی همه آماده کنی .<br /> <font color=\"Red\">حافظ.</font><br /><BR><font color=\"Blue\">◄</font> در اصطلاح بنایان، گچی روان تر از بوم .<br /></font></div>'),
(2221, 'آماده شدن', '<span class=\"hlight\">آماده شدن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ش ُ دَ ]</font></b> (مص مرکب ) بساختن . بسغدن . سغدن . آسغدن . بسیجیدن . سیجیدن . ساختن . شکردن . آراستن . حاضر، مهیا، مستعد، معد، مثمر، ممهد شدن . استعداد. تَهَیﱡاء. تیار، بساز، بسامان، ساخته و پرداخته شدن .<br /></font></div>'),
(2222, 'آماده کردن', '<span class=\"hlight\">آماده کردن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ک َ دَ ]</font></b> (مص مرکب ) اِعداد. احتشاد. برساختن . ساختن . مهیا کردن . اشراط. تیار، راست، بسامان کردن . پرداختن . ساختن و پرداختن . آمادن .<br /></font></div>'),
(2223, 'آماده کرده', '<span class=\"hlight\">آماده کرده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) ساخته . مُعَدّ.<br /></font></div>'),
(2224, 'آمادگی', '<span class=\"hlight\">آمادگی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) ساختگی .تهیه . بسیج . ساز. استعداد. تَهَیﱡاء. أهبه . ساخت وساز. عتاد. اباب . آراستگی . جهاز. عُدّه . (دهّار).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمادگی سفر</span> ؛ ساز سفر.<br /></font></div>'),
(2225, 'آمار', '<span class=\"hlight\">آمار.</span> (اِ) (از پهلوی به معنی شمار) آماره . آوار. آواره . اَواره . اَوارِجه . حساب <span class=\"hlight\">:</span> <br />آنگهی گنجور مشک آمار کرد<br />تا مر او را زآن نهان بیدار کرد.<br /> <font color=\"Red\">رودکی .</font><br /> <br /></font></div>'),
(2226, 'آمار', '<span class=\"hlight\">آمار.</span> (اِ) احصائیّه . (فرهنگستان ).<br /></font></div>'),
(2227, 'آماردن', '<span class=\"hlight\">آماردن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) رجوع به آماریدن شود.<br /></font></div>'),
(2228, 'آماردی', '<span class=\"hlight\">آماردی .</span> (اِخ ) نام طائفه ای بوده است به گیلان . <BR><font color=\"Blue\">◄</font> سفیدرود (مأخوذ از نام طائفه ٔ مذکور).<br /></font></div>'),
(2229, 'آمارشناس', '<span class=\"hlight\">آمارشناس .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (نف مرکب ) کسی که بقواعد علم آمار آگاهی دارد. متخصص احصائیه . (فرهنگستان ).<br /></font></div>'),
(2230, 'آماره', '<span class=\"hlight\">آماره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) آمار.<br /></font></div>'),
(2231, 'آماره گیر', '<span class=\"hlight\">آماره گیر.</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب ) آمارگیر. نویسنده . مُحاسب . مستوفی .<br /></font></div>'),
(2232, 'آمارگر', '<span class=\"hlight\">آمارگر.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (ص مرکب ) مأمور انجام کارهای آمار. مأمور احصائیّه . (فرهنگستان ).<br /></font></div>'),
(2233, 'آمارگیر', '<span class=\"hlight\">آمارگیر.</span> (نف مرکب ) آماره گیر. آمارگیره . محاسب .<br /></font></div>'),
(2234, 'آمارگیره', '<span class=\"hlight\">آمارگیره .</span> <font color=\"DarkGreen\"><b>[ گی رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب ) آمارگیر.<br /></font></div>'),
(2235, 'آماریدن', '<span class=\"hlight\">آماریدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آماردن . شمردن . بحساب آوردن . <BR><font color=\"Blue\">◄</font> مجازاً، اهمیت دادن . محلی نهادن . بروی خود آوردن <span class=\"hlight\">:</span> <br />ساعتکی روی پیش دار و بِهُش باش <br />کار بمن مان و برمگرد و میامار.<br /> <font color=\"Red\">سوزنی .</font><br />تو از سر نغزی ّ و لطیفی ّ و ظریفی <br />می دان همه افعال من و هیچ میامار.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(2236, 'آمازن', '<span class=\"hlight\">آمازن .</span> <font color=\"DarkGreen\"><b>[ زُ]</font></b> (اِخ ) نام رودی بزرگ در آمریکای جنوبی، و آن بزرگترین ِ رودهای جهان است .<br /></font></div>'),
(2237, 'آمازی', '<span class=\"hlight\">آمازی .</span> (اِخ ) نام یونانی شهری از چترپتی کاپادوکیه . و این شهر مسقطالرأس استرابن است . و امروز به آماسیه مشهور است .<br /></font></div>'),
(2238, 'آماس', '<span class=\"hlight\">آماس .</span> (اِ) آماه . وَرَم . تورّم .باد. نَفخ . برآمدگی . پف کردگی . تَهَبﱡج <span class=\"hlight\">:</span> <br />لیکن از راه عقل هشیاران <br />بشناسند فربهی زآماس .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مُتنبی نکو همی گوید<br />بازدانید فربهی زآماس .<br /> <font color=\"Red\">مسعودسعد.</font><br />و زنان از بهر درد و آماس رحم پنبه بدان تر کنند و برگیرند عظیم سود کند. (نوروزنامه ).<br />بسی فربه نماید آنکه دارد<br />نمای فربهی از نوع آماس .<br /> <font color=\"Red\">سنائی .</font><br />عقل را حایل جحیم شناس <br />نبود همچو فربهی آماس .<br /> <font color=\"Red\">سنائی .</font><br />کسی که چشم خرد دارداز اکابر عصر<br />نظر بحالت او می کنم ز روی قیاس <br />بعینه ٔ مثلش آن حریص محروم است <br />که بازمی نشناسد ز فربهی آماس .<br /> <font color=\"Red\">ابن یمین .</font><br />وفعل آن آماسیدن و آماس کردن و آماس گرفتن . و در متعدی آماسانیدن است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آماس لهات، آماس مزمن لهات </span> ؛ افتادن زبان کوچک .<br /></font></div>'),
(2239, 'آماس', '<span class=\"hlight\">آماس .</span> (ع اِ) ج ِ اَمْس .<br /></font></div>'),
(2240, 'آماس کش', '<span class=\"hlight\">آماس کش .</span> <font color=\"DarkGreen\"><b>[ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) (اصطلاح طب ) هَوکش . ضِد وَرم .<br /></font></div>'),
(2241, 'آماسان', '<span class=\"hlight\">آماسان .</span> (نف، ق ) در حال آماسیدن .<br /></font></div>'),
(2242, 'آماساننده', '<span class=\"hlight\">آماساننده .</span> <font color=\"DarkGreen\"><b>[ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه آماساند.<br /></font></div>'),
(2243, 'آماسانیدن', '<span class=\"hlight\">آماسانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ]</font></b> (مص ) توریم . تهبیج . آماهانیدن . ورم را سبب شدن .<br /></font></div>'),
(2244, 'آماسانیده', '<span class=\"hlight\">آماسانیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آماهانیده .<br /></font></div>'),
(2245, 'آماسنده', '<span class=\"hlight\">آماسنده .</span> <font color=\"DarkGreen\"><b>[ س َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آماهنده . تمنده .<br /></font></div>'),
(2246, 'آماسیدن', '<span class=\"hlight\">آماسیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) تمیدن . آماهیدن . نفخ .انتفاخ . وَرَم . تورّم . تهبﱡج . حَدر. باد کردن . دروء. تَفرّق . وَرَم کردن . نفخ کردن . منتفخ شدن . متوَرم شدن <span class=\"hlight\">:</span> و امیةبن خلف آماسیده بود <font color=\"DarkGreen\"><b>[ پس از مرگ ]</font></b> دست بدان نتوانستند کردن سنگهای بسیار بر وی افکندند. (ترجمه ٔ طبری بلعمی ). و ابولهب بیمار بود چون این خبر بشنید <font color=\"DarkGreen\"><b>[ خبر شکست کفار به بدر ]</font></b> سیاه گشت و بیاماسید، و دیگر روز بمرد. (ترجمه ٔ طبری بلعمی .).<br />بقول ماه دی آبی که ساری باشد و لاغر<br />بیاساید شب و روز و بیاماسد چو سندانها.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(2247, 'آماسیده', '<span class=\"hlight\">آماسیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) متوَرّم . منتفخ . متهبج . آماهیده . بادکرده . ورم کرده . پُف کرده . برآماسیده . تمیده : باثعالشفه ؛ آماسیده لب . (ربنجنی ).<br /></font></div>'),
(2248, 'آماسیدگی', '<span class=\"hlight\">آماسیدگی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) تورم . انتفاخ . تهبج .<br /></font></div>'),
(2249, 'آماسیه', '<span class=\"hlight\">آماسیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) نام شهری به آسیةالصغری، در ساحل یشیل ایرماغ، مولد استرابن مورّخ . رجوع به آمازی شود.<br /></font></div>'),
(2250, 'آماق', '<span class=\"hlight\">آماق .</span> (ع اِ) ج ِ ماق . گوشه های چشم از سوی بینی .بیغوله های چشم از جانب اِنسی . کنج چشم از درونسو.<br /></font></div>'),
(2251, 'آمال', '<span class=\"hlight\">آمال .</span> (ع اِ) ج ِ اَمَل . امیدها. اومیدها. آرزوها.<br /></font></div>'),
(2252, 'آماه', '<span class=\"hlight\">آماه .</span> (اِ) آماس . ورم . نفخ . تمیدگی . تورم . انتفاخ . تهبّج . دُروء. باد. بادکردگی . تفرق <span class=\"hlight\">:</span> <br />ز بس دم تو که خوردم به نای می مانم <br />که در میانه ٔ دفّم پدید شد آماه .<br /> <font color=\"Red\">نجیب جرفادقانی .</font><br />پس عجب نیست که با جنس ذبولی که وراست <br />تره را بر سر خوان تو بگیرد آماه .<br /> <font color=\"Red\">نجیب جرفادقانی .</font><br />شیر کز مالش عدل تو دباغت یابد<br />گردنش نرم تر از نیفه ٔ روباه بود<br />خصمت ار فربهئی یافت ز معجون غرور<br />چه شود، فربهی طبل ز آماه بود.<br /><font color=\"Red\">شرف شفروه .</font><br /></font></div>'),
(2253, 'آماهاندن', '<span class=\"hlight\">آماهاندن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آماهانیدن .<br /></font></div>'),
(2254, 'آماهانده', '<span class=\"hlight\">آماهانده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آماهانیده .<br /></font></div>'),
(2255, 'آماهاننده', '<span class=\"hlight\">آماهاننده .</span> <font color=\"DarkGreen\"><b>[ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آماساننده .<br /></font></div>'),
(2256, 'آماهانیدن', '<span class=\"hlight\">آماهانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آماسانیدن . توریم . تهبیج . احدار.<br /></font></div>'),
(2257, 'آماهانیده', '<span class=\"hlight\">آماهانیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آماسانیده .<br /></font></div>'),
(2258, 'آماهیدن', '<span class=\"hlight\">آماهیدن .</span> <font color=\"DarkGreen\"><b>[دَ ]</font></b> (مص ) آماسیدن . تورم . تهبج . ورم کردن . باد کردن . تَحدر. انتفاخ . (زوزنی ). اجدار. اسمغداد. تسخید. احدار: در قسمی از داءالفیل پای برآماهد و سخت شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آماهیدن پی دست چاروا</span> ؛ انتشار.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آماهیدن جراحت </span> ؛ بغی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آماهیدن مرده </span> ؛ اجفیظاظ.<br />و رجوع به برآماهیدن شود.<br /></font></div>'),
(2259, 'آماهیده', '<span class=\"hlight\">آماهیده .</span> <font color=\"DarkGreen\"><b>[ دَ<span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آماسیده . رجوع به آماهیدن شود.<br /></font></div>'),
(2260, 'آمای', '<span class=\"hlight\">آمای .</span> (فعل امر) امر از آمودن به معنی آراستن و درنشاندن گوهر در چیزی و بسلک و رشته کشیدن لؤلؤ و جز آن و پر کردن و انباشتن <span class=\"hlight\">:</span> <br />گفت مشّاطه را که صنعخدای <br />یعنی آن لعبت چگل، آمای .<br /> <font color=\"Red\">عمعق .</font><br /> <BR><font color=\"Blue\">◄</font> (نف مرخم ) مهیّاکننده . مستعدکننده . (برهان ). و در کلمات مرکّبه مانند گوهرآمای، لؤلؤآمای، مخفف آماینده است <span class=\"hlight\">:</span> <br />توئی گوهرآمای چارآخشیج <br />مسلسل کن ِ گوهران در مزیج .<br /> <font color=\"Red\">نظامی .</font><br />کواکب را بقدرت کارفرمای <br />طبایع را بصنعت گوهرآمای .<br /> <font color=\"Red\">نظامی .</font><br />و رجوع به آمودن و آمود و آموده شود.<br /></font></div>'),
(2261, 'آمج', '<span class=\"hlight\">آمج .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) بغایت گرم . <BR><font color=\"Blue\">◄</font> سخت تشنه . <BR><font color=\"Blue\">◄</font> شتابان (در رفتن ).<br /></font></div>'),
(2262, 'آمختن', '<span class=\"hlight\">آمختن .</span> <font color=\"DarkGreen\"><b>[ م ُ ت َ ]</font></b> (مص ) مخفف آموختن . تعلم . یاد گرفتن . <BR><font color=\"Blue\">◄</font> تعلیم . یاد دادن <span class=\"hlight\">:</span> <br />هرکه نامُخت از گذشت روزگار<br />نیز ناموزد ز هیچ آموزگار.<br /> <font color=\"Red\">رودکی .</font><br />بیامد همانگاه نستور شیر<br />نبرده کیان زاده پور زریر<br />بکشتش بسی دشمنان بی شمار<br />که آمخته بد از پدر کارزار.<br /> <font color=\"Red\">دقیقی .</font><br />جهان را به آئین شاهی بدار<br />چو آمختی از پاک پروردگار.<br /> <font color=\"Red\">فردوسی .</font><br />اگرچند مردم ندیده بد اوی <br />ز سیمرغ آمخته بد گفتگوی .<br /> <font color=\"Red\">فردوسی .</font><br />بپروردشان از ره بدخوئی <br />بیامختشان کژّی و جادوئی .<br /> <font color=\"Red\">فردوسی .</font><br />برنج و بسختی جگر سخته بود<br />ز رستم هنرها بیامخته بود.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2263, 'آمخته', '<span class=\"hlight\">آمخته .</span> <font color=\"DarkGreen\"><b>[ م ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) مخفف آموخته . تعلیم یافته . یادگرفته <span class=\"hlight\">:</span> <br />بکشتش بسی دشمنان بی شمار<br />که آمخته بد از پدر کارزار.<br /> <font color=\"Red\">دقیقی .</font><br /> <BR><font color=\"Blue\">◄</font> تعلیم داده . یادداده . <BR><font color=\"Blue\">◄</font> در تداول امروزین، خوکرده . معتاد. خوی گرفته . عادت گرفته .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمخته شدن </span> ؛ معتاد شدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمخته کردن </span> ؛ معتاد کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گنجشک آمخته </span> ؛ گنجشک که کودکان آن را روزی چند بار بگاه معلوم طعمه دهند آلوده بافیون و آن را سر دهند و او در همان ساعت بازگردد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل گنجشک آمخته </span> ؛ که در ساعت معلوم هر روز بجائی شود.<br /></font></div>'),
(2264, 'آمد', '<span class=\"hlight\">آمد.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) پر از خیر یا شرّ. بسیارخیر یا بسیارشر. <BR><font color=\"Blue\">◄</font> کشتی پر از بار. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کشتی تهی . (مهذب الاسماء).<br /></font></div>'),
(2265, 'آمد', '<span class=\"hlight\">آمد.</span> <font color=\"DarkGreen\"><b>[م ِ ]</font></b> (اِخ ) نام شهری قدیم و مستحکم در شمال بین النّهرین، و آن با سنگهای سیاه بنا شده و شط دجله آن را چون هلالی احاطه کرده است و در قرب آن چشمه هایی است که شهر را آب دهد. و امروز به دیاربکر معروف است .<br /></font></div>'),
(2266, 'آمد', '<span class=\"hlight\">آمد.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (مص مرخم، اِمص ) اسم مصدر یا مصدر مرخّم آمدن . ایاب . مَجی ٔ.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمد و رفت </span> ؛ رفت و آمد. ایاب و ذهاب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بدآمد</span> ؛ ضجرت . کراهت .<BR>۩ شقاوت . نحوست .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بِه ْآمد</span> ؛ نیک آمد. خیر. سعادت <span class=\"hlight\">:</span> <br />نیک آمد و به آمد خلق خدا ازوست <br />آن بِه ْ بود که قوّت و قدرت بود ورا.<br /> <font color=\"Red\">سوزنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بیرون آمد</span> ؛ خروج <span class=\"hlight\">:</span> و میهم چون خبر بیرون آمد امیر با جعفر بشنید... (تاریخ سیستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خلاف آمد</span> ؛ خلاف کرد. مخالفت . تخالف <span class=\"hlight\">:</span> <br />هرچه خلاف آمدِ عادت بود<br />قافله سالارِ سعادت بود.<br /> <font color=\"Red\">نظامی .</font><br />از خلاف آمدِ عادت بطلب کام، که من <br />کسب جمعیّت از آن زلف پریشان کردم .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خوش آمد</span> ؛ اقبال . مقابل ادبار. سعادت .<BR>۩ تملّق . تَبَصْبُص . مَزیدگوئی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">درآمد</span> ؛ مدخل . مقدّمه (در ساز و آواز).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">رفت و آمد</span> ؛ آمد و رفت . ذهاب و ایاب . ذهاب و مَجی ٔ. مقابل رفت و شد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سرآمد</span> ؛ انقضاء.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نیامد</span> ؛ نحوست . فال بد.<br /> <BR><font color=\"Blue\">◄</font> بازدید، مقابل دید.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">رفت و آمد</span> ؛ دید و بازدید.<br /> <BR><font color=\"Blue\">◄</font> بازگشت . مراجعت . ایاب . <BR><font color=\"Blue\">◄</font> (ن مف مرخم <span class=\"hlight\" dir=\"rtl\">/</span> نف مرخم ) مخفف آمده، در ترکیب با کلمه ٔ دیگر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">پیش آمد</span> ؛ مخفف ِ پیش آمده . حادثه . واقعه . وقعه . عارضه . رویداد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">درآمد</span> ؛ مخفف ِ درآمده . دخل . حاصل . نتیجه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سرآمد</span> ؛مخفف ِ سرآمده . برتر. مقدم . افضل . پیشوا.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کارآمد</span> ؛ مخفف ِ کارآمده . کاردان . فعال .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نوآمد</span> ؛ مخفف ِ نوآمده . نوزاد. نورسیده <span class=\"hlight\">:</span> <br />فریدون چو روشن جهان را بدید<br />بچهر نوآمد <font color=\"DarkGreen\"><b>[ منوچهر ]</font></b> یکی بنگرید.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2267, 'آمد', '<span class=\"hlight\">آمد.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (مص مرخم، اِمص ) اقبال . روی کردن بخت . مقابل ادبار: دیدن روباه در سفر آمددارد. <BR><font color=\"Blue\">◄</font> خجستگی . میمونی . میمنت . مقابل نیامد: سرکه انداختن آمد نیامد دارد؛ یعنی برای بعضی فرخنده و بفال نیک و برای برخی شوم و بفال بد است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمد داشتن </span> ؛ همیشه بفال نیک بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمدِ کار</span> ؛ فال نیک . خجستگی . یمن . میمنت : لانه کردن پرستو در خانه آمد کار است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمد کردن </span> ؛ خجسته، میمون آمدن : قَدَم ِ این عروس بما آمد کرد.<br /></font></div>'),
(2268, 'آمد و رفت', '<span class=\"hlight\">آمد ورفت .</span> <font color=\"DarkGreen\"><b>[ م َ دُ رَ ]</font></b> (ترکیب عطفی، اِمص مرکب ) رفت و آمد. آمد و شد. تردّد. مراوَده . ایاب و ذهاب .<br /></font></div>'),
(2269, 'آمد و شد', '<span class=\"hlight\">آمد و شد.</span> <font color=\"DarkGreen\"><b>[ م َ دُ ش ُ ]</font></b> (ترکیب عطفی، اِمص مرکب ) آمد و رفت . رفت و آمد. اختلاف . ترجرج . تردّد. تطوّح . مراوده .<br /></font></div>'),
(2270, 'آمد و نیامد داشتن', '<span class=\"hlight\">آمد و نیامد داشتن .</span> <font color=\"DarkGreen\"><b>[ م َ دُ ن َ م َ ت َ ]</font></b> (مص مرکب ) آمدنیامد داشتن . برای بعضی یُمن و برای بعضی شآمت داشتن . برای برخی خجسته و میمون و برای برخی شوم و بداُغر بودن : مرغ خواباندن آمد و نیامد دارد. سرکه انداختن آمد و نیامد دارد.<br /></font></div>'),
(2271, 'آمدشد', '<span class=\"hlight\">آمدشد.</span> <font color=\"DarkGreen\"><b>[ م َ ش ُ ]</font></b> (اِمص مرکب ) آمد و شد. رفت و آمد. مراوَده <span class=\"hlight\">:</span> <br />ندانی که ویران شود کاروانگه <br />چو برخیزد آمدشد کاروانی ؟<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> تکرار <span class=\"hlight\">:</span> <br />کشیده دار به دست ادب عنان نظر<br />که فتنه ٔ دل از آمدشد نظر یابی .<br /><font color=\"Red\">کمال اسماعیل .</font><br /></font></div>'),
(2272, 'آمدشدن', '<span class=\"hlight\">آمدشدن .</span> <font color=\"DarkGreen\"><b>[ م َ ش ُ دَ ]</font></b> (مص مرکب ) مراوده . آمدن و رفتن <span class=\"hlight\">:</span> <br />همه روزش آمدشدن پیش اوست <br />که هستند با یکدگر سخت دوست .<br /> <font color=\"Red\">فردوسی .</font><br />به آمدشدن راه کوته کنید<br />روان را سوی روشنی ره کنید.<br /> <font color=\"Red\">فردوسی .</font><br />به نزدیک زال آوریدش بشب <br />بر آمدشدن هیچ نگشاد لب .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2273, 'آمدن', '<span class=\"hlight\">آمدن .</span> <font color=\"DarkGreen\"><b>[ م َ دَ ]</font></b> (مص ) جیاءة. جیئه . اتو. اَتْی . اتیان . اَتْوَة. جَی ْء. (دهار). مَجی ٔ. ایاب . قدوم . مقابل رفتن و شدن و ذهاب <span class=\"hlight\">:</span> <br />شیر خشم آورد و جست از جای خویش <br />آمد آن خرگوش را آلغده پیش .<br /> <font color=\"Red\">رودکی .</font><br />بدینجای از بهر او آمدم <br />بکینه همی جنگجو آمدم .<br /> <font color=\"Red\">فردوسی .</font><br />سوی بیشه ٔ شهر چین آمدند<br />به آمل بروی زمین آمدند.<br /><font color=\"Red\">فردوسی .</font><br />با نعمت تمام بدرگاهت آمدم <br />امروز با گرازی و چوبی همی روم .<br /> <font color=\"Red\">فاخری (از فرهنگ اسدی، خطی ).</font><br />شاهد که با رفیقان آید بجفا کردن آمده است . (گلستان ). <BR><font color=\"Blue\">◄</font> شنیده شدن بوی . استشمام رائحه . مشموم شدن . برخاستن . منتشر گردیدن . ساطع بودن . فائح گشتن . مرتفع گردیدن بوی . نفح . نفاح . فوح . دمیدن بوی . دمیده شدن عطر و جز آن <span class=\"hlight\">:</span><br />از گیسوی او نسیم مشک آید<br />وز زلفک او نسیم نسترون .<br /> <font color=\"Red\">رودکی .</font><br />از زلف تو بوی عنبر و بان آید<br />زآن تنگ دهان هزار چندان آید.<br /> <font color=\"Red\">فرخی .</font><br />ناید بوی عبیر و گل ز سماروغ .<br /> <font color=\"Red\">عنصری .</font><br />از دهان تو همی آید غساک <br />پیر گشتی ریخت مویت از هباک .<br /> <font color=\"Red\">طیان .</font><br />چه سود چون همی ز تو گند آید<br />گر تو به نام احمد عطاری .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> شدن . گشتن . گردیدن <span class=\"hlight\">:</span> <br />ازیرا کارگر نامد خدنگم <br />که بر بازو کمان سام دارم .<br /> <font color=\"Red\">بوطاهر.</font><br />دانی که دل من که فکنده ست بتاراج <br />آن دو خط مشکین که پدید آمدش از عاج .<br /> <font color=\"Red\">دقیقی .</font><br />که یزدان پاک ازمیان گروه <br />برانگیخت ما را <font color=\"DarkGreen\"><b>[ فریدون ]</font></b> ز البرز کوه <br />بدان تا جهان از بد اژدها<br />بفرمان و گرز من آید رها.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد خرامان و بردش نماز<br />ببر در گرفتش زمانی دراز<br />همی چشم و رویش ببوسید دیر<br />نیامد ز دیدار آن شاه سیر.<br /> <font color=\"Red\">فردوسی .</font><br />نهان بود چند از دم اژدها<br />نیامد بفرجام هم زو رها.<br /> <font color=\"Red\">فردوسی .</font><br />که روی زمین از بد اژدها<br />بشمشیر کیخسرو آمد رها.<br /> <font color=\"Red\">فردوسی .</font><br />قلم بساعتی آن کارها تواند کرد<br />که عاجز آید از آن کارها قضا و قدر.<br /> <font color=\"Red\">فرخی .</font><br />نامه ها نبشته آمد و نسخت پیش برد <font color=\"DarkGreen\"><b>[ استاد عبدالغفار ]</font></b> . (تاریخ بیهقی ). لشکر منصور با رایت ما که بدین رباط رسد باید که وی اینجا بحاضر آید. (تاریخ بیهقی ). آنچه از خزانه برداشته اند... بدین معتمد سپارد تا بدان واقف شده آید. (تاریخ بیهقی ). باید نسخت آنچه با کدخدایش بگوزگانان فرستاده است از خزانه بدین معتمد داده آید. (تاریخ بیهقی ). فصلی بخط ما در آخر آن است که عبدوس را فرموده آمد. (تاریخ بیهقی ). و مصرح گفته آمده است که اگر آنچه مثال دادیم بنزد وی آن را امضا نباشد... ناچار ما را باز باید گشت . (تاریخ بیهقی ). خواستم <font color=\"DarkGreen\"><b>[ سلطان مسعود ]</font></b> این شادی بدل امیر برادر رسانیده آید. (تاریخ بیهقی ). چون از سرای عدنانی بگذشته آید باغیست بزرگ . (تاریخ بیهقی ). آنچه فرمودنی بود در هر باب فرموده آید. (تاریخ بیهقی ). و خمارتاش حاجب را نیز فرموده آمد. (تاریخ بیهقی ). از چند سال باز گریخته از برادر بمکران نشانده آید. (تاریخ بیهقی ). و امید می داشتیم که مگر سلطان مسعود وی <font color=\"DarkGreen\"><b>[ امیرمحمد ]</font></b> را بخواند سوی هرات و روشنائی پدیدار آید. (تاریخ بیهقی ). و وی را آرزوهای دیگر خیزد چنانکه فاداده آید یک ناحیت که خواست . (تاریخ بیهقی ). قوت پیغمبران معجزات آمد یعنی چیزها که خلق از آوردن مانند آن عاجز آیند. (تاریخ بیهقی ). و سه روز تعزیت ملکانه برسم داشته آمد. (تاریخ بیهقی ). رسولی نامزد کرد سوی بوجعفر پسر کاکو علاءالدوله و فرستاده آمد. (تاریخ بیهقی ). امیرالمؤمنین بشفاعت نامه ای نوشته بود تا صفاهان بدو بازداده آید. (تاریخ بیهقی ).<br />زمین آمد از اختران بهره مند<br />هم از هر سه ارکان ز چرخ بلند.<br /> <font color=\"Red\">اسدی .</font><br />گهرچهره شد آینه شد نبید<br />که آید در او خوب و زشتی پدید.<br /><font color=\"Red\">اسدی .</font><br />نه ببر و نه گرگ آمد از وی رها<br />نه شیر و نه دیو و نه نر اژدها.<br /> <font color=\"Red\">اسدی .</font><br />هر وعده و هر قول که کرد این فلک و گفت <br />آن وعده خلاف آمد و آن قول مزور.<br /> <font color=\"Red\">ناصرخسرو.</font><br />ز مهر و کین تو ای کوه کین و مهر، جهان <br />توانگر آمد چون کوهسار از آتش و آب .<br /> <font color=\"Red\">مسعودسعد.</font><br />و کس ندانست که آن تیر از کجا آمد هرچند تجسس کردند پدید نیامد. (نوروزنامه ). و این کتاب را از برای فال خوب بر روی نیکو ختم کرده آمد. (نوروزنامه ). تدبیرهاش خطا آمد. (نوروزنامه ). در خواص چنان آورده اند که کودک خرد را چون بدارودان زرش شیر دهند آراسته سخن آید. (نوروزنامه ). و مثال این هم چنان است که مردی در حد بلوغ بر سر گنجی افتد. فرجی بدو راه یابد و در باقی عمر از کسب فارغ آید. (کلیله و دمنه ).و اگر مدت مقام دراز شود و بزیادتی حاجت افتد بازنمای تا دیگر فرستاده آید. (کلیله و دمنه ). در جمله نزدیک آمد که این هراس فکرت و ضجرت بر من مستولی گرداند. (کلیله و دمنه ). اما کاه که علف ستور است خود بتبع حاصل آید. (کلیله و دمنه ). چند فائده ایشان را اندر آن حاصل آمد. (کلیله و دمنه ). مرا بکشید که از گوشت من هریسه نیکو آید. (چهارمقاله ). من که باکالنجارم تا بوقت اسفار سَبَقها بخواندیمی و در پی او نماز کردیمی و تا بیرون آمدمانی هزار سوار از مشاهیر و معاریف و ارباب حوائج و اصحاب عرایض بر در سرای او گرد آمده بودیمی . (چهارمقاله ). و معلوم شد که جگر بط چون پر طاوس وبال او آمد. (مرزبان نامه ). تا حقیقت معنی بر صورت دعوی گواه آمدی . (گلستان ). نه گرفتار آمدی بدست جوانی معجب خیره رای . (گلستان ).<br />بهمه حال اسیری که ز بندی برهد<br />سرخ روتر ز امیری که گرفتار آید.<br /> <font color=\"Red\">سعدی .</font><br />بسمع رضا مشنو ایذای کس <br />و گر گفته آید بغورش برس .<br /> <font color=\"Red\">سعدی .</font><br />و در افعال مرکبه ٔ ذیل نیز همه جا آمدن شدن باشد: باز جای آمدن . بخشم آمدن . پدید آمدن . پر آمدن (قفیز). پیدا آمدن . خواستار آمدن . رها آمدن . ستوه آمدن . سودمند آمدن . شاد آمدن . غالب آمدن . کارگر آمدن . کم آمدن . گرد آمدن .<br /> <BR><font color=\"Blue\">◄</font> کرده شدن <span class=\"hlight\">:</span> <br />ای شاه چه بود اینکه ترا پیش آمد<br />دشمنْت هم از پیرهن خویش آمد<br />از محنتها محنت تو بیش آمد<br />از ملک پدر بهر تو مندیش آمد.<br /> <font color=\"Red\">مکی .</font><br /> <a id=\"fn١٠٠٣٤١\" href=\"#\" onmouseover=\"javascript:ShowTip(\'\' <span class=\"><span class=\"hlight\" dir=\"rtl\">k٠٠l</span>)_&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">rb</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>;یکی چون معبد مطرب دویم چون زلزل رازی &<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">rb</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>;سیم چون ستّی زرین چهارم چون علی مکی .&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">rb</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>;&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">naps</span> <span class=\"hlight\" dir=\"rtl\">ssalc</span>=\\\'\'<span class=\"hlight\" dir=\"rtl\">tnedni</span>\\\'\'&<span class=\"hlight\" dir=\"rtl\">tg</span>;منوچهری .&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">naps/</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>;&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">rb</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>;\'\');\"> <<span class=\"hlight\" dir=\"rtl\">a/</font></div>'),
(2274, 'آمدنی', '<span class=\"hlight\">آمدنی .</span> <font color=\"DarkGreen\"><b>[ م َ دَ ]</font></b> (ص لیاقت )آنکه آمدن او ضروری است . آنکه خود آید <span class=\"hlight\">:</span> <br />آنکس که بود آمدنی آمده بهتر<br />آنکس که بود رفتنی، او رفته شده به .<br /> <font color=\"Red\">منوچهری .</font><br />عشق آمدنی بود نه آموختنی .<br /></font></div>'),
(2275, 'آمدنیامد', '<span class=\"hlight\">آمدنیامد.</span> <font color=\"DarkGreen\"><b>[ م َ ن َ م َ ]</font></b> (اِمص مرکب ) آمد و نیامد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمدنیامد داشتن </span> ؛ آمد و نیامد داشتن . محتمل خجستگی و یمن و شومی و بداُغری بودن . و رجوع به آمد و نیامد داشتن شود.<br /></font></div>'),
(2276, 'آمده', '<span class=\"hlight\">آمده .</span> <font color=\"DarkGreen\"><b>[ م َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف، اِ) رسیده . وارد. واقع. حادث . کائن <span class=\"hlight\">:</span> <br />زآمده شادمان نباید بود<br />وز گذشته نکرد باید یاد.<br /> <font color=\"Red\">رودکی .</font><br />خوارزمشاه اسب بخواست و بجهد برنشست اسب تندی کرد از قضای آمده بیفتادهم بر جانب افکار و دستش بشکست . (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> بدیهه . لطیفه . چربک . نادره <span class=\"hlight\">:</span> <br />بارها درشدی بمجلس خاص <br />گه نوازن بدی ّ وگه رقاص <br />گاه گفتی بشوخی آمده ای <br />گه نمودی بعشوه شعبده ای .<br /> <font color=\"Red\">امیرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> طبیعی، مقابل مصنوع و ساختگی <span class=\"hlight\">:</span> <br />فرق سخن عشق و خرد خواستم از دل <br />گفت آمده دیگر بود و ساخته دیگر.<br /><font color=\"Red\">؟</font><br /></font></div>'),
(2277, 'آمده', '<span class=\"hlight\">آمده .</span> <font color=\"DarkGreen\"><b>[ م َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ) در اصطلاح بنایان، قسمی گچ روان کرده ٔ گشاده و تُنُک یعنی بسیارآب و کم مایه، برای سفید کردن ظاهر بناءچون دیوار و سقف . و بنّایان قُم آن را لایه گویند.<br /></font></div>'),
(2278, 'آمده گوی', '<span class=\"hlight\">آمده گوی .</span> <font color=\"DarkGreen\"><b>[ م َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) بدیهه گوی .<br /></font></div>'),
(2279, 'آمدگی', '<span class=\"hlight\">آمدگی .</span> <font color=\"DarkGreen\"><b>[ م َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) در خمیر، رسیدگی آن . مخمر بودن آن . ورآمدگی آن .<br /></font></div>'),
(2280, 'آمدی', '<span class=\"hlight\">آمدی .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) عبدالواحدبن محمدبن عبدالواحد... تمیمی . وی از علمای اخبار شیعه و صاحب کتاب الغرر و الدرر در کلمات منسوب به حضرت علی بن ابیطالب (ع ) است . (از روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٦٤</span>).<br /></font></div>'),
(2281, 'آمدی', '<span class=\"hlight\">آمدی .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ص نسبی ) منسوب به شهر آمِد. <BR><font color=\"Blue\">◄</font> (اِخ ) نسبت و لقب چند تن از دانشمندان و از آن جمله ابوالفضایل علی بن یوسف بن احمد متوفی در <span class=\"hlight\" dir=\"rtl\">٦٠٨</span> هَ .ق . و سیف الدین ابوالحسن علی بن محمدبن سالم تغلبی متوفی به <span class=\"hlight\" dir=\"rtl\">٦٣١</span> هَ .ق . و ابومحمد محمودبن مودودبن سالم ملقب بسیف الدین صاحب تصانیف .<br /></font></div>'),
(2282, 'آمدی', '<span class=\"hlight\">آمدی .</span><font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) حسن بن بشربن یحیی، مکنی به ابوالقاسم، از مردم بصره و از دانشمندان قرن چهارم هجری و صاحب تألیفاتی بوده است ازجمله : کتاب المختلف و المؤتلف در نامهای شاعران . کتاب معانی شعر البحتری . کتاب نثرالمنظوم . کتاب الموازنة بین ابی تمام و البحتری . کتاب الرد علی علی بن عمار فیما خطاء فیه اباتمام و کتابهای دیگر. و رجوع به الفهرست ابن الندیم ص <span class=\"hlight\" dir=\"rtl\">٢٢١</span> شود.<br /></font></div>'),
(2283, 'آمدیزه', '<span class=\"hlight\">آمدیزه .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) نام قریه ای به بخارا و آن را اَمدیزه نیز گویند.<br /></font></div>'),
(2284, 'آمر', '<span class=\"hlight\">آمر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) فرماینده . فرمانده . کارفرما. صاحب امر. ج، آمِرین . <BR><font color=\"Blue\">◄</font> (اِ) ششم روز از ایام عجوز یا چهارم روز آن .<br /></font></div>'),
(2285, 'آمرا', '<span class=\"hlight\">آمرا.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِ) نام میوه ای بهندوستان شبیه به انبه .<br /></font></div>'),
(2286, 'آمرات', '<span class=\"hlight\">آمرات .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص، اِ) ج ِ آمِره .<br /></font></div>'),
(2287, 'آمرانه', '<span class=\"hlight\">آمرانه .</span> <font color=\"DarkGreen\"><b>[ م ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) چون آمر.<br /></font></div>'),
(2288, 'آمرزش', '<span class=\"hlight\">آمرزش .</span> <font color=\"DarkGreen\"><b>[ م ُ زِ ]</font></b> (اِمص ) بخشیدن خدای تعالی گناه را بر بنده پس از مرگ . مغفرت . غفران . درگذرانیدن از. درگذشتن از خطا. عفو. بخشش . بخشایش . صفح . رحمت . تجاوز. بخشیدن شاه یا مهتری خطای رعیت یا کهتری را <span class=\"hlight\">:</span> <br />گر آمرزش آید ز یزدان پاک <br />شما را ز خون برادر چه باک ؟<br /> <font color=\"Red\">فردوسی .</font><br />گر آمرزش آید شما را ز شاه <br />جز او را مخوانید خورشید و ماه .<br /> <font color=\"Red\">فردوسی .</font><br />اگر پوزش نکو باشد ز کهتر<br />نکوتر باشد آمرزش ز مهتر.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />گفت ای کنیزک گناه ... مهتر تو بزرگتر از آن است که آمرزش توان کرد. (نوروزنامه ). لکن در آن نگر که اگر توفیق باشد... آمرزش بر اطلاق مستحکم شود. (کلیله و دمنه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمرزش خواستن </span> ؛ استغفار. (زوزنی ). بخشایش طلبیدن .<br /></font></div>'),
(2289, 'آمرزشکار', '<span class=\"hlight\">آمرزشکار.</span> <font color=\"DarkGreen\"><b>[ م ُ زِ ]</font></b> (ص مرکب ) آمرزگار. آمرزنده . غافر. عَفُوّ. غفور. غفّار.<br /></font></div>'),
(2290, 'آمرزنده', '<span class=\"hlight\">آمرزنده .</span> <font color=\"DarkGreen\"><b>[ م ُزَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) غافر. بخشاینده . عَفُوّ. غفور.<br /></font></div>'),
(2291, 'آمرزگار', '<span class=\"hlight\">آمرزگار.</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (ص مرکب ) آمرزشکار. آمرزنده . غافر. غفور. غفار. عَفُوّ. حسن التجاوز. کریم الصفح . جمیل الصفح . رحیم . راحم . بخشاینده <span class=\"hlight\">:</span> <br />گناه من ار نامدی در شمار<br />تو را نام کی بودی آمرزگار؟<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(2292, 'آمرزگاری', '<span class=\"hlight\">آمرزگاری .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (حامص مرکب ) غفران . مغفرت . عفو. صفح . تجاوز. رحمت <span class=\"hlight\">:</span> <br />جز این کاعتمادم بیاری ّ تُست <br />امیدم به آمرزگاری ّ تُست .<br /><font color=\"Red\">سعدی (بوستان ).</font><br /></font></div>'),
(2293, 'آمرزیدن', '<span class=\"hlight\">آمرزیدن .</span> <font color=\"DarkGreen\"><b>[ م ُ دَ ]</font></b> (مص ) بخشیدن خدای تعالی گناه بنده را پس از مرگ . بخشیدن بزرگی جرم زیردستی را. مغفرت . غفران . عفو. صفح . اقاله . اغتفار. بخشودن . تجاوز. رحمت <span class=\"hlight\">:</span> <br />گناهم را بیامرز و چنان دان <br />که نیکی گم نگردد در دوگیهان .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />پادشاهان ما را آنانکه گذشته اند ایزدشان بیامرزاد و آنچه برجایند باقی داراد. (تاریخ بیهقی ). بومحمد و ابراهیم گذشته شده اند ایزد ایشان را بیامرزاد. (تاریخ بیهقی ).<br />روان پاک ابوبکر سعد زنگی را<br />خدای پاک بفضل و کرم بیامرزاد.<br /> <font color=\"Red\">سعدی .</font><br />نظیر خویش بنگذاشتند و بگذشتند<br />خدای عز و جل جمله را بیامرزاد.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(2294, 'آمرزیدنی', '<span class=\"hlight\">آمرزیدنی .</span> <font color=\"DarkGreen\"><b>[م ُ دَ ]</font></b> (ص لیاقت ) درخور آمرزیدن . ازدرِ آمرزیدن .<br /></font></div>'),
(2295, 'آمرزیده', '<span class=\"hlight\">آمرزیده .</span> <font color=\"DarkGreen\"><b>[ م ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) مغفور. مرحوم . مَعْفُوّ. شادروان . مُغتفر. بخشوده : پدرآمرزیده .<br /></font></div>'),
(2296, 'آمرزیش', '<span class=\"hlight\">آمرزیش .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b>(اِمص ) آمرزِش <span class=\"hlight\">:</span> نشان آمرزیش آن است که دل تو رقّتی یابد و آرامی یابد بطاعت . (کتاب المعارف ).<br /></font></div>'),
(2297, 'آمرغ', '<span class=\"hlight\">آمرغ .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (اِ) مقدار. قدر. ارز. ارج . محل . وزن . منزلت . قیمت . آب . خطر. بها <span class=\"hlight\">:</span> <br />جوان تاش پیری نیامد بروی <br />جوانی بی آمرغ نزدیک اوی .<br /> <font color=\"Red\">ابوشکور.</font><br />نداند دل آمرغ پیوند دوست <br />بدانگه که با دوست کارش نکوست .<br /> <font color=\"Red\">ابوشکور.</font><br /> <BR><font color=\"Blue\">◄</font> قلیل . اندک . یسیر. ناچیز <span class=\"hlight\">:</span> <br />از عمر نمانده ست برِ من مگر آمرغ <br />در کیسه نمانده ست بمن بر مگر آخال .<br /> <font color=\"Red\">کسائی .</font><br /> <BR><font color=\"Blue\">◄</font> نفع. سود. فائده، مجازاً <span class=\"hlight\">:</span> <br />بیکی دلو سیر گردد مرغ <br />صد درم مر مرا شود آمرغ .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> همت . مقصود عالی . کمال مطلوب . غایت و جدوای معنوی <span class=\"hlight\">:</span> <br />بدو گفت جم کی بت مهرچهر<br />ز چهر تو بر هر دلی مُهر مِهر<br />ز شاهانی ار پیشه ور گوهری <br />پدر برزگر داری ار لشکری <br />که بازاریان مایه دارند و سود<br />کدیور بود مرد کشت و درود<br />بچیزفراوان بوند این دو شاد<br />ندارند آمرغ مردم نژاد<br />سپاهی بمردی نماید هنر<br />بود پادشازادگان را گهر<br />تو زین چار گوهر کدامی بگوی <br />دلم را ره شادمانی بجوی <br />بت زابلی گفت کز این چهار<br />نیَم من جز از تخمه ٔ شهریار.<br /> <font color=\"Red\">اسدی .</font><br /><BR><font color=\"Blue\">◄</font> ذخیره و مایه . حِصّه . اصل و زبده و خلاصه ٔ هر چیز. (برهان ). بفتح میم نیز گفته اند. و معانی و ضبط اخیر ظاهراً همه از حدسهای مختلفی است که در بیت سنائی زده اند.<br /></font></div>'),
(2298, 'آمره', '<span class=\"hlight\">آمره .</span> <font color=\"DarkGreen\"><b>[ م ِ رَ ]</font></b> (ع مص، اِ) مصدر است از اَمر، چون عافیت و عاقبت و خاتمه . فرمان . فرمان دادن . امر. ج، اوامر . <BR><font color=\"Blue\">◄</font> (ص ) تأنیث آمِر. ج، آمِرات .<br /></font></div>'),
(2299, 'آمرین', '<span class=\"hlight\">آمرین .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص، اِ) ج ِ آمِر.<br /></font></div>'),
(2300, 'آمریک', '<span class=\"hlight\">آمریک .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) آمریکا. امریکا. نام یکی از پنج قاره یا قطعات زمین، میان اقیانوس اطلس و اقیانوس ساکن (آرام ). این قطعه را در سال <span class=\"hlight\" dir=\"rtl\">٨٩٧</span> هَ .ق .<span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٤٩٢</span> م . یکی از اهالی ژن موسوم به کریستف کلمب کشف کرد. از مائه ٔ دویم و سیّم هجری اهالی نروژ تا گروآنلند رسیده و شاید سواحل شرقی آمریکای شمالی را نوردیده بودند لیکن این امر عقیم ماند تا اینکه کریستف کلمب و پس از او کاشفین دیگر مانند آمریک وسپوس وکارتیه و کابو و ماژلان و شامپلن و عده ای دیگر با رنج و تعب بسیار بکشف تمام این قاره نائل شدند. امریکارا از لحاظ جغرافیائی بشمالی و مرکزی و جنوبی تقسیم کنند. وسعت آن چهار برابر اروپاست . معادن طلا و نقره و الماس و مس و زغال سنگ و قلعی و نفت و آهن بسیار دارد. محصولات زراعتی آن گندم و ذرت و دوسر و قند و قهوه و گیاههای صنعتی و توتون، پنبه، کائوچوک، گنه گنه، نیل و خشخاش است . و اغنام و احشام آن فراوان است .<br />علاوه بر بومیان یعنی سکنه ٔ اصلی که از نژاد سرخ پوست و غیره می باشند از نژاد سفید مهاجرین بسیار فرانسوی، اسپانیولی، پرتغالی و انگلیسی در نواحی مختلف آن ساکن شده و دولتها تشکیل داده اند. ممالک و قسمتهای جزء عمده ٔ آن در شمال آلاسکا و کانادا و دول متحده ٔ اتازونی و مکزیک و در مرکز گواتمالا، سالوادور، نیکاراگوآ، هندوراس، کوستاریکا و پاناما، و در جنوب، کلمبیا، اکواتر، بولیوی، پرو، شیلی، وِنِزوئلا، گویان، برزیل، پاراگوآ، اوروگوآ و آرژانتین است . و رود عظیم آمازن در امریکای جنوبی است . و این قاره را در تداول فارسی ینگی دنیا نیز گویند.<br /></font></div>'),
(2301, 'آمریک وسپوس', '<span class=\"hlight\">آمریک وسپوس .</span> <font color=\"DarkGreen\"><b>[ م ِ وِ ]</font></b> (اِخ ) (<span class=\"hlight\" dir=\"rtl\">٨٥٤</span> - <span class=\"hlight\" dir=\"rtl\">٩١٧</span> هَ .ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٤٥١</span>-<span class=\"hlight\" dir=\"rtl\">١٥١٢</span> م .) نام دریانوردی از مردم فلورانس . چهار بار پس از آنکه کلمب امریکا را کشف کرد بدان قارّه سفر کرده و از اینرو آن سرزمین به نام او موسوم شده است .<br /></font></div>'),
(2302, 'آمس', '<span class=\"hlight\">آمس .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (ع اِ) آماس . ج ِ اَمْس .<br /></font></div>'),
(2303, 'آمستردام', '<span class=\"hlight\">آمستردام .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) پایتخت کشور هُلاند (هلند). شهری صنعتی و بندری تجارتی در ساحل لامستل و ترعه ای بطول <span class=\"hlight\" dir=\"rtl\">٥٠٠</span>هزارگز آن را بدریای شمال پیوندد، دارای <span class=\"hlight\" dir=\"rtl\">٧٤٩٥٠٠</span> سکنه .<br /></font></div>'),
(2304, 'آمص', '<span class=\"hlight\">آمص .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (معرب، اِ) (معرّب خامیز) گوشت خام که در سرکه پرورند. <BR><font color=\"Blue\">◄</font> طعامی از گوشت یا پوست گوساله . <BR><font color=\"Blue\">◄</font> شوربای سکباج سرد که روغن آن را پس از سرد شدن بردارند. و آن را آمیص نیز گویند.<br /></font></div>'),
(2305, 'آمل', '<span class=\"hlight\">آمل .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) امیدوار.<br /></font></div>'),
(2306, 'آمل', '<span class=\"hlight\">آمل .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (اِخ ) نام شهری بغربی جیحون بفاصله ٔ یک میل در راه بخارا از سوی مرو، مقابل فربرا یا فربر که بشرقی جیحون است و آن را عامه آمو و آمویه گویند. و از آنجاست عبداﷲبن حماد شیخ بخاری و احمدبن عبده شیخ ابی داود. و برای تمیز از آمل طبرستان آن را آمل زم و آمل شط و آمل مفازه نیز خوانند. و این شهر را قوم تاتار ویران کردند. <BR><font color=\"Blue\">◄</font> رود جیحون . <BR><font color=\"Blue\">◄</font> نام شهری بزرگ بطبرستان <font color=\"DarkGreen\"><b>[ مازندران ]</font></b> در <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی محمودآباد و <span class=\"hlight\" dir=\"rtl\">٣٦</span>هزارگزی بابل . دارای پست و تلگراف . و در کتب قدیمه فاصله ٔ آن را تا ساری هیجده فرسنگ و تا رویان دوازده و تا چالوس (شالوس ) نیز دوازده فرسنگ نوشته اند. و ازاین شهر است محمدبن جریر طبری و فضل بن احمد زهری و سیدحیدر آملی و عده ای کثیر از علما و محدثین دیگر.<br />و صاحب حدودالعالم گوید: آمل شهری است عظیم <font color=\"DarkGreen\"><b>[ از دیلمان بناحیت طبرستان ]</font></b> و قصبه ٔ طبرستان است و او را شهرستانیست با خندق بی باره و از گِرد وی ربض است و مستقر ملوک طبرستان است و جای بازرگانان است و خواسته بسیار است و اندر وی علمای بسیارند بهر علمی و آبهای روان است سخت بسیار و از وی جامه ٔ کتان و دستار خیش و فرش طبری و حصیر طبری وچوب شمشاد خیزد که بهمه ٔ جهان جائی دیگر نبود و از وی ترنج و نارنج خیزد و گلیم سپید کومس و گلیم دیلمی زربافت و دستارچه ٔ زربافت گوناگون و کیمخته خیزد و از وی آلاتهای چوبین خیزد چون کفچه و شانه و شانه نیام و ترازوخانه و کاسه و طبق و طینوری و آنچ بدین ماند- انتهی . و صاحب معجم البلدان گوید: آمل ... نام بزرگترین ِ شهرهای طبرستان بزمین هامون و دشت و جزء اقلیم چهارم، طول آن <span class=\"hlight\" dir=\"rtl\">٧٧</span> درجه و ثلث و عرض <span class=\"hlight\" dir=\"rtl\">٣٧</span> درجه و سه ربعاست . بین آمل و ساریه هشت و میان آمل و رویان دوازده و فاصله ٔ آن تا شالوس (چالوس ) دوازده فرسنگ است . از مصنوعات آمل سجاده های نیکوست - انتهی . و حمداﷲ مستوفی گوید: آمل از اقلیم چهارم باشد طولش از جزایر خالدات نزک و عرض آن از خط استوا لز. طهمورث ساخت شهری بزرگ است و هوایش بگرمی مایل و مجموع میوه های سردسیری و گرمسیری از لوز و جوز و انگور و خرما و نارنج وترنج و لیمو و مرکب و غیره فراوان باشد و مشمومات بغایت خوب و فراوان چنانچه اگر شهربند شود هیچ چیز ازبیرون احتیاج نباشد - انتهی . رود هراز از این شهر گذرد و معادن ذغال سنگ و آهن در ناحیت آمل بسیار است وآهن آن را در قدیم نیز استخراج می کرده اند. و شهر کنونی آمل بر خرابه های شهر قدیم بنا شده است و ظاهراً این شهر یک یا چند بار از طغیان رود هراز یا علل دیگرویران گردیده است . عده ٔ سکنه ٔ فعلی آن ده هزار است . و حدود فعلی این ناحیت از شمال دریای خزر و از مشرق سوادکوه و بارفروش و از جنوب لاریجان و از مغرب نمارستاق است <span class=\"hlight\">:</span> <br />بر فلک برداشته خورشید جام آملی <br />بر سها بنواخته ناهید چنگ رامتین .<br /> <font color=\"Red\">عبدالواسع جبلی .</font><br />زمکث ملتان نزدیک شد بدانکه مرا<br />بدل شود لقب آملی بملتانی .<br /> <font color=\"Red\">طالب آملی .</font><br />بلی چو بلبل آمل شود ترانه سرای <br />چه جای زمزمه ٔعندلیب شیراز است ؟<br /> <font color=\"Red\">طالب آملی .</font><br /><BR><font color=\"Blue\">◄</font> نام شهری به روم .<br /></font></div>'),
(2307, 'آمل زم', '<span class=\"hlight\">آمل زم .</span> <font color=\"DarkGreen\"><b>[ م ُ زَ ]</font></b> (اِخ ) آمل شط. آمل مَفازه . رجوع به آمل شود.<br /></font></div>'),
(2308, 'آملج', '<span class=\"hlight\">آملج .</span> <font color=\"DarkGreen\"><b>[ م ُ ل َ ]</font></b> (معرب، اِ) مُعرّب آمله .<br /></font></div>'),
(2309, 'آمله', '<span class=\"hlight\">آمله .</span> <font color=\"DarkGreen\"><b>[ م ِ ل َ ]</font></b> (ع ص ) تأنیث آمِل .<br /></font></div>'),
(2310, 'آمله', '<span class=\"hlight\">آمله .</span> <font color=\"DarkGreen\"><b>[ م ِ <span class=\"hlight\" dir=\"rtl\">/</span> م ُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b>(اِ) آملج . نام درختی هندی که ثمره ٔ آن را نیز آمله گویند. طعم آن ترش و عفص و نازک چون آلوگوجه ببزرگی گردکانی و خردتر درخت آن ببالای گردکان . برگ آن ریزه و انبوه از دو سوی شاخ بقدر شبری رسته گاهی بدو شاخه و گاهی بسه شاخه و چوب آن از چنار سختتر بود <span class=\"hlight\">:</span> و اندر میان رامیان و جالهندر <font color=\"DarkGreen\"><b>[ هندوستان ]</font></b> پنج روزه راه است و همه ٔ راه درختان هلیله و بلیله و آمله و داروهاست که بهمه ٔ جهان ببرند. (حدودالعالم ).<br />پای ز گل برکشی بطاعت به زآنک <br />روی بشوئی همی به آمله و گل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چون نشوئی دل بدانش همچنانک <br />موی را شوئی به آب آمله ؟<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمله ٔ پرورده </span> ؛ آمله ٔ مربّابشکر یا عسل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">شیرآمله </span> ؛ عبارت از آمله ٔمالیده ٔ منقی از دانه است که چند بار در شیر تر نهند و سپس شسته و خشک کنند تا قوت آن کم و صالح برای استعمال شود.<br /></font></div>'),
(2311, 'آملیلس', '<span class=\"hlight\">آملیلس .</span> <font color=\"DarkGreen\"><b>[ م ِ لی ل ِ ]</font></b> (اِ) آآمِلیلِس . بلغت بربری و مغربی نباتیست میان شج-ر و گ-یاه و در بلاد مغرب باشد. طول آن چندِ قامت آدمی و زیادت . برگش چون مورْد و نرم، ثمرش باندازه ٔ بار سرو. ابتدا سبز و چون برسد سیاه و نرم شود. چوب آن سخت و صلب و اندرون آن سپید و زرد مایل بسرخی و ریشه های باریک آن در طب مستعمل و از قابضات است .<br /></font></div>'),
(2312, 'آمن', '<span class=\"hlight\">آمن .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) بزینهار. بازینهار. بی بیم . بی خوف . ایمن . استواردارنده بی بیمی .<br /></font></div>'),
(2313, 'آمن', '<span class=\"hlight\">آمن .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ع ن تف ) استوارتر.<br /></font></div>'),
(2314, 'آمنن', '<span class=\"hlight\">آمنن .</span> <font color=\"DarkGreen\"><b>[ ن ُ ]</font></b> (اِخ ) نام ارشد اولاد داود. <BR><font color=\"Blue\">◄</font> نام مردی از نسل یهودا.<br /></font></div>'),
(2315, 'آمنه', '<span class=\"hlight\">آمنه .</span> <font color=\"DarkGreen\"><b>[ م ِ ن َ ]</font></b> (اِخ ) نامی است زنان عرب را و ازجمله آمنه ٔ بنت عبدالمطلب و آمنه ٔ بنت وهب بن عبدمناف زوجه ٔ عبداﷲبن عبدالمطلب مادر رسول صلوات اﷲعلیهما متوفّات <span class=\"hlight\" dir=\"rtl\">٤٨</span> پیش از هجرت . و آمنه ٔ بنت ابی سفیان، زوجه ٔ پیغامبر صلوات اﷲ علیه . و نام هفت صحابیه .<br /></font></div>'),
(2316, 'آمنه', '<span class=\"hlight\">آمنه .</span> <font color=\"DarkGreen\"><b>[م َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) اَمَنه . پشته ٔ هیزم <span class=\"hlight\">:</span> <br />از آنکه گفتم کوه خشک مرا ملک است <br />بخشک چوبی مالک کشید بر دارم <br />هزار آمَنه هیزم همه ز کوه خشک <br />نهاده اند در انبار و من در انبارم .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(2317, 'آمنون', '<span class=\"hlight\">آمنون .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص، اِ) ج ِ آمِن <span class=\"hlight\">:</span> <br />عارفان زآنند دایم آمنون <br />که گذر کردند از دریای خون .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(2318, 'آمنیاک', '<span class=\"hlight\">آمنیاک .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (فرانسوی، اِ) آمونیاک . جسمی است که از زغال سنگ به دست کنند و در طب بکار است و خاصه مالیدن آن بجای گزیدگیهای عقرب و زنبور و مانند آن نهایت سودمند باشد.<br /></font></div>'),
(2319, 'آمنین', '<span class=\"hlight\">آمنین .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص، اِ) آمِنون . ج ِ آمِن .<br /></font></div>'),
(2320, 'آمه', '<span class=\"hlight\">آمه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ) ظرف که در آن سیاهی کنند نوشتن را. دوات . دویت . خوالستان . خوالسته . مِحْبَره . سیاهی دان <span class=\"hlight\">:</span> <br />ای ترا تنبک آمه نی خامه <br />لوح تعلیم تخته ٔ نرد است .<br /> <font color=\"Red\">طرطری .</font><br /><BR><font color=\"Blue\">◄</font> اَمنه، به معنی پشته ٔ هیزم و شاید یکی از دو کلمه ٔ آمنه و آمه بدین معنی، مصحف دیگری باشد.<br /></font></div>'),
(2321, 'آمه', '<span class=\"hlight\">آمه .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ع اِ) فراخی سال . <BR><font color=\"Blue\">◄</font> باران . <BR><font color=\"Blue\">◄</font> آنچه می برند از ناف کودک یا خرقه ای که کودک را درآن پیچند. <BR><font color=\"Blue\">◄</font> آنچه برمی آید با کودک زمان زادن . <BR><font color=\"Blue\">◄</font> عیب . نقصان . <BR><font color=\"Blue\">◄</font> ذلت .<br /></font></div>'),
(2322, 'آمه', '<span class=\"hlight\">آمه .</span> <font color=\"DarkGreen\"><b>[ آم ْ م َ ]</font></b> (ع ص ) شکستگی سر که میان او و میان دماغ پوستکی تُنُک ماند. (السامی فی الاسامی ). مأمومه .<br /></font></div>'),
(2323, 'آمو', '<span class=\"hlight\">آمو.</span> (اِخ ) رود آموی . آمُل . آمویه . جیحون . آمودریا. اُقسوس . آمون . آب . رود. آبهی . نهر. ورز. <BR><font color=\"Blue\">◄</font> نام شهری بکنارجیحون . آمُل . و نام قلعه ای هم بدانجای <span class=\"hlight\">:</span> <br />ریگ آموی و درشتیهای او<br />زیر پایم پرنیان آید همی .<br /> <font color=\"Red\">رودکی .</font><br />مرا هجران آن آهوی آمو<br />همی دارد چو بچه مرده آهو<br />بدرد اندر دوان زینجا بدانجا<br />ز رنج اندر نوان زین سو بدان سو.<br /> <font color=\"Red\">قطران .</font><br />شخصم چو موی گشت و عجب تر نگر که کرد<br />اشکم چو چشم چشمه ٔ آموی موی او.<br /> <font color=\"Red\">سیدحسن غزنوی .</font><br />گرش باشد سوی جیحون گذاری <br />بحیله قلعه ٔ آمو بدزدد.<br /> <font color=\"Red\">خواجوی کرمانی .</font><br />سرچشمه ٔ این رود بلورکوه است بمشرق بدخشان، و در سابق این رود بخزر میریخته و مغولان گاه جنگ با خوارزمشاه مجرای آن بگردانیدندبه بحیره ٔ ارال . طول این رود نهصد میل و آبش بخوشگواری معروف است .<br /><BR><font color=\"Blue\">◄</font> نام دشتی ریگزار و پهناور است میان مرو و بخارا. و شهر آمو به نزدیکی این دشت واقع است .<br /></font></div>'),
(2324, 'آموت', '<span class=\"hlight\">آموت .</span> (اِ) آشیان مرغان شکاری مانند باز و عقاب و شاهین . آشیانه <span class=\"hlight\">:</span> <br />بر قله ٔقاف بخت و اقبال <br />آموت عقاب دولت تست .<br /> <font color=\"Red\">منجیک .</font><br />و الموت، مرکب از آلُه ْ به معنی عقاب و موت مخفف آموت به معنی آشیان است .<br /></font></div>'),
(2325, 'آموتیا', '<span class=\"hlight\">آموتیا.</span> (هزوارش، اِ) هزوارش اَمه خادمه و پرستار است .<br /></font></div>'),
(2326, 'آموختن', '<span class=\"hlight\">آموختن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص )تعلّم . فراگرفتن . یاد گرفتن . بیاموختن <span class=\"hlight\">:</span> <br />بیاموز تا بد نیایدْت روز<br />چو پروانه مر خویشتن را مسوز.<br /> <font color=\"Red\">ابوشکور.</font><br />بیاموز هرچند بتوانیا<br />مگر خویشتن شاد گردانیا.<br /> <font color=\"Red\">ابوشکور.</font><br />ز هر دانشی گر سخن بشنوی <br />ز آموختن یک زمان نغنوی .<br /> <font color=\"Red\">فردوسی .</font><br />... بجان خواستند <font color=\"DarkGreen\"><b>[ دیوان ]</font></b> آن زمان زینهار...<br />که ما را مکش تا یکی نو هنر<br />بیاموزی از ما کِت آید ببر.<br /> <font color=\"Red\">فردوسی .</font><br />چو شد بافته <font color=\"DarkGreen\"><b>[ پارچه ها ]</font></b> شستن و دوختن <br />گرفتند از او یکسر آموختن .<br /> <font color=\"Red\">فردوسی .</font><br />هنوز این نیاموخت آیین جنگ <br />همی خوار گیرد نبرد پلنگ .<br /> <font color=\"Red\">فردوسی .</font><br />بزرگان ز تو دانش آموختند<br />بتو تیره گیتی برافروختند.<br /> <font color=\"Red\">فردوسی .</font><br />به آموختن گر ببندی میان <br />ز دانش رَوی بر سپهر روان .<br /> <font color=\"Red\">فردوسی .</font><br />هنر آنگه آموزی از هر کسی <br />بکوشی ّ و پیچی ز رنجش بسی .<br /> <font color=\"Red\">فردوسی .</font><br />بیاموخت <font color=\"DarkGreen\"><b>[داراب ]</font></b> فرهنگ و شد پُرمنش <br />برآمد ز بیغاره و سرزنش .<br /> <font color=\"Red\">فردوسی .</font><br />یکی باره از موبدان رای و راه <br />بیاموز ازرفت و آیین شاه .<br /> <font color=\"Red\">فردوسی .</font><br />چو گوئی همان گو که آموختی <br />به آموختن در، جگر سوختی .<br /> <font color=\"Red\">فردوسی .</font><br />ولیکن از آموختن چاره نیست <br />که گوید که دانا و نادان یکی است ؟<br /> <font color=\"Red\">فردوسی .</font><br />مگرآنکه تا دین بیاموختم <br />همی در جهان آذر افروختم .<br /> <font color=\"Red\">فردوسی .</font><br />از او زند و استا بیاموختند<br />نشستند و آتش برافروختند.<br /> <font color=\"Red\">فردوسی .</font><br />با علی خیزد هر کز تو بیاموزد علم <br />با عمر خیزد هر کز تو بیاموزد داد.<br /> <font color=\"Red\">فرخی .</font><br />چنین چیزها از وی آموختندی که مهذب تر و مهترتر روزگار بود. (تاریخ بیهقی ). چنان واجب کندی که ایشان نبشتندی و من بیاموزیدمی . (تاریخ بیهقی ).<br />گرد گرداب مگرد ارْت نیاموخت شنا<br />که شوی غرقه چو ناگاهی ناغوش خوری .<br /> <font color=\"Red\">اسدی (از فرهنگ، خطی ).</font><br />آموختن توان ز یکی خویش صد ادب <br />افروختن توان ز یکی شمع صد چراغ .<br /> <font color=\"Red\">قطران .</font><br />که بر کس نیست از آموختن عار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چو باطل را نیاموزی ز دانش <br />ندانی قیمت حق ای برادر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />اگر تو ز آموختن سر نتابی <br />بجوید سر تو همی سروری را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />بیاموز تا همچو سلمان بباشی <br />که سلمان از آموختن گشت سلمان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بیاموز اگر چند دشوارت آید<br />که دشوار از آموختن گشت آسان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ز جهل خویش چون عارت نیاید<br />چرا داری همی زآموختن عار؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />عار همی داری از آموختن <br />شرم همی نایدت از عار خویش ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />بیاموز تا دین بیابی ازیرا<br />ز بی علمی آید همی بی فساری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />اگر قیمتی دُرّْ خواهی که باشی <br />به آموختن گوهر جان بپرور.<br /> <font color=\"Red\">ناصرخسرو.</font><br />گفت چه پیشه می آموزی گفت قرآن حفظ می کنم . (نوروزنامه ). غایت نادانی است ... آموختن علم به آسایش . (کلیله و دمنه ). و هرکه بی وقوف در کاری شروع نماید همچنان باشدکه گویند مردی می خواست تازی آموزد... (کلیله و دمنه ). دزدان بشنودن آن ماجری ̍ و به آموختن افسون شاد شدند. (کلیله و دمنه ). گفت <font color=\"DarkGreen\"><b>[ دزدی ]</font></b> می خواهم ... آداب طریقت آموزم . (کلیله و دمنه ).<br />علم کز بهر حشمت آموزی <br />حاصلش رنج دان و بدروزی .<br /> <font color=\"Red\">سنائی .</font><br />کسی ننگ دارد ز آموختن <br />که از ننگ نادانی آگاه نیست .<br /> <font color=\"Red\">امام الدین الرافعی (از تاریخ گزیده ).</font><br />هرکه زآموختن ندارد ننگ <br />دُر بر آرد ز آب و لعل از سنگ .<br /> <font color=\"Red\">نظامی .</font><br />لقمان را گفتند ادب از که آموختی ؟ گفت از بی ادبان . (گلستان ). دو کس رنج بیهوده بردند... یکی آنکه اندوخت و نخورد و دیگر آنکه آموخت و نکرد. (گلستان ).<br />از بدان نیکوئی نیاموزی .<br /> <font color=\"Red\">سعدی .</font><br />ای مرغ سحر عشق ز پروانه بیاموز<br />کآن سوخته را جان شد و آواز نیامد.<br /> <font color=\"Red\">سعدی .</font><br />من آدمی بچنین شکل و خوی و قد و روش <br />ندیده ام مگر این شیوه از پری آموخت .<br /> <font color=\"Red\">سعدی .</font><br />تو به آموختن بلند شوی <br />تا بدانی ّ و ارجمند شوی .<br /> <font color=\"Red\">اوحدی .</font><br />کمال این گفته گر مرغی برد بر پر بهندستان <br />بیاید طوطی و از تو سخن آموختن گیرد.<br /> <font color=\"Red\">کمال خجندی .</font><br /> <BR><font color=\"Blue\">◄</font> تعلیم . یاد دادن . آموزانیدن . آموزاندن <span class=\"hlight\">:</span> <br />برآمد <font color=\"DarkGreen\"><b>[ آزاد سرو ]</font></b> همی گِرد مرو و بجست <br />یکی موبدی دید با زند و اُست <br />همی کودکان را بیاموخت زند<br />به تندی ّ و خشم و ببانگ بلند.<br /> <font color=\"Red\">فردوسی .</font><br />نبشتن مراورا <font color=\"DarkGreen\"><b>[ تهمورث را ]</font></b> بیاموختند<br />دلش را بدانش برافروختند.<br /> <font color=\"Red\">فردوسی .</font><br />جوان گفت برگوی چندین مپای <br />بیاموز ما را تو ای نیک رای .<br /> <font color=\"Red\">فردوسی .</font><br />بیاموختش رزم و بزم و خرد<br />همی خواست کز روز رامش برد.<br /> <font color=\"Red\">فردوسی .</font><br />بیاورد و آموختنْشان گرفت <br />جهانی بدو مانده اندر شگفت .<br /> <font color=\"Red\">فردوسی .</font><br />سواری ّ و می خوردن و بارگاه <br />بیاموخت رستم بدان کینه خواه .<br /> <font color=\"Red\">فردوسی .</font><br />هنرها بیاموختش سربسر<br />بسی رنج برداشت کآمد ببر.<br /> <font color=\"Red\">فردوسی .</font><br />بیاموز او را ره و ساز رزم <br />همان شادکامی ّ و آئین بزم .<br /> <font color=\"Red\">فردوسی .</font><br />همان کن که با مهتری درخورد<br />ترا خود نیاموخت باید خرد.<br /> <font color=\"Red\">فردوسی .</font><br />بیاموزم این کودکان را همی <br />برون زین نیارم زدن خود دمی .<br /> <font color=\"Red\">فردوسی .</font><br />بسی رنج بردی ّ و دل سوختی <br />هنرهای شاهانم آموختی .<br /> <font color=\"Red\">فردوسی .</font><br />چو مرا بویه ٔ درگاه تو خیزد چه کنم <br />رهی آموز رهی را واز این غم برهان .<br /> <font color=\"Red\">فرخی .</font><br />امیرمسعود گفت عبدالغفار را از ادب چیزی بیاموزد، وی قصیده ای دو سه از متنبی مرا بیاموخت .(تاریخ بیهقی ).<br />اصل دین آموخت پیغمبر اگر منکر شوی <br />کافران راکشتن از بهر شهادت چیست پس ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />بیاموزید فرزندان را تیراندازی وشناو. (نوروزنامه ).<br />هرکه رااسرار حق آموختند<br />مهر کردند و دهانش دوختند.<br /> <font color=\"Red\">مولوی .</font><br />معلمت همه شوخی ّ و دلبری آموخت <br />جفا و ناز و عتاب و ستمگری آموخت .<br /> <font color=\"Red\">سعدی .</font><br />مصدر دیگر این فعل آموزش است .<br />آموختم . بیاموز.<br /></font></div>'),
(2327, 'آموختن', '<span class=\"hlight\">آموختن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص ) آمیختن : التضییح ؛ شیر به آب بیاموختن . (زوزنی ).<br /></font></div>'),
(2328, 'آموختنی', '<span class=\"hlight\">آموختنی .</span> <font color=\"DarkGreen\"><b>[ ت َ]</font></b> (ص لیاقت ) درخور آموختن . قابل آموختن <span class=\"hlight\">:</span> <br />عشق آمدنی بود نه آموختنی .<br />ای سوخته ٔ سوخته ٔ سوختنی ...<br /> <BR><font color=\"Blue\">◄</font> آموختن <span class=\"hlight\">:</span> <br />حق را تو کجا و رحمت آموختنی .<br /><font color=\"Red\">(منسوب به خیام ).</font><br /></font></div>'),
(2329, 'آموخته', '<span class=\"hlight\">آموخته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آمُخته . یادگرفته . متعلِّم . <BR><font color=\"Blue\">◄</font> فرهخته . مؤدَّب . <BR><font color=\"Blue\">◄</font> مدرَّب . دست آموز. رام شده .مأنوس . مربّی ̍. خوگر. خوگرفته . معتاد <span class=\"hlight\">:</span> <br />وزآن پس برفتند سیصد سوار<br />پس ِ بازداران همه یوزدار...<br />پلنگان و شیران آموخته <br />بزنجیر زرین دهان دوخته .<br /> <font color=\"Red\">فردوسی (از فرهنگ نویسان ).</font><br />روان گرد بر گرد اسپرغمی را<br />تَذَروان آموخته ماده و نر.<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آموخته شدن </span> ؛ خو گرفتن . عادت کردن . معتاد شدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آموخته کردن </span> ؛ دست آموز کردن . عادت دادن به .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل گنجشک آموخته </span> ؛ سخت مأنوس .<br /><BR><font color=\"Blue\">◄</font> آمیخته .<br /></font></div>'),
(2330, 'آموختگار', '<span class=\"hlight\">آموختگار.</span> (ص مرکب ) معتادٌبِه . چشته خور. مسته خوار <span class=\"hlight\">:</span> گفت زینهار که به آموختگارم مگیرید. (اسرار التوحید).<br /></font></div>'),
(2331, 'آموختگان', '<span class=\"hlight\">آموختگان .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (اِ) ج ِ آموخته <span class=\"hlight\">:</span> <br />صعب است جدائی بهم آموختگان را.<br /><font color=\"Red\">؟</font><br /></font></div>'),
(2332, 'آموختگی', '<span class=\"hlight\">آموختگی .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص ) اُنس . خوی گرفتگی .<br /></font></div>'),
(2333, 'آمود', '<span class=\"hlight\">آمود.</span> (ن مف مرخم ) در کلمات مرکبه چون گوهرآمود و مانند آن، بگوهرکشیده . مُنسلک به ... در رشته های آن گوهر درآورده . در تارهای آن گوهر منسلک کرده . <BR><font color=\"Blue\">◄</font> مرصع. درنشانده <span class=\"hlight\">:</span> <br />گرفته مهد را در تخته ٔ زر<br />برآموده بمروارید و گوهر.<br /> <font color=\"Red\">نظامی .</font><br />نشاندش بر سریر گوهرآمود<br />زمین را کرد از لب شکّرآلود.<br /> <font color=\"Red\">امیرخسرو.</font><br />مگر سیل آمد از دریای مقصود<br />که شد پای حریفان گوهرآمود؟<br /><font color=\"Red\">امیرخسرو.</font><br /></font></div>'),
(2334, 'آمودریا', '<span class=\"hlight\">آمودریا.</span> <font color=\"DarkGreen\"><b>[ دَرْ ]</font></b> (اِخ ) نام باستانی جیحون، و آن رودیست میان خراسان و ماورأالنهر و یونانیان آن را به نام اوقسوس یاد کرده اند. آمو. جیحون . رود. ورز. آب . النهر. آمل . آمون . آبهی .<br /></font></div>'),
(2335, 'آمودن', '<span class=\"hlight\">آمودن .</span> <font color=\"DarkGreen\"><b>[ دَ]</font></b> (مص ) آمیختن . درهم کردن . آمیخته شدن <span class=\"hlight\">:</span> <br />فسونی چند با خواهش برآمود<br />فسون کردن ببابل کی کند سود؟<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> ترصیع. درنشاندن، چنانکه گوهری را <span class=\"hlight\">:</span> <br />در آمودن آن همایون بنا<br />نماند ایچ باقی بگنجینه ها.<br /> <font color=\"Red\">دقیقی .</font><br /> <BR><font color=\"Blue\">◄</font> بسلک درآوردن . منسلک کردن . نخ کردن . بتار و به نخ کشیدن گوهرها و مهره ها و مانند آن . گوهرکش کردن <span class=\"hlight\">:</span> <br />برآموده چون نرگس و مشک بید<br />بموی سیه مهره های سپید.<br /> <font color=\"Red\">نظامی .</font><br />برآموده گوهر بمشکین کمند<br />فروهشته بر گوهرآگین پرند.<br /> <font color=\"Red\">نظامی .</font><br />سرآغوشی برآموده بگوهر<br />برسم چینیان افکنده بر سر.<br /> <font color=\"Red\">نظامی .</font><br />دو خرگه داشتی خسرومهیا<br />برآموده بگوهر چون ثریا.<br /> <font color=\"Red\">نظامی .</font><br />چون حرز تواَم حمایل آمود...<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> آراسته شدن . (برهان ). <BR><font color=\"Blue\">◄</font> آراستن . زینت کردن با <span class=\"hlight\">:</span> <br />گفت مشاطه راکه خلد آرای <br />یعنی آن لعبت چگل آمای .<br /> <font color=\"Red\">عمعق .</font><br />گذارنده صراف گوهرفروش <br />سخن را بگوهر برآموده گوش .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">برآموده شدن </span> ؛ آراسته و ساخته شدن <span class=\"hlight\">:</span> <br />دگرباره در جنبش آمد نشاط<br />برآموده شد خسروانی بساط.<br /> <font color=\"Red\">امیرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> مهیا، معد، آماده کردن . آراستن کاری را <span class=\"hlight\">:</span><br />گرانمایه سپاهی داشت فرمود<br />به استقبال شهزاده برآمود.<br /> <font color=\"Red\">فخرالدین ابوالمعالی .</font><br /> <BR><font color=\"Blue\">◄</font> پر کردن . مملو ساختن . (برهان ). وفرهنگها بیت ذیل را شاهد این معنی آورده اند <span class=\"hlight\">:</span> <br />گزارنده صراف گوهرفروش <br />سخن را بگوهر برآموده گوش .<br /> <font color=\"Red\">نظامی .</font><br />و این غلط است، چه کلمه در این جاآراسته و مزین است .<br />اسم مصدر و مصدر دوم آن آزمایش است : آمودم، آمای .<br /></font></div>'),
(2336, 'آموده', '<span class=\"hlight\">آموده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آراسته . متحلی <span class=\"hlight\">:</span> <br />بخوی خوش آموده بِه ْ گوهرم <br />بر این زیستم هم بر این بگذرم .<br /> <font color=\"Red\">نظامی .</font><br />رجوع به آمای و آمود و آمودن شود. <BR><font color=\"Blue\">◄</font> پرکرده . انباشته . (از برهان ). مندرج .<br /></font></div>'),
(2337, 'آمور', '<span class=\"hlight\">آمور.</span> (اِخ ) نام رودی بزرگ، فاصل سیبریا و منچوری، و آن را ساخالین نیز نامند.<br /></font></div>'),
(2338, 'آموریان', '<span class=\"hlight\">آموریان .</span> (اِخ ) قومی از سوریان که نسب به کنعان بن نوح می رسانیدند و در میان اردُن و بحر متوسط مسکن داشتند و سپس درصدد توسعه ٔ مملکت خویش برآمدند و سرانجام تمام باشان را متصرف شدند.<br /></font></div>'),
(2339, 'آموز', '<span class=\"hlight\">آموز.</span> (نف مرخم ) در کلمات مرکبه چون بدآموز و خودآموز و غیره، مخفف آموزنده است <span class=\"hlight\">:</span> <br />سزد گر ز خویشان افراسیاب <br />بدآموز دارد دو دیده پرآب .<br /> <font color=\"Red\">فردوسی .</font><br />نگار من که بمکتب نرفت و خط ننوشت <br />بغمزه مسئله آموز صد مدرس شد.<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> (ن مف مرخم ) در دست آموز و جز آن، مخفف آموزیده یعنی آموخته است <span class=\"hlight\">:</span><br />ای دل من زوبهر حدیث میازار<br />کاین بت فرهخته نیست هست نوآموز.<br /> <font color=\"Red\">دقیقی .</font><br />دیگری را در کمند آور که ما خود بنده ایم <br />ریسمان در پا نباشد مرغ دست آموز را.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِمص ) آموزش . عمل آموختن . تعلیم <span class=\"hlight\">:</span> <br />چو فارغ شد از پند و آموز مرد<br />ببستند پیمان و سوگند خورد.<br /><font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /></font></div>'),
(2340, 'آموزان', '<span class=\"hlight\">آموزان .</span> (نف، ق ) در حال آموزانیدن . در حال آموختن .<br /></font></div>'),
(2341, 'آموزاندن', '<span class=\"hlight\">آموزاندن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آموزانیدن . تعلیم . آموختن، چون متعدی باشد. رجوع به آموزیدن شود.<br /></font></div>'),
(2342, 'آموزانیدن', '<span class=\"hlight\">آموزانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آموزاندن . تعلیم . (دهار).<br /></font></div>'),
(2343, 'آموزش', '<span class=\"hlight\">آموزش .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِمص ) اسم مصدر از آموختن . عمل آموختن . تعلیم <span class=\"hlight\">:</span> هر کس که آموزش روزگار او را نرم و دانا نکند هیچ دانا را در آموزش او رنج نباید بردن که رنج او ضایع بود. (منسوب به انوشیروان، از قابوسنامه ).<br />بباید خرد شاه را ناگزیر<br />هم آموزش مرد برنا وپیر.<br /> <font color=\"Red\">فردوسی .</font><br />پدر باید اکنون که بیند ز من <br />هنرهای آموزش پیلتن .<br /> <font color=\"Red\">فردوسی .</font><br />جود و احسان تو بی آمیزش آموزش است <br />هیچ دانا بچه ٔ بط را نیاموزد شنا.<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(2344, 'آموزشگاه', '<span class=\"hlight\">آموزشگاه .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِ مرکب ) مدرسه .<br /></font></div>'),
(2345, 'آموزشی', '<span class=\"hlight\">آموزشی .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (ص نسبی ) طالب علم . دوستدار آموختن <span class=\"hlight\">:</span> <br />بدو گفت دانا شود مرد پیر<br />که آموزشی باشد و یادگیر.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2346, 'آموزنده', '<span class=\"hlight\">آموزنده .</span> <font color=\"DarkGreen\"><b>[ زَدَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه آموزد دیگری را. مُعلّم . پیر تعلیم . <BR><font color=\"Blue\">◄</font> آنکه از دیگری آموزد. مُتعلّم .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2347, 'آموزگار', '<span class=\"hlight\">آموزگار.</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ص مرکب ) آنکه آموزد. آنکه یاد دهد. معلم . آموزنده . استاد. مربی . <BR><font color=\"Blue\">◄</font> توسعاً، ناصح . اندرزگوی . هادی . راهنما. مجرب <span class=\"hlight\">:</span> <br />هرکه نامُخت از گذشت روزگار<br />نیز ناموزد ز هیچ آموزگار.<br /> <font color=\"Red\">رودکی .</font><br />هم او آفریننده ٔ روزگار<br />بنیکی هم او باشد آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />کسی کش خرد باشد آموزگار<br />نگه داردش گردش روزگار.<br /> <font color=\"Red\">فردوسی .</font><br />که نوشه بدی تا بود روزگار<br />همیشه خرد بادت آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />چنین است خود گردش روزگار<br />نگیرد همی پند آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />کنون گر شدی آگه از روزگار<br />روان و خرد بودت آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />چو اندازه گیری ز دارا و فور<br />خود آموزگارت نباید ز دور.<br /> <font color=\"Red\">فردوسی .</font><br />بزودی بفرهنگ جائی رسید<br />کزآموزگاران سر اندرکشید.<br /> <font color=\"Red\">فردوسی .</font><br />هر آنکس که گوید که دانا شدم <br />بهر دانشی بر توانا شدم <br />یکی نغز بازی کند روزگار<br />که بنشاندش پیش آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />چنان <font color=\"DarkGreen\"><b>[ چون منوچهر ]</font></b> نامور بی هنر چون بود<br />که آموزگارش فریدون بود؟<br /> <font color=\"Red\">فردوسی .</font><br />کسی کو بود سوده ٔ روزگار<br />نباید بهر کارش آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت فرزانه کای شهریار<br />نباید ترا پند آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />خداوند گردنده بهرام و هور<br />خداوند پیل و خداوند مور<br />کند چون بخواهد ز ناچیز چیز<br />که آموزگارش نباید به نیز.<br /> <font color=\"Red\">فردوسی .</font><br />روا باشد ار پند من بشنوی <br />که آموزگار بزرگان توئی .<br /> <font color=\"Red\">فردوسی .</font><br />هنر باید و گوهر نامدار<br />خرد یار و فرهنگش آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />جهاندار آموزگار تو باد<br />خرد روشن و بخت یار تو باد.<br /> <font color=\"Red\">فردوسی .</font><br />همیشه بزی شاد و به روزگار<br />همیشه خرد بادت آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />وزآن پس هم آموزگارش تو باش <br />دلارام و دستور و یارش تو باش .<br /> <font color=\"Red\">فردوسی .</font><br />سخنها نه از یادگار تو بود<br />که گفتار آموزگار تو بود.<br /> <font color=\"Red\">فردوسی .</font><br />اگر نَبْوَدی پند آموزگار<br />برآوردمی من ز جانت دمار.<br /> <font color=\"Red\">فردوسی .</font><br />پروردگاردینی آموزگار فضلی <br />هم پیشه ٔ وفائی هم شیره ٔ سخائی .<br /> <font color=\"Red\">فرخی .</font><br />خسرو عادل که هست آموزگارش جبرئیل <br />کرده رب العالمینش اختیار و بختیار<br />این نکردش اختیار الا بعدل و راستی <br />وآن نبودش جز بخیر و جز بعدل آموزگار.<br /> <font color=\"Red\">منوچهری .</font><br />مرا این روزگار آموزگاریست <br />کز این به نیستْمان آموزگاری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای مبتدی تو تجربه آموزگار گیر<br />زیرا که به ز تجربه آموزگار نیست .<br /> <font color=\"Red\">مسعودسعد.</font><br />دولت جان پرور است صحبت آموزگار<br />خلوت بی مدعی سفره ٔ بی انتظار.<br /> <font color=\"Red\">سعدی .</font><br />نگه دار <font color=\"DarkGreen\"><b>[ فرزند را ]</font></b> از آموزگار بدش <br />که بدبخت گمره کند چون خودش .<br /> <font color=\"Red\">سعدی .</font><br />هر آن طفل کو جور آموزگار<br />نبیند، جفا بیند از روزگار.<br /> <font color=\"Red\">سعدی .</font><br />چه خوش گفت با کودک آموزگار<br />که کاری نکردیم و شد روزگار.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> بدآموز.مُوَسوِس <span class=\"hlight\">:</span> <br />بگردان ز جانم بد روزگار<br />همان چاره ٔ دیو آموزگار...<br />بگردان ز من دیو را دستگاه <br />بدان تا ندارد روانم تباه .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> متعلم . شاگرد. .پذیرنده . پندپذیر. (برهان ).<br /> <BR><font color=\"Blue\">◄</font> در شواهد زیرین مانند لقبی است سلاطین بزرگ را و شاید آن دسته از شاهان را که سنت و شریعتی نیک نهاده یا بکار بردن چیزی سودمند را بمردم آموخته اند چنانکه آتش افروختن و بکار داشتن گاوآهن و مانند آن <span class=\"hlight\">:</span> <br />یکی نیک مرد اندر آن روزگار<br />ز تخم فریدون آموزگار...<br />کجا نام آن نامور هوم بود<br />پرستنده دور از بر و بوم بود.<br /> <font color=\"Red\">فردوسی .</font><br />بخواب اندر آمد سر روزگار<br />ز خوبی ّ و از داد آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />و در بیت زیرین چنین می نماید که آموزگاری چون فرّه ٔ ایزدی از غیب میرسیده است پادشاهان و شاید بزرگان دیگر را <span class=\"hlight\">:</span> <br />کنون گشت کیخسرو آموزگار<br />کز او دور بادا بد روزگار.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2348, 'آموزگاری', '<span class=\"hlight\">آموزگاری .</span> <font color=\"DarkGreen\"><b>[ زْ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (حامص مرکب ) چگونگی و عمل و صفت آموزگار. تعلیم .<br /></font></div>'),
(2349, 'آموزی', '<span class=\"hlight\">آموزی .</span> (ص، اِ) نام یکی از چهار طبقه ٔ مردم که جمشید نهاد. و آموزیان عباد یا رؤسای دین بودند. واین کلمه مصحّف آتوربان و آتوریان است <span class=\"hlight\">:</span> <br />گروهی که آموزیان خوانیَش <br />برسم پرستندگان دانیَش .<br /> <font color=\"Red\">فردوسی .</font><br /> <br /></font></div>'),
(2350, 'آموزیدن', '<span class=\"hlight\">آموزیدن .</span> <font color=\"DarkGreen\"><b>[ دَ]</font></b> (مص ) آموختن . تعلّم <span class=\"hlight\">:</span> و چنان واجب کندی که ایشان نبشتندی و من بیاموزیدمی . (تاریخ بیهقی ).<br /></font></div>'),
(2351, 'آموسنی', '<span class=\"hlight\">آموسنی .</span> (اِ) وَسنی . هَبو. هوو. ضَرّه . نباغ . نباج . یاری . زن ِ یک شوی نسبت به زن دیگر او.<br /></font></div>'),
(2352, 'آموص', '<span class=\"hlight\">آموص .</span> (اِخ ) (قوی ) نام پدر اشعیا، و یهود او را برادر امصیا پادشاه یهودا دانند.<br /></font></div>'),
(2353, 'آمولن', '<span class=\"hlight\">آمولن .</span> <font color=\"DarkGreen\"><b>[ ل ُ ]</font></b> (یونانی، اِ) نشاسته . نشا. لباب البر. لباب الحنطه . لباب الفوم . لباب القمح . آبگون .<br /></font></div>'),
(2354, 'آمون', '<span class=\"hlight\">آمون .</span> (اِ) مخفف پیرامون .<br /></font></div>'),
(2355, 'آمون', '<span class=\"hlight\">آمون .</span> (اِخ ) جیحون . آمل . آمو. آموی <span class=\"hlight\">:</span> <br />چو از رود آمون گذشت آن سپاه <br />برآمد هیاهو ز ماهی بماه .<br /> <font color=\"Red\">هاتفی .</font><br />آن رود که خوشتر است از آمون <br />بی شبهه که هست رود سیحون .<br /><font color=\"Red\">؟ (از فرهنگها).</font><br /></font></div>'),
(2356, 'آمون', '<span class=\"hlight\">آمون .</span> (اِخ ) نام خدای مصریان قدیم، و کلمه ٔ آمین عربی را (که امروز به معنی برآور، روا فرما، استجابت کن است ) حدس میزنند که همین آمون باشد. <BR><font color=\"Blue\">◄</font> نام چهاردهمین پادشاه یهودا، پسر مِنسه که در <span class=\"hlight\" dir=\"rtl\">٢٢</span> سالگی بسال <span class=\"hlight\" dir=\"rtl\">٦٤٢</span> ق . م . بسلطنت رسید. <BR><font color=\"Blue\">◄</font> نام یکی از شهرهای قدیم بمصر علیا.<br /></font></div>'),
(2357, 'آمون', '<span class=\"hlight\">آمون .</span> (ص ) پُر. لب ریز. لبالب . مملو. (برهان ).<br /></font></div>'),
(2358, 'آمونیاک', '<span class=\"hlight\">آمونیاک .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (فرانسوی، اِ) رجوع به آمُنیاک شود.<br /></font></div>'),
(2359, 'آموی', '<span class=\"hlight\">آموی .</span> (اِخ ) آمو. آمویه . آمون . آمل . نام دشتی فراخ و ریگی بماوراءالنهر به ساحل جیحون <span class=\"hlight\">:</span> <br />ریگ آموی و درشتی های او<br />زیرپایم پرنیان آید همی .<br /> <font color=\"Red\">رودکی .</font><br />عنانش گرفتند و برتافتند<br />سوی ریگ آموی بشتافتند.<br /> <font color=\"Red\">فردوسی .</font><br />فروتر که از دشت آموی و زم <br />همیدون به ختلان درآید بهم .<br /> <font color=\"Red\">فردوسی .</font><br />به بستند آذین بشهر و براه <br />درم ریختند از بر دخت شاه <br />به آموی و راه بیابان مَرْو<br />زمین بود یکسر چو پرّ تذرو.<br /> <font color=\"Red\">فردوسی .</font><br />که ما را ز جیحون بباید گذشت <br />زدن کوس شاهی بر آن پهن دشت <br />به آموی لشکرگهی ساختن <br />شب و روز ناسودن از تاختن .<br /> <font color=\"Red\">فردوسی .</font><br />بروز چهارم به آموی شد<br />ندیدی زنی کو جهانجوی شد؟<br /> <font color=\"Red\">فردوسی .</font><br />به آموی شد پهلوان پیشرو<br />ابا لشکر و جنگ سازان نو...<br />بشهر بخارا نهادند روی <br />چنان ساخته لشکر جنگجوی .<br /> <font color=\"Red\">فردوسی .</font><br />چشم من چو چشمه ٔ آموی شد از هجر اوی <br />تن بخون در، چون میان چشمه ٔ آموی موی .<br /> <font color=\"Red\">قطران .</font><br /> <BR><font color=\"Blue\">◄</font> آمو. جیحون . آمویه . آمون . آب آموی . آب . رود. النهر. ورز. آمودریا. آمل <span class=\"hlight\">:</span> <br />بیک روز و یک شب به آموی شد <font color=\"DarkGreen\"><b>[ از مرو ]</font></b><br />ز نخجیر و بازی جهانجوی شد<br />بیامد به آموی یک پاس شب <br />گذر کرد بر آب و ریگ فَرَب .<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاه شد کردیه رفت پیش <br />از آموی با نامداران خویش .<br /> <font color=\"Red\">فردوسی .</font><br />ز انبوه پیلان و شیران زم <br />گذرهای جیحون پر از باد و دم <br />ز کشتی همی آب شدناپدید<br />بپایان ز آموی لشکر کشید.<br /> <font color=\"Red\">فردوسی .</font><br />دمادم شما از پسم بگذرید<br />بجیحون و روز و شبان مشمرید<br />شب تیره با لشکرافراسیاب <br />گذر کرد از آمو و بگذاشت آب .<br /> <font color=\"Red\">فردوسی .</font><br />چه ارزد برِ آب آموی موی ؟<br /> <font color=\"Red\">عنصری .</font><br />در جهانی که آب چشم من است <br />آب آموی درنمی گنجد.<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> آمو. آمویه . آمون . آمل . نام شهری بدشت آموی بساحل جیحون . (صحاح الفرس ) <span class=\"hlight\">:</span> <br />وزآن پس بزرگان شدند انجمن <br />ز آموی تاشهر چاچ و ختن .<br /> <font color=\"Red\">فردوسی .</font><br />ز بلخ و ز شِکْنان و آموی و زم <br />سلیح و سپه خواست و گنج و درم .<br /> <font color=\"Red\">فردوسی .</font><br />بخارا و خوارزم و آموی و زم <br />بسی یاد داریم با درد و غم .<br /> <font color=\"Red\">فردوسی .</font><br />نشستم به آموی تا پاسخم <br />بیارد مگر اختر فرّخم .<br /> <font color=\"Red\">فردوسی .</font><br />به آموی لشکر کشیدی بجنگ <br />وز ایشان به پیش من آمد پشنگ .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2360, 'آمویه', '<span class=\"hlight\">آمویه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) رود جیحون .آمو. آموی . آمل . رود. آب . النهر. وَرز. آمودریا. آمون . <BR><font color=\"Blue\">◄</font> نام شهری بکنار جیحون <span class=\"hlight\">:</span> و خود روز دیگر بیرون رفت و از جیحون بگذشت و سپاه از هر جای به آمویه گرد کردند. (تاریخ بخارای نرشخی ).<br /></font></div>'),
(2361, 'آمپدکل', '<span class=\"hlight\">آمپدکل .</span> <font color=\"DarkGreen\"><b>[ پ ِ دُ ]</font></b> (اِخ ) رجوع به انباذقلس شود.<br /></font></div>'),
(2362, 'آمپر', '<span class=\"hlight\">آمپر.</span> <font color=\"DarkGreen\"><b>[ پ ِ ]</font></b> (فرانسوی، اِ) واحد شدت جریان الکتریک .<br /></font></div>'),
(2363, 'آمپرسنج', '<span class=\"hlight\">آمپرسنج .</span> <font color=\"DarkGreen\"><b>[ پ ِ س َ ]</font></b> (اِ مرکب ) آمپرمتر. (فرهنگستان ).<br /></font></div>'),
(2364, 'آمپرمتر', '<span class=\"hlight\">آمپرمتر.</span> <font color=\"DarkGreen\"><b>[ پ ِ م ِ ]</font></b> (فرانسوی، اِ مرکب ) گالوانمتر، که شدت جریان الکتریک را بحسب آمپر معلوم کند. آمپرسنج . (فرهنگستان ).<br /></font></div>'),
(2365, 'آمی', '<span class=\"hlight\">آمی .</span> (یونانی، اِ) آمیوس . زنیان . نانخواه . نانخه . نانوخیه . نَغن . نَغن خلان . نغن خوالان . جوانی . کمون ملوکی .<br /></font></div>'),
(2366, 'آمیختن', '<span class=\"hlight\">آمیختن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص ) درهم کردن . مزج . خلط. خُلط. (دهار). مخلوط کردن . تخلیط. سوط. مذق . تألیف . ممزوج کردن . تقشیب . شوب . آمودن . ترکیب . مرکب کردن . (زوزنی ). تهویش . تشریج . بَکْل . (تاج المصادر بیهقی ). مشج . اِشراب . حیس . مخلوط شدن . درهم شدن . ممزوج گشتن . مرکب شدن . شیاب . خَشب . اختلاط. امتزاج . تأشب <span class=\"hlight\">:</span> <br />چنین گفته بد کید هندی که بخت <br />نگردد ترا شاد و خرم نه تخت ...<br />مگر تخمه ٔ مهرک نوش زاد<br />بیامیزد آن دوده با این نژاد.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت داروچرا ریختی <br />چو با رنج آن را بیامیختی ؟<br /> <font color=\"Red\">فردوسی .</font><br />از او پاک تریاکها برگزید<br />بیامیخت دارو چنان چون سزید<br />چو شب تیره شد از نوشته بجست <br />بیامیخت داروی کاهش، درست .<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود <font color=\"DarkGreen\"><b>[ مَنیژه ]</font></b> تا داروی هوش بر<br />پرستنده آمیخت با نوش بر.<br /> <font color=\"Red\">فردوسی .</font><br />دو جنگی بدانسان برآویختند<br />که گفتی بهمْشان برآمیختند.<br /> <font color=\"Red\">فردوسی .</font><br />دو لشکر بجنگ اندر آویختند<br />همه یک بدیگر درآمیختند.<br /> <font color=\"Red\">فردوسی .</font><br />کشیدند شمشیر و گرز آن سران <br />برآمیخت با هم سپاه گران .<br /> <font color=\"Red\">فردوسی .</font><br />بدوگفت این چیست کانگیختی <br />که با شهد حنظل بیامیختی ؟<br /> <font color=\"Red\">فردوسی .</font><br />ددیگر که پرسیدی از چهر من <br />بیامیخت با جان تو مهر من .<br /> <font color=\"Red\">فردوسی .</font><br />آب و آتش بهم نیامیزد<br />بالوایه ز خاک بگریزد.<br /> <font color=\"Red\">عنصری .</font><br />سر و مغزش آمیخت با خون و خاک <br />شد آن جانور کوه جنگی، هلاک .<br /> <font color=\"Red\">اسدی .</font><br />دفع مضرت شراب ممزوج را، با آب بیامیزند و کشکاب خورند. (نوروزنامه ). قدحی بر فاب در دست وشکر در آن ریخته و بعرق برآمیخته . (گلستان ).<br />تلخکامی می برد از ما بدور آن دو لب (کذا)<br />ساقیان در باده ها گویا شکر آمیختند.<br /> <font color=\"Red\">کمال خجند.</font><br /> <BR><font color=\"Blue\">◄</font> معاشرت . خلطه . رفت وآمد. آمدشد. صحبت <span class=\"hlight\">:</span> فوری نام قومی است هم از خرخیز اندر مشرق از خرخیز... و با دیگر خرخیزیان نیامیزند و مردم خوارند و بی رحم . (حدودالعالم ).<br />چنان بد که او شب نخفتی بسی <br />بیامیختی شاد با هر کسی <br />بکار زنان تیز بودی سرش <br />همی نرم جائی بجستی برش .<br /> <font color=\"Red\">فردوسی .</font><br />تو باخوبرویان بیامیختی <br />ببازی ّ و از جنگ بگریختی .<br /> <font color=\"Red\">فردوسی .</font><br />بسلام کس نرفتی و کس را نزدیک خود نگذاشتی و با کسی نیامیختی . (تاریخ بیهقی ).<br />با مردم لک تا بتوانی تو میامیز<br />زیرا که جز از عار نیاید ز لک و لاک .<br /> <font color=\"Red\">عیوقی (از تحفه ٔ اوبهی ).</font><br />با مردم پاک اصل و دانا آمیز<br />وز نااهلان هزار فرسنگ گریز.<br /> <font color=\"Red\">خیام .</font><br /><font color=\"DarkGreen\"><b>[ فرمان کرد ]</font></b> پس ایشان را زن ندهد و نخواهد و نیامیزدو بدین کار در پادشاهی بانگ کردند. (مجمل التواریخ ).<br />با من از روی طبیعت گر نیامزد رواست <br />ازبرای آنکه من در آب و او درروغن است .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> خفت و خیز با زنان <span class=\"hlight\">:</span> <br />تبه گردد از جفت شیر ژیان <br />بزودی شود نرم چون پرنیان ...<br />بیک ماه و یک بار از آمیختن <br />گر افزون بود خون بود ریختن <br />همین مایه از بهر فرزند را<br />بباید جوان خردمند را.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> الفت . انس گرفتن . خو کردن . جفت گرفتن <span class=\"hlight\">:</span> <br />تا نیامیزد با زاغ سیه باز سپید<br />تا نیامیزد با باز خشین کبک دری .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> پیوستن <span class=\"hlight\">:</span> آنجا که فرات در دجله آمیزد شهری بزرگوار بنا کند. (مجمل التواریخ ).<br /> <BR><font color=\"Blue\">◄</font> رزیدن . کردن . زدن، چنانکه رنگ را <span class=\"hlight\">:</span> <br />چوک ز شاخ درخت خویشتن آویخته <br />ماغ سیه بر دو بال غالیه آمیخته .<br /> <font color=\"Red\">منوچهری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">رنگ آمیختن، رنگ و بوی آمیختن </span> ؛ مکر، حیله، تزویر بکار بردن . تدبیر <span class=\"hlight\">:</span> <br />بهانه نباید بخون ریختن <br />چه باید کنون رنگت آمیختن ؟<br /> <font color=\"Red\">فردوسی .</font><br />نبیند <font color=\"DarkGreen\"><b>[ خاک اندلس ]</font></b> نه لشکر فرستم به جنگ <br />نه آمیزم از هر دری نیز رنگ .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت کاین مرد بهرامشاه <br />بدین زور و این شاخ و این دستگاه <br />نبایدهمی رنجش از هیچ روی <br />ز هر گونه آمیختم رنگ و بوی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> آمیختن از هم ؛ متفرق، پراکنده، پریشان شدن . از هم جدا گشتن <span class=\"hlight\">:</span> <br />ز تاب و رنج همچون زُمْرُدین تاج <br />ز هم آمیخته گسترده برعاج . <br /> <font color=\"Red\">(ویس و رامین ).</font><br /><BR><font color=\"Blue\">◄</font> ملتبس کردن . تسویط. تخلیط. <BR><font color=\"Blue\">◄</font> لیزیدن . درهم کردن . کالیدن . شیبانیدن . آشوردن . اسم مصدر و مصدر دومش آمیز یا آمیزش است . آمیختم . آمیز.<br /></font></div>'),
(2367, 'آمیختنی', '<span class=\"hlight\">آمیختنی .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص لیاقت ) درخور آمیختن . ازدرِ آمیختن . که آمیختن آن ناگزیر بود.<br /></font></div>'),
(2368, 'آمیخته', '<span class=\"hlight\">آمیخته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) درهم کرده . مخلوط. ممزوج . مشوب . مختلط. ملبوک . آگسته . مدوف <span class=\"hlight\">:</span> <br />طلخی و شیرینیش آمیخته ست <br />کس نخورد نوش و شکر بآپیون .<br /> <font color=\"Red\">رودکی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیخته تر بودن باکسی یا چیزی </span> ؛ سازگارتر، مألوف تر، مأنوس تر بودن با آن <span class=\"hlight\">:</span> <br />ای رفیقان سخن راست بگویم شنوید<br />طبع من باری، با شوّال آمیخته تر.<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیخته شدن </span> ؛ درهم شدن . اختلاط. (زوزنی ). امتزاج . تمازج . التیاث . اِخلاص . تألف . تهویش . تأشّب . ارتباک . تهاوش . تهوش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیخته کردن </span> ؛ آمیختن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیخته ها</span> ؛ اضغاث .<br /></font></div>'),
(2369, 'آمیخته', '<span class=\"hlight\">آمیخته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (اِ) جامه ای که جولایان پوشند.<br /></font></div>'),
(2370, 'آمیختگی', '<span class=\"hlight\">آمیختگی .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص ) امتزاج . اختلاط. شوب . <BR><font color=\"Blue\">◄</font> الفت . معاشرت . خلطه و آمیزش <span class=\"hlight\">:</span> چون ... آمیختگی آمد... بازار مضرِّبان و مفسدان کاسد گردد. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیختگی دادن </span> ؛ تألیف .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیختگی کار</span> ؛ ارتباک .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیختگی گرفتن با چیزی </span> ؛ الفت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیختگی و آشفتگی کار</span> ؛ بوخ .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیختگیها</span> ؛ شوائب .<br /></font></div>'),
(2371, 'آمیز', '<span class=\"hlight\">آمیز.</span> (نف مرخم ) به معنی آمیزنده، در کلمات مرکّبه، چون در مردم آمیز، رنگ آمیز و جز آن <span class=\"hlight\">:</span> <br />امرد آنگه که خوبروی بود<br />تلخ گفتار و تندخوی بود<br />چون بریش آمد و بلعنت شد<br />مردم آمیز و صلح جوی بود.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> (ن مف مرخم )به معنی آمیخته، چون در آتش آمیز، حسرت آمیز، خشم آمیز، خصومت آمیز، دُردی آمیز، زهرآمیز، شکرآمیز، شهدآمیز، شهوت آمیز، طعن آمیز، عبیرآمیز، عنبرآمیز، غم آمیز، غمان آمیز، فرقت آمیز، کذب آمیز، کفرآمیز، مشک آمیز، مصلحت آمیز، نوش آمیز و جز آن <span class=\"hlight\">:</span> <br />مرا طبع نشگفت اگر تیز گشت <br />به پیری چنین آتش آمیز گشت .<br /> <font color=\"Red\">فردوسی .</font><br />دروغ مصلحت آمیز به از راست فتنه انگیز. (گلستان ).<br />مجوی عیش خوش از دور باژگون سپهر<br />که صاف این سرخم جمله دردی آمیز است .<br /> <font color=\"Red\">حافظ.</font><br />خیال خال تو با خود به خاک خواهم برد<br />که تا ز خال تو خاکم شود عبیرآمیز.<br /> <font color=\"Red\">حافظ.</font><br />میان جعفرآباد و مصلی <br />عبیرآمیز می آید شمالش .<br /> <font color=\"Red\">حافظ.</font><br />درنزهةالقلوب حمداﷲ مستوفی عبارت ذیل آمده است : جص، خاک رنگ آمیز است که بقوت آفتاب گچ شود - انتهی . و معنی آن بر نگارنده معلوم نشد. شاید نظایر دیگری پیدا شود و معنی روشن گردد.<br />و رجوع به آمیغ شود.<br /></font></div>'),
(2372, 'آمیز', '<span class=\"hlight\">آمیز.</span> (اِمص ) آمیغ. مباشرت . صحبت . آرمش با. نزدیکی با. وقاع . <BR><font color=\"Blue\">◄</font> معاشرت . <BR><font color=\"Blue\">◄</font> آمیزش . (برهان ). <BR><font color=\"Blue\">◄</font> مخلوط کردن دو چیز یا زیاده با یکدیگر. (برهان ).<br /></font></div>'),
(2373, 'آمیزان', '<span class=\"hlight\">آمیزان .</span> (نف، ق ) در حال آمیختن .<br /></font></div>'),
(2374, 'آمیزش', '<span class=\"hlight\">آمیزش .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِمص ) اسم مصدر و عمل آمیختن . مزاج . مزج . امتزاج . خلط. (دهار). اختلاط. ترکیب <span class=\"hlight\">:</span> <br />جود و احسان تو بی آمیزش آموزش است <br />هیچ دانا بچه ٔ بط را نیاموزد شناه .<br /> <font color=\"Red\">سنائی .</font><br />مر آمیزش گوهران را بگوی <br />سبب چه که چندین صور زو بخاست ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> خلطه . مخالطت . معاشرت . الفت . صحبت . نشست و برخاست <span class=\"hlight\">:</span> <br />هرآنکس که باداد و روشن دلید<br />از آمیزش یکدگر مگسلید.<br /> <font color=\"Red\">فردوسی .</font><br />به خو هر کسی در جهان دیگر است <br />ترا با وی آمیزش اندرخور است .<br /> <font color=\"Red\">فردوسی .</font><br />رنجور نفاق دوستانم <br />زآمیزش دوستان مرا بس .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> آمیغ. مباضعه . آرام گرفتن با. آرمیدن با. نزدیکی کردن با. وقاع .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیزش تن </span> ؛ گشنی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیزش داروها</span> ؛ اَخلاط. آمیزه های دارو. عقار. اجزاء.<br /></font></div>'),
(2375, 'آمیزنده', '<span class=\"hlight\">آمیزنده .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه آمیزد. <BR><font color=\"Blue\">◄</font> خلط. خالط. لابک . خوش معاشرت . خواهان معاشرت . آمیزگار <span class=\"hlight\">:</span> و مردمانیند <font color=\"DarkGreen\"><b>[ خلخیان ]</font></b> بمردم نزدیک و خوش خو و آمیزنده . (حدودالعالم ). ولوالح شهری است خرّم ... با آب روان و مردمان آمیزنده . (حدودالعالم ). و <font color=\"DarkGreen\"><b>[ چگلیان ]</font></b> مردمانی نیک طبعند و آمیزنده و مهربان . (حدودالعالم ). دینور، شهره ژور، شهرهائی اند انبوه و بسیارنعمت و مردمانی آمیزنده . (حدودالعالم ). و آمیزنده ترین مردمان اند <font color=\"DarkGreen\"><b>[ اهل خراسان ]</font></b> اندرین ناحیت <font color=\"DarkGreen\"><b>[ ناحیت سودان ]</font></b> . (حدودالعالم ). سغد، ناحیتی است ... با آبهای روان ... و مردمانی مهماندار و آمیزنده . (حدودالعالم ).<br /></font></div>'),
(2376, 'آمیزه', '<span class=\"hlight\">آمیزه .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آمیخته . مخلوط. ممزوج . کمیژه <span class=\"hlight\">:</span> <br />گرد کرده بسی سخن ریزه <br />نیک و بد خیره درهم آمیزه .<br /> <font color=\"Red\">سنائی .</font><br />الاخلاس ؛ آمیزه شدن موی یعنی سیاهی با سپیدی آمیختن . (مجمل اللغه ). <BR><font color=\"Blue\">◄</font> پیر و کهل . (برهان ). <BR><font color=\"Blue\">◄</font> (اِمص ) بضاع . وقاع . آمیغ. آمیغه . <BR><font color=\"Blue\">◄</font> (اِ) مزاج .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیزهای دارو</span> ؛ عَقّار (ج، عقاقیر). (مهذب الاسماء) (دهار).<br /></font></div>'),
(2377, 'آمیزه مو', '<span class=\"hlight\">آمیزه مو.</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ص مرکب ) آنکه بعض مویهای سیاه و بعض آن سپید دارد، و آن پس از جوانی باشد. دومو. دومویه . اشمط. شمطاء. با موی جوگندمی <span class=\"hlight\">:</span> <br />اگر شاه هر هفت کشور بود<br />چو آمیزه مو شد مکدر بود.<br /> <font color=\"Red\">دقیقی .</font><br />کمیژه موی . (تاج المصادر بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیزه موی شدن </span> ؛ کمیژه موی شدن . اخلاس . (تاج المصادر بیهقی ).<br /></font></div>'),
(2378, 'آمیزگار', '<span class=\"hlight\">آمیزگار.</span> (ص مرکب ) آمیزنده . خواهان معاشرت . بسیار معاشرت کننده با مردمان . خالط. خلط. لابک . مخالط <span class=\"hlight\">:</span> <br />وگر خنده رویست و آمیزگار<br />عفیفش ندانند وپرهیزگار.<br /> <font color=\"Red\">سعدی .</font><br />بگویند ازاین حرف گیران هزار<br />که سعدی نه اهل است و آمیزگار.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(2379, 'آمیزگاری', '<span class=\"hlight\">آمیزگاری .</span> (حامص مرکب ) حالت و چگونگی و صفت آمیزگار. <BR><font color=\"Blue\">◄</font> حسن معاشرت . خوش مَنِشی <span class=\"hlight\">:</span> <br />زن خوش منش خواه نه روی خوب <br />که آمیزگاری بپوشد عیوب .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(2380, 'آمیص', '<span class=\"hlight\">آمیص .</span> (معرب، اِ) رجوع به آمص شود.<br /></font></div>'),
(2381, 'آمیغ', '<span class=\"hlight\">آمیغ.</span> (ن مف مرخم ) در کلمات مرکبه چون زهرآمیغ و نوش آمیغ و مانند آن، آمیخته و ممزوج و آمیز باشد <span class=\"hlight\">:</span> <br />همه به تنبل و رنگ است بازگشتن او<br />شرنگ نوش آمیغ است و روی زراندود.<br /> <font color=\"Red\">رودکی .</font><br />ای از این جوربد، زمانه ٔ شوم <br />همه شادی ّ او غمان آمیغ.<br /> <font color=\"Red\">رودکی .</font><br />بود شادیش یک سر انده آمیغ.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />دم مشک از مغز پرمیغ شد (کذا)<br />دل میغ از او عنبرآمیغ شد.<br /> <font color=\"Red\">اسدی .</font><br />سخن آرایان در وصل سرایند سخن <br />فرقت آمیغ نگویند سرود اندر بزم .<br /> <font color=\"Red\">سوزنی .</font><br />بحری است کَفَش که ماهیش تیغ<br />بر ماهی بحر گوهرآمیغ.<br /> <font color=\"Red\">خاقانی .</font><br />سر نخواهی برد هیچ از تیغ تو<br />ای بگفته لاف کذب آمیغ تو.<br /> <font color=\"Red\">مولوی .</font><br />زین تابش آفتاب و تاریکی میغ<br />وین بیهده زندگانی مرگ آمیغ<br />با خویشتن آی تا نباشی باری <br />نه بوده بافسوس و نه رفته بدریغ.<br /> <font color=\"Red\">؟</font><br /><BR><font color=\"Blue\">◄</font> (اِ) حقیقت، مقابل مجاز. (برهان ). و رجوع به آمیز شود.<br /></font></div>'),
(2382, 'آمیغ', '<span class=\"hlight\">آمیغ.</span> (اِمص )آمیزش . خلطه . مخالطت . امتزاج . مزج . خلط. <BR><font color=\"Blue\">◄</font> بضاع . مباضعه . مباشرت . مجامعت . وقاع <span class=\"hlight\">:</span> <br />چو آمیغ برنا شد آراسته <br />دو خفته سه باشند برخاسته .<br /> <font color=\"Red\">عنصری .</font><br />بسی گرد آمیغ خوبان مگرد<br />که تن را کند سست و رخساره زرد.<br /> <font color=\"Red\">اسدی .</font><br />چو برداشت دلدار از آمیغ جفت <br />بباغ بهارش گل نوشکفت .<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(2383, 'آمیغدن', '<span class=\"hlight\">آمیغدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آمیختن <span class=\"hlight\">:</span> <br />میامیغ با راستی کج روی <br />کهن چیز باشد پدید از نوی .<br /><font color=\"Red\">فردوسی (از صاحب انجمن آرا).</font><br /></font></div>'),
(2384, 'آمیغه', '<span class=\"hlight\">آمیغه .</span> <font color=\"DarkGreen\"><b>[ غ َ <span class=\"hlight\" dir=\"rtl\">/</span> غ ِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آمیخته . <BR><font color=\"Blue\">◄</font> (اِمص ) بضاع . وِقاع . (برهان ).<br /></font></div>'),
(2385, 'آمیغی', '<span class=\"hlight\">آمیغی .</span> (ص نسبی ) مرکب، مقابل بسیط. <BR><font color=\"Blue\">◄</font> مزجی . <BR><font color=\"Blue\">◄</font> حقیقی، مقابل مجازی . (برهان ).<br /></font></div>'),
(2386, 'آمیغیدن', '<span class=\"hlight\">آمیغیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) رجوع به آمیغدن شود.<br /></font></div>'),
(2387, 'آمین', '<span class=\"hlight\">آمین .</span> <font color=\"DarkGreen\"><b>[ آم ْ می ]</font></b> (ع ص، اِ) ج ِ آم ّ. قصدکنندگان .<br /></font></div>'),
(2388, 'آمین', '<span class=\"hlight\">آمین .</span> <font color=\"DarkGreen\"><b>[ آم ْ می <span class=\"hlight\" dir=\"rtl\">/</span> آ می ]</font></b> (ع صوت ) (ازآمُن، نام خدای مصریان ) برآور! بپذیر! چنین باد! مستجاب کن ! استجابت، اجابت فرما! قبول کن دعای مرا! درگیر فرمای ! باجابت مقرون باد! تراج (؟) <span class=\"hlight\">:</span> <br />گر در نماز شعرش برخوانی <br />روح الامین کند ز پَسَت آمین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تهنیت کرد شاه را قدسی <br />کرد روح الامین، براو آمین .<br /> <font color=\"Red\">مسعودسعد.</font><br />سخن بلند کنم تا برآسمان گویند<br />دعای دولت او را فرشتگان آمین .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمین ثم آمین </span> ؛ چنین باد و چنین تر باد. همچنین باد، همچنین تر باد.<br /></font></div>'),
(2389, 'آمینی', '<span class=\"hlight\">آمینی .</span> (اِخ ) نام محلی کنار راه خاش به جالق میان گدار برنجانه و بالاقلعه در <span class=\"hlight\" dir=\"rtl\">٢٣٩٨٠٠</span> گزی خاش .<br /></font></div>'),
(2390, 'آمیوس', '<span class=\"hlight\">آمیوس .</span> (از یونانی، اِ) نانخواه . (بحرالجواهر). زنیان . رجوع به آمی شود.<br /></font></div>'),
(2391, 'آمیژ', '<span class=\"hlight\">آمیژ.</span> (اِمص ) آمیز. (برهان ).<br /></font></div>'),
(2392, 'آمیژه', '<span class=\"hlight\">آمیژه .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آمیزه . (برهان ). <BR><font color=\"Blue\">◄</font> شاعر و موزون . (برهان ). <BR><font color=\"Blue\">◄</font> مرکب، مقابل بسیط. (بهار عجم ). <BR><font color=\"Blue\">◄</font> (اِمص ) آمیغ. صحبت . آرمیدن با. آمیزش با جفت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آمیژه مو</span> ؛ دومو.<br /></font></div>'),
(2393, 'آن', '<span class=\"hlight\">آن .</span> (حرف اضافه ) بنا بگفته ٔ صاحب مجمل التواریخ این کلمه در قدیم معنی «از» میداده است : بر سر حد پارس شهری بنا کرد به آن ایمدگواد نام کرد و آن است که اکنون ارغان خوانند و معنی چنان است، که از ایمد بهتر است برسان جندیشاپور که گفتم . (مجمل التواریخ ). به آن اندیوشاپور جندیوشابور است از خوزستان . اندیو نام انطاکیه است بزبان پهلوی نه آن ایو <font color=\"DarkGreen\"><b>[ ظ <span class=\"hlight\">:</span> به آن اندیو ]</font></b> یعنی از انطاکیه بهتر است . (مجمل التواریخ ). ولی وجه اشتقاقهای صاحب مجمل التواریخ مانند حمزه ٔ اصفهانی بر اساسی نیست و محتاج بتأیید است .<br /></font></div>'),
(2394, 'آن', '<span class=\"hlight\">آن .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ضمیر ملکی ) مال ِ. متعلق به . ازملک . و گاهی ازآن ِ و زآن ِ گویند <span class=\"hlight\">:</span> اسبی بود آن ِ منذر اشقر. (ترجمه ٔ طبری بلعمی ). و همه ٔ گوسفندان دیگر ازآن ِ حی ّ، خشک بود. (ترجمه ٔ طبری بلعمی ). خاتون کث، دیمعان کث، دو شهرک است خرد و آبادان و بارگاه سغد و سمرقند است و آن ِ فرغانه و ایلاق است . (حدودالعالم ). گرگانج شهری است که اندر قدیم آن ِ ملک خوارزمشاه بودی و اکنون پادشائیش جداست . (حدودالعالم ).<br />مثال بنده وآن ِ تو نگارا<br />کلیچه ٔ آفتاب و برگ ورتاج .<br /> <font color=\"Red\">منجیک .</font><br />سپهر و زمین و زمان آن ِ اوست <br />روان و خرد زیر فرمان اوست .<br /> <font color=\"Red\">فردوسی .</font><br />مرا چیز و گنج و روان آن ِ تست <br />دراین مرز فرمان فرمان تست .<br /> <font color=\"Red\">فردوسی .</font><br />که دستور و گنجور و گنج آن ِ تست <br />بروم اندرون سود و رنج آن ِ تست .<br /> <font color=\"Red\">فردوسی .</font><br />از ایران و توران دو بهر آن ِ تست <br />همان گوهر و گنج وشهر آن ِ تست .<br /> <font color=\"Red\">فردوسی .</font><br />نگهدار تن باش و آن ِ خرد<br />چو خواهی که روزت ببد نگذرد.<br /> <font color=\"Red\">فردوسی .</font><br />نخست آفرینش خرد را شناس <br />نگهبان جان است و آن ِ سپاس .<br /> <font color=\"Red\">فردوسی .</font><br />مرا هرچه ملک و سپاه است و گنج <br />همه آن ِ تست و ترا زوست خنج .<br /> <font color=\"Red\">فردوسی .</font><br />نبد لشکرش زآن ِ ما صد یکی <br />نخست از دلیران او کودکی .<br /> <font color=\"Red\">فردوسی .</font><br />چو او را گرفتی من آن ِ توام <br />چو فرمائیم پاسبان توام .<br /> <font color=\"Red\">فردوسی .</font><br />بدو مام گفتی که تخت آن ِ تست <br />خردمندی و رای و بخت آن ِ تست .<br /> <font color=\"Red\">فردوسی .</font><br />نه آئین شاهان بود این نشان <br />نه آن ِ سواران و گردنکشان .<br /> <font color=\"Red\">فردوسی .</font><br />سپاه و دژ و گنجها آن ِ تست <br />برفتن بهانه نبایدْت جست .<br /> <font color=\"Red\">فردوسی .</font><br />تن مرد و سر همچو آن ِ گراز<br />به بیچارگی مرده بر تخت ناز.<br /> <font color=\"Red\">فردوسی </font><br />مال رئیسان همه بسائل و زائر<br />وآن ِ تو به کفشگر ز بهر مچاچنگ .<br /> <font color=\"Red\">ابوعاصم .</font><br />هندوی بد که ترا باشد و زآن ِ تو بود<br />بهتر از ترکی کآن ِ تو نباشد صدبار.<br /> <font color=\"Red\">فرخی .</font><br />بس بناگوش چو سیما که سیه شد چو شبه <br />آن ِ تو نیز شود صبر کن ای جان جهان .<br /> <font color=\"Red\">فرخی .</font><br />حدیث حاسد نشنید و زآن ِ من بشنید.<br /> <font color=\"Red\">فرخی .</font><br />گفت پندارم کاین دخترکان آن ِ منند.<br /><font color=\"Red\">منوچهری .</font><br />رازدار من توئی ای شمع و یار من توئی <br />غمگسار من توئی من آن ِ توتو آن ِ من .<br /> <font color=\"Red\">منوچهری .</font><br />اگر ایدون که بکشتن نمرند این پسران <br />آن ِ خورشید و قمرباشند این جانوران .<br /> <font color=\"Red\">منوچهری .</font><br />و قیطس جانوری است در دریای و دو دست دارد و دنبالش چون آن ِ مرغ . (التفهیم ).<br />مکن زو یاد اگرچه مهربانست <br />کجا چیز کسان زآن ِ کسانست .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />گفت سرهنگی ازآن ِ ملک هر شب یا هر دو شب بر دختر من فرود آید از بام . (تاریخ سیستان ). دیگر راه بسیستان آمد با نامه ٔ پسر فرات و آن ِ پدر. (تاریخ سیستان ). آن ِ <font color=\"DarkGreen\"><b>[ یعنی داوری ِ ]</font></b> همه ٔ جهان به نیم روز راست گشتی و مظلومان سیستان را جداگانه نیم روز بایستی . (تاریخ سیستان ). صوفی داشتند سپید ازآن ِ زکریا علیه السلام .(تاریخ سیستان ). و حرب بسیار مردم ازآن ِ او بکشت . (تاریخ سیستان ). فرمان داد که سرای محمدبن ابراهیم القوسی و آن ِ خواص او غارت کنند. (تاریخ سیستان ). و نامه ها آوردند ازآن ِ امیریوسف و حاجب بزرگ علی . (تاریخ بیهقی ). چون حاصلی بدین بزرگی ازآن ِ وی ... عرضه کردند گفت طاهر... را بخوانید. (تاریخ بیهقی ). غلامی ترک ازآن ِ پسرش <font color=\"DarkGreen\"><b>[ ابواحمد ]</font></b> برای امیر آورده بودند تا خریده آید. (تاریخ بیهقی ). تا آن مدّت که ایزد... تقدیر کرده باشد و ازآن ِ پیغمبران ... همچنین رفته است . (تاریخ بیهقی ). و خواهری که ازآن ِ ما به نام وی است فرستاده آید تا ما را داماد و خلیفه باشد. (تاریخ بیهقی ). و پسر گهرآگین شهره نوش بادی در سر کرده بود و قزوین که ازآن ِ پدرش بود فروگرفته . (تاریخ بیهقی ). ومعمائی رسیده بود ازآن ِ امیرک . (تاریخ بیهقی ). و استطلاع رأی کرده بودند تا بر مثالهائی که ازآن ِ ما باشد کار کنند. (تاریخ بیهقی ). دختری ازآن ِ قدرخان امیرمحمد عقد نکاح کردند. (تاریخ بیهقی ). من نسختی کردم چنانکه در دیگر نسختها... و ازآن ِ امیرالمؤمنین هم از این معانی بود. (تاریخ بیهقی ). طبع بشریت است و خصوصاً ازآن ِ ملوک که دشوار آید ایشان را دیدن کسی که مستحق جایگاه ایشان باشد. (تاریخ بیهقی ). اگر امیر در این جنگ با ما مساعدت کند... چون کارها بمراد گردد ولایتی سخت با نام به نام فرزندان ازآن ِ او کرده آید. (تاریخ بیهقی ). از دور مجمّزی پیدا شد... امیرمحمد او را بدید... و کسی ازآن ِ خویش نزد حاجب فرستاد. (تاریخ بیهقی ). معتمدی را ازآن ِ بنده ... فرمود <font color=\"DarkGreen\"><b>[ حصیری ]</font></b> تا بزدند. (تاریخ بیهقی ). اگر در آن وقت سکونت را کاری پیوستند اندر آن فرمانی ازآن ِ خداوند ماضی رضی اﷲعنه نگاه داشتند. (تاریخ بیهقی ). بسیار مرتبه داران ... را ازآن ِ خواجه نیز بحاجبی نامزد کردند. (تاریخ بیهقی ).<br />چو دستت بچیز تو نبود رسان <br />چه چیز تو باشد چه آن ِ کسان .<br /> <font color=\"Red\">اسدی .</font><br />ببخش و بخور هرچه داری مایست <br />که چون نَدْهی و بنْهی آن ِ تو نیست .<br /><font color=\"Red\">اسدی .</font><br />نگه دار اندر زیان آن ِ خویش <br />چنان کِت بگفته ست بسیارخوار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چون تو از دنیا گوئی ّ و من از دین خدای <br />نه تو آن ِ منی و نیز نه من آن ِ توَم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />هر طائفه ای بمن گمانی دارند<br />من زآن ِ خودم هر آنچه هستم هستم .<br /> <font color=\"Red\">خیام .</font><br />بروزگار پیشین در اسب شناختن و هنر و عیب ایشان دانستن هیچ گروه به از عجم ندانستندی از بهر آنکه ملک جهان ازآن ِ ایشان بود و هر کجا در عرب و عجم اسب نیکو بودی بدرگاه ایشان آوردندی . (نوروزنامه ).<br />چند گوئی سنائی آن ِ من است <br />با همه کس پلاس با من هم ؟<br /> <font color=\"Red\">سنائی .</font><br />ما آن ِ توایم و دل و جان آن ِ تو، ما را<br />خواهی سوی منبر بر و خواهی بسوی دار.<br /> <font color=\"Red\">سنائی .</font><br />و عقل مرد را به هشت خصلت بتوان شناخت ... پنجم مبالغت در کتمان راز خویش و ازآن ِ دیگران . (کلیله و دمنه ). الاستلحاق ؛ دعوی کردن که فرزند آن ِ من است . (زوزنی ).<br />از ستوران دیگر آید یاد<br />کم ِ خر باد و آن ِ کاه و شعیر.<br /> <font color=\"Red\">سوزنی .</font><br />تا روزگار ازآن ِ تو شد هرکه بخت را<br />گفت آن ِ کیستی تو، بگفت آن ِ روزگار.<br /> <font color=\"Red\">انوری .</font><br />کرده ٔ قصّار و پس عقوبت حدّاد<br />این مثل است آن ِ اولیای صفاهان .<br /> <font color=\"Red\">خاقانی .</font><br />چند غلام ازآن ِ او دست برآوردند. (ترجمه ٔ تاریخ یمینی ).<br />گر بدم گر نیک هم زآن ِ توام .<br /> <font color=\"Red\">عطار.</font><br />روز عدل و عدل و داد اندرخور است <br />کفش زآن ِپا، کُلَه آن ِ سر است .<br /> <font color=\"Red\">مولوی .</font><br />جان ما آن ِ تو است ای شیرخو<br />پیش ما چندی امانت باش گو.<br /> <font color=\"Red\">مولوی .</font><br />و در بعض امثله ٔ فوق چنان می نماید که این کلمه تکرارکلمه ٔ پیش است : این مثل است آن ِ اولیای صفاهان ؛ این مثل است مَثَل ِ. کم ِ خر باد و آن ِ کاه و شعیر؛ کم خر باد و کم کاه و شعیر. چه چیز تو باشد چه آن ِ کسان ؛چه چیز تو باشد چه چیز کسان . اگر ایدون که بکشتن نمرند این پسران - آن ِ خورشید و قمر باشند این جانوران ؛ این پسران پسران خورشید و قمر باشند و غیره و غیره .<br /></font></div>'),
(2395, 'آن', '<span class=\"hlight\">آن .</span> (ع اِ) وقت . هنگام . لحظه ای که در آنی . دَم . وقت حاضر، متوسط میان ماضی ومستقبل . اندک زمان . ج، آنات : در یک آن . آن به آن .<br /></font></div>'),
(2396, 'آن', '<span class=\"hlight\">آن .</span> (ع پسوند) َان . علامت تثنیه در حال رفع: اَبَوان . توأمان . شِعْرَیان . فرقدان . مَلَوان <span class=\"hlight\">:</span> <br />شده شِعْرَیانش چو دو چشم مجنون <br />شده فرقدانش چو دوخد لیلی .<br /> <font color=\"Red\">منوچهری .</font><br />چو پاسی از شب دیرنده بگذشت <br />برآمد شِعْرَیان از کوه موصل .<br /> <font color=\"Red\">منوچهری .</font><br />ای نیاموخته ادب زَ ابوان <br />ادب آموز زین پس از ملوان .<br /> <font color=\"Red\">سنائی .</font><br />دروغ راست نمای است در ولایت شاه <br />ز عدل او بره با گرگ توامان گفتن .<br /> <font color=\"Red\">سوزنی .</font><br />زآنروی که روزی از فراقت <br />با سال تمام توأمانست .<br /><font color=\"Red\">انوری .</font><br /></font></div>'),
(2397, 'آن', '<span class=\"hlight\">آن .</span> (ع پسوند)َان . در عربی چون پیش از یاء نسبت درآید شدت و مبالغه ٔ انتساب راست . و گفته اند برای تعظیم و تأکید است : باقلانی . بحری، بحرانی (شدیدالحمرة). برّی، برّانی .تحتانی . جسدانی . جسمی، جسمانی . حقانی . دَیرانی (خداوند دیر). ربّی، ربّانی . رقبانی (ستبرگردن ). روحی، روحانی . شَعْرانی (پُرموی ). شهوانی . صمدانی . طولانی . ظلمانی . عبرانی . عصبی، عصبانی . عضلی، عضلانی . عقلانی . فوقانی . لحمانی . لحیانی (بلندریش ). نفسانی . نورانی . هندوانی . هیولانی . و در بعض امثله ٔ فوق ظاهراً افاده ٔ مطلق نسبت کند، از قبیل عبرانی، دیرانی <span class=\"hlight\">:</span> <br />دودندان میان دو لب همچو نائی <br />که ناگه از او درکشی هندوانی .<br /> <font color=\"Red\">منوچهری .</font><br />غریب از جاه نورانی ز نافرمانی لشکر<br />بدست دشمنان درمانده اندر چاه ظلمانی .<br /> <font color=\"Red\">سنائی .</font><br />ز بدروئی ّ و خودرائی همه یکبارگی رفته <br />ز گلشنهای روحانی بگلخنهای جسمانی .<br /> <font color=\"Red\">سنائی .</font><br />که گر تأیید عقل کل نبودی نفس کلی را<br />نگشتی قابل نفس دوم نقش هیولانی .<br /> <font color=\"Red\">سنائی .</font><br />در دماغ و جگر بدوزیده <br />روح طبعی ّ و روح نفسانی .<br /> <font color=\"Red\">سنائی .</font><br />هر آنکو گشت پرورده بزیر دامن خذلان <br />گریبان گیر او ناید دمی توفیق ربانی .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(2398, 'آن', '<span class=\"hlight\">آن .</span> <font color=\"DarkGreen\"><b>[ نِن ْ ]</font></b> (ع ص ) اعلال شده ٔ آنی . سخت گرم . <BR><font color=\"Blue\">◄</font> نزدیک . <BR><font color=\"Blue\">◄</font> بردبار.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2399, 'آن', '<span class=\"hlight\">آن .</span> (ضمیر، ص ) اسم اشاره بدور، چنانکه «این » اسم اشاره به نزدیک است . ج، آنان، آنها. و گویند آنان مخصوص بذوی الروح و آنها در غیرذوی الروح و هم در ذوی الروح مستعمل است <span class=\"hlight\">:</span> <br />نزد آن شاه زمین کردش پیام <br />داروئی فرمای زامهران بنام .<br /> <font color=\"Red\">رودکی .</font><br />آمد آن نوبهار توبه شکن <br />پرنیان گشت باغ و برزن و کوی .<br /> <font color=\"Red\">رودکی .</font><br />چو گشت آن پریچهره بیمار غنج <br />ببرّید دل زین سرای سپنج .<br /> <font color=\"Red\">رودکی .</font><br />ز مرغ و آهو رانم بجویبار و بدشت <br />از آن جفاله جفاله از این قطارقطار.<br /> <font color=\"Red\">عنصری .</font><br />سوی آسمان کردش آن مرد روی <br />بگفت ای خدا این تن من بشوی <br />از این اَزْغها پاک کن مر مرا<br />همه آفرین زآفرینش ترا.<br /> <font color=\"Red\">بوشکور.</font><br />زن پیر رفت و می آورد و جام <br />از آن جام فرهاد شد شادکام .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت افراسیاب آن زمان <br />که آن نامور گرد خسرونشان .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد نشست از بر تختگاه <br />بسر برنهاد آن کیانی کلاه .<br /> <font color=\"Red\">فردوسی .</font><br />فرستاد آیین گشسب آن زمان <br />کسی را برِ شاه گیتی دمان .<br /> <font color=\"Red\">فردوسی .</font><br />کجا گیو و طوس و کجا پیلتن <br />فرامرز و دستان و آن انجمن .<br /> <font color=\"Red\">فردوسی .</font><br />از آن پیشتر کآن گو پیلتن <br />درآید بخرگاهیان رزم زن .<br /> <font color=\"Red\">فردوسی .</font><br />خیال خنجر او را شبی مه دید ناگاهان <br />به هر ماهی شود آن شب مه از دیدار ناپیدا.<br /> <font color=\"Red\">مسعودسعد.</font><br />سالاری محتشم فرستاده آید بر آن جانب . (تاریخ بیهقی ). حاجب بکتکین و آن قوم بازگشتند. (تاریخ بیهقی ). من که عبدالرحمن فضولیم آن دو تن را... دریافتم و پرسیدم که امیر آن سجده چرا کرد. (تاریخ بیهقی ). بوعلی کوتوال بگفته که از برادر ما آن شغل می برنیاید. (تاریخ بیهقی ). تو که بونصری ... ممکن نخواهی بودن در شغل خویش که آن نظام که بود بگسست . (تاریخ بیهقی ). اندیشیدیم که مگر آنجای دیرتر بماند و در آن دیار باشد که خلل افتد. (تاریخ بیهقی ). رعایا و اعیان آن نواحی در هوای ما <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> مطیع وی گشته . (تاریخ بیهقی ). استادم در خرد و فضل آن بود که بود... و آن طائفه از حسد وی هر کس نسختی کرد و شرم دارم که بگویم بر چه جمله بود. (تاریخ بیهقی ). دانست که آن دیار تا روم ... بضبط ما آراسته گردد. (تاریخ بیهقی ). از چپ راه قلعه ٔ مندیش ... پیداآمد و راه بتافتند و بر آن جانب رفتند. (تاریخ بیهقی ). سالاری محتشم فرستاده آید بر آن جانب تا آن دیار را... ضبط کند. (تاریخ بیهقی ). مقرر است که این تکلفها از آن جهت بکردند <font color=\"DarkGreen\"><b>[ پدران ]</font></b> تا فرزندان ... بر آن تخمها که ایشان کاشتند بردارند. (تاریخ بیهقی ). نامه ها رفت جملگی این حالها را به ری و سپاهان و آن نواحی نیز تا درست مقرر گردد. (تاریخ بیهقی ). اهل جمله ٔ آن ولایات گردن برافراشته تا نام ما بر آن نشیند. (تاریخ بیهقی ). ملوک روزگار... چون ... بروند فرزندان ایشان که مستحق آن تخت باشند بر جایهای ایشان نشینند. (تاریخ بیهقی ). سلطان مسعود گفت ... ما... حرکت خواهیم کرد بر جانب بلخ تا... احوال آن جانب را مطالعه کنیم . (تاریخ بیهقی ). سلطان مسعود را آن حال مقرر گشت .(تاریخ بیهقی ).<br />بدنامی حیات دو روزی نبود بیش <br />وآن هم کلیم با تو بگویم چسان گذشت <br />یک روز صرف بستن دل شد به آن و این <br />روز دگر بکندن دل زین و آن گذشت .<br /> <font color=\"Red\">کلیم .</font><br />برون آمد از خیمه و آن دو زلف <br />نبشته پریشیده بر نسترن .<br /> <font color=\"Red\">؟(از تحفةالاحباب اوبهی ).</font><br />و در بعض امثله ٔ فوق، کلمه ٔ آن بجای الف و لام عهد ذهنی و ذکری عرب آمده است . <BR><font color=\"Blue\">◄</font> پس از کلمه ٔ آن، مشارالیه گاه حذف می شود، از قبیل کس در این امثله <span class=\"hlight\">:</span> <br />با دل پاک مرا جامه ٔ ناپاک رواست <br />بد مر آن را که تن و جامه پلید است و نژند.<br /> <font color=\"Red\">کسائی .</font><br />بهی زآن فزاید که تو بِه ْ کنی <br />مِه ْ آن شد بگیتی که تو مِه ْ کنی .<br /> <font color=\"Red\">فردوسی .</font><br />هر آن را که خواهد برآرد بلند<br />هم او را سپارد به خاک نژند.<br /> <font color=\"Red\">فردوسی .</font><br />آن که برهم زن جمعیت ما شد یارب <br />تو پریشانتر از آن زلف پریشانش کن .<br /> <font color=\"Red\">؟</font><br />من آنم که من دانم .<br /> <BR><font color=\"Blue\">◄</font> سبب و جهت و علت و مانند آن، در شواهد زیرین <span class=\"hlight\">:</span> رسولی با وی نامزد کردند بدین جهت که ولیعهد پدر وی است و ری از آن بما دادند تا... هر کسی بر آنچه داریم اقتصار کنیم . (تاریخ بیهقی ). از آن گریستم که ما بندگان چنین خداوند را خدمت می کنیم با چندین حلم و کرم ... (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> عمل و کار و نظایر آن، در این مثالها <span class=\"hlight\">:</span> <br />که من با زن جادوان آن کنم <br />که پشت و دل جادوان بشکنم .<br /> <font color=\"Red\">فردوسی .</font><br />مرا آن بود تخت و گنج و کلاه <br />که خشنود باشد جهاندار شاه .<br /> <font color=\"Red\">فردوسی .</font><br />زآنکه با جان شما آن می کند<br />کآن بهاران با درختان می کند.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> عقیده و رای و عزم و قصد، چون : من بر آنم که ؛ یعنی چنین اعتقاد دارم . چنان قصد کرده ام <span class=\"hlight\">:</span> <br />اگر تو سرو سیمین تن بر آنی <br />که از پیشم برانی من بر آنم ...<br /> <font color=\"Red\">سعدی (کلیات چ فروغی ص <span class=\"hlight\" dir=\"rtl\">٦٣٢</span>).</font><br />کس نیست که پنهان نظری با تو ندارد<br />من نیز بر آنم که همه خلق بر آنند.<br /> <font color=\"Red\">سعدی .</font><br />بر سر آنم که گر ز دست برآید<br />دست بکاری زنم که غصه سر آید.<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> بجای آن چیز و آن امرو آن کار، مانند <span class=\"hlight\">:</span> <br />کاشک آن گویدکه باشد بیش نه <br />بر یکی بر، چند نفزاید فره .<br /> <font color=\"Red\">رودکی .</font><br />امروز چون تخت بما رسید... خرد آن مثال دهد که ... بناهای افراشته را افراشته تر کرده آید. (تاریخ بیهقی ). هر کس آن کند که نبایدکردن آن بیند که نباید دیدن . (قابوسنامه ).<br />آن خور و آن پوش چو شیر و پلنگ <br />کآوری آن را همه ساله بچنگ .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> مخفف آن زمان، چون <span class=\"hlight\">:</span> <br />آن شد ای خواجه که در صومعه بازم بینی <br />کار ما با رخ ساقی ّ و لب جام افتاد.<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> ضمیر که مرجع آن ممکن است از ذوی العقول یا غیرذوی العقول باشد <span class=\"hlight\">:</span> <br />بخندید ازآن شهریار جهان <br />بدو گفت کاین نیست از ما نهان .<br /> <font color=\"Red\">فردوسی .</font><br />دلیران و گردان مازندران <br />بخیره فروماندند اندر آن .<br /> <font color=\"Red\">فردوسی .</font><br />از آن محتشم تر در آن روزگار از اهل قلم کسی نبود. (تاریخ بیهقی ). زلت آن <font color=\"DarkGreen\"><b>[ اسکندر ]</font></b> با دارا آن بود که بنشابور در جنگ خویشتن را بر شبه رسولی بلشکرگاه دارا برد. (تاریخ بیهقی ). چند نکت دیگر بود سخت دانستنی که آن <font color=\"DarkGreen\"><b>[ نُکَت ]</font></b> بروزگار کودکی <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> چون یال برکشید و پدر وی را ولیعهد کرد واقع شده بود. (تاریخ بیهقی ). امیر ماضی چند رنج برد... تا قدرخان خانی یافت ... امروز آن را تربیت باید کرد تا دوستی زیادت گردد. (تاریخ بیهقی ). آن ملوک که ایشان را قهر کرد <font color=\"DarkGreen\"><b>[ اسکندر ]</font></b> و آن را گردن نهادند... راست بدان مانست که درآن باب سوگند داشته است . (تاریخ بیهقی ). بلکاتکین گفت خواجه ٔ بزرگ ... حشمت آن ما بندگان را نگاه باید داشت . (تاریخ بیهقی ). اگر آنچه مثال دادیم ... آن را امضا نباشد... آنچه گرفته آمده است مهمل ماند و روی بکار ملک نهیم که اصل آن است و این دیگر فرع . (تاریخ بیهقی ). امیرالمؤمنین اعزازها ارزانی داشتی ... تا... بمدینةالسلام رویم و غضاضتی که جاه خلافت را می باشد از گروهی اذناب آن را دریابیم . (تاریخ بیهقی ). منتظریم جواب این نامه را... تا بتازه گشتن اخبار سلامتی خان ... لباس شادی پوشیم و آن را از بزرگتر مواهب شمریم . (تاریخ بیهقی ). بهرچه ببایست که باشد پادشاهان بزرگ را از آن زیادت تر بود. (تاریخ بیهقی ). توفیق صلح خواهیم از ایزد... در این باب که توفیق آن دهد بندگان را. (تاریخ بیهقی ). پیغامها دادیم رسول را که اندرآن اصلاح ذات البین بود. (تاریخ بیهقی ). برادر ما... را... بامیری سلام کردند و اندر آن تسکین وقت دانستند. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> گاه بمعنی یاء تنکیرفارسی و تنوین تنکیر عرب باشد <span class=\"hlight\">:</span> <br />نکو گفت مزدور با آن خدیش <br />مکن بدبکس گر نخواهی بخویش .<br /> <font color=\"Red\">رودکی .</font><br />چه گفت آن هنرمند مرد خرد<br />که دانا ز گفتار او بر خورد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> آن، پیش از فعل شنیدم و شنیدی و شنیدستی و شنیدستم و مانند آن در ابتداء حکایت ظاهراً زاید و فقط برای حفظ وزن می آید و نیز ممکن است بدان معنی ِ چنین و چنان داد <span class=\"hlight\">:</span> <br />آن شنیدی که صوفئی میکوفت <br />زیر نعلین خویش میخی چند؟<br /> <font color=\"Red\">سعدی .</font><br />آن شنیدم که در بلاد شمال <br />بود مردی بخیل و صاحب مال .<br /> <font color=\"Red\">سعدی .</font><br />آن شنیدی که لاغری دانا<br />گفت روزی بابلهی فربه ...<br /> <font color=\"Red\">سعدی .</font><br />آن شنیدستی که در صحرای غور<br />بارسالاری بیفتاد از ستور؟<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> ایشان . آنان <span class=\"hlight\">:</span> <br />بگرد جهان چار سالار من <br />که هستند بر جان نگهدار من <br />ابا هر یکی زآن ده و دو هزار<br />از ایرانیانند جنگی سوار.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> در بیت ذیل و نظایر آن یا از کلمه ٔ «آن » و یا از سوق کلام معنی تفخیم و تعظیم مفهوم می شود <span class=\"hlight\">:</span> <br />آمد آن نوبهار توبه شکن <br />پرنیان گشت باغ و برزن و کوی .<br /> <font color=\"Red\">رودکی .</font><br />آن مال و نعمتش همه گردید ترت و مرت <br />آن خیل و آن حشم همه گشتند تار و مار.<br /> <font color=\"Red\">خجسته .</font><br />دریغ آن کمربند و آن گردگاه <br />دریغ آن کشی برز و بالای شاه .<br /> <font color=\"Red\">فردوسی .</font><br />کجا گیو و طوس و کجا پیلتن <br />فرامرز و دستان و آن انجمن ؟<br /> <font color=\"Red\">فردوسی .</font><br />آنی که پادشاه جهان خسرو ملوک <br />در روی تو نگه نکند جز به احترام .<br /> <font color=\"Red\">سوزنی .</font><br />برون آمد از خیمه و آن دو زلف <br />نبشته پریشیده بر نسترن .<br /> <font color=\"Red\">؟(از تحفه ٔ اوبهی ).</font><br /> <BR><font color=\"Blue\">◄</font> (پسوند) آن (َان ) در آخر کلمه به معنی یای مصدری است : چادردَران کردن ؛ یعنی چادردری کردن . و راه جامه دران نیز از این قبیل است . <BR><font color=\"Blue\">◄</font> و گاه افاده ٔ کثرت و استمرار کند <span class=\"hlight\">:</span> <br />در باغ بنوروز درم ریزان است <br />بر نارونان لحن دل انگیزان است .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> و گاه علامت جمع منطقی باشد در فارسی از ذوی الشّعور و جز آن <span class=\"hlight\">:</span> <br />خرد افسر شهریاران بود<br />خرد زیور نامداران بود.<br /> <font color=\"Red\">فردوسی .</font><br />نگر تا نداری ببازی جهان <br />نه برگردی از نیک پی همرهان .<br /> <font color=\"Red\">فردوسی .</font><br />بپرسیدشان از نژاد کیان <br />وزآن نامداران و فرخ گَوان .<br /> <font color=\"Red\">فردوسی .</font><br />همه نیکیت باید آغاز کرد<br />چو با نیکنامان بُوی در نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />که خورشید بعد از رسولان مه <br />نتابید بر کس ز بوبکر به .<br /> <font color=\"Red\">فردوسی .</font><br />شما شش هزارید و من یک دلیر<br />سر سرکشان اندرآرم بزیر<br />چو من گرزه ٔ سرگرای آورم <br />سرانْتان همه زیر پای آورم .<br /> <font color=\"Red\">فردوسی .</font><br />بر زال رفتند با سوگ و درد<br />رخان پر ز خون و سران پر ز گرد.<br /> <font color=\"Red\">فردوسی .</font><br />چو بنمود خورشید بر چرخ دست <br />شب تیره بار غریبان ببست .<br /> <font color=\"Red\">فردوسی .</font><br />بسی آفرین بزرگان بگفت <br />بدان کش برون آورید از نهفت .<br /> <font color=\"Red\">فردوسی .</font><br />گلستانْش برکندو سروان بسوخت <br />بیکبارگی چشم شادی بدوخت .<br /> <font color=\"Red\">فردوسی .</font><br />سکندر ز گفتار او گشت زرد<br />روان پر ز دردو رخان لاجورد.<br /> <font color=\"Red\">فردوسی .</font><br />بسی نفت و روغن برآمیختند<br />همه بر سر گوهران ریختند.<br /> <font color=\"Red\">فردوسی .</font><br />نوان و برهنه تن و پای و سر<br />تنان بی بر و جان بدانش به بر.<br /> <font color=\"Red\">فردوسی .</font><br />گیا رست با چند گونه درخت <br />بزیر اندر آمد سرانْشان ز بخت .<br /> <font color=\"Red\">فردوسی .</font><br />بزرگان و بازارگانان شهر<br />هم از داد باید که یابند بهر.<br /> <font color=\"Red\">فردوسی .</font><br />که بود آنکه دیهیم بر سر نهاد<br />ندارد کس از روزگاران بیاد.<br /><font color=\"Red\">فردوسی .</font><br />همی گفت وز نرگسان سیاه <br />ستاره همی ریخت بر گرد ماه .<br /> <font color=\"Red\">فردوسی .</font><br />چنانکه زالان نشابور گفته اند. (تاریخ بیهقی ). و قوم را بجمله آنجا رسانیدند <font color=\"DarkGreen\"><b>[ بقلعه ]</font></b> و چند خدمتکار... از مردان . (تاریخ بیهقی ). و مکی بود از ندیمان این پادشاه <font color=\"DarkGreen\"><b>[ امیرمحمد ]</font></b> و شعر و ترانه خوش گفتی . (تاریخ بیهقی ). و دیگر خدمتکاران او را <font color=\"DarkGreen\"><b>[ احمد ارسلان را ]</font></b> گفتند... که هر کس پس ِ شغل خویش رود. (تاریخ بیهقی ). ودشمنان ایشان را ممکن نگردد که ... قصدی کنند. (تاریخ بیهقی )... خان داند که بزرگان ... که با یکدیگر دوستی بسر برند... وفاق و ملاطفات را پیوسته گردانند. (تاریخ بیهقی ). توفیق صلح خواهیم از ایزد... که توفیق آن دهد بندگان را. (تاریخ بیهقی ). ملوک روزگار چون ... بروند... فرزندان ایشان ...بر جایهای ایشان نشینند.(تاریخ بیهقی ). مقرّر است که این تکلفها از آن جهت بکردند <font color=\"DarkGreen\"><b>[ پدران ]</font></b> تا فرزندان از آن الفت شاد باشند. (تاریخ بیهقی ). و طریقی که پدران ما بر آن رفته اند نگاه داشته آید. (تاریخ بیهقی ). جهد کرده آید تا بناهای افراشته در دوستی را افراشته تر کرده آید تا از هردو جانب دوستان شادمانه شوند. (تاریخ بیهقی ). بهرچه ببایست که باشد پادشاهان بزرگ را، از آن زیادت تر بود <font color=\"DarkGreen\"><b>[ محمود ]</font></b>. (تاریخ بیهقی ). و خدای را عز و جل چرا فروخت بسوگندان گران که بخورد و در دل خیانت داشت ؟ (تاریخ بیهقی ). اگر این سوگندان را دروغ کنم ... از خدای ... بیزارم . (تاریخ بیهقی ).<br /> <BR><font color=\"Blue\">◄</font> در امثله ٔ ذیل، آن برای تأکید شمار آمده است و یا زاید است <span class=\"hlight\">:</span> <br />گوری کنیم و باده کشیم و بُویم شاد<br />بوسه دهیم بر دو لبان پری نژاد.<br /> <font color=\"Red\">رودکی .</font><br />بهر نیک و بد هر دوان یک منش <br />براز اندرون هر دوان بدکنش .<br /> <font color=\"Red\">ابوشکور.</font><br />پس از هر دوان بود عثمان گزین <br />خداوند شرم و خداوند دین .<br /> <font color=\"Red\">فردوسی .</font><br />شبگیر نه بینی که خجسته به چه درد است <br />کرده دو رخان زردو برو پرچین کرده ست .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> بعضی گویند آن علامت جمع است در حیوان و نبات و اعضای جفت حیوان، بنابراین : اختران، اَنْدُهان، سخنان، سوگندان، غمان، گوهران مخالف قیاس است . همچنین در روزگاران و روزان و شبان و سران و آفتابان و ماهان . <BR><font color=\"Blue\">◄</font> در اشعار ذیل ممکن است کلمات غمان، اندهان، شبان جمع باشند یا فقط آن برای زینت ملحق شده باشد <span class=\"hlight\">:</span> <br />جهان را چنین است آئین و سان <br />یکی روز شادی ّ و دیگر غمان .<br /> <font color=\"Red\">فردوسی .</font><br />آن برگ رزان است که برشاخ رزان است <br />گوئی بمثل پیرهن رنگ رزان است .<br /> <font color=\"Red\">منوچهری .</font><br />خون دلم مخور که غمان تو می خورم <br />رحمی بکن که زخم سنان تو می خورم .<br /> <font color=\"Red\">خاقانی .</font><br />جان کاهی و اندهان فزائی <br />سیبی بدو کرده روزگاری .<br /> <font color=\"Red\">خاقانی .</font><br />متقلب درون جامه ٔ ناز<br />چه خبر دارد از شبان دراز؟<br /> <font color=\"Red\">سعدی .</font><br />سعدی بروزگاران مهری نشسته بر دل <br />بیرون نمی توان کرد الا بروزگاران .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> هرگاه در آخر کلمه «َا» یا «َو» باشد مانند: دانا. بینا. خدا. بینوا. سخن سرا. سخنگو. دانشجو و جز آن، «َان » علامت جمع را به «یان » تبدیل کنند مانند: خدای، خدایان . سخن سرای، سخن سرایان . سخنگوی، سخنگویان . آزمای، آزمایان . ولی قدما غالباً این تبدیل را روا نمی داشتند <span class=\"hlight\">:</span> شاه دگرباره با داناآن بدیدار آن درخت شد. (نوروزنامه ). و غیره و غیره . <BR><font color=\"Blue\">◄</font> چون کلمه مختوم به ها باشد مانند:رونده . آینده . آسوده، ها را در جمع بدل بگاف فارسی کنند و گویند: روندگان . آیندگان . آسودگان، برای آنکه در این الفاظ «هَ » در زبان پهلوی «ک » بوده و کلمه روندک و آسودک و مانند آن تلفظ می شده است . <BR><font color=\"Blue\">◄</font> در کلمه ٔ نیاکان علامت جمع همان آن است و نیاک صورتی دیگر از نیا باشد <span class=\"hlight\">:</span> <br />ایا شاهی که ملک تو قدیم است <br />نیاکت برده پاک از اژدها کا.<br /> <font color=\"Red\">دقیقی .</font><br />کجا آن بزرگان با تاج و تخت <br />کجا آن نیاکان پیروزبخت ؟<br /> <font color=\"Red\">فردوسی .</font><br />نیاکانتان پهلوانان بدند<br />ز تخم بزرگان و شاهان بدند (کذا).<br /> <font color=\"Red\">فردوسی .</font><br />و نیاکان سیده همه پادشاهان طبرستان و دیلمیان بودند. (مجمل التواریخ ).<br /> <BR><font color=\"Blue\">◄</font> آن، گاه در آخر مفرد امر حاضر درآید و دلالت بر وصف فاعلی یا حال کند، مانند خرامان یعنی خرامنده و درخشان، درخشنده و روان، رونده و آرایان، آراینده <span class=\"hlight\">:</span> <br />فرود آمد از تخت ویله کنان <br />زنان برسر و دست و بازوکنان .<br /> <font color=\"Red\">فردوسی .</font><br />دهقان بتحیر سر انگشت گزان است <br />کاندر چمن و باغ نه گل ماند و نه گلنار.<br /> <font color=\"Red\">منوچهری .</font><br />باد سحری سپیده دم خیزان است <br />با میغ سیه بچنگ آویزان است <br />وآن میغ سیه ز چشم خونریزان است <br />تا باد مگر ز میغ بردارد چنگ .<br /> <font color=\"Red\">منوچهری .</font><br />دلها ز نوای مرغ جوشان بینی <br />شبگیر کلنگ را خروشان بینی .<br /> <font color=\"Red\">منوچهری </font><br />سال امسالین نوروز طربناکانست <br />پار و پیرار همی دیدم اندوهگنا.<br /> <font color=\"Red\">منوچهری .</font><br />گر شاخ نوان بود ز بی برگی و بی برگ <br />از برگ نوا داد قضا شاخ نوان را.<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />بکان حکمت مانند نور خورشیدیم <br />ببحر دانش مانند ابر گریانیم .<br /> <font color=\"Red\">مسعودسعد.</font><br />تبارک اللَّه از آن پیکری که نسبت کرد<br />تنش بکوه متین و تکش بباد وزان .<br /> <font color=\"Red\">مسعودسعد.</font><br />نوعروسی چو سرو نوبالان <br />گشت روزی ز چشم بد نالان .<br /> <font color=\"Red\">سنائی .</font><br />روزی که زرد گل دمد از چهره ٔ دلیر<br />نیلوفری حسام شود ارغوان فشان .<br /> <font color=\"Red\">اثیر اخسیکتی .</font><br />حذر کن زآه مظلومی که بیدار است و خون باران .<br /> <font color=\"Red\">خاقانی .</font><br />بی باده ٔ زرفشان نباشیم <br />چون باد شده ست عنبرافشان .<br /><font color=\"Red\">خاقانی .</font><br />تا سلسله ٔ ایوان بگسست مداین را<br />در سلسله شد دجله چون سلسله شد پیچان .<br /> <font color=\"Red\">خاقانی .</font><br />گوئی که نگون کرده ست ایوان فلک وش را<br />حکم فلک گردان یا حکم فلک گردان .<br /> <font color=\"Red\">خاقانی .</font><br />دچند باشی باین و آن نگران <br />پند گیر از گذشتن دگران .<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> و گاه، آن علامت نسبت بنوّت باشد چنانکه کسره در فارسی و ابن و بنت در عربی : ارتخشتران، پسر ارتخشتر. ارشکان، پسر ارشک . پاپکان، پسر پاپک .پرثوان، پسر پرثو. خسرو کبادان، پسر کباد. دارای دارایان، دارای پس دارا. عبیداﷲ زیادان، پسر زیاد. کواتان، پسر کوات (قباد). مهرسپندان، پسر مهرسپند <span class=\"hlight\">:</span> <br />سپهدارشان قارن کاوکان <br />به پیش سپه اندرون آوکان .<br /> <font color=\"Red\">فردوسی .</font><br />جای دیگر در نسبت قارن گوید:<br />ز آهنگران کاوه ٔ پرهنر<br />به پیشش یکی رزم دیده پسر<br />کجا نام او قارن رزم زن ...<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> در. بَ : چاشتگاهان . دیرگاهان . سحرگاهان . شامگاهان . صبحگاهان . گرمگاهان . و صاحب المعجم گوید آن در آخر اوقات و ازمنه حرف تخصیص است و گویند سحرگاهان و شبانگاهان و بامدادان، یعنی بسحرگاه و بشبانگاه و به بامداد، و چون بسحرگاهان و ببامدادان و بشبانگاهان گویند باء زیادت است و به آن احتیاج نباشد. (از المعجم نقل به معنی و اختصار) <span class=\"hlight\">:</span> <br />دهقان به سحرگاهان کز خانه بیاید<br />نه هیچ بیارامد و نه هیچ بپاید<br />نزدیک رز آید در رز را بگشاید<br />تا دختر رز را چه بکار است و چه شاید.<br /> <font color=\"Red\">منوچهری .</font><br />سحرگاهان که مخمور شبانه <br />گرفتم باده با چنگ و چغانه .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> گاه ِ. هنگام ِ. وقت ِ. زمان ِ. موسم ِ: بامدادان . بهاران . سپیده دمان . نوبهاران . نیم روزان . مانند آنه (َانه ) <span class=\"hlight\">:</span> <br />ببود آن شب و بامدادان پگاه <br />به آرام بر تخت بنشست شاه .<br /> <font color=\"Red\">فردوسی .</font><br />بمژده ز رستم هم اندرزمان <br />هیونی بیامد سپیده دمان <br />که ما در بیابان خبر یافتیم <br />بدان آگهی تیز بشتافتیم .<br /> <font color=\"Red\">فردوسی .</font><br />زواره بیامد سپیده دمان <br />سپه راند رستم هم اندرزمان .<br /> <font color=\"Red\">فردوسی .</font><br />بهاران بدی اوبه ارونددشت <br />بر این گونه چندی بر او برگذشت .<br /> <font color=\"Red\">فردوسی .</font><br />چو ابر بهاران به بارندگی <br />همی مرگ جوید بدان زندگی .<br /> <font color=\"Red\">فردوسی .</font><br />پشّه کی داند که این باغ از کی است <br />در بهاران زاد و مرگش در دی است .<br /> <font color=\"Red\">مولوی .</font><br />بگذار تا بگریم چون ابر در بهاران <br />کز سنگ ناله خیزد روز وداع یاران .<br /> <font color=\"Red\">سعدی .</font><br />بامدادان که تفاوت نکند لیل و نهار.<br /> <font color=\"Red\">سعدی .</font><br />درخت اندر بهاران برفشاند<br />زمستان لاجرم بی برگ ماند.<br /> <font color=\"Red\">سعدی .</font><br />بگذارتا بگریم چون ابر در بهاران <br />کز سنگ ناله خیزد روز وداع یاران .<br /> <font color=\"Red\">سعدی .</font><br />تغویر؛ در نیم روزان رفتن . (منتهی الارب ).<br />صبحدمان مست برآمد ز کوی <br />زلف پژولیده و ناشسته روی .<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> علامت احتفالی به آئین یا جشن و سوری و یا اجرای رسم و آئین و عادتی پس از صورت مفرد امر حاضر و عقیب بعض اسماء معنی از قبیل مرگ، سور و طلب : آش برگ پزان ؛ دعوتی که زنان از زنان کنند پختن و خوردن آش برگ را. آشتی کنان ؛ محفلی از دوستان و خویشان برای آشتی دادن دو تن، و نیز عمل آشتی در این محفل . آینه بندان ؛پوشیدن دیوارها و خوازه ها و گنبدها به آئینه، گاه ورود شاهی یا بزرگی . احوال پرسان ؛ رفتن بدیدار کسی یا بیماری برعایت ادب . اسم گذاران ؛ جشن و سوری برای نام گذاری نوزاد. بله بُران (از بلی و بران )؛ محفل قول گرفتن از کسان عروس ازدواجی را. پشت پاپزان ؛ دعوتی برای خوردن آش پشت پای مسافری و عمل پختن آن . چله بران ؛ جشنی برای آب چله زدن نوزاد را. حمام روان ؛ دعوت و سور حمام رفتن عروس یا داماد یا زچه ای . خاج شویان ؛ عیدی سالیانه مسیحیان را. حنابندان ؛ احتفالی بستن حنا دست و پای عروس را. ختنه سوران و ختنه کنان ؛ سوری خِتان ِ کودکی را. خلعت پوشان ؛ جشنی پوشیدن خلعت شاهی، امیر یاحاکمی را. دست بوسان ؛ رسم رفتن داماد بدیدار پدرزن یا مادرزن . رخت بُران ؛ احتفالی بریدن جامه های عروس را.سمنوپزان ؛ احتفال پختن سمنو و اجرای مراسم و خواندن اوراد زنانه ٔ آن . سهراب کشان ؛ روز یا شبی که درویش شاهنامه خوان قصه ٔ کشتن سهراب را خواند. شیرینی خوران ؛ سور نامزدی عروس . شیشه بندان ؛ سور شب ششم نوزاد و اجرای رسوم خرافی آن . عروس بینان ؛ مهمانی خواستاری عروس در خانه ٔ او. عقابین کنان ؛ شبی که این جزء از کارهای رستم را درویش در قهوه خانه حکایت کند. عقدکنان ؛ سور کابین بستن عروس . فطیرخوران ؛ عیدی مذهبی یهود و نصاری را. کلوخ اندازان ؛ مهمانی و شرابخواری در سلخ شعبان . گلریزان ؛ جشن گل افشاندن بر پهلوانی و جز آن . مَرگان ؛ تعزیه . مجلس ختم . میوه بندان ؛ جشن آویختن میوه و ذخیره ٔ آن برای زمستان . گوسفندکشان (عید...)؛ اضحی . مردگیران ؛ جشنی مغان را در پنج روز آخر اسفند. و طلبان کردن عبارتی است زنانه که چون شوی آنان را خواند گویند آقا طلبان کرده است و از آن بمزاح این خواهند که این رسمی نوین است بی سابقه . ظاهراً الف و نون چراغان نیز از این قبیل باشد. <BR><font color=\"Blue\">◄</font> آن در عقیب بعض صفات چون شاد و آباد و مست و ناگاه و جاوید اگردر قدیم افاده ٔ مفهومی زیاده میکرده است در زمان ما زاید یا حرفی برای زینت بنظر می آید، چه شادان و شاد و آبادان و آباد و مستان و مست و ناگاه و ناگاهان و جاوید و جاویدان به یک معنی است <span class=\"hlight\">:</span> <br />بمی دست بردند و مستان شدند<br />ز یاد سپهبد بدستان شدند.<br /> <font color=\"Red\">فردوسی .</font><br />برفتند کارآگهان ناگهان <br />نهفته بجستند کار جهان .<br /> <font color=\"Red\">فردوسی .</font><br />که اندر شبستان شاه جهان <br />نباشد شگفت ار شوی ناگهان .<br /> <font color=\"Red\">فردوسی .</font><br />سوی رز رفتن باید بصبوح <br />خویشتن کردن مستان و خراب .<br /> <font color=\"Red\">منوچهری .</font><br />بگشادش در با کبر شهنشاهان <br />گفت بسم اﷲ اندرشد ناگاهان .<br /> <font color=\"Red\">منوچهری .</font><br />گر آمد ناگهان از من خطائی <br />مرا منمای داغ هر جفائی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />همایون باد و فرخنده بر او این عز و جاه او<br />همیشه عز و جاه اوچو نامش باد جاویدان .<br /> <font color=\"Red\">مسعودسعد.</font><br />خیال خنجر او را شبی مه دید ناگاهان <br />به هر ماهی شود آن شب مه از دیدار ناپیدا.<br /> <font color=\"Red\">مسعودسعد.</font><br />گفتی که کجا رفتند آن تاجوران یکسر<br />زایشان شکم خاک است آبستن جاویدان .<br /> <font color=\"Red\">خاقانی .</font><br />چون نکردی خرابی آبادان <br />بخرابی چه میشوی شادان ؟<br /> <font color=\"Red\">اوحدی .</font><br />و آن در بهاران و مرغزاران و سپیده دمان و گوزنان و شبانگاه بیت های ذیل نیز از این قبیل است <span class=\"hlight\">:</span> <br />چنین تا برآمدسپیده دمان <br />بزرگان چین را سرآمد زمان .<br /> <font color=\"Red\">فردوسی .</font><br />چو سوفارش آمد به پهنای گوش <br />ز چرم گوزنان برآمد خروش .<br /> <font color=\"Red\">فردوسی .</font><br />جهانجوی هندوی تنها برفت <br />بدان مرغزاران شتابید تفت .<br /><font color=\"Red\">فردوسی .</font><br />بمژده شبانگه سوی او شوید<br />بگوئید و گفتار او بشنوید.<br /> <font color=\"Red\">فردوسی .</font><br />بهاران آمد و آورد باد و ابر نیسانی <br />چو طبع و خلق تو هر دو جهان شد خرم و بویا.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> جای . موطن . کشور: گرگان ؛ جای گرگ . توران ؛ جای تور. اَترپاتگان ؛ جای ارپاتک . خزران ؛ جای خزر. آلانان ؛ جای آلان . دیلمان ؛ جای دیلم . گیلان ؛ جای مردم گیل . <BR><font color=\"Blue\">◄</font> زمان . فصل . موسم : توت پزان . انگورپزان . <BR><font color=\"Blue\">◄</font> و گاه برای تعدیه ٔ فعل لازم آید یا تکرار تعدیه، چنانکه در خندیدن، خندانیدن . کردن، کنانیدن . شنودن، شنوانیدن . خوردن، خورانیدن . گریستن، گریانیدن و امثال آن . <BR><font color=\"Blue\">◄</font> (اِ) چگونگی و کیفیت خاص در حسن و زیبائی و جز آن که عبارت از آن نتوان کرد و تنها بذوق توان دریافت . همان که شاعر گوید <span class=\"hlight\">:</span> <br />لطیفه ای است نهانی که حسن از آن خیزد<br />که نام آن نه لب لعل و خط زنگاریست .<br /> <font color=\"Red\">حافظ.</font><br />آنچه گویند صوفیانش آن <br />توئی آن آن، علیک عین اﷲ.<br /> <font color=\"Red\">سنائی .</font><br />آن گویم و آن چو صوفیانت <br />نی نی که تو پادشاه آنی .<br /> <font color=\"Red\">سنائی .</font><br /> <br />ای آنکه جمالت از گهرها<br />آن دارد آن که کان ندارد<br />از یوسف خوشتری که در حسن <br />آن داری و یوسف آن ندارد.<br /> <font color=\"Red\">سنائی .</font><br />آنچه آن را صوفیان گویند آن <br />ازجمال خواهرم جویند آن .<br /> <font color=\"Red\">عطار.</font><br />آنچه او را صوفی آن گوید بنام <br />ختم شد آن بر محمد والسلام .<br /> <font color=\"Red\">عطار.</font><br />از بتان آن طلب ار حسن شناسی ای دل <br />کاین کسی گفت که در علم نظر بینا بود.<br /> <font color=\"Red\">حافظ.</font><br />زاغ گردد چون پی زاغان رود<br />جسم گردد جان، چو او بی آن رود.<br /> <font color=\"Red\">مولوی .</font><br />در شگرفان حرکاتیست که آنش خوانند<br />در تو آن هست و دوصد فتنه به آن پیوسته .<br /> <font color=\"Red\">اوحدی .</font><br />قمر گفتم چو رویت دلفروز است <br />ولیکن چون بدیدم آن ندارد.<br /> <font color=\"Red\">خواجو.</font><br />شاهد آن نیست که موئی ّ و میانی دارد<br />بنده ٔ طلعت آن باش که آنی دارد.<br /> <font color=\"Red\">حافظ.</font><br />اینکه می گویند آن بهتر ز حسن <br />یار ما این دارد و آن نیز هم .<br /> <font color=\"Red\">حافظ.</font><br />گل ارچه شاهد رعناست لیکن <br />به پیش روی خوبت آن ندارد.<br /> <font color=\"Red\">همام .</font><br /><BR><font color=\"Blue\">◄</font> عقل . (برهان ). <BR><font color=\"Blue\">◄</font> شراب . (برهان ).<br /></font></div>'),
(2400, 'آن تیس تن', '<span class=\"hlight\">آن تیس تن .</span> <font color=\"DarkGreen\"><b>[ تی ت ِ ]</font></b> (اِخ ) نام فیلسوف یونانی متولد درآطینه (آتن )، تلمیذ سقراط و مؤسس و بانی طریقه ٔ کلبیون . و این طریقه خیر اعلی را در ترک و اهمال غنا ومقام و لذات میشمرد. دیوجانس معروف کلبی از شاگردان این حکیم است . سقراط روزی باو گفت : «آن تیس تِن، من کبر و نخوت را از خلال دریدگیهای جامه ٔ تو میخوانم ».<br /></font></div>'),
(2401, 'آن جهان', '<span class=\"hlight\">آن جهان .</span> <font color=\"DarkGreen\"><b>[ج َ ]</font></b> (اِ مرکب ) آخرت . عقبی . اخری . آجله . آجل . آخره .عاقبت . آن سرا. مقابل این جهان، دنیا، اولی، عاجله .<br /></font></div>'),
(2402, 'آن دگر', '<span class=\"hlight\">آن دگر.</span> <font color=\"DarkGreen\"><b>[ دِ گ َ ]</font></b> (ضمیر مبهم مرکب ) دیگری . والاَّخر <span class=\"hlight\">:</span> <br />هر دو یک گوهرند لیک بطبع<br />این بیفسرد وآن دگر بگداخت .<br /><font color=\"Red\">رودکی .</font><br /></font></div>'),
(2403, 'آن دیگر', '<span class=\"hlight\">آن دیگر.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (ضمیر مبهم مرکب ) آن دگر. آن یک <span class=\"hlight\">:</span> که وقتی در بیابان مانده بودم او مرا بر شتری نشاند و از دست آن دیگر تازیانه خورده ام . (گلستان ).<br /></font></div>'),
(2404, 'آن را', '<span class=\"hlight\">آن را.</span> (ضمیر + حرف اضافه ) کسی را. آن کس را <span class=\"hlight\">:</span> <br />این مدّعیان در طلبش بی خبرانند<br />آن را که خبر شد خبری بازنیامد.<br /> <font color=\"Red\">سعدی .</font><br />آن را که جای نیست همه شهر جای اوست <br />درویش هر کجاکه شب آید سرای اوست .<br /> <font color=\"Red\">سعدی .</font><br />آن را که هست هست هم اینجاش داده اند<br />آن را که نیست وعده بفرداش داده اند.<br /> <font color=\"Red\">عبید زاکانی (لطائف ).</font><br />آن را چه زنی که روزگارش زده است .<br /> <BR><font color=\"Blue\">◄</font> چیز معهود یا مشهود را <span class=\"hlight\">:</span> <br />گفت آن را من نخواهم، گفت چون <br />گفت او واپس رو است و بس حرون .<br /> <font color=\"Red\">مولوی .</font><br />گفت آن را جمله می گفتند خوش <br />مر مرا هم ذوق آمد گفتنش .<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> برای آن . بسبب آن . بدان روی <span class=\"hlight\">:</span> گفتم <font color=\"DarkGreen\"><b>[ عبدالرّحمن ]</font></b> الحق روز این صوت هست امّا آن را ایستاده ام تا این نکته ٔ دیگر بشنوم و بروم . (تاریخ بیهقی ). ملوک روزگار... عقود و عهود که کرده باشند بجای آرند... اینهمه آن را کنند تا که چون ... بروند فرزندان ایشان ... بر جایهای ایشان نشینند. (تاریخ بیهقی ).<br /></font></div>'),
(2405, 'آن روزینه', '<span class=\"hlight\">آن روزینه .</span> <font color=\"DarkGreen\"><b>[ زی ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ق مرکب ) آن زمان <span class=\"hlight\">:</span> و آن روزینه شهر <font color=\"DarkGreen\"><b>[ بخارا ]</font></b> همانقدر بود که شهرستان است . (تاریخ بخارای نرشخی ).<br /></font></div>'),
(2406, 'آن زمان', '<span class=\"hlight\">آن زمان .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (ق مرکب ) آنگاه . در آن وقت <span class=\"hlight\">:</span> <br />بگستهم گفت آن زمان شهریار<br />که تنگ اندرآمد مرا روزگار.<br /> <font color=\"Red\">فردوسی .</font><br />به بستند بندی بر آئین خویش <br />بدانسان که بود آن زمان دین و کیش .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> بَعد. پس . سپس .<br /></font></div>'),
(2407, 'آن سرا', '<span class=\"hlight\">آن سرا.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) آن سرای . آخرت . سرای دیگر. عُقبا. مقابل این سرای، دنیا <span class=\"hlight\">:</span> <br />پناه روانست دین از نهاد<br />کلید بهشت و ترازوی داد<br />درِ رستگاری ورا از خدای <br />ره توبه و توشه ٔ آن سرای .<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(2408, 'آن سری', '<span class=\"hlight\">آن سری .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (ص نسبی ) عقبائی . اُخرَوی . آخرتی . <BR><font color=\"Blue\">◄</font> خدائی . الهی . غیبی . مقابل این سری <span class=\"hlight\">:</span> <br />باشم گستاخ وار با تو که لاشی کند<br />صد گنه این سری یک نظر آن سری .<br /> <font color=\"Red\">سنائی .</font><br />سری دارم چو حافظ مست لیکن <br />بلطف آن سری امّیدوارم .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(2409, 'آن سو', '<span class=\"hlight\">آن سو.</span> (اِ مرکب، ق مرکب ) آن سوی . آن طرف . مقابل این سوی .<br /></font></div>'),
(2410, 'آن سوی رودی', '<span class=\"hlight\">آن سوی رودی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) گروهی از مردم گیلان که میان سپیدرود و کوه نشینند. و آنان را یازده ناحیت است : خانکجال، ننک، کوتم، سراوان، پیلمان شهر، رشت، تولیم، دولاب، کهن رود، استراب، خان بلی . (حدودالعالم ).<br /></font></div>'),
(2411, 'آن کجا', '<span class=\"hlight\">آن کجا.</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (ضمیر + حرف ربط) آنچه <span class=\"hlight\">:</span> <br />بنزد سیاوش خرامید زود<br />بر او برشمرد آن کجا رفته بود.<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به کجا شود.<br /> <BR><font color=\"Blue\">◄</font> آن کس که <span class=\"hlight\">:</span><br />آن کجا تیزت <font color=\"DarkGreen\"><b>[ ظ: سَرْت ]</font></b> برکشید بچرخ <br />باز ناگه فروبَرَدْت به خَرْد.<br /><font color=\"Red\">خسروانی (از اسدی چ پاول هورن ).</font><br /></font></div>'),
(2412, 'آن کس', '<span class=\"hlight\">آن کس .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (صفت + ضمیر مبهم ) آن آدمی . آن شخص، به معنی «مَن » عرب <span class=\"hlight\">:</span> <br />چنین گفت آن کس که پیروز گشت <br />سر بخت او گیتی افروز گشت ...<br /> <font color=\"Red\">فردوسی .</font><br />که اسفندیار از بنه خود مباد<br />نه آن کس بگیتی کز اوهست شاد.<br /> <font color=\"Red\">فردوسی .</font><br />و شریف آن کس تواند بود که خسروان روزگار وی را مشرّف گردانند. (کلیله و دمنه ).<br /></font></div>'),
(2413, 'آن کسی', '<span class=\"hlight\">آن کسی .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (صفت + ضمیر مبهم ) آن آدمی <span class=\"hlight\">:</span> <br />بشیر آن کسی را که بودی نیاز<br />بدان خواسته دست بردی فراز.<br /> <font color=\"Red\">فردوسی .</font><br />ترا آفرین از فریدون گرد<br />بزرگ آن کسی کو نداردْش خرد.<br /> <font color=\"Red\">فردوسی .</font><br />بزرگ آن کسی کو بگفتار راست <br />زبان را بیاراست و کژّی نخواست .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2414, 'آنات', '<span class=\"hlight\">آنات .</span> (ع اِ) ج ِ آن .<br /></font></div>'),
(2415, 'آنار', '<span class=\"hlight\">آنار.</span> (اِ) رجوع به انار شود.<br /></font></div>'),
(2416, 'آناطولی', '<span class=\"hlight\">آناطولی .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) (از یونانی آناطل، برآمدن آفتاب ) آسیای صغیر. آسیةالصغری .<br /></font></div>'),
(2417, 'آناف', '<span class=\"hlight\">آناف .</span> (ع اِ) ج ِ انف، مثل اُنوف و آنُف .<br /></font></div>'),
(2418, 'آنالوطیقا', '<span class=\"hlight\">آنالوطیقا.</span> (معرب، اِ) (از یونانی آنا، از نو + لوئین، گشادن، حل کردن ) اَنالوطیقا. تحقیق تحلیلی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آنالوطیقای اوّل </span> ؛ مبحث قیاس . تحلیل قیاس از کتاب ارسطو.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آنالوطیقای ثانی </span> ؛ مبحث برهان از کتاب ارسطو.<br /></font></div>'),
(2419, 'آنام', '<span class=\"hlight\">آنام .</span> (ع اِ) اَنام . خلق . جن و انس .<br /></font></div>'),
(2420, 'آنام', '<span class=\"hlight\">آنام .</span> (اِخ ) نام مملکتی بمشرق شبه جزیره ٔ هندوچین بوسعت <span class=\"hlight\" dir=\"rtl\">١٤٧</span> هزار کیلومتر مربع و <span class=\"hlight\" dir=\"rtl\">٥٦٠٠٠٠٠</span> تن مردم . کرسی آن هوء و از شهرهای مهم ّ آن توران و محصول آن ابریشم و برنج باشد.<br /></font></div>'),
(2421, 'آنان', '<span class=\"hlight\">آنان .</span> (ضمیر) ج ِ آن . آن کسان . ایشان . اوشان . آنها <span class=\"hlight\">:</span> <br />همه تفاخر آنان بجود و دانش بود<br />همه تفاخر اینان بغاشیه ست و جناغ .<br /> <font color=\"Red\">منجیک .</font><br />آنانکه محیط فضل و آداب شدند<br />در جمع کمال شمع اصحاب شدند<br />ره زین شب تاریک نبردند برون <br />گفتند فسانه ای ّ و درخواب شدند.<br /> <font color=\"Red\">خیام .</font><br />نظر آنان که نکردند بدین مشتی خاک <br />الحق انصاف توان داد که صاحبنظرند.<br /> <font color=\"Red\">سعدی .</font><br />شراب لعل کش و روی مه جبینان بین <br />خلاف مذهب آنان جمال اینان بین .<br /> <font color=\"Red\">حافظ.</font><br />آنانکه خاک را بنظر کیمیا کنند<br />آیا بود که گوشه ٔ چشمی بما کنند؟<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(2422, 'آناناس', '<span class=\"hlight\">آناناس .</span> (فرانسوی، اِ) نام درختی با میوه ای بهمان نام .<br /></font></div>'),
(2423, 'آنت', '<span class=\"hlight\">آنت .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> آن ْت ْ ]</font></b> (ضمیر + ضمیر) مخفف آن تورا. <BR><font color=\"Blue\">◄</font> (صوت ) زهی . خه خه . خَه . (برهان ).<br /></font></div>'),
(2424, 'آنتالسیداس', '<span class=\"hlight\">آنتالسیداس .</span> (اِخ ) آنتالکیداس . سردار مقدونی که عهد واگذاشتن اسپارطه را بشاهنشاه ایران او بست (<span class=\"hlight\" dir=\"rtl\">٣٨٧</span> ق . م .) و از اینرو منفور مردم یونان گردید.<br /></font></div>'),
(2425, 'آنتی پیرین', '<span class=\"hlight\">آنتی پیرین .</span> (فرانسوی، اِ مرکب ) ماده ای است که از زغال سنگ گیرند، و در طب مستعمل است چون مسکّن و تب بری .<br /></font></div>'),
(2426, 'آنتیل', '<span class=\"hlight\">آنتیل .</span> (اِخ ) نام مجمعالجزایری میان امریکای شمالی و جنوبی، و آن بمجمعالجزایر آنتیل بزرگ و مجمعالجزایر آنتیل کوچک منقسم است . سکنه ٔ مجموع آن <span class=\"hlight\" dir=\"rtl\">٨٤٠٠٠٠٠</span> تن . محصول آن قند و شراب رم و قهوه است . جزایر عمده ٔ آنتیل بزرگ کوبا، ژامائیک (جامائیکا) و هائی تی است و جزایر مهم آنتیل کوچک بارباد، گادولوپ، مارتی نیک، سن مارتن، سن لوسی، تری نی ته و غیره است . آتش فشانیها و زلزله ها در این جزایر بسیار روی دهد.<br /></font></div>'),
(2427, 'آنتیوش', '<span class=\"hlight\">آنتیوش .</span> <font color=\"DarkGreen\"><b>[ تیُش ْ ]</font></b> (اِخ ) آنتیُش . نامی است که مردم اروپا به انطاکیه میدهند.<br /></font></div>'),
(2428, 'آنتیک', '<span class=\"hlight\">آنتیک .</span> (فرانسوی، ص، اِ) (از لاطینی آنتی کواوس، به همین معنی ) ظرف یا جامه یا کتاب یا فرش یا مجسمه و مانند آن سخت دیرینه . <BR><font color=\"Blue\">◄</font> در تداول فارسی، سخت بد. سخت زشت و کریه .<br /></font></div>'),
(2429, 'آنتیک خر', '<span class=\"hlight\">آنتیک خر.</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (نف مرکب ) آنکه حرفتش خریدن آنتیک است .<br /></font></div>'),
(2430, 'آنتیک خری', '<span class=\"hlight\">آنتیک خری .</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (حامص مرکب ) عمل آنتیک خر.<br /></font></div>'),
(2431, 'آنتیک فروش', '<span class=\"hlight\">آنتیک فروش .</span> <font color=\"DarkGreen\"><b>[ ف ُ ]</font></b> (نف مرکب ) آنکه آنتیک فروشد.<br /></font></div>'),
(2432, 'آنتیک فروشی', '<span class=\"hlight\">آنتیک فروشی .</span> <font color=\"DarkGreen\"><b>[ ف ُ ]</font></b> (حامص مرکب ) حرفت آنتیک فروش . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) دکان آنتیک فروشی .<br /></font></div>'),
(2433, 'آنج', '<span class=\"hlight\">آنج .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِ) زعرور. گمان میکنم این صورت مصحف آلج باشد.<br /></font></div>'),
(2434, 'آنجا', '<span class=\"hlight\">آنجا.</span> (اِ مرکب، ق مرکب ) از اسماء اشاره بجائی دور چون ثَم َّ و هنا و هنالک در زبان عرب <span class=\"hlight\">:</span> <br />از آنجا به نزدیک مادر دوان <br />بیامد چو خورشید روشن روان .<br /> <font color=\"Red\">فردوسی .</font><br />چو آنجارسید آن گرانمایه شاه <br />پذیره شدش پهلوان سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />هم آنجا بدش تاج و گنج و سپاه <br />هم آنجا نگین و هم آنجا کلاه .<br /> <font color=\"Red\">فردوسی .</font><br />یکی تخت جامه بفرمود شاه <br />که آنجا بیارند پیش سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />بوعلی وی رابه تون فرستد چنانکه آنجا شهربند باشد. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آنجا که </span> ؛ آن مقام . آن حال . حیث <span class=\"hlight\">:</span> <br />بکن شیری آنجا که شیری سزد<br />که از شهریاران دلیری سزد.<br /> <font color=\"Red\">فردوسی .</font><br />آنجا که عقاب کندپر گردد<br />مرغابی تیزپر نخواهد شد.<br /><font color=\"Red\">عمادی شهریاری .</font><br /></font></div>'),
(2435, 'آنجاق', '<span class=\"hlight\">آنجاق .</span> (اِ مرکب ) (از ترکی جغتائی ) آن وقت <span class=\"hlight\">:</span> <br />در جافجانان ختا کافر نمیکرد این جفا<br />این بس که در عهد تو ما یاد آوریم آنجاق را.<br /><font color=\"Red\">خواجو (از شعوری ).</font><br /></font></div>'),
(2436, 'آنح', '<span class=\"hlight\">آنح .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص ) دم برآرنده از تاسه و جز آن . بسختی نفس کشنده . <BR><font color=\"Blue\">◄</font> آنکه تَنحنح کند. آنکه سینه روشن کند. <BR><font color=\"Blue\">◄</font> مجازاً، بخیل، یعنی آنکس که چون چیزی از او خواهند تنحنح آرد از بخل . ج، اُنَّح .<br /></font></div>'),
(2437, 'آنحه', '<span class=\"hlight\">آنحه .</span> <font color=\"DarkGreen\"><b>[ ن ِ ح َ ]</font></b> (ع ص ) زَن کوتاه قَد.<br /></font></div>'),
(2438, 'آندروماخس', '<span class=\"hlight\">آندروماخس .</span> <font color=\"DarkGreen\"><b>[ رُ خ ِ ]</font></b> (اِخ ) آندروماک (تِریاک ). نام سرپزشک نِرُن، عظیم روم (<span class=\"hlight\" dir=\"rtl\">٥٤</span>-<span class=\"hlight\" dir=\"rtl\">٦٨</span> م .). و تریاق یا تریاق فاروق منسوب بدوست . و تریاق مترودیطوس نیز همانست .<br /></font></div>'),
(2439, 'آندن', '<span class=\"hlight\">آندن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (پسوند) َاندن . چنانکه آنیدن (َانیدن )، پس از مفرد امر حاضر درآید و مصدر را متعدی سازد: ایستاندن . پوشاندن . جهاندن . خنداندن . خوراندن . خیزاندن . دواندن . کشاندن . گیراندن .<br /></font></div>'),
(2440, 'آندون', '<span class=\"hlight\">آندون .</span> (ق ) آنجا. مقابل ایدون، اینجا <span class=\"hlight\">:</span> <br />راه تو زی خیر و شرّْ هر دو گشاده ست <br />خواهی ایدون گرای و خواهی آندون .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> بدانسوی . بدان جهت <span class=\"hlight\">:</span> <br />خواسته چونان دهد که گوئی بستد<br />روی گه ایدون کند ز شرم گه آندون .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> چنان . مقابل ایدون، چنین . صاحب فرهنگ منظومه گفته است <span class=\"hlight\">:</span> <br />مثل آندون چنان، چنین ایدون <br />آگه آژیر بودن از چه و چون .<br /><BR><font color=\"Blue\">◄</font> آنگاه . آن زمان . آن دم . (جهانگیری ).<br /></font></div>'),
(2441, 'آنس', '<span class=\"hlight\">آنس .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص ) خوگرفته . خوگیرنده . مأنوس . انس گیرنده .<br /></font></div>'),
(2442, 'آنس', '<span class=\"hlight\">آنس .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (ع ن تف ) خوگیرنده تر. مأنوس تر.<br /></font></div>'),
(2443, 'آنسات', '<span class=\"hlight\">آنسات .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص، اِ) ج ِ آنِسه .<br /></font></div>'),
(2444, 'آنسته', '<span class=\"hlight\">آنسته .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (اِ) بیخ گیاهی است خوشبو که آن را عرب سُعد و به فارسی مشکک نیز گویند.<br /></font></div>'),
(2445, 'آنسه', '<span class=\"hlight\">آنسه .</span> <font color=\"DarkGreen\"><b>[ ن ِ س َ ]</font></b> (ع ص، اِ) تأنیث آنِس . زنی نیکوحدیث . طیّبةالنفس . ج، اَوانِس . <BR><font color=\"Blue\">◄</font> در تداول عربی امروز، به معنی دخترخانم، بانوچه بکار است .<br /></font></div>'),
(2446, 'آنشتنگاه', '<span class=\"hlight\">آنشتنگاه .</span> <font color=\"DarkGreen\"><b>[ ن ِ ت َ ]</font></b> (اِ مرکب ) بضبط صحاح الفرس، خلاخانه .متوضّا. مَبرز. رجوع به آبشتنگاه و آپشتنگاه شود.<br /></font></div>'),
(2447, 'آنف', '<span class=\"hlight\">آنف .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص ) ننگ دارنده . ج، آنفین . <BR><font color=\"Blue\">◄</font> رام . آهسته . <BR><font color=\"Blue\">◄</font> آنکه بینی او درد کند. <BR><font color=\"Blue\">◄</font> اول وقت . سابق . هم اکنون .<br /></font></div>'),
(2448, 'آنف', '<span class=\"hlight\">آنف .</span> <font color=\"DarkGreen\"><b>[ ن ُ ]</font></b> (ع اِ) ج ِ اَنْف .<br /></font></div>'),
(2449, 'آنف', '<span class=\"hlight\">آنف .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (ع ن تف ) آنف بلاد؛ آنکه حاصل آن پیش رس تر باشد. <BR><font color=\"Blue\">◄</font> بادسرتر. کله شَخ تر. منیعتر. ابی تر. مستنکف تر. <BR><font color=\"Blue\">◄</font> (ص ) بزرگ بینی .<br /></font></div>'),
(2450, 'آنفه', '<span class=\"hlight\">آنفه .</span> <font color=\"DarkGreen\"><b>[ ن ِ ف َ ]</font></b> (ع اِ) آنفه ٔ صِبا، آنفه ٔ شباب ؛ اوّل صِبا. اوّل شباب . میعه ٔ صِبا. میعه ٔ شباب .<br /></font></div>'),
(2451, 'آنفین', '<span class=\"hlight\">آنفین .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص، اِ) ج ِ آنِف .<br /></font></div>'),
(2452, 'آنقره', '<span class=\"hlight\">آنقره .</span> <font color=\"DarkGreen\"><b>[ ق ُ رَ ]</font></b> (اِخ ) رجوع به انگوریه شود.<br /></font></div>'),
(2453, 'آنقون', '<span class=\"hlight\">آنقون .</span> (اِ) اَنقون . ایقون . گلگنده . وردالمنتن . و نوعی از آن دورس و معرب آن دریاس است .<br /></font></div>'),
(2454, 'آنند', '<span class=\"hlight\">آنند.</span> <font color=\"DarkGreen\"><b>[ ن َن ْ ]</font></b> (اِخ ) یا آنند و زیراب . نام خُرّه ای از ولوپی سوادکوه، و قریه ٔ بزرگ آن زیراب است .<br /></font></div>'),
(2455, 'آنه', '<span class=\"hlight\">آنه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (هندی، اِ) شانزده یک ِ قیراط: الماسی بوزن پنج قیراط و دو آنه . <BR><font color=\"Blue\">◄</font> شانزده یک ِ روپیه .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2456, 'آنه', '<span class=\"hlight\">آنه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (پسوند) َانه . چون در آخر اسماء ملحق شود دلالت کند بر یکی از معانی ذیل : مانند.مثل . چون . بطور. بگونه ٔ. لائق . درخور. سزاوار. متعلق به . مال . منسوب به . در حال . در وقت . بصفت . هر یک :<br />مستانه <span class=\"hlight\">:</span> <br />اندرین بود که از مستی و از غایت شرم <br />خواب مستانه در آن لحظه درآورد حشر.<br /> <font color=\"Red\">سنائی .</font><br />ساکنان حرم ستر و عفاف ملکوت <br />با من راه نشین باده ٔ مستانه زدند.<br /> <font color=\"Red\">حافظ.</font><br />یک ناله ٔ مستانه ز جائی نشنیدیم <br />ویران شود آن شهر که میخانه ندارد.<br /> <font color=\"Red\">؟</font><br />مردانه <span class=\"hlight\">:</span> <br />چنین داد پاسخ بفرزانگان <br />بدان نامداران و مردانگان .<br /> <font color=\"Red\">فردوسی .</font><br />مردانه دوختیم و کس از ما نمی خرد<br />رو رو زنانه دوز که مردانه میخرند.<br /> <font color=\"Red\">؟</font><br />شاهانه <span class=\"hlight\">:</span> <br />همه موی شاهانه از سر بکند<br />همی ریخت بر تخت خاک نژند.<br /> <font color=\"Red\">فردوسی .</font><br />هر گوشه یکی مستی دستی زده بر دستی <br />زآن ساقی هر مستی با ساغر شاهانه .<br /> <font color=\"Red\">مولوی .</font><br />عاشقانه <span class=\"hlight\">:</span> <br />دلت بوصل گل ای بلبل صبا خوش باد<br />که در چمن همه گلبانگ عاشقانه ٔ تست .<br /> <font color=\"Red\">حافظ.</font><br />شبانه <span class=\"hlight\">:</span> <br />دام جهانست بر تو و خبرت نیست <br />گاهی مستی ّ و گه خمار شبانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بدانش گرای و در این روز پیری <br />برون افکن از سر خمار شبانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />داری سخن خوب گوش یانه <br />کامروز نه هشیاری از شبانه ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />سحرگاهان که مخمور شبانه <br />گرفتم باده با چنگ و چغانه .<br /> <font color=\"Red\">حافظ.</font><br />معاشران ز حریف شبانه یاد آرید<br />حقوق بندگی مخلصانه یاد آرید.<br /> <font color=\"Red\">حافظ.</font><br />پیرانه <span class=\"hlight\">:</span> <br />پسر را بکشتم به پیرانه سر<br />بریده پی و بیخ آن نامور.<br /> <font color=\"Red\">فردوسی .</font><br />نیا چون شنید از نبیره سخُن <br />یکی پند پیرانه افکند بن .<br /> <font color=\"Red\">فردوسی .</font><br />پدر چون دور عمرش منقضی گشت <br />مرا پیرانه پندی داد و بگذشت .<br /> <font color=\"Red\">سعدی .</font><br />خوشتر از کوی خرابات نباشد جائی <br />گر به پیرانه سرم دست دهد مأوائی .<br /> <font color=\"Red\">حافظ.</font><br />ماهیانه <span class=\"hlight\">:</span> <br />همان نیز هر ماهیانه دو بار<br />درم شصت، گنجی، بر او برشمار.<br /> <font color=\"Red\">فردوسی .</font><br />درانه و دوزانه <span class=\"hlight\">:</span> <br />درّانه و دوزانه بسر کلک نیابی (کذا)<br />درّانه و دوزانه بسر کلک و بنان است .<br /> <font color=\"Red\">منوچهری .</font><br />جادوانه <span class=\"hlight\">:</span> <br />آن چشم جادوانه ٔ عابدفریب بین <br />کش کاروان سحر بدنباله میرود.<br /> <font color=\"Red\">حافظ.</font><br />مغانه <span class=\"hlight\">:</span> <br />مؤمنی و می خوری بجز تو ندیدم <br />در جسد مؤمنانه جان مغانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />که تا روز خواهی نیوشید و نوشید<br />سماع مغنی شراب مغانه .<br /> <font color=\"Red\">انوری .</font><br />پدرانه <span class=\"hlight\">:</span> با خرد رجوع کن تا بدانی که نصیحت پدرانه میکنم . (تاریخ بیهقی ).<br />زنانه <span class=\"hlight\">:</span> <br />کشان دامن اندر ره کوی و برزن <br />زنان دست بر شعرهای زنانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کسانه <span class=\"hlight\">:</span> <br />بیدار و هشیوار مرد نَنْهَد<br />دل بر وطن و خانه ٔ کسانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آمدنی اندرین سرای کسانند<br />خیز و برون شو از این سرای کسانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نه بینی همی خویشتن را نشسته <br />غریب و سپنجی بخانه کسانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چاکرانه <span class=\"hlight\">:</span> <br />آنکس که ترا داد صدر و بالش <br />خود رفت بدانجای چاکرانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دوستانه <span class=\"hlight\">:</span> <br />دشمن ارچه دوستانه گویدت <br />دام دان گرچه ز دانه گویدت .<br /> <font color=\"Red\">مولوی .</font><br />یگانه <span class=\"hlight\">:</span> <br />یگانه ٔ زمانه شدستی ولیکن <br />نشد هیچکس را زمانه یگانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آنکس که زبانش بما رسانید<br />پیغام جهان داور یگانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مرادی یاسمین پیغام داده ست <br />بتو ای صاحب صدر یگانه .<br /> <font color=\"Red\">انوری .</font><br />جانانه <span class=\"hlight\">:</span> <br />ببوی زلف تو گر جان بباد رفت چه شد<br />هزار جان گرامی فدای جانانه .<br /> <font color=\"Red\">حافظ.</font><br />صوفیانه <span class=\"hlight\">:</span> <br />چو اندر وثاق آمدی نانشسته <br />فروریختی خورده ٔ صوفیانه .<br /> <font color=\"Red\">انوری .</font><br />طالب علمانه <span class=\"hlight\">:</span> <br />کبک چون طالب علم است و در این نیست شکی ...<br />پیرهن دارد زین طالب علمانه یکی .<br /> <font color=\"Red\">منوچهری .</font><br />خرانه <span class=\"hlight\">:</span> <br />راه خران است خواب و خوردن و رفتن <br />خیره مرو با خرد براه خرانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تازیانه، تازانه <span class=\"hlight\">:</span> <br />گر ایدون که تازانه بازآورم <br />و یا سر بگوشش بگاز آورم .<br /> <font color=\"Red\">فردوسی .</font><br />من این درع و تازانه برداشتم <br />بتوران دگرخوار بگذاشتم .<br /> <font color=\"Red\">فردوسی .</font><br />وزآن پس ببین تا که آید ز راه <br />همی کن بدین تازیانه نگاه .<br /> <font color=\"Red\">فردوسی .</font><br />که این تازیانه بدرگاه بر<br />بیاویز جائی که باشد گذر.<br /> <font color=\"Red\">فردوسی .</font><br />زین به نبود مذهبی که گیری <br />از بیم عقابین و تازیانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />اگر اسب تازیست یک تازیانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />راستانه <span class=\"hlight\">:</span> <br />جهان خانه ٔ راستان نیست راهت <br />بگردان سوی خانه ٔ راستانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />زاولانه <span class=\"hlight\">:</span> <br />چون خانه ٔ بیگانه ت آشنا شد<br />خو کرد در این بند و زاولانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بشهر تو گرچه گران است آهن <br />نشائی تو بی بند و بی زاولانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دیوانه <span class=\"hlight\">:</span> <br />هشیواردیوانه خواند ورا<br />همان خویش بیگانه خواند ورا.<br /> <font color=\"Red\">فردوسی .</font><br />دل زال یکباره دیوانه گشت <br />خرد دورشد عشق فرزانه گشت .<br /> <font color=\"Red\">فردوسی .</font><br />عاشقی از بند عقل و عافیت جستن بود<br />گر چنینی عاشقی ور نیستی دیوانه ای .<br /> <font color=\"Red\">سنائی .</font><br />آسمان بار امانت نتوانست کشید<br />قرعه ٔ فال به نام من دیوانه زدند.<br /> <font color=\"Red\">حافظ.</font><br />جوانه <span class=\"hlight\">:</span> <br />شراب جوانه هنوز از قدح <br />همی زد بتعجیل بر، تابها.<br /> <font color=\"Red\">منوچهری .</font><br />دبیرانه <span class=\"hlight\">:</span> <br />چون دو انگشت دبیرانه کند وقت بهار<br />بدوات بُسَدین اندر شب گیر بگاه .<br /> <font color=\"Red\">منوچهری .</font><br />بَریدانه <span class=\"hlight\">:</span> <br />چون بَریدانه مرقع بتن اندر فکند<br />راست چون پیکان نامه بسر اندر بزند.<br /> <font color=\"Red\">منوچهری .</font><br />مخلصانه <span class=\"hlight\">:</span> <br />معاشران ز حریف شبانه یاد آرید<br />حقوق بندگی مخلصانه یاد آرید.<br /> <font color=\"Red\">حافظ.</font><br />رندانه <span class=\"hlight\">:</span> <br />در خرقه از این بیش منافق نتوان بود<br />بنیاد از این شیوه ٔ رندانه نهادیم .<br /> <font color=\"Red\">حافظ.</font><br />و از این قبیل است : دوستانه . درویشانه . طبیبانه . غریبانه . حکیمانه . عالمانه . عارفانه . کودکانه . دخترانه . پسرانه . بچگانه . صبحانه . عصرانه . انگشتانه . ویارانه . پرهیزانه . هوسانه . روزانه . سالانه . ماهانه . شاگردانه . شاهانه . شاعرانه . بیعانه . سرانه . هندوانه . شامیانه . محرمانه . مخفیانه . گستاخانه . مجرمانه .هردوانه . عاقلانه و جز آن .<br /></font></div>'),
(2457, 'آنه', '<span class=\"hlight\">آنه .</span> <font color=\"DarkGreen\"><b>[ ن ِه ْ ]</font></b> (ع ص ) بسختی نفس کشنده . نالنده از گرانی بار.<br /></font></div>'),
(2458, 'آنه', '<span class=\"hlight\">آنه .</span> <font color=\"DarkGreen\"><b>[ آن ْ ن َ ]</font></b> (ع ص ) زن ناله کننده . مُتاعَمه . متوجّعه . <BR><font color=\"Blue\">◄</font> (اِ) بکنایه، گوسفند ماده . <BR><font color=\"Blue\">◄</font> کنیز.<br /></font></div>'),
(2459, 'آنها', '<span class=\"hlight\">آنها.</span> (ضمیر) ج ِ آن . آنان . ایشان . اوشان <span class=\"hlight\">:</span> <br />گر آنها که می گفتمی کردمی <br />نکوسیرت وپارسا بودمی .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(2460, 'آنهمه', '<span class=\"hlight\">آنهمه .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب، ق مرکب ) تمام آن <span class=\"hlight\">:</span> <br />چو بشنید شه کیقباد آن همه <br />برآورد سر از میان رمه .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> آن مقدار بسیار <span class=\"hlight\">:</span> <br />ایا ز بیم زبانم نژند گشته و هاژ<br />کجا شد آنهمه دعوی ّ و لاف و آنهمه ژاژ؟<br /><font color=\"Red\">لبیبی .</font><br /></font></div>'),
(2461, 'آنوبانی نی', '<span class=\"hlight\">آنوبانی نی .</span> (اِخ ) نام یکی از پادشاهان لولویی، در ناحیه ٔ سرپل زهاب . دومرگان کتیبه ای یافته که یکی از قدیمترین آثار باستانی آسیاست و صورت آنوبانی نی بر آن منقوش است که پای بر روی اسیری نهاده و از نی نی رب النوع دو اسیر دیگر می گیرد که بینی یکی از آن دو مهار شده و اسرای دیگر در زیر این کتیبه اند و نوشته های آن از کثرت قدمت سوده و فرسوده است و بدرستی قابل خواندن نیست .<br /></font></div>'),
(2462, 'آنوبیس', '<span class=\"hlight\">آنوبیس .</span> <font color=\"DarkGreen\"><b>[ ن ُ ]</font></b> (از یونانی، اِ) بیونانی اشراس است . آنویس .<br /></font></div>'),
(2463, 'آنورسما', '<span class=\"hlight\">آنورسما.</span> <font color=\"DarkGreen\"><b>[ ن ُ رُ ]</font></b> (از یونانی، اِ) (از یونانی آن رُوسما، اتّساع ) بیماری اتّساع شرایین یا قلب .<br /></font></div>'),
(2464, 'آنومیا', '<span class=\"hlight\">آنومیا.</span> <font color=\"DarkGreen\"><b>[ ن ُ ]</font></b> (از یونانی، اِ) لاله ٔ کوهی . شقیقةالنعمان .<br /></font></div>'),
(2465, 'آنویس', '<span class=\"hlight\">آنویس .</span> <font color=\"DarkGreen\"><b>[ ن ُ وی ]</font></b> (از یونانی، اِ) آنوبیس .<br /></font></div>'),
(2466, 'آنچ', '<span class=\"hlight\">آنچ .</span> (ضمیر + حرف ربط) مخفف آنچه <span class=\"hlight\">:</span> <br />بیاورد جاماسب آنچ او بخواست <br />بپوشید و آنگاه برپای خاست .<br /> <font color=\"Red\">فردوسی .</font><br />هرآنچ آفریده ست جفت آفرید<br />گشاده ز راز نهفت آفرید.<br /> <font color=\"Red\">فردوسی .</font><br />وآنچ او خَلَق شود چه بود؟ مُحْدَث <br />هر عاجز این بداند و نادانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />غافل کی بود خداوند از آنچ <br />رفت در این سبز و بلند آسیاش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />توانائی و آفرینش تراست <br />همی سازی آن کز تو آنت سزاست <br />تو آنچ از پیمبر رسیدت بگوش <br />بفرمان بجای آر و آن را بکوش .<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(2467, 'آنچت', '<span class=\"hlight\">آنچت .</span> <font color=\"DarkGreen\"><b>[ چ ِ ]</font></b> (ضمیر + حرف ربط + ضمیر) مخفف آنچه ترا <span class=\"hlight\">:</span> <br />بدو گفت زال ای پسر هوش دار<br />هر آنچت بگویم ز من گوش دار.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2468, 'آنچش', '<span class=\"hlight\">آنچش .</span> <font color=\"DarkGreen\"><b>[ چ ِ ]</font></b> (ضمیر + حرف ربط + ضمیر) مخفف آنچه اش . آنچه او را <span class=\"hlight\">:</span> <br />بدو بازداد آنچنان کش بخواست <br />بیفزود در تن هر آنچش بکاست .<br /> <font color=\"Red\">فردوسی .</font><br />فرود آوردی آنچش خود برآوردی <br />گسستی هرچه را کآن خود به پیوستی .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(2469, 'آنچنان', '<span class=\"hlight\">آنچنان .</span> <font color=\"DarkGreen\"><b>[ چ ُ ]</font></b> (ص مرکب، ق مرکب ) مخفف آن چونان . بطوری . بقسمی . بدانگونه . آنطور. آنگونه .<br /></font></div>'),
(2470, 'آنچه', '<span class=\"hlight\">آنچه .</span> <font color=\"DarkGreen\"><b>[ چ ِ ]</font></b> (ضمیر + حرف ربط) آن چیز که . هر چیز که . هرچه . هرچه را که . تمام چیزها که . آن چیز را که . هر چیز که از <span class=\"hlight\">:</span> <br />رو بخور و هم بده که گشت پشیمان <br />هرکه نخورد و نداد از آنچه بیلفخت .<br /> <font color=\"Red\">رودکی .</font><br />جدا کرد گاو و خر و گوسفند<br />بورز آورید آنچه بد سودمند.<br /> <font color=\"Red\">فردوسی .</font><br />بدیشان بگفت آنچه بایست گفت <br />همان نیز با مریم اندر نهفت .<br /> <font color=\"Red\">فردوسی .</font><br />بگنج اندرون آنچه بد نامدار<br />گزیدند زربفت چینی هزار.<br /> <font color=\"Red\">فردوسی .</font><br />ورا سام یل گفت برگرد و رو<br />بگو آنچه دیدی بمهراب گَو.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت رو آنچه داری بیار<br />خورش نیز با بَرْسَم آید بکار.<br /> <font color=\"Red\">فردوسی .</font><br />بگفت آنچه بشنید از آن مهتران <br />بدان نامداران و گندآوران .<br /> <font color=\"Red\">فردوسی .</font><br />ز شطرنج بازی ّ و از رنج رای <br />بگفت آنچه آمد همه رهنمای .<br /> <font color=\"Red\">فردوسی .</font><br />همی تاخت تا پیش خاقان رسید<br />یکایک بگفت آنچه دید و شنید.<br /> <font color=\"Red\">فردوسی .</font><br />آنچه بودم بخانه خم و کنور<br />وآنچه از گونه گون قماش و خنور.<br /> <font color=\"Red\">طیان .</font><br />آنچه خواهی که نَدْرَویش مکار<br />وآنچه خواهی که نشنویش مگوی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />شنیدم آنچه بیان کردی لیکن بعقل خود رجوع کن . (کلیله و دمنه ). شاخ رَز...بر آنچه نزدیکتر باشد درآویزد. (کلیله و دمنه ). آنچه در دهن داشت بباد داد. (کلیله و دمنه ). و اجتهاد تو در کارها و رأی آنچه در امکان آید علماء و اشراف مملکت را نیز معلوم گردد. (کلیله و دمنه ).<br />روی تو دارد ز حسن آنچه پری آن نداشت <br />حسن تو دارد ز ملک آن که سلیمان نداشت .<br /> <font color=\"Red\">خاقانی .</font><br />آنچه آبست است شب جز آن نزاد<br />حیله ها و مکرها باد است باد.<br /> <font color=\"Red\">مولوی .</font><br />آنچه گندم کاشتندش آنچه جو<br />چشم او آنجاست روز و شب گرو.<br /> <font color=\"Red\">مولوی .</font><br />آنچه آن خر دید از رنج و عذاب <br />مرغ خاکی بیند اندر سیل آب .<br /> <font color=\"Red\">مولوی .</font><br />آتش سوزان نکند با سپند<br />آنچه کند دود دل مستمند.<br /> <font color=\"Red\">سعدی .</font><br />آنچه خوبان همه دارند تو تنها داری .<br /><font color=\"Red\">؟</font><br /></font></div>'),
(2471, 'آنک', '<span class=\"hlight\">آنک .</span> (ضمیر + حرف ربط) مخفف آنکه <span class=\"hlight\">:</span> <br />یک قحف خون بچه ٔ تاکم فرست از آنک <br />هم بوی مشک دارد هم گونه ٔ عقیق .<br /> <font color=\"Red\">عماره .</font><br />با او بمراد دل زی ای دل از آنک <br />ار دانی خواست کام، در کام رسی .<br /> <font color=\"Red\">(از قابوسنامه ).</font><br />دشنام دهی بازدهندت ز پی آنک <br />دشنام مَثَل چون درم دیرمدار است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بنده کردش بطبع از پی آنک <br />شیفته بر نگار منثور است .<br /> <font color=\"Red\">مسعودسعد.</font><br />کی دیده و رخ چون زرو چون سیم کند آنک <br />لفظی چوگهر هستش اگر سیم و زری نیست .<br /> <font color=\"Red\">سنائی .</font><br />با دوستان خورآنچه ترا هست پیش از آنک <br />بعد از تو دشمنان تو با دوستان خورند.<br /><font color=\"Red\">ادیب صابر.</font><br /></font></div>'),
(2472, 'آنک', '<span class=\"hlight\">آنک .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (صوت، ق ) کلمه ای است برای اشاره ٔ به دور، اعم از مکان یا زمان . مقابل اینک که برای اشاره ٔ نزدیک است <span class=\"hlight\">:</span> <br />آنک بنگر ز روی او یکسر<br />کآرام نماندش گه زادن .<br /> <font color=\"Red\">مسعودسعد.</font><br />گر دند خواهی اینک، ور تو ملک خوهی <br />آنک علأدین ملک عنبرین کمند.<br /> <font color=\"Red\">سوزنی .</font><br />چو هر دانشی کآنک اندوختند<br />نخستین ورق زو درآموختند.<br /> <font color=\"Red\">نظامی .</font><br />خلاف رای سلطان رای جستن <br />بخون خویش باشد دست شستن <br />اگر خود روز را گوید شب است این <br />بباید گفت آنک ماه و پروین .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(2473, 'آنک', '<span class=\"hlight\">آنک .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِ) آبله که بر اندام برآید.<br /></font></div>'),
(2474, 'آنک', '<span class=\"hlight\">آنک .</span> <font color=\"DarkGreen\"><b>[ ن ُ ]</font></b> (ع اِ) سُرُب . سُرْب . اُسرُب . اُسرُف . رصاص یا رصاص اسود. <BR><font color=\"Blue\">◄</font> قلعی یا رصاص ابیض .<br /></font></div>'),
(2475, 'آنکارا', '<span class=\"hlight\">آنکارا.</span> (اِخ ) رجوع به انگوریه شود.<br /></font></div>'),
(2476, 'آنکت', '<span class=\"hlight\">آنکت .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ضمیر + حرف ربط + ضمیر) مخفف آنکه ترا <span class=\"hlight\">:</span> <br />آنکت کلوخ روی لقب کرد خوب کرد<br />ایرا لقب گران نبود بر دل فغاک .<br /><font color=\"Red\">منجیک .</font><br /></font></div>'),
(2477, 'آنکش', '<span class=\"hlight\">آنکش .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ضمیر + حرف ربط + ضمیر) مخفف آنکه اَش . آنکه او را <span class=\"hlight\">:</span> <br />هر آن شمعی که ایزد برفروزد<br />هر آنکش پف کند سبلت بسوزد.<br /><font color=\"Red\">ابوشکور (از تحفه ٔ اوبهی ).</font><br /></font></div>'),
(2478, 'آنکه', '<span class=\"hlight\">آنکه .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ضمیر + حرف ربط) از موصولات، به معنی آن کس که . کسی که . هر کس که . بجای الذی و الّتی عرب <span class=\"hlight\">:</span> <br />آنکه نشک آفرید و سرو سهی <br />آنکه بید آفرید و نار وبهی .<br /> <font color=\"Red\">رودکی .</font><br />ای آنکه من از عشق تو اندرجگر خویش <br />آتشکده دارم صد و در هر مژه ای ژی .<br /> <font color=\"Red\">رودکی .</font><br />آنکه گردون را بدیوان بر نهاد و کار بست <br />وآنکجا بودش خجسته مهر آهرمن گراه .<br /> <font color=\"Red\">دقیقی .</font><br />خورید و دهید آنکه دارید چیز<br />کسی کو ندارید خواهید نیز.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد پس آن نرّه شیر دلیر<br />نبرده سوار آنکه نامش زریر.<br /> <font color=\"Red\">فردوسی .</font><br />میر ابواحمد محمد خسرو ایران زمین <br />آنکه پیش آرد در شادی چو پیش آید کفا.<br /> <font color=\"Red\">قصار امی (از فرهنگ اسدی ).</font><br />آنکه خوبی از او نمونه بود<br />چون بیارائیش چگونه بود؟<br /> <font color=\"Red\">عنصری .</font><br />ای آنکه تاخته ریسی از منبر <font color=\"DarkGreen\"><b>[ کذا ]</font></b><br />باریک تر از من نه بریسی نه برشتی .<br /> <font color=\"Red\">اسدی (از فرهنگ، خطی ).</font><br />آنکه بود بر سخن سوار سوار اوست <br />آن نه سوار است کو بر اسب سوار است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ونیز آنکه سعی برای آخرت کند مرادهای دنیا بتبعیت بیابد. (کلیله و دمنه ).<br />آنکه جنگ آرد بخون خویش بازی می کند<br />روز میدان، وآنکه بگریزدبخون لشکری .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> و در غیرذوی العقول و نیز غیرذوی الروح آمده است . آنچه . آن چیز که . آنچه را که <span class=\"hlight\">:</span> <br />رمنده ددان را همه بنگرید<br />سیه گوش و یوز از میان برگزید<br />بچاره بیاوردش از دشت و کوه <br />به بند آمدند آنکه بد زآن گروه .<br /> <font color=\"Red\">فردوسی .</font><br />ز مرغان همان آنکه بد نیکساز...<br />بیاورد و آموختنْشان گرفت ...<br /><font color=\"Red\">فردوسی .</font><br />کنون آنکه گفتی ز کار دو اسب <br />گریزان بکردار آذرگشسب ...<br /> <font color=\"Red\">فردوسی .</font><br />یکی آنکه گفتی شمار سپاه <br />فزون تر بد از تابش هور و ماه ...<br /> <font color=\"Red\">فردوسی .</font><br />چرا نخوانی <font color=\"DarkGreen\"><b>[ خطاب به عبدالرحمن فضولی ]</font></b> آنکه شاعر گوید... (تاریخ بیهقی ).<br /></font></div>'),
(2479, 'آنکو', '<span class=\"hlight\">آنکو.</span> (ضمیر + حرف ربط + ضمیر) مخفف آنکه او. آن کس که او <span class=\"hlight\">:</span> <br />یکی آنکه گفتی شمار سپاه <br />فزونتر بد از تابش هور و ماه <br />ستوران و پیلان چو تخم گیا<br />شد اندر دم پرّه ٔ آسیا<br />بر آنکو چنین بود برگشت روز<br />نمانی تو هم شاد و گیتی فروز.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2480, 'آنگاه', '<span class=\"hlight\">آنگاه .</span> (ق مرکب ) پس از آن . پس . سپس . آنگه . در آخر. بعد. بعد از آن <span class=\"hlight\">:</span> <br />چو سی روزگردش بپیمایدا<br />دو روز و دو شب روی ننمایدا<br />پدید آید آنگاه بارنگ زرد...<br /> <font color=\"Red\">فردوسی .</font><br />آنگاه یکی ساتگنی باده برآرد.<br /> <font color=\"Red\">منوچهری .</font><br />وآنگاه یکی زرگرک زیرک جادو<br />به آژیر بهم بازنهاده لب هر دو...<br /> <font color=\"Red\">منوچهری .</font><br />حرکت خواهیم کرد بر جانب بلخ ... آنگاه سوی غزنین رفته آید. (تاریخ بیهقی ). نخست بر منابر نام ما برند بشهرها و خطبه به نام ما کنند، آنگاه به نام وی . (تاریخ بیهقی ). به قدرخان ... بباید نبشت تا رکابداری بتعجیل ببرد... آنگاه چون رکاب عالی ... ببلخ رسد تدبیر گسیل کردن رسولی ... کرده آید. (تاریخ بیهقی ). آنگاه فرمود بازگردید و طلب کنید در مملکت من خردمند مردمان را. (تاریخ بیهقی ). نخست خطبه خواهم نبشت ... آنگاه تاریخ روزگار همایون او برانم . (تاریخ بیهقی ). نامه ها که از کوتوال کرک آمدی همه عبدوس عرضه کردی آنگاه نزدیک استادم فرستادی . (تاریخ بیهقی ). و چون از این فارغ شدم آنگاه بسر آن بازشوم . (تاریخ بیهقی ). بر سکه ٔ درم و دینار... نخست نام ما نویسند آنگاه نام وی . (تاریخ بیهقی ). امیرمسعود را بیاوردی و بر صدر بنشاندی آنگاه امیرمحمد را بیاوردندی . (تاریخ بیهقی ). ملوک روزگار که با یکدیگر دوستی بسر برند... وفاق و ملاطفات را پیوسته گردانند و آنگاه آن لطف حال را بدان منزلت رسانند که دیدار کنند. (تاریخ بیهقی ). از وی و پسرش خط بستانند بنام خزانه ٔ معمور آنگاه حدیث آن مال با سلطان افکنده آید. (تاریخ بیهقی ). گروهی از فرزندان آدم ... یکدیگر را... میخورند... آنگاه خود می گذارند و می روند. (تاریخ بیهقی ). و بر سکه ٔ درم و دینار و طراز جامه نخست نام ما نویسند آنگاه نام برادر. (تاریخ بیهقی ). چون از این فارغ شوم آنگاه نشستن این پادشاه ببلخ بر تخت ملک پیش گیرم . (تاریخ بیهقی ). التماس کردند که فلان رنجور است توجّه خاطر شریف درویزه می نماید فرمودند اول بازگشت خسته می باید آنگاه توجه خاطر شکسته . (انیس الطالبین بخاری ). <BR><font color=\"Blue\">◄</font> آن وقت . آن زمان . آن هنگام <span class=\"hlight\">:</span> <br />وز درخت اندر گواهی خواهد اوی <br />تو بدانگاه ازدرخت اندر بگوی <br />کان تبنگو کاندرو دینار بود<br />آن ستد زیدر که ناهشیار بود.<br /> <font color=\"Red\">رودکی .</font><br /> <br />چون شدم نیم مست و کالیوه <br />باطل آنگاه نزد من حق بود.<br /> <font color=\"Red\">خطیری .</font><br />ایشان دبیری نیک بکردندی و لکن این نمط که از تخت ملوک بتخت ملوک باید نبشت دیگر است و مرد آنگاه آگاه شود که نبشتن گیرد. (تاریخ بیهقی ). هرچه در خشم فرمان دهم آن را امضاء نکنند تا... آنگاه که نظر کنم بر آن و پرسم که اگر آن خشم را بحق کرده باشم چوبی چند زنند. (تاریخ بیهقی ). هر کس که او خویشتن را بشناخت ... آنگاه او بداند که مرکب است از چهار چیز که تن بدو بپاست .(تاریخ بیهقی ). اگر وی را امروز بر این نهاد یله کنیم آنچه خواسته آمده است از غلام و... سلاح فرستاده آید آنگاه فرستد که عهدی باشد که قصد خراسان کرده نیاید. (تاریخ بیهقی ). تا آنگاه که ایشان را این اتفاق خوب روی نمود. (کلیله و دمنه ). و آنگاه انگشت بگزید وگفت آه آه . (کلیله و دمنه ). و آنگاه آن را در صورت هزل فرانموده . (کلیله و دمنه ). و آنگاه مثال داد تا روزی مسعود و طالعی میمون برای حرکت او تعیین کردند.(کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> معهذا. و معهذا. و معذلک <span class=\"hlight\">:</span> <br />اندازد ابروانْت همه ساله تیرغوش <br />وآنگاه گویدم که خروشان مشو خموش .<br /> <font color=\"Red\">خسروی .</font><br />بسیار طبیبانند که می گویند فلان چیز نباید خوردن ... آنگاه خود از آن بسیار خورند. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> و بعلاوه . و از آن گذشته <span class=\"hlight\">:</span> خرد آن بودی که ... وی را بخوبی باز خانه فرستادی وآنگاه آزرده کردن بوعبداﷲ از همه زشت تر بود. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آنگاه که </span> ؛ وقتی که . زمانی که . چون .<br /></font></div>'),
(2481, 'آنگرامانیو', '<span class=\"hlight\">آنگرامانیو.</span> (اِخ ) اَنْگْرَه مَئین یَوَه . اهریمن . آهرمن .<br /></font></div>'),
(2482, 'آنگلتر', '<span class=\"hlight\">آنگلتر.</span> <font color=\"DarkGreen\"><b>[ ل ِ ت ِ ]</font></b> (اِخ ) انگلیس . انگلستان . مجموع جزایر بریتانیا.<br /></font></div>'),
(2483, 'آنگلند', '<span class=\"hlight\">آنگلند.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) آنگلتر.<br /></font></div>'),
(2484, 'آنگلوساکسن', '<span class=\"hlight\">آنگلوساکسن .</span> <font color=\"DarkGreen\"><b>[ گ ْ <span class=\"hlight\" dir=\"rtl\">/</span> گ ِ ل ُ سا س ُ ]</font></b> (اِخ ) نام عام ملل ژرمنی که در مائه ٔ ششم م . بر بریطانیه تسلط یافتند. آنگل ها. ژوت ها. ساکسن ها.<br /></font></div>'),
(2485, 'آنگلی کانی', '<span class=\"hlight\">آنگلی کانی .</span> (اِخ ) مذهب رسمی انگلستان و آن از زمان هنری هشتم آغاز شد آنگاه که پاپ از اجازه ٔ طلاق کاترین ملکه ٔ انگلستان امتناع ورزید.<br /></font></div>'),
(2486, 'آنگندن', '<span class=\"hlight\">آنگندن .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ ]</font></b> (مص ) آکندن . پر ساختن . انباشتن .<br /></font></div>'),
(2487, 'آنگه', '<span class=\"hlight\">آنگه .</span> <font color=\"DarkGreen\"><b>[ گ َه ْ ]</font></b> (ق مرکب ) آنگاه . پس . سپس . بعد. بعد از آن <span class=\"hlight\">:</span> اکنون نواحی اسلام همه یاد کنیم و آنگه باقی نواحی کافران یاد کنیم . (حدودالعالم ). و اندر وی <font color=\"DarkGreen\"><b>[ اندر نصیبین ]</font></b> چشمه ها است بسیار و از آن چشمه ها پنج رود برخیزد و بیک جای گرد شود و آن را خابور خوانند و آنگه اندر فرات افتد. (حدودالعالم ).<br />شاها هزار سال بعز اندرون بزی <br />وآنگه هزار سال بملک اندرون ببال .<br /> <font color=\"Red\">عنصری .</font><br />وز پشت فروگیرد و بر هم نهد انبار<br />آنگه بیکی چرخشت اندر فکَنَدْشان .<br /> <font color=\"Red\">منوچهری .</font><br />یک جزو مغنسیا بباید گرفت با یک جزو بُسد و یک جزو زنگار آنگاه هر سه را خرد بساید... آنگه یک من نرم آهن بیاورد.(نوروزنامه ). <BR><font color=\"Blue\">◄</font> آن وقت . آن زمان . در آن حال . در آن هنگام <span class=\"hlight\">:</span> <br />نکنی طاعت و آنگه که کنی سست و ضعیف <br />راست گوئی که همه سخره و شاکار کنی .<br /> <font color=\"Red\">کسائی .</font><br />بدانگه کجا مادرت را ز چین <br />فرستاد خاقان بایران زمین .<br /> <font color=\"Red\">فردوسی .</font><br />نه بینی که عیسی ّ مریم چه گفت <br />بدانگه که بگشاد راز نهفت ؟<br /> <font color=\"Red\">فردوسی .</font><br />که آیم بر افراز کُه ْ چون پلنگ <br />نه دژ ماند آنگه نه کهسار و سنگ .<br /> <font color=\"Red\">فردوسی .</font><br />چون شدم نیم مست و کالیوه <br />باطل آنگه بنزد من حق بود.<br /> <font color=\"Red\">حصیری (خطیری ؟).</font><br />ساخت آنگه یکی بیوگانی <br />هم بر آئین و رسم یونانی .<br /> <font color=\"Red\">عنصری .</font><br />چه سود از دزدی آنگه توبه کردن <br />که نتوانی کمند انداخت بر کاخ .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">زآنگه که </span> ؛ از آن وقت که <span class=\"hlight\">:</span> <br />زآنگه که تو را بر من مسکین نظر است <br />آثارم ازآفتاب مشهورتر است .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">هر آنگه </span> ؛ هرزمان . هر وقت <span class=\"hlight\">:</span> <br />هر آنگه که خوری می خوش آنگه است <br />خاصه که گل و یاسمن دمید.<br /> <font color=\"Red\">رودکی .</font><br />هر آنگه که روز تو اندرگذشت <br />نهاده همی باد گردد بدشت .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">همانگه </span> ؛ در همان وقت <span class=\"hlight\">:</span> <br />همانگه ز دینار بردی هزار<br />ز گنج جهاندیده ٔ نامدار.<br /> <font color=\"Red\">فردوسی .</font><BR>۩ فوراً. فی الفور. درساعت <span class=\"hlight\">:</span> <br />خشمش آمد و همانگه گفت ویک <br />خواست کو را برکند از دیده کیک .<br /> <font color=\"Red\">رودکی .</font><br />یکی گرز زد ترک را بر هباک <br />کز اسب اندر آمد همانگه بخاک .<br /><font color=\"Red\">فردوسی (از فرهنگ اسدی ).</font><br /></font></div>'),
(2488, 'آنگهی', '<span class=\"hlight\">آنگهی .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (ق مرکب ) آن زمان . آن وقت . در آن حال <span class=\"hlight\">:</span> <br />بهرام، آنگهی که بخشم افتی <br />بر گاه اورمزد دُرافشانی .<br /> <font color=\"Red\">دقیقی .</font><br />کشیدندشان خسته و بسته زار<br />بجان خواستند آنگهی زینهار.<br /> <font color=\"Red\">فردوسی .</font><br />سوی زال کرد آنگهی سام روی <br />که داد و دهش گیرد آرامجوی .<br /> <font color=\"Red\">فردوسی .</font><br />نبشت آنگهی پاسخ نامه باز<br />به نزدیک فرزند گردنفراز.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> پس . سپس . بعد. بعد از آن <span class=\"hlight\">:</span> <br />بخواند آنگهی زرگر دند را<br />ز همسایگانان تنی چند را. <br /> <font color=\"Red\">ابوشکور.</font><br />چو این کرده شد چاره ٔ آب ساخت <br />ز دریا برآورد و هامون نواخت <br />بجوی آنگهی آب را راه کرد<br />به فرّ کئی رنج کوتاه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />بزال آنگهی گفت تندی مکن <br />بر اندازه باید که رانی سخُن .<br /> <font color=\"Red\">فردوسی .</font><br />بطوس آنگهی گفت کای هوشمند<br />مر این گفته رابشنو و کار بند.<br /> <font color=\"Red\">فردوسی .</font><br />قوم فرعون همه رادر تک دریا راند<br />آنگهی غرقه کُنَدْشان و نگون گرداند.<br /> <font color=\"Red\">منوچهری .</font><br />ترک بدی مقدمه ٔ فعل نیکی است <br />کاوّل علاج واجب بیمار احتماست <br />خود نفی باطل اوّل لفظ شهادت است <br />کاوّل اعوذ وآنگهی الحمد و والضحی است .<br /> <font color=\"Red\">کمال اسماعیل .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">وانگهی </span> ؛بعلاوه . از این گذشته .<br /></font></div>'),
(2489, 'آنگونه', '<span class=\"hlight\">آنگونه .</span> <font color=\"DarkGreen\"><b>[ گو ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (صفت + اسم ) بر آنگونه . بدانگونه . بدانسان . بر آنسان <span class=\"hlight\">:</span> <br />بدانگونه آن لشکر نامدار<br />بیامد روارو سوی کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />بدانگونه آن سنگ را برگرفت <br />کزو ماند لشکر سراسر شگفت .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2490, 'آنی', '<span class=\"hlight\">آنی .</span> (اِخ ) نام شهر و دژی استوار به ارمینیه، میان خلاط و گنجه .<br /></font></div>'),
(2491, 'آنی', '<span class=\"hlight\">آنی .</span> (ع ص ) آن . آب بغایت گرم . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> مرد بغایت بردبار.<br /></font></div>'),
(2492, 'آنی', '<span class=\"hlight\">آنی .</span> <font color=\"DarkGreen\"><b>[ نی ی ]</font></b> (ع پسوند) َانی . در بعض کلمات عرب بجای یاء نسبت آید، چون صنعانی، منسوب بصنعاء.<br /></font></div>'),
(2493, 'آنی', '<span class=\"hlight\">آنی .</span> (ص نسبی، ق ) فی الفور. فوری . آناً.<br /></font></div>'),
(2494, 'آنی', '<span class=\"hlight\">آنی .</span> (پسوند) َانی . حرف نسبت است چون یاء: خسروانی . کیانی . کاویانی . پهلوانی، بجای خسروی و کیی و کاوَیی و پهلوی <span class=\"hlight\">:</span> <br />ببخشای بر پهلوانی ّ من <br />بدین بازوی خسروانی ّ من .<br /> <font color=\"Red\">فردوسی .</font><br />برافراشته کاویانی درفش <br />همایون همان خسروانی درفش .<br /> <font color=\"Red\">فردوسی .</font><br />یکی پهلوانی نهادند خوان <br />نشستند بر خون او فرّخان .<br /> <font color=\"Red\">فردوسی .</font><br />کنون تاجت آوردم ای شاه و تخت <br />ببار آمد آن خسروانی درخت .<br /> <font color=\"Red\">فردوسی .</font><br />پیاده بدینسان ز پرده سرای <br />برنجیدت آن خسروانی دو پای .<br /> <font color=\"Red\">فردوسی .</font><br />وز این ریدکان سپهبدپرست <br />وز این باغ و این خسروانی نشست .<br /> <font color=\"Red\">فردوسی .</font><br />تنش را یکی پهلوانی قبای <br />بپوشید و از کوه بگذارْد پای .<br /> <font color=\"Red\">فردوسی .</font><br />گشاده زبان و جوانیت هست <br />سخن گفتن پهلوانیت هست .<br /> <font color=\"Red\">فردوسی .</font><br />ترا گاه بزم است و آوای رود<br />کشیدن ْ می و پهلوانی سرود.<br /> <font color=\"Red\">فردوسی .</font><br />دو لب پر ز خنده دو رخ پر ز شرم <br />کیانی زبان پر ز گفتار نرم .<br /> <font color=\"Red\">فردوسی .</font><br />بدان تیز زهر آبگون خنجرش <br />همی کرد چاک آن کیانی برش .<br /> <font color=\"Red\">فردوسی .</font><br />بزور کیانی بیازید دست <br />جهانسوز مار از جهانجو بجست .<br /> <font color=\"Red\">فردوسی .</font><br />بتندی میان کیانی به بست <br />بر آن باره ٔ شیردل برنشست .<br /> <font color=\"Red\">فردوسی .</font><br />سخنهای منظوم شاعر شنیدن <br />بود سیرت و شیمت خسروانی .<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(2495, 'آنی بال', '<span class=\"hlight\">آنی بال .</span> (اِخ ) هانی بال . نام سردار مشهور قرطاجنه . (<span class=\"hlight\" dir=\"rtl\">٢٤٧</span> - <span class=\"hlight\" dir=\"rtl\">١٨٢</span> ق . م .). و جنگهای او با دولت روم در تاریخ معروف است .<br /></font></div>'),
(2496, 'آنیت', '<span class=\"hlight\">آنیت .</span> <font color=\"DarkGreen\"><b>[ نی ی َ ]</font></b>(مص جعلی، اِمص ) در تداول عوام، از «آن ِ» فارسی که به صورت جعلی مصدر عرب درآمده، مانند دوئیّت . کیفیتی از حُسن و جز آن که از آن تعبیری نتوان کرد. لطف .<br /></font></div>'),
(2497, 'آنیدن', '<span class=\"hlight\">آنیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (پسوند) َانیدن . چنانکه آندن (َاندن )، پس از مفرد امر حاضر درآید و مصدر را متعدی کند: کنانیدن . خورانیدن . خیزانیدن . گیرانیدن . ایستانیدن . خندانیدن .<br /></font></div>'),
(2498, 'آنیس', '<span class=\"hlight\">آنیس .</span> (از یونانی، اِ) (از یونانی آنی زُن ) انیسون .<br /></font></div>'),
(2499, 'آنیسته', '<span class=\"hlight\">آنیسته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص ) رجوع به آنیسه شود.<br /></font></div>'),
(2500, 'آنیسه', '<span class=\"hlight\">آنیسه .</span> <font color=\"DarkGreen\"><b>[ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (ص ) هر چیز بسته که بدشواری باز شود. به معنی خون بسته ومداد بسته و امثال آن نیز آمده است و آن را آنیسته نیز گویند. (برهان ). دَلَمه . انبسته بر وزن سرگشته نیز نوشته اند و دو صورت از این سه بی شبهه مصحف است .<br /></font></div>'),
(2501, 'آنیلین', '<span class=\"hlight\">آنیلین .</span> (فرانسوی، اِ) ماده ٔ رنگی که از زغال سنگ گیرند.<br /></font></div>'),
(2502, 'آنین', '<span class=\"hlight\">آنین .</span> (اِ) اَنین . نیم خم سفالین و کوچک که دوغ در آن کرده و جنبانند یعنی زنند تا کره ٔ آن جدا شود. تغار. تغارچه . نهره (بزبان آذری ). شیرزنه، و آن خنوری بود که ماست در وی کنند و می جنبانند تا روغن آن گیرند. (از فرهنگ اسدی، خطی ) <span class=\"hlight\">:</span> <br />سبو و ساغر و آنین وغولین <br />حصیر و جای روب و خیم و پالان .<br /> <font color=\"Red\">طیّان .</font><br />بخرم آخر آنین ترا جان پدر<br />پس در او ریزم جغرات و همی جنبانم .<br /> <font color=\"Red\">طیّان .</font><br />دوغم ای دوست در آنین تو میخواهم ریخت <br />تا کشم روغن از آن دوغ همی جنبانم .<br /> <font color=\"Red\">طیّان .</font><br />دوغم اکنون که در آنین تو شد<br />بزنم تا بکشم روغن از او.<br /> <font color=\"Red\">طیّان .</font><br /><BR><font color=\"Blue\">◄</font> چوبی که ماست را بدان برهم زنند تا مسکه از دوغ جدا شود. (برهان ). و ظاهراً این معنی دوم مجعول باشد و از بعض امثله ٔ فوق باشتباه افتاده اند.<br /></font></div>'),
(2503, 'آنیه', '<span class=\"hlight\">آنیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) ج ِ اِناء. ظروف . آبدانها.<br /></font></div>'),
(2504, 'آنیه', '<span class=\"hlight\">آنیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) تأنیث آنی . چیزی بغایت گرم . بغایت گرم .<br /></font></div>'),
(2505, 'آه', '<span class=\"hlight\">آه .</span> (اِخ ) نام قریه ای بناحیه ٔ دماوند، و آبهای معدنی بسیار بدانجا هست .<br /></font></div>'),
(2506, 'آه', '<span class=\"hlight\">آه .</span> (صوت، اِ) آوازیست که برای نمودن درد و رنج و الم و اسف و تلهف و اندوه از سینه برآرند. آوَه . آوخ . وای . آخ . اَه . دردا. افسوس . <BR><font color=\"Blue\">◄</font> باد. باد سرد. دم سرد <span class=\"hlight\">:</span> <br />آه از این جور بد، زمانه ٔ شوم <br />همه شادی ّ او غمان آمیغ.<br /> <font color=\"Red\">رودکی .</font><br />چو بهرام گفت آه مردم، ز راه <br />برفتند پویان به نزدیک شاه .<br /> <font color=\"Red\">فردوسی .</font><br />بپیچید از آن پس یکی آه کرد<br />ز نیک و بد اندیشه کوتاه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />از این کار دل تنگ شد شاه را<br />همی هر زمان برکشید آه را.<br /> <font color=\"Red\">فردوسی .</font><br />شغاد از پس زخم او آه کرد<br />تهمتن بر او درد کوتاه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />یکی دشنه زد بر تهیگاه شاه <br />رها شدبزخم اندر، از شاه آه .<br /> <font color=\"Red\">فردوسی .</font><br />نگه کرد افراسیاب آن بدید<br />یکی آه سرد از جگر برکشید.<br /> <font color=\"Red\">فردوسی .</font><br />ابا ناله و آه و با روی زرد<br />به پیش فریدون شد آن نیکمرد.<br /> <font color=\"Red\">فردوسی .</font><br />خروشیدن و ناله و آه بود<br />بهر برزنی ماتم شاه بود.<br /> <font color=\"Red\">فردوسی .</font><br />چو بشنید زوزن، دم اندرکشید<br />یکی آه سرد از جگر برکشید.<br /> <font color=\"Red\">فردوسی .</font><br />چو رستم به نزدیک توران رسید<br />پشیمان شد آه از جگربرکشید.<br /> <font color=\"Red\">فردوسی .</font><br />سیاوش چو رخسارایشان بدید<br />ز دل باز آه دگر برکشید.<br /> <font color=\"Red\">فردوسی .</font><br />مر آن درد را راه چاره ندید<br />بسی آه سرد از جگر برکشید.<br /> <font color=\"Red\">فردوسی .</font><br />بس اشک شکّرین که فروبارم از نیاز<br />بس آه عنبرین که بعمدا برآورم <br />لب را حنوط زآه معنبر کنم چنانک <br />رخ را وضو ز اشک مصفا برآورم .<br /> <font color=\"Red\">خاقانی .</font><br />شب نباشد که آه خاقانی <br />فلک چنبری نمی شکند.<br /> <font color=\"Red\">خاقانی .</font><br />گر بود در ماتمی صد نوحه گر<br />آه صاحب درد را باشد اثر.<br /> <font color=\"Red\">عطار.</font><br />تا ز تحسر مرا نباید گفتن <br />آه که برگل نهاد یار بنفشه .<br /> <font color=\"Red\">رفیعالدین مرزبان فارسی .</font><br />پیرزن نیم شب که آه کند<br />روی هفت آسمان سیاه کند.<br /> <font color=\"Red\">اوحدی .</font><br />آهی کن و زین جای بجه گرد برانگیز<br />کخ کخ کن و برگرد و بدر، برپس ایزار.<br /> <font color=\"Red\">حقیقی صوفی (تحفةالاحباب اوبهی ).</font><br />گفتمش پوشیده رخ مگذر به آه کاتبی <br />گفت هرجا باد باشد شمع را پنهان کنند.<br /> <font color=\"Red\">کاتبی .</font><br />و این کلمه میان فارس و عرب مشترک است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آه در بساط نداشتن </span> ؛ هیچ نداشتن . بالتمام مفلس بودن . فاقد مال و دارائی بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آه در جگر نداشتن (نبودن کسی را)</span> ؛ سخت فقیر و بی چیزبودن <span class=\"hlight\">:</span> <br />آن پیرگشته را که نبد آه در جگر<br />آروغ امتلا زند اکنون ز خوان شکر.<br /><font color=\"Red\">کمال اسماعیل .</font><br /><BR><font color=\"Blue\">◄</font> دم . نفس .<br /></font></div>'),
(2507, 'آه', '<span class=\"hlight\">آه .</span> (ع پسوند) َاه . حرفی است که در آخر بعض کلمات درآید و حکایت از حسرت و تألم و استغاثه و توجعکند. و در این صورت در اول کلمه نیز «وا» درآرند: وادیناه . واحمزتاه . وامحمداه . وااسلاماه . واشریعتاه . واشنعتاه . وافضیحتاه . واحسرتاه . واقِلَّةَ صبراه . واویلاه . و بجای آه گاهی، آ (َا) نیز آید: واحسرتا، چنانکه بجای وا، یا: یاحسرة(تا) علی العباد، و در این کلمات الف را الف ندبه گویند و ها را علامت وقف شمارند.<br /></font></div>'),
(2508, 'آه و دم', '<span class=\"hlight\">آه و دم .</span> <font color=\"DarkGreen\"><b>[ هَُ دَ ]</font></b> (ترکیب عطفی، اِ مرکب ) (از: آه، اسم صوت حاکی حَسرَت + دم، نفس ) آدمی آه است و دم ؛ یعنی مردن آدمی در هر لحظه ممکن است .<br /></font></div>'),
(2509, 'آه و زاری', '<span class=\"hlight\">آه و زاری .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ترکیب عطفی، اِ مرکب ) آه و ناله .<br /></font></div>'),
(2510, 'آه و ناله', '<span class=\"hlight\">آه و ناله .</span> <font color=\"DarkGreen\"><b>[ هَُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ترکیب عطفی، اِ مرکب ) آه و زاری .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آه و ناله کردن از</span> ؛ شکایت کردن از.<br /></font></div>'),
(2511, 'آه و واه', '<span class=\"hlight\">آه و واه .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِ مرکب، ازاتباع ) اسم صوت علامت اعجاب و تحسین و بدیع شمردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آه و واه کردن </span> ؛در تداول زنان، چشم زخم و عین الکمال رسانیدن با گفتن آه و واه .<br /></font></div>'),
(2512, 'آه کشیدن', '<span class=\"hlight\">آه کشیدن .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) برآوردن آه از سینه بر اثر غمی و اندوهی یا دریغ و حسرتی یا غبطه ای و مانند آن <span class=\"hlight\">:</span> <br />از این کاردل تنگ شد شاه را<br />همی هر زمان برکشید آه را.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آه کشیدن برای چیزی </span> ؛ سخت آرزومند آن بودن . آهه . اهّه . تأوّه .<br /></font></div>'),
(2513, 'آهار', '<span class=\"hlight\">آهار.</span> (اِ) چیزی از نشاسته یا کتیرا یا صمغ و یالعاب خطمی و مانند آن که جامه و کاغذ و جز آن را بدان آغارند تا شخ ّ و محکم شود یا صیقل و مهره گیرد. شو. شوی . شوربا. پَت . خورش . آش . آش جامه . پالوده . بَت . آهر. تانه . بخیر. آغار. لعاب . و فعل آن آهاردن و آهاریدن و آهار دادن و آهار کردن و آهار زدن باشد در متعدی . و در لازم آهار شدن و آهار گرفتن <span class=\"hlight\">:</span> <br />سوار بود بر اسبان چو شیر بر سر کوه <br />پیاده جمله بخون داده جامه را آهار.<br /> <font color=\"Red\">عماره یا عنصری .</font><br />در گنج بگشاد و دینار داد<br />روان را بخون دل آهار داد.<br /> <font color=\"Red\">فردوسی .</font><br />چو او <font color=\"DarkGreen\"><b>[رخش ]</font></b> سست گردد پیاده شوم <br />بخون و خوی آهارداده شوم .<br /> <font color=\"Red\">فردوسی .</font><br />بیا تا بکشتی پیاده شویم <br />بخون و خوی آهارداده شویم .<br /> <font color=\"Red\">فردوسی .</font><br />درخشیدن تیغ الماسگون <br />سنانهای آهارداده بخون .<br /> <font color=\"Red\">فردوسی .</font><br />همه بوم و بر زیر نعل اندرون <br />چو کرباس آهارداده بخون .<br /> <font color=\"Red\">فردوسی .</font><br />الماس کرده چنگ را خوش کرده دل نیرنگ را<br />آهار داده سنگ را از کشتن شیران بدم .<br /><font color=\"Red\">لامعی .</font><br />شد خوب به نیکو سخنت دفتر ناخوب <br />دفتر بسخن خوب شود، جامه به آهار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />از این پس چون شد از آهار جسمی <br />مرا در کالبد جانی موقر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />جامه ست مثل طاعت و آهار بر او علم <br />چون جامه نباشد بچه کار آید آهار؟<br /><font color=\"Red\">ناصرخسرو.</font><br />مرا پرس کز مهر او آستینم <br />ز مکرش بخون دل آهار دارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />شخص را پاکی آورد حمام <br />جامه را تازگی دهد آهار.<br /> <font color=\"Red\">نظام قاری .</font><br /> <BR><font color=\"Blue\">◄</font> نام گلی است باساق باریک و تا یک گز ساق آن برشود و گلها برنگهای مختلف دهد، برگ آن پرزدار و مزغّب و شخ و شکننده است و گل و برگ آن بوی و عطر ندارد . <BR><font color=\"Blue\">◄</font> در فرهنگها باین کلمه معنی فولاد جوهردار نیز داده و بیت ذیل را شاهد آورده اند <span class=\"hlight\">:</span> <br />نهاد از کمین هرکه سالار بود<br />عمودش ز پولاد آهار بود.<br /> <font color=\"Red\">اسدی .</font><br />و این مثال برای دعوی رسا نیست . <BR><font color=\"Blue\">◄</font> ونیز معنی طعام بدان داده اند و شاهدی برای آن یافته نشده است و گمان می برم کلمه ٔ خورش که یکی از مترادفات شوی و پت و آهار است منشاء این التباس شده است . و در تأیید معنی طعام برای آهار گفته اند که ناهار مرکب از «نا»ی حرف نفی و آهار به معنی طعام است . واﷲ اعلم .<br /></font></div>'),
(2514, 'آهار', '<span class=\"hlight\">آهار.</span> (اِخ )نام گردنه ای میان شهرستانک و رودبار در ایالت تهران . <BR><font color=\"Blue\">◄</font> نام دره ای در ناحیه ٔ رودبار طهران و نام قریه ای در آن درّه در نزدیک قریه ٔ اوشان، و در این دره معادن سنگ گچ فراوانست . <BR><font color=\"Blue\">◄</font> نام یکی از آب راهه های جاجرود که در اوشان بجاجرود پیوندد.<br /></font></div>'),
(2515, 'آهار زدن', '<span class=\"hlight\">آهار زدن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ ]</font></b> (مص مرکب ) آهاردن .<br /></font></div>'),
(2516, 'آهار کردن', '<span class=\"hlight\">آهار کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) آهاردن .<br /></font></div>'),
(2517, 'آهاردار', '<span class=\"hlight\">آهاردار.</span> (نف مرکب )آهارزده . آهارکرده : کاغذ آهاردار. چلوار آهاردار.<br /></font></div>'),
(2518, 'آهاردن', '<span class=\"hlight\">آهاردن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آهار زدن . آهار کردن .<br /></font></div>'),
(2519, 'آهارمهره', '<span class=\"hlight\">آهارمهره .</span> <font color=\"DarkGreen\"><b>[ م ُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) عمل آهار زدن و سپس با مهره روشن و صیقلی کردن : کاغذ آهارمهره دار. وفعل آن آهارمهره کردن و آهارمهره زدن است . ترزیز.<br /></font></div>'),
(2520, 'آهاریدن', '<span class=\"hlight\">آهاریدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آهاردن . آهار زدن .<br /></font></div>'),
(2521, 'آهازیدن', '<span class=\"hlight\">آهازیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) درفرهنگها این کلمه را به معنی آختن و آهختن و آهیختن و آهنجیدن آورده اند. صاحب برهان قاطع گوید: آهازیده به معنی کشیده باشد خواه قد کشیده باشد و خواه شمشیر کشیده و خواه تنگ اسب و امثال آن، و عمارتهای طولانی را نیز گویند - انتهی . لیکن من شاهد برای این مصدرو نیز مشتقی از آن نیافتم و عدم الوجدان لایدل ....<br /></font></div>'),
(2522, 'آهازیده', '<span class=\"hlight\">آهازیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) رجوع به آهازیدن شود.<br /></font></div>'),
(2523, 'آهال', '<span class=\"hlight\">آهال .</span> (ع اِ) ج ِ اَهل .<br /></font></div>'),
(2524, 'آهان', '<span class=\"hlight\">آهان .</span> (صوت ) در تداول اطفال و زنان، آری . نعم .<br /></font></div>'),
(2525, 'آهای', '<span class=\"hlight\">آهای .</span> (صوت ) در تداول عامّه، حرف ندا و گاه علامت تحذیر است .<br /></font></div>'),
(2526, 'آهبنیابه', '<span class=\"hlight\">آهبنیابه .</span> <font color=\"DarkGreen\"><b>[ هََ ب َن ْ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) خمیازه . آسا. دهان دره . تثاءُب .<br /></font></div>'),
(2527, 'آهبه', '<span class=\"hlight\">آهبه .</span> <font color=\"DarkGreen\"><b>[ هَِ ب َ ]</font></b> (ع اِ) ج ِ اِهاب . پوستهای ناپیراسته .<br /></font></div>'),
(2528, 'آهتن', '<span class=\"hlight\">آهتن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص ) صورتی از آختن و آهختن .<br /></font></div>'),
(2529, 'آهته', '<span class=\"hlight\">آهته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف ) آهِخته .<br /></font></div>'),
(2530, 'آهختن', '<span class=\"hlight\">آهختن .</span> <font color=\"DarkGreen\"><b>[ هَِ ت َ ]</font></b> (مص ) آهیختن . آختن . لنجیدن . آهنجیدن . کشیدن . برکشیدن . بیرون کردن . بیرون آوردن . برآوردن . بیرون کشیدن . تشهیر. سَل ّ <span class=\"hlight\">:</span> <br />ز آهختن تیغها از غلاف <br />کُه ِ قاف را در دل افتاد کاف .<br /> <font color=\"Red\">فردوسی .</font><br />گرش بر فریدون بدی تاختن <br />امانش ندادی به تیغ آختن .<br /> <font color=\"Red\">فردوسی .</font><br />خدنگی که پیکان او ده ستیر<br />ز ترکش برآهخت گُرد دلیر.<br /> <font color=\"Red\">فردوسی .</font><br />طبیب تست حکیم و تو با طبیب حکیم <br />همیشه خنجرت آهخته و کمان بزهی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چو تیر از زخمگه آهخت بیرون <br />نشانه بود و تیر آن هر دو پرخون .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />چهارم درآهخت از آنسان شگفت <br />که هر دو کمانگوشه گوشش گرفت .<br /> <font color=\"Red\">اسدی .</font><br />برآهخت خرطوم فیل از زره <br />بپیچید وچون رشته برزد گره .<br /> <font color=\"Red\">اسدی .</font><br />چو عزمش برآهخت شمشیر بیم <br />بمعجز میان قمر زد دو نیم .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> برآوردن و کشیدن، چنانکه دیوار را <span class=\"hlight\">:</span> <br />وفا پیرامنش آهخته دیوار<br />نه دیواری که کوه نام بردار.<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> بیرون کردن و کشیدن و خلع و سلخ جامه را <span class=\"hlight\">:</span> <br />برآهخت از بر سیمینْش سنجاب <br />بگستردش میان آن گل و آب .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />یک چند کنون لباس بدمهری <br />از دلْت همی بباید آهختن .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> راست کردن . ستیخ کردن . شخ ّ کردن . تیز کردن گوش . براق کردن و انتفاش یال <span class=\"hlight\">:</span> <br />قَوی قَوائم و فربه سرین و چیده میان <br />درازگردن و آهخته گوش و گردشکم .<br /> <font color=\"Red\">سنائی .</font><br />همچون کَشَف بسینه سر اندرکشد اجل <br />آنجا که نیزه ٔ تو برآهخت یال را.<br /> <font color=\"Red\">کمال اسماعیل .</font><br />چو گوش آهخته دارد دیده گوید<br />مگر تیری دو پیکان می نماید.<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> ممدود کردن . امتداد. کشیدن <span class=\"hlight\">:</span> <br />بر او راه ماران شکن بر شکن <br />چو آهخته بر برق <font color=\"DarkGreen\"><b>[ کذا ]</font></b> بیجان رسن .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> تحریک کردن . تهییج کردن . برانگیختن به جنگ و خصومت <span class=\"hlight\">:</span> <br />چو بینم بچهر تو و بخت تو<br />سپاه و کلاه تو و تخت تو<br />چو آهخته شیری که گردد ژیان <br />برآرم بسر کار ساسانیان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> رها، مطلق، گسسته کردن . اطلاق . سر دادن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهختن عنان (ماهار، افسار)</span> ؛ اطلاق آن . رها کردن آن <span class=\"hlight\">:</span> <br />کنون جوئی همی حیلت که گشتی سست و بیطاقت <br />ترا دیدم به برنائی فسار آهخته و لانه .<br /> <font color=\"Red\">کسائی .</font><br />از آنجا سوی قلب توران سپاه <br />گوان زادگان برگرفتند راه <br />بکردار شیران بروز شکار<br />بر آن بادپایان آهخته هار .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> برافراختن <span class=\"hlight\">:</span> <br />چو تنگ اندرآورد با من زمین <br />برآهختم آن گاوسر گرز کین .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font>آهختن پوست ؛ درکشیدن آن . سَلْخ . - <BR><font color=\"Blue\">◄</font> درکشیده شدن پوست . انسلاخ .<br /> <BR><font color=\"Blue\">◄</font> برکشیدن . استوار کردن، چنانکه تنگ را بر ستور و مانند آن <span class=\"hlight\">:</span> <br />یکی تیز کرد از پی جنگ چنگ <br />برآهخت گلرخش را تنگ تنگ .<br /><font color=\"Red\">اسدی .</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2531, 'آهخته', '<span class=\"hlight\">آهخته .</span> <font color=\"DarkGreen\"><b>[ هَِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف ) آهیخته . آخته . آهنجیده . لنجیده . برکشیده . کشیده . بیرون کرده . برآورده . مسلول . مُشهَّر. افراخته . افراشته <span class=\"hlight\">:</span> <br />رزبان برزد سوی رز گامی را<br />غرضی را و مرادی را، کامی را<br />برگرفت از لب رف <font color=\"DarkGreen\"><b>[ آنگه ]</font></b> جامی را<br />بر لب جام نگاریده غلامی را<br />داده در دستش آهخته حسامی را<br />بر دگر دستش جامی ّ و مدامی را.<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> برانگیخته . برافژولیده . تحریض شده <span class=\"hlight\">:</span> <br />بیازم بدین کار ساسانیان <br />چو آهخته شیری که گردد ژیان <br />ز دفتر همه نامشان بِسْتُرَم <br />سر تخت ساسان به پی بسپرم .<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به آهختن شود.<br /></font></div>'),
(2532, 'آهر', '<span class=\"hlight\">آهر.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) آهار، در تمام معنی های آن .<br /></font></div>'),
(2533, 'آهر', '<span class=\"hlight\">آهر.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) نام شهری کوچک است و هوایش سرد است و آبش از رودی که بدانجا منسوب است از جبال اشکنبر برمیخیزد و از عیون و قنوات نیز آب دارد. حاصلش غلّه و اندک میوه بود و مردمش شافعی مذهبند و حقوق دیوانیش به تمغا مقرر است و ولایتش قریب بیست پاره ده بود و قرب پنج هزار دینار متوجه دارد. و از آن ولایت پانزده هزار دینار بر وی دفترثبت است . (نزهةالقلوب ). و این رود و هم این شهر امروز به نام اَهَر مشهور است، و مردم آن شیعی باشند.<br /></font></div>'),
(2534, 'آهرامن', '<span class=\"hlight\">آهرامن .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) آهریمن . اهریمن . آهرمن .<br /></font></div>'),
(2535, 'آهردار', '<span class=\"hlight\">آهردار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (نف مرکب ) آهاردار.<br /></font></div>'),
(2536, 'آهردن', '<span class=\"hlight\">آهردن .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (مص ) آهاردن .<br /></font></div>'),
(2537, 'آهرمن', '<span class=\"hlight\">آهرمن .</span> <font color=\"DarkGreen\"><b>[ هَِ م َ ]</font></b> (اِخ ) اَهرمَن . اهریمن . دیو. مقابل یزدان . فاعل شر. ظلمت <span class=\"hlight\">:</span> <br />آنکه گردون را به دیوان برنهاد و کار بست <br />وآنکجا بودش خجسته مهر، آهرمن گرای .<br /> <font color=\"Red\">دقیقی .</font><br />بروز معرکه بانگشت اگر پدید آید<br />بچشم برکند از دور کیک آهرمن .<br /> <font color=\"Red\">منجیک .</font><br />روانم نباید که آرد منی <br />بد اندیشد و کیش آهرمنی .<br /> <font color=\"Red\">فردوسی .</font><br />گرت دل نه با رای آهرمن است <br />سوی آز منگر که او دشمن است .<br /> <font color=\"Red\">فردوسی .</font><br />به رشک اندر آهرمن بدسگال <br />همی رای زدتا بیاکند یال .<br /> <font color=\"Red\">فردوسی .</font><br />جوانی برآراست <font color=\"DarkGreen\"><b>[ ابلیس ]</font></b> از خویشتن ...<br />بدو<font color=\"DarkGreen\"><b>[ بضحاک ]</font></b> گفت اگر شاه را درخورم <br />یکی نامور پاک خوالیگرم ...<br />فراوان نبود آن زمان پرورش <br />که کمتر بد از کشتنیها خورش <br />جز از رستنیها نخوردند چیز...<br />پس آهرمن بدکنش رای کرد<br />بدل کشتن جانورجای کرد.<br /> <font color=\"Red\">فردوسی .</font><br />گر این دژ <font color=\"DarkGreen\"><b>[ ... بهمن ]</font></b> برو بوم آهرمن است <br />جهان آفرین را بدل دشمن است <br />به فرّ و بفرمان یزدان پاک <br />سرش را زابر اندر آرم بخاک .<br /> <font color=\"Red\">فردوسی .</font><br />چه بندی دل اندر سرای سپنج <br />که هرگز نداند بهی را ز رنج <br />زمانی چو آهرمن آید بجنگ <br />زمانی عروسی پر از بوی و رنگ .<br /> <font color=\"Red\">فردوسی .</font><br />خزروان چنین گفت کاین یک تن است <br />نه از آهنست ونه آهرمنست .<br /> <font color=\"Red\">فردوسی .</font><br />همه بند آهرمنی برگشاد <font color=\"DarkGreen\"><b>[ فریدون ]</font></b><br />بیاراست گیتی سراسر بداد.<br /> <font color=\"Red\">فردوسی .</font><br />زمین پر ز جوش و هوا پرخروش <br />هزبر ژیان رابدرّید گوش <br />جهان سربسر گفتی آهرمن است <br />بدامن بر از آستین دشمن است .<br /> <font color=\"Red\">فردوسی .</font><br />چو نزدیکی حصن بهمن رسید <font color=\"DarkGreen\"><b>[ طوس ]</font></b><br />زمین همچو آتش همی بردمید...<br />زمین سربسر گفتی از آتش است <br />هوا دام آهرمن سرکشست .<br /> <font color=\"Red\">فردوسی .</font><br />بس نپاید تا بروشن روی و موی تیره گون <br />مانوی را حجت آهرمن و یزدان کند.<br /> <font color=\"Red\">عنصری .</font><br />ستیزآوری کار آهرمن است <br />ستیزه بپرخاش آبستن است .<br /> <font color=\"Red\">اسدی .</font><br />مگر ناگه کمین آورد بر عفریت سیاره <br />مگر در شب شبیخون کرد بر مریخ آهرمن .<br /> <font color=\"Red\">معزی .</font><br />گرد بادی گر نگردی گرد خاکی هم مگرد<br />مرد یزدان گر نباشی جفت آهرمن مباش .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> ابلیس . شیطان اسلامی <span class=\"hlight\">:</span> <br />گریزنده گشته ست بخل از کَفَش <br />کَفَش قل اعوذ است و بخل آهْرمن .<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> (ص، اِ) بددین . بی دین . کافر <span class=\"hlight\">:</span> <br />چه جوئی همی زین سرای سپنج <br />که آغاز رنج است و فرجام رنج <br />بریزی به خاک ار همه آهنی <br />اگر دین پرستی گر آهرمنی .<br /> <font color=\"Red\">فردوسی .</font><br />شما را ز من هوش و جان در تن است <br />بمن نگرود هرکه آهرمن است .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> میرغضب . جلاد. دژخیم . روزبان <span class=\"hlight\">:</span> <br />بفرمودمی تا سرت را ز تن <br />بکندی بکردار مرغ آهرمن .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2538, 'آهرمنی', '<span class=\"hlight\">آهرمنی .</span> <font color=\"DarkGreen\"><b>[ هَِ م َ ]</font></b> (ص نسبی ) منسوب به آهرمن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کلمات آهرمنی </span> ؛ کلمات زشت و نیز آن کلمات که بجای کلمه های خوب آرند بقصد ایذاء و تخفیف و اهانت، مانند درائیدن و لاییدن به معنی گفتن .ترکیدن، بجای زادن . تمرگیدن، بجای نشستن یا خفتن . کپیدن و کپه ٔ مرگش را گذاشتن، بجای خفتن . کوته کردن، بجای زائیدن بسیار. گوربگور افتادن، بجای مردن . عر زدن، بجای گریه کردن . گورش را گم کردن، بجای رفتن . کوفت یا زهرمار کردن، بجای خوردن . جان بکن، بجای بده . گم شو، بجای برو. خفه شو، بجای مگوی و ساکت شو. خبر مرگت بیاید، بجای چرا دیر آمدی یا چرا دیر آیی .<br /></font></div>'),
(2539, 'آهرمهره', '<span class=\"hlight\">آهرمهره .</span> <font color=\"DarkGreen\"><b>[ هََ م ُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) آهارمهره .<br /></font></div>'),
(2540, 'آهرن', '<span class=\"hlight\">آهرن .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) آهرمن . (برهان ).<br /></font></div>'),
(2541, 'آهرهماردبیره', '<span class=\"hlight\">آهرهماردبیره .</span> <font color=\"DarkGreen\"><b>[ هَُ هََ دَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) دبیری آخرشماری . کتاب اصطبلات . (مفاتیح العلوم خوارزمی ).<br /></font></div>'),
(2542, 'آهرکرده', '<span class=\"hlight\">آهرکرده .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) آهرزده . آهارزده .<br /></font></div>'),
(2543, 'آهریدن', '<span class=\"hlight\">آهریدن .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (مص ) آهار زدن . آهردن .<br /></font></div>'),
(2544, 'آهریمن', '<span class=\"hlight\">آهریمن .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) اهرمن .<br /></font></div>'),
(2545, 'آهریمه', '<span class=\"hlight\">آهریمه .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) آهرمن . (برهان ).<br /></font></div>'),
(2546, 'آهسته', '<span class=\"hlight\">آهسته .</span> <font color=\"DarkGreen\"><b>[ هَِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص، ق ) آرام . بی شرور <span class=\"hlight\">:</span> اوهر، شهرکیست به بر کوه نهاده و با آبهای بسیار، جائی بسیارکشت و مردمانی آهسته . (حدودالعالم ).<br />شتاب گیرد و گرمی بوقت پاداشن <br />صبور گردد و آهسته گاه بادافراه .<br /> <font color=\"Red\">فرخی .</font><br />بس آهسته و چابک و بخردند<br />ز کنعان بامّید بار آمدند.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهسته آهسته </span> ؛ نرم نرم <span class=\"hlight\">:</span> <br />بساغر نقل کرد از خم شراب آهسته آهسته <br />برآمد از پس کوه آفتاب آهسته آهسته .<br /><font color=\"Red\">صائب .</font><br /> <BR><font color=\"Blue\">◄</font> نرم . بارفق . سردماغ . مقابل آشفته <span class=\"hlight\">:</span> <br />گهی آرمده و گه آرغده <br />گهی آشفته و گه آهسته .<br /> <font color=\"Red\">رودکی .</font><br />بدو گفت ما را که شایسته تر<br />چنین گفت آنکس که آهسته تر.<br /> <font color=\"Red\">فردوسی .</font><br />پراندیشه شد شاه یزدان پرست <br />ز خون ریختن دست گردان ببست <br />چو مهر جهانجوی پیوسته شد<br />دل مرد آشفته آهسته شد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> با آوازی که جهر نباشد. یواش . نرم . <BR><font color=\"Blue\">◄</font> آرام . باسکینه . باطمأنینه . رزین . گران سنگ . باوقار. موقر. حازم . محتاط. رکین . متین . مقابل تیز و تند <span class=\"hlight\">:</span> <br />کنون بند فرمای و خواهی بکش <br />مرا دل درست است و آهسته هش .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> حلیم . بردبار. درنگ پیشه <span class=\"hlight\">:</span> <br />چنین گفت موبد به بهرام تیز<br />که خون سربیگناهان مریز<br />چو خواهی که تاج تو ماند بجای <br />مبادی جز آهسته و پاکرای .<br /> <font color=\"Red\">فردوسی .</font><br />ز گردنکشان او همال من است <br />نه چون بنده ٔ بدسگال من است <br />هشیوار و آهسته و بانژاد<br />بسی نام بردار دارد بیاد.<br /> <font color=\"Red\">فردوسی .</font><br />بشب چیزهائی نمایم بخواب <br />که آهستگان را کنم پرشتاب .<br /> <font color=\"Red\">فردوسی .</font><br />کریم است و آزاده و تازه روئی <br />جوان است و آهسته و باوقاری .<br /><font color=\"Red\">فرخی .</font><br />تو شاه و شهریار و پادشائی <br />بکام خویشتن فرمانروائی <br />چنان باید که تو آهسته باشی <br />همه کار نکو دانسته باشی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />متناسب اعضاء و خوش حرکات و خردمند و آهسته . (چهارمقاله ). <BR><font color=\"Blue\">◄</font> بی آوازی : زن را آهسته بیدار کرد. <BR><font color=\"Blue\">◄</font> ساکت و صامت <span class=\"hlight\">:</span> <br />یهودا هم آهسته و خامش است <br />دلم زین جهت بی ره و بی هش است .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> یواش . بی شتاب . بطی ٔ. کند. باتأنی <span class=\"hlight\">:</span> <br />بر شیر از آن شدند بزرگان دین سوار<br />کآهسته تر ز مور گذشتند بر زمین .<br /> <font color=\"Red\">خواجه عماد فقیه .</font><br />ره رو آن نیست که گه تند و گه آهسته رود<br />ره رو آن است که آهسته و پیوسته رود.<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> بنرمی . رفته رفته . یواش یواش . کم کم <span class=\"hlight\">:</span> <br />اول چراغ بودی آهسته شمع گشتی <br />آسان فرا گرفتم در خرمن اوفتادی .<br /> <font color=\"Red\">سعدی .</font><br />گرچه آهسته خر همی رانی <br />هم بجائی رسی چو میدانی .<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> نرم . برِفْق <span class=\"hlight\">:</span> <br />زنهار قدم به خاک آهسته نهی <br />کآن مردمک چشم نگاری بوده ست .<br /> <font color=\"Red\">خیام .</font><br /><BR><font color=\"Blue\">◄</font> (صوت ) آهسته ! آرام گوی ! آرام رو! مَهْلاً!<br /></font></div>'),
(2547, 'آهسته خوی', '<span class=\"hlight\">آهسته خوی .</span> <font color=\"DarkGreen\"><b>[ هَِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) آرام <span class=\"hlight\">:</span> <br />هم آهوفغند است و هم تیزتک <br />هم آهسته خوی است و هم تیزگام .<br /><font color=\"Red\">فرالاوی .</font><br /></font></div>'),
(2548, 'آهسته خویی', '<span class=\"hlight\">آهسته خویی .</span> <font color=\"DarkGreen\"><b>[ هَِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) چگونگی و حال آهسته خوی .<br /></font></div>'),
(2549, 'آهسته رای', '<span class=\"hlight\">آهسته رای .</span> <font color=\"DarkGreen\"><b>[ هَِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) محتاط. باحزم . <BR><font color=\"Blue\">◄</font> دانا. <BR><font color=\"Blue\">◄</font> با رای رزین .<br /></font></div>'),
(2550, 'آهسته رایی', '<span class=\"hlight\">آهسته رایی .</span> <font color=\"DarkGreen\"><b>[ هَِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ]</font></b> (حامص مرکب ) چگونگی و صفت آهسته رای . رزانت رای .<br /></font></div>'),
(2551, 'آهسته رو', '<span class=\"hlight\">آهسته رو.</span><font color=\"DarkGreen\"><b>[ هَِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رُو ]</font></b> (نف مرکب ) مقابل تندرو.<br /></font></div>'),
(2552, 'آهسته کار', '<span class=\"hlight\">آهسته کار.</span> <font color=\"DarkGreen\"><b>[ هَِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) بطی ٔ. کند. دیرجُنْب . کر <span class=\"hlight\">:</span> <br />مگر میرفت استاد مهینه <br />خری میبرد بارش آبگینه <br />یکی گفتش که بس آهسته کاری <br />بدین آهستگی بر خر چه داری <br />چه دارم، گفت دل پرپیچ دارم <br />اگر این خر بیفتد هیچ دارم .<br /><font color=\"Red\">عطار.</font><br /><BR><font color=\"Blue\">◄</font> متأنی . درنگی . نرم .<br /></font></div>'),
(2553, 'آهسته کاری', '<span class=\"hlight\">آهسته کاری .</span> <font color=\"DarkGreen\"><b>[ هَِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) چگونگی و صفت آهسته کار. بطوء. کندی . <BR><font color=\"Blue\">◄</font> تأنی . نرمی . آرامی .<br /></font></div>'),
(2554, 'آهستگی', '<span class=\"hlight\">آهستگی .</span> <font color=\"DarkGreen\"><b>[ هَِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص ) بطوء. آهسته کاری . دیرجنبی . کیار. کندی . سستی . اِتّآد <span class=\"hlight\">:</span> <br />همی دیر شد سوده آن بستگی <br />سبک شد دل بسته زآهستگی .<br /> <font color=\"Red\">فردوسی .</font><br />مگر میرفت استاد مهینه <br />خری میبرد بارش آبگینه <br />یکی گفتش که بس آهسته کاری <br />بدین آهستگی بر خر چه داری <br />چه دارم، گفت دل پرپیچ دارم <br />اگر این خر بیفتد هیچ دارم .<br /> <font color=\"Red\">عطار.</font><br /> <BR><font color=\"Blue\">◄</font> درنگ . تأنی . انات . اون . هون . (دهار). مقابل تیزی و شتاب و عجله : تهور و تیزی کرد و پیش آن لشکر بازشد و هرچه محمدبن هرون آهستگی فرمود تعجیل کرد. (تاریخ طبرستان ). <BR><font color=\"Blue\">◄</font> رفق . ملایمت . مدارات . آرامی . نرمی . مساهله . مهل . مقابل خرق و خشونت <span class=\"hlight\">:</span> <br />ستون بزرگیست آهستگی <br />همان بخشش و داد و شایستگی .<br /> <font color=\"Red\">فردوسی .</font><br />بود رسم و آئین مرد دلیر<br />که آرد به آهستگی شیر زیر.<br /> <font color=\"Red\">فردوسی .</font><br />جم اندیشه از دل فراموش کرد<br />سه جام می از پیش نان نوش کرد<br />ز دادار پس یاد کردن گرفت <br />به آهستگی رای خوردن گرفت .<br /> <font color=\"Red\">فردوسی .</font><br />خجسته بر و بوم پیوستگی <br />به آهستگی هم بشایستگی .<br /> <font color=\"Red\">فردوسی .</font><br />بیمار کجا گردد از قوت او ساقط<br />دانی که بیک ساعت کارش نشود کاری <br />... آهستگیی باید آنجا و مدارائی <br />صد گونه عمل کردن صد گونه پرستاری .<br /> <font color=\"Red\">منوچهری .</font><br />بلکه فواید آن را به آهستگی در طبع جای دهد. (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> رزانت . (زمخشری ). سکینه . هون . (ادیب نطنزی ) <span class=\"hlight\">:</span> <br />پس پرده ٔ قیصر <font color=\"DarkGreen\"><b>[ بزمان لهراسب ]</font></b> آن روزگار<br />سه دختر بد اندر جهان نامدار<br />ببالا ودیدار و آهستگی <br />به رای و بشرم و بشایستگی .<br /> <font color=\"Red\">فردوسی .</font><br />ز هرمز همی بینم آهستگی <br />خردمندی و شرم و شایستگی .<br /> <font color=\"Red\">فردوسی .</font><br />دگر گفت کز ما چه نیکوتر است <br />که بر دانش بخردان افسر است <br />چنین داد پاسخ که آهستگی <br />کریمی ّ و رادی ّ و شایستگی .<br /> <font color=\"Red\">فردوسی .</font><br />بگنج و بزرگی ّ و شایستگی <br />به آهستگی هم ببایستگی <br />نه بینی بمانند او در زمان ...<br /> <font color=\"Red\">فردوسی .</font><br />از او جز بزرگی ّ وآهستگی <br />خردمندی و شرم و شایستگی <br />نگه کرد بیدار و چیزی ندید...<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> حلم . بردباری <span class=\"hlight\">:</span> <br />بیابی ز من شرم و آهستگی <br />اگر شرمگن مرد و آهسته ای .<br /> <font color=\"Red\">ناصرخسرو.</font><br />پیر پرآهستگی ّ و حلم بُوَد<br />تو همه پر مکر و زرق و پرحیلی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بعقل ار نه آهستگی کردمی <br />بگفتار خصمش بیازردمی .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(2555, 'آهل', '<span class=\"hlight\">آهل .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص ) آنکه او را زن باشد. <BR><font color=\"Blue\">◄</font> بامردم . باسکنه . آبادان . آبادان بمردم . پرمردم . باکسان . <BR><font color=\"Blue\">◄</font> آبادکننده . (مقدمةالادب زمخشری ).<br /></font></div>'),
(2556, 'آهلات', '<span class=\"hlight\">آهلات .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص، اِ) ج ِ آهله .<br /></font></div>'),
(2557, 'آهله', '<span class=\"hlight\">آهله .</span> <font color=\"DarkGreen\"><b>[ هَِ ل َ ]</font></b> (ع ص ) تأنیث آهل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دار آهله </span> ؛ سرای آبادان . (زمخشری ).<br /></font></div>'),
(2558, 'آهمند', '<span class=\"hlight\">آهمند.</span> <font color=\"DarkGreen\"><b>[ هَُ م َ ]</font></b> (ص مرکب ) شاید مخفف آهومند. مقصر. گناهکار. عاصی . جانی <span class=\"hlight\">:</span> <br />چو جستی کسی با کسی گفتگوی <br />بچیزی که سوگند بودی در اوی <br />ز پولاد سندانی اندر شتاب <br />ببردی چو تفسیده اخگر ز تاب <br />یکی برگ تر زآن درخت به بر<br />نهادی اَبَر دست و سندان زبر<br />کَفَش سوختی گر بدی آهمند<br />و گر راست بودی نکردی گزند.<br /> <font color=\"Red\">اسدی .</font><br />و در فرهنگ اسدی به معنی دروغگو بفریب آمده، و از صاحب فرهنگ منظومه نیز بعض دیگر فرهنگها بیت ذیل را نقل کرده اند <span class=\"hlight\">:</span> <br />آدرخش صاعقه، بدی آسیب <br />آهمند آن دروغگو بفریب .<br />و اینکه بسکون هاء ضبط کرده اند ظاهراً صواب نیست . و رجوع به آهومندشود.<br /></font></div>'),
(2559, 'آهن', '<span class=\"hlight\">آهن .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) (از پهلوی آسین ) گوهری کانی که بندرت خالص و غالباً مخلوط با سایر اجسام یافته میشود، و آن بیش از همه ٔ فلزات محتاج الیه آدمی و در تمام صنایع بکار است و در هر جای حتی در نباتات و آبهای معدنی نیز وجود دارد. حدید <span class=\"hlight\">:</span> <br />نه پادیر باید ترا نه ستون <br />نه دیوار خشت و نه زآهن درا.<br /> <font color=\"Red\">رودکی .</font><br />تا کی کند او خارم تا کی زند او شنگم <br />فرسوده شوم آخر گر آهن و گر سنگم .<br /> <font color=\"Red\">ابوشکور.</font><br />به آهن نگه کن که برّید سنگ <br />نرست آهن از سنگ بی آذرنگ .<br /> <font color=\"Red\">ابوشکور.</font><br />از آبنوس دری اندر او فراشته بود<br />بجای آهن، سیمین همه بش و مسمار.<br /> <font color=\"Red\">ابوالمؤید بلخی .</font><br />آهن، یکی از اجساد صناعت کیمیا و از آن در آن صناعت به مریخ کنایت کنند.(مفاتیح العلوم خوارزمی ).<br />اخگرهم آتش است ولیکن نه چون چراغ <br />سوزن هم آهن است ولیکن نه چون تبر.<br /> <font color=\"Red\">عسجدی .</font><br />همه از آدمیم ما لیکن <br />او گرامی تر است کو داناست <br />همه آهن ز جنس یکدگر است <br />که همه از میانه ٔ خاراست <br />نعل اسبان شد آنچه ریم آهن <br />تیغ شاهان شد آنچه روهیناست .<br /> <font color=\"Red\">مسعودسعد.</font><br />آتش ز آهن آمد و زو گشت آهن آب <br />آهن ز خاره زاد و از او خاره گشت سست .<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهن چینی </span> ؛ ظاهراً آهنی بوده است که از چین می آورده اند، سخت <span class=\"hlight\">:</span> <br />با دشمن دین تا نزنم بازنگردم <br />ور قلعه ٔ او آهن چینی بود و روی .<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهن نر</span> ؛ پولاد.روهینا. مقابل نرم آهن .<br /> <BR><font color=\"Blue\">◄</font> شمشیر <span class=\"hlight\">:</span> <br />پس دری کردم از سنگ و درافزاری <br />که بدو آهن هندی نکند کاری .<br /> <font color=\"Red\">منوچهری .</font><br />بی هنر دان نزد بی دین هم قلم هم تیغ را<br />چون نباشد دین، نباشد کلک و آهن را ثمن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کسی را که جانش به آهن گزم <br />بسی جامه ها در سکاهن رَزَم .<br /> <font color=\"Red\">نظامی .</font><br />سخنهای بدش تعلیم کردند<br />بزر وعده، به آهن بیم کردند.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> مطلق سلاح آهنین از درع و جوشن و خود و رانین و غیره .غرق آهن بودن <span class=\"hlight\">:</span> <br />ور شخص من نخواهی چون تار پرنیان <br />آهن مپوش بر تن چون پرنیان خویش .<br /> <font color=\"Red\">معزی .</font><br /> <BR><font color=\"Blue\">◄</font> زنجیر <span class=\"hlight\">:</span> <br />به آهن ببستند پای قباد<br />ز فرّ و نژادش نکردند یاد.<br /> <font color=\"Red\">فردوسی .</font><br />و به آهن گران وی را ببستند و صوفی سخت درشت در وی پوشانیدند. (تاریخ بیهقی ).<br />ز پا و ز سر آهن انداختش <br />ز منسوج زر خلعتی ساختش .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آهن افسرده کوفتن </span> ؛ آهن سرد کوفتن <span class=\"hlight\">:</span> <br />آهن افسرده میکوبد که جهد<br />با قضای آسمانی می کند.<br /> <font color=\"Red\">سعدی .</font><br /> <span class=\"hlight\">آهن سرد کوفتن </span> ؛ کاری لغو و عبث و بیهوده کردن <span class=\"hlight\">:</span> <br />از این در کآمدی نومید برگرد<br />به بیهوده مکوب این آهن سرد.<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <span class=\"hlight\">دیو از آهن گریختن </span> ؛ سخت از چیزی دوری جستن خواستن <span class=\"hlight\">:</span> <br />ز دست طبع و زبانت چنان گریزد بخل <br />که دیو از آهن و لاحول و لفظ استغفار.<br /><font color=\"Red\">ازرقی .</font><br /></font></div>'),
(2560, 'آهن', '<span class=\"hlight\">آهن .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص ) مال ِ قدیمی و موجود.<br /></font></div>'),
(2561, 'آهن', '<span class=\"hlight\">آهن .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِ) آهون . نقب .<br /></font></div>'),
(2562, 'آهن ایمد', '<span class=\"hlight\">آهن ایمد.</span> <font color=\"DarkGreen\"><b>[اَ ی ْ م َ ]</font></b> سِنه . آماج . سکّه . (السامی فی الاسامی ).<br /></font></div>'),
(2563, 'آهن بر', '<span class=\"hlight\">آهن بر.</span> <font color=\"DarkGreen\"><b>[ هَُ ب ُ ]</font></b> (نف مرکب ) آهُن بُره . نقاب . نقب زن . آهون بُر.<br /></font></div>'),
(2564, 'آهن تاب', '<span class=\"hlight\">آهن تاب .</span><font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ن مف مرکب ) که با آهن تفته گرم شده باشد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب آهن تاب </span> ؛ آبی که آهن تفته در آن افکنند یا فروبرند و در طب بکار است .<br /></font></div>'),
(2565, 'آهن تر', '<span class=\"hlight\">آهن تر.</span> <font color=\"DarkGreen\"><b>[ هََ ن ِ ت َ ]</font></b> (ترکیب وصفی، اِ مرکب ) آهن جوهردار. آهن سبز.<br /></font></div>'),
(2566, 'آهن تن', '<span class=\"hlight\">آهن تن .</span> <font color=\"DarkGreen\"><b>[ هََ ت َ ]</font></b> (ص مرکب ) که تن از آهن دارد <span class=\"hlight\">:</span> <br />خزروان بدو گفت کاین یک تن است <br />نه آهن تن است و نه آهرمن است .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2567, 'آهن جامه', '<span class=\"hlight\">آهن جامه .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) آهنی باشد تنک و بپهنای دو انگشت و بیشتر که تخته های صندوق و جز آن را با یکدیگر پیوندند و بمسمار بدوزند. فش . بش . پش . گام . ضبه .<br /></font></div>'),
(2568, 'آهن جان', '<span class=\"hlight\">آهن جان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) سخت جان . سختی کش .<br /></font></div>'),
(2569, 'آهن جفت', '<span class=\"hlight\">آهن جفت .</span> <font color=\"DarkGreen\"><b>[ هََ ج ُ ]</font></b> (اِ مرکب ) دستگاهی برای شیار کردن زمین کشت را، و آن آهنی است بر بن چوبی پیوسته و بگاوی بسته و چون کشاورز گاو براند آهن به زمین فروشود و بدرازا زمین را شکافد. گاوآهن . ایمر. ایمد. سپار. فدان . آهن شیار. آهن گاو. آهن آماج . آهن خیش . آماج . سنه .<br /></font></div>'),
(2570, 'آهن خای', '<span class=\"hlight\">آهن خای .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (نف مرکب ) کنایه از اسب سرشخ پرزور باشد. (برهان ).<br /></font></div>'),
(2571, 'آهن داغ', '<span class=\"hlight\">آهن داغ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ مرکب ) عمل سوختن جزئی از پوست تن جانور را با آهن تفته برای نشان و علامت یا مداوا و چاره ٔ دردی . کَی ّ. کاویا. <BR><font color=\"Blue\">◄</font> آهنی که برای داغ کردن بکار است . داغینه . <BR><font color=\"Blue\">◄</font> عمل فروبردن آهن تفته در آب . آهن تاب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهن داغ کردن آبی را</span> ؛ آهن تاب کردن آن .<br /></font></div>'),
(2572, 'آهن دل', '<span class=\"hlight\">آهن دل .</span> <font color=\"DarkGreen\"><b>[ هََ دِ ]</font></b> (ص مرکب ) آهنین دل . قسی . قاسی . سنگدل . <BR><font color=\"Blue\">◄</font> شجاع . شیردل <span class=\"hlight\">:</span> <br />مرد که آهن دل و روئین تن است <br />نی زرهش حاجت و نی جوشن است .<br /><font color=\"Red\">امیرخسرو.</font><br /></font></div>'),
(2573, 'آهن دلی', '<span class=\"hlight\">آهن دلی .</span> <font color=\"DarkGreen\"><b>[ هََ دِ ]</font></b> (حامص مرکب ) قسوت . قساوَت . <BR><font color=\"Blue\">◄</font> شکیبائی بیش از حد <span class=\"hlight\">:</span> <br />گفتم آهن دلی کنم چندی <br />ندهم دل بهیچ دلبندی <br />وآنکه را دیده بر دهان تو رفت <br />هرگزش گوش نشنود پندی .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(2574, 'آهن ربا', '<span class=\"hlight\">آهن ربا.</span> <font color=\"DarkGreen\"><b>[ هََ رُ ]</font></b> (نف مرکب، اِ مرکب ) سنگی است که بطبع آهن و فولاد را بخود کشد و جذب کند. آهن کش . مغناطیس . مغنطیس . مغنیاطیس . حجر مغناطیسی . و آن بر دو گونه است، طبیعی که اکسیدآهن مغناطیسی است، و مصنوعی که از قرار دادن آهن یا فولاد در معرض جریان الکتریک به دست آید. فولاد خاصیت مغناطیسی دائمی پیدا میکند و آهن خالص موقتاً دارای این خاصیت میگردد. آهن ربا دارای دو قطب است، شمالی و جنوبی و برای ساختن قطب نما ونیز معالجات طبی بکار است . و در کتب قدیمه گویند که چون آهن ربا را به آب سیر و خیوی روزه دار و خون گوسفند ماده آلایند، خاصیت جذب آن باطل گردد <span class=\"hlight\">:</span> <br />که گر سیر بر سنگ آهن ربای <br />بمالی نیاهنجد آهن ز جای .<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(2575, 'آهن ساز', '<span class=\"hlight\">آهن ساز.</span> <font color=\"DarkGreen\"><b>[هََ ]</font></b> (نف مرکب ) آنکه بخاری و انبر و خاک انداز و حمامهای آهنین و منقل و امثال آن سازد از تنکه ٔ آهن .<br /></font></div>'),
(2576, 'آهن سازی', '<span class=\"hlight\">آهن سازی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) حرفه ٔ آهن ساز. <BR><font color=\"Blue\">◄</font> دکان آهن ساز.<br /></font></div>'),
(2577, 'آهن سای', '<span class=\"hlight\">آهن سای .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ مرکب ) سوهان .<br /></font></div>'),
(2578, 'آهن سلب', '<span class=\"hlight\">آهن سلب .</span> <font color=\"DarkGreen\"><b>[ هََ س َ ل َ ]</font></b> (ص مرکب ) آنکه سلب از آهن دارد <span class=\"hlight\">:</span> <br />جائی که برکشند مصاف از پس مصاف <br />وآهن سلب شوند یلان از پس یلان .<br /><font color=\"Red\">فرخی .</font><br /></font></div>'),
(2579, 'آهن شیار', '<span class=\"hlight\">آهن شیار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ مرکب ) ایمر. خیش . آماج . سنه . آهن آماج . آهن خیش . آهن جفت . سپار.<br /></font></div>'),
(2580, 'آهن نرم', '<span class=\"hlight\">آهن نرم .</span> <font color=\"DarkGreen\"><b>[ هََ ن ِ ن َ ]</font></b> (ترکیب وصفی، اِ مرکب ) نرم آهن . انیث . انیف .<br /></font></div>'),
(2581, 'آهن پایه', '<span class=\"hlight\">آهن پایه .</span><font color=\"DarkGreen\"><b>[ هََ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (اِ مرکب ) آلتی فلزین مرکّب از چهار دیواره که بر آتش نهند و سیخهای کباب بر آن گردانند بریان کردن را. <BR><font color=\"Blue\">◄</font> بعض فرهنگها بدان معنی دهن دره و خمیازه داده اند. رجوع به آهبنیابه شود.<br /></font></div>'),
(2582, 'آهن پوش', '<span class=\"hlight\">آهن پوش .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ن مف مرکب ) آهن پوشیده . پوشیده ٔ به آهن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهن پوش کردن شیروانی </span> ؛ پوشیدن آن به تنکه ٔ آهن .<br /></font></div>'),
(2583, 'آهن پولاد', '<span class=\"hlight\">آهن پولاد.</span> <font color=\"DarkGreen\"><b>[ هََ ن ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) ذَکر. جراذ. مقابل نرم آهن، اَنیث، اَنیف .<br /></font></div>'),
(2584, 'آهن کرسی', '<span class=\"hlight\">آهن کرسی .</span> <font color=\"DarkGreen\"><b>[ هََ ک ُ ]</font></b> (اِ مرکب ) سندان .<br /></font></div>'),
(2585, 'آهن کش', '<span class=\"hlight\">آهن کش .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب، اِ مرکب ) سنگ آهن ربا. حجر مغناطیس . مغنطیس . مغنیاطیس <span class=\"hlight\">:</span> <br />که کُهْشان همه سنگ آهن کش است <br />دزی تنگ و ره در میان ناخوش است .<br /> <font color=\"Red\">اسدی .</font><br />تو گفتی تنش کوه آهن کش است <br />همان اسبش از باد و از آتش است .<br /> <font color=\"Red\">اسدی .</font><br />دل اعدای او سنگ است لیکن سنگ آهن کش <br />ازآن، پیکان او هرگز نجوید جز دل اعدا.<br /><font color=\"Red\">فرخی .</font><br /></font></div>'),
(2586, 'آهن کشان', '<span class=\"hlight\">آهن کشان .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) جاذب آهن . کشنده ٔ آهن <span class=\"hlight\">:</span> <br />تو ازمغنیاطیس گیر این نشان <br />نه او را کسی کرد آهن کشان .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2587, 'آهن کوب', '<span class=\"hlight\">آهن کوب .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b>(نف مرکب ) آنکه حرفه ٔ او پیوستن آهن شیروانی است .<br /></font></div>'),
(2588, 'آهن کوبی', '<span class=\"hlight\">آهن کوبی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) عمل کوفتن آهن . <BR><font color=\"Blue\">◄</font> کار وشغل آهن کوب . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) دکان آهن کوب .<br /></font></div>'),
(2589, 'آهن گاو', '<span class=\"hlight\">آهن گاو.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ مرکب ) گاوآهن . آهن جفت . ایمر. ایمد. سپار.<br /></font></div>'),
(2590, 'آهن گداز', '<span class=\"hlight\">آهن گداز.</span> <font color=\"DarkGreen\"><b>[ هََ گ ُ ]</font></b> (نف مرکب ) آنکه آهن گدازد <span class=\"hlight\">:</span> <br />بر این روزگاری برآمد براز <font color=\"DarkGreen\"><b>[ ظ: دراز ]</font></b><br />دم آتش و رنج آهن گداز<br />گهرها یک اندر دگر ساختند<br />وزآن آتش تیز بگداختند.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2591, 'آهن گذار', '<span class=\"hlight\">آهن گذار.</span> <font color=\"DarkGreen\"><b>[ هََ گ ُ ]</font></b> (نف مرکب ) که از آهن گذراند تیر و جز آن را. که از آهن گذرد، تیغ و مانند آن <span class=\"hlight\">:</span> <br />شماره سپاه آمدش صدهزار<br />همه شیرمردان آهن گذار.<br /> <font color=\"Red\">فردوسی .</font><br />بگفتش بدین تیغ آهن گذار<br />بکینه برآرم از ایشان دمار.<br /> <font color=\"Red\">فردوسی .</font><br />کجا تیغ و زوبین آهن گذار<br />کجا نیزه و گرزه ٔ گاوسار؟<br /> <font color=\"Red\">فردوسی .</font><br />همیدون پیاده پس ِ نیزه دار<br />ابا جوشن و تیر آهن گذار.<br /> <font color=\"Red\">فردوسی .</font><br />مرا تیر و پیکان آهن گذار<br />همی بر برهنه نیاید بکار.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2592, 'آهنج', '<span class=\"hlight\">آهنج .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (نف مرخم ) در کلمات مرکبه چون آب آهنج و جان آهنج و دم آهنج و سکارآهنج و عالم آهنج و کفن آهنج و گوشت آهنج و معده آهنج، به معنی آهنجنده یعنی برآورنده و برکننده و بیرون کننده و برکشنده است <span class=\"hlight\">:</span> <br />آفریده مردمان مر رنج را<br />پیشه کرده رنج جان آهنج را.<br /> <font color=\"Red\">رودکی .</font><br />آفرین بادا برآن شمشیر جان آهنج تو.<br /> <font color=\"Red\">قطران .</font><br />بدست راد تو اندر حسام جان آهنج <br />بدان صفت که بود در میان بحر نهنگ .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />که آن ترک در جنگ نر اژدهاست <br />دم آهنج و در کینه ابر بلاست .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت کای مردم بی بها<br />ببین آن دم آهنج نر اژدها.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت شنگل که ما را بلاست <br />که بر بوم ما بر یکی اژدهاست <br />بخشکی ّ و دریا همی بگذرد<br />نهنگ دم آهنج را بشکرد.<br /> <font color=\"Red\">فردوسی .</font><br />شه عالم آهنج گیتی نورد<br />در آن خاک یک ماه کرد آبخورد.<br /> <font color=\"Red\">نظامی .</font><br />گر ز حبس باد قولنجت کند<br />چارمیخ معده آهنجت کند.<br /> <font color=\"Red\">؟</font><br />الکُلاّب ؛ سکارآهنج . النباش ؛ کفن آهنج . المنشال ؛ گوشت آهنج . (دهار). <BR><font color=\"Blue\">◄</font> (اِ) آهنگ . عزم . اراده . قصد.<br /></font></div>'),
(2593, 'آهنجان', '<span class=\"hlight\">آهنجان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (نف، ق ) در حال آهنجیدن .<br /></font></div>'),
(2594, 'آهنجنده', '<span class=\"hlight\">آهنجنده .</span> <font color=\"DarkGreen\"><b>[ هََ ج َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) برکشنده . بیرون کشنده . <BR><font color=\"Blue\">◄</font> برکننده . <BR><font color=\"Blue\">◄</font> جاذب .<br /></font></div>'),
(2595, 'آهنجه', '<span class=\"hlight\">آهنجه .</span> <font color=\"DarkGreen\"><b>[ هََ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ ]</font></b> (اِ) ریسمانی که جولاهان در آخر کار بندند و بر سقف خانه استوار کنند. (السامی فی الاسامی ). هو الرسن الذی یجر به الغزل حالة المسح فی الصخر و غیرها. (فرهنگ شعوری، از مشکلات ) <span class=\"hlight\">:</span> <br />ز تشریف صاحب بگویم که من <br />بفریادم از صاحب مخزنش <br />تو خود حله برگیر بر قد حور<br />ببغداد خلد برین معدنش <br />ز آغاز جبریل آهنجه کار<br />بفرجام ادریس ما کوزنش .<br /> <font color=\"Red\">اثیر اخسیکتی .</font><br /><BR><font color=\"Blue\">◄</font> پهناکش . محبره .<br /></font></div>'),
(2596, 'آهنجیدن', '<span class=\"hlight\">آهنجیدن .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (مص )بیرون کردن . بدر آوردن . کشیدن . لنجیدن <span class=\"hlight\">:</span> <br />گفت فردا نشتر آرم پیش تو<br />خود بیاهنجم ستیم از ریش تو.<br /> <font color=\"Red\">رودکی .</font><br />بگویم چه گوید چهارند یاران <br />بیاهنجم از مغز تیره بخارش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چونکه آن گه گه سرشک افشاند این دایم گهر<br />چونکه گه گه آن بخار آهنجد این دایم روان .<br /> <font color=\"Red\">شرف شفروه .</font><br /> <BR><font color=\"Blue\">◄</font> کندن . برکندن <span class=\"hlight\">:</span> <br />باز کز دست تو پرّد نه شگفت ار بهوا<br />بدو چنگال ز سیمرغ بیاهنجد بال .<br /> <font color=\"Red\">فرخی .</font><br />خوب گفتن پیشه کن با هر کسی <br />کاین برون آهنجد از دل بیخ کین .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> برکردن . برکشیدن، چنانکه جامه را از تن <span class=\"hlight\">:</span> <br />کمان بفکن از دست و ببر بیان <br />بیاهنج و بگشای بند از میان .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> آختن . آهختن . آهیختن . سَل ّ. برکشیدن، چنانکه شمشیر و مانند آن . کشیدن . تشهیر <span class=\"hlight\">:</span> <br />چون جام بکف گیری از زر بشود قدر<br />چون تیغ برآهنجی از خون برود هین .<br /> <font color=\"Red\">فرخی .</font><br />چون برآهنجی شمشیر و فروپوشی درع <br />پشت و روی سپهی اصل و فروع ظفری .<br /> <font color=\"Red\">فرخی .</font><br />کیست سلطان آنکه هست اندر نفاذ حکم او<br />خنجرآهنجانْش بحری ناوک اندازان بَری .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> جذب کردن <span class=\"hlight\">:</span> <br />که گر سیر بر سنگ آهن ربای <br />بمالی نیاهنجد آهن ز جای .<br /> <font color=\"Red\">اسدی .</font><br />دل پرمهر برآهنجد از تن <br />بسان سنگ مغناطیس آهن .<br /> <font color=\"Red\">(ویس و رامین ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">درآهنجیدن </span> ؛ درکشیدن، چنانکه گوشت را بسیخ <span class=\"hlight\">:</span> <br />پس آنگه پیش ویرو کس فرستاد<br />بخواند و کرد او را یک بیک یاد<br />بفرمودش که خواهر را بفرهنج <br />بشفشاهنگ فرهنگش درآهنج .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />و در فرهنگها معنی نوشیدن و پوشیدن و گستردن و انداختن و افکندن نیز بکلمه داده اند. و در معنی آن آمیختن نیز نوشته اند، و آن مصحف آهیختن است و نیز معنی فریس و چنبر و خلال در فرهنگها برای کلمه ٔ آهنج آمده است .<br /></font></div>'),
(2597, 'آهنجیده', '<span class=\"hlight\">آهنجیده .</span> <font color=\"DarkGreen\"><b>[ هََ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) بیرون کرده . برکشیده . مسلول . مشهر. آخته . آهیخته . آهخته . <BR><font color=\"Blue\">◄</font> مسلوب . برکنده . <BR><font color=\"Blue\">◄</font> مجذوب .<br /></font></div>'),
(2598, 'آهنوخوشی', '<span class=\"hlight\">آهنوخوشی .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (ص، اِ) اَهْنوخُشی . پیشه ور. اهل صنعت . یکی از طبقات چهارگانه ای که جمشید مردمان را بدان بخش کرد <span class=\"hlight\">:</span> <br />چهارم که خوانند اَهنوخوشی <br />همان دست ورزان با سرکشی <br />کجا کارشان همگنان پیشه بود<br />روانْشان همیشه پراندیشه بود.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2599, 'آهنود', '<span class=\"hlight\">آهنود.</span> <font color=\"DarkGreen\"><b>[ ن ُ وَ ]</font></b> (اِ) اَهنُوَد. نام روز اول از خمسه ٔ مسترقه . <BR><font color=\"Blue\">◄</font> (اِخ ) نام گاتهای اول از پنج گاتها.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2600, 'آهنگ', '<span class=\"hlight\">آهنگ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) قصد. عزم . عزیمت . عمد. (ادیب نطنزی ). تعمد. نیت . بسیج . تأمیم . استواء. اندیشه .توجه به . برفتن بسوی . حرد. نحو. اراده <span class=\"hlight\">:</span> <br />خسرو غازی آهنگ بخارا دارد<br />زده از غزنین تا جیحون تاژ و خرگاه .<br /> <font color=\"Red\">بهرامی .</font><br />بد گشت چرخ با من بیچاره <br />وآهنگ جنگ دارد و پتیاره .<br /> <font color=\"Red\">کسائی .</font><br />نوروز و گل و نبید چون زنگ <br />ما شادو بسبزه کرده آهنگ .<br /> <font color=\"Red\">عماره .</font><br />گرفتی ز کردار گیتی شتاب <br />چو شب تیره شد کرد آهنگ خواب .<br /> <font color=\"Red\">فردوسی .</font><br />به بیداد جوئی همی جنگ من <br />چنین با سپه کردن آهنگ من .<br /> <font color=\"Red\">فردوسی .</font><br />بیفشرد ران رخش را تیز کرد <font color=\"DarkGreen\"><b>[ رستم ]</font></b><br />برآشفت و آهنگ آویز کرد.<br /> <font color=\"Red\">فردوسی .</font><br />وزآن پس که او <font color=\"DarkGreen\"><b>[ کاوس ]</font></b> شد بهاماوران <br />ببستند پایش به بند گران <br />کس آهنگ آن تخت شاهی نکرد<br />جز از گرم و تیمار ایشان نخورد.<br /> <font color=\"Red\">فردوسی .</font><br />ولیکن چو رای تو با جنگ نیست <br />مرا نیز با جنگ آهنگ نیست .<br /> <font color=\"Red\">فردوسی .</font><br />ور ایدون که رایت جز از جنگ نیست <br />بخوبی ّ و پیوندت آهنگ نیست .<br /> <font color=\"Red\">فردوسی .</font><br />تن آسان بدی شادو پیروزبخت <br />چرا کردی آهنگ این تاج و تخت ؟<br /> <font color=\"Red\">فردوسی .</font><br />همه آشتی گردد این جنگ ما<br />بدین رزمگه کردن آهنگ ما.<br /> <font color=\"Red\">فردوسی .</font><br />بدان حد کشان بود نیرو بجای <br />سوی گوشت کردند آهنگ و رای .<br /> <font color=\"Red\">فردوسی .</font><br />بلند آسمان را که فرسنگ نیست <br />کسی را بدو راه آهنگ نیست .<br /> <font color=\"Red\">فردوسی .</font><br />همان ماده <font color=\"DarkGreen\"><b>[ شیر ]</font></b> آهنگ بهرام کرد<br />بغرید و چنگش باندام کرد.<br /> <font color=\"Red\">فردوسی .</font><br />یکی بانگ برزد بدان نره شیر<br />چو آهنگ اوکرد شیر دلیر<br />ز بیشه بیک سو جهانید اسب <br />برافروخت برسان آذرگشسب .<br /> <font color=\"Red\">فردوسی .</font><br />چو هنگام فرهنگ باشد ترا<br />بدانائی آهنگ باشد ترا<br />بایوان نمانم که بازی کنی <br />ببازی چنین سرفرازی کنی .<br /> <font color=\"Red\">فردوسی .</font><br />کنون از خردمندی اردشیر<br />سخن بشنو و یک بیک یاد گیر<br />هم از داد و آئین و فرهنگ اوی <br />بنیکی بهرجای آهنگ اوی .<br /> <font color=\"Red\">فردوسی .</font><br />بخوردند و کردند آهنگ خواب <br />بسی مار پیچان برآمد ز آب .<br /> <font color=\"Red\">فردوسی .</font><br />بسوگ اندر آهنگ شادی کنم <br />نه از پارسائی ّ و رادی کنم .<br /> <font color=\"Red\">فردوسی .</font><br />جهاندار <font color=\"DarkGreen\"><b>[ یزدگرد ]</font></b> چون کرد آهنگ مرو<br />بماهوی سوری کنارنگ مرو<br />یکی نامه بنوشت، با درد و خشم <br />پر از آرزو دل، پر از آب چشم .<br /> <font color=\"Red\">فردوسی .</font><br />چو آهنگ میدان کند در نبرد<br />سر نرّه دیوان برآرد بگرد.<br /> <font color=\"Red\">فردوسی .</font><br />دگرگونه آهنگ بدکامه کرد<br />به پیروز خسرو یکی نامه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />و از آنجایگه شد سوی جنگ کرم <br />سپاهش همه کرده آهنگ کرم .<br /> <font color=\"Red\">فردوسی .</font><br />بجوشید و رخسارگان کرد زرد<br />بدرد دل آهنگ آورد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />ز عشق بنده ٔ رومی ّو خادم زنگی <br />سوی عنا و بلا چون همی کنی آهنگ ؟<br /> <font color=\"Red\">عنصری .</font><br />شیر بنیزه درآمد و قوت کرد تا نیزه بشکست و آهنگ امیر کرد. (تاریخ بیهقی ).<br />اگر کوچکم کار مردان کنم <br />ببینی چو آهنگ میدان کنم ...<br /> <font color=\"Red\">اسدی .</font><br />دگر ره شد آهنگ آویز کرد<br />برآورد گرد اسب را تیز کرد.<br /> <font color=\"Red\">اسدی .</font><br />نایدْش بچنگ آنکه سوی وی کند آهنگ <br />آن نیز که دارد شود از چنگش کوتاه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کنون که کردی شاها سوی هزاردرخت <br />بشادکامی و پیروزی و نشاط آهنگ .<br /><font color=\"Red\">مسعودسعد.</font><br />ماری دید در گردن همای پیچیده و سرش درآویخته و آهنگ آن میکرد که همای را بگزد. (نوروزنامه ). پس بترسیدند عظیم، و آهنگ آن کردند که بازگردند. (مجمل التواریخ ). و چون سر سال بود با هزار مرد آهنگ راه کرد. (مجمل التواریخ ).<br />مرا با ملک طاقت جنگ نیست <br />بصلح ویم نیز آهنگ نیست .<br /> <font color=\"Red\">آتسزبن قطب الدین محمد.</font><br />سوزنی تیز درگرفته بچنگ <br />کرد زی خایه های خویش آهنگ .<br /> <font color=\"Red\">سنائی .</font><br />چو آهنگ رفتن کند جان پاک <br />چه بر تخت مردن چه بر روی خاک .<br /> <font color=\"Red\">سعدی .</font><br />خشکسالی در اسکندریه پدید آمده بود. در چنین سالی محتشمی ... نعمت بیکران داشت تنگدستان را زر و سیم دادی ... طایفه ٔ درویشان از جور فاقه بجان آمده بودند... آهنگ دعوت او کردند. (گلستان ). آورده اند که سپاه دشمن بیقیاس بود و اینان اندک و جماعتی آهنگ گریز کردند. (گلستان ). ما در این حالت که دو هندو از پس سنگی سر برآوردند و آهنگ قتال ما کردند. (گلستان ).<br />گر آید گل زبانگ بلبلان تنگ <br />مگر کرکس کند سوی وی آهنگ .<br /> <font color=\"Red\">امیرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> مقصد. مقصود. راه . سبیل <span class=\"hlight\">:</span> <br />بسا نامداران که در جنگ من <br />بدادند جان را بر آهنگ من .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> قصد جان . سوء قصد <span class=\"hlight\">:</span> <br />جهان ننگ دارد همی زآن پسر<br />که آهنگ دارد بجان پدر.<br /> <font color=\"Red\">دقیقی .</font><br />جهاندار گفتا که اینت پسر<br />که آهنگ دارد بجان پدر.<br /> <font color=\"Red\">فردوسی .</font><br />چون پَنْد فرومایه سوی جوژه گراید<br />شاهین ستنبه به تذروان کند آهنگ .<br /> <font color=\"Red\">جلاب بخاری .</font><br />فلک بین چه ظلم آشکارا کند<br />که اسکندر آهنگ دارا کند.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> حمله . صولت . صیال <span class=\"hlight\">:</span> <br />بدو <font color=\"DarkGreen\"><b>[ برستم ]</font></b> گفت پولادوند ای دلیر<br />جهاندیده و نامبردار شیر...<br />نگه کن کنون آتش جنگ من <br />کمند و دل و زور و آهنگ من .<br /> <font color=\"Red\">فردوسی .</font><br />تو دانی که شاهی دل و چنگ من <br />بجنگ اندرون زور و آهنگ من .<br /> <font color=\"Red\">فردوسی .</font><br />بکردار شیر است آهنگ اوی <br />نه پیچد کسی گردن از چنگ اوی .<br /> <font color=\"Red\">فردوسی .</font><br />تو آهنگ کردی بدیشان نخست <br />کسی با تو پیکار و کینه نجست .<br /> <font color=\"Red\">فردوسی .</font><br />اگر بچه ٔ شیر ناخورده شیر<br />بپوشد کسی در میان حریر...<br />بگوهر شود باز چون شد بزرگ <br />نترسد ز آهنگ پیل سترگ .<br /> <font color=\"Red\">فردوسی .</font><br />که جز مرگ را کس ز مادر نزاد<br />ز دهقان و تازی ّ و رومی نژاد<br />دو لشکر نظاره بر این جنگ ما<br />بدین گرز و شمشیر و آهنگ ما.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> سیما. قیافه . ملامح <span class=\"hlight\">:</span> <br />یکی شارسانست آن چون بهشت <br />که گوئی نه از خاک دارد سرشت <br />نبینی همی اندر ایوان و خان <br />مگر پوشش او همه استخوان <br />بر ایوانها جنگ افراسیاب <br />نگاریده روشنتر از آفتاب <br />همان چهر کیخسروجنگجوی <br />بزرگی ّ و مردی ّ و آهنگ اوی <br />بر آن استخوانها نگاریده پاک <br />نبینی بشهر اندرون گرد و خاک .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نوا. آواز. لحن صوت . راه . ره . پرده . آوا <span class=\"hlight\">:</span> <br />یک بریشم کم کن از آهنگ جور<br />گر نه با ایّام در یک پرده ای .<br /> <font color=\"Red\">انوری .</font><br />چو زهره وقت صبوح از افق بسازد چنگ <br />زمانه تیز کند ناله ٔ مرا آهنگ .<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />هر شبی زاویه ٔ مدح گهربار تو باد<br />روشن از شمع رخ مطرب ناهیدآهنگ .<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />تو نیکوروش باش تا بدسگال <br />به نقص تو گفتن نیابد مجال <br />چو آهنگ بربط بود مستقیم <br />کی از دست مطرب خورد گوشمال ؟<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />ره بط باز تیزآهنگ میزد<br />برقص کبک شاهین چنگ میزد.<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهنگ حجاز</span> . آهنگ حصار و غیره .<br /> <BR><font color=\"Blue\">◄</font> چَم . فَحوی ̍: از آهنگ گفتار او؛ از لحن، از فحوای کلام او. <BR><font color=\"Blue\">◄</font> سان . گونه . کردار. طرز. روش . صفت . رفتار <span class=\"hlight\">:</span><br />چه بد کردم بتو ای شوخ دلبر<br />که محزونم بدین آهنگ داری ؟<br /> <font color=\"Red\">حکاک .</font><br /> <BR><font color=\"Blue\">◄</font> خمیدگی طاق و سقف ایوان و امثال آن، و آن را باصطلاح بنّایان لنگر خوانند <span class=\"hlight\">:</span> <br />جلالت ار بفلک بر بصدر بنشیند<br />شکسته گردد طاق سپهر را آهنگ .<br /> <font color=\"Red\">رفیع لنبانی (از فرهنگها).</font><br />لکن آهنگ در این بیت به معنی لنگر و خمیدگی نمینماید. <BR><font color=\"Blue\">◄</font> کنار صفه و حوض . (برهان ) <span class=\"hlight\">:</span> <br />ز ناتوانی جائی رسیده ام که مرا<br />مسافتی است ز آهنگ صُفه تا پرده .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />در این بیت معنی آهنگ نیز روشن نیست و به تبعیت فرهنگها نقل شد. <BR><font color=\"Blue\">◄</font> صف مردمان و جانوران . (برهان ). و در بعض فرهنگها بیت ذیل را شاهد این معنی آورده اند <span class=\"hlight\">:</span> <br />زمین پیکر از یکدگر بگسلاند<br />بروز نبرد تو زآهنگ لشکر.<br /> <font color=\"Red\">ازرقی .</font><br />لکن معنی صف در این بیت مناسب نمیآید، و با معنی قصد یا حمله یا آواز بیشتر تناسب دارد. <BR><font color=\"Blue\">◄</font> طویله . شترخان . پاگاه . اخته خانه . <BR><font color=\"Blue\">◄</font> عمارت دراز و طولانی که به عربی ازج و به فارسی اوستان و سغ خوانند. <BR><font color=\"Blue\">◄</font> مقام و مکان حیوان . (برهان ). <BR><font color=\"Blue\">◄</font> توجه . تمایل . یازش . چسبیدن . گرایش <span class=\"hlight\">:</span> <br />بود آهنگ نعمتها همه ساله بسوی تو<br />بود آهنگ کشتیها همه ساله بمعبرها.<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> صوت . آواز <span class=\"hlight\">:</span> <br />چو برزد سر از برج خرچنگ هور<br />جهان شد پر از جنگ و آهنگ و شور.<br /> <font color=\"Red\">فردوسی .</font><br />بانگ و آهنگ او بنصرت و فتح <br />در عراقین و در خراسان باد.<br /> <font color=\"Red\">مسعودسعد.</font><br />وآهنگ در کلمه ٔ مرکبه ٔ هم آهنگ از همین معنی است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به آهنگ برخاستن </span> ؛ شتاب گرفتن <span class=\"hlight\">:</span> سگی بیامد و سر در دیگ کرد و پاره ای گوشت برداشت دهنش بسوخت سبک سر برآورد حلقه ٔ دیگ در گردنش افتاد از سوزش به آهنگ خاست و دیگ را ببرد. (سیاست نامه ٔ منسوب بنظام الملک ).<br /> <BR><font color=\"Blue\">◄</font> (نف مرخم ) در کلمات مرکبه، آهنگ غالباً بمعنای کشنده و کش مخفف کشنده آید.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آب آهنگ </span> ؛ آب کش . ناضح . نازح <span class=\"hlight\">:</span> <br />کرده شیران حضرت تو مرا<br />سرزده همچو گاو آب آهنگ .<br /> <font color=\"Red\">سنائی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بدآهنگ </span> ؛ بدلحن . بدقصد. بدنیت <span class=\"hlight\">:</span> <br />ز بس کینه جوی و بدآهنگ بود<br />فراخای گیتی بر او تنگ بود.<br /> <font color=\"Red\">عنصری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بسترآهنگ </span> ؛ از بستر، جامه ٔ خواب و آهنگ . چادرشب که بر بستر کشند <span class=\"hlight\">:</span> <br />خوشا حال لحاف و بسترآهنگ <br />که میگیرند هر شب در برت تنگ .<br /> <font color=\"Red\">لبیبی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">پالاهنگ </span>؛ از پالا، اسب جنیبت و آهنگ بمعنی مذکور <span class=\"hlight\">:</span> <br />کشی ز روم بخوارزم بت پرستان را<br />فسار در سر و در دست نیز پالاهنگ .<br /> <font color=\"Red\">معزی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">پس آهنگ </span> ؛ از پس، مقابل پیش و آهنگ . آهنی که کفشگران در پس کفش نهند تا بدان کفش را فراخ کنند و قالب را در آن نهند. پاشنه کش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">پیش آهنگ </span> ؛ نهاز. نخراز. تکه . برون . باژن . کراز.پیشهنگ <span class=\"hlight\">:</span> <br />الا یا خیمگی خیمه فروهل <br />که پیشاهنگ بیرون شد ز منزل .<br /> <font color=\"Red\">منوچهری .</font><br />پیشرو. قائد. پیشوا.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خوش آهنگ </span> ؛ خوش لحن . نیکونیّت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">درازآهنگ </span> ؛ بدرازاکشیده . مطول . طویل <span class=\"hlight\">:</span> <br />ز صحرا سیلها برخاست هر سو<br />درازآهنگ و پیچان و زمین کن .<br /> <font color=\"Red\">منوچهری .</font><br />سنت حجت خراسان گیر<br />کارِ کوته مکن درازآهنگ .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دراز آهنگ شد این کار با تو<br />ندانم چون کنم ای یار با تو.<br /> <font color=\"Red\">جامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دژآهنگ </span> ؛ بدقصد. بدنیت . مخوف . تند. صعب <span class=\"hlight\">:</span> <br />بیک خدنگ دژآهنگ جنگ داری تنگ <br />تو بر پلنگ شخ و بر نهنگ دریابار.<br /> <font color=\"Red\">عنصری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دودآهنگ </span> ؛ دودکش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سرآهنگ </span> ؛ قائد. پیشوا <span class=\"hlight\">:</span> <br />نوشته در آن نامه ٔ شهریار<br />سرآهنگ مردان نبرده سوار.<br /> <font color=\"Red\">فردوسی .</font><br />طلایه نگه کن که از خیل کیست <br />سرآهنگ این دوده را نام چیست .<br /> <font color=\"Red\">فردوسی .</font><br />و کلمه ٔ سرهنگ مخفف سرآهنگ است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">شب آهنگ </span> ؛ شِعْری ̍. کاروان کش <span class=\"hlight\">:</span> <br />بگفت این و بر پشت شبرنگ شد<br />بچهره بسان شباهنگ شد.<br /> <font color=\"Red\">فردوسی .</font><br />چویک بهره زآن تیره شب درگذشت <br />شباهنگ بر چرخ گردان بگشت .<br /> <font color=\"Red\">فردوسی .</font><br />شه شرق بر کُه کشیده سرادق <br />رمیده شباهنگ از صبح کاذب .<br /> <font color=\"Red\">حسن متکلم .</font><br />در شب تاریک حیرت کاروان صبح را<br />صد شباهنگ است در یک آه آتشبار من .<br /> <font color=\"Red\">سیف اسفرنگ .</font><BR>۩ مرغ حق گوی . شب آویز.<br />-<BR><font color=\"Blue\">◄</font> بلبل . عندلیب . هزار. هزاردستان <span class=\"hlight\">:</span> <br />مغنی نوائی بده چنگ را<br />بدل آتشی زن شباهنگ را.<br /> <font color=\"Red\">فخر گرگانی .</font><BR>۩ اسب سیاه زیور. شبدیز <span class=\"hlight\">:</span> <br />به پشت شباهنگ بربسته تنگ <br />چو جنگی پلنگی گرازان بجنگ .<br /> <font color=\"Red\">فردوسی .</font><BR>۩ و در بیت ذیل ظاهراً شب آهنگ هنگام شب است <span class=\"hlight\">:</span> <br />شب آهنگ چون برزد از کوه دود<br />برآهنگ شب مرغ دستان نمود.<br /> <font color=\"Red\">نظامی .</font><BR>۩ شوغا. شبگاه . جایگاه چهارپایان در شب . لغت نامه ها برای این معنی بیت ذیل را شاهد آورده اند(؟) <span class=\"hlight\">:</span> <br />از حوصله ٔ زمانه ٔ تنگ <br />بر فرق فلک زده شباهنگ .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">شفشاهنگ </span> ؛ از شفشفه، شوشه و آهنگ بمعنی کش و کشنده . صرمه کش . صورت دیگر آن شفشاهنج است <span class=\"hlight\">:</span> <br />بفرمودش که خواهر را بفرهنج <br />بشفشاهنگ فرهنگش بیاهنج .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />کوه محروق است همچون زر بشفشاهنج در<br />دیو را زو در شکنجه حبس خذلان دیده اند.<br /> <font color=\"Red\">خاقانی .</font><br />ز زخم ناوگ مژگان او بود هر شب <br />بسیط چرخ مشبک بسان شفشاهنگ .<br /> <font color=\"Red\">نجیب جرفادقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کبوترآهنگ </span> ؛ از کبوتر به معنی حمامه و آهنگ . کبوترکش . برج کبوتر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سیم آهنگ </span> ؛ شاید از سیم به معنی ستیم و ریم و آهنگ .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">هم آهنگ </span> ؛ هم آواز. متوافق . هم لحن . هم داستان . هم عقیده <span class=\"hlight\">:</span> <br />گر سیاهست و هم آهنگ تو است <br />تو سفیدش خوان که هم رنگ تو است .<br /> <font color=\"Red\">مولوی .</font><BR>۩ هم وزن . هم بحر.<br /> <BR><font color=\"Blue\">◄</font> (اِ) چگونگی و کیفیت تصویت که با گوش آواز کسی را از دیگری تمیز دهند: آهنگی زنانه . آهنگی لطیف . چگونگی تصویت که بسامعه آواز مردم ولایت و ناحیتی را که بیک زبان تکلم کنند از دیگران فرق توان کردن . <BR><font color=\"Blue\">◄</font> راه . پرده در موسیقی : آهنگ عراق ؛ راه عراق . یکی از نواهای موسیقی <span class=\"hlight\">:</span> <br />عراقی وار بانگ از چرخ بگذاشت <br />به آهنگ عراق این بانگ برداشت .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> وَزن . <BR><font color=\"Blue\">◄</font> (اصطلاح عَروض ) بحر. <BR><font color=\"Blue\">◄</font> موزونی آواز و ساز. (برهان ). <BR><font color=\"Blue\">◄</font> آواز نرم در پرده ٔ سرود و ساز. (مؤید). وزن اغانی، و آن را دراصطلاح موسیقی دانان، برداشت آواز نیز گویند. <BR><font color=\"Blue\">◄</font> آوازی که در اول گویندگی و قوالی برکشند. <BR><font color=\"Blue\">◄</font> شتاب . (برهان ). <BR><font color=\"Blue\">◄</font> در بیت ذیل فردوسی معنی آهنگ معلوم نیست <span class=\"hlight\">:</span> <br />درم نام را باید و ننگ را<br />دگر بخشش و بزم و آهنگ را.<br />وشاید به معنی مقاصد مهمه باشد.<br /></font></div>'),
(2601, 'آهنگر', '<span class=\"hlight\">آهنگر.</span> <font color=\"DarkGreen\"><b>[ هََ گ َ ]</font></b> (ص مرکب ) پیشه وری که آهن در کوره تافته و کوبد و آلات آهنینه سازد. حداد. هبرَقی . هالکی . قین . ریّام . نهامی . نهامین <span class=\"hlight\">:</span> <br />کشاورز و آهنگر و پای باف <br />چو بیکار باشند سَرْشان بکاف .<br /> <font color=\"Red\">ابوشکور.</font><br />سر سروران زیر گرز گران <br />چو سندان بد و پتک آهنگران .<br /> <font color=\"Red\">فردوسی .</font><br />وزآن چرم کآهنگران پشت پای <br />بپوشند هنگام زخم درای <br />همان کاوه آن بر سر نیزه کرد...<br /> <font color=\"Red\">فردوسی .</font><br />برآمد چکاچاک زخم سران <br />چو پولاد با پتک آهنگران .<br /> <font color=\"Red\">فردوسی .</font><br />به پیش آوریدند آهنگران <br />غل و بند وزنجیرهای گران .<br /> <font color=\"Red\">فردوسی .</font><br />بفرمای آهنگر آرند چند<br />ز پای من اکنون بسایند بند.<br /> <font color=\"Red\">فردوسی .</font><br />بر آن بی بها چرم آهنگران <br />برآویختی نوبنو گوهران .<br /> <font color=\"Red\">فردوسی .</font><br />بیارید داننده آهنگران <br />یکی گرز سازند ما را گران .<br /> <font color=\"Red\">فردوسی .</font><br />چنانش بکوبم بگرز گران <br />که فولاد کوبند آهنگران .<br /> <font color=\"Red\">فردوسی .</font><br />نخست اندرآمد بگرز گران <br />همی کوفت چون پتک آهنگران .<br /> <font color=\"Red\">فردوسی .</font><br />یکی بی زیان مرد آهنگرم <br />ز شاه آتش آید همی بر سرم .<br /> <font color=\"Red\">فردوسی .</font><br />یکی نامور بود بوراب نام <br />پسندیده آهنگری شادکام <br />همی کرد او نعل، اسپان شاه <br />ورا نزد قیصر بدی دستگاه .<br /> <font color=\"Red\">فردوسی .</font><br />نه خسرونژادی نه والاسری <br />پدرْت از سپاهان بد آهنگری .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2602, 'آهنگران', '<span class=\"hlight\">آهنگران .</span> <font color=\"DarkGreen\"><b>[ هََ گ َ ]</font></b> (اِخ )نام محلی کنار راه همدان و کرمانشاهان میان هاشم آباد و سمنگان بالا، در <span class=\"hlight\" dir=\"rtl\">٥١٥٥٠٠</span> گزی طهران . <BR><font color=\"Blue\">◄</font> نام کوهی نزدیک حد غربی ایران، و خط سرحدی ایران و عراق بفاصله ٔ یک فرسنگ و نیم در امتداد آن کوه است .<br /></font></div>'),
(2603, 'آهنگرخانه', '<span class=\"hlight\">آهنگرخانه .</span> <font color=\"DarkGreen\"><b>[ هََ گ َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) کارخانه ٔ آهنگری . آهنگری بزرگ .<br /></font></div>'),
(2604, 'آهنگری', '<span class=\"hlight\">آهنگری .</span> <font color=\"DarkGreen\"><b>[ هََ گ َ ]</font></b> (حامص مرکب ) شغل و عمل آهنگر. حرفه ٔ حداد <span class=\"hlight\">:</span> هوشنگ بجای او نشست ... و دیوان را قهر کرد و آهنگری و درودگری و بافندگی پیشه آورد. (نوروزنامه ).<br />چو بشناخت <font color=\"DarkGreen\"><b>[ هوشنگ آهن را ]</font></b> آهنگری پیشه کرد<br />کجا زو تبر وَ ارّه و تیشه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />مرا نیست زآهنگری ننگ و عار<br />خرد باید و مردی ای بادسار.<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> (اِ مرکب ) دکان آهنگر.حدّادی .<br /></font></div>'),
(2605, 'آهنگی', '<span class=\"hlight\">آهنگی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص نسبی ) در بیت ذیل شاید بمعنی کوشا و مجدّ و ساعی باشد <span class=\"hlight\">:</span> <br />همان کودکش را بفرهنگیان <br />سپردی <font color=\"DarkGreen\"><b>[ اردشیر ]</font></b> چو بودی ز آهنگیان <br />بهر برزنی بر، دبستان بدی <br />همان جای آتش پرستان بدی .<br /> <font color=\"Red\">فردوسی .</font><br />و شاید تأیید میکند این حدس را دو بیت زیرین <span class=\"hlight\">:</span> <br />چو هنگام فرهنگ باشد ترا<br />بدانائی آهنگ باشد ترا<br />بایوان نمانم که بازی کنی <br />ببازی چنین سرفرازی کنی .<br /> <font color=\"Red\">فردوسی .</font><br />و معهذا ظاهراً آهنگیان بیشتر صفت پدر کودک می نماید نه کودک، و در آن حال معنی آهنگیان معلوم نیست .<br /></font></div>'),
(2606, 'آهنگیدن', '<span class=\"hlight\">آهنگیدن .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (مص ) قصد کردن . آهنگ کردن . <BR><font color=\"Blue\">◄</font> آهنجیدن . کشیدن، چنانکه آب را از چاه و جز آن <span class=\"hlight\">:</span> <br />کرده شیران حضرت تو مرا<br />سرزده همچو گاو آب آهنگ .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(2607, 'آهنی', '<span class=\"hlight\">آهنی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b>(ص نسبی ) از آهن . منسوب به آهن . آهنین <span class=\"hlight\">:</span> <br />میان من و او بایوان درست <br />یکی آهنی کوه گفتی برست .<br /> <font color=\"Red\">فردوسی .</font><br />برافراشتم گرزسیصدمنی <br />برانگیختم باره ٔ آهنی .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2608, 'آهنیابه', '<span class=\"hlight\">آهنیابه .</span> <font color=\"DarkGreen\"><b>[ هََ ن ْ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) خمیازه . دهان دره . دهن دره . آسا. فاژ. فاژه . خامیاز. خامیازه . بیاستو. باسک . دهن در. ثَأب . ثؤباء. و رجوع به آهبنیابه شود.<br /></font></div>'),
(2609, 'آهنین', '<span class=\"hlight\">آهنین .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص نسبی ) (از پهلوی آسی نان ) منسوب به آهن . از آهن <span class=\"hlight\">:</span> <br />صف دشمن ترا ناستد پیش <br />ور همه آهنین ترا باشد.<br /> <font color=\"Red\">شهید بلخی .</font><br />آنجا که پتک باید خایسک بیهده ست <br />گوز است خواجه سنگین مغز، آهنین سفال .<br /> <font color=\"Red\">منجیک .</font><br />به شاهراه نیاز اندرون، سفر مسگال <br />که مرد کوفته گردد بدان ره اندر سخت <br />وگر خلاف کنی طَمْع را و، هم بشوی <br />بدرّد ار به مثل آهنین بودهملخت .<br /> <font color=\"Red\">کسائی .</font><br />از این مرز تا مرز ایران زمین <br />کنم روی هامون همه آهنین .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت بر من نیاری گزند<br />اگر آهنین کوه گردی بلند.<br /> <font color=\"Red\">فردوسی .</font><br />زمین آهنین شد هوا لاجورد<br />به ابر اندر آمد سر تیره گرد.<br /> <font color=\"Red\">فردوسی .</font><br />بکشتند چندان که روی زمین <br />شد از جوشن کشتگان آهنین .<br /> <font color=\"Red\">فردوسی .</font><br />یکی نغز تابوت کرد آهنین <br />بگسترد فرشی ز دیبای چین .<br /> <font color=\"Red\">فردوسی .</font><br />اگر باره ٔ آهنینی بپای <br />سپهرت بساید نمانی بجای .<br /> <font color=\"Red\">فردوسی .</font><br />بپای پست کند برکشیده گردن شیر<br />بدست رخنه کند لاد آهنین دیوار.<br /> <font color=\"Red\">عنصری .</font><br />چو دیلمان ِ زره پوش شاه، مژگانش <br />به تیز زوبین، بر پیل ساخته خنگال <br />درست گوئی شیران آهنین چرمند<br />همی جهانند از پنجه آهنین چنگال .<br /> <font color=\"Red\">عسجدی .</font><br />چه برخیزد از خود آهن ترا<br />چو سر آهنین نیست در زیر خود؟<br /> <font color=\"Red\">عطار.</font><br />با سیه دل چه سود گفتن وعظ<br />نرود میخ آهنین بر سنگ .<br /> <font color=\"Red\">سعدی .</font><br />سست بازو بجهل می فکند<br />پنجه با مرد آهنین چنگال .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهنین جان </span> ؛ ستم بر. جفابر. سخت جان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهنین جگر</span> ؛ دلاور.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهنین رگ </span> ؛ پرزور. دلاور.<br /></font></div>'),
(2610, 'آهنین دل', '<span class=\"hlight\">آهنین دل .</span> <font color=\"DarkGreen\"><b>[ هََ دِ ]</font></b> (ص مرکب ) شجاع . <BR><font color=\"Blue\">◄</font> قسی . بی رحم . نامهربان . سنگدل . آهن دل <span class=\"hlight\">:</span> <br />آهنین دل بین که سنگ خاره از وی وام خواهد<br />سخت تر زآن دل دل من کز چنین دل کام خواهد.<br /><font color=\"Red\">؟</font><br /></font></div>'),
(2611, 'آهنین پنجه', '<span class=\"hlight\">آهنین پنجه .</span> <font color=\"DarkGreen\"><b>[ هََپ َ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ ]</font></b> (ص مرکب ) قوی پنجه . پرزور <span class=\"hlight\">:</span> <br />یکی آهنین پنجه در اردبیل <br />همی بگذرانید بیلک ز بیل .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(2612, 'آهنینه', '<span class=\"hlight\">آهنینه .</span> <font color=\"DarkGreen\"><b>[ هََ نی ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b>(ص نسبی ) آهنین . منسوب به آهن . از آهن <span class=\"hlight\">:</span> <br />بدیماه ار ایدون که خواهد خدای <br />بپوشم برزم آهنینه قبای .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ مرکب ) آلات آهنین . آنچه از آهن کنند از آلات و ادوات و ظروف و اوانی <span class=\"hlight\">:</span> <br />همیشه تا نجهد زآهنینه مرزنگوش <br />همیشه تا ندمدزآبگینه سیسنبر.<br /> <font color=\"Red\">فرخی .</font><br />بسی حنجر بریده ست او بدنبه <br />شکسته ست آهنینه به آبگینه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />سه روز متواتر می غارتیدند اوّل روز زرّینه و سیمینه و ابریشمینه، دوّم روز برنجینه و روئینه و آهنینه، سوم روز افکندنی و حشو بالشها و نهالیهاو خم و خمره و در و چوب . (راحةالصدور راوندی ).<br /></font></div>'),
(2613, 'آهه', '<span class=\"hlight\">آهه .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) تأوﱡه . <BR><font color=\"Blue\">◄</font> حصبه، یعنی آبله های خرد که بر تن مردم پیدا آید با تب .<br /></font></div>'),
(2614, 'آهو', '<span class=\"hlight\">آهو.</span> (اِ) غزال . غزاله . ظبی . ظبیه . ابوالسفاح . فائر. ج، فور <span class=\"hlight\">:</span> <br />بباغ اندر کنون مردم نبرّد مجلس از مجلس <br />براغ اندر کنون آهو نبرّد سیله از سیله .<br /> <font color=\"Red\">رودکی .</font><br />چون نهاد او پَهَنْد را نیکو<br />قید شد در پَهَنْد او آهو.<br /> <font color=\"Red\">رودکی .</font><br />آهو از دام اندرون آواز داد<br />پاسخ گرزه بدانش بازداد.<br /> <font color=\"Red\">رودکی .</font><br />اکنون فکنده بینی از ترک تا یمن <br />یکچند گاه زیر پی آهوان سمن .<br /> <font color=\"Red\">دقیقی .</font><br />آهو همی گرازد گردن همی فرازد<br />گه سوی کوه تازد گه سوی راغ و صحرا.<br /> <font color=\"Red\">کسائی .</font><br />آهو مر جفت را بغالد بر خوید<br />عاشق معشوق را بباغ بغالید.<br /> <font color=\"Red\">عماره .</font><br />بزرگان ببازی بباغ آمدند<br />همه میش و آهو براغ آمدند.<br /> <font color=\"Red\">فردوسی .</font><br />بپرّیم تا مرغ جادو شویم <br />بپوییم و در چاره آهو شویم .<br /> <font color=\"Red\">فردوسی .</font><br />چپ و راست گفتی که جادو شده ست <br />به آورد تازنده آهو شده ست .<br /> <font color=\"Red\">فردوسی .</font><br />نوازنده بلبل براغ اندرون <br />گرازنده آهو براغ اندرون .<br /> <font color=\"Red\">فردوسی .</font><br />چو زان بگذری سنگلاخ است و دشت <br />که آهو برآن بر نیارد گذشت .<br /> <font color=\"Red\">فردوسی .</font><br />دگر سو سرخس و بیابان به پیش <br />گله گشته بر دشت آهو و میش .<br /> <font color=\"Red\">فردوسی .</font><br />همه دشت پر خرگه و خیمه گشت <br />از انبوه آهو سراسیمه گشت .<br /> <font color=\"Red\">فردوسی .</font><br />چو پیلان بزور و چو مرغان به پر<br />چو ماهی بدریا چو آهو به بر.<br /> <font color=\"Red\">فردوسی .</font><br />بدان دژ درون رفت مرد دلیر<br />چنانچون سوی آهوان نرّشیر.<br /> <font color=\"Red\">فردوسی .</font><br />گوزن است اگر آهوی دلبر است <br />شکاری چنین درخور مهتر است .<br /> <font color=\"Red\">فردوسی .</font><br />ببایست بر کوه آتش گذشت <br />بمن زار بگریست آهو بدشت .<br /> <font color=\"Red\">فردوسی .</font><br />همه کوه نخجیر و آهو بدشت <br />چو این شهربینی نباید گذشت .<br /> <font color=\"Red\">فردوسی .</font><br />نه اندر شکاری که گور افکنی <br />وگر آهوان را بشور افکنی .<br /><font color=\"Red\">فردوسی .</font><br />همی کرد نخجیر آهو نخست <br />ره شیر و جنگ پلنگان نجست <br />کنون نزد او جنگ شیر ژیان <br />همانست و نخجیر آهو همان .<br /> <font color=\"Red\">فردوسی .</font><br />بخارید گوش آهو اندرزمان <br />خدنگی نهاد آن زمان در کمان <br />سر و گوش و پایش بیک جای دوخت <br />بر آن آهو آزاده را دل بسوخت .<br /> <font color=\"Red\">فردوسی .</font><br />بگوش یکی آهو اندرفکند<br />پسند آمدش بود جای پسند.<br /> <font color=\"Red\">فردوسی .</font><br />وزآن پس برفتند سیصد سوار<br />پس بازداران همه یوزدار...<br />قلاده بزر هشتصد بود سگ <br />که در دشت آهو گرفتی به تگ .<br /> <font color=\"Red\">فردوسی .</font><br />صحرای سنگروی و کُه وسنگلاخ را<br />از سم ّ آهوان و گوزنان شیار کرد.<br /> <font color=\"Red\">فرخی .</font><br />ز مرغ و آهو رانم بجویبار و بدشت <br />از آن جفاله جفاله از این قطارقطار.<br /> <font color=\"Red\">عنصری .</font><br />آهوی محالات و آرزو را<br />اندردل من معدن ِ چرا نیست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بمال و قوّت دنیا مشو غره چو دانستی <br />که روزی آهوان بودند پر از آرد انبانها(؟).<br /> <font color=\"Red\">ناصرخسرو.</font><br />کی شناسدقیمت و مقدار دُر بی معرفت <br />کی شناسد قدر مشک آهوی خرخیز و ختن ؟<br /> <font color=\"Red\">سنائی .</font><br />دیدی آن جانور که زاید مشک <br />نامش آهو و او همه هنر است ؟<br /> <font color=\"Red\">خاقانی .</font><br />سگ تازی که آهوگیر گردد<br />بگیرد آهوش چون پیر گردد.<br /> <font color=\"Red\">نظامی .</font><br />وقت شکار دل است آهوی تو شیرگیر<br />گشته گریزان چو شیر زین دل آتش فشان .<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />چو بستی نرگسش را پرده ٔ خواب <br />شدی با شمع همدم در تب و تاب <br />دو مست آهوی خود را تا سحرگاه <br />چرانیدی بباغ حسن آن ماه .<br /> <font color=\"Red\">جامی .</font><br />بمارقیب تو داند هنر گرفتن عیب <br />بلی بود هنر سگ گرفتن آهو.<br /> <font color=\"Red\">منصور شیرازی .</font><br />به پیش اندر آمدْش آهو دو جفت <br />جوانمرد خندان به آزاده گفت ...<br />کدام آهو افکنده خواهی به تیر<br />که ماده جوان است و همتاش پیر<br />چنین گفت آزاده کای شیرمرد<br />به آهو نجویند مردان نبرد...<br />وزآن پس هیون را برانگیز تیز<br />چو آهو ز جنگ تو گیرد گریز.<br /> <font color=\"Red\">فردوسی .</font><br />گشاده برو چرب دستی ّ و زور<br />کمان مهره ٔ آهو و شیر و گور.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> کنایه از چشم معشوق .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهوَکان </span> ؛ آهوان خُرد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهوی سپید</span> ؛ رئم . ج، اَرْآم، آرام .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ماده آهو</span> ؛ظبیه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آهو شدن </span> ؛ در تداول عوام، برای یافتن مطلوب یا معشوقی سر به بیابان نهاده رفتن چنانکه کس او را بازیافتن نتواند.<br /> <span class=\"hlight\">آهوی مانده (آهوی لنگ ) گرفتن </span> ؛ زبون گیری کردن . زور با ناتوان . جنگ با افتاده <span class=\"hlight\">:</span> <br />زهی سوار که آهوی مانده می گیرد!<br />بود مصاف تو ای چرخ با شکسته دلان <br />همیشه شیر تو آهوی لنگ می گیرد.<br /> <font color=\"Red\">صائب .</font><br /><span class=\"hlight\">آهوی ناگرفته بخشیدن </span> ؛ چیز را که در تصرف وملکیت ندارد بعطا دادن <span class=\"hlight\">:</span> <br />فرستاده گفت ای خداوند رخش <br />بدشت آهوی ناگرفته مبخش .<br /> <font color=\"Red\">فردوسی .</font><br /> <span class=\"hlight\">به آهو گوید دو بتازی گوید گیر</span> ؛دو تن را بر یکدیگر برآغالد.<br /> <span class=\"hlight\">شاخ آهو میوه نیارد </span> <span class=\"hlight\">:</span> <br />ز شاخ آهو هرگز مدار چشم ثمر.<br /> <font color=\"Red\">قاآنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آهو</span> ؛ تند در تک .<BR>۩ با چشمانی نیکو.<br /></font></div>'),
(2615, 'آهو', '<span class=\"hlight\">آهو.</span> (اِ) (از: آ علامت سلب و نفی به معنی نه و نا + هوک، به معنی خوب . عیب . نقص . خبط. خطا. ادمان خمر). عیب . نقص . ذمیمه . رذیله . صفت زشت . عوار. مقابل هنر، فضیلت <span class=\"hlight\">:</span> <br />یک آهوست خان را چو ناریش پیش <br />چو پیش آوریدی صد آهوش بیش .<br /> <font color=\"Red\">ابوشکور.</font><br />خردمند گوید که مرد خرد<br />بهنگام خویش اندرون بنگرد<br />شود نیکی افزون چو افزون شود<br />وز آهوی و بد، پاک بیرون شود.<br /> <font color=\"Red\">ابوشکور.</font><br />هنرهاز بخت بد آهو بود<br />ز بخت آوران زشت نیکو بود.<br /><font color=\"Red\">ابوشکور.</font><br />نکوهش رسیدی بهر آهوئی <br />ستایش بد از هر هنر هر سوئی .<br /> <font color=\"Red\">ابوشکور.</font><br />شنید این سخن شاه و نیرو گرفت <br />هنرها بشست از دل آهو گرفت .<br /> <font color=\"Red\">فردوسی .</font><br />ولیکن نبیند کس آهوی خویش <br />ترا روشن آید همی خوی خویش .<br /> <font color=\"Red\">فردوسی .</font><br />بی آهو کسی نیست اندر جهان <br />چه در آشکار و چه اندر نهان .<br /> <font color=\"Red\">فردوسی .</font><br />چه فرمائیَم چیست نیروی من <br />تو دانی هنرها و آهوی من .<br /> <font color=\"Red\">فردوسی .</font><br />چو گفتار و کردار نیکو کنی <br />بگیتی روان را بی آهو کنی .<br /> <font color=\"Red\">فردوسی .</font><br />کسی را کجا دل پرآهو بود<br />روانش ز هستی به نیرو بود<br />به بیچارگان بر ستم سازد او<br />گر از خیره گردن برافرازد او<br />بکوشیم و نیروش بیرون کنیم <br />بدرویش ما نازش افزون کنیم .<br /> <font color=\"Red\">فردوسی .</font><br />که آهوست بر مرد گفتار زشت <br />ترا خود ز آغاز بود این سرشت .<br /> <font color=\"Red\">فردوسی .</font><br />بگفتار بی بر چونیرو کنی <br />روان و خرد را بی آهو کنی .<br /> <font color=\"Red\">فردوسی .</font><br />نخستین بنرمی سخنگوی باش <br />بداد و بکوشش بی آهوی باش .<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ که بر شهریار<br />خردمند گوید که آهوست چار.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت ازیدر بیک سو شویم <br />بر آوردگه بر بی آهو شویم .<br /> <font color=\"Red\">فردوسی .</font><br />از آهو همان کش سپید است موی <br />نگوید بجز مردم عیبجوی .<br /> <font color=\"Red\">فردوسی .</font><br />ز آهو همان کش سپید است موی <font color=\"DarkGreen\"><b>[ زال ]</font></b><br />چنین بود بخش تو ای نامجوی .<br /> <font color=\"Red\">فردوسی .</font><br />گر آهوست بر مرد موی سپید<br />ترا ریش و سر گشت چون برگ بید.<br /><font color=\"Red\">فردوسی .</font><br />سراسر سپید است مویش بسر<br />از آهوهمین است و این است فر.<br /> <font color=\"Red\">فردوسی .</font><br />هنرها همه هست و آهو یکی <br />که گردد هنر پیش او اندکی .<br /> <font color=\"Red\">فردوسی .</font><br />ز بهر من آهو ز هر سو مخواه <br />میان دو صف برکشیده سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />مرا گفت آن دادگر شهریار<br />که گر خو بود پیش باغ بهار<br />اگر آب یابد به نیرو شود<br />همه باغ ازو پر ز آهو شود.<br /> <font color=\"Red\">فردوسی .</font><br />دو گوش و دو پای من آهو گرفت <br />تهی دستی و سال نیرو گرفت .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت آن کس که آهوی خویش <br />ببیند بگرداند آیین و کیش .<br /> <font color=\"Red\">فردوسی .</font><br />کز او دین یزدان به نیرو شود<br />همان تخت شاهی بی آهو شود.<br /> <font color=\"Red\">فردوسی .</font><br />سه آهو کدام است با دل براز<br />که دارند و هستند از آن بی نیاز...<br />بی آهو کسی نیست اندر جهان <br />تن و جان چو ببْساود اندر نهان .<br /> <font color=\"Red\">فردوسی .</font><br />بپرسید کآهو کدام است زشت <br />که از ارج دور است و دور از بهشت ؟<br /> <font color=\"Red\">فردوسی .</font><br />هرآنکس که آهوی تو با تو گفت <br />همه راستیها گشاد از نهفت .<br /> <font color=\"Red\">فردوسی .</font><br />قباد بداندیش نیرو گرفت <br />هنرها بشست از دل آهو گرفت .<br /> <font color=\"Red\">فردوسی .</font><br />همه لشکر شاه نیرو گرفت <br />کز او کار بهرام آهو گرفت .<br /> <font color=\"Red\">فردوسی .</font><br />از این نیست آهو بزرگ است و شاه <br />دلیر و خداوند توران سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />ایا ستوده بمردی چو پیش بین بخرد<br />ایا زدوده ز آهو چو پارسا ز گناه .<br /> <font color=\"Red\">فرخی .</font><br />خوش خو دارم بکار، بدخو چه کنم <br />چون هست هنر نگه به آهو چه کنم <br />چون کار گشاده گشت نیرو چه کنم <br />با زشت مرا خوش است نیکو چه کنم ؟<br /> <font color=\"Red\">عنصری .</font><br />امروز بخم اندر نیکوتر از آنید<br />نیکوتر از آنید و بی آهوتر از آنید.<br /> <font color=\"Red\">منوچهری .</font><br />اگرچه ویس بی آهو و پاک است <br />مرا زین روی دل اندیشه ناک است .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />چو بیند جامه های سخت نیکو<br />بگوید هر یکی را چند آهو<br />که زرد است این سزای نابکاران <br />کبود است این سزای سوگواران <br />سپید است این سزای گنده پیران <br />دورنگ است این سزاوار دبیران .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />مکن تندی که باشد از تو آهو<br />به است از روی نیکو خوی نیکو.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بدیده کوری دختر نبیند<br />همان داماد بی آهو گزیند.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />کرا دوست داری ّ و کام تو اوست <br />هر آهوش را همچنان دار دوست .<br /> <font color=\"Red\">اسدی .</font><br />هنرها ز بخت بد آهو بود<br />ز بخت آوران زشت نیکو بود.<br /> <font color=\"Red\">اسدی .</font><br />از آهو سخن پاک و پردخته گوی <br />ترازو خرد ساز و برسخته گوی .<br /> <font color=\"Red\">اسدی ؟</font><br />چنین داد پاسخ که پیری ّ و درد<br />درآرد دوصد گونه آهو بمرد.<br /> <font color=\"Red\">اسدی .</font><br />هر آهو که خیزد ز یک کژ سخُن <br />بصد راست نیکو نگردد ز بن .<br /> <font color=\"Red\">اسدی .</font><br />چهار است آهوی شه آشکار<br />که شه را نباشد بترزین چهار.<br /> <font color=\"Red\">اسدی .</font><br />از آهوش تا بیشتر آگهیم <br />بمهرش درون بیشتر گمرهیم .<br /><font color=\"Red\">اسدی .</font><br />این جهان سربسر آهو و در او یک هنر است <br />که نپاید غم و تیمارش چون عز و جلال .<br /> <font color=\"Red\">قطران .</font><br />برشو بهنر بعالم علوی <br />زین عالم پرعوار و پرآهو.<br /> <font color=\"Red\">ناصرخسرو.</font><br />هرچه زایزد بود همه نیکوست <br />هرچه از تست سربسر آهوست .<br /> <font color=\"Red\">سنائی .</font><br />به تیه حرص چون آهو چه تازی نفس همچون سگ <br />بصحرای قناعت شو که بی آهوست آن صحرا.<br /> <font color=\"Red\">سنائی .</font><br />تا ز خرد باشد یا از سفه <br />تا بود از آهو یا از هنر.<br /> <font color=\"Red\">سوزنی .</font><br />دیدی آن جانور که زاید مشک <br />نامش آهو و آن همه هنر است ؟<br /> <font color=\"Red\">خاقانی .</font><br />گر اندازه ز چشم خویش گیرد<br />بر آهوئی صد آهو بیش گیرد.<br /> <font color=\"Red\">نظامی .</font><br />سگ تازی که آهوگیر گردد<br />بگیرد آهوش چون پیر گردد.<br /> <font color=\"Red\">نظامی .</font><br />جز آنکس ندانم نکوگوی ِ من <br />که روشن کند بر من آهوی ِ من .<br /> <font color=\"Red\">سعدی .</font><br />پیش چشم سیهت یاد غزالست آهو<br />نزد آن سنبل مو، دم زدن از مشک خطاست .<br /> <font color=\"Red\">نظیری نیشابوری .</font><br /><BR><font color=\"Blue\">◄</font> (ص ) بد <span class=\"hlight\">:</span> <br />سفر نیست آهو که والاگهر<br />چوبیند جهان پیش گیرد هنر.<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) و به معنی بیماری و مرض آید. و در فرهنگها معنی بلا نیز بدان داده اند و دربعض دیگر به آهو معنی ضیق النفس میدهند و بیت ذیل نظامی را شاهد می آورند <span class=\"hlight\">:</span> <br />سگ تازی که آهوگیر گردد<br />بگیرد آهوش چون پیر گردد.<br /> <font color=\"Red\">نظامی .</font><br />و این ادعا با استناد باین بیت غلط و دلیل اختلال ذوق مدعی است . و نیز باین کلمه معنای فریاد داده اند و بیت ذیل را با انتساب آن بفردوسی مثال گذرانیده اند <span class=\"hlight\">:</span> <br />به آهو ز باره فتاد و بمرد<br />بدید از کیان زاده آن دستبرد.<br />بیت از دقیقی است، و در همه ٔ نسخ چاپی و یک نسخه ٔ خطی کهن که در دسترس نگارنده است صورت شعر این است <span class=\"hlight\">:</span> <br />ز باره نگون اندرافتاد و مرد<br />بدید آن کیان زادگی دستبرد.<br />و ابیات پیش و پس این بیت نیز تأیید میکند که کلمه ٔ آهو خاصه به معنی فریاد در اینجا بی مورد است . <br /></font></div>'),
(2616, 'آهواز', '<span class=\"hlight\">آهواز.</span> <font color=\"DarkGreen\"><b>[ آه ْ ]</font></b> (اِخ ) اهواز <span class=\"hlight\">:</span> <br />گر از بهار خلق تو بوئی برد صبا<br />روید شکر ز نیش عقارب به آهواز.<br /><font color=\"Red\">سیف اسفرنگ .</font><br /></font></div>'),
(2617, 'آهوان', '<span class=\"hlight\">آهوان .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِ) ج ِ آهو <span class=\"hlight\">:</span> <br />همه مرگ رائیم پیر و جوان <br />که مرگ است چون شیر و ما آهوان .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2618, 'آهوان', '<span class=\"hlight\">آهوان .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نام محلی کنار راه سمنان بدامغان، میان تیلستان و کلاته یعقوب در <span class=\"hlight\" dir=\"rtl\">٢٦٦</span> هزارگزی طهران .<br /></font></div>'),
(2619, 'آهوانه', '<span class=\"hlight\">آهوانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی ) چون آهو. درخور آهو <span class=\"hlight\">:</span> <br />آن چشم آهوانه ٔ عابدفریب بین <br />کش کاروان حسن بدنباله میرود.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(2620, 'آهوای', '<span class=\"hlight\">آهوای .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام شهری کنار جیحون . (شعوری ). و ظاهراً این کلمه مصحف آموی باشد.<br /></font></div>'),
(2621, 'آهوبره', '<span class=\"hlight\">آهوبره .</span> <font color=\"DarkGreen\"><b>[ ب َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) بچه ٔ آهو. آهوبچه . برّه ٔ آهو. شادن . رشا. غزال . غزاله . ظبی . ظبیه . طلا. خِشف . ریم . جدایه . خریجه . یعفور <span class=\"hlight\">:</span> <br />کف یوز پرمغز آهوبره <br />همه چنگ شاهین دل گودره .<br /> <font color=\"Red\">عنصری .</font><br />این عجب نیست بسی کز اثر لاله و خوید<br />گفتی آهوبره میناسُم و بیجاده لب است .<br /> <font color=\"Red\">انوری .</font><br />در ایام عدل تو آهوبره <br />ز پستان شیران شده سیرشیر.<br /> <font color=\"Red\">ظهیر فاریابی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهوبره ٔ فلک </span> ؛ برج حمل .<br /><BR><font color=\"Blue\">◄</font> هوبره . آبره . حُباری ̍. چرز. چرزه . جرز. توقدری . تغدری .<br /></font></div>'),
(2622, 'آهوبچه', '<span class=\"hlight\">آهوبچه .</span> <font color=\"DarkGreen\"><b>[ ب َ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ مرکب ) بچه ٔ آهو. بره ٔ آهو. آهوبره . شادِن . رشا. و رجوع به آهوبره شود <span class=\"hlight\">:</span> <br />آهوبچه کی باشد چون بچه ٔ ضیغم ؟<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهوبچه ٔ ماده </span> ؛ عَزَّه .<br /></font></div>'),
(2623, 'آهوتک', '<span class=\"hlight\">آهوتک .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص مرکب ) چون آهو در دویدن . آهودو <span class=\"hlight\">:</span> <br />سیه چشم و گیسوفش و مشک دم <br />پری پوی و آهوتک و گورسم .<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(2624, 'آهوجه', '<span class=\"hlight\">آهوجه .</span> <font color=\"DarkGreen\"><b>[ ج َه ْ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِه ْ ]</font></b> (نف مرکب <span class=\"hlight\" dir=\"rtl\">/</span> ص مرکب ) آنکه جهشی چون آهو دارد. آهوفغند <span class=\"hlight\">:</span> <br />شیرکام و پیل زور و گرگ پوی و گورگر <br />ببردو آهوجه و روباه عطف و رنگ تاز.<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(2625, 'آهوخرام', '<span class=\"hlight\">آهوخرام .</span> <font color=\"DarkGreen\"><b>[ خ ِ <span class=\"hlight\" dir=\"rtl\">/</span> خ َ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ ]</font></b> (نف مرکب <span class=\"hlight\" dir=\"rtl\">/</span> ص مرکب ) آنکه رفتنی چون آهو دارد.<br /></font></div>'),
(2626, 'آهود', '<span class=\"hlight\">آهود.</span> (اِخ ) پسر جیرا از سبط بن یامین . (قاموس کتاب مقدس ).<br /></font></div>'),
(2627, 'آهودل', '<span class=\"hlight\">آهودل .</span> <font color=\"DarkGreen\"><b>[دِ ]</font></b> (ص مرکب ) ترسنده . شتردل . اشتردل . گاودل . بزدل .مرغ دل . کلنگ دل . بَددِل . غردِل . کبک زهره . گاوزهره .<br /></font></div>'),
(2628, 'آهودلی', '<span class=\"hlight\">آهودلی .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (حامص مرکب ) صفت و چگونگی آهودِل .<br /></font></div>'),
(2629, 'آهودو', '<span class=\"hlight\">آهودو.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُو ]</font></b> (نف مرکب <span class=\"hlight\" dir=\"rtl\">/</span> ص مرکب ) آهوتک . آنکه دویدنی چون آهو دارد <span class=\"hlight\">:</span> <br />یوزجست و رنگ خیز و گرگ پوی و غرم تک <br />ببرجه آهودو و روباه حیله، گوردن .<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(2630, 'آهودوستک', '<span class=\"hlight\">آهودوستک .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) حزا. برگ کازرونی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهودوستک صحرائی </span> ؛ سداب .<br />رجوع به حُزا شود.<br /></font></div>'),
(2631, 'آهورامزدا', '<span class=\"hlight\">آهورامزدا.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) اورمزد. یزدان . رب ّ اعلی . رب الارباب . فاعل خیر. مقابل آهرمن، فاعل شر، دیو. و هفت فرشته یا امشاسپند وسایط فیض او بدیگر مخلوق باشند.<br /></font></div>'),
(2632, 'آهوربر', '<span class=\"hlight\">آهوربر.</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (نف مرکب ) در بعض فرهنگها به معنی نقاب آمده، وآن مصحف آهون بر است . رجوع به آهون و آهون بُر شود.<br /></font></div>'),
(2633, 'آهوری', '<span class=\"hlight\">آهوری .</span> (اِ) تخم ترتیزک سفید. خردل . و فرهنگها بیت ذیل را شاهد می آورند <span class=\"hlight\">:</span> <br />وقت برجستن چو آهوئیست تند<br />گاه بررفتن چو آهوریست تیز.<br /> <font color=\"Red\">شهاب طلحه .</font><br /> <br /></font></div>'),
(2634, 'آهوفغند', '<span class=\"hlight\">آهوفغند.</span> <font color=\"DarkGreen\"><b>[ ف َ غ َ ]</font></b> (ص مرکب ) آهوجه <span class=\"hlight\">:</span> <br />هم آهوفغند است و هم تیزتک <br />هم آهسته خوی است و هم تیزگام .<br /><font color=\"Red\">فرالاوی .</font><br /></font></div>'),
(2635, 'آهومند', '<span class=\"hlight\">آهومند.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ص مرکب ) مریض . بیمار. <BR><font color=\"Blue\">◄</font> معیوب . ناقص . آهُمند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مغزی آهومند</span> ؛ دماغی مختل . مُخبط <span class=\"hlight\">:</span> <br />ز پیری مغزت آهومند گشته ست <br />ز گیتی روزگارت درگذشته ست .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />و رجوع به آهُمند شود.<br /></font></div>'),
(2636, 'آهون', '<span class=\"hlight\">آهون .</span> (اِ) رخنه و راه و مجرائی که زیر زمین کنند. نقب . سُمج . سُمجه <span class=\"hlight\">:</span> <br />حور بهشتی گرش به بیند بی شک <br />حفره زند تا زمین بیارد آهون .<br /> <font color=\"Red\">دقیقی .</font><br />به آهون زدن در زمین با شتاب <br />سبکتر روندی ز ماهی در آب .<br /> <font color=\"Red\">اسدی .</font><br />بن باره سرتاسر آهون زدند<br />نگون باره بر روی هامون زدند.<br /> <font color=\"Red\">اسدی .</font><br />منگر سوی حرام و جز حق مشنو<br />تا نبرد دزد سوی نقد تو آهون .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دانه مر این را بخوشه ها در خانه ست <br />بیخ مر آن را بزیر خاک درآهون .<br /> <font color=\"Red\">ناصرخسرو.</font><br />سر بفلک برکشیده بی خردی <br />مردمی و سروری در آهون شد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />بر راه خلق سوی دگر عالم <br />یکّی رباط یا یکی آهونی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مردم بروز در چاهها و آهونها و کاریزهای کهن میگریختند. (راحةالصدور).<br /> <BR><font color=\"Blue\">◄</font> دائره . زه . طوقه . حلقه : الحماره ؛ آنچه گردآهون حوض بنهند... و آن سنگ که صیاد گرد آهون جایگاه خویش بپای کند. (محمودبن عمر ربنجنی ). <BR><font color=\"Blue\">◄</font> آبدان <span class=\"hlight\">:</span> <br />مشرق بنور صبح سحرگاهان <br />رخشان بسان طارم زریون است <br />گوئی میان خیمه ٔ پیروزه <br />پر زآب زعفران یکی آهون است .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> کهف . غار. (برهان ). و در بعض فرهنگها معنی معدن نیز بکلمه داده اند. <br /></font></div>'),
(2637, 'آهون بر', '<span class=\"hlight\">آهون بر.</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (نف مرکب ) نقّاب . نقب زن . چاهجوی . کان کن <span class=\"hlight\">:</span> <br />بدل درفکندی چنان چاک را<br />که میتین آهون بران خاک را.<br /><font color=\"Red\">؟</font><br /></font></div>'),
(2638, 'آهوناک', '<span class=\"hlight\">آهوناک .</span> (ص مرکب ) معیوب . معیب .<br /></font></div>'),
(2639, 'آهوپا', '<span class=\"hlight\">آهوپا.</span> (ص مرکب، اِ مرکب ) آهوپای . بنا یا خانه ٔ آهوپای ؛ خانه ٔ شش پهلو. خانه ٔ مسدس . خانه ٔ شش ضلعی . خانه ٔ مسدس الاضلاع <span class=\"hlight\">:</span> <br />ای مبارک بنای آهوپای <br />آهویی در تو نافریده خدای .<br /> <font color=\"Red\">ابوالفرج رونی .</font><br /> <BR><font color=\"Blue\">◄</font> گچ بریهای برجسته بر آسمانه ٔ خانه آویخته چون پای آهو. مقرنَس . مقرنس کاری . و بهر دو معنی، پاآهو و پاآهوی نیز گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهوپای شدن </span> ؛ گریختن . سخت بشتاب دویدن <span class=\"hlight\">:</span> <br />زآن بساط ددان آهن خای <br />کرده با هم دو آتش آهوپای (کذا).<br /><font color=\"Red\">امیرخسرو دهلوی .</font><br /></font></div>'),
(2640, 'آهوپرواز', '<span class=\"hlight\">آهوپرواز.</span> <font color=\"DarkGreen\"><b>[ پ َرْ ]</font></b> (ص مرکب ) سخت بشتاب دونده <span class=\"hlight\">:</span> <br />برق جه بادگذر یوزدو و کوه قرار<br />شیردل پیل قدم گورتک آهوپرواز.<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(2641, 'آهوچشم', '<span class=\"hlight\">آهوچشم .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span>چ ِ ]</font></b> (ص مرکب ) آنکه چشمی چون آهو دارد <span class=\"hlight\">:</span> <br />بزن ای ترک آهوچشم، آهو از سر تیری <br />که باغ و راغ و کوه و دشت پرماهست و پرشِعْری .<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(2642, 'آهوگردان', '<span class=\"hlight\">آهوگردان .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (نف مرکب ) آنکه آهوان را در صحرا راند بجائی که شاه یاامیر به آسانی شکار توانند کرد. نخجیروال . نجاشی .<br /></font></div>'),
(2643, 'آهوگردانی', '<span class=\"hlight\">آهوگردانی .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (حامص مرکب ) شغل آهوگردان . نخجیروالی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهوگردانی کردن </span> ؛ با گربزی و با اغفال دیگران امری را رفته رفته بسوی مقصود خویش سوق کردن .<br /></font></div>'),
(2644, 'آهوی', '<span class=\"hlight\">آهوی .</span> (اِ) (در حال اضافه ) آهو. غزال <span class=\"hlight\">:</span> <br />یارب آن آهوی مشکین بختن بازرسان <br />وآن سهی سرو خرامان بچمن بازرسان .<br /><font color=\"Red\">حافظ.</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2645, 'آهوی', '<span class=\"hlight\">آهوی .</span> (اِ) (در حال اضافه ) عیب <span class=\"hlight\">:</span> <br />ولیکن نبیند کس آهوی خویش <br />ترا روشن آید همی خوی خویش .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت آنکس که آهوی خویش <br />ببیند بگرداند آیین و کیش .<br /> <font color=\"Red\">فردوسی .</font><br />چه فرمائیَم چیست نیروی من <br />تو دانی هنرها و آهوی من .<br /> <font color=\"Red\">فردوسی .</font><br />هر آنکس که آهوی تو با تو گفت <br />همه راستیها گشاد از نهفت .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2646, 'آهوی تاتار', '<span class=\"hlight\">آهوی تاتار.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آهوی تاتاری . آهوی تَتر. آهوی تتاری . آهوی ختن . آهوی ختا. آهوی خرخیز. آهوی مشک .آهوی مشکین . غزال المسک . دابةالمسک . آف . آهوی چین .<br /></font></div>'),
(2647, 'آهوی تاتاری', '<span class=\"hlight\">آهوی تاتاری .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) آهوی تاتار.<br /></font></div>'),
(2648, 'آهوی تتار', '<span class=\"hlight\">آهوی تتار.</span> <font color=\"DarkGreen\"><b>[ ی ِ ت َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آهوی تاتار.<br /></font></div>'),
(2649, 'آهوی تتاری', '<span class=\"hlight\">آهوی تتاری .</span> <font color=\"DarkGreen\"><b>[ ی ِ ت َ ]</font></b> (ترکیب وصفی، اِ مرکب ) آهوی تاتار.<br /></font></div>'),
(2650, 'آهوی تتر', '<span class=\"hlight\">آهوی تتر.</span><font color=\"DarkGreen\"><b>[ ی ِ ت َ ت َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آهوی تاتار.<br /></font></div>'),
(2651, 'آهوی تتری', '<span class=\"hlight\">آهوی تتری .</span> <font color=\"DarkGreen\"><b>[ ی ِ ت َ ت َ ]</font></b> (ترکیب وصفی، اِ مرکب ) آهوی تاتار.<br /></font></div>'),
(2652, 'آهوی خاوری', '<span class=\"hlight\">آهوی خاوری .</span> <font color=\"DarkGreen\"><b>[ ی ِ وَ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از خورشید.<br /></font></div>'),
(2653, 'آهوی ختا', '<span class=\"hlight\">آهوی ختا.</span> <font color=\"DarkGreen\"><b>[ ی ِ خ َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آهوی تاتار.<br /></font></div>'),
(2654, 'آهوی ختن', '<span class=\"hlight\">آهوی ختن .</span><font color=\"DarkGreen\"><b>[ ی ِ خ ُ ت َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آهوی تاتار.<br /></font></div>'),
(2655, 'آهوی خرخیز', '<span class=\"hlight\">آهوی خرخیز.</span> <font color=\"DarkGreen\"><b>[ ی ِ خ َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آهوی تاتار.<br /></font></div>'),
(2656, 'آهوی خطا', '<span class=\"hlight\">آهوی خطا.</span> <font color=\"DarkGreen\"><b>[ ی ِ خ َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آهوی تاتار.<br /></font></div>'),
(2657, 'آهوی فلک', '<span class=\"hlight\">آهوی فلک .</span> <font color=\"DarkGreen\"><b>[ ی ِ ف َ ل َ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از خورشید است .<br /></font></div>'),
(2658, 'آهوی مشک', '<span class=\"hlight\">آهوی مشک .</span> <font color=\"DarkGreen\"><b>[ی ِ م ِ <span class=\"hlight\" dir=\"rtl\">/</span> م ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) آهوی تاتار.<br /></font></div>'),
(2659, 'آهوی مشکین', '<span class=\"hlight\">آهوی مشکین .</span> <font color=\"DarkGreen\"><b>[ ی ِ م ِ <span class=\"hlight\" dir=\"rtl\">/</span> م ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) آهوی تاتار <span class=\"hlight\">:</span> <br />یارب آن آهوی مشکین بختن بازرسان <br />وآن سهی سرو خرامان بچمن بازرسان .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(2660, 'آهویی', '<span class=\"hlight\">آهویی .</span> (حامص ) رمندگی . (برهان ). <BR><font color=\"Blue\">◄</font> عیبناکی . (برهان ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام شهری کنار جیحون، و ظاهراً این صورت مصحف آموی باشد.<br /></font></div>'),
(2661, 'آهک', '<span class=\"hlight\">آهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) پخته و ریزیده شده ٔ سنگی مخصوص که برای محکم کردن بنا در ملاط و شفته و ساروج آمیزند. کلس . اَژه . نوره . جبصین . صاروج . اهک <span class=\"hlight\">:</span> <br />فرمان کن تا آهک و زرنیخ بسایند<br />بر روت براندای و برون آر همه رت .<br /> <font color=\"Red\">لبیبی .</font><br />سنگ البرزرا کند آهک <br />آتش آب پرور تیغش .<br /> <font color=\"Red\">خاقانی .</font><br />زمین از ملاقات طوفان تیغش همان خاصیت یافت کز آب آهک . (از تاج المآثر).<br />بدست آهک تفته کردن خمیر<br />به از دست بر سینه پیش امیر.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> نوره . واجبی . آهک نوره . حنازرد. جمش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهک بادامچه </span> ؛ آهک از جنس خوب از سنگهای کوچک .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهک زنده </span> ؛ که تیزی و قوت آن نشده باشد. مکلس .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهک کردن </span> ؛ سخت متلاشی و ازهم ریزیده کردن : بعض مارها چون بگزند مرد را آهک کنند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آهک کُشته </span> ؛ مقابل مُکلس و آهک زنده . آهکی که قوّت و حدّت آن بمرور زمان یا مجاورت نم و رطوبت بشده است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سنگ آهک </span> ؛ قرمَد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آهک </span> ؛ سخت متلاشی . سخت ازهم ریزیده .<br /></font></div>'),
(2662, 'آهک ساروج', '<span class=\"hlight\">آهک ساروج .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ مرکب ) سارو. آهک چارو.<br /></font></div>'),
(2663, 'آهک نوره', '<span class=\"hlight\">آهک نوره .</span> <font color=\"DarkGreen\"><b>[ هََ ک ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) نوره . واجبی . حنازرد <span class=\"hlight\">:</span> گفتند این را <font color=\"DarkGreen\"><b>[ موهای بلقیس سبا را ]</font></b> به آهک نوره حیلت کنیم ... آنگاه سلیمان آهک نوره به بلقیس فرستاد. (ترجمه ٔ طبری بلعمی ).<br /></font></div>'),
(2664, 'آهک نوشادر', '<span class=\"hlight\">آهک نوشادر.</span> <font color=\"DarkGreen\"><b>[ هََ ک ِ دُ ]</font></b> (ترکیب اضافی، اِ مرکب ) نوره . (محمودبن عمر ربنجنی ).<br /></font></div>'),
(2665, 'آهک پز', '<span class=\"hlight\">آهک پز.</span> <font color=\"DarkGreen\"><b>[ هََ پ َ ]</font></b> (نف مرکب ) آنکه حرفه اش پختن آهک است . حرّاض . کَلاّس . مکلِّس .<br /></font></div>'),
(2666, 'آهک پزی', '<span class=\"hlight\">آهک پزی .</span> <font color=\"DarkGreen\"><b>[ هََ پ َ ]</font></b> (حامص مرکب ) حرفه ٔ آهک پز. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) کوره ٔ آهک پز.<br /></font></div>'),
(2667, 'آهک چارو', '<span class=\"hlight\">آهک چارو.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ مرکب ) آهک مخلوط بخاکستر و لوئی که بدان حوض وخزانه ٔ حمام و مانند آن اندایند. آهک ساروج . سارو.<br /></font></div>'),
(2668, 'آهکی', '<span class=\"hlight\">آهکی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص نسبی ) منسوب به آهک . از آهک . کلسی . <BR><font color=\"Blue\">◄</font> آهک فروش . <BR><font color=\"Blue\">◄</font> کلسی . (فرهنگستان ). <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نمد آهکی </span> ؛ قسمی نمد از جنس پست .<br /></font></div>'),
(2669, 'آهکی بیرک', '<span class=\"hlight\">آهکی بیرک .</span> <font color=\"DarkGreen\"><b>[ هََ رَ ]</font></b> (اِخ ) نام کوهی بناحیه ٔ سراوان ِ بلوچستان، به ارتفاع <span class=\"hlight\" dir=\"rtl\">٢٧٤٢</span> گز.<br /></font></div>'),
(2670, 'آهی', '<span class=\"hlight\">آهی .</span> (اِخ ) تخلص شاعری از مردم ترشیز. <BR><font color=\"Blue\">◄</font> آهی جغتائی . تخلص شاعری مدّاح غریب میرزا پسر سلطان حسین بایقرا. و تخلص او در ابتدا نرگسی بوده، و در <span class=\"hlight\" dir=\"rtl\">٩٢٧</span> هَ .ق . وفات کرده است .<br /></font></div>'),
(2671, 'آهی', '<span class=\"hlight\">آهی .</span> (اِ) بلغت زند و پازندبه معنی آهو. (برهان ) .<br /></font></div>'),
(2672, 'آهیانه', '<span class=\"hlight\">آهیانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) استخوان بالای مغز از کاسه ٔ سر. قحف . <BR><font color=\"Blue\">◄</font> صاحب جهانگیری گوید در بعض فرهنگها به معنی کاسه ٔ سر <font color=\"DarkGreen\"><b>[ جمجمه ]</font></b> و شقیقه نیز آمده است . <BR><font color=\"Blue\">◄</font> کام . فک اعلی یعنی آنجای که بحلقوم نزدیک و به عربی حنک باشد. (برهان ). <BR><font color=\"Blue\">◄</font> عظم مصفات : القحف ؛ بر آهیانه زدن . (تاج المصادر بیهقی ). آنجای از سر کودک که می جنبد. (مؤید الفضلاء). یافوخ .<br /></font></div>'),
(2673, 'آهیختن', '<span class=\"hlight\">آهیختن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص ) کشیدن . برکشیدن . برآوردن . سَل ّ. تشهیر. بیرون کشیدن . آختن . آهختن . آهنجیدن . برآوردن <span class=\"hlight\">:</span> <br />برآهیخت جنگی نهنگ از نیام <br />بغرید چون رعد و برگفت نام .<br /> <font color=\"Red\">فردوسی .</font><br />برآهیخت شمشیر و اندرنهاد<br />همی کرد از آن رزم گشتاسب یاد.<br /> <font color=\"Red\">فردوسی .</font><br />برآهیخت شمشیر کین پیلتن <br />ز دیوان بپرداخت آن انجمن .<br /> <font color=\"Red\">فردوسی .</font><br />چو آهیخت بر جنگ شب، روز تیغ<br />ستاره گرفت از سپیده گریغ.<br /> <font color=\"Red\">اسدی .</font><br />چو آهیخت خور تیغ زرین زبر<br />نهان کرد از او ماه سیمین سپر.<br /> <font color=\"Red\">اسدی .</font><br />چو عزمش برآهیخت شمشیر بیم <br />بمعجز میان قمر زد دو نیم .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> برداشتن .بلند کردن . برافراختن . برافراشتن <span class=\"hlight\">:</span> <br />برآهیخت گرز و برانگیخت اسب <br />بیامد بکردار آذرگشسب .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> کشیدن، چنانکه دلو را برسن . از چاه بالا کشیدن <span class=\"hlight\">:</span> <br />بدلو اندرون رفت آن پاک تن <br />برآهیخت بُشری ̍ بقوت رسن .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> کشیدن، چنانکه صف را. رده برزدن <span class=\"hlight\">:</span> <br />بدانسان که فرموده بد شهریار<br />شد آهیخته صفّهای سوار.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> کشیدن، چنانکه اژدهابدَم <span class=\"hlight\">:</span> <br />برفت ازپسش رستم شیرگیر<br />ببارید بر لشکرش گرز و تیر<br />دو فرسنگ چون اژدهای دژم <br />همی مردم آهیخت گفتی بدم .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> راست کردن . ستیخ کردن . باز کردن، چنانکه درنده ای پنجه را <span class=\"hlight\">:</span> <br />برون آمد آراسته جنگ را<br />بکین جستن آهیخته چنگ را.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> برکشیدن، چنانکه پوست را از تن . سلخ <span class=\"hlight\">:</span> <br />بکشت و ز سَرْشان برآهیخت پوست <br />نماند ایچ از ایشان نه دشمن نه دوست .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> کشیدن . برکشیدن . محکم و استوار کردن، چنانکه تنگ اسب را <span class=\"hlight\">:</span><br />چو زین برنهادش برآهیخت تنگ <br />بجنبید بر جای تازان نهنگ .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> براق کردن .انتفاش . ستیخ کردن، چنانکه پر و موی را <span class=\"hlight\">:</span> <br />همچون کَشَف بسینه سر اندرکشد اجل <br />آنجا که نیزه ٔ تو برآهیخت یال را.<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> کشیدن، چنانکه دست را از دست کسی <span class=\"hlight\">:</span> <br />بیاهیخت زو دست و بر پای خاست <br />غمی شد بیازید با بند راست .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> دست کشیدن از چیزی . <BR><font color=\"Blue\">◄</font> لنجیدن . و رجوع به آختن و آهختن شود. و مصدر دوم یا اسم مصدر آن آهنجش باشد: آهیخت، بیاهنج .<br /></font></div>'),
(2674, 'آهیخته', '<span class=\"hlight\">آهیخته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف ) کشیده . برکشیده . بیرون آورده . برآورده . آخته . آهخته . آهنجیده . لنجیده . مسلول . مُشهّر. و رجوع به آهیختن، آهِختن، آختن و آهنجیدن شود.<br /></font></div>'),
(2675, 'آهین', '<span class=\"hlight\">آهین .</span> (اِ) آهن . حدید <span class=\"hlight\">:</span> و معادن، چون مس و برنج و آهین برای آلات را. (کیمیای سعادت ). و این همه را به آلات حاجت افتاد از چوب و آهین و پوست و غیر آن . (کیمیای سعادت ) .<br /></font></div>'),
(2676, 'آو', '<span class=\"hlight\">آو.</span> (اِ) آب <span class=\"hlight\">:</span> <br />کی تواند که همچو ماغ چکاو<br />بزند غوطه در میانه ٔ آو.<br /> <font color=\"Red\">سنائی یا لطیفی ؟</font><br />دستی که جود با کف او آشناوش است <br />دستی که آو در یم او آشناوراست .<br /> <font color=\"Red\">شرف شفروه .</font><br />بیت شرف شفروه شاهد این دعوی نتواند بود، چه آو را آب هم توان خواند بی آنکه تغییری در معنی و وزن راه یابد، لکن فرهنگها بدین گونه نقل کرده اند.<br /></font></div>'),
(2677, 'آوا', '<span class=\"hlight\">آوا.</span> (اِ) مخفف آواز . آواز. بانگ . ندا. آوازه . صوت . (صراح ). آوای . ازمل <span class=\"hlight\">:</span> <br />ای بلبل خوش آوا آوا ده <br />ای ساقی آن قدح رابا ما ده .<br /> <font color=\"Red\">رودکی .</font><br />هزارآوا به بستان در کند اکنون هزارآوا.<br /> <font color=\"Red\">رودکی .</font><br />دمنه را گفتا که تا این بانگ چیست <br />با نهیب و سهم این آوای کیست <br />دمنه گفت اورا جز این آوا دگر<br />کار تو نه (؟) هست و سهمی بیشتر<br />آب هرچه بیشتر نیرو کند<br />بندروغ <font color=\"DarkGreen\"><b>[ ظ: بند و درغ ]</font></b> سست بوده بفکند<br />دل گسسته داری از بانگ بلند<br />رنجگی باشدْت و آزار و گزند.<br /> <font color=\"Red\">رودکی .</font><br />از آن دشت سودابه آوا شنید<br />از ایوان ببام آمد آتش بدید.<br /> <font color=\"Red\">فردوسی .</font><br />از آوای شیپور و هندی درای <br />تو گفتی سپهر اندرآمد ز جای .<br /> <font color=\"Red\">فردوسی .</font><br />بزد بر سپر زود بهزاد گرز<br />به پیچید آواش در کوه برز.<br /> <font color=\"Red\">فردوسی .</font><br />تبیره برآمد ز درگاه طوس <br />همان ناله ٔ بوق و آوای کوس .<br /> <font color=\"Red\">فردوسی .</font><br />چو آمد بگوش اندرش کرّنای <br />دم بوق و آوای هندی درای .<br /> <font color=\"Red\">فردوسی .</font><br />چو خسرو بدانگونه آوا شنید<br />برخساره شد چون گل شنبلید.<br /> <font color=\"Red\">فردوسی .</font><br />چو ده سال شد پادشاهیش راست <br />ز هر کشور آوای بدخواه خاست .<br /> <font color=\"Red\">فردوسی .</font><br />چه آواز نای و چه آواز چنگ <br />خروشیدن بوق و آوای زنگ .<br /> <font color=\"Red\">فردوسی .</font><br />چه بندی دل اندر سرای فسوس <br />که هزمان بگوش آید آوای کوس ؟<br /> <font color=\"Red\">فردوسی .</font><br />برآمد دگرباره بانگ سرود<br />دگرگونه تر ساخت آوای رود<br />همی سبز در سبز خوانی کنون <br />بدینگونه سازند مردان فسون .<br /> <font color=\"Red\">فردوسی .</font><br />خداوند رای و خداوند شرم <br />سخن گفتن خوب و آوای نرم .<br /> <font color=\"Red\">فردوسی .</font><br />ز درگاه برخاست آوای کوس <br />زمین آهنین شد هوا آبنوس .<br /> <font color=\"Red\">فردوسی .</font><br />سپهدار ترکان چو آوا شنود<br />بدانست کآن پهلوانی چه بود.<br /> <font color=\"Red\">فردوسی .</font><br />سپهبد چو از باره آوا شنید<br />نگه کرد و خورشیدرخ را بدید.<br /> <font color=\"Red\">فردوسی .</font><br />کجا آن بتانی پر از ناز و شرم <br />سخن گفتن خوب و آوای نرم .<br /> <font color=\"Red\">فردوسی .</font><br />همانگاه راهب چو آوا شنید<br />فرود آمد از دیر و او را بدید.<br /> <font color=\"Red\">فردوسی .</font><br />ماه و خورشید و کوکبای فلک <br />آتش و آب و خاک و باد صبا<br />همه جمله مسبِّحان تواَند<br />ما ندانیم و نشنویم آوا.<br /> <font color=\"Red\">عنصری .</font><br />جهاندیده ای نام او ذیفنوس <br />که کردی بر آوای بلبل فسوس .<br /> <font color=\"Red\">عنصری .</font><br />شاد باشید که جشن مهرگان آمد<br />بانگ و آوای درای کاروان آمد.<br /> <font color=\"Red\">منوچهری .</font><br />ای روی داده صحبت دنیا را<br />شادان و برفراشته آوا را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />ببانگ خوش گرامی شد سوی مردم هزارآوا<br />وز آن خوار است زاغ ایدون که خوش و خوب نسراید.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چو مر جاهلان را سوی خود نخواند<br />نه بوی نبید و نه آوای زیرم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />قول او را بشنود داناز راه گشتنش <br />گشتنش آواست گر او را چو ما آواستی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از لحن و ز آوای خوش بمانَد<br />در تنگ قفس ها هزاردستان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ز باد فقه و باد فقر دین را هیچ نگشاید<br />میان دربند کاری را که این رنگ است و آن آوا.<br /><font color=\"Red\">سنائی .</font><br />هر صبح سر ز گلشن سودا برآورم <br />وز صور آه، بر فلک آوا برآورم .<br /> <font color=\"Red\">خاقانی .</font><br />از این سراچه ٔآوا و رنگ، پی بگسل <br />بارغوان ده رنگ و بارغنون آوا.<br /> <font color=\"Red\">خاقانی .</font><br />هر آنکو لؤلؤ لفظت ز گوش خود درآویزد<br />بدانسان حق شنو گردد که جز حق نشنود آوا.<br /> <font color=\"Red\">خاقانی ؟</font><br /> <BR><font color=\"Blue\">◄</font> صیت .شهرت . نامبرداری . بلندآوازگی <span class=\"hlight\">:</span> <br />همانا شنیدستی آوای سام <br />نبد در زمانه چنو نیکنام .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> عقیده . رای <span class=\"hlight\">:</span> <br />بدان بی بها ناسزاوار پوست <br />پدید آمد آوای دشمن ز دوست .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوا کردن </span> ؛ خواندن . دعوت . دعاء. طلبیدن <span class=\"hlight\">:</span> <br />تا نام کسی نخست ناموزی <br />در مجمع خلق چون کنیش آوا؟<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوای سرد</span>؛ گفتار زشت <span class=\"hlight\">:</span> <br />بداندیش ما آن کجا گفت و کرد<br />ز کردار ناخوب و آوای سرد<br />چو ما رفته باشیم کیفر برند<br />نه بس روزگار از جهان بر خورند.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">هزارآوا</span> ؛ به معنی هزاردستان، مرکب از هزار و آوای به معنی بانگ و صوت است .<br /></font></div>'),
(2678, 'آواخ', '<span class=\"hlight\">آواخ .</span> (صوت ) آوخ . آه . وای . افسوس . دردا <span class=\"hlight\">:</span> <br />آواخ ز پیمان و ز پیمانه ٔ او.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> (اِ) قسمت . نصیب . (برهان ). <BR><font color=\"Blue\">◄</font> آوای نرم . همس . صوت خفی . حسیس . و رجوع به نرم شود.<br /></font></div>'),
(2679, 'آوادان', '<span class=\"hlight\">آوادان .</span> (ص مرکب ) آبادان .<br /></font></div>'),
(2680, 'آوار', '<span class=\"hlight\">آوار.</span> (اِخ ) نام قومی ازمردم ارال و آلتائی که مدت سه قرن بر اروپا تاختن بردند و در <span class=\"hlight\" dir=\"rtl\">١٦٨</span> هَ .ق . شارلمانْی آنان را دفع کرد.<br /></font></div>'),
(2681, 'آوار', '<span class=\"hlight\">آوار.</span> (ص ) از خانمان و یا وطن و جز آن دورافتاده . دربدر <span class=\"hlight\">:</span> <br />لجاج ومشغله ماغاز تا سخن گویم <br />که ما ز مشغله ٔ تو ز خانه آواریم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بمن سپرد و ز من بستدند فرعونان <br />شدم بعجز و ضرورت ز خانمان آوار.<br /> <font color=\"Red\">مسعودسعد.</font><br />تو بادی و من خاک تو تو آب و من خاشاک تو<br />با خوی آتشناک تو صبر من آوار آمده .<br /> <font color=\"Red\">خاقانی .</font><br />آنچه بر من ز دل و دلدار است <br />چون دهم شرح ؟ که بس بسیار است <br />گر تن است از در او محروم است <br />ور دل است از بر من آوار است .<br /> <font color=\"Red\">اثیر اخسیکتی .</font><br />ای گشته ز صبح آفرینت <br />از من شب بینوائی آوار.<br /> <font color=\"Red\">عمادی شهریاری .</font><br />آه کز بیم رستم اجل است <br />خیل افراسیاب عمر آوار.<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوار کردن </span> ؛ بیرون کردن . اخراج . نفی کردن . جلا دادن <span class=\"hlight\">:</span> <br />چو کرد خواهد مر بچه را مرشح شیر<br />ز مرغزار نه از دشمنی کند آوار.<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br />پلنگان را درآوردن ز کهسار<br />گوزنان را ز بیشه کردن آوار.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />شکوه تاج کیان وارث ممالک جم <br />که ازممالکش آوار کرده است آوار. <br /> <font color=\"Red\">اسدی (از فرهنگ، خطی ).</font><br />مکر و حسد را زدل آوار کن <br />این تن خفته ت را بیدار کن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />جای مهر تو دلست ای دلت از مهر تهی <br />پس دلم را ز تن آوار مکن گو نکنم .<br /><font color=\"Red\">مسعودسعد.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بی آوار</span> ؛ برخلاف قاعده <span class=\"hlight\">:</span> <br />من بچه کارم خدای را که ببایست <br />کردن چندین هزار کار بی آوار؟<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) هرج و مرج . بی حسابی . بلبشوئی . فساد. فتنه <span class=\"hlight\">:</span> <br />خشم گیری جنگ جوئی چون بمانی از جواب <br />خشم یک سو نه سخن گستر که شهر آوار نیست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کار فردا بعدل خواهد بود<br />گرچه امروز کار به آوار است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از فعل بد خسان این امت <br />ناگاه چنین بخاست آواری .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> ریزه ٔ آهن که هنگام سوراخ کردن نعل بیفتد. <BR><font color=\"Blue\">◄</font> آزار. رنج <span class=\"hlight\">:</span> <br />نپیچد دلت بر چنین کارها<br />بدین رنج و تیمار و آوارها.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> خراب . ویران . برافتاده . مقابل آباد و عامر <span class=\"hlight\">:</span> <br />هزار بتکده آوار کرده هر یک از او<br />هزار شیر درنده بقهر کرده شکار.<br /> <font color=\"Red\">غضایری رازی .</font><br /> <BR><font color=\"Blue\">◄</font> گرد وخاک و غبار <span class=\"hlight\">:</span> <br />ز گرد سپه روز روشن نماند<br />ز نیزه هوا جز بجوشن نماند<br />از آوار اسبان و گرد سپاه <br />بشد روشنائی ز خورشید و ماه .<br /> <font color=\"Red\">فردوسی .</font><br />هرگه که مجرّه را ببینم <br />گسترده بروی چرخ آوار<br />گویم که ز بهر اسب قدرت <br />بر گردون کرده اند افسار.<br /> <font color=\"Red\">عمادی شهریاری .</font><br /> <BR><font color=\"Blue\">◄</font> یقین . آور. <BR><font color=\"Blue\">◄</font> غارت . اغاره . چپاول . یغما <span class=\"hlight\">:</span> <br />نگار خویش را در برگرفتم <br />خزینه ٔ بوسه ٔ او کردم آوار.<br /> <font color=\"Red\">فرخی .</font><br />باد گوئی نافه های تبتستان بردرید<br />باغ گوئی کاروان شوشتر آوار کرد.<br /> <font color=\"Red\">فرخی .</font><br />تا سایه ٔ او دور شد از دولت محمود<br />دیدی که جهان بر چه نمط بود و چه کردار<br />لشکر بخروش آمده و ملک بجنبش <br />وز روی دگر گشته خزینه همه آوار.<br /> <font color=\"Red\">فرخی .</font><br />انگشتری جم برسیده ست بجم باز<br />وز دیو نگون اختر برده شده آوار.<br /> <font color=\"Red\">منوچهری .</font><br />ز گیهان مر ترا خواهد بناچار<br />ازیرا کش تو دل بردی به آوار.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />خاک ره پر نافه ٔ مشک است از آنک <br />موکب زلفت به آوار آمده .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> آنچه فروریزد از افتادن خانه ای از خاک و سنگ و آجر و گچ و تیر و تخته و جز آن . و عامّه آن را هوار گویند: زیر آوار ماندن . <BR><font color=\"Blue\">◄</font> آمار. آماره . آواره . حساب . شماره . اَماره . اوارجه <span class=\"hlight\">:</span> <br />خردمند بااهل دنیا برغبت <br />نه صحبت نه کار و نه آوار دارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> آزار. ستم . (برهان ). جور.هرج و مرج . شلوغی . بی حسابی <span class=\"hlight\">:</span> <br />شکوه تاج کیان وارث ممالک جم <br />که از ممالکش آوار کرده است آوار.<br /> <font color=\"Red\">اسدی (از فرهنگ ).</font><br />نیست در ملک عدل تو مظلوم <br />نیست در عدل ملک تو آوار.<br /><font color=\"Red\">ابوالفرج رونی .</font><br /></font></div>'),
(2682, 'آوارجه', '<span class=\"hlight\">آوارجه .</span> <font color=\"DarkGreen\"><b>[ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ ]</font></b> (اِ) آوارچه . روزنامه و فرد حساب یومیه . (بهار عجم ). گمان میکنم این کلمه مصحف اَوارِجه معرّب اواره است : الاوارجه ؛ من کتب اصحاب الدواوین فی الخراج و نحوه . (فیروزآبادی : وَرَج ). الاوارجه من کتب اصحاب الدواوین، معرّب آواره ای الناقل، لأنّه ینقل الیها الانجیذج، الذی یثبت فیه ما علی کل ّ انسان، ثم ینقل الی جریدة الاخراجات و هی عِدّة اوارجات . (فیروزآبادی : ارَج ). رجوع به اَواره و اوارجه شود.<br /></font></div>'),
(2683, 'آواره', '<span class=\"hlight\">آواره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص ) آوار. از وطن دورافتاده . سرگردان . دَربِدر. غریب <span class=\"hlight\">:</span> <br />ایا گم شده بخت و بیچارگان <br />همه زار و غم خوار و آوارگان .<br /> <font color=\"Red\">فردوسی .</font><br />که آواره ٔ بدنشان رستم است <br />که از روز شادیش بهره کم است ...<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت کز خانه آواره ام <br />از ایران یکی مرد بیواره ام .<br /> <font color=\"Red\">اسدی .</font><br />نام و صیتت رونده همچو مثل <br />خصمت آواره در جهان چو سمر.<br /> <font color=\"Red\">شرف شفروه .</font><br />ما و مجنون همسفر بودیم در دشت جنون <br />او بمطلب ها رسید و ما هنوز آواره ایم .<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> از وطن بیرون کرده . مُبعد. اخراج شده . منفی از بلد. مجلوّ از وطن <span class=\"hlight\">:</span> <br />ترا از خان مان آواره کردند<br />مرا بی دختر وبیچاره کردند.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />ور دوستارآل رسولی تو<br />از خانمان کنندت آواره .<br /> <font color=\"Red\">ناصرخسرو.</font><br />محمدبن زید را با حشم به کهستان اِصفهبد فرستاد و او را آواره کردند بیچاره شد هر روز برای اَمان قاصد میفرستاد. (تاریخ طبرستان ).<br /> <BR><font color=\"Blue\">◄</font> گم گردیده . بی نام ونشان <span class=\"hlight\">:</span> <br />نشانی ندادش کس اندر جهان <br />بدانگونه آواره شد ناگهان .<br /> <font color=\"Red\">فردوسی .</font><br />بباید چو جمشید آواره گشت <br />که بنْهیم سر جمله در کوه و دشت .<br /> <font color=\"Red\">فردوسی .</font><br />آواره ٔطلب را خضر است هر گیاهی <br />کشتی شکستگان را هر موج ناخدائیست .<br /> <font color=\"Red\">صائب .</font><br /> <BR><font color=\"Blue\">◄</font> گریخته <span class=\"hlight\">:</span> <br />یکی داستان زد گَوی از نخست <br />که پرمایه آنکس که دشمن نجست <br />چو بدخواه پیش آیدت کشته به <br />گر <font color=\"DarkGreen\"><b>[ یعنی یا ]</font></b> از جنگ آواره برگشته به .<br /> <font color=\"Red\">فردوسی .</font><br />به دُم ّ گریزندگان شب مپوی <br />چو دشمن شد آواره بیشش مجوی .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> پراکنده . پریشان . متفرق . گریزان . گریزانده . رانده . تار و مار <span class=\"hlight\">:</span> دیالم گفتند این جایگاه نیکوست ما را دستوری ده تا اول بر پیادگان اصفهبد قارن زنیم ایشان را برداریم که در این موضع چون پیاده شکسته شود سوار هیچ بدست ندارد. حسن زید رخصت داد بیامدند و پیاده را آواره کرده و چیرگی یافته و ... (تاریخ طبرستان ). چون وشمگیر خبر یافت ناگاه تاختن بسر ایشان برد و آواره گردانید. (تاریخ طبرستان ). و اصفهبد علاءالدوله حسن را با جمله حشم بشکست و آواره کرد. (تاریخ طبرستان ). <BR><font color=\"Blue\">◄</font> خراب، مقابل آباد <span class=\"hlight\">:</span> و گفتند این چیست تو میکنی بهرزه ولایت خویشتن خراب و آواره کردی و با چندان حق که سلطان با تو دارد عصیان پیش گرفتی . (تاریخ طبرستان ). <BR><font color=\"Blue\">◄</font> (اِ) ظلم . ستم . آزار. <BR><font color=\"Blue\">◄</font> تحقیق . یقین . (برهان ). <BR><font color=\"Blue\">◄</font> آهن ریزه که هنگام سوراخ کردن نعل اسب و استر و مانند آن از نعل بیفتد. (برهان ). <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواره ٔ افلاک </span> ؛ عرش . (بنقل مؤید از ادات ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواره بردن </span> ؛ بغربت بردن . سَبْی . اَسر <span class=\"hlight\">:</span> <br />چو دایه شد ز کار ویس آگاه <br />که چون آواره برد او را شهنشاه <br />جهان تاریک شد در دیدگانش ...<br /> <font color=\"Red\">(ویس و رامین ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواره شدن </span> ؛ دور شدن . گم شدن . ضایع شدن <span class=\"hlight\">:</span> <br />ز لشکر جهاندیدگان را بخواند<br />همه گفتنی پیش ایشان براند<br />ببینید گفت اینکه گشتاسب کرد<br />دلم کرد پردرد و سر پر ز گرد<br />بپروردمش تابرآورد یال <br />شد اندر جهان سرور بی همال <br />بدانگه که گفتم که آمد ببار<br />ز باغ من آواره شد میوه دار.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواره شدن (گردیدن ) از تخت و گاه </span> ؛ از سلطنت دورماندن . از تاج و تخت ماندن <span class=\"hlight\">:</span> <br />بایرانیان گفت پیروز شاه <font color=\"DarkGreen\"><b>[ کیخسرو ]</font></b><br />که دشمن چو آواره گردد ز گاه <br />ز گیتی بر او نام و کام اندکیست <br />ورا مرگ با زندگانی یکیست .<br /> <font color=\"Red\">فردوسی .</font><BR>۩ از خانمان و وطن دور ماندن . سر در جهان نهادن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواره شو!</span> ؛ گم شو!<br /></font></div>'),
(2684, 'آواره', '<span class=\"hlight\">آواره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) حساب . دفتر حساب . اوارجه . آمار. آماره . آوار که حسابهای پراکنده ٔ دیوانی در آن نویسند <span class=\"hlight\">:</span> <br />بس دیر نمانده ست که ملک ملکان را<br />آرند بدیوان تو آواره و دفتر.<br /><font color=\"Red\">معزی .</font><br /></font></div>'),
(2685, 'آواره کردن', '<span class=\"hlight\">آواره کردن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ک َ دَ ]</font></b> (مص مرکب ) بیرون کردن . اخراج . تبعید کردن . جلاء دادن .<br /></font></div>'),
(2686, 'آواره گیر', '<span class=\"hlight\">آواره گیر.</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب ) آواره گیره . محاسب .<br /></font></div>'),
(2687, 'آوارگی', '<span class=\"hlight\">آوارگی .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (حامص ) جلا. بی خانمانی و بی منزلی . دورافتادگی از خانمان . حال ِ آنکه جای معین و وطن معلوم ندارد و در صحراها و یاقراء با سختی معیشت از جائی بجائی رود <span class=\"hlight\">:</span> <br />یار آوارگی همی خواهد<br />رفتن حج بهانه افتاده ست <br />چند گوئی ز خانه ٔ کعبه <br />کار با خصم خانه افتاده ست .<br /> <font color=\"Red\">حسن دهلوی .</font><br />سر اندر جهان نِه ْ به آوارگی <br />وگرنه بنه دل به بیچارگی .<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> سرگردانی . پریشانی .<br /></font></div>'),
(2688, 'آوارگیر', '<span class=\"hlight\">آوارگیر.</span> (نف مرکب ) آواره گیر. آمارگیر. آماره گیر. محاسب .<br /></font></div>'),
(2689, 'آواری', '<span class=\"hlight\">آواری .</span> (حامص ) آوارگی . <BR><font color=\"Blue\">◄</font> (اِ) خاکها و سنگهای توده از خرد شدن و فروریختن کوه .<br /></font></div>'),
(2690, 'آوارین', '<span class=\"hlight\">آوارین .</span> (اِخ ) نام محلّی در حدّ غربی ایران، نزدیک کوه کلاعه بساحل سیروان .<br /></font></div>'),
(2691, 'آواز', '<span class=\"hlight\">آواز.</span> (اِ) آوا. صوت . (صراح ). بانگ <span class=\"hlight\">:</span> <br />از آواز کوسش همی روز جنگ <br />بدرّد دل شیر و چرم پلنگ .<br /><font color=\"Red\">فردوسی .</font><br />چو بشنید آواز او را تبرگ <br />بر آن اسب جنگی چو شیر سترگ .<br /> <font color=\"Red\">فردوسی .</font><br />خور جادوان بد چو رستم رسید<br />از آواز او دیو شد ناپدید.<br /> <font color=\"Red\">فردوسی .</font><br />پرستنده بشنید آواز اوی <br />ندانست کودک همی راز اوی .<br /> <font color=\"Red\">فردوسی .</font><br />چو بشنید کرکوی آواز من <br />همان زخم کوپال سریاز من .<br /> <font color=\"Red\">فردوسی .</font><br />اگر یار باشید با من بجنگ <br />ز آواز روبه نترسد پلنگ .<br /> <font color=\"Red\">فردوسی .</font><br />چو برخیزد آواز طبل رحیل <br />به خاک اندر آید سر شیر و پیل .<br /> <font color=\"Red\">فردوسی .</font><br />زنالیدن بوق و بانگ سرود<br />هوا گشت از آواز بی تار و پود.<br /><font color=\"Red\">فردوسی .</font><br />بخفت آن شب و بامداد پگاه <br />از آواز او چشم بگشاد شاه .<br /> <font color=\"Red\">فردوسی .</font><br />برادر چو آواز خواهر شنید<br />ز گفتار و پاسخ فروآرمید.<br /> <font color=\"Red\">فردوسی .</font><br />چو برداری میان شورم آواز<br />مر آواز تو را پاسخ دهد باز.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />من قوم خویش را گفتم تا بدهلیز بنشینند و گوش به آوازمن دارند. (تاریخ بیهقی ). امیر آواز ابواحمد بشنویدبیگانه پوشیده نگاه کرد مردی را دید هیچ نگفت تا حدیث تمام کرد. (تاریخ بیهقی ).<br />کرّ شود باطل از آواز حق <br />کور کند چشم خطا را صواب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آواز گلوی بخت شوم آز است <br />تو فتنه شده بر این بد آوازی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />با قوی گوی اگر بگوئی راز<br />زآنکه باشد قوی ضعیف آواز.<br /> <font color=\"Red\">سنائی .</font><br />گمان می برم که قوت و ترکیب صاحب آن فراخور آواز باشد. (کلیله و دمنه ). دمنه گفت جز این آواز ملک را ریبتی بوده است . (کلیله و دمنه ). تو چنانکه آواز ترا بشنوند با من در سخن آی . (کلیله و دمنه ). گاوی دیدم که آواز او بگوش ملک میرسید. (کلیله و دمنه ). هرگز <font color=\"DarkGreen\"><b>[ شیر ]</font></b> گاو ندیده بود و آواز او نشنوده . (کلیله و دمنه ). آواز سهمناک بگوش روباه آمدی . (کلیله و دمنه ). گفت سبب آن آواز است که میشنوی . (کلیله و دمنه ). آفت عقل تصلف است و آفت دل ضعیف آواز قوی . (کلیله و دمنه ). آواز برخاست که بطان سنگ پشت را می برند. (کلیله و دمنه ).<br />تو چنگال شیران کجا دیده ای <br />که آواز روباه نشنیده ای .<br /> <font color=\"Red\">؟(از مرزبان نامه ).</font><br />عاشقان کشتگان معشوقند<br />برنیاید ز کشتگان آواز.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> خروش . فریاد. آوای بلند. بانگ بلند. ژخ . نعره <span class=\"hlight\">:</span> <br />به آواز گفتند ما کهتریم <br />ز رای و ز فرمان تو نگذریم .<br /> <font color=\"Red\">فردوسی .</font><br />به آواز گفت آن زمان شهریار<br />که جز پاک یزدان مدانید یار.<br /> <font color=\"Red\">فردوسی .</font><br />بخندیدرستم به آواز گفت <br />که بنشین به پیش گرانمایه جفت .<br /> <font color=\"Red\">فردوسی .</font><br />به آوازگفتند تا زنده ایم <br />خود اندر جهان شاه را بنده ایم .<br /> <font color=\"Red\">فردوسی .</font><br />به آواز گفت آن زمان شهریار<br />که ای نامداران به روزگار.<br /> <font color=\"Red\">فردوسی .</font><br />به آواز گفتند ما بنده ایم <br />بدل مهربان و پرستنده ایم .<br /> <font color=\"Red\">فردوسی .</font><br />به آواز گفتند کای سرفراز<br />غم و شادمانی نماند دراز.<br /> <font color=\"Red\">فردوسی .</font><br />بگفت این و از دیده آواز خاست <br />که ای شاه نیک اختر دادراست <br />یکی گرد تیره برآمد ز راه <br />درفشی درفشان میان سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />به آواز گفتند کای شهریار<br />مبیناد چشمت بد روزگار.<br /> <font color=\"Red\">فردوسی .</font><br />چو دیدی کم ِ شاه اندر نبرد<br />به آواز گفتی که ای شاه بَرْد!<br /> <font color=\"Red\">فردوسی .</font><br />سیاوش برِ شمعتیغی بدست <br />به آواز گفتی نشاید نشست .<br /> <font color=\"Red\">فردوسی .</font><br />نگه کرد یک تن به آواز گفت <br />که صندوق را چیست اندر نهفت ؟<br /> <font color=\"Red\">فردوسی .</font><br />پراندیشه شد جان سیندخت از اوی <br />به آواز گفت از کجائی بگوی .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد بدان تیره آوردگاه <br />به آواز گفت ای گزیده سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />سوم بهره را سوی خود بازداشت <br />که چون ابر غرّنده آواز داشت .<br /> <font color=\"Red\">فردوسی .</font><br />به آواز گفتا پس آن نامدار<br />که گر رخصتم بودی از شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />به آواز گفت آن زمان گرگسار<br />که ای نامور فرخ اسفندیار.<br /> <font color=\"Red\">فردوسی .</font><br />به آواز گفت آن زمان شهریار<br />چه بود ای دلیران و مردان کار.<br /> <font color=\"Red\">فردوسی .</font><br />از ایوان از آن پس خروش آمدی <br />کز آواز دلها بجوش آمدی <br />که ای زیردستان شاه جهان <br />مباشید تیره دل و بدنهان .<br /> <font color=\"Red\">فردوسی .</font><br />جوانان به آواز گفتند زود<br />عنان و رکابت بباید بسود.<br /> <font color=\"Red\">فردوسی .</font><br />ز آواز کوپال بر ترک و خود<br />همی داد گردون زمین را درود.<br /> <font color=\"Red\">فردوسی .</font><br />شنید آنهمه لشکر آواز شاه <br />بسر برنهادند زآهن کلاه .<br /> <font color=\"Red\">فردوسی .</font><br />ای آنکه همی بلعنت من <br />آواز برآسمان رسانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> خواندن . صوت، اعم از نیک و بد <span class=\"hlight\">:</span> <br />یک مؤذن داشت یک آواز بد<br />شب همه شب میدریدی حلق خود...<br />وآن مؤذن عاشق آواز خود<br />در میان کافرستان بانگ زد...<br />راحتم این بود از آواز او<br />هدیه آوردم بشکر آن مرد کو؟<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> هتف . ندای غیب . سروش <span class=\"hlight\">:</span> <br />سه بار این هم آواز آمد بگوش <br />شگفتی دلش تنگ شد زآن خروش .<br /> <font color=\"Red\">فردوسی .</font><br />بکردند چون او بفرمودشان <br />چنان هم که آواز بنمودشان .<br /> <font color=\"Red\">فردوسی .</font><br />آنکس که همی گوید کآواز شنیدی <br />مندیش از آن جاهل و منیوش محالش .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> نام . <BR><font color=\"Blue\">◄</font> دعوی بی معنی . بی برهان . اُشتلم <span class=\"hlight\">:</span> <br />معنی از قول، علی دارد آواز جز او<br />مرد باید کز تقصیر بداند توفیر<br />تو به آواز چرا میرمی از شیر خدای <br />چون پی شیر نگیری ّ و نباشی نخجیر؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />صدق و معنی باش و از آواز و دعوی باز گرد<br />رایض استاد داند شیهه ٔ زاد از زغن .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> خبر. آگاهی . آوازه . حکایت . روایت . حدیث <span class=\"hlight\">:</span> <br />چو گفتی ندارم ز شاه آگهی <br />تنش را ز جان زود کردی تهی ...<br />بدان تا نداند کسی راز اوی <br />همان نشنود نام و آواز اوی .<br /> <font color=\"Red\">فردوسی .</font><br />بخواهم گشادن یکی راز خویش <br />نهان دارم از لشکر آواز خویش .<br /> <font color=\"Red\">فردوسی .</font><br />بگیتی از او <font color=\"DarkGreen\"><b>[ از افراسیاب ]</font></b> نام و آواز نیست <br />ز من راز باشد ز تو راز نیست .<br /> <font color=\"Red\">فردوسی .</font><br />هر آن پادشا کو کشیدی بجنگ <br />چو رفتی سپاهش برِ کرم تنگ <br />شکسته شدی لشکرش کآمدی <br />چو آواز این داستان بشندی .<br /> <font color=\"Red\">فردوسی .</font><br />همی گفت با پیرزن راز خویش <br />نهان کرده از هر کس آواز خویش .<br /> <font color=\"Red\">فردوسی .</font><br />ز هر گونه ای هست آواز این <br />نداند بجز پرخردراز این .<br /> <font color=\"Red\">فردوسی .</font><br />سراسر همه روم گریان شدند<br />وز آواز شاپور بریان شدند.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> آوازه . صیت . شهرت . نام آوری . ذِکر <span class=\"hlight\">:</span> <br />بپرسش گرفتی همه راز اوی <br />ز نیک و بد و نام و آواز اوی <br />ز داد و ز بیداد و از کشورش <br />ز آئین و از شاه و از لشکرش .<br /> <font color=\"Red\">فردوسی .</font><br />وزآن پس پرآواز گردد جهان <br />شود نام و آواز او در نهان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> شکوه . رونق . اعتلاء <span class=\"hlight\">:</span> <br />چو زنار قسیس شد سوخته <br />چلیپای مطران برافروخته <br />کنون روم و قنوج ما را یکیست <br />چو آواز کیش مسیح اندکیست .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> قول . رای . عقیده . <BR><font color=\"Blue\">◄</font> نغمه . (ربنجنی ) (وطواط). آوازه . صوت حسن . غِناء. تغنی . خواندن . آهنگ . لحن . دهاز <span class=\"hlight\">:</span> <br />نهاده بر او <font color=\"DarkGreen\"><b>[ بر گاه ]</font></b> نامه ٔ زند و اُست <br />به آواز برخواند موبد درست .<br /> <font color=\"Red\">فردوسی .</font><br />سرودی به آواز خوش برکشید<br />که اکنونْش خوانی تو داد آفرید.<br /> <font color=\"Red\">فردوسی .</font><br />سراینده ٔ این غزل ساز کرد<br />دف و چنگ و نی را هم آواز کرد.<br /> <font color=\"Red\">فردوسی .</font><br />زمین باغ گشت از کران تا کران <br />زشادی ّ و آواز رامشگران .<br /> <font color=\"Red\">فردوسی .</font><br />هر کسی زآواز خود شد پرغرور<br />لیک این ختم است بر صاحب زبور.<br /> <font color=\"Red\">عطار.</font><br />همه عالم جمال و آواز است <br />چشم کور است و گوش کر چه کنم ؟<br /> <font color=\"Red\">عطار.</font><br />کی بود آواز چنگ از زیر و بم <br />ازبرای گوش بی حس ّ و اصم ؟<br /> <font color=\"Red\">مولوی .</font><br />بِه ْ از روی خوب است آواز خوش <br />که این حظّ نفس است و آن قوت روح .<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /> <BR><font color=\"Blue\">◄</font> سجع. هدیر و جز آن <span class=\"hlight\">:</span> <br />هر کجا باغی بود آنجا بود آواز مرغ .<br /> <font color=\"Red\">منوچهری .</font><br />ز خاموشی است در دست شهان باز<br />که بلبل در قفس ماند ز آواز.<br /> <font color=\"Red\">عطار.</font><br />مطرب ما را دردی است که خوش می نالد<br />مرغ عاشق طرب انگیز بود آوازش .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> سَمَر. مشهور. مشتهر. شُهره <span class=\"hlight\">:</span> <br />گهی گفتی که گر من بازگردم <br />بزشتی در جهان آواز گردم .<br /> <font color=\"Red\">(ویس ورامین ).</font><br />اگر نومید از این در بازگردم <br />بزشتی در جهان آواز گردم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> مشهور به بدی . بدنام <span class=\"hlight\">:</span> <br />گهی گفتی هم اکنون بازگردم <br />بهل تا در جهان آواز گردم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> آمین <span class=\"hlight\">:</span> <br />دوش از بخت شنیدم خبر وصل ترا<br />من دعاکردم و از شش جهت آواز آمد.<br /> <font color=\"Red\">علی خراسانی .</font><br /> <BR><font color=\"Blue\">◄</font> تیپ و تیپچه . تیپچه <span class=\"hlight\">:</span> وی فرموده بود آوازها ساخته بودند از بهر حواصل گرفتن و دیگر مرغان . (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواز اسب </span> ؛ صَهیل . شنه . شیهه <span class=\"hlight\">:</span> <br />از آواز اسبان و غوّ سپاه <br />همی بر فلک راه گم کرده ماه .<br /> <font color=\"Red\">فردوسی .</font><br />غو نای و آواز اسبان ز دشت <br />تو گفتی همی از هوا برگذشت .<br /> <font color=\"Red\">فردوسی .</font><br />ز آواز اسبان و بانگ سپاه <br />بیابان همی جست بر کوه راه .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواز برآوردن </span> ؛ برکشیدن صوت . خواندن جهر. (دهار). اهلال <span class=\"hlight\">:</span> و آوازی برآورد که مرغ از هوا درآورد. (گلستان ).<br />غزلسرائی ناهید صرفه ای نبرد<br />در آن مقام که حافظ برآورد آواز.<br /> <font color=\"Red\">حافظ.</font><BR>۩ بانگ برآوردن . صیحه زدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواز برکشیدن </span> ؛ با صوت عالی خواندن <span class=\"hlight\">:</span> <br />صبا بمقدم گل راح و روح بخشد باز<br />کجاست بلبل خوشگو که برکشد آواز؟<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواز خواندن </span> ؛ تغنّی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواز دادن </span> ؛ نداء. ندا کردن . خواندن . فراخواندن . تأذین . دعوت . آوا برآوردن <span class=\"hlight\">:</span> <br />آهو از دام اندرون آواز داد<br />پاسخ گرزه بدانش بازداد.<br /><font color=\"Red\">رودکی .</font><br />ز قلب سیه ویسه آواز داد<br />که شد تخت و تاج بزرگی بباد.<br /> <font color=\"Red\">فردوسی .</font><br />غمین گشت کاووس و آواز داد<br />که ای نامداران فرخ نژاد.<br /> <font color=\"Red\">فردوسی .</font><br />به نزدیک دَیر آمد آواز داد<br />که این جایگه کیست از بخت شاد؟<br /> <font color=\"Red\">فردوسی .</font><br />بدان لشکر فرخ آواز داد<br />گو پیلتن شاه خسرونژاد.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد گرازان بدرگاه سام <br />نه آواز داد و نه برگفت نام .<br /> <font color=\"Red\">فردوسی .</font><br />زن مهتر از پرده آواز داد<br />که ای شاه پیروز بادی ّ و شاد.<br /> <font color=\"Red\">فردوسی .</font><br />فرامرز آنگاه آواز داد<br />چو دیدش که گردون ورا ساز داد.<br /> <font color=\"Red\">فردوسی .</font><br />یک روز <font color=\"DarkGreen\"><b>[ امیر مسعودبن محمود غزنوی ]</font></b> از بام جده ٔ مرا بخواند و آوازداد چون به نزدیک وی رسید گفت ... (تاریخ بیهقی ). بوعبداﷲ را آواز داد تا بازگشت و خالی کردند. (تاریخ بیهقی ). آواز دادم بخدمتکاران تا شمع برافروختند و بگرمابه رفتم . (تاریخ بیهقی ). مرا که بونصرم آواز داد و گفت چون خواجه بازگردد تو بازآی . (تاریخ بیهقی ). امیر آواز داد که چیست ؟ گفتم بونصر پیغامی داده و رقعه بنمودم . (تاریخ بیهقی ). امیر غلامان را آواز داد غلامی که وی را قماشی گفتندی ... درآمد. (تاریخ بیهقی ). اگر آواز دادی که بار دهید دیگران درآمدندی . (تاریخ بیهقی ). حجام آواز داد. (کلیله و دمنه ). بطان آواز دادند که بر دوستان نصیحت باشد. (کلیله و دمنه ).<BR>۩ اعلان کردن . منادی کردن . اعلام کردن . اذان . اطلاع دادن <span class=\"hlight\">:</span> <br />چو جائی بپوشد زمین را ملخ <br />برو سبزه ٔ کشتمندان به شخ <br />تو از گنج تاوان آن بازده <br />بکشور ز فرمانم آواز ده .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواز درای </span> ؛ بانگ جرس <span class=\"hlight\">:</span> <br />کی بود نغمه ٔ داود چو آواز درای ؟<br /> <font color=\"Red\">شرف شفروه .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواز شمشیر و دیگر سلاح ها و آواز زخم آن </span> ؛ صلیل . قعقعه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواز کردن </span> ؛ آواز دادن . خواندن . نداء. تصویت <span class=\"hlight\">:</span> <br />بگردان لشکرْش آواز کرد<br />که ای نامداران و مردان مرد.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواز گردانیدن </span> ؛ تحریر. ترنیم . تغرّد. تغرید.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آواز گشتن </span> ؛ مشهور شدن .<BR>۩ مجازاً، مُردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">برآوازِ</span> ؛ بنام ِ <span class=\"hlight\">:</span> <br />ببستند <font color=\"DarkGreen\"><b>[ در روم ]</font></b> آذین به بیراه و راه <br />برآواز شیروی پرویزشاه <br />برآمد هم آواز رامشگران <br />همه شهر روم از کران تا کران .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به یک آواز</span> ؛ هم آواز. همگی با یک صوت . همزبان <span class=\"hlight\">:</span> وحوش و طیور و سباع دید بیک جاجمع شده او را عجب آمد به یک آواز او را گفتند بزبانهای فصیح بسخن آدمی که ... (تاریخ سیستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دوآواز شدن </span> ؛ اختلاف کلمه پیدا کردن <span class=\"hlight\">:</span> <br />دوآواز شد رومی و پارسی <br />سخنْشان ز تابوت شد یک بسی <br />هر آنکس که او پارسی بود گفت <br />که او را جز ایران نباید نهفت ...<br />چنین گفت رومی یکی رهنمای <br />که ایدر نهفتن ورا نیست رای .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">هم آواز</span> ؛ هم عقیده <span class=\"hlight\">:</span> <br />هم آواز گشتند با یکدگر<br />سپه را سوی بربر آمد گذر.<br /> <font color=\"Red\">فردوسی .</font><br />چنین است پیران و این راز نیست <br />که این پیر با ما هم آواز نیست .<br /> <font color=\"Red\">فردوسی .</font><br />ای بر احدیّتت ز آغاز<br />خلق ازل و ابد هم آواز.<br /> <font color=\"Red\">مکتبی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">هم آواز شدن با راه </span> ؛ براه افتادن . راه پیش گرفتن <span class=\"hlight\">:</span> <br />چو با راه رستم هم آواز گشت <br />سپهدار <font color=\"DarkGreen\"><b>[ کیخسرو ]</font></b> از آن جایگه بازگشت .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">آواز دهل شنیدن از دور خوش است </span> ؛ پاره ای شهرتهای نیک را حقیقت و اصلی نباشد.<br /></font></div>'),
(2692, 'آوازجو', '<span class=\"hlight\">آوازجو.</span> (نف مرکب ) شهرت طلب <span class=\"hlight\">:</span> <br />از این لافندگان وآوازجویان بگذر ای حجت <br />که تو مرد حق و زهدی نه مرد لاف و آوازی .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(2693, 'آوازدهنده', '<span class=\"hlight\">آوازدهنده .</span> <font color=\"DarkGreen\"><b>[ دَ هََ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) هاتف . (دهار).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2694, 'آوازه', '<span class=\"hlight\">آوازه .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ) آوا. آواز. صوت <span class=\"hlight\">:</span> <br />دل چو خم چند برآوازه نهی <br />ناید آواز جز از خم ّ تهی .<br /> <font color=\"Red\">جامی .</font><br />مشو غافل ز گردیدن که روزی در قدم باشد<br />همین آوازه می آید ز سنگ آسیا بیرون .<br /> <font color=\"Red\">صائب .</font><br /> <BR><font color=\"Blue\">◄</font> خبر. آگاهی . اطلاع <span class=\"hlight\">:</span> <br />بدین آوازه هرجائی که شاهیست <br />بغایت ناشکیب و بی قرار است .<br /> <font color=\"Red\">مسعودسعد.</font><br />ناگه یارم بی خبر و آوازه <br />آمد بر من بلطف بی اندازه <br />گفتم که چو ناگه آمدی عیب مکن <br />چشم تر و نان خشک و روی تازه .<br /> <font color=\"Red\">محمدبن یحیی ̍.</font><br /> <BR><font color=\"Blue\">◄</font> صیت و شهرت مطلق . ذکر. چاو. (زمخشری ). چَو <span class=\"hlight\">:</span> <br />بر اینگونه بر نام وآوازه رفت <br />ازیرا که او را پسر بود هفت .<br /> <font color=\"Red\">فردوسی .</font><br />و نام و آوازه ٔ عهد همایون ... بر امتداد ایام و مخلد گردانید. (کلیله و دمنه ).<br />آوازه فراخ شد بعالم <br />درگاه تو را به تنگ باری .<br /> <font color=\"Red\">خاقانی .</font><br />در آن سال آوازه بود. (تاریخ طبرستان ). و هم در آن مدت آوازه افتاد که خوارزمشاه ... فرمان یافت . (تاریخ طبرستان ).<br />چو بهمن بزابلستان خواست شد<br />چپ افکند آوازه وز راست شد.<br /> <font color=\"Red\">سعدی .</font><br />بنیکی و بدی آوازه در بسیط جهان <br />سه کس برند، غریب و رسول و بازرگان .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> شهرت نیک . صیت و ذکر جمیل . نام نیک .نام آوری . نام <span class=\"hlight\">:</span> <br />مر او را سزد گر گواهی دهند<br />که معنی ّ و آوازه اش همرهند.<br /> <font color=\"Red\">سعدی .</font><br />که حاتم بدان نام و آوازه خواست <br />ترا سعی و جهد ازبرای خداست .<br /> <font color=\"Red\">سعدی .</font><br />ور آوازه خواهی در اقلیم فاش <br />برون حله کن گو درون حشو باش .<br /> <font color=\"Red\">سعدی .</font><br />فضل باید برای آوازه <br />اصل ناید برون ز دروازه .<br /> <font color=\"Red\">مکتبی .</font><br /> <BR><font color=\"Blue\">◄</font> شهرت بد. بدنامی <span class=\"hlight\">:</span> <br />زنامهربانی که در دورتست <br />همه عالم آوازه ٔ جور تست .<br /> <font color=\"Red\">سعدی .</font><br />کی آنجا دگر هوشمندان روند<br />چو آوازه ٔ رسم بد بشنوند؟<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> غناء. نوا. سرود. صوت حسن . <BR><font color=\"Blue\">◄</font> زمزمه . <BR><font color=\"Blue\">◄</font> نغمه . آهنگ . لحن . آواز.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوازه خوان </span> ؛ مغنی . مغنیه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوازه شدن </span> ؛ مشهور گشتن . مایه ٔ عبرت گشتن <span class=\"hlight\">:</span> فان گفت هرگز مباد که من بر ملک برتری جویم و ترا چون بنده ام ایستاده بفرمان و اگر ملک چنین سخن گوید و فرماید خویشتن بسوزم تا در جهان آوازه شوم . (مجمل التواریخ ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوازه گشتن </span> ؛ آواز گشتن . شهرت یافتن . مشهور شدن . سَمَر گشتن .<BR>۩ مجازاً، درگذشتن . مردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">شش آوازه </span> ؛ سَلمک . شهناز. مایه . نوروز. گردانیا (؟). گردانیه . گوشت .<br /></font></div>'),
(2695, 'آوازه', '<span class=\"hlight\">آوازه .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) نام دژی بترکستان که پرموده پسر ساوه شاه گنج خویش در آن نهفت و پس از شکست یافتن از بهرام چوبینه در آن تحصن جست <span class=\"hlight\">:</span> <br />دژی داشت پرموده آوازه نام <br />از آن دژ بدی ایمن و شادکام <br />چو کین پدر در دلش تازه شد<br />از آنجایکی سوی آوازه شد.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2696, 'آوازه خوان', '<span class=\"hlight\">آوازه خوان .</span> <font color=\"DarkGreen\"><b>[زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) آنکه شغلش خواندن آواز است . مُغنی . خواننده . قوال . خنیاگر. <BR><font color=\"Blue\">◄</font> مغنیه . مطربه . عالمه . قینه (چون خواننده زن باشد).<br /></font></div>'),
(2697, 'آوازه خوانی', '<span class=\"hlight\">آوازه خوانی .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (حامص مرکب ) عمل وشغل آوازه خوان . تغنی . خوانندگی . قوّالی . خنیاگری .<br /></font></div>'),
(2698, 'آوازه دژ', '<span class=\"hlight\">آوازه دژ.</span><font color=\"DarkGreen\"><b>[ زَ دِ ]</font></b> (اِخ ) رجوع به آوازه (مَدخل ِ آخر) شود.<br /></font></div>'),
(2699, 'آوال', '<span class=\"hlight\">آوال .</span> (اِخ ) بزرگترین جزیره ٔ مجمعالجزایر بحرین در خلیج فارس، و آن را بحرین نیز گویند. بطول <span class=\"hlight\" dir=\"rtl\">٥٠</span>هزار و عرض <span class=\"hlight\" dir=\"rtl\">١٧</span>هزار گز، و مرکز و بندر آن مینابه است . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١١٥٠٠٠</span> تن باشد. مروارید و خرما و لاک و کاسه ٔ سنگ پشت و کف دریا و میگو از صادرات آن است و انار و انجیر و زردآلو و شفتالو و مرکبات فراوان دارد. در دوفرسنگی این شهر معدن نفت ذیقیمتی است که یکی از غنی ترین معادن نفت دنیا بشمار می آید.<br /></font></div>'),
(2700, 'آوام', '<span class=\"hlight\">آوام .</span> (اِ) وام . <BR><font color=\"Blue\">◄</font> فام . رنگ . لون .<br /></font></div>'),
(2701, 'آواه', '<span class=\"hlight\">آواه .</span> (صوت ) آوَه ! آوخ !<br /></font></div>'),
(2702, 'آوای', '<span class=\"hlight\">آوای .</span> (صوت ) آواه .<br /></font></div>'),
(2703, 'آوج', '<span class=\"hlight\">آوج .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) آوه . نام محلی براه قزوین و همدان، میان یولچی و سلطان بلاغ در <span class=\"hlight\" dir=\"rtl\">٢٦٢٥٠٠</span> گزی طهران، و در آنجا پست خانه و تلگرافخانه هست .<br /></font></div>'),
(2704, 'آوخ', '<span class=\"hlight\">آوخ .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (صوت، اِ) دریغا. دریغ. افسوس . آواخ . آه . آخ . آوَه . یاحسرتا. آواه . دردا <span class=\"hlight\">:</span> <br />بدرد دل آوخ که بریان شوند<br />چه بر حال من زار گریان شوند.<br /> <font color=\"Red\">فردوسی .</font><br /> <br />گفت آوخ ! بفریفت مرا آنکه پدر ما را فریفت . (مجمل التواریخ ).<br />زدم ز عشق رخش پیش از این هزار نوا<br />کنون ز خار خطش میزنم هزار آوخ <br />بدود دوزخ پوشیده عارضی چو بهشت <br />بهشتئی که دلم تفته داشت چون دوزخ .<br /> <font color=\"Red\">سوزنی .</font><br />تهدید تیغ میدهد آوخ کجاست تیغ<br />تا چون جلیس دست بگردن درآورم .<br /> <font color=\"Red\">خاقانی .</font><br />جهان دست جفا بگشادآوخ <br />وفا را زور بازوئی نمانده ست .<br /> <font color=\"Red\">خاقانی .</font><br />گفت آوخ بعد هستی نیستی <br />گفت جرمت آنکه افزون زیستی .<br /> <font color=\"Red\">مولوی .</font><br />ما کشته ٔ نفسیم و بس آوخ که برآید<br />از ما بقیامت که چرا نفس نکشتیم .<br /> <font color=\"Red\">سعدی .</font><br />آوخ که چو روزگار برگشت <br />از من دل و صبر و یاربرگشت .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوخ کردن </span> ؛ تأوّه . (زوزنی ).<br /> <BR><font color=\"Blue\">◄</font> (اِ) نصیب و قسمت <span class=\"hlight\">:</span> <br />از تو پیش که و کجا نالم <br />کآوخم از تو جز غم دل نیست ؟<br /><font color=\"Red\">شهید قمی (از فرهنگ جهانگیری ).</font><br /></font></div>'),
(2705, 'آوخ', '<span class=\"hlight\">آوخ .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (اِخ ) نام کوهی است بسرحد غربی ایران، میان لادین و مرغاب، نزدیک کوه ماهی هلانه و کوه مورشهیدان .<br /></font></div>'),
(2706, 'آوختن', '<span class=\"hlight\">آوختن .</span> <font color=\"DarkGreen\"><b>[ وِ ت َ ]</font></b> (مص ) آویختن <span class=\"hlight\">:</span> <br />برآوختشان در شبستان شاه <br />بدان تا دگر کس نجوید گناه .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2707, 'آود', '<span class=\"hlight\">آود.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ع ص ) کج . منحنی . مُعوَج ّ.<br /></font></div>'),
(2708, 'آور', '<span class=\"hlight\">آور.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (نف مرخم ) مخفف آورنده : بارآور. برآور: درختی بارآور یا برآور. دین آور. سودائی زیان آور. معاملتی سودآور. شرم آور. ننگ آور <span class=\"hlight\">:</span> <br />جهاندار گفتا به نام خدای <br />بدین نام دین آور پاکرای .<br /> <font color=\"Red\">دقیقی .</font><br />به ره هست چندانکه آید بکار<br />درختان بارآور سایه دار.<br /> <font color=\"Red\">فردوسی .</font><br />به صورتگری گفت <font color=\"DarkGreen\"><b>[ مانی ]</font></b> پیغمبرم <br />ز دین آوران جهان برترم .<br /> <font color=\"Red\">فردوسی .</font><br />ز دین آوران این سخن کس نگفت <br />تو دیوانگی داشتی در نهفت .<br /> <font color=\"Red\">فردوسی .</font><br />مسیح فریبنده خود کشته شد<br />چو از دین یزدان سرش گشته شد<br />ز دین آوران دین آن کس مجوی <br />که او کار خود را ندانست روی .<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت دین آور تازیان <br />که خشم پدر جانت آرد زیان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> (ن مف مرخم ) مخفف آورده : گنج بادآور. شاهدی خطآور. رودآور <span class=\"hlight\">:</span> <br />دگر گنج بادآورش خواندند<br />شمارش بکردند و درماندند.<br /> <font color=\"Red\">فردوسی .</font><br />فراوان ز نامش سخن راندیم <br />سرانجام بادآورش خواندیم .<br /> <font color=\"Red\">فردوسی .</font><br />دی کآمدم ز غاتفر آمد مرا به پیش <br />شیرین خطآوری چو شکر در قمیطره .<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> (پسوند) دارنده . دارا. مالک . صاحب . خداوند: بخت آور. پرندآور. جاناور. سُروآور: شاةٌ قَرْناء؛ میشی سُروآور. کمین آور؛ خداوند کمین <span class=\"hlight\">:</span> <br />بینداخت تیغ پرندآورش <br />همی خواست از تن بریدن سرش .<br /> <font color=\"Red\">فردوسی .</font><br />کمندی بفتراک و اسبی دوان <br />پرندآور و جامه ٔ هندوان .<br /> <font color=\"Red\">فردوسی .</font><br />جهانی پر از دشمن و از بدان <br />نماند بتو تاج تاج آوران (کذا).<br /> <font color=\"Red\">فردوسی .</font><br />بزیر اندرون بود و هامون و دشت <br />که بدبخت و بخت آور آنجا گذشت .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> بسیار. پُر: تکاور؛ بسیارتک . خارآور؛ پرخار: العضاة؛ درختان خارآور. (ربنجنی ). خشم آور؛ بسیارخشم . دلاور؛ پردل . زورآور؛ پرزور. شتاب آور؛ پرشتاب . کین آور؛ پرکین <span class=\"hlight\">:</span> <br />ستاره شناسان و دین آوران <br />سواران جنگی ّ و کین آوران .<br /> <font color=\"Red\">فردوسی .</font><br />بپردازی و خود بتوران شوی <br />ز جنگ و ز کین آوران بغنوی .<br /> <font color=\"Red\">فردوسی .</font><br />یلان سینه آمد پس ِ اردوان <br />بر اسب تکاور ببسته میان .<br /> <font color=\"Red\">فردوسی .</font><br />یکی داستان زد بر این بر پلنگ <br />چو با شیر زورآورش خاست جنگ .<br /> <font color=\"Red\">فردوسی .</font><br />تو نیز بزیر ران درآری <br />آن رخش تکاور هنرمند.<br /><font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> بزرگ . کلان . درشت : استخوان آور؛ درشت استخوان : الزاهق ؛ اسبی استخوان آور. بیخ آور؛ کلان بیخ : جبل راسخ ؛ کوه بیخ آور. (ربنجنی ). تناور؛ بزرگ تنه . بزرگ تن : مردی تناور. درختی تن آور. جگرآور؛ بزرگ جگر. دلیر. دنبه آور؛ بزرگ دنبه : الیانه ؛ میشی دنبه آور. (ربنجنی ). ریش آور؛ بزرگ ریش . بلمه . لحیانی : مردی ریش آور. شکم آور؛ بزرگ شکم . بطین . نام آور؛ بزرگ نام . مشهور <span class=\"hlight\">:</span> <br />تناور یکی لشکر زورمند<br />برهنه تن و سفت و بالا بلند.<br /> <font color=\"Red\">فردوسی .</font><br />بهی ّ تناور گرفته بدست <br />دژم خفته بر جایگاه ِ نشست .<br /> <font color=\"Red\">فردوسی .</font><br />مر او را ستودند یک یک مهان <br />بزرگان و نام آوران جهان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> جوی . جوینده . خواه . خواهنده : جنگ آور؛ جنگجوی . رزم آور؛ رزمخواه <span class=\"hlight\">:</span> <br />بیاری بیاید سپاهی گران <br />بزرگان توران و جنگ آوران .<br /> <font color=\"Red\">فردوسی .</font><br />که گردان کدامند و سالار کیست <br />ز رزم آوران جنگ را یار کیست ؟<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> چون . مانند: اسب بادآور؛ اسب چون باد <span class=\"hlight\">:</span> <br />یکی ترجمان را ز لشکر بخواند<br />بگلگون بادآورش برنشاند.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> و در زبان آور مجموع مرکب به معنی فصیح و سخنور است . <BR><font color=\"Blue\">◄</font> کلمه ٔ گُندآورچون گفته های فرهنگ نویسان در عربی یا فارسی و مضموم یا مفتوح بودن کاف مضطرب است معنی مجموع مرکب آن ظاهر نیست، چه گاهی جزء اول کلمه را کندا گرفته اند و گاهی گُند اصل کلمه ٔ جُند عرب دانسته اند و از این رو کندآور را حکیم و فیلسوف معنی کرده اند و گندآور را معنی قائد و سپهسالار داده اند. معنی فیلسوف برای کندآور درست نمی نماید چه خود کندا را فرهنگ نویسان معنی حکیم و فیلسوف میدهند و در این صورت کندآور معنی معقولی ندارد. و اگر کلمه گُندآور مرکب از گند به معنی جُندباشد معانی شجاع و دلیر در آن تَوَسع یا مسامحه ایست . صاحب اقرب الموارد گوید: الکند بالضّم ؛ الشرس الشدید فارسی، نقله فریتغ عن بعض کتب العرب . و هم او گوید: الکنداکِر؛ الشّجاع، الجسور فارسیة نقلها فریتغ عن بعض کتب العرب . و گُند به معنی خصیه و بیضه نیز آمده است و امروز در تداول عامه، فلان مردی خایه دار است، تعبیر مثلی است که از آن اقتحام مرد و مقتحم بودن او را اراده کنند <span class=\"hlight\">:</span> <br />نگه کن سواران وکندآوران <br />چو بهرام و چون زنگه ٔ شاوران .<br /> <font color=\"Red\">فردوسی .</font><br />همه ریگ صحرا مرا لشکرند<br />همه نرّه شیران وکندآورند.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2709, 'آور', '<span class=\"hlight\">آور.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ق ) یقیناً. بالقطع. براستی . راست . (صحاح الفرس ). صحیح . بتحقیق . (فرهنگ اسدی، خطی ). برتحقیق <span class=\"hlight\">:</span> <br />کسی را که باشد بدل مهر حیدر<br />شود سرخ رو در دو گیتی به آور.<br /> <font color=\"Red\">رودکی .</font><br />اگر دیده بگردون برگمارد<br />ز سهمش پاره پاره گردد آور.<br /> <font color=\"Red\">بوشعیب .</font><br />گروه دیگر گفتند نه، که این بت را<br />بر آسمان برین بود جایگاه، آور.<br /> <font color=\"Red\">فرخی .</font><br />چنین شنیدم از مردمان دانا<br />که می بسنبد الماس گوهر، آور.<br /><font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) ایمان . یقین <span class=\"hlight\">:</span> <br />گر سلیم حیه ٔ عشقی بخور تریاق فقر<br />تا مسلم گرددت آور چو سلمان داشتن .<br /> <font color=\"Red\">شیخ روزبهان .</font><br />هرچه کردی نیک و بد فردابه پیشت آورند<br />بی شک ای مسکین، اگر در دل نداری آوری .<br /> <font color=\"Red\">؟ (از جهانگیری ).</font><br />و کلمه ٔ باور مخفف به آور، یعنی به یقین، مؤید دعوی فوق است .<br /> <BR><font color=\"Blue\">◄</font> و در فرهنگها بکلمه ٔ آور معنی آسمان هفتم و یا مطلق آسمان داده اند و بیت مزبور بوشعیب را مثال آورده اند. گذشته از اینکه شاهد دیگری برای این مدعا نیست، کلمه در آن بیت ظاهراً همان معنی یقیناً و قطعاً میدهد. و نیز زشت را یکی از معانی این کلمه شمرده و بیت ذیل را شاهد گذرانیده اند <span class=\"hlight\">:</span><br />نزدیک عقل جمله در این عهد باوراست <br />کامروز همچو جهل هنر زشت و آور است .<br /> <font color=\"Red\">عنصری .</font><br /><BR><font color=\"Blue\">◄</font> (ص ) طعم بگشته . تندشده . تیزگردیده . بیورزده (مغز جوز و لوز و پسته و مانند آن ).<br /></font></div>'),
(2710, 'آوران', '<span class=\"hlight\">آوران .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (نف، ق ) در حال آوردن .<br /></font></div>'),
(2711, 'آورانیدن', '<span class=\"hlight\">آورانیدن .</span> <font color=\"DarkGreen\"><b>[ وَ دَ ]</font></b> (مص ) سبب شدن آوردن را.<br /></font></div>'),
(2712, 'آورتا', '<span class=\"hlight\">آورتا.</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (از یونانی، اِ) رجوع به آورتی شود.<br /></font></div>'),
(2713, 'آورتی', '<span class=\"hlight\">آورتی .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (از یونانی، اِ) آئورت . آوُرطی . ام الشرائین . اُرطی . دبر. شریانی که از بطن اَیْسَر قلب بوسیله ٔ شریانهای دیگر، خون سرخ بهمه ٔ اعضاء رساند. و آن بر دو قسمت است آورتی بطنی و آورتی صدری، و آورتی صدری را وتین گویند.<br /></font></div>'),
(2714, 'آورجه', '<span class=\"hlight\">آورجه .</span><font color=\"DarkGreen\"><b>[ وَ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ ]</font></b> (اِ) به معنی آوارجه است که دفتر حسابهای پراکنده باشد. (برهان ). رجوع به آوارجه شود.<br /></font></div>'),
(2715, 'آورد', '<span class=\"hlight\">آورد.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ) کوشیدن بجنگ . (فرهنگ اسدی، خطی ). جنگ کردن بمبارزت . حمله در جنگ . (تحفةالاحباب اوبهی ). نبرد. ناورد. کارزار. جنگ . مبارزت . پیکار. رزم . پرخاش . فرخاش . جدال . رغا. هیجا <span class=\"hlight\">:</span> <br />به آورد هر دو برآویختند<br />همی خاک بر اختران ریختند.<br /> <font color=\"Red\">فردوسی .</font><br />فرامرز نشگفت اگر سرکش است <br />که پولاد را دل پر از آتش است <br />چو آورد با سنگ خارا کند<br />ز دل راز خویش آشکارا کند.<br /> <font color=\"Red\">فردوسی .</font><br />سکندر چو دید آن تن پیل مست <br />یکی کوه زیر، اژدهائی بدست <br />به آورد از او ماند اندر شگفت <br />غمی شد دل از جان و تن برگرفت .<br /> <font color=\"Red\">فردوسی .</font><br />بجوشید و رخسارگان کرد زرد<br />بدرد دل آهنگ آورد کرد.<br /> <font color=\"Red\">فردوسی .</font><br />هر آنکس که در جنگ سست آمدی <br />به آورد ناتندرست آمدی <br />شهنشاه را نامه کردی بر آن <br />هم از بی هنر هم ز جنگاوران .<br /> <font color=\"Red\">فردوسی .</font><br />ز ناورد و آورد او در نبرد<br />رسد تا بگردون گردنده گرد.<br /> <font color=\"Red\">فردوسی .</font><br />کس آورد با کوه خارانکرد.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت رستم که ای شهریار<br />مجوی آشتی درگه کارزار<br />نبد آشتی پیش از آوردشان <br />بدین روز گرز من آوردشان .<br /> <font color=\"Red\">فردوسی .</font><br />اگر تاج یابد جهانجوی مرد<br />و گر خاک آورد و خون نبرد<br />به ناکام میرفت باید ز دهر<br />چه زو بهره تریاک باشد چه زهر.<br /> <font color=\"Red\">فردوسی .</font><br />ز نعل خنگش روی زمین گه آورد<br />پر از پشیزه شود همچو پشت ماهی شیم .<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />رجوع به آوردگاه شود. <BR><font color=\"Blue\">◄</font> میدان <span class=\"hlight\">:</span> <br />به آورد رزمی کنم با سپاه <br />که خون بارد از ابر آوردگاه .<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به آوردگاه شود.<BR><font color=\"HotPink\">♦ </font>آورد گرفتن (؟) <span class=\"hlight\">:</span> <br />نیاطوس بگزید هفتاد مرد<br />که آورد گیرند روز نبرد<br />که زیر درفشش برفتی هزار<br />گزیده سواران نیزه گذار.<br /> <font color=\"Red\">فردوسی .</font><br />به رزمش چه پیل و چه شیر و چه دیو<br />چو آورد گیرد برآرد غریو.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خاک ِ آورد</span> ؛ میدان <span class=\"hlight\">:</span> <br />از ایرانیان هرکه افکنده بود<br />اگر کشته بود و اگر زنده بود<br />از آن خاک آورد برداشتند<br />تن دشمنان خوار بگذاشتند.<br /> <font color=\"Red\">فردوسی .</font><br />و در بیت ذیل معنی آورد روشن نیست و در بعض نسخ بجای آورد آواز آمده است <span class=\"hlight\">:</span> <br />بدان نامور ترجمان شیده گفت <br />که آورد مردان نشاید نهفت .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">هم آورد</span> ؛ هم نبرد <span class=\"hlight\">:</span> <br />هم آورد او در جهان پیل نیست <br />چو گرد پی اسپ او نیل نیست .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2716, 'آورد', '<span class=\"hlight\">آورد.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> ( ن مف مرخم ) در کلمات مرکبه چون آب آورد و بادآورد و بزم آورد و راه آورد و ره آورد و مادرآورد، مخفف آورده و آوریده است <span class=\"hlight\">:</span> <br />بروزگار هوای تو کم شود نی نی <br />هوای تو عَرَضی نیست مادرآورد است .<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">روآورد کردن یا نکردن (در تداول عامه )</span> ؛ علم خویش را بخطای او، به او گفتن یا نگفتن .<br /></font></div>'),
(2717, 'آورد', '<span class=\"hlight\">آورد.</span> <font color=\"DarkGreen\"><b>[ وِ ]</font></b> (اِ) برادر پدر. عم . عمو. پِربرار.<br /></font></div>'),
(2718, 'آورد و برد', '<span class=\"hlight\">آورد و برد.</span> <font color=\"DarkGreen\"><b>[ وَ دُ ب ُ ]</font></b>(ترکیب عطفی، اِمص مرکب ) عمل پیاپی آوردن و بردن .<br /></font></div>'),
(2719, 'آوردجوی', '<span class=\"hlight\">آوردجوی .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (نف مرکب ) جنگجوی . مبارز <span class=\"hlight\">:</span> <br />جهان گشت پر گرد آوردجوی <br />ز خون خاست در جای ناورد، جوی .<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(2720, 'آوردخواه', '<span class=\"hlight\">آوردخواه .</span> <font color=\"DarkGreen\"><b>[ وَ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) جنگجوی <span class=\"hlight\">:</span> <br />که از ما یکی را به آوردگاه <br />فرستی برِ ترک آوردخواه .<br /> <font color=\"Red\">فردوسی .</font><br />نگه کن که بااو به آوردگاه <br />توانی شدن زآن پس آوردخواه .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2721, 'آوردن', '<span class=\"hlight\">آوردن .</span> <font color=\"DarkGreen\"><b>[ وَ دَ ]</font></b> (مص ) (از: آ، به معنی سوی یا به معنی سلب + بردن ) بردن بسوی کسی . ایتاء. اجأه . اِتیان . مقابل بردن <span class=\"hlight\">:</span> <br />ز چیزی که از بلخ بامی ببرد<br />بیاورد و یکسر به گهرم سپرد.<br /> <font color=\"Red\">فردوسی .</font><br />بگیریدش از پشت آن پیل مست <br />به پیش من آریدبسته دو دست .<br /> <font color=\"Red\">فردوسی .</font><br />بسیندُخت فرمود پس نامدار<br />که رودابه را خیز و نزد من آر.<br /> <font color=\"Red\">فردوسی .</font><br /> <br /> <BR><font color=\"Blue\">◄</font> روایت، نقل حکایت، حدیث، ذکر، یاد، بیان، ایراد، قصه کردن . گفتن . نوشتن <span class=\"hlight\">:</span> <br />کنون زین سپس هفت خوان آورم <br />سخنهای نغز و جوان آورم .<br /> <font color=\"Red\">فردوسی .</font><br />بگو تا چه داری بیار از خرد<br />که گوش نیوشنده زو بر خورد.<br /> <font color=\"Red\">فردوسی .</font><br />سخندان که رای ردان آورد<br />سخن بر زبان ددان آورد.<br /> <font color=\"Red\">عنصری .</font><br />هرکه خواند دانم که عیب نکند به آوردن این حکایت که بی فائده نیست . (تاریخ بیهقی ). در این باب حکایتی که بنشابور گذشته از جهت غاشیه بیاورم . (تاریخ بیهقی ). هزلها و جدّهای وی را اندازه نبود و پس از این بیارم بجای خویش . (تاریخ بیهقی ). بیاورم ناچار این حال را تا بدان واقف شده آید. (تاریخ بیهقی ). خداوند سلطان فرموده بود تا ترا و پسرت را هزار عقابین بزنند من بر تو رقت آوردم . (تاریخ بیهقی ). و بجای خود بیارم که از گونه گونه چه کار رفت . (تاریخ بیهقی ). بیاورم پس از این که بر هر یکی از اینها چه رفت . (تاریخ بیهقی ). ذکر و بیان کردن بوصالح تیانی ... که نام و حال وی بیاورم یکی بود از ایشان ... (تاریخ بیهقی ). نسخت سوگندنامه ... بیاورده ام در مقامات محمودی که کرده ام . (تاریخ بیهقی ). چنانکه بیارم چگونگی آن بر جای خویش . (تاریخ بیهقی ). و بیارم پس از این، که درباب علی چه رفت تا آنگاه که فرمان یافت . (تاریخ بیهقی ). من حکایتی خوانده ام در اخبار خلفا... بیاورم . (تاریخ بیهقی ). و پس از این بیارم آنچه رفت در باب این بازداشته، بجای خویش . (تاریخ بیهقی ). آن قصه سخت معروف است نیاورده ام که سخن سخت دراز کشد. (تاریخ بیهقی ). تعدیها رفت از وی که در تاریخ پیش از این بیاورده ام . (تاریخ بیهقی ). چنین سخنان ازبرای آن می آورم تا خفتگان ... بیدار شوند. (تاریخ بیهقی ). و پدریان را نیک ازآن درد می آمد و می ژکیدند تا آخر بیفکندندش چنانکه بیاورم . (تاریخ بیهقی ). و پس از این آورده آید. (تاریخ بیهقی ). در تاریخ گذشته بیاورده ام دو باب در آن ازحدیث این پادشاه بزرگ . (تاریخ بیهقی ). من نسختی کردم چنانکه در دیگر نسختها و در این تاریخ بیاورده ام نامه را. (تاریخ بیهقی ). استادم دو نسخت کرد این دو نامه را... و نسختها بشده است چنانکه چند جای این حال بیاوردم . (تاریخ بیهقی ). قصه ای که او را افتاد بیارم بجای خویش . (تاریخ بیهقی ). آنچه غرض بود بیاوردم از این سه لقب . (تاریخ بیهقی ). چنین آورده اند که فضل وزیر مأمون خلیفه بمرد. (تاریخ بیهقی ). این حدیث درتاریخ یمینی بیاورده ام . (تاریخ بیهقی ). در مجلد پنجم بیاوردم که امیرمسعود... در بلخ آمد. (تاریخ بیهقی ). و نوادر و عجایب که وی را افتاده بود در روزگار پدرش همه بیاورده ام در این تاریخ . (تاریخ بیهقی ). احوال این امام آورده آید سخت مشبع بجایگاه خویش . (تاریخ بیهقی ).<br />ور بپرسیش یکی مشکل گویدْت بخشم <br />سخن رافضیان است که آوردی باز.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و در خواص <font color=\"DarkGreen\"><b>[ زر ]</font></b> چنان آورده اند که کودک خرد را چون بدارودان زرش شیر دهند آراسته سخن آید و بر دل مردم شیرین آید. (نوروزنامه ). آورده اند که <font color=\"DarkGreen\"><b>[ اسدبن عبداﷲ ]</font></b> مردی نیکوکار بود. (تاریخ بخارای نرشخی ). آورده اند که در آبگیری از راه دور... سه ماهی بودند. (کلیله و دمنه ). آورده اند که روباهی در بیشه ای رفت . (کلیله و دمنه ).<br />مؤمنان آیینه ٔ یکدیگرند<br />این خبر را از پیمبر آورند.<br /> <font color=\"Red\">مولوی .</font><br />اینکه در شه نامه ها آورده اند<br />رستم و اسکندر و اسفندیار <br />تا بدانند این خداوندان ملک <br />کز بسی خلق است دنیا یادگار.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />آورده اند که آن پادشاه زاده را که ملموح نظر او بود... (گلستان ). و آورده اندکه ظرافت بسیار کردن هنر ندیمان است و عیب حکیمان . (گلستان ). آورده اند که نوشیروان عادل را در شکارگاه صیدی کباب کردند و نمک نبود. (گلستان ). آورده اند که یکی از ستم دیدگان بر سر او بگذشت . (گلستان ). آورده اند که بر تاج کیخسرو نبشته بود... (گلستان ). آورده اندکه یکی از وزراء بزیردستان رحمت آوردی . (گلستان ). می آرند که درویشی طعام غیرمعهود میخورد. (انیس الطالبین بخاری ). <BR><font color=\"Blue\">◄</font> دادن . کردن چنانکه رزم و نبرد و حرب و جنگ را <span class=\"hlight\">:</span> <br />نبیره که جنگ آورد با نیا<br />هم از ابلهی باشد و کانیا .<br /> <font color=\"Red\">فردوسی .</font><br />که تا هر کسی کو نبرد آورد<br />سر دشمنی زیر گرد آورد<br />نویسد بنامه درون نام او<br />رونده شود در جهان کام او.<br /> <font color=\"Red\">فردوسی .</font><br />میانها ببندیم و جنگ آوریم <br />چو باید که کشور بچنگ آوریم .<br /> <font color=\"Red\">فردوسی .</font><br />تهمتن چنین داد پاسخ بدوی <font color=\"DarkGreen\"><b>[ به اشکبوس ]</font></b><br />که ای بیهده مرد پرخاشجوی <br />پیاده ندیدی که جنگ آورد<br />سر سرکشان زیر سنگ آورد.<br /> <font color=\"Red\">فردوسی .</font><br />به آوردگه با تو جنگ آورد<br />دل شیر و چنگ پلنگ آورد.<br /> <font color=\"Red\">فردوسی .</font><br />من از تخمه ٔ نامور آرشم <br />چو جنگ آورم آتش سرکشم .<br /> <font color=\"Red\">فردوسی .</font><br />کنون گر تو با او نبرد آوری <br />سرش را ز گردون بگرد آوری .<br /> <font color=\"Red\">فردوسی .</font><br />چو جنگ آیدش پیش جنگ آورد<br />سر شهریاران به چنگ آورد.<br /> <font color=\"Red\">فردوسی .</font><br />که گر هست چون مه نبرد آورم <br />ز گردون سرش زیر گرد آورم .<br /> <font color=\"Red\">فردوسی .</font><br />گر ایدون که رزم آورم با سپاه <br />جهان را کنم پیش چشمش سیاه .<br /><font color=\"Red\">فردوسی .</font><br />ابا رستم امروز جنگ آورم <br />همه نام او زیر ننگ آورم .<br /> <font color=\"Red\">فردوسی .</font><br />برآشفت <font color=\"DarkGreen\"><b>[ افراسیاب ]</font></b> با نامداران تور<br />که این دشت جنگ است یا بزم سور<br />بکوشید و یکباره جنگ آورید<br />جهان بر بداندیش تنگ آورید.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت گرشاسب کای دیومرد<br />چگونه نخندم بدشت نبرد<br />که پیشم تو آئی ّ و جنگ آوری <br />مرا خنده آید از این داوری .<br /> <font color=\"Red\">فردوسی .</font><br />گر او با تهمتن نبرد آورد<br />سر خویشتن زیر گرد آورد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> دادن . گفتن، چنانکه پاسخ یا پیام یا خبر را <span class=\"hlight\">:</span> <br />بدان تا زواره بیاید ز راه <br />بر او آگهی آورد زآن سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />هرکه حجت خواهدت آری جوابش تیغ تیز<br />حجت ار تیغ است و بس درس و مقالت چیست پس ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> دادن، چنانکه شکن و خم در رسنی و جز آن <span class=\"hlight\">:</span> <br />چو خم در دوال کمند آورم <br />سر جادوان را به بند آورم .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> کردن <span class=\"hlight\">:</span> <br />ببُد تا بهار اندر آورد روی <br />جهان شد بهشتی پر از رنگ و بوی .<br /> <font color=\"Red\">فردوسی .</font><br />نباید که یزدان چو خوانَدْت پیش <br />روان تو شرم آرد از کار خویش .<br /> <font color=\"Red\">فردوسی .</font><br />پی جادوان بگسلاند ز خاک <br />پدید آورد راه یزدان پاک .<br /> <font color=\"Red\">فردوسی .</font><br />ز هردست چیزی فراز آوریم <br />بدشمن سپاریم و خود بگذریم .<br /><font color=\"Red\">فردوسی .</font><br />کنون گاه شادی ّ و می خوردن است <br />نه هنگام اندیشه آوردن است .<br /> <font color=\"Red\">فردوسی .</font><br />بکوشیم تا نیکی آریم و داد<br />خنک آنکه پند پدر کرد یاد.<br /> <font color=\"Red\">فردوسی .</font><br />بر امّید آن کش بچنگ آورم <br />جهان پیش او تار و تنگ آورم .<br /> <font color=\"Red\">فردوسی .</font><br />سرش تنگ بگرفت و یک بوسه داد<br />همانا که از شرم ناورد یاد.<br /> <font color=\"Red\">فردوسی .</font><br />بدانسان شوم پیش او با سپاه <br />که بخشایش آرد بر او هور و ماه .<br /> <font color=\"Red\">فردوسی .</font><br />یکی حمله آورد <font color=\"DarkGreen\"><b>[ گیو ]</font></b> بر پهلوان <br />تو گفتی که بود اژدهای دمان .<br /> <font color=\"Red\">فردوسی .</font><br />نوا چون نیابند جنگ آورند<br />جهان بر بداندیش تنگ آورند.<br /> <font color=\"Red\">فردوسی .</font><br />بنظم آرم این نامه را گفت من <br />از او شادمان شد دل انجمن .<br /> <font color=\"Red\">فردوسی .</font><br />چو گفتار کاوس یاد آوریم <br />روان را همه سوی داد آوریم .<br /> <font color=\"Red\">فردوسی .</font><br />بهنگام نان شیر گرم آوری <br />بدان شیر این چرم نرم آوری .<br /> <font color=\"Red\">فردوسی .</font><br />خروشی بد اندر میان سپاه <br />که بخشایش آورد خورشید و ماه .<br /> <font color=\"Red\">فردوسی .</font><br />نیک آوردی که نیامدی و بشراب بخواجه مساعدت کردی . (تاریخ بیهقی ).<br />هم اکنون چو آهنگ راه آورم <br />سر هر دوشان پیش شاه آورم .<br /> <font color=\"Red\">اسدی .</font><br />اگر رحمت نیاری من بمیرم <br />درآن گیتی ترا دامن بگیرم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />و از همه ٔ جهان مردم گرد آورد. (نوروزنامه ). مالی بمشقت فراهم آرند و به خست نگه دارند. (گلستان ). رحم آوردن بر بدان ستم است بر نیکان . (گلستان ). چیزی نیافتم که به آن یخ را شکنم و آب گیرم و غسل آرم . (انیس الطالبین بخاری ). <BR><font color=\"Blue\">◄</font> زادن . زاییدن . ایلاد. تولید. وضع. نهادن <span class=\"hlight\">:</span> <br />که فرزند آرد ورا در جهان <br />بدیدار او در میان مهان .<br /> <font color=\"Red\">فردوسی .</font><br />ششم سال آن دخت قیصر ز شاه <br />یکی کودک آورد مانند ماه .<br /> <font color=\"Red\">فردوسی .</font><br />چون بیضا انوش را بیاورد و آن نور اندر جبین او پدید شد شاد شد. (تاریخ سیستان ). ساره همچنان غمگین بود تا اسحاق را بیاورد. (تاریخ سیستان ).<br />بجان تو که من دختر ندارم <br />وگر دارم بدیده پیشت آرم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />بایتکین ... با خویشتن صد و سی تن طاووس ... آورده بود... در گنبدها بچه می آوردندی . (تاریخ بیهقی ).<br />پرسیدمش چگونه ای و چه حالت است ؟ گفت تاکودکی بیاوردم دگر کودکی نکردم . (گلستان ). درویش راهمه عمر فرزند نبود گفت اگر خدای عزّ و جل مرا فرزندی نرینه دهد... اتفاقاً پسر آورد. (گلستان ).<br /> <BR><font color=\"Blue\">◄</font> بردن <span class=\"hlight\">:</span> <br />چنین گفت کای داور دادگر<br />همه رنج و سختی تو آری بسر.<br /> <font color=\"Red\">فردوسی .</font><br />مگر شاه را نزدماه آوریم <br />به نزدیک او پایگاه آوریم .<br /> <font color=\"Red\">فردوسی .</font><br />نباید که یابد شما را زبون <br />بکار آورد مرد دانا فسون .<br /> <font color=\"Red\">فردوسی .</font><br />بکوشیدو خوبی بکار آورید<br />چو دیدید سرما بهار آورید.<br /> <font color=\"Red\">فردوسی .</font><br />فرنگیس با رنج دیده پسر<br />بخواب اندر آورده بودند سر.<br /> <font color=\"Red\">فردوسی .</font><br />یکی را بجان داد زنهار و گفت <br />نگر تا بیاری سر اندر نهفت <br />نگر تا نباشی به آباد شهر<br />ترا در جهان کوه و دشت است بهر.<br /> <font color=\"Red\">فردوسی .</font><br />امیرمحمود از بُست تاختن آورد بر جانب ... (تاریخ بیهقی ). و دیگر روزآن لشکر و خزاین و غلامان سرای را برداشت و لطایف الحیل بکار آورد تا بخوارزم بازبرد. (تاریخ بیهقی ).<br /> <BR><font color=\"Blue\">◄</font> ستدن . استدن . ستاندن . گرفتن . تلافی کردن . پس گرفتن . اخذ ثار کردن <span class=\"hlight\">:</span> و چون خون پدرش ایرج بازآورد افریدون خدای تعالی را شکر کرد. (تاریخ سیستان ). تا روزگار کیکاوس، باز هم رستم بترکستان شد و خون سیاوخش بازآورد تا باز که با کیخسرو برفت و حربها کرد. (تاریخ سیستان ). چون بنی اسرائیل یحیی را و زکریّا علیهماالسلام را بکشت بخت النصر را آنجا فرستاد تا خون ایشان بازآورد. (تاریخ سیستان ). و ما انصاف خویش از ایشان بیاوردیم . (تاریخ سیستان ). <BR><font color=\"Blue\">◄</font> رسانیدن . رساندن <span class=\"hlight\">:</span> <br />سپهبد <font color=\"DarkGreen\"><b>[ طوس ]</font></b> فریبرز را گفت مرد<br />بچیزی چو آید بدشت نبرد<br />به تیر و کمان و به تیغ و کمند<br />بکوشد که بر دشمن آرد گزند.<br /> <font color=\"Red\">فردوسی .</font><br />بر آن گونه بردند گردان گمان <br />که خسرو سر آرد بدیشان زمان .<br /> <font color=\"Red\">فردوسی .</font><br />چو نامه بمهر اندر آورد و بند<br />بفرمود تا برستور نوند<br />ز بابل بروم آورند آگهی <br />که تیره شد آن فرّ شاهنشهی .<br /> <font color=\"Red\">فردوسی .</font><br />چه داند خوابناک مست و مخمور<br />که شب را چون بروز آورد رنجور.<br /> <font color=\"Red\">سعدی .</font><br />کنون گر کنی دل تو از کینه پاک <br />سر دشمنان اندرآری بخاک .<br /> <font color=\"Red\">فردوسی .</font><br />همیدون جهان بر تو سازم سیاه <br />اَبَر خاک آرم ترا این کلاه .<br /> <font color=\"Red\">فردوسی .</font><br />فقیره ٔ درویشی حامله بود مدّت حمل بسر آورده . (گلستان ).<br />کسی قول دشمن نیارد بدوست <br />جز آنکس که در دشمنی یار اوست .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> دادن . گفتن، چنانکه پاسخ و جواب را <span class=\"hlight\">:</span> <br />چنین پاسخ آورد کاین رای نیست <br />بخان تو اندر مرا جای نیست .<br /> <font color=\"Red\">فردوسی .</font><br />بدیشان چنین پاسخ آورد شاه <br />که ای موبدان نماینده راه .<br /> <font color=\"Red\">فردوسی .</font><br />چنین پاسخ آورد فرزانه زن <br />که با موبد نیکدل رای زن .<br /> <font color=\"Red\">فردوسی .</font><br />فریدون چنین پاسخ آورد باز...<br /> <font color=\"Red\">فردوسی .</font><br />کی ِ نامور پاسخ آورد زود<br />که از من شگفتی بباید شنود.<br /> <font color=\"Red\">فردوسی .</font><br />چنین پاسخ آورد یزدان پرست <br />کز آن راه بر کرّه باید نشست .<br /> <font color=\"Red\">فردوسی .</font><br />سخن را بباید شنیدن نخست <br />چو داناشوی پاسخ آری درست .<br /> <font color=\"Red\">فردوسی .</font><br />چنین پاسخ آورد هومان بدوی <font color=\"DarkGreen\"><b>[ بطوس ]</font></b><br />که ناساخته جنگ بیشی مجوی .<br /> <font color=\"Red\">فردوسی .</font><br />مهان را چنین پاسخ آورد شاه <br />کز اندیشه گردد همی دل تباه .<br /> <font color=\"Red\">فردوسی .</font><br />چنین پاسخ آوردش اسفندیار<br />که بی تو مبیناد کس روزگار.<br /> <font color=\"Red\">فردوسی .</font><br />چنین پاسخ آورد کای نامدار<br />نشسته بخان من است این سوار.<br /> <font color=\"Red\">فردوسی .</font><br />چنین پاسخ آورد بهرام باز<br />که از من تو پیکار خردی مساز.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت کز دل خرد دور کن <br />چو رزم آورد پاسخش سور کن .<br /> <font color=\"Red\">فردوسی .</font><br />گفت این موافق حال من نگفتی و جواب سؤال من نیاوردی . (گلستان ). <BR><font color=\"Blue\">◄</font> برکشیدن . برداشتن . بلند کردن، چنانکه آواز را یا نعره را <span class=\"hlight\">:</span> <br />چو یابم <font color=\"DarkGreen\"><b>[ آرزو ]</font></b> بگویم همه راز خویش <br />برآرم نهان کرده آواز خویش .<br /> <font color=\"Red\">فردوسی .</font><br />بکوشید و اندر میان آورید<br />خروش هزبر ژیان آورید.<br /> <font color=\"Red\">فردوسی .</font><br />کودکی سیاه از حی عرب بدر آمد و آوازی برآورد که مرغ از هوا درآورد. (گلستان ). شوریده ای که در آن سفر همراه ما بود نعره ای برآورد و راه بیابان گرفت . (گلستان ). بیهنران مر هنرمند را نتوانند که بینند، همچنان که سگان بازاری سگ صید را بینند مشغله برآرند و پیش آمدن نیارند. (گلستان ).<br /> <BR><font color=\"Blue\">◄</font> بار، بر، ثمر، میوه دادن <span class=\"hlight\">:</span> <br />گفت برتر شواز بر خورشید<br />که رطب خیره بار نارد بید.<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> صید کردن . گرفتن <span class=\"hlight\">:</span> <br />اگر من شوم کشته بر دست تو<br />ز دریا نهنگ آورد شست تو.<br /> <font color=\"Red\">فردوسی .</font><br />شکیبا و با هوش و رای و خرد<br />هژبر ژیان را به دام آورد.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوردن بخت </span> ؛ مساعد شدن بخت .<br /> <BR><font color=\"Blue\">◄</font> کشیدن . برکشیدن . تحشید لشکر وسپاه را <span class=\"hlight\">:</span> <br />بیامد سبک پهلوان با سپاه <br />بیاورد لشکر به نزدیک شاه <br />چو آسوده تر گشت مرد وستور<br />بیاورد لشکر سوی شهرزور.<br /> <font color=\"Red\">فردوسی .</font><br />سران هر دو بودند و کابل سپاه <br />بیاورد با خویشتن سوی راه .<br /> <font color=\"Red\">فردوسی .</font><br />گر ایدون که فرمان دهد شهریار<br />بیارم از ایران بمیدان سوار.<br /> <font color=\"Red\">فردوسی .</font><br />ز چین و ز ماچین سپاه آورم <br />جهان پیش خسرو تباه آورم .<br /> <font color=\"Red\">فردوسی .</font><br />نه دو ماه می باید و نی چهار<br />که ما خود بیاریم شیران کار.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> داشتن . واداشتن . وادار کردن . مصمم کردن . ناگزیر کردن . مجبور کردن <span class=\"hlight\">:</span> جهد کردم تا خویشتن بدان آوردم تا در بزدم . (تاریخ سیستان ). در شب امیر را بر آن آورده بودند که ناچار آلتون تاش را فرو باید گرفت . (تاریخ بیهقی ). لکن امیر را بر آن آورده بودند که وی را فرو باید گرفت . (تاریخ بیهقی ).<br />آری مرا بدان کت برخیزم <br />وز زلف عنبرینْت درآویزم .<br /> <font color=\"Red\">؟(از فرهنگ اسدی ).</font><br />طمع قوت مرا بدین کار آورد. (مجمل التواریخ ). <BR><font color=\"Blue\">◄</font> برافراشتن . برافراختن . برداشتن . بلند کردن . برکشیدن <span class=\"hlight\">:</span> <br />یکی پیل پیکر درفش از برش <br />بابر اندرآورده زرین سرش .<br /> <font color=\"Red\">فردوسی .</font><br />به ابر اندر آورده بالای او<br />زمین کوه تا کوه پهنای او.<br /> <font color=\"Red\">فردوسی .</font><br />ما در این حالت که دو هندو از پس سنگی سر برآوردند. (گلستان ). قاضی چون ... حجت ما بشنید سر بجیب تفکر فروبرد و پس ازتأمل بسیار سر برآورد و گفت . (گلستان ). آنگه بقوّت استیناس محبوب از میان تلاطم امواج مودّت سر برآورد و گفت ... (گلستان ). عابدی در وی گذر کرد و در حالت مستقبح او نظر، جوان از خواب مستی سر برآورد. (گلستان ).<br />وگر دست قدرت نداری بکار<br />چو بیچارگان دست زاری برآر.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> افکندن . انداختن <span class=\"hlight\">:</span> <br />بفرمود تا مهتران هر کسی <br />به آب اندر آرند کشتی بسی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> دادن <span class=\"hlight\">:</span> <br />چو با لشکرم تن برنج آورم <br />ز روم و ز چین نام و گنج آورم .<br /> <font color=\"Red\">فردوسی .</font><br />برنج اندر آری تنت را رواست <br />که خود رنج بردن بدانش سزاست .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نهادن . گذاشتن <span class=\"hlight\">:</span> <br />همه دِه بویرانی آورد روی <br />درختان شده خشک وبی آب جوی .<br /> <font color=\"Red\">فردوسی .</font><br />شما تیغهادر نیام آورید<br />بر آئین شمشیر جام آورید.<br /> <font color=\"Red\">فردوسی .</font><br />سواران چو کشتی روان اندر اوی <br />بروی اندر آورده از کینه روی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> عرض کردن . گستردن . گفتن . خواستن، چنانکه عذری را، یا حاجتی را <span class=\"hlight\">:</span> <br />همی پوزش آرد بدین بد که کرد<br />به بیچارگی جست خواهد نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />ز دیدار تو شرم دارم همی <br />بدین کرده ها پوزش آرم همی .<br /> <font color=\"Red\">اسدی .</font><br />نیاز آورد هرکه یک روز پیشش <br />بماند همه عمر در بی نیازی .<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> تشریع کردن . آئین نهادن . نهادن . مرسوم کردن . معمول ساختن <span class=\"hlight\">:</span> <br />چنین گفت کآئین تخت و کلاه <br />کیومرث آورد کو بود شاه .<br /> <font color=\"Red\">فردوسی .</font><br />شاه شمیران را معلوم شد شراب خوردن، و بزم نهادن آئین آورد. (نوروزنامه ).<br /> <BR><font color=\"Blue\">◄</font> اتیان، چنانکه دینی را <span class=\"hlight\">:</span> زردشت بیرون آمد و دین گبری آورد. (نوروزنامه ). <BR><font color=\"Blue\">◄</font> پدید کردن . گرفتن (چنانکه خشم ). ابراز کردن . اظهار کردن . نمودن . آشکار کردن . ظاهر کردن . در میان نهادن . پیدا کردن <span class=\"hlight\">:</span> <br />یوز را هرچند بهتر پروری <br />چون یکی خشم آورد کیفر بری .<br /> <font color=\"Red\">رودکی .</font><br />شیر خشم آورد و جست از جای خویش <br />آمد آن خرگوش را آلغده پیش .<br /> <font color=\"Red\">رودکی .</font><br />اگر زو دل شاه کین آورد<br />همه رخنه در داد و دین آورد.<br /> <font color=\"Red\">فردوسی .</font><br />منم بار آن خسروانی درخت ...<br />که بر دست او شیر بیجان شود<br />چو خشم آورد پیل پیچان شود.<br /> <font color=\"Red\">فردوسی .</font><br />تو گر پیش شمشیر مهر آوری <br />سرت گردد آزرده زین داوری .<br /> <font color=\"Red\">فردوسی .</font><br />بجای گنه کار بر بی گناه <br />چو خشم آوری نیست آئین وراه .<br /> <font color=\"Red\">فردوسی .</font><br />چو خشم آوری هم پشیمان شوی <br />بپوزش نگهبان درمان شوی <br />هر آنگه که خشم آوردپادشا<br />سبک مایه خواند ورا، پارسا.<br /> <font color=\"Red\">فردوسی .</font><br />خم آورد پشت سنان ستیخ <br />سراپرده برکند وهفتاد میخ .<br /> <font color=\"Red\">فردوسی .</font><br />چو کیخسرو آگاه شد زین سخن <br />که کار نو آورد مرد کهن .<br /> <font color=\"Red\">فردوسی .</font><br />چو خرسند باشی تن آسان شوی <br />چو خشم آوری زآن هراسان شوی .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت خسرو ز کردار بد<br />چه داری بیاور ز گفتار بد.<br /> <font color=\"Red\">فردوسی .</font><br />نهند و ز هر گونه رای آورند<br />که این نغز بازی بجای آورند.<br /> <font color=\"Red\">فردوسی .</font><br />ز پیر جهاندیده بشنو سخُن <br />چو کژ آورد رای فرمان مکن .<br /> <font color=\"Red\">فردوسی .</font><br />ز پیری خم آورد بالای راست <br />هم از نرگسان روشنائی بکاست .<br /> <font color=\"Red\">فردوسی .</font><br />بگو تا چه داری بیار از خرد<br />که گوش نیوشنده زو بر خورد.<br /> <font color=\"Red\">فردوسی .</font><br />نشان پدر بایداندر پسر<br />روا نبود ار کمتر آرد هنر.<br /> <font color=\"Red\">فردوسی .</font><br />زره در بر و تیغ هندی بچنگ <br />چه زور آورد مرغ پیش نهنگ ؟<br /> <font color=\"Red\">فردوسی .</font><br />ز بس خشم دندانْش بر یکدگر <font color=\"DarkGreen\"><b>[ طوس ]</font></b><br />همی زد چو خشم آورد شیر نر.<br /> <font color=\"Red\">فردوسی .</font><br />کجا آورد دانش تو بها<br />چو آئی چنین در دم اژدها؟<br /> <font color=\"Red\">فردوسی .</font><br />همی خواست آید فرود اردشیر<br />دو مرد جوان دید در آبگیر<br />جوانان به آواز گفتند زود<br />عنان و رکابت بباید بسود<br />که رستی ز کام و دم اژدها<br />کنون آب خوردن نیارد بها.<br /> <font color=\"Red\">فردوسی .</font><br />او چون به بُست شد عصیان آورد اندر کثیربن احمد. (تاریخ سیستان ).<br />چه فضل آوریم ای پسر بر ستور<br />اگر همچو ایشان خوریم و مِریم ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />بیار آنچه داری ز مردی ّ و زور<br />که دشمن بپای خود آمد بگور.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوردن مانندچیزی را</span> ؛ اتیان مثل آن <span class=\"hlight\">:</span> قوت پیغامبران معجزات آمد یعنی چیزهائی که خلق از آوردن مانندآن عاجز آیند. (تاریخ بیهقی ).<br /> <BR><font color=\"Blue\">◄</font> پذیرفتن، چنانکه دینی را <span class=\"hlight\">:</span> <br />اگر من گناهی گران کرده ام <br />وگر کیش اهریمن آورده ام .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> گردانیدن <span class=\"hlight\">:</span> علی تکین را... در این فترات که افتاد بادی در سر کرده است بدان حد و اندازه که بود بازآوردن . (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> پوشیدن . کشیدن، چنانکه جامه را <span class=\"hlight\">:</span> <br />چون پرند بیدگون بر روی پوشد مرغزار<br />پرنیان هفت رنگ اندر سر آردکوهسار.<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> پنداشتن . شمردن . گرفتن <span class=\"hlight\">:</span> <br />اگر رزم گرشاسب یاد آوری <br />همه رزم رستم بباد آوری .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> دمیدن . نفخ <span class=\"hlight\">:</span> <br />آنکه بر شمع خداآرد پفو<br />شمع کی میرد بسوزد پوز او.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> گفتن <span class=\"hlight\">:</span> <br />بیارم کنون پاسخ اینهمه <br />بدان تا بگوئی بپیش رمه .<br /> <font color=\"Red\">فردوسی .</font><br />گفت این لطیفه بدیع آوردی و این نکته بدیع گفتی . (گلستان ). <BR><font color=\"Blue\">◄</font> بدست کردن . بحاصل کردن . تحصیل کردن . واجد شدن <span class=\"hlight\">:</span> <br />مگر شاه را نزد ماه آوریم <br />به نزدیک او پایگاه آوریم .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوردن مرضی را یا عیبی را</span>؛ بدان مبتلا شدن : باد آوردن، یا آب آوردن شکم . آب آوردن چشم . زردی آوردن . تب لازم آوردن <span class=\"hlight\">:</span> <br />اگر پادشا آز گنج آورد<br />تن زیردستان به رنج آورد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> همراه کردن . مع کردن <span class=\"hlight\">:</span> <br />همان به که با کینه داد آوریم <br />بکام اندرون، نام یاد آوریم .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نقل کردن . انتقال دادن، چنانکه نثری را بنظمی و بالعکس <span class=\"hlight\">:</span> <br />که این نامه را دست پیش آورم <br />ز دفتر بگفتار خویش آورم .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> گذرانیدن . درگذاشتن، چنانکه بشمشیر و جز آن <span class=\"hlight\">:</span> <br />سپهدار ترکان چو باد دمان <br />بتیغ آوریده سپه آن زمان <br />جهانجوی قارن چو آشفته پیل <br />زمین کرده از خون چو دریای نیل .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> سزا دادن . تلافی کردن . مکافات کردن . کیفر راندن <span class=\"hlight\">:</span> <br />که ضحاک کشته ست جم را بکین <br />دگر تور کشت ایرج پاکدین <br />بیزدان نگر تا ز دست دو شاه <br />بر ایشان چه آورد در رزمگاه .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> سبب شدن . موجب، مورث گشتن . تولید کردن <span class=\"hlight\">:</span> <br />نگر تا نگردد بگرد تو آز<br />که آز آورد خشم و بیم و نیاز.<br /> <font color=\"Red\">فردوسی .</font><br />طَمْع خام است آن مخور خام ای پسر<br />خام خوردن علت آرد در بشر.<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">باد باران آورد بازیچه جنگ </span> ؛ مزاح بسیار، گاه بجدال و نزاع کشد.<br /> <span class=\"hlight\">حرف حرف می آرد</span> ؛ گفتاری بد گفتاری بد را سبب شود.<br /> <span class=\"hlight\">دشمنی دشمنی آرد</span> ؛ عداوت تولید عداوت کند.<br /><span class=\"hlight\">هستی می آرد مستی </span> ؛ تمول و رفاه و خصب، مورث برتنی و کبر شود.<br /> <BR><font color=\"Blue\">◄</font> سود دادن . نفع آوردن .فایده دادن <span class=\"hlight\">:</span> و شبه در بازار جوهریان جوی نیارد. (گلستان ). <BR><font color=\"Blue\">◄</font> درآوردن <span class=\"hlight\">:</span> <br />مرا گر نه پیری ببستی بجای <br />بتنهائی آوردَمیشان ز پای .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> جُستن . کشیدن، چنانکه کین را <span class=\"hlight\">:</span> <br />که او از پی فور کین آورد<br />بکین آسمان بر زمین آورد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> خطور دادن . گذرانیدن، چنانکه اندیشه ای را بخاطر <span class=\"hlight\">:</span> <br />تهمتن بدو گفت یک هفته شاد<br />بباشیم تا پاسخ آریم یاد.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نصیب، روزی، قسمت کردن <span class=\"hlight\">:</span> <br />وزآن باره چندی ز ترکان بزیر<br />نگون اندرآمد بکردارشیر<br />که آرد بدو شوربختی جهان <br />بدام اندر آید سرش ناگهان .<br /> <font color=\"Red\">فردوسی .</font><br />بدان تا چه فرمایدم شهریار<br />چه کردش از این کار پروردگار.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> تعمیر، ترمیم، مرمت، عمارت کردن . ساختن . برآوردن <span class=\"hlight\">:</span> <br />از ایران دگر هرچه ویران شده ست <br />کنام پلنگان و شیران شده ست <br />سراسر برآری بدینار خویش <br />ببینی مکافات کردار خویش .<br /> <font color=\"Red\">فردوسی .</font><br />صدقه ٔ جاریه آن است که پادشاهان مدرسه ها سازند و وقفها کنند و مساجد و خانیها و چشمه سارها و کهریزها آورند. (راحةالصدور راوندی ). <BR><font color=\"Blue\">◄</font> متوجه کردن . گرفتن چنانکه چیزی را برابر چیزی <span class=\"hlight\">:</span> پس روی عتاب از من بجانب درویش آورد و گفت . (گلستان ). <BR><font color=\"Blue\">◄</font> گذاردن، چنانکه خبر و آگاهی را <span class=\"hlight\">:</span> خبری که دانی دلی بیازارد تو خاموش تا دیگری بیارد. (گلستان ). <BR><font color=\"Blue\">◄</font> پیدا کردن <span class=\"hlight\">:</span> صاحبدلی را گفتند بدین خوبی که آفتاب است نشنیده ایم که کس او را دوست گرفته است و عشق آورده . (گلستان ). <BR><font color=\"Blue\">◄</font> افکندن . انداختن، چنانکه حاجت کسی را بکسی <span class=\"hlight\">:</span> <br />مرا گفت کز من چه آید همی <br />که جانت سخن برگراید همی <br />بچیزی که باشد مرا دسترس <br />بکوشم نیازت نیارم بکس .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مایل، متمایل کردن . جلب کردن <span class=\"hlight\">:</span> <br />دل کینه ورْشان <font color=\"DarkGreen\"><b>[ سلم و تور را ]</font></b> بدین آورم <br />سزاوارتر زآنکه کین آورم .<br /> <font color=\"Red\">فردوسی .</font><br />که راند بدان مرز فرمان او<br />دل هر کس آرد به پیمان او.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نسبت کردن . منسوب داشتن . بستن، چنانکه عیب و نقصی را <span class=\"hlight\">:</span> <br />تو عیب کسان هیچگونه مجوی <br />که عیب آورد بر تو بر عیبجوی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> بدل کردن . تبدیل کردن <span class=\"hlight\">:</span> <br />چو خشنود از او در جهان کس نبود<br />تو او را نهان داری از من چه سود<br />وگر زو تو خشنودی ای دادگر<br />مرا بازگردان زپیکار سر<br />بکش در دل این آتش کین من <br />به آئین خویش آر آئین من .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> خلق . ایجاد. ابداع <span class=\"hlight\">:</span> <br />وی باد صبا اینهمه آورده ٔ تست .<br />رجوع به آورده شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">با هم آوردن </span> ؛ تقبیض .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فراهم آوردن </span> ؛ گرد کردن . جمع کردن .<br />صرف مشتقات این مصدر منتظم است . و رجوع به آردن و آوریدن شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2722, 'آوردنی', '<span class=\"hlight\">آوردنی .</span> <font color=\"DarkGreen\"><b>[ وَ دَ ]</font></b> (ص لیاقت، اِ) درخور آوردن . ازدرِ آوردن . <BR><font color=\"Blue\">◄</font> آنچه باید آوردن <span class=\"hlight\">:</span> <br />ز پوشیدنی هم ز آکندنی <br />ز هرسو بیاورد آوردنی .<br /> <font color=\"Red\">فردوسی .</font><br />کنیم از سر آباد با خوردنی <br />بیاریم هر چیز آوردنی .<br /> <font color=\"Red\">فردوسی .</font><br />گیاشان بود زآن سپس خوردنی <br />بپویند هر سو به آوردنی .<br /> <font color=\"Red\">فردوسی .</font><br />ز پوشیدنی ّ و ز گستردنی <br />ز هر چیز کآن هست آوردنی .<br /> <font color=\"Red\">فردوسی .</font><br />یکی چاره ای ساخت درخوردنی <br />بیاورد هر گونه آوردنی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> واردات، مقابل صادرات <span class=\"hlight\">:</span> <br />ز ماهی بدیشان همه خوردنی <br />ز جائی نبد راه آوردنی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> هدیه . ارمغان . پیشکش . حمل <span class=\"hlight\">:</span> <br />گذرها که راه دلیران بُده ست <br />ببینیم تا چند ویران شده ست <br />کنیم از سر آباد، با خوردنی <br />بیائیم و آریمش آوردنی .<br /> <font color=\"Red\">فردوسی .</font><br />ز آوردنیهای شاهانه نیز<br />در آن عرضه گه برد بسیار چیز.<br /><font color=\"Red\">هاتفی .</font><br /></font></div>'),
(2723, 'آورده', '<span class=\"hlight\">آورده .</span> <font color=\"DarkGreen\"><b>[ وَدَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) بحاصل کرده . ابداع کرده <span class=\"hlight\">:</span> <br />وی باد صبا اینهمه آورده ٔ تست .<br /><font color=\"Red\">سراج قمری .</font><br /></font></div>'),
(2724, 'آوردگاه', '<span class=\"hlight\">آوردگاه .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ مرکب ) معرک . معرکه . جنگ گاه . آوردگه . ناوردگه . ناوردگاه . میدان . میدان جنگ . رزمگاه . عرصه ٔ جنگ <span class=\"hlight\">:</span> <br />بکین جستن از دشت آوردگاه <br />برآرم بخورشید گرد سیاه .<br /> <font color=\"Red\">فردوسی .</font><br />برفتند هر دو ز قلب سپاه <br />بیک سو کشیدند از آوردگاه .<br /> <font color=\"Red\">فردوسی .</font><br />همی گشت با او به آوردگاه <br />خروشی برآمد ز پشت سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />بزانوش بنشست و اندیشه کرد<br />ز رزم و ز آوردگاه و نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />یکی باغ بد در میان سپاه <br />از این روی و آن روی آوردگاه .<br /> <font color=\"Red\">فردوسی .</font><br />فلک ز ترس فراموش کرد دوران را<br />چو اسب شاه در آوردگاه جولان کرد.<br /> <font color=\"Red\">مسعود سعد.</font><br /> <br /> <BR><font color=\"Blue\">◄</font> از امثله ٔ ذیل ظاهراً چنین مستفاد می شود که آورد در آوردگاه مرکب از آورد به معنی ناورد و جنگ نیست بلکه آورد به معنی جولان اسب و آدمی و مانند آن است و آوردگاه وسعت و فسحت و مکانی بوده بمعنی جولانگاه و میدان جولان اسب یا مسابقه ٔ آدمی و غیره <span class=\"hlight\">:</span> <br />نهادند آوردگاهی بزرگ <br />دو جنگی بکردار ارغنده گرگ <br />به آوردگه شد سپه، پهلوان <br />بقلب اندرون با گروه گوان .<br /> <font color=\"Red\">فردوسی .</font><br />اسیران و سرها همه گرد کرد<br />ببردند از آوردگاه نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />بباغ اندر آوردگاهی گرفت <br />چپ و راست هر گونه راهی گرفت <br />همی هر زمان اسب برگاشتی <br />و از ابر سیه نعره بگذاشتی .<br /> <font color=\"Red\">فردوسی .</font><br />امیر غازی محمود رای میدان کرد<br />نشاط مرکب میمون و گوی و چوگان کرد<br />زمین میدان بر اوج چرخ فخر آورد<br />چوشاه گیتی رای و نشاط میدان کرد<br />فلک ز ترس فراموش کرد دوران را<br />چو اسب شاه برآوردگاه جولان کرد<br />ز بیم آنکه رسد گوی شاه بر خورشید<br />بگرد تاری خورشید روی پنهان کرد.<br /> <font color=\"Red\">مسعودسعد.</font><br />و رجوع به آورد و آوردگه شود.<br /></font></div>'),
(2725, 'آوردگه', '<span class=\"hlight\">آوردگه .</span> <font color=\"DarkGreen\"><b>[ وَ گ َه ْ ]</font></b> (اِ مرکب ) آوردگاه . رزمگاه . میدان . میدان جنگ <span class=\"hlight\">:</span> <br />به آوردگه رفت نیزه به دست <font color=\"DarkGreen\"><b>[ سیاوش ]</font></b><br />عنان را بپیچید چون پیل مست .<br /> <font color=\"Red\">فردوسی .</font><br />به آوردگه شد سپه، پهلوان <br />بقلب اندرون با گروه گوان .<br /> <font color=\"Red\">فردوسی .</font><br />بگفت این و بگرفت نیزه بدست <br />به آوردگه رفت چون پیل مست .<br /> <font color=\"Red\">فردوسی .</font><br />گو پیلتن گفت جنگی منم <br />به آوردگه بر درنگی منم .<br /> <font color=\"Red\">فردوسی .</font><br /> <br /> <BR><font color=\"Blue\">◄</font> در بیت ذیل فرخی آوردگه معنی چراگاه و گشتنگاه میدهد <span class=\"hlight\">:</span> <br />معدن زاغ شد آرامگه کبک و تذرو<br />مسکن شیر شد آوردگه گور و غزال .<br /> <font color=\"Red\">فرخی .</font><br />و رجوع به آورد و آوردگاه شود.<br /></font></div>'),
(2726, 'آوردیدن', '<span class=\"hlight\">آوردیدن .</span> <font color=\"DarkGreen\"><b>[ وَ دی دَ ]</font></b> (مص ) حمله کردن . جنگ آوری . (برهان ). رزم دادن . نبرد. حرب و مجادله کردن .<br /></font></div>'),
(2727, 'آورطی', '<span class=\"hlight\">آورطی .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (از یونانی، اِ) رجوع به آورتی شود.<br /></font></div>'),
(2728, 'آورنجن', '<span class=\"hlight\">آورنجن .</span> <font color=\"DarkGreen\"><b>[ وَ رَ ج َ ]</font></b> (اِ) آبرنجن . برنجن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">پای آورنجن </span> ؛ پاآبرنجن . خدمه . خلخال .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دست آورنجن </span> ؛ دست آبرنجن . دست برنجن . دست بند. سِوار. جباره .<br /></font></div>'),
(2729, 'آورند', '<span class=\"hlight\">آورند.</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) اورند. اروند. مکر و فریب و حیله . آرنگ . رجوع به اَورند و اروند شود.<br /></font></div>'),
(2730, 'آورند', '<span class=\"hlight\">آورند.</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) دجله ٔ بغداد. <BR><font color=\"Blue\">◄</font> رود نیل . (برهان ).<br /></font></div>'),
(2731, 'آورنده', '<span class=\"hlight\">آورنده .</span> <font color=\"DarkGreen\"><b>[ وَ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه آورد.<br /></font></div>'),
(2732, 'آوره', '<span class=\"hlight\">آوره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) اَبرَه . ظهاره .<br /></font></div>'),
(2733, 'آوره', '<span class=\"hlight\">آوره .</span> <font color=\"DarkGreen\"><b>[ رَه ْ ]</font></b> (اِ مرکب ) آبراهه . گذرگاه آب . معبر آب .<br /></font></div>'),
(2734, 'آورود کردن', '<span class=\"hlight\">آورود کردن .</span> <font color=\"DarkGreen\"><b>[ک َ دَ ]</font></b> (مص مرکب ) آورید کردن . ارید کردن . اُرود کردن . رود کردن . روده کردن . رجوع به آورید کردن شود.<br /></font></div>'),
(2735, 'آورچه', '<span class=\"hlight\">آورچه .</span><font color=\"DarkGreen\"><b>[ وَ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ) به معنی آوارجه است که دفتر حسابهای پراکنده باشد. (برهان ). رجوع به آوارجه شود.<br /></font></div>'),
(2736, 'آورک', '<span class=\"hlight\">آورک .</span> <font color=\"DarkGreen\"><b>[ وَ رَ ]</font></b>(اِ) تاب . اَورک . و آن طنابی است دو سوی آن بر بالائی استوار کرده که بر آن نشسته در هوا آیند و روند.<br /></font></div>'),
(2737, 'آوری', '<span class=\"hlight\">آوری .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ص نسبی ) موقن . مؤمن . معتقد. صاحب یقین . گرویده <span class=\"hlight\">:</span> <br />کسی کو بمحشر بود آوری <br />ندارد بکس کینه و داوری .<br /> <font color=\"Red\">ابوشکور.</font><br /> <BR><font color=\"Blue\">◄</font> یقین و درست . (صحاح الفرس ). <BR><font color=\"Blue\">◄</font> (ق ) بی خلاف . بالقطع <span class=\"hlight\">:</span><br />مردمان هموار دانند، آوری <br />کز نهان من تو خود آگه تری (کذا).<br /> <font color=\"Red\">رودکی .</font><br />یکی گفت ما را بخوالیگری <br />بباید بر شاه رفت، آوری <br />وزآن پس یکی چاره ای ساختن <br />ز هر گونه اندیشه انداختن <br />مگر زین دو تن را که ریزند خون <br />یکی را توان آوریدن برون .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2738, 'آوری', '<span class=\"hlight\">آوری .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (حامص ) در استخوان آوری، بارآوری، بخت آوری، بیخ آوری، تناوری، جان آوری، خارآوری، خطآوری، دل آوری، دنبه آوری، دین آوری، ریش آوری، زبان آوری، زورآوری، سروآوری، سودآوری، شتاب آوری، کین آوری، گندآوری ونظائر آن به معنی آوردن و آوریدن باشد <span class=\"hlight\">:</span> <br />میان را ببستی بکین آوری <br />بایران نکردی کسی سروری .<br /> <font color=\"Red\">فردوسی .</font><br />یکی سرو فرمود کشتن بدست <br />بدین آوری راه پیشین ببست .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2739, 'آورید کردن', '<span class=\"hlight\">آورید کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) (شاید از: آب + رُفت ) آورود کردن . اُرید کردن . رود کردن . روده کردن . تمام برکندن پَر مرغ کشته . <BR><font color=\"Blue\">◄</font> در آب جوشان نهادن حیوانی کشته تا پر یا پشم آن را آسان توان باز کردن .<br /></font></div>'),
(2740, 'آوریدن', '<span class=\"hlight\">آوریدن .</span> <font color=\"DarkGreen\"><b>[ وَ دَ ]</font></b> (مص ) آوردن، مقابل بردن <span class=\"hlight\">:</span> <br />به پیش آوریدند آهنگران <br />غل و بند و زنجیرهای گران .<br /> <font color=\"Red\">فردوسی .</font><br />سپهبد هر آنجا که بد موبدی ...<br />ز کشور به نزدیک خویش آورید<br />بگفت آن جگرخسته خوابی که دید.<br /> <font color=\"Red\">فردوسی .</font><br />بشد تیز نعمان صد اسب آورید<br />ز اسبان جنگ آوران برگزید.<br /> <font color=\"Red\">فردوسی .</font><br />ز دینار با هر یکی سی هزار<br />نثار آوریده بر شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />نثارآورید او چو روز نخست <br />ز گوهر بسی اندرون مایه جست .<br /> <font color=\"Red\">فردوسی .</font><br />جهان سر نهادند سوی عزیز<br />بسی آوریدند هر گونه چیز.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />چنین آوریدیم چیزی حقیر<br />ز روغن ز ریچال و کشک و پنیر.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />مر آن را <font color=\"DarkGreen\"><b>[ یوسف را ]</font></b> در آن پیشگاه آورید<br />بر تخت دستور شاه آورید.<br /> <font color=\"Red\">شمسی (یوسف وزلیخا).</font><br />بندیش که کردگار گیتی <br />از بهر چه آوریدت ایدر.<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> رسانیدن . ابلاغ <span class=\"hlight\">:</span> <br />درود آوریدش خجسته سروش <br />کزین بیش مخْروش و بازآر هوش .<br /> <font color=\"Red\">فردوسی .</font><br />سیاوش یکی جایگه ساخت نغز<br />پسندیده ٔ مردم پاک مغز<br />مگر خود سروش آوریدش خبر<br />که چونان نگارید آن شهر و بر.<br /> <font color=\"Red\">فردوسی .</font><br />ز دزدی ّ صاع آوریده خبر<br />بدین داستان من شدم چون شرر.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />به یوسف ز یزدان سلام آورید<br />نه تنها که با این پیام آورید.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />مر او را سلام آورید از خدای <br />جهان آفرین خالق رهنمای .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />تن خویشتن را بیوسف نمود<br />ز یزدان سلام آورید و درود.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> گزیدن بشاهی <span class=\"hlight\">:</span> و از این پس یزدجرد شهریار را آوریدند. چون بنشست روزگار خلافت ... عمر خطاب بود. (مجمل التواریخ ).<br /> <BR><font color=\"Blue\">◄</font> گذرانیدن، چنانکه به شمشیر <span class=\"hlight\">:</span> <br />سپهدار ترکان چو باد دمان <br />بتیغ آوریده سپه آن زمان <br />جهانجوی قارَن چون آشفته پیل <br />زمین کرده از خون چو دریای نیل .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> بردن . رسانیدن، چنانکه مدت و اجلی را <span class=\"hlight\">:</span> <br />که گیتی سپنج است و جاوید نیست <br />فری برتر از فرّ جمشید نیست <br />سپهر بلندش بپای آورید<br />جهان را جز او کدخدای آورید.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> کردن <span class=\"hlight\">:</span> <br />سپاهی که نوروز گرد آورید<br />همه نیست کردش ز ناگه شجام .<br /> <font color=\"Red\">دقیقی .</font><br />ز گرد آوریدن که یابد بهی <br />که میرفت باید به دست تهی .<br /> <font color=\"Red\">فردوسی .</font><br />جهاندار سی سال از این پیشتر<br />چگونه پدید آوریدی گهر<br />برفت و سر آمد بر او روزگار<br />همه رنج او ماند از او یادگار.<br /> <font color=\"Red\">فردوسی .</font><br />به پیران ویسه چنین گفت شاه <font color=\"DarkGreen\"><b>[ افراسیاب ]</font></b><br />که گفتم بیاور ز هر سو سپاه <br />درنگ آوریدی تو از کاهلی <br />سبب پیری آمد و گر بددلی .<br /> <font color=\"Red\">فردوسی .</font><br />تو و مادرت هر دو از چنگ دیو<br />برون آوریدم به رای و به ریو.<br /> <font color=\"Red\">فردوسی .</font><br />بدست آوریده خردمند سنگ <br />به نایافته دُرّ نَدْهد زچنگ .<br /> <font color=\"Red\">اسدی .</font><br />بدان ای پدر کآخر کار من <br />بخیر آوریده ست دادار من .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />چنین گفت کای داور ماه و مهر<br />پدید آوریدی زمین و سپهر.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بنظم آوریدم بسی داستان <br />از افسانه و گفته ٔ باستان .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بکار آمد آنها که برداشتند<br />نه گرد آوریدند و بگذاشتند.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> نهادن <span class=\"hlight\">:</span> <br />یک آهوست خان را چو ناریش پیش <br />چو پیش آوریدی صد آهوش بیش .<br /> <font color=\"Red\">ابوشکور.</font><br />برفتند فرمانبران پیش اوی <br />به نزدیک جهن آوریدند روی .<br /> <font color=\"Red\">فردوسی .</font><br />نشستند با ماه دو مهرجوی <br />شب و روز روی آوریده بروی .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> کشیدن <span class=\"hlight\">:</span> <br />تا سمو سر برآورید ز دشت <br />گشت زنگارگون همه لب کشت <br />هر یکی کاردی ز جان <font color=\"DarkGreen\"><b>[ کذا ]</font></b> برداشت <br />تا برند از سمو طعامک چاشت .<br /> <font color=\"Red\">رودکی .</font><br />بچنگ آمدش چند گونه گهر<br />چو یاقوت و بیجاده و سیم و زر<br />ز خارا بافسون برون آورید<br />شد آراسته بندها را کلید.<br /> <font color=\"Red\">فردوسی .</font><br />بسی آفرین بزرگان بگفت <br />بدان کش برون آورید از نهفت .<br /> <font color=\"Red\">فردوسی .</font><br />سر مرد تازی <font color=\"DarkGreen\"><b>[ ضحاک ]</font></b> بدام آورید <font color=\"DarkGreen\"><b>[ ابلیس ]</font></b><br />چنان شد که فرمان او برگزید.<br /> <font color=\"Red\">فردوسی .</font><br />همه خلعت شاه پیش آورید<br />بر او آفرین کرد هر کس که دید.<br /> <font color=\"Red\">فردوسی .</font><br />دوپاکیزه از خانه ٔ جمّشید<br />برون آوریدند لرزان چو بید.<br /> <font color=\"Red\">فردوسی .</font><br />جدا کرد گاو و خر و گوسفند<br />بورز آورید آنچه بد سودمند.<br /> <font color=\"Red\">فردوسی .</font><br />چو یک چند بگذشت او شد بلند<br />بنخجیر شیر آوریدی به بند.<br /> <font color=\"Red\">فردوسی .</font><br />بزد کوس و لشکر برون آورید<br />ز هامون بدریای خون آورید.<br /> <font color=\"Red\">فردوسی .</font><br />بیاورد گستهم آن خواسته <br />که جهنش فرستاد آراسته <br />به نزدیک شاه جهان آورید<br />چو خسرو مر آن را همه بنگرید<br />ببخشید جمله بایرانیان ...<br /> <font color=\"Red\">فردوسی .</font><br />چو آن کاسه ٔ زهر پیش آورید<br />نگه کرد موبد بدو بنگرید.<br /> <font color=\"Red\">فردوسی .</font><br />شتر زیر بار آوریدند زود.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> پدید کردن . پیدا کردن <span class=\"hlight\">:</span> <br />چون کَشَف انبوه غوغائی بدید<br />بانگ و زخ ّ مردمان خشم آورید .<br /> <font color=\"Red\">رودکی .</font><br />از آن جوی راحت که راه آورید<br />شب و روز و خورشید و ماه آورید.<br /> <font color=\"Red\">فردوسی .</font><br />دو سد برفرازید و جنگ آورید<br />همه رسم و راه پلنگ آورید.<br /> <font color=\"Red\">فردوسی .</font><br />مرا آنگه آمد بکف باز تن <br />که مهر آوریدم بفرزند من .<br /> <font color=\"Red\">فردوسی .</font><br />تگرگ آوریدند با باد سخت <br />پس از باد سرما که درّد درخت .<br /> <font color=\"Red\">اسدی .</font><br />دل یوسف آئین و رای آورید<br />ره کدخدائی بجای آورید.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> حامل بودن، چنانکه پیغامی را <span class=\"hlight\">:</span> <br />بگوید که روشن دلی شیده نام <br />بشاه آوریده ست چندین پیام .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت رستم که از پهلوان <br />پیام آوریدم بروشن روان .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> آفریدن .خلق کردن <span class=\"hlight\">:</span> <br />بدان کردگاری که چرخ آفرید<br />ستاره نمود و زمین آفرید.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />نهال فتنه در دلها تو کشتی <br />در آغاز خلایق آوریدن .<br /> <font color=\"Red\">(منسوب به ناصرخسرو).</font><br /> <BR><font color=\"Blue\">◄</font> عرض کردن . گستردن . گستریدن <span class=\"hlight\">:</span> <br />نبایستی تو گفتارش شنیدن <br />چو بشنیدی به پیشم آوریدن .<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> حمله کردن . جنگ آوری نمودن . (برهان ) (انجمن آرای ناصری ). شاهدی برای این معنی دیده نشد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بجای آوریدن </span> ؛ گزاردن . اجرا کردن <span class=\"hlight\">:</span> <br />هر آنکس که فرمان بجای آورید<br />سپاه شهنشه بدو ننگرید.<br /> <font color=\"Red\">فردوسی .</font><br />اگر کژ اگر راست پوینده اند<br />همه کس ره راست جوینده اند<br />ولیکن درست آوریدن بجای <br />مر آن را نماید که خواهد خدای .<br /> <font color=\"Red\">اسدی .</font><br />تو آنچ از پیمبر رسیدت بگوش <br />ببین و بجای آوریدن بکوش .<br /> <font color=\"Red\">اسدی .</font><br />بفرمود پس یوسف دین پناه <br />بجای آوریدند فرمان شاه .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />چو لختی پرستش بجای آورید<br />زمانی بسی شکرها گسترید.<br /> <font color=\"Red\">شمسی (یوسف وزلیخا).</font><br />بشد مرد و بسیار گرمی نمود<br />بجا آورید آنچه فرموده بود.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">زیر (بزیر) آوریدن </span> ؛ بزمین پیوستن . پست کردن . بر زمین زدن . برزمین افکندن . مغلوب کردن . مقهور کردن <span class=\"hlight\">:</span> <br />کجات آن شبیخون ناگه چو شیر<br />که شیر ژیان آوریدی بزیر؟<br /> <font color=\"Red\">فردوسی .</font><br />دگر نامور گرد سهراب شیر<br />که پیل ژیان آوریدی بزیر.<br /> <font color=\"Red\">فردوسی .</font><br />دوفرزند بودش <font color=\"DarkGreen\"><b>[ لهراسب را ]</font></b> بسان دو ماه <br />سزاوار شاهی ّ و تخت و کلاه <br />یکی نام گشتاسب دیگر زریر<br />که زیر آوریدی سر نرّه شیر.<br /> <font color=\"Red\">فردوسی .</font><br />نبرده برادرْم فرخ زریر<br />که شیر ژیان آوریدی بزیر.<br /> <font color=\"Red\">فردوسی .</font><br />وزآن پس چو جنبنده آمد پدید<br />همه رستنی زیر خویش آورید.<br /> <font color=\"Red\">فردوسی .</font><br />شه غرچگان بود برسان شیر<br />کجا پشت پیل آوریدی بزیر.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت اولاد کای نرّه شیر<br />جهان را به تیغآوریدی بزیر.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فراز آوریدن </span> ؛ گردکردن <span class=\"hlight\">:</span> <br />چو گسترد خورشید دیبای زرد<br />بجوشید دریای دشت نبرد...<br />دو سالار هر دو بسان پلنگ <br />فراز آوریدند لشکر بجنگ .<br /> <font color=\"Red\">فردوسی .</font><br />فراز آوریدند بیمر سپاه <br />ز شادی بریدند و آرامگاه .<br /> <font color=\"Red\">فردوسی .</font><br />چو آن نامه برخواند <font color=\"DarkGreen\"><b>[ نامه ٔ گراز ]</font></b> قیصر، سپاه <br />فراز آورید از پی رزمگاه .<br /> <font color=\"Red\">فردوسی .</font><br />چو دیوار، پیلان به پیش سپاه <br />فراز آوریدندو بستند راه .<br /> <font color=\"Red\">فردوسی .</font><br />بوقت خواستن آسان دهد بزائر زر<br />اگر چه هست فراز آوریدنش دشوار.<br /> <font color=\"Red\">فرخی .</font><br />بدیدی که ما را پس از کین سخت <br />بهم چون فراز آوریده ست بخت .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><BR>۩ بیاوردن <span class=\"hlight\">:</span> <br />بگویش که من نامه ٔ نغزناک <br />فراز آوریدستم از مغز پاک .<br /> <font color=\"Red\">ابوشکور یا عنصری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فرودآوریدن </span> ؛ پیاده کردن . در جائی متوقف ساختن <span class=\"hlight\">:</span> <br />بدان مرز لشکر فرود آورید <font color=\"DarkGreen\"><b>[ طوس ]</font></b><br />زمین گشت از آن خیمه ها ناپدید.<br /> <font color=\"Red\">فردوسی .</font><br />بدینگونه تا شهر هَمْدان رسید<br />بجائی که لشکر فرود آورید.<br /> <font color=\"Red\">فردوسی .</font><br />چو خسرو به نزدیک ایشان رسید<br />به بیرونْش لشکر فرود آورید.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فرود آوریدن از تخت </span> ؛ خلع کردن از پادشاهی <span class=\"hlight\">:</span> <br />براندیش از کار پرویزشاه <br />از آن ناسزاوار کار تباه <br />چو او را فرود آوریدی ز تخت <br />شد از تخم ساسان بیکبار بخت .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2741, 'آوریز', '<span class=\"hlight\">آوریز.</span> (اِ مرکب ) آبریز.<br /></font></div>'),
(2742, 'آوشن', '<span class=\"hlight\">آوشن .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِ) آویشن . اَوشن . یَوشن . سَعتر.و اینکه بعض فرهنگ نویسان کاکوتی را مرادف دیگر این کلمه آورده اند غلط است، چه کاکوتی گیاه دیگری است .<br /></font></div>'),
(2743, 'آول و تاول', '<span class=\"hlight\">آول و تاول .</span> <font color=\"DarkGreen\"><b>[ وَ ل ُ تا وَ ]</font></b> (اِ مرکب، از اتباع ) پر از جراحت . پر از سوختگی . پر از جای گزیدگی .<br /></font></div>'),
(2744, 'آوله', '<span class=\"hlight\">آوله .</span> <font color=\"DarkGreen\"><b>[ وِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) آبِله .<br /></font></div>'),
(2745, 'آون', '<span class=\"hlight\">آون .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ص، اِ) مخفف آونگ . نگون . معلق . آویزان . آویخته . دروا.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آون کردن میوه </span> ؛ به آونگ کردن آن <span class=\"hlight\">:</span> <br />همه مردم از دانه خرمن کنند<br />ز انگور دوشاب و آون کنند.<br /> <font color=\"Red\">شمسی (یوسف وزلیخا).</font><br /> <br /></font></div>'),
(2746, 'آون', '<span class=\"hlight\">آون .</span> <font color=\"DarkGreen\"><b>[ وِ ]</font></b> (اِ) در لهجه ٔ عرب اندلس «ابن » بوده و از اینرو کنیه ها مَبْدُوّ بابن عربی که از آن طریق داخل مغرب شده است بهمان صورت باقیست : آون پاس بجای ابن باجه .<br /></font></div>'),
(2747, 'آون پاس', '<span class=\"hlight\">آون پاس .</span> <font color=\"DarkGreen\"><b>[ وِم ْ ]</font></b> (اِخ ) آوِمْپاس . مصحف نام ابن باجه، نزد مردم اروپا.<br /></font></div>'),
(2748, 'آوند', '<span class=\"hlight\">آوند.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ) (از: آو، آب + وند، خنور) اناء. ظرف . خنور. وعاء. باردان . <BR><font color=\"Blue\">◄</font> کوزه ٔ آب . ظرف شراب . کوزه ٔ شراب . خنور آب . (المعجم ) <span class=\"hlight\">:</span> <br />چون آب بگونه ٔ هر آوند شوی .<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی (از فرهنگ اسدی ).</font><br />مبادا ساغرش یک لحظه از خون رزان خالی <br />فلک راتا رود خون شفق زین نیلی آوندش .<br /> <font color=\"Red\">عمید لوبکی .</font><br />که بنیت آدمی چون آوندی ضعیف است . (کلیله و دمنه ).<br />شودهر سفالی که آوند می <br />بر ما بود بهتر از تاج کی .<br /> <font color=\"Red\">؟ (از فرهنگها).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوند شراب </span> ؛ قحف . بط.صراحی . صراحیه . بلبله . باطیه . ناجو. قرابه .<br /><BR><font color=\"Blue\">◄</font> تخت و مسند. <BR><font color=\"Blue\">◄</font> شطرنج . <BR><font color=\"Blue\">◄</font> اول و نخست . و باین معنی بکسر ثالث هم گفته اند. (برهان ). <BR><font color=\"Blue\">◄</font> صولجان .<br /></font></div>'),
(2749, 'آوند', '<span class=\"hlight\">آوند.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ) وعاء، که بفرانسه وِسو گویند. (فرهنگستان ).<br /></font></div>'),
(2750, 'آوند', '<span class=\"hlight\">آوند.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ) دلیل . بیّنه . (برهان ). حجت <span class=\"hlight\">:</span> <br />چنین گفت با پهلوان زال زر<br />گر آوند خواهی به تیغم نگر.<br /> <font color=\"Red\">فردوسی .</font><br /> <br /> <BR><font color=\"Blue\">◄</font> آونگ <span class=\"hlight\">:</span> <br />بر بستر غم خفت عدوی تو چنان زار<br />کش تن شود از تار قزا کند شکسته <br />وز دار عنان گشت حسود تو نگونسار<br />چون خوشه ٔ انگور بر آوند شکسته .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(2751, 'آوند', '<span class=\"hlight\">آوند.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (پسوند) َاوند. وَند. مند. اومند. دارا. صاحب . مالک . و شاید وند در زین آوند و ستاوند و ستناوند از این قبیل باشد، و در کلمات خداوند و پساوند و پژاوند و زرآوند، و نیز بعض اسماء امکنه مثل نهاوند و دماوند و فراوند و الوند معنی آن بر نگارنده مجهول است .<br /></font></div>'),
(2752, 'آوندی', '<span class=\"hlight\">آوندی .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ) ظرفی که شراب در آن کنند. (برهان ). <BR><font color=\"Blue\">◄</font> (ص نسبی ) وعائی .<br /></font></div>'),
(2753, 'آونه', '<span class=\"hlight\">آونه .</span> <font color=\"DarkGreen\"><b>[ وِ ن َ ]</font></b> (ع اِ) ج ِ اوان . وقتها. <BR><font color=\"Blue\">◄</font> سنگ پشتها، و بدین معنی جمعی است بی مفرد.<br /></font></div>'),
(2754, 'آونوس', '<span class=\"hlight\">آونوس .</span> (اِ) آبنوس .<br /></font></div>'),
(2755, 'آونگ', '<span class=\"hlight\">آونگ .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ) رشته ای که انگور و دیگر میوه بندند و آویزند (فرهنگ اسدی، خطی )، و این کار برای تازه ماندن و گنده نشدن میوه است به زمستان . معلاق . آوند. بند <span class=\"hlight\">:</span> <br />چون برگ لاله بودم <font color=\"DarkGreen\"><b>[ من ]</font></b> واکنون <br />چون سیب پژمریده بر آونگم .<br /><font color=\"Red\">رودکی .</font><br />دختر رز که تو بر طارم تاکش دیدی <br />مدتی شد که در آونگ سرش در کنب است .<br /> <font color=\"Red\">انوری .</font><br /> <BR><font color=\"Blue\">◄</font> (ص ) آویخته . معلق . دَرْوا. آونگان . آویزان . دلنگان <span class=\"hlight\">:</span> <br />عیار حلم گرانش پدید نتوان کرد<br />اگر سپهر ترازو شود زمین پاسنگ <br />هزاریک گر از آن زآسمان درآویزد<br />چنان بود که ز کاهی کُهی کنند آونگ .<br /> <font color=\"Red\">فرخی .</font><br />وآنگه او را سوی دروازه ٔ گرگانج برند<br />سرنگون باد گران از سر پیلان آونگ .<br /> <font color=\"Red\">فرخی .</font><br />بخت مردی است از قیاس دو روی <br />خلق گشته بدو درون، آونگ .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آونگ دوزخیم بزنجیر معصیت <br />دوزخ نهنگ و ما چو یکی لقمه ٔ نهنگ .<br /> <font color=\"Red\">سوزنی .</font><br />نگونش در آن چاه آونگ کرد<br />هنوز اندر آنجاست آونگ مرد.<br /> <font color=\"Red\">زجاجی .</font><br /> <BR><font color=\"Blue\">◄</font> هر چیز درآویخته و معلق و دروا: انگور، خربزه، سیب، هندوانه ٔ آونگ <span class=\"hlight\">:</span> <br />توئی که خوشه ٔ پروین بر این بلند رواق <br />ز بهر نقل جلال تو بسته اند آونگ .<br /><font color=\"Red\">ظهیر فاریابی .</font><br />یا ما سر خصم را بکوبیم به سنگ <br />یا او تن ما بدار سازد آونگ <br />القصه در این سراچه ٔ پرنیرنگ <br />یک مرده به نام به که صد زنده به ننگ .<br /> <font color=\"Red\">شاه نظر.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آونگ شدن </span> ؛ آویخته گشتن <span class=\"hlight\">:</span> <br />جانی چو بدار هجرت آونگ شود<br />صحرای جهان بر دل من تنگ شود.<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آونگ کردن </span> ؛ آونگ بستن . آویختن <span class=\"hlight\">:</span> <br />وظیفه ٔ تو رسید و نیافت راه ز در<br />زهی کرم که ز روزن بکردیَش آونگ .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">خانه ٔ خرس و انگور آونگ </span> !<br /><BR><font color=\"Blue\">◄</font> (اِ) جسمی وزین که تحت اثرقوه ٔ ثقل واقع و پیرامون نقطه ای ثابت جنبان باشد، وآن بر دو گونه است بسیط و یا ساده و آمیغی یا مرکب .و از اقسام مرکب شاهین ترازو و رقاصک ساعت است .<br /></font></div>'),
(2756, 'آونگان', '<span class=\"hlight\">آونگان .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ص مرکب ) در تداول عوام، آونگ . دروا. معلق . آویخته . و فصیح آن آویزان باشد. بیت ذیل را در فرهنگها برای کلمه مثال می آورند <span class=\"hlight\">:</span> <br />رفته با بازوش از تندی ّ مرکب آستین <br />گشته آونگانش از پهلوی استر پوستین .<br /><font color=\"Red\">جلال الدین خوافی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آونگان شدن </span> ؛ آویزان شدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آونگان کردن </span> ؛ آویختن .<br /></font></div>'),
(2757, 'آوه', '<span class=\"hlight\">آوه .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) آوه ٔ سمکنان . نام یکی از سران سپاه کیخسرو <span class=\"hlight\">:</span> <br />پس ِگیو بد آوه ٔ سمکنان <br />برفتند خیلش یکان و دوگان .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2758, 'آوه', '<span class=\"hlight\">آوه .</span> <font color=\"DarkGreen\"><b>[ وَه ْ ]</font></b> (صوت ) آه . آخ . آوخ . آواه . دریغا. دریغ. افسوس . واحسرتا. کلمه ای است که از درد یا اسف و اندوه گوینده حکایت کند <span class=\"hlight\">:</span> <br />باز چون شب می شود آن گاو زفت <br />میشود لاغر که آوه رزق رفت .<br /> <font color=\"Red\">مولوی .</font><br />همچو مجنونی که بشنید از یکی <br />که مرض آمد بلیلی اندکی <br />گفت آوه بی بهانه چون روم <br />ور بمانم از عیادت، چون شوم ؟<br /> <font color=\"Red\">مولوی .</font><br />انبیا گفتند آوه بند جان <br />سخت تر کرد ای سفیهان بندتان .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آوه کردن </span> ؛ تأویه .<br /><BR><font color=\"Blue\">◄</font> و برای نمودن تعجب نیز مستعمل است .<br /></font></div>'),
(2759, 'آوه', '<span class=\"hlight\">آوه .</span> <font color=\"DarkGreen\"><b>[ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (اِ) کوره که در آن خشت و آهک و امثال آن پزند. پزاوه . داش . <BR><font color=\"Blue\">◄</font> در بعض فرهنگها معنی صدا و ندا یا برآورنده ٔ صدا و ندا بکلمه داده اند. <BR><font color=\"Blue\">◄</font> زنجیره ای که نقاشان و دوزندگان بر کنار چیزها کشند یا دوزند.<br /></font></div>'),
(2760, 'آوه', '<span class=\"hlight\">آوه .</span> <font color=\"DarkGreen\"><b>[وَ ]</font></b> (اِخ ) نام محلی در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزار گز فاصله از ساوه که آبه و آوج نیز گویند و آن در قدیم شهری بوده و آثار قدیمه ٔ بسیار پیرامون آن دیده میشود. و صاحب حدودالعالم گوید: آوه شهرکیست از جبال، انبوه و آبادان و هوای درست و راه حجاج خراسان . و در نزهةالقلوب آمده است : آوه از اقلیم چهارم است، طولش از جزایر خالدات قه نه و عرض از خط استوا لدم طالع بناش سنبله دور باروش قرب ده هزار گام . هواش معتدل آبش از رودخانه ٔ گاوماها که بماهین بره می خوانند و در آن شهر زمستان یخ آب در چاه می بندند بچند کرت تا فرومیخورد در تابستان همچنان یخ آب بازمیدهد آنقدر آب یخ که در زمستان خورده بود بازدهد بعد از آن آب ساده مثل دیگر چاه ها. و غله و پنبه در آنجا بسیار نیکو بود، از میوه هایش انجیر نیکو بود مردم آنجا سفیدچهره و شیعه ٔ اثناعشریند ... و با هم اتفاق نیکو دارند و حقوق دیوانی آنجا به تمغا مقرر است و ده هزار دینار است . (نزهةالقلوب ).<br /></font></div>'),
(2761, 'آوو', '<span class=\"hlight\">آوو.</span> <font color=\"DarkGreen\"><b>[ وَوْ ]</font></b> (اِخ ) نام شهری .<br /></font></div>'),
(2762, 'آوکان', '<span class=\"hlight\">آوکان .</span> (اِخ ) نام سرداری از سپاه فریدون <span class=\"hlight\">:</span> <br />سپهدارشان قارن کاوگان <br />به پیش سپه اندرون آوکان .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2763, 'آوی', '<span class=\"hlight\">آوی .</span> (ع ص ) مأوی ̍گیر.<br /></font></div>'),
(2764, 'آوی', '<span class=\"hlight\">آوی .</span> (اِخ ) نام یکی از پادشاهان مدیان که بنی اسرائیل او را بکشتند.<br /></font></div>'),
(2765, 'آوی سبرون', '<span class=\"hlight\">آوی سبرون .</span> <font color=\"DarkGreen\"><b>[ س ِ رُن ْ ]</font></b> (اِخ ) محرّف ابن جبرول، نزد اروپائیان .<br /></font></div>'),
(2766, 'آویج', '<span class=\"hlight\">آویج .</span> (نف مرخم ) آویز. (برهان ): مردآویج .<br /></font></div>'),
(2767, 'آویختن', '<span class=\"hlight\">آویختن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص )آویزان کردن از. آویزان شدن به . تعلیق . متعلق شدن . آونگ کردن . آونگ شدن . استرسال . دروا شدن . دروا کردن .اندروا شدن . اندروا کردن . دلنگان کردن <span class=\"hlight\">:</span> <br />که طغرل بشاخی درآویخته ست <br />کنون بازدارش بگیرد بدست .<br /> <font color=\"Red\">فردوسی .</font><br />که خون چنان خسروی ریختی <br />همی کوه در گردن آویختی .<br /> <font color=\"Red\">فردوسی .</font><br />سیاوش نشست از بر تخت عاج <br />بیاویخت او از بر عاج تاج .<br /> <font color=\"Red\">فردوسی .</font><br />ز زین اندر آویخت اسفندیار<br />بدان تا گمانی برد گرکسار.<br /> <font color=\"Red\">فردوسی .</font><br />نهادند زیر اندرش تخت عاج <br />بیاویختند از بر عاج تاج .<br /> <font color=\"Red\">فردوسی .</font><br />بیاویخت بر نیزه ران بره <br />ببست اندر اندیشه دل یکسره .<br /> <font color=\"Red\">فردوسی .</font><br />چو رفتی جهاندار بر تخت عاج <br />بیاویختندی بزنجیر تاج .<br /> <font color=\"Red\">فردوسی .</font><br />دو زلفکانْت بگیرم دل پر از غم خویش <br />چو مرغ بسمل کرده از او درآویزم .<br /> <font color=\"Red\">خفاف .</font><br />آبی مگر چو من ز غم عشق زرد گشت <br />وز شاخ همچو چوک بیاویخت خویشتن .<br /> <font color=\"Red\">بهرامی .</font><br />آری مرا بدان کِت برخیزم <br />وز زلف عنبرینْت بیاویزم .<br /> <font color=\"Red\">سروری (از فرهنگ اسدی ).</font><br />آن جخش ز گردنْش بیاویخته گوئی <br />خیکیست پر ازباد بیاویخته از بار.<br /> <font color=\"Red\">لبیبی .</font><br />چوک ز شاخ درخت خویشتن آویخته <br />بانگ کنان تا سحر آب دهان ریخته .<br /> <font color=\"Red\">منوچهری (از تحفه ٔ اوبهی ).</font><br />یک پایک او را ز بن اندر بشکسته <br />وآویخته او را بدگرپای نگونسار.<br /> <font color=\"Red\">منوچهری .</font><br />نهال او را <font color=\"DarkGreen\"><b>[رَز را ]</font></b> دید درخت شده و آن خوشه ها از او درآویخته .(نوروزنامه ). چون مدتی برآمد شاخهاش <font color=\"DarkGreen\"><b>[ رَز ]</font></b> بسیار شد و بلگها پهن گشت و خوشه خوشه به مثال گاورس از او درآویخت . (نوروزنامه ). همچون آن مرد باشد که از پیش شتر مست بگریخت و بضرورت خویشتن در چاهی آویخت . (کلیله و دمنه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">هر بزی را بپای خود آویزند</span> ؛ کل ﱡ شاة بِرِجلها معلَّقة.<br /> <BR><font color=\"Blue\">◄</font> فروهشتن . فروگذاشتن . افکندن . پائین انداختن . سدل .اسدال . تسدیل . ارسال . ارخاء <span class=\"hlight\">:</span> خانه برآوردند خواب قیلوله را... و خیشها آویختند. (تاریخ بیهقی ).<br />یکی چادری جوی پهن و دراز<br />بیاویز چادرز بالای گاز.<br /> <font color=\"Red\">ازرقی (از تحفه ٔ اوبهی ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آویختن دلو بچاه، آویختن رسن از بام </span> ؛ فروهشتن دلو و رسن .<br /> <BR><font color=\"Blue\">◄</font> حمایل کردن . تقلد. توشح . اتشاح <span class=\"hlight\">:</span> <br />بروزکارزار خصم و روز نام و ننگ تو<br />فلک در گردن آویزد شغا و نیم لنگ تو.<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> بدار کشیدن . صلب . مصلوب کردن . بر دار کردن . بدار زدن <span class=\"hlight\">:</span> <br />فکندند ناگاه بر گردنش <br />بیاویختند آن گرامی تنش .<br /> <font color=\"Red\">فردوسی .</font><br />برآشفت و سودابه را پیش خواند<br />گذشته سخنها بدو بازراند<br />که بی شرمی و بد بسی کرده ای <br />فراوان دل من بیازرده ای <br />نشاید که باشی تو اندر زمین <br />جز آویختن نیست پاداش این .<br /> <font color=\"Red\">فردوسی .</font><br />بدژخیم فرموده کاین را بکوی <br />بدار اندر آویز و برتاب روی .<br /> <font color=\"Red\">فردوسی .</font><br />برآویختشان در شبستان شاه <br />بدان تا دگر کس نجوید گناه .<br /> <font color=\"Red\">فردوسی .</font><br />و مهتر ایشان را، عطاش، بکشتند و بیاویختند. (مجمل التواریخ ). و در آن گوری هست که ترسایان آن را قبرالمسیح خوانند، گور آن مرد است که مسیح بر او پیدا آمد و بیاویختندش . (مجمل التواریخ ). ان یقتلوا او یصلّبوا ؛ بکشند یا بیاویزند. (راحةالصدور راوندی ). خواجه قوام را بر در لیشتر بیاویخت . (راحةالصدور راوندی ). جزای ایشان ... آن است کشان بکشند یا بیاویزند یا دست و پاهاشان مخالف ببرند. (راحةالصدور راوندی ).<br />نازکی ّ و لطف دزدید از بناگوش تو دُر<br />غوطه ای در آب دادند آنگهش آویختند.<br /> <font color=\"Red\">کمال خجندی .</font><br /> <BR><font color=\"Blue\">◄</font> جنگ . حرب . رزم . پیکار<span class=\"hlight\">:</span> <br />فراز آمد آن روز آویختن <br />همان خون ز بهر پدر ریختن .<br /> <font color=\"Red\">فردوسی .</font><br />بپرهیز از این رزم و آویختن <br />به بیدادبرخیره خون ریختن .<br /> <font color=\"Red\">فردوسی .</font><br />گرش رای کین است و خون ریختن <br />نداریم نیروی آویختن .<br /> <font color=\"Red\">فردوسی .</font><br />نگر تا نبینید بگریختن <br />نگر تا نترسید از آویختن .<br /> <font color=\"Red\">فردوسی .</font><br />کنون غارت از تست و خون ریختن <br />بهر جای تاراج و آویختن .<br /> <font color=\"Red\">فردوسی .</font><br />ببیند کنون راه خون ریختن <br />بیاساید از رنج آویختن .<br /> <font color=\"Red\">فردوسی .</font><br />شما را حلال است خون ریختن <br />بهر جای تاراج و آویختن .<br /> <font color=\"Red\">فردوسی .</font><br />هنرْتان همی روز آویختن <br />نبینم جز از زود بگریختن .<br /> <font color=\"Red\">اسدی .</font><br />بدین وقتها رای آویختن <br />فزون کن که خواهند بگریختن .<br /> <font color=\"Red\">اسدی .</font><br />چون مخیّر شد میان جستن و آویختن <br />کرد آب زاده را بر آتش تیغ اختیار.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> جنگ کردن . رزم دادن . نبرد کردن . بجنگ درآمدن <span class=\"hlight\">:</span> <br />وز آن پس بروی سپه بنگرید<br />سپه را همه گونه پژمرده دید<br />ز رنج نبرد و ز خون ریختن <br />بهر جای با دشمن آویختن .<br /> <font color=\"Red\">فردوسی .</font><br />بسی رنج بردی ّ و آویختی <br />سرانجام از آن بنده بگریختی .<br /> <font color=\"Red\">فردوسی .</font><br />چو زور تن اژدها دید رخش <br />کز آنسان برآویخت با تاج بخش .<br /> <font color=\"Red\">فردوسی .</font><br />و لشکر میمنه بازگشت و بگتکین چوکانی و ... با سواری پانصد می آویختند. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> بجنگ درآمدن . بجنگ پرداختن . بجنگ آغازیدن <span class=\"hlight\">:</span> <br />سپاه از دو سو اندرآویختند<br />یکی گرد تیره برانگیختند.<br /> <font color=\"Red\">فردوسی .</font><br />دو جنگی بدانسان برآویختند<br />که گفتی بهمْشان درآمیختند.<br /> <font color=\"Red\">فردوسی .</font><br />دو لشکر بجنگ اندر آویختند<br />همه یک بدیگر درآمیختند.<br /> <font color=\"Red\">فردوسی .</font><br />نبینی که عیسی ّ مریم چه گفت <br />بدانگه که بگشاد راز نهفت <br />که پیراهنت گر ستاند کسی <br />میاویز با او به تندی بسی .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آویختن با، بر</span> ؛ گلاویز، دست و گریبان، دست و یقه، هُشت و مُشت شدن . تناسب <span class=\"hlight\">:</span> <br />بباره برآمد چو مرغی بپر<br />درآویخت با من گو نامور.<br /> <font color=\"Red\">فردوسی .</font><br />برآویخت با شاه مازندران <br />همی لشکرش خیره گشت اندر آن .<br /> <font color=\"Red\">فردوسی .</font><br />بریده برآویخت با او بهم <br />چو پیل سرافراز و شیر دژم .<br /> <font color=\"Red\">فردوسی .</font><br />پیاده بهم اندر آویختند<br />یکی گرد تیره برانگیختند.<br /> <font color=\"Red\">فردوسی .</font><br />چون خطیب بجای ذکر خلیفه رسید به وی اندر آویختند و خطبه بریده شد. (مجمل التواریخ ). <BR><font color=\"Blue\">◄</font> چنگ زدن <span class=\"hlight\">:</span> حالی که من این سخن بگفتم دامن گل بریخت و در دامنم آویخت که الکریم اذا وعد وفی . (گلستان ). <BR><font color=\"Blue\">◄</font> چنگ زدن بر، چنانکه گرگ و پلنگ و مانند آن در صیدی <span class=\"hlight\">:</span> <br />چو با زور و با چنگ برخیزد اوی <br />بپروردگار اندر آویزد اوی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> درزدن . تشبت . زَدَن <span class=\"hlight\">:</span> <br />چو روشن شد آن چادر مشک رنگ <br />سپیده بدو اندر آویخت چنگ .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آویختن دل کسی بکسی </span> ؛ بدو تعلق خاطر پیدا کردن <span class=\"hlight\">:</span> <br />چو دانست سودابه کو گشت خوار<br />بیاویخت در وی دل شهریار...<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span>:<br /><span class=\"hlight\">تا از گوشوار من چه آویزی </span> ؛ تا در مقابل این خدمت بمن چه عطا کنی <span class=\"hlight\">:</span> <br />دگر گفت کاری که فرمود شاه <br />برآمد بکام دل نیک خواه ...<br />وز این پس کنون تا چه فرمان دهی <br />چه آویزی از گوشوار رهی .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مأخوذ، مسئول شدن . معاقَب، مؤاخَذ، مَجْزی ّ شدن <span class=\"hlight\">:</span> <br />هر آنکس که از داد بگریزد اوی <br />ببادافره ما بیاویزد اوی .<br /> <font color=\"Red\">فردوسی .</font><br />هر آن خون کز این کینه شد ریخته <br />بدین گیتی او باشد آویخته .<br /> <font color=\"Red\">فردوسی .</font><br />که هر خون که آید بکین ریخته <br />تو باشی بدان گیتی آویخته .<br /> <font color=\"Red\">فردوسی .</font><br />بر این رزم خونی که شد ریخته <br />تو باشی بدان گیتی آویخته .<br /><font color=\"Red\">فردوسی .</font><br />چون نترسم که چو جائی بروم دیگر<br />به بد خویش بیاویزم و درمانم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آویزد آن کسی که گریزد ز مهر تو<br />گرچه رسن دراز سرش هم بچنبر است .<br /> <font color=\"Red\">معزی .</font><br />عقل را هرکه با بدی آمیخت <br />لاجرم عقل جست و او آویخت .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> گرفتار شدن . دچارگشتن <span class=\"hlight\">:</span> <br />بیاویزد آنکس به غدر خدای <br />که بگریزد از عهد روز غدیر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />هرکس که ز ما قصد جهان دارد از اوباش <br />بس زود بیاویزد در ننگ و نکالش .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> افتادن <span class=\"hlight\">:</span> <br />چو شد کار بی برگ بگریختم <br />بدام بلا برنیاویختم .<br /> <font color=\"Red\">فردوسی .</font><br />که ایدر برینسان بماندیم دیر<br />برآویخت بر دام روباه شیر.<br /> <font color=\"Red\">فردوسی .</font><br />بدام من آویزد از ناگهان <br />بخونها که او ریخت اندر جهان .<br /> <font color=\"Red\">فردوسی .</font><br />از آن لشکر روم بگریخت اوی <br />بدام بلا درنیاویخت اوی .<br /> <font color=\"Red\">فردوسی .</font><br />دو مهتر بد از جنگ بگریختند<br />بدام بلا درنیاویختند.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نصب کردن . کار گذاشتن . جا گذاشتن <span class=\"hlight\">:</span> و ده در بر آن آویخته چهار زرین و شش از سیم خام . (مجمل التواریخ ). و دری از آهن بدو پاره بر وی آویخته . (مجمل التواریخ ). و پیرامونش دیوار است چهار در بر آن آویخته . (مجمل التواریخ ). و آن درها از واسط بیاورد و بر آنجادرآویخت . (مجمل التواریخ ). و دری آهنین بدو پاره بر وی درآویخته . (مجمل التواریخ ). و آن در را بر باب البصره آویخت و یکی در دیگر از مصر بیاوردند و بر باب الکوفه آویخت . (مجمل التواریخ ).<br /> <BR><font color=\"Blue\">◄</font> درافتادن با. ایذاء <span class=\"hlight\">:</span> <br />نه والا بود خیره خون ریختن <br />نه از شاه با بنده آویختن .<br /> <font color=\"Red\">فردوسی .</font><br />تو دانی که تاراج و خون ریختن <br />چو با بی گنه مردم آویختن <br />مهان سرافراز دارند شوم <br />چه با شهر ایران چه با شهر روم .<br /> <font color=\"Red\">فردوسی .</font><br />مرا نیست آئین خون ریختن <br />نه بر خیره بامهتر آویختن .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> شبک . تشبیک . در هم افکندن . نسج . انشباب <span class=\"hlight\">:</span> <br />چنان نیزه در نیزه آویختند<br />تو گفتی بهمْشان درآمیختند.<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به آویخته شود. <BR><font color=\"Blue\">◄</font> بستن <span class=\"hlight\">:</span> <br />بپیچید اولاد را بر درخت <br />بخم ّ کمندش بیاویخت سخت .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> دوسیدن . چسبیدن . انتشاب . نشوب . تنشب . تعلیق <span class=\"hlight\">:</span> <br />بدلهااندر آویزد دو زلفش <br />چو دوژه اندرآویزد به دامن .<br /> <font color=\"Red\">خفاف .</font><br />چه آویزی در این چون می ندانی <br />که دینه ست این مدینه یا کهینه .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> سرگرم شدن . مشغول گشتن .وررفتن <span class=\"hlight\">:</span> چون سگ که در استخوان آویزد. (تاریخ طبرستان ). <BR><font color=\"Blue\">◄</font> بحث بسزا کردن . تعمق . تحقیق . استقصا. فحص کردن <span class=\"hlight\">:</span> و من میخواستم که این تاریخ بکنم هر کجا نکته ای بودی در آن آویختمی . (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> آرامیدن . آرامیدن با. وقاع . بضاع <span class=\"hlight\">:</span> <br />بیک ماه یک بار از آویختن <br />فزون گر کنی خون بود ریختن <br />هم این مایه از بهر فرزند را<br />بباید جوان خردمند را.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> برآویختن هور با ماه، در بیت ذیل فردوسی ظاهراً به معنی خسوف یا کسوف است <span class=\"hlight\">:</span> <br />تو گفتی برآویخت با هور ماه <br />ز باریدن تیر و گرد سپاه .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> پیچیدن . (برهان ). <BR><font color=\"Blue\">◄</font> درگرفتن . (برهان ). <BR><font color=\"Blue\">◄</font> توسل کردن . متوسل شدن <span class=\"hlight\">:</span> <br />همه آویخته از دامن دعوی ّ و دروغ <br />چون کُفه از کُس گاو و، چو کلیدان ز مدنگ .<br /> <font color=\"Red\">قریعالدهر.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">لب و لنج آویختن </span> ؛ سُرش را آویختن . با ملامح روی خود ناخرسندی خویش نمودن . ومصدر دوم آن آویز یا آویزش باشد: آویختم . بیاویز. اعتلاج ؛ با یکدیگر بیاویختن در جستن و گرفتن و آنچه بدان ماند. (تاج المصادر بیهقی ). زوشیدن ؛ درآویختن . بشلیدن . بردوسیدن . در مردم آویختن . (فرهنگ اسدی ). اعتلاق ؛ در چیزی درآویختن .<br /></font></div>'),
(2768, 'آویختنی', '<span class=\"hlight\">آویختنی .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص لیاقت ) درخور آویختن . ازدرِ آویختن . که آویختن آن ناگزیر و واجب باشد.<br /></font></div>'),
(2769, 'آویخته', '<span class=\"hlight\">آویخته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آویزان شده . آونگ شده . دروا. اندروا. معلق . فروهشته . فروگذاشته . نگون <span class=\"hlight\">:</span> <br />آب گلفهشنگ گشته از فسردن ای شگفت <br />همچنان چون شیشه ٔ سیمین نگون آویخته .<br /> <font color=\"Red\">فرالاوی .</font><br />یکی حلقه زرین بدی ریخته <br />از آن چرخ کار اندرآویخته <font color=\"DarkGreen\"><b>[ در ایوان مداین ]</font></b><br />فروهشته زو سرخ زنجیر زر<br />بهر مهره ای درنشانده گهر.<br /> <font color=\"Red\">فردوسی .</font><br />کآن هر دو فریشته بفعل خود<br />آویخته مانده اند در بابل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از آن جانب که بریده بود انثیین او در شکاف چوب آویخته شد. (کلیله و دمنه ).<br /> <BR><font color=\"Blue\">◄</font> متشبث <span class=\"hlight\">:</span> <br />همه آویخته از دامن دعوی ّ و دروغ <br />چو کُفه از کُس گاو و چو کلیدان ز مدنگ .<br /> <font color=\"Red\">قریعالدهر.</font><br /> <BR><font color=\"Blue\">◄</font> بدارزده . بردارکرده . مصلوب . مصلوبه <span class=\"hlight\">:</span> محمود... بسیار دارها بفرمود زدن و بزرگان دیلم را بر درخت کشیدند... ومقدار پنجاه خروار دفتر روافض و باطنیان و فلاسفه ازسراهای ایشان بیرون آوردند و زیر درختهای آویختگان بفرمود سوختن . (مجمل التواریخ ). <BR><font color=\"Blue\">◄</font> منشب ّ. منشبک . مشبک . منتسج <span class=\"hlight\">:</span> <br />نیست آمیخته با آب هنر خاکش <br />نیست آویخته در پود خرد تارش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و رجوع به آویختن شود. <BR><font color=\"Blue\">◄</font> مأخوذ. مسؤول . معاقَب . مَجْزی ّ <span class=\"hlight\">:</span> <br />بر این رزم خونی که شد ریخته <br />تو باشی بدان گیتی آویخته .<br /> <font color=\"Red\">فردوسی .</font><br />هر آن خون که آید بکین ریخته <br />تو باشی بدان گیتی آویخته .<br /> <font color=\"Red\">فردوسی .</font><br />هر آن خون که آید بر این ریخته <br />گنهکار اویست و آویخته .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نگون . دروا. معلق . اندروا <span class=\"hlight\">:</span> <br />بزین اندر آورد و بستش چو سنگ <br />سر آویخته پایها زیر تنگ .<br /> <font color=\"Red\">فردوسی .</font><br />نبیند مگر تخته ٔ گور تخت <br />گر آویخته سر ز شاخ درخت .<br /> <font color=\"Red\">فردوسی .</font><br />بماند او <font color=\"DarkGreen\"><b>[ ضحاک بدماوند ]</font></b> بدانگونه آویخته <br />وزو خون دل بر زمین ریخته .<br /> <font color=\"Red\">فردوسی .</font><br />بیفشرد چنگ کلاهور سخت <br />فروریخت ناخن چو برگ درخت <br />کلاهور با دست آویخته <br />پی و پوست و ناخن فروریخته .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2770, 'آویخته دوش', '<span class=\"hlight\">آویخته دوش .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) اَحدَل .<br /></font></div>'),
(2771, 'آویخته لب', '<span class=\"hlight\">آویخته لب .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ل َ ]</font></b> (ص مرکب ) اَهْدَل . هَدْلاء.<br /></font></div>'),
(2772, 'آویخته ناف', '<span class=\"hlight\">آویخته ناف .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) اَبْجَر. بَجْراء.<br /></font></div>'),
(2773, 'آویخته چشم', '<span class=\"hlight\">آویخته چشم .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (ص مرکب ) آنکه خلقةً چشمی مسترخی دارد. مُطْرِق .<br /></font></div>'),
(2774, 'آویخته گوش', '<span class=\"hlight\">آویخته گوش .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ص مرکب ) اَحدَل . اَخطل . گاوگوش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سگی آویخته گوش </span> ؛ شلل گوش .<br /></font></div>'),
(2775, 'آویختگی', '<span class=\"hlight\">آویختگی .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص ) کیفیت و صفت و حالت آویخته .<br /></font></div>'),
(2776, 'آویز', '<span class=\"hlight\">آویز.</span> (نف مرخم )در کلمات مرکّبه چون دست آویز، به معنی وسیله و بهانه، و دل آویز، و گلاویز مخفف آویزنده است <span class=\"hlight\">:</span> <br />بدو گفتم که مشکی یا عبیری <br />که از بوی دلاویز تو مستم .<br /><font color=\"Red\">سعدی .</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2777, 'آویز', '<span class=\"hlight\">آویز.</span> (اِ) نام قسمی گل با ساقی باریک بطول نیم گز و کمتر و برگی سخت سبز وشبیه ببرگ نعناع و گلی چون گل انار. <BR><font color=\"Blue\">◄</font> منشور و جز آن از بلور و مانند آن که بر جارها و لاله ها و چلچراغها آویخته است زینت را. <BR><font color=\"Blue\">◄</font> آنچه از احجار کریمه چون الماس و زمرد و مانند آن که بر حلقه ٔ گوشواره آویزند. <BR><font color=\"Blue\">◄</font> جنگ . پیکار. مبارزت . نبرد. درآویختن با خصم . زد و خورد <span class=\"hlight\">:</span> <br />بیفشرد ران رخش را تیز کرد<br />برآشفت و آهنگ آویز کرد.<br /><font color=\"Red\">فردوسی .</font><br />برانگیخت از جای شبدیز را<br />تن و جان بیاراست آویز را.<br /> <font color=\"Red\">فردوسی .</font><br />چهل روز با لشکر آویز بود<br />گهی رزم و گه روی پرهیز بود.<br /> <font color=\"Red\">فردوسی .</font><br />غمین گشت و آهنگ آویزکرد<br />از آن پس که از جنگ پرهیز کرد.<br /> <font color=\"Red\">فردوسی .</font><br />با شیر و پلنگ هرکه آویز کند<br />آن بِه ْ که ز تیر فقر پرهیز کند.<br /> <font color=\"Red\">؟ (از تاریخ بیهقی ).</font><br />دگر ره شد آهنگ آویز کرد<br />برآورد گرد اسب را تیز کرد.<br /> <font color=\"Red\">اسدی .</font><br />چرخ رابا حاسدت آویز باد<br />بخت را با دشمنت پیکار باد.<br /> <font color=\"Red\">مسعودسعد.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گریز و آویز</span> ؛ آویز و گریز. جنگ و گریز <span class=\"hlight\">:</span> اشکانیان در گریز و آویز بس استاد بودند. و رجوع به «آویز و گریز» شود.<br /><BR><font color=\"Blue\">◄</font> منگوله . شرّابه . پَش . فَش .<br /></font></div>'),
(2778, 'آویز و گریز', '<span class=\"hlight\">آویز و گریز.</span> <font color=\"DarkGreen\"><b>[ زُ گ ُ ]</font></b> (ترکیب عطفی، اِمص مرکب ) گریز و آویز. عمل جنگ کردن در حال عقب نشستن . جنگ و گریز. کَرّ و فَرّ <span class=\"hlight\">:</span> <br />زین عاریتی سرای آویز و گریز<br />زآن پیش که برکَنندت ای دل برخیز.<br /><font color=\"Red\">رضی نیشابوری .</font><br /></font></div>'),
(2779, 'آویزان', '<span class=\"hlight\">آویزان .</span> (نف، ق ) در حال آویختگی . <BR><font color=\"Blue\">◄</font> آویخته . معلق . آونگ . آون . دروا. آونگان . دلنگان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آویزان کردن </span> ؛ آویختن . تعلیق .<br /> <BR><font color=\"Blue\">◄</font> جنگ و گریز کنان . گریز و آویز کنان <span class=\"hlight\">:</span> غوریان دررمیدند و هزیمت شدند وآویزان میرفتند تا ده . (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> مشغول . دست بکار. آغازان . <BR><font color=\"Blue\">◄</font> دست بیقه <span class=\"hlight\">:</span> <br />باد سحری سپیده دم خیزانست <br />با میغ سیه بجنگ آویزانست .<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(2780, 'آویزش', '<span class=\"hlight\">آویزش .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِمص ) جنگ <span class=\"hlight\">:</span> <br />بدانست کو را ز شاه بلند<br />ز رزم و ز آویزش آید گزند.<br /> <font color=\"Red\">فردوسی .</font><br />سخن گفتن اکنون نیاید بکار<br />گه جنگ و آویزش و کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />بر این گونه تا خورز گنبد بگشت <br />وز اندازه آویزش اندرگذشت .<br /> <font color=\"Red\">فردوسی .</font><br />بدان گیتی ارچندشان برگ نیست <br />همان به که آویزش و مرگ نیست .<br /> <font color=\"Red\">فردوسی .</font><br />دو پایش فروشد بیک چاه سار<br />نبد جای آویزش و کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />چو خورشید بر چرخ گردان بگشت <br />از اندازه آویزش اندرگذشت .<br /> <font color=\"Red\">فردوسی .</font><br />هر دو لشکر بجنگ مشغول شدند و آویزشی بود که خوارزمشاه گفت در مدت عمر چنین یاد ندارد. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> علقه . علاقه . تعلق . پیوستگی . بستگی <span class=\"hlight\">:</span> <br />قدم را با حدوث آویزشی نیست <br />و گر آویزش است آمیزشی نیست .<br /> <font color=\"Red\">عطار.</font><br /> <BR><font color=\"Blue\">◄</font> در بیت ذیل محتمل است کلمه آویختن، بر دار کردن، یا مؤاخذه و بازپرس کردن یا سزا دادن باشد <span class=\"hlight\">:</span> <br />ز کارآگهان موبدی نیک خواه <br />چنان بد که برداشت روزی بشاه <font color=\"DarkGreen\"><b>[ انوشیروان ]</font></b><br />که گاهی گنه بگذرانی همی <br />به بد، نام آنکس نخوانی همی <br />هم آن را دگرباره آویزش است <br />گنهکاراگرچند با پوزش است ...<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2781, 'آویزنده', '<span class=\"hlight\">آویزنده .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) عَلِق . شَبِث . آویزگن .<br /></font></div>'),
(2782, 'آویزه', '<span class=\"hlight\">آویزه .</span> <font color=\"DarkGreen\"><b>[زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ) گوشوار. گوشواره . قرطه <span class=\"hlight\">:</span> <br />ای از تو مرا گوش پر و دیده تهی <br />خوش آنکه ز گوش پای در دیده نهی <br />تو مردم دیده ای نه آویزه ٔ گوش <br />از گوش بدیده آ که در دیده بهی .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />نخشبیهای وی از گوهر پاک <br />کرد یاقوت تر آویزه ٔ تاک .<br /> <font color=\"Red\">جامی .</font><br />دُرِ نظم من در سراسرْ جهان <br />شد آویزه ٔ گوش شاهنشهان .<br /> <font color=\"Red\">هاتفی .</font><br />و بیشتر این کلمه به معنی الماس و دیگر گوهرهای ثمین است که بحلقه ٔ گوشواره آویزند یا در نگین دان آن نشانند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آویزه ٔ گوش کردن گفته ای را</span> ؛ آن را فراموش نکردن . از آن پند و عبرت گرفتن . هماره بدان کار کردن .<br /></font></div>'),
(2783, 'آویزه', '<span class=\"hlight\">آویزه .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ)آپاندیس . (فرهنگستان ).<br /></font></div>'),
(2784, 'آویزه بند', '<span class=\"hlight\">آویزه بند.</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ب َ ]</font></b> (نف مرکب ) آویزه بندنده . آویزه بسته <span class=\"hlight\">:</span> <br />چو گوش خدیو از لاَّلی ّ پند<br />شد از روی اخلاص آویزه بند.<br /> <font color=\"Red\">هاتفی .</font><br /><BR><font color=\"Blue\">◄</font> (اِ مرکب ) بندی که رویان (جنین ) دانه را بجفت متصل کند. (فرهنگستان ).<br /></font></div>'),
(2785, 'آویزگن', '<span class=\"hlight\">آویزگن .</span> <font color=\"DarkGreen\"><b>[ گ ِ ]</font></b> (ص مرکب ) آنکه بهر کس درآویزد. آنکه بهر چیز درآویزد. آنکه بهر چیز تشبث کند. شَبِث . (ربنجنی ) (السامی فی الاسامی ). عَلِق . (السامی فی الاسامی ). متشبث . <BR><font color=\"Blue\">◄</font> مبرم (چون گدا).<br /></font></div>'),
(2786, 'آویسن', '<span class=\"hlight\">آویسن .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) محرَّف ابن سینا نزد مردم اروپا.<br /></font></div>'),
(2787, 'آویشن', '<span class=\"hlight\">آویشن .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِ) صعتر. سعتر. آویشه . آویش . اوشه . اوشن . یوشن . پودنه ٔ برّی . پودینه ٔ صحرائی . پودنه ٔ کوهی . زلف شاهدان <span class=\"hlight\">:</span> <br />چه کنی دنیا بی دین و خرد زیراک <br />خوش نباشد بی نان ترّه و آویشن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />اکنون نچرد گوزن در صحرا<br />جز سنبل و کرویا و آویشن .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(2788, 'آویشنه', '<span class=\"hlight\">آویشنه .</span> <font color=\"DarkGreen\"><b>[ ش َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) آویشن .<br /></font></div>'),
(2789, 'آویشه', '<span class=\"hlight\">آویشه .</span> <font color=\"DarkGreen\"><b>[ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِ) آویشن . سعتر <span class=\"hlight\">:</span> <br />آویشه خوری چو نیم مثقال <br />بیرون برد از تن تو بلغم <br />نیکو بود از برای معده <br />قوت یابد از او جگر هم <br />فارغ کندت ز درد سینه <br />تشویش سپرز را کند کم .<br /><font color=\"Red\">یوسفی طبیب .</font><br /></font></div>'),
(2790, 'آویژه', '<span class=\"hlight\">آویژه .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ ]</font></b> (ص، اِ) ویژه . خاص . خالص . بَحْت . <BR><font color=\"Blue\">◄</font> مجازاً، دلبر. معشوق . <BR><font color=\"Blue\">◄</font> آویزه . پاکیزه . <BR><font color=\"Blue\">◄</font> شراب انگوری .<br /></font></div>'),
(2791, 'آویژگان', '<span class=\"hlight\">آویژگان .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ ]</font></b> (اِ) ج ِ آویژه . ویژگان . خواص . <BR><font color=\"Blue\">◄</font> مجازاً، دلبران . معشوقان .<br /></font></div>'),
(2792, 'آپادانا', '<span class=\"hlight\">آپادانا.</span> (اِخ ) بارگاه پادشاهان ایران . <BR><font color=\"Blue\">◄</font> نام یکی از قصور تخت جمشید.<br /></font></div>'),
(2793, 'آپارتمان', '<span class=\"hlight\">آپارتمان .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (فرانسوی، اِ) خانه ای بچندین آشکوب .<br /></font></div>'),
(2794, 'آپاردی', '<span class=\"hlight\">آپاردی .</span> (ص ) (شاید از ترکی آپارماق بمعنی بردن ) سخت گربز. <BR><font color=\"Blue\">◄</font> سخت بی شرم .<br /></font></div>'),
(2795, 'آپاندیسیت', '<span class=\"hlight\">آپاندیسیت .</span> (فرانسوی، اِ) آماس که در ضمیمه یعنی زائده ٔ دودی پدید آید.<br /></font></div>'),
(2796, 'آپستنگاه', '<span class=\"hlight\">آپستنگاه .</span> <font color=\"DarkGreen\"><b>[ پ َ ت َ ]</font></b> (اِ مرکب ) در فرهنگ اسدی (خطی ) کلمه ای بدین صورت هست بمعنی آبشتنگاه و شعر قریعالدهر را در اینجا نیز شاهد آورده است .<br /></font></div>'),
(2797, 'آپلن', '<span class=\"hlight\">آپلن .</span> <font color=\"DarkGreen\"><b>[ پ ُ ل ُ ]</font></b> (اِخ ) رجوع به افولن و ابلن شود.<br /></font></div>'),
(2798, 'آپوق', '<span class=\"hlight\">آپوق .</span> (اِ) پرباد کردن دهان و زدن دست در آن حال از بیرون سوی بر گونه، تا آوازی از میان دو لب برهم آورده برآید. لپق .<br /></font></div>'),
(2799, 'آپکانه', '<span class=\"hlight\">آپکانه .</span> <font color=\"DarkGreen\"><b>[ ن َ<span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص، اِ) آبکانه . افکانه . آفکانه . (برهان ).<br /></font></div>'),
(2800, 'آپیخ', '<span class=\"hlight\">آپیخ .</span> (اِ) پیخال :<br />همواره بر آپیخ است آن چشم فژا کند<br />گویی که دو بوم آنجا بر خانه گرفته ست .<br /> <font color=\"Red\">عماره ٔ مروزی .</font><br /> <br /></font></div>'),
(2801, 'آپیس', '<span class=\"hlight\">آپیس .</span> (اِخ ) هاپی . گاو مقدس مصریان قدیم و معبود مردم ممفیس .<br /></font></div>'),
(2802, 'آپیون', '<span class=\"hlight\">آپیون .</span> <font color=\"DarkGreen\"><b>[ آپ ْ ]</font></b> (از یونانی، اِ) (از یونانی ِ اُپیُن ) اَپیون . هَپیون . اَفیون . تریاک به استعمال امروز <span class=\"hlight\">:</span> <br />تلخی و شرینیش آمیخته ست <br />کس نخورد نوش و شکر به آپیون .<br /><font color=\"Red\">رودکی .</font><br /></font></div>'),
(2803, 'آچار', '<span class=\"hlight\">آچار.</span> (اِ) پرورده ها و ترشی ها در آب لیمو و سرکه و امثال آن . ترشی . چاشنی <span class=\"hlight\">:</span> این مرد... آچارها و کامه ها نیکو ساختی ... امیر وی را بنواخت و گفت از گوسفندان خاص پدرم وی بسیار داشت ... یله کردم بدو. (تاریخ بیهقی ).<br />آچار خدای است مزه وْ بوی خوش و رنگ <br />با سیب و ترنج آمد و جوز و بهی و نار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />آچار سخن چیست معانی و عبارت <br />نونو سخن آری چو فراز آمدت آچار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />نمی بینی کز آن آچار اگر خاکی تهی ماند<br />ترا ای خاک خور، آن خاک بی آچار نگْوارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چو آچار است لفظ فارس درخورد<br />که بی آچار چیزی کم توان خورد.<br /> <font color=\"Red\">امیرخسرو دهلوی .</font><br /> <BR><font color=\"Blue\">◄</font> مطلق میوه ها و ترشی ها و مربَّیات و ریچار و ریصار و خوشاب که برای تیز کردن اشتها خورند <span class=\"hlight\">:</span> <br />ز آچارها هرچه باشد عزیز<br />ترنج و به و نار و نارنج نیز.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> در فرهنگها این کلمه را به معنی زمین سراشیب و پست و بلند ضبط کرده و این بیت را شاهد آورده اند <span class=\"hlight\">:</span> <br />زمینی نیست در عالم سراسر<br />از این پژمرده تر زین بس عجب تر<br />دو گونه جای باشد صعب و دشوار<br />یکی دریا دگر آچار و کهسار.<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> (ص ) درهم آمیخته و ضم کرده . (برهان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آجیل آچار</span> ؛ آجیل که بدان زعفران و آب لیمو و گلپر زنند.<br /></font></div>'),
(2804, 'آچار', '<span class=\"hlight\">آچار.</span> (ترکی، اِ) (ظ. از آچمق ترکی گشودن ) کلید. دست افزار فلزین که بدان چوب پنبه ٔ شیشه و پیچ و مهره های آهنین را باز کنند.<br /></font></div>'),
(2805, 'آچاردان', '<span class=\"hlight\">آچاردان .</span> (اِ مرکب ) ظرفی که در آن ظروف نمک و فلفل و خردل و سرکه و روغن زیتون و جز آن نهند.<br /></font></div>'),
(2806, 'آچاردن', '<span class=\"hlight\">آچاردن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b>(مص ) آچاریدن . چاشنی و آچار بطعام زدن <span class=\"hlight\">:</span> <br />عذرطرازی که میر توبه ام اشکست <br />نیست دروغ ترا خدای خریدار<br />راست نگردد دروغ و مکر بچاره <br />معصیتت را بدین دروغ میاچار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />دیو است جهان که زهر قاتل را<br />در نوش بمکرمی بیاچارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />فلک مر خاک را ای خاک خور در میوه و دانه <br />زبهر تو بشور و چرب و شیرین می بیاچارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> در بعض فرهنگها به این کلمه معنی درآمیختن و آمیختن مطلق داده و ظاهراً در معنی شواهد فوق و امثال آن بخطا رفته اند .<br /></font></div>'),
(2807, 'آچاک', '<span class=\"hlight\">آچاک .</span> (اِ) خاک . شاهدی برای این کلمه یافته نشد و دور نیست که تصحیفی از آخال بمعنی خاشاک باشد.<br /></font></div>'),
(2808, 'آچمز', '<span class=\"hlight\">آچمز.</span> <font color=\"DarkGreen\"><b>[ م َ]</font></b> (ترکی، ص ) (ظ. از ترکی ِ آچلمز به معنی باز نمی شود) مهره ای که اگر آن را برگیرند شاه شطرنج زده شود.<br /></font></div>'),
(2809, 'آچین', '<span class=\"hlight\">آچین .</span> (اِ) درختی عظیم با برگی کم عرض و طویل و گلی پنج برگ و سفید و خوشبوی، و این درخت در اول گل آرد و سپس برگ کند و پوست بیخ آن مسهلی قوی است .<br /></font></div>'),
(2810, 'آژانس', '<span class=\"hlight\">آژانس .</span> (فرانسوی، اِ) نماینده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آژانس اخبار</span> ؛ خبرگزاری .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آژانس معاملات </span> ؛ کارگزاری . (فرهنگستان ).<br /></font></div>'),
(2811, 'آژخ', '<span class=\"hlight\">آژخ .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) رجوع به آزخ شود.<br /></font></div>'),
(2812, 'آژدف', '<span class=\"hlight\">آژدف .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ) آزْدَف . اَزْدَف . زعرور. آلج . آلوج . (زمخشری ). رجوع به ازدف شود.<br /></font></div>'),
(2813, 'آژدن', '<span class=\"hlight\">آژدن .</span> <font color=\"DarkGreen\"><b>[ ژْ <span class=\"hlight\" dir=\"rtl\">/</span> ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ دَ ]</font></b> (مص ) آجدن . آجیدن . آجیده کردن . نکنده کردن . آزدن . آزیدن . آژیدن . برجستگی هائی بر روی جامه یا کف برون سوی گیوه و امثال آن با نخ از پنبه یا پشم یا با رشته ٔ سیم و زر دوختن زینت یا محکمی را <span class=\"hlight\">:</span> <br />کشیده پرستنده هر سو رده <br />همه جامه هاشان بزر آژده .<br /> <font color=\"Red\">فردوسی .</font><br />نشاید بود گه ماهی و گه مار<br />گلیم خر بزررشته میاژن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />خوب سخنهاش را بسوزن فکرت <br />بر دل و جان لطیف خویش بیاژن .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> درنشاندن تیر در تن خصم و مانند آن . رجوع به آژده شود <span class=\"hlight\">:</span> <br />ز بس در چرم ایشان آژده تیر<br />تو گفتی پُر ز پَر گشتند نخجیر.<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> رندیدن، چنانکه با سوهان و مانند آن <span class=\"hlight\">:</span> <br />زبان را نگهدار باید بدن <br />نباید زبان را بزهر آژدن .<br /> <font color=\"Red\">فردوسی .</font><br />بکام اندرش نیزه ٔ آهنین <br />بدندان چو سوهان بیاژد بکین .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> سوراخ کردن <span class=\"hlight\">:</span> <br />کنون نیزه و گرزباید زدن <br />همه چشم دشمن به تیر آژدن .<br /> <font color=\"Red\">فردوسی .</font><br />میندیش از آن کآن نشاید بدن <br />که نتوانی آهن به آب آژدن .<br /> <font color=\"Red\">فردوسی .</font><br />همه چرم او را به تیر آژدن .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> اندودن . رنگ کردن . ملون کردن . طلی کردن . روکش کردن، باصطلاح امروز <span class=\"hlight\">:</span> <br />سوی خانه شد دختر دل زده <br />رخان معصفر بخون آژده .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بسیم، بزر آژدن </span> ؛ سیم اندود، زراندود، مُفَضَّض، مُذَهَّب کردن <span class=\"hlight\">:</span> <br />نشسته بر او بر، زنی تاجدار<br />ببالای سرو و برخ چون بهار<br />فروهشته بر سرو مشکین کمند<br />که کردی بدان پردلان را به بند...<br />بسان ستونی بسیم آژده <br />رخش رشک خورشید تابان شده .<br /> <font color=\"Red\">فردوسی .</font><br />نشست اندر آن شهر از آن کرده بود<br />که کندز فریدون برآورده بود<br />برآورده در کندز آتشکده <br />همه زند و استا بزر آژده .<br /> <font color=\"Red\">فردوسی .</font><br />بی اندازه زرّین و سیمین دَده <br />درون مشک و بیرون بزر آژده .<br /> <font color=\"Red\">اسدی .</font><br />نوان اندرآمد <font color=\"DarkGreen\"><b>[ انوشیروان ]</font></b> به آتشکده <br />نهادند گاهی بزر آژده <br />نهاده بدو نامه ٔ زند و اُست <br />به آواز برخواند موبد درست .<br /> <font color=\"Red\">اسدی .</font><br />ز پولاد درآژده مغفرش <br />پرندین نشان بسته اندر سرش .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> بساییدن . مالش دادن <span class=\"hlight\">:</span> <br />از گرد سفالت بلب جوی سخندان <br />جان را بکف عقل همی شوی و همی آژ.<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آژدن به سیم، آژدن به زر</span> ؛ سیم کوفت، زرکوب کردن <span class=\"hlight\">:</span> <br />نهادند <font color=\"DarkGreen\"><b>[ ترکان ]</font></b> سرسوی آتشکده <br />بدان کاخ و ایوان زرآژده <br />همه زند و استا برافروختند<br />همه کاخ و ایوانها سوختند.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آژدن سنگ آسیا</span> ؛ نقر طاحونه .<br /> <BR><font color=\"Blue\">◄</font> گودی و فرورفتگی در سطح چیزی پدید آوردن از خلانیدن چیزی تیز چون سوزن و مانند آن بی آنکه سوراخی در آن پیدا آید. استیشام . نکنده کردن <span class=\"hlight\">:</span> <br />چشم مخالفت بیاژن به تیر<br />همچو کف ولی بزر آژدی .<br /> <font color=\"Red\">فرخی .</font><br />نارنج چو دو کفّه ٔ سیمین ترازو<br />هر دو ز زر سرخ طلی کرده برونسو<br />آکنده بکافور و گلاب خوش و لؤلو<br />و آنگاه یکی زرگرک زیرک جادو<br />به آژیر بهم باز نهاده لب هردو<br />رویش بسرسوزن تیز آژده هموار.<br /> <font color=\"Red\">منوچهری .</font><br />بادام وار چشم حسود تو آژده <br />وز ناله باز مانده دهان همچو پسته باد.<br /> <font color=\"Red\">انوری .</font><br />از ملاقات هوا روی غدیر<br />راست چون آژده ٔ سوهان است .<br /> <font color=\"Red\">انوری .</font><br />رخ عدوت چو نارنگ زرد و آژده باد<br />بسوزنی که نه آتش گدازدو نه زرنگ .<br /> <font color=\"Red\">ظهیر فاریابی .</font><br /> <BR><font color=\"Blue\">◄</font> ترصیع. مرصع کردن . درنشاندن در... <span class=\"hlight\">:</span> <br />بفرمود تا تاج خاقان چین <br />به پیش آورد موبد پاکدین <br />گهرها که بود اندر آن آژده <br />بکندند و دیوار آتشکده <br />بزرّ و بگوهر بیاراستند...<br /> <font color=\"Red\">فردوسی .</font><br />صد اشتر ز گنج و درم کرد بار <font color=\"DarkGreen\"><b>[ قیصر روم ]</font></b><br />ز دینار پنجَه ْ زبهر نثار...<br />همان چند زرین و سیمین دده <br />ز گوهر بر و چشمشان آژده <br />بمریم <font color=\"DarkGreen\"><b>[ زن خسروپرویز ]</font></b> فرستاد چندی گهر<br />یکی نغز طاوس کرده بزر.<br /> <font color=\"Red\">فردوسی .</font><br />پی افرازه سیمین و زرین زده <br />درون مشک، بیرون به دُر آژده .<br /> <font color=\"Red\">اسدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کام شیر آژدن </span> ؛ تعبیری مثلی، مانند کام شیر خاریدن، دم شیر ببازی گرفتن ؛ دشمن صعب و هول را آزردن و از اینرو خود را بخطر کین خواهی او افکندن <span class=\"hlight\">:</span> <br />همه مولش و رای چندان زدن <br />بدین نیشتر کام شیر آژدن .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2814, 'آژده', '<span class=\"hlight\">آژده .</span> <font color=\"DarkGreen\"><b>[ ژْ <span class=\"hlight\" dir=\"rtl\">/</span> ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آزده . آجیده . آژیده . آجده . خلیده با چیزی نوک تیز <span class=\"hlight\">:</span> <br />اندام دشمنان تو از تیر ناوکی <br />مانند سوک خوشه ٔ جو باد آژده .<br /> <font color=\"Red\">شاکر بخاری .</font><br />بداغی جگرْشان کنی آژده <br />که بخشایش آرند دام و دده .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مجازاً، خسته . مجروح . حزین . غمین <span class=\"hlight\">:</span> <br />نه مردم شمر بل زدیو و دده <br />دلی کو نباشد بدرد آژده .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آژده کردن </span> ؛ مجازاً، خسته، مجروح، حزین، غمین کردن <span class=\"hlight\">:</span> <br />دل هر دو بیدادگر را بسوز<br />که هرگز نبینند جز تیره روز<br />بداغی جگرْشان کنی آژده <br />که بخشایش آرد بر ایشان دده .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> رنگ کرده . ملون <span class=\"hlight\">:</span> <br />سوی خانه شد دختر دل زده <br />رخان معصفر بخون آژده .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> دوخته با بخیه های نکنده . <BR><font color=\"Blue\">◄</font> منقور. منقوره، چنانکه در سنگ آسیا. <BR><font color=\"Blue\">◄</font> جامه ٔ نکنده زده . مُضرَّ به . (صحاح الفرس ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آژده بودن بزر</span> ؛ غرق زر بودن <span class=\"hlight\">:</span> <br />دورویه بزرگان کشیده رده <br />سراپای یکسر بزر آژده .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> معنی کلمه ٔ آژده در این قطعه ٔ فردوسی برای نگارنده روشن نیست <span class=\"hlight\">:</span> <br />بفرمود کآهنگران آورند<br />مس و روی و پتک گران آورند<br />گچ و سنگ و هیزم فزون از شمار<br />بیارند چندانکه آید بکار<br />بی اندازه بردند چیزی که خواست <br />چو شد کار بر آرزو کرده راست <br />ز دیوارگر، هم ز آهنگران <br />هر آنکس که استاد بود اندر آن <br />ز گیتی بنزد سکندر شدند<br />بر آن کار بایسته یاور شدند<br />ز هر کشوری دانشی شد گروه <br />دو دیوار کرد از دو پهنای کوه <br />ز بن تا سر تیغ بالای او<br />چو صد شاه رش کرده پهنای او<br />از او صد رش انگشت و آهن یکی <br />پراکنده مس در میان اندکی <br />همی ریخت گوگردش اندر میان <br />چنین باشد افسون و رای کیان <br />همی ریخت هر گوهری یک رده <br />چو از خاک تا تیغ گشت آژده <br />بسی نفت و روغن برآویختند <br />همی بر سر گوهران ریختند<br />بخروار انگشت بر سر زدند<br />بفرمود تا آتش اندرزدند.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2815, 'آژغ', '<span class=\"hlight\">آژغ .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِ) رجوع به آزغ شود.<br /></font></div>'),
(2816, 'آژفنداک', '<span class=\"hlight\">آژفنداک .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (اِ) آزفنداک . آفنداک .<br /></font></div>'),
(2817, 'آژن', '<span class=\"hlight\">آژن .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (ن مف مرخم ) این کلمه در عقیب بعض اسماء درآید و بکلمه معنی وصف مفعولی دهد، چون تیرآژن و شمعآژن، که بمعنی به تیرآژده و بشمعآژده باشد <span class=\"hlight\">:</span> <br />کَشَف کردار هر کو سر کشید از طوق امرت سر<br />بسان خارپشتش کرد شست چرخ تیرآژن .<br /><font color=\"Red\">سید ذوالفقار شیروانی .</font><br /></font></div>'),
(2818, 'آژند', '<span class=\"hlight\">آژند.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) گل یا شفته ٔ دیگر که میان دو خشت گسترند پیوستن بیکدیگر را. ملاط. اَژند. <BR><font color=\"Blue\">◄</font> گل و لای که در ته آبی نشیند. <BR><font color=\"Blue\">◄</font> گِلابه .<br /></font></div>'),
(2819, 'آژندن', '<span class=\"hlight\">آژندن .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ ]</font></b> (مص ) ملاط یعنی آژند میان دو خشت و مانند آن گستردن، پیوستن آن دو را. <BR><font color=\"Blue\">◄</font> آجیدن . و رجوع به آزندن شود.<br /></font></div>'),
(2820, 'آژنده', '<span class=\"hlight\">آژنده .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه گل میان دو خشت گسترد. <BR><font color=\"Blue\">◄</font> آنکه آجیده و آژده کند.<br /></font></div>'),
(2821, 'آژندیدن', '<span class=\"hlight\">آژندیدن .</span> <font color=\"DarkGreen\"><b>[ ژَ دی دَ ]</font></b> (مص ) آژندن . ملات و گل میان دو خشت یا آجر و سنگ گستردن دوسانیدن آن دو را.<br /></font></div>'),
(2822, 'آژندیده', '<span class=\"hlight\">آژندیده .</span> <font color=\"DarkGreen\"><b>[ ژَ دی دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) بملاطکرده .<br /></font></div>'),
(2823, 'آژنگ', '<span class=\"hlight\">آژنگ .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) چین . شکن . شکنج . انجوغ . نَوَرد. ترنجیدگی که بر اندام افتد از خشم یا پیری و یا بیماری <span class=\"hlight\">:</span> <br />بماندستم چون فنگ در این خانه و دلتنگ <br />ز سرما شده چون نیل سر وروی پرآژنگ .<br /> <font color=\"Red\">حکاک .</font><br />دلی را پر از مهر دارد سپهر<br />دلی پر ز کین و پرآژنگ چهر.<br /> <font color=\"Red\">فردوسی .</font><br />چو کاوس دژخیم دیگر نیا<br />پرآژنگ رخ، دل پر از کیمیا.<br /> <font color=\"Red\">فردوسی .</font><br />تو با دشمنت رخ پرآژنگ دار<br />بداندیش را چهره بیرنگ دار.<br /> <font color=\"Red\">فردوسی .</font><br />بگفت این و بیرون شد از پیش اوی <br />پر از خشم جان و پرآژنگ روی .<br /> <font color=\"Red\">فردوسی .</font><br />ز گرگان بیامدسوی راه بُست <br />پرآژنگ رخسار و ناتندرست .<br /> <font color=\"Red\">فردوسی .</font><br />پرآژنگ شد روی پور پشنگ <br />ز گفتار اغریرث آمدْش ننگ .<br /> <font color=\"Red\">فردوسی .</font><br />به نزدیک شیروی رفت آن دو مرد<br />پرآژنگ رخسار و دل پر ز درد.<br /> <font color=\"Red\">فردوسی .</font><br />رخ شاه ایران پرآژنگ شد<br />وز آن کار دشمن دلش تنگ شد.<br /> <font color=\"Red\">فردوسی .</font><br />پراکنده گشت آن بزرگ انجمن <br />همه رخ پرآژنگ و دل پرشکن .<br /> <font color=\"Red\">فردوسی .</font><br />نه بخشایش آرد بکس بر نه مهر<br />دژآگاه دیوی پرآژنگ چهر.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد نهم روز بوزرجمهر<br />پر از آرزو دل، پرآژنگ چهر.<br /> <font color=\"Red\">فردوسی .</font><br />یکی نامه بنوشت پر داغ و درد<br />پرآژنگ رخ، لب پر از باد سرد.<br /> <font color=\"Red\">فردوسی .</font><br />ز پاسخ پرآژنگ شد روی شاه <br />چنین گفت کو دور مانَد ز راه .<br /> <font color=\"Red\">فردوسی .</font><br />برفتند یکسر پرآژنگ چهر<br />بیامد برِ شاه بوزرجمهر.<br /> <font color=\"Red\">فردوسی .</font><br />بزرگواری و کردار او و بخشش او<br />ز روی پیران بیرون همی برد آژنگ .<br /> <font color=\"Red\">فرخی .</font><br />آنکه چون روی بخوارزم نهاد، از فزعش <br />روی لشکرکش خوارزم درآورد آژنگ .<br /> <font color=\"Red\">فرخی .</font><br />ترا چشم درد است و من آفتابم <br />ازیرا ز من رخ پرآژنگ و چینی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />زی تو آید عدو چو نصرت یافت <br />کرده دل تنگ و روی پرآژنگ .<br /> <font color=\"Red\">ناصرخسرو.</font><br />پرآژنگ رخ داد پاسخ تورگ <br />که گر کوچکم هست کارم بزرگ .<br /> <font color=\"Red\">اسدی .</font><br />رخ شاه از انده پرآژنگ شد<br />ز کرده پشیمان و دلتنگ شد.<br /> <font color=\"Red\">اسدی .</font><br />آن دم که بدم جوان و مویم شبه رنگ <br />صد حور بدی بدامنم درزده چنگ <br />اکنون که شدم پیر و برخ پرآژنگ <br />از من زن و فرزند همی دارد ننگ .<br /> <font color=\"Red\">ازرقی .</font><br />ای زمین گوهر، شد روی من از آتش دل <br />همچو آبی که بر او باد وزد از آژنگ .<br /> <font color=\"Red\">سنائی .</font><br />چون چشم ترکان ودل بخیلان تنگ است و چون روی کریمان بی آژنگ . (مقامات حمیدی ).<br />هیچ آژنگی نیفتد بر رخت <br />تازه ماند این شباب فرخت .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> گرِه . خم <span class=\"hlight\">:</span> <br />ز بس اندیشه کردن گشت دلتنگ <br />رخش بی رنگ و پیشانی پرآژنگ .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />چندین آژنگ نامیدی را در پیشانی مه آرید آن چوب خشک اگرآژنگ نامیدیها پرده بر پرده بر پوست او افتاده است اما چون فصل بهار می آید تازگیش میدهیم . (کتاب المعارف ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آژنگ در ابرو آوردن </span> ؛ چین به ابرو افکندن . شکن در ابرو آوردن . (زمخشری ). خم بابرو آوردن .<br /> <BR><font color=\"Blue\">◄</font> انقباض . گرفتگی <span class=\"hlight\">:</span> <br />چنین گفت با مادر اسفندیار<br />که نیکو زد این داستان هوشیار<br />که پیش زنان راز هرگز مگوی <br />چو گوئی سخن بازیابی بکوی ...<br />پر آژنگ و تشویر شد مادرش <br />ز گفتن پشیمانی آمد برش .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> کیس که در جامه افتد. <BR><font color=\"Blue\">◄</font> موج خرد که در آب پدید آید. <BR><font color=\"Blue\">◄</font> (اِخ ) در بعض فرهنگهابه آژنگ معنی نگارخانه ٔ مانی داده اند و بیت ذیل را مثال آورده اند <span class=\"hlight\">:</span> <br />ز بس جادوئیها و فرهنگ او<br />بدو بگرویدند و آژنگ او.<br />ولی کلمه ٔ آژنگ ظاهراً مخفف ارژنگ و ارتنگ باشد.<br /></font></div>'),
(2824, 'آژنگ ناک', '<span class=\"hlight\">آژنگ ناک .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (ص مرکب ) شکن، شکنج، چین، نورد، گره، انجوغ دار. ترنجیده . چین خورده . کیس . <BR><font color=\"Blue\">◄</font> مواج . <BR><font color=\"Blue\">◄</font> منقبض . گرفته .<br /></font></div>'),
(2825, 'آژنگ ناکی', '<span class=\"hlight\">آژنگ ناکی .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (حامص مرکب ) صفت و چگونگی آژنگ ناک . شکن، شکنج، چین، نورد، انجوغ گرفتگی . چین خوردگی . <BR><font color=\"Blue\">◄</font> انقباض . <BR><font color=\"Blue\">◄</font> تشنج . <BR><font color=\"Blue\">◄</font> کیسی .<br /></font></div>'),
(2826, 'آژنگ چهر', '<span class=\"hlight\">آژنگ چهر.</span> <font color=\"DarkGreen\"><b>[ ژَ چ ِ ]</font></b> (اِخ ) لقب رادبرزین <span class=\"hlight\">:</span> <br />همان نیز چون قارن و برزمهر<br />دگر رادبرزین آژنگ چهر.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2827, 'آژنگ گرفتن', '<span class=\"hlight\">آژنگ گرفتن .</span> <font color=\"DarkGreen\"><b>[ ژَ گ ِ رِ ت َ ]</font></b> (مص مرکب ) چین، شکن، شکنج، گره، انجوغ پیدا کردن . ترنجیدن . نورد پیدا کردن . منقبض شدن . متشنج گشتن . تقلص .<br /></font></div>'),
(2828, 'آژور', '<span class=\"hlight\">آژور.</span> (ص مرکب ) در بعض فرهنگهاآزور ضبط کرده اند و بیت انوری را که در فرهنگها برای آزور نیز شاهد آمده مثال آورده اند. و ظاهراً تصحیف آزور باشد.<br /></font></div>'),
(2829, 'آژوغ', '<span class=\"hlight\">آژوغ .</span> (اِ) آژُغ . آزوغ . آزُغ . اَزغ .<br /></font></div>'),
(2830, 'آژگن', '<span class=\"hlight\">آژگن .</span> <font color=\"DarkGreen\"><b>[ گ ِ ]</font></b> (ص مرکب، اِ مرکب ) دری مُشبک که از پس آن توان دیدن . غلبکن .<br /></font></div>'),
(2831, 'آژی ده آک', '<span class=\"hlight\">آژی ده آک .</span> <font color=\"DarkGreen\"><b>[ دَه ْ]</font></b> (اِخ ) (از: آژی، مار + ده، عشره + آک، ظ. به معنی اسب ) آزی ده آک . ضحاک . و رجوع به آک و بیوراسب شود.<br /></font></div>'),
(2832, 'آژیانه', '<span class=\"hlight\">آژیانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) فرش زمین از مرمر و گچ کرده . <BR><font color=\"Blue\">◄</font> فرش زمین از سنگ و خشت پخته <span class=\"hlight\">:</span> <br />برای زینت درگاه عالیت <br />ز مهر و ماه کردند آژیانه .<br /><font color=\"Red\">عمید لوبکی .</font><br /></font></div>'),
(2833, 'آژیخ', '<span class=\"hlight\">آژیخ .</span> (اِ) در بعض فرهنگها به این کلمه معنی رمص یعنی آب خشک و سطبر شده ٔ کنج چشم داده اند که امروز قی و در گیلان کَنَد گویند، و بیت ذیل را شاهد آورده اند <span class=\"hlight\">:</span> <br />همواره پرآژیخ است آن چشم فژاگن <br />گوئی که دو بوم آنجا بر، خانه گرفته ست .<br /> <font color=\"Red\">عماره ٔ مروزی .</font><br />لکن ظاهراً چنین کلمه ای در فارسی نباشد و از غلط خواندن بیت عماره ساخته شده است . شعر عماره در فرهنگ اسدی خطی کهنی «همواره پر از پیخ است ...» ضبط شده و برای پیخ مثال آمده است و حق نیز همانست، چه پیخال نیز به همین معنی یا منسوب به پیخ در لغت فارسی هست . و در بعض فرهنگهای نو برای آژیخ بیتی از طیان نیز بتأیید شاهد میگذرانند که ظاهراً مصنوع و مجعول است . و پیخ و پیخال به معنی مطلق چرک و شوخ و فضول است نه رَمص .<br /></font></div>'),
(2834, 'آژیدن', '<span class=\"hlight\">آژیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آژدن . آجیدن .<br /></font></div>'),
(2835, 'آژیده', '<span class=\"hlight\">آژیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ]</font></b> (ن مف ) آژده . آجیده . آجده . نکنده کرده <span class=\"hlight\">:</span> <br />ملاف با قلمی ای لباس آژیده <br />بروی کار چو افتاد بخیه ات یکسر.<br /><font color=\"Red\">نظام قاری .</font><br /></font></div>'),
(2836, 'آژیر', '<span class=\"hlight\">آژیر.</span> (ص ) محتذر. حَذِر. برحذر. محتاط. بپرهیز <span class=\"hlight\">:</span> <br />کنون باید آژیر بودن ز شیر<br />که در مهرگان بچه دارند زیر.<br /> <font color=\"Red\">فردوسی .</font><br />که برگشت از اینگونه افراسیاب <br />همانا بجنگ تو دارد شتاب <br />سپه را بیارای و آژیرباش <br />شب و روز با ترکش و تیر باش .<br /> <font color=\"Red\">فردوسی .</font><br />پراندیشه شد نامجوی از تباک <br />دلش گشت از آن پیر پر ترس و باک <br />براه اندر از پیر آژیر بود<br />که با او سپاهی جهانگیر بود.<br /> <font color=\"Red\">فردوسی .</font><br />ز بدخواه روز و شب آژیر بود<br />بهر جای خوردنْش نخجیر بود.<br /> <font color=\"Red\">فردوسی .</font><br />هم از دشمن آژیر بودن بجنگ <br />نگه داشتن بهره ٔ نام و ننگ .<br /> <font color=\"Red\">فردوسی .</font><br />برستم بفرمود کآژیر باش <br />شب و روز با مغفر و تیر باش .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آژیرتر</span> ؛ احذر <span class=\"hlight\">:</span> <br />ز دشمن ز نخجیر آژیرتر<br />برِ دوست پیوسته چون تیر و پر.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> قوی . توانا <span class=\"hlight\">:</span> <br />گرت رای با آزمایش بود<br />همه روزت اندر فزایش بود<br />شود جانت از دشمن آژیرتر<br />دل و مغز و رایت جهانگیرتر.<br /> <font color=\"Red\">فردوسی .</font><br />چو آژیر باشی ز دشمن به رای <br />بداندیش را دل برآید ز جای .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) قوّت . توان . توانائی <span class=\"hlight\">:</span> <br />چراگاه این گاو کمتر نبود<br />هم آبشخورش نیز بدتر نبود (کذا)<br />به پستان چنین خشک شد شیر اوی <br />دگرگونه شد رنگ و آژیر اوی .<br /> <font color=\"Red\">فردوسی .</font><br />برِ زادفرخ یکی پیر بود<br />که در کار کردن پرآژیر بود.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> غلبه . <BR><font color=\"Blue\">◄</font> بانگ . <BR><font color=\"Blue\">◄</font> بعض فرهنگها به این کلمه معنی آماده و حاضر و آگاه و زیرک و ذکی و دانا و هشیار، بهوش و هوشمند و تیزفهم داده اند و ظاهراً در معنی این کلمه در بعض شواهد مذکوره ٔ فوق باشتباه افتاده اند. و نیز آژیر را به معنی پرهیزکاری آورده و بیت اسدی : سراسر همه دشت ... را مثال قرار داده اند و بی شبهه بدین معنی نیست و بعضی به معنی ژی و آبگیر و گَوی که در آن آب جمع شده گفته اند و بیت منوچهری را شاهد گذرانیده اند<span class=\"hlight\">:</span> <br />شیر دهدْشان بپای مادر آژیر...<br />و آن نیز بی شک غلط است . در ابیات ذیل معنی کلمه بر نگارنده مجهول است <span class=\"hlight\">:</span> <br />ازار از یکی چرم نخجیر بود<br />گیا خوردن و پوشش آژیر بود.<br /> <font color=\"Red\">فردوسی .</font><br />زبان در سخن گفتن آژیر کن <br />خرد را کمان و زبان تیر کن .<br /> <font color=\"Red\">فردوسی .</font><br />یکی نغز پولاد زنجیر داشت <font color=\"DarkGreen\"><b>[ اسفندیار ]</font></b><br />نهان کرده از جادو آژیر داشت <br />بینداخت زنجیر در گردنش <br />بدانسان که نیرو ببرد از تنش .<br /> <font color=\"Red\">فردوسی .</font><br />سراسرهمه دشت نخجیر بود<br />گیا خوردن و پوشش آژیر بود.<br /> <font color=\"Red\">اسدی .</font><br />و صاحب صحاح الفرس پرهیزکار را یکی از معانی کلمه قرار داده و بیت ذیل را شاهد گذرانیده است <span class=\"hlight\">:</span> <br />ترا نخوانم جز کافر و ستمگر از آنک <br />ببد نمودن من کرده کار آژیری .<br /> <font color=\"Red\">دقیقی .</font><br />و در این بیت معنی مجرّب و آزموده یا ذکی و هشیار انسب مینماید.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به آژیر</span> ؛ بامهارت . به اُستادی . بدقت . باحتیاط <span class=\"hlight\">:</span> <br />نارنج چو دو کفّه ٔ سیمین ترازو<br />هر دو ز زر سرخ طلی کرده برونسو<br />آکنده بکافور و گلاب خوش و لؤلو<br />وآنگاه یکی زرگرک زیرک جادو<br />به آژیر بهم باز نهاده لب هر دو<br />رویش بسر سوزن تیز آژده هموار.<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> ساعی . کوشا. مُجدّ. جادّ <span class=\"hlight\">:</span> <br />رزبان گفت چه رای است و چه تدبیر همی <br />مادر این بچگکان را ندهد شیر همی <br />نه بپروردنشان باشد به آژیر همی <br />نه رهاشان کند از حلقه ٔ زنجیر همی .<br /> <font color=\"Red\">منوچهری .</font><br />شیر دهدْشان بپای مادر به آژیر<br />کودک دیدی کجا بپای خورد شیر؟<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(2837, 'آژیراک', '<span class=\"hlight\">آژیراک .</span> (اِ) اَژیراک . بانگ و فریاد از آدمی و ستور.<br /></font></div>'),
(2838, 'آژیرنده', '<span class=\"hlight\">آژیرنده .</span> <font color=\"DarkGreen\"><b>[ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آگاهاننده .<br /></font></div>'),
(2839, 'آژیریدن', '<span class=\"hlight\">آژیریدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) هشیار کردن . <BR><font color=\"Blue\">◄</font> بانگ زدن . خروشیدن . <BR><font color=\"Blue\">◄</font> آگاهانیدن . خبردار کردن . خبردار گفتن . اعلام . اعلان . <BR><font color=\"Blue\">◄</font> مهیا ساختن .<br /></font></div>'),
(2840, 'آژیریده', '<span class=\"hlight\">آژیریده .</span> <font color=\"DarkGreen\"><b>[دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آگاه کرده . <BR><font color=\"Blue\">◄</font> مهیاشده .<br /></font></div>'),
(2841, 'آژینه', '<span class=\"hlight\">آژینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) آزینه . آهنی باشد چون کلندی با دندانه های درشت و دسته ٔ چوبین که سنگ آسیا را از درون سوی بدان نقر کنند تا دانه بهتر خرد کند. آسیازَنه . آس افزون . آس افژون . منقار. مِکْوَس . میقعه . بِرطیل . آسیاآژن .<br /></font></div>'),
(2842, 'آک', '<span class=\"hlight\">آک .</span> (پسوند) ر تباک و خاشاک و خباک و سوزاک و فغاک و کاواک و مغاک و نماک، حرف نسبت است . و در خوراک و پوشاک افاده ٔ لیاقت کند.<br /></font></div>'),
(2843, 'آک', '<span class=\"hlight\">آک .</span> (هندی، اِ) درزبان هندی به معنی آتش و نیز نام درختی که شیره ٔ آن زهر قاتل است و یا درخت عُشَر. و رجوع به آگ شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2844, 'آک', '<span class=\"hlight\">آک .</span> (اِ) بعض فرهنگ نویسان ما این صورت را آورده و بدان معنی آسیب، آفت، عاهت، عیب، عار و آهو و زشتی داده اند. و در کلمه ٔ ده آک، صورتی از ضحّاک نیز می آورند که چون ضحّاک صاحب ده عیب : زشتی، کوتاهی، بیدادگری، بیشرمی، بسیارخواری، بدزبانی، دروغگوئی، شتابکاری، بددلی و بی خردی بوده او را ده آک خوانده اند. و حمزه ٔ اصفهانی در کتاب خود تاریخ سنی ملوک الأرض گوید: «بیورسب، ده آک، اشتقاقه : ده، اسم لعقد العشرة و آک اسم للاَّفة والمعنی انّه کان ذاعشر آفات احدثها فی الدنیا و لیس هذا موضع ذکرها و هذا لقب فی نهایة القبح فلمّا عرّبوه صار فی نهایة الحسن لأن ده آک لما عرّب انقلب الی ضحّاک و به یسمی فی کتب العربیّة و هو بیوراسف بن ارونداسف بن ریکاون ...». و صاحب مجمل التواریخ نیز که ظاهراً مأخذیگانه ٔ او همین کتاب حمزه است گوید ضحّاک بیوراسپ، او را بیوراسپ خوانند، و گویند بیور، اسپ تازی بهره ای <font color=\"DarkGreen\"><b>[ ظ : بهرّای ]</font></b> از زر و سیم پیش وی جنیبت کشیدندی ... و پارسیان ده آک گفتندی از جهت آنکه ده آفت و رسم زشت در جهان آورد از عذاب و آویختن و فعلهاء پلید و آک را معنی زشتی و آفت است پس چون معرب کردند سخت نیکو آمد، ضحاک یعنی خندناک - انتهی . کلمه ٔ آک را فردوسی، با احتیاجی که ضرورةً در قوافی پنجاه - شصت هزاربیت گاهی او را دست داده یک بار هم استعمال نکرده است . در شعرای سامانی و غزنوی با اینکه خباک و هباک و غساک و ستاک و ورکاک و فغاک و بساک و کراک و هزاک و کاک و شرفاک و آزفنداک و نظایر آن را قافیه کرده اند کلمه ٔ آک دیده نشده است . اسدی در گرشاسب نامه و هم در فرهنگ خود با اصراری که در ضبط نوادر و شوارد ورزیده، آک را نیاورده . شعرای سلجوقی تا اندازه ای که فحص آن برای من میسر شده این لغت را بکار نبرده اند و سعدی و حافظ و بعض گویندگان دیگر که باین قافیه غزل و قطعه ای سروده اند این لفظ را ندارند. و در لغت های مترجم عربی به فارسی مانند مقدّمةالادب زمخشری و صراح قرشی و السامی میدانی و مهذب الاسماء ربنجنی و دستوراللغه ٔ نطنزی و دستورالاخوان قاضی محمد دهار و مصادر زوزنی، در ترجمه ٔ کلمات عیب، عار، وصمت، نقیصه، آفت، عاهت، صدمت، ثلب، قبح و مترادفات آنها بکلمه ٔ آک برنمیخوریم . و در تداول فارسی زبانان امروز نیز این لفظ شنیده نمیشود. تنها فرهنگ نویسان قرون اخیر از منصور شیرازی که ظاهراً همان غیاث الدین منصور دشتکی باشد بیت ذیل را برای لفظ و معنی آک شاهد می آورند <span class=\"hlight\">:</span> <br />عدوی توکه چو هیزم شکسته باد مدام <br />تنور حادثه میسوزدش در آتش آک .<br />و نیز سوزنی دو بار این کلمه را آورده است <span class=\"hlight\">:</span> <br />آکی نرسید بر تو از من <br />صد بار مرا ز تو رسید آک .<br /> <font color=\"Red\">سوزنی .</font><br />بدین صفت که منم هرکجا فتم خیزم <br />که آک ناید خود آک را من آرم آک .<br /> <font color=\"Red\">سوزنی .</font><br />و چنانکه مشهود است در استعمال این دو شاعر نیز (در صورتی که کلمه محرّف ِ باک و ناک و نظایرآن نباشد) معنی مدّعای فرهنگ نویسان صریح نیست مثلاً در بیت منصور معنی حرمان یا حسد مناسب تر است و در بیت دوم سوزنی «باک » بودن اصل کلمه بعید نیست . و بر فرض صراحت این معنی برای این لفظ در سه مورد فوق خودداری همه ٔ شعرا و نویسندگان سلف تا نیمه ٔ اول قرن ششم (زمان سوزنی ) و نیز احتراز تمام گویندگان خلف (به استثنای منصور) از استعمال این کلمه عجیب است . و عجب ترآنکه از معنی کلمه ٔ ضحاک یا ده آک نیز مورخین معتبر قدیم از قبیل ابوحنیفه احمدبن داود دینوری و طبری و بلعمی و ابوعلی مسکویه و مسعودی هیچیک اطلاعی ندارند:فاَحس َ بذلک َ بیورسب و هو الذی تسمیه العرب الضحاک َ. (ابوعلی مسکویه ). ثم ملک َ بعده بیوراسب بن اردواسب بن رستوان بن نیاداس ... و هو الده آک و قد عرّب اَسمائُه ُ جمیعاً فسماه ُ قوم ٌ من العرب الضحاک و سماه ُ قوم ٌبهراسب و لیس َ هو کذلک و انما اسمه ُ علی ما وَصفنا بُیوراسب و قَتل َ جمشیدَ الملک ... (مروج الذهب ). و اَن َّ الضحاک الذی تسمیه العجم بیوراسف عند ماکان َ من غلبته جم الملک و قتله ُ ایاه و اطمئنانه ُ فی الملک و فراغُه ُ اَخذ یجمعُ الیه السحرة من آفاق ِ مملکته و یتعلم ُ السحرَ حتی صار فیه اماماً. (اخبارالطوال ابوحنیفه ٔ دینوری ). ایدون گویند که این مرد <font color=\"DarkGreen\"><b>[ بیوراسب ]</font></b> بیامد و شهرها بگرفت ... بیوراسب جمشید بگرفت ... و ارّه بر سرش نهاد و تا پای بدو نیمه کردش . (بلعمی ). وحتی شاهنامه که هیچ فرصت را برای نمودن مثالب دشمنان ایران، خاصه عرب فوت نکرده است به معنی زشت نام این تازی غاصب تاج و تخت ایران و صنم عقلی جور و بیدادی اشاره ای هم ندارد . و این امر مینماید که قدما از چنین معنی برای چنین صورت بی خبر بوده اند. و این لفظ با معنای منتسب بدان را ظاهراً بار اول حمزه که کتاب او مشحون بوجه اشتقاقهای مصنوع و منحوت و معانی مجعول من عندی میباشد آورده است، و صاحب مجمل التواریخ نیزکه قدوه و امام او حمزه است باو تأسّی کرده، بی آنکه دیگر نویسندگان و شعرا (جز سوزنی باحتمالی ضعیف ) بتقلید و تأیید و تأکید آن پرداخته باشند. و بگمان نگارنده کلمه ٔ ده آک بلهجه ای از لهجه های پارسی یا مادی یا یکی از همسایگان مثلاً بابلی، ترجمه یا صورت دیگر بیوراسب است : ده و بیور مترادف یکدیگر به معنی عشره و آک و اسب نیز، هم معنی، یعنی فَرَس . و این دعوی را تأیید میکند آمدن لفظ آس و اسپ و اَسپا چنانکه آش و اشوا و آک و اَک و آکا در بسیاری از اعلام اشخاص یعنی همانطور که گشنسپ، لهراسپ، گشتاسب (ویشتاسپ )، شیدسپ، زراسپ، ارجاسپ، برجاسپ، گرشاسپ (گرش اَشوا)، تهماسپ، جاماسپ، اَوروَت اسپا، پئوروش اسپ، هورشسپ، اَرِم اسپا (آرام اسپ )، آریااسپا (آری اسپ )، اَسپاچنا (خواهنده ٔ اسپ )، اَسپامترا، اشوامترا، اسپااِشا، کَرَن اسپا، هواسپا، اواسپا، واتاسپا (باداسپ )، فرش اسپا، رُدْراسپا، ستااسپا (صداسپ )، توری اسپا، هوداتااسپا، همازااسپا و بلاش در نامهای کسان آمده است، همانطور هم تیماک، لهّاک، آرشاک، اَرَناک، افراواک (اوشهنگ بن افراواک . آثارالباقیه )، آرمناک، سیماک (نامی از نامهای غلامان )، هوراماک، فورسراسیاک (اصل نام افراسیاب )، طورک، سیامَک، فرانَک، مزدک، هروک، ایلک، هویدَک، لَمبک، برمک، پاپک، فورک، آبی یاتاکا، مناشاکا (ماناهاکا)، مزدَآکا، ماهاکا، اِست وهاکا، پَشاکا، ورنداق (فارس بن رنداق ) نام گذاشته اند. و در اسماء امکنه نیز چنانکه گل اسپ، هزاراسپ، جاسپ، خراسپ، برطاس و اوطاس آمده است کلمات مختوم به آک و اَک و آق، مانند خفچاق، بجناک، کیماک، یَمک، ارداک، نارمَک، سَرمَک، هزَک، آرمَک، نامَک، سینک، انداق (قریه ای بمرو و قریه ای بسمرقند) و یلاق و امثال آن نیز بسیار است و حتی بعض از اسامی معین عیناً همانطور که به اسپ تمام شده به آک نیز ختم شده است مثل فَرَن اسپا و فَرَناکا و زیری اَسپا و زیراک (نام موبدی ). در زبان لاطینی اِکوئوس به معنی اسپ است و اِکی تاسیو به معنی سواری و سوارکاری و در زبان انگلیسی اِکستریَن به معنی سوار و در فرانسه اِکی تاسیون سواری و اِکویّر زن سوارکار و اِکوری عین کلمه ٔ آخور فارسی بمعنی آخور یعنی اصطبل و در فارسی علاوه بر کلمات هَذلَک (بمعنی اسب پالانی ) و نعلک (نوعی از رکاب ) و پشک و پشتک (بیماری در اسب ) و فتراک (دوالی که از پس و پیش زین اسب آویزند) و کرَنگ و سرخنگ و خنگ و هدنک (در رنگهای اسب ) و پالاهنگ (اسب جنیبت ) و آهِنگ (بمعنی نعل یا پابند اسب ) و بیراک (که آن را استر و خرکره ترجمه میکنند) و یراغ و یَرَغ به معنی ریاضت اسپ و ستاک (ستاغ ) به معنی کرّه یا اسپ زین ناکرده و جناغ قسمتی از ساز اسب و یراق (زین و برگ و دهنه ٔ اسب، شاید از یهروآک ) و دفنوک (بمعنی غاشیه ) و اخیه و آخور و اخته و اَکدش که همه ٔ آنها مطرداًمعنی اسب را متضمن میباشند در دو کلمه ٔ آکنده مخفف آک کنده، به معنی اصطبل و یَدَک (مرکب از یَد هزوارِش، دست + آک اسب ) این دعوی ظاهرتر است . و بعید نیست که لفظ آت آذری یا ترک نزدیک نیز صورتی از آک باشد وتبدیل «ک » به «ت » در زبانهای ما و همسایگان نظائر بسیار دارد:<br />یابن الزبیر طالما عصیکا.<br /> <font color=\"Red\">راجز.</font><br />وَتَد، وَکَد در عربی و در فارسی تارتَنک، کارتَنک، تملول، کملول، تود و توده، کوت، تملیک، تملیت، تَریوه، کریوه، پکوک، پُتک . علاوه بر آنکه در تداول کودکان همیشه و در هرجا «ت »بجای «ک » آید: تَردم، تَندی، تُشت، پات، بجای کردم، کندی، کشت، پاک و غیره و غیره . و از طرف دیگر کَتزیاس مورخ طبیب اردشیر دویم که ظاهراً مآخذ او اسناد دولتی ایران بوده است نام ضحاک را آسپاداس ضبط میکند واین صورت دیگر آژی دهاک است . چنانکه مردآس نیز اسم پدر ضحاک است و مینماید که آک و صورت دیگر آن، آس مثل نام خانوادگی این دودمان است و آس در نام مرداس پدر، همان آک در نام ده آک و یا آسپاداس پسر است، و نام کوچک پدر «مرد» و نام کوچک پسر «آژی » (مار) است . و دلیل دیگر که نشان میدهد آک در کلمه ٔ ده آک به معنی عیب نیست این است که مورخین ایرانی و یونانی و عرب آژی دهاک یا ضحاک را نام اصلی این پادشاه میدانند و متصور نیست که لقبی مذموم نام اصلی پادشاهی باشد آنهم لقبی حاکی از ده عیب (بیدادگری، بیشرمی، بدزبانی، دروغگوئی، شتابکاری و بددلی و غیره ) که البته گاه ولادت در او پیدا نبوده و نامگذاران او نمیتوانسته اند طاری شدن آن عیوب را بر او پیش بینی کرده و به مناسبت آن بدو نام دهند، علاوه بر آنکه نام زشت و قبیح دادن والدین بفرزند خاصه که فرزند شاهزاده ای باشد در نهایت غرابت است . اکنون برای روشن کردن این منظور امعان نظری در کلمه و معنی بیور و بیوراسب نیز ضرور است . کلمه ٔبیور و بیوراسب برخلاف آک در شعر و نثر ماضحاک مکرر آمده است <span class=\"hlight\">:</span> <br />نه من بیش دارم ز جمشید فرّ<br />که بُبْرید بیور میانش به اَرّ.<br /> <font color=\"Red\">فردوسی .</font><br />جهانجوی را نام ضحاک بود<br />دلیر و سبک سار و ناپاک بود<br />همان بیوراسبش همی خواندند<br />چنین نام بر پهلوی راندند.<br /> <font color=\"Red\">فردوسی .</font><br />دانی کاین قصه بود هم به گه بیوراسب <br />هم به گه بخت نصر هم به گه بوالحکم .<br /> <font color=\"Red\">منوچهری .</font><br />بیوراسب که او را ضحاک خوانند از گوشه ای درآمد و او را <font color=\"DarkGreen\"><b>[ جمشید را ]</font></b> بتاخت ... <font color=\"DarkGreen\"><b>[ و او ]</font></b> بزمین هندوستان گریخت . (نوروزنامه ). بیوراسب هزار سال پادشاهی کرد. (نوروزنامه ).<br />زمانه مملکت جم به بیوراسب ندادی <br />اگر بجرعه رسیدی ز جام دولت او جم .<br /> <font color=\"Red\">فلکی شروانی .</font><br />کتف محمد ازدرِ مُهر نبوت است <br />وآن کتف بیوراسب بود جای اژدها.<br /> <font color=\"Red\">خاقانی .</font><br />ولی آیا بیور به معنی ده هزار و بیوراسب بمعنی ده هزار اسب است جای شک و تردید است، و بلکه ظواهراستعمالات همه جا ده (عشره ) بودن ِ معنی این کلمه را نشان میدهد. فردوسی در اول داستان ضحاک میگوید <span class=\"hlight\">:</span> <br />یکی مرد بد اندر آن روزگار<br />ز دشت سواران نیزه گذار<br />گرانمایه هم شاه و هم نیکمرد<br />ز ترس جهاندار با باد سرد<br />که مرداس نام گرانمایه بود<br />بداد و دهش برترین پایه بود<br />مر او را ز دوشیدنی چارپای <br />ز هریک هزار آمدندی بجای <br />بز و اشتر و میش را همچنین <br />بدوشندگان داده بد پاکدین <br />همان گاو دوشا بفرمان بری <br />همان تازی اسبان رمنده فری <br />بشیر آن کسی را که بودی نیاز<br />بدان خواسته دست بردی فراز<br />پسر بُد مر آن پاکدین را یکی <br />کش از مهر بهره نبد اندکی <br />جهانجوی را نام ضحاک بود<br />دلیر و سبکسار و ناباک بود<br />همان بیوراسبش همی خواندند<br />چنین نام بر پهلوی راندند<br />کجا بیور از پهلوانی شمار<br />بود در زبان دری ده هزار<br />از اسبان تازی بزرین ستام <br />ورا بود بیور که بردند نام <br />شب و روز بودی دو بهره بزین <br />ز راه بزرگی نه از راه کین .<br /> <font color=\"Red\">فردوسی .</font><br />وقتی بابیات فوق بدقت به بینیم حاصل معنی این است که شیخی از شیوخ عرب یا سرشبانی از دشت سواران نیزه گذار یا دشت نیزه وران، مرداس نام هزار بز و هزار گوسفند و چند رأس اشتر و گاو داشته و شاهی و گرانمایگی او بشیرفروشی یا شیربخشی ختم و تمام میشده است و باعزت و قدری که اسب در ازمنه ٔ قدیم داشته است ده هزار اسب زرین ستام برای سواری عادی پسر آماده کرده است و این بسیار بعید است چه با اصول زندگی شبانی و بدوی که پدر همیشه مالک مطلق اموال خانواده است ده هزار اسب داشتن پسر در حیات چنین پدری کم مایه، آن هم بزرین ستام و تنها برای گردش و تفرج نه «از راه کین » نهایت غریب و با اصول افسانه سرائی هر ملت و هر زبان و حتّی قصه های زنانه که مادران ْ اطفال را گویند سازگار نیست، ولی اگر بیور به معنی ده باشد با در نظر گرفتن اندازه ٔ دارائی این پدر امر منطقی تر و بقبول خاطر نزدیکتر است و در این صورت بی تردید بیت ذیل <span class=\"hlight\">:</span> <br />کجا بیور از پهلوانی شمار<br />بود در زبان دری ده هزار<br />مصحف است . مثلاً «ده هزار» ممکن است در اصل داه بار، بوده باشد و یا کلمه ٔ هزار با لفظی مانند بکار یا همار و امار (فقط برای اینکه با دعوی فرهنگ نویسان که بیورده هزار است مطابق باشد) تبدیل شده باشد . و نام بودن ده اسب در ازمنه ٔ باستانی برای مردی مستبعد نیست چه اشت اسپا (هشت اسب ) و نظایر آن در اسامی قدیمه هست و از طرفی دیگر در همه ٔ مواردی که در کتب قدیمه بیور جزء نام یا لقبی آمده است میتوان آن را به معنی ده گرفت و این امر سبب می شود که اغراق و مبالغه های گزاف و دور از ذوق سلیم که در بعض آن اسامی یا القاب تصور شده است از میان برود. مثل بیورفرسکمیا (صاحب ده هزار حمّال ) و بیورواِدهاکا (دارای ده هزار مستحفظ) و بیورسپئسن َ (دارنده ٔ ده هزار جاسوس ) و غیره . در متنی از پهلوی یادگار زریران باز کلمه ٔ بیور آمده است و آن را پهلوی دانان برحسب عادت بده هزار ترجمه کرده اند: «اپ شان ویدرفش جادوک نام خواست پسر هزار اپاک دوبیورسپاه وژیتک به بغدسپان فرستاده او ایران شهر یاتونت و پس جاماسپ پیشینیگان سردار زود اندرون اندر از یونت اوش اووشتاب شد گفت که از جانب ارجاسپ خیونان خوتای دو فرستک آمد... یکی ویدرفش جادوک و دیگر نامخواست هزاران، پسر هزار با دوبیور سپاه وژیتک بادارند...» این دو رسول نامه ای از ارجاسب بگشتاسب آورده بوده اند که بروایت دقیقی نام یکی بیدرفش پیر جادو و نام دیگری نام خواست بوده است و این امر نیز عجیب است، چه بیست هزار رسول فرستادن یا با رسول فرستادن امری است که در هیچ عصر و در هیچ مملکت نظیر ندارد و تجاوزبیست هزار سپاهی آن هم گزیده (وَژیتک ) در هر تاریخ و در هر کشور عین جنگ واقعی و حقیقی است، خاصه که دقیقی شماره ٔ همراهان این دو رسول را سیصد میگوید <span class=\"hlight\">:</span> <br />بهمراهشان کرد سیصدسوار<br />همه جنگجویان خنجرگذار.<br />و البته دقیقی یا عین متن یادگار زریران و یا چیزی مانندآن را در دست داشته است و اگر بیور به معنی ده هزار بوده دوبیور را بیست هزار ترجمه میکرده است، در صورتی که می بینیم او هر بیور را (اگر بیت مصحف و سیصد سوار، بیستی سوار نباشد) صد و پنجاه گرفته است و از این اختلاف چنین برمی آید که از زمان قدیم معنی بیور مجهول ویا مشکوک فیه بوده است و باز در عده ای از ابیات شاهنامه (که امروز به شصت هزار نمیرسد لیکن بگفته ٔ فردوسی و بقول مشهور شصت هزار بیت بوده است ) فردوسی گوید <span class=\"hlight\">:</span> <br />کهن گشته این نامه ٔ باستان <br />ز گفتار و کردار آن راستان <br />یکی نامه ٔ نو کنم زین نشان <br />کجا یادگار است از آن سرکشان <br />بود بیت شش بار بیورهزار<br />سخنهای شایسته ٔ غمگسار<br />نبیند کسی نامه ٔ پارسی <br />نوشته بابیات صد بار سی <br />اگر بازجوئی از او بیت رد<br />همانا که کم باشد از پنج صد.<br /> <font color=\"Red\">فردوسی .</font><br />در ابیات فوق بی شبهه در شعر سوم و چهارم تصحیفی روی داده است چه اگر بیورده هزارباشد معنی بیت سوم این می شود که اشعار شاهنامه شصت هزارهزار است، حاصل ضرب شش در ده هزارهزار، و این محال است، لیکن اگر بیور را چنانکه گفتم به معنی ده بگیریم معنی بیت درست و عده ٔ ابیات شش ده هزار می شود یعنی شصت هزار. و در بیت چهارم «نوشته بابیات صد بار سی »، بی شک کلمه ٔ نوشته، مصحف دوبیور است، چه صد بار سی، سه هزار است و مراد فردوسی اگر از نامه ٔ پارسی شاهنامه ٔ خود اوست ابیات شاهنامه بیست بار سه هزار است و اگرمراد (باحتمال بعید و دور از ذوق سلیم ) مطلق نامه ٔ پارسی است و فردوسی میخواهد بگوید پیش از او در زبان پارسی حتی کتابی که مؤلَّف از سه هزار بیت باشد وجودنداشته این هم خلاف ظاهر است، چه گذشته از مثنویهای عنصری از قبیل وامق و عذرا و شادبهر و غیره و مثنویهای شعرای پیش از او، ازجمله آفرین نامه ٔ ابوشکور و سندبادنامه ٔ رودکی و امثال آن که فعلاً مفقود است و محتمل است که هر یک یا بعض آنها اقلاً سه هزار بیت باشد بی هیچ شبهه کلیله و دمنه ٔ رودکی از اضعاف سه هزار بیت تجاوز میکرده است . و اما اگر کلمه ٔ نوشته را دوبیور بخوانیم و دوبیور را به معنی دودَه ْ بگیریم یعنی بیست، وقتی بیست در حاصل صد بار سی یعنی سه هزار ضرب شودبیست سه هزار بدست می آید، یعنی شصت هزار، و این همان نصاب ابیات شاهنامه است . و این تصحیف عمدی است نه سهوو غلط کاتب، چه از آنجا که معنی بیور را ده هزار میدانسته اند و آن وقت لازم می آمده است که بیست هزار را ضرب در صد بار سی یعنی سه هزار کنند و حاصل عمل، شصت هزارهزار میشده است، دوبیور را بکلمه ٔ نوشته تبدیل کرده اندتا معنی آن باشد که قبل از شاهنامه، نامه ٔ منظومی بسه هزار بیت نیز گفته نشده است و بی خبری فردوسی را از وجود کلیله و دمنه ٔ رودکی و امثال آن طبیعی تر از دعوی شصت هزارهزار بودن ابیات شاهنامه دیده اند. در صورتی که خود فردوسی شرح نظم کردن کلیله را در شاهنامه آورده است <span class=\"hlight\">:</span> <br />گزارنده را پیش بنشاندند<br />همه نامه بر رودکی خواندند<br />بپیوست گویا پراکنده را<br />بسفت این چنین درّ آکنده را.<br /> <font color=\"Red\">فردوسی .</font><br />و باز در بیت ذیل فردوسی نیز <span class=\"hlight\">:</span> <br />بدو ماندم این نامه را یادگار<br />بشش بیور ابیاتش آمد هزار<br />کلمه ٔ بیور غیر از ده، معنی دیگر نمیتواند بدهد، زیرا چنانکه گفتیم در آن صورت نیز عده ٔ ابیات شصت هزارهزار می شود در صورتی که اگر بیور رابه معنی ده بگیریم عدد مطلوب یعنی شصت هزار به دست می آید.<br />در اسدی باز کلمه ٔ بیور در بیت ذیل آمده است <span class=\"hlight\">:</span> <br />دوباره چهل بار بیور هزار<br />گزین کرد گردان خنجرگزار.<br /> <font color=\"Red\">اسدی .</font><br />در این بیت هم اگر معنی بیور ده هزار باشد حاصل ضرب هشتاد در ده هزارهزار، هشتصدهزارهزار می شود و این عددی است که هیچ اغراق گوئی دارای عقل متعارف خاصه در تاریخ بزبان نیاورده است و مبالغه سرائی یونانیان در اینکه عدد سپاه ایران در جنگ یونان چهارهزارهزار بوده است مَثَل اعلای مبالغه ای است که تا حال در تاریخ در عده ٔ سپاه کرده اند، لیکن در همین شعر اسدی اگر بیور را به معنی ده بگیریم حاصل هشتصدهزار می شود یعنی عددی که از دایره ٔ اغراق و گزاف گوئی عادی خارج نیست . واﷲ اعلم .<br /></font></div>'),
(2845, 'آکادمی', '<span class=\"hlight\">آکادمی .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (فرانسوی، اِ) (مشتق از نام یلی اساطیری از مردم یونان موسوم به آکادمُس که اراضی منسوب بدو را آکادمی مینامیدند، در شمال غربی اَطینه «آتن »، و مَدْرَس افلاطون بدانجا بود.) اقاذیمیا. فرهنگستان . و رجوع به اقاذیمیا شود.<br /></font></div>'),
(2846, 'آکال', '<span class=\"hlight\">آکال .</span> (ع اِ) مهتران قوم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آکال الملوک </span> ؛ مآکِل پادشاهان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آکال جُند</span> ؛ ارزاق لشکر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذووالاَّکال </span> ؛ رؤسای قبائل جاهلیت که از غنیمت چهاریک (مِرْباع ) برگرفتندی .<br /></font></div>'),
(2847, 'آکام', '<span class=\"hlight\">آکام .</span> (ع اِ) ج ِ اُکُم و اُکُم ج ِ اِکام و اِکام ج ِ اَکم و اَکم ج ِ اَکمه . منظرها. زمینهای بلند. تل ها. تپه ها. پشته ها. توده ها. سنگلاخها.<br /></font></div>'),
(2848, 'آکاهولی', '<span class=\"hlight\">آکاهولی .</span> (هندی، اِ) نام داروئیست هندی، دافع پَرمیو یعنی سوزاک .<br /></font></div>'),
(2849, 'آکب', '<span class=\"hlight\">آکب .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِ) آکُپ .<br /></font></div>'),
(2850, 'آکتور', '<span class=\"hlight\">آکتور.</span> <font color=\"DarkGreen\"><b>[ تُرْ ]</font></b> (فرانسوی، ص، اِ) بازیگر. نمایشگر.<br /></font></div>'),
(2851, 'آکج', '<span class=\"hlight\">آکج .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِ) قلاب آهنین که سقایان و فقاعیان بدان یخ در یخدان افکنند. یخ گیر. <BR><font color=\"Blue\">◄</font> قلابی بزرگ آهنین بر سر چوبی کرده که بدان کشتی دشمن فراکشیدندی یا مرد از کشتی دشمن ربودندی <span class=\"hlight\">:</span> <br />بجستند تاراج و زشتیش را<br />به آکج کشیدند کشتیش را.<br /> <font color=\"Red\">عنصری .</font><br /><BR><font color=\"Blue\">◄</font> علف شیران . زعرور. تفاح البرّی . اَکَج .شاید زالزالک و کویج یا ازگیل .<br /></font></div>'),
(2852, 'آکح', '<span class=\"hlight\">آکح .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِ) جلاب را گویند و آن داروئی باشد جوشانیده و صاف کرده شده . (برهان ).خلاب باشد یعنی لای سیاه . (نسخه ٔ لغتی خطی ). و گمان میکنم این کلمه چنانکه آکَحج بمعنی جلاب (برهان ) و آکَخ نیز به معنی جلاب (برهان ) و اکحج به همین معنی و آکخج بمعنی مزبور (جهانگیری ) و صور دیگری که فرهنگ نویسان ضبط کرده اند همه مصحف کلمه ٔ آکج به معنی قلاب مخصوص باشد. و قلاب را گاهی جُلاب و گاهی خلاب خوانده اند.<br /></font></div>'),
(2853, 'آکحج', '<span class=\"hlight\">آکحج .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِ) رجوع به آکح شود.<br /></font></div>'),
(2854, 'آکخ', '<span class=\"hlight\">آکخ .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِ) رجوع به آکح شود.<br /></font></div>'),
(2855, 'آکده', '<span class=\"hlight\">آکده .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) مخفف آکنده <span class=\"hlight\">:</span> <br />بدو زلف، قاری بعنبر سرشته <br />بدو چشم زهرآکده ذوالفقاری .<br /><font color=\"Red\">قطران .</font><br /></font></div>'),
(2856, 'آکر', '<span class=\"hlight\">آکر.</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِ) آگَر. سُرین و کفل را گویند مطلقاً. (برهان ).ظاهراً این صورت مصحف آلر باشد. رجوع به آلر شود.<br /></font></div>'),
(2857, 'آکرکراهه', '<span class=\"hlight\">آکرکراهه .</span> <font color=\"DarkGreen\"><b>[ ک ِ ک ِ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (اِ) عاقرقرحا. رجوع به عاقرقرحا و آککرا شود.<br /></font></div>'),
(2858, 'آکس', '<span class=\"hlight\">آکس .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِ) قلمی آهنین سنگ تراشان را.<br /></font></div>'),
(2859, 'آکسه', '<span class=\"hlight\">آکسه .</span> <font color=\"DarkGreen\"><b>[ ک َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (ص ) درزده . درآویخته . بندشده . آویزان <span class=\"hlight\">:</span> <br />هیچ اهل هوا و بدعت را<br />چنگ در دامن تو آکسه نیست <br />دی بسی کس ز شاه مدرسه رفت <br />ظاهر است این نهان و بر کسه نیست .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(2860, 'آکشانیدن', '<span class=\"hlight\">آکشانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) در حاشیه ٔ فرهنگ اسدی (خطی ) که در <span class=\"hlight\" dir=\"rtl\">٧٦٦</span> هَ .ق . کتابت شده بنام قریح <font color=\"DarkGreen\"><b>[ شاید: قریعالدهر ]</font></b> این بیت ضبط شده است (و این حاشیه ٔ ظاهراً تحفةالاحباب حافظ اوبهی است ) <span class=\"hlight\">:</span> <br />عبدای توام مریز مر عبدا را<br />زهمای توام میاکشان زهما را.<br />و بیت شاهد لغت زهما به معنی عاشق آمده است و کلمه ٔ میاکشان ظاهراً نهی از مصدرآکشاندن یا آکشانیدن است لکن معنی آن روشن نیست . شاید به معنی رنجانیدن و تعب دادن و امثال آن باشد.<br /></font></div>'),
(2861, 'آکفت', '<span class=\"hlight\">آکفت .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ <span class=\"hlight\" dir=\"rtl\">/</span> ک ُ ]</font></b> (اِ) رجوع به آگفت شود.<br /></font></div>'),
(2862, 'آکل', '<span class=\"hlight\">آکل .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ع ص، اِ) خورنده . ج، آکلین <span class=\"hlight\">:</span> <br />زآنکه تو هم لقمه ای هم لقمه خوار<br />آکل و مأکولی ای جان هوش دار.<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">دنیا آکل و مأکول است </span> .<br /><BR><font color=\"Blue\">◄</font> مَلِک . سلطان . پادشاه .<br /></font></div>'),
(2863, 'آکل المرار', '<span class=\"hlight\">آکل المرار.</span> <font color=\"DarkGreen\"><b>[ ک ِ لُل ْ م ُ ]</font></b> (اِخ ) لقب حارث بن عمروبن حجر الکندی، هیجدهمین از ملوک مَعد، جدّ امروءالقیس شاعر معروف .<br /></font></div>'),
(2864, 'آکل نفسه', '<span class=\"hlight\">آکل نفسه .</span> <font color=\"DarkGreen\"><b>[ ک ِ ل ُ ن َ س ِه ْ ]</font></b> (ع اِ مرکب ) فرفیون . فربیون . افربیون . انفسه . حافظالنحل . حافظالاطفال . تاکوب . لبن سوداء. <BR><font color=\"Blue\">◄</font> کافور. <BR><font color=\"Blue\">◄</font> نفت .<br /></font></div>'),
(2865, 'آکلات', '<span class=\"hlight\">آکلات .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ع ص، اِ) ج ِ آکِله . خورندگان (زنان ) .<br /></font></div>'),
(2866, 'آکله', '<span class=\"hlight\">آکله .</span> <font color=\"DarkGreen\"><b>[ ک ُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) آکوله . بهترین جنسی از اجناس برنج . اجود انواع برنج .<br /></font></div>'),
(2867, 'آکله', '<span class=\"hlight\">آکله .</span> <font color=\"DarkGreen\"><b>[ ک ِ ل َ ]</font></b> (ع ص، اِ) تأنیث آکِل . خورنده (زن ). <BR><font color=\"Blue\">◄</font> هر قرحه که گوشت را خورد. <BR><font color=\"Blue\">◄</font> خوره . خوره باد. (ربنجنی ). <BR><font color=\"Blue\">◄</font> قسمی ریش که بر اندام افتد و گوشت را خورد. و این غیر ارمنی دانه است . جذام . و قسمی از آن آکله ٔ دهان است که تنها در دهان پیدا شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">مال یتیم آکله است </span> ؛ یعنی چون کسی آن را در مال خود درآمیزد همه ٔ مال تباه شود.<br /><BR><font color=\"Blue\">◄</font> ماشیه ٔ چرنده .<br /></font></div>'),
(2868, 'آکلین', '<span class=\"hlight\">آکلین .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ع ص، اِ) ج ِ آکل .<br /></font></div>'),
(2869, 'آکم', '<span class=\"hlight\">آکم .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (ع اِ) ج ِ اَکم و اَکم ج ِ اَکَمَه است .<br /></font></div>'),
(2870, 'آکن', '<span class=\"hlight\">آکن .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (نف مرخم ) مخفف آکننده، و از آن کلماتی مرکب توان کرد، چون پشم آکن، قزاکن، جوزآکن، سحرآکن ؛ آنکه پشم، قز، جوز، و سحر آکند.<br /></font></div>'),
(2871, 'آکنان', '<span class=\"hlight\">آکنان .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (نف، ق ) در حال آکندن .<br /></font></div>'),
(2872, 'آکنج', '<span class=\"hlight\">آکنج .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِ) قلابی که بدان یخ در یخدان اندازند. (برهان ). و ظاهراً این کلمه مصحف آکج است .<br /></font></div>'),
(2873, 'آکند', '<span class=\"hlight\">آکند.</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (ن مف مرخم ) مخفف آکنده، در کلمات مرکبه چون پشم آکند، جوزآکند، قزآکند، کژآکند، سحرآکند، سیم آکند <span class=\"hlight\">:</span> <br />نشان پشت من است آن دو زلف مشک آگین <br />نشان جان من است آن دو چشم سحرآکند.<br /> <font color=\"Red\">رودکی .</font><br />هزاران گوی سیم آکند گردان <br />که افکند اندر این میدان اخضر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />در قزآکند مرد باید بود<br />بر مخنث سلاح جنگ چه سود؟<br /> <font color=\"Red\">سعدی .</font><br />و کاف در این کلمه گاه به «غ » و گاه به «ق » بدل شده است : کژآغند. جوزقند.<br /></font></div>'),
(2874, 'آکندن', '<span class=\"hlight\">آکندن .</span> <font color=\"DarkGreen\"><b>[ک َ دَ ]</font></b> (مص ) پر کردن . انباشتن . امتلاء <span class=\"hlight\">:</span> <br />نشان پشت من است آن دو زلف مشک آگین <br />نشان جان من است آن دو چشم سحرآکند.<br /> <font color=\"Red\">رودکی .</font><br />بیفکنی خورش پاک را ز بی اصلی <br />بیاکنی به پلیدی چو ماکیان تو کژار.<br /> <font color=\"Red\">بهرامی .</font><br />وگر ببلخ زمانی شکار چال کند<br />بیاکند همه وادیش را به بط وبچال .<br /> <font color=\"Red\">عماره .</font><br />نخستین صد و شصت پیدا و سی <br />که پیداوسی خواندش پارسی <br />بگوهر بیاکند هر یک چو سنگ <br />نهادند بر هر یکی مهر تنگ .<br /> <font color=\"Red\">فردوسی .</font><br />دگر گنج کش خواندندی عروس <br />کش آکند کاوس در شهر طوس .<br /> <font color=\"Red\">فردوسی .</font><br />نکوشم به آکندن گنج من <br />نخواهم پراکندن انجمن .<br /> <font color=\"Red\">فردوسی .</font><br />گهی گنج را روز آکندن است <br />بسختی ّو روزی پراکندن است .<br /> <font color=\"Red\">فردوسی .</font><br />جهاندار شاه است و ما بنده ایم <br />دل و جان بمهر وی آکنده ایم .<br /><font color=\"Red\">فردوسی .</font><br />کنون من دل و مغز تا زنده ام <br />بکین سیاووش آکنده ام .<br /> <font color=\"Red\">فردوسی .</font><br />فرانک بدش نام و فرخنده بود<br />بمهر فریدون دل آکنده بود.<br /> <font color=\"Red\">فردوسی .</font><br />بجائی که زهر آکندروزگار<br />از او نوش خیره مکن خواستار.<br /> <font color=\"Red\">فردوسی .</font><br />بگریم بر این ننگ تا زنده ام <br />بمغز اندرون آتش آکنده ام .<br /> <font color=\"Red\">فردوسی .</font><br />همی گشت یک چند بر سر سپهر<br />دل زال آکنده یکسر بمهر.<br /> <font color=\"Red\">فردوسی .</font><br />من او را بسان یکی بنده ام <br />بمهرش روان و دل آکنده ام .<br /> <font color=\"Red\">فردوسی .</font><br />بگفتند با شاه ما بنده ایم <br />تن و جان بمهر تو آکنده ایم .<br /> <font color=\"Red\">فردوسی .</font><br />ز بس خواسته کش پراکنده بود<br />ز گنج و درم کشور آکنده بود.<br /> <font color=\"Red\">فردوسی .</font><br />مهان تاج و تخت مرا بنده اند<br />دل و جان بمهر من آکنده اند.<br /> <font color=\"Red\">فردوسی .</font><br />جهان چون بهشتی شد آراسته <br />پر از داد و آکنده از خواسته .<br /> <font color=\"Red\">فردوسی .</font><br />که گفت ِ پراکنده بِپْراکَنَد<br />چو پیوسته شد مغز جان آکَنَد.<br /> <font color=\"Red\">فردوسی .</font><br />تو خوانیش کایدر مرا بنده باش <br />بخواری ّو زاری تن آکنده باش .<br /> <font color=\"Red\">فردوسی .</font><br />که ما شهریارا همه بنده ایم <br />دل و دیده از مهرت آکنده ایم .<br /> <font color=\"Red\">فردوسی .</font><br />به پیش پدر شه گشاده زبان <br />دل آکنده از کین کمر بر میان .<br /> <font color=\"Red\">فردوسی .</font><br />ز خون کرد باید تهیگاه خشک <br />بدو اندر آکند کافور و مشک .<br /> <font color=\"Red\">فردوسی .</font><br />دهانش پر از گوهر شاهوار<br />بیاکند و دینار چون صدهزار.<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت زنگه که ما بنده ایم <br />بمهر سپهبد دل آکنده ایم .<br /> <font color=\"Red\">فردوسی .</font><br />کنون شهر توران تو را بنده اند<br />همه دل بمهر تو آکنده اند.<br /> <font color=\"Red\">فردوسی .</font><br />بخوانم سپاه پراکنده را<br />برافشانم این گنج آکنده را.<br /> <font color=\"Red\">فردوسی .</font><br />سرانجام گفتند کاین کی بود<br />بجامی که زهر آکنی می بود.<br /> <font color=\"Red\">فردوسی .</font><br />شاد ببلخ آی و خسروآئین بنشین <br />همچو پدر گنجهای خویش بیاکن .<br /> <font color=\"Red\">فرخی .</font><br />بر سَرْش یکی غالیه دانی بگشاده <br />وآکنده درآن غالیه دان سونش دینار.<br /> <font color=\"Red\">منوچهری .</font><br />نواحی تخارستان و بلخ ... بمردم آکنده باید کرد که هر کجا خالی یافت و فرصت دید <font color=\"DarkGreen\"><b>[ علی تکین ]</font></b> غارت کند و فروگیرد. (تاریخ بیهقی ).<br />به آکندن گنج نَکْنَد ستم <br />نخواهد که خسبد از او کس دژم .<br /> <font color=\"Red\">اسدی .</font><br />بنیکوئی آکن چو گنج آکنی <br />بدانش پراکن چو بپْراکنی <br />از آن کش خرد با روان بود جفت <br />کسی باددستی ز رادی نگفت .<br /> <font color=\"Red\">اسدی .</font><br />زمین را دل از تاختن گشت چاک <br />بیاکند کام نهنگان بخاک .<br /> <font color=\"Red\">اسدی .</font><br />در بزم همه لفظ تو آکنده بدانش <br />در رزم همه قول تو النار ولا العار.<br /> <font color=\"Red\">قطران .</font><br />بندیش که بر چسان بحکمت <br />این خوب قصیده را بیاکند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />توشه ٔ تو علم و طاعتست در این راه <br />سفره ٔ دل را بدین دو توشه بیاکن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />خری آموختت آنکس که همی گفتت <br />که همیشه شکم و معده همی آکن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />هرکه بهی ّ تو نخواهد چو نار<br />سینه اش از خون دل آکنده باد.<br /> <font color=\"Red\">کمال اسماعیل .</font><br />در لحد کاین چشم را خاک آکند<br />هست آنچه گور را روشن کند.<br /> <font color=\"Red\">مولوی .</font><br />کاین دو دایه پوست را افزون کنند<br />شحم و لحم و کبر و شهوت آکنند.<br /> <font color=\"Red\">مولوی .</font><br />کسی که لطف کند بر تو خاک پایش باش <br />وگر ستیزه کند بر دو چشمش آکن خاک .<br /> <font color=\"Red\">سعدی .</font><br />بهمیان تا بکی آکندن زر<br />بنقد علم کن دل را منور.<br /> <font color=\"Red\">عزالدین شیروانی .</font><br />سائل بسوءالی از در تو<br />صد گنج ز زرّ و سیم آکند.<br /> <font color=\"Red\">عزالدین شیروانی .</font><br /> <BR><font color=\"Blue\">◄</font> دفن کردن . دفین کردن . زیر خاک نهان کردن . به خاک سپردن <span class=\"hlight\">:</span> <br />به نیروی دارنده یزدان پاک <br />بیاکندمی در زمانش بخاک .<br /> <font color=\"Red\">فردوسی .</font><br />مر او را فراوان نمودند گنج <br />کجا بابک آکنده بود آن به رنج <br />درمهای آکنده را برفشاند<br />به نیرو شد از پارس لشکر براند.<br /> <font color=\"Red\">فردوسی .</font><br />بکوه اندر آکند چیزی که بود<br />ز دینار و از گوهر نابسود<br />چو درکوه شد گنجها ناپدید<br />کسی چهر آکنده ها را ندید.<br /> <font color=\"Red\">فردوسی .</font><br />چه داری چشم ازو چون این و آن را<br />به پیش تو بدین خاک اندر آکند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و رجوع به آکنیدن و آکنده شود.<br /> <BR><font color=\"Blue\">◄</font> آکنه و آکنش، حشو درنهادن . حشو. احتشاء. اعتباء <span class=\"hlight\">:</span> <br />هم اندر زمان آنکه فریاد ازوست <br />پر از کاه بینیدش آکنده پوست .<br /> <font color=\"Red\">فردوسی .</font><br />تو گوئی به سنگستم آکنده پوست <br />و یا زآهن است آنکه بوده دروست .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> پوشیدن سطح چیزی بچیزی <span class=\"hlight\">:</span> <br />نخستین بفرمود بیجاده تاج <br />بگوهر بیاکنده و تخت عاج <br />ز سیمین و زرّینه اشتر هزار<br />بفرمود تا برنهادند بار.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نهادن (؟). نهان کردن (؟) <span class=\"hlight\">:</span> <br />بخایه نمک درپراکند زود<br />بحقه درآکند مانند دود.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> غنی و آبادان کردن <span class=\"hlight\">:</span> <br />بیاکند گنج و سپاه ورا<br />بیاراست ایوان و گاه ورا.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آکندن پهلو</span> ؛ فربه شدن <span class=\"hlight\">:</span> <br />چریده دیولاخ آکنده پهلو<br />به تن فربی میان چون موی لاغر .<br /> <font color=\"Red\">عنصری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آکندن یال </span> ؛ قوی شدن . بزرگ شدن <span class=\"hlight\">:</span> <br />همی داشتندش چنین چار سال <br />چو شد سیر شیر و برآکند یال <font color=\"DarkGreen\"><b>[ بهرام گور ]</font></b><br />بدشواری از شیر کردند باز<br />همی داشتندش ببر بر بناز.<br /> <font color=\"Red\">فردوسی .</font><br />پسر بد مر اورا <font color=\"DarkGreen\"><b>[ کیومرث را ]</font></b> یکی خوبروی <br />هنرمند و همچون پدر نامجوی ...<br />بگیتی نبد هیچکس دشمنش <br />مگر در نهان ریمن آهرمنش <br />برشک اندر آهرمن بدسگال <br />همی رای زد تا برآکند یال .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">درآکندن مغز</span> ؛ پر و سخت شدن آن . اکتناز <span class=\"hlight\">:</span> <br />زآنکه چون مغزش درآکند و رسید<br />پوستها شد بس رقیق و واکفید.<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ریش بفلفل آکندن </span> ؛ بجای تسلیه یا تسکین، تیزتر کردن غم یا درد و یا خشم .<br />و مشتقات آن همه از این یک مصدر باشد منتظم .<br /></font></div>'),
(2875, 'آکندنی', '<span class=\"hlight\">آکندنی .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (ص لیاقت، اِ) آگندنی . آکَنه . آکَنش . حَشو <span class=\"hlight\">:</span> <br />ز پوشیدنی هم ز افکندنی <br />ز گستردنی هم ز آکندنی .<br /> <font color=\"Red\">فردوسی .</font><br />ز پوشیدنی هم ز آکندنی <br />ز هر سو بیاورد آوردنی .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2876, 'آکنده', '<span class=\"hlight\">آکنده .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ) جایگاه ستور. آخور. آخُر. اصطبل . پاگاه . پایگاه . طویله <span class=\"hlight\">:</span> <br />روز به آکنده شدم یافتم <br />آخُرچون پاتله ٔ سفلگان .<br /> <font color=\"Red\">ابوالعباس .</font><br />چراگاه اسبان شود کوه و دشت <br />به آکنده زآن پس نباید گذشت .<br /> <font color=\"Red\">فردوسی (از اسدی ).</font><br />همه چارپایان بکردار گور<br />بر آکنده آکنده گردن بزور<br />بگردن بکردار شیران نر<br />بسان گوزنان بگوش و بسر.<br /> <font color=\"Red\">فردوسی .</font><br />لؤلؤافشان کند دو جزع مرا<br />عشق آن لعل لؤلؤآکنده <br />وآن دگر کندگان در آن حجره <br />بر سکیزان چو خر در آکنده .<br /> <font color=\"Red\">سوزنی .</font><br />خوه سر خر باش یا تو خواه سُم خر<br />خواه به آکنده باش و خواه بصحرا.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(2877, 'آکنده', '<span class=\"hlight\">آکنده .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) پُر. انباشته . مملو. ممتلی . مکتنز. مشحون . مُختزَن <span class=\"hlight\">:</span> <br />بایوان یکی گنج بودش <font color=\"DarkGreen\"><b>[ فرنگیس را ]</font></b> نهان <br />نبد زآن کسی آگه اندر جهان <br />یکی گنج آکنده دینار بود<br />گهر بود و یاقوت بسیار بود.<br /> <font color=\"Red\">فردوسی .</font><br />بفرمای تا اسب و زین آورند<br />کمان و کمند گزین آورند<br />همان نیزه و خودو خفتان جنگ <br />یکی ترکش آکنده تیر خدنگ .<br /> <font color=\"Red\">فردوسی .</font><br />یکی بدره آکنده او را دهند<br />سپاسی بشاه جهان برنهند.<br /> <font color=\"Red\">فردوسی .</font><br />ز هر گونه ای گنج آکنده دید<br />جهان سربسر پیش خود بنده دید.<br /> <font color=\"Red\">فردوسی .</font><br />ز گنج تو آکنده تر گنج اوی <br />بباید گسست از جهان رنج اوی .<br /> <font color=\"Red\">فردوسی .</font><br />همه سربسر مر ترا بنده ایم <br />همه دل بمهر تو آکنده ایم .<br /> <font color=\"Red\">فردوسی .</font><br />چنان خیره شد اندر آن چهر اوی <br />که شد دلْش آکنده از مهر اوی .<br /> <font color=\"Red\">فردوسی .</font><br />از این پس ترا هرچه آید به کار<br />ز دینار و از گوهر شاهوار<br />فرستم، نگردل نداری به رنج <br />نه ارزد به رنج تو آکنده گنج .<br /> <font color=\"Red\">فردوسی .</font><br />بهر کشوری گنج آکنده هست <br />که کس را نباید شدن دوردست <br />چو باید بخواهید و خرم زیید<br />خردمند باشید وبی غم زیید.<br /> <font color=\"Red\">فردوسی .</font><br />همان چرمش آکنده باید بکاه <br />بدان تا نجوید کس این پایگاه .<br /> <font color=\"Red\">فردوسی .</font><br />نهفته مرا گنج آکنده هست <br />همان نامداران خسروپرست .<br /> <font color=\"Red\">فردوسی .</font><br />زمین پر ز آکنده دینار اوست <br />که نه مغز بادش به تن در، نه پوست .<br /> <font color=\"Red\">فردوسی .</font><br />غم عیال نبود و غم تبار نبود<br />دلم برامش آکنده بود چون چغبوت .<br /> <font color=\"Red\">طیان .</font><br />نارنج چو دو کفّه ٔ سیمین ترازو<br />هر دو ز زر سرخ طلی کرده برونسو<br />آکنده بکافور و گلاب خوش و لؤلو...<br /> <font color=\"Red\">منوچهری .</font><br />بسا شاهان با ملک و سپاه و گنج آکنده <br />که شان بِربْودی از گاه و بدین چاه اندر افکندی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />سائل و زائر ز کف ّ راد تو در روز بزم <br />بدره ها گیرند آکنده بزرّ جعفری .<br /> <font color=\"Red\">سوزنی .</font><br />نامه ای آید به دست بنده ای <br />سر سیه از جرم و فسق آکنده ای .<br /> <font color=\"Red\">مولوی .</font><br />زآنکه زآن بستان جانها زنده است <br />زآن جواهر بحر دل آکنده است .<br /> <font color=\"Red\">مولوی .</font><br />شکم تا سر آکنده از لقمه تنگ <br />چو زنبیل دریوزه هفتادرنگ .<br /> <font color=\"Red\">سعدی .</font><br />لیک هر آن مزبله کآکنده تر<br />هرچه بشویند شود گنده تر.<br /> <font color=\"Red\">امیرخسرو.</font><br />در کلمات مرکبه ٔ زرآکنده و سیم آکنده و قزآکنده به معنی به زر و سیم آکنده و آکنیده است .<br /> <BR><font color=\"Blue\">◄</font> نهان . پنهان . پنهان کرده . نهان کرده . نهفته . پوشیده .مخفی . مختفی . مستور <span class=\"hlight\">:</span> <br />خرد جوید آکنده راز جهان <br />که چشم سر مانبیند نهان .<br /> <font color=\"Red\">فردوسی .</font><br />سخن هیچ مَسْرای با رازدار<br />که او را بود نیز همساز و یار<br />سخن را تو آکنده دانی همی <br />به گیتی پراکنده خوانی (کذا) همی .<br /> <font color=\"Red\">فردوسی .</font><br /> <br />چو آن خوب رخ سیب اندرگزید<br />یکی در میان ْ کرم آکنده دید.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> نگارکرده . مُلوّن . مُنقش . برنگ کرده . مزین <span class=\"hlight\">:</span> <br />همی گفت و لبهاپر از خنده داشت <br />رخان همچو گلنار آکنده داشت .<br /> <font color=\"Red\">فردوسی .</font><br />همه عالم ز فتوح تو نگاری گشته ست <br />همچو آکنده بصد رنگ نگارین سیرنگ .<br /> <font color=\"Red\">فرخی .</font><br />خاکی که مرده بود و شده ریزان <br />آکنده چون شد و ز چه گلگون است ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> مدفون . دفین . در خاک فروبرده <span class=\"hlight\">:</span> <br />بدرگاه کسری یکی باغ بود<br />که دیوار او برتر از راغ بود<br />همه گرد بر گرد آن کنده کرد<br />مر آن مردمان را بر، آکنده کرد<br />بکشتندشان هم بسان درخت <br />زبَر پای و سر زیر آکنده سخت <br />بمزدک چنین گفت کسری که رو<br />بدرگاه باغ گرانمایه شو.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> رُست . مصمت . توپُر. میان پُر. ناسفته . مغزدار <span class=\"hlight\">:</span> <br />بپیوست گویا، پراکنده را<br />بسفت این چنین درّ آکنده را.<br /> <font color=\"Red\">فردوسی .</font><br />زره بود و دیبای پرمایه بود<br />ز زر کرده آکنده صد خایه بود.<br /> <font color=\"Red\">فردوسی .</font><br />و تخمهای انفاس تو چون گندم کوهی آکنده باشد. (کتاب المعارف ). <BR><font color=\"Blue\">◄</font> قوی فربه . سخت فربی . با گوشتی سخت پیچیده <span class=\"hlight\">:</span> <br />خورش آن بود سال تا سالشان <br />که آکنده گردد بر و یالشان .<br /> <font color=\"Red\">فردوسی .</font><br />تو چنین فربه و آکنده چرائی ؟ پدرت، <br />هندوی بود یکی لاغر و خشکانج و نحیف .<br /> <font color=\"Red\">لبیبی .</font><br />شد آکنده بلورین بازوانش <br />چو یازنده کمند گیسوانش .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />دراز و گرد و آکنده دو بازو<br />درخت دلربائی گشته هر دو.<br /> <font color=\"Red\">(ویس و رامین ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دل آکنده شدن </span> ؛ از راه بشدن (؟). قوی گشتن (؟) <span class=\"hlight\">:</span> <br />دل آکنده گردد جوان را بچیز<br />نه اندیشد از شاه و موبد بنیز.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2878, 'آکنده شدن', '<span class=\"hlight\">آکنده شدن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ<span class=\"hlight\" dir=\"rtl\">/</span> دِ ش ُ دَ ]</font></b> (مص مرکب ) ارتکاح ؛ آکنده شدن استخوان بمغز و تن بگوشت و خوشه بدانه و مانند آن . اکتناز.<br /></font></div>'),
(2879, 'آکنده پهلو', '<span class=\"hlight\">آکنده پهلو.</span> <font color=\"DarkGreen\"><b>[ ک َ دَ<span class=\"hlight\" dir=\"rtl\">/</span> دِ پ َ ]</font></b> (ص مرکب ) چرب پهلو. سخت فربه <span class=\"hlight\">:</span> <br />چرنده ٔ دیولاخ آکنده پهلو<br />تنی فربه میان چون موی لاغر.<br /><font color=\"Red\">عنصری .</font><br /></font></div>'),
(2880, 'آکنده کردن', '<span class=\"hlight\">آکنده کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ک َ دَ ]</font></b> (مص مرکب ) تصمید.<br /></font></div>'),
(2881, 'آکنده گردن', '<span class=\"hlight\">آکنده گردن .</span> <font color=\"DarkGreen\"><b>[ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ گ َ دَ ]</font></b> (ص مرکب ) ستبرگردن <span class=\"hlight\">:</span> <br />همه چارپایان بکردار گور<br />بر آکنده، آکنده گردن، بزور<br />بگردن بکردار شیران نر<br />بسان گوزنان بگوش و بسر.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2882, 'آکنده گوش', '<span class=\"hlight\">آکنده گوش .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب ) اصم ّ. کر. مجازاً، اندرزناپذیر. که پند ننیوشد <span class=\"hlight\">:</span> <br />فراوان سخن باشد آکنده گوش <br />نصیحت نگیرد مگر در خموش .<br /> <font color=\"Red\">سعدی .</font><br />پریشیده عقل و پراکنده هوش <br />ز قول نصیحتگر آکنده گوش .<br /> <font color=\"Red\">سعدی .</font><br />بفریادتا برنداری خروش <br />سخن نشنود مرد آکنده گوش .<br /><font color=\"Red\">؟</font><br /></font></div>'),
(2883, 'آکنده گوشت', '<span class=\"hlight\">آکنده گوشت .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب )فربه . فربی . سمین . با گوشتی پیچیده . پرگوشت . با گوشتی سخت : کِناز؛ شتر آکنده گوشت . (السامی فی الاسامی ).<br /></font></div>'),
(2884, 'آکنده یال', '<span class=\"hlight\">آکنده یال .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب ) فربی . فربه . قوی . رجوع به آکندن شود.<br /></font></div>'),
(2885, 'آکندگی', '<span class=\"hlight\">آکندگی .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) پُری . انباشتگی . امتلاء معده . رودِل . <BR><font color=\"Blue\">◄</font> جمعیت، مقابل پراکندگی و تفرقه <span class=\"hlight\">:</span> روزگار چندان جمعیت و آکندگی را بتفرقه و پراکندگی رسانید. (تاریخ طبرستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آکندگی بازو یا ران و جز آن </span> ؛ گوشتناکی او.<br /></font></div>'),
(2886, 'آکنش', '<span class=\"hlight\">آکنش .</span> <font color=\"DarkGreen\"><b>[ ک َ ن ِ ]</font></b> (اِمص ) اسم مصدر و عمل آکندن . <BR><font color=\"Blue\">◄</font> (اِ) آکنه . حشو <span class=\"hlight\">:</span> <br />چون راست بود خوب نماید سخن <br />در خوب جامه خوب شود آکنش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آن طبع را که علم و سخاوت شعار نیست <br />از عالمیش فخر و ز زفتیش عار نیست <br />جز چشم زخم امت و تعویذ بخل نیست <br />جز رد چرخ و آکنش روزگار نیست .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(2887, 'آکنش گر', '<span class=\"hlight\">آکنش گر.</span> <font color=\"DarkGreen\"><b>[ ک َ ن ِ گ َ ]</font></b> (ص مرکب ) آنکه شغلش آکندن جامه به آکنه و حشو است . محشّی .<br /></font></div>'),
(2888, 'آکننده', '<span class=\"hlight\">آکننده .</span> <font color=\"DarkGreen\"><b>[ ک َ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آنکه آکند <span class=\"hlight\">:</span> <br />چو در کوه شد گنجها ناپدید<br />کسی چهره ٔ آکننده ندید.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2889, 'آکنه', '<span class=\"hlight\">آکنه .</span> <font color=\"DarkGreen\"><b>[ ک َن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) آنچه از پشم و پنبه و لاس و پر و جز آن میان ابره و آستر قبا و لحاف و نهالین و مانند آن آکنند. حَشو. چغبت . چغبوت . آکین . آگین <span class=\"hlight\">:</span> <br />شدزمستان و ز جودت بنه ای میخواهم <br />ابره و آستر و آکنه ای میخواهم .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(2890, 'آکنیدن', '<span class=\"hlight\">آکنیدن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص ) آکندن . پرکردن . انباشتن . <BR><font color=\"Blue\">◄</font> جای دادن <span class=\"hlight\">:</span> <br />آنکه اندر جهان ندارد گُنج <br />چون توان آکنیدنش در کُنج ؟<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> به خاک سپردن . دفن کردن . زیر خاک کردن . دفین کردن <span class=\"hlight\">:</span> <br />مرا مرده درخاک مصر آکنید<br />ز گفتار من هیچ مپْراکنید.<br /> <font color=\"Red\">فردوسی .</font><br />تا نگردد بصدْمه ای بدو نیم <br />در زمین آکنیده اند ز بیم .<br /> <font color=\"Red\">نظامی .</font><br />آکنیده خمی سفال، در او<br />آبی الحق خوش و زلال در او.<br /> <font color=\"Red\">نظامی .</font><br />و مشتقات آن تنها از همین یک مصدر آید منتظم .<br /></font></div>'),
(2891, 'آکنیده', '<span class=\"hlight\">آکنیده .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آکنده <span class=\"hlight\">:</span> <br />منم در کشور عشقت خنیده <br />دلی از مهر رویت آکنیده .<br /><font color=\"Red\">شاکر بخاری .</font><br /></font></div>'),
(2892, 'آکو', '<span class=\"hlight\">آکو.</span> (اِ) بوم . جغد.<br /></font></div>'),
(2893, 'آکوج', '<span class=\"hlight\">آکوج .</span> (اِ) میوه ٔ صحرائی . <BR><font color=\"Blue\">◄</font> قلاب . برای هر دو معنی، رجوع به آکج شود.<br /></font></div>'),
(2894, 'آکوله', '<span class=\"hlight\">آکوله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) آکُله . نوعی برنج و آن اجود اقسام برنج باشد.<br /></font></div>'),
(2895, 'آکپ', '<span class=\"hlight\">آکپ .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِ) آکُب . لُپ . لنبوس . یک جانب دهان از درونسو <span class=\"hlight\">:</span> <br />کند از خست، او همی پنهان <br />همچو میمون نخود در آکپ خویش .<br /><font color=\"Red\">خسروانی .</font><br /></font></div>'),
(2896, 'آککرا', '<span class=\"hlight\">آککرا.</span> <font color=\"DarkGreen\"><b>[ ک ِک ْ ]</font></b> (اِ) عاقرقرحا. عقار کوهان . فوریون . عقر کوهن . تاغندست . قدم اسکندر. کژترخون . کج طرخون . کلیکان . طرخون رومی . رجوع به عاقرقرحا شود.<br /></font></div>'),
(2897, 'آکیش', '<span class=\"hlight\">آکیش .</span> کیش . گویند آهنج بود یعنی باز کردن و هنج نیز گویند (کذا). (فرهنگ اسدی، خطی ) <span class=\"hlight\">:</span> <br />توشه ٔ خویش زود از او بربای <br />پیش کآیدْت مرگ پای آکیش .<br /> <font color=\"Red\">رودکی (از فرهنگ اسدی، خطی ).</font><br />چنگ در چیزی زده . درازکرده . (برهان ). و رجوع به آگیشیدن شود.<br /></font></div>'),
(2898, 'آکیشیدن', '<span class=\"hlight\">آکیشیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آکیش ...درآویخته باشد، چه اندرآکیشیدیعنی اندرآویخت . (برهان ). و رجوع به آگیشیدن شود.<br /></font></div>'),
(2899, 'آکین', '<span class=\"hlight\">آکین .</span> (اِ) آکنه . حشو <span class=\"hlight\">:</span> <br />بهر آکین چاربالش اوست <br />هر پری کاین کبوتر افشانده ست .<br /> <font color=\"Red\">خاقانی .</font><br />و رجوع به آگین شود.<br /></font></div>'),
(2900, 'آگ', '<span class=\"hlight\">آگ .</span> (هندی، اِ) نام درختی بهند که شیره ٔ آن زهر قاتل است . (برهان ). <BR><font color=\"Blue\">◄</font> گندم . <BR><font color=\"Blue\">◄</font> درخت عُشر. و رجوع به آک شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(2901, 'آگاه', '<span class=\"hlight\">آگاه .</span> (ص ) آگه . مطلع. باخبر. مخبر. خبردار. مستحضر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگاه بودن </span> ؛ خبر داشتن . آگاهی داشتن <span class=\"hlight\">:</span> <br />ز کوه سپند و ز پیل ژیان <br />گمانم که آگاه بد پهلوان .<br /> <font color=\"Red\">فردوسی .</font><br />گرازان گرازان نه آگاه از این <br />که بیژن نهاده ست بر بور زین .<br /> <font color=\"Red\">فردوسی .</font><br />بجائی که لشکرگه شاه بود<br />که گستهم از آن لشکر آگاه بود<br />همی بر سرانْشان فرود آمدی <br />سپه را یکایک بهم برزدی .<br /> <font color=\"Red\">فردوسی .</font><br />چنین داد پاسخ که این راه نیست <br />کزین یافتن بیژن آگاه نیست .<br /> <font color=\"Red\">فردوسی .</font><br />کیومرث زین خود کی آگاه بود<br />که او را بدرگاه بدخواه بود.<br /> <font color=\"Red\">فردوسی .</font><br />فرانک نه آگاه بد زین نهان <br />که فرزند او شاه شد در جهان .<br /> <font color=\"Red\">فردوسی .</font><br />چو هنگام برگشتن شاه <font color=\"DarkGreen\"><b>[ ایرج ]</font></b> بود<br />پدر زآن سخن خود کی آگاه بود؟<br /> <font color=\"Red\">فردوسی .</font><br />آگاه نیستید که دین علم و طاعت است <br />ای مردمان چه بود که علم از شما شده ست ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />ور نیستی آگاه از این بجویش <br />زیرا که کنون بر سر دوراهی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چندین غم تو خوردم و ناز تو کشیدم <br />از عشق من و ناز خود آگاه نه ای نوز.<br /> <font color=\"Red\">سوزنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگاه شدن </span> ؛ خبر و آگاهی یافتن <span class=\"hlight\">:</span> <br />چو آگاه شد زآن سخن مادرش <br />به خاک اندر آمد سر و افسرش .<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاه شد زآن سخن هفت واد<br />از ایشان بدل برنیامدْش یاد.<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاه شد زآن سخن شهریار<br />همی داشت آن کار دشوار خوار.<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاه شد زآن سخن یزدگرد<br />ز هر سو سپاه اندرآورد گرد.<br /> <font color=\"Red\">فردوسی .</font><br />در عمر تنم بخوشدلی زیست <br />آگاه نشد که عاشقی چیست .<br /> <font color=\"Red\">امیر حسینی سادات .</font><br />بونصر دبیر خویش را نزدیک من ... فرستاد... که دستوری یافتم برفتن سوی خوارزم و فردا شب که آگاه شوند ما رفته باشیم . (تاریخ بیهقی ). چون نامه بعبداﷲ برسید و از حال آگاه شد آن مرد را بخواند. (تاریخ برامکه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگاه کردن </span> ؛ مطلع، باخبر کردن . آگاهانیدن . اِخبار. خبر دادن . اِنباء. آگاهی دادن <span class=\"hlight\">:</span> <br />یکی نامه <font color=\"DarkGreen\"><b>[ کردیه ]</font></b> سوی برادر بدرد<br />نوشت و ز هر کارش آگاه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />همانا که برزوت آگاه کرد<br />که تیره شبت نزد من راه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />پس آگاه کردند از آن کارزار<br />پُس ِ شاه را فرخ اسفندیار.<br /> <font color=\"Red\">فردوسی .</font><br />حاجب نوبتی را آگاه کردند درساعت نزدیک من آمد. (تاریخ بیهقی ). تو خداوند را از آمدن من آگاه گردان اگر راه باشد بفرماید تا پیش رَوَم . (تاریخ بیهقی ). بوالحسن آلتونتاش را آگاه کرد و بونصر مشکان نیز با دبیر آلتونتاش بگفت . (تاریخ بیهقی ). ما امیرالمؤمنین را از عزیمت خویش آگاه کردیم و عهد خراسان و جمله ٔ مملکت پدر را بخواستیم . (تاریخ بیهقی ). هفتاد و اند تن را ببخارا آوردند... و نصر احمد را آگاه کردند. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگاه گشتن </span> ؛ آگاه گردیدن . خبر و آگاهی یافتن . انتباه . اصباح <span class=\"hlight\">:</span> <br />از او پرهیز کن چون گشتی آگاه <br />که جز فعل بد او را نیست کاری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کرد مردی در آن میانه نگاه <br />گشت از ابلهی ّ کور آگاه .<br /> <font color=\"Red\">سنائی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">عاشق نبود ز عیب معشوق آگاه </span> .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> واقف . خبیر. نبیه . عارف . بیدار. یقظ. هشیار. متیقظ. آگه <span class=\"hlight\">:</span> <br />تو آگاهی از کار دین و هنر<br />ز فرمان یزدان و رای پدر<br />که بر گرد آن کوه یک راه بود<br />وزآن راه گشتاسب آگاه بود.<br /> <font color=\"Red\">فردوسی .</font><br />ای بدریای عقل کرده شناه <br />وز بد و نیک روزگار آگاه .<br /> <font color=\"Red\">سنائی .</font><br />هرکه او بیدارتر پردردتر<br />هرکه او آگاه تر رخ زردتر.<br /> <font color=\"Red\">مولوی .</font><br />اهل عالم به نان چو محتاجند<br />پس به نزدیک آنکه آگاهیست ...<br />چون گدا شاه نیز نانخواهیست .<br /> <font color=\"Red\">ابن یمین .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگاه باش !</span> ؛ اَلا! هان !<br /> <BR><font color=\"Blue\">◄</font> آگاه در کلمات مرکبه معانی گوناگون دهد، چنانکه دل آگاه به معنی روشن ضمیر و دژآگاه و بدآگاه به معنی جاهل مرکب و کارآگاه بمعنی بصیر و اهل خبرت و ناآگاه بی خبر و نادان آید <span class=\"hlight\">:</span> <br />در این کارگه مرد هشیارجوی <br />نه دنگ و دژآگاه و بسیارگوی .<br /> <font color=\"Red\">خسروانی .</font><br />ز چیز کسان دست کوته کنی <br />دژآگاه را بر، خوش آگه کنی .<br /> <font color=\"Red\">ابوشکور.</font><br /> <BR><font color=\"Blue\">◄</font> (اِمص ) آگاهی، چنانکه تشنه به معنی تشنگی و گرسنه به معنی گرسنگی <span class=\"hlight\">:</span> <br />چو این کرده شد چاره ٔ آب ساخت <br />ز دریا برآورد و هامون نواخت <br />بجوی و برود آب را راه کرد <font color=\"DarkGreen\"><b>[ هوشنگ ]</font></b><br />به فرّ کئی رنج کوتاه کرد<br />چوآگاه مردم بر آن برفزود<br />پراکندن تخم و کشت و درود<br />بسیجید پس هر کسی نان خویش <br />بورزید و بشناخت سامان خویش .<br /> <font color=\"Red\">فردوسی .</font><br />چنان دان کزین بردش آگاه نیست <br />بچون و چرا سوی او راه نیست .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت کای نورسیده شبان <br />چه آگاه داری ز روز و شبان ؟<br /> <font color=\"Red\">فردوسی .</font><br />همی رفت و نبودش هیچ آگاه <br />که ره در پیش او راه است یا چاه .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />آگه نیز به همین معنی آمده است . رجوع به آگه شود.<br /></font></div>'),
(2902, 'آگاه', '<span class=\"hlight\">آگاه .</span> (اِخ ) تخلص مولوی محمد باقر، از شعرای پارسی سرای هند. (<span class=\"hlight\" dir=\"rtl\">١١٥٨</span>-<span class=\"hlight\" dir=\"rtl\">١٢٢٠</span> هَ .ق .). <BR><font color=\"Blue\">◄</font> تخلص اردشیرمیرزا پسر عباس میرزا.<br /></font></div>'),
(2903, 'آگاه دل', '<span class=\"hlight\">آگاه دل .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (ص مرکب ) دل آگاه . صاحبدل .<br /></font></div>'),
(2904, 'آگاهان', '<span class=\"hlight\">آگاهان .</span> (نف، ق ) آگاه . در حال آگاهانیدن . <BR><font color=\"Blue\">◄</font> (اِ) ج ِ آگاه .<br /></font></div>'),
(2905, 'آگاهاندن', '<span class=\"hlight\">آگاهاندن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آگاهانیدن .<br /></font></div>'),
(2906, 'آگاهاننده', '<span class=\"hlight\">آگاهاننده .</span> <font color=\"DarkGreen\"><b>[ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) مُخبر. مُنذر. نبی ّ.<br /></font></div>'),
(2907, 'آگاهانیدن', '<span class=\"hlight\">آگاهانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) اِعلام . تنبیه . اذان . تنبئه . اخطار. اِشعار. ایذان . ازکان . ایقاظ. تعریف . انهاء. تخبیر. اِخبار. انباء. آگاهاندن . آگهانیدن . آگهاندن . مطلع کردن . خبر دادن . تأذّن . اطلاع دادن . مستحضر ساختن . آگاه کردن . تمئنه <span class=\"hlight\">:</span> بیامدم تا ترا بیاگاهانم . (تاریخ بیهقی ).<br /></font></div>'),
(2908, 'آگاهانیده', '<span class=\"hlight\">آگاهانیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) خبرداده شده .<br /></font></div>'),
(2909, 'آگاهی', '<span class=\"hlight\">آگاهی .</span> (اِ) اداره ای در شهربانی برای تعقیب بزهکاران . (فرهنگستان ).<br /></font></div>'),
(2910, 'آگاهی', '<span class=\"hlight\">آگاهی .</span> (حامص، اِ) شناخت . خبَر. نباء. اطلاع . آگهی . <BR><font color=\"Blue\">◄</font> علم . معرفت . خبرت . وقوف . عرفان <span class=\"hlight\">:</span> <br />پس آگاهی آمد به اسفندیار<br />که کشته شد آن شاهزاده سوار.<br /> <font color=\"Red\">فردوسی .</font><br />پس آگاهی آمد بشاه بزرگ <br />ز مهراب و دستان سام سترگ .<br /> <font color=\"Red\">فردوسی .</font><br />پس آگاهی آمد ز فرخ پسر<br />بمادر که فرزند <font color=\"DarkGreen\"><b>[ فریدون ]</font></b> شد تاجور.<br /> <font color=\"Red\">فردوسی .</font><br />پس آگاهی آمد ز هاماوران <br />بدشت سواران نیزه وران .<br /> <font color=\"Red\">فردوسی .</font><br />پس آگاهی آمد سوی نیمروز<br />به نزدیک سالار گیتی فروز.<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمد به آزادگان <br />برِ پیر گودرز گشوادگان .<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمدبایران ز شاه <br />از آن ایزدی فرّ و آن دستگاه .<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمد به پرویز شاه <br />که پیغمبر قیصرآمد ز راه .<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمد بسوی گراز<br />که آن نامور شد سوی رزم باز.<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمد بگردان شاه <br />خرامان برفتند تا بارگاه .<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمد بگشتاسب شاه <br />که سالار ترکان چین با سپاه ...<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمد سوی نیمروز<br />بنزد سپهدار گیتی فروز.<br /> <font color=\"Red\">فردوسی .</font><br />چو آن نامه نزدیک خسرو رسید<br />ز پیوستن آگاهی نو رسید.<br /> <font color=\"Red\">فردوسی .</font><br />ز آگاهی نامدار اردشیر<br />سپه انجمن شد بر آن آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br />که آگاهی ما بخسرو برد<br />ورا زآن سخن هدیه ٔ نو برد.<br /> <font color=\"Red\">فردوسی .</font><br />چنان کز تو به نزدیک من است ای خسرو آگاهی <br />ز تو تا خسروان چندان بود کز ماه تا ماهی .<br /> <font color=\"Red\">فرخی .</font><br />این ملکه نصیحتی کرده است و سخت بوقت آگاهی داده .(تاریخ بیهقی ). پادشاهان را این آگاهی نباشد اما منهیان و جاسوسان برای این کارها باشند تا چنین دقائق ها را نپوشانند. (تاریخ بیهقی ).<br />عبادت بتقلید گمراهی است <br />خنک رهروی را که آگاهی است .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگاهی خواستن </span> ؛ استخبار. استعلام .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگاهی دادن </span> ؛ آگاه کردن . اِخبار. اعلام . انباء. آگاهانیدن . اذان . تنبیه . پیام .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگاهی، آگاهی مرگ </span> ؛ نَعی . خبر مرگ <span class=\"hlight\">:</span> <br />چنین تا به نزدیک گشتاسب شد<br />به آگاهی درد لهراسب شد.<br /> <font color=\"Red\">فردوسی .</font><br />از آن روزبانان ناپاکمرد<br />تنی چند روزی بدو بازخورد<br />گرفتند و بردند بسته چو یوز<br />بر او بر سر آورد ضحاک روز...<br />چو آگاهی شوی بشنود زن <br />ز بیدادها بر سرش آمدن <br />دوان داغدل خسته ٔ روزگار<br />همی رفت پویان سوی مرغزار.<br /> <font color=\"Red\">فردوسی .</font><br />بمادر یکی نامه فرمود و گفت <br />که آگاهی مرگ نتوان نهفت .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگاهی یافتن </span> ؛ انتباه . انتبال .<br /></font></div>'),
(2911, 'آگاهیدن', '<span class=\"hlight\">آگاهیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) خبر یافتن . آگاه شدن . مطلع، باخبر گشتن . آگهیدن <span class=\"hlight\">:</span> <br />بیاگاهد اکنون چو من رزم جوی <br />شوم با سواران به نزدیک اوی .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2912, 'آگاهیده', '<span class=\"hlight\">آگاهیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آگاه شده . باخبرگشته . آگهیده .<br /></font></div>'),
(2913, 'آگج', '<span class=\"hlight\">آگج .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِ) رجوع به آکج شود.<br /></font></div>'),
(2914, 'آگده', '<span class=\"hlight\">آگده .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آکده . آکنده . (برهان ). و شاید مصحف آکنده باشد.<br /></font></div>'),
(2915, 'آگر', '<span class=\"hlight\">آگر.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِ) آکر. به معنی سرین که در فرهنگها مضبوط است، ظاهراً مصحف آلر است . آلر در فرهنگهای قدیم تر هست و چند بیت از قدما برای آن شاهد آمده است . رجوع به آکر و آلر شود.<br /></font></div>'),
(2916, 'آگسته', '<span class=\"hlight\">آگسته .</span> <font color=\"DarkGreen\"><b>[ گ َ ت َ <span class=\"hlight\" dir=\"rtl\">/</span>ت ِ ]</font></b> (ن مف ) ترکرده . آلوده . آمیخته . آگشته . آغشته .<br /></font></div>'),
(2917, 'آگسته', '<span class=\"hlight\">آگسته .</span><font color=\"DarkGreen\"><b>[ گ ِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف ) محکم بسته . (برهان ). آگشته .<br /></font></div>'),
(2918, 'آگسه', '<span class=\"hlight\">آگسه .</span> <font color=\"DarkGreen\"><b>[ گ ِ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (ص ) رجوع به آکسه شود.<br /></font></div>'),
(2919, 'آگش', '<span class=\"hlight\">آگش .</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (اِ) آغوش .<br /></font></div>'),
(2920, 'آگشتن', '<span class=\"hlight\">آگشتن .</span> <font color=\"DarkGreen\"><b>[ گ َ ت َ ]</font></b> (مص ) آلودن .<br /></font></div>'),
(2921, 'آگشته', '<span class=\"hlight\">آگشته .</span> <font color=\"DarkGreen\"><b>[ گ َ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف ) ترکرده . آلوده . آمیخته .(برهان ). آگسته . و رجوع به آگَسته شود <span class=\"hlight\">:</span> <br />دلش خود ز تخت و کله گشته بود<br />به تیمار اغریرث آگشته بود.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2922, 'آگشته', '<span class=\"hlight\">آگشته .</span> <font color=\"DarkGreen\"><b>[ گ ِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف ) محکم بسته . (برهان ). آگِسته <span class=\"hlight\">:</span> <br />خود مکن قصه دراز آخر نباشد کم زیان <br />چون طمع آگشته است از جبه و دستار تو.<br /> <font color=\"Red\">کمال اسماعیل .</font><br />لیکن این بیت کمال اسماعیل ظاهراً در دعوی فرهنگ نویسان نیست .<br /></font></div>'),
(2923, 'آگفت', '<span class=\"hlight\">آگفت .</span> <font color=\"DarkGreen\"><b>[ گ َ <span class=\"hlight\" dir=\"rtl\">/</span> گ ِ <span class=\"hlight\" dir=\"rtl\">/</span> گ ُ ]</font></b> (اِ) آسیب . صدمه . آزار. آفت . رنج . بلا. عاهت . مصیبت . فتنه . فساد <span class=\"hlight\">:</span> <br />چون صبح برافکند ردای زربفت <br />بنشست بصد حیله و برخاست بتفت <br />گفتم که مرو جز این نگفتم که برفت <br />دیدم که دمید صبح و آمد آگفت (کذا).<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />دین ورز ای روی تو آگفت دین <br />می خور و شادی کن و خرم نشین .<br /> <font color=\"Red\">مسعودسعد.</font><br />شاها ادبی کن فلک بدخو را<br />کآگفت رسانید رخ نیکو را<br />گر گوی غلط رفت بچوگانش زن <br />ور اسب خطا کرد بمن بخش او را.<br /> <font color=\"Red\">معزّی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٧٩٩</span>).</font><br />برگرفت از ره بهشت آگفت <br />در پیغمبری ببست و برفت .<br /> <font color=\"Red\">مختاری .</font><br />باز گفت این سخن سه بارو برفت <br />بنگر او را که چون گرفت آگفت .<br /> <font color=\"Red\">سنائی .</font><br />بنالم از غم این روزگار و این آگفت <br />که هر چه بد سبب شادی و نشاط برفت <br />سپید شد سر اقبال و سال روی بتافت <br />زمانه حال بشولیده کرد و بخت بخفت .<br /> <font color=\"Red\">سید ابوطالب (از تاریخ بیهق ).</font><br />و آن را آکفت با کاف تازی و نیز بکسر گاف ضبط کرده اند. در شعر منقول از تاریخ بیهق گاف مضموم و در رباعی رونی و بیت سنائی و مختاری ظاهراً مفتوح آمده است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگفت دیده </span> ؛ مئوف . آفت رسیده .<br /></font></div>'),
(2924, 'آگن', '<span class=\"hlight\">آگن .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِ) آکندنی باشد، مثل آنچه در جامه و لحاف و بالش کنند از پنبه و پشم و غیره . <BR><font color=\"Blue\">◄</font> (نف مرخم ) آکن . به معنی پرکننده که فاعل پر کردن باشد هم آمده است . (برهان ). شاید مخفف آگند باشد.<br /></font></div>'),
(2925, 'آگن', '<span class=\"hlight\">آگن .</span> <font color=\"DarkGreen\"><b>[ گ ِ]</font></b> (پسوند) در کلمات مُرکبه، مرادف آگین . گن . گین .<br /></font></div>'),
(2926, 'آگنج', '<span class=\"hlight\">آگنج .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِ) امعاء سطبر گوسفند و مانند آن بگوشت آکنده <span class=\"hlight\">:</span> <br />عصیب و گرده برون کن تو زود و برهم کوب <br />جگر بیازن و آگنج را بسامان کن <br />وز این همه که بگفتم نصیب روز بزرگ <br />غدود و زهره و سرگین و خون و فوکان کن .<br /> <font color=\"Red\">کسائی .</font><br />چرغند، رونج، ارونج، مالکانه، شاه لوت، زونج، جگرآکند، عصیب، سختو، سغدو، چرب روده، مبار، جهودانه، غازی، لکانه، ولوالی، زناج، اکامه، گاشاک، کدک مترادفات یا انواع آن است . <BR><font color=\"Blue\">◄</font> (ن مف مرخم ) آگند. در کلمات مرکبه، انباشته و پرکرده، چون جگرآگنج به معنی جگرآکند <span class=\"hlight\">:</span> <br />چون لنگ خر مرده آن جعد پرآفت (کذا)<br />چون روده ٔ ناشسته با روی گه آگنج .<br /><font color=\"Red\">سیف اسفرنگ .</font><br /></font></div>'),
(2927, 'آگند', '<span class=\"hlight\">آگند.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (ن مف مرخم ) رجوع به آکند شود.<br /></font></div>'),
(2928, 'آگندن', '<span class=\"hlight\">آگندن .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ ]</font></b> (مص ) رجوع به آکندن شود.<br /></font></div>'),
(2929, 'آگندنی', '<span class=\"hlight\">آگندنی .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ ]</font></b> (ص لیاقت، اِ) رجوع به آکندنی شود.<br /></font></div>'),
(2930, 'آگنده', '<span class=\"hlight\">آگنده .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) رجوع به آکنده شود.<br /></font></div>'),
(2931, 'آگنده گوش', '<span class=\"hlight\">آگنده گوش .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب ) رجوع به آکنده گوش شود.<br /></font></div>'),
(2932, 'آگندگی', '<span class=\"hlight\">آگندگی .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) رجوع به آکندگی شود.<br /></font></div>'),
(2933, 'آگنش', '<span class=\"hlight\">آگنش .</span> <font color=\"DarkGreen\"><b>[ گ َ ن ِ ]</font></b> (اِمص، اِ) رجوع به آکنش شود.<br /></font></div>'),
(2934, 'آگنه', '<span class=\"hlight\">آگنه .</span> <font color=\"DarkGreen\"><b>[ گ َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) رجوع به آکنه شود.<br /></font></div>'),
(2935, 'آگنیدن', '<span class=\"hlight\">آگنیدن .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ ]</font></b> (مص ) رجوع به آکنیدن شود.<br /></font></div>'),
(2936, 'آگنیده', '<span class=\"hlight\">آگنیده .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) رجوع به آکنیده شود.<br /></font></div>'),
(2937, 'آگه', '<span class=\"hlight\">آگه .</span> <font color=\"DarkGreen\"><b>[ گ َه ْ ]</font></b> (ص ) آگاه . باخبر.مطلع. مستحضر. عالم . خبیر. عارف . واقف <span class=\"hlight\">:</span> <br />چو آگه شد از مرگ فرزند شاه <br />ز اندوه گیتی بر او شد سیاه .<br /> <font color=\"Red\">فردوسی .</font><br />همانا خوش آمدْش گفتار اوی <br />نبود آگه از زشت کردار اوی .<br /> <font color=\"Red\">فردوسی .</font><br />بایوان یکی گنج بودش <font color=\"DarkGreen\"><b>[ فرنگیس را ]</font></b> نهان <br />نبد زآن کسی آگه اندر جهان .<br /> <font color=\"Red\">فردوسی .</font><br />ز خیمه برآورد پرخون سرش <br />که آگه نبد زآن سخن لشکرش .<br /> <font color=\"Red\">فردوسی .</font><br />چو از جنبش خسرو آگه شدند<br />از آن دشت تازان سوی ره شدند.<br /> <font color=\"Red\">فردوسی .</font><br />مرا کرد یزدان از این بی نیاز<br />گر آگه نه ای برگشایمْت راز.<br /> <font color=\"Red\">فردوسی .</font><br />بدانگاه از این کار آگه شوی <br />که بی تاج و بی تخت و بی گه شوی .<br /> <font color=\"Red\">فردوسی .</font><br />چو از لشکر آگه شد افراسیاب <br />بر او تیره شد تابش آفتاب .<br /> <font color=\"Red\">فردوسی .</font><br />شما یکسر از کارها آگهید<br />بر این بر که گویم گواهی دهید.<br /> <font color=\"Red\">فردوسی .</font><br />چو قیدافه آگه شد از قیدروش <br />ز بهر پسر پهن بگشاد گوش .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد سخن جوی پویان ز پس <br />نبد آگه از راز او هیچکس .<br /> <font color=\"Red\">فردوسی .</font><br />بگفتا مرا زود آگه کنید<br />روانرا سوی روشنی ره کنید.<br /> <font color=\"Red\">فردوسی .</font><br />بت دلنواز و می خوشگوار<br />پرستید و آگه نبد او ز کار.<br /> <font color=\"Red\">فردوسی .</font><br />بدل گفت آن هر سه بیره شدند<br />چواز ماو از لشکر آگه شدند.<br /> <font color=\"Red\">فردوسی .</font><br />ز بربر همه لشکر آگه شدند<br />سگالش چنین بود در ره شدند.<br /> <font color=\"Red\">فردوسی .</font><br />قلون دلاور شد آگه ز کار<br />پذیره بیامد سوی کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />چو تهمورس آگه شد از کارشان <br />برآشفت و بشکست بازارشان .<br /> <font color=\"Red\">فردوسی .</font><br />کسانیکه زین دانش آگه بوند<br />پراکنده یا بر در شه بوند.<br /> <font color=\"Red\">فردوسی .</font><br />از آن چاره آگه نبد هیچکس <br />که او داشت آن راز پنهان و بس .<br /> <font color=\"Red\">فردوسی .</font><br />همی گفت با کردگار جهان <br />که ای آگه از آشکار و نهان .<br /> <font color=\"Red\">فردوسی .</font><br />چنین تا برآمد بر این سال پنج <br />نبودند آگه ز درد و ز رنج .<br /> <font color=\"Red\">فردوسی .</font><br />گر نه ای آگه تو از این گنده پیر<br />منت خبر گویم از این بد فعال .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نیستی آگه چه گویم مر ترا من جز همانْک <br />عامه گوید نیستی آگه ز نرخ لوبیا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />آگه منم ز خوی بد او از آنک <br />کس نازمود هرگز بیش از منش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دریغا جوانی ّ و آن روزگار<br />که از رنج پیری تن آگه نبود.<br /> <font color=\"Red\">مسعودسعد.</font><br />آگه شدم که خدمت مخلوق هیچ نیست <br />هست از همه گزیر و ز اﷲ ناگزیر.<br /> <font color=\"Red\">سوزنی .</font><br />اقتضای جان چو آید آگهی است <br />هرکه آگه تر بود جانش قویست .<br /> <font color=\"Red\">مولوی .</font><br />نی ولیکن یار ما زین آگه است <br />زآنکه از دل سوی دل پنهان ره است .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگه بودن </span> ؛ باخبر، عالم، خبیر بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگه شدن </span> ؛ خبر یافتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگه کردن </span> ؛ باخبر کردن . مطلع ساختن .<br /> <BR><font color=\"Blue\">◄</font> چون با کلمه ای مرکب شود کلمه بمعانی مختلفه آید، مثلاً دل آگه به معنی صاحبدل و روشن ضمیر و دژآگه و بدآگه به معنی جاهل بجهل مرکب مقابل خوش آگه و کارآگه اهل خبرت و بصیرت باشد. <BR><font color=\"Blue\">◄</font> (اِمص ) آگهی . آگاهی . خبر <span class=\"hlight\">:</span> <br />منم همچون پیاده تو سواری <br />ز رنج رفتنم آگه نداری .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />حسودا تو مگر آگه نداری <br />که در باران بودامیدواری <br />بهار آید چو بارد ابر بسیار<br />مگر بازآید از باران من یار.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />چنین یافتم آگه از راستان <br />چنین گفت گوینده ٔ داستان .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />و آگاه نیز بدین معنی آمده است .رجوع به آگاه شود.<br /></font></div>'),
(2938, 'آگه', '<span class=\"hlight\">آگه .</span> <font color=\"DarkGreen\"><b>[ گ َه ْ ]</font></b> (اِخ ) نام شاعری شیرازی ازمتأخرین، برادر نواب، متخلص به بسمل . از مریدان میرزا ابوالقاسم درویش شیرازی . وفات در <span class=\"hlight\" dir=\"rtl\">١٢٤٤</span> هَ .ق .<br /></font></div>'),
(2939, 'آگهان', '<span class=\"hlight\">آگهان .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (نف، ق ) آگاه . در حال آگهیدن .<br /></font></div>'),
(2940, 'آگهاندن', '<span class=\"hlight\">آگهاندن .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ ]</font></b> (مص ) آگاهانیدن .<br /></font></div>'),
(2941, 'آگهاننده', '<span class=\"hlight\">آگهاننده .</span> <font color=\"DarkGreen\"><b>[ گ َ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آگاهاننده . مخبر.<br /></font></div>'),
(2942, 'آگهانیدن', '<span class=\"hlight\">آگهانیدن .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ ]</font></b> (مص ) آگاهانیدن .<br /></font></div>'),
(2943, 'آگهانیده', '<span class=\"hlight\">آگهانیده .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) آگاهانیده . مطلعساخته . باخبرکرده .<br /></font></div>'),
(2944, 'آگهی', '<span class=\"hlight\">آگهی .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (حامص، اِ) مخفف آگاهی . خبر. نباء. اطلاع . آگاهی .علم . معرفت . خبرت . وقوف . عرفان . شناخت <span class=\"hlight\">:</span> <br />بدو گفت کای مهتر کاروان <br />مرا آگهی ده ز بارنهان .<br /> <font color=\"Red\">فردوسی .</font><br />بایران رسدزین بدی آگهی <br />برآشوبد این روزگار بهی .<br /> <font color=\"Red\">فردوسی .</font><br />چو آمد ببغداد از او آگهی <br />که آمد خریدار تخت مهی <br />همه شهر از آگاهی آرام یافت <br />جهانجوی ازآرامشان کام یافت .<br /> <font color=\"Red\">فردوسی .</font><br />که من این آگهی دیگر شنیدم <br />چنان دانم که من بهتر شنیدم .<br /> <font color=\"Red\">(ویس ورامین ).</font><br />به گفتن گرفتند راز نهان <br />بگسترد از آن آگهی در جهان .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بیزدان بخشنده ٔ دادگر<br />که آگاهیم ده ز کار پدر<br />که باشد کنار من از وی تهی <br />هنوزم نیامد از او آگهی .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بیاورد چون آگهی یافت شاه <br />فرستاد مردم پَس ِ ما براه .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />ملک را هم بشب آگهی دادند. (گلستان ).<br />بَریدِ باد صبا دوشم آگهی آورد<br />که روز محنت و غم رو بکوتهی آورد.<br /> <font color=\"Red\">حافظ.</font><br /> <br /> <BR><font color=\"Blue\">◄</font> شهرت . صیت . اشتهار <span class=\"hlight\">:</span> <br />بهر هفت کشور ز من آگهیست <br />ستاره رخ روشنم را رهیست .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> روایت . اثَر. حدیث <span class=\"hlight\">:</span> <br />چنین آورد راستگو آگهی <br />که چون شد بخانه رسول چهی ...<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> علم . استحضار <span class=\"hlight\">:</span> <br />که از مرز هیتال تا مرز چین <br />نباید که کس پی نهد بر زمین <br />مگر به آگهی ّ و بفرمان ما<br />روان بسته دارد ز پیمان ما.<br /> <font color=\"Red\">فردوسی .</font><br />ز رنج و ز بدْشان نبد آگهی <br />میان بسته دیوان بسان رهی .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">از آگهی رفتن (بشدن )</span> ؛ از خویش بی خویش، از خود بی خود گشتن . مغمی علیه گردیدن <span class=\"hlight\">:</span> <br />شهنشه مست بود از باده بیهوش <br />برفت از آگهی ّ و شد از او هوش .<br /> <font color=\"Red\">(ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> اعلام <span class=\"hlight\">:</span> <br />چو آمد به بغداد از او آگهی <br />که آمد خریدار تخت مهی <br />همه شهر از آگاهی آرام یافت <br />دل شاه از آرامشان کام یافت .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> سماع . شنودن <span class=\"hlight\">:</span> <br />تو دانی که دیدن به از آگهی است <br />میان شنیدن همیشه تهی است .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> علم . خبرت . معرفت <span class=\"hlight\">:</span> <br />چون سِر و ماهیت جان مخبر است <br />هرکه او آگاه تر باجان تر است <br />اقتضای جان چو آید آگهی است <br />هرکه آگه تر بود جانش قوی است <br />خود جهان جان سراسر آگهی است <br />هرکه بی جان است از دانش تهی است .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(2945, 'آگهی', '<span class=\"hlight\">آگهی .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) تخلص شاعری از مردم یزد.<br /></font></div>'),
(2946, 'آگهی', '<span class=\"hlight\">آگهی .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِ) نوشته ای که خبر یا دستوری نوین دهد. <BR><font color=\"Blue\">◄</font> اعلامیه ای که بانک بمشتری فرستد. (فرهنگستان ).<br /></font></div>'),
(2947, 'آگهیدن', '<span class=\"hlight\">آگهیدن .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ ]</font></b> (مص ) آگاهیدن . باخبر شدن .<br /></font></div>'),
(2948, 'آگهیده', '<span class=\"hlight\">آگهیده .</span> <font color=\"DarkGreen\"><b>[ گ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آگاهیده . باخبرشده .<br /></font></div>'),
(2949, 'آگو', '<span class=\"hlight\">آگو.</span> (اِ) بوم . جغد. رجوع به آکو شود.<br /></font></div>'),
(2950, 'آگور', '<span class=\"hlight\">آگور.</span> (اِ) خشت پخته . آجر. (ربنجنی ). کرمید <span class=\"hlight\">:</span> <br />بر در و بام برف پنداری <br />بیخته گچ و کشته آگور است .<br /> <font color=\"Red\">مسعودسعد.</font><br />خانه ٔجغد را بکوشیدی <br />بگچ آگور و نقش پوشیدی <br />آن گچ آگور کرده خانه ٔ دین <br />وین بیاراسته بنور یقین .<br /> <font color=\"Red\">سنائی .</font><br />آهک کافوروش اندوده بر آگور او<br />خشت زرین را مطلا کرده گوئی آب سیم .<br /><font color=\"Red\">ابن یمین .</font><br /></font></div>'),
(2951, 'آگورگر', '<span class=\"hlight\">آگورگر.</span> <font color=\"DarkGreen\"><b>[گو گ َ ]</font></b> (ص مرکب ) آجرپز. آجوری . (ربنجنی ). آگوری .<br /></font></div>'),
(2952, 'آگورگری', '<span class=\"hlight\">آگورگری .</span> <font color=\"DarkGreen\"><b>[ گو گ َ ]</font></b> (حامص مرکب ) کار آگورگر.<br /></font></div>'),
(2953, 'آگوری', '<span class=\"hlight\">آگوری .</span> (ص نسبی ) آگورگر. آجرپز. آجوری .<br /></font></div>'),
(2954, 'آگوش', '<span class=\"hlight\">آگوش .</span> (اِ) آغوش . بغل <span class=\"hlight\">:</span> امیر اورا بخویشتن خواند و در آگوش گرفت . (تاریخ بیهقی ).<br />گاه بادش گرفته بر گردن <br />گاه گردش کشیده در آگوش .<br /> <font color=\"Red\">مسعودسعد.</font><br />یک قطره از آن شراب مشکین <br />آورد دو عالمم درآگوش .<br /> <font color=\"Red\">عطار.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آگوش آگوش </span> ؛ بغل بغل <span class=\"hlight\">:</span> <br />در مجلس ما گلی و خاری باشد<br />آگوش آگوش مرغزاری باشد<br />سرتاسر اگر پلاس و کرباس بود<br />این اکسون است کلاه واری باشد.<br /> <font color=\"Red\">جلال الدین فضل اﷲ خواری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یک آگوش </span> ؛ یک بغل . یک آغوش .<br /><BR><font color=\"Blue\">◄</font> نامی از نامهای پرستاران ترک . رجوع به آغوش شود.<br /></font></div>'),
(2955, 'آگوشیدن', '<span class=\"hlight\">آگوشیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) در آغوش گرفتن . در بغل گرفتن . <BR><font color=\"Blue\">◄</font> در بیت ذیل سوزنی اگر تصحیفی راه نیافته باشد آگوشیدن به معنی بستن آمده است <span class=\"hlight\">:</span> <br />در شادیت گشاده ست و در غم بسته <br />بسته مگشای همه عمر وگشاده ماگوش <br />می آسوده بکف گیر و ز عشرت ماسای <br />کز نوا بلبل آسوده درآمد بخروش .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(2956, 'آگون', '<span class=\"hlight\">آگون .</span> (ص ) بر وزن و معنی وارون یعنی نگون باشد، چه سراگون سرنگون را گویند. (برهان ). واژون . واژگون . سرنگون . معلق . <BR><font color=\"Blue\">◄</font> سراشیب . و ظاهراً این کلمه جز در حال ترکیب مستعمل نیست .<br /></font></div>'),
(2957, 'آگپ', '<span class=\"hlight\">آگپ .</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (اِ) رجوع به آکپ شود.<br /></font></div>'),
(2958, 'آگیشیدن', '<span class=\"hlight\">آگیشیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) آویختن . پیچیدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">پای آگیش </span> ؛ بپای آویز. پای پیچ <span class=\"hlight\">:</span> <br />توشه ٔ جان خویش از او بربای <br />پیش کآیدْت مرگ ِ پای آگیش .<br /> <font color=\"Red\">رودکی .</font><br />رجوع به آکیش و آکیشیدن شود.<br /></font></div>'),
(2959, 'آگیم', '<span class=\"hlight\">آگیم .</span> (اِ) کَم ِ غربال .<br /></font></div>'),
(2960, 'آگین', '<span class=\"hlight\">آگین .</span> (اِ) حشو. آکنه . جغبوت <span class=\"hlight\">:</span> <br />خود پرّ کبوتران مینوست <br />کآگین چهاربالش اوست .<br /> <font color=\"Red\">خاقانی .</font><br />بهر آگین چاربالش اوست <br />هر پری کاین کبوتر افشانده ست .<br /> <font color=\"Red\">خاقانی .</font><br />و اجزاء میان صدر و عَروض و ابتداو ضرب را حشو خوانند یعنی آگین میانه ٔ اول و آخر مصاریع. (المعجم ).<br />و این کلمه را بقیاس به آکندن و آکنه با تداول فعلی، باید بکاف تازی خواند.<br /></font></div>'),
(2961, 'آگین', '<span class=\"hlight\">آگین .</span> (ص ) پُر <span class=\"hlight\">:</span> <br />همه کاخ تابوت بد سربسر<br />غنوده بصندوق در شیر نر<br />تو گفتی که سام است با یال و سفت <br />غمین شد ز جنگ اندر آمد بخفت <br />بپوشید بازش بدیبای زرد<br />سر تنگ تابوت را سخت کرد<br />همی گفت اگر دخمه زرین کنم <br />ز مشک سیه گِردَش آگین کنم <br />چو من رفته باشم نماند بجای <br />وگرنه مرا خود جز این نیست رای .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> فربه . مقابل لاغر. (برهان ).<br /></font></div>'),
(2962, 'آگین', '<span class=\"hlight\">آگین .</span> (پسوند) مرادف ِ آگِن و گِن و گین . درکلمات مرکبه ٔ با آن بمعانی آلود و آلوده آید، مانندعبیرآگین، عنبرآگین، مشک آگین، زهرآگین <span class=\"hlight\">:</span> <br />بدخمه درون تخت زرین نهند<br />کله بر سرش عنبرآگین نهند.<br /> <font color=\"Red\">فردوسی .</font><br />شکسته زلف تو تازه بنفشه ٔ طبریست <br />رخ و دو عارض تو تازه لاله و نسرین <br />تو لاله دیدی شمشادپوش و سنبل تاج <br />بنفشه دیدی عنبرسرشت و مشک آگین .<br /> <font color=\"Red\">فرخی .</font><br />ز بس که عنبر و مشک است توده برتوده <br />دماغ دانش از اندیشه عنبرآگین است .<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> مرصع. گوهردرنشانیده . گوهرآگین <span class=\"hlight\">:</span> <br />همه طشت زرین و سیمین بدی <br />چو زرین بدی گوهرآگین بدی .<br /> <font color=\"Red\">فردوسی .</font><br />از آن تختها چند زرین بدی <br />چه مایه از او گوهرآگین بدی .<br /> <font color=\"Red\">فردوسی .</font><br />رکابش دو زرین، دو سیمین بدی <br />همان هر یکی گوهرآگین بدی .<br /> <font color=\"Red\">فردوسی .</font><br />چنین هم بمشکوی زرین من <br />چه در خانه ٔ گوهرآگین من <br />پرستار باشد ده و دو هزار<br />همه پاک با طوق و با گوشوار.<br /> <font color=\"Red\">فردوسی .</font><br />زآن جام گوهرآگین جمشید خورده حسرت <br />زآن رمح اژدهاسر ضحاک برده مالش .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> محشو. انباشته . ممتلی : عقیق آگین <span class=\"hlight\">:</span> <br />تا بدان وقتی که همچون گوی سیمین گشت سیب <br />نار همچون حقه ٔ گرد عقیق آگین شود.<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> مانند. گونه : طلسم آگین <span class=\"hlight\">:</span> <br />من بدین راه طلسم آگین همی کردم نگاه <br />در تفکر خیره مانده همچو شخص بی روان .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> صاحب . دارا. مالک : عثرت آگین <span class=\"hlight\">:</span> <br />مر ترادین نبی خاص دبستانیست <br />دین کند جان ترا زنده و علم آگین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کژکژی نفس عثرت آگین راست <br />راستی عقل عاقبت بین راست .<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> اندود. اندوده : زرآگین <span class=\"hlight\">:</span> <br />مدخلان را رکاب زرآگین <br />پای آزادگان نیابد سر.<br /> <font color=\"Red\">رودکی .</font><br /> <BR><font color=\"Blue\">◄</font> پُر. بسیار: پندآگین . سحرآگین . غم آگین <span class=\"hlight\">:</span> <br />آن خوانده ای بخوان سخن حجت <br />رنگین برنگ معنی و پندآگین .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(2963, 'آی', '<span class=\"hlight\">آی .</span> (صوت ) صوتی است نشانه ٔ ضجرت از درد: آی دلم . آی سرم . <BR><font color=\"Blue\">◄</font> نشانه ٔ حسرت و دریغ <span class=\"hlight\">:</span> <br />آی دریغا که خردمند را<br />باشد فرزند و خردمند نی .<br /> <font color=\"Red\">رودکی .</font><br /><BR><font color=\"Blue\">◄</font> (حرف ندا) حرف ندا و خطاب، چون اِی ! <BR><font color=\"Blue\">◄</font> (فعل امر) امر از آمدن <span class=\"hlight\">:</span> تو چنانکه آواز ترا بشنوند با من در سخن آی . (کلیله و دمنه ).<br /></font></div>'),
(2964, 'آی', '<span class=\"hlight\">آی .</span> (ع اِ) ج ِ آیت و آیه .<br /></font></div>'),
(2965, 'آی آبه', '<span class=\"hlight\">آی آبه .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) (مؤید...) نام مملوکی از سلطان سنجر. و او در <span class=\"hlight\" dir=\"rtl\">٥٤٨</span> هَ .ق . بر نیشابور و طوس و نسا و ابیورد و دامغان استیلا یافت و در <span class=\"hlight\" dir=\"rtl\">٥٦٩</span> به دست تکش خوارزمشاه مغلوب و مقتول شد.<br /></font></div>'),
(2966, 'آی بابا', '<span class=\"hlight\">آی بابا.</span> (اِخ ) (از: ترکی آی، ماه + فارسی بابا، پدر) نامی است که مادران ماه را دهند آنگاه که کودکان شیرخواره ٔ خود را با نشان دادن ماه بازی دهند.<br /></font></div>'),
(2967, 'آی بیک سیف الدین', '<span class=\"hlight\">آی بیک سیف الدین .</span> <font color=\"DarkGreen\"><b>[ ب َ س َ فُدْ دی ]</font></b>(اِخ ) از حکام و سلاطین بنگاله (<span class=\"hlight\" dir=\"rtl\">٦٢٧</span>-<span class=\"hlight\" dir=\"rtl\">٦٣١</span> هَ .ق .).<br /></font></div>'),
(2968, 'آی بیک عزالدین', '<span class=\"hlight\">آی بیک عزالدین .</span> <font color=\"DarkGreen\"><b>[ ب َ ع ِزْ زُدْ دی ]</font></b> (اِخ ) دومین کس از ممالیک بحری که فرمانروای مصر و شام بوده اند (<span class=\"hlight\" dir=\"rtl\">٦٤٨</span> - <span class=\"hlight\" dir=\"rtl\">٦٥٥</span> هَ .ق .).<br /></font></div>'),
(2969, 'آی بیک قطب الدین', '<span class=\"hlight\">آی بیک قطب الدین .</span> <font color=\"DarkGreen\"><b>[ ب َ ق ُ بُدْ دی ]</font></b> (اِخ ) مؤسس سلسله ٔ ممالیک یا سلاطین مملوک دهلی (<span class=\"hlight\" dir=\"rtl\">٦٠٢</span>-<span class=\"hlight\" dir=\"rtl\">٦٠٧</span> هَ .ق .).<br /></font></div>'),
(2970, 'آی تیمور', '<span class=\"hlight\">آی تیمور.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) از سربداران، نامش محمد، و او پس از وجیه الدین مسعود امارت یافت (<span class=\"hlight\" dir=\"rtl\">٧٤٤</span>-<span class=\"hlight\" dir=\"rtl\">٧٤٦</span> هَ .ق .).<br /></font></div>'),
(2971, 'آی درویش', '<span class=\"hlight\">آی درویش .</span> <font color=\"DarkGreen\"><b>[ دَرْ ]</font></b> (اِخ ) نام تیره ای از ترکمانان ایران، ساکن شمال غربی سنگر.<br /></font></div>'),
(2972, 'آیا', '<span class=\"hlight\">آیا.</span> (ادات استفهام ) کلمه ای است که بدان طلب دانستن و استفهام کنند <span class=\"hlight\">:</span> <br />فروماند و از کارش آمد شگفت <br />بسی با دل اندیشه اندرگرفت <br />که آیا بهشت است یا بزمگاه <br />سپهر برینست یا چرخ ماه ؟<br /> <font color=\"Red\">فردوسی .</font><br />مشتاق آن نگارم آیا کجاست گوئی <br />با ما نمی نشیند بی ما چراست گوئی ؟<br /> <font color=\"Red\">اوحدی .</font><br />و بیشتر در فارسی بمدّ حرف ماقبل آخر کلمه برای افاده ٔ استفهام اکتفا کنند. و هیچ و مگر نیز در پاره ای مواضع معنی استفهام دهد و مرادف آیاباشد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیا بود، بود آیا</span> ؛ برای ترجّی و تمنی است، بمعنی تواندبود <span class=\"hlight\">:</span> <br />بود آیا که در میکده ها بگشایند<br />گره از کار فروبسته ٔ ما بگشایند؟<br /> <font color=\"Red\">حافظ.</font><br />آنانکه خاک را بنظر کیمیا کنند<br />آیا بود که گوشه ٔ چشمی بما کنند؟<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(2973, 'آیات', '<span class=\"hlight\">آیات .</span> (ع اِ) ج ِ آیه . نشانها. علامتها. هر یک از فقرات و جم-ل ق-رآن که سوره از آنها مرکب است . <BR><font color=\"Blue\">◄</font> معجزات <span class=\"hlight\">:</span> و باظهار آیات مثال داد. (کلیله و دمنه ). و آن را به آیات و اخبار وابیات و اشعار مؤکد گردانیده شود. (کلیله و دمنه ).و شرایط سخن رانی در تضمین امثال و تلفیق آیات ... تقدیم نموده آید. (کلیله و دمنه ). و در آیات براعت و معجزات صناعت که این کتاب بر اظهار بعضی از آن مشتمل است تأملی بسزا رود شناخته گردد. (کلیله و دمنه ).<br />این طبیبان نوآموزند خود<br />که بدین آیاتشان حاجت بود<br />کاملان از دور نامت بشنوند<br />تا بقعر تار و پودت درروند.<br /> <font color=\"Red\">مولوی .</font><br />محکوم باد ملک ترا تا اساس دین <br />زآیات محکمات و احادیث محکم است .<br /> <font color=\"Red\">سلمان ساوجی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نماز آیات </span> ؛ نمازی که گاه خسوف و کسوف و زلزله و امثال آن مسلمانان را واجب باشد. و رجوع به آیت شود.<br /></font></div>'),
(2974, 'آیار', '<span class=\"hlight\">آیار.</span> (ع اِ) ج ِ اَیر.<br /></font></div>'),
(2975, 'آیاز', '<span class=\"hlight\">آیاز.</span> (اِخ ) ایاز. آیازاویماق . نام غلام محمودبن سبکتکین . این غلام برای کثرت فِراست و هوش و جنگجوئی و هم زیبائی و جمال محبوب سلطان بود <span class=\"hlight\">:</span> <br />نکند کار تیر آیازی <br />شل هندی ّ و نیزه ٔ تازی .<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />کاندر این راه جمله را شرط است <br />عشق محمود و خدمت آیاز.<br /> <font color=\"Red\">سنائی .</font><br />در دوره ٔ مسعود امارت قصدار و مکران داشته و در <span class=\"hlight\" dir=\"rtl\">٤٤٩</span> هَ .ق . وفات کرده است .<br /></font></div>'),
(2976, 'آیاس', '<span class=\"hlight\">آیاس .</span>(اِخ ) یاس ؟ <span class=\"hlight\">:</span> <br />به آیاس و خلخ همی برگذر<br />بکش هرکه یابی بخون پدر.<br /> <font color=\"Red\">فردوسی .</font><br />نه ارجاسب مانم نه آیاس و چین <br />نه کهرم نه خلخ نه توران زمین .<br /> <font color=\"Red\">فردوسی .</font><br />که این گر بدارد زمانی چنین <br />نه آیاس ماند نه خلخ نه چین .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(2977, 'آیان', '<span class=\"hlight\">آیان .</span> (نف، ق ) در حال آمدن . <BR><font color=\"Blue\">◄</font> بدیهه . آمده .<br /></font></div>'),
(2978, 'آیان', '<span class=\"hlight\">آیان .</span> (ص ) شب دراز. (سروری از تحفةالسعاده ).<br /></font></div>'),
(2979, 'آیای', '<span class=\"hlight\">آیای .</span> (ع اِ) ج ِ آیه .<br /></font></div>'),
(2980, 'آیت', '<span class=\"hlight\">آیت .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b>(ع اِ) نشان . نشانه . علامت . اماره . آیة <span class=\"hlight\">:</span> <br />ای بزمگه تو صورت فردوس <br />وی رزمگه تو آیت محشر.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> معجز. دشواری . معجزه . اعجاز. کرامت <span class=\"hlight\">:</span> <br />او آیت پیمبر ما بود روز حرب <br />از ذوالفقار بود و ز صمصام آیتش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و آیتها نمود از عصا و دیگر چیزها. (مجمل التواریخ ).<br />گفت من اینها ندانم حجتی <br />که بود در پیش عامه آیتی .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> دلیل . حجت . برهان <span class=\"hlight\">:</span><br />چون چون و چرا خواستم وآیت محکم <br />در عجز بپیچیدند این کور شد آن کر.<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> هر یک از تکّه، طائفه، جمله، کلام، فقره و جماعت حرفهای قرآن که سوره از آنها مرکب است . یک سخن تمام از قرآن : سوره ٔ اخلاص چهار آیت است . ج، آیات، آی، آیای <span class=\"hlight\">:</span> <br />بوقت شاه جهان گر پیمبری بودی <br />دویست آیت بودی به شأن شاه ایدر.<br /> <font color=\"Red\">فرخی .</font><br />مادر فرقان چه دانی تو که هفت آیت چراست <br />یا شهادت را چرا همراه کردستند لا؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />بیت و غزل بر طلب فحش و لهو<br />بی هنران را بدل آیت است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آیتی آمده در این بشما<br />گرچه امروز وقت آیت نیست .<br /> <font color=\"Red\">مسعودسعد.</font><br />تا یکی نان بسائلی به نداد<br />هجده آیت خداش نفرستاد.<br /> <font color=\"Red\">سنائی .</font><br />هست در تنزیل بر تصدیق این معنی دلیل <br />آیت ان لیس للانسان الا ما سعی .<br /> <font color=\"Red\">عبدالواسع جبلی .</font><br />سعدی شیرین سخن این همه شور از کجاست <br />شاهد ما آیتیست وینهمه تفسیر او .<br /> <font color=\"Red\">سعدی .</font><br />سعادت ازلی ّ و شقاوت ابدی <br />دو آیتند بر اوراق آسمان مسطور.<br /> <font color=\"Red\">سلمان ساوجی .</font><br /> <BR><font color=\"Blue\">◄</font> عجیبه . اُعجوبه <span class=\"hlight\">:</span> و امیر مسعود در این باب آیتی بود و او را در این باب دقایق بسیار است . (تاریخ بیهقی ). جدّه ای بود مرا... و با این چیزهای پاکیزه ساختی از خوردنی و شربتها بغایت نیکو و اندر آن آیتی بود. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> رسالت . <BR><font color=\"Blue\">◄</font> عبرت . <BR><font color=\"Blue\">◄</font> شخص . کالبد. <BR><font color=\"Blue\">◄</font> جماعت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیت مرد</span> ؛ رهط او. قوم او.<br /></font></div>'),
(2981, 'آیتی', '<span class=\"hlight\">آیتی .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) تخلص دو شاعر، یکی از اهل یزد و دیگری از مردم اصفهان . و آیتی اصفهانی معلم کُتّاب بوده و خط نستعلیق نیکو می نوشته .<br /></font></div>'),
(2982, 'آیتین', '<span class=\"hlight\">آیتین .</span> <font color=\"DarkGreen\"><b>[ ی َ ت َ ]</font></b> (ع اِ) تثنیه ٔ آیت . <BR><font color=\"Blue\">◄</font> (اِخ ) لقبی که آزادیخواهان در انقلاب آزادی بسید محمد طباطبائی و سید عبداﷲ بهبهانی دادند، و هر یک را جدا آیةاﷲ میخواندند.<br /></font></div>'),
(2983, 'آیدین', '<span class=\"hlight\">آیدین .</span> (اِخ ) نام شهری از ترکیه (لیدی ) بجنوب شرقی ازمیر، دارای <span class=\"hlight\" dir=\"rtl\">١٢</span> هزار تن سکنه و آب معدنی . محصول آن پنبه است .<br /></font></div>'),
(2984, 'آیدین', '<span class=\"hlight\">آیدین .</span> (اِخ ) نام سلسله ای از امرای ولایت لیدیا. این سلسله را بایزید اول در <span class=\"hlight\" dir=\"rtl\">٧٩٢</span> هَ .ق . برانداخت و مملکت آنان را ضمیمه ٔ ممالک عثمانی کرد.<br /></font></div>'),
(2985, 'آیر', '<span class=\"hlight\">آیر.</span> <font color=\"DarkGreen\"><b>[ ی ُ ]</font></b> (ع اِ) ج ِ اَیر.<br /></font></div>'),
(2986, 'آیران', '<span class=\"hlight\">آیران .</span> (اِخ ) ایران .<br /></font></div>'),
(2987, 'آیرتام', '<span class=\"hlight\">آیرتام .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام منزلی از منازل راه گرگان بخوارزم .<br /></font></div>'),
(2988, 'آیریا', '<span class=\"hlight\">آیریا.</span> (اِخ ) آریا.<br /></font></div>'),
(2989, 'آیریانا', '<span class=\"hlight\">آیریانا.</span> (اِخ ) ایران .<br /></font></div>'),
(2990, 'آیرین', '<span class=\"hlight\">آیرین .</span> (اِخ ) قاسم آباد. ایستگاه شماره ٔ سه در راه آهن جنوب . (فرهنگستان ).<br /></font></div>'),
(2991, 'آیزنه', '<span class=\"hlight\">آیزنه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ترکی، اِ) شوهرخواهر. یزنه .<br /></font></div>'),
(2992, 'آیزک', '<span class=\"hlight\">آیزک .</span> <font color=\"DarkGreen\"><b>[ ی ِ زَ ]</font></b> (اِ) کرم درخت . <BR><font color=\"Blue\">◄</font> کرم شب تاب . (شعوری ). و ظاهراً مصحف آتشیزک باشد.<br /></font></div>'),
(2993, 'آیس', '<span class=\"hlight\">آیس .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) ناامید. نومید. نمید. مأیوس . قانط. قنوط <span class=\"hlight\">:</span> <br />بود شخصی عالمی قطبی کریم <br />اندر آن منزل که آیس شد ندیم .<br /> <font color=\"Red\">مولوی .</font><br />چونکه قبضی آیدت ای راهرو<br />آن صلاح تست آیس دل مشو.<br /> <font color=\"Red\">مولوی .</font><br />عسر با یسر است هین آیس مباش <br />راه داری زین ممات اندر معاش .<br /> <font color=\"Red\">مولوی .</font><br />لیک تو آیس مشو هم پیل باش <br />ور نه پیلی در پی تبدیل باش .<br /> <font color=\"Red\">مولوی .</font><br />لیک خورشید عنایت تافته ست <br />آیسان را از کرم دریافته ست .<br /> <font color=\"Red\">مولوی .</font><br />هم بر آن بو می تنند و میروند<br />هر دمی راجی ّ و آیس میشوند.<br /> <font color=\"Red\">مولوی .</font><br />و آن در اصل آئس باشد.<br /></font></div>'),
(2994, 'آیسه', '<span class=\"hlight\">آیسه .</span> <font color=\"DarkGreen\"><b>[ ی ِ س َ ]</font></b> (ع ص ) تأنیث آیس . زنی که در مدت سال حیض نبیند. (تعریفات جرجانی ). و در اصل، آئسه .<br /></font></div>'),
(2995, 'آیش', '<span class=\"hlight\">آیش .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِ) زمینی که امسال بنوبت خود کاشته نشده . زمین نوبتی . چیمو. ولی . کشخان . کشتخان . کفشن . مرتاحه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیش دادن </span>؛ کشت یک بخش از دو بخش زمین را به سال دیگر گذاشتن، و این برای قوت یافتن زمین باشد.<br /></font></div>'),
(2996, 'آیشتنه', '<span class=\"hlight\">آیشتنه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ت َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص ) جاسوس . چاپلوس . رجوع به آیشنه و آیشه شود.<br /></font></div>'),
(2997, 'آیشم', '<span class=\"hlight\">آیشم .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِ) بلغت زند و پازندماهتاب است که پرتو ماه باشد. (برهان ).<br /></font></div>'),
(2998, 'آیشنه', '<span class=\"hlight\">آیشنه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص ) جاسوس . چاپلوس . (برهان ). رجوع به آیشتنه و آیشه شود.<br /></font></div>'),
(2999, 'آیشه', '<span class=\"hlight\">آیشه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص ) آیشتنه . آیشنه . چاپلوس . جاسوس . (برهان ) .<br /></font></div>'),
(3000, 'آیغر', '<span class=\"hlight\">آیغر.</span> <font color=\"DarkGreen\"><b>[ غ ُ ]</font></b> (ترکی، ص، اِ) ایغر. اسب گشن . حصان . اسب نر. (زمخشری ).<br /></font></div>'),
(3001, 'آیفت', '<span class=\"hlight\">آیفت .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِ) حاجت که خواهند <span class=\"hlight\">:</span> <br />ناسزا را مکن آیفت که آبت بشود<br />بسزاوار کن آیفت که ارجت دارد.<br /> <font color=\"Red\">دقیقی .</font><br />ز یزدان خواستن آنجمله آیفت <br />که تا نرسد مر او را هیچ آکفت .<br /> <font color=\"Red\">زراتشت بهرام .</font><br />ز حق آیفت میخواهد بزاری <br />کند شکر ره پرهیزکاری .<br /> <font color=\"Red\">زراتشت بهرام .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیفت کردن، آیفت بردن، آیفت خواستن </span> ؛ تمنی کردن . خواهش و درخواست کردن چیزی را. حاجت خواستن . عرض حاجت . درخواستن . سؤال چیزی .<br /></font></div>'),
(3002, 'آیل', '<span class=\"hlight\">آیل .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) آب ستبر چرکین . <BR><font color=\"Blue\">◄</font> شیر ستبر. <BR><font color=\"Blue\">◄</font> هر چیز ستبر از روغن و عسل و جز آن . ج، اُیَّل . و آیل صورت فارسی ِ آئل است .<br /></font></div>'),
(3003, 'آیل', '<span class=\"hlight\">آیل .</span><font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) نام کوهی بناحیه ٔ نقره در طریق مکه .<br /></font></div>'),
(3004, 'آیم سایم', '<span class=\"hlight\">آیم سایم .</span> <font color=\"DarkGreen\"><b>[ ی َ ی َ ]</font></b> (ق مرکب، از اتباع ) در تداول عامه، گاه گاه . با فاصله های زمانی دور. <BR><font color=\"Blue\">◄</font> به نُدرت .<br /></font></div>'),
(3005, 'آین', '<span class=\"hlight\">آین .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) نرم . آسان . سبک .<br /></font></div>'),
(3006, 'آین', '<span class=\"hlight\">آین .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِ) آهن .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(3007, 'آین', '<span class=\"hlight\">آین .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِ) مخفف آیین <span class=\"hlight\">:</span> <br />جشن سده امیرا رسم کبار باشد<br />این آین کیومرث و اسفندیار باشد.<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(3008, 'آین رود', '<span class=\"hlight\">آین رود.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) نام رودیست، سرچشمه ٔ آن بمغرب گردنه ٔ کندوان و شعب آن به طالقان رود.<br /></font></div>'),
(3009, 'آینات', '<span class=\"hlight\">آینات .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص، اِ) ج ِ آینة.<br /></font></div>'),
(3010, 'آینده', '<span class=\"hlight\">آینده .</span> <font color=\"DarkGreen\"><b>[ ی َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف، اِ) آنکه آید <span class=\"hlight\">:</span> <br />زآنکه عشق مردگان پاینده نیست <br />چونکه مرده سوی ما آینده نیست .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> وارد. <BR><font color=\"Blue\">◄</font> مستقبل . مستقبله . قادم . قادمه . آتی . آتیه . زمان پس از حال . وقتی که نیامده است : آینده نیامده ست و بگذشته گذشت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آینده و رونده </span> ؛ صادر و وارد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سال آینده </span> ؛عام قابل . عام مقبل . سال دیگر.<br /></font></div>'),
(3011, 'آیندگان', '<span class=\"hlight\">آیندگان .</span> <font color=\"DarkGreen\"><b>[ ی َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ) ج ِآینده . آنان که آیند. <BR><font color=\"Blue\">◄</font> آنان که پس از ای-ن ی-ا پ-س از ما بدین جهان آیند. مقابل گذشتگان .<br /></font></div>'),
(3012, 'آینه', '<span class=\"hlight\">آینه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ ]</font></b> (ع ص ) تأنیث آین . ج، آینات .<br /></font></div>'),
(3013, 'آینه', '<span class=\"hlight\">آینه .</span> <font color=\"DarkGreen\"><b>[ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) نقش هلال وار که بر دم طاوس است .<br /></font></div>'),
(3014, 'آینه', '<span class=\"hlight\">آینه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) در کلمه ٔ هرآینه، ظاهراً مخفف هرآیینه است و آیینه به معنی آیین یعنی صورت و گونه و سان، و مجموع مرکب بمعنی بهر حال و در هر حال و بهر روی و بهر صورت و لاجرم . (زمخشری ) <span class=\"hlight\">:</span> <br />همه سر آرد بار آن سنان نیزه ٔ او<br />هرآینه که همی خون خورد سر آرد بار.<br /> <font color=\"Red\">دقیقی .</font><br />آن حوض آب روشن و آن کوم گرداو<br />روشن کند دلت چو به بینی هرآینه .<br /> <font color=\"Red\">بهرامی .</font><br />با درفش ار تپانچه خواهی زد<br />بازگردد بتو هرآینه بد.<br /> <font color=\"Red\">عنصری .</font><br />کسی که آتش را جای سازد اندر دل <br />هرآینه بدل او رسد نخست زیان .<br /> <font color=\"Red\">عنصری .</font><br />گر شوم بودتی بغلامی بنزد خویش <br />با ریش شوم تر به برِ ما هرآینه .<br /> <font color=\"Red\">عسجدی .</font><br />و عزیمت ما بر آن قرار گرفته بود که هرآینه و ناچار فرمان عالی <font color=\"DarkGreen\"><b>[ خلیفه ]</font></b> را نگاه داشته آید. (تاریخ بیهقی ). هرگاه دو دوست بمداخلت شریری مبتلا گردند هرآینه میان ایشان جدائی افتد. (کلیله و دمنه ).<br />قبله مساز زآینه هرچند مر ترا<br />صورت هرآینه بنماید هرآینه .<br /> <font color=\"Red\">خاقانی .</font><br />و سزای بدسگال هرآینه برسد. (ترجمه ٔ تاریخ یمینی ). پسر گفت هرآینه تا رنج نبری گنج برنداری . (گلستان ).<br />دو بامداد گر آید کسی بخدمت شاه <br />سیم هرآینه در وی کند بلطف نگاه .<br /> <font color=\"Red\">سعدی .</font><br />و رجوع به هرآینه و هرآیینه شود.<br /></font></div>'),
(3015, 'آینه', '<span class=\"hlight\">آینه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) پاره های آهن که جنگجویان بر پشت و سینه و ران راست کردندی دفاع را، و ظاهراً مجموع آن را چهارآینه یا چارآیینه خواندندی <span class=\"hlight\">:</span> <br />سازد فلک ز عزم تو دایم سلاح خویش <br />دارد شجاع روز وغا در بر آینه .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(3016, 'آینه', '<span class=\"hlight\">آینه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) آهن مصقول و آهن پرداخت کرده و شیشه و بلور پشت بزیبق کرده که صور اشیاء خارجی در آن افتد. مرآت . آیینه . آبگین . آبگینه . و از آن مسطح و محدب و مقعر باشد <span class=\"hlight\">:</span> <br />فرستاد از آن آهن تیره رنگ <br />یکی آینه کرده روشن ز زنگ .<br /> <font color=\"Red\">فردوسی .</font><br />سکندر نهاد آینه زیر نم <br />همی بود تا شدسیاه و دژم .<br /> <font color=\"Red\">فردوسی .</font><br />بود آینه دوست را مرد دوست <br />نماید بدو هرچه زشت و نکوست .<br /> <font color=\"Red\">اسدی .</font><br />تنت آینه ساز و هر دو جهان <br />ببین اندر او آشکار و نهان .<br /> <font color=\"Red\">اسدی .</font><br />گهر چهره شد آینه شد نبید<br />که آید در او خوب و زشتی پدید.<br /> <font color=\"Red\">اسدی .</font><br />آینه ام من اگر تو زشتی زشتم <br />ور تو نکوئی نکوست سیرت و سانم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />جهان آینه ست و در او هرچه بینی <br />خیالیست ناپایدار و مزور.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چرخ کبود مانده بر او ابر جای جای <br />چون برزدوده آینه بر، جای جای زنگ .<br /> <font color=\"Red\">ناصرخسرو.</font><br />در آینه ٔ خُرد روی مردم <br />هم خُرد چنان آینه نماید.<br /> <font color=\"Red\">مسعودسعد.</font><br />ما آینه ایم هرکه در ما نگرد<br />هر نیک و بدی که گوید از خود گوید.<br /> <font color=\"Red\">خیام .</font><br />هرکه را آینه ٔ یقین باشد<br />گرچه خودبین، خدای بین باشد.<br /> <font color=\"Red\">سنائی .</font><br />چو بر او عیبش آینه ننهفت <br />بر زمینش زد آن زمان و بگفت ...<br /> <font color=\"Red\">سنائی .</font><br />فریاد و فغان زین فلک آینه گون <br />کز خاک بچرخ برکشد مشتی دون <br />ما منتظران روزگاریم هنوز<br />تاخود فلک از پرده چه آرد بیرون .<br /> <font color=\"Red\">عمادی شهریاری .</font><br />آب صفت هرچه پلیدی بشوی <br />آینه سان هرچه ندیدی مگوی .<br /> <font color=\"Red\">نظامی .</font><br />چونکه مؤمن آینه ٔ مؤمن بود<br />روی او زآلودگی ایمن بود.<br /> <font color=\"Red\">مولوی .</font><br />گر طمع در آینه برخاستی <br />در نفاق آن آینه چون ماستی .<br /> <font color=\"Red\">مولوی .</font><br />دارم ز جفای فلک آینه گون <br />پرآه دلی که سنگ از او گردد خون .<br /> <font color=\"Red\">ابن یمین .</font><br />هرچه در آینه جوان بیند<br />پیر در خشت خام آن بیند.<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آینه ٔ بینی، آینه ٔ چشم، آینه ٔ حلق، آینه ٔ حنجره، آینه ٔ دهان، آینه ٔ رحم، آینه ٔ گوش </span> ؛ آینه هاست برای دید درون این اندامها، و در طب بکار است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">در دست سوار آینه چکار</span> ؟<br />و رجوع به آیینه شود.<br /></font></div>'),
(3017, 'آینه', '<span class=\"hlight\">آینه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) ظاهر پوست گاو از پستانها تا دُبُر. <BR><font color=\"Blue\">◄</font> وضع موی این قسمت از پوست در ماده گاوکه بعقیده ٔ بعض علماء فن کیفیت و چگونگی شیر را در اختلافات آن توان شناخت . <br /></font></div>'),
(3018, 'آینه افروز', '<span class=\"hlight\">آینه افروز.</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ<span class=\"hlight\" dir=\"rtl\">/</span> ن ِ اَ ]</font></b> (نف مرکب ) مجلی . (حبیش تفلیسی ). صیقل . آینه زدای . آنکه آینه روشن کند. روشن گر. صاقل . صقّال .<br /></font></div>'),
(3019, 'آینه افروزی', '<span class=\"hlight\">آینه افروزی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ اَ ]</font></b> (حامص مرکب ) عمل آینه افروز. روشن گری .<br /></font></div>'),
(3020, 'آینه بندان', '<span class=\"hlight\">آینه بندان .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ب َ ]</font></b> (اِمص مرکب ) عمل تزیین خانه و کوی با نهادن آیینه ٔ بسیار بر دیوارها و جز آن .<br /></font></div>'),
(3021, 'آینه بندی', '<span class=\"hlight\">آینه بندی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ب َ ]</font></b> (حامص مرکب ) آینه بندان .<br /></font></div>'),
(3022, 'آینه خانه', '<span class=\"hlight\">آینه خانه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ن َ ]</font></b>(اِ مرکب ) اطاقی که آن را آینه کاری کرده باشند. <BR><font color=\"Blue\">◄</font> (اِخ ) نام بنائی از آثار صفویه باصفهان .<br /></font></div>'),
(3023, 'آینه دار', '<span class=\"hlight\">آینه دار.</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (نف مرکب ) آنکه آینه در پیش دارد تا عروس و جز او خویشتن در آن بینند <span class=\"hlight\">:</span> <br />ای آفتاب آینه دار جمال تو<br />مشک سیاه مجمره گردان خال تو.<br /> <font color=\"Red\">حافظ.</font><br /><BR><font color=\"Blue\">◄</font> سرتراش . گرّای . سلمانی . گرّا. تانگول . تونکو. موی تراش . موی ستر. حلاق . مُزَیِّن . <BR><font color=\"Blue\">◄</font> توسعاً، دلاک . حجام .<br /></font></div>'),
(3024, 'آینه داری', '<span class=\"hlight\">آینه داری .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (حامص مرکب ) عمل آینه دار <span class=\"hlight\">:</span> دریغ آمدم همی تربیت ستوران و آینه داری در محلت کوران . (گلستان ). <BR><font color=\"Blue\">◄</font> سرتراشی . گرّایی . سلمانی گری . حلاقی . مُزَیِّنی . <BR><font color=\"Blue\">◄</font> دلاکی . <BR><font color=\"Blue\">◄</font> حجامی .<br /></font></div>'),
(3025, 'آینه دان', '<span class=\"hlight\">آینه دان .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) رَبعه . آینه نیام . رجوع به آیینه دان شود.<br /></font></div>'),
(3026, 'آینه زدا', '<span class=\"hlight\">آینه زدا.</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ <span class=\"hlight\" dir=\"rtl\">/</span> زُ ]</font></b> آینه زدای . صیقل . (زمخشری ). صاقل . روشنگر. پرداخت کننده ٔ آینه . آینه افروز. صقّال . آنکه آینه روشن کند.<br /></font></div>'),
(3027, 'آینه زدایی', '<span class=\"hlight\">آینه زدایی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ <span class=\"hlight\" dir=\"rtl\">/</span> زُ ]</font></b> (حامص مرکب ) کار وحرفت آینه زدای . روشنگری . آینه افروزی . صقل . صِقال .<br /></font></div>'),
(3028, 'آینه لی', '<span class=\"hlight\">آینه لی .</span><font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب، اِ مرکب ) (از: آینه + «لی »ترکی، به معنی دارا و دارنده ) قسمی تفنگ در قدیم .<br /></font></div>'),
(3029, 'آینه ور', '<span class=\"hlight\">آینه ور.</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ وَ ]</font></b> (اِخ ) قصبه ٔ ناحیه ٔ بندپی به طبرستان .<br /></font></div>'),
(3030, 'آینه کار', '<span class=\"hlight\">آینه کار.</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب ) آنکه آینه کاری کند.<br /></font></div>'),
(3031, 'آینه کاری', '<span class=\"hlight\">آینه کاری .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (حامص مرکب ) نشاندن آینه های خرد بر دیوار خانه و سقف آن بنظم و ترتیب خاص، زینت را.<br /></font></div>'),
(3032, 'آینه گر', '<span class=\"hlight\">آینه گر.</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ گ َ ]</font></b> (ص مرکب ) سازنده ٔ آینه <span class=\"hlight\">:</span> <br />شاگردی عبارت و خط تو کرده اند<br />هم صبح آینه گر و هم شام مشک سای .<br /><font color=\"Red\">کمال اسماعیل .</font><br /></font></div>'),
(3033, 'آینه گری', '<span class=\"hlight\">آینه گری .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ گ َ ]</font></b> (حامص مرکب ) حرفه ٔ آینه گر.<br /></font></div>'),
(3034, 'آینه گون', '<span class=\"hlight\">آینه گون .</span><font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب ) چون آینه . رخشنده . صافی .<br /></font></div>'),
(3035, 'آینی', '<span class=\"hlight\">آینی .</span> (ترکی، اِ) اَینی . برادر کوچک .<br /></font></div>'),
(3036, 'آیه', '<span class=\"hlight\">آیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) آیت . ج، آیات، آی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیه ٔ حجاب </span> ؛ آیه ٔ سی و یکم سوره ٔ نور <span class=\"hlight\" dir=\"rtl\">٢٤</span>.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیه ٔ سجده </span> ؛ هر یک از چهار آیت ذیل : آیه ٔ <span class=\"hlight\" dir=\"rtl\">١٥</span> از سوره ٔ <span class=\"hlight\" dir=\"rtl\">٣٢</span>. آیه ٔ <span class=\"hlight\" dir=\"rtl\">٣٧</span> از سوره ٔ <span class=\"hlight\" dir=\"rtl\">٤١</span>. آیه ٔ <span class=\"hlight\" dir=\"rtl\">٦٢</span> از سوره ٔ <span class=\"hlight\" dir=\"rtl\">٥٣</span>. آیه ٔ <span class=\"hlight\" dir=\"rtl\">١٩</span> از سوره ٔ <span class=\"hlight\" dir=\"rtl\">٩٦</span>.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیه ٔ سخّر</span> ؛ آیه ٔ <span class=\"hlight\" dir=\"rtl\">١٢</span> از سوره ٔ <span class=\"hlight\" dir=\"rtl\">١٦</span>.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیه ٔ شهادة</span> ؛ آیه ٔ هیجدهم از سوره ٔ آل عمران <span class=\"hlight\" dir=\"rtl\">٣</span>.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیه ٔ فتح </span> ؛ آیه ٔ اول از سوره ٔ فتح <span class=\"hlight\" dir=\"rtl\">٤٨</span>.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیه ٔ نور</span> ؛ آیه ٔ سی و پنجم از سوره ٔ نور <span class=\"hlight\" dir=\"rtl\">٢٤</span>.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیه ٔ و ان یکاد</span> ؛ آیه ٔ پنجاه و یکم از سوره ٔ القلم <span class=\"hlight\" dir=\"rtl\">٦٨</span> <span class=\"hlight\">:</span> <br />حضور خلوت انس است و دوستان جمعند<br />و ان یکاد بخوانید و در فراز کنید.<br /> <font color=\"Red\">حافظ.</font><br />و رجوع به آیت شود.<br /></font></div>'),
(3037, 'آیه و مایه', '<span class=\"hlight\">آیه و مایه .</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ وُ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (ق مرکب، از اتباع ) در تداول عامه، همگی . بالجمله . جمعاً. این و بس (بطور تحقیر): این روغن آیه و مایه دو سیر بود. آیه و مایه یک تومان دارم .<br /></font></div>'),
(3038, 'آیژ', '<span class=\"hlight\">آیژ.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِ) آییژ. شراره . رجوع به آبید شود. <BR><font color=\"Blue\">◄</font> بویمدران . بویمادران . قیصوم . برنجاسف .<br /></font></div>'),
(3039, 'آییز', '<span class=\"hlight\">آییز.</span> آییژ. (اِ) رجوع به آبید شود.<br /></font></div>'),
(3040, 'آیین', '<span class=\"hlight\">آیین .</span> (اِ) سیرت . رسم .(صراح ). عرف . طبع. عادت . داب . (دهار). آئین . شیمه . روش . دَیْدَن . خلق . خصلت . خو. خوی . منش <span class=\"hlight\">:</span> <br />سیرت اوبود وحی نامه بکسری <br />چونکه به آئینْش پندنامه بیاکند.<br /> <font color=\"Red\">رودکی .</font><br />همه شب بدی خوردن آیین او<br />دل مهتران پر شد از کین او.<br /> <font color=\"Red\">فردوسی .</font><br />مزن رای جز با خردمند مرد<br />ز آیین شاهان پیشین مگرد.<br /> <font color=\"Red\">فردوسی .</font><br />ترا دانش و هوش و رای است و فر<br />بر آیین شاهان پیروزگر.<br /> <font color=\"Red\">فردوسی .</font><br />دگر آنکه آیین شاهنشهان <br />بیاموخت از شهریار جهان .<br /> <font color=\"Red\">فردوسی .</font><br />کنون از ره بیگناهان بما<br />نگه کن بر آیین شاهان بما.<br /> <font color=\"Red\">فردوسی .</font><br />بسر برنهاده کلاه دوپر<br />به آیین ترکان ببستش کمر.<br /> <font color=\"Red\">فردوسی .</font><br />بیاساید از بزم و شادی دو ماه <br />که این باشد آیین پس از مرگ شاه .<br /> <font color=\"Red\">فردوسی .</font><br />جز این است آیین پیوند و کین <br />جهان را بچشم جوانی مبین .<br /> <font color=\"Red\">فردوسی .</font><br />همی دید تا هر یکی برنشست <br />به آیین چین با درفشی بدست .<br /> <font color=\"Red\">فردوسی .</font><br />همه کوهشان بود آرامگاه <br />چنین بود آیین هوشنگ شاه .<br /> <font color=\"Red\">فردوسی .</font><br />جوانی به آیین ایرانیان <br />گشاده کش و تنگ بسته میان .<br /> <font color=\"Red\">فردوسی .</font><br />بسه چیز هر کار نیکو شود<br />کز آن تخت شاهی بی آهو شود<br />بگنج و به رنج و بمردان مرد<br />جز این نیست آیین ننگ و نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />تو بصدر اندر بنشسته به آیین ملوک <br />همچنین مدح نیوشنده و من مدح نواز.<br /> <font color=\"Red\">فرخی .</font><br />ساخت آنگه یکی بیوگانی <br />هم بر آیین و رسم یونانی .<br /> <font color=\"Red\">عنصری .</font><br />جشن سده آیین جهاندار فریدون <br />بر شاه جهاندار فری باد و همایون .<br /> <font color=\"Red\">عنصری .</font><br />اما عمرو <font color=\"DarkGreen\"><b>[ لیث ]</font></b> چون او <font color=\"DarkGreen\"><b>[ یعقوب لیث ]</font></b> برفت سعی کرد تا بیشتری از آیین و سیرت نگاه داشت . (تاریخ سیستان ). <br />آیین ملوک عجم از گاه کیخسرو تا بروزگار یزدجرد شهریار که آخر ملوک عجم بوده چنان بوده است که روز نوروز نخست کس از مردمان بیگانه موبد موبدان پیش ملک آمدی . (نوروزنامه ). چون ایوان مداین تمام گشت نوروزکرد و رسم جشن بجای آورد چنانک آیین ایشان بود... وگفت این آیین بجا ماند. (نوروزنامه ). و آیین او چنان بود که چون جنگی کردی سپاهی داشتی آراسته و ساخته و ایشان را جامه ٔ سیاه پوشانیده . (نوروزنامه ). شاه شمیران را معلوم شد، شراب خوردن و بزم نهادن آیین آورد. (نوروزنامه ). و سلطان سنجر را <font color=\"DarkGreen\"><b>[ غزان ]</font></b> بگرفتند وهمچنان با خویشتن می آوردند، بر آیین سلطنت، الاّ آنکه خدمتکاران از آن خویش نصب کردند. (مجمل التواریخ ).<br />پس آنگه بود چون شاهانه آیین <br />فرستادش عماریهای زرین .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />شنیدم ز دانای فرهنگ دوست <br />که زی هرکس آیین شهرش نکوست .<br /> <font color=\"Red\">اسدی .</font><br />ببین تا ز کردار شاهان پیش <br />چه بِه ْ بُد همان کن تو آیین خویش .<br /> <font color=\"Red\">اسدی .</font><br />تا باغبان در او بود از حد خویش نگذشت <br />بر کوهها چریدی از رسم خویش و آیین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از دیدن دگر دگر آیینش <br />دیگر شده ست یکسره آیینم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گر بقا خواهی چو کرم پیله گرد خود متن <br />کبر کبک وحرص مور و فعل مار آیین مکن .<br /> <font color=\"Red\">سنائی .</font><br />گرچه خرم روی و خوشبوئی ّ و خندان لب چو گل <br />با من اندر عشق بدعهدی، چو گل، آیین مکن .<br /> <font color=\"Red\">عبدالواسع جبلی .</font><br />کس این رسم و ترتیب و آیین ندید<br />فریدون ِ با آن شکوه این ندید.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> شرع . شریعت .دین . کیش . سنت . راه . طریقت <span class=\"hlight\">:</span> <br />زخوردن همه روز بربسته لب <br />به پیش جهاندار برپای شب <br />همان بر دل هر کسی بود دوست <br />نماز شب و روزه آیین اوست .<br /> <font color=\"Red\">فردوسی .</font><br />نیا را همین بود آیین و کیش <br />پرستیدن ایزدی بود پیش .<br /> <font color=\"Red\">فردوسی .</font><br />ز یزدان بخواهید تا همچنین <br />دل ما بدارد به آیین و دین .<br /> <font color=\"Red\">فردوسی .</font><br />خروشان بشستش ز خاک نبرد<br />بر آیین شاهان یکی دخمه کرد.<br /> <font color=\"Red\">فردوسی .</font><br />بداد فریدون و آیین و راه <br />بخون سیاوش بجان تو شاه .<br /> <font color=\"Red\">فردوسی .</font><br />ز ما مهتر آزرده شد بیگناه <br />چنین سر بپیچید از آیین و راه .<br /> <font color=\"Red\">فردوسی .</font><br />بر آیین شاهان پیشین رویم <br />سخنهای آن برتران بشنویم .<br /> <font color=\"Red\">فردوسی .</font><br />بر آیین شاهان پیشین رویم <br />همان از پس فرّه ٔ دین رویم <br />ز یزدان نیکی دهش یاد باد<br />همه کار و کردار ما داد باد.<br /> <font color=\"Red\">فردوسی .</font><br />سپاهش همی خواندند آفرین <br />که این است پیمان و آیین دین .<br /> <font color=\"Red\">فردوسی .</font><br />چه مهترچه کهتر چو شد جفت جوی <br />سوی دین و آیین نهاده ست روی .<br /> <font color=\"Red\">فردوسی .</font><br />مر او را <font color=\"DarkGreen\"><b>[ شیرین را ]</font></b> به آیین پیشین بخواست <br />که آن رسم و آیین بد آنگاه راست .<br /> <font color=\"Red\">فردوسی .</font><br />گرت زین بد آید گناه من است <br />چنین است و آیین و راه من است .<br /> <font color=\"Red\">فردوسی .</font><br />بر آیین ایران مر او را بخواست <font color=\"DarkGreen\"><b>[ کردیه را ]</font></b><br />پذیرفت و با جان همی داشت راست .<br /> <font color=\"Red\">فردوسی .</font><br />نه رسم کیی بد<font color=\"DarkGreen\"><b>[ ضحاک را ]</font></b> نه آیین نه کیش .<br /> <font color=\"Red\">فردوسی .</font><br />چو ضحاک بر تخت شد شهریار (کذا)<br />...نهان گشت آیین فرزانگان <br />پراکنده شد کام دیوانگان <br />هنر خوار شد جادوئی ارجمند<br />نهان راستی، آشکاراگزند.<br /> <font color=\"Red\">فردوسی .</font><br />همه مردمی باید آیین تو<br />همه رادی و راستی دین تو.<br /> <font color=\"Red\">فردوسی .</font><br />تو دانی که از دین و آیین و راه <br />چه فرمان یزدان چه فرمان شاه .<br /> <font color=\"Red\">اسدی .</font><br />همه هم صورتند و هم سیرت <br />همه هم سنتند و هم آیین .<br /> <font color=\"Red\">سنائی .</font><br />بدین اندر همی از علم ترتیب علی سازد<br />بملک اندر همی از عدل آیین عمر بندد.<br /> <font color=\"Red\">عبدالواسع جبلی .</font><br />چو بشکست از هیربد پشت را<br />برانداخت آیین زردشت را.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> معمول . متداول . مرسوم <span class=\"hlight\">:</span> <br />بپوشید تن را بچرم پلنگ <br />که جوشن نبودآنگه آیین جنگ .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> جشن سور <span class=\"hlight\">:</span> <br />با ماه سمرقند کن آیین سپرجی <br />رامشگر خوب آور با نعمه ٔ چون قند.<br /> <font color=\"Red\">عماره .</font><br />یک روز مانده باز ز ماه بزرگوار<br />آیین مهرگان نتوان کرد خواستار.<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> شیوه . آهنگ <span class=\"hlight\">:</span> <br />تا بر گل سوری هزاردستان <br />آیین نواهای زار دارد.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> گونه . صفت . کردار. مانند. سان . آسا. چون . وار.<br />ترکیب ها:<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بهارآیین </span> . بهشت آیین . جنت آیین . خسروآیین <span class=\"hlight\">:</span> <br />بهشت آیین سرائی را بپرداخت <br />ز هرگونه در او تمثالها ساخت <br />ز عود و چندن او را آستانه <br />درش سیمین و زرین بالکانه .<br /> <font color=\"Red\">رودکی .</font><br />هر روز شادیی نوبنیاد و رامشی <br />زین باغ جنت آیین زین کاخ کرخ وار.<br /> <font color=\"Red\">فرخی .</font><br />شاد ببلخ آی و خسروآیین بنشین <br />همچو پدر گنجهای خویش بیاکن .<br /> <font color=\"Red\">فرخی .</font><br />باش از دولت بهارآیین <br />همچو آزاده سرو برخوردار.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> اندازه . حد. عدد. شمار. چند <span class=\"hlight\">:</span> <br />بیامد بر خال پاکیزه کیش <br />وزآن مال بی حد ستد بهر خویش <br />ز گاو و خر و گوسفند و ستور<br />ز اشتر ز استر به آیین مور.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> اسباب . وسائل . آلات . ادوات . ساز. سامان . آمادگی <span class=\"hlight\">:</span><br />بیاراست <font color=\"DarkGreen\"><b>[ مردی عرب ]</font></b> آیین کشت و درود<br />از آن زر که یوسف بدو داده بود.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />پس از نامه آیین ره ساختند<br />بروز سوم برگ پرداختند<br />بروز سوم کاروان رفت خواست ...<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> سزاوار. روا. جایز. مباح <span class=\"hlight\">:</span> <br />گر ایدون که فرمان ِ شاه این بود<br />از آن پس مرا رفتن آیین بود.<br /> <font color=\"Red\">فردوسی .</font><br />گر از ما بدلْش اندرون کین بود<br />بریدن سر دشمن آیین بود.<br /> <font color=\"Red\">فردوسی .</font><br />فرستاده گر کشتن آیین بدی <br />سرت را کنون جای پایین بدی .<br /> <font color=\"Red\">فردوسی .</font><br />غم آن کسی خوردن آیین بود<br />که او برغمت نیز غمگین بود.<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> قاعده . قانون . نظم . ترتیب . ضبط. زیج . شرع . یاسا. نَسَق <span class=\"hlight\">:</span> <br />بکوشید و <font color=\"DarkGreen\"><b>[ اردشیر ]</font></b> آیین نیکو نهاد<br />بگسترد بر هر سوئی مهر و داد.<br /> <font color=\"Red\">فردوسی .</font><br />نشست <font color=\"DarkGreen\"><b>[ فریدون ]</font></b> از بر تخت زرین اوی <br />بیفکند ناخوب آیین اوی .<br /> <font color=\"Red\">فردوسی .</font><br />نباید برسم بد آیین نهاد<br />که گویند لعنت بر آن کاین نهاد.<br /> <font color=\"Red\">فردوسی .</font><br />آیین این دو مرغ دراین گنبد<br />پرّیدن و شتاب همی بینم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بفرمود که هر صد و بیست سال کبیسه کنند تا سالها بر جای خویش بماند و مردمان اوقات خویش بسرما و گرما بدانند پس آن آیین تا بروزگار اسکندر رومی که او را ذوالقرنین خوانند بماند. (نوروزنامه ). و جهانیان را واجب است آیین پادشاهان بجای آوردن . (نوروزنامه ). و او صف لشکر از سواره و پیاده چنان به آیین داشته بود که سلطان را عجب آمد. (تاریخ طبرستان ).<br />آیین تقوی ما نیز دانیم <br />اما چه چاره با بخت گمراه ؟<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> تشریف . سامان . اسباب <span class=\"hlight\">:</span> <br />ترا من بدین گونه نشناختم <br />نه در خوردت آیین همی ساختم <br />تو اندرخور بند و غل نیستی <br />بچندین بلا در، کجا ایستی ؟<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />بفرمود پس دادگر شهریار<br />بسیجیدن آیین آن روزگار<br />ز هرگونه تشریفها کردنش <br />ز زندان بگردون بیاوردنش .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> طبیعت . نهاد. وَضع. جبلت . فطرت . حالت .چگونگی <span class=\"hlight\">:</span> <br />جهان همیشه چنین است و گرد گردانست <br />همیشه تا بود آیینْش گرد گردان بود.<br /> <font color=\"Red\">رودکی .</font><br />آیین جهان چونین تا گردون گردان شد<br />مرده نشود زنده و زنده بستودان شد.<br /><font color=\"Red\">رودکی .</font><br />چنین است آیین گردنده دهر<br />کز اونوش یابی گهی گاه زهر.<br /> <font color=\"Red\">فردوسی .</font><br />چنین است آیین گردنده دهر<br />گهی نوش بار آورد گاه زهر.<br /> <font color=\"Red\">فردوسی .</font><br />چنین است آیین چرخ روان <br />تواناست او گر توئی ناتوان .<br /> <font color=\"Red\">فردوسی .</font><br />چنین است آیین و رسم جهان <br />پدر را بفرزند باشد توان .<br /> <font color=\"Red\">فردوسی .</font><br />چنین است آیین و رسم جهان <br />نخواهد گشادن بما بر، نهان .<br /> <font color=\"Red\">فردوسی .</font><br />آیین تنت همه دگر شد<br />تو نیز بجان دگر کن آیین .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> آذین . شهرآرای <span class=\"hlight\">:</span> <br />ببازارگه بسته آیین براه <br />ز دروازه تا پیش درگاه شاه .<br /> <font color=\"Red\">فردوسی .</font><br />هر آنگه که گشتی <font color=\"DarkGreen\"><b>[ خسروپرویز ]</font></b> ز نخجیر باز<br />برخشنده روز و شب دیریاز<br />هر آنکس که بودی ورا دستگاه <br />ببستی بشهر اندر آیین براه .<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود آیین کران تا کران <br />همه شهر سگسار و مازندران .<br /> <font color=\"Red\">فردوسی .</font><br />چنین تا به بسطام و گرگان رسید<br />تو گفتی زمین آسمان را ندید<br />از آیین و گنبد بشهر و بدشت <br />براهی که لشکرهمی برگذشت .<br /> <font color=\"Red\">فردوسی .</font><br />همه شهرها جمله آیین ببست <br />منوچهر بر تخت زرین نشست .<br /> <font color=\"Red\">فردوسی .</font><br />چو آیینها بسته شد در سرای <br />نه کم بد سرای از بهشت خدای .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />و مردم شهر شادی نمودند و آیین بستند. (ترجمه ٔتاریخ یمینی ).<br />و فعل آن بستن باشد. <BR><font color=\"Blue\">◄</font> زینت . آرایش . زیب . زیور <span class=\"hlight\">:</span> <br />خزائن پر از بهر لشکر بود<br />نه از بهر آیین وزیور بود.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> فرّ <span class=\"hlight\">:</span> <br />بر آن زیب و آیین که داماد تست <br />بخوبی بکام دل شاد تست .<br /> <font color=\"Red\">فردوسی .</font><br />چو آمد بگرسیوز این آگهی <br />که شد تیره آیین شاهنشهی .<br /> <font color=\"Red\">فردوسی .</font><br />چو آمد ببرج حمل آفتاب <br />جهان گشت با فرّ و آیین و آب .<br /> <font color=\"Red\">فردوسی .</font><br />چوفرزند باشد به آیین و فر<br />گرامی بدل بر، چه ماده چه نر.<br /><font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> اَدَب . آداب . مراسم <span class=\"hlight\">:</span> <br />بیاموز او را ره و سازرزم <br />همان شادکامی ّ و آیین بزم .<br /> <font color=\"Red\">فردوسی .</font><br />پر از خشم بهرام گفتش چنین <br />شما راست آیین بتوران و چین <br />که بی خواهش من سر اندرنهی <br />براه، این نباشد مگر ابلهی .<br /> <font color=\"Red\">فردوسی .</font><br />چه دانی تو آئین شاهنشهی <br />که داری سر از مغز و دانش تهی .<br /> <font color=\"Red\">فردوسی .</font><br />بکردار و به آیین و به خوهای ستوده <br />جمالیست جهان را و که داند چه جمالی .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> اراده . خواست . خواهش <span class=\"hlight\">:</span> <br />وگر زو <font color=\"DarkGreen\"><b>[ از افراسیاب ]</font></b> تو خشنودی ای دادگر<br />مرا بازگردان ز پیکار سر<br />بکش در دل این آتش کین من <br />به آیین خویش آر آیین من .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بآیین </span> ؛ چنانکه باید. بطوری که ضرور است . متنظم . منتسق . مرتب <span class=\"hlight\">:</span> <br />دبیری بآیین و بادستگاه <br />که دارد ز بیداد لشکر نگاه .<br /> <font color=\"Red\">فردوسی .</font><br />چو آگاهی آمد ز رستم بشاه <br />خروش آمد از شهر وز بارگاه ...<br />جهانی بآیین شد آراسته <br />می و رود و رامشگران خواسته .<br /> <font color=\"Red\">فردوسی .</font><br />دل از داوریها بپرداختند<br />بآیین یکی جشن نو ساختند.<br /> <font color=\"Red\">فردوسی .</font><br />تو بنشین بآیین به تخت کیان <br />چو من پیشت آیم کمربرمیان .<br /> <font color=\"Red\">فردوسی .</font><br />تو شو تخت شاهی بآیین بدار<br />بگیتی بجز تخم نیکی مکار.<br /> <font color=\"Red\">فردوسی .</font><br />چو افراسیاب آن سپه را بدید<br />که سالارشان رستم آمد پدید<br />برابر بآیین صفی برکشید<br />هوا نیلگون شد زمین ناپدید.<br /> <font color=\"Red\">فردوسی .</font><br />همان قیصر از سلم دارد نژاد<br />نژادی بآیین و با فر و داد.<br /> <font color=\"Red\">فردوسی .</font><br />تو قلب سپه را بآیین بدار<br />من اینک پیاده کنم کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />یاری بودی سخت بآیین و بسنگ <br />همسایه ٔ تو بهانه جوی و دلتنگ <br />این خو تو از او گرفته ای ای سرهنگ <br />انگور ز انگور همی گیرد رنگ .<br /> <font color=\"Red\">فرخی .</font><br />از پس خلعت شایسته بآیین صلتی <br />بدرفشانی چون شمس و بگردی چو قمر.<br /> <font color=\"Red\">فرخی .</font><br />بهارا بآیین و خرم بهاری <br />بمان همچنان سالیانی ّو مگذر.<br /> <font color=\"Red\">فرخی .</font><br />بآیین صورتی کاندر جهان کس <br />نظیر او نه دیده ست و نه گفته .<br /> <font color=\"Red\">عنصری .</font><br />بچون تو شاه بآیین شده ست کار جهان <br />بچون تو خسرو روشن شده ست چشم حشم .<br /> <font color=\"Red\">مسعودسعد.</font><BR>۩ زیبا. جمیل <span class=\"hlight\">:</span> <br />شوشه ٔ سیم نکوتر بر تو یا گَه ِ سیم <br />شاخ بادام بآیین تر یا شاخ چنار؟<br /> <font color=\"Red\">فرخی .</font><br />بآیین یکی شهر شامس بنام <br />یکی شهریار اندرو شادکام .<br /> <font color=\"Red\">عنصری .</font><br /> <BR><font color=\"Blue\">◄</font> صورت . طریق .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بَر آیین ِ مَثَل </span> ؛ بر طریق مَثَل . به صورت مَثَل <span class=\"hlight\">:</span> <br />هرکه باور می ندارد بی ثباتی ّ جهان <br />ازبرای او بر آیین مثل گویند عِش .<br /> <font color=\"Red\">ابن یمین .</font><br /> <BR><font color=\"Blue\">◄</font> نهره ای بود که بدان ماست و دوغ از یکدیگر جدا کنند. (تحفة الاحباب اوبهی ) <span class=\"hlight\">:</span> <br />دوغم اکنون که در آیین تو شد<br />بزنم تا بکشم روغن از او.<br /> <font color=\"Red\">طیان .</font><br />و آنین مصحف این کلمه است، یا بعکس .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیین تخت و کلاه، آیین شمشیر و گاه </span> ؛ پادشاهی . سلطنت <span class=\"hlight\">:</span> <br />چنین گفت کآیین تخت و کلاه <br />کیومرث آورد کو بود شاه .<br /> <font color=\"Red\">فردوسی .</font><br />نیازرد باید کسی را به راه <br />چنین است آیین تخت وکلاه .<br /> <font color=\"Red\">فردوسی .</font><br />سر کینه ورْشان براه آورند<br />گر آیین شمشیر و گاه آورند.<br /> <font color=\"Red\">فردوسی .</font><br />و برای کلمه ٔ آیین در نوآیین، رجوع به نوآیین شود.<br /></font></div>'),
(3041, 'آیین', '<span class=\"hlight\">آیین .</span> (اِخ ) نام دهی به نزدیک غار مومیائی . (برهان ). صحیح آبین است : و بقربه قریة تسمی آبین ... فینسب الیها و یقال موم آبین ... معنی اسمه شمعالماء. (الجماهر بیرونی ).<br /></font></div>'),
(3042, 'آیین اکبری', '<span class=\"hlight\">آیین اکبری .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَ ب َ ]</font></b> (اِخ ) قوانین و یاسا و دین گونه ای که میرزا ابوالفضل به امر اکبرشاه هندی آورد. <BR><font color=\"Blue\">◄</font> نام کتاب سوم از اکبرنامه .<br /></font></div>'),
(3043, 'آیین بندی', '<span class=\"hlight\">آیین بندی .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ب َ ]</font></b> (حامص مرکب ) آذین شهر.شهرآرای هنگام قدوم شاهی یا بزرگی یا جشن و سوری .<br /></font></div>'),
(3044, 'آیین جمشید', '<span class=\"hlight\">آیین جمشید.</span> <font color=\"DarkGreen\"><b>[ ن ِ ج َ ]</font></b> (اِخ ) نام نوا و آهنگی است در موسیقی، منسوب به جمشید پادشاه پیشدادی . <BR><font color=\"Blue\">◄</font> نام لحن دوم از سی لحن باربد. (برهان ).<br /></font></div>'),
(3045, 'آیین دادرسی', '<span class=\"hlight\">آیین دادرسی .</span> <font color=\"DarkGreen\"><b>[ ن ِ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) اصول محاکمات . (فرهنگستان ).<br /></font></div>'),
(3046, 'آیین محله', '<span class=\"hlight\">آیین محله .</span> <font color=\"DarkGreen\"><b>[ م َ ح َل ْ ل َ ]</font></b> (اِخ ) نام قریه ای به مازندران .<br /></font></div>'),
(3047, 'آیین نامه', '<span class=\"hlight\">آیین نامه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) نظامنامه . (فرهنگستان ).<br /></font></div>'),
(3048, 'آیین هوشنگ', '<span class=\"hlight\">آیین هوشنگ .</span> <font color=\"DarkGreen\"><b>[ ن ِ ش َ ]</font></b> (اِخ ) نام کتابی موضوع و برساخته که در آن فلسفه ٔ یونانی مترجَم به عربی را با اصطلاحات و لغات عرب، به اجزاء قسمت و هر جزء را به یکی از مردان اساطیری تاریخ ایران نسبت کرده اند. و انتخاب این نام شاید به تناسب پاره ای از ابیات فردوسی است <span class=\"hlight\">:</span> <br />به ما بر ز دین کهن ننگ نیست <br />به گیتی به از دین هوشنگ نیست .<br /><font color=\"Red\">فردوسی .</font><br />بگشتی ز دین کیومرّثی <br />هم از راه هوشنگ و طهمورثی .<br /> <font color=\"Red\">فردوسی .</font><br />ز هوشنگ ماند این سده یادگار<br />بسی باد چون او دگر شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />همه کوهشان بود آرامگاه <br />چنین بود آیین هوشنگ شاه .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(3049, 'آیین پرست', '<span class=\"hlight\">آیین پرست .</span> <font color=\"DarkGreen\"><b>[ پ َ رَ ]</font></b> (نف مرکب ) مطیع. منقاد. تابع. پیرو <span class=\"hlight\">:</span> <br />عروسانه بر کرسی زر نشست <br />شهنشاه را گشت آیین پرست .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(3050, 'آیین پرستی', '<span class=\"hlight\">آیین پرستی .</span> <font color=\"DarkGreen\"><b>[ پ َ رَ ]</font></b> (حامص مرکب ) خدمت با فروتنی . (برهان ) <span class=\"hlight\">:</span> <br />به درگاه خسرو خرامش کنیم <br />به آیین پرستیش رامش کنیم .<br /><font color=\"Red\">فردوسی (از بعض فرهنگها).</font><br /></font></div>'),
(3051, 'آیین گشسب', '<span class=\"hlight\">آیین گشسب .</span> <font color=\"DarkGreen\"><b>[ گ ُ ش َ ]</font></b> (اِخ ) نام سپهبدی که هرمز او را به جنگ بهرام چوبینه فرستاد و او به دست مردی زندانی کشته شد.<br /></font></div>'),
(3052, 'آیینه', '<span class=\"hlight\">آیینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) آینه . مرآت . آئینه . آبگینه <span class=\"hlight\">:</span> <br />آیینه عزیز شد بر ما<br />چون نور گرفت و روشنائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />هنگام سپیده دم خروس سحری <br />دانی که چرا همی کند نوحه گری <br />یعنی که نمودند در آیینه ٔ صبح <br />کز عمر شبی گذشت و تو بیخبری .<br /> <font color=\"Red\">(منسوب به خیام ).</font><br />کور آیینه شناسد هیهات .<br /> <font color=\"Red\">خاقانی .</font><br />ازصفا آیینه منظور نظرها میشود.<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />عاشق آیینه باشد روی خوب .<br /> <font color=\"Red\">مولوی .</font><br />تا چه شکلی تو در آیینه همان خواهی دید.<br /> <font color=\"Red\">سعدی .</font><br />تأمل در آیینه ٔ دل کنی <br />صفائی به تدریج حاصل کنی .<br /> <font color=\"Red\">سعدی .</font><br />ولیکن کی نمائی رخ برندان <br />تو کز خورشید و مه آیینه داری ؟<br /> <font color=\"Red\">حافظ.</font><br />حسن روی تو به یک جلوه که در آینه کرد<br />این همه نقش در آیینه ٔ اوهام افتاد.<br /> <font color=\"Red\">حافظ.</font><br />هرچه رفت از عمر یاد آن به نیکی میکنند<br />چهره ٔ امروز در آیینه ٔ فردا خوش است .<br /> <font color=\"Red\">صائب .</font><br />هر کجا آیینه بینی صیقلش خاکستر است .<br /><font color=\"Red\">قاآنی .</font><br />زشت را گو روی خود را نیک کن <br />ورنه با آیینه ات چِبْوَد سخُن ؟<br /> <font color=\"Red\">؟</font><br />دوست آن است کو معایب دوست <br />همچو آیینه روبرو گوید.<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آیینه اش پاک نبودن </span> ؛ با تندرستی صوری، بیماری و مرضی در باطن داشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">در آیینه ٔ کسان (دیگران ) دیدن </span> ؛ از نظر و لحاظ سود و زیان دیگران در امری اندیشیدن <span class=\"hlight\">:</span> اگر خواهی از زیرکان باشی در آیینه ٔ کسان مبین .(منسوب به نوشیروان، از قابوسنامه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل آیینه </span> ؛ سخت مصقول .<BR>۩ سخت صافی .<BR>۩ سخت روشن .<br />و رجوع به آینه شود.<br /></font></div>'),
(3053, 'آیینه', '<span class=\"hlight\">آیینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) هر یک از قطعات آهنین که مبارزترین پوشیدی <span class=\"hlight\">:</span> <br />نماید ز آیینه پوشی سوار<br />چو آیینه ٔ تیغ در کارزار.<br /> <font color=\"Red\">طاهر وحید.</font><br />ماه سر منجوق کمانش ز رخ خویش <br />آیینه ٔ زر بست بر این طاق مقرنس .<br /> <font color=\"Red\">بدر چاچی .</font><br />و آینه در چهارآینه و چارآینه به همین معنی است .<br /></font></div>'),
(3054, 'آیینه', '<span class=\"hlight\">آیینه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) آینه . سان . آئین . طریق . منوال .گونه . حال و صورت . و هرآیینه و هرآینه مرکب از هر وآینه به معنی مذکور است که به صورت مرکبه، معنی در هر حال و بهر طریق و لاجرم (زمخشری ) دهد <span class=\"hlight\">:</span> <br />ندارم هرآیینه از شاه راز<br />وگرچه بخواهد ز من گفت باز.<br /> <font color=\"Red\">فردوسی .</font><br />هرآیینه خرد داری ّ و دانی <br />که تو امروز در شهر کسانی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />و رجوع به هرآینه و هرآیینه شود.<br /></font></div>'),
(3055, 'آیینه', '<span class=\"hlight\">آیینه .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) رجوع به ایل کرند شود.<br /></font></div>'),
(3056, 'آیینه افروز', '<span class=\"hlight\">آیینه افروز.</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ اَ ]</font></b> (نف مرکب ) آینه افروز. آینه زدای . صیقل . آنکه آینه روشن کند. روشن گر. صاقل . صقّال .<br /></font></div>'),
(3057, 'آیینه افروزی', '<span class=\"hlight\">آیینه افروزی .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ اَ ]</font></b> (حامص مرکب ) عمل آینه افروز. روشن گری .<br /></font></div>'),
(3058, 'آیینه بندان', '<span class=\"hlight\">آیینه بندان .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ب َ ]</font></b> (اِمص مرکب ) آینه بندان .<br /></font></div>'),
(3059, 'آیینه بندی', '<span class=\"hlight\">آیینه بندی .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ب َ ]</font></b> (حامص مرکب ) آینه بندان .<br /></font></div>'),
(3060, 'آیینه خانه', '<span class=\"hlight\">آیینه خانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) آینه خانه . <BR><font color=\"Blue\">◄</font> (اِخ ) نام یکی از بناهای صفویه بوده است به اصفهان .<br /></font></div>'),
(3061, 'آیینه دار', '<span class=\"hlight\">آیینه دار.</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (نف مرکب ) آینه دار <span class=\"hlight\">:</span> <br />شهسوار من که مه آیینه دار روی اوست .<br /> <font color=\"Red\">حافظ.</font><br />دل سراپرده ٔ محبت اوست <br />دیده آیینه دار طلعت اوست .<br /> <font color=\"Red\">حافظ.</font><br /><BR><font color=\"Blue\">◄</font> سرتراش . گرّای . سلمانی . حجّام . فصّاد.<br /></font></div>'),
(3062, 'آیینه داری', '<span class=\"hlight\">آیینه داری .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (حامص مرکب ) عمل آینه دار: آیینه داری در محلّه ٔ کوران . <BR><font color=\"Blue\">◄</font> سرتراشی . گرّایی . سلمانی گری . حجامی . فصادی .<br /></font></div>'),
(3063, 'آیینه دان', '<span class=\"hlight\">آیینه دان .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) قاب آینه . آینه نیام <span class=\"hlight\">:</span> <br />دل را ز سینه در نظر دلستان برآر<br />آیینه پیش یوسف از آیینه دان برآر.<br /><font color=\"Red\">صائب .</font><br /></font></div>'),
(3064, 'آیینه زدا', '<span class=\"hlight\">آیینه زدا.</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ <span class=\"hlight\" dir=\"rtl\">/</span> زُ ]</font></b> آیینه زدای . آینه افروز. صیقل . صاقل . صقّال . آنکه آینه روشن کند. روشنگر.<br /></font></div>'),
(3065, 'آیینه فروز', '<span class=\"hlight\">آیینه فروز.</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ف ُ ]</font></b> (نف مرکب ) آینه افروز.<br /></font></div>'),
(3066, 'آیینه نیام', '<span class=\"hlight\">آیینه نیام .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِ مرکب ) آینه دان . قاب آینه .<br /></font></div>'),
(3067, 'آیینه ورزان', '<span class=\"hlight\">آیینه ورزان .</span> <font color=\"DarkGreen\"><b>[ ن َ وَ ]</font></b> (اِخ ) نام قریه ای بزرگ بدماوند، کنار راه طهران به فیروزکوه، میان گلیارد و جابون در <span class=\"hlight\" dir=\"rtl\">٧٩٤٠٠</span> گزی طهران .<br /></font></div>'),
(3068, 'آیینه پرداز', '<span class=\"hlight\">آیینه پرداز.</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ پ َ ]</font></b> (نف مرکب ) آینه افروز.<br /></font></div>'),
(3069, 'آیینه پیرا', '<span class=\"hlight\">آیینه پیرا.</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (نف مرکب ) آیینه افروز.<br /></font></div>'),
(3070, 'آیینه کار', '<span class=\"hlight\">آیینه کار.</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب ) آینه کار.<br /></font></div>'),
(3071, 'آیینه کاری', '<span class=\"hlight\">آیینه کاری .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (حامص مرکب ) آینه کاری .<br /></font></div>'),
(3072, 'آیینه گون', '<span class=\"hlight\">آیینه گون .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب ) آینه گون .<br /></font></div>'),
(3073, 'آییژ', '<span class=\"hlight\">آییژ.</span> <font color=\"DarkGreen\"><b>[ یی ]</font></b> (اِ) شراره . شرر آتش <span class=\"hlight\">:</span> <br />زآتش حسرت و آییژ حسد صد کرت <br />سوختی سینه ٔ بحرو دل کان آزردی .<br /> <font color=\"Red\">سراج الدین قمری .</font><br /><BR><font color=\"Blue\">◄</font> بویمادران . رجوع به ابیژ و آبید و اَبید شود. و البته یکی از این صور درست و باقی مصحف است .<br /></font></div>'),
(3074, 'آییژه', '<span class=\"hlight\">آییژه .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ ]</font></b> (اِ) آییژ.<br /></font></div>'),
(3075, 'آییژک', '<span class=\"hlight\">آییژک .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ مصغر) مصغر آییژ.<br /></font></div>');
